export const getRatingColor = (rating: number) => {
    if (rating >= 4.5) { return 'text-green-600 dark:text-green-400'; }
    if (rating >= 3.5) { return 'text-blue-600 dark:text-blue-400'; }
    if (rating >= 2.5) { return 'text-yellow-600 dark:text-yellow-400'; }
    return 'text-red-600 dark:text-red-400';
};

export const getQualityColor = (score: number) => {
    if (score >= 80) { return 'text-green-600 dark:text-green-400'; }
    if (score >= 70) { return 'text-yellow-600 dark:text-yellow-400'; }
    return 'text-red-600 dark:text-red-400';
};

export const formatDate = (date: Date | string) => {
    return new Date(date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
};

export const formatDateTime = (date: Date | string) => {
    return new Date(date).toLocaleString('en-US', {
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
    });
};

export const COLORS = ['#10b981', '#3b82f6', '#f59e0b', '#ef4444', '#8b5cf6'];

import { Plus, Trash2, Clock } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useWorkflowDataSources, useWorkflowVariables } from "@/lib/vault-hooks";
interface PayloadMapping {
    key: string;
    value: string;
}
interface ExternalSendConfig {
    destinationId: string;
    payloadMappings: PayloadMapping[];
}
interface ExternalSendBlockEditorProps {
    workflowId: string;
    config: ExternalSendConfig;
    onChange: (config: ExternalSendConfig) => void;
    phase?: string;
    onPhaseChange?: (phase: string) => void;
}
export function ExternalSendBlockEditor({ workflowId, config, onChange, phase, onPhaseChange }: ExternalSendBlockEditorProps) {
    const { data: dataSources } = useWorkflowDataSources(workflowId);
    const { data: variables = [] } = useWorkflowVariables(workflowId);
    // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access -- legacy type check
    const destinations = dataSources?.filter(ds => ds.type === 'external' || (ds.type as string) === 'api');
    const updateConfig = (updates: Partial<ExternalSendConfig>) => {
        onChange({ ...config, ...updates });
    };
    const addMapping = () => {
        const mappings = config.payloadMappings ?? [];
        updateConfig({ payloadMappings: [...mappings, { key: "", value: "" }] });
    };
    const updateMapping = (index: number, key: keyof PayloadMapping, value: string) => {
        const mappings = [...(config.payloadMappings ?? [])];
        mappings[index] = { ...mappings[index], [key]: value };
        updateConfig({ payloadMappings: mappings });
    };
    const removeMapping = (index: number) => {
        const mappings = [...(config.payloadMappings ?? [])];
        mappings.splice(index, 1);
        updateConfig({ payloadMappings: mappings });
    };
    return (
        <div className="space-y-4">
            <div className="space-y-2">
                <Label>Destination</Label>
                <Select
                    value={config.destinationId}
                    onValueChange={(val) => updateConfig({ destinationId: val })}
                >
                    <SelectTrigger>
                        <SelectValue placeholder="Select destination" />
                    </SelectTrigger>
                    <SelectContent>
                        {(destinations?.length ?? 0) > 0 ? destinations?.map(ds => (
                            <SelectItem key={ds.id} value={ds.id}>{ds.name}</SelectItem>
                        )) : <SelectItem value="none" disabled>No external destinations Linked</SelectItem>}
                    </SelectContent>
                </Select>
                <p className="text-xs text-muted-foreground">
                    Link external APIs in the Data Sources tab.
                </p>
            </div>
            <div className="space-y-2">
                <div className="flex justify-between items-center">
                    <Label>Payload Mappings</Label>
                    <Button type="button" variant="outline" size="sm" onClick={addMapping}>
                        <Plus className="w-3 h-3 mr-1" />
                        Add Field
                    </Button>
                </div>
                <div className="space-y-2">
                    {config.payloadMappings?.map((mapping, idx) => (
                        <div key={idx} className="flex gap-2 items-center">
                            <Input
                                placeholder="Field name"
                                value={mapping.key}
                                onChange={(e) => updateMapping(idx, "key", e.target.value)}
                                className="flex-1"
                            />
                            <span className="text-muted-foreground">=</span>
                            {/* Variable Select for Mapping Value */}
                            <div className="flex-1 min-w-0">
                                <Select
                                    value={mapping.value}
                                    onValueChange={(val) => updateMapping(idx, "value", val)}
                                >
                                    <SelectTrigger>
                                        <SelectValue placeholder="Select value...">
                                            {mapping.value?.startsWith('system:') ? (
                                                <span className="text-xs">
                                                    {mapping.value === 'system:current_date' && '≡ƒôà Current Date'}
                                                    {mapping.value === 'system:current_time' && '≡ƒòÉ Current Time'}
                                                    {mapping.value === 'system:current_datetime' && '≡ƒôà Current Date & Time'}
                                                </span>
                                            ) : (
                                                <span className="font-mono text-xs">{mapping.value}</span>
                                            )}
                                        </SelectValue>
                                    </SelectTrigger>
                                    <SelectContent>
                                        {/* System Values */}
                                        <SelectItem value="system:current_date">
                                            <div className="flex items-center gap-2">
                                                <span className="text-xs">≡ƒôà Current Date</span>
                                            </div>
                                        </SelectItem>
                                        <SelectItem value="system:current_time">
                                            <div className="flex items-center gap-2">
                                                <span className="text-xs">≡ƒòÉ Current Time</span>
                                            </div>
                                        </SelectItem>
                                        <SelectItem value="system:current_datetime">
                                            <div className="flex items-center gap-2">
                                                <span className="text-xs">≡ƒôà Current Date & Time</span>
                                            </div>
                                        </SelectItem>
                                        {variables.length > 0 && <hr className="my-1" />}
                                        {/* Workflow Variables */}
                                        {variables.map(v => (
                                            <SelectItem key={v.key} value={v.alias ?? v.key}>
                                                <div className="flex items-center gap-2">
                                                    <span className="font-mono text-xs">{v.alias ?? v.key}</span>
                                                    {v.label && <span className="text-muted-foreground text-xs font-normal">({v.label})</span>}
                                                </div>
                                            </SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                            </div>
                            <Button type="button" variant="ghost" size="icon" onClick={() => removeMapping(idx)}>
                                <Trash2 className="w-4 h-4 text-muted-foreground" />
                            </Button>
                        </div>
                    ))}
                    {(config.payloadMappings === null || config.payloadMappings === undefined || config.payloadMappings.length === 0) && (
                        <p className="text-sm text-muted-foreground italic">Empty payload (sending {"{}"}).</p>
                    )}
                </div>
            </div>
            {(config.destinationId === '' || config.destinationId === undefined) && (
                <div className="p-2 border border-yellow-200 bg-yellow-50 text-yellow-800 text-xs rounded">
                    Please select a destination.
                </div>
            )}
            {/* Execution Timing */}
            {phase !== undefined && onPhaseChange !== undefined && (
                <Card>
                    <CardHeader className="pb-4">
                        <div className="flex items-center gap-2">
                            <Clock className="w-4 h-4 text-primary" />
                            <CardTitle className="text-sm">When to Run</CardTitle>
                        </div>
                        <CardDescription className="text-xs">
                            Choose when this action should execute
                        </CardDescription>
                    </CardHeader>
                    <CardContent>
                        <Select value={phase} onValueChange={onPhaseChange}>
                            <SelectTrigger>
                                <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="onSectionSubmit">
                                    <div className="flex flex-col">
                                        <span className="font-medium">When page is submitted</span>
                                        <span className="text-xs text-muted-foreground">Runs after user submits this page</span>
                                    </div>
                                </SelectItem>
                                <SelectItem value="onRunComplete">
                                    <div className="flex flex-col">
                                        <span className="font-medium">When workflow completes</span>
                                        <span className="text-xs text-muted-foreground">Runs at the end of the workflow</span>
                                    </div>
                                </SelectItem>
                                <SelectItem value="onSectionEnter">
                                    <div className="flex flex-col">
                                        <span className="font-medium">When page loads</span>
                                        <span className="text-xs text-muted-foreground">Runs before user sees this page</span>
                                    </div>
                                </SelectItem>
                            </SelectContent>
                        </Select>
                    </CardContent>
                </Card>
            )}
        </div>
    );
}

/**
 * Comprehensive List Tools Block Editor
 * Applies multiple operations in sequence: filter ΓåÆ sort ΓåÆ offset/limit ΓåÆ select ΓåÆ dedupe
 */

import { Filter, ArrowUpDown, Scissors, Columns, Hash, Target, ChevronDown, ChevronRight } from "lucide-react";
import { useState, useEffect } from "react";

import { FilterBuilderUI, SortBuilderUI, RangeControlsUI, AdvancedTransformUI } from "@/components/builder/transforms";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useSteps } from "@/lib/vault-hooks";

import type {
  ListToolsConfig,
  ListToolsFilterGroup,
  ListToolsSortKey,
  ListToolsDedupe
} from "@shared/types/blocks";

interface ListToolsBlockEditorProps {
  workflowId: string;
  config: Partial<ListToolsConfig>;
  onChange: (config: Partial<ListToolsConfig>) => void;
  mode: 'easy' | 'advanced';
}

export function ListToolsBlockEditor({ workflowId, config, onChange, mode }: ListToolsBlockEditorProps) {
  const { data: steps } = useSteps(workflowId);
  const [localConfig, setLocalConfig] = useState<Partial<ListToolsConfig>>(config);
  const [expandedSections, setExpandedSections] = useState<Set<string>>(new Set(['source']));

  useEffect(() => {
    setLocalConfig(config);
  }, [config]);

  // Get list variables from workflow
  const listVariables = (steps ?? []).filter(step =>
    step.type === 'computed' && step.alias && step.alias.length > 0
  );

  // Get all workflow variables for value source
  const allVariables = (steps ?? [])
    .filter((step): step is typeof step & { alias: string } => !!step.alias && step.alias.length > 0)
    .map(step => step.alias);

  const handleChange = (updates: Partial<ListToolsConfig>) => {
    const newConfig = { ...localConfig, ...updates };
    setLocalConfig(newConfig);
    onChange(newConfig);
  };

  const toggleSection = (section: string) => {
    const newExpanded = new Set(expandedSections);
    if (newExpanded.has(section)) {
      newExpanded.delete(section);
    } else {
      newExpanded.add(section);
    }
    setExpandedSections(newExpanded);
  };

  // Validation
  const isValid = !!(localConfig.sourceListVar && localConfig.outputListVar);

  const filterCount = localConfig.filters?.rules?.length || 0;
  const sortCount = localConfig.sort?.length || 0;

  // Summary stats
  const hasFilters = filterCount > 0;
  const hasSorts = sortCount > 0;
  const hasRange = !!(localConfig.offset || localConfig.limit);
  const hasDedupe = !!localConfig.dedupe;
  const hasSelect = (localConfig.select?.length || 0) > 0;
  const hasTransforms = hasFilters || hasSorts || hasRange || hasDedupe || hasSelect;

  return (
    <div className="space-y-4 max-h-[70vh] overflow-y-auto pr-2">
      {/* Transform Summary */}
      {localConfig.sourceListVar && localConfig.outputListVar && hasTransforms && (
        <div className="p-3 bg-gradient-to-r from-blue-50 to-purple-50 border border-blue-200 rounded-md">
          <div className="flex items-start justify-between gap-2">
            <div className="flex-1">
              <p className="text-xs font-medium text-gray-900 mb-1">Transform Pipeline</p>
              <div className="flex flex-wrap gap-1">
                {hasFilters && (
                  <Badge variant="outline" className="text-[10px] bg-blue-100 border-blue-300 text-blue-700">
                    {filterCount} filter{filterCount > 1 ? 's' : ''}
                  </Badge>
                )}
                {hasSorts && (
                  <Badge variant="outline" className="text-[10px] bg-purple-100 border-purple-300 text-purple-700">
                    Sort by {sortCount} key{sortCount > 1 ? 's' : ''}
                  </Badge>
                )}
                {hasRange && (
                  <Badge variant="outline" className="text-[10px] bg-orange-100 border-orange-300 text-orange-700">
                    {localConfig.offset ? `Skip ${localConfig.offset}` : ''}{localConfig.offset && localConfig.limit ? ', ' : ''}{localConfig.limit ? `Take ${localConfig.limit}` : ''}
                  </Badge>
                )}
                {hasSelect && (
                  <Badge variant="outline" className="text-[10px] bg-indigo-100 border-indigo-300 text-indigo-700">
                    {localConfig.select!.length} column{localConfig.select!.length > 1 ? 's' : ''}
                  </Badge>
                )}
                {hasDedupe && (
                  <Badge variant="outline" className="text-[10px] bg-pink-100 border-pink-300 text-pink-700">
                    Dedupe by {localConfig.dedupe!.fieldPath}
                  </Badge>
                )}
              </div>
            </div>
            <Badge className="bg-green-600 text-white text-[10px] px-2">Active</Badge>
          </div>
        </div>
      )}

      {/* Execution Order Info */}
      <div className="flex items-center justify-center gap-2 text-[10px] text-muted-foreground py-2 bg-muted/20 rounded border border-dashed mb-2">
        <span className="font-medium">Execution Order:</span>
        <span>Filter</span>
        <span>ΓåÆ</span>
        <span>Sort</span>
        <span>ΓåÆ</span>
        <span>Range</span>
        <span>ΓåÆ</span>
        <span>Select</span>
        <span>ΓåÆ</span>
        <span>Dedupe</span>
      </div>

      {/* Source & Output */}
      <Card className="border-green-200 bg-green-50/30">
        <CardHeader className="pb-3 cursor-pointer" onClick={() => toggleSection('source')}>
          <div className="flex items-center justify-between">
            <CardTitle className="text-sm font-medium flex items-center gap-2">
              {expandedSections.has('source') ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
              <Target className="w-4 h-4 text-green-600" />
              Source & Output
            </CardTitle>
            {localConfig.sourceListVar && localConfig.outputListVar && (
              <Badge variant="outline" className="text-xs bg-green-100 border-green-300">
                {localConfig.sourceListVar} ΓåÆ {localConfig.outputListVar}
              </Badge>
            )}
          </div>
        </CardHeader>
        {expandedSections.has('source') && (
          <CardContent className="space-y-3 pt-0">
            <div className="space-y-2">
              <Label className="text-xs">Source List Variable</Label>
              <Select
                value={localConfig.sourceListVar ?? ""}
                onValueChange={(value) => handleChange({ sourceListVar: value })}
              >
                <SelectTrigger className="bg-background">
                  <SelectValue placeholder="Select source list..." />
                </SelectTrigger>
                <SelectContent>
                  {listVariables.length === 0 && (
                    <div className="p-2 text-xs text-muted-foreground">
                      No list variables found. Create a Read Table or Query block first.
                    </div>
                  )}
                  {listVariables.map((variable) => (
                    <SelectItem key={variable.id} value={variable.alias ?? ""}>
                      {variable.alias} ({variable.title})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label className="text-xs">Output List Variable</Label>
              <Input
                className="font-mono text-sm bg-background"
                placeholder="e.g., filtered_users"
                value={localConfig.outputListVar ?? ""}
                onChange={(e) => handleChange({ outputListVar: e.target.value })}
              />
              <p className="text-[11px] text-muted-foreground">
                Name for the transformed list output
              </p>
            </div>
          </CardContent>
        )}
      </Card>

      {/* Filters */}
      <Card className="border-blue-200 bg-blue-50/30">
        <CardHeader className="pb-3 cursor-pointer" onClick={() => toggleSection('filters')}>
          <div className="flex items-center justify-between">
            <CardTitle className="text-sm font-medium flex items-center gap-2">
              {expandedSections.has('filters') ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
              <Filter className="w-4 h-4 text-blue-600" />
              Filters {filterCount > 0 && <Badge variant="secondary" className="ml-1 text-xs">{filterCount}</Badge>}
            </CardTitle>
          </div>
        </CardHeader>
        {expandedSections.has('filters') && (
          <CardContent className="pt-0">
            <FilterBuilderUI
              filters={localConfig.filters}
              onChange={(filters) => handleChange({ filters })}
              availableVariables={allVariables}
            />
          </CardContent>
        )}
      </Card>

      {/* Sort */}
      <Card className="border-purple-200 bg-purple-50/30">
        <CardHeader className="pb-3 cursor-pointer" onClick={() => toggleSection('sort')}>
          <div className="flex items-center justify-between">
            <CardTitle className="text-sm font-medium flex items-center gap-2">
              {expandedSections.has('sort') ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
              <ArrowUpDown className="w-4 h-4 text-purple-600" />
              Sort {sortCount > 0 && <Badge variant="secondary" className="ml-1 text-xs">{sortCount} keys</Badge>}
            </CardTitle>
          </div>
        </CardHeader>
        {expandedSections.has('sort') && (
          <CardContent className="pt-0">
            <SortBuilderUI
              sort={localConfig.sort}
              onChange={(sort) => handleChange({ sort })}
            />
          </CardContent>
        )}
      </Card>

      {/* Range (Offset/Limit) */}
      <Card className="border-orange-200 bg-orange-50/30">
        <CardHeader className="pb-3 cursor-pointer" onClick={() => toggleSection('range')}>
          <div className="flex items-center justify-between">
            <CardTitle className="text-sm font-medium flex items-center gap-2">
              {expandedSections.has('range') ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
              <Scissors className="w-4 h-4 text-orange-600" />
              Range
            </CardTitle>
            {(localConfig.offset || localConfig.limit) && (
              <Badge variant="outline" className="text-xs bg-orange-100 border-orange-300">
                {localConfig.offset ? `Skip ${localConfig.offset}` : ''}{localConfig.offset && localConfig.limit ? ', ' : ''}{localConfig.limit ? `Take ${localConfig.limit}` : ''}
              </Badge>
            )}
          </div>
        </CardHeader>
        {expandedSections.has('range') && (
          <CardContent className="pt-0">
            <RangeControlsUI
              offset={localConfig.offset}
              limit={localConfig.limit}
              onChange={(updates) => handleChange(updates)}
            />
          </CardContent>
        )}
      </Card>

      {/* Transform (Select/Dedupe) */}
      {mode === 'advanced' && (
        <Card className="border-indigo-200 bg-indigo-50/30">
          <CardHeader className="pb-3 cursor-pointer" onClick={() => toggleSection('transform')}>
            <div className="flex items-center justify-between">
              <CardTitle className="text-sm font-medium flex items-center gap-2">
                {expandedSections.has('transform') ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
                <Columns className="w-4 h-4 text-indigo-600" />
                Transform
              </CardTitle>
            </div>
          </CardHeader>
          {expandedSections.has('transform') && (
            <CardContent className="pt-0">
              <AdvancedTransformUI
                select={localConfig.select}
                dedupe={localConfig.dedupe}
                onChange={(updates) => handleChange(updates)}
              />
            </CardContent>
          )}
        </Card>
      )}

      {/* Derived Outputs */}
      {mode === 'advanced' && (
        <Card className="border-pink-200 bg-pink-50/30">
          <CardHeader className="pb-3 cursor-pointer" onClick={() => toggleSection('outputs')}>
            <div className="flex items-center justify-between">
              <CardTitle className="text-sm font-medium flex items-center gap-2">
                {expandedSections.has('outputs') ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
                <Hash className="w-4 h-4 text-pink-600" />
                Derived Outputs
              </CardTitle>
            </div>
          </CardHeader>
          {expandedSections.has('outputs') && (
            <CardContent className="space-y-3 pt-0">
              <div className="space-y-2">
                <Label className="text-xs">Count Variable (optional)</Label>
                <Input
                  className="h-8 text-xs font-mono bg-background"
                  placeholder="e.g., user_count"
                  value={localConfig.outputs?.countVar ?? ''}
                  onChange={(e) => handleChange({
                    outputs: {
                      ...localConfig.outputs,
                      countVar: e.target.value || undefined
                    }
                  })}
                />
                <p className="text-[11px] text-muted-foreground">
                  Store the number of rows as a separate variable
                </p>
              </div>

              <div className="space-y-2">
                <Label className="text-xs">First Row Variable (optional)</Label>
                <Input
                  className="h-8 text-xs font-mono bg-background"
                  placeholder="e.g., top_user"
                  value={localConfig.outputs?.firstVar ?? ''}
                  onChange={(e) => handleChange({
                    outputs: {
                      ...localConfig.outputs,
                      firstVar: e.target.value || undefined
                    }
                  })}
                />
                <p className="text-[11px] text-muted-foreground">
                  Store the first row as a separate variable
                </p>
              </div>
            </CardContent>
          )}
        </Card>
      )}

      {/* Validation Message */}
      {!isValid && (
        <div className="p-3 bg-yellow-50 border border-yellow-200 rounded-md text-xs text-yellow-900">
          <p className="font-medium mb-1">Required Fields</p>
          <p>Please provide both a source list variable and output list variable name.</p>
        </div>
      )}

      {mode === 'easy' && (
        <div className="p-3 bg-blue-50 border border-blue-200 rounded-md text-xs text-blue-900">
          <p className="font-medium mb-1">Easy Mode Note</p>
          <p>
            List Tools apply filtering, sorting, and transformations to lists. Switch to Advanced Mode for more options (multi-sort, dedupe, column selection).
          </p>
        </div>
      )}
    </div>
  );
}

import { useQuery } from "@tanstack/react-query";
import { Plus, Trash2 } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { dataSourceAPI } from "@/lib/vault-api";
import { useWorkflowDataSources } from "@/lib/vault-hooks";
interface QueryFilter {
    column: string;
    operator: string;
    value: string;
}
interface QuerySort {
    column: string;
    direction: "asc" | "desc";
}
interface QueryConfig {
    dataSourceId?: string;
    queryId?: string;
    table?: string;
    outputVariableName?: string;
    filters?: QueryFilter[];
    sort?: QuerySort;
}
interface QueryBlockEditorProps {
    workflowId: string;
    config: QueryConfig;
    onChange: (config: QueryConfig) => void;
}
export function QueryBlockEditor({ workflowId, config, onChange }: QueryBlockEditorProps) {
    const { data: dataSources } = useWorkflowDataSources(workflowId);
    // Fetch tables
    const { data: tables } = useQuery({
        queryKey: ["dataSource", config.dataSourceId, "tables"],
        queryFn: () => config.dataSourceId ? dataSourceAPI.getTables(config.dataSourceId) : Promise.resolve([]),
        enabled: !!config.dataSourceId
    });
    const handleChange = <K extends keyof QueryConfig>(key: K, value: QueryConfig[K]) => {
        onChange({ ...config, [key]: value });
    };
    const addFilter = () => {
        const filters = config.filters ?? [];
        handleChange("filters", [...filters, { column: "", operator: "equals", value: "" }]);
    };
    const removeFilter = (index: number) => {
        const filters = config.filters ?? [];
        handleChange("filters", filters.filter((_, i) => i !== index));
    };
    const updateFilter = (index: number, field: keyof QueryFilter, value: string) => {
        const filters = config.filters ?? [];
        const newFilters = [...filters];
        newFilters[index] = { ...newFilters[index], [field]: value };
        handleChange("filters", newFilters);
    };
    return (
