import { Badge } from "@/components/ui/badge";
import { Label } from "@/components/ui/label";
import type { DatavaultColumn } from "@/lib/types/datavault";

import type { ReadTableConfig } from "@shared/types/blocks";

interface ReadTableColumnSelectorProps {
    config: ReadTableConfig;
    columns?: DatavaultColumn[];
    onChange: (updates: Partial<ReadTableConfig>) => void;
}

export function ReadTableColumnSelector({ config, columns, onChange }: ReadTableColumnSelectorProps) {
    const isAllSelected = config.columns === undefined || config.columns === null;

    const handleAllColsChange = (checked: boolean) => {
        if (checked) {
            // Explicitly set columns to null to clear it from database
            onChange({ columns: null, totalColumnCount: columns?.length || 0 });
        } else {
            // Default to all selected when switching to manual mode
            onChange({ columns: columns?.map(c => c.id) ?? [], totalColumnCount: columns?.length || 0 });
        }
    };

    const handleColumnToggle = (colId: string, checked: boolean) => {
        const current = config.columns ?? [];
        let next: string[];
        if (checked) {
            next = [...current, colId];
        } else {
            next = current.filter(id => id !== colId);
        }
        onChange({ columns: next });
    };

    return (
        <div className="bg-slate-50 border rounded-lg p-4 space-y-3">
            <div className="flex items-center justify-between pb-2 border-b border-slate-200">
                <div className="flex items-center space-x-2">
                    <input
                        type="checkbox"
                        id="all-cols"
                        className="rounded border-gray-300"
                        checked={isAllSelected}
                        onChange={(e) => handleAllColsChange(e.target.checked)}
                    />
                    <Label htmlFor="all-cols" className="font-medium cursor-pointer">
                        Read All Columns
                    </Label>
                </div>
                <Badge variant="outline">
                    {isAllSelected ? `All (${columns?.length || 0})` : config.columns?.length}
                </Badge>
            </div>

            {/* Individual Columns List */}
            {!isAllSelected && (
                <div className="space-y-2 max-h-[200px] overflow-y-auto pr-2 custom-scrollbar">
                    {columns?.map((col) => {
                        const isSelected = config.columns?.includes(col.id);
                        return (
                            <div key={col.id} className="flex items-center space-x-2">
                                <input
                                    type="checkbox"
                                    id={`col-${col.id}`}
                                    className="rounded border-gray-300"
                                    checked={isSelected}
                                    onChange={(e) => handleColumnToggle(col.id, e.target.checked)}
                                />
                                <Label htmlFor={`col-${col.id}`} className="text-sm font-normal cursor-pointer truncate" title={col.name}>
                                    {col.name}
                                </Label>
                            </div>
                        );
                    })}
                </div>
            )}

            {isAllSelected && (
                <div className="py-4 text-center text-xs text-muted-foreground italic">
                    Retrieving all ({columns?.length || 0}) fields.
                </div>
            )}
        </div>
    );
}

import { Plus, Trash2 } from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import type { DatavaultColumn } from "@/lib/types/datavault";

import type { ReadTableConfig, ReadTableOperator, ReadTableFilter } from "@shared/types/blocks";

interface ReadTableFilterSelectorProps {
    config: ReadTableConfig;
    columns?: DatavaultColumn[];
    onChange: (updates: Partial<ReadTableConfig>) => void;
}

export function ReadTableFilterSelector({ config, columns, onChange }: ReadTableFilterSelectorProps) {
    const handleUpdateFilter = (index: number, updates: Partial<ReadTableFilter>) => {
        const newFilters = [...(config.filters ?? [])];
        if (newFilters[index]) {
            newFilters[index] = { ...newFilters[index], ...updates };
            onChange({ filters: newFilters });
        }
    };

    const handleRemoveFilter = (index: number) => {
        const newFilters = [...(config.filters ?? [])];
        newFilters.splice(index, 1);
        onChange({ filters: newFilters });
    };

    const handleAddFilter = () => {
        onChange({ filters: [...(config.filters ?? []), { columnId: '', operator: 'equals', value: '' }] });
    };

    return (
        <div className="space-y-3">
            <div className="flex items-center justify-between">
                <h3 className="font-semibold">Filters</h3>
                <Badge variant="outline">{config.filters?.length || 0}</Badge>
            </div>
            <div className="bg-slate-50 border rounded-lg p-4 space-y-3">
                {(config.filters ?? []).map((filter, index) => (
                    <div key={index} className="flex gap-2 items-start p-2 bg-white rounded border shadow-sm">
                        <div className="grid grid-cols-3 gap-2 flex-1">
                            <Select
                                value={filter.columnId || "_clear"}
                                onValueChange={(val) => {
                                    const newFilters = [...(config.filters ?? [])];
                                    if (val === '_clear') {
                                        // Keep index but reset
                                        newFilters[index] = { columnId: '', operator: 'equals', value: '' };
                                        onChange({ filters: newFilters });
                                    } else {
                                        handleUpdateFilter(index, { columnId: val });
                                    }
                                }}
                            >
                                <SelectTrigger className="h-8 text-xs"><SelectValue placeholder="Column" /></SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="_clear" className="text-muted-foreground italic">None</SelectItem>
                                    {columns?.map(c => <SelectItem key={c.id} value={c.id}>{c.name}</SelectItem>)}
                                </SelectContent>
                            </Select>

                            <Select
                                value={filter.operator}
                                onValueChange={(val: ReadTableOperator) => handleUpdateFilter(index, { operator: val })}
                            >
                                <SelectTrigger className="h-8 text-xs"><SelectValue /></SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="equals">Equals</SelectItem>
                                    <SelectItem value="contains">Contains</SelectItem>
                                    <SelectItem value="greater_than">Greater Than</SelectItem>
                                    <SelectItem value="less_than">Less Than</SelectItem>
                                </SelectContent>
                            </Select>

                            <Input
                                value={filter.value}
                                onChange={(e) => handleUpdateFilter(index, { value: e.target.value })}
                                className="h-8 text-xs"
                                placeholder="Value..."
                            />
                        </div>
                        <Button variant="ghost" size="icon" className="h-8 w-8 text-gray-400 hover:text-red-500" onClick={() => handleRemoveFilter(index)}>
                            <Trash2 className="w-4 h-4" />
                        </Button>
                    </div>
                ))}
                <Button variant="outline" size="sm" className="w-full border-dashed" onClick={handleAddFilter}>
                    <Plus className="w-4 h-4 mr-2" />
                    Add Filter
                </Button>
            </div>
        </div>
    );
}

