import { Loader2, Sparkles, Send, Check, X } from "lucide-react";
import { useState, useRef, useEffect } from 'react';

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription } from "@/components/ui/sheet";
import { useToast } from "@/hooks/use-toast";
import { cn } from "@/lib/utils";
import { useReviseWorkflow, useUpdateWorkflow, useWorkflowMode } from "@/lib/vault-hooks";

import type { WorkflowDiff, AIGeneratedWorkflow, WorkflowChange } from "@shared/types/ai";

import { AIFeedbackWidget, QualityScore } from "./AIFeedbackWidget";

interface Message {
    role: 'user' | 'assistant';
    content: string;
    diff?: WorkflowDiff; // Structured diff if available
    timestamp: number;
    status?: 'pending' | 'applied' | 'discarded';
    qualityScore?: QualityScore;
}

interface OperationMeta {
    aiProvider?: string;
    aiModel?: string;
    requestDescription?: string;
}

interface AIAssistPanelProps {
    workflowId: string;
    currentWorkflow: AIGeneratedWorkflow | Record<string, unknown>;
    isOpen: boolean;
    onClose: () => void;
}

export function AIAssistPanel({ workflowId, currentWorkflow, isOpen, onClose }: AIAssistPanelProps) {
    const [input, setInput] = useState('');
    const [messages, setMessages] = useState<Message[]>([
        {
            role: 'assistant',
            content: 'Hi! I can help you revise this workflow. Try saying "Add a phone number question" or "Make the email required".',
            timestamp: Date.now()
        }
    ]);
    const [proposedWorkflow, setProposedWorkflow] = useState<AIGeneratedWorkflow | Record<string, unknown> | null>(null);
    const [showFeedbackWidget, setShowFeedbackWidget] = useState(false);
    const [lastQualityScore, setLastQualityScore] = useState<QualityScore | undefined>(undefined);
    const [lastOperationMeta, setLastOperationMeta] = useState<OperationMeta | null>(null);
    const [inspirationIndex, setInspirationIndex] = useState(0);
    const scrollRef = useRef<HTMLDivElement>(null);
    const { toast } = useToast();
    const reviseMutation = useReviseWorkflow();
    const updateMutation = useUpdateWorkflow();
    const { data: workflowMode } = useWorkflowMode(workflowId);
    const mode = workflowMode?.mode || 'easy';
    const inspirationalPhrases = [
        "Every great workflow starts with a single step.",
        "Automation is not about replacing humans, it's about empowering them.",
        "Good workflows are built, great workflows are evolved.",
        "The best time to automate was yesterday. The second best time is now.",
        "Small improvements in process lead to massive gains in productivity.",
        "A well-designed workflow is like a good conversation - it flows naturally.",
        "Simplicity is the ultimate sophistication in workflow design.",
        "Your future self will thank you for documenting this process.",
        "Great workflows don't just save time, they create possibilities.",
        "Think of this as building the future, one question at a time."
    ];

    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
    }, [messages]);

    // Rotate inspirational phrases while AI is thinking
    useEffect(() => {
        if (reviseMutation.isPending) {
            const interval = setInterval(() => {
                setInspirationIndex((prev) => (prev + 1) % inspirationalPhrases.length);
            }, 4000); // Change phrase every 4 seconds
            return () => clearInterval(interval);
        }
    }, [reviseMutation.isPending, inspirationalPhrases.length]);

    const handleSend = async () => {
        if (!input.trim()) { return; }

        const userMsg: Message = { role: 'user', content: input, timestamp: Date.now() };
        setMessages(prev => [...prev, userMsg]);
        setInput('');
        setProposedWorkflow(null); // Clear previous proposal if any

        try {
            // Convert messages to history format
            const history = messages
                .filter(m => !m.diff)
                .map(m => ({ role: m.role, content: m.content }));

            const result = await reviseMutation.mutateAsync({
                workflowId,
                currentWorkflow: currentWorkflow as AIGeneratedWorkflow,
                userInstruction: userMsg.content,
                conversationHistory: history,
                mode: mode
            });

            // Capture quality score if available
            const qualityScore = result.quality;
            if (qualityScore) {
                setLastQualityScore(qualityScore);
                setLastOperationMeta({
                    aiProvider: result.metadata?.provider,
                    aiModel: result.metadata?.model,
                    requestDescription: userMsg.content,
                });
            }

            // NOTE: Backend now auto-applies changes (Option B implementation)
            // Backend returns metadata.applied: true when changes are persisted
            const backendApplied = result.metadata?.applied === true;

            if (backendApplied) {
                // Backend already applied changes - show as applied
                const assistantMsg: Message = {
                    role: 'assistant',
                    content: result.explanation ? result.explanation.join(' ') : 'I have updated the workflow.',
                    diff: result.diff,
                    timestamp: Date.now(),
                    status: 'applied',
                    qualityScore,
                };
                setMessages(prev => [...prev, assistantMsg]);
                toast({
                    title: "Changes Applied",
                    description: `${result.diff?.changes?.length || 0} changes applied successfully.`
                });
                // Show feedback widget after successful auto-apply
                if (qualityScore) {
                    setShowFeedbackWidget(true);
                }
                // Force refetch workflow to show updated data in UI
                window.location.reload(); // Simple approach - can be improved with cache invalidation
            } else {
                // Fallback: Show as pending (advanced mode or old backend)
                const assistantMsg: Message = {
                    role: 'assistant',
                    content: result.explanation ? result.explanation.join(' ') : 'Here are the suggested changes.',
                    diff: result.diff,
                    timestamp: Date.now(),
                    status: 'pending',
                    qualityScore,
                };
                setMessages(prev => [...prev, assistantMsg]);
                setProposedWorkflow(result.updatedWorkflow);
            }
        } catch (error: unknown) {
            const errorMessage = error instanceof Error ? error.message : 'Unknown error occurred';
            setMessages(prev => [...prev, {
                role: 'assistant',
                content: `Sorry, I encountered an error: ${errorMessage}`,
                timestamp: Date.now()
            }]);
        }
    };
    const handleApply = async () => {
        if (!proposedWorkflow) { return; }
        try {
            await updateMutation.mutateAsync({
                id: workflowId,
                ...proposedWorkflow
            });
            toast({ title: "Changes Applied", description: "Workflow updated successfully." });
            setProposedWorkflow(null);
            setMessages(prev => {
                const newMessages = [...prev];
                const lastMsg = newMessages[newMessages.length - 1];
                if (lastMsg.role === 'assistant' && lastMsg.status === 'pending') {
                    lastMsg.status = 'applied';
                } else {
                    newMessages.push({
                        role: 'assistant',
                        content: "Changes applied!",
                        timestamp: Date.now(),
                        status: 'applied'
                    });
                }
                return newMessages;
            });
            // Show feedback widget after successful apply
            if (lastQualityScore) {
                setShowFeedbackWidget(true);
            }
        } catch (error) {
            toast({ title: "Update Failed", variant: "destructive", description: "Could not apply changes." });
        }
    };
    const handleDiscard = () => {
        setProposedWorkflow(null);
        setMessages(prev => {
            const newMessages = [...prev];
            const lastMsg = newMessages[newMessages.length - 1];
            if (lastMsg.role === 'assistant' && lastMsg.status === 'pending') {
                lastMsg.status = 'discarded';
            } else {
                newMessages.push({
                    role: 'assistant',
                    content: "Changes discarded.",
                    timestamp: Date.now()
                });
            }
            return newMessages;
        });
    };
    return (
        <Sheet open={isOpen} onOpenChange={(open) => !open && onClose()}>
            <SheetContent className="w-[400px] sm:w-[540px] flex flex-col p-0">
                <SheetHeader className="p-6 border-b">
                    <SheetTitle className="flex items-center gap-2">
                        <Sparkles className="w-5 h-5 text-purple-500" />
                        AI Assistant
                        {mode === 'easy' && <Badge variant="secondary" className="ml-auto text-xs">Easy Mode</Badge>}
                    </SheetTitle>
                    <SheetDescription>
                        Iterate on your workflow using natural language.
                    </SheetDescription>
                </SheetHeader>
                <div className="flex-1 p-4 overflow-y-auto" ref={scrollRef}>
                    <div className="space-y-6">
                        {messages.map((msg, idx) => (
                            <div key={idx} className={`flex flex-col gap-2 ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                                <div className={`rounded-lg p-3 max-w-[85%] text-sm ${msg.role === 'user'
                                    ? 'bg-primary text-primary-foreground'
                                    : 'bg-muted'
                                    }`}>
                                    <p className="whitespace-pre-wrap">{msg.content}</p>
                                </div>
                                {msg.diff?.changes && msg.diff.changes.length > 0 && (
                                    <Card className={cn(
                                        "w-full mt-2 p-3 border shadow-sm",
                                        msg.status === 'applied' ? "bg-green-50/50 border-green-200 dark:bg-green-900/10 dark:border-green-900" :
                                            msg.status === 'discarded' ? "bg-muted/50 opacity-70" :
                                                "bg-purple-50/50 border-purple-200 dark:bg-purple-900/10 dark:border-purple-900"
                                    )}>
                                        <div className="flex items-center justify-between mb-2">
                                            <span className={cn(
                                                "text-xs font-semibold",
                                                msg.status === 'applied' ? "text-green-700 dark:text-green-400" :
                                                    msg.status === 'discarded' ? "text-muted-foreground" :
                                                        "text-purple-700 dark:text-purple-300"
                                            )}>
                                                {msg.status === 'applied' ? 'Changes Applied' :
                                                    msg.status === 'discarded' ? 'Changes Discarded' :
                                                        'Proposed Changes'}
                                            </span>
                                            <Badge variant="outline" className="text-[10px]">{msg.diff.changes.length} changes</Badge>
                                        </div>
                                        <ul className="space-y-1 mb-3">
                                            {msg.diff.changes.map((change: WorkflowChange, i: number) => (
                                                <li key={i} className="text-xs flex gap-2">
                                                    <Badge variant={change.type === 'add' ? 'default' : change.type === 'remove' ? 'destructive' : 'secondary'} className="h-5 px-1 text-[10px] capitalize shrink-0">
                                                        {change.type}
                                                    </Badge>
                                                    <span className="truncate flex-1 text-muted-foreground">{change.explanation}</span>
                                                </li>
                                            ))}
                                        </ul>
                                        {msg.status === 'pending' && proposedWorkflow && idx === messages.length - 1 && (
                                            <div className="flex gap-2 justify-end pt-2 border-t border-purple-200/50">
                                                <Button size="sm" variant="ghost" className="h-7 text-xs" onClick={() => { void handleDiscard(); }}>
                                                    <X className="w-3 h-3 mr-1" /> Discard
                                                </Button>
                                                <Button size="sm" className="h-7 text-xs bg-purple-600 hover:bg-purple-700 text-white" onClick={() => { void handleApply(); }}>
                                                    <Check className="w-3 h-3 mr-1" /> Apply
                                                </Button>
                                            </div>
                                        )}
                                    </Card>
                                )}
                            </div>
                        ))}
                        {reviseMutation.isPending && (
                            <div className="flex flex-col gap-3">
                                <div className="bg-muted rounded-lg p-4">
                                    <div className="flex items-center gap-2 mb-2">
                                        <Loader2 className="w-4 h-4 animate-spin text-purple-500" />
                                        <span className="text-sm font-medium text-foreground">Thinking...</span>
                                    </div>
                                    <p className="text-xs text-muted-foreground mb-3">
                                        This can take a few minutes for larger documents. Great time to go get a coffee Γÿò
                                    </p>
                                    <div className="border-t border-border pt-3">
                                        <p className="text-xs italic text-muted-foreground transition-opacity duration-500">
                                            {inspirationalPhrases[inspirationIndex]}
                                        </p>
                                    </div>
                                </div>
                            </div>
                        )}
                        {showFeedbackWidget && lastQualityScore && (
                            <div className="mt-4">
                                <AIFeedbackWidget
                                    workflowId={workflowId}
                                    operationType="revision"
                                    qualityScore={lastQualityScore}
                                    aiProvider={lastOperationMeta?.aiProvider}
                                    aiModel={lastOperationMeta?.aiModel}
                                    requestDescription={lastOperationMeta?.requestDescription}
                                    onClose={() => setShowFeedbackWidget(false)}
                                />
                            </div>
                        )}
                        <div ref={scrollRef} />
                    </div>
                </div>
                <div className="p-4 border-t bg-background">
                    <form
                        className="flex gap-2"
                        onSubmit={(e) => {
                            e.preventDefault();
                            void handleSend();
                        }}
                    >
                        <Input
                            placeholder={mode === 'easy' ? "Describe changes to auto-apply..." : "Describe changes..."}
                            value={input}
                            onChange={(e) => { void setInput(e.target.value); }}
                            disabled={reviseMutation.isPending || !!proposedWorkflow}
                        />
                        <Button type="submit" size="icon" disabled={!input.trim() || reviseMutation.isPending || !!proposedWorkflow}>
                            <Send className="w-4 h-4" />
                        </Button>
                    </form>
                    {!!proposedWorkflow && (
                        <p className="text-xs text-center mt-2 text-muted-foreground animate-pulse">Waiting for your review...</p>
                    )}
                </div>
            </SheetContent>
        </Sheet>
    );
}

import { CheckCircle2, Lightbulb, X } from 'lucide-react';
import { useState } from 'react';

import { Alert, AlertDescription } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Separator } from '@/components/ui/separator';
import { Textarea } from '@/components/ui/textarea';
import { useToast } from '@/hooks/use-toast';
import { cn } from '@/lib/utils';
import { fetchAPI } from '@/lib/vault-api';

import type { QualityScore } from '@shared/types/ai';

// Imported sub-components
import { IssueList } from './ai-feedback/IssueList';
import { QualityBreakdown, QualityHeader } from './ai-feedback/QualityBreakdown';
import { RatingInput } from './ai-feedback/RatingInput';

export { type QualityScore };

interface AIFeedbackWidgetProps {
  workflowId?: string;
  operationType: 'generation' | 'revision' | 'suggestion' | 'logic' | 'optimization';
  qualityScore?: QualityScore;
  aiProvider?: string;
  aiModel?: string;
  requestDescription?: string;
  generatedSections?: number;
  generatedSteps?: number;
  onClose?: () => void;
  className?: string;
}

export function AIFeedbackWidget({
  workflowId,
  operationType,
  qualityScore,
  aiProvider,
  aiModel,
  requestDescription,
  generatedSections,
  generatedSteps,
  onClose,
  className,
}: AIFeedbackWidgetProps) {
  const [rating, setRating] = useState<number>(0);
  const [comment, setComment] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);
  const { toast } = useToast();

  const handleSubmit = async () => {
    if (rating === 0) {
      toast({
        title: 'Rating Required',
        description: 'Please select a rating before submitting.',
        variant: 'destructive',
      });
      return;
    }

    setIsSubmitting(true);

    try {
      await fetchAPI('/api/ai/feedback', {
        method: 'POST',
        body: JSON.stringify({
          workflowId: workflowId || undefined,
          operationType,
          rating,
          comment: comment.trim() || undefined,
          aiProvider,
          aiModel,
          qualityScore: qualityScore?.overall,
          qualityPassed: qualityScore?.passed,
          issuesCount: qualityScore?.issues.length,
          requestDescription,
          generatedSections,
          generatedSteps,
        }),
      });

      setIsSubmitted(true);
      toast({
        title: 'Feedback Submitted',
        description: 'Thank you for helping us improve!',
      });

      if (onClose) {
        setTimeout(onClose, 2000);
      }
    } catch (error: unknown) {
      console.error('Failed to submit feedback:', error);
      const errorMessage = error instanceof Error ? error.message : 'Failed to submit feedback. Please try again.';
      toast({
        title: 'Submission Failed',
        description: errorMessage,
        variant: 'destructive',
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isSubmitted) {
    return (
      <Card className={cn('border-green-200 dark:border-green-800 bg-green-50/50 dark:bg-green-900/10', className)}>
        <CardContent className="pt-6 flex flex-col items-center justify-center text-center space-y-3">
          <div className="bg-green-100 dark:bg-green-900/30 p-3 rounded-full">
            <CheckCircle2 className="w-8 h-8 text-green-600 dark:text-green-400" />
          </div>
          <h3 className="text-lg font-semibold text-green-900 dark:text-green-100">Thank You!</h3>
          <p className="text-sm text-green-700 dark:text-green-300">Your feedback helps us improve the AI assistant.</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className={cn('border-indigo-200 dark:border-indigo-800', className)}>
      <CardHeader className="pb-3">
        <div className="flex items-start justify-between">
          <div className="flex-1">
            <CardTitle className="text-lg flex items-center gap-2">
              AI Quality & Feedback
              {qualityScore && <QualityHeader qualityScore={qualityScore} />}
            </CardTitle>
            <CardDescription className="mt-1">
              Rate the AI&apos;s performance to help us improve
            </CardDescription>
          </div>
          {onClose && (
            <Button variant="ghost" size="icon" className="h-6 w-6" onClick={() => { void onClose(); }}>
              <X className="w-4 h-4" />
            </Button>
          )}
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        {qualityScore && (
          <>
            <QualityBreakdown qualityScore={qualityScore} />
            <IssueList issues={qualityScore.issues} />
            <Separator />
          </>
        )}

        <RatingInput rating={rating} setRating={setRating} />

        <div className="space-y-2">
          <h4 className="text-sm font-medium">Additional Comments (Optional)</h4>
          <Textarea
            placeholder="Tell us what worked well or what could be improved..."
            value={comment}
            onChange={(e) => { void setComment(e.target.value); }}
            rows={3}
            className="text-sm resize-none"
          />
        </div>

        {qualityScore?.suggestions && qualityScore.suggestions.length > 0 && (
          <Alert>
            <Lightbulb className="w-4 h-4" />
            <AlertDescription className="text-xs">
              <strong>Suggestions:</strong>
              <ul className="list-disc list-inside mt-1 space-y-0.5">
                {qualityScore.suggestions.slice(0, 3).map((suggestion, idx) => (
                  <li key={idx}>{suggestion}</li>
                ))}
              </ul>
            </AlertDescription>
          </Alert>
        )}

        <div className="flex gap-2 justify-end pt-2">
          {onClose && (
            <Button variant="outline" onClick={() => { void onClose(); }} disabled={isSubmitting}>
              Skip
            </Button>
          )}
          <Button
            onClick={() => { void handleSubmit(); }}
            disabled={rating === 0 || isSubmitting}
            className="bg-indigo-600 hover:bg-indigo-700"
          >
            {isSubmitting ? 'Submitting...' : 'Submit Feedback'}
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

/**
 * Add Snip Dialog
 * UI for selecting and importing snips into a workflow
 * Includes collision detection and resolution modal (Prompt 31)
 */
import { useQueryClient } from "@tanstack/react-query";
import { Loader2, Plus, Package } from "lucide-react";
import { useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import { useToast } from "@/hooks/use-toast";
import { importSnip, validateSnipImport } from "@/lib/snips/importService";
import { getAllSnips } from "@/lib/snips/registry";

import { CollisionResolutionModal } from "./CollisionResolutionModal";
interface AddSnipDialogProps {
    workflowId: string;
    open: boolean;
    onOpenChange: (open: boolean) => void;
}
export function AddSnipDialog({ workflowId, open, onOpenChange }: AddSnipDialogProps) {
    const { toast } = useToast();
    const queryClient = useQueryClient();
    const [importing, setImporting] = useState(false);
    const [selectedSnipId, setSelectedSnipId] = useState<string | null>(null);
    // Collision resolution state
    const [showCollisionModal, setShowCollisionModal] = useState(false);
    const [detectedCollisions, setDetectedCollisions] = useState<string[]>([]);
    const [resolvedMappings, setResolvedMappings] = useState<Record<string, string>>({});
    const snips = getAllSnips();
    const handleImportClick = async () => {
        if (!selectedSnipId) {
            toast({
                title: "No snip selected",
                description: "Please select a snip to import",
                variant: "destructive",
            });
            return;
        }
        // Step 1: Detect collisions
        setImporting(true);
        try {
            const validation = await validateSnipImport(workflowId, selectedSnipId);
            if (validation.aliasConflicts.length > 0) {
                // Collisions detected - show resolution modal
                setDetectedCollisions(validation.aliasConflicts);
                setShowCollisionModal(true);
                setImporting(false);
            } else {
                // No collisions - proceed with import
                await executeImport({});
            }
        } catch (error) {
            console.error('[AddSnipDialog] Validation error:', error);
            toast({
                title: "Validation failed",
                description: error instanceof Error ? error.message : "Failed to validate snip",
                variant: "destructive",
            });
            setImporting(false);
        }
    };
    const executeImport = async (aliasMappings: Record<string, string>) => {
        if (!selectedSnipId) {return;}
        setImporting(true);
        try {
            const result = await importSnip(workflowId, {
                snipId: selectedSnipId,
                aliasMappings,
            });
            // Invalidate workflow queries to refresh sections/steps
            await queryClient.invalidateQueries({ queryKey: ["workflow", workflowId] });
            await queryClient.invalidateQueries({ queryKey: ["sections", workflowId] });
            await queryClient.invalidateQueries({ queryKey: ["workflow-all-steps", workflowId] });
            // Enhanced feedback based on collision status
            let description = "Pages and questions have been added to your workflow";
            if (result.hadCollisions) {
                description += ". Some variables were renamed to avoid conflicts";
            }
            toast({
                title: "Snip imported",
                description,
            });
            onOpenChange(false);
            setSelectedSnipId(null);
            setShowCollisionModal(false);
            setDetectedCollisions([]);
            setResolvedMappings({});
        } catch (error) {
            console.error('[AddSnipDialog] Import error:', error);
            toast({
                title: "Import failed",
                description: error instanceof Error ? error.message : "Failed to import snip",
                variant: "destructive",
            });
        } finally {
            setImporting(false);
        }
    };
    const handleCollisionResolve = (resolutions: Record<string, string>) => {
        setResolvedMappings(resolutions);
        setShowCollisionModal(false);
        // Proceed with import using resolved mappings
        executeImport(resolutions);
    };
    const handleCollisionCancel = () => {
        setShowCollisionModal(false);
        setDetectedCollisions([]);
        setResolvedMappings({});
        toast({
            title: "Import cancelled",
            description: "No changes were made to your workflow",
        });
    };
    return (
        <>
            <Dialog open={open} onOpenChange={onOpenChange}>
                <DialogContent className="max-w-3xl max-h-[80vh] overflow-y-auto">
                    <DialogHeader>
                        <DialogTitle>Add Snip to Workflow</DialogTitle>
                        <DialogDescription>
                            Select a reusable workflow fragment to add to your workflow.
                            Snips include pre-configured pages, questions, and logic.
                        </DialogDescription>
                    </DialogHeader>
                    <div className="space-y-3">
                        {snips.length === 0 ? (
                            <div className="text-center py-8 text-muted-foreground">
                                <Package className="w-12 h-12 mx-auto mb-2 opacity-50" />
                                <p>No snips available yet</p>
                            </div>
                        ) : (
                            snips.map((snip) => (
                                <Card
                                    key={snip.id}
                                    className={`cursor-pointer transition-all ${selectedSnipId === snip.id
                                        ? "ring-2 ring-indigo-500 border-indigo-500"
                                        : "hover:border-indigo-300"
                                        }`}
                                    onClick={() => { void setSelectedSnipId(snip.id); }}
                                >
                                    <CardHeader className="pb-3">
                                        <div className="flex items-start justify-between">
                                            <div>
                                                <CardTitle className="text-base">{snip.displayName}</CardTitle>
                                                <CardDescription className="text-sm mt-1">
                                                    {snip.description}
                                                </CardDescription>
                                            </div>
                                            {snip.category && (
                                                <Badge variant="secondary" className="ml-2">
                                                    {snip.category}
                                                </Badge>
                                            )}
                                        </div>
                                    </CardHeader>
                                    <CardContent className="pt-0">
                                        <div className="flex items-center gap-4 text-xs text-muted-foreground">
                                            <span>{snip.pages.length} page{snip.pages.length !== 1 ? 's' : ''}</span>
                                            <span>
                                                {snip.pages.reduce((sum, p) => sum + p.questions.length, 0)} question
                                                {snip.pages.reduce((sum, p) => sum + p.questions.length, 0) !== 1 ? 's' : ''}
                                            </span>
                                            <span className="ml-auto font-mono">v{snip.version}</span>
                                        </div>
                                    </CardContent>
                                </Card>
                            ))
                        )}
                    </div>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => { void onOpenChange(false); }} disabled={importing}>
                            Cancel
                        </Button>
                        <Button onClick={() => { void handleImportClick(); }} disabled={!selectedSnipId || importing}>
                            {importing ? (
                                <>
                                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                                    Importing...
                                </>
                            ) : (
                                <>
                                    <Plus className="w-4 h-4 mr-2" />
                                    Import Snip
                                </>
                            )}
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
            {/* Collision Resolution Modal */}
            <CollisionResolutionModal
                open={showCollisionModal}
                onOpenChange={setShowCollisionModal}
                collisions={detectedCollisions}
                onResolve={handleCollisionResolve}
                onCancel={handleCollisionCancel}
            />
        </>
    );
}

import { Loader2, Sparkles, Send, Check, X, Paperclip, FileText } from "lucide-react";
import React, { useState, useRef, useEffect } from 'react';

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { ScrollArea } from "@/components/ui/scroll-area";
import { useToast } from "@/hooks/use-toast";
import { cn } from "@/lib/utils";
import { getAccessToken } from "@/lib/vault-api";
import { useReviseWorkflow, useUpdateWorkflow, useWorkflowMode } from "@/lib/vault-hooks";
interface Message {
    role: 'user' | 'assistant';
    content: string;
    diff?: any;
    timestamp: number;
    status?: 'pending' | 'applied' | 'discarded';
}
interface UploadedFile {
    name: string;
    content: string;
}
interface AiConversationPanelProps {
    workflowId: string;
    currentWorkflow: any; // Basic workflow metadata
    transformBlocks?: any[];
    initialPrompt?: string;
    className?: string;
}
export function AiConversationPanel({ workflowId, currentWorkflow, transformBlocks = [], initialPrompt, className }: AiConversationPanelProps) {
    const [input, setInput] = useState('');
    const [messages, setMessages] = useState<Message[]>([
        {
            role: 'assistant',
            content: 'Hi! I can help you revise this workflow. Try saying "Add a phone number question" or "Make the email required".\n\nYou can also drop PDF or DOCX files here to give me more context!',
            timestamp: Date.now()
        }
    ]);
    const [proposedWorkflow, setProposedWorkflow] = useState<any>(null);
    const [isDragging, setIsDragging] = useState(false);
    const [uploading, setUploading] = useState(false);
    const [contextFiles, setContextFiles] = useState<UploadedFile[]>([]);
    const scrollRef = useRef<HTMLDivElement>(null);
    const { toast } = useToast();
    const reviseMutation = useReviseWorkflow();
    const updateMutation = useUpdateWorkflow();
    const { data: workflowMode } = useWorkflowMode(workflowId);
    const mode = workflowMode?.mode || 'easy';
    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
    }, [messages]);
    // Handle initial prompt from "Create with AI" flow
    const hasSentInitialPrompt = useRef(false);
    useEffect(() => {
        if (initialPrompt && !hasSentInitialPrompt.current && messages.length === 1) { // 1 because of greeting
            hasSentInitialPrompt.current = true;
            setInput(initialPrompt);
            // We need to wait a tick for the state to update, then send
            setTimeout(() => {
                void handleSend(initialPrompt);
            }, 100);
        }
    }, [initialPrompt, messages.length]);
    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(true);
    };
    const handleDragLeave = (e: React.DragEvent) => {
        e.preventDefault();
        // Prevent flickering: only disable if leaving the main container, not entering a child
        if (e.currentTarget.contains(e.relatedTarget as Node)) { return; }
        setIsDragging(false);
    };
    const handleDrop = async (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
        const files = Array.from(e.dataTransfer.files);
        if (files.length === 0) { return; }
        setUploading(true);
        const newContextFiles: UploadedFile[] = [];
        try {
            for (const file of files) {
                // Check type (MIME or Extension)
                const allowedTypes = [
                    'application/pdf',
                    'application/msword',
                    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
                    'text/plain',
                    'text/markdown'
                ];
                const allowedExtensions = ['.pdf', '.doc', '.docx', '.txt', '.md'];
                const isTypeValid = allowedTypes.includes(file.type);
                const isExtValid = allowedExtensions.some(ext => file.name.toLowerCase().endsWith(ext));
                if (!isTypeValid && !isExtValid) {
                    toast({ title: "Skipped File", description: `${file.name} is not a supported document type (PDF/Word/Txt).` });
                    continue;
                }
                const formData = new FormData();
                formData.append('file', file);
                try {
                    // Use fetch directly to handle FormData correctly (apiRequest forces JSON)
                    const token = getAccessToken();
                    const headers: Record<string, string> = {};
                    if (token) { headers['Authorization'] = `Bearer ${token}`; }
                    const res = await fetch('/api/ai/doc/extract-text', {
                        method: 'POST',
                        body: formData,
                        headers
                    });
                    if (!res.ok) {
                        const errData = await res.json().catch(() => ({}));
                        throw new Error(errData.message || res.statusText);
                    }
                    const data = await res.json();
                    if (data.text) {
                        newContextFiles.push({
                            name: file.name,
                            content: data.text
                        });
                    }
                } catch (err) {
                    console.error(err);
                    toast({ title: "Upload Failed", variant: "destructive", description: `Could not process ${file.name}` });
                }
            }
            setContextFiles(prev => [...prev, ...newContextFiles]);
        } finally {
            setUploading(false);
        }
    };
    const handleSend = async (textOverride?: string) => {
        const textToSend = textOverride !== undefined ? textOverride : input;
        if (!textToSend.trim() && contextFiles.length === 0) { return; }
        // Construct full message with context
        let fullMessage = textToSend;
        if (contextFiles.length > 0) {
            fullMessage += `\n\n--- CONTEXT FROM UPLOADED FILES ---\n`;
            contextFiles.forEach(f => {
                fullMessage += `DATA FROM FILE: ${f.name}\n${f.content}\n\n`;
            });
            fullMessage += `--- END CONTEXT ---\n`;
        }
        // Display message (hide massive context from UI, show attachment badges instead)
        const displayContent = textToSend || (contextFiles.length > 0 ? "Processed uploaded files." : "");
        const userMsg: Message = {
            role: 'user',
            content: displayContent,
            timestamp: Date.now()
        };
        // Add a "visible" note about attachments if they exist
        if (contextFiles.length > 0) {
            userMsg.content += `\n\n[Attached: ${contextFiles.map(f => f.name).join(', ')}]`;
        }
        setMessages(prev => [...prev, userMsg]);
        setInput('');
        setContextFiles([]); // Clear context after sending
        setProposedWorkflow(null);
        try {
            const history = messages
                .filter(m => !m.diff)
                .map(m => ({ role: m.role, content: m.content }));
            const fullWorkflow = {
                title: currentWorkflow.title || 'Untitled Workflow',
                description: currentWorkflow.description ?? '',
                sections: currentWorkflow.sections ?? [],
                logicRules: currentWorkflow.logicRules ?? [],
                transformBlocks: transformBlocks,
                notes: ''
            };
            const result = await reviseMutation.mutateAsync({
                workflowId,
                currentWorkflow: fullWorkflow,
                userInstruction: fullMessage, // Send the full context to AI
                conversationHistory: history,
                mode: mode
            });
            // Auto-apply if in easy mode
            if (mode === 'easy' && result.updatedWorkflow) {
                try {
                    await updateMutation.mutateAsync({
                        id: workflowId,
                        ...result.updatedWorkflow
                    });
                    const assistantMsg: Message = {
                        role: 'assistant',
                        content: result.explanation ? result.explanation.join(' ') : 'I have updated the workflow.',
                        diff: result.diff,
                        timestamp: Date.now(),
                        status: 'applied'
                    };
                    setMessages(prev => [...prev, assistantMsg]);
                    toast({ title: "Changes Applied", description: "Workflow updated successfully." });
                    return; // Done
                } catch (error) {
                    console.error("Auto-apply failed", error);
                    // Fallback to manual if update fails
                }
            }
            // Normal Flow (Manual Review)
            const assistantMsg: Message = {
                role: 'assistant',
                content: result.explanation ? result.explanation.join(' ') : 'Here are the suggested changes.',
                diff: result.diff,
                timestamp: Date.now(),
                status: 'pending'
            };
            setMessages(prev => [...prev, assistantMsg]);
            setProposedWorkflow(result.updatedWorkflow);
        } catch (error: any) {
            setMessages(prev => [...prev, {
                role: 'assistant',
                content: `Sorry, I encountered an error: ${error.message}`,
                timestamp: Date.now()
            }]);
        }
    };
    const handleApply = async () => {
        if (!proposedWorkflow) { return; }
        try {
            await updateMutation.mutateAsync({
                id: workflowId,
                ...proposedWorkflow
            });
            toast({ title: "Changes Applied", description: "Workflow updated successfully." });
            setProposedWorkflow(null);
            // Update the last message status to applied
            setMessages(prev => {
                const newMessages = [...prev];
                const lastMsg = newMessages[newMessages.length - 1];
                if (lastMsg.role === 'assistant' && lastMsg.status === 'pending') {
                    lastMsg.status = 'applied';
                } else {
                    // fallback if message structure changed, though unlikely in this flow
                    newMessages.push({
                        role: 'assistant',
                        content: "Changes applied!",
                        timestamp: Date.now(),
                        status: 'applied'
                    });
                }
                return newMessages;
            });
        } catch (error) {
            toast({ title: "Update Failed", variant: "destructive", description: "Could not apply changes." });
        }
    };
    const handleDiscard = () => {
        setProposedWorkflow(null);
        setMessages(prev => {
            const newMessages = [...prev];
            const lastMsg = newMessages[newMessages.length - 1];
            if (lastMsg.role === 'assistant' && lastMsg.status === 'pending') {
                lastMsg.status = 'discarded';
            } else {
                newMessages.push({
                    role: 'assistant',
                    content: "Changes discarded.",
                    timestamp: Date.now()
                });
            }
            return newMessages;
        });
    };
    return (
        <div
            className={cn("flex flex-col h-full bg-background relative", className)}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={(e) => { void handleDrop(e); }}
        >
            {/* Drag Overlay */}
            {isDragging && (
                <div className="absolute inset-0 z-50 bg-background/90 border-2 border-dashed border-primary flex items-center justify-center pointer-events-none">
                    <div className="text-center p-8">
                        <Paperclip className="w-12 h-12 mx-auto mb-4 text-primary" />
                        <h3 className="text-lg font-semibold">Drop files to add context</h3>
                        <p className="text-sm text-muted-foreground">PDFs and Word documents supported</p>
                    </div>
                </div>
            )}
            <div className="p-4 border-b flex items-center gap-2 font-semibold bg-muted/40">
                <Sparkles className="w-5 h-5 text-purple-500" />
                AI Assistant
                {mode === 'easy' && <Badge variant="secondary" className="ml-auto text-xs">Easy Mode</Badge>}
            </div>
            <ScrollArea className="flex-1 p-4" ref={scrollRef}>
                <div className="space-y-6 pb-4">
                    {messages.map((msg, idx) => (
                        <div key={idx} className={`flex flex-col gap-2 ${msg.role === 'user' ? 'items-end' : 'items-start'} w-full`}>
                            <div className={`rounded-lg p-3 max-w-[80%] text-sm shadow-sm ${msg.role === 'user'
                                ? 'bg-primary text-primary-foreground'
                                : 'bg-card border'
                                }`}>
                                <p className="whitespace-pre-wrap break-words">{msg.content}</p>
                            </div>
                            {msg.diff?.changes && msg.diff.changes.length > 0 && (
                                <Card className={cn(
                                    "w-full max-w-[80%] mt-1 p-3 border shadow-sm self-start",
                                    msg.status === 'applied' ? "bg-green-50/50 border-green-200 dark:bg-green-900/10 dark:border-green-900" :
                                        msg.status === 'discarded' ? "bg-muted/50 opacity-70" :
                                            "bg-purple-50/50 border-purple-200 dark:bg-purple-900/10 dark:border-purple-900"
                                )}>
                                    <div className="flex items-center justify-between mb-2">
                                        <span className={cn(
                                            "text-xs font-semibold",
                                            msg.status === 'applied' ? "text-green-700 dark:text-green-400" :
                                                msg.status === 'discarded' ? "text-muted-foreground" :
                                                    "text-purple-700 dark:text-purple-300"
                                        )}>
                                            {msg.status === 'applied' ? 'Changes Applied' :
                                                msg.status === 'discarded' ? 'Changes Discarded' :
                                                    'Proposed Changes'}
                                        </span>
                                        <Badge variant="outline" className="text-[10px] whitespace-nowrap ml-2">{msg.diff.changes.length} changes</Badge>
                                    </div>
                                    <ul className="space-y-1 mb-3 min-w-0">
                                        {msg.diff.changes.map((change: any, i: number) => (
                                            <li key={i} className="text-xs flex gap-2 w-full min-w-0 items-center">
                                                <Badge
                                                    variant={change.type === 'add' ? 'default' : change.type === 'remove' ? 'destructive' : 'secondary'}
                                                    className={cn("h-5 px-1 text-[10px] capitalize shrink-0",
                                                        change.type === 'add' && "bg-green-500 hover:bg-green-600",
                                                        change.type === 'update' && "bg-blue-500 hover:bg-blue-600"
                                                    )}
                                                >
                                                    {change.type}
                                                </Badge>
                                                <span className="whitespace-normal break-words text-muted-foreground min-w-0">{change.explanation}</span>
                                            </li>
                                        ))}
                                    </ul>
                                    {/* Only show buttons if pending */}
                                    {msg.status === 'pending' && proposedWorkflow && idx === messages.length - 1 && (
                                        <div className="flex gap-2 justify-end pt-2 border-t border-purple-200/50 dark:border-purple-800/50">
                                            <Button size="sm" variant="ghost" className="h-7 text-xs hover:bg-red-100 hover:text-red-600 dark:hover:bg-red-900/30" onClick={() => { void handleDiscard(); }}>
                                                <X className="w-3 h-3 mr-1" /> Discard
                                            </Button>
                                            <Button size="sm" className="h-7 text-xs bg-purple-600 hover:bg-purple-700 text-white" onClick={() => { void handleApply(); }}>
                                                <Check className="w-3 h-3 mr-1" /> Apply
                                            </Button>
                                        </div>
                                    )}
                                </Card>
                            )}
                        </div>
                    ))}
                    {(reviseMutation.isPending || uploading) && (
                        <div className="flex items-start gap-2">
                            <div className="bg-muted rounded-lg p-3 flex items-center gap-2">
                                <Loader2 className="w-4 h-4 animate-spin text-muted-foreground" />
                                <span className="text-xs text-muted-foreground">
                                    {uploading ? "Processing file..." : "Thinking..."}
                                </span>
                            </div>
                        </div>
                    )}
                    <div ref={scrollRef} />
                </div>
            </ScrollArea>
            <div className="p-4 border-t bg-background">
                {/* File Previews */}
                {contextFiles.length > 0 && (
                    <div className="flex flex-wrap gap-2 mb-2">
                        {contextFiles.map((f, i) => (
                            <Badge key={i} variant="secondary" className="pl-1 pr-2 py-0.5 h-6 text-xs flex items-center gap-1">
                                <FileText className="w-3 h-3" />
                                <span className="max-w-[100px] truncate">{f.name}</span>
                                <button
                                    onClick={() => setContextFiles(prev => prev.filter((_, idx) => idx !== i))}
                                    className="ml-1 hover:text-destructive"
                                >
                                    <X className="w-3 h-3" />
                                </button>
                            </Badge>
                        ))}
                    </div>
                )}
                <form
                    className="flex gap-2"
                    onSubmit={(e) => {
                        e.preventDefault();
                        void handleSend();
                    }}
                >
                    <Input
                        placeholder={mode === 'easy' ? "Describe changes to auto-apply..." : "Describe changes..."}
                        value={input}
                        onChange={(e) => { void setInput(e.target.value); }}
                        disabled={reviseMutation.isPending || !!proposedWorkflow || uploading}
                        className="flex-1"
                    />
                    <Button type="submit" size="icon" disabled={(!input.trim() && contextFiles.length === 0) || reviseMutation.isPending || !!proposedWorkflow || uploading}>
                        <Send className="w-4 h-4" />
                    </Button>
                </form>
                {!!proposedWorkflow && (
                    <p className="text-xs text-center mt-2 text-muted-foreground animate-pulse">Waiting for your review...</p>
                )}
            </div>
        </div>
    );
}

import { useState, useEffect } from "react";

import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { useToast } from "@/hooks/use-toast";
import { getAvailableBlockTypes, type Mode } from "@/lib/mode";
import { useCreateBlock, useUpdateBlock, useCreateTransformBlock, useUpdateTransformBlock } from "@/lib/vault-hooks";

import type { BlockPhase, WriteBlockConfig, ReadTableConfig, ExternalSendBlockConfig, ValidateConfig, QueryBlockConfig } from "@shared/types/blocks";

import { RegularBlockForm } from "./forms/RegularBlockForm";
import { TransformBlockForm } from "./forms/TransformBlockForm";

// UniversalBlock type definition (matching what was in BlocksPanel)
export type UniversalBlock = {
    id: string;
    type: string;
    phase: string;
    order: number;
    enabled: boolean;
    raw: Record<string, unknown> | null;
    source: 'regular' | 'transform';
    title?: string;
    displayType?: string;
};


export interface BlockFormData {
    phase: string;
    enabled: boolean;
    order: number | string;
    type: string;
    config: Record<string, unknown>;
    name: string;
    language: string;
    code: string;
    inputKeys: string[];
    outputKey: string;
    timeoutMs: number;
}

export function BlockEditorDialog({
    workflowId,
    block,
    mode,
    isOpen,
    onClose,
}: {
    workflowId: string;
    block: UniversalBlock | null;
    mode: Mode;
    isOpen: boolean;
    onClose: () => void;
}) {
    const createBlockMutation = useCreateBlock();
    const updateBlockMutation = useUpdateBlock();
    const createTransformMutation = useCreateTransformBlock();
    const updateTransformMutation = useUpdateTransformBlock();
    const { toast } = useToast();

    // Determine initial state
    // If block is null, we are creating. Default to 'regular'.
    const [creationMode, setCreationMode] = useState<'regular' | 'transform'>(block?.source || 'regular');

    const [formData, setFormData] = useState<BlockFormData>({
        // Common
        phase: block?.phase || "onRunStart",
        enabled: block?.enabled ?? true,
        order: block?.order ?? 0,

        // Regular Block
        type: block?.source === 'regular' ? block.type : 'write', // Default to write for new blocks
        config: (block?.raw?.config as Record<string, unknown>) || ({} as Record<string, unknown>),

        // Transform Block
        name: (block?.raw?.name as string) ?? "",
        language: (block?.raw?.language as string) || "javascript",
        code: (block?.raw?.code as string) ?? "",
        inputKeys: (block?.raw?.inputKeys as string[]) ?? [],
        outputKey: (block?.raw?.outputKey as string) ?? "",
        timeoutMs: (block?.raw?.timeoutMs as number) || 1000,
    });

    useEffect(() => {
        if (isOpen) {
            const source = block?.source || 'regular';
            setCreationMode(source);

            // Determine block type correctly
            // If block exists, use its type. 
            // If it's a new block (block is null), DO NOT overwrite the type set by useState unless we want to reset it?
            // Actually, for new blocks, useState sets the default. We should only override if block exists.
            let blockType = formData.type; // Keep existing defaults for new blocks

            if (block) {
                // MIGRATION: Auto-fix legacy blocks with wrong type
                blockType = source === 'regular' ? block.type : 'write';
                if (source === 'regular') {
                    // Normalize send_table to write for routing
                    if (blockType === 'send_table') {
                        blockType = 'write';
                    }
                }
            }

            const isReadTable = blockType === 'read_table';
            const isWriteBlock = blockType === 'write' || blockType === 'send_table';

            setFormData({
                phase: block?.phase || (isReadTable ? "onSectionEnter" : isWriteBlock ? "onSectionSubmit" : "onRunStart"),
                enabled: block?.enabled ?? true,
                order: block?.order ?? 0,
                type: blockType, // Use derived type
                config: (block?.raw?.config as Record<string, unknown>) || ({} as Record<string, unknown>),
                name: (block?.raw?.name as string) ?? "",
                language: (block?.raw?.language as string) || "javascript",
                code: (block?.raw?.code as string) ?? "",
                inputKeys: (block?.raw?.inputKeys as string[]) ?? [],
                outputKey: (block?.raw?.outputKey as string) ?? "",
                timeoutMs: (block?.raw?.timeoutMs as number) || 1000,
            });
        }
    }, [isOpen, block]);

    const handleSave = async () => {
        try {
            if (creationMode === 'regular') {
                const data = {
                    type: formData.type,
                    phase: formData.phase,
                    config: formData.config,
                    enabled: formData.enabled === undefined ? true : formData.enabled,
                    order: Number(formData.order) || 0,
                    // Preserve existing sectionId if updating, otherwise null (or handled by caller for create)
                    sectionId: (block?.raw?.sectionId as string | null) ?? null
                };

                if (block && block.source === 'regular') {
                    await updateBlockMutation.mutateAsync({
                        id: block.id,
                        workflowId,
                        ...data,
                        type: data.type as any,
                        phase: data.phase as any,
                        sectionId: (block?.raw?.sectionId as string | null) ?? null
                    });
                } else {
                    await createBlockMutation.mutateAsync({
                        workflowId,
                        ...data,
                        type: data.type as any,
                        phase: data.phase as any,
                        sectionId: (block?.raw?.sectionId as string | null) ?? null
                    });
                }
            } else {
                // Transform
                const data = {
                    name: formData.name,
                    language: formData.language,
                    phase: formData.phase,
                    code: formData.code,
                    inputKeys: formData.inputKeys,
                    outputKey: formData.outputKey,
                    timeoutMs: formData.timeoutMs,
                    enabled: formData.enabled === undefined ? true : formData.enabled,
                    order: Number(formData.order) || 0,
                    // Preserve existing sectionId for transforms too
                    sectionId: (block?.raw?.sectionId as string | null) ?? null
                };

                if (block && block.source === 'transform') {
                    await updateTransformMutation.mutateAsync({
                        id: block.id,
                        workflowId,
                        ...data,
                        language: data.language as any,
                        phase: data.phase as any
                    });
                } else {
                    await createTransformMutation.mutateAsync({
                        workflowId,
                        ...data,
                        language: data.language as any,
                        phase: data.phase as any
                    });
                }
            }

            toast({ title: "Success", description: "Block saved successfully." });
            onClose();
        } catch (e) {
            console.error(e);
            toast({ title: "Error", description: "Failed to save block.", variant: "destructive" });
        }
    };

    const availableBlockTypes = getAvailableBlockTypes(mode);

    return (
        <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
            <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle>
                        {block ? (
                            // Use block.type for title (direct from database, not formData)
                            (block.type === 'write' || block.type === 'send_table') ? 'Send Data to Table' :
                                block.type === 'read_table' ? 'Read from Table' :
                                    block.type === 'external_send' ? 'Send Data to API' :
                                        block.type === 'list_tools' ? 'List Tools' :
                                            block.type === 'query' ? 'Query Data' :
                                                block.type === 'validate' ? 'Validate' :
                                                    block.type === 'js' ? 'JS Transform' :
                                                        `Edit ${block.title || block.type}`
                        ) : "Add New Block"}
                    </DialogTitle>
                    <DialogDescription>
                        {creationMode === 'regular' ? "Configure a standard workflow block." : "Configure a custom code transformation."}
                    </DialogDescription>
                </DialogHeader>

                <div className="py-4 space-y-6">
                    {/* Top Controls: Type Selection (Only if creating new) */}
                    {!block && (
                        <div className="flex items-center gap-4 p-4 bg-muted/30 rounded-lg border">
                            <Label>Block Category:</Label>
                            <div className="flex gap-2">
                                <Button
                                    variant={creationMode === 'regular' ? "default" : "outline"}
                                    size="sm"
                                    onClick={() => { void setCreationMode('regular'); }}
                                >
                                    Standard Block
                                </Button>
                                <Button
                                    variant={creationMode === 'transform' ? "default" : "outline"}
                                    size="sm"
                                    onClick={() => { void setCreationMode('transform'); }}
                                    disabled={mode === 'easy'}
                                >
                                    Code Transform
                                </Button>
                            </div>
                            {mode === 'easy' && creationMode === 'regular' && (
                                <span className="text-xs text-muted-foreground ml-2">Code transforms are an Advanced Mode feature.</span>
                            )}
                        </div>
                    )}

                    {/* Configuration Form */}
                    {creationMode === 'regular' ? (
                        <RegularBlockForm
                            formData={formData}
                            setFormData={setFormData}
                            mode={mode}
                            block={block}
                            workflowId={workflowId}
                        />
                    ) : (
                        <TransformBlockForm
                            formData={formData}
                            setFormData={setFormData}
                            workflowId={workflowId}
                        />
                    )}
                </div>

                <DialogFooter>
                    <Button variant="outline" onClick={() => { void onClose(); }}>Cancel</Button>
                    <Button onClick={() => { void handleSave(); }}>Save Block</Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

/**
 * Canvas Editor - Section/Step editor in center pane
 */

/* eslint-disable @typescript-eslint/no-unsafe-member-access */
