/* eslint-disable @typescript-eslint/no-unsafe-call */
/* eslint-disable @typescript-eslint/no-unsafe-argument */

import { Workflow } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { UI_LABELS } from "@/lib/labels";
import { useSections, useSteps, useUpdateSection, useUpdateStep, useCreateStep, useStep } from "@/lib/vault-hooks";
import { useWorkflowBuilder } from "@/store/workflow-builder";

export function CanvasEditor({ workflowId }: { workflowId: string }) {
  const { selection, mode } = useWorkflowBuilder();
  const { data: sections } = useSections(workflowId);
  const { data: step } = useStep(selection && selection.type === "step" ? selection.id : "");

  if (!selection) {
    return (
      <div className="h-full flex items-center justify-center">
        <div className="text-center max-w-md">
          <Workflow className="w-16 h-16 mx-auto text-muted-foreground mb-4" />
          <h3 className="text-lg font-semibold mb-2">No Selection</h3>
          <p className="text-muted-foreground text-sm">
            Select a section or step from the sidebar to edit its properties
          </p>
        </div>
      </div>
    );
  }

  if (selection.type === "section") {
    const section = sections?.find((s) => s.id === selection.id);
    if (!section) { return null; }
    return <SectionCanvas section={section} workflowId={workflowId} />;
  }



  if (selection.type === "step" && step) {
    return <StepCanvas step={step} sectionId={step.sectionId} />;
  }

  return null;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function SectionCanvas({ section, workflowId }: { section: any; workflowId: string }) {
  const updateMutation = useUpdateSection();

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const handleUpdate = (field: string, value: any) => {
    updateMutation.mutate({ id: section.id, workflowId, [field]: value });
  };

  return (
    <div className="p-8 max-w-4xl mx-auto space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>{UI_LABELS.PAGE_SETTINGS}</CardTitle>
          <CardDescription>Configure this page's properties</CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="space-y-2">
            <Label htmlFor="section-title">Title *</Label>
            <Input
              id="section-title"
              value={section.title}
              onChange={(e) => { void handleUpdate("title", e.target.value); }}
              onBlur={() => { }}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="section-description">Description</Label>
            <Textarea
              id="section-description"
              value={section.description ?? ""}
              onChange={(e) => { void handleUpdate("description", e.target.value); }}
              rows={4}
              placeholder="Optional description for this page..."
            />
          </div>
        </CardContent>
      </Card>

      <StepEmptyState sectionId={section.id} />
    </div>
  );
}

function StepEmptyState({ sectionId }: { sectionId: string }) {
  const { data: steps } = useSteps(sectionId);
  const createStepMutation = useCreateStep();

  // Only show if no steps
  if (!steps || steps.length > 0) { return null; }

  const handleQuickAdd = async (type: string, title: string) => {
    await createStepMutation.mutateAsync({
      sectionId,
      type: type as any,
      title,
      description: null,
      required: false,
      alias: null,
      options: null,
      order: 0,
      config: {},
    });
  };

  return (
    <Card className="border-dashed bg-muted/30">
      <CardContent className="py-12 flex flex-col items-center text-center">
        <div className="p-3 bg-background rounded-full mb-4 shadow-sm">
          <Workflow className="w-6 h-6 text-muted-foreground" />
        </div>
        <h3 className="font-semibold text-lg mb-1">Add your first question</h3>
        <p className="text-muted-foreground text-sm mb-6 max-w-sm">
          This page is empty. Choose a question type to get started.
        </p>
        <div className="flex flex-wrap gap-3 justify-center">
          <Button variant="outline" onClick={() => { void handleQuickAdd("short_text", "Client Name"); }}>
            Short Text
          </Button>
          <Button variant="outline" onClick={() => { void handleQuickAdd("yes_no", "Confirmation"); }}>
            Yes / No
          </Button>
          <Button variant="outline" onClick={() => { void handleQuickAdd("single_choice", "Select Option"); }}>
            Choice
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function StepCanvas({ step, sectionId }: { step: any; sectionId: string }) {
  const { mode } = useWorkflowBuilder();
  const updateMutation = useUpdateStep();

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const handleUpdate = (field: string, value: any) => {
    updateMutation.mutate({ id: step.id, sectionId, [field]: value });
  };

  return (
    <div className="p-8 max-w-4xl mx-auto">
      <Card>
        <CardHeader>
          <CardTitle>Step Settings</CardTitle>
          <CardDescription>Configure this step&apos;s properties and behavior</CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Title */}
          <div className="space-y-2">
            <Label htmlFor="step-title">Label *</Label>
            <Input
              id="step-title"
              value={step.title}
              onChange={(e) => { void handleUpdate("title", e.target.value); }}
              autoFocus
            />
          </div>

          {/* Description */}
          <div className="space-y-2">
            <Label htmlFor="step-description">Description</Label>
            <Textarea
              id="step-description"
              value={step.description ?? ""}
              onChange={(e) => { void handleUpdate("description", e.target.value); }}
              rows={3}
              placeholder="Help text shown to participants..."
            />
          </div>

          {/* Variable Alias */}
          <div className="space-y-2">
            <Label htmlFor="step-alias">Variable (alias)</Label>
            <Input
              id="step-alias"
              value={step.alias ?? ""}
              onChange={(e) => { void handleUpdate("alias", e.target.value ?? null); }}
              placeholder="e.g., firstName, age, department"
              className="font-mono text-sm"
            />
            <p className="text-xs text-muted-foreground">
              Optional: A human-friendly name to reference this step&apos;s answer in logic and blocks
            </p>
          </div>

          {/* Type */}
          <div className="space-y-2">
            <Label htmlFor="step-type">Input Type</Label>
            <Select value={step.type} onValueChange={(v) => handleUpdate("type", v)}>
              <SelectTrigger id="step-type">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="short_text">Short Text</SelectItem>
                <SelectItem value="long_text">Long Text</SelectItem>
                <SelectItem value="radio">Radio (Single Choice)</SelectItem>
                <SelectItem value="multiple_choice">Multiple Choice</SelectItem>
                <SelectItem value="yes_no">Yes/No</SelectItem>
                <SelectItem value="date_time">Date/Time</SelectItem>
                <SelectItem value="file_upload">File Upload</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {/* Required */}
          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <Label htmlFor="step-required">Required</Label>
              <p className="text-sm text-muted-foreground">
                Participants must provide an answer
              </p>
            </div>
            <Switch
              id="step-required"
              checked={step.required}
              onCheckedChange={(v) => handleUpdate("required", v)}
            />
          </div>

          {/* Options for choice types */}
          {(step.type === "radio" || step.type === "multiple_choice") && (
            <div className="space-y-2">
              <Label>Options</Label>
              <OptionsEditor
                options={step.options?.options ?? []}
                onChange={(opts) => { void handleUpdate("options", { options: opts }); }}
              />
            </div>
          )}

          {/* Advanced Mode Fields */}
          {mode === "advanced" && (
            <div className="pt-4 border-t space-y-4">
              <h4 className="font-medium text-sm">Advanced</h4>
              <div className="space-y-2">
                <Label htmlFor="step-key" className="text-xs">
                  Variable Key (for formulas/logic)
                </Label>
                <Input
                  id="step-key"
                  value={step.id}
                  disabled
                  className="text-xs font-mono"
                />
                <p className="text-xs text-muted-foreground">
                  Use this ID in block configs to reference this step&apos;s value
                </p>
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

function OptionsEditor({ options, onChange }: { options: string[]; onChange: (opts: string[]) => void }) {
  const handleAdd = () => {
    onChange([...options, `Option ${options.length + 1}`]);
  };

  const handleChange = (index: number, value: string) => {
    const newOptions = [...options];
    newOptions[index] = value;
    onChange(newOptions);
  };

  const handleRemove = (index: number) => {
    onChange(options.filter((_, i) => i !== index));
  };

  return (
    <div className="space-y-2">
      {options.map((option, index) => (
        <div key={index} className="flex gap-2">
          <Input
            value={option}
            onChange={(e) => { void handleChange(index, e.target.value); }}
            placeholder={`Option ${index + 1}`}
          />
          <Button variant="outline" size="icon" onClick={() => { void handleRemove(index); }}>
            ├ù
          </Button>
        </div>
      ))}
      <Button variant="outline" size="sm" onClick={() => { void handleAdd(); }} className="w-full">
        Add Option
      </Button>
    </div>
  );
}

/**
 * Collision Resolution Modal
 * Allows users to resolve alias conflicts when importing Snips
 * 
 * Default behavior: Snip aliases are preserved, existing workflow aliases are renamed
 */
import { AlertTriangle, Info } from "lucide-react";
import { useState, useEffect } from "react";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
export interface CollisionItem {
    originalWorkflowAlias: string;
    originalSnipAlias: string;
    resolvedWorkflowAlias: string;
    resolvedSnipAlias: string;
}
interface CollisionResolutionModalProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    collisions: string[]; // Array of conflicting aliases
    onResolve: (resolutions: Record<string, string>) => void; // Map: old alias -> new alias
    onCancel: () => void;
}
export function CollisionResolutionModal({
    open,
    onOpenChange,
    collisions,
    onResolve,
    onCancel,
}: CollisionResolutionModalProps) {
    // State: array of collision items with resolution
    const [items, setItems] = useState<CollisionItem[]>([]);
    const [errors, setErrors] = useState<Record<number, string>>({});
    // Initialize items when collisions change
    useEffect(() => {
        if (collisions.length > 0) {
            const initialItems: CollisionItem[] = collisions.map(alias => {
                // Generate auto-renamed workflow alias (add _2 suffix)
                const parts = alias.split('.');
                let renamedWorkflowAlias: string;
                if (parts.length > 1) {
                    // Has namespace: respondent.name.first -> respondent_2.name.first
                    renamedWorkflowAlias = `${parts[0]}_2.${parts.slice(1).join('.')}`;
                } else {
                    // No namespace: name -> name_2
                    renamedWorkflowAlias = `${alias}_2`;
                }
                return {
                    originalWorkflowAlias: alias,
                    originalSnipAlias: alias,
                    resolvedWorkflowAlias: renamedWorkflowAlias,
                    resolvedSnipAlias: alias, // Snip wins by default
                };
            });
            setItems(initialItems);
        }
    }, [collisions]);
    // Validate all items
    const validate = (): boolean => {
        const newErrors: Record<number, string> = {};
        const allResolvedAliases = new Set<string>();
        items.forEach((item, idx) => {
            // Check for empty aliases
            if (!item.resolvedWorkflowAlias.trim()) {
                newErrors[idx] = "Workflow alias cannot be empty";
            }
            if (!item.resolvedSnipAlias.trim()) {
                newErrors[idx] = "Snip alias cannot be empty";
            }
            // Check for invalid characters (basic check)
            const validPattern = /^[a-zA-Z0-9_.]+$/;
            if (!validPattern.test(item.resolvedWorkflowAlias)) {
                newErrors[idx] = "Workflow alias contains invalid characters";
            }
            if (!validPattern.test(item.resolvedSnipAlias)) {
                newErrors[idx] = "Snip alias contains invalid characters";
            }
            // Check for duplicates
            if (allResolvedAliases.has(item.resolvedWorkflowAlias)) {
                newErrors[idx] = "Duplicate alias in resolution";
            }
            if (allResolvedAliases.has(item.resolvedSnipAlias)) {
                newErrors[idx] = "Duplicate alias in resolution";
            }
            allResolvedAliases.add(item.resolvedWorkflowAlias);
            allResolvedAliases.add(item.resolvedSnipAlias);
        });
        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };
    const handleWorkflowAliasChange = (idx: number, value: string) => {
        const newItems = [...items];
        newItems[idx].resolvedWorkflowAlias = value;
        setItems(newItems);
    };
    const handleSnipAliasChange = (idx: number, value: string) => {
        const newItems = [...items];
        newItems[idx].resolvedSnipAlias = value;
        setItems(newItems);
    };
    const handleContinue = () => {
        if (!validate()) {
            return;
        }
        // Build final mapping
        // Map old workflow aliases to new workflow aliases
        // Map old snip aliases to final snip aliases (usually unchanged)
        const resolutions: Record<string, string> = {};
        items.forEach(item => {
            // If workflow alias changed, add mapping
            if (item.originalWorkflowAlias !== item.resolvedWorkflowAlias) {
                resolutions[item.originalWorkflowAlias] = item.resolvedWorkflowAlias;
            }
            // If snip alias changed, add mapping
            if (item.originalSnipAlias !== item.resolvedSnipAlias) {
                resolutions[item.originalSnipAlias] = item.resolvedSnipAlias;
            }
        });
        onResolve(resolutions);
    };
    const handleCancel = () => {
        onCancel();
        onOpenChange(false);
    };
    const isValid = Object.keys(errors).length === 0;
    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-4xl max-h-[85vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2">
                        <AlertTriangle className="w-5 h-5 text-amber-600" />
                        Resolve Naming Conflicts
                    </DialogTitle>
                    <DialogDescription>
                        Two questions use the same name. We need to rename one to avoid confusion.
                        By default, we'll keep the Snip's names and update your existing workflow.
                    </DialogDescription>
                </DialogHeader>
                <div className="space-y-4 py-4">
                    {/* Info banner */}
                    <Alert className="bg-blue-50 border-blue-200">
                        <Info className="h-4 w-4 text-blue-600" />
                        <AlertDescription className="text-sm text-blue-900">
                            The Snip's variable names are preserved by default. Your existing workflow variables will be renamed with a "_2" suffix.
                        </AlertDescription>
                    </Alert>
                    {/* Collision table */}
                    <div className="border rounded-lg overflow-hidden">
                        <div className="bg-muted px-4 py-3 border-b">
                            <div className="grid grid-cols-3 gap-4 text-xs font-medium text-muted-foreground uppercase tracking-wider">
                                <div>Existing Workflow Variable</div>
                                <div>Incoming Snip Variable</div>
                                <div>After Import</div>
                            </div>
                        </div>
                        <div className="divide-y">
                            {items.map((item, idx) => {
                                const snipChanged = item.resolvedSnipAlias !== item.originalSnipAlias;
                                const workflowChanged = item.resolvedWorkflowAlias !== item.originalWorkflowAlias;
                                return (
                                    <div key={idx} className="p-4 bg-background hover:bg-muted/50 transition-colors">
                                        <div className="grid grid-cols-3 gap-4">
                                            {/* Existing workflow variable */}
                                            <div className="space-y-2">
                                                <div className="text-sm font-mono text-muted-foreground line-through">
                                                    {item.originalWorkflowAlias}
                                                </div>
                                                <Input
                                                    value={item.resolvedWorkflowAlias}
                                                    onChange={(e) => handleWorkflowAliasChange(idx, e.target.value)}
                                                    className="h-9 font-mono text-sm"
                                                    placeholder="Enter new name..."
                                                />
                                                {workflowChanged && (
                                                    <p className="text-xs text-amber-600 flex items-start gap-1">
                                                        <AlertTriangle className="w-3 h-3 mt-0.5 shrink-0" />
                                                        <span>Existing logic and documents will reference the new name</span>
                                                    </p>
                                                )}
                                            </div>
                                            {/* Incoming snip variable */}
                                            <div className="space-y-2">
                                                <div className="text-sm font-mono text-emerald-700 font-medium">
                                                    {item.originalSnipAlias}
                                                </div>
                                                <Input
                                                    value={item.resolvedSnipAlias}
                                                    onChange={(e) => handleSnipAliasChange(idx, e.target.value)}
                                                    className="h-9 font-mono text-sm"
                                                    placeholder="Enter new name..."
                                                />
                                                {snipChanged && (
                                                    <Alert className="bg-amber-50 border-amber-200 p-2">
                                                        <AlertDescription className="text-xs text-amber-800 flex items-start gap-1">
                                                            <AlertTriangle className="w-3 h-3 mt-0.5 shrink-0" />
                                                            <span>
                                                                This Snip may already be mapped to document templates.
                                                                Changing Snip aliases can break document outputs.
                                                            </span>
                                                        </AlertDescription>
                                                    </Alert>
                                                )}
                                            </div>
                                            {/* Resolution result */}
                                            <div className="space-y-2">
                                                <div className="text-sm space-y-1">
                                                    <div className="font-mono text-xs">
                                                        <span className="text-muted-foreground">Workflow: </span>
                                                        <span className="font-medium">{item.resolvedWorkflowAlias}</span>
                                                    </div>
                                                    <div className="font-mono text-xs">
                                                        <span className="text-muted-foreground">Snip: </span>
                                                        <span className="font-medium text-emerald-700">{item.resolvedSnipAlias}</span>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                        {errors[idx] && (
                                            <div className="mt-2 text-sm text-destructive flex items-center gap-1">
                                                <AlertTriangle className="w-4 h-4" />
                                                {errors[idx]}
                                            </div>
                                        )}
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                </div>
                <DialogFooter>
                    <Button variant="outline" onClick={handleCancel}>
                        Cancel Import
                    </Button>
                    <Button
                        onClick={handleContinue}
                        disabled={!isValid}
                        className="bg-emerald-600 hover:bg-emerald-700"
                    >
                        Continue with Import
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

/**
 * Inspector - Right panel with tabs for Properties, Blocks, Logic
 */

import { Settings, Blocks, GitBranch, Code } from "lucide-react";

import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useWorkflowBuilder } from "@/store/workflow-builder";

import { BlocksPanel } from "./BlocksPanel";
// const BlocksPanel = ({ workflowId }: { workflowId: string }) => <div className="p-4 text-sm text-muted-foreground">Blocks Panel is currently unavailable.</div>;
import { LogicPanel } from "./LogicPanel";
import { StepPropertiesPanel } from "./StepPropertiesPanel";
import { TransformBlocksPanel } from "./TransformBlocksPanel";

export function Inspector({ workflowId }: { workflowId: string }) {
  const { inspectorTab, setInspectorTab, selection } = useWorkflowBuilder();

  if (!selection) {
    return (
      <div className="h-full flex items-center justify-center p-8 text-center">
        <p className="text-sm text-muted-foreground">
          Select an element to view its properties
        </p>
      </div>
    );
  }

  // Determine which properties panel to show based on selection type
  const renderPropertiesPanel = () => {
    if (selection.type === "step") {
      // We need the sectionId to update the step, which we can get from the step data
      // For now, we'll pass it through. The StepPropertiesPanel will fetch the step and get sectionId
      return <StepPropertiesPanel stepId={selection.id} sectionId="" />;
    } else if (selection.type === "section") {
      return (
        <div className="p-4">
          <p className="text-sm text-muted-foreground">
            Section properties can be edited directly in the canvas.
          </p>
        </div>
      );
    } else if (selection.type === "block") {
      return (
        <div className="p-4">
          <p className="text-sm text-muted-foreground">
            Block properties can be edited by clicking on the block in the Blocks tab.
          </p>
        </div>
      );
    }

    return (
      <div className="p-4">
        <p className="text-sm text-muted-foreground">
          Select a question to edit its properties.
        </p>
      </div>
    );
  };

  return (
    <div className="h-full flex flex-col">
      <Tabs value={inspectorTab} onValueChange={(v: any) => setInspectorTab(v)} className="flex-1 flex flex-col">
        <TabsList className="w-full grid grid-cols-4 m-2">
          <TabsTrigger value="properties" className="text-xs">
            <Settings className="w-3 h-3 mr-1" />
            Properties
          </TabsTrigger>
          <TabsTrigger value="blocks" className="text-xs">
            <Blocks className="w-3 h-3 mr-1" />
            Blocks
          </TabsTrigger>
          <TabsTrigger value="transform" className="text-xs">
            <Code className="w-3 h-3 mr-1" />
            Transform
          </TabsTrigger>
          <TabsTrigger value="logic" className="text-xs">
            <GitBranch className="w-3 h-3 mr-1" />
            Logic
          </TabsTrigger>
        </TabsList>

        <TabsContent value="properties" className="flex-1 overflow-y-auto">
          {renderPropertiesPanel()}
        </TabsContent>

        <TabsContent value="blocks" className="flex-1 overflow-y-auto">
          <BlocksPanel workflowId={workflowId} />
        </TabsContent>

        <TabsContent value="transform" className="flex-1 overflow-y-auto">
          <TransformBlocksPanel workflowId={workflowId} />
        </TabsContent>

        <TabsContent value="logic" className="flex-1 overflow-y-auto">
          <LogicPanel workflowId={workflowId} selection={selection} />
        </TabsContent>
      </Tabs>
    </div>
  );
}

import { useQuery } from '@tanstack/react-query';
import React, { createContext, useContext, useMemo } from 'react';

import { variableAPI, workflowAPI, type ApiWorkflowVariable, type ApiWorkflow } from '@/lib/vault-api';
import { useWorkflow } from '@/lib/vault-hooks';

interface IntakeContextType {
    upstreamWorkflowId: string | null;
    upstreamWorkflow: ApiWorkflow | null;
    upstreamVariables: ApiWorkflowVariable[];
    isLoading: boolean;
    isIntake: boolean;
}

const IntakeContext = createContext<IntakeContextType | null>(null);

export function IntakeProvider({
    workflowId,
    children
}: {
    workflowId: string;
    children: React.ReactNode
}) {
    // 1. Get current workflow to check config
    const { data: workflow, isLoading: workflowLoading } = useWorkflow(workflowId);
    const intakeConfig = (workflow?.intakeConfig as Record<string, unknown> | undefined) ?? {};
    const isIntake = intakeConfig.isIntake === true;
    const upstreamWorkflowId = (intakeConfig.upstreamWorkflowId as string | undefined) ?? null;

    // 2. Fetch upstream workflow details (if linked)
    const { data: upstreamWorkflow, isLoading: upstreamWfLoading } = useQuery({
        queryKey: ['workflow', upstreamWorkflowId ?? ''],
        queryFn: () => workflowAPI.get(upstreamWorkflowId as string),
        enabled: Boolean(upstreamWorkflowId),
        staleTime: 1000 * 60 * 5, // 5 mins
    });

    // 3. Fetch upstream variables (if linked)
    const { data: upstreamVariables, isLoading: varsLoading } = useQuery({
        queryKey: ['workflow', upstreamWorkflowId ?? '', 'variables'],
        queryFn: () => variableAPI.list(upstreamWorkflowId as string),
        enabled: Boolean(upstreamWorkflowId),
    });

    const value = useMemo(() => ({
        upstreamWorkflowId,
        upstreamWorkflow: upstreamWorkflow ?? null,
        upstreamVariables: upstreamVariables ?? [],
        isLoading: workflowLoading || upstreamWfLoading || varsLoading,
        isIntake
    }), [upstreamWorkflowId, upstreamWorkflow, upstreamVariables, workflowLoading, upstreamWfLoading, varsLoading, isIntake]);

    return (
        <IntakeContext.Provider value={value}>
            {children}
        </IntakeContext.Provider>
    );
}

export function useIntake() {
    const context = useContext(IntakeContext);
    if (!context) {
        throw new Error('useIntake must be used within an IntakeProvider');
    }
    return context;
}

/**
 * List Inspector Panel
 * Shows metadata and preview for list variables in Advanced Mode
 */

import { Database, Layers, Filter, ArrowUpDown, Copy } from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { useToast } from "@/hooks/use-toast";

interface ListVariable {
  metadata: {
    source: 'read_table' | 'query' | 'list_tools';
    sourceId?: string;
    tableName?: string;
    queryName?: string;
    filteredBy?: string[];
    sortedBy?: { columnId: string; direction: 'asc' | 'desc' };
  };
  rows: Array<{
    id: string;
    [key: string]: any;
  }>;
  count: number;
  columns: Array<{
    id: string;
    name: string;
    type: string;
  }>;
}

interface ListInspectorProps {
  list: ListVariable;
  variableName: string;
}

export function ListInspector({ list, variableName }: ListInspectorProps) {
  const { toast } = useToast();

  const handleCopyReference = (ref: string) => {
    void navigator.clipboard.writeText(ref);
    toast({
      title: "Copied",
      description: `Reference copied: ${ref}`,
    });
  };

  const getSourceIcon = () => {
    switch (list.metadata.source) {
      case 'read_table': return <Database className="w-4 h-4" />;
      case 'query': return <Database className="w-4 h-4" />;
      case 'list_tools': return <Layers className="w-4 h-4" />;
      default: return <Layers className="w-4 h-4" />;
    }
  };

  const getSourceLabel = () => {
    switch (list.metadata.source) {
      case 'read_table': return 'Read Table';
      case 'query': return 'Query';
      case 'list_tools': return 'List Tools';
      default: return 'Unknown';
    }
  };

  return (
    <Card className="w-full">
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <CardTitle className="text-sm flex items-center gap-2">
            {getSourceIcon()}
            List Inspector: {variableName}
          </CardTitle>
          <Badge variant="outline" className="text-xs">
            {getSourceLabel()}
          </Badge>
        </div>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* Metadata */}
        <div className="grid grid-cols-2 gap-3 text-xs">
          <div className="space-y-1">
            <div className="text-muted-foreground">Row Count</div>
            <div className="font-mono font-semibold">{list.count}</div>
          </div>
          <div className="space-y-1">
            <div className="text-muted-foreground">Columns</div>
            <div className="font-mono font-semibold">{list.columns.length}</div>
          </div>
        </div>

        {/* Source Info */}
        {list.metadata.tableName && (
          <div className="space-y-1 text-xs">
            <div className="text-muted-foreground">Source Table</div>
            <div className="font-mono text-sm">{list.metadata.tableName}</div>
          </div>
        )}

        {list.metadata.queryName && (
          <div className="space-y-1 text-xs">
            <div className="text-muted-foreground">Query Name</div>
            <div className="font-mono text-sm">{list.metadata.queryName}</div>
          </div>
        )}

        {/* Filter/Sort Info */}
        {list.metadata.filteredBy && list.metadata.filteredBy.length > 0 && (
          <div className="flex items-center gap-2 text-xs p-2 bg-blue-50 rounded-md">
            <Filter className="w-3 h-3 text-blue-600" />
            <span className="text-blue-900">
              Filtered by {list.metadata.filteredBy.length} column{list.metadata.filteredBy.length > 1 ? 's' : ''}
            </span>
          </div>
        )}

        {list.metadata.sortedBy && (
          <div className="flex items-center gap-2 text-xs p-2 bg-purple-50 rounded-md">
            <ArrowUpDown className="w-3 h-3 text-purple-600" />
            <span className="text-purple-900">
              Sorted by: {list.columns.find(c => c.id === list.metadata.sortedBy?.columnId)?.name ?? 'Unknown'} ({list.metadata.sortedBy.direction})
            </span>
          </div>
        )}

        {/* Columns */}
        <div className="space-y-2">
          <div className="text-xs text-muted-foreground font-medium">Columns</div>
          <div className="grid grid-cols-1 gap-1 max-h-32 overflow-y-auto">
            {list.columns.map((col) => (
              <div
                key={col.id}
                className="flex items-center justify-between p-2 bg-muted/50 rounded text-xs hover:bg-muted group"
              >
                <div className="flex-1 min-w-0">
                  <div className="font-medium truncate">{col.name}</div>
                  <div className="text-muted-foreground text-[10px]">{col.type}</div>
                </div>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-6 w-6 opacity-0 group-hover:opacity-100"
                  onClick={() => { void handleCopyReference(`${variableName}.rows[i].${col.id}`); }}
                  title="Copy reference"
                >
                  <Copy className="w-3 h-3" />
                </Button>
