export function SidebarTree({ workflowId }: { workflowId: string }) {
  const { data: workflow } = useWorkflow(workflowId);
  const { data: sections } = useSections(workflowId);
  const { data: transformBlocks } = useTransformBlocks(workflowId);
  const mode: Mode = (workflow?.modeOverride as Mode) || 'easy';
  const { data: blocks } = useBlocks(workflowId);
  const createSectionMutation = useCreateSection();
  const createStepMutation = useCreateStep();
  const [expandedSections, setExpandedSections] = useState<Set<string>>(new Set());
  const [editingBlock, setEditingBlock] = useState<UniversalBlock | null>(null);
  const [editingSection, setEditingSection] = useState<ApiSection | null>(null);
  const [isBlockEditorOpen, setIsBlockEditorOpen] = useState(false);
  const [isSectionSettingsOpen, setIsSectionSettingsOpen] = useState(false);
  const [showAiDialog, setShowAiDialog] = useState(false);
  const [showSnipDialog, setShowSnipDialog] = useState(false);
  // Group blocks by section
  const blocksBySection = (blocks ?? []).reduce((acc: Record<string, ApiBlock[]>, block: ApiBlock) => {
    if (block.sectionId) {
      if (!acc[block.sectionId]) { acc[block.sectionId] = []; }
      acc[block.sectionId].push(block);
    }
    return acc;
  }, {});
  // We don't have sectionId for transform blocks easily available in current API mock/usage potentially?
  // If they don't have sectionId, we might not be able to map them easily. 
  // Assuming they might be mapped by logic or assume they are global if not mapped.
  // For now, let's just map regular blocks which have explicit sectionId.
  const handleCreateSection = async () => {
    const order = sections?.length || 0;
    await createSectionMutation.mutateAsync({
      workflowId,
      title: `${UI_LABELS.PAGE} ${order + 1}`,
      order,
    });
  };
  const handleCreateFinalDocumentsSection = async () => {
    const order = sections?.length || 0;
    const section = await createSectionMutation.mutateAsync({
      workflowId,
      title: "Final Documents",
      order,
      config: {
        finalBlock: true,
        templates: [],
        screenTitle: "Your Completed Documents",
        markdownMessage: "# Thank You!\n\nYour documents are ready for download below.",
        advanced: {}
      }
    });
    // Create the system step for this section
    await createStepMutation.mutateAsync({
      sectionId: section.id,
      type: "final_documents",
      title: "Final Documents",
      description: null,
      required: false,
      alias: "final_documents",
      options: null,
      order: 0,
      config: {},
    });
  };
  const toggleSection = (id: string) => {
    setExpandedSections((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  };
  return (
    <div className="h-full flex flex-col">
      <div className="p-4 border-b space-y-2">
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button size="sm" className="w-full">
              <Plus className="w-4 h-4 mr-2" />
              {UI_LABELS.ADD_PAGE}
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="start" className="w-56">
            <DropdownMenuItem onClick={() => { void handleCreateSection(); }}>
              <FileText className="w-4 h-4 mr-2" />
              Regular Page
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => { void handleCreateFinalDocumentsSection(); }}>
              <FileCheck className="w-4 h-4 mr-2" />
              Final Documents Section
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
        {/* AI Assistant Button */}
        <Button
          variant="outline"
          size="sm"
          className="w-full border-dashed border-indigo-300 text-indigo-700 hover:bg-indigo-50 hover:text-indigo-800"
          onClick={() => { void setShowAiDialog(true); }}
        >
          <Sparkles className="w-3 h-3 mr-2" />
          Edit with AI
        </Button>
        {/* Add Snip Button */}
        <Button
          variant="outline"
          size="sm"
          className="w-full border-dashed border-emerald-300 text-emerald-700 hover:bg-emerald-50 hover:text-emerald-800"
          onClick={() => { void setShowSnipDialog(true); }}
        >
          <Plus className="w-3 h-3 mr-2" />
          Add Snip
        </Button>
      </div>
      {mode === 'easy' && workflow?.projectId && (
        <DocumentStatusPanel workflowId={workflowId} projectId={workflow.projectId} />
      )}
      <ScrollArea className="flex-1">
        <div className="p-2">
          {sections && sections.length === 0 && (
            <div className="flex flex-col items-center justify-center py-8 text-center px-4 animate-in fade-in duration-500">
              <div className="p-3 bg-indigo-50 rounded-full mb-3 ring-4 ring-indigo-50/50">
                <FileText className="w-5 h-5 text-indigo-600" />
              </div>
              <h4 className="font-medium text-sm text-foreground mb-1">Start Building</h4>
              <p className="text-xs text-muted-foreground mb-3 leading-relaxed">
                Pages are the main steps of your workflow. Add one to begin.
              </p>
              <div className="relative">
                <div className="absolute -top-3 left-1/2 -translate-x-1/2 w-0.5 h-3 bg-indigo-200"></div>
                <Button onClick={() => { void handleCreateSection(); }} size="sm" className="bg-indigo-600 hover:bg-indigo-700 shadow-sm">
                  <Plus className="w-3.5 h-3.5 mr-1.5" />
                  Add First Page
                </Button>
              </div>
            </div>
          )}
          {sections?.map((section) => (
            <SectionItem
              key={section.id}
              section={section}
              workflowId={workflowId}
              isExpanded={expandedSections.has(section.id)}
              onToggle={() => toggleSection(section.id)}
              mode={mode}
              blocks={blocksBySection[section.id] ?? []}
              onEditBlock={(rawBlock) => {
                // Transform raw block to UniversalBlock format
                const universalBlock: UniversalBlock = {
                  id: rawBlock.id,
                  type: rawBlock.type,
                  phase: rawBlock.phase,
                  order: rawBlock.order,
                  enabled: rawBlock.enabled,
                  raw: rawBlock as unknown as Record<string, unknown>,
                  source: 'regular',
                  title: undefined,
                  displayType: rawBlock.type,
                };
                setEditingBlock(universalBlock);
                setIsBlockEditorOpen(true);
              }}
              onEditSection={() => {
                setEditingSection(section);
                setIsSectionSettingsOpen(true);
              }}
            />
          ))}
        </div>
      </ScrollArea>
      {/* Block Editor Dialog */}
      <BlockEditorDialog
        workflowId={workflowId}
        block={editingBlock}
        mode={mode}
        isOpen={isBlockEditorOpen}
        onClose={() => {
          setIsBlockEditorOpen(false);
          setEditingBlock(null);
        }}
      />
      {/* Section Settings Dialog */}
      <SectionSettingsDialog
        workflowId={workflowId}
        section={editingSection}
        isOpen={isSectionSettingsOpen}
        onClose={() => {
          setIsSectionSettingsOpen(false);
          setEditingSection(null);
        }}
        mode={mode}
      />
      <AiAssistantDialog
        workflowId={workflowId}
        open={showAiDialog}
        onOpenChange={setShowAiDialog}
      />
      <AddSnipDialog
        workflowId={workflowId}
        open={showSnipDialog}
        onOpenChange={setShowSnipDialog}
      />
    </div>
  );
}
function SectionItem({
  section,
  workflowId,
  isExpanded,
  onToggle,
  mode,
  blocks,
  onEditBlock,
  onEditSection,
}: {
  section: ApiSection;
  workflowId: string;
  isExpanded: boolean;
  onToggle: () => void;
  mode: Mode;
  blocks: ApiBlock[];
  onEditBlock: (block: ApiBlock) => void;
  onEditSection: () => void;
}) {
  const { data: steps } = useSteps(section.id);
  const createStepMutation = useCreateStep();
  const createBlockMutation = useCreateBlock();
  const { selection, selectSection } = useWorkflowBuilder();
  const isSelected = selection?.type === "section" && selection.id === section.id;
  // Check if this is a Final Documents section
  const isFinalSection = (section.config as Record<string, unknown> | undefined)?.finalBlock === true;
  // Don't show page-level required pill based on questions - only show if page is conditional
  const isPageConditional = !!section.visibleIf;

  const createStep = async () => {
    // Prevent adding questions to Final Documents sections
    if (isFinalSection) {
      return;
    }
    const order = steps?.length || 0;
    await createStepMutation.mutateAsync({
      sectionId: section.id,
      type: "short_text",
      title: `${UI_LABELS.QUESTION} ${order + 1}`,
      description: null,
      required: false,
      alias: null,
      options: null,
      order,
      config: {},
    });
    if (!isExpanded) { onToggle(); }
  };

  const handleCreateStep = async (e: React.MouseEvent) => {
    e.stopPropagation();
    await createStep();
  };
  const handleCreateLogicBlock = async (type: "write" | "read_table" | "list_tools" | "external_send") => {
    const order = blocks?.length || 0;
    // Default configs for quick-add
    const config = type === "write" ? {
      dataSourceId: "",
      tableId: "",
      mode: "upsert",
      columnMappings: []
    } : type === "read_table" ? {
      tableId: "",
      outputKey: "list_data",
      filters: []
    } : {};
    await createBlockMutation.mutateAsync({
      workflowId,
      type,
      phase: "onSectionSubmit", // Default to submit phase for flow
      sectionId: section.id,
      config,
      enabled: true,
      order
    });
    if (!isExpanded) { onToggle(); }
  };
  // Combine steps and blocks for display (if advanced mode or simple mode interoperability)
  // In Advanced: Show items interleaved based on something? 
  // Blocks have 'order'. Steps have 'order'. They might clash.
  // For now, let's just show blocks AT THE TOP of the section (like pre-fill) or BOTTOM?
  // Blocks have phases. 
  // onSectionEnter -> Top
  // onSectionSubmit -> Bottom
  const topBlocks = blocks.filter(b => b.phase === 'onSectionEnter' || b.phase === 'onRunStart');
  const bottomBlocks = blocks.filter(b => !topBlocks.includes(b)); // Submit, Next, etc.
  return (
    <div className="mb-1">
      <div
        className={cn(
          "flex items-center gap-2 p-2 rounded-md hover:bg-sidebar-accent/50 cursor-pointer group transition-colors focus:outline-none focus:ring-2 focus:ring-indigo-500/20",
          isSelected && "bg-sidebar-accent text-sidebar-accent-foreground font-medium"
        )}
        onClick={() => { void selectSection(section.id); }}
        tabIndex={0}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            selectSection(section.id);
          }
          if (e.key === 'ArrowRight') {
            if (!isExpanded) { onToggle(); }
          }
          if (e.key === 'ArrowLeft') {
            if (isExpanded) { onToggle(); }
          }
        }}
      >
        <Button
          variant="ghost"
          size="icon"
          className="h-4 w-4 p-0"
          onClick={(e) => {
            e.stopPropagation();
            onToggle();
          }}
        >
          {isExpanded ? <ChevronDown className="h-3 w-3" /> : <ChevronRight className="h-3 w-3" />}
        </Button>
        <GripVertical className="h-4 w-4 text-muted-foreground" />
        <span className="flex-1 text-sm truncate">{section.title}</span>
        {isFinalSection && (
          <Badge variant="secondary" className="text-xs px-1.5 py-0">
            <FileCheck className="h-3 w-3 mr-1" />
            Final
          </Badge>
        )}
        {isPageConditional && (
          <Badge variant="outline" className="text-[9px] h-4 px-1.5 bg-amber-500/10 text-amber-600 hover:bg-amber-500/20 border-amber-500/20 font-medium">
            Conditional
          </Badge>
        )}
        <div className="flex gap-1 items-center opacity-0 group-hover:opacity-100 transition-opacity">
          <Button
            variant="ghost"
            size="icon"
            className="h-6 w-6"
            onClick={(e) => {
              e.stopPropagation();
              onEditSection();
            }}
            title="Page Settings"
          >
            <Settings className="h-3 w-3 text-muted-foreground" />
          </Button>
        </div>
        {!isFinalSection && (
          <div className={cn(
            "flex gap-1",
            mode === 'easy' ? "opacity-100" : "opacity-0 group-hover:opacity-100 transition-opacity"
          )}>
            <Button
              variant="ghost"
              size="icon"
              className="h-6 w-6"
              onClick={() => { void createStep(); }}
              title="Add Question"
            >
              <Plus className="h-3 w-3" />
            </Button>
            {(mode === 'easy' || mode === 'advanced') && (
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button
                    variant="ghost"
                    size="icon"
                    className="h-6 w-6"
                    title="Add Logic"
                    onClick={(e) => { void e.stopPropagation(); }}
                  >
                    <Zap className="h-3 w-3" />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end">
                  <DropdownMenuItem onClick={(e) => {
                    e.stopPropagation();
                    handleCreateLogicBlock("write");
                  }}>
                    <Save className="w-3 h-3 mr-2" />
                    Send Data to Table
                  </DropdownMenuItem>
                  <DropdownMenuItem onClick={(e) => {
                    e.stopPropagation();
                    handleCreateLogicBlock("read_table");
                  }}>
                    <Database className="w-3 h-3 mr-2" />
                    Read from Table
                  </DropdownMenuItem>
                  <DropdownMenuItem onClick={(e) => {
                    e.stopPropagation();
                    handleCreateLogicBlock("external_send");
                  }}>
                    <Send className="w-3 h-3 mr-2" />
                    Send Data to API
                  </DropdownMenuItem>
                  <DropdownMenuItem onClick={(e) => {
                    e.stopPropagation();
                    handleCreateLogicBlock("list_tools");
                  }}>
                    <Sparkles className="w-3 h-3 mr-2" />
                    List Tools
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            )}
          </div>
        )}
      </div>
      {isExpanded && (
        <div className="ml-4 pl-2 mt-1 space-y-0.5 border-l border-sidebar-border/50">
          {/* Top Blocks (Prefill/Enter) */}
          {topBlocks.map((block) => (
            <BlockTreeItem key={block.id} block={block} mode={mode} onEdit={() => onEditBlock(block)} workflowId={workflowId} />
          ))}
          {/* Steps */}
          {steps && steps.length > 0 &&
            steps
              // Filter out system steps and questions in final sections
              .filter((step) => {
                // Hide final_documents system steps (they're just metadata)
                if (step.type === 'final_documents') { return false; }
                // Hide any other questions that might exist in final sections (orphaned data)
                if (isFinalSection) { return false; }
                return true;
              })
              .map((step) => (
                <StepItem key={step.id} step={step} sectionId={section.id} />
              ))}
          {/* Bottom Blocks (Submit/Next) */}
          {bottomBlocks.map((block) => (
            <BlockTreeItem key={block.id} block={block} mode={mode} onEdit={() => onEditBlock(block)} workflowId={workflowId} />
          ))}
        </div>
      )}
    </div>
  );
}
function StepItem({ step, sectionId }: { step: ApiStep; sectionId: string }) {
  const { selection, selectStep } = useWorkflowBuilder();
  const deleteStepMutation = useDeleteStep();
  const isSelected = selection?.type === "step" && selection.id === step.id;
  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm("Are you sure you want to delete this question?")) {
      deleteStepMutation.mutate({ id: step.id, sectionId });
    }
  };
  return (
    <div
      className={cn(
        "flex items-start gap-2 py-1.5 px-1.5 rounded-md hover:bg-sidebar-accent/50 cursor-pointer text-sm transition-colors focus:outline-none focus:ring-2 focus:ring-indigo-500/20 group",
        isSelected && "bg-sidebar-accent text-sidebar-accent-foreground font-medium"
      )}
      onClick={() => { void selectStep(step.id); }}
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          selectStep(step.id);
        }
      }}
    >
      <GripVertical className="h-3 w-3 text-muted-foreground shrink-0 mt-0.5" />
      {/* Required pill before question */}
      {step.required && (
        <Badge variant="destructive" className="text-[8px] h-3.5 px-1 font-medium shrink-0 mt-0.5">
          Req
        </Badge>
      )}
      <FileText className="h-3 w-3 text-muted-foreground shrink-0 mt-0.5" />
      {/* Question title and alias stacked */}
      <div className="flex-1 min-w-0">
        <div className="truncate text-xs leading-tight">{step.title || "(Untitled)"}</div>
        {step.alias && (
          <div className="text-[10px] text-muted-foreground/70 font-mono ml-2 truncate leading-tight mt-0.5">
            {step.alias}
          </div>
        )}
      </div>
      {step.visibleIf !== null && step.visibleIf !== undefined && (
        <Badge variant="outline" className="text-[8px] h-3.5 px-1 bg-amber-500/10 text-amber-600 hover:bg-amber-500/20 border-amber-500/20 font-medium shrink-0 mt-0.5">
          Cond
        </Badge>
      )}
      {/* Delete Action (Hover) */}
      <div className="opacity-0 group-hover:opacity-100 transition-opacity ml-1">
        <Button
          variant="ghost"
          size="icon"
          className="h-5 w-5 text-muted-foreground hover:text-destructive hover:bg-destructive/10"
          onClick={(e) => { void handleDelete(e); }}
          title="Delete Question"
        >
          <Trash2 className="h-3 w-3" />
        </Button>
      </div>
    </div>
  );
}
function BlockTreeItem({ block, mode, onEdit, workflowId }: { block: ApiBlock, mode: Mode, onEdit: () => void, workflowId: string }) {
  // Unlock editing for supported blocks in Easy Mode
  const isEditableInEasyMode = ['read_table', 'write', 'send_table', 'external_send', 'list_tools', 'query'].includes(block.type);
  const isLocked = mode === 'easy' && !isEditableInEasyMode;
  const deleteBlockMutation = useDeleteBlock();
  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    // eslint-disable-next-line no-alert
    if (confirm("Are you sure you want to delete this block?")) {
      deleteBlockMutation.mutate({ id: block.id, workflowId });
    }
  };
  const getIcon = (type: string) => {
    switch (type) {
      case 'prefill': return <Play className="w-3 h-3" />;
      case 'validate': return <CheckCircle className="w-3 h-3" />;
      case 'branch': return <GitBranch className="w-3 h-3" />;
      case 'query': case 'read_table': return <Database className="w-3 h-3" />;
      case 'write': case 'send_table': return <Save className="w-3 h-3" />;
      case 'external_send': return <Send className="w-3 h-3" />;
      case 'js': case 'transform': return <Code className="w-3 h-3" />;
      case 'list_tools': return <Sparkles className="w-3 h-3" />;
      default: return <Blocks className="w-3 h-3" />;
    }
  }
  const getLabel = (type: string) => {
    switch (type) {
      case 'read_table': return 'Read Table';
      case 'write': case 'send_table': return 'Send to Table';
      case 'external_send': return 'Send to API';
      case 'list_tools': return 'List Tool';
      case 'js': return 'Script';
      case 'query': return 'Read Data (Legacy)';
      default: return type;
    }
  }
  return (
    <div
      className={cn(
        "flex items-center gap-2 p-1.5 rounded-md text-sm transition-colors border border-transparent group",
        isLocked
          ? "bg-slate-50 text-slate-400 cursor-not-allowed italic"
          : "hover:bg-sidebar-accent/50 cursor-pointer text-slate-600"
      )}
      onClick={(e) => {
        if (!isLocked) {
          e.stopPropagation();
          onEdit();
        }
      }}
      title={isLocked ? "This block type is only editable in Advanced Mode" : block.type}
    >
      <div className={cn("w-3 mr-1", isLocked ? "opacity-50" : "")}>
        {isLocked ? <Lock className="w-3 h-3" /> : <GripVertical className="w-3 h-3 text-muted-foreground" />}
      </div>
      <div className={cn(isLocked ? "opacity-50" : "text-indigo-500")}>
        {getIcon(block.type)}
      </div>
      <span className="flex-1 truncate text-xs font-medium">
        {getLabel(block.type)}
        {block.phase === 'onSectionEnter' ? ' (Enter)' : ' (Submit)'}
      </span>
      {/* Delete Action (Hover) */}
      {!isLocked && (
        <div className="opacity-0 group-hover:opacity-100 transition-opacity ml-1">
          <Button
            variant="ghost"
            size="icon"
            className="h-5 w-5 text-muted-foreground hover:text-destructive hover:bg-destructive/10"
            onClick={(e) => { void handleDelete(e); }}
            title="Delete Block"
          >
            <Trash2 className="h-3 w-3" />
          </Button>
        </div>
      )}
    </div>
  )
}

import React from 'react';

import type { ApiStep } from '@/lib/vault-api';

import { AddressCardEditor } from './cards/AddressCardEditor';
import { BooleanCardEditor } from './cards/BooleanCardEditor';
import { ChoiceCardEditor } from './cards/ChoiceCardEditor';
import { DisplayCardEditor } from './cards/DisplayCardEditor';
import { EmailCardEditor } from './cards/EmailCardEditor';
import { MultiFieldCardEditor } from './cards/MultiFieldCardEditor';
import { NumberCardEditor } from './cards/NumberCardEditor';
import { PhoneCardEditor } from './cards/PhoneCardEditor';
import { ScaleCardEditor } from './cards/ScaleCardEditor';
import { TextCardEditor } from './cards/TextCardEditor';
import { WebsiteCardEditor } from './cards/WebsiteCardEditor';
import { LegacyStepBody } from './questions/LegacyStepBody';

export interface StepEditorCommonProps {
    stepId: string;
    sectionId: string;
    workflowId: string;
    step: ApiStep;
}

export function StepEditorRouter({ step, sectionId, workflowId }: { step: ApiStep; sectionId: string; workflowId: string }) {
    const commonProps: StepEditorCommonProps = {
        stepId: step.id,
        sectionId,
        workflowId,
        step,
    };

    // Display Steps
    if (step.type === 'display') {
        return <DisplayCardEditor {...commonProps} />;
    }

    // Text Steps
    if (step.type === 'short_text' || step.type === 'long_text' || step.type === 'text') {
        return <TextCardEditor {...commonProps} />;
    }

    // Boolean Steps
    if (step.type === 'yes_no' || step.type === 'true_false' || step.type === 'boolean') {
        return <BooleanCardEditor {...commonProps} />;
    }

    // Choice Steps
    if (step.type === 'radio' || step.type === 'multiple_choice' || step.type === 'choice') {
        return <ChoiceCardEditor {...commonProps} />;
    }

    // Number Steps
    if (step.type === 'number' || step.type === 'currency') {
        return <NumberCardEditor {...commonProps} />;
    }

    // Address Steps
    if (step.type === 'address') {
        return <AddressCardEditor {...commonProps} />;
    }

    // Email Steps
    if (step.type === 'email') {
        return <EmailCardEditor {...commonProps} />;
    }

    // Phone Steps
    if (step.type === 'phone') {
        return <PhoneCardEditor {...commonProps} />;
    }

    // Website/URL Steps
    if (step.type === 'website') {
        return <WebsiteCardEditor {...commonProps} />;
    }

    // Scale/Rating Steps
    if (step.type === 'scale') {
        return <ScaleCardEditor {...commonProps} />;
    }

    // Multi-Field Steps
    if (step.type === 'multi_field') {
        return <MultiFieldCardEditor {...commonProps} />;
    }

    // Phase 1: Route everything to LegacyStepBody
    // Phase 2: Incrementally add specialized editors here
    // Remaining Legacy Types: date_time, date, time, file_upload, js_question, signature, signature_block
    return <LegacyStepBody {...commonProps} />;
}

/**
 * Step Properties Panel
 * Displays and allows editing of step properties when a step is selected
 */

import { HelpCircle, ExternalLink } from "lucide-react";
import { useState, useEffect } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Separator } from "@/components/ui/separator";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { useToast } from "@/hooks/use-toast";
import { useStep, useUpdateStep } from "@/lib/vault-hooks";
import { OptionsEditor } from "./step-properties/OptionsEditor";

interface StepPropertiesPanelProps {
  stepId: string;
  sectionId?: string;
}

type DateTimeType = "date" | "time" | "datetime";
type TextType = "short" | "long";

export function StepPropertiesPanel({ stepId, sectionId: propSectionId }: StepPropertiesPanelProps) {
  const { data: step } = useStep(stepId);
  const updateStepMutation = useUpdateStep();


  // Get sectionId from prop or from the step data
  const sectionId = (propSectionId ?? step?.sectionId) ?? "";

  // Local state only for options (needed for intermediate editing state)
  const [localOptions, setLocalOptions] = useState<string[]>([]);
  const [dateTimeType, setDateTimeType] = useState<DateTimeType>("datetime");
  const [textType, setTextType] = useState<TextType>("short");

  // Initialize local state from step data
  useEffect(() => {
    if (step) {
      // Initialize options for radio/multiple_choice
      const stepOptions = step.options as { options?: string[] } | undefined;
      if ((step.type === "radio" || step.type === "multiple_choice") && stepOptions?.options) {
        setLocalOptions(stepOptions.options);
      }

      // Initialize date/time type
      const dtOptions = step.options as { dateTimeType?: DateTimeType } | undefined;
      if (step.type === "date_time" && dtOptions?.dateTimeType) {
        setDateTimeType(dtOptions.dateTimeType);
      }

      // Initialize text type from step type
      if (step.type === "short_text") {
        setTextType("short");
      } else if (step.type === "long_text") {
        setTextType("long");
      }
    }
  }, [step]);



  if (!step) {
    return (
      <div className="p-4">
        <p className="text-sm text-muted-foreground">Loading...</p>
      </div>
    );
  }

  const handleTitleChange = (title: string) => {
    updateStepMutation.mutate({ id: stepId, sectionId, title });
  };

  const handleDescriptionChange = (description: string) => {
    updateStepMutation.mutate({ id: stepId, sectionId, description });
  };

  const handleRequiredChange = (required: boolean) => {
    updateStepMutation.mutate({ id: stepId, sectionId, required });
  };

  const handleDefaultValueChange = (value: string) => {
    // Parse the value based on step type
    let parsedValue: string | number | boolean | string[] | null = value;

    // For empty string, set to null to clear the default
    if (value === "") {
      parsedValue = null;
    } else if (step.type === "yes_no") {
      // Convert to boolean
      parsedValue = value.toLowerCase() === "yes" || value === "true";
    } else if (step.type === "multiple_choice") {
      // For multiple choice, try to parse as JSON array
      try {
        parsedValue = JSON.parse(value) as string[];
      } catch {
        // If not valid JSON, keep as string
        parsedValue = value;
      }
    }

    updateStepMutation.mutate({
      id: stepId,
      sectionId,
      defaultValue: parsedValue
    });
  };

  const handleOptionsDraftChange = (options: string[]) => {
    setLocalOptions(options);
  };

  const handleOptionsCommitChange = (options: string[]) => {
    setLocalOptions(options);
    updateStepMutation.mutate({
      id: stepId,
      sectionId,
      options: { options },
    });
  };



  const handleDateTimeTypeChange = (type: DateTimeType) => {
    setDateTimeType(type);
    updateStepMutation.mutate({
      id: stepId,
      sectionId,
      options: { dateTimeType: type },
    });
  };

  const handleTextTypeChange = (type: TextType) => {
    setTextType(type);
    // Update the step type itself
    const newType = type === "short" ? "short_text" : "long_text";
    updateStepMutation.mutate({
      id: stepId,
      sectionId,
      type: newType,
    });
  };



  return (
    <div className="p-4 space-y-6">
      <div>
        <div className="space-y-1">
          <Input
            value={step.title}
            onChange={(e) => handleTitleChange(e.target.value)}
            className="font-semibold text-lg px-2 -ml-2 border-transparent hover:border-input focus:border-input transition-colors h-auto py-1"
            placeholder="Step Title"
            autoFocus
          />
          <p className="text-xs text-muted-foreground px-0.5">
            {step.type.replace(/_/g, " ").replace(/\b\w/g, (l) => l.toUpperCase())}
          </p>
        </div>
      </div>

      <Separator />

      {/* Description */}
      <div className="space-y-2">
        <Label htmlFor="description">Description</Label>
        <Textarea
          id="description"
          value={step.description ?? ""}
          onChange={(e) => handleDescriptionChange(e.target.value)}
          placeholder="Add a description for this question..."
          rows={3}
        />
      </div>

      {/* Required toggle */}
      <div className="flex items-center justify-between">
        <Label htmlFor="required">Required</Label>
        <Switch
          id="required"
          checked={step.required ?? false}
          onCheckedChange={handleRequiredChange}
        />
      </div>

      <Separator />

      {/* Default Value */}
      <div className="space-y-2">
        <div className="flex items-center gap-2">
          <Label htmlFor="defaultValue">Default Value</Label>
          <TooltipProvider>
            <Tooltip>
              <TooltipTrigger asChild>
                <a
                  href="/docs/url-parameters"
                  target="_blank"
                  rel="noopener noreferrer"
                  className="inline-flex items-center text-muted-foreground hover:text-foreground transition-colors"
                  onClick={(e) => e.stopPropagation()}
                >
                  <HelpCircle className="h-4 w-4" />
                </a>
              </TooltipTrigger>
              <TooltipContent side="right" className="max-w-xs">
                <p className="text-sm">
                  Set a default value that appears when the workflow runs.
                  Can be overridden using URL parameters.
                </p>
                <div className="flex items-center gap-1 mt-2 text-xs text-primary">
                  <ExternalLink className="h-3 w-3" />
                  <span>Click for full documentation</span>
                </div>
              </TooltipContent>
            </Tooltip>
          </TooltipProvider>
        </div>

        {step.type === "yes_no" || step.type === "true_false" ? (
          <Select
            value={
              step.defaultValue === null || step.defaultValue === undefined
                ? "no_default"
                : String(step.defaultValue)
            }
            onValueChange={(val) => {
              let finalVal: boolean | null = null;
              if (val === "true") { finalVal = true; }
              else if (val === "false") { finalVal = false; }

              updateStepMutation.mutate({
                id: stepId,
                sectionId,
                defaultValue: finalVal
              });
            }}
          >
            <SelectTrigger>
              <SelectValue placeholder="Select default..." />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="no_default">No Default</SelectItem>
              {step.type === "yes_no" ? (
                <>
                  <SelectItem value="true">Yes</SelectItem>
                  <SelectItem value="false">No</SelectItem>
                </>
              ) : (
                <>
                  <SelectItem value="true">True</SelectItem>
                  <SelectItem value="false">False</SelectItem>
                </>
              )}
            </SelectContent>
          </Select>
        ) : (
          <>
            <Input
              id="defaultValue"
              value={
                step.defaultValue === null || step.defaultValue === undefined
                  ? ""
                  : typeof step.defaultValue === "object"
                    ? JSON.stringify(step.defaultValue)
                    : String(step.defaultValue)
              }
              onChange={(e) => handleDefaultValueChange(e.target.value)}
              placeholder={
                step.type === "multiple_choice"
                  ? '["Option 1", "Option 2"]'
                  : step.type === "radio"
                    ? "Option text"
                    : step.type === "date_time"
                      ? "YYYY-MM-DD or YYYY-MM-DDTHH:mm"
                      : "Enter default value..."
              }
            />
            <p className="text-xs text-muted-foreground">
              This value will be pre-filled when the workflow runs. Can be overridden by URL parameters.
            </p>
          </>
        )}
      </div>

      {/* Text Type Toggle (for short_text and long_text) */}
      {(step.type === "short_text" || step.type === "long_text") && (
        <>
          <Separator />
          <div className="space-y-3">
            <Label>Input Type</Label>
            <RadioGroup value={textType} onValueChange={(v) => handleTextTypeChange(v as TextType)}>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="short" id="text-short" />
                <Label htmlFor="text-short" className="font-normal cursor-pointer">
                  Short Text (Single line)
                </Label>
              </div>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="long" id="text-long" />
                <Label htmlFor="text-long" className="font-normal cursor-pointer">
                  Long Text (Multi-line)
                </Label>
              </div>
            </RadioGroup>
          </div>
        </>
      )}

      {/* Date/Time Type Selector */}
      {step.type === "date_time" && (
        <>
          <Separator />
          <div className="space-y-3">
            <Label>Date/Time Type</Label>
            <RadioGroup value={dateTimeType} onValueChange={(v) => handleDateTimeTypeChange(v as DateTimeType)}>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="date" id="dt-date" />
                <Label htmlFor="dt-date" className="font-normal cursor-pointer">
                  Date Only
                </Label>
              </div>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="time" id="dt-time" />
                <Label htmlFor="dt-time" className="font-normal cursor-pointer">
                  Time Only
                </Label>
              </div>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="datetime" id="dt-datetime" />
                <Label htmlFor="dt-datetime" className="font-normal cursor-pointer">
                  Date and Time
                </Label>
              </div>
            </RadioGroup>
          </div>
        </>
      )}

      {/* Options Editor (for radio and multiple_choice) */}
      {(step.type === "radio" || step.type === "multiple_choice") && (
        <>
          <Separator />
          <OptionsEditor
            options={localOptions}
            onDraftChange={handleOptionsDraftChange}
            onCommitChange={handleOptionsCommitChange}
          />
        </>
      )}
    </div>
  );
}

/**
 * Transform Blocks Panel - CRUD for JavaScript/Python transform blocks
