function TransformBlockTester({ block }: { block: ApiTransformBlock }) {
  const testMutation = useTestTransformBlock();
  const { toast } = useToast();
  const [testData, setTestData] = useState("{}");
  const [testResult, setTestResult] = useState<unknown>(null);

  const handleTest = async () => {
    if (!block?.id) {
      toast({ title: "Info", description: "Save the block first before testing", variant: "default" });
      return;
    }

    try {
      const parsedData = JSON.parse(testData);
      const result = await testMutation.mutateAsync({ id: block.id, testData: parsedData });
      setTestResult(result);

      if (result.success) {
        toast({ title: "Test Successful", description: "Check output below" });
      } else {
        toast({ title: "Test Failed", description: result.error ?? "Unknown error", variant: "destructive" });
      }
    } catch (error) {
      if (error instanceof SyntaxError) {
        toast({ title: "Invalid JSON", description: "Test data must be valid JSON", variant: "destructive" });
      } else {
        toast({ title: "Test Error", description: "Failed to test block", variant: "destructive" });
      }
    }
  };

  return (
    <div className="space-y-2 pt-4 border-t">
      <Label>Test Block</Label>
      <div className="flex gap-2">
        <Textarea
          value={testData}
          onChange={(e) => { void setTestData(e.target.value); }}
          rows={4}
          className="font-mono text-xs flex-1"
          placeholder='{"inputKey1": "value1", "inputKey2": "value2"}'
        />
        <Button
          type="button"
          variant="outline"
          onClick={() => { void handleTest(); }}
          disabled={testMutation.isPending}
        >
          <Play className="w-3 h-3 mr-1" />
          Test
        </Button>
      </div>
      {testResult !== null && (
        <div className="mt-2">
          <Label className="text-xs">Result:</Label>
          <pre className="mt-1 p-2 bg-muted rounded text-xs font-mono overflow-x-auto">
            {JSON.stringify(testResult, null, 2)}
          </pre>
        </div>
      )}
    </div>
  );
}

/**
 * TransformSummary - Read-only display of transform configuration
 * Shows what filters, sorts, limits, etc. are applied to a list
 */

import { Filter, ArrowUpDown, Scissors, Columns, Hash } from "lucide-react";
import React from "react";

import { Badge } from "@/components/ui/badge";

import type { ListToolsConfig } from "@shared/types/blocks";

interface TransformSummaryProps {
  config: Partial<ListToolsConfig> | undefined;
  className?: string;
}

export function TransformSummary({ config, className }: TransformSummaryProps) {
  if (!config) {return null;}

  const hasFilters = (config.filters?.rules?.length || 0) > 0;
  const hasSorts = (config.sort?.length || 0) > 0;
  const hasRange = config.offset !== undefined || config.limit !== undefined;
  const hasSelect = (config.select?.length || 0) > 0;
  const hasDedupe = !!config.dedupe;

  const hasAnyTransforms = hasFilters || hasSorts || hasRange || hasSelect || hasDedupe;

  if (!hasAnyTransforms) {
    return (
      <div className={className}>
        <p className="text-[10px] text-muted-foreground italic">No transforms applied</p>
      </div>
    );
  }

  return (
    <div className={`space-y-1.5 ${className ?? ''}`}>
      <p className="text-[10px] font-medium text-muted-foreground">Applied Transforms:</p>
      <div className="flex flex-wrap gap-1">
        {/* Filters */}
        {hasFilters && (
          <Badge variant="outline" className="text-[10px] bg-blue-50/50 border-blue-200 text-blue-700 gap-1">
            <Filter className="h-3 w-3" />
            {config.filters!.rules!.length} filter{config.filters!.rules!.length > 1 ? 's' : ''}
          </Badge>
        )}

        {/* Sort */}
        {hasSorts && (
          <Badge variant="outline" className="text-[10px] bg-purple-50/50 border-purple-200 text-purple-700 gap-1">
            <ArrowUpDown className="h-3 w-3" />
            Sort by {config.sort!.length} key{config.sort!.length > 1 ? 's' : ''}
          </Badge>
        )}

        {/* Range (Offset/Limit) */}
        {hasRange && (
          <Badge variant="outline" className="text-[10px] bg-orange-50/50 border-orange-200 text-orange-700 gap-1">
            <Scissors className="h-3 w-3" />
            {config.offset ? `Skip ${config.offset}` : ''}
            {config.offset && config.limit ? ', ' : ''}
            {config.limit ? `Take ${config.limit}` : ''}
          </Badge>
        )}

        {/* Select */}
        {hasSelect && (
          <Badge variant="outline" className="text-[10px] bg-indigo-50/50 border-indigo-200 text-indigo-700 gap-1">
            <Columns className="h-3 w-3" />
            {config.select!.length} column{config.select!.length > 1 ? 's' : ''}
          </Badge>
        )}

        {/* Dedupe */}
        {hasDedupe && (
          <Badge variant="outline" className="text-[10px] bg-pink-50/50 border-pink-200 text-pink-700 gap-1">
            <Hash className="h-3 w-3" />
            Dedupe by {config.dedupe!.fieldPath}
          </Badge>
        )}
      </div>
    </div>
  );
}

import {  Trash2, Code, AlertCircle, List , Database } from "lucide-react";
import { useState } from "react";

import { EnhancedVariablePicker } from "@/components/common/EnhancedVariablePicker";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";

// Types derived from existing codebase or re-declared for standalone usage if needed
// Assuming @shared/types/blocks is available
import type {
    ValidateRule,
    CompareRule,
    ConditionalRequiredRule,
    ForEachRule,
    LegacyValidateRule
} from "@shared/types/blocks";
interface ValidationRulesEditorProps {
    rules: ValidateRule[];
    onChange: (rules: ValidateRule[]) => void;
    workflowId: string;
    mode?: "easy" | "advanced";
}
export function ValidationRulesEditor({ rules, onChange, workflowId, mode = "easy" }: ValidationRulesEditorProps) {
    const [activeTab, setActiveTab] = useState<"visual" | "json">("visual");
    const addRule = (type: string) => {
        let newRule: ValidateRule;
        if (type === 'compare') {
            newRule = {
                type: 'compare',
                left: '',
                op: 'equals',
                right: '',
                rightType: 'constant',
                message: 'Value mismatch'
            } as CompareRule;
        } else if (type === 'conditional_required') {
            newRule = {
                type: 'conditional_required',
                when: { key: '', op: 'equals', value: '' },
                requiredFields: [],
                message: 'This field is required'
            } as ConditionalRequiredRule;
        } else if (type === 'foreach') {
            newRule = {
                type: 'foreach',
                listKey: '',
                itemAlias: 'item',
                rules: [],
                message: 'List item validation failed'
            } as ForEachRule;
        } else {
            newRule = { assert: { key: '', op: 'is_not_empty' }, message: 'Invalid' } as LegacyValidateRule;
        }
        onChange([...rules, newRule]);
    };
    const updateRule = (index: number, updated: ValidateRule) => {
        const newRules = [...rules];
        newRules[index] = updated;
        onChange(newRules);
    };
    const deleteRule = (index: number) => {
        const newRules = [...rules];
        newRules.splice(index, 1);
        onChange(newRules);
    };
    return (
        <div className="space-y-4">
            <div className="flex items-center justify-between">
                <Label>Validation Rules</Label>
                {mode === 'advanced' && (
                    <div className="flex bg-muted rounded-md p-1">
                        <button
                            onClick={() => setActiveTab("visual")}
                            className={`px-3 py-1 text-xs rounded-sm transition-all ${activeTab === "visual" ? "bg-background shadow-sm" : "text-muted-foreground"}`}
                        >
                            Visual
                        </button>
                        <button
                            onClick={() => setActiveTab("json")}
                            className={`px-3 py-1 text-xs rounded-sm transition-all ${activeTab === "json" ? "bg-background shadow-sm" : "text-muted-foreground"}`}
                        >
                            JSON
                        </button>
                    </div>
                )}
            </div>
            {activeTab === "json" ? (
                <Textarea
                    value={JSON.stringify(rules, null, 2)}
                    onChange={(e) => {
                        try {
                            onChange(JSON.parse(e.target.value));
                        } catch (error) {
                            // Ignore parse errors during typing - user may be mid-edit
                            // The textarea will keep showing the invalid JSON until fixed
                        }
                    }}
                    className="font-mono text-xs h-[400px]"
                />
            ) : (
                <div className="space-y-4">
                    {rules.length === 0 && (
                        <div className="text-center py-8 border-2 border-dashed rounded-lg text-muted-foreground text-sm">
                            No validation rules defined.
                        </div>
                    )}
                    {rules.map((rule, index) => (
                        <RuleCard
                            key={index}
                            rule={rule}
                            index={index}
                            onUpdate={(r) => updateRule(index, r)}
                            onDelete={() => deleteRule(index)}
                            workflowId={workflowId}
                        />
                    ))}
                    <div className="flex gap-2">
                        <Button size="sm" variant="outline" onClick={() => addRule('compare')} className="gap-1">
                            <Code className="w-3 h-3" /> Compare Values
                        </Button>
                        <Button size="sm" variant="outline" onClick={() => addRule('conditional_required')} className="gap-1">
                            <AlertCircle className="w-3 h-3" /> Conditional Required
                        </Button>
                        <Button size="sm" variant="outline" onClick={() => addRule('foreach')} className="gap-1">
                            <List className="w-3 h-3" /> For Each Loop
                        </Button>
                    </div>
                </div>
            )}
        </div>
    );
}
