            scrollRef.current.scrollIntoView({ behavior: 'smooth' });
        }
    }, [messages]);
    const handleApply = async (suggestions: any) => {
        const success = await applyAiSuggestions(workflowId, suggestions, {
            createSection,
            createStep
        });
        if (success) {
            onOpenChange(false);
            // Optionally mark message as applied in UI if we kept dialog open
        }
    };
    const suggestMutation = useMutation({
        mutationFn: async (description: string) => {
            const res = await apiRequest("POST", `/api/ai/workflows/${workflowId}/suggest`, {
                description,
            });
            return res.json();
        },
        onSuccess: (data) => {
            // Add assistant message with suggestions
            const newMessage: Message = {
                id: Date.now().toString(),
                role: 'assistant',
                content: "I've generated some suggestions based on your request. Please review the changes below.",
                suggestions: data
            };
            setMessages(prev => [...prev, newMessage]);
        },
        onError: (error: any) => {
            toast({
                title: "AI Error",
                description: error?.message || "Failed to generate suggestions.",
                variant: "destructive",
            });
        },
    });
    const handleGenerate = () => {
        if (!prompt.trim()) {return;}
        // Add user message via optimistic update
        const userMsg: Message = {
            id: Date.now().toString(),
            role: 'user',
            content: prompt
        };
        setMessages(prev => [...prev, userMsg]);
        suggestMutation.mutate(prompt);
        setPrompt("");
    };
    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-xl flex flex-col h-[600px] p-0 gap-0">
                <DialogHeader className="p-6 border-b shrink-0">
                    <DialogTitle className="flex items-center gap-2">
                        <Sparkles className="h-5 w-5 text-indigo-600" />
                        Edit Workflow with AI
                    </DialogTitle>
                    <DialogDescription>
                        Refine your workflow using natural language. Review changes before applying.
                    </DialogDescription>
                </DialogHeader>
                <ScrollArea className="flex-1 p-6">
                    <div className="space-y-6">
                        {messages.length === 0 && (
                            <div className="text-center text-muted-foreground py-8">
                                <Sparkles className="w-12 h-12 mx-auto mb-3 text-indigo-100" />
                                <p>Describe what you want to change.</p>
                                <p className="text-xs mt-1 opacity-70">"Add a phone number question"</p>
                                <p className="text-xs opacity-70">"Create a new page for payment info"</p>
                            </div>
                        )}
                        {messages.map((msg) => (
                            <div key={msg.id} className={cn(
                                "flex gap-3",
                                msg.role === 'user' ? "flex-row-reverse" : "flex-row"
                            )}>
                                <div className={cn(
                                    "w-8 h-8 rounded-full flex items-center justify-center shrink-0",
                                    msg.role === 'user' ? "bg-slate-200" : "bg-indigo-100 text-indigo-600"
                                )}>
                                    {msg.role === 'user' ? <div className="text-xs font-semibold">You</div> : <Sparkles className="w-4 h-4" />}
                                </div>
                                <div className={cn(
                                    "rounded-lg p-3 text-sm max-w-[80%]",
                                    msg.role === 'user' ? "bg-slate-100 text-slate-900" : "bg-white border text-slate-900"
                                )}>
                                    <p>{msg.content}</p>
                                    {/* Placeholder for Diff View */}
                                    {msg.suggestions && (
                                        <div className="mt-3 border rounded-md p-2 bg-slate-50">
                                            <div className="flex items-center gap-2 text-xs font-medium text-slate-500 mb-2">
                                                <RotateCcw className="w-3 h-3" />
                                                Proposed Changes
                                            </div>
                                            {/* We will replace this with AiDiffView later */}
                                            <pre className="text-[10px] overflow-x-auto p-2 bg-white rounded border">
                                                {JSON.stringify(msg.suggestions, null, 2).slice(0, 200)}...
                                            </pre>
                                            <div className="flex gap-2 mt-3">
                                                <Button
                                                    size="sm"
                                                    variant="outline"
                                                    className="h-7 text-xs w-full"
                                                    onClick={() => {
                                                        // Reject just hides/removes the message or marks it rejected
                                                        // For now, simpler to just toast and ignore
                                                        toast({ title: "Suggestion Rejected", description: "No changes were made." });
                                                    }}
                                                >
                                                    <X className="w-3 h-3 mr-1" /> Reject
                                                </Button>
                                                <Button
                                                    size="sm"
                                                    className="h-7 text-xs w-full bg-indigo-600 hover:bg-indigo-700"
                                                    onClick={() => { void handleApply(msg.suggestions); }}
                                                >
                                                    <Check className="w-3 h-3 mr-1" /> Apply Changes
                                                </Button>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>
                        ))}
                        {suggestMutation.isPending && (
                            <div className="flex items-center gap-2 text-muted-foreground text-sm ml-11">
                                <Loader2 className="w-3 h-3 animate-spin" /> Thinking...
                            </div>
                        )}
                        <div ref={scrollRef} />
                    </div>
                </ScrollArea>
                <div className="p-4 border-t bg-slate-50 shrink-0">
                    <div className="flex gap-2">
                        <Textarea
                            placeholder="Message AI..."
                            value={prompt}
                            onChange={(e) => { void setPrompt(e.target.value); }}
                            onKeyDown={(e) => {
                                if (e.key === 'Enter' && !e.shiftKey) {
                                    e.preventDefault();
                                    handleGenerate();
                                }
                            }}
                            className="min-h-[44px] max-h-[120px] resize-none py-3"
                        />
                        <Button
                            onClick={() => { void handleGenerate(); }}
                            disabled={suggestMutation.isPending || !prompt.trim()}
                            size="icon"
                            className="h-[44px] w-[44px] shrink-0"
                        >
                            <Send className="w-4 h-4" />
                        </Button>
                    </div>
                </div>
            </DialogContent>
        </Dialog>
    );
}

import { Send, Sparkles, AlertTriangle, HelpCircle, History, Undo } from "lucide-react";
import React, { useState } from "react";

import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";

interface Message {
  id: string;
  role: "user" | "assistant";
  content: string;
  timestamp: Date;
  summary?: string[];
  warnings?: string[];
  questions?: AiQuestion[];
  confidence?: number;
  versionId?: string | null;
}

interface AiQuestion {
  id: string;
  prompt: string;
  type: "text" | "single_select" | "multi_select" | "number";
  options?: string[];
  blocking: boolean;
}

interface AiConversationPanelProps {
  workflowId: string;
  onEdit?: (versionId: string) => void;
  onUndo?: (versionId: string) => void;
  onViewDiff?: (versionId: string) => void;
}

export function AiConversationPanel({
  workflowId,
  onEdit,
  onUndo,
  onViewDiff,
}: AiConversationPanelProps) {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!input.trim() || isLoading) {return;}

    const userMessage: Message = {
      id: Date.now().toString(),
      role: "user",
      content: input,
      timestamp: new Date(),
    };

    setMessages(prev => [...prev, userMessage]);
    setInput("");
    setIsLoading(true);
    setError(null);

    try {
      const response = await fetch(`/api/workflows/${workflowId}/ai/edit`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        credentials: "include",
        body: JSON.stringify({
          userMessage: input,
          workflowId,
          preferences: {
            readingLevel: "standard",
            tone: "neutral",
          },
        }),
      });

      if (!response.ok) {
        throw new Error(`Failed to process AI request: ${response.statusText}`);
      }

      const result = await response.json();
      const data = result.data;

      const assistantMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: "assistant",
        content: data.summary?.join("\n") || "No changes made",
        timestamp: new Date(),
        summary: data.summary,
        warnings: data.warnings,
        questions: data.questions,
        confidence: data.confidence,
        versionId: data.versionId,
      };

      setMessages(prev => [...prev, assistantMessage]);

      // Notify parent if edit was successful
      if (data.versionId && onEdit) {
        onEdit(data.versionId);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");

      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: "assistant",
        content: `Error: ${err instanceof Error ? err.message : "Unknown error"}`,
        timestamp: new Date(),
      };

      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleUndo = (versionId: string) => {
    if (onUndo) {
      onUndo(versionId);
    }
  };

  const handleViewDiff = (versionId: string) => {
    if (onViewDiff) {
      onViewDiff(versionId);
    }
  };

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="p-4 border-b bg-gradient-to-r from-purple-50 to-blue-50">
        <div className="flex items-center gap-2">
          <Sparkles className="w-5 h-5 text-purple-600" />
          <h2 className="font-semibold text-lg">AI Workflow Assistant</h2>
        </div>
        <p className="text-sm text-gray-600 mt-1">
          Describe what you want to change, and I'll update the workflow
        </p>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.length === 0 && (
          <div className="text-center text-gray-500 mt-8">
            <Sparkles className="w-12 h-12 mx-auto mb-3 text-purple-300" />
            <p className="text-sm">Start a conversation to edit your workflow</p>
            <p className="text-xs mt-1">Example: "Add a phone number field to the contact section"</p>
          </div>
        )}

        {messages.map((message) => (
          <div
            key={message.id}
            className={cn(
              "flex",
              message.role === "user" ? "justify-end" : "justify-start"
            )}
          >
            <Card
              className={cn(
                "max-w-[85%] p-3",
                message.role === "user"
                  ? "bg-blue-500 text-white"
                  : "bg-white border"
              )}
            >
              {/* Message content */}
              <div className="text-sm whitespace-pre-wrap">{message.content}</div>

              {/* Summary bullets */}
              {message.summary && message.summary.length > 0 && (
                <div className="mt-3 pt-3 border-t">
                  <div className="text-xs font-semibold mb-2">What changed:</div>
                  <ul className="text-xs space-y-1">
                    {message.summary.map((item, idx) => (
                      <li key={idx} className="flex items-start gap-2">
                        <span className="text-green-500">Γ£ô</span>
                        <span>{item}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {/* Warnings */}
              {message.warnings && message.warnings.length > 0 && (
                <div className="mt-3 pt-3 border-t">
                  <div className="flex items-center gap-1 text-xs font-semibold mb-2 text-amber-600">
                    <AlertTriangle className="w-3 h-3" />
                    Warnings:
                  </div>
                  <ul className="text-xs space-y-1">
                    {message.warnings.map((item, idx) => (
                      <li key={idx} className="flex items-start gap-2">
                        <span className="text-amber-500">ΓÜá</span>
                        <span>{item}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {/* Questions */}
              {message.questions && message.questions.length > 0 && (
                <div className="mt-3 pt-3 border-t">
                  <div className="flex items-center gap-1 text-xs font-semibold mb-2">
                    <HelpCircle className="w-3 h-3" />
                    Questions:
                  </div>
                  <ul className="text-xs space-y-2">
                    {message.questions.map((q) => (
                      <li key={q.id} className="flex items-start gap-2">
                        <span>ΓÇó</span>
                        <span>{q.prompt}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {/* Confidence */}
              {message.confidence !== undefined && (
                <div className="mt-3 pt-3 border-t">
                  <div className="flex items-center justify-between text-xs">
                    <span className="text-gray-600">Confidence:</span>
                    <span className="font-medium">
                      {Math.round(message.confidence * 100)}%
                    </span>
                  </div>
                </div>
              )}

              {/* Actions */}
              {message.versionId && (
                <div className="mt-3 pt-3 border-t flex gap-2">
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => { void handleViewDiff(message.versionId!); }}
                    className="text-xs"
                  >
                    <History className="w-3 h-3 mr-1" />
                    View Diff
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => { void handleUndo(message.versionId!); }}
                    className="text-xs"
                  >
                    <Undo className="w-3 h-3 mr-1" />
                    Undo
                  </Button>
                </div>
              )}
            </Card>
          </div>
        ))}

        {isLoading && (
          <div className="flex justify-start">
            <Card className="max-w-[85%] p-3 bg-white border">
              <div className="flex items-center gap-2 text-sm text-gray-500">
                <div className="animate-spin rounded-full h-4 w-4 border-2 border-purple-500 border-t-transparent" />
                <span>Thinking...</span>
              </div>
            </Card>
          </div>
        )}
      </div>

      {/* Input */}
      <form onSubmit={(e) => { e.preventDefault(); void handleSubmit(e); }} className="p-4 border-t bg-white">
        {error && (
          <div className="mb-3 p-2 bg-red-50 border border-red-200 rounded text-xs text-red-600">
            {error}
          </div>
        )}
        <div className="flex gap-2">
          <Textarea
            value={input}
            onChange={(e) => { void setInput(e.target.value); }}
            placeholder="Describe what you want to change..."
            className="min-h-[60px] resize-none"
            onKeyDown={(e) => {
              if (e.key === "Enter" && !e.shiftKey) {
                e.preventDefault();
                handleSubmit(e);
              }
            }}
            disabled={isLoading}
          />
          <Button
            type="submit"
            size="icon"
            disabled={!input.trim() || isLoading}
            className="shrink-0"
          >
            <Send className="w-4 h-4" />
          </Button>
        </div>
        <p className="text-xs text-gray-500 mt-2">
          Press Enter to send, Shift+Enter for new line
        </p>
      </form>
    </div>
  );
}

import { Plus, Edit, Minus } from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
interface DiffChange {
    type: 'add' | 'modify' | 'remove';
    entity: 'section' | 'step' | 'logic';
    name: string;
    details?: string;
}
interface AiDiffViewProps {
    suggestions: any;
}
export function AiDiffView({ suggestions }: AiDiffViewProps) {
    // Parse suggestions into a flat list of changes for display
    const changes: DiffChange[] = [];
    if (suggestions.newSections) {
        suggestions.newSections.forEach((s: any) => {
            changes.push({ type: 'add', entity: 'section', name: s.title, details: `${s.steps?.length || 0} steps` });
        });
    }
    if (suggestions.newSteps) {
        suggestions.newSteps.forEach((s: any) => {
            changes.push({ type: 'add', entity: 'step', name: s.title, details: s.type });
        });
    }
    // Hypothetical 'modifications' structure from AI
    if (suggestions.modifications) {
        suggestions.modifications.forEach((m: any) => {
            changes.push({ type: 'modify', entity: m.entity, name: m.name, details: m.reason });
        });
    }
    return (
        <div className="space-y-2 text-xs">
            {changes.length === 0 && (
                <div className="text-muted-foreground italic">No structural changes detected.</div>
            )}
            {changes.map((change, i) => (
                <div key={i} className="flex items-center gap-2 p-2 bg-white rounded border select-none">
                    <ChangeIcon type={change.type} />
                    <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                            <span className={cn("font-medium", getChangeColor(change.type))}>
                                {change.type === 'add' ? 'Create' : change.type === 'modify' ? 'Update' : 'Remove'}
                            </span>
                            <Badge variant="outline" className="text-[10px] px-1 h-4">{change.entity}</Badge>
                        </div>
                        <div className="truncate text-slate-700 mt-0.5">
                            {change.name}
                        </div>
                    </div>
                    {change.details && (
                        <div className="text-[10px] text-muted-foreground bg-slate-50 px-1.5 py-0.5 rounded border">
                            {change.details}
                        </div>
                    )}
                </div>
            ))}
        </div>
    );
}
function ChangeIcon({ type }: { type: DiffChange['type'] }) {
    switch (type) {
        case 'add': return <div className="w-5 h-5 rounded-full bg-emerald-100 flex items-center justify-center shrink-0"><Plus className="w-3 h-3 text-emerald-600" /></div>;
        case 'modify': return <div className="w-5 h-5 rounded-full bg-amber-100 flex items-center justify-center shrink-0"><Edit className="w-3 h-3 text-amber-600" /></div>;
        case 'remove': return <div className="w-5 h-5 rounded-full bg-rose-100 flex items-center justify-center shrink-0"><Minus className="w-3 h-3 text-rose-600" /></div>;
    }
}
function getChangeColor(type: DiffChange['type']) {
    switch (type) {
        case 'add': return "text-emerald-700";
        case 'modify': return "text-amber-700";
        case 'remove': return "text-rose-700";
    }
}

/**
 * Address Block Card Editor
 * Editor for address blocks (USA)
 *
 * Config shape:
 * {
 *   country: "US",
 *   fields: ["street", "city", "state", "zip"],
 *   requireAll?: boolean
 * }
 */

import { useState, useEffect } from "react";


import { Separator } from "@/components/ui/separator";
import { useUpdateStep } from "@/lib/vault-hooks";

import type { ConditionExpression } from "@shared/types/conditions";

import { StepEditorCommonProps } from "../StepEditorRouter";

import { AliasField } from "./common/AliasField";
import { SwitchField, SectionHeader } from "./common/EditorField";
import { RequiredToggle } from "./common/RequiredToggle";
import { VisibilityField } from "./common/VisibilityField";


import type { AddressConfig } from "@/../../shared/types/stepConfigs";

export function AddressCardEditor({ stepId, sectionId, workflowId, step }: StepEditorCommonProps) {
  const updateStepMutation = useUpdateStep();

  // Parse config
  const config = step.config as AddressConfig | undefined;
  const [localConfig, setLocalConfig] = useState<AddressConfig>({
    country: config?.country ?? "US",
    fields: config?.fields ?? ["street", "city", "state", "zip"],
    requireAll: config?.requireAll !== undefined ? config.requireAll : true,
  });

  useEffect(() => {
    const cfg = step.config as AddressConfig | undefined;
    setLocalConfig({
      country: cfg?.country ?? "US",
      fields: cfg?.fields ?? ["street", "city", "state", "zip"],
      requireAll: cfg?.requireAll !== undefined ? cfg.requireAll : true,
    });
  }, [step.config]);

  const handleUpdate = (updates: Partial<typeof localConfig>) => {
    const newConfig = { ...localConfig, ...updates };
    setLocalConfig(newConfig);

    const configToSave: AddressConfig = {
      country: newConfig.country,
      fields: newConfig.fields,
      requireAll: newConfig.requireAll,
    };

    updateStepMutation.mutate({ id: stepId, sectionId, config: configToSave });
  };

  const _handleLabelChange = (title: string) => {
    updateStepMutation.mutate({ id: stepId, sectionId, title });
  };

  const handleAliasChange = (alias: string | null) => {
    updateStepMutation.mutate({ id: stepId, sectionId, alias });
  };

  const handleRequiredChange = (required: boolean) => {
    updateStepMutation.mutate({ id: stepId, sectionId, required });
  };

  return (
    <div className="space-y-4 p-4 border-t bg-muted/30">
      {/* Alias */}
      <AliasField value={step.alias} onChange={handleAliasChange} />

      {/* Required Toggle */}
      <RequiredToggle checked={step.required} onChange={handleRequiredChange} />

      <Separator />

      {/* Address Fields Preview */}
      <div className="space-y-3">
        <SectionHeader
          title="Address Fields"
          description="USA address format (street, city, state, zip)"
        />

        <div className="p-3 bg-background border rounded-md space-y-2 text-sm">
          <div className="flex items-center gap-2 text-muted-foreground">
            <span className="font-mono">street</span>
            <span className="text-xs">ΓåÆ</span>
            <span>Street address</span>
          </div>
          <div className="flex items-center gap-2 text-muted-foreground">
            <span className="font-mono">city</span>
            <span className="text-xs">ΓåÆ</span>
            <span>City</span>
          </div>
          <div className="flex items-center gap-2 text-muted-foreground">
            <span className="font-mono">state</span>
            <span className="text-xs">ΓåÆ</span>
            <span>State (dropdown)</span>
          </div>
          <div className="flex items-center gap-2 text-muted-foreground">
            <span className="font-mono">zip</span>
            <span className="text-xs">ΓåÆ</span>
            <span>ZIP code (5 or 9 digits)</span>
          </div>
        </div>
      </div>

      <Separator />

      {/* Configuration Options */}
      <div className="space-y-3">
        <SectionHeader
          title="Validation"
          description="Configure validation rules"
        />

        <SwitchField
          label="Require All Fields"
          description="All address fields must be filled"
          checked={localConfig.requireAll ?? true}
          onChange={(checked) => handleUpdate({ requireAll: checked })}
        />
      </div>

      {/* How it works */}
      <div className="text-xs text-muted-foreground bg-muted p-3 rounded-md">
        <p className="font-medium mb-1">How it works:</p>
        <ul className="list-disc list-inside space-y-1">
          <li>Street: Text input</li>
          <li>City: Text input</li>
          <li>State: Dropdown of US states</li>
          <li>ZIP: Validated for 5 or 9 digits</li>
          <li>Stored as: <code className="font-mono">{`{street, city, state, zip}`}</code></li>
        </ul>
      </div>

      {workflowId && (
        <VisibilityField
          stepId={stepId}
          sectionId={sectionId}
          workflowId={workflowId}
          visibleIf={step.visibleIf as ConditionExpression}
          mode="advanced"
        />
      )}
    </div>
  );
}

/**
 * Boolean Block Card Editor
 * Editor for boolean blocks (yes_no, true_false, boolean)
 */

import { useState, useEffect } from "react";

import { Separator } from "@/components/ui/separator";
import { useUpdateStep } from "@/lib/vault-hooks";

import type { ConditionExpression } from "@shared/types/conditions";

import { StepEditorCommonProps } from "../StepEditorRouter";

import { AliasField } from "./common/AliasField";
import { DefaultValueField, DefaultValueType } from "./common/DefaultValueField";
import { TextField, SwitchField, SectionHeader } from "./common/EditorField";
import { RequiredToggle } from "./common/RequiredToggle";
import { VisibilityField } from "./common/VisibilityField";


import type { BooleanAdvancedConfig, TrueFalseConfig } from "@/../../shared/types/stepConfigs";

export function BooleanCardEditor({ stepId, sectionId, workflowId, step }: StepEditorCommonProps) {
  const updateStepMutation = useUpdateStep();

  // Determine if this is advanced mode (type === "boolean") or easy mode (yes_no/true_false)
  const isAdvancedMode = step.type === "boolean";
  const isEasyMode = !isAdvancedMode;

  // Get config with defaults
  const config = step.config as BooleanAdvancedConfig | TrueFalseConfig | undefined;

  // Default labels based on type
  const getDefaultLabels = () => {
    if (step.type === "yes_no") {
      return { trueLabel: "Yes", falseLabel: "No" };
    } else if (step.type === "true_false") {
      return { trueLabel: "True", falseLabel: "False" };
    } else {
      return { trueLabel: "Yes", falseLabel: "No" };
    }
  };

  const defaults = getDefaultLabels();

  const [localConfig, setLocalConfig] = useState({
    trueLabel: config?.trueLabel ?? defaults.trueLabel,
    falseLabel: config?.falseLabel ?? defaults.falseLabel,
    storeAsBoolean: isAdvancedMode
      ? ((config as BooleanAdvancedConfig)?.storeAsBoolean ?? true)
      : true,
    trueAlias: (config as BooleanAdvancedConfig)?.trueAlias ?? "",
    falseAlias: (config as BooleanAdvancedConfig)?.falseAlias ?? "",
  });

  useEffect(() => {
    const defaults = getDefaultLabels();
    setLocalConfig({
      trueLabel: config?.trueLabel ?? defaults.trueLabel,
      falseLabel: config?.falseLabel ?? defaults.falseLabel,
      storeAsBoolean: isAdvancedMode
        ? ((config as BooleanAdvancedConfig)?.storeAsBoolean ?? true)
        : true,
      trueAlias: (config as BooleanAdvancedConfig)?.trueAlias ?? "",
      falseAlias: (config as BooleanAdvancedConfig)?.falseAlias ?? "",
    });
  }, [step.config, step.type, isAdvancedMode, config]);

  const handleUpdate = (updates: Partial<typeof localConfig>) => {
    const newConfig = { ...localConfig, ...updates };
    setLocalConfig(newConfig);

    // Build the config object based on mode
    if (isAdvancedMode) {
      const configToSave: BooleanAdvancedConfig = {
        trueLabel: newConfig.trueLabel,
        falseLabel: newConfig.falseLabel,
        storeAsBoolean: newConfig.storeAsBoolean,
      };

      // Only include aliases if not storing as boolean
      if (!newConfig.storeAsBoolean) {
        if (newConfig.trueAlias && newConfig.trueAlias.trim() !== "") {
          configToSave.trueAlias = newConfig.trueAlias;
        }
        if (newConfig.falseAlias && newConfig.falseAlias.trim() !== "") {
          configToSave.falseAlias = newConfig.falseAlias;
        }
      }

      updateStepMutation.mutate({ id: stepId, sectionId, config: configToSave });
    } else {
      // Easy mode - just save labels
      const configToSave: TrueFalseConfig = {
        trueLabel: newConfig.trueLabel,
        falseLabel: newConfig.falseLabel,
      };

      updateStepMutation.mutate({ id: stepId, sectionId, config: configToSave });
    }
  };



  const handleAliasChange = (alias: string | null) => {
    updateStepMutation.mutate({ id: stepId, sectionId, alias });
  };

  const handleRequiredChange = (required: boolean) => {
    updateStepMutation.mutate({ id: stepId, sectionId, required });
  };

  return (
    <div className="space-y-4 p-4 border-t bg-muted/30">
      {/* Alias */}
      <AliasField value={step.alias} onChange={handleAliasChange} />

      {/* Required Toggle */}
      <RequiredToggle checked={step.required} onChange={handleRequiredChange} />

      <Separator />

      {/* Labels Configuration */}
      <div className="space-y-4">
        <SectionHeader
          title="Option Labels"
          description="Customize the labels for true and false values"
        />

        {/* True Label */}
        <TextField
          label="True Label"
          value={localConfig.trueLabel}
          onChange={(val) => handleUpdate({ trueLabel: val })}
          placeholder={defaults.trueLabel}
          required
        />

        {/* False Label */}
        <TextField
          label="False Label"
          value={localConfig.falseLabel}
          onChange={(val) => handleUpdate({ falseLabel: val })}
          placeholder={defaults.falseLabel}
          required
        />
      </div>

      {/* Advanced Mode Only - Storage Options */}
      {isAdvancedMode && (
        <>
          <Separator />

          <div className="space-y-4">
            <SectionHeader
              title="Storage Mode"
              description="Choose how to store the boolean value"
            />

            {/* Store as Boolean Toggle */}
            <SwitchField
              label="Store as Boolean"
              checked={localConfig.storeAsBoolean}
              onChange={(val) => handleUpdate({ storeAsBoolean: val })}
              description="Store true/false instead of custom alias values"
            />

            {/* Alias Fields - Only show if not storing as boolean */}
            {!localConfig.storeAsBoolean && (
              <div className="space-y-4 pl-4 border-l-2 border-muted">
                <p className="text-xs text-muted-foreground">
                  When not storing as boolean, you can specify custom string values for true and
                  false
                </p>

                {/* True Alias */}
                <TextField
                  label="True Value (String)"
                  value={localConfig.trueAlias}
                  onChange={(val) => handleUpdate({ trueAlias: val })}
                  placeholder="yes"
                  description="String value to store when true is selected"
                />

                {/* False Alias */}
                <TextField
                  label="False Value (String)"
                  value={localConfig.falseAlias}
                  onChange={(val) => handleUpdate({ falseAlias: val })}
                  placeholder="no"
                  description="String value to store when false is selected"
                />
              </div>
            )}
          </div>
        </>
      )}

      {workflowId && (
        <>
          <DefaultValueField
            stepId={stepId}
            sectionId={sectionId}
            workflowId={workflowId}
            defaultValue={step.defaultValue as DefaultValueType}
            type={step.type}
            mode={isEasyMode ? 'easy' : 'advanced'}
          />
          <VisibilityField
            stepId={stepId}
            sectionId={sectionId}
            workflowId={workflowId}
            visibleIf={step.visibleIf as ConditionExpression}
            mode={isAdvancedMode ? 'advanced' : 'easy'}
          />
        </>
      )}
    </div>
  );
}

/**
 * Choice Block Card Editor
 * Editor for choice blocks (radio, multiple_choice, choice)
 *
 * Config shape:
 * {
 *   display: "radio" | "dropdown" | "multiple",
 *   allowMultiple: boolean,
 *   options: Array<{ id: string; label: string; alias?: string; }>
 * }
 */

import { useQueryClient } from "@tanstack/react-query";
import { AlertCircle } from "lucide-react";
import { useState, useMemo } from "react";

import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Separator } from "@/components/ui/separator";
import { Switch } from "@/components/ui/switch";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { useToast } from "@/hooks/use-toast";
import { useChoiceConfig, type ChoiceCardState } from "@/hooks/useChoiceConfig";
import { useListToolsValidation } from "@/hooks/useListToolsValidation";
import { blockAPI, type ApiWorkflowVariable, type ApiTransformBlock } from "@/lib/vault-api";
import { useUpdateStep, useWorkflowVariables, useWorkflow } from "@/lib/vault-hooks";

import { BlockEditorDialog, type UniversalBlock } from "../BlockEditorDialog";
import { StepEditorCommonProps } from "../StepEditorRouter";

import { AliasField } from "./common/AliasField";
import { DefaultValueField, DefaultValueType } from "./common/DefaultValueField";
import { SectionHeader } from "./common/EditorField";
import { RequiredToggle } from "./common/RequiredToggle";
import { DynamicOptionsEditor } from "./DynamicOptionsEditor";
import { StaticOptionsEditor } from "./StaticOptionsEditor";

import type { ChoiceAdvancedConfig, ChoiceOption } from "@/../../shared/types/stepConfigs";




export function ChoiceCardEditor({ stepId, sectionId, workflowId, step }: StepEditorCommonProps) {
  const updateStepMutation = useUpdateStep();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [isCreatingListTools, setIsCreatingListTools] = useState(false);

  // Block Editor Dialog state
  const [isBlockEditorOpen, setIsBlockEditorOpen] = useState(false);
  const [editingBlock, setEditingBlock] = useState<UniversalBlock | null>(null);

  // Unlink Confirmation Dialog state
  const [showUnlinkConfirm, setShowUnlinkConfirm] = useState(false);
  const [unlinkMode, setUnlinkMode] = useState<"keep" | "remove">("keep");

  // Replace Confirmation Dialog state
  const [showReplaceConfirm, setShowReplaceConfirm] = useState(false);
  const [replaceMode, setReplaceMode] = useState<"migrate" | "reset">("migrate");

  // Fetch workflow for mode
  const { data: workflow } = useWorkflow(workflowId);
  const mode = workflow?.modeOverride || 'easy';

  // Determine mode (kept for compatibility, but hook also provides this)
  const isAdvancedMode = step.type === "choice";

  // Use custom hooks for config management
  const { localConfig, setLocalConfig, sourceMode, setSourceMode } = useChoiceConfig(step);

  // State
  const [errors, setErrors] = useState<string[]>([]);

  // Fetch Workflow Variables (for dynamic mode)
  const { data: variables = [] } = useWorkflowVariables(workflowId);

  // Filter for List variables only
  const listVariables = useMemo(() => {
    return (variables).filter(v => v.type === 'read_table' || v.type === 'list_tools');
  }, [variables]);

  // Use custom hook for validation
  const {
    timingWarning,
    labelColumnWarning,
    valueColumnWarning,
    sourceBlock,
    sourceTableId,
    columns,
    loadingColumns,
    blocks
  } = useListToolsValidation({ localConfig, workflowId, sectionId });


  // Derived state for Dynamic Columns
  const selectedListVarName = localConfig?.dynamicOptions?.listVariable;

  // ---------------------------------------------------------------------------
  // HANDLERS
  // ---------------------------------------------------------------------------

  const saveConfig = (newConfig: ChoiceCardState, mode: "static" | "dynamic") => {
    // Validation
    const errors: string[] = [];
    if (mode === "static") {
      if ((newConfig.staticOptions || []).length === 0) { errors.push("At least one option is required"); }
      // Check for duplicate aliases
      const aliases = (newConfig.staticOptions || []).map((opt) => opt.alias || opt.id);
      if (new Set(aliases).size !== aliases.length) { errors.push("Duplicate aliases found"); }
    } else {
      if (!newConfig.dynamicOptions?.listVariable) { errors.push("List variable is required"); }
      // We allow saving with warning
    }
    setErrors(errors);
    if (errors.length > 0) { return; }

    // Construct Payload
    // If we are in "dynamic" mode, we MUST be 'choice' type (Advanced schema)
    const isNowAdvanced = mode === "dynamic" || isAdvancedMode;

    if (isNowAdvanced) {
      const payload: ChoiceAdvancedConfig = {
        display: newConfig.display,
        allowMultiple: newConfig.allowMultiple,
        searchable: newConfig.searchable,
        options: mode === 'static'
          ? { type: 'static', options: newConfig.staticOptions || [] }
          : { ...(newConfig.dynamicOptions || { listVariable: '' }), type: 'list' }
      };
      // Auto-upgrade type if needed
      if (step.type !== 'choice') {
        updateStepMutation.mutate({ id: stepId, sectionId, type: 'choice', config: payload });
      } else {
        updateStepMutation.mutate({ id: stepId, sectionId, config: payload });
      }
    } else {
      // Legacy Save
      const payload = {
        options: (newConfig.staticOptions || []).map((opt) => ({
          id: opt.id,
          label: opt.label,
          alias: opt.alias
        }))
      };
      updateStepMutation.mutate({ id: stepId, sectionId, config: payload });
    }
  };

  const handleUpdate = (updates: Partial<ChoiceCardState>) => {
    const next = { ...localConfig, ...updates };
    setLocalConfig(next as ChoiceCardState);
    saveConfig(next as ChoiceCardState, sourceMode);
  };

  const handleSourceModeChange = (val: string) => {
    if (!localConfig) { return; }
    const newMode = val as "static" | "dynamic";
    setSourceMode(newMode);
    saveConfig(localConfig, newMode);
  };

  const handleAddOption = () => {
    if (!localConfig) { return; }
    const newOptions = [
      ...localConfig.staticOptions,
      {
        id: `opt${localConfig.staticOptions.length + 1}`,
        label: `Option ${localConfig.staticOptions.length + 1}`,
        alias: `option${localConfig.staticOptions.length + 1}`,
      },
    ];
    handleUpdate({ staticOptions: newOptions });
  };

  const handleUpdateOption = (index: number, field: keyof ChoiceOption, value: string) => {
    if (!localConfig) { return; }
    const newOptions = [...localConfig.staticOptions];
    newOptions[index] = { ...newOptions[index], [field]: value };
    handleUpdate({ staticOptions: newOptions });
  };

  const handleDeleteOption = (index: number) => {
    if (!localConfig) { return; }
    const newOptions = localConfig.staticOptions.filter((_, i: number) => i !== index);
    handleUpdate({ staticOptions: newOptions });
  };


  const handleAliasChange = (alias: string | null) => updateStepMutation.mutate({ id: stepId, sectionId, alias });
  const handleRequiredChange = (required: boolean) => updateStepMutation.mutate({ id: stepId, sectionId, required });
  const handleDisplayChange = (display: "radio" | "dropdown" | "multiple") => {
    const allowMultiple = display === "multiple";
    if (!isAdvancedMode && sourceMode === 'static') {
      const newType = allowMultiple ? "multiple_choice" : "radio";
      updateStepMutation.mutate({ id: stepId, sectionId, type: newType });
    } else {
      handleUpdate({ display, allowMultiple });
    }
  };

  // List Tools block handlers
  const handleCreateListTools = async () => {
    if (!localConfig?.dynamicOptions?.listVariable) {
      toast({
        title: "Error",
        description: "Please select a list variable first",
        variant: "destructive"
      });
      return;
    }

    setIsCreatingListTools(true);
    try {
      const result = await blockAPI.createListToolsFromChoice(workflowId, stepId, {
        sourceListVar: localConfig.dynamicOptions.listVariable,
        transformConfig: localConfig.dynamicOptions.transform,
        sectionId: sectionId
      });

      // Update the question config to link to the new block
      const newDynamic = {
        ...localConfig.dynamicOptions,
        linkedListToolsBlockId: result.block.id,
        baseListVar: localConfig.dynamicOptions.listVariable,
        listVariable: result.outputVar,
        transform: undefined // Clear transform since it's now in the block
      };

      handleUpdate({ dynamicOptions: newDynamic });

      // Invalidate blocks query to refresh the list
      queryClient.invalidateQueries({ queryKey: ['blocks', workflowId] });

      toast({
        title: "Success",
        description: `Created List Tools block: ${result.outputVar}`,
      });

      // Auto-open the block editor so user can immediately configure transforms
      const universalBlock: UniversalBlock = {
        id: result.block.id,
        type: result.block.type,
        phase: result.block.phase || 'onRunStart',
        order: result.block.order || 0,
        enabled: result.block.enabled ?? true,
        raw: result.block as unknown as Record<string, unknown>,
        source: 'regular',
        title: result.outputVar,
        displayType: 'list_tools'
      };

      setEditingBlock(universalBlock);
      setIsBlockEditorOpen(true);
    } catch (error) {
      console.error("Error creating List Tools block:", error);
      toast({
        title: "Error",
        description: error instanceof Error ? error.message : "Failed to create List Tools block",
        variant: "destructive"
      });
    } finally {
      setIsCreatingListTools(false);
    }
  };



  const confirmUnlinkListTools = () => {
    if (!localConfig?.dynamicOptions?.baseListVar) {
      toast({
        title: "Error",
        description: "No base list variable found", // Should theoretically not happen if button enabled
        variant: "destructive"
      });
      // Fallback: just clear link if we can't find base? No, risky.
      // But if baseListVar is missing, maybe we should just use current listVariable?
      // For now, respect the error.
      setShowUnlinkConfirm(false);
      return;
    }

    let transform = undefined;

    if (unlinkMode === 'keep') {
      // Attempt to migrate transforms back
      if ((linkedBlock)?.config) {
        const blockConfig = (linkedBlock).config;
        transform = {
          filters: blockConfig.filters,
          sort: blockConfig.sort,
          limit: blockConfig.limit,
          offset: blockConfig.offset,
          dedupe: blockConfig.dedupe,
          select: blockConfig.select
        };
      } else {
        // Warning if block not found?
        toast({
          title: "Warning",
          description: "Linked block not found. Transforms could not be preserved.",
          variant: "destructive"
        });
      }
    }

    const newDynamic = {
      ...localConfig.dynamicOptions,
      linkedListToolsBlockId: undefined,
      listVariable: localConfig.dynamicOptions.baseListVar,
      baseListVar: undefined,
      transform: transform
    };

    handleUpdate({ dynamicOptions: newDynamic });

    toast({
      title: "Unlinked",
      description: unlinkMode === 'keep'
        ? "List Tools block unlinked. Transforms have been copied to this question."
        : "List Tools block unlinked. Transforms have been removed.",
    });

    setShowUnlinkConfirm(false);
  };



  const confirmReplaceListTools = async () => {
    if (!localConfig?.dynamicOptions?.baseListVar) {
      toast({
        title: "Error",
        description: "No base list variable found",
        variant: "destructive"
      });
      setShowReplaceConfirm(false);
      return;
    }

    setIsCreatingListTools(true);
    try {
      // Determine transform config for new block
      let transformConfig = undefined;
      if (replaceMode === 'migrate' && (linkedBlock)?.config) {
        // Create copy of existing transforms
        transformConfig = {
          filters: (linkedBlock).config.filters,
          sort: (linkedBlock).config.sort,
          limit: (linkedBlock).config.limit,
          offset: (linkedBlock).config.offset,
          dedupe: (linkedBlock).config.dedupe,
          select: (linkedBlock).config.select
        };
      }

      // Unlink first (conceptually), but we can just overwrite the link.
      // Actually, we should probably keep the old block unless we want to delete it?
      // "Replace" implies swapping. We won't delete the old block automatically as it might be used elsewhere (though unlikely for dedicated tools).
      // API createListToolsFromChoice creates a NEW block.

      const result = await blockAPI.createListToolsFromChoice(workflowId, stepId, {
        sourceListVar: localConfig.dynamicOptions.baseListVar, // Use base list as source
        transformConfig: transformConfig,
        sectionId: sectionId
      });

      // Update the question config to link to the new block
      const newDynamic = {
        ...localConfig.dynamicOptions,
        linkedListToolsBlockId: result.block.id,
        listVariable: result.outputVar,
        // baseListVar remains the same
        transform: undefined
      };

      handleUpdate({ dynamicOptions: newDynamic });

      // Invalidate blocks
      queryClient.invalidateQueries({ queryKey: ['blocks', workflowId] });

      toast({
        title: "Success",
        description: replaceMode === 'migrate'
          ? `Replaced List Tools block (transforms maintained): ${result.outputVar}`
          : `Replaced List Tools block (fresh start): ${result.outputVar}`,
      });

      // Open new block
      const universalBlock: UniversalBlock = {
        id: result.block.id,
        type: result.block.type,
        phase: result.block.phase || 'onRunStart',
        order: result.block.order || 0,
        enabled: result.block.enabled ?? true,
        raw: result.block as unknown as Record<string, unknown>,
        source: 'regular',
        title: result.outputVar,
        displayType: 'list_tools'
      };

      setEditingBlock(universalBlock);
      setIsBlockEditorOpen(true);

    } catch (error) {
      console.error("Error replacing List Tools block:", error);
      toast({
        title: "Error",
        description: error instanceof Error ? error.message : "Failed to replace List Tools block",
        variant: "destructive"
      });
    } finally {
      setIsCreatingListTools(false);
      setShowReplaceConfirm(false);
    }
  };

  const linkedBlock = useMemo(() => {
    if (!localConfig?.dynamicOptions?.linkedListToolsBlockId || !blocks) { return null; }
    return (blocks || []).find((b) => b.id === localConfig.dynamicOptions?.linkedListToolsBlockId);
  }, [localConfig?.dynamicOptions?.linkedListToolsBlockId, blocks]);

  const handleOpenLinkedBlock = () => {
    if (!linkedBlock) {
      toast({
        title: "Error",
        description: "Linked block not found",
        variant: "destructive"
      });
      return;
    }

    // Convert to UniversalBlock format expected by BlockEditorDialog
    const universalBlock: UniversalBlock = {
      id: (linkedBlock).id,
      type: (linkedBlock).type,
      phase: (linkedBlock).phase || 'onRunStart',
      order: (linkedBlock).order || 0,
      enabled: (linkedBlock).enabled ?? true,
      raw: linkedBlock as unknown as Record<string, unknown>,
      source: 'regular',
      title: (linkedBlock).config?.outputListVar || (linkedBlock).config?.outputKey || 'List Tools',
      displayType: 'list_tools'
    };

    setEditingBlock(universalBlock);
    setIsBlockEditorOpen(true);
  };

  const handleCloseBlockEditor = () => {
    setIsBlockEditorOpen(false);
    setEditingBlock(null);
    // Refresh blocks after editing
    queryClient.invalidateQueries({ queryKey: ['workflows', workflowId, 'blocks'] });
  };

  if (!localConfig) { return null; }

  return (
    <div className="space-y-4 p-4 border-t bg-muted/30">
      <AliasField value={step.alias} onChange={(val) => { void handleAliasChange(val); }} />
      <RequiredToggle checked={step.required} onChange={(val) => { void handleRequiredChange(val); }} />

      <Separator />

      {/* Display Mode */}
      <div className="space-y-3">
        <SectionHeader title="Display Mode" description="How choices are displayed" />
        <RadioGroup value={localConfig.display} onValueChange={(v) => handleDisplayChange(v as "radio" | "dropdown" | "multiple")} disabled={false} className="flex gap-4">
          <div className="flex items-center space-x-2">
            <RadioGroupItem value="radio" id="d-radio" />
            <Label htmlFor="d-radio">Radio</Label>
          </div>
          <div className="flex items-center space-x-2">
            <RadioGroupItem value="dropdown" id="d-dropdown" />
            <Label htmlFor="d-dropdown">Dropdown</Label>
          </div>
          <div className="flex items-center space-x-2">
            <RadioGroupItem value="multiple" id="d-multiple" />
            <Label htmlFor="d-multiple">Multiple</Label>
          </div>
        </RadioGroup>

        {(localConfig.display === 'dropdown' || localConfig.display === 'multiple') && (
          <div className="flex items-center space-x-2 pt-2">
            <Switch
              id="searchable-mode"
              checked={localConfig.searchable ?? false}
              onCheckedChange={(c) => handleUpdate({ searchable: c })}
            />
            <Label htmlFor="searchable-mode" className="text-xs font-normal text-muted-foreground">Allow Search</Label>
          </div>
        )}
      </div>

      <Separator />

      {/* Options Source Toggle */}
      <Tabs value={sourceMode} onValueChange={handleSourceModeChange} className="w-full">
        <div className="flex items-center justify-between mb-4">
          <Label className="text-sm font-medium">Options Source</Label>
          <TabsList className="grid w-[200px] grid-cols-2 h-8">
            <TabsTrigger value="static" className="text-xs">Manual</TabsTrigger>
            <TabsTrigger value="dynamic" className="text-xs">From Table</TabsTrigger>
          </TabsList>
        </div>

        <TabsContent value="static" className="mt-0 space-y-3">
          <StaticOptionsEditor
            options={localConfig.staticOptions}
            onUpdate={handleUpdateOption}
            onDelete={handleDeleteOption}
            onAdd={handleAddOption}
          />
        </TabsContent>

        <TabsContent value="dynamic" className="mt-0 space-y-4">
          <DynamicOptionsEditor
            config={localConfig.dynamicOptions}
            listVariables={listVariables}
            sourceBlock={(sourceBlock as ApiTransformBlock | null)}
            sourceTableId={sourceTableId}
            columns={columns}
            loadingColumns={loadingColumns}
            timingWarning={timingWarning}
            labelColumnWarning={labelColumnWarning}
            valueColumnWarning={valueColumnWarning}
            onUpdate={(updates) => handleUpdate({ dynamicOptions: { ...localConfig.dynamicOptions, ...updates } })}
            onCreateListTools={handleCreateListTools}
            onEditBlock={handleOpenLinkedBlock}
            onUnlinkBlock={() => setShowUnlinkConfirm(true)}
            onReplaceBlock={() => setShowReplaceConfirm(true)}
          />
        </TabsContent>
      </Tabs>

      {/* Errors */}
      {
        errors.length > 0 && (
          <div className="flex items-start gap-2 text-xs text-destructive bg-destructive/10 p-3 rounded-md">
            <AlertCircle className="h-4 w-4 mt-0.5 flex-shrink-0" />
            <ul className="list-disc list-inside">
              {errors.map((error, idx) => <li key={idx}>{error}</li>)}
            </ul>
          </div>
        )
      }

      {/* Block Editor Dialog */}
      <BlockEditorDialog
        workflowId={workflowId}
        block={editingBlock}
        mode={mode}
        isOpen={isBlockEditorOpen}
        onClose={handleCloseBlockEditor}
      />

      {/* Replace Confirmation Dialog */}
      <AlertDialog open={showReplaceConfirm} onOpenChange={setShowReplaceConfirm}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Replace List Tools Block?</AlertDialogTitle>
            <AlertDialogDescription>
              This will create a new List Tools block and link this question to it.
              Do you want to copy the current transforms (filters, sort, etc.) to the new block?
            </AlertDialogDescription>
            <div className="py-4">
              <RadioGroup value={replaceMode} onValueChange={(v) => setReplaceMode(v as "migrate" | "reset")}>
                <div className="flex items-start space-x-2 space-y-1">
                  <RadioGroupItem value="migrate" id="rp-migrate" className="mt-1" />
                  <div className="grid gap-1.5 leading-none">
                    <Label htmlFor="rp-migrate" className="font-medium cursor-pointer">
                      Keep current behavior (Recommended)
                    </Label>
                    <p className="text-sm text-muted-foreground">
                      Initialize the new block with the same filters and sorting as the current one.
                    </p>
                  </div>
                </div>
                <div className="flex items-start space-x-2 space-y-1 mt-2">
                  <RadioGroupItem value="reset" id="rp-reset" className="mt-1" />
                  <div className="grid gap-1.5 leading-none">
                    <Label htmlFor="rp-reset" className="font-medium cursor-pointer">
                      Start fresh
                    </Label>
                    <p className="text-sm text-muted-foreground">
                      Create a completely empty block with no transforms.
                    </p>
                  </div>
                </div>
              </RadioGroup>
            </div>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={confirmReplaceListTools}>
              Replace
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Unlink Confirmation Dialog */}
      <AlertDialog open={showUnlinkConfirm} onOpenChange={setShowUnlinkConfirm}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Unlink List Tools Block?</AlertDialogTitle>
            <AlertDialogDescription>
              This question currently uses a linked List Tools block to generate its options.
            </AlertDialogDescription>
            <div className="py-4">
              <RadioGroup value={unlinkMode} onValueChange={(v) => setUnlinkMode(v as "keep" | "remove")}>
                <div className="flex items-start space-x-2 space-y-1">
                  <RadioGroupItem value="keep" id="ul-keep" className="mt-1" />
                  <div className="grid gap-1.5 leading-none">
                    <Label htmlFor="ul-keep" className="font-medium cursor-pointer">
                      Keep current behavior (Recommended)
                    </Label>
                    <p className="text-sm text-muted-foreground">
                      Copy the transforms from the block into this question configuration. The options will remain the same.
                    </p>
                  </div>
                </div>
                <div className="flex items-start space-x-2 space-y-1 mt-2">
                  <RadioGroupItem value="remove" id="ul-remove" className="mt-1" />
                  <div className="grid gap-1.5 leading-none">
                    <Label htmlFor="ul-remove" className="font-medium cursor-pointer">
                      Remove transforms
                    </Label>
                    <p className="text-sm text-muted-foreground">
                      Use the original list without any filters or sorting.
                    </p>
                  </div>
                </div>
              </RadioGroup>
            </div>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={confirmUnlinkListTools}>
              Unlink
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
      <DefaultValueField
        stepId={stepId}
        sectionId={sectionId}
        workflowId={workflowId}
        defaultValue={step.defaultValue as DefaultValueType}
        type={step.type}
        mode={isAdvancedMode ? 'advanced' : 'easy'}
      />
    </div >
  );
}

