/**
 * Step Card Component
 * Expandable card for editing step properties inline
 * Shows label, type, required (in header), and uses StepEditorRouter for the body
 */

import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import {
    GripVertical,
    FileText,
    ChevronDown,
    ChevronRight,
    Trash2,
    Type,
    AlignLeft,
    Circle,
    CheckSquare,
    ToggleLeft,
    Calendar,
    Upload,
    Zap,
    X,
    Database,
} from "lucide-react";
import { useState, useEffect, useRef } from "react";

import { useCollaboration, useBlockCollaborators } from "@/components/collab/CollaborationContext";
import { LogicIndicator } from "@/components/logic";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { useToast } from "@/hooks/use-toast";
import { cn } from "@/lib/utils";
import type { ApiStep, StepType } from "@/lib/vault-api";
import {
    useUpdateStep,
    useDeleteStep,
    useWorkflow,
    useWorkflowMode
} from "@/lib/vault-hooks";

import type { ConditionExpression } from "@shared/types/conditions";

import { useIntake } from "../IntakeContext";
import { StepEditorRouter } from "../StepEditorRouter";

import { StepGuidance } from "./common/StepGuidance";
import { getQuestionTypeIcon } from "./common/StepIcons";
import { StepTitleRow } from "./common/StepTitleRow";

interface StepCardProps {
    step: ApiStep;
    sectionId: string;
    workflowId: string;
    isExpanded?: boolean;
    autoFocus?: boolean;
    onToggleExpand?: () => void;
    onEnterNext?: () => void;
}

interface StepDefaultValue {
    source?: string;
    variable?: string;
    value?: unknown;
}

// Get icon for each question type


// eslint-disable-next-line max-lines-per-function
export function StepCard({
    step,
    sectionId,
    workflowId,
    isExpanded = false,
    autoFocus = false,
    onToggleExpand,
    onEnterNext,
}: StepCardProps) {
    const updateStepMutation = useUpdateStep();
    const deleteStepMutation = useDeleteStep();
    const { toast } = useToast();
    const { data: modeData } = useWorkflowMode(workflowId);
    const mode = modeData?.mode || 'easy';
    const { data: workflow } = useWorkflow(workflowId);
    const { upstreamWorkflow, upstreamVariables } = useIntake();

    // Intake Derived Values
    const defVal = step.defaultValue as StepDefaultValue | undefined;
    const isLinkedToIntake = defVal?.source === 'intake';
    const linkedVariable = isLinkedToIntake ? upstreamVariables.find(v => v.alias === defVal?.variable) : null;

    // Collaboration Hooks
    const { updateActiveBlock, user: currentUser } = useCollaboration();
    const { lockedBy, isLocked } = useBlockCollaborators(step.id);
    const isLockedByOther = isLocked && lockedBy?.userId !== currentUser?.id;

    const handleFocus = () => {
        if (!isLockedByOther) {
            updateActiveBlock(step.id);
        }
    };

    const handleBlur = (e: React.FocusEvent) => {
        // Check if new focus is still within this card
        if (e.relatedTarget && (e.relatedTarget as HTMLElement).closest(`[data-step-id="${step.id}"]`)) {
            return;
        }
        // Only clear if we were the one locking it
        if (!isLockedByOther) {
            updateActiveBlock(null);
        }
    };


    const [isGuidanceDismissed, setIsGuidanceDismissed] = useState(false);



    // Make sortable
    const {
        attributes,
        listeners,
        setNodeRef,
        transform,
        transition,
        isDragging,
    } = useSortable({ id: step.id });

    const style = {
        transform: CSS.Transform.toString(transform),
        transition,
    };

    // Immediate update handlers with optimistic rendering
    const handleTitleChange = (value: string) => {
        updateStepMutation.mutate({ id: step.id, sectionId, title: value });
    };

    const handleDelete = async () => {
        // eslint-disable-next-line no-alert
        if (!confirm(`Delete question "${step.title}"?`)) { return; }

        try {
            await deleteStepMutation.mutateAsync({ id: step.id, sectionId });
            toast({
                title: "Question deleted",
                description: "Question removed from page",
            });
        } catch (error) {
            toast({
                title: "Error",
                description: "Failed to delete question",
                variant: "destructive",
            });
        }
    };

    return (
        <div ref={setNodeRef} style={style} data-step-id={step.id} onFocus={() => { void handleFocus(); }} onBlur={(e) => { void handleBlur(e); }}>
            <Card className={cn("shadow-sm transition-all duration-300", isDragging && "opacity-50", isLockedByOther && "ring-2 ring-indigo-400/50 border-indigo-200")}>
                <CardContent className="p-3 relative">
                    {/* Lock Overlay */}
                    {isLockedByOther && (
                        <>
                            <div className="absolute top-2 right-12 z-20 flex items-center gap-2 bg-background/95 backdrop-blur px-2 py-1 rounded-full shadow-sm border border-indigo-100 animate-in fade-in zoom-in-95 duration-200">
                                <span className="text-[10px] font-medium text-indigo-700">Edited by {lockedBy?.displayName}</span>
                                <Avatar className="w-5 h-5 ring-1 ring-white">
                                    <AvatarFallback style={{ backgroundColor: lockedBy?.color }} className="text-[9px] text-white">
                                        {lockedBy?.displayName.charAt(0)}
                                    </AvatarFallback>
                                </Avatar>
                            </div>
                            {/* Interaction Blocker */}
                            <div className="absolute inset-0 z-10 bg-white/20" />
                        </>
                    )}

                    <div className="flex items-start gap-2">
                        {/* Drag Handle */}
                        <button
                            className="cursor-grab active:cursor-grabbing p-1 hover:bg-accent rounded mt-1"
                            {...attributes}
                            {...listeners}
                        >
                            <GripVertical className="h-4 w-4 text-muted-foreground" />
                        </button>

                        {/* Icon and Collapse Button (stacked vertically) */}
                        <div className="flex flex-col items-center gap-1">
                            <div className="mt-2 relative">
                                {getQuestionTypeIcon(step.type)}
                                {/* Show logic indicator when collapsed */}
                                {!isExpanded && !!step.visibleIf && (
                                    <div className="absolute -top-1 -right-1">
                                        <LogicIndicator
                                            visibleIf={step.visibleIf as ConditionExpression}
                                            variant="icon"
                                            size="sm"
                                            elementType="question"
                                        />
                                    </div>
                                )}
                            </div>
                            <Button
                                variant="ghost"
                                size="icon"
                                className="h-5 w-5"
                                onClick={() => { onToggleExpand?.(); }}
                            >
                                {isExpanded ? (
                                    <ChevronDown className="h-3 w-3" />
                                ) : (
                                    <ChevronRight className="h-3 w-3" />
                                )}
                            </Button>
                        </div>

                        {/* Visual Pills (collapsed view) */}
                        {!isExpanded && step.visibleIf !== null && step.visibleIf !== undefined && (
                            <div className="mt-2">
                                <Badge variant="outline" className="text-[9px] h-4 px-1.5 bg-amber-500/10 text-amber-600 hover:bg-amber-500/20 border-amber-500/20 font-medium">
                                    Conditional
                                </Badge>
                            </div>
                        )}

                        {/* Content */}
                        <div className="flex-1 min-w-0 space-y-2">
                            {/* Header Row - Badges (required/conditional) above question */}
                            {(step.required || (step.visibleIf !== null && step.visibleIf !== undefined)) && (
                                <div className="flex items-center gap-1.5">
                                    {step.required && (
                                        <Badge variant="destructive" className="text-[9px] h-4 px-1.5 font-medium">
                                            Required
                                        </Badge>
                                    )}
                                    {step.visibleIf !== null && step.visibleIf !== undefined && (
                                        <Badge variant="outline" className="text-[9px] h-4 px-1.5 bg-amber-500/10 text-amber-600 hover:bg-amber-500/20 border-amber-500/20 font-medium">
                                            Conditional
                                        </Badge>
                                    )}
                                </div>
                            )}

                            {/* Title and Delete Row */}
                            <StepTitleRow
                                step={step}
                                mode={mode}
                                isGuidanceDismissed={isGuidanceDismissed}
                                onDismissGuidance={() => setIsGuidanceDismissed(true)}
                                onTitleChange={(val) => { void handleTitleChange(val); }}
                                onDelete={() => { void handleDelete(); }}
                                onEnterNext={onEnterNext}
                                autoFocus={autoFocus}
                                isExpanded={isExpanded}
                            />

                            {/* Intake Badge (Collapsed View) */}
                            {!isExpanded && isLinkedToIntake && (
                                <div className="flex items-center gap-1.5 text-[10px] text-emerald-600 bg-emerald-50 px-2 py-0.5 rounded-full w-fit border border-emerald-100">
                                    <Database className="w-3 h-3" />
                                    <span>Linked to <strong>{upstreamWorkflow?.title}</strong> ({linkedVariable?.label ?? linkedVariable?.alias})</span>
                                </div>
                            )}

                            {/* Expanded Content - Rendered by Router */}
                            {isExpanded && (
                                <StepEditorRouter step={step} sectionId={sectionId} workflowId={workflowId} />
                            )}
                        </div>
                    </div>
                </CardContent>
            </Card>
        </div >
    );
}

import { AlertCircle } from "lucide-react";
import { useState, useEffect } from "react";

import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Separator } from "@/components/ui/separator";
import { useToast } from "@/hooks/use-toast";
import type { ApiStep } from "@/lib/vault-api";
import { useUpdateStep } from "@/lib/vault-hooks";


import type { ConditionExpression } from "@shared/types/conditions";

import { AliasField } from "./common/AliasField";
import { DefaultValueField, DefaultValueType } from "./common/DefaultValueField";
import { TextField, NumberField, SectionHeader } from "./common/EditorField";
import { RequiredToggle } from "./common/RequiredToggle";
import { VisibilityField } from "./common/VisibilityField";


import type { TextAdvancedConfig } from "@/../../shared/types/stepConfigs";

// Local Props
interface TextCardEditorProps {
  stepId: string;
  sectionId: string;
  workflowId: string;
  step: ApiStep;
}

interface TextCardState {
  variant: "short" | "long";
  minLength?: number;
  maxLength?: number;
  pattern: string;
  patternMessage: string;
}

const InputTypeSection = ({
  variant,
  isEasyMode,
  onVariantChange
}: {
  variant: "short" | "long";
  isEasyMode: boolean;
  onVariantChange: (v: "short" | "long") => void;
}) => (
  <div className="space-y-3">
    <SectionHeader
      title="Input Type"
      description={isEasyMode ? "Fixed in easy mode" : "Choose input style"}
    />
    <RadioGroup
      value={variant}
      onValueChange={(v) => onVariantChange(v as "short" | "long")}
      disabled={isEasyMode}
    >
      <div className="flex items-center space-x-2">
        <RadioGroupItem value="short" id="variant-short" disabled={isEasyMode} />
        <Label
          htmlFor="variant-short"
          className={isEasyMode ? "text-muted-foreground" : "cursor-pointer"}
        >
          Short Text (Single line)
        </Label>
      </div>
      <div className="flex items-center space-x-2">
        <RadioGroupItem value="long" id="variant-long" disabled={isEasyMode} />
        <Label
          htmlFor="variant-long"
          className={isEasyMode ? "text-muted-foreground" : "cursor-pointer"}
        >
          Long Text (Multi-line)
        </Label>
      </div>
    </RadioGroup>
  </div>
);

const TextValidationSection = ({
  localConfig,
  onUpdate,
  minMaxError,
  patternError
}: {
  localConfig: TextCardState;
  onUpdate: (updates: Partial<TextCardState>) => void;
  minMaxError: string | null;
  patternError: string | null;
}) => (
  <div className="space-y-4">
    <SectionHeader
      title="Validation Rules"
      description="Optional constraints for user input"
    />

    {/* Min Length */}
    <NumberField
      label="Minimum Length"
      value={localConfig.minLength}
      onChange={(val) => onUpdate({ minLength: val })}
      placeholder="No minimum"
      description="Minimum number of characters"
      min={0}
      error={minMaxError ?? undefined}
    />

    {/* Max Length */}
    <NumberField
      label="Maximum Length"
      value={localConfig.maxLength}
      onChange={(val) => onUpdate({ maxLength: val })}
      placeholder="No maximum"
      description="Maximum number of characters"
      min={0}
      error={minMaxError ?? undefined}
    />

    {/* Pattern (Regex) */}
    <TextField
      label="Pattern (Regex)"
      value={localConfig.pattern}
      onChange={(val) => onUpdate({ pattern: val })}
      placeholder="e.g., ^[A-Z]{3}-\\d{4}$"
      description="Regular expression for advanced validation"
      error={patternError ?? undefined}
    />

    {/* Pattern Error Message */}
    {localConfig.pattern && localConfig.pattern.trim() !== "" && !patternError && (
      <TextField
        label="Custom Error Message"
        value={localConfig.patternMessage}
        onChange={(val) => onUpdate({ patternMessage: val })}
        placeholder="e.g., Must match format ABC-1234"
        description="Message shown when pattern doesn't match"
      />
    )}
  </div>
);

export function TextCardEditor({ stepId, sectionId, workflowId, step }: TextCardEditorProps) {
  const updateStepMutation = useUpdateStep();
  const { toast } = useToast();

  // Determine if this is advanced mode (type === "text") or easy mode (short_text/long_text)
  const isAdvancedMode = step.type === "text";
  const isEasyMode = step.type === "short_text" || step.type === "long_text";

  // Get config with defaults using generic access for flexibility
  const config = step.config;
  const variant = isAdvancedMode
    ? (config?.variant ?? "short")
    : step.type === "long_text"
      ? "long"
      : "short";

  const [localConfig, setLocalConfig] = useState<TextCardState>({
    variant: variant,
    minLength: config?.validation?.minLength,
    maxLength: config?.validation?.maxLength,
    pattern: config?.validation?.pattern ?? "",
    patternMessage: config?.validation?.patternMessage ?? "",
  });

  const [patternError, setPatternError] = useState<string | null>(null);

  useEffect(() => {
    // Re-sync local config when step props change
    const currentConfig = step.config;
    const currentAdvanced = step.type === "text";

    // Determine variant from current state
    const newVariant = currentAdvanced
      ? (currentConfig?.variant ?? "short")
      : step.type === "long_text"
        ? "long"
        : "short";

    setLocalConfig({
      variant: newVariant,
      minLength: currentConfig?.validation?.minLength,
      maxLength: currentConfig?.validation?.maxLength,
      pattern: currentConfig?.validation?.pattern ?? "",
      patternMessage: currentConfig?.validation?.patternMessage ?? "",
    });
  }, [step.config, step.type]);

  const validatePattern = (pattern: string): string | null => {
    if (!pattern.trim()) { return null; }

    try {
      // eslint-disable-next-line security/detect-non-literal-regexp
      new RegExp(pattern);
      return null;
    } catch (error) {
      return "Invalid regular expression";
    }
  };

  const validateMinMax = (): string | null => {
    if (
      localConfig.minLength !== undefined &&
      localConfig.maxLength !== undefined &&
      localConfig.minLength > localConfig.maxLength
    ) {
      return "Min length cannot be greater than max length";
    }
    return null;
  };

  const handleUpdate = (updates: Partial<typeof localConfig>) => {
    const newConfig = { ...localConfig, ...updates };
    setLocalConfig(newConfig);

    // Validate pattern if it changed or exists in update
    // Note: We validate against `newConfig` pattern if updates contains it, or re-validate if needed
    // Actually, only validate if pattern is being updated
    if (updates.pattern !== undefined) {
      const error = validatePattern(updates.pattern);
      setPatternError(error);
      if (error) { return; } // Don't save if invalid
    }

    // Validate min/max
    const minMaxError = validateMinMax();
    // Logic: if min/max changed and invalid
    if (minMaxError && (updates.minLength !== undefined || updates.maxLength !== undefined)) {
      toast({
        title: "Validation Error",
        description: minMaxError,
        variant: "destructive",
      });
      return;
    }

    // Build the config object for advanced mode
    const configToSave: TextAdvancedConfig = {
      variant: newConfig.variant,
    };

    // Only include validation if there are validation rules
    const hasValidation =
      newConfig.minLength !== undefined ||
      newConfig.maxLength !== undefined ||
      (newConfig.pattern && newConfig.pattern.trim() !== "");

    if (hasValidation) {
      configToSave.validation = {};

      if (newConfig.minLength !== undefined) {
        configToSave.validation.minLength = newConfig.minLength;
      }
      if (newConfig.maxLength !== undefined) {
        configToSave.validation.maxLength = newConfig.maxLength;
      }
      if (newConfig.pattern && newConfig.pattern.trim() !== "") {
        configToSave.validation.pattern = newConfig.pattern;
        if (newConfig.patternMessage && newConfig.patternMessage.trim() !== "") {
          configToSave.validation.patternMessage = newConfig.patternMessage;
        }
      }
    }

    // If variant changed in advanced mode, also update the config
    if (isAdvancedMode) {
      updateStepMutation.mutate({ id: stepId, sectionId, config: configToSave });
    } else {
      // In easy mode, type change handled separately, but validation still saves to config?
      // Yes, short_text/long_text steps use validation config too.
      // But updateStepMutation expects config to match type...
      // `short_text` uses `TextConfig`?
      // Assuming backend handles it or config structure is compatible.
      updateStepMutation.mutate({ id: stepId, sectionId, config: configToSave });
    }
  };

  const handleVariantChange = (newVariant: "short" | "long") => {
    if (isEasyMode) {
      // In easy mode, changing variant means changing the step type
      const newType = newVariant === "short" ? "short_text" : "long_text";
      updateStepMutation.mutate({ id: stepId, sectionId, type: newType });
    } else {
      // In advanced mode, just update the config
      handleUpdate({ variant: newVariant });
    }
  };

  const handleAliasChange = (alias: string | null) => {
    updateStepMutation.mutate({ id: stepId, sectionId, alias });
  };

  const handleRequiredChange = (required: boolean) => {
    updateStepMutation.mutate({ id: stepId, sectionId, required });
  };

  return (
    <div className="space-y-4 p-4 border-t bg-muted/30">
      {/* Alias */}
      <AliasField value={step.alias} onChange={handleAliasChange} />

      {/* Required Toggle */}
      <RequiredToggle checked={step.required} onChange={handleRequiredChange} />

      <Separator />

      {/* Variant Selection */}
      <InputTypeSection
        variant={localConfig.variant}
        isEasyMode={isEasyMode}
        onVariantChange={handleVariantChange}
      />

      <Separator />

      {/* Validation Rules */}
      <TextValidationSection
        localConfig={localConfig}
        onUpdate={handleUpdate}
        minMaxError={validateMinMax()}
        patternError={patternError}
      />

      {patternError && (
        <div className="flex items-start gap-2 text-xs text-destructive bg-destructive/10 p-3 rounded-md">
          <AlertCircle className="h-4 w-4 mt-0.5 flex-shrink-0" />
          <div>
            <p className="font-medium">Pattern Error</p>
            <p>{patternError}</p>
          </div>
        </div>
      )}

      {workflowId && (
        <>
          <DefaultValueField
            stepId={stepId}
            sectionId={sectionId}
            workflowId={workflowId}
            defaultValue={step.defaultValue as DefaultValueType}
            type={step.type}
            mode={isEasyMode ? 'easy' : 'advanced'}
          />
          <VisibilityField
            stepId={stepId}
            sectionId={sectionId}
            workflowId={workflowId}
            visibleIf={step.visibleIf as ConditionExpression}
            mode={isAdvancedMode ? 'advanced' : 'easy'}
          />
        </>
      )}
    </div>
  );
}

