/**
 * Final Documents Section Editor
 * Configure Final Documents blocks for document generation
 */
import { useQuery } from "@tanstack/react-query";
import axios from "axios";
import { FileText, Eye, HelpCircle, CheckCircle } from "lucide-react";
import { useState } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Textarea } from "@/components/ui/textarea";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import type { ApiSection } from "@/lib/vault-api";
import { useUpdateSection } from "@/lib/vault-hooks";
interface FinalDocumentsSectionEditorProps {
  section: ApiSection;
  workflowId: string;
}
interface WorkflowTemplate {
  id: string;
  name: string;
  description: string | null;
}
import { useWorkflowBuilder } from "@/store/workflow-builder";
export function FinalDocumentsSectionEditor({ section, workflowId }: FinalDocumentsSectionEditorProps) {
  const updateSectionMutation = useUpdateSection();
  const { mode } = useWorkflowBuilder();
  const isEasyMode = mode === 'easy';
  // Define config type locally if not available globally yet
  interface FinalDocumentsConfig {
    finalBlock?: boolean;
    templates?: string[];
    screenTitle?: string;
    markdownMessage?: string;
    advanced?: Record<string, unknown>;
  }

  // Get config from section or use defaults
  const config = (section.config || {
    finalBlock: true,
    templates: [],
    screenTitle: "Your Completed Documents",
    markdownMessage: "# Thank You!\n\nYour documents are ready for download below.",
    advanced: {}
  }) as FinalDocumentsConfig;

  const [selectedTemplates, setSelectedTemplates] = useState<string[]>(config.templates ?? []);
  const [screenTitle, setScreenTitle] = useState(config.screenTitle || "Your Completed Documents");
  const [markdownMessage, setMarkdownMessage] = useState(config.markdownMessage || "# Thank You!\n\nYour documents are ready for download below.");
  // Fetch workflow to get projectId
  const { data: workflow } = useQuery({
    queryKey: ["workflow", workflowId],
    queryFn: async () => {
      const response = await axios.get(`/api/workflows/${workflowId}`);
      return response.data;
    },
  });
  // Fetch available templates for this project
  const { data: templatesData } = useQuery({
    queryKey: ["project-templates", workflow?.projectId],
    queryFn: async () => {
      if (!workflow?.projectId) { return { items: [] }; }
      const response = await axios.get(`/api/projects/${workflow.projectId}/templates`);
      return response.data;
    },
    enabled: !!workflow?.projectId,
  });
  // API returns paginated response: { items: [...], nextCursor, hasMore }
  const templates = templatesData?.items ?? [];
  // Update section config when values change
  const handleUpdate = (field: string, value: any) => {
    const newConfig = {
      ...config,
      [field]: value
    };
    updateSectionMutation.mutate({
      id: section.id,
      workflowId,
      config: newConfig
    });
  };
  const handleTemplateToggle = (templateId: string) => {
    const newSelection = selectedTemplates.includes(templateId)
      ? selectedTemplates.filter(id => id !== templateId)
      : [...selectedTemplates, templateId];
    setSelectedTemplates(newSelection);
    handleUpdate("templates", newSelection);
  };
  const handleScreenTitleChange = (value: string) => {
    setScreenTitle(value);
  };
  const handleScreenTitleBlur = () => {
    handleUpdate("screenTitle", screenTitle);
  };
  const handleMarkdownChange = (value: string) => {
    setMarkdownMessage(value);
  };
  const handleMarkdownBlur = () => {
    handleUpdate("markdownMessage", markdownMessage);
  };
  return (
    <div className="p-8 max-w-4xl mx-auto space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Final Documents</CardTitle>
          <CardDescription>
            {isEasyMode
              ? "Customize the final screen your client sees when they download their documents."
              : "Configure document generation and completion message for this workflow"}
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Screen Title - Hidden in Easy Mode */}
          {!isEasyMode && (
            <div className="space-y-2">
              <Label htmlFor="screenTitle">Screen Title</Label>
              <Input
                id="screenTitle"
                value={screenTitle}
                onChange={(e) => handleScreenTitleChange(e.target.value)}
                onBlur={handleScreenTitleBlur}
                placeholder="Your Completed Documents"
              />
              <p className="text-xs text-muted-foreground">
                The heading shown to users when they reach this section
              </p>
            </div>
          )}
          {/* Message with Markdown Preview */}
          <div className="space-y-2">
            <Label>Completion Message</Label>
            {isEasyMode && <p className="text-xs text-muted-foreground -mt-1 mb-2">This text appears above the download links.</p>}
            <Tabs defaultValue="edit" className="w-full">
              <TabsList className="grid w-full grid-cols-2">
                <TabsTrigger value="edit">
                  <FileText className="w-4 h-4 mr-2" />
                  Edit
                </TabsTrigger>
                <TabsTrigger value="preview">
                  <Eye className="w-4 h-4 mr-2" />
                  Preview
                </TabsTrigger>
              </TabsList>
              <TabsContent value="edit" className="mt-2">
                <Textarea
                  value={markdownMessage}
                  onChange={(e) => handleMarkdownChange(e.target.value)}
                  onBlur={handleMarkdownBlur}
                  rows={8}
                  placeholder="# Thank You!&#10;&#10;Your documents are ready for download below."
                  className="font-mono text-sm"
                />
                {!isEasyMode && (
                  <p className="text-xs text-muted-foreground mt-2 inline-flex items-center gap-1">
                    Supports Markdown formatting
                    <Tooltip>
                      <TooltipTrigger asChild>
                        <HelpCircle className="h-3.5 w-3.5 cursor-help" />
                      </TooltipTrigger>
                      <TooltipContent>Markdown supported</TooltipContent>
                    </Tooltip>
                  </p>
                )}
              </TabsContent>
              <TabsContent value="preview" className="mt-2">
                <div className="border rounded-md p-4 min-h-[200px] prose prose-sm dark:prose-invert max-w-none bg-slate-50">
                  <div className="flex justify-center mb-4">
                    <div className="w-12 h-12 bg-green-100 rounded-full flex items-center justify-center text-green-600">
                      <CheckCircle className="w-6 h-6" />
                    </div>
                  </div>
                  <h2 className="text-center mt-0">{screenTitle}</h2>
                  <ReactMarkdown remarkPlugins={[remarkGfm]}>
                    {markdownMessage}
                  </ReactMarkdown>
                </div>
              </TabsContent>
            </Tabs>
          </div>
          {/* Template Selection */}
          <div className="space-y-2">
            <Label>Selected Documents</Label>
            {templates.length === 0 ? (
              <div className="border rounded-md p-4 text-center text-muted-foreground bg-muted/20">
                <p className="text-sm">No templates found.</p>
                <p className="text-xs mt-2">
                  Add templates in the project settings.
                </p>
              </div>
            ) : (
              <div className="border rounded-md p-4 space-y-3">
                {templates.map((template: WorkflowTemplate) => (
                  <div key={template.id} className="flex items-start space-x-3">
                    <Checkbox
                      id={`template-${template.id}`}
                      checked={selectedTemplates.includes(template.id)}
                      onCheckedChange={() => handleTemplateToggle(template.id)}
                    />
                    <div className="flex-1">
                      <label
                        htmlFor={`template-${template.id}`}
                        className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70 cursor-pointer"
                      >
                        {template.name}
                      </label>
                      {(!isEasyMode && template.description) && (
                        <p className="text-xs text-muted-foreground mt-1">
                          {template.description}
                        </p>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
            {!isEasyMode && (
              <p className="text-xs text-muted-foreground">
                Select which document templates to generate
              </p>
            )}
          </div>
          {/* Advanced Options - Hidden in Easy Mode */}
          {!isEasyMode && (
            <div className="space-y-2">
              <Label>Advanced Options</Label>
              <div className="border rounded-md p-4 text-center text-muted-foreground">
                <p className="text-sm">No advanced options available yet</p>
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { ExternalSendBlockEditor } from "@/components/blocks/ExternalSendBlockEditor";
import { ListToolsBlockEditor } from "@/components/blocks/ListToolsBlockEditor";
import { QueryBlockEditor } from "@/components/blocks/QueryBlockEditor";
import { ReadTableBlockEditor } from "@/components/blocks/ReadTableBlockEditor";
import { SendDataToTableBlockEditor } from "@/components/blocks/SendDataToTableBlockEditor";
import { ValidateBlockEditor } from "@/components/blocks/ValidateBlockEditor";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { getAvailableBlockTypes, type Mode } from "@/lib/mode";

import type { ExternalSendBlockConfig, QueryBlockConfig, ReadTableConfig, ValidateConfig, WriteBlockConfig } from "@shared/types/blocks";

import type { BlockFormData, UniversalBlock } from "../BlockEditorDialog";

interface RegularBlockFormProps {
    formData: BlockFormData;
    setFormData: (data: BlockFormData) => void;
    mode: Mode;
    block: UniversalBlock | null;
    workflowId: string;
}

// eslint-disable-next-line max-lines-per-function
export function RegularBlockForm({ formData, setFormData, mode, block, workflowId }: RegularBlockFormProps) {
    const availableBlockTypes = getAvailableBlockTypes(mode);

    if (formData.type === 'write' || formData.type === 'send_table') {
        return (
            <SendDataToTableBlockEditor
                workflowId={workflowId}
                config={formData.config as unknown as WriteBlockConfig}
                onChange={(c) => { setFormData({ ...formData, config: c as unknown as Record<string, unknown> }); }}
                phase={formData.phase}
                onPhaseChange={(p) => setFormData({ ...formData, phase: p })}
                order={Number(formData.order) || 0}
                onOrderChange={(o) => setFormData({ ...formData, order: o })}
                enabled={formData.enabled ?? true}
                onEnabledChange={(e) => setFormData({ ...formData, enabled: e })}
            />
        );
    }

    if (formData.type === 'read_table') {
        return (
            <ReadTableBlockEditor
                workflowId={workflowId}
                config={formData.config as unknown as ReadTableConfig}
                onChange={(c) => { setFormData({ ...formData, config: c as unknown as Record<string, unknown> }); }}
                phase={formData.phase}
                onPhaseChange={(p) => setFormData({ ...formData, phase: p })}
                order={Number(formData.order) || 0}
                onOrderChange={(o) => setFormData({ ...formData, order: o })}
                enabled={formData.enabled ?? true}
                onEnabledChange={(e) => setFormData({ ...formData, enabled: e })}
            />
        );
    }

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Left Column: Settings */}
            <div className="space-y-4">
                {/* Hide Block Type dropdown for data blocks (write, send_table, read_table, external_send) */}
                {!['write', 'send_table', 'read_table', 'external_send'].includes(formData.type) && (
                    <div className="space-y-3">
                        <Label>Block Type</Label>
                        <Select
                            value={formData.type}
                            onValueChange={(v) => {
                                const isRead = v === 'read_table';
                                const isWrite = v === 'write' || v === 'send_table';
                                setFormData({
                                    ...formData,
                                    type: v,
                                    config: {} as Record<string, unknown>,
                                    phase: isRead ? 'onSectionEnter' : isWrite ? 'onSectionSubmit' : 'onRunStart'
                                });
                            }} // Reset config and set default phase on type change
                            disabled={!!block} // If editing, likely shouldn't change type unless we want to allow it (risky for config)
                        >
                            <SelectTrigger><SelectValue /></SelectTrigger>
                            <SelectContent>
                                {/* Show legacy types only if editing a block of that type */}
                                {(formData.type === 'prefill' || block?.type === 'prefill') && <SelectItem value="prefill">Prefill (Deprecated)</SelectItem>}
                                {(formData.type === 'validate' || block?.type === 'validate') && <SelectItem value="validate">Validate (Deprecated)</SelectItem>}
                                {(formData.type === 'branch' || block?.type === 'branch') && <SelectItem value="branch">Branch (Deprecated)</SelectItem>}

                                {/* Supported Types */}
                                {availableBlockTypes.includes('query') && <SelectItem value="query">Read Data (Legacy)</SelectItem>}
                                {availableBlockTypes.includes('list_tools') && <SelectItem value="list_tools">List Tools</SelectItem>}
                            </SelectContent>
                        </Select>
                    </div>
                )}

                {/* Only show execution phase selector for non-data blocks */}
                {!['write', 'send_table', 'read_table', 'external_send'].includes(formData.type) && (
                    <div className="space-y-3">
                        <Label>Execution Phase</Label>
                        <Select value={formData.phase} onValueChange={(v) => setFormData({ ...formData, phase: v })}>
                            <SelectTrigger><SelectValue /></SelectTrigger>
                            <SelectContent>
                                <SelectItem value="onRunStart">On Run Start</SelectItem>
                                <SelectItem value="onSectionEnter">On Section Enter</SelectItem>
                                <SelectItem value="onSectionSubmit">On Section Submit</SelectItem>
                                <SelectItem value="onNext">On Next</SelectItem>
                                <SelectItem value="onRunComplete">On Run Complete</SelectItem>
                            </SelectContent>
                        </Select>
                        <p className="text-xs text-muted-foreground">When should this block run?</p>
                    </div>
                )}

                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <Label>Order</Label>
                        <Input
                            type="number"
                            value={formData.order}
                            onChange={(e) => { setFormData({ ...formData, order: e.target.value }); }}
                        />
                    </div>
                    <div className="space-y-2 pt-8">
                        <label className="flex items-center gap-2 cursor-pointer">
                            <input
                                type="checkbox"
                                checked={formData.enabled}
                                onChange={(e) => { setFormData({ ...formData, enabled: e.target.checked }); }}
                                className="rounded border-gray-300"
                            />
                            <span className="text-sm font-medium">Enabled</span>
                        </label>
                    </div>
                </div>
            </div>

            {/* Right Column: Editor */}
            <div className="border-l pl-6">
                <Label className="mb-2 block">Configuration</Label>

                {/* Render specific editors based on type - STRICT ROUTING */}
                {(formData.type === 'write' || formData.type === 'send_table') ? (
                    <SendDataToTableBlockEditor
                        workflowId={workflowId}
                        config={formData.config as unknown as WriteBlockConfig}
                        onChange={(c) => { setFormData({ ...formData, config: c as unknown as Record<string, unknown> }); }}
                        phase={formData.phase}
                        onPhaseChange={(p) => setFormData({ ...formData, phase: p })}
                        order={Number(formData.order) || 0}
                        onOrderChange={(o) => setFormData({ ...formData, order: o })}
                        enabled={formData.enabled ?? true}
                        onEnabledChange={(e) => setFormData({ ...formData, enabled: e })}
                    />
                ) : formData.type === 'external_send' ? (
                    <ExternalSendBlockEditor
                        workflowId={workflowId}
                        config={formData.config as unknown as ExternalSendBlockConfig}
                        onChange={(c) => { setFormData({ ...formData, config: c as unknown as Record<string, unknown> }); }}
                        phase={formData.phase}
                        onPhaseChange={(p) => setFormData({ ...formData, phase: p })}
                    />
                ) : formData.type === 'list_tools' ? (
                    <ListToolsBlockEditor workflowId={workflowId} config={formData.config} onChange={(c) => { setFormData({ ...formData, config: c }); }} mode={mode} />
                ) : formData.type === 'query' ? (
                    <QueryBlockEditor workflowId={workflowId} config={formData.config as unknown as QueryBlockConfig} onChange={(c) => { setFormData({ ...formData, config: c as unknown as Record<string, unknown> }); }} />
                ) : formData.type === 'validate' ? (
                    <ValidateBlockEditor workflowId={workflowId} config={formData.config as unknown as ValidateConfig} onChange={(c) => { setFormData({ ...formData, config: c as unknown as Record<string, unknown> }); }} mode={mode} />
                ) : (
                    <div className="space-y-2">
                        <Textarea
                            value={JSON.stringify(formData.config, null, 2)}
                            onChange={(e) => {
                                try {
                                    setFormData({ ...formData, config: JSON.parse(e.target.value) })
                                } catch (error) {
                                    // Ignore parse errors during typing
                                }
                            }}
                            className="font-mono text-xs h-[300px]"
                            placeholder="{}"
                        />
                        <p className="text-xs text-muted-foreground">JSON Configuration for {formData.type}</p>
                    </div>
                )}
            </div>
        </div>
    );
}

/**
 * BuilderTabNav - Tab navigation for workflow builder
 * Supports: Sections, Templates, Data Sources, Settings, Snapshots
 */
import {
  Layers,
  FileText,
  Database,
  Settings,
  Camera,
  ClipboardCheck,
  GitBranch,
  Sparkles,
} from "lucide-react";

import { cn } from "@/lib/utils";
export type BuilderTab = "sections" | "templates" | "data-sources" | "settings" | "snapshots" | "review" | "assignment";
interface TabConfig {
  id: BuilderTab;
  label: string;
  icon: React.ComponentType<{ className?: string }>;
}
const TABS: TabConfig[] = [
  { id: "sections", label: "Sections", icon: Layers },
  { id: "templates", label: "Templates", icon: FileText },
  { id: "data-sources", label: "Data Sources", icon: Database },
  { id: "review", label: "Review", icon: ClipboardCheck },
  { id: "snapshots", label: "Snapshots", icon: Camera },
  { id: "settings", label: "Settings", icon: Settings },
  { id: "assignment", label: "Assignment", icon: GitBranch },
];
interface BuilderTabNavProps {
  workflowId: string;
  activeTab: BuilderTab;
  onTabChange: (tab: BuilderTab) => void;
  isIntake?: boolean;
}
export function BuilderTabNav({ workflowId, activeTab, onTabChange, isIntake }: BuilderTabNavProps) {
  const visibleTabs = TABS.filter(tab => {
    if (tab.id === "assignment" && !isIntake) {return false;}
    return true;
  });
  return (
    <div className="flex items-center justify-center gap-1 border-b bg-card/50">
      {visibleTabs.map((tab) => {
        const Icon = tab.icon;
        const isActive = activeTab === tab.id;
        return (
          <button
            key={tab.id}
            onClick={() => onTabChange(tab.id)}
            className={cn(
              "flex flex-col md:flex-row items-center justify-center gap-1 md:gap-2 py-3 text-sm font-medium transition-colors relative",
              "w-[100px] md:w-auto md:px-4",
              "hover:text-foreground hover:bg-accent/50",
              isActive
                ? "text-foreground bg-background border-b-2 border-primary"
                : "text-muted-foreground"
            )}
          >
            <Icon className="w-5 h-5 md:w-4 md:h-4" />
            <span className="text-xs md:text-sm">{tab.label}</span>
          </button>
        );
      })}
    </div>
  );
}

import { ChevronRight, ChevronLeft } from "lucide-react";
import React, { useState, useRef, useEffect } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

interface ResizableBuilderLayoutProps {
  leftPanel: React.ReactNode;
  centerPanel: React.ReactNode;
  rightPanel?: React.ReactNode;
  workflowId?: string;
  // Control props for right panel
  rightPanelOpen?: boolean;
  onRightPanelToggle?: (isOpen: boolean) => void;
}

const STORAGE_KEY_PREFIX = "builder-layout-widths";
const MIN_PANEL_WIDTH = 200;
const DEFAULT_LEFT_WIDTH = 280;
const DEFAULT_RIGHT_WIDTH = 400;

export function ResizableBuilderLayout({
  leftPanel,
  centerPanel,
  rightPanel,
  workflowId,
  rightPanelOpen,
  onRightPanelToggle,
}: ResizableBuilderLayoutProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [leftWidth, setLeftWidth] = useState(DEFAULT_LEFT_WIDTH);
  const [rightWidth, setRightWidth] = useState(DEFAULT_RIGHT_WIDTH);

  // Internal state for right panel if not controlled externally
  const [internalRightCollapsed, setInternalRightCollapsed] = useState(true);

  // Derived state
  const isRightCollapsed = rightPanelOpen !== undefined ? !rightPanelOpen : internalRightCollapsed;

  const [isDraggingLeft, setIsDraggingLeft] = useState(false);
  const [isDraggingRight, setIsDraggingRight] = useState(false);

  const storageKey = workflowId
    ? `${STORAGE_KEY_PREFIX}-${workflowId}`
    : `${STORAGE_KEY_PREFIX}-global`;

  // Load saved widths from localStorage
  useEffect(() => {
    try {
      const saved = localStorage.getItem(storageKey);
      if (saved) {
        const { left, right } = JSON.parse(saved);
        if (left) {setLeftWidth(left);}
        if (right) {setRightWidth(right);}
        // We don't load collapsed state if it's controlled externally
        if (rightPanelOpen === undefined && JSON.parse(saved).rightCollapsed !== undefined) {
          setInternalRightCollapsed(JSON.parse(saved).rightCollapsed);
        }
      }
    } catch (error) {
      console.error("Failed to load layout preferences:", error);
    }
  }, [storageKey, rightPanelOpen]);

  // Save widths to localStorage
  useEffect(() => {
    try {
      localStorage.setItem(
        storageKey,
        JSON.stringify({
          left: leftWidth,
          right: rightWidth,
          rightCollapsed: isRightCollapsed,
        })
      );
    } catch (error) {
      console.error("Failed to save layout preferences:", error);
    }
  }, [leftWidth, rightWidth, isRightCollapsed, storageKey]);

  // Handle left resize
  useEffect(() => {
    if (!isDraggingLeft) {return;}

    const handleMouseMove = (e: MouseEvent) => {
      if (!containerRef.current) {return;}

      const containerRect = containerRef.current.getBoundingClientRect();
      const newWidth = e.clientX - containerRect.left;

      if (newWidth >= MIN_PANEL_WIDTH && newWidth <= containerRect.width - MIN_PANEL_WIDTH) {
        setLeftWidth(newWidth);
      }
    };

    const handleMouseUp = () => {
      setIsDraggingLeft(false);
    };

    document.addEventListener("mousemove", handleMouseMove);
    document.addEventListener("mouseup", handleMouseUp);

    return () => {
      document.removeEventListener("mousemove", handleMouseMove);
      document.removeEventListener("mouseup", handleMouseUp);
    };
  }, [isDraggingLeft]);

  // Handle right resize
  useEffect(() => {
    if (!isDraggingRight) {return;}

    const handleMouseMove = (e: MouseEvent) => {
      if (!containerRef.current) {return;}

      const containerRect = containerRef.current.getBoundingClientRect();
      const newWidth = containerRect.right - e.clientX;

      if (newWidth >= MIN_PANEL_WIDTH && newWidth <= containerRect.width - MIN_PANEL_WIDTH) {
        setRightWidth(newWidth);
      }
    };

    const handleMouseUp = () => {
      setIsDraggingRight(false);
    };

    document.addEventListener("mousemove", handleMouseMove);
    document.addEventListener("mouseup", handleMouseUp);

    return () => {
      document.removeEventListener("mousemove", handleMouseMove);
      document.removeEventListener("mouseup", handleMouseUp);
    };
  }, [isDraggingRight]);

  const handleToggleRight = () => {
    const newState = !isRightCollapsed;
    if (onRightPanelToggle) {
      onRightPanelToggle(!newState); // Toggle "Open" state
    } else {
      setInternalRightCollapsed(newState);
    }
  };

  return (
    <div ref={containerRef} className="flex h-full w-full relative overflow-hidden">
      {/* Left Panel */}
      <div
        style={{ width: `${leftWidth}px` }}
        className="flex-shrink-0 border-r bg-background overflow-hidden relative"
      >
        <div className="h-full w-full overflow-y-auto">
          {leftPanel}
        </div>
      </div>

      {/* Left Resize Handle */}
      <div
        className={cn(
          "w-1 cursor-col-resize hover:bg-blue-400 transition-colors flex-shrink-0 z-10",
          isDraggingLeft && "bg-blue-500"
        )}
        onMouseDown={() => setIsDraggingLeft(true)}
      />

      {/* Center Panel (flexible) */}
      <div className="flex-1 overflow-hidden min-w-0 bg-background relative z-0">
        {centerPanel}
      </div>

      {/* Right Panel (AI Assistant) */}
      {rightPanel && (
        <>
          {/* Right Resize Handle (only when not collapsed) */}
          {!isRightCollapsed && (
            <div
              className={cn(
                "w-1 cursor-col-resize hover:bg-purple-400 transition-colors flex-shrink-0 z-10",
                isDraggingRight && "bg-purple-500"
              )}
              onMouseDown={() => setIsDraggingRight(true)}
            />
          )}

          {/* Right Panel */}
          <div
            style={{
              width: isRightCollapsed ? "0px" : `${rightWidth}px`,
            }}
            className={cn(
              "flex-shrink-0 border-l bg-background transition-all duration-300 overflow-hidden relative",
              isRightCollapsed && "border-l-0"
            )}
          >
            <div className="h-full w-full overflow-hidden">
              {rightPanel}
            </div>
          </div>

          {/* Right Panel Toggle Button */}
          <Button
            size="sm"
            variant="ghost"
            onClick={handleToggleRight}
            className={cn(
              "absolute right-0 top-1/2 -translate-y-1/2 z-20",
              "rounded-l-md rounded-r-none border border-r-0",
              "bg-background hover:bg-accent shadow-md",
              isRightCollapsed ? "translate-x-0" : ""
            )}
            style={{
              right: isRightCollapsed ? "0" : `${rightWidth}px`,
              transition: "right 0.3s ease-in-out"
            }}
          >
            {isRightCollapsed ? (
              <ChevronLeft className="w-4 h-4" />
            ) : (
              <ChevronRight className="w-4 h-4" />
            )}
          </Button>
        </>
      )}

      {/* Drag overlay to prevent text selection */}
      {(isDraggingLeft || isDraggingRight) && (
        <div className="fixed inset-0 z-50 cursor-col-resize" />
      )}
    </div>
  );
}

/**
 * Block Card Component
 * Renders a card for Logic Blocks
 * Used in the inline page view
 */

import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { GripVertical, Code2, Database, CheckCircle, GitBranch, Trash2, ChevronDown, ChevronRight, ArrowRight, ArrowLeft } from "lucide-react";
import React from "react";

import { JSBlockEditor, type JSBlock } from "@/components/blocks/JSBlockEditor";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { useToast } from "@/hooks/use-toast";
import type { PageItem } from "@/lib/dnd";
import { cn } from "@/lib/utils";
import { type ApiBlock } from '@/lib/vault-api';
import { useDeleteBlock, useDeleteTransformBlock, useUpdateTransformBlock } from "@/lib/vault-hooks";
import { useWorkflowBuilder } from "@/store/workflow-builder";

// Narrowed prop type
interface BlockCardProps {
  item: Extract<PageItem, { kind: 'block' }>;
  workflowId: string;
  sectionId: string;
  isExpanded?: boolean;
  onToggleExpand?: () => void;
  onEnterNext?: () => void;
  onEdit?: () => void;
}

const BLOCK_TYPE_ICONS: Record<string, typeof Code2> = {
  prefill: Database,
  validate: CheckCircle,
  branch: GitBranch,
  js: Code2,
  read_table: ArrowRight,
  write: ArrowLeft,
  send_table: ArrowLeft,
};

const BLOCK_TYPE_LABELS: Record<string, string> = {
  prefill: "Prefill Data",
  validate: "Validate",
  branch: "Branch",
  js: "JS Transform",
  write: "Send Data to Table",
  send_table: "Send Data to Table",
  read_table: "Read from Table",
  external_send: "Send Data to API",
  list_tools: "List Tool",
};

// Helper to generate block summaries
function getBlockSummary(block: ApiBlock): string | null {
  try {
    const type = block.type as string; // Allow legacy types like send_table
    const config = block.config || {};

    if (type === 'write' || type === 'send_table') {
      const mode = config.mode === 'create' ? 'Insert' : config.mode === 'update' ? 'Update' : 'Upsert';
      const mappingCount = Array.isArray(config.columnMappings) ? config.columnMappings.length : 0;
      if (!mappingCount) { return null; }
      return `${mode} ${mappingCount} field${mappingCount === 1 ? '' : 's'}`;
    }

    if (type === 'read_table') {
      const columnCount = Array.isArray(config.columns) ? config.columns.length : undefined;
      const totalCount = typeof config.totalColumnCount === 'number' ? config.totalColumnCount : 0;

      if (columnCount === undefined || columnCount === null) {
        // All fields selected
        return `Retrieving all(${totalCount}) fields`;
      } else {
        // Specific fields selected
        return `Retrieving ${columnCount} field${columnCount === 1 ? '' : 's'}`;
      }
    }

    if (type === 'external_send') {
      const mappingCount = Array.isArray(config.payloadMappings) ? config.payloadMappings.length : 0;
      if (!mappingCount) { return null; }
      return `${mappingCount} field${mappingCount === 1 ? '' : 's'}`;
    }

    if (type === 'list_tools') {
      const parts: string[] = [];

      if (config.sourceListVar && config.outputListVar) {
        parts.push(`${config.sourceListVar} ΓåÆ ${config.outputListVar}`);
      }

      const filterCount = config.filters?.rules?.length || 0;
      if (filterCount > 0) {
        parts.push(`filters:${filterCount}`);
      }

      const sortCount = (config.sort as unknown[])?.length || 0;
      if (sortCount > 0) {
        parts.push(`sort:${sortCount}`);
      }

      if (config.limit !== undefined) {
        parts.push(`limit:${config.limit}`);
      }

      if (Array.isArray(config.select) && config.select.length > 0) {
        parts.push(`select:${config.select.length}`);
      }

      if (config.dedupe) {
        parts.push('dedupe');
      }

      return parts.length > 0 ? parts.join(' | ') : 'Configure list transformation';
    }
  } catch (e) {
    return null;
  }

  return null;
}

export function BlockCard({ item, workflowId, sectionId, isExpanded = false, onToggleExpand, onEnterNext, onEdit }: BlockCardProps) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } =
    useSortable({ id: item.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  };

  const { selection, selectBlock } = useWorkflowBuilder();
  const deleteBlockMutation = useDeleteBlock();
  const deleteTransformBlockMutation = useDeleteTransformBlock();
  const updateTransformBlockMutation = useUpdateTransformBlock();
  const { toast } = useToast();

  const isSelected = selection?.type === "block" && selection.id === item.id;

  // Helper to check if read/write blocks are configured
  const isReadWriteConfigured = () => {
    const { type, config } = item.data;
    const typeStr = type as string;
    if (typeStr === 'read_table') {
      return !!(config?.tableId && config?.outputKey);
    }
    if (typeStr === 'write' || typeStr === 'send_table') {
      return !!(config?.tableId && config?.mode);
    }
    return true; // Other blocks considered configured by default for this styling purpose
  };

  const typeStr = item.data.type as string;
  const isReadTableOrWrite = ['read_table', 'write', 'send_table'].includes(typeStr);
  const isNotConfigured = !isReadWriteConfigured();

  const handleClick = () => {
    selectBlock(item.id);
    // For non-JS blocks, also open the editor dialog
    if (item.data.type !== "js" && onEdit) {
      onEdit();
    }
  };

  const handleDelete = async (e: React.MouseEvent) => {
    e.stopPropagation();
    try {
      // Use different API for transform blocks (type === "js")
      if (item.data.type === "js") {
        await deleteTransformBlockMutation.mutateAsync({ id: item.id, workflowId });
      } else {
        await deleteBlockMutation.mutateAsync({ id: item.id, workflowId });
      }
      toast({
        title: "Logic block deleted",
        description: "Logic block removed from page",
      });
    } catch (error) {
      toast({
        title: "Error",
        description: "Failed to delete logic block",
        variant: "destructive",
      });
    }
  };

  const handleJSBlockChange = (updated: JSBlock) => {
    if (item.data.type === "js") {
      updateTransformBlockMutation.mutate({
        id: item.id,
        workflowId,
        name: updated.config?.name,
        code: updated.config?.code,
        inputKeys: updated.config?.inputKeys,
        outputKey: updated.config?.outputKey,
        timeoutMs: updated.config?.timeoutMs,
      });
    }
  };

  return (
    <div ref={setNodeRef} style={style}>
      <Card
        className={cn(
          "cursor-pointer hover:shadow-md transition-shadow",
          isSelected && "ring-2 ring-primary",
          isReadTableOrWrite && isNotConfigured && !isSelected && "ring-2 ring-green-500 bg-green-50/50",
          isReadTableOrWrite && isNotConfigured && isSelected && "bg-green-50/30",
          isDragging && "opacity-50"
        )}
        onClick={handleClick}
      >
        <CardContent className="p-3">
          <div className="flex items-start gap-2">
            {/* Drag Handle */}
            <button
              className="cursor-grab active:cursor-grabbing p-1 hover:bg-accent rounded"
              {...attributes}
              {...listeners}
            >
              <GripVertical className="h-4 w-4 text-muted-foreground" />
            </button>

            {/* Icon and Collapse Button (stacked vertically) */}
            <div className="flex flex-col items-center gap-1">
              <div className="mt-0.5">
                {(() => {
                  const Icon = BLOCK_TYPE_ICONS[item.data.type as string] || Code2;
                  return <Icon className="h-4 w-4 text-muted-foreground" />;
                })()}
              </div>
              {!isReadTableOrWrite && (
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-5 w-5"
                  onClick={(e) => {
                    e.stopPropagation();
                    onToggleExpand?.();
                  }}
                >
                  {isExpanded ? (
                    <ChevronDown className="h-3 w-3" />
                  ) : (
                    <ChevronRight className="h-3 w-3" />
                  )}
                </Button>
              )}
            </div>

            {/* Content */}
            <div className="flex-1 min-w-0">
              <div className="font-medium text-sm">
                {item.data.type === "js" && item.data.config?.name
                  ? item.data.config.name
                  : (BLOCK_TYPE_LABELS[item.data.type as string] || item.data.type)}
              </div>
              {/* Block summary */}
              {getBlockSummary(item.data) && (
                <div className="text-xs text-muted-foreground mt-0.5">
                  {getBlockSummary(item.data)}
                </div>
              )}
              <div className="flex items-center gap-2 mt-1">
                <Badge variant="outline" className="text-xs">
                  {item.data.type}
                </Badge>
                <Badge variant="secondary" className="text-xs">
                  {item.data.phase}
                </Badge>
                {item.data.type === "js" && item.data.config?.outputKey && (
                  <Badge variant="secondary" className="text-xs font-mono">
                    ΓåÆ {item.data.config.outputKey}
                  </Badge>
                )}
                {!item.data.enabled && (
                  <span className="text-xs text-muted-foreground">Disabled</span>
                )}
              </div>
            </div>

            {/* Delete Button */}
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8 text-muted-foreground hover:text-destructive hover:bg-destructive/10 shrink-0"
              onClick={(e) => { void handleDelete(e); }}
            >
              <Trash2 className="h-4 w-4" />
            </Button>
          </div>

          {/* Expanded Content - Block Editors */}
          {isExpanded && item.data.type === "js" && (
            <div className="mt-3 pt-3 border-t">
              <JSBlockEditor
                block={item.data as unknown as JSBlock}
                onChange={handleJSBlockChange}
                workflowId={workflowId}
              />
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

/**
 * Logic Add Menu Component
 * Dropdown menu for adding logic blocks (new data blocks + advanced)
 */
import { Code2, Database, Save, Send, Sparkles } from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useToast } from "@/hooks/use-toast";
import { UI_LABELS } from "@/lib/labels";
import { isFeatureAllowed } from "@/lib/mode";
import { useCreateBlock, useCreateTransformBlock, useWorkflowMode } from "@/lib/vault-hooks";
import { useWorkflowBuilder } from "@/store/workflow-builder";
interface LogicAddMenuProps {
  workflowId: string;
  sectionId: string;
  nextOrder: number;
}
const LOGIC_TYPES = {
  easy: [
    {
      type: "read_table" as const,
      label: "Read from Table",
      icon: Database,
      description: "Query rows from DataVault",
    },
    {
      type: "write" as const,
      label: "Send Data to Table",
      icon: Save,
      description: "Save data to a DataVault table",
    },
    {
      type: "external_send" as const,
      label: "Send Data to API",
      icon: Send,
      description: "Send payload to external API",
    },
    {
      type: "list_tools" as const,
      label: "List Tools",
      icon: Sparkles,
      description: "Filter, sort and transform lists",
    },
  ],
  advanced: [
    {
      type: "js" as const,
      label: "JS Transform",
      icon: Code2,
      description: "Custom JavaScript logic",
    },
  ],
};
export function LogicAddMenu({ workflowId, sectionId, nextOrder }: LogicAddMenuProps) {
  const createBlockMutation = useCreateBlock();
  const createTransformBlockMutation = useCreateTransformBlock();
  const { data: workflowMode } = useWorkflowMode(workflowId);
  const { toast } = useToast();
  const { selectBlock } = useWorkflowBuilder();
  const mode = workflowMode?.mode || "easy";
  const showAdvanced = isFeatureAllowed(mode, "js");
  const handleAddLogic = async (type: string) => {
    try {
      // Handle JS blocks differently
      if (type === "js") {
        const block = await createTransformBlockMutation.mutateAsync({
          workflowId,
          sectionId,
          name: "JS Transform",
          language: "javascript" as const,
          phase: "onSectionSubmit",
          code: "// Write your custom JavaScript here\n// Access variables via input.variableName\n// Return an object with your transformed data\n\nreturn {\n  // your computed values\n};",
          inputKeys: [],
          outputKey: "computed_value",
          timeoutMs: 1000,
          enabled: true,
          order: nextOrder,
        });
        selectBlock(block.id);
        toast({ title: "Logic block added", description: "JS Transform created" });
        return;
      }
      // Handle regular blocks
      let config = {};
      let phase: "onSectionEnter" | "onSectionSubmit" = "onSectionSubmit";
      const blockType = type as any;
      // New Block Defaults
      if (type === 'write') {
        config = {
          mode: 'upsert',
          dataSourceId: '',
          tableId: '',
          columnMappings: [],
          matchStrategy: undefined
        };
      } else if (type === 'read_table') {
        config = {
          dataSourceId: '',
          tableId: '',
          outputKey: 'list_data',
          filters: []
        };
        phase = 'onSectionEnter';
      } else if (type === 'external_send') {
        config = {
          destinationId: '',
          payloadMappings: []
        };
      } else if (type === 'list_tools') {
        config = {
          inputKey: '',
          operation: 'filter',
          outputKey: 'processed_list'
        };
      } else if (type === 'branch') {
        config = { conditions: [], targetSectionId: null };
      }
      const block = await createBlockMutation.mutateAsync({
        workflowId,
        sectionId,
        type: blockType,
        phase,
        config,
        enabled: true,
        order: nextOrder,
      });
      selectBlock(block.id);
      const label = [...LOGIC_TYPES.easy, ...LOGIC_TYPES.advanced].find((t) => t.type === type)?.label;
      toast({
        title: "Logic block added",
        description: `${label} created`,
      });
    } catch (error) {
      toast({
        title: "Error",
        description: "Failed to create logic block",
        variant: "destructive",
      });
    }
  };
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="outline" size="sm">
          <Code2 className="w-3 h-3 mr-1" />
          {UI_LABELS.ADD_LOGIC}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className="w-64">
        {LOGIC_TYPES.easy.map((logic) => {
          const Icon = logic.icon;
          return (
            <DropdownMenuItem
              key={logic.type}
              onClick={() => { void handleAddLogic(logic.type); }}
            >
              <div className="flex items-start gap-2">
                <Icon className="w-4 h-4 mt-0.5" />
                <div className="flex-1">
                  <div className="font-medium text-sm">{logic.label}</div>
                  <div className="text-xs text-muted-foreground">
                    {logic.description}
                  </div>
                </div>
              </div>
            </DropdownMenuItem>
          );
        })}
        {showAdvanced && (
          <>
            <DropdownMenuSeparator />
            <div className="px-2 py-1.5 text-xs font-semibold text-muted-foreground">
              Advanced
            </div>
            {LOGIC_TYPES.advanced.map((logic) => {
              const Icon = logic.icon;
              return (
                <DropdownMenuItem
                  key={logic.type}
                  onClick={() => { void handleAddLogic(logic.type); }}
                >
                  <div className="flex items-start gap-2">
                    <Icon className="w-4 h-4 mt-0.5" />
                    <div className="flex-1">
                      <div className="font-medium text-sm">{logic.label}</div>
                      <div className="text-xs text-muted-foreground">
                        {logic.description}
                      </div>
                    </div>
                  </div>
                </DropdownMenuItem>
              );
            })}
          </>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/**
 * Page Canvas Component
 * Main canvas that renders the vertical stack of page cards
 * Supports drag-and-drop for both sections and steps (including cross-section)
 */
import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  type DragEndEvent,
  type DragOverEvent,
  DragOverlay,
  pointerWithin,
  rectIntersection,
} from "@dnd-kit/core";
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { Plus } from "lucide-react";
import { useState } from "react";

import { Button } from "@/components/ui/button";
import { UI_LABELS } from "@/lib/labels";
import type { } from "@/lib/vault-api";
import { useSections, useBlocks, useReorderSections, useAllSteps, useUpdateStep, useReorderSteps, useCreateSection, useWorkflowMode, useTransformBlocks } from "@/lib/vault-hooks";

import { BlockEditorDialog, type UniversalBlock } from "../BlockEditorDialog";

import { PageCard } from "./PageCard";
interface PageCanvasProps {
  workflowId: string;
}
interface DragData {
  type: 'section' | 'step';
  id: string;
  sectionId?: string; // For steps, which section they belong to
}
export function PageCanvas({ workflowId }: PageCanvasProps) {
  const { data: pages = [] } = useSections(workflowId);
  const { data: allBlocks = [] } = useBlocks(workflowId);
  const { data: transformBlocks = [] } = useTransformBlocks(workflowId);
  const { data: modeData } = useWorkflowMode(workflowId);
  const mode = modeData?.mode || 'easy';
  const reorderSectionsMutation = useReorderSections();
  const reorderStepsMutation = useReorderSteps();
  const updateStepMutation = useUpdateStep();
  const createSectionMutation = useCreateSection();
  const [activeId, setActiveId] = useState<string | null>(null);
  const [activeDragData, setActiveDragData] = useState<DragData | null>(null);
  const [editingBlock, setEditingBlock] = useState<UniversalBlock | null>(null);
  const [isBlockEditorOpen, setIsBlockEditorOpen] = useState(false);
  const handleCreateSection = async () => {
    const order = pages?.length || 0;
    await createSectionMutation.mutateAsync({
      workflowId,
      title: `${UI_LABELS.PAGE} ${order + 1}`,
      order,
    });
  };
  const handleEditBlock = (blockId: string) => {
    // Find the block in regular blocks or transform blocks
    const regularBlock = allBlocks.find(b => b.id === blockId);
    const transformBlock = transformBlocks.find(tb => tb.id === blockId);
    if (regularBlock) {
      setEditingBlock({
        id: regularBlock.id,
        type: regularBlock.type,
        phase: regularBlock.phase,
        order: regularBlock.order,
        enabled: regularBlock.enabled,
        raw: regularBlock as unknown as Record<string, unknown>,
        source: 'regular',
        title: undefined,
        displayType: regularBlock.type,
      });
      setIsBlockEditorOpen(true);
    } else if (transformBlock) {
      setEditingBlock({
        id: transformBlock.id,
        type: 'js',
        phase: transformBlock.phase,
        order: transformBlock.order,
        enabled: transformBlock.enabled,
        raw: transformBlock as unknown as Record<string, unknown>,
        source: 'transform',
        title: transformBlock.name,
        displayType: 'js',
      });
      setIsBlockEditorOpen(true);
    }
  };
  // Fetch all steps for all sections using the proper useAllSteps hook
  // This respects React's Rules of Hooks by using useQueries internally
  const allSteps = useAllSteps(pages);
  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8, // Require 8px movement before drag starts
      },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );
  const handleDragStart = (event: any) => {
    const { active } = event;
    setActiveId(active.id);
    // Determine what type of item is being dragged
    const isSection = pages.some(p => p.id === active.id);
    if (isSection) {
      setActiveDragData({ type: 'section', id: active.id });
    } else {
      // Find which section this step belongs to
      const sectionId = Object.keys(allSteps).find(
        sId => allSteps[sId].some(step => step.id === active.id)
      );
      if (sectionId) {
        setActiveDragData({ type: 'step', id: active.id, sectionId });
      }
    }
  };
  const handleDragEnd = async (event: DragEndEvent) => {
    const { active, over } = event;
    setActiveId(null);
    setActiveDragData(null);
    if (!over || active.id === over.id) { return; }
    // Handle section reordering
    if (activeDragData?.type === 'section') {
      const oldIndex = pages.findIndex((p) => p.id === active.id);
      const newIndex = pages.findIndex((p) => p.id === over.id);
      if (oldIndex !== -1 && newIndex !== -1) {
        const reordered = arrayMove(pages, oldIndex, newIndex);
        const updates = reordered.map((page, index) => ({
          id: page.id,
          order: index,
        }));
        reorderSectionsMutation.mutate({
          workflowId,
          sections: updates,
        });
      }
      return;
    }
    // Handle step drag
    if (activeDragData?.type === 'step') {
      const sourceSectionId = activeDragData.sectionId!;
      // Determine target section (could be a section ID or a step ID)
      let targetSectionId: string | null = null;
      let targetStepId: string | null = null;
      // Check if dropped on a section
      if (pages.some(p => p.id === over.id)) {
        targetSectionId = over.id as string;
      } else {
        // Dropped on a step - find which section
        targetStepId = over.id as string;
        targetSectionId = Object.keys(allSteps).find(
          sId => allSteps[sId].some(step => step.id === targetStepId)
        ) ?? null;
      }
      if (!targetSectionId) { return; }
      const sourceSteps = [...allSteps[sourceSectionId]];
      const oldIndex = sourceSteps.findIndex(s => s.id === active.id);
      if (oldIndex === -1) { return; }
      // Same section - just reorder
      if (sourceSectionId === targetSectionId) {
        const targetSteps = [...allSteps[targetSectionId]];
        const newIndex = targetStepId
          ? targetSteps.findIndex(s => s.id === targetStepId)
          : targetSteps.length;
        if (newIndex === -1) { return; }
        const reordered = arrayMove(targetSteps, oldIndex, newIndex);
        const updates = reordered.map((step, index) => ({
          id: step.id,
          order: index,
        }));
        reorderStepsMutation.mutate({
          sectionId: targetSectionId,
          steps: updates,
        });
      } else {
        // Different section - move step and reorder both sections
        const draggedStep = sourceSteps[oldIndex];
        const targetSteps = [...allSteps[targetSectionId]];
        const newIndex = targetStepId
          ? targetSteps.findIndex(s => s.id === targetStepId)
          : targetSteps.length;
        // Update the step's section
        await updateStepMutation.mutateAsync({
          id: draggedStep.id,
          sectionId: targetSectionId,
          order: newIndex,
        });
        // Reorder remaining steps in source section
        const remainingSourceSteps = sourceSteps.filter(s => s.id !== draggedStep.id);
        const sourceUpdates = remainingSourceSteps.map((step, index) => ({
          id: step.id,
          order: index,
        }));
        if (sourceUpdates.length > 0) {
          reorderStepsMutation.mutate({
            sectionId: sourceSectionId,
            steps: sourceUpdates,
          });
        }
        // Reorder steps in target section
        const targetUpdatesWithNew = [
          ...targetSteps.slice(0, newIndex),
          draggedStep,
          ...targetSteps.slice(newIndex),
        ].map((step, index) => ({
          id: step.id,
          order: index,
        }));
        reorderStepsMutation.mutate({
          sectionId: targetSectionId,
          steps: targetUpdatesWithNew,
        });
      }
    }
  };
  if (pages.length === 0) {
    return (
      <div className="h-full flex items-center justify-center p-8">
        <div className="text-center max-w-md">
          <h3 className="text-lg font-semibold mb-2">{UI_LABELS.NO_PAGES}</h3>
          <p className="text-muted-foreground text-sm">
            Use the "{UI_LABELS.ADD_PAGE}" button in the sidebar to create your first page.
          </p>
        </div>
      </div>
    );
  }
  // Get all sortable item IDs (sections + all steps from all sections)
  const allItemIds = [
    ...pages.map(p => p.id),
    ...Object.values(allSteps).flat().map(s => s.id),
  ];
  return (
    <div className="h-full overflow-y-auto">
      <div className="max-w-4xl mx-auto p-6">
        <DndContext
          sensors={sensors}
          collisionDetection={closestCenter}
          onDragStart={handleDragStart}
          onDragEnd={handleDragEnd}
        >
          <SortableContext
            items={allItemIds}
            strategy={verticalListSortingStrategy}
          >
            <div className="space-y-6">
              {pages.map((page, index) => (
                <PageCard
                  key={page.id}
                  workflowId={workflowId}
                  page={page}
                  blocks={allBlocks}
                  allSteps={allSteps[page.id] ?? []}
                  index={index}
                  total={pages.length}
                  onEditBlock={handleEditBlock}
                />
              ))}
              {/* Add Page Button at Bottom */}
              <div className="flex justify-center pt-4 pb-8">
                <Button
                  onClick={() => { void handleCreateSection(); }} // Ensure this function is defined
                  variant="outline"
                  className="w-full max-w-sm border-dashed text-muted-foreground hover:text-foreground hover:bg-muted/50"
                >
                  <Plus className="w-4 h-4 mr-2" />
                  {UI_LABELS.ADD_PAGE}
                </Button>
              </div>
            </div>
          </SortableContext>
        </DndContext>
        {/* Block Editor Dialog */}
        <BlockEditorDialog
          workflowId={workflowId}
          block={editingBlock}
          mode={mode as any}
          isOpen={isBlockEditorOpen}
          onClose={() => {
            setIsBlockEditorOpen(false);
            setEditingBlock(null);
          }}
        />
      </div>
    </div>
  );
}

/**
 * Page Card Component
 * Displays one page (section) with its questions and logic blocks
 * Includes toolbars for adding questions and logic
 */
import { useSortable, SortableContext, verticalListSortingStrategy } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { GripVertical, Settings, Trash2, ChevronDown, ChevronRight, EyeOff, FileText } from "lucide-react";
import React, { useState, useEffect, useRef } from "react";

import { LogicIndicator, SectionLogicSheet } from "@/components/logic";
import { AutoExpandTextarea } from "@/components/ui/auto-expand-textarea";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Input } from "@/components/ui/input";
import { useToast } from "@/hooks/use-toast";
import { combinePageItems, getNextOrder } from "@/lib/dnd";
import { UI_LABELS } from "@/lib/labels";
import { cn } from "@/lib/utils";
import type { ApiSection, ApiBlock, ApiStep } from "@/lib/vault-api";
import { useTransformBlocks, useUpdateSection, useDeleteSection, useReorderBlocks, useWorkflowMode } from "@/lib/vault-hooks";
import { useWorkflowBuilder } from "@/store/workflow-builder";

import type { ConditionExpression } from "@shared/types/conditions";

import { StepCard } from "../cards/StepCard";
import { FinalDocumentsSectionEditor } from "../final/FinalDocumentsSectionEditor";

import { BlockCard } from "./BlockCard";
import { LogicAddMenu } from "./LogicAddMenu";
import { QuestionAddMenu } from "./QuestionAddMenu";
interface PageCardProps {
  workflowId: string;
  page: ApiSection;
  blocks: ApiBlock[];
  allSteps: ApiStep[];
  index?: number;
  total?: number;
  onEditBlock?: (blockId: string) => void;
}
export function PageCard({ workflowId, page, blocks, allSteps: steps, index, total, onEditBlock }: PageCardProps) {
  const { data: transformBlocks = [] } = useTransformBlocks(workflowId);
  const { data: modeData } = useWorkflowMode(workflowId);
  const mode = modeData?.mode || 'easy';
  const updateSectionMutation = useUpdateSection();
  const deleteSectionMutation = useDeleteSection();
  const reorderBlocksMutation = useReorderBlocks();
  const { selectSection, selectBlock, selectStep, selection } = useWorkflowBuilder();
  const { toast } = useToast();
  const [isDescriptionExpanded, setIsDescriptionExpanded] = useState(false);
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [expandedStepIds, setExpandedStepIds] = useState<Set<string>>(new Set());
  const [expandedBlockIds, setExpandedBlockIds] = useState<Set<string>>(new Set());
  const [autoFocusStepId, setAutoFocusStepId] = useState<string | null>(null);
  const [isLogicSheetOpen, setIsLogicSheetOpen] = useState(false);
  const prevSelectionRef = useRef<typeof selection>(null);
  const prevItemsLengthRef = useRef<number>(0);
  // Check if this is a Final Documents section
  const isFinalDocumentsSection = (page.config as Record<string, unknown> | undefined)?.finalBlock === true;
  // For Final Documents sections, filter out all steps (they shouldn't exist, but if they do, hide them)
  // The only step should be the system step of type 'final_documents' which is hidden anyway
  const filteredSteps = isFinalDocumentsSection
    ? steps.filter(s => s.type === 'final_documents')
    : steps;
  // Combine steps and blocks into sortable items
  const pageBlocks = blocks.filter((b) => b.sectionId === page.id);
  // Convert transform blocks to ApiBlock format for this section
  const pageTransformBlocks: ApiBlock[] = transformBlocks
    .filter((tb) => tb.sectionId === page.id)
    .map((tb) => ({
      id: tb.id,
      workflowId: tb.workflowId,
      sectionId: tb.sectionId ?? null,
      type: "js" as const,
      phase: tb.phase as any,
      config: {
        name: tb.name,
        language: tb.language,
        code: tb.code,
        inputKeys: tb.inputKeys,
        outputKey: tb.outputKey,
        timeoutMs: tb.timeoutMs,
      },
      enabled: tb.enabled,
      order: tb.order,
      createdAt: tb.createdAt,
      updatedAt: tb.updatedAt,
    }));
  // Combine regular blocks and transform blocks
  const allPageBlocks = [...pageBlocks, ...pageTransformBlocks];
  const items = combinePageItems(filteredSteps, allPageBlocks);
  // Auto-expand and focus newly selected items
  // We track a "pending" focus ID to handle the race condition where selection updates
  // before the new step data has propagated to the props.
  const [pendingFocusId, setPendingFocusId] = useState<string | null>(null);

  useEffect(() => {
    // If we have a selected step
    if (selection?.type === "step" && selection.id) {
      // Check if it's a new selection
      const isNewSelection = prevSelectionRef.current?.id !== selection.id;

      // If it's a new selection, we validly want to try to focus it
      if (isNewSelection) {
        setPendingFocusId(selection.id);
      }
    }
    prevSelectionRef.current = selection;
  }, [selection]);

  // Effect to apply focus once the step is available
  useEffect(() => {
    if (pendingFocusId) {
      const stepInThisPage = steps.find((s) => s.id === pendingFocusId);

      if (stepInThisPage) {
        // Step is now available!
        setExpandedStepIds((prev) => new Set(prev).add(pendingFocusId));
        setAutoFocusStepId(pendingFocusId);
        setPendingFocusId(null);

        // Clear auto-focus after a short delay to allow animation
        setTimeout(() => setAutoFocusStepId(null), 100);
      }
    }
  }, [pendingFocusId, steps]);
  // Auto-expand newly created items
  useEffect(() => {
    if (items.length > prevItemsLengthRef.current && prevItemsLengthRef.current > 0) {
      // A new item was just added, find it and expand it
      const newItem = items[items.length - 1];
      if (newItem) {
        if (newItem.kind === "step") {
          setExpandedStepIds((prev) => new Set(prev).add(newItem.id));
          setAutoFocusStepId(newItem.id);
          setTimeout(() => setAutoFocusStepId(null), 100);
        } else {
          setExpandedBlockIds((prev) => new Set(prev).add(newItem.id));
        }
      }
    }
    prevItemsLengthRef.current = items.length;
  }, [items]);
  // Make the page card sortable for page reordering
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: page.id });
  // Immediate update with optimistic rendering
  const handleTitleChange = (title: string) => {
    updateSectionMutation.mutate({ id: page.id, workflowId, title });
  };
  // Immediate update with optimistic rendering
  const handleDescriptionChange = (description: string) => {
    updateSectionMutation.mutate({ id: page.id, workflowId, description });
  };
  const handleDelete = async () => {
    if (!confirm(`Delete page "${page.title}"? This will remove all questions and logic blocks.`)) {
      return;
    }
    try {
      await deleteSectionMutation.mutateAsync({ id: page.id, workflowId });
      toast({
        title: "Page deleted",
        description: `"${page.title}" has been removed`,
      });
    } catch (error) {
      toast({
        title: "Error",
        description: "Failed to delete page",
        variant: "destructive",
      });
    }
  };
  const nextOrder = getNextOrder(items);
  const handleToggleExpand = (stepId: string) => {
    setExpandedStepIds((prev) => {
      const next = new Set(prev);
      if (next.has(stepId)) {
        next.delete(stepId);
      } else {
        next.add(stepId);
      }
      return next;
    });
  };
  const handleToggleBlockExpand = (blockId: string) => {
    setExpandedBlockIds((prev) => {
      const next = new Set(prev);
      if (next.has(blockId)) {
        next.delete(blockId);
      } else {
        next.add(blockId);
      }
      return next;
    });
  };
  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  };
  return (
    <div ref={setNodeRef} style={style}>
      <Card className={cn("shadow-sm", isDragging && "opacity-50")}>
        <CardHeader className="pb-3">
          <div className="flex items-start gap-2">
            {/* Drag handle for page reordering */}
            <button
              className="cursor-grab active:cursor-grabbing p-1 hover:bg-accent rounded"
              {...attributes}
              {...listeners}
            >
              <GripVertical className="h-4 w-4 text-muted-foreground" />
            </button>
            {/* Collapse/Expand button */}
            <Button
              variant="ghost"
              size="icon"
              className="h-6 w-6 mt-1"
              onClick={(e) => {
                e.stopPropagation();
                setIsCollapsed(!isCollapsed);
              }}
            >
              {isCollapsed ? (
                <ChevronRight className="h-4 w-4" />
              ) : (
                <ChevronDown className="h-4 w-4" />
              )}
            </Button>
            {/* Page title and description */}
            <div className="flex-1 space-y-1">
              {mode === 'easy' && typeof index === 'number' && typeof total === 'number' && !isFinalDocumentsSection && (
                <div className="text-[10px] font-bold text-muted-foreground/70 uppercase tracking-widest pl-1 select-none">
                  Page {index + 1} of {total}
                </div>
              )}
              <div className="flex items-center gap-2">
                <Input
                  value={page.title}
                  onChange={(e) => { void handleTitleChange(e.target.value); }}
                  className="font-semibold text-base border-none shadow-none px-0 focus-visible:ring-0 flex-1"
                  placeholder="Page title"
                />
                {isFinalDocumentsSection && (
                  <Badge variant="secondary" className="text-xs px-2 py-1">
                    <FileText className="h-3 w-3 mr-1" />
                    Final Documents Block
                  </Badge>
                )}
                <LogicIndicator
                  visibleIf={page.visibleIf as ConditionExpression | undefined}
                  variant="badge"
                  size="sm"
                  elementType="page"
                />
              </div>
              <AutoExpandTextarea
                value={page.description ?? ""}
                onChange={(e) => { void handleDescriptionChange(e.target.value); }}
                className="text-sm text-muted-foreground border-none shadow-none px-0 focus-visible:ring-0 min-h-0"
                placeholder="Page description (optional)"
                minRows={1}
                maxRows={4}
              />
            </div>
            {/* Page actions */}
            <div className="flex items-center gap-1">
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="ghost" size="icon" title="Page settings">
                    <Settings className="h-4 w-4" />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end">
                  <DropdownMenuItem onClick={() => { void selectSection(page.id); }}>
                    <Settings className="h-4 w-4 mr-2" />
                    Page Settings
                  </DropdownMenuItem>
                  <DropdownMenuItem onClick={() => { void setIsLogicSheetOpen(true); }}>
                    <EyeOff className="h-4 w-4 mr-2" />
                    Visibility Logic
                    {!!page.visibleIf && (
                      <span className="ml-auto text-xs text-amber-600">Active</span>
                    )}
                  </DropdownMenuItem>
                  <DropdownMenuSeparator />
                  <DropdownMenuItem
                    onClick={() => { void handleDelete(); }}
                    className="text-destructive focus:text-destructive"
                  >
                    <Trash2 className="h-4 w-4 mr-2" />
                    Delete Page
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          </div>
        </CardHeader>
        {!isCollapsed && (
          <CardContent className="pt-0 space-y-3">
            {isFinalDocumentsSection ? (
              <FinalDocumentsSectionEditor section={page} workflowId={workflowId} />
            ) : items.length === 0 ? (
              <div className="py-8 text-center text-sm text-muted-foreground flex flex-col items-center gap-2">
                {mode === 'easy' ? (
                  <>
                    <div className="p-3 bg-amber-50 rounded-full mb-2">
                      <FileText className="w-6 h-6 text-amber-500" />
                    </div>
                    <p className="font-medium text-amber-900">Add your first question to this page</p>
                    <p className="text-xs text-amber-700 max-w-xs">
                      Start by asking something simple. You can always add more pages later.
                    </p>
                  </>
                ) : (
                  UI_LABELS.NO_QUESTIONS
                )}
              </div>
            ) : (
              <SortableContext
                items={items.map((i) => i.id)}
                strategy={verticalListSortingStrategy}
              >
                <div className="space-y-2">
                  {items.map((item, index) => {
                    const handleEnterNext = () => {
                      // Find next item in list
                      if (index < items.length - 1) {
                        const nextItem = items[index + 1];
                        if (nextItem.kind === "step") {
                          // Select and expand next step
                          selectStep(nextItem.id);
                          setExpandedStepIds((prev) => new Set(prev).add(nextItem.id));
                          setAutoFocusStepId(nextItem.id);
                        } else {
                          // Just select next block
                          selectBlock(nextItem.id);
                        }
                      }
                    };
                    if (item.kind === "step") {
                      return (
                        <StepCard
                          key={item.id}
                          step={item.data}
                          sectionId={page.id}
                          workflowId={workflowId}
                          isExpanded={expandedStepIds.has(item.id)}
                          autoFocus={autoFocusStepId === item.id}
                          onToggleExpand={() => handleToggleExpand(item.id)}
                          onEnterNext={handleEnterNext}
                        />
                      );
                    } else {
                      return (
                        <BlockCard
                          key={item.id}
                          item={item}
                          workflowId={workflowId}
                          sectionId={page.id}
                          isExpanded={expandedBlockIds.has(item.id)}
                          onToggleExpand={() => handleToggleBlockExpand(item.id)}
                          onEnterNext={handleEnterNext}
                          onEdit={() => onEditBlock?.(item.id)}
                        />
                      );
                    }
                  })}
                </div>
              </SortableContext>
            )}
            {/* Add buttons at the bottom - hidden for Final Documents sections */}
            {!isFinalDocumentsSection && (
              <div className="space-y-2">
                {mode === 'easy' && items.length > 0 && (
                  <div className="flex items-center gap-2 px-1 pb-1 animate-in fade-in slide-in-from-top-1">
                    <span className="text-[10px] text-muted-foreground italic">
                      You can add another question here, or create a new page below.
                    </span>
                  </div>
                )}
                <div className="flex items-center gap-2 pt-2">
                  <QuestionAddMenu
                    sectionId={page.id}
                    nextOrder={nextOrder}
                    workflowId={workflowId}
                  />
                  <LogicAddMenu
                    workflowId={workflowId}
                    sectionId={page.id}
                    nextOrder={nextOrder}
                  />
                </div>
              </div>
            )}
          </CardContent>
        )}
      </Card>
      {/* Section Logic Sheet */}
      <SectionLogicSheet
        open={isLogicSheetOpen}
        onOpenChange={setIsLogicSheetOpen}
        section={page}
        workflowId={workflowId}
      />
    </div>
  );
}

/**
 * Question Add Menu Component
 * Dropdown menu for adding different question types to a page
 *
 * Uses the centralized Block Registry for block types and mode filtering
 *
 * @version 2.0.0 - Block System Overhaul
 */

import { Plus } from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useToast } from "@/hooks/use-toast";
import {
  getBlocksByCategory,
  CATEGORY_LABELS,
  CATEGORY_ORDER,
  type BlockRegistryEntry,
} from "@/lib/blockRegistry";
import { useCreateStep, useWorkflowMode } from "@/lib/vault-hooks";
import { useWorkflowBuilder } from "@/store/workflow-builder";

interface QuestionAddMenuProps {
  sectionId: string;
  nextOrder: number;
  workflowId: string;
}

export function QuestionAddMenu({ sectionId, nextOrder, workflowId }: QuestionAddMenuProps) {
  const createStepMutation = useCreateStep();
  const { toast } = useToast();
  const { selectStep } = useWorkflowBuilder();
  const { data: workflowMode } = useWorkflowMode(workflowId);

  const mode = workflowMode?.mode || "easy";

  const handleAddQuestion = async (block: BlockRegistryEntry) => {
    try {
      // Generate default config
      const config = block.createDefaultConfig();

      // Create the step
      const step = await createStepMutation.mutateAsync({
        sectionId,
        type: block.type as any, // Cast to any to avoid strict StepType mismatch until registry is fully typed
        title: `New ${block.label}`,
        description: null,
        required: false,
        alias: null,
        options: config ?? null,
        config: config || {},
        order: nextOrder,
      });

      // Select the newly created step
      selectStep(step.id);

      toast({
        title: "Question added",
        description: `${block.label} question created`,
      });
    } catch (error) {
      console.error("Failed to create question:", error);
      toast({
        title: "Error",
        description: "Failed to create question",
        variant: "destructive",
      });
    }
  };

  // Get blocks grouped by category for the current mode
  const blocksByCategory = getBlocksByCategory(mode);

  // Filter out empty categories and sort by defined order
  const orderedCategories = CATEGORY_ORDER.filter(
    (category) => blocksByCategory[category]?.length > 0
  );

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="outline" size="sm">
          <Plus className="w-3 h-3 mr-1" />
          Add Question
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className="w-64 max-h-[600px] overflow-y-auto">
        {orderedCategories.map((category, categoryIndex) => (
          <div key={category}>
            {categoryIndex > 0 && <DropdownMenuSeparator />}
            <DropdownMenuLabel className="text-xs text-muted-foreground">
              {CATEGORY_LABELS[category]}
            </DropdownMenuLabel>
            {blocksByCategory[category].map((block) => {
              const Icon = block.icon;
              return (
                <DropdownMenuItem
                  key={block.type}
                  onClick={() => { void handleAddQuestion(block); }}
                  className="cursor-pointer"
                >
                  <Icon className="mr-2 h-4 w-4 text-muted-foreground" />
                  <div className="flex flex-col">
                    <span>{block.label}</span>
                    {block.description && (
                      <span className="text-xs text-muted-foreground">
                        {block.description}
                      </span>
                    )}
                  </div>
                </DropdownMenuItem>
              );
            })}
          </div>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/**
 * Variable Palette Component
 * Lists available variables/aliases with insert and copy helpers
 */

import { Copy, ChevronRight } from "lucide-react";
import { useMemo } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { useToast } from "@/hooks/use-toast";
import { useWorkflowVariables } from "@/lib/vault-hooks";

interface VariablePaletteProps {
  workflowId: string;
  onInsert: (key: string) => void;
}

export function VariablePalette({ workflowId, onInsert }: VariablePaletteProps) {
  const { data: variables = [] } = useWorkflowVariables(workflowId);
  const { toast } = useToast();

  // Group variables by section/page
  const grouped = useMemo(() => {
    const groups = new Map<string, typeof variables>();

    variables.forEach((variable) => {
      const sectionTitle = variable.sectionTitle || "Other";
      if (!groups.has(sectionTitle)) {
        groups.set(sectionTitle, []);
      }
      groups.get(sectionTitle)!.push(variable);
    });

    return Array.from(groups.entries());
  }, [variables]);

  const handleCopy = (key: string) => {
    navigator.clipboard.writeText(key);
    toast({
      title: "Copied",
      description: `Variable key "${key}" copied to clipboard`,
    });
  };

  if (variables.length === 0) {
    return (
      <div className="p-4 text-center text-sm text-muted-foreground">
        No variables available yet. Add questions to your pages to create variables.
      </div>
    );
  }

  return (
    <ScrollArea className="h-full">
      <div className="p-4 space-y-4">
        <div className="space-y-1">
          <h3 className="text-sm font-semibold">Variables</h3>
          <p className="text-xs text-muted-foreground">
            Click to insert variable keys into your code
          </p>
        </div>

        {grouped.map(([sectionTitle, vars]) => (
          <div key={sectionTitle} className="space-y-2">
            <h4 className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
              {sectionTitle}
            </h4>
            <div className="space-y-1">
              {vars.map((variable) => (
                <div
                  key={variable.key}
                  className="flex items-center gap-2 p-2 rounded-md hover:bg-accent group"
                >
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-0.5">
                      <span className="font-medium text-sm truncate">
                        {variable.alias || variable.key}
                      </span>
                      {variable.type && (
                        <Badge variant="outline" className="text-[10px] h-4 px-1 py-0 uppercase">
                          {variable.type.replace('_', ' ')}
                        </Badge>
                      )}
                    </div>
                    {variable.alias && (
                      <div className="font-mono text-xs text-muted-foreground truncate">
                        {variable.key}
                      </div>
                    )}
                    {variable.label && (
                      <div className="text-xs text-muted-foreground truncate">
                        {variable.label}
                      </div>
                    )}
                  </div>

                  <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-6 w-6"
                      onClick={() => { void handleCopy(variable.key); }}
                      title="Copy key"
                    >
                      <Copy className="h-3 w-3" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-6 w-6"
                      onClick={() => { void onInsert(variable.key); }}
                      title="Insert key"
                    >
                      <ChevronRight className="h-3 w-3" />
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </ScrollArea>
  );
}

/**
 * JS Question Editor Component
 * Editor for JavaScript question configuration
 * Handles code, input/output mapping, display mode, and timeout settings
 */

import { ChevronDown, ChevronUp } from "lucide-react";
import { useState, useEffect, useRef } from "react";

import { HelperLibraryDocs } from "@/components/builder/HelperLibraryDocs";
import { EnhancedVariablePicker } from "@/components/common/EnhancedVariablePicker";
import { Button } from "@/components/ui/button";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";

export interface JSQuestionConfig {
  display: "visible" | "hidden";
  code: string;
  inputKeys: string[];
  outputKey: string;
  timeoutMs?: number;
  helpText?: string;
}

interface JSQuestionEditorProps {
  config: JSQuestionConfig;
  onChange: (config: JSQuestionConfig) => void;
  className?: string;
  elementId: string;
  workflowId?: string; // For variable picker
}

export function JSQuestionEditor({ config, onChange, className, elementId, workflowId }: JSQuestionEditorProps) {
  const [localConfig, setLocalConfig] = useState<JSQuestionConfig>(config);
  const [showVariables, setShowVariables] = useState(false);
  const codeTextareaRef = useRef<HTMLTextAreaElement>(null);

  // Sync with external changes
  useEffect(() => {
    setLocalConfig(config);
  }, [config]);

  const handleChange = (updates: Partial<JSQuestionConfig>) => {
    const newConfig = { ...localConfig, ...updates };
    setLocalConfig(newConfig);
  };

  const handleBlur = () => {
    onChange(localConfig);
  };

  const handleInputKeysChange = (value: string) => {
    const keys = value.split(',').map(k => k.trim()).filter(k => k.length > 0);
    handleChange({ inputKeys: keys });
  };

  // Insert variable path into code editor at cursor position
  const handleInsertVariable = (path: string) => {
    if (!codeTextareaRef.current) {return;}

    const textarea = codeTextareaRef.current;
    const start = textarea.selectionStart;
    const end = textarea.selectionEnd;
    const currentCode = localConfig.code;

    // Insert the variable path with "input." prefix
    const insertText = `input.${path}`;
    const newCode = currentCode.substring(0, start) + insertText + currentCode.substring(end);

    handleChange({ code: newCode });

    // Set cursor position after inserted text
    setTimeout(() => {
      textarea.focus();
      const newPosition = start + insertText.length;
      textarea.setSelectionRange(newPosition, newPosition);
    }, 0);
  };

  return (
    <div className={cn("space-y-3", className)}>
      <div className="text-sm font-medium text-muted-foreground border-b pb-1">
        JavaScript Configuration
      </div>

      {/* Display Mode */}
      <div className="space-y-1.5">
        <Label htmlFor={`frame-js-display-${elementId}`} className="text-xs text-muted-foreground">
          Display Mode
        </Label>
        <Select
          value={localConfig.display}
          onValueChange={(value) => {
            const newDisplay = value as "visible" | "hidden";
            handleChange({ display: newDisplay });
            handleBlur();
          }}
        >
          <SelectTrigger id={`frame-js-display-${elementId}`} className="h-9 text-sm">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="hidden">Hidden (compute only)</SelectItem>
            <SelectItem value="visible">Visible (interactive)</SelectItem>
          </SelectContent>
        </Select>
        <p className="text-xs text-muted-foreground pl-1">
          {localConfig.display === "hidden"
            ? "Runs as background computation, no UI shown"
            : "Shows help text in runner, but still computes automatically"}
        </p>
      </div>

      {/* Output Key */}
      <div className="space-y-1.5">
        <Label htmlFor={`frame-js-output-${elementId}`} className="text-xs text-muted-foreground">
          Output Variable
        </Label>
        <Input
          id={`frame-js-output-${elementId}`}
          value={localConfig.outputKey}
          onChange={(e) => handleChange({ outputKey: e.target.value })}
          onBlur={handleBlur}
          placeholder="e.g., computed_value, full_name"
          className="h-9 text-sm font-mono"
        />
        <p className="text-xs text-muted-foreground pl-1">
          Where to store the computed result
        </p>
      </div>

      {/* Input Keys */}
      <div className="space-y-1.5">
        <Label htmlFor={`frame-js-inputs-${elementId}`} className="text-xs text-muted-foreground">
          Input Variables (comma-separated)
        </Label>
        <Input
          id={`frame-js-inputs-${elementId}`}
          value={localConfig.inputKeys.join(', ')}
          onChange={(e) => handleInputKeysChange(e.target.value)}
          onBlur={handleBlur}
          placeholder="e.g., first_name, last_name, age"
          className="h-9 text-sm font-mono"
        />
        <p className="text-xs text-muted-foreground pl-1">
          Variables from other questions to use as inputs
        </p>
      </div>

      {/* Code Editor */}
      <div className="space-y-1.5">
        <Label htmlFor={`frame-js-code-${elementId}`} className="text-xs text-muted-foreground">
          JavaScript Code
        </Label>
        <Textarea
          ref={codeTextareaRef}
          id={`frame-js-code-${elementId}`}
          value={localConfig.code}
          onChange={(e) => handleChange({ code: e.target.value })}
          onBlur={handleBlur}
          placeholder="return input.first_name + ' ' + input.last_name;"
          rows={6}
          className="text-sm font-mono resize-none"
        />
        <p className="text-xs text-muted-foreground pl-1">
          Function body. Use <code className="font-mono">input</code> to access input variables. Return the result.
        </p>
      </div>

      {/* Variable Picker (if workflowId provided) */}
      {workflowId && (
        <Collapsible open={showVariables} onOpenChange={setShowVariables}>
          <CollapsibleTrigger asChild>
            <Button
              variant="outline"
              size="sm"
              className="w-full justify-between text-xs"
            >
              <span>Available Variables</span>
              {showVariables ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
            </Button>
          </CollapsibleTrigger>
          <CollapsibleContent className="mt-2">
            <div className="border rounded-md max-h-64 overflow-hidden">
              <EnhancedVariablePicker
                workflowId={workflowId}
                onInsert={handleInsertVariable}
                showListProperties={true}
              />
            </div>
            <p className="text-xs text-muted-foreground mt-1 pl-1">
              Click any variable to insert it into your code at the cursor position.
            </p>
          </CollapsibleContent>
        </Collapsible>
      )}

      {/* Helper Library Documentation */}
      <HelperLibraryDocs />

      {/* Timeout */}
      <div className="space-y-1.5">
        <Label htmlFor={`frame-js-timeout-${elementId}`} className="text-xs text-muted-foreground">
          Timeout (ms)
        </Label>
        <Input
          id={`frame-js-timeout-${elementId}`}
          type="number"
          value={localConfig.timeoutMs || 1000}
          onChange={(e) => handleChange({ timeoutMs: parseInt(e.target.value) || 1000 })}
          onBlur={handleBlur}
          min={100}
          max={3000}
          className="h-9 text-sm"
        />
        <p className="text-xs text-muted-foreground pl-1">
          Execution timeout (100-3000ms)
        </p>
      </div>

      {/* Help Text (shown when display = visible) */}
      {localConfig.display === "visible" && (
        <div className="space-y-1.5">
          <Label htmlFor={`frame-js-help-${elementId}`} className="text-xs text-muted-foreground">
            Help Text (optional)
          </Label>
          <Textarea
            id={`frame-js-help-${elementId}`}
            value={localConfig.helpText ?? ""}
            onChange={(e) => handleChange({ helpText: e.target.value })}
            onBlur={handleBlur}
            placeholder="Optional text to show in the runner..."
            rows={2}
            className="text-sm resize-none"
          />
        </div>
      )}
    </div>
  );
}

import {
    HelpCircle,
    Database,
    Link as LinkIcon,
    EyeOff,
    ChevronDown,
