import { cn } from "@/lib/utils";
import type { ApiStep, StepType } from "@/lib/vault-api";
import {
    useUpdateStep,
    useWorkflow,
    useWorkflowMode
} from "@/lib/vault-hooks";

import type { ConditionExpression } from "@shared/types/conditions";

import { useIntake } from "../IntakeContext";

import { JSQuestionEditor, type JSQuestionConfig } from "./JSQuestionEditor";
import { OptionsEditor, type OptionItemData } from "./OptionsEditor";

interface LegacyStepBodyProps {
    step: ApiStep;
    sectionId: string;
    workflowId: string;
}

export function LegacyStepBody({ step, sectionId, workflowId }: LegacyStepBodyProps) {
    const updateStepMutation = useUpdateStep();
    const { toast } = useToast();
    const { data: modeData } = useWorkflowMode(workflowId);
    const mode = modeData?.mode || 'easy';
    const { data: workflow } = useWorkflow(workflowId);
    const { upstreamWorkflow, upstreamVariables, upstreamWorkflowId } = useIntake();

    // Intake Derived Values
    const isLinkedToIntake = !!step.defaultValue && typeof step.defaultValue === 'object' && (step.defaultValue as { source?: string }).source === 'intake';

    // Local State
    const [localRequired, setLocalRequired] = useState(step.required ?? false);
    const [localType, setLocalType] = useState<StepType>(step.type);
    const [isVisibilityOpen, setIsVisibilityOpen] = useState(false);
    const [activeTab, setActiveTab] = useState(isLinkedToIntake ? "intake" : "static");

    const [localOptions, setLocalOptions] = useState<OptionItemData[]>(() => {
        if (step.type === "radio" || step.type === "multiple_choice") {
            const opts = step.options?.options ?? [];
            return opts.map((opt: any, idx: number) => {
                if (typeof opt === 'string') {
                    return {
                        id: `opt-${Date.now()}-${idx}`,
                        label: opt,
                        alias: opt.toLowerCase().replace(/\s+/g, '_')
                    };
                }
                return opt;
            });
        }
        return [];
    });

    const [localJsConfig, setLocalJsConfig] = useState<JSQuestionConfig>(
        step.type === "js_question" && step.options
            ? (step.options as JSQuestionConfig)
            : {
                display: "hidden",
                code: "return input;",
                inputKeys: [],
                outputKey: "computed_value",
                timeoutMs: 1000,
                helpText: "",
            }
    );

    // Sync state when step prop changes
    useEffect(() => {
        setLocalRequired(step.required ?? false);
        setLocalType(step.type);
        if (step.type === "radio" || step.type === "multiple_choice") {
            const opts = step.options?.options ?? [];
            setLocalOptions(opts.map((opt: any, idx: number) => {
                if (typeof opt === 'string') {
                    return {
                        id: `opt-${Date.now()}-${idx}`,
                        label: opt,
                        alias: opt.toLowerCase().replace(/\s+/g, '_')
                    };
                }
                return opt;
            }));
        }

        // Sync activeTab if we become linked
        if (isLinkedToIntake) {
            setActiveTab("intake");
        }
    }, [step, isLinkedToIntake]);

    // Handlers
    const handleTabChange = (val: string) => {
        setActiveTab(val);
        // Requirement: "Only clear intake link when switching from intakeΓåÆstatic, and only if currently linked"
        if (val === 'static' && isLinkedToIntake) {
            handleIntakeLinkChange("none");
        }
    };

    const handleAliasChange = (value: string) => {
        updateStepMutation.mutate(
            { id: step.id, sectionId, alias: value.trim() ?? null },
            {
                onError: (error: any) => {
                    toast({
                        title: "Error",
                        description: error?.message || "Failed to update variable name",
                        variant: "destructive",
                    });
                },
            }
        );
    };

    const handleRequiredChange = (required: boolean) => {
        setLocalRequired(required);
        updateStepMutation.mutate({ id: step.id, sectionId, required });
    };

    const handleDescriptionChange = (value: string) => {
        updateStepMutation.mutate({ id: step.id, sectionId, description: value });
    };

    const handleDefaultValueChange = (value: string) => {
        let parsedValue: string | boolean | number | null = value;

        if (step.type === 'yes_no') {
            parsedValue = value === 'yes' ? true : value === 'no' ? false : null;
        } else if (value === '') {
            parsedValue = null;
        }

        updateStepMutation.mutate({
            id: step.id,
            sectionId,
            defaultValue: parsedValue
        });
    };

    const handleIntakeLinkChange = (variableAlias: string) => {
        updateStepMutation.mutate({
            id: step.id,
            sectionId,
            defaultValue: variableAlias === 'none' ? null : { source: 'intake', variable: variableAlias }
        });
    };

    const handleOptionsChange = (options: OptionItemData[] | import("@/../../shared/types/stepConfigs").DynamicOptionsConfig) => {
        if (Array.isArray(options)) {
            setLocalOptions(options);
            updateStepMutation.mutate({
                id: step.id,
                sectionId,
                options: { options },
            });
        } else {
            if (options.type === 'static') {
                setLocalOptions(options.options);
                updateStepMutation.mutate({
                    id: step.id,
                    sectionId,
                    options: { options: options.options },
                });
            } else {
                console.warn('[QuestionCard] Dynamic options not supported for legacy radio/multiple_choice types');
            }
        }
    };

    const handleJsConfigChange = (config: JSQuestionConfig) => {
        setLocalJsConfig(config);
        updateStepMutation.mutate({
            id: step.id,
            sectionId,
            options: config,
        });
    };

    const handleVisibilityChange = (expression: ConditionExpression) => {
        updateStepMutation.mutate(
            {
                id: step.id,
                sectionId,
                visibleIf: expression,
            },
            {
                onSuccess: () => {
                    toast({
                        title: "Visibility updated",
                        description: "Question visibility conditions have been saved.",
                    });
                },
                onError: (error) => {
                    toast({
                        title: "Error",
                        description:
                            error instanceof Error
                                ? error.message
                                : "Failed to save visibility conditions",
                        variant: "destructive",
                    });
                },
            }
        );
    };

    // Determine displayed values for static inputs
    const staticInputValue = (step.defaultValue === null || step.defaultValue === undefined || typeof step.defaultValue === 'object')
        ? ""
        : String(step.defaultValue);

    const staticSelectValue = (step.defaultValue === null || step.defaultValue === undefined || typeof step.defaultValue === 'object')
        ? "none"
        : step.defaultValue === true ? "yes" : "no";

    return (
        <div className="space-y-3 pt-1 border-t">
            {/* Alias / Save Answer As */}
            {step.type !== "display" && (
                <div className={cn(
                    "space-y-1.5 p-2 rounded-md transition-colors",
                    mode === 'easy' && !step.alias && "bg-amber-50/50 border border-amber-200/50"
                )}>
                    <div className="flex items-center justify-between">
                        <Label htmlFor={`alias-${step.id}`} className="text-xs font-medium text-foreground">
                            {mode === 'easy' ? "Save answer as" : "Variable (alias)"}
                        </Label>
                        {mode === 'advanced' && (
                            <span className="text-xs text-muted-foreground">
                                Internal key: <code className="font-mono text-[10px]">{step.id.slice(0, 8)}...</code>
                            </span>
                        )}
                    </div>
                    <Input
                        id={`alias-${step.id}`}
                        name={`alias-${step.id}`}
                        value={step.alias ?? ""}
                        onChange={(e) => { void handleAliasChange(e.target.value); }}
                        placeholder={mode === 'easy' ? "e.g. clientName or client.name" : "e.g., user_email, phone_number"}
                        className={cn(
                            "h-9 text-sm font-mono",
                            mode === 'easy' && !step.alias && "border-amber-300 focus-visible:ring-amber-400"
                        )}
                    />
                    {mode === 'easy' && (
                        <div className="animate-in fade-in slide-in-from-top-1 space-y-1">
                            {!step.alias ? (
                                <p className="text-[10px] text-amber-600 flex items-center gap-1">
                                    <HelpCircle className="h-3 w-3" />
                                    Used later to fill documents and make decisions.
                                </p>
                            ) : (
                                !/^[a-zA-Z0-9_.]+$/.test(step.alias) && (
                                    <p className="text-[10px] text-amber-600 flex items-center gap-1">
                                        ΓÜá∩╕Å Simple names are safest (a-z, 0-9, dots).
                                    </p>
                                )
                            )}
                        </div>
                    )}
                </div>
            )}

            {/* Answer Settings */}
            <div className="space-y-1.5 pt-2">

                {/* Required Toggle */}
                {step.type !== "display" && (
                    <div className="flex items-center justify-between py-1">
                        <Label htmlFor={`required-${step.id}`} className="text-sm cursor-pointer">
                            Required
                        </Label>
                        <Switch
                            id={`required-${step.id}`}
                            checked={localRequired}
                            onCheckedChange={handleRequiredChange}
                        />
                    </div>
                )}

                {/* Description / Help Text */}
                <div className="space-y-1.5">
                    <Label htmlFor={`description-${step.id}`} className="text-xs text-muted-foreground">
                        {step.type === "display" ? "Content (Markdown)" : "Description / Help Text (optional)"}
                    </Label>
                    <AutoExpandTextarea
                        id={`description-${step.id}`}
                        name={`description-${step.id}`}
                        value={step.description ?? ""}
                        onChange={(e) => { void handleDescriptionChange(e.target.value); }}
                        placeholder={step.type === "display" ? "Enter markdown content..." : "Add instructions for the user..."}
                        minRows={step.type === "display" ? 6 : 1}
                        maxRows={step.type === "display" ? 12 : 4}
                        className="text-sm"
                    />
                </div>

                {/* Options Editor (for radio/multiple_choice) */}
                {(localType === "radio" || localType === "multiple_choice") && (
                    <OptionsEditor
                        options={localOptions}
                        onChange={(opts) => { void handleOptionsChange(opts); }}
                        elementId={step.id}
                    />
                )}

                {/* Default Value Section */}
                {step.type !== "display" && (mode === 'advanced' || upstreamWorkflowId) && (
                    <div className="space-y-1.5 pt-2 border-t border-dashed">
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-2">
                                <Label htmlFor={`default-val-${step.id}`} className="text-xs text-muted-foreground">
                                    Default Value {mode === 'easy' && !upstreamWorkflowId && '(Advanced)'}
                                </Label>
                                {isLinkedToIntake && (
                                    <Badge variant="outline" className="text-[10px] h-4 px-1 gap-1 text-emerald-600 border-emerald-200 bg-emerald-50">
                                        <LinkIcon className="w-2.5 h-2.5" />
                                        Linked
                                    </Badge>
                                )}
                            </div>
                        </div>

                        {upstreamWorkflowId ? (
                            <div className="space-y-2">
                                {/* Toggle: Static vs Intake */}
                                <Tabs
                                    value={activeTab}
                                    onValueChange={handleTabChange}
                                    className="w-full"
                                >
                                    <TabsList className="grid w-full grid-cols-2 h-7">
                                        <TabsTrigger value="static" className="text-xs h-6">Static Value</TabsTrigger>
                                        <TabsTrigger value="intake" className="text-xs h-6 flex items-center gap-1">
                                            <Database className="w-3 h-3" /> From Intake
                                        </TabsTrigger>
                                    </TabsList>

                                    <TabsContent value="static" className="mt-2 space-y-1.5">
                                        {step.type === "yes_no" ? (
                                            <Select
                                                value={staticSelectValue}
                                                onValueChange={(value) => {
                                                    if (value === "none") {
                                                        handleDefaultValueChange("");
                                                    } else {
                                                        handleDefaultValueChange(value);
                                                    }
                                                }}
                                            >
                                                <SelectTrigger id={`default-val-${step.id}`} className="h-9">
                                                    <SelectValue placeholder="No default" />
                                                </SelectTrigger>
                                                <SelectContent>
                                                    <SelectItem value="none">No default</SelectItem>
                                                    <SelectItem value="yes">Yes</SelectItem>
                                                    <SelectItem value="no">No</SelectItem>
                                                </SelectContent>
                                            </Select>
                                        ) : (
                                            <Input
                                                id={`default-val-${step.id}`}
                                                name={`default-val-${step.id}`}
                                                value={staticInputValue}
                                                onChange={(e) => { void handleDefaultValueChange(e.target.value); }}
                                                placeholder="Enter default value..."
                                                className="h-9 text-sm"
                                            />
                                        )}
                                    </TabsContent>

                                    <TabsContent value="intake" className="mt-2 text-primary-foreground">
                                        <div className="space-y-1">
                                            <Label htmlFor={`default-val-intake-${step.id}`} className="sr-only">Select Intake Variable</Label>
                                            <Select
                                                value={isLinkedToIntake && (step.defaultValue as { variable?: string })?.variable ? (step.defaultValue as { variable?: string }).variable : "none"}
                                                onValueChange={handleIntakeLinkChange}
                                            >
                                                <SelectTrigger id={`default-val-intake-${step.id}`} className="h-9 w-full bg-emerald-50/50 border-emerald-200 text-emerald-900 focus:ring-emerald-500">
                                                    <SelectValue placeholder="Select intake variable..." />
                                                </SelectTrigger>
                                                <SelectContent>
                                                    <SelectItem value="none">-- Select Variable --</SelectItem>
                                                    {upstreamVariables.map(v => (
                                                        <SelectItem key={v.key} value={v.alias || v.key}>
                                                            <div className="flex flex-col text-left">
                                                                <span className="font-medium text-sm">{v.label}</span>
                                                                <span className="text-[10px] text-muted-foreground font-mono">{v.alias || v.key}</span>
                                                            </div>
                                                        </SelectItem>
                                                    ))}
                                                </SelectContent>
                                            </Select>
                                            {isLinkedToIntake && (
                                                <p className="text-[10px] text-emerald-600 pl-1">
                                                    This field will pre-fill from <strong>{upstreamWorkflow?.title}</strong> data.
                                                    <span className="sr-only">Input linked to intake variable.</span>
                                                </p>
                                            )}
                                        </div>
                                    </TabsContent>
                                </Tabs>
                            </div>
                        ) : (
                            // Standard Static Default Value (No Upstream)
                            step.type === "yes_no" ? (
                                <Select
                                    value={
                                        step.defaultValue === null || step.defaultValue === undefined
                                            ? "none"
                                            : step.defaultValue === true
                                                ? "yes"
                                                : "no"
                                    }
                                    onValueChange={(value) => {
                                        if (value === "none") {
                                            handleDefaultValueChange("");
                                        } else {
                                            handleDefaultValueChange(value);
                                        }
                                    }}
                                >
                                    <SelectTrigger id={`default-val-${step.id}`} className="h-9">
                                        <SelectValue placeholder="No default" />
                                    </SelectTrigger>
                                    <SelectContent>
                                        <SelectItem value="none">No default</SelectItem>
                                        <SelectItem value="yes">Yes</SelectItem>
                                        <SelectItem value="no">No</SelectItem>
                                    </SelectContent>
                                </Select>
                            ) : (
                                <Input
                                    id={`default-val-${step.id}`}
                                    name={`default-val-${step.id}`}
                                    value={
                                        step.defaultValue === null || step.defaultValue === undefined
                                            ? ""
                                            : typeof step.defaultValue === "object"
                                                ? JSON.stringify(step.defaultValue)
                                                : String(step.defaultValue)
                                    }
                                    onChange={(e) => { void handleDefaultValueChange(e.target.value); }}
                                    placeholder="Enter default value..."
                                    className="h-9 text-sm"
                                />
                            )
                        )}
                    </div>
                )}

                {/* JS Question Editor (for js_question) */}
                {localType === "js_question" && (
                    <JSQuestionEditor
                        config={localJsConfig}
                        onChange={(config) => { void handleJsConfigChange(config); }}
                        elementId={step.id}
                        workflowId={workflowId}
                    />
                )}

                {/* Visibility Logic Section - Advanced Mode Only */}
                {mode === 'advanced' && (
                    <Collapsible
                        open={isVisibilityOpen}
                        onOpenChange={setIsVisibilityOpen}
                        className="border rounded-md"
                    >
                        <CollapsibleTrigger asChild>
                            <Button
                                variant="ghost"
                                className="w-full justify-between px-3 py-2 h-auto"
                            >
                                <div className="flex items-center gap-2">
                                    <EyeOff className="h-4 w-4 text-muted-foreground" />
                                    <span className="text-sm font-medium">Visibility</span>
                                </div>
                                <div className="flex items-center gap-2">
                                    <LogicStatusText visibleIf={step.visibleIf as ConditionExpression} />
                                    {isVisibilityOpen ? (
                                        <ChevronDown className="h-4 w-4" />
                                    ) : (
                                        <ChevronRight className="h-4 w-4" />
                                    )}
                                </div>
                            </Button>
                        </CollapsibleTrigger>
                        <CollapsibleContent className="px-3 pb-3">
                            <LogicBuilder
                                workflowId={workflowId}
                                elementId={step.id}
                                elementType="step"
                                value={(step.visibleIf as ConditionExpression) ?? null}
                                onChange={(expression) => { void handleVisibilityChange(expression); }}
                                isSaving={updateStepMutation.isPending}
                            />
                        </CollapsibleContent>
                    </Collapsible>
                )}
            </div>
        </div>
    );
}

/**
 * Options Editor Component
 * Comprehensive editor for choice question options
 * Supports three source types:
 * 1. Static: Manual options with drag-and-drop reordering
 * 2. From List: Bind to a ListVariable from Read Table / List Tools blocks
 * 3. From Table Column: Convenience path to read from a table column
 */

import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  type DragEndEvent,
} from "@dnd-kit/core";
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
  useSortable,
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { Plus, X, GripVertical, Database, List as ListIcon } from "lucide-react";
import { useState, useEffect } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { cn } from "@/lib/utils";

import type { DynamicOptionsConfig, DynamicOptionsSourceType } from "@/../../shared/types/stepConfigs";

export interface OptionItemData {
  id: string;
  label: string;
  alias?: string;
}

interface OptionsEditorProps {
  options: (string | OptionItemData)[] | DynamicOptionsConfig;
  onChange: (options: OptionItemData[] | DynamicOptionsConfig) => void;
  className?: string;
  elementId: string;
  mode?: 'easy' | 'advanced';  // Easy mode shows simplified UI
}

export function OptionsEditor({ options, onChange, className, elementId, mode = 'advanced' }: OptionsEditorProps) {
  // =========================================================================
  // State Management
  // =========================================================================

  // Determine source type from options structure
  const getSourceType = (opts: any): DynamicOptionsSourceType => {
    if (opts && typeof opts === 'object' && 'type' in opts) {
      return opts.type as DynamicOptionsSourceType;
    }
    if (opts && typeof opts === 'object' && ('listVariable' in opts || 'dataSourceId' in opts)) {
      // Legacy dynamic format
      return opts.listVariable ? 'list' : 'table_column';
    }
    return 'static';
  };

  const [sourceType, setSourceType] = useState<DynamicOptionsSourceType>(getSourceType(options));

  // Static options
  const normalizeOptions = (opts: any): OptionItemData[] => {
    if (!opts) {return [];}
    if (!Array.isArray(opts)) {return [];}
    return opts.map((opt, index) => {
      if (typeof opt === 'string') {
        return {
          id: `opt-${Date.now()}-${index}`,
          label: opt,
          alias: opt.toLowerCase().replace(/\s+/g, '_')
        };
      }
      return {
        ...opt,
        id: opt.id || `opt-${Date.now()}-${index}`
      };
    });
  };

  const [localOptions, setLocalOptions] = useState<OptionItemData[]>(() => {
    if (sourceType === 'static' && Array.isArray(options)) {
      return normalizeOptions(options);
    }
    if (typeof options === 'object' && 'type' in options && options.type === 'static') {
      return normalizeOptions(options.options);
    }
    return [];
  });

  // List source state
  const [listConfig, setListConfig] = useState(() => {
    if (typeof options === 'object' && 'type' in options && options.type === 'list') {
      return {
        listVariable: options.listVariable ?? '',
        labelPath: options.labelPath ?? '',
        valuePath: options.valuePath ?? '',
      };
    }
    return { listVariable: '', labelPath: '', valuePath: '' };
  });

  // Table column source state
  const [tableConfig, setTableConfig] = useState(() => {
    if (typeof options === 'object' && 'type' in options && options.type === 'table_column') {
      return {
        dataSourceId: options.dataSourceId ?? '',
        tableId: options.tableId ?? '',
        columnId: options.columnId ?? '',
        labelColumnId: options.labelColumnId ?? '',
        sort: options.sort,
        limit: options.limit || 100,
      };
    }
    return {
      dataSourceId: '',
      tableId: '',
      columnId: '',
      labelColumnId: '',
      limit: 100,
    };
  });

  // Sync with external changes
  useEffect(() => {
    const newSourceType = getSourceType(options);
    setSourceType(newSourceType);

    if (newSourceType === 'static') {
      if (Array.isArray(options)) {
        setLocalOptions(normalizeOptions(options));
      } else if (typeof options === 'object' && 'type' in options && options.type === 'static') {
        setLocalOptions(normalizeOptions(options.options));
      }
    }
  }, [options]);

  // =========================================================================
  // DnD Sensors
  // =========================================================================

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  // =========================================================================
  // Static Options Handlers
  // =========================================================================

  const handleAddOption = () => {
    const newId = `opt-${Date.now()}`;
    const newOption: OptionItemData = {
      id: newId,
      label: `Option ${localOptions.length + 1}`,
      alias: `option_${localOptions.length + 1}`
    };
    const newOptions = [...localOptions, newOption];
    setLocalOptions(newOptions);
    emitStaticOptions(newOptions);
  };

  const handleRemoveOption = (index: number) => {
    const newOptions = localOptions.filter((_, i) => i !== index);
    setLocalOptions(newOptions);
    emitStaticOptions(newOptions);
  };

  const handleUpdateOption = (index: number, field: keyof OptionItemData, value: string) => {
    const newOptions = [...localOptions];
    newOptions[index] = { ...newOptions[index], [field]: value };
    setLocalOptions(newOptions);
  };

  const handleBlur = () => {
    emitStaticOptions(localOptions);
  };

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;

    if (over && active.id !== over.id) {
      const oldIndex = localOptions.findIndex((o) => o.id === active.id);
      const newIndex = localOptions.findIndex((o) => o.id === over.id);

      if (oldIndex !== -1 && newIndex !== -1) {
        const reordered = arrayMove(localOptions, oldIndex, newIndex);
        setLocalOptions(reordered);
        emitStaticOptions(reordered);
      }
    }
  };

  const emitStaticOptions = (opts: OptionItemData[]) => {
    onChange({ type: 'static', options: opts } as DynamicOptionsConfig);
  };

  // =========================================================================
  // Source Type Change Handler
  // =========================================================================

  const handleSourceTypeChange = (newType: DynamicOptionsSourceType) => {
    setSourceType(newType);

    if (newType === 'static') {
      emitStaticOptions(localOptions);
    } else if (newType === 'list') {
      onChange({
        type: 'list',
        listVariable: listConfig.listVariable ?? '',
        labelPath: listConfig.labelPath ?? '',
        valuePath: listConfig.valuePath ?? '',
      } as DynamicOptionsConfig);
    } else if (newType === 'table_column') {
      onChange({
        type: 'table_column',
        dataSourceId: tableConfig.dataSourceId ?? '',
        tableId: tableConfig.tableId ?? '',
        columnId: tableConfig.columnId ?? '',
        labelColumnId: tableConfig.labelColumnId ?? '',
        limit: tableConfig.limit || 100,
      } as DynamicOptionsConfig);
    }
  };

  // =========================================================================
  // List Config Handlers
  // =========================================================================

  const handleListConfigChange = (field: keyof typeof listConfig, value: string) => {
    const newConfig = { ...listConfig, [field]: value };
    setListConfig(newConfig);
    onChange({
      type: 'list',
      listVariable: newConfig.listVariable,
      labelPath: newConfig.labelPath,
      valuePath: newConfig.valuePath,
    } as DynamicOptionsConfig);
  };

  // =========================================================================
  // Table Config Handlers
  // =========================================================================

  const handleTableConfigChange = (field: keyof typeof tableConfig, value: any) => {
    const newConfig = { ...tableConfig, [field]: value };
    setTableConfig(newConfig);
    onChange({
      type: 'table_column',
      dataSourceId: newConfig.dataSourceId,
      tableId: newConfig.tableId,
      columnId: newConfig.columnId,
      labelColumnId: newConfig.labelColumnId,
      limit: newConfig.limit,
    } as DynamicOptionsConfig);
  };

  // =========================================================================
  // Render
  // =========================================================================

  const isEasyMode = mode === 'easy';

  return (
    <div className={cn("space-y-4", className)}>
      {/* Source Type Selector */}
      <div className="space-y-2">
        <Label htmlFor={`source-type-${elementId}`} className="text-sm font-medium">
          Options Source
        </Label>
        {isEasyMode ? (
          <Select value={sourceType} onValueChange={handleSourceTypeChange}>
            <SelectTrigger id={`source-type-${elementId}`}>
              <SelectValue placeholder="Select source..." />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="static">Static Options</SelectItem>
              <SelectItem value="list">From Saved Data</SelectItem>
            </SelectContent>
          </Select>
        ) : (
          <div className="flex bg-muted rounded-md p-0.5">
            <button
              onClick={() => handleSourceTypeChange('static')}
              className={cn(
                "flex-1 text-xs px-3 py-1.5 rounded-sm transition-colors flex items-center justify-center gap-1.5",
                sourceType === 'static' ? "bg-background shadow-sm text-foreground font-medium" : "text-muted-foreground hover:text-foreground"
              )}
            >
              Static
            </button>
            <button
              onClick={() => handleSourceTypeChange('list')}
              className={cn(
                "flex-1 text-xs px-3 py-1.5 rounded-sm transition-colors flex items-center justify-center gap-1.5",
                sourceType === 'list' ? "bg-background shadow-sm text-foreground font-medium" : "text-muted-foreground hover:text-foreground"
              )}
            >
              <ListIcon className="w-3 h-3" />
              From List
            </button>
            <button
              onClick={() => handleSourceTypeChange('table_column')}
              className={cn(
                "flex-1 text-xs px-3 py-1.5 rounded-sm transition-colors flex items-center justify-center gap-1.5",
