                  </p>
                </div>
                <Switch
                  id="allow-portal"
                  checked={allowPortal}
                  onCheckedChange={setAllowPortal}
                />
              </div>

              <Separator />

              <div className="flex items-center justify-between">
                <div>
                  <Label htmlFor="allow-resume">Allow Resuming</Label>
                  <p className="text-xs text-muted-foreground">
                    Allow clients to resume incomplete or outdated workflows from the portal
                  </p>
                </div>
                <Switch
                  id="allow-resume"
                  checked={allowResume}
                  onCheckedChange={setAllowResume}
                />
              </div>

              <Separator />

              <div className="flex items-center justify-between">
                <div>
                  <Label htmlFor="allow-redownload">Allow Re-downloading</Label>
                  <p className="text-xs text-muted-foreground">
                    Allow clients to access generated documents after completion
                  </p>
                </div>
                <Switch
                  id="allow-redownload"
                  checked={allowRedownload}
                  onCheckedChange={setAllowRedownload}
                />
              </div>
            </CardContent>
          </Card>
        </div>
      </BuilderLayoutContent>
    </BuilderLayout >
  );
}

/**
 * SnapshotsTab - Manage workflow test snapshots
 * Fully integrated with backend API for snapshot management
 */
import { Camera, Trash2, Eye, Play, Edit2, AlertCircle, AlertTriangle } from "lucide-react";
import { useState } from "react";
import { useLocation } from "wouter";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { useToast } from "@/hooks/use-toast";
import {  type ApiSnapshot } from "@/lib/vault-api";
import {
  useSnapshots,
  useRenameSnapshot,
  useDeleteSnapshot,
} from "@/lib/vault-hooks";
import { usePreviewStore } from "@/store/preview";

import { BuilderLayout, BuilderLayoutHeader, BuilderLayoutContent } from "../layout/BuilderLayout";
interface SnapshotsTabProps {
  workflowId: string;
}
export function SnapshotsTab({ workflowId }: SnapshotsTabProps) {
  const { toast } = useToast();
  const [, setLocation] = useLocation();
  const setPreviewToken = usePreviewStore((s) => s.setToken);
  // Fetch snapshots from API
  const { data: snapshots, isLoading, error } = useSnapshots(workflowId);
  const renameSnapshot = useRenameSnapshot();
  const deleteSnapshot = useDeleteSnapshot();
  // Dialog states
  const [viewDialogOpen, setViewDialogOpen] = useState(false);
  const [renameDialogOpen, setRenameDialogOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [selectedSnapshot, setSelectedSnapshot] = useState<ApiSnapshot | null>(null);
  const [newName, setNewName] = useState("");
  const [isCreatingRun, setIsCreatingRun] = useState(false);
  // Handle rename snapshot
  const handleRename = async () => {
    if (!selectedSnapshot || !newName.trim()) {return;}
    try {
      await renameSnapshot.mutateAsync({
        workflowId,
        snapshotId: selectedSnapshot.id,
        name: newName.trim(),
      });
      toast({ title: "Success", description: "Snapshot renamed" });
      setRenameDialogOpen(false);
      setSelectedSnapshot(null);
      setNewName("");
    } catch (error: any) {
      toast({
        title: "Error",
        description: error.message || "Failed to rename snapshot",
        variant: "destructive",
      });
    }
  };
  // Handle delete snapshot
  const handleDelete = async () => {
    if (!selectedSnapshot) {return;}
    try {
      await deleteSnapshot.mutateAsync({
        workflowId,
        snapshotId: selectedSnapshot.id,
      });
      toast({ title: "Success", description: "Snapshot deleted" });
      setDeleteDialogOpen(false);
      setSelectedSnapshot(null);
    } catch (error: any) {
      toast({
        title: "Error",
        description: error.message || "Failed to delete snapshot",
        variant: "destructive",
      });
    }
  };
  // Handle preview with snapshot (navigate to new WorkflowPreview with snapshot parameter)
  const handlePreview = async (snapshot: ApiSnapshot) => {
    toast({
      title: "Scenario Loaded",
      description: `Previewing scenario "${snapshot.name}"`,
    });
    // Navigate to workflow preview with snapshot ID
    setLocation(`/workflows/${workflowId}/preview?snapshotId=${snapshot.id}`);
  };
  // Handle view snapshot data
  const handleView = (snapshot: ApiSnapshot) => {
    setSelectedSnapshot(snapshot);
    setViewDialogOpen(true);
  };
  // Open rename dialog
  const handleOpenRename = (snapshot: ApiSnapshot) => {
    setSelectedSnapshot(snapshot);
    setNewName(snapshot.name);
    setRenameDialogOpen(true);
  };
  // Open delete confirmation
  const handleOpenDelete = (snapshot: ApiSnapshot) => {
    setSelectedSnapshot(snapshot);
    setDeleteDialogOpen(true);
  };
  return (
    <BuilderLayout>
      <BuilderLayoutHeader>
        <div>
          <h2 className="text-lg font-semibold">Saved Scenarios</h2>
          <p className="text-sm text-muted-foreground">
            Save different client situations (e.g. "Married with Kids") to quick-check your workflow logic.
          </p>
        </div>
      </BuilderLayoutHeader>
      <BuilderLayoutContent>
        {error && (
          <Alert variant="destructive" className="mb-4">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription>
              Failed to load scenarios: {error.message}
            </AlertDescription>
          </Alert>
        )}
        {isLoading ? (
          <div className="flex items-center justify-center py-12">
            <div className="text-muted-foreground">Loading scenarios...</div>
          </div>
        ) : snapshots && snapshots.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-12 text-center max-w-sm mx-auto">
            <div className="w-12 h-12 bg-indigo-50 text-indigo-500 rounded-full flex items-center justify-center mb-4">
              <Camera className="w-6 h-6" />
            </div>
            <h3 className="text-lg font-semibold mb-2">No saved scenarios yet</h3>
            <p className="text-sm text-muted-foreground text-center">
              Create a scenario by running a Preview. At any point, you can click "Save Scenario" to capture the current answers for later use.
            </p>
          </div>
        ) : (
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Scenario Name</TableHead>
                <TableHead>Data Points</TableHead>
                <TableHead>Created</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {snapshots?.map((snapshot) => {
                const valueCount = Object.keys(snapshot.values).length;
                // Show outdated indicator if no versionHash (old snapshot) or hash missing
                const isOutdated = !snapshot.versionHash;
                return (
                  <TableRow key={snapshot.id}>
                    <TableCell className="font-medium">
                      <div className="flex items-center gap-2">
                        {snapshot.name}
                        {isOutdated && (
                          <span
                            className="inline-flex items-center gap-1 text-xs text-amber-600 dark:text-amber-400 bg-amber-50 px-1.5 py-0.5 rounded"
                            title="Scenario created on an older version of this workflow"
                          >
                            <AlertTriangle className="w-3 h-3" />
                            <span className="hidden sm:inline">Needs Update</span>
                          </span>
                        )}
                      </div>
                    </TableCell>
                    <TableCell className="text-muted-foreground">
                      {valueCount} {valueCount === 1 ? 'answer' : 'answers'}
                    </TableCell>
                    <TableCell>{new Date(snapshot.createdAt).toLocaleDateString()}</TableCell>
                    <TableCell className="text-right space-x-2">
                      <Button
                        size="sm"
                        variant="default"
                        className="bg-indigo-600 hover:bg-indigo-700"
                        onClick={() => { void handlePreview(snapshot); }}
                      >
                        <Play className="w-3 h-3 mr-1" />
                        Run Scenario
                      </Button>
                      <Button size="sm" variant="ghost" onClick={() => { void handleView(snapshot); }}>
                        <Eye className="w-3 h-3" />
                      </Button>
                      <Button size="sm" variant="ghost" onClick={() => { void handleOpenRename(snapshot); }}>
                        <Edit2 className="w-3 h-3" />
                      </Button>
                      <Button size="sm" variant="ghost" className="text-muted-foreground hover:text-destructive" onClick={() => { void handleOpenDelete(snapshot); }}>
                        <Trash2 className="w-3 h-3" />
                      </Button>
                    </TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        )}
        {/* Rename Dialog */}
        <Dialog open={renameDialogOpen} onOpenChange={setRenameDialogOpen}>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Rename Scenario</DialogTitle>
              <DialogDescription>Give this scenario a descriptive name (e.g. "Scenario A: High Net Worth")</DialogDescription>
            </DialogHeader>
            <div className="space-y-4 py-4">
              <div className="space-y-2">
                <Label htmlFor="rename">Scenario Name</Label>
                <Input
                  id="rename"
                  value={newName}
                  onChange={(e) => { void setNewName(e.target.value); }}
                  onKeyDown={(e) => { void e.key === "Enter" && handleRename(); }}
                />
              </div>
            </div>
            <DialogFooter>
              <Button
                variant="outline"
                onClick={() => {
                  setRenameDialogOpen(false);
                  setNewName("");
                }}
              >
                Cancel
              </Button>
              <Button onClick={() => { void handleRename(); }} disabled={renameSnapshot.isPending || !newName.trim()}>
                {renameSnapshot.isPending ? "Saving..." : "Save Name"}
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
        {/* Delete Confirmation Dialog */}
        <Dialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Delete Scenario</DialogTitle>
              <DialogDescription>
                Are you sure you want to delete "{selectedSnapshot?.name}"?
              </DialogDescription>
            </DialogHeader>
            <DialogFooter>
              <Button variant="outline" onClick={() => { void setDeleteDialogOpen(false); }}>
                Cancel
              </Button>
              <Button variant="destructive" onClick={() => { void handleDelete(); }} disabled={deleteSnapshot.isPending}>
                {deleteSnapshot.isPending ? "Deleting..." : "Delete Scenario"}
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
        {/* View Dialog with JSON */}
        <Dialog open={viewDialogOpen} onOpenChange={setViewDialogOpen}>
          <DialogContent className="max-w-2xl">
            <DialogHeader>
              <DialogTitle>{selectedSnapshot?.name} (Data View)</DialogTitle>
              <DialogDescription>
                {Object.keys(selectedSnapshot?.values || {}).length} stored values in this scenario
              </DialogDescription>
            </DialogHeader>
            <div className="max-h-96 overflow-auto">
              <pre className="p-4 bg-muted rounded-lg text-xs font-mono">
                {JSON.stringify(selectedSnapshot?.values, null, 2)}
              </pre>
            </div>
            <DialogFooter>
              <Button onClick={() => { void setViewDialogOpen(false); }}>Close</Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </BuilderLayoutContent>
    </BuilderLayout>
  );
}

/**
 * TemplatesTab - Manage document templates (DOCX/PDF)
 * PR4: Full UI implementation with stubs
 */
import axios from "axios";
import { Upload, FileText, Trash2, TestTube, AlertCircle, CheckCircle, ExternalLink, Edit } from "lucide-react";
import { useState, useEffect } from "react";
import { useLocation } from "wouter";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useToast } from "@/hooks/use-toast";
import { cn } from "@/lib/utils";
import { type ApiWorkflowVariable } from "@/lib/vault-api";
import { useWorkflow, useProjects, useWorkflowVariables } from "@/lib/vault-hooks";
import { DocumentTemplateEditor } from "@/pages/visual-builder/components/DocumentTemplateEditor";

import { BuilderLayout, BuilderLayoutHeader, BuilderLayoutContent } from "../layout/BuilderLayout";
import { PdfMappingEditor } from "../templates/PdfMappingEditor";
interface Template {
  id: string;
  name: string;
  key: string;
  type: "docx" | "pdf";
  lastUpdated: string;
  fileSize?: number;
  variables?: string[];
}
interface TemplatesTabProps {
  workflowId: string;
}
export function TemplatesTab({ workflowId }: TemplatesTabProps) {
  const { toast } = useToast();
  const [, navigate] = useLocation();
  const [templates, setTemplates] = useState<Template[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [uploadDialogOpen, setUploadDialogOpen] = useState(false);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [templateKey, setTemplateKey] = useState("");
  const [workflowProjectId, setWorkflowProjectId] = useState<string | null>(null);
  const [editingTemplate, setEditingTemplate] = useState<Template | null>(null);
  // Fetch workflow for project context
  const { data: workflow } = useWorkflow(workflowId);
  // Fetch variables for variable analysis
  const { data: variables } = useWorkflowVariables(workflowId);
  // Fetch projects to find fallback
  const { data: projects } = useProjects();
  const workflowVariables = (variables ?? []).map((v: ApiWorkflowVariable) => ({
    id: v.key,
    alias: v.alias ?? null,
    text: v.label
  }));
  // console.log("TemplatesTab: Computed workflowVariables", workflowVariables);
  const workflowVariableAliases = new Set(workflowVariables.map(v => v.alias).filter((a): a is string => !!a));
  // Fetch templates for this project
  const fetchTemplates = async () => {
    try {
      if (!workflowProjectId) { return; }
      const response = await axios.get(`/api/projects/${workflowProjectId}/templates`);
      const data = response.data;
      const mappedTemplates = (data.items ?? []).map((t: any) => ({
        id: t.id,
        name: t.name,
        key: t.id,
        type: t.type || "docx",
        lastUpdated: t.updatedAt || t.createdAt,
        fileSize: t.fileSize,
        // Mock variables if backend doesn't return them yet, for UX demonstration
        variables: t.variables || ["clientName", "matterDate", "unmatched_variable"]
      }));
      setTemplates(mappedTemplates);
    } catch (error) {
      console.error("Error fetching templates:", error);
    }
  };
  useEffect(() => {
    if (workflow?.projectId) {
      setWorkflowProjectId(workflow.projectId);
    } else if (projects && projects.length > 0) {
      // Fallback: Use the first project (Default Project) if workflow is unfiled
      setWorkflowProjectId(projects[0].id);
    }
  }, [workflow?.projectId, projects]);
  useEffect(() => {
    if (workflowProjectId) {
      fetchTemplates();
    }
  }, [workflowProjectId]);
  // Helper to check variable status
  const getVariableStatus = (templateVars: string[]) => {
    const missing = templateVars.filter(v => !workflowVariableAliases.has(v));
    const matched = templateVars.filter(v => workflowVariableAliases.has(v));
    return { missing, matched, total: templateVars.length };
  };
  // Handle template upload
  const handleUpload = async () => {
    if (!selectedFile || !templateKey || !workflowProjectId) {
      toast({
        title: "Missing information",
        description: !workflowProjectId
          ? "No project context found. Please save the workflow to a project first."
          : "Please select a file and provide a display name.",
        variant: "destructive",
      });
      return;
    }
    setIsUploading(true);
    try {
      const formData = new FormData();
      formData.append("file", selectedFile);
      formData.append("name", templateKey);
      await axios.post(`/api/projects/${workflowProjectId}/templates`, formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      toast({
        title: "Template uploaded",
        description: `${templateKey} has been uploaded successfully.`,
      });
      setUploadDialogOpen(false);
      setSelectedFile(null);
      setTemplateKey("");
      fetchTemplates();
    } catch (error: any) {
      console.error("Upload error:", error);
      toast({
        title: "Upload failed",
        description: error.response?.data?.message || "Failed to upload template",
        variant: "destructive",
      });
    } finally {
      setIsUploading(false);
    }
  };
  // Handle template test
  const handleTest = async (templateId: string) => {
    try {
      toast({
        title: "Testing template",
        description: "Generating test document...",
      });
      const response = await axios.post(`/api/templates/${templateId}/test`, {
        workflowId,
      });
      if (response.data?.url) {
        window.open(response.data.url, "_blank");
        toast({
          title: "Test successful",
          description: "Test document generated and opened.",
        });
      }
    } catch (error: any) {
      console.error("Test error:", error);
      toast({
        title: "Test failed",
        description: error.response?.data?.message || "Failed to test template",
        variant: "destructive",
      });
    }
  };
  // Handle template deletion
  const handleDelete = async (templateId: string, templateName: string) => {
    if (!confirm(`Are you sure you want to delete "${templateName}"?`)) {
      return;
    }
    try {
      await axios.delete(`/api/templates/${templateId}`);
      toast({
        title: "Template deleted",
        description: `${templateName} has been deleted.`,
      });
      fetchTemplates();
    } catch (error: any) {
      console.error("Delete error:", error);
      toast({
        title: "Delete failed",
        description: error.response?.data?.message || "Failed to delete template",
        variant: "destructive",
      });
    }
  };
  const renderTemplateGrid = (type: 'docx' | 'pdf') => {
    const filteredTemplates = templates.filter(t => t.type === type);
    if (filteredTemplates.length === 0 && workflowProjectId) {
      return (
        <div className="flex flex-col items-center justify-center h-64 text-center border-2 border-dashed rounded-lg bg-slate-50/50">
          <FileText className="w-10 h-10 text-muted-foreground mb-4 opacity-50" />
          <p className="text-sm text-muted-foreground font-medium">No {type === 'docx' ? 'Word' : 'PDF'} templates uploaded.</p>
          <p className="text-xs text-muted-foreground mt-1">Upload a {type === 'docx' ? '.docx' : '.pdf'} file to get started.</p>
        </div>
      );
    }
    return (
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredTemplates.map((template) => {
          const { missing, matched, total } = getVariableStatus(template.variables ?? []);
          const hasMissing = missing.length > 0;
          return (
            <Card key={template.id} className="flex flex-col hover:shadow-md transition-shadow">
              <CardHeader className="pb-3">
                <div className="flex justify-between items-start gap-4">
                  <div className="min-w-0">
                    <CardTitle className="text-base truncate leading-tight" title={template.name}>{template.name}</CardTitle>
                    <CardDescription className="font-mono text-[10px] mt-1 text-slate-400 truncate">{template.key}</CardDescription>
                  </div>
                  <Badge variant="secondary" className="shrink-0 text-[10px] px-1.5 py-0 h-5 font-normal text-slate-500">
                    {template.type.toUpperCase()}
                  </Badge>
                </div>
              </CardHeader>
              <CardContent className="flex-1 space-y-4">
                {/* Variable Analysis Feedback */}
                <div className="rounded-md bg-slate-50 p-3 text-xs space-y-2 border border-slate-100">
                  <div className="flex items-center justify-between font-medium">
                    <span className="text-slate-500">Variables</span>
                    {hasMissing ? (
                      <span className="text-amber-600 flex items-center gap-1">
                        <AlertCircle className="w-3 h-3" />
                        {missing.length} missing
                      </span>
                    ) : (
                      <span className="text-emerald-600 flex items-center gap-1">
                        <CheckCircle className="w-3 h-3" />
                        {matched.length}/{total} matched
                      </span>
                    )}
                  </div>
                  {/* Progress Bar */}
                  <div className="h-1.5 w-full bg-slate-200 rounded-full overflow-hidden">
                    <div
                      className={cn("h-full transition-all", hasMissing ? "bg-amber-500" : "bg-emerald-500")}
                      style={{ width: `${total > 0 ? (matched.length / total) * 100 : 100}%` }}
                    />
                  </div>
                  {hasMissing && (
                    <div className="pt-2 border-t border-slate-200/50 mt-2">
                      <p className="font-semibold text-amber-700 mb-1.5">Create these variables:</p>
                      <div className="flex flex-wrap gap-1">
                        {missing.slice(0, 3).map(v => (
                          <code key={v} className="bg-white text-amber-700 px-1 py-0.5 rounded border border-amber-200 shadow-sm text-[10px]">
                            {v}
                          </code>
                        ))}
                        {missing.length > 3 && <span className="text-amber-600 text-[10px] self-center">+{missing.length - 3}</span>}
                      </div>
                    </div>
                  )}
                </div>
              </CardContent>
              <CardFooter className="pt-0 flex gap-2 justify-end border-t bg-slate-50/30 p-3">
                <Button size="sm" variant="default" className="h-7 text-xs px-3 shadow-sm" onClick={() => { void setEditingTemplate(template); }}>
                  <Edit className="w-3 h-3 mr-1.5" />
                  {template.type === 'pdf' ? 'Map Fields' : 'Preview'}
                </Button>
                <Button size="sm" variant="ghost" className="h-7 w-7 p-0" onClick={() => { void handleTest(template.id); }} title="Test Generation">
                  <TestTube className="w-3.5 h-3.5 text-slate-500" />
                </Button>
                <Button size="sm" variant="ghost" className="h-7 w-7 p-0 hover:bg-destructive/10 hover:text-destructive text-slate-400" onClick={() => { void handleDelete(template.id, template.name); }} title="Delete Template">
                  <Trash2 className="w-3.5 h-3.5" />
                </Button>
              </CardFooter>
            </Card>
          );
        })}
      </div>
    );
  };
  return (
    <BuilderLayout>
      <BuilderLayoutHeader>
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-lg font-semibold">Document Templates</h2>
            <div className="text-sm text-muted-foreground">
              Upload and manage document templates. We'll check if your workflow collects the required data.
            </div>
          </div>
          {/* Upload Dialog Trigger */}
          <Dialog open={uploadDialogOpen} onOpenChange={setUploadDialogOpen}>
            <DialogTrigger asChild>
              <Button>
                <Upload className="w-4 h-4 mr-2" />
                Upload Template
              </Button>
            </DialogTrigger>
            {/* ... Dialog Content same as before ... */}
            <DialogContent>
              <DialogHeader>
                <DialogTitle>Upload Document Template</DialogTitle>
                <DialogDescription>Supported formats: .docx, .pdf</DialogDescription>
              </DialogHeader>
              {/* Simplified upload form for brevity in replacement, assuming inner content is preserved if I was careful? 
                   Wait, I am replacing the WHOLE return? No, start line 39. 
                   I need to be careful. I'll stick to replacing specific blocks to avoid deleting the dialog content logic.
               */}
              <div className="space-y-4 py-4">
                <div className="space-y-2">
                  <Label htmlFor="file">Template File</Label>
                  <Input id="file" type="file" accept=".docx,.pdf" onChange={(e) => {
                    const file = e.target.files?.[0];
