import { format } from "date-fns";
import { Loader2, GitCommit, RotateCcw, FileDiff, Sparkles } from "lucide-react";
import { useEffect, useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
    Sheet,
    SheetContent,
    SheetHeader,
    SheetTitle,
    SheetDescription
} from "@/components/ui/sheet";
import { useToast } from "@/hooks/use-toast";
import { ApiWorkflowVersion, versionAPI } from "@/lib/vault-api";

interface VersionHistoryPanelProps {
    workflowId: string;
    isOpen: boolean;
    onClose: () => void;
    onRestore: (version: ApiWorkflowVersion) => void;
    onDiff: (version: ApiWorkflowVersion) => void;
}

export function VersionHistoryPanel({
    workflowId,
    isOpen,
    onClose,
    onRestore,
    onDiff
}: VersionHistoryPanelProps) {
    const [versions, setVersions] = useState<ApiWorkflowVersion[]>([]);
    const [loading, setLoading] = useState(false);
    const { toast } = useToast();

    useEffect(() => {
        if (isOpen && workflowId) {
            loadVersions();
        }
    }, [isOpen, workflowId]);

    const loadVersions = async () => {
        setLoading(true);
        try {
            const data = await versionAPI.list(workflowId);
            setVersions(data);
        } catch (error) {
            toast({
                title: "Error loading versions",
                description: "Failed to fetch version history",
                variant: "destructive"
            });
        } finally {
            setLoading(false);
        }
    };

    const handleRestore = async (version: ApiWorkflowVersion) => {
        if (confirm(`Are you sure you want to restore version ${version.versionNumber}? This will overwrite your current draft.`)) {
            try {
                await versionAPI.restore(workflowId, version.id);
                toast({ title: "Restored successfully", description: `Reverted to v${version.versionNumber}` });
                onRestore(version);
                onClose();
                // Trigger reload? The parent should handle it.
            } catch (error) {
                toast({ title: "Restore failed", variant: "destructive" });
            }
        }
    };

    return (
        <Sheet open={isOpen} onOpenChange={onClose}>
            <SheetContent className="w-[400px] sm:w-[540px]">
                <SheetHeader>
                    <SheetTitle>Version History</SheetTitle>
                    <SheetDescription>
                        View and manage previous versions of this workflow.
                    </SheetDescription>
                </SheetHeader>

                <div className="mt-6 flex flex-col gap-4 h-full">
                    {loading ? (
                        <div className="flex justify-center p-8">
                            <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
                        </div>
                    ) : (
                        <ScrollArea className="h-[calc(100vh-200px)] pr-4">
                            <div className="space-y-4">
                                {versions.map((version) => {
                                                    const isAiGenerated = version.migrationInfo &&
                                                        typeof version.migrationInfo === 'object' &&
                                                        'aiMetadata' in version.migrationInfo &&
                                                        (version.migrationInfo).aiMetadata?.aiGenerated;

                                                    return (
                                    <div
                                        key={version.id}
                                        className={`flex flex-col gap-2 p-4 border rounded-lg hover:bg-accent/50 transition-colors ${
                                            isAiGenerated ? 'border-purple-200 bg-purple-50/50' : ''
                                        }`}
                                    >
                                        <div className="flex items-center justify-between">
                                            <div className="flex items-center gap-2">
                                                <Badge variant={version.isDraft ? "secondary" : "default"}>
                                                    {version.isDraft ? "Draft" : `v${version.versionNumber}`}
                                                </Badge>
                                                {isAiGenerated && (
                                                    <Badge variant="outline" className="gap-1 text-purple-600 border-purple-300">
                                                        <Sparkles className="h-3 w-3" />
                                                        AI
                                                    </Badge>
                                                )}
                                                <span className="text-sm text-muted-foreground">
                                                    {format(new Date(version.createdAt), "PPP p")}
                                                </span>
                                            </div>
                                            <div className="flex gap-1">
                                                <Button size="icon" variant="ghost" title="Compare" onClick={() => { void onDiff(version); }}>
                                                    <FileDiff className="h-4 w-4" />
                                                </Button>
                                                <Button size="icon" variant="ghost" title="Restore" onClick={() => { void handleRestore(version); }}>
                                                    <RotateCcw className="h-4 w-4" />
                                                </Button>
                                            </div>
                                        </div>

                                        {version.notes && (
                                            <p className="text-sm text-muted-foreground bg-muted/50 p-2 rounded">
                                                {version.notes}
                                            </p>
                                        )}

                                        <div className="flex items-center gap-2 text-xs text-muted-foreground">
                                            <GitCommit className="h-3 w-3" />
                                            <span>{version.createdBy}</span>
                                            {isAiGenerated && (
                                                <span className="text-purple-600">
                                                    (via AI)
                                                </span>
                                            )}
                                        </div>
                                    </div>
                                    );
                                })}
                            </div>
                        </ScrollArea>
                    )}
                </div>
            </SheetContent>
        </Sheet>
    );
}

import React, { createContext, useContext, useMemo } from 'react';

import { useCollabClient, CollabClientState, CollabClientActions } from '@/hooks/collab/useCollabClient';

import type { Node, Edge } from 'reactflow';
// We just need the state and actions, not the raw provider refs for now
type CollabContextType = CollabClientState & CollabClientActions;
const CollabContext = createContext<CollabContextType | null>(null);
interface CollaborationProviderProps {
    children: React.ReactNode;
    config: {
        workflowId: string;
        tenantId: string;
        token: string;
        enabled?: boolean;
        user: {
            id: string;
            name: string;
            color: string;
            email?: string;
        };
    };
    // If we want to sync graph changes (Nodes/Edges), we pass callbacks here.
    // For this specific 'UX' task, we might not be syncing the graph fully yet, 
    // but the hook requires these callbacks. 
    // We can pass empty, or pass the real ones if available from parent.
    onNodesChange?: (nodes: Node[]) => void;
    onEdgesChange?: (edges: Edge[]) => void;
}
export function CollaborationProvider({ children, config, onNodesChange, onEdgesChange }: CollaborationProviderProps) {
    const noOp = () => { };
    // Use the hook
    const collab = useCollabClient({
        workflowId: config.workflowId,
        tenantId: config.tenantId,
        token: config.token,
        enabled: config.enabled ?? true,
        user: config.user,
        onNodesChange: onNodesChange || noOp,
        onEdgesChange: onEdgesChange || noOp,
    });
    return (
        <CollabContext.Provider value={collab}>
            {children}
        </CollabContext.Provider>
    );
}
export function useCollaboration() {
    const context = useContext(CollabContext);
    if (!context) {
        throw new Error('useCollaboration must be used within a CollaborationProvider');
    }
    return context;
}
/**
 * Hook to get collaborators who are currently "editing" a specific block
 */
export function useBlockCollaborators(blockId: string) {
    const { users } = useCollaboration();
    // Filter users who have this block as their activeBlockId
    // Sort? Maybe by latest first?
    const editors = useMemo(() => {
        return users.filter(u => u.activeBlockId === blockId);
    }, [users, blockId]);
    const isLocked = editors.length > 0;
    return {
        editors,
        isLocked,
        lockedBy: editors[0] // Simplify to first editor for "locked by" text
    };
}

import { formatDistanceToNow } from 'date-fns';
import { MessageSquare, Send, Trash2, X } from 'lucide-react';
import React, { useState } from 'react';

import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Textarea } from '@/components/ui/textarea';
import type { Comment } from '@/hooks/collab/useComments';

interface CommentsPanelProps {
  comments: Comment[];
  currentUserId: string;
  currentUserName: string;
  nodeName?: string;
  onAddComment: (text: string) => void;
  onDeleteComment: (commentId: string) => void;
  onClose?: () => void;
}

/**
 * Panel for displaying and adding comments on a workflow node
 */
export function CommentsPanel({
  comments,
  currentUserId,
  currentUserName,
  nodeName,
  onAddComment,
  onDeleteComment,
  onClose,
}: CommentsPanelProps) {
  const [newComment, setNewComment] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async () => {
    if (!newComment.trim()) { return; }

    setIsSubmitting(true);
    try {
      onAddComment(newComment.trim());
      setNewComment('');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
      e.preventDefault();
      handleSubmit();
    }
  };

  return (
    <Card className="w-full h-full flex flex-col">
      <CardHeader className="flex-shrink-0 border-b">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <MessageSquare className="w-5 h-5" />
            <CardTitle className="text-lg">
              {nodeName ? `Comments on "${nodeName}"` : 'Comments'}
            </CardTitle>
          </div>
          {onClose && (
            <Button variant="ghost" size="sm" onClick={() => { void onClose(); }}>
              <X className="w-4 h-4" />
            </Button>
          )}
        </div>
        <p className="text-sm text-muted-foreground">
          {comments.length} {comments.length === 1 ? 'comment' : 'comments'}
        </p>
      </CardHeader>

      <CardContent className="flex-1 flex flex-col p-4 gap-4 overflow-hidden">
        {/* Comments list */}
        <ScrollArea className="flex-1">
          <div className="space-y-4 pr-4">
            {comments.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-32 text-center text-muted-foreground">
                <MessageSquare className="w-8 h-8 mb-2 opacity-50" />
                <p className="text-sm">No comments yet</p>
                <p className="text-xs">Be the first to comment!</p>
              </div>
            ) : (
              comments.map((comment) => (
                <CommentItem
                  key={comment.id}
                  comment={comment}
                  currentUserId={currentUserId}
                  onDelete={onDeleteComment}
                />
              ))
            )}
          </div>
        </ScrollArea>

        {/* Add comment form */}
        <div className="flex-shrink-0 border-t pt-4 space-y-2">
          <Textarea
            placeholder="Add a comment... (Cmd/Ctrl+Enter to submit)"
            value={newComment}
            onChange={(e) => { void setNewComment(e.target.value); }}
            onKeyDown={(e) => { void handleKeyDown(e); }}
            className="min-h-[80px] resize-none"
            disabled={isSubmitting}
          />
          <div className="flex justify-end">
            <Button
              size="sm"
              onClick={() => { void handleSubmit(); }}
              disabled={!newComment.trim() || isSubmitting}
            >
              <Send className="w-4 h-4 mr-2" />
              Comment
            </Button>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

interface CommentItemProps {
  comment: Comment;
  currentUserId: string;
  onDelete: (commentId: string) => void;
}

/**
 * Single comment item
 */
function CommentItem({ comment, currentUserId, onDelete }: CommentItemProps) {
  const isOwner = comment.userId === currentUserId;
  const initials = getInitials(comment.userName);

  return (
    <div className="flex gap-3 group">
      <Avatar className="w-8 h-8 flex-shrink-0">
        <AvatarFallback className="text-xs">
          {initials}
        </AvatarFallback>
      </Avatar>

      <div className="flex-1 min-w-0">
        <div className="flex items-baseline gap-2 mb-1">
          <span className="font-medium text-sm">{comment.userName}</span>
          <span className="text-xs text-muted-foreground">
            {formatDistanceToNow(comment.timestamp, { addSuffix: true })}
          </span>
        </div>

        <p className="text-sm whitespace-pre-wrap break-words">{comment.text}</p>

        {isOwner && (
          <Button
            variant="ghost"
            size="sm"
            className="mt-1 h-auto py-1 px-2 text-xs opacity-0 group-hover:opacity-100 transition-opacity"
            onClick={() => { void onDelete(comment.id); }}
          >
            <Trash2 className="w-3 h-3 mr-1" />
            Delete
          </Button>
        )}
      </div>
    </div>
  );
}

/**
 * Get initials from user name
 */
function getInitials(name: string): string {
  const parts = name.trim().split(/\s+/);
  if (parts.length >= 2) {
    return (parts[0][0] + parts[1][0]).toUpperCase();
  }
  return name.substring(0, 2).toUpperCase();
}

import { MousePointer2 } from 'lucide-react';
import { useEffect, useRef } from 'react';

import type { CollabUser } from '@/hooks/collab/useCollabClient';

interface LiveCursorsLayerProps {
  users: CollabUser[];
  viewport: {
    x: number;
    y: number;
    zoom: number;
  };
}

/**
 * Render live cursors for remote users on the canvas
 */
export function LiveCursorsLayer({ users, viewport }: LiveCursorsLayerProps) {
  const cursorsWithPosition = users.filter((user) => user.cursor);

  return (
    <div className="absolute inset-0 pointer-events-none z-50">
      {cursorsWithPosition.map((user) => (
        <RemoteCursor key={user.userId} user={user} viewport={viewport} />
      ))}
    </div>
  );
}

interface RemoteCursorProps {
  user: CollabUser;
  viewport: {
    x: number;
    y: number;
    zoom: number;
  };
}

/**
 * Single remote cursor component
 */
function RemoteCursor({ user, viewport }: RemoteCursorProps) {
  const cursorRef = useRef<HTMLDivElement>(null);
  const lastPositionRef = useRef({ x: 0, y: 0 });

  useEffect(() => {
    if (!user.cursor || !cursorRef.current) {return;}

    const { x, y } = user.cursor;

    // Throttle cursor updates to ~30fps
    const now = Date.now();
    const lastUpdate = lastPositionRef.current;

    // Calculate screen position from canvas position
    const screenX = x * viewport.zoom + viewport.x;
    const screenY = y * viewport.zoom + viewport.y;

    // Use requestAnimationFrame for smooth updates
    requestAnimationFrame(() => {
      if (cursorRef.current) {
        cursorRef.current.style.transform = `translate(${screenX}px, ${screenY}px)`;
      }
    });

    lastPositionRef.current = { x, y };
  }, [user.cursor, viewport]);

  if (!user.cursor) {return null;}

  return (
    <div
      ref={cursorRef}
      className="absolute top-0 left-0 transition-transform duration-100"
      style={{ willChange: 'transform' }}
    >
      <MousePointer2
        className="w-5 h-5"
        style={{ color: user.color }}
        strokeWidth={2}
      />
      <div
        className="absolute left-6 top-0 px-2 py-1 rounded-md text-xs font-medium text-white shadow-lg whitespace-nowrap"
        style={{ backgroundColor: user.color }}
      >
        {user.displayName}
      </div>
    </div>
  );
}

import { Users, Sparkles, Feather } from 'lucide-react';
import React from 'react';

import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import type { CollabUser } from '@/hooks/collab/useCollabClient';

interface PresenceAvatarsProps {
  users: CollabUser[];
  maxVisible?: number;
}

/**
 * Display avatars of users currently collaborating on the workflow
 */
export function PresenceAvatars({ users, maxVisible = 5 }: PresenceAvatarsProps) {
  const visibleUsers = users.slice(0, maxVisible);
  const hiddenCount = Math.max(0, users.length - maxVisible);

  if (users.length === 0) {
    return null;
  }

  return (
    <TooltipProvider>
      <div className="flex items-center gap-2">
        <div className="flex items-center">
          <Users className="w-4 h-4 text-muted-foreground mr-2" />
          <span className="text-sm text-muted-foreground">{users.length} online</span>
        </div>

        <div className="flex -space-x-2">
          {visibleUsers.map((user) => (
            <Tooltip key={user.userId}>
              <TooltipTrigger asChild>
                <Avatar
                  className="w-8 h-8 border-2 border-background ring-2 ring-offset-0"
                  style={{ borderColor: user.color }}
                >
                  <AvatarFallback
                    className="text-xs font-semibold text-white"
                    style={{ backgroundColor: user.color }}
                  >
                    {getInitials(user.displayName)}
                  </AvatarFallback>
                </Avatar>
              </TooltipTrigger>
              <TooltipContent side="bottom" className="flex flex-col gap-1">
                <div className="font-semibold">{user.displayName}</div>
                <div className="text-xs text-muted-foreground">{user.email}</div>
                <div className="text-xs text-muted-foreground capitalize">{user.role}</div>
                {user.mode && (
                  <div className="flex items-center gap-1 text-[10px] bg-muted/50 px-1 py-0.5 rounded mt-1">
                    {user.mode === 'advanced' ? <Sparkles className="w-3 h-3 text-indigo-500" /> : <Feather className="w-3 h-3 text-emerald-500" />}
                    <span className="capitalize">{user.mode} Mode</span>
                  </div>
                )}
              </TooltipContent>
            </Tooltip>
          ))}

          {hiddenCount > 0 && (
            <Tooltip>
              <TooltipTrigger asChild>
                <Avatar className="w-8 h-8 border-2 border-background">
                  <AvatarFallback className="text-xs font-semibold bg-muted">
                    +{hiddenCount}
                  </AvatarFallback>
                </Avatar>
              </TooltipTrigger>
              <TooltipContent side="bottom">
                <div className="text-xs">
                  {hiddenCount} more {hiddenCount === 1 ? 'user' : 'users'}
