}

/**
 * Get initials from display name
 */
function getInitials(name: string): string {
  const parts = name.trim().split(/\s+/);
  if (parts.length >= 2) {
    return (parts[0][0] + parts[1][0]).toUpperCase();
  }
  return name.substring(0, 2).toUpperCase();
}

/**
 * CreateCollectionModal Component
 * Modal dialog for creating a new collection
 */

import { Loader2 } from "lucide-react";
import React, { useState } from "react";

import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";

interface CreateCollectionModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSubmit: (data: { name: string; slug?: string; description?: string }) => void;
  isLoading?: boolean;
}

export function CreateCollectionModal({
  open,
  onOpenChange,
  onSubmit,
  isLoading = false,
}: CreateCollectionModalProps) {
  const [name, setName] = useState("");
  const [slug, setSlug] = useState("");
  const [description, setDescription] = useState("");
  const [autoGenerateSlug, setAutoGenerateSlug] = useState(true);

  // Auto-generate slug from name
  const handleNameChange = (value: string) => {
    setName(value);
    if (autoGenerateSlug) {
      const generatedSlug = value
        .toLowerCase()
        .trim()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '');
      setSlug(generatedSlug);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) {return;}

    onSubmit({
      name: name.trim(),
      slug: slug.trim() || undefined,
      description: description.trim() || undefined,
    });

    // Reset form
    setName("");
    setSlug("");
    setDescription("");
    setAutoGenerateSlug(true);
  };

  const handleCancel = () => {
    setName("");
    setSlug("");
    setDescription("");
    setAutoGenerateSlug(true);
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px]">
        <form onSubmit={handleSubmit}>
          <DialogHeader>
            <DialogTitle>Create Collection</DialogTitle>
            <DialogDescription>
              Create a new data collection to store structured records.
            </DialogDescription>
          </DialogHeader>

          <div className="grid gap-4 py-4">
            <div className="grid gap-2">
              <Label htmlFor="name">
                Name <span className="text-destructive">*</span>
              </Label>
              <Input
                id="name"
                placeholder="e.g., Customers, Products, Orders"
                value={name}
                onChange={(e) => handleNameChange(e.target.value)}
                required
                autoFocus
                disabled={isLoading}
              />
            </div>

            <div className="grid gap-2">
              <Label htmlFor="slug">
                Slug
                <span className="text-xs text-muted-foreground ml-2">
                  (URL-safe identifier)
                </span>
              </Label>
              <Input
                id="slug"
                placeholder="e.g., customers, products, orders"
                value={slug}
                onChange={(e) => {
                  setSlug(e.target.value);
                  setAutoGenerateSlug(false);
                }}
                disabled={isLoading}
              />
              <p className="text-xs text-muted-foreground">
                {autoGenerateSlug ? "Auto-generated from name" : "Custom slug"}
              </p>
            </div>

            <div className="grid gap-2">
              <Label htmlFor="description">Description</Label>
              <Textarea
                id="description"
                placeholder="Describe what this collection stores..."
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                rows={3}
                disabled={isLoading}
              />
            </div>
          </div>

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={handleCancel}
              disabled={isLoading}
            >
              Cancel
            </Button>
            <Button type="submit" disabled={!name.trim() || isLoading}>
              {isLoading && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
              Create Collection
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

/**
 * CreateFieldModal Component
 * Modal dialog for creating/editing collection fields
 */

import { Loader2, Plus, X } from "lucide-react";
import React, { useState, useEffect } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import type { ApiCollectionField } from "@/lib/vault-api";

type FieldType = 'text' | 'number' | 'boolean' | 'date' | 'datetime' | 'file' | 'select' | 'multi_select' | 'json';

interface CreateFieldModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSubmit: (data: Omit<ApiCollectionField, 'id' | 'collectionId' | 'createdAt' | 'updatedAt'>) => void;
  isLoading?: boolean;
  field?: ApiCollectionField; // For editing existing field
}

const FIELD_TYPES: { value: FieldType; label: string; description: string }[] = [
  { value: 'text', label: 'Text', description: 'Single line text' },
  { value: 'number', label: 'Number', description: 'Numeric values' },
  { value: 'boolean', label: 'Boolean', description: 'True/false checkbox' },
  { value: 'date', label: 'Date', description: 'Date only' },
  { value: 'datetime', label: 'Date & Time', description: 'Date with time' },
  { value: 'file', label: 'File', description: 'File upload' },
  { value: 'select', label: 'Select', description: 'Single choice from options' },
  { value: 'multi_select', label: 'Multi-Select', description: 'Multiple choices' },
  { value: 'json', label: 'JSON', description: 'Structured data' },
];

export function CreateFieldModal({
  open,
  onOpenChange,
  onSubmit,
  isLoading = false,
  field,
}: CreateFieldModalProps) {
  const [name, setName] = useState("");
  const [slug, setSlug] = useState("");
  const [type, setType] = useState<FieldType>("text");
  const [isRequired, setIsRequired] = useState(false);
  const [autoGenerateSlug, setAutoGenerateSlug] = useState(true);

  // For select/multi-select
  const [options, setOptions] = useState<string[]>([]);
  const [newOption, setNewOption] = useState("");

  // Default value
  const [defaultValue, setDefaultValue] = useState("");

  // Initialize form for editing
  useEffect(() => {
    if (field) {
      setName(field.name);
      setSlug(field.slug);
      setType(field.type);
      setIsRequired(field.isRequired);
      setAutoGenerateSlug(false);

      if (field.options && Array.isArray(field.options)) {
        setOptions(field.options as string[]);
      }

      if (field.defaultValue !== null && field.defaultValue !== undefined) {
        setDefaultValue(String(field.defaultValue));
      }
    }
  }, [field]);

  // Auto-generate slug from name
  const handleNameChange = (value: string) => {
    setName(value);
    if (autoGenerateSlug && !field) {
      const generatedSlug = value
        .toLowerCase()
        .trim()
        .replace(/[^a-z0-9]+/g, '_')
        .replace(/^_+|_+$/g, '');
      setSlug(generatedSlug);
    }
  };

  const handleAddOption = () => {
    if (newOption.trim() && !options.includes(newOption.trim())) {
      setOptions([...options, newOption.trim()]);
      setNewOption("");
    }
  };

  const handleRemoveOption = (option: string) => {
    setOptions(options.filter(o => o !== option));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) { return; }

    // Validate select/multi-select has options
    if ((type === 'select' || type === 'multi_select') && options.length === 0) {
      return;
    }

    const fieldData: Omit<ApiCollectionField, 'id' | 'collectionId' | 'createdAt' | 'updatedAt'> = {
      name: name.trim(),
      slug: slug.trim(),
      type,
      isRequired,
      options: (type === 'select' || type === 'multi_select') ? options : null,
      defaultValue: defaultValue.trim() ? parseDefaultValue(type, defaultValue.trim()) : null,
    };

    onSubmit(fieldData);

    // Reset form
    if (!field) {
      resetForm();
    }
  };

  const parseDefaultValue = (type: FieldType, value: string): any => {
    switch (type) {
      case 'number':
        return Number(value);
      case 'boolean':
        return value === 'true';
      case 'multi_select':
        return value.split(',').map(v => v.trim());
      case 'json':
        try {
          return JSON.parse(value);
        } catch {
          return null;
        }
      default:
        return value;
    }
  };

  const resetForm = () => {
    setName("");
    setSlug("");
    setType("text");
    setIsRequired(false);
    setAutoGenerateSlug(true);
    setOptions([]);
    setNewOption("");
    setDefaultValue("");
  };

  const handleCancel = () => {
    if (!field) {
      resetForm();
    }
    onOpenChange(false);
  };

  const requiresOptions = type === 'select' || type === 'multi_select';

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[600px] max-h-[90vh] overflow-y-auto">
        <form onSubmit={handleSubmit}>
          <DialogHeader>
            <DialogTitle>{field ? 'Edit Field' : 'Create Field'}</DialogTitle>
            <DialogDescription>
              {field ? 'Update field properties and configuration.' : 'Add a new field to this collection.'}
            </DialogDescription>
          </DialogHeader>

          <div className="grid gap-4 py-4">
            <div className="grid gap-2">
              <Label htmlFor="name">
                Name <span className="text-destructive">*</span>
              </Label>
              <Input
                id="name"
                placeholder="e.g., Email, Age, Status"
                value={name}
                onChange={(e) => handleNameChange(e.target.value)}
                required
                autoFocus
                disabled={isLoading}
              />
            </div>

            <div className="grid gap-2">
              <Label htmlFor="slug">
                Slug <span className="text-xs text-muted-foreground">(field identifier)</span>
              </Label>
              <Input
                id="slug"
                placeholder="e.g., email, age, status"
                value={slug}
                onChange={(e) => {
                  setSlug(e.target.value);
                  setAutoGenerateSlug(false);
                }}
                disabled={isLoading}
              />
              <p className="text-xs text-muted-foreground">
                {autoGenerateSlug && !field ? "Auto-generated from name" : "Custom slug"}
              </p>
            </div>

            <div className="grid gap-2">
              <Label htmlFor="type">
                Type <span className="text-destructive">*</span>
              </Label>
              <Select value={type} onValueChange={(value) => setType(value as FieldType)} disabled={!!field || isLoading}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {FIELD_TYPES.map((ft) => (
                    <SelectItem key={ft.value} value={ft.value}>
                      <div className="flex flex-col">
                        <span className="font-medium">{ft.label}</span>
                        <span className="text-xs text-muted-foreground">{ft.description}</span>
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {field && (
                <p className="text-xs text-muted-foreground">Field type cannot be changed after creation</p>
              )}
            </div>

            <div className="flex items-center space-x-2">
              <Checkbox
                id="required"
                checked={isRequired}
                onCheckedChange={(checked) => setIsRequired(checked === true)}
                disabled={isLoading}
              />
              <Label htmlFor="required" className="cursor-pointer">
                Required field
              </Label>
            </div>

            {/* Options for select/multi-select */}
            {requiresOptions && (
              <div className="grid gap-2">
                <Label>
                  Options <span className="text-destructive">*</span>
                </Label>
                <div className="flex gap-2">
                  <Input
                    placeholder="Add option"
                    value={newOption}
                    onChange={(e) => setNewOption(e.target.value)}
                    onKeyPress={(e) => {
                      if (e.key === 'Enter') {
                        e.preventDefault();
                        handleAddOption();
                      }
                    }}
                    disabled={isLoading}
                  />
                  <Button
                    type="button"
                    variant="secondary"
                    size="icon"
                    onClick={handleAddOption}
                    disabled={!newOption.trim() || isLoading}
                  >
                    <Plus className="w-4 h-4" />
                  </Button>
                </div>
                <div className="flex flex-wrap gap-2">
                  {options.map((option) => (
                    <Badge key={option} variant="secondary" className="gap-1">
                      {option}
                      <X
                        className="w-3 h-3 cursor-pointer hover:text-destructive"
                        onClick={() => handleRemoveOption(option)}
                      />
                    </Badge>
                  ))}
                </div>
                {options.length === 0 && (
                  <p className="text-xs text-destructive">At least one option is required</p>
                )}
              </div>
            )}

            {/* Default value */}
            {type !== 'file' && (
              <div className="grid gap-2">
                <Label htmlFor="defaultValue">Default Value</Label>
                <Input
                  id="defaultValue"
                  placeholder={
                    type === 'boolean' ? 'true or false' :
                      type === 'multi_select' ? 'option1, option2' :
                        type === 'json' ? '{"key": "value"}' :
                          'Default value...'
                  }
                  value={defaultValue}
                  onChange={(e) => setDefaultValue(e.target.value)}
                  disabled={isLoading}
                />
              </div>
            )}
          </div>

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={handleCancel}
              disabled={isLoading}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={!name.trim() || !slug.trim() || (requiresOptions && options.length === 0) || isLoading}
            >
              {isLoading && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
              {field ? 'Update Field' : 'Create Field'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

/**
 * FieldsList Component
 * Displays list of fields in a collection with edit/delete actions
 */

import { Pencil, Trash2, Type, Hash, ToggleLeft, Calendar, FileIcon, List, Braces } from "lucide-react";
import React from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import type { ApiCollectionField } from "@/lib/vault-api";

interface FieldsListProps {
  fields: ApiCollectionField[];
  onEdit?: (field: ApiCollectionField) => void;
  onDelete?: (fieldId: string) => void;
}

const FIELD_TYPE_ICONS = {
  text: Type,
  number: Hash,
  boolean: ToggleLeft,
  date: Calendar,
  datetime: Calendar,
  file: FileIcon,
  select: List,
  multi_select: List,
  json: Braces,
};

const FIELD_TYPE_COLORS = {
  text: 'bg-blue-500/10 text-blue-600',
  number: 'bg-green-500/10 text-green-600',
  boolean: 'bg-purple-500/10 text-purple-600',
  date: 'bg-orange-500/10 text-orange-600',
  datetime: 'bg-orange-500/10 text-orange-600',
  file: 'bg-pink-500/10 text-pink-600',
  select: 'bg-indigo-500/10 text-indigo-600',
  multi_select: 'bg-indigo-500/10 text-indigo-600',
  json: 'bg-gray-500/10 text-gray-600',
};

export function FieldsList({ fields, onEdit, onDelete }: FieldsListProps) {
  if (fields.length === 0) {
    return (
      <Card>
        <CardContent className="pt-6">
          <p className="text-center text-muted-foreground">
            No fields yet. Add your first field to define the structure.
          </p>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-2">
      {fields.map((field) => {
        const Icon = FIELD_TYPE_ICONS[field.type] || Type;
        const colorClass = FIELD_TYPE_COLORS[field.type] || 'bg-gray-500/10 text-gray-600';

        return (
          <Card key={field.id} className="hover:shadow-md transition-shadow">
            <CardContent className="pt-6">
              <div className="flex items-start justify-between">
                <div className="flex items-start gap-3 flex-1">
                  <div className={`p-2 rounded-lg ${colorClass}`}>
                    <Icon className="w-5 h-5" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <h3 className="font-semibold">{field.name}</h3>
                      {field.isRequired && (
                        <Badge variant="destructive" className="text-xs">Required</Badge>
                      )}
                    </div>
                    <div className="flex items-center gap-2 mt-1">
                      <code className="text-xs bg-muted px-2 py-0.5 rounded">{field.slug}</code>
                      <Badge variant="secondary" className="text-xs capitalize">
                        {field.type.replace('_', ' ')}
                      </Badge>
                    </div>

                    {/* Options for select/multi-select */}
                    {field.options && Array.isArray(field.options) && field.options.length > 0 && (
                      <div className="mt-2">
                        <p className="text-xs text-muted-foreground mb-1">Options:</p>
                        <div className="flex flex-wrap gap-1">
                          {field.options.map((option, idx) => (
                            <Badge key={idx} variant="outline" className="text-xs">
                              {option as React.ReactNode}
                            </Badge>
                          ))}
                        </div>
                      </div>
                    )}

                    {/* Default value */}
                    {field.defaultValue !== null && field.defaultValue !== undefined && (
                      <div className="mt-2">
                        <p className="text-xs text-muted-foreground">
                          Default: <span className="font-mono">{String(field.defaultValue)}</span>
                        </p>
                      </div>
                    )}
                  </div>
                </div>

                <div className="flex items-center gap-1">
                  {onEdit && (
                    <Button
                      variant="ghost"
                      size="icon"
                      onClick={() => onEdit(field)}
                      title="Edit field"
                    >
                      <Pencil className="w-4 h-4" />
                    </Button>
                  )}
                  {onDelete && (
                    <Button
                      variant="ghost"
                      size="icon"
                      onClick={() => onDelete(field.id)}
                      title="Delete field"
                    >
                      <Trash2 className="w-4 h-4 text-destructive" />
                    </Button>
                  )}
                </div>
              </div>
            </CardContent>
          </Card>
        );
      })}
    </div>
  );
}

/**
 * RecordEditorModal Component
 * Dynamic form for creating/editing collection records
 */
import { Loader2 } from "lucide-react";
import React, { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import type { ApiCollectionField, ApiCollectionRecord } from "@/lib/vault-api";
interface RecordEditorModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  fields: ApiCollectionField[];
  record?: ApiCollectionRecord;
  onSubmit: (data: Record<string, any>) => Promise<void>;
  isLoading?: boolean;
}
export function RecordEditorModal({
  open,
  onOpenChange,
  fields,
  record,
  onSubmit,
  isLoading = false,
}: RecordEditorModalProps) {
  const isEditing = !!record;
  const [formData, setFormData] = useState<Record<string, any>>({});
  // Initialize form data from record or defaults
  useEffect(() => {
    if (open) {
      const initialData: Record<string, any> = {};
      fields.forEach((field) => {
        if (record) {
          // Editing: use existing value
          initialData[field.slug] = record.data[field.slug] ?? getDefaultValue(field);
        } else {
          // Creating: use default value
          initialData[field.slug] = getDefaultValue(field);
        }
      });
      setFormData(initialData);
    }
  }, [open, record, fields]);
  // Get default value for a field
  const getDefaultValue = (field: ApiCollectionField): any => {
    if (field.defaultValue !== null && field.defaultValue !== undefined) {
      return field.defaultValue;
    }
    switch (field.type) {
      case "boolean":
        return false;
      case "number":
        return "";
      case "multi_select":
        return [];
      case "json":
        return {};
      default:
        return "";
    }
  };
  // Update form field value
  const updateField = (slug: string, value: any) => {
    setFormData((prev) => ({ ...prev, [slug]: value }));
  };
  // Validate and submit
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    // Validate required fields
    const missingFields = fields
      .filter((field) => field.isRequired)
      .filter((field) => {
        const value = formData[field.slug];
        if (value === null || value === undefined || value === "") { return true; }
        if (Array.isArray(value) && value.length === 0) { return true; }
        return false;
      })
      .map((field) => field.name);
    if (missingFields.length > 0) {
      alert(`Please fill in required fields: ${missingFields.join(", ")}`);
      return;
    }
    // Clean up data (remove empty optional fields, convert types)
    const cleanedData: Record<string, any> = {};
    fields.forEach((field) => {
      let value = formData[field.slug];
      // Skip empty optional fields
      if (!field.isRequired && (value === "" || value === null || value === undefined)) {
        return;
      }
      // Type conversions
      if (field.type === "number" && value !== "" && value !== null) {
        value = Number(value);
      }
      if (field.type === "json" && typeof value === "string") {
        try {
          value = JSON.parse(value);
        } catch {
          // Keep as string if invalid JSON
        }
      }
      cleanedData[field.slug] = value;
    });
    await onSubmit(cleanedData);
  };
  // Render field input based on type
  const renderFieldInput = (field: ApiCollectionField) => {
    const value = formData[field.slug] ?? getDefaultValue(field);
    switch (field.type) {
      case "text":
        return (
          <Input
            value={value ?? ""}
            onChange={(e) => { void updateField(field.slug, e.target.value); }}
            placeholder={`Enter ${field.name.toLowerCase()}`}
          />
        );
      case "number":
        return (
          <Input
            type="number"
            value={value ?? ""}
            onChange={(e) => { void updateField(field.slug, e.target.value); }}
            placeholder="0"
          />
        );
      case "boolean":
        return (
          <div className="flex items-center gap-2">
            <Checkbox
              checked={value}
              onCheckedChange={(checked) => updateField(field.slug, checked)}
            />
            <span className="text-sm text-muted-foreground">
              {value ? "True" : "False"}
            </span>
          </div>
        );
      case "date":
        return (
          <Input
            type="date"
            value={value ?? ""}
            onChange={(e) => { void updateField(field.slug, e.target.value); }}
          />
        );
      case "datetime":
        return (
          <Input
            type="datetime-local"
            value={value ?? ""}
            onChange={(e) => { void updateField(field.slug, e.target.value); }}
          />
        );
      case "select":
        const selectOptions = Array.isArray(field.options) ? field.options as string[] : [];
        return (
          <Select
            value={value ?? ""}
            onValueChange={(val) => updateField(field.slug, val)}
          >
            <SelectTrigger>
              <SelectValue placeholder="Select an option" />
            </SelectTrigger>
            <SelectContent>
              {selectOptions.map((option) => (
                <SelectItem key={option} value={option}>
                  {option}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        );
      case "multi_select":
        const multiOptions = Array.isArray(field.options) ? field.options as string[] : [];
        const selectedValues = Array.isArray(value) ? value : [];
        return (
          <div className="space-y-2">
            {multiOptions.map((option) => (
              <div key={option} className="flex items-center gap-2">
                <Checkbox
                  checked={selectedValues.includes(option)}
                  onCheckedChange={(checked) => {
                    if (checked) {
                      updateField(field.slug, [...selectedValues, option]);
                    } else {
                      updateField(
                        field.slug,
                        selectedValues.filter((v) => v !== option)
                      );
                    }
                  }}
                />
                <Label className="font-normal">{option}</Label>
              </div>
            ))}
          </div>
        );
      case "file":
        return (
          <div className="space-y-2">
            <Input
              type="file"
              onChange={(e) => {
                const file = e.target.files?.[0];
                if (file) {
                  // For now, just store the filename
                  // TODO: Implement actual file upload in future
                  updateField(field.slug, file.name);
                }
              }}
            />
            {value && (
              <p className="text-sm text-muted-foreground">
                Current: {value}
              </p>
            )}
          </div>
        );
      case "json":
        const jsonValue = typeof value === "object" ? JSON.stringify(value, null, 2) : value;
        return (
          <Textarea
            value={jsonValue ?? ""}
            onChange={(e) => { void updateField(field.slug, e.target.value); }}
            placeholder='{"key": "value"}'
            className="font-mono text-sm"
            rows={4}
          />
        );
      default:
        return (
          <Textarea
            value={value ?? ""}
            onChange={(e) => { void updateField(field.slug, e.target.value); }}
            placeholder={`Enter ${field.name.toLowerCase()}`}
            rows={3}
          />
        );
    }
  };
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[80vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>
            {isEditing ? "Edit Record" : "Create Record"}
          </DialogTitle>
          <DialogDescription>
            {isEditing
              ? "Update the record details below."
              : "Fill in the details to create a new record."}
          </DialogDescription>
        </DialogHeader>
        <form onSubmit={(e) => { e.preventDefault(); void handleSubmit(e); }} className="space-y-6">
          {fields.map((field) => (
            <div key={field.id} className="space-y-2">
              <Label>
                {field.name}
                {field.isRequired && (
                  <span className="text-destructive ml-1">*</span>
                )}
              </Label>
              <div className="text-xs text-muted-foreground mb-1">
                <code>{field.slug}</code> ┬╖ {field.type}
              </div>
              {renderFieldInput(field)}
            </div>
          ))}
          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => { void onOpenChange(false); }}
              disabled={isLoading}
            >
              Cancel
            </Button>
            <Button type="submit" disabled={isLoading}>
              {isLoading && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
              {isEditing ? "Update Record" : "Create Record"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

/**
 * RecordTable Component
 * Displays collection records in a table format with type-specific rendering
 */
import { ChevronLeft, ChevronRight, FileIcon, CheckCircle2, XCircle, MoreVertical, Pencil, Trash2 } from "lucide-react";
import {  } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import type { ApiCollectionRecord, ApiCollectionField } from "@/lib/vault-api";
interface RecordTableProps {
  records: ApiCollectionRecord[];
  fields: ApiCollectionField[];
  isLoading?: boolean;
  page?: number;
  pageSize?: number;
  totalRecords?: number;
  onPageChange?: (page: number) => void;
  onRecordClick?: (record: ApiCollectionRecord) => void;
  onDelete?: (recordId: string) => void;
}
export function RecordTable({
  records,
  fields,
  isLoading = false,
  page = 1,
  pageSize = 50,
  totalRecords = 0,
  onPageChange,
  onRecordClick,
  onDelete,
}: RecordTableProps) {
  const totalPages = Math.ceil(totalRecords / pageSize);
  const hasNextPage = page < totalPages;
  const hasPrevPage = page > 1;
  // Render field value based on field type
  const renderFieldValue = (value: any, field: ApiCollectionField) => {
    if (value === null || value === undefined) {
      return <span className="text-muted-foreground italic">ΓÇö</span>;
    }
    switch (field.type) {
      case "boolean":
        return value ? (
          <CheckCircle2 className="w-4 h-4 text-green-600" />
        ) : (
          <XCircle className="w-4 h-4 text-red-600" />
        );
      case "date":
        try {
          return new Date(value).toLocaleDateString();
        } catch {
          return value;
        }
      case "datetime":
        try {
          return new Date(value).toLocaleString();
        } catch {
          return value;
        }
      case "file":
        if (typeof value === "string") {
          return (
            <div className="flex items-center gap-2">
              <FileIcon className="w-4 h-4 text-muted-foreground" />
              <span className="text-sm truncate max-w-[200px]">{value}</span>
            </div>
          );
        }
        return value;
      case "select":
        return <Badge variant="secondary">{value}</Badge>;
      case "multi_select":
        if (Array.isArray(value)) {
          return (
            <div className="flex flex-wrap gap-1">
              {value.map((v, idx) => (
                <Badge key={idx} variant="secondary" className="text-xs">
                  {v}
                </Badge>
              ))}
            </div>
          );
        }
        return value;
      case "json":
        return (
          <code className="text-xs bg-muted px-2 py-1 rounded">
            {JSON.stringify(value)}
          </code>
        );
      case "number":
        return <span className="font-mono">{value}</span>;
      case "text":
      default:
        const strValue = String(value);
        return (
          <span className="truncate max-w-[300px] block" title={strValue}>
            {strValue}
          </span>
        );
    }
  };
  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="text-muted-foreground">Loading records...</div>
      </div>
    );
  }
  if (records.length === 0) {
    return (
      <div className="text-center py-12">
        <p className="text-muted-foreground">No records found</p>
      </div>
    );
  }
  return (
    <div className="space-y-4">
      <div className="rounded-md border">
        <Table>
          <TableHeader>
            <TableRow>
              {fields.map((field) => (
                <TableHead key={field.id}>
                  <div className="flex items-center gap-2">
                    <span>{field.name}</span>
                    {field.isRequired && (
                      <span className="text-destructive text-xs">*</span>
                    )}
                  </div>
                  <code className="text-xs text-muted-foreground font-normal">
                    {field.slug}
                  </code>
                </TableHead>
              ))}
              {(onRecordClick || onDelete) && (
                <TableHead className="w-[50px]">
                  <span className="sr-only">Actions</span>
                </TableHead>
              )}
            </TableRow>
          </TableHeader>
          <TableBody>
            {records.map((record) => (
              <TableRow key={record.id}>
                {fields.map((field) => (
                  <TableCell
                    key={field.id}
                    className={onRecordClick && !onDelete ? "cursor-pointer" : ""}
                    onClick={onRecordClick && !onDelete ? () => onRecordClick(record) : undefined}
                  >
                    {renderFieldValue(record.data[field.slug], field)}
                  </TableCell>
                ))}
                {(onRecordClick || onDelete) && (
                  <TableCell>
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="ghost" size="icon" onClick={(e) => e.stopPropagation()}>
                          <MoreVertical className="w-4 h-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        {onRecordClick && (
                          <DropdownMenuItem onClick={() => onRecordClick(record)}>
                            <Pencil className="w-4 h-4 mr-2" />
                            Edit
                          </DropdownMenuItem>
                        )}
                        {onDelete && onRecordClick && <DropdownMenuSeparator />}
                        {onDelete && (
                          <DropdownMenuItem
                            className="text-destructive"
                            onClick={() => onDelete(record.id)}
                          >
                            <Trash2 className="w-4 h-4 mr-2" />
                            Delete
                          </DropdownMenuItem>
                        )}
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                )}
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>
      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between">
          <div className="text-sm text-muted-foreground">
            Page {page} of {totalPages} ({totalRecords} total records)
          </div>
          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => onPageChange?.(page - 1)}
              disabled={!hasPrevPage}
            >
              <ChevronLeft className="w-4 h-4 mr-1" />
              Previous
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={() => onPageChange?.(page + 1)}
              disabled={!hasNextPage}
            >
              Next
              <ChevronRight className="w-4 h-4 ml-1" />
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * Breadcrumbs Component
 * Reusable navigation breadcrumbs with links
 * DataVault Phase 2: PR 13
 */

import { ChevronRight, Home } from "lucide-react";
import React from "react";
import { Link } from "wouter";

import { cn } from "@/lib/utils";

export interface BreadcrumbItem {
  label: string;
  href?: string;
  icon?: React.ReactNode;
}

interface BreadcrumbsProps {
  items: BreadcrumbItem[];
  className?: string;
  showHome?: boolean;
}

export function Breadcrumbs({ items, className, showHome = true }: BreadcrumbsProps) {
  const allItems = showHome
    ? [{ label: "Home", href: "/", icon: <Home className="w-3 h-3" /> }, ...items]
    : items;

  return (
    <nav
      className={cn("flex items-center space-x-1 text-sm text-muted-foreground", className)}
      aria-label="Breadcrumb"
    >
      {allItems.map((item, index) => {
        const isLast = index === allItems.length - 1;

        return (
          <div key={index} className="flex items-center">
            {index > 0 && <ChevronRight className="w-4 h-4 mx-1 flex-shrink-0" />}

            {item.href && !isLast ? (
              <Link
                href={item.href}
                className="hover:text-foreground transition-colors flex items-center gap-1.5"
              >
                {item.icon}
                <span>{item.label}</span>
              </Link>
            ) : (
              <span
                className={cn(
                  "flex items-center gap-1.5",
                  isLast && "text-foreground font-medium"
                )}
              >
                {item.icon}
                {item.label}
              </span>
            )}
          </div>
        );
      })}
    </nav>
  );
}

/**
 * Enhanced Variable Picker Component
 * Supports selecting variables and list properties (list.count, list.rows[0].column, etc.)
 */

import { Copy, ChevronRight, ChevronDown, ListIcon } from "lucide-react";
import { useMemo, useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { useToast } from "@/hooks/use-toast";
import { cn } from "@/lib/utils";
import { type ApiWorkflowVariable } from "@/lib/vault-api";
import { useWorkflowVariables } from "@/lib/vault-hooks";

interface EnhancedVariablePickerProps {
  workflowId: string;
  onInsert: (path: string) => void;
  onCopy?: (path: string) => void;
  showListProperties?: boolean; // Show expandable list properties
}

export function EnhancedVariablePicker({
  workflowId,
  onInsert,
  onCopy,
  showListProperties = true,
}: EnhancedVariablePickerProps) {
  const { data: variables = [] } = useWorkflowVariables(workflowId);
  const { toast } = useToast();
  const [expandedVars, setExpandedVars] = useState<Set<string>>(new Set());

  // Group variables by section/page
  const grouped = useMemo(() => {
    const groups = new Map<string, ApiWorkflowVariable[]>();

    variables.forEach((variable) => {
      const sectionTitle = variable.sectionTitle || "Other";
      if (!groups.has(sectionTitle)) {
        groups.set(sectionTitle, []);
      }
      groups.get(sectionTitle)!.push(variable);
    });

    return Array.from(groups.entries());
  }, [variables]);

  const handleCopy = (path: string) => {
    navigator.clipboard.writeText(path);
    toast({
      title: "Copied",
      description: `Variable path "${path}" copied to clipboard`,
      duration: 2000,
    });
    if (onCopy) { onCopy(path); }
  };

  const isListType = (type: string) => {
    // Check if the type suggests a list/array
    return type === "query" || type === "read_table" || type === "list_tools" || type === "computed";
  };

  const toggleExpanded = (key: string) => {
    setExpandedVars((prev) => {
      const next = new Set(prev);
      if (next.has(key)) {
        next.delete(key);
      } else {
        next.add(key);
      }
      return next;
    });
  };

  if (variables.length === 0) {
    return (
      <div className="p-4 text-center text-sm text-muted-foreground">
        No variables available yet. Add questions to your pages to create variables.
      </div>
    );
  }

  return (
    <ScrollArea className="h-full">
      <div className="p-4 space-y-4">
        <div className="space-y-1">
          <h3 className="text-sm font-semibold">Variables</h3>
          <p className="text-xs text-muted-foreground">
            Click to insert variable paths into your code
          </p>
        </div>

        {grouped.map(([sectionTitle, vars]) => (
          <div key={sectionTitle} className="space-y-2">
            <h4 className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
              {sectionTitle}
            </h4>
            <div className="space-y-1">
              {vars.map((variable) => {
                const isExpanded = expandedVars.has(variable.key);
                const showExpand = showListProperties && isListType(variable.type);
                const variablePath = variable.alias || variable.key;

                return (
                  <div key={variable.key} className="space-y-0.5">
                    {/* Main Variable Row */}
                    <div
                      className={cn(
                        "flex items-center gap-2 p-2 rounded-md hover:bg-accent group",
                        isExpanded && "bg-accent/50"
                      )}
                    >
                      {/* Expand Button (if list) */}
                      {showExpand && (
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-5 w-5 p-0 shrink-0"
                          onClick={() => { void toggleExpanded(variable.key); }}
                          title={isExpanded ? "Collapse" : "Expand list properties"}
                        >
                          {isExpanded ? (
                            <ChevronDown className="h-3 w-3" />
                          ) : (
                            <ChevronRight className="h-3 w-3" />
                          )}
                        </Button>
                      )}

                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-0.5">
                          {showExpand && <ListIcon className="h-3 w-3 text-muted-foreground" />}
                          <span className="font-medium text-sm truncate font-mono">
                            {variablePath}
                          </span>
                          {variable.type && (
                            <Badge variant="outline" className="text-[10px] h-4 px-1 py-0 uppercase">
                              {variable.type.replace("_", " ")}
                            </Badge>
                          )}
                        </div>
                        {variable.label && (
                          <div className="text-xs text-muted-foreground truncate pl-1">
                            {variable.label}
                          </div>
                        )}
                      </div>

                      <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-6 w-6"
                          onClick={() => { void handleCopy(variablePath); }}
                          title="Copy path"
                        >
                          <Copy className="h-3 w-3" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-6 w-6"
                          onClick={() => { void onInsert(variablePath); }}
                          title="Insert path"
                        >
                          <ChevronRight className="h-3 w-3" />
                        </Button>
                      </div>
                    </div>

                    {/* Expanded List Properties */}
                    {showExpand && isExpanded && (
                      <div className="ml-9 space-y-0.5 border-l-2 border-muted pl-2">
                        {/* .count property */}
                        <div className="flex items-center gap-2 p-1.5 rounded-md hover:bg-accent/50 group/item">
                          <div className="flex-1 min-w-0">
                            <span className="font-mono text-xs text-muted-foreground">
                              {variablePath}.count
                            </span>
                            <div className="text-[10px] text-muted-foreground">
                              Number of rows in the list
                            </div>
                          </div>
                          <div className="flex items-center gap-1 opacity-0 group-hover/item:opacity-100 transition-opacity">
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-5 w-5"
                              onClick={() => { void handleCopy(`${variablePath}.count`); }}
                              title="Copy"
                            >
                              <Copy className="h-2.5 w-2.5" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-5 w-5"
                              onClick={() => { void onInsert(`${variablePath}.count`); }}
                              title="Insert"
                            >
                              <ChevronRight className="h-2.5 w-2.5" />
                            </Button>
                          </div>
                        </div>

                        {/* .rows property */}
                        <div className="flex items-center gap-2 p-1.5 rounded-md hover:bg-accent/50 group/item">
                          <div className="flex-1 min-w-0">
                            <span className="font-mono text-xs text-muted-foreground">
                              {variablePath}.rows
                            </span>
                            <div className="text-[10px] text-muted-foreground">
                              Array of row objects
                            </div>
                          </div>
                          <div className="flex items-center gap-1 opacity-0 group-hover/item:opacity-100 transition-opacity">
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-5 w-5"
                              onClick={() => { void handleCopy(`${variablePath}.rows`); }}
                              title="Copy"
                            >
                              <Copy className="h-2.5 w-2.5" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-5 w-5"
                              onClick={() => { void onInsert(`${variablePath}.rows`); }}
                              title="Insert"
                            >
                              <ChevronRight className="h-2.5 w-2.5" />
                            </Button>
                          </div>
                        </div>

                        {/* .rows[0] example */}
                        <div className="flex items-center gap-2 p-1.5 rounded-md hover:bg-accent/50 group/item">
                          <div className="flex-1 min-w-0">
                            <span className="font-mono text-xs text-muted-foreground">
                              {variablePath}.rows[0]
                            </span>
                            <div className="text-[10px] text-muted-foreground">
                              First row object (example)
                            </div>
                          </div>
                          <div className="flex items-center gap-1 opacity-0 group-hover/item:opacity-100 transition-opacity">
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-5 w-5"
                              onClick={() => { void handleCopy(`${variablePath}.rows[0]`); }}
                              title="Copy"
                            >
                              <Copy className="h-2.5 w-2.5" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-5 w-5"
                              onClick={() => { void onInsert(`${variablePath}.rows[0]`); }}
                              title="Insert"
                            >
                              <ChevronRight className="h-2.5 w-2.5" />
                            </Button>
                          </div>
                        </div>

                        {/* .columns property */}
                        <div className="flex items-center gap-2 p-1.5 rounded-md hover:bg-accent/50 group/item">
                          <div className="flex-1 min-w-0">
                            <span className="font-mono text-xs text-muted-foreground">
                              {variablePath}.columns
                            </span>
                            <div className="text-[10px] text-muted-foreground">
                              Column metadata array
                            </div>
                          </div>
                          <div className="flex items-center gap-1 opacity-0 group-hover/item:opacity-100 transition-opacity">
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-5 w-5"
                              onClick={() => { void handleCopy(`${variablePath}.columns`); }}
                              title="Copy"
                            >
                              <Copy className="h-2.5 w-2.5" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-5 w-5"
                              onClick={() => { void onInsert(`${variablePath}.columns`); }}
                              title="Insert"
                            >
                              <ChevronRight className="h-2.5 w-2.5" />
                            </Button>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        ))}
      </div>
    </ScrollArea>
  );
}

/**
 * VariableSelect - Dropdown selector for workflow variables (steps with aliases)
 *
 * This component displays all steps in a workflow, showing their alias (if available)
 * or key, allowing users to select variables for use in logic rules and blocks.
 */

import { Select, SelectContent, SelectGroup, SelectItem, SelectLabel, SelectTrigger, SelectValue } from "@/components/ui/select";
import { type ApiWorkflowVariable } from "@/lib/vault-api";
import { useWorkflowVariables } from "@/lib/vault-hooks";

interface VariableSelectProps {
  workflowId: string;
  value: string | null | undefined;
  onChange: (value: string) => void;
  placeholder?: string;
  disabled?: boolean;
}

export function VariableSelect({ workflowId, value, onChange, placeholder, disabled }: VariableSelectProps) {
  const { data: variables, isLoading } = useWorkflowVariables(workflowId);

  if (isLoading) {
    return (
      <Select disabled>
        <SelectTrigger>
          <SelectValue placeholder="Loading variables..." />
        </SelectTrigger>
      </Select>
    );
  }

  if (!variables || variables.length === 0) {
    return (
      <Select disabled>
        <SelectTrigger>
          <SelectValue placeholder="No variables available" />
        </SelectTrigger>
      </Select>
    );
  }

  // Group variables by section
  const variablesBySection = variables.reduce((acc, variable) => {
    const sectionId = variable.sectionId;
    if (!acc[sectionId]) {
      acc[sectionId] = {
        title: variable.sectionTitle,
        variables: [],
      };
    }
    acc[sectionId].variables.push(variable);
    return acc;
  }, {} as Record<string, { title: string; variables: ApiWorkflowVariable[] }>);

  return (
    <Select value={value || undefined} onValueChange={onChange} disabled={disabled}>
      <SelectTrigger className="font-mono text-sm">
        <SelectValue placeholder={placeholder || "Select a variable..."}>
          {value && (() => {
            const selectedVar = variables.find(v => v.key === value);
            return selectedVar ? (
              <span>
                {selectedVar.alias ? (
                  <span className="font-mono">
                    <span className="font-semibold text-primary">{selectedVar.alias}</span>
                    <span className="text-muted-foreground text-xs ml-2">({selectedVar.label})</span>
                  </span>
                ) : (
                  <span className="text-muted-foreground">
                    {selectedVar.label}
                  </span>
                )}
              </span>
            ) : value;
