/**
 * WorkflowCard Component
 * Displays a workflow document card with status
 */

import { FileText, Archive, Trash2, Play, Move, Link } from "lucide-react";

import { EntityCard, type EntityAction } from "@/components/shared/EntityCard";
import { Badge } from "@/components/ui/badge";
import { toast } from "@/hooks/use-toast";
import type { ApiWorkflow } from "@/lib/vault-api";
import { workflowAPI } from "@/lib/vault-api";

interface WorkflowCardProps {
  workflow: ApiWorkflow;
  onMove?: (workflow: ApiWorkflow) => void;
  onArchive?: (id: string) => void;
  onActivate?: (id: string) => void;
  onDelete?: (id: string) => void;
}

export function WorkflowCard({ workflow, onMove, onArchive, onActivate, onDelete }: WorkflowCardProps) {
  const statusVariant = workflow.status === "active" ? "default" : workflow.status === "draft" ? "secondary" : "outline";

  const handleCopyLink = async () => {
    try {
      const { publicUrl } = await workflowAPI.getPublicLink(workflow.id);
      await navigator.clipboard.writeText(publicUrl);
      toast({
        title: "Link copied!",
        description: "The workflow link has been copied to your clipboard.",
      });
    } catch (error) {
      toast({
        title: "Failed to copy link",
        description: error instanceof Error ? error.message : "An error occurred",
        variant: "destructive",
      });
    }
  };

  const actions: EntityAction[] = [
    {
      label: "Edit Builder",
      href: `/workflows/${workflow.id}/builder`,
    },
    {
      label: "Copy Link",
      icon: Link,
      onClick: handleCopyLink,
    },
  ];

  if (onMove) {
    actions.push({
      label: "Move to Project",
      icon: Move,
      onClick: () => onMove(workflow),
      separator: true,
    });
  }

  // Conditional activate/archive action
  if (workflow.status === "draft" || workflow.status === "archived") {
    actions.push({
      label: "Activate",
      icon: Play,
      onClick: () => onActivate?.(workflow.id),
      separator: !onMove, // Only add separator if no move action above
    });
  } else if (onArchive) {
    actions.push({
      label: "Archive",
      icon: Archive,
      onClick: () => onArchive(workflow.id),
      separator: !onMove, // Only add separator if no move action above
    });
  }

  if (onDelete) {
    actions.push({
      label: "Delete",
      icon: Trash2,
      onClick: () => onDelete(workflow.id),
      variant: "destructive",
      separator: true,
    });
  }

  return (
    <EntityCard
      entity={workflow}
      icon={FileText}
      iconClassName="bg-secondary/50 text-secondary-foreground"
      link={{ href: `/workflows/${workflow.id}/builder` }}
      actions={actions}
      renderBadge={() => (
        <div className="flex gap-2">
          {workflow.intakeConfig?.isIntake && (
            <Badge variant="secondary" className="bg-emerald-100 text-emerald-800 hover:bg-emerald-100">
              Intake
            </Badge>
          )}
          <Badge variant={statusVariant}>
            {workflow.status}
          </Badge>
        </div>
      )}
    />
  );
}

/**
 * Add Google Sheets Dialog
 * Guided onboarding flow for connecting Google Sheets
 */

import { FileSpreadsheet, Plus, CheckCircle } from "lucide-react";
import { useState } from "react";

import { Button } from "@/components/ui/button";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";

interface AddGoogleSheetsDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onComplete?: () => void;
}

type Step = 'auth' | 'select-spreadsheet' | 'select-sheet' | 'name';

export function AddGoogleSheetsDialog({ open, onOpenChange, onComplete }: AddGoogleSheetsDialogProps) {
    const { toast } = useToast();
    const [step, setStep] = useState<Step>('auth');
    const [isConnecting, setIsConnecting] = useState(false);
    const [selectedSpreadsheet, setSelectedSpreadsheet] = useState('');
    const [selectedSheet, setSelectedSheet] = useState('');
    const [connectionName, setConnectionName] = useState('');

    // Mock data for demo - would come from Google Sheets API
    const mockSpreadsheets = [
        { id: 'sheet1', name: 'Client Intake Responses' },
        { id: 'sheet2', name: 'Case Management Database' },
        { id: 'sheet3', name: 'Document Templates' },
    ];

    const mockSheets = [
        { id: 'tab1', name: 'Main Data' },
        { id: 'tab2', name: 'Archive' },
        { id: 'tab3', name: 'Reference' },
    ];

    const handleGoogleAuth = async () => {
        setIsConnecting(true);

        // Simulate OAuth flow
        await new Promise(resolve => setTimeout(resolve, 1000));

        setIsConnecting(false);
        setStep('select-spreadsheet');

        toast({
            title: "Connected to Google",
            description: "Select a spreadsheet to continue",
        });
    };

    const handleContinue = () => {
        if (step === 'select-spreadsheet' && selectedSpreadsheet) {
            setStep('select-sheet');
        } else if (step === 'select-sheet' && selectedSheet) {
            // Auto-generate name
            const spreadsheetName = mockSpreadsheets.find(s => s.id === selectedSpreadsheet)?.name || 'Google Sheets';
            setConnectionName(`${spreadsheetName} - Connection`);
            setStep('name');
        }
    };

    const handleComplete = async () => {
        setIsConnecting(true);

        try {
            // TODO: Call backend API to create data source
            await fetch('/api/data-sources', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify({
                    type: 'google_sheets',
                    name: connectionName,
                    metadata: {
                        spreadsheetId: selectedSpreadsheet,
                        sheetId: selectedSheet,
                    },
                }),
            });

            toast({
                title: "Google Sheets Connected",
                description: `${connectionName} is now available`,
            });

            onComplete?.();
            onOpenChange(false);

            // Reset state
            setStep('auth');
            setSelectedSpreadsheet('');
            setSelectedSheet('');
            setConnectionName('');
        } catch (error) {
            toast({
                title: "Connection Failed",
                description: error instanceof Error ? error.message : "Failed to connect",
                variant: "destructive",
            });
        } finally {
            setIsConnecting(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-md">
                <DialogHeader>
                    <div className="flex items-center gap-2">
                        <FileSpreadsheet className="w-5 h-5 text-green-600" />
                        <DialogTitle>Connect Google Sheets</DialogTitle>
                    </div>
                    <DialogDescription>
                        {step === 'auth' && 'Connect your Google account to access spreadsheets'}
                        {step === 'select-spreadsheet' && 'Choose a spreadsheet to connect'}
                        {step === 'select-sheet' && 'Select which sheet tab to use'}
                        {step === 'name' && 'Name this connection'}
                    </DialogDescription>
                </DialogHeader>

                <div className="py-4">
                    {/* Step 1: Google Auth */}
                    {step === 'auth' && (
                        <div className="text-center space-y-4">
                            <div className="p-8 bg-muted/50 rounded-lg">
                                <FileSpreadsheet className="w-16 h-16 mx-auto mb-4 text-green-600" />
                                <p className="text-sm text-muted-foreground">
                                    You'll be redirected to Google to authorize access to your spreadsheets.
                                </p>
                            </div>
                            <Button
                                onClick={() => { void handleGoogleAuth(); }}
                                disabled={isConnecting}
                                className="w-full"
                            >
                                {isConnecting ? 'Connecting...' : 'Connect to Google'}
                            </Button>
                        </div>
                    )}

                    {/* Step 2: Select Spreadsheet */}
                    {step === 'select-spreadsheet' && (
                        <div className="space-y-4">
                            <div className="flex items-center gap-2 text-sm text-green-600 mb-4">
                                <CheckCircle className="w-4 h-4" />
                                <span>Connected to Google</span>
                            </div>
                            <div className="space-y-2">
                                <Label>Spreadsheet</Label>
                                <Select value={selectedSpreadsheet} onValueChange={setSelectedSpreadsheet}>
                                    <SelectTrigger>
                                        <SelectValue placeholder="Select a spreadsheet" />
                                    </SelectTrigger>
                                    <SelectContent>
                                        {mockSpreadsheets.map(sheet => (
                                            <SelectItem key={sheet.id} value={sheet.id}>
                                                {sheet.name}
                                            </SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                            </div>
                        </div>
                    )}

                    {/* Step 3: Select Sheet Tab */}
                    {step === 'select-sheet' && (
                        <div className="space-y-4">
                            <div className="space-y-2">
                                <Label>Sheet Tab</Label>
                                <Select value={selectedSheet} onValueChange={setSelectedSheet}>
                                    <SelectTrigger>
                                        <SelectValue placeholder="Select a sheet tab" />
                                    </SelectTrigger>
                                    <SelectContent>
                                        {mockSheets.map(sheet => (
                                            <SelectItem key={sheet.id} value={sheet.id}>
                                                {sheet.name}
                                            </SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                            </div>
                        </div>
                    )}

                    {/* Step 4: Name Connection */}
                    {step === 'name' && (
                        <div className="space-y-4">
                            <div className="space-y-2">
                                <Label>Connection Name</Label>
                                <Input
                                    value={connectionName}
                                    onChange={(e) => { void setConnectionName(e.target.value); }}
                                    placeholder="e.g., Client Intake Data"
                                />
                                <p className="text-xs text-muted-foreground">
                                    This name will appear in your workflow blocks
                                </p>
                            </div>
                        </div>
                    )}
                </div>

                <DialogFooter>
                    {step !== 'auth' && (
                        <Button
                            variant="outline"
                            onClick={() => {
                                if (step === 'select-spreadsheet') {setStep('auth');}
                                if (step === 'select-sheet') {setStep('select-spreadsheet');}
                                if (step === 'name') {setStep('select-sheet');}
                            }}
                        >
                            Back
                        </Button>
                    )}

                    {step === 'select-spreadsheet' && (
                        <Button
                            onClick={() => { void handleContinue(); }}
                            disabled={!selectedSpreadsheet}
                        >
                            Continue
                        </Button>
                    )}

                    {step === 'select-sheet' && (
                        <Button
                            onClick={() => { void handleContinue(); }}
                            disabled={!selectedSheet}
                        >
                            Continue
                        </Button>
                    )}

                    {step === 'name' && (
                        <Button
                            onClick={() => { void handleComplete(); }}
                            disabled={!connectionName || isConnecting}
                        >
                            <Plus className="w-4 h-4 mr-2" />
                            {isConnecting ? 'Adding...' : 'Add Connection'}
                        </Button>
                    )}
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Loader2, Database, Table, Check, Search } from "lucide-react";
import { useState } from "react";

import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { ScrollArea } from "@/components/ui/scroll-area";
import { useToast } from "@/hooks/use-toast";
interface NativeCatalog {
    databases: {
        id: string;
        name: string;
        tables: { id: string; name: string }[];
    }[];
    orphanTables: { id: string; name: string }[];
}
interface AddNativeTableDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onComplete: () => void;
}
export function AddNativeTableDialog({ open, onOpenChange, onComplete }: AddNativeTableDialogProps) {
    const { toast } = useToast();
    const queryClient = useQueryClient();
    const [selectedTableId, setSelectedTableId] = useState<string | null>(null);
    const [selectedTableName, setSelectedTableName] = useState<string>("");
    const [selectedDatabaseId, setSelectedDatabaseId] = useState<string | null>(null);
    const [filter, setFilter] = useState("");
    const { data: catalog, isLoading } = useQuery<NativeCatalog>({
        queryKey: ["/api/data-sources/native/catalog"],
        enabled: open,
    });
    const createMutation = useMutation({
        mutationFn: async (data: { name: string; type: string; config: any }) => {
            const res = await fetch("/api/data-sources", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(data),
            });
            if (!res.ok) {
                const err = await res.json();
                throw new Error(err.message || "Failed to create data source");
            }
            return res.json();
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["/api/data-sources"] });
            toast({ title: "Success", description: "Native table added as data source." });
            onComplete();
            onOpenChange(false);
            setSelectedTableId(null);
            setSelectedTableName("");
            setSelectedDatabaseId(null);
        },
        onError: (err) => {
            toast({ title: "Error", description: err.message, variant: "destructive" });
        },
    });
    const handleAdd = () => {
        if (!selectedTableId) {return;}
        createMutation.mutate({
            name: selectedTableName || "Native Table",
            type: "native_table",
            config: {
                tableId: selectedTableId,
                databaseId: selectedDatabaseId,
            },
        });
    };
    const handleSelect = (tableId: string, tableName: string, databaseId: string | null) => {
        setSelectedTableId(tableId);
        setSelectedTableName(tableName);
        setSelectedDatabaseId(databaseId);
    };
    // Filter logic
    const filteredDatabases = catalog?.databases.map(db => ({
        ...db,
        tables: db.tables.filter(t => t.name.toLowerCase().includes(filter.toLowerCase()))
    })).filter(db => db.tables.length > 0) ?? [];
    const filteredOrphans = catalog?.orphanTables.filter(t => t.name.toLowerCase().includes(filter.toLowerCase())) ?? [];
    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-md h-[500px] flex flex-col">
                <DialogHeader>
                    <DialogTitle>Select Native Table</DialogTitle>
                    <DialogDescription>
