                                        <button
                                            key={table.id}
                                            onClick={() => { void handleSelect(table.id, table.name, null); }}
                                            className={`w-full flex items-center justify-between px-2 py-2 rounded-md text-sm transition-colors ${selectedTableId === table.id
                                                    ? "bg-primary text-primary-foreground"
                                                    : "hover:bg-accent hover:text-accent-foreground"
                                                }`}
                                        >
                                            <div className="flex items-center gap-2">
                                                <Table className="w-4 h-4 opacity-70" />
                                                <span>{table.name}</span>
                                            </div>
                                            {selectedTableId === table.id && <Check className="w-4 h-4" />}
                                        </button>
                                    ))}
                                </div>
                            )}
                            {filteredDatabases.length === 0 && filteredOrphans.length === 0 && (
                                <div className="text-center py-8 text-muted-foreground text-sm">
                                    No tables found.
                                </div>
                            )}
                        </div>
                    )}
                </ScrollArea>
                <DialogFooter className="mt-4">
                    <Button variant="outline" onClick={() => { void onOpenChange(false); }}>
                        Cancel
                    </Button>
                    <Button
                        onClick={() => { void handleAdd(); }}
                        disabled={!selectedTableId || createMutation.isPending}
                    >
                        {createMutation.isPending && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                        Add Data Source
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

/**
 * Add Row Button Component (PR 7)
 * Button to add a new row to the table
 */

import { Plus, Loader2 } from "lucide-react";
import React, { useState } from "react";

import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useToast } from "@/hooks/use-toast";
import { datavaultAPI } from "@/lib/datavault-api";

import type { DatavaultColumn } from "@shared/schema";

interface AddRowButtonProps {
  tableId: string;
  columns: DatavaultColumn[];
  onAdd: () => void;
}

export function AddRowButton({ tableId, columns, onAdd }: AddRowButtonProps) {
  const [open, setOpen] = useState(false);
  const [values, setValues] = useState<Record<string, any>>({});
  const [isLoading, setIsLoading] = useState(false);
  const { toast } = useToast();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      // Filter out empty values and auto-number fields
      const filteredValues: Record<string, any> = {};
      for (const [colId, value] of Object.entries(values)) {
        const column = columns.find(c => c.id === colId);
        if (column?.type === 'auto_number') {continue;} // Skip auto-number fields

        if (value !== undefined && value !== null && value !== '') {
          filteredValues[colId] = value;
        }
      }

      await datavaultAPI.createRow(tableId, filteredValues);

      toast({
        title: "Row added",
        description: "The new row has been created successfully.",
      });

      // Reset and close
      setValues({});
      setOpen(false);
      onAdd();
    } catch (error) {
      toast({
        title: "Failed to add row",
        description: error instanceof Error ? error.message : "An error occurred",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  const renderInput = (column: DatavaultColumn) => {
    const value = values[column.id];

    // Auto-number fields are read-only
    if (column.type === 'auto_number') {
      return (
        <Input
          type="number"
          disabled
          placeholder="Auto-generated"
          className="bg-muted"
        />
      );
    }

    switch (column.type) {
      case 'text':
      case 'email':
      case 'url':
        return (
          <Input
            type={column.type === 'email' ? 'email' : column.type === 'url' ? 'url' : 'text'}
            value={value ?? ''}
            onChange={(e) => setValues(prev => ({ ...prev, [column.id]: e.target.value }))}
            required={column.required}
          />
        );

      case 'number':
        return (
          <Input
            type="number"
            value={value ?? ''}
            onChange={(e) => setValues(prev => ({
              ...prev,
              [column.id]: e.target.value ? parseFloat(e.target.value) : null
            }))}
            required={column.required}
          />
        );

      case 'boolean':
        return (
          <div className="flex items-center space-x-2">
            <Checkbox
              checked={!!value}
              onCheckedChange={(checked) => setValues(prev => ({ ...prev, [column.id]: checked }))}
            />
            <span className="text-sm text-muted-foreground">
              {value ? 'Yes' : 'No'}
            </span>
          </div>
        );

      case 'date':
        return (
          <Input
            type="date"
            value={value ?? ''}
            onChange={(e) => setValues(prev => ({ ...prev, [column.id]: e.target.value }))}
            required={column.required}
          />
        );

      case 'datetime':
        return (
          <Input
            type="datetime-local"
            value={value ?? ''}
            onChange={(e) => setValues(prev => ({ ...prev, [column.id]: e.target.value }))}
            required={column.required}
          />
        );

      default:
        return (
          <Input
            type="text"
            value={value ?? ''}
            onChange={(e) => setValues(prev => ({ ...prev, [column.id]: e.target.value }))}
            required={column.required}
          />
        );
    }
  };

  return (
    <>
      <Button onClick={() => { void setOpen(true); }} size="sm" variant="outline">
        <Plus className="w-4 h-4 mr-2" />
        Add Row
      </Button>

      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent className="max-w-2xl max-h-[80vh] overflow-y-auto">
          <form onSubmit={(e) => { e.preventDefault(); void handleSubmit(e); }}>
            <DialogHeader>
              <DialogTitle>Add New Row</DialogTitle>
              <DialogDescription>
                Fill in the values for the new row. Required fields are marked with *.
              </DialogDescription>
            </DialogHeader>

            <div className="grid gap-4 py-4">
              {columns.map((column) => (
                <div key={column.id} className="grid gap-2">
                  <Label htmlFor={column.id}>
                    {column.name}
                    {column.required && <span className="text-red-500 ml-1">*</span>}
                    {column.isPrimaryKey && (
                      <span className="text-xs bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300 px-1.5 py-0.5 rounded ml-2">
                        PK
                      </span>
                    )}
                  </Label>
                  {renderInput(column)}
                </div>
              ))}
            </div>

            <DialogFooter>
              <Button type="button" variant="outline" onClick={() => { void setOpen(false); }}>
                Cancel
              </Button>
              <Button type="submit" disabled={isLoading}>
                {isLoading && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                Add Row
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </>
  );
}

/**
 * Cell Renderer Component (PR 7)
 * Renders editable cells based on column type
 * Supports: text, number, date, boolean
 * Future: email, url, reference fields
 */

import React, { useState, useEffect, useRef } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import type { ApiDatavaultRowWithValues } from "@/lib/datavault-api";
import type { DatavaultColumn, SelectOption } from "@/lib/types/datavault";

import { ReferenceCell } from "./ReferenceCell";

interface CellRendererProps {
  row: ApiDatavaultRowWithValues;
  column: DatavaultColumn;
  editing: boolean;
  onCommit: (value: any) => void;
  onCancel?: () => void;
  batchReferencesData?: Record<string, { displayValue: string; row: any }>;
}

// Helper: Render value based on column type (display mode)
function renderValue(value: any, type: string): string {
  if (value === null || value === undefined) {return "";}

  switch (type) {
    case "boolean":
      return value ? "Yes" : "No";
    case "date":
      if (value) {
        const date = new Date(value);
        return date.toLocaleDateString();
      }
      return "";
    case "datetime":
      if (value) {
        const date = new Date(value);
        return date.toLocaleString();
      }
      return "";
    case "number":
    case "auto_number":
      return typeof value === "number" ? value.toString() : value;
    default:
      return value.toString();
  }
}

export function CellRenderer({ row, column, editing, onCommit, onCancel, batchReferencesData }: CellRendererProps) {
  const value = row.values[column.id];
  const [editValue, setEditValue] = useState(value);
  const inputRef = useRef<HTMLInputElement>(null);

  // Update edit value when row value changes
  useEffect(() => {
    setEditValue(value);
  }, [value]);

  // Focus input when entering edit mode
  useEffect(() => {
    if (editing && inputRef.current) {
      inputRef.current.focus();
      inputRef.current.select();
    }
  }, [editing]);

  const handleSave = () => {
    onCommit(editValue);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter") {
      e.preventDefault();
      handleSave();
    } else if (e.key === "Escape") {
      e.preventDefault();
      setEditValue(value); // Revert
      onCancel?.();
    }
  };

  // Display mode
  if (!editing) {
    // Special handling for reference types
    if (column.type === "reference") {
      return <ReferenceCell value={value} column={column} batchData={batchReferencesData} />;
    }

    // Special handling for boolean types
    if (column.type === "boolean") {
      return (
        <div className="flex items-center">
          <Checkbox checked={!!value} disabled aria-label={column.name} />
        </div>
      );
    }

    // Special handling for select types
    if (column.type === "select" && value) {
      const option = column.options?.find(opt => opt.value === value);
      if (option) {
        const colorVar = option.color || 'blue';
        return (
          <Badge
            variant="outline"
            className="max-w-full truncate dark:border-opacity-50"
            style={{
              backgroundColor: `hsl(var(--${colorVar}-100) / 0.15)`,
              color: `hsl(var(--${colorVar}-700) / 1)`,
              borderColor: `hsl(var(--${colorVar}-300) / 0.5)`
            }}
            title={option.label}
          >
            {option.label}
          </Badge>
        );
      }
      return <span className="text-muted-foreground">{value}</span>;
    }

    // Special handling for multiselect types
    if (column.type === "multiselect" && Array.isArray(value) && value.length > 0) {
      const options = value.map(val => column.options?.find(opt => opt.value === val)).filter(Boolean);
      return (
        <div className="flex flex-wrap gap-1">
          {options.map((option, idx) => {
            const colorVar = option?.color || 'blue';
            return (
              <Badge
                key={idx}
                variant="outline"
                className="max-w-[150px] truncate dark:border-opacity-50"
                style={{
                  backgroundColor: `hsl(var(--${colorVar}-100) / 0.15)`,
                  color: `hsl(var(--${colorVar}-700) / 1)`,
                  borderColor: `hsl(var(--${colorVar}-300) / 0.5)`
                }}
                title={option?.label}
              >
                {option?.label}
              </Badge>
            );
          })}
        </div>
      );
    }

    return (
      <span className="truncate block" title={renderValue(value, column.type)}>
        {renderValue(value, column.type)}
      </span>
    );
  }

  // Edit mode - render appropriate input based on column type
  switch (column.type) {
    case "text":
    case "email":
    case "url":
      return (
        <EditableTextCell
          value={editValue}
          type={column.type}
          onCommit={onCommit}
          onChange={setEditValue}
          onKeyDown={handleKeyDown}
          inputRef={inputRef}
        />
      );

    case "number":
    case "auto_number":
      return (
        <NumberCell
          value={editValue}
          onCommit={onCommit}
          onChange={setEditValue}
          onKeyDown={handleKeyDown}
          inputRef={inputRef}
          readOnly={column.type === "auto_number"}
        />
      );

    case "boolean":
      return (
        <BooleanCell
          value={editValue}
          onCommit={onCommit}
        />
      );

    case "date":
      return (
        <DateCell
          value={editValue}
          onCommit={onCommit}
          onChange={setEditValue}
          onKeyDown={handleKeyDown}
          inputRef={inputRef}
        />
      );

    case "datetime":
      return (
        <DateTimeCell
          value={editValue}
          onCommit={onCommit}
          onChange={setEditValue}
          onKeyDown={handleKeyDown}
          inputRef={inputRef}
        />
      );

    case "reference":
      // Reference columns are read-only for now
      return <ReferenceCell value={editValue} column={column} />;

    case "select":
      return (
        <SelectCell
          value={editValue}
          options={column.options ?? []}
          onCommit={onCommit}
        />
      );

    case "multiselect":
      return (
        <MultiselectCell
          value={editValue}
          options={column.options ?? []}
          onCommit={onCommit}
        />
      );

    default:
      return <span className="text-muted-foreground">Unsupported type: {column.type}</span>;
  }
}

// Editable Text Cell
function EditableTextCell({
  value,
  type,
  onCommit,
  onChange,
  onKeyDown,
  inputRef
}: {
  value: any;
  type: string;
  onCommit: (v: any) => void;
  onChange: (v: any) => void;
  onKeyDown: (e: React.KeyboardEvent) => void;
  inputRef: React.RefObject<HTMLInputElement>;
}) {
  return (
    <Input
      ref={inputRef}
      type={type === "email" ? "email" : type === "url" ? "url" : "text"}
      value={value ?? ""}
      onChange={(e) => onChange(e.target.value)}
      onBlur={() => onCommit(value)}
      onKeyDown={onKeyDown}
      className="h-8 text-sm"
    />
  );
}

// Number Cell
function NumberCell({
  value,
  onCommit,
  onChange,
  onKeyDown,
  inputRef,
  readOnly = false
}: {
  value: any;
  onCommit: (v: any) => void;
  onChange: (v: any) => void;
  onKeyDown: (e: React.KeyboardEvent) => void;
  inputRef: React.RefObject<HTMLInputElement>;
  readOnly?: boolean;
}) {
  return (
    <Input
      ref={inputRef}
      type="number"
      value={value ?? ""}
      onChange={(e) => onChange(e.target.value ? parseFloat(e.target.value) : null)}
      onBlur={() => onCommit(value)}
      onKeyDown={onKeyDown}
      disabled={readOnly}
      className="h-8 text-sm"
    />
  );
}

// Boolean Cell
function BooleanCell({
  value,
  onCommit
}: {
  value: any;
  onCommit: (v: any) => void;
}) {
  return (
    <div className="flex items-center">
      <Checkbox
        checked={!!value}
        onCheckedChange={(checked) => onCommit(checked)}
        aria-label="Toggle value"
      />
    </div>
  );
}

// Date Cell
function DateCell({
  value,
  onCommit,
  onChange,
  onKeyDown,
  inputRef
}: {
  value: any;
  onCommit: (v: any) => void;
  onChange: (v: any) => void;
  onKeyDown: (e: React.KeyboardEvent) => void;
  inputRef: React.RefObject<HTMLInputElement>;
}) {
  // Convert to YYYY-MM-DD format
  const dateValue = value ? new Date(value).toISOString().split('T')[0] : "";

  return (
    <Input
      ref={inputRef}
      type="date"
      value={dateValue}
      onChange={(e) => onChange(e.target.value)}
      onBlur={() => onCommit(value)}
      onKeyDown={onKeyDown}
      className="h-8 text-sm"
    />
  );
}

// DateTime Cell
function DateTimeCell({
  value,
  onCommit,
  onChange,
  onKeyDown,
  inputRef
}: {
  value: any;
  onCommit: (v: any) => void;
  onChange: (v: any) => void;
  onKeyDown: (e: React.KeyboardEvent) => void;
  inputRef: React.RefObject<HTMLInputElement>;
}) {
  // Convert to datetime-local format (YYYY-MM-DDThh:mm)
  const dateTimeValue = value
    ? new Date(value).toISOString().slice(0, 16)
    : "";

  return (
    <Input
      ref={inputRef}
      type="datetime-local"
      value={dateTimeValue}
      onChange={(e) => onChange(e.target.value)}
      onBlur={() => onCommit(value)}
      onKeyDown={onKeyDown}
      className="h-8 text-sm"
    />
  );
}

// Select Cell
function SelectCell({
  value,
  options,
  onCommit
}: {
  value: any;
  options: SelectOption[];
  onCommit: (v: any) => void;
}) {
  return (
    <Select value={value ?? ""} onValueChange={onCommit}>
      <SelectTrigger className="h-8 text-sm focus:ring-2 focus:ring-primary">
        <SelectValue placeholder="Select..." />
      </SelectTrigger>
      <SelectContent>
        {options.map((option) => (
          <SelectItem
            key={option.value}
            value={option.value}
            className="focus:bg-accent focus:text-accent-foreground cursor-pointer"
          >
            <div className="flex items-center gap-2">
              <div
                className="w-3 h-3 rounded-full flex-shrink-0"
                style={{ backgroundColor: `hsl(var(--${option.color || 'blue'}-500) / 1)` }}
              />
              <span className="truncate max-w-[200px]" title={option.label}>
                {option.label}
              </span>
            </div>
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

// Multiselect Cell
function MultiselectCell({
  value,
  options,
  onCommit
}: {
  value: any;
  options: SelectOption[];
  onCommit: (v: any) => void;
}) {
  const [selectedValues, setSelectedValues] = useState<string[]>(Array.isArray(value) ? value : []);

  const toggleValue = (optionValue: string) => {
    const newValues = selectedValues.includes(optionValue)
      ? selectedValues.filter(v => v !== optionValue)
      : [...selectedValues, optionValue];
    setSelectedValues(newValues);
    onCommit(newValues);
  };

  const handleKeyDown = (e: React.KeyboardEvent, optionValue: string) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      toggleValue(optionValue);
    }
  };

  const selectedOptions = selectedValues.map(val => options.find(opt => opt.value === val)).filter(Boolean) as SelectOption[];

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button variant="outline" className="h-8 text-sm justify-start w-full focus:ring-2 focus:ring-primary">
          {selectedOptions.length > 0 ? (
            <div className="flex flex-wrap gap-1 max-w-full">
              {selectedOptions.map((option, idx) => (
                <Badge key={idx} variant="outline" className="text-xs max-w-[100px] truncate" title={option.label}>
                  {option.label}
                </Badge>
              ))}
            </div>
          ) : (
            <span className="text-muted-foreground">Select...</span>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-64 p-2 max-h-80 overflow-y-auto">
        <div className="space-y-1">
          {options.map((option) => (
            <div
              key={option.value}
              className="flex items-center gap-2 p-2 rounded hover:bg-accent cursor-pointer focus-within:bg-accent transition-colors"
              onClick={() => toggleValue(option.value)}
              onKeyDown={(e) => handleKeyDown(e, option.value)}
              tabIndex={0}
              role="option"
              aria-selected={selectedValues.includes(option.value)}
            >
              <Checkbox
                checked={selectedValues.includes(option.value)}
                onCheckedChange={() => toggleValue(option.value)}
                tabIndex={-1}
              />
              <div
                className="w-3 h-3 rounded-full flex-shrink-0"
                style={{ backgroundColor: `hsl(var(--${option.color || 'blue'}-500) / 1)` }}
              />
              <span className="text-sm truncate flex-1" title={option.label}>
                {option.label}
              </span>
            </div>
          ))}
        </div>
      </PopoverContent>
    </Popover>
  );
}

