import { ColumnTypeIcon, getColumnTypeColor } from "./ColumnTypeIcon";
interface ColumnManagerProps {
  columns: DatavaultColumn[];
  tableId: string;
  onAddColumn: (data: {
    name: string;
    type: string;
    required: boolean;
    description?: string;
    referenceTableId?: string;
    referenceDisplayColumnSlug?: string;
  }) => Promise<void>;
  onUpdateColumn: (columnId: string, data: { name: string; required: boolean; description?: string }) => Promise<void>;
  onDeleteColumn: (columnId: string) => Promise<void>;
  onReorderColumns?: (columnIds: string[]) => Promise<void>;
  isLoading?: boolean;
}
interface SortableColumnProps {
  column: DatavaultColumn;
  onEdit: () => void;
  onDelete: () => void;
  isLoading: boolean;
  canDelete: boolean;
}
function SortableColumn({ column, onEdit, onDelete, isLoading, canDelete }: SortableColumnProps) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: column.id });
  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };
  return (
    <div
      ref={setNodeRef}
      style={style}
      className="flex items-center justify-between p-3 border rounded-lg hover:bg-accent/50 transition-colors"
    >
      <div className="flex items-center space-x-3 flex-1 min-w-0">
        <div
          {...attributes}
          {...listeners}
          className="cursor-grab active:cursor-grabbing touch-none"
        >
          <GripVertical className="w-4 h-4 text-muted-foreground" />
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center space-x-2 flex-wrap">
            <ColumnTypeIcon type={column.type} className={getColumnTypeColor(column.type)} />
            <p className="font-medium truncate">{column.name}</p>
            {column.isPrimaryKey && (
              <span className="text-xs bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300 px-2 py-0.5 rounded font-semibold">
                ≡ƒöæ PRIMARY KEY
              </span>
            )}
            {column.isUnique && !column.isPrimaryKey && (
              <span className="text-xs bg-purple-100 text-purple-700 dark:bg-purple-900 dark:text-purple-300 px-2 py-0.5 rounded">
                Unique
              </span>
            )}
            {column.required && !column.isPrimaryKey && (
              <span className="text-xs bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-300 px-2 py-0.5 rounded">
                Required
              </span>
            )}
          </div>
          <p className="text-sm text-muted-foreground">
            Type: <span className="font-mono">{column.type}</span>
            {column.slug && (
              <span className="ml-3">
                Slug: <span className="font-mono">{column.slug}</span>
              </span>
            )}
          </p>
        </div>
      </div>
      <div className="flex items-center space-x-1">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => { void onEdit(); }}
          disabled={isLoading}
          title="Edit column"
        >
          <Edit2 className="w-4 h-4" />
        </Button>
        <Button
          variant="ghost"
          size="sm"
          onClick={() => { void onDelete(); }}
          disabled={isLoading || !canDelete}
          className="text-destructive hover:text-destructive disabled:opacity-50 disabled:cursor-not-allowed"
          title={
            !canDelete
              ? "Cannot delete the only primary key column"
              : "Delete column"
          }
        >
          <Trash2 className="w-4 h-4" />
        </Button>
      </div>
    </div>
  );
}
export function ColumnManagerWithDnd({
  columns,
  tableId,
  onAddColumn,
  onUpdateColumn,
  onDeleteColumn,
  onReorderColumns,
  isLoading = false,
}: ColumnManagerProps) {
  const { toast } = useToast();
  const [localColumns, setLocalColumns] = useState(columns);
  const [addDialogOpen, setAddDialogOpen] = useState(false);
  const [editDialog, setEditDialog] = useState<{ id: string; name: string; required: boolean } | null>(null);
  const [deleteConfirm, setDeleteConfirm] = useState<{ id: string; name: string } | null>(null);
  // Add column state
  const [newColumnName, setNewColumnName] = useState("");
  const [newColumnType, setNewColumnType] = useState<string>("text");
  const [newColumnRequired, setNewColumnRequired] = useState(false);
  const [newColumnDescription, setNewColumnDescription] = useState("");
  const [newReferenceTableId, setNewReferenceTableId] = useState<string>("");
  const [newReferenceDisplayColumnSlug, setNewReferenceDisplayColumnSlug] = useState<string>("");
  // Edit column state
  const [editColumnName, setEditColumnName] = useState("");
  const [editColumnRequired, setEditColumnRequired] = useState(false);
  const [editColumnDescription, setEditColumnDescription] = useState("");
  // Fetch tables for reference column dropdown
  const { data: tables } = useTables();
  // Fetch schema of selected reference table to get columns
  const { data: refTableSchema } = useTableSchema(newReferenceTableId || undefined);
  // Drag and drop sensors
  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );
  // Update local columns when props change
  // Update local columns when props change
  useEffect(() => { void setLocalColumns(columns); }, [columns]);
  // Listen for custom event from header button
  useEffect(() => {
    const handleOpenDialog = () => {
      setAddDialogOpen(true);
    };
    window.addEventListener('openAddColumnDialog', handleOpenDialog);
    return () => {
      window.removeEventListener('openAddColumnDialog', handleOpenDialog);
    };
  }, []);
  const handleDragEnd = async (event: DragEndEvent) => {
    const { active, over } = event;
    if (over && active.id !== over.id) {
      const oldIndex = localColumns.findIndex((col) => col.id === active.id);
      const newIndex = localColumns.findIndex((col) => col.id === over.id);
      const newColumns = arrayMove(localColumns, oldIndex, newIndex);
      setLocalColumns(newColumns);
      // Call reorder API
      if (onReorderColumns) {
        try {
          await onReorderColumns(newColumns.map((col) => col.id));
          toast({
            title: "Columns reordered",
            description: "Column order has been updated successfully.",
          });
        } catch (error) {
          // Revert on error
          setLocalColumns(columns);
          toast({
            title: "Failed to reorder columns",
            description: error instanceof Error ? error.message : "An error occurred",
            variant: "destructive",
          });
        }
      }
    }
  };
  const handleAddColumn = async () => {
    if (!newColumnName.trim()) {return;}
    // Validate reference column
    if (newColumnType === 'reference' && !newReferenceTableId) {
      toast({
        title: "Reference table required",
        description: "Please select a table to reference",
        variant: "destructive",
      });
      return;
    }
    await onAddColumn({
      name: newColumnName.trim(),
      type: newColumnType,
      required: newColumnRequired,
      description: newColumnDescription.trim() || undefined,
      referenceTableId: newColumnType === 'reference' ? newReferenceTableId : undefined,
      referenceDisplayColumnSlug: newColumnType === 'reference' ? newReferenceDisplayColumnSlug : undefined,
    });
    // Reset form
    setNewColumnName("");
    setNewColumnType("text");
    setNewColumnRequired(false);
    setNewColumnDescription("");
    setNewReferenceTableId("");
    setNewReferenceDisplayColumnSlug("");
    setAddDialogOpen(false);
  };
  const handleEditColumn = async () => {
    if (!editDialog || !editColumnName.trim()) {return;}
    try {
      await onUpdateColumn(editDialog.id, {
        name: editColumnName.trim(),
        required: editColumnRequired,
        description: editColumnDescription.trim() || undefined,
      });
      setEditDialog(null);
    } catch (error) {
      console.error('Failed to update column:', error);
    }
  };
  const handleDeleteColumn = async () => {
    if (!deleteConfirm) {return;}
    await onDeleteColumn(deleteConfirm.id);
    setDeleteConfirm(null);
  };
  const openEditDialog = (column: DatavaultColumn) => {
    setEditDialog({ id: column.id, name: column.name, required: column.required });
    setEditColumnName(column.name);
    setEditColumnRequired(column.required);
    setEditColumnDescription(column.description ?? "");
  };
  return (
    <>
      <div className="space-y-2">
        {localColumns.length === 0 ? (
          <div className="text-center py-8 text-muted-foreground">
            <p className="text-sm">No columns yet. Click "Add Column" above to get started.</p>
          </div>
        ) : (
          <DndContext
            sensors={sensors}
            collisionDetection={closestCenter}
            onDragEnd={handleDragEnd}
          >
            <SortableContext
              items={localColumns.map((col) => col.id)}
              strategy={verticalListSortingStrategy}
            >
              <div className="space-y-2">
                {localColumns.map((column) => (
                  <SortableColumn
                    key={column.id}
                    column={column}
                    onEdit={() => openEditDialog(column)}
                    onDelete={() => setDeleteConfirm({ id: column.id, name: column.name })}
                    isLoading={isLoading}
                    canDelete={!(column.isPrimaryKey && localColumns.filter(c => c.isPrimaryKey).length === 1)}
                  />
                ))}
              </div>
            </SortableContext>
          </DndContext>
        )}
      </div>
      {/* Add Column Dialog */}
      <Dialog open={addDialogOpen} onOpenChange={setAddDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Add Column</DialogTitle>
            <DialogDescription>Add a new column to the table</DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid gap-2">
              <Label htmlFor="column-name">
                Column Name <span className="text-destructive">*</span>
              </Label>
              <Input
                id="column-name"
                placeholder="e.g., Full Name, Email, Age"
                value={newColumnName}
                onChange={(e) => { void setNewColumnName(e.target.value); }}
                autoFocus
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="column-type">Type</Label>
              <Select value={newColumnType} onValueChange={(value) => {
                setNewColumnType(value);
                // Reset reference fields when changing away from reference type
                if (value !== 'reference') {
                  setNewReferenceTableId("");
                  setNewReferenceDisplayColumnSlug("");
                }
              }}>
                <SelectTrigger id="column-type">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="text">Text</SelectItem>
                  <SelectItem value="number">Number</SelectItem>
                  <SelectItem value="boolean">Boolean</SelectItem>
                  <SelectItem value="date">Date</SelectItem>
                  <SelectItem value="datetime">Date/Time</SelectItem>
                  <SelectItem value="email">Email</SelectItem>
                  <SelectItem value="phone">Phone</SelectItem>
                  <SelectItem value="url">URL</SelectItem>
                  <SelectItem value="json">JSON</SelectItem>
                  <SelectItem value="reference">≡ƒöù Reference</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="grid gap-2">
              <Label htmlFor="column-description">Description (optional)</Label>
              <Textarea
                id="column-description"
                placeholder="Describe this column's purpose..."
                value={newColumnDescription}
                onChange={(e) => { void setNewColumnDescription(e.target.value); }}
                rows={3}
              />
            </div>
            {/* Reference-specific fields */}
            {newColumnType === 'reference' && (
              <>
                <div className="grid gap-2">
                  <Label htmlFor="ref-table">
                    Reference Table <span className="text-destructive">*</span>
                  </Label>
                  <Select value={newReferenceTableId} onValueChange={setNewReferenceTableId}>
                    <SelectTrigger id="ref-table">
                      <SelectValue placeholder="Select a table..." />
                    </SelectTrigger>
                    <SelectContent>
                      {tables
                        ?.filter(t => t.id !== tableId) // Don't allow self-reference
                        .map((table) => (
                          <SelectItem key={table.id} value={table.id}>
                            {table.name}
                          </SelectItem>
                        ))}
                    </SelectContent>
                  </Select>
                </div>
                {newReferenceTableId && refTableSchema?.columns && (
                  <div className="grid gap-2">
                    <Label htmlFor="ref-display-column">Display Field (optional)</Label>
                    <Select
                      value={newReferenceDisplayColumnSlug}
                      onValueChange={setNewReferenceDisplayColumnSlug}
                    >
                      <SelectTrigger id="ref-display-column">
                        <SelectValue placeholder="Use row ID" />
                      </SelectTrigger>
                      <SelectContent>
                        {refTableSchema.columns.map((col) => (
                          <SelectItem key={col.id} value={col.slug}>
                            {col.name} ({col.type})
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                )}
              </>
            )}
            <div className="flex items-center space-x-2">
              <Checkbox
                id="column-required"
                checked={newColumnRequired}
                onCheckedChange={(checked) => setNewColumnRequired(checked as boolean)}
              />
              <Label htmlFor="column-required" className="cursor-pointer">
                Required field
              </Label>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => { void setAddDialogOpen(false); }}>
              Cancel
            </Button>
            <Button onClick={() => { void handleAddColumn(); }} disabled={!newColumnName.trim() || isLoading}>
              {isLoading && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
              Add Column
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
      {/* Edit Column Dialog */}
      <Dialog open={!!editDialog} onOpenChange={() => setEditDialog(null)}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Edit Column</DialogTitle>
            <DialogDescription>
              Update column name and settings. Type cannot be changed after creation.
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid gap-2">
              <Label htmlFor="edit-column-name">
                Column Name <span className="text-destructive">*</span>
              </Label>
              <Input
                id="edit-column-name"
                value={editColumnName}
                onChange={(e) => { void setEditColumnName(e.target.value); }}
                autoFocus
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="edit-column-description">Description (optional)</Label>
              <Textarea
                id="edit-column-description"
                placeholder="Describe this column's purpose..."
                value={editColumnDescription}
                onChange={(e) => { void setEditColumnDescription(e.target.value); }}
                rows={3}
              />
            </div>
            <div className="flex items-center space-x-2">
              <Checkbox
                id="edit-column-required"
                checked={editColumnRequired}
                onCheckedChange={(checked) => setEditColumnRequired(checked as boolean)}
              />
              <Label htmlFor="edit-column-required" className="cursor-pointer">
                Required field
              </Label>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => { void setEditDialog(null); }}>
              Cancel
            </Button>
            <Button onClick={() => { void handleEditColumn(); }} disabled={!editColumnName.trim() || isLoading}>
              {isLoading && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
              Save Changes
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
      {/* Delete Confirmation */}
      <AlertDialog open={!!deleteConfirm} onOpenChange={() => setDeleteConfirm(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Column?</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete the column "{deleteConfirm?.name}"? This will permanently
              delete all data in this column for all rows. This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => { void handleDeleteColumn(); }}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              disabled={isLoading}
            >
              {isLoading && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
              Delete Column
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

/**
 * Column Type Icon Component
 * Maps column data types to visual icons
 */

import {
  Type,
  Hash,
  ToggleLeft,
  Calendar,
  Clock,
  Mail,
  Phone,
  Link,
  FileJson,
  File,
  Link2,
} from "lucide-react";
import React from "react";

import { cn } from "@/lib/utils";

interface ColumnTypeIconProps {
  type: string;
  className?: string;
}

export function ColumnTypeIcon({ type, className }: ColumnTypeIconProps) {
  const iconProps = {
    className: cn("w-4 h-4", className),
    "aria-label": `${type} column type`,
  };

  switch (type) {
    case "text":
    case "long_text":
      return <Type {...iconProps} />;

    case "number":
    case "auto_number":
      return <Hash {...iconProps} />;

    case "boolean":
    case "yes_no":
      return <ToggleLeft {...iconProps} />;

    case "date":
      return <Calendar {...iconProps} />;

    case "datetime":
      return <Clock {...iconProps} />;

    case "email":
      return <Mail {...iconProps} />;

    case "phone":
      return <Phone {...iconProps} />;

    case "url":
      return <Link {...iconProps} />;

    case "json":
      return <FileJson {...iconProps} />;

    case "file_upload":
      return <File {...iconProps} />;

    case "reference":
      return <Link2 {...iconProps} />;

    default:
      return <Type {...iconProps} />;
  }
}

/**
 * Get color class for column type
 */
export function getColumnTypeColor(type: string): string {
  switch (type) {
    case "text":
    case "long_text":
      return "text-blue-600 dark:text-blue-400";

    case "number":
    case "auto_number":
      return "text-green-600 dark:text-green-400";

    case "boolean":
    case "yes_no":
      return "text-purple-600 dark:text-purple-400";

    case "date":
    case "datetime":
      return "text-orange-600 dark:text-orange-400";

    case "email":
      return "text-pink-600 dark:text-pink-400";

    case "phone":
      return "text-cyan-600 dark:text-cyan-400";

    case "url":
      return "text-indigo-600 dark:text-indigo-400";

    case "json":
      return "text-yellow-600 dark:text-yellow-400";

    case "file_upload":
      return "text-gray-600 dark:text-gray-400";

    case "reference":
      return "text-violet-600 dark:text-violet-400";

    default:
      return "text-muted-foreground";
  }
}

/**
 * Get human-readable type label
 */
export function getColumnTypeLabel(type: string): string {
  switch (type) {
    case "text":
      return "Text";
    case "long_text":
      return "Long Text";
    case "number":
      return "Number";
    case "auto_number":
      return "Auto Number";
    case "boolean":
      return "Boolean";
    case "yes_no":
      return "Yes/No";
    case "date":
      return "Date";
    case "datetime":
      return "Date & Time";
    case "email":
      return "Email";
    case "phone":
      return "Phone";
    case "url":
      return "URL";
    case "json":
      return "JSON";
    case "file_upload":
      return "File";
    case "reference":
      return "Reference";
    default:
      return type;
  }
}

/**
 * Create Database Modal Component
 * Modal for creating a new database with scope configuration
 * DataVault Phase 2: Databases feature
 */

import { Loader2, Info } from "lucide-react";
import React, { useState } from "react";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";

interface CreateDatabaseModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSubmit: (data: {
    name: string;
    description?: string;
    scopeType: 'account' | 'project' | 'workflow';
    scopeId?: string;
  }) => Promise<void>;
  isLoading: boolean;
}

export function CreateDatabaseModal({
  open,
  onOpenChange,
  onSubmit,
  isLoading,
}: CreateDatabaseModalProps) {
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [scopeType, setScopeType] = useState<'account' | 'project' | 'workflow'>('account');
  const [scopeId, setScopeId] = useState("");

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!name.trim()) {
      return;
    }

    // Validate scope configuration
    if ((scopeType === 'project' || scopeType === 'workflow') && !scopeId.trim()) {
      return;
    }

    await onSubmit({
      name: name.trim(),
      description: description.trim() || undefined,
      scopeType,
      scopeId: scopeId.trim() || undefined,
    });

    // Reset form
    setName("");
    setDescription("");
    setScopeType('account');
    setScopeId("");
  };

  const resetForm = () => {
    setName("");
    setDescription("");
    setScopeType('account');
    setScopeId("");
  };

  return (
    <Dialog
      open={open}
      onOpenChange={(isOpen) => {
        onOpenChange(isOpen);
        if (!isOpen) {
          resetForm();
        }
      }}
    >
      <DialogContent className="sm:max-w-[500px]">
        <form onSubmit={(e) => { e.preventDefault(); void handleSubmit(e); }}>
          <DialogHeader>
            <DialogTitle>Create Database</DialogTitle>
            <DialogDescription>
              Create a new database to organize your tables by project, workflow, or account.
            </DialogDescription>
          </DialogHeader>

          <div className="grid gap-4 py-4">
            {/* Name */}
            <div className="grid gap-2">
              <Label htmlFor="name">
                Name <span className="text-destructive">*</span>
              </Label>
              <Input
                id="name"
                placeholder="e.g., Customer Data, Product Catalog"
                value={name}
                onChange={(e) => { void setName(e.target.value); }}
                required
                autoFocus
              />
            </div>

            {/* Description */}
            <div className="grid gap-2">
              <Label htmlFor="description">Description</Label>
              <Textarea
                id="description"
                placeholder="Optional description of this database..."
                value={description}
                onChange={(e) => { void setDescription(e.target.value); }}
                rows={3}
              />
            </div>

            {/* Scope Type */}
            <div className="grid gap-2">
              <Label htmlFor="scopeType">
                Scope Type <span className="text-destructive">*</span>
              </Label>
              <Select
                value={scopeType}
                onValueChange={(value) => setScopeType(value as 'account' | 'project' | 'workflow')}
              >
                <SelectTrigger id="scopeType">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="account">
                    <div className="flex items-center gap-2">
                      <i className="fas fa-building"></i>
                      <span>Account</span>
                    </div>
                  </SelectItem>
                  <SelectItem value="project">
                    <div className="flex items-center gap-2">
                      <i className="fas fa-folder"></i>
                      <span>Project</span>
                    </div>
                  </SelectItem>
                  <SelectItem value="workflow">
                    <div className="flex items-center gap-2">
                      <i className="fas fa-sitemap"></i>
                      <span>Workflow</span>
                    </div>
                  </SelectItem>
                </SelectContent>
              </Select>
            </div>

            {/* Scope ID (conditionally shown) */}
            {(scopeType === 'project' || scopeType === 'workflow') && (
              <div className="grid gap-2">
                <Label htmlFor="scopeId">
                  {scopeType === 'project' ? 'Project ID' : 'Workflow ID'}{' '}
                  <span className="text-destructive">*</span>
                </Label>
                <Input
                  id="scopeId"
                  placeholder={`Enter ${scopeType} UUID`}
                  value={scopeId}
                  onChange={(e) => { void setScopeId(e.target.value); }}
                  required
                />
                <Alert>
                  <Info className="h-4 w-4" />
                  <AlertDescription className="text-xs">
                    This database will be scoped to a specific {scopeType}.
                    Provide the {scopeType} UUID.
                  </AlertDescription>
                </Alert>
              </div>
            )}

            {scopeType === 'account' && (
              <Alert>
                <Info className="h-4 w-4" />
                <AlertDescription className="text-xs">
                  Account-level databases are accessible across all projects and workflows in your account.
                </AlertDescription>
              </Alert>
            )}
          </div>

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => { void onOpenChange(false); }}
              disabled={isLoading}
            >
              Cancel
            </Button>
            <Button type="submit" disabled={isLoading}>
              {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Create Database
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

/**
 * CreateTableModal Component
 * Modal dialog for creating a new DataVault table with column definitions
 */

import { Loader2, Plus, Trash2 } from "lucide-react";
import React, { useState } from "react";

import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";

interface Column {
  name: string;
  type: 'text' | 'number' | 'boolean' | 'date' | 'datetime' | 'email' | 'phone' | 'url' | 'json' | 'auto_number';
  required: boolean;
}

interface CreateTableModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSubmit: (data: { name: string; slug?: string; description?: string; columns: Column[] }) => void;
  isLoading?: boolean;
}

export function CreateTableModal({
  open,
  onOpenChange,
  onSubmit,
  isLoading = false,
}: CreateTableModalProps) {
  const [name, setName] = useState("");
  const [slug, setSlug] = useState("");
  const [description, setDescription] = useState("");
  const [autoGenerateSlug, setAutoGenerateSlug] = useState(true);
  const [columns, setColumns] = useState<Column[]>([
    { name: "", type: "text", required: false }
  ]);

  // Auto-generate slug from name
  const handleNameChange = (value: string) => {
    setName(value);
    if (autoGenerateSlug) {
      const generatedSlug = value
        .toLowerCase()
        .trim()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '');
      setSlug(generatedSlug);
    }
  };

  const addColumn = () => {
    setColumns([...columns, { name: "", type: "text", required: false }]);
  };

  const removeColumn = (index: number) => {
    if (columns.length > 1) {
      setColumns(columns.filter((_, i) => i !== index));
    }
  };

  const updateColumn = (index: number, field: keyof Column, value: any) => {
    const updated = [...columns];
    updated[index] = { ...updated[index], [field]: value };
    setColumns(updated);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) {return;}

    // Filter out empty columns
    const validColumns = columns.filter(col => col.name.trim());
    if (validColumns.length === 0) {
      alert("Please add at least one column");
      return;
    }

    onSubmit({
      name: name.trim(),
      slug: slug.trim() || undefined,
      description: description.trim() || undefined,
      columns: validColumns,
    });

    // Reset form
    setName("");
    setSlug("");
    setDescription("");
    setAutoGenerateSlug(true);
    setColumns([{ name: "", type: "text", required: false }]);
  };

  const handleCancel = () => {
    setName("");
    setSlug("");
    setDescription("");
    setAutoGenerateSlug(true);
    setColumns([{ name: "", type: "text", required: false }]);
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[600px] max-h-[90vh] overflow-y-auto">
        <form onSubmit={handleSubmit}>
          <DialogHeader>
            <DialogTitle>Create Table</DialogTitle>
            <DialogDescription>
              Create a new data table with custom columns
            </DialogDescription>
          </DialogHeader>

          <div className="grid gap-4 py-4">
            <div className="grid gap-2">
              <Label htmlFor="name">
                Name <span className="text-destructive">*</span>
              </Label>
              <Input
                id="name"
                placeholder="e.g., People, Businesses, Contacts"
                value={name}
                onChange={(e) => handleNameChange(e.target.value)}
                required
                autoFocus
                disabled={isLoading}
              />
            </div>

            <div className="grid gap-2">
              <Label htmlFor="slug">
                Slug
                <span className="text-xs text-muted-foreground ml-2">
                  (URL-safe identifier)
                </span>
              </Label>
              <Input
                id="slug"
                placeholder="e.g., people, businesses, contacts"
                value={slug}
                onChange={(e) => {
                  setSlug(e.target.value);
                  setAutoGenerateSlug(false);
                }}
                disabled={isLoading}
              />
              <p className="text-xs text-muted-foreground">
                {autoGenerateSlug ? "Auto-generated from name" : "Custom slug"}
              </p>
            </div>

            <div className="grid gap-2">
              <Label htmlFor="description">Description</Label>
              <Textarea
                id="description"
                placeholder="Optional description"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                disabled={isLoading}
                rows={2}
              />
            </div>

            {/* Columns Section */}
            <div className="grid gap-3 border-t pt-4">
              <div className="flex items-center justify-between">
                <Label>
                  Columns <span className="text-destructive">*</span>
                </Label>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={addColumn}
                  disabled={isLoading}
                >
                  <Plus className="w-4 h-4 mr-1" />
                  Add Column
                </Button>
              </div>

              <div className="space-y-3">
                {columns.map((column, index) => (
                  <div key={index} className="grid grid-cols-[1fr_140px_80px_40px] gap-2 items-start">
                    <Input
                      placeholder="Column name"
                      value={column.name}
                      onChange={(e) => updateColumn(index, 'name', e.target.value)}
                      disabled={isLoading}
                    />
                    <Select
                      value={column.type}
                      onValueChange={(value) => updateColumn(index, 'type', value)}
                      disabled={isLoading}
                    >
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="auto_number">Auto Number</SelectItem>
                        <SelectItem value="text">Text</SelectItem>
                        <SelectItem value="number">Number</SelectItem>
                        <SelectItem value="boolean">Boolean</SelectItem>
                        <SelectItem value="date">Date</SelectItem>
                        <SelectItem value="datetime">Date/Time</SelectItem>
                        <SelectItem value="email">Email</SelectItem>
                        <SelectItem value="phone">Phone</SelectItem>
                        <SelectItem value="url">URL</SelectItem>
                        <SelectItem value="json">JSON</SelectItem>
                      </SelectContent>
                    </Select>
                    <div className="flex items-center space-x-2 pt-2">
                      <Checkbox
                        id={`required-${index}`}
                        checked={column.required}
                        onCheckedChange={(checked) => updateColumn(index, 'required', checked)}
                        disabled={isLoading}
                      />
                      <Label htmlFor={`required-${index}`} className="text-xs">Req</Label>
                    </div>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={() => removeColumn(index)}
                      disabled={isLoading || columns.length === 1}
                      className="h-9"
                    >
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </div>
                ))}
              </div>
            </div>
          </div>

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={handleCancel}
              disabled={isLoading}
            >
              Cancel
            </Button>
            <Button type="submit" disabled={isLoading || !name.trim()}>
              {isLoading && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
              Create Table
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

/**
 * DataGrid Component
 * Displays table data in a responsive grid with edit/delete actions
 */

import { MoreVertical, Edit2, Trash2, Archive, ArchiveRestore, ArrowUp, ArrowDown, ArrowUpDown, GripVertical } from "lucide-react";
import React, { useState, useRef, useEffect } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import type { ApiDatavaultRowWithValues } from "@/lib/datavault-api";

import type { DatavaultColumn } from "@shared/schema";

interface DataGridProps {
  columns: DatavaultColumn[];
  rows: ApiDatavaultRowWithValues[];
  selectedRowIds?: Set<string>;
  sortBy?: string;
  sortOrder?: 'asc' | 'desc';
  onSelectRow?: (rowId: string, selected: boolean) => void;
  onSelectAll?: (selected: boolean) => void;
  onSort?: (columnSlug: string) => void;
  onColumnResize?: (columnId: string, widthPx: number) => void;
  onEditRow: (rowId: string, values: Record<string, any>) => void;
  onDeleteRow: (rowId: string) => void;
  onArchiveRow?: (rowId: string) => void;
  onUnarchiveRow?: (rowId: string) => void;
}

export function DataGrid({
  columns,
  rows,
  selectedRowIds,
  sortBy,
  sortOrder,
  onSelectRow,
  onSelectAll,
  onSort,
  onColumnResize,
  onEditRow,
  onDeleteRow,
  onArchiveRow,
  onUnarchiveRow,
}: DataGridProps) {
  const [resizingColumn, setResizingColumn] = useState<string | null>(null);
  const [columnWidths, setColumnWidths] = useState<Record<string, number>>(() => {
    const widths: Record<string, number> = {};
    columns.forEach((col) => {
      widths[col.id] = col.widthPx ?? 150;
    });
    return widths;
  });
  const resizeStartX = useRef<number>(0);
  const resizeStartWidth = useRef<number>(0);
  const formatValue = (value: any, type: string): string => {
    if (value === null || value === undefined) {return "-";}

    switch (type) {
      case "boolean":
        return value ? "Yes" : "No";
      case "date":
        return value ? new Date(value).toLocaleDateString() : "-";
      case "datetime":
        return value ? new Date(value).toLocaleString() : "-";
      case "json":
        return typeof value === "object" ? JSON.stringify(value) : String(value);
      default:
        return String(value);
    }
  };

  // Resize handlers
  const handleResizeStart = (columnId: string, e: React.MouseEvent) => {
    e.preventDefault();
    setResizingColumn(columnId);
    resizeStartX.current = e.clientX;
    resizeStartWidth.current = columnWidths[columnId] || 150;
  };

  const handleResizeMove = (e: MouseEvent) => {
    if (!resizingColumn) {return;}

    const delta = e.clientX - resizeStartX.current;
    const newWidth = Math.max(80, resizeStartWidth.current + delta); // Min width 80px

    setColumnWidths((prev) => ({
      ...prev,
      [resizingColumn]: newWidth,
    }));
  };

  const handleResizeEnd = () => {
    if (resizingColumn && onColumnResize) {
      onColumnResize(resizingColumn, columnWidths[resizingColumn]);
    }
    setResizingColumn(null);
  };

  // Add mouse event listeners for resize
  useEffect(() => {
    if (resizingColumn) {
      document.addEventListener('mousemove', handleResizeMove);
      document.addEventListener('mouseup', handleResizeEnd);
      return () => {
        document.removeEventListener('mousemove', handleResizeMove);
        document.removeEventListener('mouseup', handleResizeEnd);
      };
    }
  }, [resizingColumn, columnWidths]);

  if (columns.length === 0) {
    return (
      <div className="text-center py-8 text-muted-foreground">
        <p>No columns defined</p>
      </div>
    );
  }



  const allRowIds = rows.map((r) => r.row.id);
  const allSelected = selectedRowIds && allRowIds.length > 0 && allRowIds.every((id) => selectedRowIds.has(id));
  const someSelected = selectedRowIds && allRowIds.some((id) => selectedRowIds.has(id)) && !allSelected;

  return (
    <div className="border rounded-lg overflow-hidden">
      <div className="overflow-x-auto">
        <Table>
          <TableHeader>
            <TableRow>
              {onSelectAll && (
                <TableHead className="w-[50px] border-r border-border">
                  <Checkbox
                    checked={allSelected}
                    onCheckedChange={(checked) => onSelectAll(!!checked)}
                    aria-label="Select all rows"
                    className={someSelected ? "data-[state=checked]:bg-primary/50" : ""}
                  />
                </TableHead>
              )}
              {columns.map((column, index) => {
                const isSorted = sortBy === column.slug;
                const SortIcon = isSorted
                  ? sortOrder === 'asc'
                    ? ArrowUp
                    : ArrowDown
                  : ArrowUpDown;

                return (
                  <TableHead
                    key={column.id}
                    className={`whitespace-nowrap relative border-r border-border ${isSorted ? 'bg-primary/10' : ''
                      }`}
                    style={{ width: `${columnWidths[column.id] || 150}px`, minWidth: '80px' }}
                  >
                    <div className="flex items-center gap-2 pr-2 relative z-10">
                      <span>
                        {column.name}
                        {column.required && <span className="text-destructive ml-1">*</span>}
                      </span>
                      {onSort && (
                        <Button
                          variant="ghost"
                          size="sm"
                          className={`h-6 w-6 p-0 ${isSorted ? 'text-primary' : ''}`}
                          onClick={(e) => {
                            e.stopPropagation();
                            onSort(column.slug);
                          }}
                        >
                          <SortIcon className="h-4 w-4" />
                        </Button>
                      )}
                    </div>
                    {/* Resize handle */}
                    {onColumnResize && (
                      <div
                        className="absolute right-0 top-0 bottom-0 w-2 cursor-col-resize hover:bg-primary/50 group z-20"
                        onMouseDown={(e) => {
                          e.stopPropagation();
                          handleResizeStart(column.id, e);
                        }}
                      >
                        <div className="absolute right-0 top-1/2 -translate-y-1/2 opacity-0 group-hover:opacity-100">
                          <GripVertical className="h-4 w-4 text-muted-foreground" />
                        </div>
                      </div>
                    )}
                  </TableHead>
                );
              })}
              <TableHead className="w-[50px]">Actions</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {rows.length === 0 && (
              <TableRow>
                <TableCell
                  colSpan={columns.length + (onSelectAll ? 1 : 0) + 1}
                  className="h-24 text-center text-muted-foreground"
                >
                  No data yet
                </TableCell>
              </TableRow>
            )}
            {rows.map((rowData) => {
              const isArchived = !!rowData.row.deletedAt;
              const isSelected = selectedRowIds?.has(rowData.row.id) ?? false;

              return (
                <TableRow key={rowData.row.id} className={isArchived ? "opacity-60" : undefined}>
                  {onSelectRow && (
                    <TableCell className="border-r border-border">
                      <Checkbox
                        checked={isSelected}
                        onCheckedChange={(checked) => onSelectRow(rowData.row.id, !!checked)}
                        aria-label={`Select row ${rowData.row.id}`}
                      />
                    </TableCell>
                  )}
                  {columns.map((column, idx) => {
                    const isSorted = sortBy === column.slug;
                    return (
                      <TableCell
                        key={column.id}
                        className={`truncate border-r border-border ${isSorted ? 'bg-primary/5' : ''}`}
                        style={{ width: `${columnWidths[column.id] || 150}px`, minWidth: '80px', maxWidth: `${columnWidths[column.id] || 150}px` }}
                      >
                        {idx === 0 && isArchived && (
                          <Badge variant="secondary" className="mr-2 text-xs">
                            Archived
                          </Badge>
                        )}
                        {formatValue(rowData.values[column.id], column.type)}
                      </TableCell>
                    );
                  })}
                  <TableCell>
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                          <MoreVertical className="h-4 w-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem
                          onClick={() => onEditRow(rowData.row.id, rowData.values)}
                          disabled={isArchived}
                        >
                          <Edit2 className="w-4 h-4 mr-2" />
                          Edit
                        </DropdownMenuItem>
                        <DropdownMenuSeparator />
                        {isArchived ? (
                          <>
                            {onUnarchiveRow && (
                              <DropdownMenuItem onClick={() => onUnarchiveRow(rowData.row.id)}>
                                <ArchiveRestore className="w-4 h-4 mr-2" />
                                Restore
                              </DropdownMenuItem>
                            )}
                          </>
                        ) : (
                          <>
                            {onArchiveRow && (
                              <DropdownMenuItem onClick={() => onArchiveRow(rowData.row.id)}>
                                <Archive className="w-4 h-4 mr-2" />
                                Archive
                              </DropdownMenuItem>
                            )}
                          </>
                        )}
                        <DropdownMenuSeparator />
                        <DropdownMenuItem
                          onClick={() => onDeleteRow(rowData.row.id)}
                          className="text-destructive focus:text-destructive"
                        >
                          <Trash2 className="w-4 h-4 mr-2" />
                          Delete Permanently
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              );
            })}
          </TableBody>
        </Table>
      </div>
    </div>
  );
}

/**
 * DataGrid Empty State Component
 * Empty states for the data grid (no rows, filtered empty, no archived)
 */

import { Database, Filter, Archive } from "lucide-react";

import { Button } from "@/components/ui/button";

type EmptyStateVariant = "no_rows" | "filtered_empty" | "no_archived";

interface DataGridEmptyStateProps {
  variant: EmptyStateVariant;
  onAddRow?: () => void;
  onClearFilters?: () => void;
  onShowAll?: () => void;
}

const emptyStateConfig = {
  no_rows: {
    icon: Database,
    title: "No rows yet",
    description: "Get started by adding your first row to this table.",
    actionLabel: "Add Row",
  },
  filtered_empty: {
    icon: Filter,
    title: "No matching rows",
    description: "Try adjusting your filters or search criteria.",
    actionLabel: "Clear Filters",
  },
  no_archived: {
    icon: Archive,
    title: "No archived rows",
    description: "Archived rows will appear here when you archive them.",
    actionLabel: "Show All Rows",
  },
};

export function DataGridEmptyState({
  variant,
  onAddRow,
  onClearFilters,
  onShowAll,
}: DataGridEmptyStateProps) {
  const config = emptyStateConfig[variant];
  const Icon = config.icon;

  const handleAction = () => {
    if (variant === "no_rows" && onAddRow) {
      onAddRow();
    } else if (variant === "filtered_empty" && onClearFilters) {
      onClearFilters();
    } else if (variant === "no_archived" && onShowAll) {
      onShowAll();
    }
  };

  const showAction =
    (variant === "no_rows" && onAddRow) ||
    (variant === "filtered_empty" && onClearFilters) ||
    (variant === "no_archived" && onShowAll);

  return (
    <div className="border rounded-lg bg-muted/10 flex flex-col items-center justify-center py-16 px-4 text-center">
      <div className="rounded-full bg-muted p-4 mb-4">
        <Icon className="h-8 w-8 text-muted-foreground" />
      </div>
      <h3 className="text-lg font-semibold mb-2">{config.title}</h3>
      <p className="text-sm text-muted-foreground mb-4 max-w-sm">
        {config.description}
      </p>
      {showAction && (
        <Button onClick={handleAction} variant="outline">
          {config.actionLabel}
        </Button>
      )}
    </div>
  );
}

/**
 * Database API Tokens Component
 * Manage API tokens for external access to DataVault databases
 * DataVault v4 Micro-Phase 5: PR 10
 */

import { Loader2, Plus, Trash2, Key, Copy, Check, AlertTriangle, Calendar } from "lucide-react";
import { useState } from "react";

import { Alert, AlertDescription } from "@/components/ui/alert";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useToast } from "@/hooks/use-toast";
import {
  useDatavaultApiTokens,
  useCreateApiToken,
  useDeleteApiToken,
} from "@/lib/datavault-hooks";

interface DatabaseApiTokensProps {
  databaseId: string;
}

export function DatabaseApiTokens({ databaseId }: DatabaseApiTokensProps) {
  const { toast } = useToast();
  const { data, isLoading } = useDatavaultApiTokens(databaseId);
  const createMutation = useCreateApiToken();
  const deleteMutation = useDeleteApiToken();

  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [isTokenRevealOpen, setIsTokenRevealOpen] = useState(false);
  const [plainToken, setPlainToken] = useState<string>("");
  const [tokenLabel, setTokenLabel] = useState<string>("");
  const [copiedToken, setCopiedToken] = useState(false);
  const [deleteTokenId, setDeleteTokenId] = useState<string | null>(null);

  // Create token form state
  const [label, setLabel] = useState("");
  const [readScope, setReadScope] = useState(true);
  const [writeScope, setWriteScope] = useState(false);
  const [expiresAt, setExpiresAt] = useState("");

  const handleCreateToken = async () => {
    if (!label.trim()) {
      toast({
        title: "Label required",
        description: "Please enter a label for the token",
        variant: "destructive",
      });
      return;
    }

    const scopes: ('read' | 'write')[] = [];
    if (readScope) {scopes.push('read');}
    if (writeScope) {scopes.push('write');}

    if (scopes.length === 0) {
      toast({
        title: "Scope required",
        description: "Please select at least one scope (Read or Write) for the API token",
        variant: "destructive",
      });
      return;
    }

    // Validate expiration date is in the future
    if (expiresAt) {
      const expirationDate = new Date(expiresAt);
      if (expirationDate <= new Date()) {
        toast({
          title: "Invalid expiration date",
          description: "Expiration date must be in the future",
          variant: "destructive",
        });
        return;
      }
    }

    try {
      const result = await createMutation.mutateAsync({
        databaseId,
        data: {
          label: label.trim(),
          scopes,
          expiresAt: expiresAt || undefined,
        },
      });

      setPlainToken(result.plainToken);
      setTokenLabel(label);
      setIsCreateOpen(false);
      setIsTokenRevealOpen(true);

      // Reset form
      setLabel("");
      setReadScope(true);
      setWriteScope(false);
      setExpiresAt("");
    } catch (error) {
      toast({
        title: "Failed to create token",
        description: error instanceof Error ? error.message : "An error occurred",
        variant: "destructive",
      });
    }
  };

  const handleCopyToken = () => {
    navigator.clipboard.writeText(plainToken);
    setCopiedToken(true);
    setTimeout(() => setCopiedToken(false), 2000);
  };

  const handleDeleteToken = async () => {
    if (!deleteTokenId) {return;}

    try {
      await deleteMutation.mutateAsync({ tokenId: deleteTokenId, databaseId });
      toast({
        title: "Token revoked",
        description: "API token has been revoked successfully",
      });
      setDeleteTokenId(null);
    } catch (error) {
      toast({
        title: "Failed to revoke token",
        description: error instanceof Error ? error.message : "An error occurred",
        variant: "destructive",
      });
    }
  };

  const tokens = data?.tokens ?? [];

  return (
    <>
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle>API Access</CardTitle>
              <CardDescription>
                Manage API tokens for external access to this database
              </CardDescription>
            </div>
            <Button onClick={() => { void setIsCreateOpen(true); }} size="sm">
              <Plus className="w-4 h-4 mr-2" />
              Create Token
            </Button>
          </div>
        </CardHeader>
        <CardContent className="space-y-4">
          {isLoading ? (
            <div className="flex items-center justify-center py-8">
              <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
            </div>
          ) : tokens.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">
              <Key className="w-12 h-12 mx-auto mb-3 opacity-50" />
              <p>No API tokens yet</p>
              <p className="text-sm">Create a token to enable external API access</p>
            </div>
          ) : (
            <div className="space-y-3">
              {tokens.map((token) => (
                <div
                  key={token.id}
                  className="flex items-center justify-between p-3 border rounded-lg"
                >
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      <p className="font-medium">{token.label}</p>
                      {token.expiresAt && new Date(token.expiresAt) < new Date() && (
                        <Badge variant="destructive" className="text-xs animate-pulse">
                          <AlertTriangle className="w-3 h-3 mr-1" />
                          Expired
                        </Badge>
                      )}
                      {token.expiresAt && new Date(token.expiresAt) > new Date() && new Date(token.expiresAt).getTime() - Date.now() < 7 * 24 * 60 * 60 * 1000 && (
                        <Badge variant="outline" className="text-xs text-orange-600 border-orange-300">
                          <AlertTriangle className="w-3 h-3 mr-1" />
                          Expires soon
                        </Badge>
                      )}
                    </div>
                    <div className="flex items-center gap-2 text-sm text-muted-foreground">
                      <div className="flex gap-1">
                        {token.scopes.map((scope) => (
                          <Badge key={scope} variant="outline" className="text-xs">
                            {scope}
                          </Badge>
                        ))}
                      </div>
                      <span>ΓÇó</span>
                      <span>Created {token.createdAt ? new Date(token.createdAt).toLocaleDateString() : 'Unknown'}</span>
                      {token.expiresAt && (
                        <>
                          <span>ΓÇó</span>
                          <div className="flex items-center gap-1">
                            <Calendar className="w-3 h-3" />
                            Expires {new Date(token.expiresAt).toLocaleDateString()}
                          </div>
                        </>
                      )}
                    </div>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => { void setDeleteTokenId(token.id); }}
                    disabled={deleteMutation.isPending}
                  >
                    <Trash2 className="w-4 h-4 text-destructive" />
                  </Button>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Create Token Dialog */}
      <Dialog open={isCreateOpen} onOpenChange={setIsCreateOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Create API Token</DialogTitle>
            <DialogDescription>
              Generate a new API token for external access to this database
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div className="grid gap-2">
              <Label htmlFor="label">
                Label <span className="text-destructive">*</span>
              </Label>
              <Input
                id="label"
                value={label}
                onChange={(e) => { void setLabel(e.target.value); }}
                placeholder="e.g., Production API"
              />
            </div>

            <div className="grid gap-2">
              <Label>
                Scopes <span className="text-destructive">*</span>
              </Label>
              <div className="space-y-2">
                <div className="flex items-center space-x-2">
                  <Checkbox
                    id="read"
                    checked={readScope}
                    onCheckedChange={(checked) => setReadScope(checked === true)}
                  />
                  <Label htmlFor="read" className="font-normal cursor-pointer">
                    Read - View database data
                  </Label>
                </div>
                <div className="flex items-center space-x-2">
                  <Checkbox
                    id="write"
                    checked={writeScope}
                    onCheckedChange={(checked) => setWriteScope(checked === true)}
                  />
                  <Label htmlFor="write" className="font-normal cursor-pointer">
                    Write - Create, update, and delete data
                  </Label>
                </div>
              </div>
            </div>

            <div className="grid gap-2">
              <Label htmlFor="expiresAt">Expiration Date (optional)</Label>
              <Input
                id="expiresAt"
                type="datetime-local"
                value={expiresAt}
                onChange={(e) => { void setExpiresAt(e.target.value); }}
              />
              <p className="text-xs text-muted-foreground">
                Leave empty for a token that never expires
              </p>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => { void setIsCreateOpen(false); }}>
              Cancel
            </Button>
            <Button
              onClick={() => { void handleCreateToken(); }}
              disabled={createMutation.isPending}
            >
              {createMutation.isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Create Token
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Token Reveal Dialog */}
      <Dialog open={isTokenRevealOpen} onOpenChange={setIsTokenRevealOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Your API Token</DialogTitle>
            <DialogDescription>
              Copy and save this token now. For security reasons, it will not be shown again.
            </DialogDescription>
          </DialogHeader>
          <Alert variant="destructive">
            <AlertTriangle className="h-4 w-4" />
            <AlertDescription className="font-medium">
              <strong>Important:</strong> This is the only time you will see this token! Copy it now and store it securely.
            </AlertDescription>
          </Alert>
          <div className="space-y-3">
            <div>
              <Label>Token Label</Label>
              <p className="text-sm text-muted-foreground mt-1">{tokenLabel}</p>
            </div>
            <div>
              <Label>API Token</Label>
              <div className="flex gap-2 mt-1">
                <Input
                  value={plainToken}
                  readOnly
                  className="font-mono text-sm"
                />
                <Button
                  variant="outline"
                  size="icon"
                  onClick={() => { void handleCopyToken(); }}
                >
                  {copiedToken ? (
                    <Check className="h-4 w-4 text-green-600" />
                  ) : (
                    <Copy className="h-4 w-4" />
                  )}
                </Button>
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button onClick={() => { void setIsTokenRevealOpen(false); }}>
              Done
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <AlertDialog open={!!deleteTokenId} onOpenChange={() => setDeleteTokenId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Revoke API Token?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently revoke the token. Any applications using this token will
              lose access immediately. This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={() => { void handleDeleteToken(); }}>
              Revoke Token
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

/**
