  };

  const scopeIcons = {
    account: "fas fa-building",
    project: "fas fa-folder",
    workflow: "fas fa-sitemap",
  };

  return (
    <Card
      className="cursor-pointer hover:shadow-lg transition-shadow"
      onMouseEnter={() => setShowActions(true)}
      onMouseLeave={() => setShowActions(false)}
      onClick={(e) => {
        // Don't trigger onClick if clicking on dropdown
        if (!(e.target as HTMLElement).closest('[data-dropdown-menu]')) {
          onClick();
        }
      }}
    >
      <CardHeader>
        <div className="flex items-start justify-between">
          <div className="flex-1">
            <CardTitle className="text-lg flex items-center gap-2">
              <FolderOpen className="w-5 h-5 text-primary" />
              {database.name}
            </CardTitle>
            {database.description && (
              <CardDescription className="mt-1 line-clamp-2">
                {database.description}
              </CardDescription>
            )}
          </div>

          {showActions && (
            <DropdownMenu>
              <DropdownMenuTrigger asChild data-dropdown-menu>
                <Button
                  variant="ghost"
                  size="sm"
                  className="h-8 w-8 p-0"
                  onClick={(e) => e.stopPropagation()}
                >
                  <MoreVertical className="h-4 w-4" />
                  <span className="sr-only">Open menu</span>
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" data-dropdown-menu>
                <DropdownMenuItem onClick={(e) => {
                  e.stopPropagation();
                  onClick();
                }}>
                  <Edit className="mr-2 h-4 w-4" />
                  Edit
                </DropdownMenuItem>
                {onTransfer && (
                  <DropdownMenuItem onClick={(e) => {
                    e.stopPropagation();
                    onTransfer(database.id, database.name);
                  }}>
