  const handleReset = () => {
    setName(database.name);
    setDescription(database.description ?? "");
    setScopeType(database.scopeType);
    setScopeId(database.scopeId ?? "");
  };

  const scopeIcons = {
    account: "fas fa-building",
    project: "fas fa-folder",
    workflow: "fas fa-sitemap",
