/**
 * Delete Row Button Component (PR 7)
 * Button to delete a row from the table
 */

import { Trash2, Loader2 } from "lucide-react";
import { useState } from "react";

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { useToast } from "@/hooks/use-toast";
import { datavaultAPI } from "@/lib/datavault-api";

interface DeleteRowButtonProps {
  tableId: string;
  rowId: string;
  onDelete: () => void;
}

export function DeleteRowButton({ tableId, rowId, onDelete }: DeleteRowButtonProps) {
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const { toast } = useToast();

  const handleDelete = async () => {
    setIsDeleting(true);

    try {
      await datavaultAPI.deleteRow(rowId);

      toast({
        title: "Row deleted",
        description: "The row has been deleted successfully.",
      });

      setConfirmOpen(false);
      onDelete();
    } catch (error) {
      toast({
        title: "Failed to delete row",
        description: error instanceof Error ? error.message : "An error occurred",
        variant: "destructive",
      });
    } finally {
      setIsDeleting(false);
    }
  };

  return (
    <>
      <Button
        onClick={() => { void setConfirmOpen(true); }}
        size="sm"
        variant="ghost"
        className="h-8 w-8 p-0 hover:bg-destructive/10 hover:text-destructive"
        aria-label="Delete row"
        title="Delete row"
      >
        <Trash2 className="w-4 h-4" />
      </Button>

      <AlertDialog open={confirmOpen} onOpenChange={setConfirmOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Row?</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete this row? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isDeleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => { void handleDelete(); }}
              disabled={isDeleting}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {isDeleting && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

/**
 * Editable Cell Component
 * Inline editable cell with auto-save on blur/enter
 * Supports different input types based on column type
 * Enhanced with loading states, error handling, and accessibility
 */

import { Loader2 } from "lucide-react";
import React, { useState, useEffect, useRef } from "react";

import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

import type { DatavaultColumn } from "@shared/schema";

interface EditableCellProps {
  column: DatavaultColumn;
  value: any;
  onSave: (value: any) => Promise<void>;
  readOnly?: boolean;
  placeholder?: string;
}

export function EditableCell({ column, value, onSave, readOnly = false, placeholder }: EditableCellProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [editValue, setEditValue] = useState(value);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Update editValue when value prop changes
  useEffect(() => { void setEditValue(value); }, [value]);

  // Focus input when entering edit mode
  useEffect(() => {
    if (isEditing && inputRef.current) {
      inputRef.current.focus();
      inputRef.current.select();
    }
  }, [isEditing]);

  const handleDoubleClick = () => {
    if (!readOnly) {
      setIsEditing(true);
    }
  };

  const handleSave = async () => {
    if (editValue === value) {
      setIsEditing(false);
      setError(null);
      return;
    }

    // Optimistic update: exit edit mode immediately for better UX
    setIsEditing(false);
    setIsSaving(true);
    setError(null);

    try {
      await onSave(editValue);
    } catch (error) {
      // Revert on error and show error message
      setEditValue(value);
      setError(error instanceof Error ? error.message : "Failed to save");
      console.error("Failed to save cell:", error);
      // Clear error after 3 seconds
      setTimeout(() => setError(null), 3000);
    } finally {
      setIsSaving(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter") {
      e.preventDefault();
      handleSave();
    } else if (e.key === "Escape") {
      e.preventDefault();
      setEditValue(value);
      setIsEditing(false);
    }
  };

  const handleBlur = () => {
    void handleSave();
  };

  // Format display value based on column type
  const formatDisplayValue = (val: any) => {
    if (val === null || val === undefined) { return ""; }

    switch (column.type as string) {
      case "boolean":
      case "yes_no":
        return val ? "Yes" : "No";
      case "date":
        if (val) {
          const date = new Date(val);
          return date.toLocaleDateString(undefined, { timeZone: 'UTC' });
        }
        return "";
      case "datetime":
        if (val) {
          const date = new Date(val);
          return date.toLocaleString();
        }
        return "";
      case "number":
        return typeof val === "number" ? val.toString() : val;
      default:
        return val.toString();
    }
  };

  // Render checkbox for boolean types
  if (column.type === "boolean" && !isEditing) {
    return (
      <div
        className={cn(
          "px-3 py-2 min-h-[40px] flex items-center gap-2",
          !readOnly && "cursor-pointer hover:bg-accent/50",
          error && "bg-destructive/10 border-l-2 border-destructive"
        )}
        onDoubleClick={handleDoubleClick}
        role="gridcell"
        aria-label={`${column.name}: ${formatDisplayValue(value)}${readOnly ? " (read-only)" : ""}`}
      >
        {isSaving && <Loader2 className="w-3 h-3 animate-spin text-muted-foreground flex-shrink-0" />}
        <Checkbox
          checked={!!value}
          onCheckedChange={async (checked) => {
            if (!readOnly) {
              setIsSaving(true);
              setError(null);
              try {
                await onSave(checked);
              } catch (error) {
                setError(error instanceof Error ? error.message : "Failed to save");
                setTimeout(() => setError(null), 3000);
              } finally {
                setIsSaving(false);
              }
            }
          }}
          disabled={readOnly || isSaving}
          aria-label={column.name}
        />
        {error && <span className="text-xs text-destructive flex-shrink-0">Error</span>}
      </div>
    );
  }

  // Display mode
  if (!isEditing) {
    const displayValue = formatDisplayValue(value);
    const showPlaceholder = !displayValue && placeholder;

    return (
      <div
        className={cn(
          "px-3 py-2 min-h-[40px] flex items-center gap-2 group",
          !readOnly && "cursor-pointer hover:bg-accent/50 transition-colors",
          error && "bg-destructive/10 border-l-2 border-destructive"
        )}
        onDoubleClick={handleDoubleClick}
        title={error || (readOnly ? "" : "Double-click to edit")}
        role="gridcell"
        aria-label={`${column.name}: ${displayValue}${readOnly ? " (read-only)" : ""}`}
        tabIndex={readOnly ? -1 : 0}
        onKeyDown={(e) => {
          if (!readOnly && (e.key === "Enter" || e.key === " ")) {
            e.preventDefault();
            handleDoubleClick();
          }
        }}
      >
        {isSaving && <Loader2 className="w-3 h-3 animate-spin text-muted-foreground flex-shrink-0" />}
        <span className={cn("truncate flex-1", isSaving && "opacity-50", showPlaceholder && "text-muted-foreground italic")}>
          {showPlaceholder ? placeholder : displayValue}
        </span>
        {error && <span className="text-xs text-destructive flex-shrink-0">Error</span>}
      </div>
    );
  }

  // Edit mode
  return (
    <div className="px-2 py-1">
      <Input
        ref={inputRef}
        type={
          column.type === "number"
            ? "number"
            : column.type === "email"
              ? "email"
              : column.type === "url"
                ? "url"
                : column.type === "date"
                  ? "date"
                  : column.type === "datetime"
                    ? "datetime-local"
                    : "text"
        }
        value={editValue ?? ""}
        onChange={(e) => { void setEditValue(e.target.value); }}
        onKeyDown={handleKeyDown}
        onBlur={handleBlur}
        disabled={isSaving}
        className="h-9"
        aria-label={`Edit ${column.name}`}
        placeholder={placeholder || `Enter ${column.name.toLowerCase()}`}
      />
    </div>
  );
}

/**
 * Editable Data Grid Component
 * Grid with inline editable cells, auto-save, and row actions
 * Supports different column types and validation
 */

import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent,
} from "@dnd-kit/core";
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  useSortable,
  horizontalListSortingStrategy,
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { Edit2, Trash2, MoreVertical, GripVertical, FileText } from "lucide-react";
import { useState, useEffect, useMemo } from "react";

import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
  DropdownMenuSeparator,
} from "@/components/ui/dropdown-menu";
import { useToast } from "@/hooks/use-toast";

import type { DatavaultColumn } from "@shared/schema";

import { ColumnTypeIcon, getColumnTypeColor } from "./ColumnTypeIcon";
import { EditableCell } from "./EditableCell";
import { RowDetailDrawer } from "./RowDetailDrawer";



interface EditableDataGridProps {
  columns: DatavaultColumn[];
  rows: any[];
  onCellUpdate: (rowId: string, columnId: string, value: any) => Promise<void>;
  onEditRow?: (rowId: string, values: Record<string, any>) => void;
  onDeleteRow?: (rowId: string) => void;
  onReorderColumns?: (columnIds: string[]) => Promise<void>;
  onCreateRow?: (values: Record<string, any>) => Promise<void>;
}

interface SortableColumnHeaderProps {
  column: DatavaultColumn;
  isDragDisabled?: boolean;
  isFirst?: boolean;
}

function SortableColumnHeader({ column, isDragDisabled = false, isFirst = false }: SortableColumnHeaderProps) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({
    id: column.id,
    disabled: isDragDisabled,
  });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
    position: 'relative' as const,
  };

  return (
    <th
      ref={setNodeRef}
      style={style}
      className={`text-left text-sm font-semibold text-foreground min-w-[150px] bg-muted/50 border-l border-border ${isFirst ? 'border-l-0' : ''}`}
      role="columnheader"
      scope="col"
      aria-label={`${column.name}${column.isPrimaryKey ? " (Primary Key)" : ""}${column.required ? " (Required)" : ""}`}
    >
      <div className="flex items-center">
        {/* Drag handle zone - more pronounced */}
        <div
          {...attributes}
          {...listeners}
          className={isDragDisabled
            ? "flex items-center justify-center w-8 h-full py-3 opacity-30 cursor-not-allowed bg-muted/30 border-r border-border/50"
            : "flex items-center justify-center w-8 h-full py-3 cursor-grab active:cursor-grabbing touch-none bg-muted/70 hover:bg-accent border-r border-border/50 transition-colors"
          }
          title={isDragDisabled ? "Primary key position is locked" : "Drag to reorder column"}
        >
          <GripVertical className="w-4 h-4 text-muted-foreground" />
        </div>
        {/* Column content */}
        <div className="flex items-center gap-2 px-3 py-3">
          <ColumnTypeIcon type={column.type} className={getColumnTypeColor(column.type)} />
          <span>{column.name}</span>
          {column.isPrimaryKey && (
            <span className="text-xs bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300 px-1.5 py-0.5 rounded" aria-label="Primary Key">
              PK
            </span>
          )}
          {column.required && (
            <span className="text-xs text-destructive" aria-label="Required">*</span>
          )}
        </div>
      </div>
    </th>
  );
}

export function EditableDataGrid({
  columns,
  rows,
  onCellUpdate,
  onEditRow,
  onDeleteRow,
  onReorderColumns,
  onCreateRow,
}: EditableDataGridProps) {
  const [savingCells, setSavingCells] = useState<Set<string>>(new Set());
  const [localColumns, setLocalColumns] = useState(columns);
  const [emptyRowValues, setEmptyRowValues] = useState<Record<string, any>>({});
  const [emptyRowTouched, setEmptyRowTouched] = useState(false);
  const [selectedRowId, setSelectedRowId] = useState<string | null>(null);
  const { toast } = useToast();

  // Drag and drop sensors
  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8,
      },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  // Update local columns when props change
  useEffect(() => { void setLocalColumns(columns); }, [columns]);

  // Sort columns by orderIndex (memoized to prevent unnecessary recalculations)
  const sortedColumns = useMemo(
    () => [...localColumns].sort((a, b) => a.orderIndex - b.orderIndex),
    [localColumns]
  );

  // Initialize empty row with autonumber pre-filled
  useEffect(() => {
    const autoNumberColumn = sortedColumns.find(
      (col) => col.type === 'auto_number' && col.isPrimaryKey
    );

    if (autoNumberColumn) {
      // Calculate next autonumber
      const maxValue = rows.reduce((max, row) => {
        const value = row.values[autoNumberColumn.id];
        const num = typeof value === 'number' ? value : parseInt(value, 10);
        return !isNaN(num) && num > max ? num : max;
      }, 0);

      setEmptyRowValues((prev) => ({
        ...prev,
        [autoNumberColumn.id]: maxValue + 1,
      }));
    }
  }, [rows, sortedColumns]);

  const handleDragEnd = async (event: DragEndEvent) => {
    const { active, over } = event;

    if (over && active.id !== over.id) {
      const oldIndex = sortedColumns.findIndex((col) => col.id === active.id);
      const newIndex = sortedColumns.findIndex((col) => col.id === over.id);

      const draggedColumn = sortedColumns[oldIndex];
      const targetColumn = sortedColumns[newIndex];

      // Count primary key columns
      const primaryKeyCount = sortedColumns.filter((col) => col.isPrimaryKey).length;
      const primaryKeyColumns = sortedColumns.filter((col) => col.isPrimaryKey);
      const lastPrimaryKeyIndex = sortedColumns.findIndex(
        (col) => col.id === primaryKeyColumns[primaryKeyColumns.length - 1]?.id
      );

      // Rule 1: If only one primary key, it cannot be moved
      if (primaryKeyCount === 1 && draggedColumn.isPrimaryKey) {
        return; // Block the move
      }

      // Rule 2: Primary keys must stay on the left
      if (draggedColumn.isPrimaryKey && newIndex > lastPrimaryKeyIndex) {
        return; // Block moving a primary key past the last primary key
      }

      // Rule 3: Non-primary keys cannot be moved before primary keys
      if (!draggedColumn.isPrimaryKey && targetColumn.isPrimaryKey) {
        return; // Block moving a non-primary key to a primary key position
      }

      const newColumns = arrayMove(sortedColumns, oldIndex, newIndex);
      setLocalColumns(newColumns);

      // Call reorder API if provided
      if (onReorderColumns) {
        try {
          await onReorderColumns(newColumns.map((col) => col.id));
        } catch (error) {
          // Revert on error
          setLocalColumns(columns);
        }
      }
    }
  };

  const handleCellSave = async (rowId: string, columnId: string, value: any) => {
    const cellKey = `${rowId}-${columnId}`;
    setSavingCells((prev) => new Set(prev).add(cellKey));

    try {
      await onCellUpdate(rowId, columnId, value);
    } finally {
      setSavingCells((prev) => {
        const next = new Set(prev);
        next.delete(cellKey);
        return next;
      });
    }
  };

  const handleEmptyRowCellUpdate = async (columnId: string, value: any) => {
    // Update the empty row values
    const updatedValues = {
      ...emptyRowValues,
      [columnId]: value,
    };
    setEmptyRowValues(updatedValues);
    setEmptyRowTouched(true);

    // Check if all required fields are filled
    const requiredColumns = sortedColumns.filter((col) => col.required);
    const allRequiredFilled = requiredColumns.every((col) => {
      const val = updatedValues[col.id];
      return val !== undefined && val !== null && val !== '';
    });

    if (allRequiredFilled && onCreateRow) {
      // Create the actual row
      try {
        // Filter out undefined/null values
        const valuesToSave: Record<string, any> = {};
        for (const [colId, val] of Object.entries(updatedValues)) {
          if (val !== undefined && val !== null && val !== '') {
            valuesToSave[colId] = val;
          }
        }

        await onCreateRow(valuesToSave);

        // Show success notification
        toast({
          title: "New Row Added",
          description: "The row has been successfully created.",
        });

        // Reset empty row state
        setEmptyRowValues({});
        setEmptyRowTouched(false);
      } catch (error) {
        toast({
          title: "Failed to add row",
          description: error instanceof Error ? error.message : "An error occurred",
          variant: "destructive",
        });
      }
    }
  };

  // Check if a column should be highlighted as missing required value in empty row
  const isEmptyRowColumnMissingRequired = (columnId: string) => {
    if (!emptyRowTouched) {return false;}

    const column = sortedColumns.find((col) => col.id === columnId);
    if (!column?.required) {return false;}

    const value = emptyRowValues[columnId];
    return value === undefined || value === null || value === '';
  };

  if (rows.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-16 px-4 text-center">
        <div className="w-16 h-16 rounded-full bg-muted/50 flex items-center justify-center mb-4">
          <svg
            className="w-8 h-8 text-muted-foreground"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
            aria-hidden="true"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
            />
          </svg>
        </div>
        <h3 className="text-lg font-semibold text-foreground mb-2">No data yet</h3>
        <p className="text-sm text-muted-foreground max-w-sm mb-4">
          This table is empty. Click the "Add Row" button above to create your first row of data.
        </p>
        <p className="text-xs text-muted-foreground">
          ≡ƒÆí Tip: You can also double-click any cell to edit it inline after adding rows.
        </p>
      </div>
    );
  }

  return (
    <div className="border rounded-lg overflow-hidden">
      <div className="overflow-x-auto">
        <DndContext
          sensors={sensors}
          collisionDetection={closestCenter}
          onDragEnd={handleDragEnd}
        >
          <table className="w-full border-collapse" role="table" aria-label="Data table with inline editing">
            <thead className="border-b" role="rowgroup">
              <tr role="row">
                <SortableContext
                  items={sortedColumns.map((col) => col.id)}
                  strategy={horizontalListSortingStrategy}
                >
                  {sortedColumns.map((column, index) => {
                    // Disable dragging if this is the only primary key
                    const primaryKeyCount = sortedColumns.filter((col) => col.isPrimaryKey).length;
                    const isDragDisabled = column.isPrimaryKey && primaryKeyCount === 1;

                    return (
                      <SortableColumnHeader
                        key={column.id}
                        column={column}
                        isDragDisabled={isDragDisabled}
                        isFirst={index === 0}
                      />
                    );
                  })}
                </SortableContext>
                <th className="px-3 py-3 text-left text-sm font-semibold text-foreground w-[80px] bg-muted/50 border-l border-border" role="columnheader" scope="col">
                  Actions
                </th>
              </tr>
            </thead>
          <tbody className="divide-y divide-border" role="rowgroup">
            {rows.map((row) => (
              <tr key={row.row.id} className="hover:bg-accent/30 transition-colors" role="row">
                {sortedColumns.map((column, index) => (
                  <td key={column.id} className={`border-l border-border ${index === 0 ? 'border-l-0' : ''}`}>
                    <EditableCell
                      column={column}
                      value={row.values[column.id]}
                      onSave={(value) => handleCellSave(row.row.id, column.id, value)}
                      readOnly={column.isPrimaryKey && column.type === 'auto_number'}
                    />
                  </td>
                ))}
                <td className="px-3 py-2 border-l border-border" role="gridcell">
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button variant="ghost" size="sm" className="h-8 w-8 p-0" aria-label="Row actions">
                        <MoreVertical className="w-4 h-4" />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end">
                      <DropdownMenuItem onClick={() => { void setSelectedRowId(row.row.id); }}>
                        <FileText className="w-4 h-4 mr-2" />
                        View Details
                      </DropdownMenuItem>
                      {(onEditRow || onDeleteRow) && <DropdownMenuSeparator />}
                      {onEditRow && (
                        <DropdownMenuItem onClick={() => { void onEditRow(row.row.id, row.values); }}>
                          <Edit2 className="w-4 h-4 mr-2" />
                          Edit Row
                        </DropdownMenuItem>
                      )}
                      {onDeleteRow && (
                        <DropdownMenuItem
                          onClick={() => { void onDeleteRow(row.row.id); }}
                          className="text-destructive focus:text-destructive"
                        >
                          <Trash2 className="w-4 h-4 mr-2" />
                          Delete Row
                        </DropdownMenuItem>
                      )}
                    </DropdownMenuContent>
                  </DropdownMenu>
                </td>
              </tr>
            ))}

            {/* Empty Row for Quick Add */}
            <tr className="bg-muted/20 hover:bg-muted/30 transition-colors" role="row">
              {sortedColumns.map((column, index) => (
                <td
                  key={column.id}
                  className={`border-l border-border ${index === 0 ? 'border-l-0' : ''} ${
                    isEmptyRowColumnMissingRequired(column.id) ? 'bg-red-50 dark:bg-red-950/20' : ''
                  }`}
                >
                  <EditableCell
                    column={column}
                    value={emptyRowValues[column.id]}
                    onSave={(value) => handleEmptyRowCellUpdate(column.id, value)}
                    readOnly={column.isPrimaryKey && column.type === 'auto_number'}
                    placeholder={
                      column.isPrimaryKey && column.type === 'auto_number'
                        ? String(emptyRowValues[column.id] ?? '')
                        : column.required
                        ? 'Required'
                        : 'Optional'
                    }
                  />
                </td>
              ))}
              <td className="px-3 py-2 border-l border-border" role="gridcell">
                {/* Empty cell for actions column */}
              </td>
            </tr>
          </tbody>
        </table>
        </DndContext>
      </div>

      {/* Row Detail Drawer */}
      <RowDetailDrawer
        rowId={selectedRowId}
        tableOwnerId={null} // TODO: Pass table owner ID from props
        onClose={() => setSelectedRowId(null)}
      />
    </div>
  );
}

/**
 * Filter Panel Component
 * Allows users to add, edit, and remove filters for data grid
 */

import { Filter, Plus, X, ChevronDown, ChevronRight } from "lucide-react";
import { useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useDatavaultFilterStore, EMPTY_FILTERS, type FilterCondition, type FilterOperator } from "@/stores/useDatavaultFilterStore";

import type { DatavaultColumn } from "@shared/schema";

interface FilterPanelProps {
  tableId: string;
  columns: DatavaultColumn[];
}

// Operator labels for UI
const operatorLabels: Record<FilterOperator, string> = {
  equals: "Equals",
  not_equals: "Not Equals",
  contains: "Contains",
  not_contains: "Does Not Contain",
  greater_than: "Greater Than",
  less_than: "Less Than",
  greater_than_or_equal: "Greater Than or Equal",
  less_than_or_equal: "Less Than or Equal",
  is_empty: "Is Empty",
  is_not_empty: "Is Not Empty",
  in: "In (comma-separated)",
  not_in: "Not In (comma-separated)",
};

// Get available operators for a column type
const getOperatorsForType = (type: string): FilterOperator[] => {
  switch (type) {
    case "short_text":
    case "long_text":
      return ["equals", "not_equals", "contains", "not_contains", "is_empty", "is_not_empty"];

    case "number":
      return [
        "equals",
        "not_equals",
        "greater_than",
        "less_than",
        "greater_than_or_equal",
        "less_than_or_equal",
        "is_empty",
        "is_not_empty",
      ];

    case "date":
    case "datetime":
      return [
        "equals",
        "not_equals",
        "greater_than",
        "less_than",
        "greater_than_or_equal",
        "less_than_or_equal",
        "is_empty",
        "is_not_empty",
      ];

    case "boolean":
    case "yes_no":
      return ["equals", "not_equals", "is_empty", "is_not_empty"];

    case "multiple_choice":
    case "radio":
    case "checkbox":
      return ["equals", "not_equals", "contains", "not_contains", "in", "not_in", "is_empty", "is_not_empty"];

    default:
      return ["equals", "not_equals", "is_empty", "is_not_empty"];
  }
};

// Check if operator needs a value input
const operatorNeedsValue = (operator: FilterOperator): boolean => {
  return operator !== "is_empty" && operator !== "is_not_empty";
};

export function FilterPanel({ tableId, columns }: FilterPanelProps) {
  const [isExpanded, setIsExpanded] = useState(true);
  // Use stable EMPTY_FILTERS reference to avoid infinite re-renders
  const filters = useDatavaultFilterStore((state) => state.filtersByTable[tableId] ?? EMPTY_FILTERS);
  const addFilter = useDatavaultFilterStore((state) => state.addFilter);
  const updateFilter = useDatavaultFilterStore((state) => state.updateFilter);
  const removeFilter = useDatavaultFilterStore((state) => state.removeFilter);
  const clearFilters = useDatavaultFilterStore((state) => state.clearFilters);

  const handleAddFilter = () => {
    if (columns.length === 0) {return;}

    const firstColumn = columns[0];
    const defaultOperator = getOperatorsForType(firstColumn.type)[0];

    const newFilter: FilterCondition = {
      id: crypto.randomUUID(),
      columnId: firstColumn.id,
      operator: defaultOperator,
      value: "",
    };

    addFilter(tableId, newFilter);
  };

  const handleColumnChange = (filterId: string, columnId: string) => {
    const column = columns.find((c) => c.id === columnId);
    if (!column) {return;}

    const availableOps = getOperatorsForType(column.type);
    const currentFilter = filters.find((f) => f.id === filterId);

    // Reset operator if current one isn't valid for new column type
    const newOperator = currentFilter && availableOps.includes(currentFilter.operator)
      ? currentFilter.operator
      : availableOps[0];

    updateFilter(tableId, filterId, { columnId, operator: newOperator, value: "" });
  };

  const handleOperatorChange = (filterId: string, operator: FilterOperator) => {
    updateFilter(tableId, filterId, { operator });
  };

  const handleValueChange = (filterId: string, value: string) => {
    updateFilter(tableId, filterId, { value });
  };

  const handleRemoveFilter = (filterId: string) => {
    removeFilter(tableId, filterId);
  };

  const handleClearAll = () => {
    clearFilters(tableId);
  };

  return (
    <Card className="mb-4">
      <CardHeader className="py-3 px-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setIsExpanded(!isExpanded)}
              className="h-6 w-6 p-0"
            >
              {isExpanded ? (
                <ChevronDown className="h-4 w-4" />
              ) : (
                <ChevronRight className="h-4 w-4" />
              )}
            </Button>
            <Filter className="h-4 w-4 text-muted-foreground" />
            <CardTitle className="text-sm font-medium">
              Filters {filters.length > 0 && `(${filters.length})`}
            </CardTitle>
          </div>
          <div className="flex items-center gap-2">
            {filters.length > 0 && (
              <Button
                variant="ghost"
                size="sm"
                onClick={handleClearAll}
                className="h-7 text-xs"
              >
                Clear All
              </Button>
            )}
            <Button
              variant="outline"
              size="sm"
              onClick={handleAddFilter}
              disabled={columns.length === 0}
              className="h-7"
            >
              <Plus className="h-3 w-3 mr-1" />
              Add Filter
            </Button>
          </div>
        </div>
      </CardHeader>

      {isExpanded && filters.length > 0 && (
        <CardContent className="pt-0 pb-4 px-4 space-y-3">
          {filters.map((filter) => {
            const column = columns.find((c) => c.id === filter.columnId);
            if (!column) {return null;}

            const availableOperators = getOperatorsForType(column.type);
            const needsValue = operatorNeedsValue(filter.operator);

            return (
              <div
                key={filter.id}
                className="flex items-start gap-2 p-3 border rounded-lg bg-muted/30"
              >
                <div className="flex-1 space-y-2">
                  <div className="grid grid-cols-2 gap-2">
                    {/* Column Select */}
                    <div className="space-y-1">
                      <Label className="text-xs text-muted-foreground">Column</Label>
                      <Select
                        value={filter.columnId}
                        onValueChange={(value) => handleColumnChange(filter.id, value)}
                      >
                        <SelectTrigger className="h-8 text-sm">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {columns.map((col) => (
                            <SelectItem key={col.id} value={col.id}>
                              {col.name}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>

                    {/* Operator Select */}
                    <div className="space-y-1">
                      <Label className="text-xs text-muted-foreground">Operator</Label>
                      <Select
                        value={filter.operator}
                        onValueChange={(value) =>
                          handleOperatorChange(filter.id, value as FilterOperator)
                        }
                      >
                        <SelectTrigger className="h-8 text-sm">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {availableOperators.map((op) => (
                            <SelectItem key={op} value={op}>
                              {operatorLabels[op]}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                  </div>

                  {/* Value Input (if needed) */}
                  {needsValue && (
                    <div className="space-y-1">
                      <Label className="text-xs text-muted-foreground">Value</Label>
                      <Input
                        type={column.type === "number" ? "number" : column.type === "date" ? "date" : column.type === "datetime" ? "datetime-local" : "text"}
                        value={filter.value?.toString() ?? ""}
                        onChange={(e) => handleValueChange(filter.id, e.target.value)}
                        placeholder={`Enter ${column.name.toLowerCase()}...`}
                        className="h-8 text-sm"
                      />
                    </div>
                  )}
                </div>

                {/* Remove Button */}
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => handleRemoveFilter(filter.id)}
                  className="h-8 w-8 p-0 text-muted-foreground hover:text-destructive mt-5"
                >
                  <X className="h-4 w-4" />
                </Button>
              </div>
            );
          })}
        </CardContent>
      )}
    </Card>
  );
}

/**
 * Infinite Data Grid Component
 * Wrapper around DataGrid with infinite scroll support
 */
import { useInfiniteQuery } from "@tanstack/react-query";
import { Loader2 } from "lucide-react";
import { useEffect, useRef } from "react";

import { datavaultAPI } from "@/lib/datavault-api";
import { datavaultQueryKeys } from "@/lib/datavault-hooks";

import type { DatavaultColumn } from "@shared/schema";

import { DataGrid } from "./DataGrid";
import { DataGridSkeleton } from "./DataGridSkeleton";
interface InfiniteDataGridProps {
  tableId: string;
  columns: DatavaultColumn[];
  showArchived?: boolean;
  sortBy?: string;
  sortOrder?: 'asc' | 'desc';
  filters?: Array<{ columnId: string; operator: string; value: any }>;
  selectedRowIds?: Set<string>;
  onSelectRow?: (rowId: string, selected: boolean) => void;
  onSelectAll?: (selected: boolean) => void;
  onSort?: (columnSlug: string) => void;
  onColumnResize?: (columnId: string, widthPx: number) => void;
  onEditRow: (rowId: string, values: Record<string, any>) => void;
  onDeleteRow: (rowId: string) => void;
  onArchiveRow?: (rowId: string) => void;
  onUnarchiveRow?: (rowId: string) => void;
}
export function InfiniteDataGrid({
  tableId,
  columns,
  showArchived = false,
  sortBy,
  sortOrder,
  filters,
  selectedRowIds,
  onSelectRow,
  onSelectAll,
  onSort,
  onColumnResize,
  onEditRow,
  onDeleteRow,
  onArchiveRow,
  onUnarchiveRow,
}: InfiniteDataGridProps) {
  const observerTarget = useRef<HTMLDivElement>(null);
  const {
    data,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
    isLoading,
    isError,
    error,
  } = useInfiniteQuery({
    queryKey: [...datavaultQueryKeys.tableRows(tableId), "infinite", showArchived, sortBy, sortOrder, filters],
    queryFn: ({ pageParam = 0 }) =>
      datavaultAPI.listRows(tableId, { limit: 25, offset: pageParam, showArchived, sortBy, sortOrder, filters }),
    getNextPageParam: (lastPage, allPages) => {
      const totalFetched = allPages.reduce((sum, page) => sum + page.rows.length, 0);
      if (totalFetched < lastPage.pagination.total) {
        return totalFetched;
      }
      return undefined;
    },
    initialPageParam: 0,
  });
  // Intersection observer for infinite scroll
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && hasNextPage && !isFetchingNextPage) {
          void fetchNextPage();
        }
      },
      { threshold: 0.1 }
    );
    const currentTarget = observerTarget.current;
    if (currentTarget) {
      observer.observe(currentTarget);
    }
    return () => {
      if (currentTarget) {
        observer.unobserve(currentTarget);
      }
    };
  }, [fetchNextPage, hasNextPage, isFetchingNextPage]);
  if (isLoading) {
    return <DataGridSkeleton rows={10} columns={columns.length > 0 ? columns.length : 5} />;
  }
  if (isError) {
    return (
      <div className="text-center py-8 text-destructive">
        <p>Error loading rows: {error instanceof Error ? error.message : "Unknown error"}</p>
      </div>
    );
  }
  // Flatten all pages into a single array
  const allRows = data?.pages.flatMap((page) => page.rows) ?? [];
  return (
    <div>
      <DataGrid
        columns={columns}
        rows={allRows}
        selectedRowIds={selectedRowIds}
        sortBy={sortBy}
        sortOrder={sortOrder}
        onSelectRow={onSelectRow}
        onSelectAll={onSelectAll}
        onSort={onSort}
        onColumnResize={onColumnResize}
        onEditRow={onEditRow}
        onDeleteRow={onDeleteRow}
        onArchiveRow={onArchiveRow}
        onUnarchiveRow={onUnarchiveRow}
      />
      {/* Intersection observer target */}
      <div ref={observerTarget} className="h-4 flex items-center justify-center">
        {isFetchingNextPage && (
          <div className="py-4">
            <Loader2 className="w-5 h-5 animate-spin text-muted-foreground mx-auto" />
          </div>
        )}
        {!hasNextPage && allRows.length > 25 && (
          <p className="text-sm text-muted-foreground py-4">No more rows to load</p>
        )}
      </div>
    </div>
  );
}

/**
 * Infinite Editable Data Grid Component
 * Wrapper around EditableDataGrid with infinite scroll support
 * Includes cell-level auto-save functionality
 */

import { useInfiniteQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Loader2, Plus } from "lucide-react";
import { useEffect, useRef } from "react";

import { Button } from "@/components/ui/button";
import { useToast } from "@/hooks/use-toast";
import { datavaultAPI } from "@/lib/datavault-api";
import { datavaultQueryKeys } from "@/lib/datavault-hooks";

import { DATAVAULT_CONFIG } from "@shared/config";
import type { DatavaultColumn } from "@shared/schema";

import { EditableDataGrid } from "./EditableDataGrid";


interface InfiniteEditableDataGridProps {
  tableId: string;
  columns: DatavaultColumn[];
  onEditRow: (rowId: string, values: Record<string, any>) => void;
  onDeleteRow: (rowId: string) => void;
  onReorderColumns?: (columnIds: string[]) => Promise<void>;
  onAddRow?: () => void;
  onCreateRow?: (values: Record<string, any>) => Promise<void>;
}

export function InfiniteEditableDataGrid({
  tableId,
  columns,
  onEditRow,
  onDeleteRow,
  onReorderColumns,
  onAddRow,
  onCreateRow,
}: InfiniteEditableDataGridProps) {
  const observerTarget = useRef<HTMLDivElement>(null);
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const {
    data,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
    isLoading,
    isError,
    error,
  } = useInfiniteQuery({
    queryKey: [...datavaultQueryKeys.tableRows(tableId), "infinite"],
    queryFn: ({ pageParam = 0 }) =>
      datavaultAPI.listRows(tableId, { limit: DATAVAULT_CONFIG.INFINITE_SCROLL_PAGE_SIZE, offset: pageParam }),
    getNextPageParam: (lastPage, allPages) => {
      const totalFetched = allPages.reduce((sum, page) => sum + page.rows.length, 0);
      if (totalFetched < lastPage.pagination.total) {
        return totalFetched;
      }
      return undefined;
    },
    initialPageParam: 0,
  });

  // Cell update mutation with optimistic updates
  const updateCellMutation = useMutation({
    mutationFn: async ({
      rowId,
      columnId,
      value,
    }: {
      rowId: string;
      columnId: string;
      value: any;
    }) => {
      // Get current row values
      const allRows = data?.pages.flatMap((page) => page.rows) ?? [];
      const row = allRows.find((r) => r.row.id === rowId);
      if (!row) {throw new Error("Row not found");}

      // Update only the changed cell
      const updatedValues = {
        ...row.values,
        [columnId]: value,
      };

      // Call update API
      await datavaultAPI.updateRow(rowId, updatedValues);
      return { rowId, columnId, value };
    },
    onMutate: async ({ rowId, columnId, value }) => {
      // Cancel any outgoing refetches (so they don't overwrite our optimistic update)
      await queryClient.cancelQueries({
        queryKey: [...datavaultQueryKeys.tableRows(tableId), "infinite"],
      });

      // Snapshot the previous value
      const previousData = queryClient.getQueryData([
        ...datavaultQueryKeys.tableRows(tableId),
        "infinite",
      ]);

      // Optimistically update to the new value
      queryClient.setQueryData(
        [...datavaultQueryKeys.tableRows(tableId), "infinite"],
        (old: any) => {
          if (!old) {return old;}
          return {
            ...old,
            pages: old.pages.map((page: any) => ({
              ...page,
              rows: page.rows.map((row: any) =>
                row.row.id === rowId
                  ? {
                      ...row,
                      values: {
                        ...row.values,
                        [columnId]: value,
                      },
                    }
                  : row
              ),
            })),
          };
        }
      );

      // Return a context object with the snapshotted value
      return { previousData };
    },
    onSuccess: () => {
      // Invalidate and refetch to ensure consistency
      queryClient.invalidateQueries({
        queryKey: [...datavaultQueryKeys.tableRows(tableId), "infinite"],
      });
    },
    onError: (error, _variables, context) => {
      // Revert to previous data on error
      if (context?.previousData) {
        queryClient.setQueryData(
          [...datavaultQueryKeys.tableRows(tableId), "infinite"],
          context.previousData
        );
      }

      toast({
        title: "Failed to update cell",
        description: error instanceof Error ? error.message : "An error occurred",
        variant: "destructive",
      });
    },
  });

  // Intersection observer for infinite scroll
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && hasNextPage && !isFetchingNextPage) {
          fetchNextPage();
        }
      },
      { threshold: 0.1 }
    );

    const currentTarget = observerTarget.current;
    if (currentTarget) {
      observer.observe(currentTarget);
    }

    return () => {
      if (currentTarget) {
        observer.unobserve(currentTarget);
      }
    };
  }, [fetchNextPage, hasNextPage, isFetchingNextPage]);

  const handleCellUpdate = async (rowId: string, columnId: string, value: any) => {
    await updateCellMutation.mutateAsync({ rowId, columnId, value });
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (isError) {
    return (
      <div className="text-center py-8 text-destructive">
        <p>Error loading rows: {error instanceof Error ? error.message : "Unknown error"}</p>
      </div>
    );
  }

  // Flatten all pages into a single array
  const allRows = data?.pages.flatMap((page) => page.rows) ?? [];

  return (
    <div>
      <EditableDataGrid
        columns={columns}
        rows={allRows}
        onCellUpdate={handleCellUpdate}
        onEditRow={onEditRow}
        onDeleteRow={onDeleteRow}
        onReorderColumns={onReorderColumns}
        onCreateRow={onCreateRow}
      />

      {/* Intersection observer target */}
      <div ref={observerTarget} className="h-4 flex items-center justify-center mt-4">
        {isFetchingNextPage && (
          <div className="py-4">
            <Loader2 className="w-5 h-5 animate-spin text-muted-foreground mx-auto" />
          </div>
        )}
        {!hasNextPage && allRows.length > 25 && (
          <p className="text-sm text-muted-foreground py-4">No more rows to load</p>
        )}
      </div>

      {/* Add Row Button */}
      {onAddRow && (
        <div className="mt-4 flex justify-start">
          <Button
            onClick={() => { void onAddRow(); }}
            disabled={columns.length === 0}
            variant="outline"
            size="sm"
          >
            <Plus className="w-4 h-4 mr-2" />
            Add Row
          </Button>
        </div>
      )}
    </div>
  );
}

/**
 * Move Table Modal Component
 * Modal for moving a table between databases or to the main folder
 * DataVault Phase 2: Table Movement
 */

import { Loader2, FolderOpen, Database as DatabaseIcon } from "lucide-react";
import { useState } from "react";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import type { DatavaultDatabase } from "@/lib/datavault-api";

interface MoveTableModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  tableName: string;
  currentDatabaseId: string | null;
  databases: DatavaultDatabase[];
  onMove: (databaseId: string | null) => Promise<void>;
  isLoading: boolean;
}

export function MoveTableModal({
  open,
  onOpenChange,
  tableName,
  currentDatabaseId,
  databases,
  onMove,
  isLoading,
}: MoveTableModalProps) {
  const [selectedDatabaseId, setSelectedDatabaseId] = useState<string | null>(
    currentDatabaseId
  );

  const handleMove = async () => {
    await onMove(selectedDatabaseId);
    onOpenChange(false);
  };

  const hasChanged = selectedDatabaseId !== currentDatabaseId;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle>Move Table</DialogTitle>
          <DialogDescription>
            Move "{tableName}" to a different database or to the main folder.
          </DialogDescription>
        </DialogHeader>

        <div className="grid gap-4 py-4">
          <div className="grid gap-2">
            <Label htmlFor="destination">
              Destination <span className="text-destructive">*</span>
            </Label>
            <Select
              value={selectedDatabaseId || "main"}
              onValueChange={(value) =>
                setSelectedDatabaseId(value === "main" ? null : value)
              }
            >
              <SelectTrigger id="destination">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="main">
                  <div className="flex items-center gap-2">
                    <FolderOpen className="w-4 h-4" />
                    <span>Main Folder (No Database)</span>
                  </div>
                </SelectItem>
                {databases.map((database) => (
                  <SelectItem key={database.id} value={database.id}>
                    <div className="flex items-center gap-2">
                      <DatabaseIcon className="w-4 h-4" />
                      <span>{database.name}</span>
                    </div>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {currentDatabaseId && (
            <div className="text-sm text-muted-foreground">
              Current location:{" "}
              <span className="font-medium">
                {databases.find((db) => db.id === currentDatabaseId)?.name ||
                  "Unknown"}
              </span>
            </div>
          )}

          {!currentDatabaseId && (
            <div className="text-sm text-muted-foreground">
              Current location: <span className="font-medium">Main Folder</span>
            </div>
          )}
        </div>

        <DialogFooter>
          <Button
            variant="outline"
            onClick={() => { void onOpenChange(false); }}
            disabled={isLoading}
          >
            Cancel
          </Button>
          <Button onClick={() => { void handleMove(); }} disabled={!hasChanged || isLoading}>
            {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Move Table
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * Notes Tab Component
 * Displays notes for a row with ability to add/delete notes
 */

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Loader2, MessageSquare } from "lucide-react";
import React, { useState, useRef, useEffect } from "react";

import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/hooks/useAuth";
import { datavaultAPI } from "@/lib/datavault-api";

import { NoteItem } from "./NoteItem";

interface NotesTabProps {
  rowId: string;
  tableOwnerId?: string | null; // User ID of table owner for delete permissions
}

export function NotesTab({ rowId, tableOwnerId }: NotesTabProps) {
  const [noteText, setNoteText] = useState("");
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const { user } = useAuth();
  const notesEndRef = useRef<HTMLDivElement>(null);
  const notesListRef = useRef<HTMLDivElement>(null);

  // Fetch notes
  const { data: notes = [], isLoading, isError } = useQuery({
    queryKey: ["datavault", "rows", rowId, "notes"],
    queryFn: () => datavaultAPI.getRowNotes(rowId),
  });

  // Scroll to bottom when notes change
  useEffect(() => {
    if (notes.length > 0 && notesEndRef.current) {
      notesEndRef.current.scrollIntoView({ behavior: "smooth", block: "end" });
    }
  }, [notes.length]);

  // Create note mutation
  const createNoteMutation = useMutation({
    mutationFn: (text: string) => datavaultAPI.createRowNote(rowId, text),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["datavault", "rows", rowId, "notes"] });
      setNoteText("");
      toast({
        title: "Note added",
        description: "Your note has been added successfully.",
      });
      // Scroll to bottom after adding note
      setTimeout(() => {
        if (notesEndRef.current) {
          notesEndRef.current.scrollIntoView({ behavior: "smooth", block: "end" });
        }
      }, 100);
    },
    onError: (error: any) => {
      toast({
        title: "Failed to add note",
        description: error.message || "An error occurred while adding the note.",
        variant: "destructive",
      });
    },
  });

  // Delete note mutation
  const deleteNoteMutation = useMutation({
    mutationFn: (noteId: string) => datavaultAPI.deleteRowNote(noteId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["datavault", "rows", rowId, "notes"] });
      toast({
        title: "Note deleted",
        description: "The note has been deleted successfully.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Failed to delete note",
        description: error.message || "An error occurred while deleting the note.",
        variant: "destructive",
      });
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmedText = noteText.trim();
    if (!trimmedText) {
      toast({
        title: "Empty note",
        description: "Please enter some text before submitting.",
        variant: "destructive",
      });
      return;
    }

    createNoteMutation.mutate(trimmedText);
  };

  const handleDeleteNote = async (noteId: string) => {
    await deleteNoteMutation.mutateAsync(noteId);
  };

  // Check if user can delete a note (owner or table owner)
  const canDeleteNote = (note: any) => {
    if (!user) {return false;}
    return note.userId === user.id || tableOwnerId === user.id;
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (isError) {
    return (
      <div className="flex flex-col items-center justify-center py-8 text-center">
        <MessageSquare className="w-12 h-12 text-muted-foreground mb-2" />
        <p className="text-sm text-muted-foreground">
          Failed to load notes. Please try again.
        </p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full">
      {/* Notes list */}
      <div ref={notesListRef} className="flex-1 overflow-y-auto px-4 py-2">
        {notes.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-12 text-center">
            <MessageSquare className="w-12 h-12 text-muted-foreground mb-2" />
            <p className="text-sm text-muted-foreground">
              No notes yet. Be the first to add one!
            </p>
          </div>
        ) : (
          <div className="space-y-3">
            {notes.map((note) => (
              <NoteItem
                key={note.id}
                note={note}
                onDelete={handleDeleteNote}
                canDelete={canDeleteNote(note)}
              />
            ))}
            <div ref={notesEndRef} />
          </div>
        )}
      </div>

      {/* Add note form */}
      <div className="border-t p-4 bg-background">
        <form onSubmit={(e) => { e.preventDefault(); void handleSubmit(e); }} className="space-y-2">
          <Textarea
            value={noteText}
            onChange={(e) => { void setNoteText(e.target.value); }}
            placeholder="Add a note..."
            className="min-h-[80px] resize-none"
            disabled={createNoteMutation.isPending}
          />
          <div className="flex justify-end">
            <Button
              type="submit"
              size="sm"
              disabled={createNoteMutation.isPending || !noteText.trim()}
            >
              {createNoteMutation.isPending ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Adding...
                </>
              ) : (
                "Add Note"
              )}
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
}

/**
 * OptionsEditor Component
 * Manage options for select/multiselect columns
 */

import { Plus, Trash2, GripVertical } from "lucide-react";
import { useState } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import type { SelectOption } from "@/lib/types/datavault";

interface OptionsEditorProps {
  options: SelectOption[];
  onChange: (options: SelectOption[]) => void;
}

const TAILWIND_COLORS = [
  { name: "Red", value: "red" },
  { name: "Orange", value: "orange" },
  { name: "Amber", value: "amber" },
  { name: "Yellow", value: "yellow" },
  { name: "Lime", value: "lime" },
  { name: "Green", value: "green" },
  { name: "Emerald", value: "emerald" },
  { name: "Teal", value: "teal" },
  { name: "Cyan", value: "cyan" },
  { name: "Sky", value: "sky" },
  { name: "Blue", value: "blue" },
  { name: "Indigo", value: "indigo" },
  { name: "Violet", value: "violet" },
  { name: "Purple", value: "purple" },
  { name: "Fuchsia", value: "fuchsia" },
  { name: "Pink", value: "pink" },
  { name: "Rose", value: "rose" },
  { name: "Gray", value: "gray" },
];

export function OptionsEditor({ options, onChange }: OptionsEditorProps) {
  const [newLabel, setNewLabel] = useState("");
  const [newValue, setNewValue] = useState("");
  const [newColor, setNewColor] = useState("blue");

  const addOption = () => {
    if (!newLabel.trim() || !newValue.trim()) {return;}

    const newOption: SelectOption = {
      label: newLabel.trim(),
      value: newValue.trim(),
      color: newColor,
    };

    onChange([...options, newOption]);
    setNewLabel("");
    setNewValue("");
    setNewColor("blue");
  };

  const removeOption = (index: number) => {
    onChange(options.filter((_, i) => i !== index));
  };

  const updateOption = (index: number, updates: Partial<SelectOption>) => {
    const updated = options.map((opt, i) => (i === index ? { ...opt, ...updates } : opt));
    onChange(updated);
  };

  return (
    <div className="space-y-3">
      <Label>Options</Label>

      {/* Existing options */}
      {options.length > 0 && (
        <div className="space-y-2">
          {options.map((option, index) => (
            <div key={index} className="flex items-center gap-2 p-2 border rounded-md bg-accent/20">
              <GripVertical className="w-4 h-4 text-muted-foreground cursor-grab flex-shrink-0" />
              <div className="flex-1 grid grid-cols-3 gap-2 min-w-0">
                <Input
                  placeholder="Label"
                  value={option.label}
                  onChange={(e) => updateOption(index, { label: e.target.value })}
                  className="text-sm"
                />
                <Input
                  placeholder="Value"
                  value={option.value}
                  onChange={(e) => updateOption(index, { value: e.target.value })}
                  className="text-sm"
                />
                <Select
                  value={option.color || "blue"}
                  onValueChange={(color) => updateOption(index, { color })}
                >
                  <SelectTrigger className="text-sm">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {TAILWIND_COLORS.map((color) => (
                      <SelectItem key={color.value} value={color.value}>
                        <div className="flex items-center gap-2">
                          <div
                            className="w-3 h-3 rounded-full"
                            style={{
                              backgroundColor: `var(--${color.value}-500, #3b82f6)`,
                            }}
                          />
                          {color.name}
                        </div>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => removeOption(index)}
                className="flex-shrink-0"
              >
                <Trash2 className="w-4 h-4 text-destructive" />
              </Button>
            </div>
          ))}
        </div>
      )}

      {/* Add new option */}
      <div className="flex items-end gap-2">
        <div className="flex-1 grid grid-cols-3 gap-2">
          <div>
            <Label htmlFor="new-option-label" className="text-xs">
              Label
            </Label>
            <Input
              id="new-option-label"
              placeholder="e.g., Active"
              value={newLabel}
              onChange={(e) => setNewLabel(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault();
                  addOption();
                }
              }}
              className="text-sm"
            />
          </div>
          <div>
            <Label htmlFor="new-option-value" className="text-xs">
              Value
            </Label>
            <Input
              id="new-option-value"
              placeholder="e.g., active"
              value={newValue}
              onChange={(e) => setNewValue(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault();
                  addOption();
                }
              }}
              className="text-sm"
            />
          </div>
          <div>
            <Label htmlFor="new-option-color" className="text-xs">
              Color
            </Label>
            <Select value={newColor} onValueChange={setNewColor}>
              <SelectTrigger id="new-option-color" className="text-sm">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {TAILWIND_COLORS.map((color) => (
                  <SelectItem key={color.value} value={color.value}>
                    <div className="flex items-center gap-2">
                      <div
                        className="w-3 h-3 rounded-full"
                        style={{
                          backgroundColor: `var(--${color.value}-500, #3b82f6)`,
                        }}
                      />
                      {color.name}
                    </div>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>
        <Button
          size="sm"
          onClick={addOption}
          disabled={!newLabel.trim() || !newValue.trim()}
        >
          <Plus className="w-4 h-4" />
        </Button>
      </div>

      {options.length === 0 && (
        <p className="text-sm text-muted-foreground">
          Add at least one option to use this column type.
        </p>
      )}
    </div>
  );
}

/**
 * ReferenceCell Component
 * Displays a reference to another table's row
 * Now uses batch data to avoid N+1 query problem
 */

import { Link2, Loader2 } from 'lucide-react';

import { useReferenceRow } from '@/hooks/useReferenceRow';
import type { DatavaultColumn } from '@/lib/types/datavault';

interface ReferenceCellProps {
  value: any;
  column: DatavaultColumn;
  batchData?: Record<string, { displayValue: string; row: any }>;
}

export function ReferenceCell({ value, column, batchData }: ReferenceCellProps) {
  const tableId = column.reference?.tableId;
  const rowId = value;
  const displayColumnSlug = column.reference?.displayColumnSlug;

  // Use batch data if available (preferred - fixes N+1 query problem)
  // Fall back to individual query for backward compatibility
  const shouldUseBatch = batchData !== undefined;

  const { data: refRow, isLoading, isError } = useReferenceRow(
    tableId,
    rowId,
    displayColumnSlug,
    { enabled: !shouldUseBatch } // Only fetch if batch data not available
  );

  // Handle empty/null value
  if (!rowId) {
    return <span className="text-muted-foreground text-sm">ΓÇö</span>;
  }

  // Use batch data if available
  if (shouldUseBatch) {
    const batchItem = batchData[rowId];

    if (!batchItem) {
      return (
        <span className="inline-flex items-center gap-1.5 text-destructive text-sm">
          <Link2 className="w-3 h-3" />
          <span>Not found</span>
        </span>
      );
    }

    return (
      <span className="inline-flex items-center gap-1.5 text-sm">
        <Link2 className="w-3 h-3 text-violet-500 opacity-70" />
        <span className="truncate">{batchItem.displayValue}</span>
      </span>
    );
  }

  // Fallback to individual query (backward compatibility)
  if (isLoading) {
    return (
      <span className="inline-flex items-center gap-1.5 text-muted-foreground text-sm">
        <Loader2 className="w-3 h-3 animate-spin" />
        <span>Loading...</span>
      </span>
    );
  }

  if (isError || !refRow) {
    return (
      <span className="inline-flex items-center gap-1.5 text-destructive text-sm">
        <Link2 className="w-3 h-3" />
        <span>Not found</span>
      </span>
    );
  }

  return (
    <span className="inline-flex items-center gap-1.5 text-sm">
      <Link2 className="w-3 h-3 text-violet-500 opacity-70" />
      <span className="truncate">{refRow.displayValue}</span>
    </span>
  );
}

/**
 * RowEditorModal Component
 * Modal for adding or editing a row with dynamic form fields based on columns
 */

import { Loader2 } from "lucide-react";
import React, { useState, useEffect } from "react";

import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";

import type { DatavaultColumn } from "@shared/schema";

interface RowEditorModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  columns: DatavaultColumn[];
  initialValues?: Record<string, any>;
  onSubmit: (values: Record<string, any>) => Promise<void>;
  isLoading?: boolean;
  mode: "add" | "edit";
}

export function RowEditorModal({
  open,
  onOpenChange,
  columns,
  initialValues = {},
  onSubmit,
  isLoading = false,
  mode,
}: RowEditorModalProps) {
  const [values, setValues] = useState<Record<string, any>>({});

  // Initialize values when modal opens
  // Using open as the only dependency - we capture initialValues at open time
  useEffect(() => {
    if (open) {
      setValues(initialValues);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validate required fields (excluding auto_number fields which are auto-generated)
    const missingRequired = columns
      .filter((col) => col.required && col.type !== "auto_number" && !values[col.id])
      .map((col) => col.name);

    if (missingRequired.length > 0) {
      alert(`Please fill in required fields: ${missingRequired.join(", ")}`);
      return;
    }

    // Remove auto_number values from submission in add mode (backend will generate them)
    const submitValues = mode === "add"
      ? Object.fromEntries(
          Object.entries(values).filter(([key]) => {
            const column = columns.find(c => c.id === key);
            return column?.type !== "auto_number";
          })
        )
      : values;

    await onSubmit(submitValues);
    setValues({});
  };

  const handleCancel = () => {
    setValues({});
    onOpenChange(false);
  };

  const renderField = (column: DatavaultColumn) => {
    const value = values[column.id] ?? "";
    const isAutoNumber = column.type === "auto_number";
    const isReadOnly = isAutoNumber || isLoading;

    // Auto-number fields in add mode show placeholder, in edit mode show the value
    if (isAutoNumber && mode === "add") {
      return (
        <Input
          id={column.id}
          value="Auto-generated"
          disabled
          className="bg-muted text-muted-foreground"
        />
      );
    }

    switch (column.type) {
      case "text":
      case "email":
      case "phone":
      case "url":
        return (
          <Input
            id={column.id}
            type={column.type === "email" ? "email" : column.type === "url" ? "url" : "text"}
            value={value}
            onChange={(e) => { void setValues({ ...values, [column.id]: e.target.value }); }}
            required={column.required}
            disabled={isReadOnly}
          />
        );

      case "auto_number":
        return (
          <Input
            id={column.id}
            type="number"
            value={value}
            disabled
            className="bg-muted text-muted-foreground"
          />
        );

      case "json":
        return (
          <Textarea
            id={column.id}
            value={typeof value === "object" ? JSON.stringify(value, null, 2) : value}
            onChange={(e) => { void setValues({ ...values, [column.id]: e.target.value }); }}
            required={column.required}
            disabled={isReadOnly}
            rows={4}
          />
        );

      case "number":
        return (
          <Input
            id={column.id}
            type="number"
            value={value}
            onChange={(e) => { void setValues({ ...values, [column.id]: e.target.value }); }}
            required={column.required}
            disabled={isReadOnly}
          />
        );

      case "boolean":
        return (
          <div className="flex items-center space-x-2 pt-2">
            <Checkbox
              id={column.id}
              checked={Boolean(value)}
              onCheckedChange={(checked) => setValues({ ...values, [column.id]: checked })}
              disabled={isLoading}
            />
            <Label htmlFor={column.id} className="cursor-pointer">
              {value ? "Yes" : "No"}
            </Label>
          </div>
        );

      case "date":
        return (
          <Input
            id={column.id}
            type="date"
            value={value ? new Date(value).toISOString().split("T")[0] : ""}
            onChange={(e) => { void setValues({ ...values, [column.id]: e.target.value }); }}
            required={column.required}
            disabled={isReadOnly}
          />
        );

      case "datetime":
        return (
          <Input
            id={column.id}
            type="datetime-local"
            value={value ? new Date(value).toISOString().slice(0, 16) : ""}
            onChange={(e) => { void setValues({ ...values, [column.id]: e.target.value }); }}
            required={column.required}
            disabled={isReadOnly}
          />
        );

      default:
        return (
          <Input
            id={column.id}
            value={value}
            onChange={(e) => { void setValues({ ...values, [column.id]: e.target.value }); }}
            required={column.required}
            disabled={isReadOnly}
          />
        );
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[600px] max-h-[90vh] overflow-y-auto">
        <form onSubmit={(e) => { e.preventDefault(); void handleSubmit(e); }}>
          <DialogHeader>
            <DialogTitle>{mode === "add" ? "Add Row" : "Edit Row"}</DialogTitle>
            <DialogDescription>
              {mode === "add" ? "Add a new row to the table" : "Update the row data"}
            </DialogDescription>
          </DialogHeader>

          <div className="grid gap-4 py-4">
            {columns.length === 0 ? (
              <p className="text-sm text-muted-foreground text-center py-4">
                No columns defined. Add columns first before adding rows.
              </p>
            ) : (
              columns.map((column) => (
                <div key={column.id} className="grid gap-2">
                  <Label htmlFor={column.id}>
                    {column.name}
                    {column.required && column.type !== "auto_number" && <span className="text-destructive ml-1">*</span>}
                    <span className="text-xs text-muted-foreground ml-2">
                      ({column.type}{column.type === "auto_number" ? " - auto-generated" : ""})
                    </span>
                  </Label>
                  {renderField(column)}
                </div>
              ))
            )}
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => { void handleCancel(); }} disabled={isLoading}>
              Cancel
            </Button>
            <Button type="submit" disabled={isLoading || columns.length === 0}>
              {isLoading && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
              {mode === "add" ? "Add Row" : "Save Changes"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

/**
 * Sortable Column Header Component (PR 8)
 * Draggable column header with type icon and reorder handle
 */

import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { GripVertical } from "lucide-react";
import React from "react";

import type { DatavaultColumn } from "@shared/schema";

import { ColumnTypeIcon, getColumnTypeColor } from "./ColumnTypeIcon";


interface SortableColumnHeaderProps {
  column: DatavaultColumn;
  isFirst?: boolean;
}

export function SortableColumnHeader({ column, isFirst = false }: SortableColumnHeaderProps) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({
    id: column.id,
  });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };

  return (
    <th
      ref={setNodeRef}
      style={style}
      className={`text-left text-sm font-semibold text-foreground min-w-[150px] bg-muted/50 border-l border-border ${isFirst ? 'border-l-0' : ''}`}
    >
      <div className="flex items-center">
        {/* Drag handle zone - more pronounced */}
        <span
          {...listeners}
          {...attributes}
          className="flex items-center justify-center w-8 h-full py-3 cursor-grab active:cursor-grabbing touch-none bg-muted/70 hover:bg-accent border-r border-border/50 transition-colors"
          title="Drag to reorder column"
        >
          <GripVertical className="w-4 h-4 text-muted-foreground" />
        </span>

        {/* Column content */}
        <div className="flex items-center gap-2 px-3 py-3">
          {/* Type icon */}
          <ColumnTypeIcon
            type={column.type}
            className={getColumnTypeColor(column.type)}
          />

          {/* Column name */}
          <span className="font-semibold">{column.name}</span>

          {/* Primary key badge */}
          {column.isPrimaryKey && (
            <span className="text-xs bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300 px-1.5 py-0.5 rounded">
              PK
            </span>
          )}

          {/* Required indicator */}
          {column.required && <span className="text-xs text-red-500">*</span>}
        </div>
      </div>
    </th>
  );
}

