/**
 * VariableList Component
 * Displays workflow variables with Copy/Insert/Pin actions
 */

import { Copy, Plus, Pin, Search } from "lucide-react";
import { useState } from "react";

import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { ScrollArea } from "@/components/ui/scroll-area";
import { useToast } from "@/hooks/use-toast";
import { DevPanelBus } from "@/lib/devpanelBus";
import { cn } from "@/lib/utils";
import type { ApiWorkflowVariable } from "@/lib/vault-api";
import { useDevPanel } from "@/store/devpanel";

interface VariableListProps {
  workflowId: string;
  variables: ApiWorkflowVariable[];
  isLoading?: boolean;
}

export function VariableList({ workflowId, variables, isLoading }: VariableListProps) {
  const [searchQuery, setSearchQuery] = useState("");
  const { toast } = useToast();
  const { isPinned, togglePin } = useDevPanel();

  // Filter variables based on search query
  const filteredVariables = variables.filter((v) => {
    const searchText = searchQuery.toLowerCase();
    return (
      v.alias?.toLowerCase().includes(searchText) ||
      v.label.toLowerCase().includes(searchText) ||
      v.key.toLowerCase().includes(searchText)
    );
  });

  // Group by section
  const groupedVariables = filteredVariables.reduce((acc, variable) => {
    const section = variable.sectionTitle || "Uncategorized";
    if (!acc[section]) {
      acc[section] = [];
    }
    acc[section].push(variable);
    return acc;
  }, {} as Record<string, ApiWorkflowVariable[]>);

  // Sort sections alphabetically
  const sortedSections = Object.keys(groupedVariables).sort();

  const handleCopy = (key: string) => {
    navigator.clipboard.writeText(key).then(() => {
      toast({
        title: "Copied",
        description: `Variable key "${key}" copied to clipboard`,
      });
    });
  };

  const handleInsert = (key: string) => {
    DevPanelBus.emitInsert(key);
  };

  const handlePin = (key: string) => {
    togglePin(workflowId, key);
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-full text-muted-foreground">
        Loading variables...
      </div>
    );
  }

  if (variables.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-full text-muted-foreground p-4 text-center">
        <p>No variables available</p>
        <p className="text-xs mt-2">Add questions to your workflow to create variables</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full">
      {/* Search Bar */}
      <div className="p-3 border-b">
        <div className="relative">
          <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Search variables..."
            value={searchQuery}
            onChange={(e) => { void setSearchQuery(e.target.value); }}
            className="pl-8"
          />
        </div>
      </div>

      {/* Variables List */}
      <ScrollArea className="flex-1">
        <div className="p-2">
          {filteredVariables.length === 0 ? (
            <div className="text-center text-muted-foreground text-sm py-4">
              No variables match your search
            </div>
          ) : (
            <Accordion
              type="multiple"
              defaultValue={sortedSections} // Default expand all to see content
              className="w-full space-y-2"
            >
              {sortedSections.map((sectionTitle) => (
                <AccordionItem key={sectionTitle} value={sectionTitle} className="border rounded-md px-2">
                  <AccordionTrigger className="py-2 hover:no-underline hover:bg-muted/50 -mx-2 px-2 rounded-t-md data-[state=open]:rounded-b-none">
                    <div className="flex items-center gap-2">
                      <span className="font-medium text-sm">{sectionTitle}</span>
                      <span className="text-xs text-muted-foreground bg-muted px-1.5 py-0.5 rounded-full">
                        {groupedVariables[sectionTitle].length}
                      </span>
                    </div>
                  </AccordionTrigger>
                  <AccordionContent className="pb-2 pt-1">
                    <div className="space-y-1">
                      {groupedVariables[sectionTitle].map((variable) => {
                        const displayKey = variable.alias || variable.key;
                        const pinned = isPinned(workflowId, displayKey);

                        return (
                          <div
                            key={variable.stepId}
                            className={cn(
                              "group flex items-start gap-2 p-2 rounded-md hover:bg-accent transition-colors",
                              pinned && "bg-accent/50"
                            )}
                          >
                            {/* Variable Info */}
                            <div className="flex-1 min-w-0">
                              <div className="font-mono text-sm font-medium truncate">
                                {displayKey}
                              </div>
                              <div className="text-xs text-muted-foreground truncate">
                                {variable.label}
                              </div>
                              <div className="text-xs text-muted-foreground">
                                {variable.type}
                              </div>
                            </div>

                            {/* Actions */}
                            <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                              <Button
                                size="icon"
                                variant="ghost"
                                className="h-7 w-7"
                                onClick={() => { void handleCopy(displayKey); }}
                                title="Copy to clipboard"
                              >
                                <Copy className="h-3.5 w-3.5" />
                              </Button>
                              <Button
                                size="icon"
                                variant="ghost"
                                className="h-7 w-7"
                                onClick={() => { void handleInsert(displayKey); }}
                                title="Insert into editor"
                              >
                                <Plus className="h-3.5 w-3.5" />
                              </Button>
                              <Button
                                size="icon"
                                variant="ghost"
                                className={cn(
                                  "h-7 w-7",
                                  pinned && "text-primary opacity-100"
                                )}
                                onClick={() => { void handlePin(displayKey); }}
                                title={pinned ? "Unpin" : "Pin"}
                              >
                                <Pin className={cn("h-3.5 w-3.5", pinned && "fill-current")} />
                              </Button>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </AccordionContent>
                </AccordionItem>
              ))}
            </Accordion>
          )}
        </div>
      </ScrollArea>
    </div>
  );
}

import { useState, useMemo } from "react";

import { ExecutionTimeline } from "@/components/devpanel/ExecutionTimeline";
import { RuntimeVariableList } from "@/components/devpanel/RuntimeVariableList";
import { UnifiedDevPanel } from "@/components/devpanel/UnifiedDevPanel";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { PreviewEnvironment } from "@/lib/previewRunner/PreviewEnvironment";
import { usePreviewEnvironment } from "@/lib/previewRunner/usePreviewEnvironment";
import { ApiWorkflowVariable } from "@/lib/vault-api";

import { JsonViewer } from "./JsonViewer";


interface DevToolsPanelProps {
    env: PreviewEnvironment | null;
    isOpen: boolean;
    onClose: () => void;
}

export function DevToolsPanel({ env, isOpen, onClose }: DevToolsPanelProps) {
    const state = usePreviewEnvironment(env);
    const [localOpen, setLocalOpen] = useState(true);

    const variables = useMemo<ApiWorkflowVariable[]>(() => {
        if (!state || !env) {return [];}

        // Map steps to variables
        return env.getSteps()
            .map(step => {
                const section = env.getSections().find(s => s.id === step.sectionId);
                return {
                    key: step.id,
                    alias: step.alias ?? null,
                    label: step.title,
                    type: step.type,
                    sectionId: step.sectionId,
                    sectionTitle: section?.title || "Unknown Section",
                    stepId: step.id
                };
            })
            .filter(v => v.sectionTitle !== "Final Documents");
    }, [state, env]);

    // ALL HOOKS MUST BE CALLED BEFORE ANY CONDITIONAL RETURNS
    // Determine the effective toggle handler based on parent's onClose or local intent
    // The requirement says "minimize to Sidebar", so we should ideally control the open state
    // But PreviewRunner might be controlling the overall visibility.
    // However, Builder's "DevPanel" controls its own width (w-0 vs w-[360px]) based on isOpen props.
    // We'll use local state to toggle between collapsed and expanded sidebar,
    // assuming 'isOpen' from props means "Dev Tools Enabled/Visible at all".

    const contextValues = useMemo(() => {
        if (!state || !env) {return {};}
        const values = { ...state.values };
        const steps = env.getSteps();

        const contextAwareValues: Record<string, any> = {};

        // Helper to deep set values
        const deepSet = (obj: Record<string, any>, path: string[], value: any) => {
            let current = obj;
            for (let i = 0; i < path.length - 1; i++) {
                const key = path[i];
                // If the key doesn't exist, create an object
                if (!(key in current)) {
                    current[key] = {};
                }
                // If it exists but isn't an object (collision), we have a problem.
                if (current[key] !== undefined && (typeof current[key] !== 'object' || current[key] === null)) {
                    // Collision: Primitive blocks path. Skip this nested value to prevent crash.
                    return;
                }
                current = current[key];
            }
            const lastKey = path[path.length - 1];
            current[lastKey] = value;
        };

        // First pass: Put all values in.
        // We need to handle the case where "pet" (object) and "pet.email" (string) both exist.
        // If "pet.email" is processed BEFORE "pet" (object), we create { pet: { email: ... } }.
        // Then "pet" (object) comes along and overwrites it!
        // So we should process "deep" objects (shorter keys / objects) first? 
        // Or process everything and do a smart merge?

        // Better strategy:
        // 1. Map all entries to { path: string[], value: any }
        // 2. Sort by path length? Or just use a deep merge utility.

        Object.entries(values).forEach(([stepId, value]) => {
            if (value === undefined || value === null) {return;}

            const step = steps.find(s => s.id === stepId);
            const key = step?.alias || stepId;
            const path = key.split('.');

            if (path.length === 1) {
                // Top level assignment
                // If existing value is an object (created by a previous nested child), we should merge this value into it?
                // Example: processed 'pet.email' -> context['pet'] = { email: ... }
                // Now processing 'pet' -> value is { street: ... }
                // We should merge { street: ... } into existing { email: ... }
                if (contextAwareValues[key] && typeof contextAwareValues[key] === 'object' && typeof value === 'object') {
                    Object.assign(contextAwareValues[key], value);
                } else {
                    // Overwrite (or first assignment)
                    // If we overwrite an existing object created by children, we lose those children!
                    // So if existing is object, we must merge.
                    if (contextAwareValues[key] && typeof contextAwareValues[key] === 'object') {
                        if (typeof value === 'object') {
                            Object.assign(contextAwareValues[key], value);
                        } else {
                            // Collision: existing is object (container), new is primitive.
                            // Rare case. Just overwrite? 
                            contextAwareValues[key] = value;
                        }
                    } else {
                        contextAwareValues[key] = value;
                    }
                }
            } else {
                // Nested assignment
                deepSet(contextAwareValues, path, value);
            }
        });

        // Re-sorting keys for display?
        // JS objects preserve insertion order mostly, but recursive structure is what matters.
        return contextAwareValues;
    }, [state, env]);

    // Conditional return AFTER all hooks have been called
    if (!isOpen || !state) {return null;}

    return (
        <div className="h-full flex flex-col pointer-events-auto">
            <UnifiedDevPanel
                workflowId={state.workflowId}
                isOpen={localOpen}
                onToggle={() => setLocalOpen(!localOpen)}
                className="border-l shadow-xl h-full"
            >
                <Tabs defaultValue="variables" className="h-full flex flex-col">
                    <div className="px-3 py-2 border-b">
                        <TabsList className="w-full grid grid-cols-3">
                            <TabsTrigger value="variables">Variables</TabsTrigger>
                            <TabsTrigger value="execution">Execution</TabsTrigger>
                            <TabsTrigger value="json">JSON</TabsTrigger>
                        </TabsList>
                    </div>

                    <TabsContent value="variables" className="flex-1 mt-0 overflow-hidden">
                        <RuntimeVariableList
                            workflowId={state.workflowId}
                            variables={variables}
                            values={state.values}
                        />
                    </TabsContent>

                    <TabsContent value="execution" className="flex-1 mt-0 overflow-hidden">
                        <ExecutionTimeline
                            trace={state.trace ?? []}
                        />
                    </TabsContent>

                    <TabsContent value="json" className="flex-1 mt-0 p-0 overflow-hidden">
                        <JsonViewer
                            data={contextValues}
                            className="w-full h-full"
                        />
                    </TabsContent>
                </Tabs>
            </UnifiedDevPanel>
        </div>
    );
}

import { ChevronRight, ChevronDown, Copy, Check } from "lucide-react";
import React, { useState, useEffect, useRef } from "react";

import { cn } from "@/lib/utils";
interface JsonViewerProps {
    data: Record<string, any>;
    className?: string;
}
// Hook to detect dark mode from HTML class
function useDarkModeObserver() {
    const [isDark, setIsDark] = useState(document.documentElement.classList.contains("dark"));
    useEffect(() => {
        const observer = new MutationObserver((mutations) => {
            mutations.forEach((mutation) => {
                if (mutation.attributeName === "class") {
                    setIsDark(document.documentElement.classList.contains("dark"));
                }
            });
        });
        observer.observe(document.documentElement, {
            attributes: true,
            attributeFilter: ["class"],
        });
        return () => observer.disconnect();
    }, []);
    return isDark;
}
// Helper to check if two values are effectively different
function isDifferent(val1: any, val2: any): boolean {
    if (val1 === val2) { return false; }
    if (typeof val1 !== typeof val2) { return true; }
    if (typeof val1 === 'object' && val1 !== null && val2 !== null) {
        if (Array.isArray(val1) !== Array.isArray(val2)) { return true; }
        return JSON.stringify(val1) !== JSON.stringify(val2);
    }
    return true;
}
export function JsonViewer({ data, className }: JsonViewerProps) {
    const isDark = useDarkModeObserver();
    const prevDataRef = useRef<Record<string, any>>({});
    const [changedPaths, setChangedPaths] = useState<Map<string, number>>(new Map());
    // Calculate changed paths
    useEffect(() => {
        const prevData = prevDataRef.current;
        const now = Date.now();
        const newChanges = new Map<string, number>();
        // Flatten keys to check changes? Or just recursive check?
        // Simple recursive diff
        function findChanges(current: any, prev: any, path: string) {
            if (isDifferent(current, prev)) {
                newChanges.set(path, now);
            }
            if (typeof current === 'object' && current !== null && typeof prev === 'object' && prev !== null) {
                Object.keys(current).forEach(key => {
                    const nextPath = path ? `${path}.${key}` : key;
                    findChanges(current[key], prev[key], nextPath);
                });
            }
        }
        findChanges(data, prevData, "");
        if (newChanges.size > 0) {
            setChangedPaths(prev => {
                const map = new Map(prev);
                newChanges.forEach((ts, path) => map.set(path, ts));
                return map;
            });
            // Cleanup
            setTimeout(() => {
                setChangedPaths(current => {
                    const threshold = Date.now() - 5000;
                    const map = new Map();
                    current.forEach((ts, path) => {
                        if (ts > threshold) { map.set(path, ts); }
                    });
                    return map;
                });
            }, 5000);
        }
        prevDataRef.current = data;
    }, [data]);
    return (
        <div className={cn("text-xs font-mono h-full w-full overflow-auto p-2 bg-slate-50 dark:bg-slate-950/50", className)}>
            <JsonNode
                name="root"
                value={data}
                isLast={true}
                depth={0}
                path=""
                changedPaths={changedPaths}
                initiallyExpanded={true}
            />
        </div>
    );
}
interface JsonNodeProps {
    name: string | null;
    value: any;
    isLast: boolean;
    depth: number;
    path: string;
    changedPaths: Map<string, number>;
    initiallyExpanded?: boolean;
}
function JsonNode({ name, value, isLast, depth, path, changedPaths, initiallyExpanded = false }: JsonNodeProps) {
    const [expanded, setExpanded] = useState(initiallyExpanded);
    const [copied, setCopied] = useState(false);
    // Highlight logic
    const lastChange = changedPaths.get(path);
    const isHighlighted = lastChange && (Date.now() - lastChange < 2000); // 2s highlight
    const isObject = typeof value === 'object' && value !== null;
    const isArray = Array.isArray(value);
    const isEmpty = isObject && Object.keys(value).length === 0;
    const handleCopy = (e: React.MouseEvent, text: string) => {
        e.stopPropagation();
        navigator.clipboard.writeText(text);
        setCopied(true);
        setTimeout(() => setCopied(false), 1500);
    };
    const getTypeColor = (val: any) => {
        if (val === null) { return "text-rose-500"; }
        switch (typeof val) {
            case 'string': return "text-emerald-600 dark:text-emerald-400";
            case 'number': return "text-blue-600 dark:text-blue-400";
            case 'boolean': return "text-purple-600 dark:text-purple-400";
            default: return "text-gray-600 dark:text-gray-400";
        }
    };
    const renderValue = (val: any) => {
        if (val === null) { return "null"; }
        if (typeof val === 'string') { return `"${val}"`; }
        return String(val);
    };
    const containerClass = cn(
        "flex items-start group rounded-sm px-1 -ml-1 border border-transparent transition-colors",
        isHighlighted ? "bg-yellow-100 dark:bg-yellow-900/30 duration-500" : "hover:bg-black/5 dark:hover:bg-white/5",
        // isHighlighted ? "animate-category-pulse" : "" 
    );
    if (isObject) {
        const keys = Object.keys(value);
        return (
            <div className="ml-0">
                <div className={containerClass} onClick={() => { if (!isEmpty) {setExpanded(!expanded);} }}>
                    {/* Toggle */}
                    {!isEmpty ? (
                        <span className="cursor-pointer mr-1 mt-0.5 opacity-50 hover:opacity-100">
                            {expanded ? <ChevronDown className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
                        </span>
                    ) : <span className="w-4 mr-1"></span>}
                    {/* Key */}
                    {name && (
                        <span className="text-indigo-600 dark:text-indigo-400 mr-1 select-text" onDoubleClick={(e) => handleCopy(e, path)}>
                            {name}:
                        </span>
                    )}
                    {/* Preview */}
                    <span className="text-gray-500 dark:text-gray-400">
                        {isArray ? "[" : "{"}
                        {!expanded && !isEmpty && (
                            <span className="mx-1 text-gray-400 italic">
                                {keys.length} {keys.length === 1 ? 'item' : 'items'}
                            </span>
                        )}
                        {isEmpty && (isArray ? "]" : "}")}
                    </span>
                    {/* Tools */}
                    <div className="ml-auto opacity-0 group-hover:opacity-100 flex gap-2">
                        <button onClick={(e) => handleCopy(e, JSON.stringify(value, null, 2))} title="Copy Value">
                            {copied ? <Check className="w-3 h-3 text-green-500" /> : <Copy className="w-3 h-3 text-gray-400 hover:text-gray-600" />}
                        </button>
                    </div>
                </div>
                {/* Children */}
                {expanded && !isEmpty && (
                    <div className="ml-4 border-l border-gray-200 dark:border-gray-800 pl-2">
                        {keys.map((key, i) => (
                            <JsonNode
                                key={key}
                                name={isArray ? null : key} // Don't show index keys for arrays generally, or do? usually no.
                                // Actually for debugging, index is useful `[0]`. But user prefers cleanly list.
                                // Let's show index if array?
                                value={value[key]}
                                isLast={i === keys.length - 1}
                                depth={depth + 1}
                                path={path ? `${path}.${key}` : key}
                                changedPaths={changedPaths}
                            />
                        ))}
                    </div>
                )}
                {expanded && !isEmpty && (
                    <div className="ml-4 pl-1 text-gray-500 dark:text-gray-400">
                        {isArray ? "]" : "}"}{!isLast && ","}
                    </div>
                )}
            </div>
        )
    }
    // Primitive
    return (
        <div className={containerClass}>
            <span className="w-4 mr-1"></span> {/* Indent spacer for leaves */}
            {name && (
                <span className="text-indigo-600 dark:text-indigo-400 mr-1 select-text" title={path} onDoubleClick={(e) => handleCopy(e, path)}>
                    {name}:
                </span>
            )}
            <span
                className={cn("break-all select-text", getTypeColor(value))}
            >
                {renderValue(value)}
            </span>
            {!isLast && <span className="text-gray-400">,</span>}
            {/* Tools */}
            <div className="ml-auto opacity-0 group-hover:opacity-100 flex gap-2">
                <button onClick={(e) => handleCopy(e, String(value))} title="Copy Value">
                    {copied ? <Check className="w-3 h-3 text-green-500" /> : <Copy className="w-3 h-3 text-gray-400 hover:text-gray-600" />}
                </button>
            </div>
        </div>
    );
}

import { AlertCircle, User, Users } from 'lucide-react';
import { useState } from 'react';

import { Button } from '@/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group';
import { useAuth } from '@/hooks/useAuth';
import { useOrganizations } from '@/hooks/useOrganizations';

export type AssetType = 'workflow' | 'project' | 'database';

interface TransferOwnershipDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  assetType: AssetType;
  assetName: string;
  onTransfer: (targetOwnerType: 'user' | 'org', targetOwnerUuid: string) => Promise<void>;
  isPending?: boolean;
}

export function TransferOwnershipDialog({
  open,
  onOpenChange,
  assetType,
  assetName,
  onTransfer,
  isPending = false,
}: TransferOwnershipDialogProps) {
  const { user } = useAuth();
  const { data: organizations, isLoading: orgsLoading } = useOrganizations();

  const [selectedOwner, setSelectedOwner] = useState<string>('');

  const handleTransfer = async () => {
    if (!selectedOwner) {return;}

    const [ownerType, ownerUuid] = selectedOwner.split(':') as ['user' | 'org', string];

    try {
      await onTransfer(ownerType, ownerUuid);
      onOpenChange(false);
      setSelectedOwner('');
    } catch (error) {
      // Error handling done by parent
      console.error('Transfer failed:', error);
    }
  };

  const getAssetLabel = () => {
    switch (assetType) {
      case 'workflow':
        return 'workflow';
      case 'project':
        return 'project';
      case 'database':
        return 'database';
      default:
        return 'asset';
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>Transfer Ownership</DialogTitle>
          <DialogDescription>
            Transfer {getAssetLabel()} "{assetName}" to a new owner
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-4">
          {/* Warning */}
          <div className="flex items-start space-x-2 p-3 bg-amber-50 border border-amber-200 rounded-lg">
            <AlertCircle className="h-5 w-5 text-amber-600 mt-0.5 flex-shrink-0" />
            <div className="text-sm text-amber-800">
              <p className="font-medium mb-1">Important</p>
              <p>
                Transferring to an organization will make this {getAssetLabel()} available to
                everyone in that organization.
                {assetType === 'project' && ' All workflows in this project will also be transferred.'}
              </p>
            </div>
          </div>

          {/* Owner Selection */}
          <div className="space-y-3">
            <Label className="text-base font-medium">Transfer to...</Label>

            {orgsLoading ? (
              <div className="text-center py-4">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mx-auto"></div>
                <p className="text-sm text-muted-foreground mt-2">Loading options...</p>
              </div>
            ) : (
              <RadioGroup value={selectedOwner} onValueChange={setSelectedOwner}>
                {/* My Account Option */}
                <div className="flex items-center space-x-2 p-3 rounded-lg border hover:bg-accent cursor-pointer">
                  <RadioGroupItem value={`user:${user?.id}`} id="owner-user" />
                  <Label htmlFor="owner-user" className="flex items-center space-x-3 cursor-pointer flex-1">
                    <div className="w-10 h-10 bg-primary/10 rounded-full flex items-center justify-center">
                      <User className="h-5 w-5 text-primary" />
                    </div>
                    <div>
                      <p className="font-medium">My Account</p>
                      <p className="text-sm text-muted-foreground">{user?.email}</p>
                    </div>
                  </Label>
                </div>

                {/* Organizations */}
                {organizations && organizations.length > 0 && (
                  <>
                    <div className="pt-2">
                      <Label className="text-sm text-muted-foreground">Organizations</Label>
                    </div>
                    {organizations.map((org) => (
                      <div
                        key={org.id}
                        className="flex items-center space-x-2 p-3 rounded-lg border hover:bg-accent cursor-pointer"
                      >
                        <RadioGroupItem value={`org:${org.id}`} id={`owner-${org.id}`} />
                        <Label
                          htmlFor={`owner-${org.id}`}
                          className="flex items-center space-x-3 cursor-pointer flex-1"
                        >
                          <div className="w-10 h-10 bg-purple-100 rounded-full flex items-center justify-center">
                            <Users className="h-5 w-5 text-purple-600" />
                          </div>
                          <div>
                            <div className="flex items-center space-x-2">
                              <p className="font-medium">{org.name}</p>
                              {org.role === 'admin' && (
                                <span className="text-xs px-2 py-0.5 rounded-full bg-primary/10 text-primary">
                                  Admin
                                </span>
                              )}
                            </div>
                            {org.description && (
                              <p className="text-sm text-muted-foreground line-clamp-1">
                                {org.description}
                              </p>
                            )}
                          </div>
                        </Label>
                      </div>
                    ))}
                  </>
                )}

                {(!organizations || organizations.length === 0) && (
                  <div className="text-center py-4 text-sm text-muted-foreground">
                    <p>You don't belong to any organizations yet.</p>
                    <p className="mt-1">Create one to transfer assets to your team.</p>
                  </div>
                )}
              </RadioGroup>
            )}
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => { void onOpenChange(false); }} disabled={isPending}>
            Cancel
          </Button>
          <Button
            onClick={() => { void handleTransfer(); }}
            disabled={!selectedOwner || isPending}
          >
            {isPending ? 'Transferring...' : 'Transfer Ownership'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useQuery } from "@tanstack/react-query";
import { format } from "date-fns";
import { ArrowLeft, FileText } from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { ScrollArea } from "@/components/ui/scroll-area";
import { runAPI } from "@/lib/vault-api";
interface ExecutionDetailViewProps {
    runId: string;
    onBack: () => void;
}
export function ExecutionDetailView({ runId, onBack }: ExecutionDetailViewProps) {
    const { data: run, isLoading } = useQuery({
        queryKey: ['run-detail', runId],
        queryFn: () => runAPI.getWithValues(runId),
    });
    const { data: documents } = useQuery({
        queryKey: ['run-documents', runId],
        queryFn: () => runAPI.getDocuments(runId),
    });
    if (isLoading) {
        return <div className="p-8 text-center">Loading execution details...</div>;
    }
    if (!run) {
        return <div className="p-8 text-center text-destructive">Execution not found.</div>;
    }
    const duration = run.completed && run.completedAt
        ? Math.round((new Date(run.completedAt).getTime() - new Date(run.createdAt).getTime()) / 1000)
        : null;
    return (
        <div className="flex flex-col h-full bg-muted/10">
            <div className="flex items-center gap-2 p-4 border-b bg-background">
                <Button variant="ghost" size="sm" onClick={onBack}>
                    <ArrowLeft className="w-4 h-4 mr-1" /> Back
                </Button>
                <div className="flex-1">
                    <h3 className="font-semibold flex items-center gap-2">
                        Execution #{run.id.substring(0, 8)}
                        {run.completed ? (
                            <Badge className="bg-green-100 text-green-800 border-green-200">Completed</Badge>
                        ) : (
                            <Badge variant="secondary">In Progress</Badge>
                        )}
                    </h3>
                    <p className="text-xs text-muted-foreground">
                        {format(new Date(run.createdAt), "PPP p")}  ΓÇó v{run.versionId.substring(0, 8)}
                    </p>
                </div>
                {duration && (
                    <div className="text-sm text-muted-foreground font-mono bg-muted px-2 py-1 rounded">
                        duration: {duration}s
                    </div>
                )}
            </div>
            <ScrollArea className="flex-1 p-6">
                <div className="space-y-6 max-w-4xl mx-auto">
                    {/* Metadata Card */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <Card>
                            <CardHeader className="pb-2">
                                <CardTitle className="text-sm font-medium text-muted-foreground">Type</CardTitle>
                            </CardHeader>
                            <CardContent>
                                <div className="text-lg font-semibold capitalize">
                                    {run.participantId ? "User Session" : "Anonymous / Test"}
                                </div>
                            </CardContent>
                        </Card>
                        <Card>
                            <CardHeader className="pb-2">
                                <CardTitle className="text-sm font-medium text-muted-foreground">Step Values</CardTitle>
                            </CardHeader>
                            <CardContent>
                                <div className="text-lg font-semibold">{run.values?.length || 0}</div>
                            </CardContent>
                        </Card>
                        <Card>
                            <CardHeader className="pb-2">
                                <CardTitle className="text-sm font-medium text-muted-foreground">Generated Docs</CardTitle>
                            </CardHeader>
                            <CardContent>
                                <div className="text-lg font-semibold">{documents?.length || 0}</div>
                            </CardContent>
                        </Card>
                    </div>
                    {/* Documents */}
                    {documents && documents.length > 0 && (
                        <Card>
                            <CardHeader>
                                <CardTitle className="text-base flex items-center gap-2">
                                    <FileText className="w-4 h-4 text-primary" /> Generated Documents
                                </CardTitle>
                            </CardHeader>
                            <CardContent className="grid gap-2">
                                {documents.map((doc: any) => (
                                    <div key={doc.id} className="flex items-center justify-between p-3 bg-muted/30 rounded border">
                                        <span className="font-medium text-sm">{doc.name}</span>
                                        <Badge variant="outline">{doc.fileType}</Badge>
                                    </div>
                                ))}
                            </CardContent>
                        </Card>
                    )}
                    {/* Variable State */}
                    <Card>
                        <CardHeader>
                            <CardTitle className="text-base">Captured Values</CardTitle>
                            <CardDescription>
                                Data collected during this execution.
                            </CardDescription>
                        </CardHeader>
                        <CardContent>
                            {run.values && run.values.length > 0 ? (
                                <div className="rounded-md border">
                                    <table className="w-full text-sm">
                                        <thead className="bg-muted/50 text-left">
                                            <tr>
                                                <th className="p-3 font-medium text-muted-foreground">Step / ID</th>
                                                <th className="p-3 font-medium text-muted-foreground">Value</th>
                                                <th className="p-3 font-medium text-muted-foreground w-32">Time</th>
                                            </tr>
                                        </thead>
                                        <tbody className="divide-y">
                                            {run.values.map((val: any) => (
                                                <tr key={val.id}>
                                                    <td className="p-3 font-mono text-xs">{val.stepId}</td>
                                                    <td className="p-3">
                                                        <code className="bg-muted px-1.5 py-0.5 rounded text-xs break-all">
                                                            {JSON.stringify(val.value)}
                                                        </code>
                                                    </td>
                                                    <td className="p-3 text-xs text-muted-foreground">
                                                        {format(new Date(val.updatedAt), "HH:mm:ss")}
                                                    </td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                            ) : (
                                <div className="text-center py-8 text-muted-foreground italic">
                                    No data captured in this run.
                                </div>
                            )}
                        </CardContent>
                    </Card>
                </div>
            </ScrollArea>
        </div>
    );
}

/**
 * Stage 17: Intake Demo Component
 *
 * Demonstration of themed intake portal components
 * Useful for preview and testing
 */

import React, { useState } from 'react';

import IntakeLayout from './IntakeLayout';
import IntakeProgressBar from './IntakeProgressBar';
import ThemedButton from './ThemedButton';
import { ThemedInput, ThemedTextarea } from './ThemedInput';

export interface IntakeDemoProps {
  /** Custom header text */
  headerText?: string;

  /** Custom logo URL */
  logoUrl?: string;
}

/**
 * Demo intake portal showing all themed components
 *
 * Use this with BrandingProvider to see branding in action:
 * ```tsx
 * <BrandingProvider tenantId={tenantId} enableTheming={true}>
 *   <IntakeDemo />
 * </BrandingProvider>
 * ```
 */
export default function IntakeDemo({ headerText, logoUrl }: IntakeDemoProps) {
  const [currentStep, setCurrentStep] = useState(1);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    message: '',
  });

  const totalSteps = 3;

  const handleNext = () => {
    if (currentStep < totalSteps) {
      setCurrentStep(currentStep + 1);
    }
  };

  const handlePrevious = () => {
    if (currentStep > 1) {
      setCurrentStep(currentStep - 1);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    alert('Form submitted! (This is a demo)');
  };

  return (
    <IntakeLayout headerText={headerText} logoUrl={logoUrl}>
      <div className="max-w-2xl mx-auto px-6 py-8">
        {/* Progress Bar */}
        <IntakeProgressBar
          currentStep={currentStep}
          totalSteps={totalSteps}
          showPercentage={true}
          showStepCount={true}
          className="mb-8"
        />

        {/* Form Steps */}
        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Step 1: Personal Information */}
          {currentStep === 1 && (
            <div className="space-y-6">
              <div>
                <h2
                  className="text-2xl font-bold mb-2"
                  style={{ color: 'var(--brand-heading, #0F172A)' }}
                >
                  Personal Information
                </h2>
                <p style={{ color: 'var(--brand-text-muted, #64748B)' }}>
                  Please provide your basic information
                </p>
              </div>

              <ThemedInput
                label="Full Name"
                type="text"
                placeholder="John Doe"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                showRequired
              />

              <ThemedInput
                label="Email Address"
                type="email"
                placeholder="john@example.com"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                helperText="We'll never share your email with anyone else"
                showRequired
              />

              <ThemedInput
                label="Phone Number"
                type="tel"
                placeholder="(555) 123-4567"
                value={formData.phone}
                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
              />
            </div>
          )}

          {/* Step 2: Additional Details */}
          {currentStep === 2 && (
            <div className="space-y-6">
              <div>
                <h2
                  className="text-2xl font-bold mb-2"
                  style={{ color: 'var(--brand-heading, #0F172A)' }}
                >
                  Additional Details
                </h2>
                <p style={{ color: 'var(--brand-text-muted, #64748B)' }}>
                  Tell us more about your needs
                </p>
              </div>

              <ThemedTextarea
                label="Message"
                placeholder="Please describe your inquiry..."
                value={formData.message}
                onChange={(e) => setFormData({ ...formData, message: e.target.value })}
                rows={6}
                helperText="Provide as much detail as possible"
                showRequired
              />

              {/* Example of multiple choice */}
              <div className="space-y-3">
                <label
                  className="block text-sm font-medium"
                  style={{ color: 'var(--brand-text, #0F172A)' }}
                >
                  How did you hear about us? <span className="text-red-500">*</span>
                </label>
                <div className="space-y-2">
                  {['Search Engine', 'Social Media', 'Referral', 'Other'].map((option) => (
                    <label
                      key={option}
                      className="flex items-center gap-2 cursor-pointer"
                      style={{ color: 'var(--brand-text, #0F172A)' }}
                    >
                      <input
                        type="radio"
                        name="source"
                        value={option}
                        className="h-4 w-4"
                        style={{ accentColor: 'var(--brand-primary, #3B82F6)' }}
                      />
                      <span>{option}</span>
                    </label>
                  ))}
                </div>
              </div>
            </div>
          )}

          {/* Step 3: Review */}
          {currentStep === 3 && (
            <div className="space-y-6">
              <div>
                <h2
                  className="text-2xl font-bold mb-2"
                  style={{ color: 'var(--brand-heading, #0F172A)' }}
                >
                  Review & Submit
                </h2>
                <p style={{ color: 'var(--brand-text-muted, #64748B)' }}>
                  Please review your information before submitting
                </p>
              </div>

              <div
                className="p-6 rounded-lg space-y-4"
                style={{
                  backgroundColor: 'var(--brand-surface, #FFFFFF)',
                  border: '1px solid var(--brand-border, #E2E8F0)',
                }}
              >
                <div>
                  <p
                    className="text-sm font-medium mb-1"
                    style={{ color: 'var(--brand-text-muted, #64748B)' }}
                  >
                    Full Name
                  </p>
                  <p style={{ color: 'var(--brand-text, #0F172A)' }}>
                    {formData.name || '(Not provided)'}
                  </p>
                </div>

                <div>
                  <p
                    className="text-sm font-medium mb-1"
                    style={{ color: 'var(--brand-text-muted, #64748B)' }}
                  >
                    Email Address
                  </p>
                  <p style={{ color: 'var(--brand-text, #0F172A)' }}>
                    {formData.email || '(Not provided)'}
                  </p>
                </div>

                {formData.phone && (
                  <div>
                    <p
                      className="text-sm font-medium mb-1"
                      style={{ color: 'var(--brand-text-muted, #64748B)' }}
                    >
                      Phone Number
                    </p>
                    <p style={{ color: 'var(--brand-text, #0F172A)' }}>{formData.phone}</p>
                  </div>
                )}

                <div>
                  <p
                    className="text-sm font-medium mb-1"
                    style={{ color: 'var(--brand-text-muted, #64748B)' }}
                  >
                    Message
                  </p>
                  <p style={{ color: 'var(--brand-text, #0F172A)' }}>
                    {formData.message || '(Not provided)'}
                  </p>
                </div>
              </div>
            </div>
          )}

          {/* Navigation Buttons */}
          <div className="flex items-center gap-3 pt-4">
            {currentStep > 1 && (
              <ThemedButton
                type="button"
                variant="secondary"
                onClick={handlePrevious}
                className="flex-1"
              >
