/**
 * ConditionGroup - A group of conditions with AND/OR toggle
 *
 * Displays a bordered group containing:
 * - Multiple condition rows
 * - AND/OR toggle between conditions
 * - Nested groups (recursive)
 * - Add condition/group buttons
 */

import { Plus, Trash2, FolderPlus } from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";


import type {
  Condition,
  ConditionGroup as ConditionGroupType,
  LogicalOperator,
  VariableInfo,
} from "@shared/types/conditions";
import { createEmptyCondition, createEmptyGroup } from "@shared/types/conditions";

import { ConditionRow } from "./ConditionRow";

interface ConditionGroupProps {
  group: ConditionGroupType;
  variables: VariableInfo[];
  onChange: (updated: ConditionGroupType) => void;
  onDelete?: () => void;
  depth?: number;
  isRoot?: boolean;
}

export function ConditionGroup({
  group,
  variables,
  onChange,
  onDelete,
  depth = 0,
  isRoot = false,
}: ConditionGroupProps) {
  // Toggle the group's logical operator
  const handleToggleOperator = () => {
    onChange({
      ...group,
      operator: group.operator === "AND" ? "OR" : "AND",
    });
  };

  // Update a condition at a specific index
  const handleConditionChange = (index: number, updated: Condition | ConditionGroupType) => {
    const newConditions = [...group.conditions];
    newConditions[index] = updated;
    onChange({
      ...group,
      conditions: newConditions,
    });
  };

  // Delete a condition at a specific index
  const handleConditionDelete = (index: number) => {
    const newConditions = group.conditions.filter((_, i) => i !== index);
    onChange({
      ...group,
      conditions: newConditions.length > 0 ? newConditions : [createEmptyCondition()],
    });
  };

  // Add a new condition
  const handleAddCondition = () => {
    onChange({
      ...group,
      conditions: [...group.conditions, createEmptyCondition()],
    });
  };

  // Add a nested group
  const handleAddGroup = () => {
    const nestedOperator: LogicalOperator = group.operator === "AND" ? "OR" : "AND";
    onChange({
      ...group,
      conditions: [...group.conditions, createEmptyGroup(nestedOperator)],
    });
  };

  // Render a single item (condition or nested group)
  const renderItem = (item: Condition | ConditionGroupType, index: number) => {
    if (item.type === "condition") {
      return (
        <ConditionRow
          key={item.id}
          condition={item}
          variables={variables}
          onChange={(updated: any) => handleConditionChange(index, updated)}
          onDelete={() => handleConditionDelete(index)}
          canDelete={group.conditions.length > 1}
        />
      );
    } else {
      return (
        <ConditionGroup
          key={item.id}
          group={item}
          variables={variables}
          onChange={(updated: any) => handleConditionChange(index, updated)}
          onDelete={() => handleConditionDelete(index)}
          depth={depth + 1}
        />
      );
    }
  };

  // Style based on depth
  const borderColor = depth % 2 === 0 ? "border-border" : "border-primary/30";
  const bgColor = depth % 2 === 0 ? "bg-background" : "bg-muted/20";

  return (
    <div
      className={`
        relative rounded-lg border-2 ${borderColor} ${bgColor}
        ${isRoot ? "p-4" : "p-3 ml-4"}
        ${depth > 0 ? "mt-2" : ""}
      `}
    >
      {/* Group Header */}
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          {/* Operator Toggle */}
          <Button
            variant="outline"
            size="sm"
            className="h-7 px-3 text-xs font-semibold"
            onClick={handleToggleOperator}
          >
            Match{" "}
            <Badge
              variant={group.operator === "AND" ? "default" : "secondary"}
              className="ml-1.5 px-1.5"
            >
              {group.operator === "AND" ? "ALL" : "ANY"}
            </Badge>
          </Button>

          <span className="text-xs text-muted-foreground">
            of these conditions
          </span>
        </div>

        {/* Delete Group (only for nested groups) */}
        {!isRoot && onDelete && (
          <Button
            variant="ghost"
            size="sm"
            className="h-7 px-2 text-destructive hover:text-destructive"
            onClick={onDelete}
          >
            <Trash2 className="h-3.5 w-3.5 mr-1" />
            Remove Group
          </Button>
        )}
      </div>

      {/* Conditions */}
      <div className="space-y-1">
        {group.conditions.map((item, index) => (
          <div key={item.id}>
            {/* Render the condition or nested group */}
            {renderItem(item as any, index)}

            {/* Operator divider between conditions */}
            {index < group.conditions.length - 1 && (
              <div className="flex items-center justify-center py-1">
                <div className="flex-1 border-t border-dashed border-muted-foreground/30" />
                <span
                  className={`
                    px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wider
                    ${group.operator === "AND" ? "text-primary" : "text-secondary-foreground"}
                  `}
                >
                  {group.operator}
                </span>
                <div className="flex-1 border-t border-dashed border-muted-foreground/30" />
              </div>
            )}
          </div>
        ))}
      </div>

      {/* Add Buttons */}
      <div className="flex items-center gap-2 mt-3 pt-3 border-t border-dashed">
        <Button
          variant="outline"
          size="sm"
          className="h-7 text-xs"
          onClick={handleAddCondition}
        >
          <Plus className="h-3 w-3 mr-1" />
          Add Condition
        </Button>

        {depth < 2 && ( // Limit nesting depth to 3 levels
          <Button
            variant="outline"
            size="sm"
            className="h-7 text-xs"
            onClick={handleAddGroup}
          >
            <FolderPlus className="h-3 w-3 mr-1" />
            Add Group
          </Button>
        )}
      </div>
    </div>
  );
}

/**
 * ConditionRow - A single condition row in the logic builder
 *
 * Displays: [Variable Dropdown] [Operator Dropdown] [Value Input(s)] [Delete Button]
 */

import { X, ArrowRightLeft } from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";

import type {
  Condition,
  ComparisonOperator,
  VariableInfo,
  ConditionSupportedStepType as StepType,
} from "@shared/types/conditions";
import { getOperatorsForStepType, getOperatorConfig } from "@shared/types/conditions";

import { ConditionValueInput } from "./ConditionValueInput";

interface ConditionRowProps {
  condition: Condition;
  variables: VariableInfo[];
  onChange: (updated: Condition) => void;
  onDelete: () => void;
  canDelete: boolean;
}

export function ConditionRow({
  condition,
  variables,
  onChange,
  onDelete,
  canDelete,
}: ConditionRowProps) {
  // Find the selected variable to get its type
  const selectedVariable = variables.find(
    (v) => v.id === condition.variable || v.alias === condition.variable
  );
  const stepType: StepType = selectedVariable?.type || "short_text";
  const operators = getOperatorsForStepType(stepType);
  const currentOperator = getOperatorConfig(stepType, condition.operator);

  // Group variables by section for the dropdown
  const variablesBySection = variables.reduce((acc, variable) => {
    const sectionId = variable.sectionId;
    if (!acc[sectionId]) {
      acc[sectionId] = {
        title: variable.sectionTitle,
        variables: [],
      };
    }
    acc[sectionId].variables.push(variable);
    return acc;
  }, {} as Record<string, { title: string; variables: VariableInfo[] }>);

  // Helpers
  const getStringValue = (val: unknown): string => {
    if (val === null || val === undefined) { return ""; }
    return String(val);
  };

  const getVariableLabel = (val: string) => {
    const v = variables.find((v) => v.id === val || v.alias === val);
    return v ? (v.alias || v.title) : val;
  };

  // Handlers
  const handleVariableChange = (value: string) => {
    const newVariable = variables.find((v) => v.id === value || v.alias === value);
    const newStepType: StepType = newVariable?.type || "short_text";
    const newOperators = getOperatorsForStepType(newStepType);

    // Check if current operator is valid for new type, otherwise reset
    const isOperatorValid = newOperators.some((op) => op.value === condition.operator);
    const newOperator = isOperatorValid ? condition.operator : newOperators[0]?.value || "equals";

    onChange({
      ...condition,
      variable: value,
      operator: newOperator,
      // Reset value if operator changes
      value: isOperatorValid ? condition.value : "",
    });
  };

  const handleOperatorChange = (value: string) => {
    const newOperator = value as ComparisonOperator;
    const operatorConfig = getOperatorConfig(stepType, newOperator);

    onChange({
      ...condition,
      operator: newOperator,
      // Set implied value for boolean operators, or maintain/reset value
      value: operatorConfig?.impliedValue ?? (operatorConfig?.needsValue ? condition.value : undefined),
      value2: operatorConfig?.needsTwoValues ? condition.value2 : undefined,
    });
  };

  const handleToggleValueType = () => {
    onChange({
      ...condition,
      valueType: condition.valueType === "constant" ? "variable" : "constant",
      value: "", // Reset value when toggling
    });
  };

  return (
    <div className="flex items-center gap-2 py-2 px-3 bg-muted/30 rounded-md">
      {/* Variable Selector */}
      <Select value={getStringValue(condition.variable)} onValueChange={handleVariableChange}>
        <SelectTrigger className="w-[160px] text-sm bg-background">
          <SelectValue placeholder="Select variable...">
            {getVariableLabel(getStringValue(condition.variable))}
          </SelectValue>
        </SelectTrigger>
        <SelectContent>
          {Object.entries(variablesBySection).map(([sectionId, { title, variables: sectionVars }]) => (
            <SelectGroup key={sectionId}>
              <SelectLabel className="text-xs font-semibold text-muted-foreground">{title}</SelectLabel>
              {sectionVars.map((v) => (
                <SelectItem key={v.id} value={v.alias || v.id}>
                  <div className="flex flex-col text-left">
                    <span>{v.alias || v.title}</span>
                    {v.alias && (
                      <span className="text-[10px] text-muted-foreground">{v.title}</span>
                    )}
                  </div>
                </SelectItem>
              ))}
            </SelectGroup>
          ))}
        </SelectContent>
      </Select>

      {/* Operator Selector */}
      <Select value={condition.operator} onValueChange={handleOperatorChange}>
        <SelectTrigger className="w-[160px] text-sm bg-background">
          <SelectValue>
            {currentOperator?.label || condition.operator}
          </SelectValue>
        </SelectTrigger>
        <SelectContent>
          {operators.map((op) => (
            <SelectItem key={op.value} value={op.value}>
              {op.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>

      {/* Value Input */}
      {currentOperator?.needsValue && currentOperator && (
        <ConditionValueInput
          condition={condition}
          operatorConfig={currentOperator}
          selectedVariable={selectedVariable}
          allVariables={variables}
          onChange={(updates) => onChange({ ...condition, ...updates })}
        />
      )}

      {/* Toggle Value Type (constant/variable) */}
      {currentOperator?.needsValue && (
        <TooltipProvider>
          <Tooltip>
            <TooltipTrigger asChild>
              <Button
                variant="ghost"
                size="icon"
                className="h-8 w-8 shrink-0 hover:bg-background"
                onClick={handleToggleValueType}
              >
                <ArrowRightLeft className={`h-3.5 w-3.5 ${condition.valueType === "variable" ? "text-primary" : "text-muted-foreground"}`} />
              </Button>
            </TooltipTrigger>
            <TooltipContent>
              <p>{condition.valueType === "constant" ? "Compare to variable" : "Compare to constant"}</p>
            </TooltipContent>
          </Tooltip>
        </TooltipProvider>
      )}

      {/* Delete Button */}
      <Button
        variant="ghost"
        size="icon"
        className="h-8 w-8 shrink-0 text-muted-foreground hover:text-red-500 hover:bg-red-50"
        onClick={onDelete}
        disabled={!canDelete}
      >
        <X className="h-4 w-4" />
      </Button>
    </div>
  );
}

import { useMemo } from "react";

import { Input } from "@/components/ui/input";
import {
    Select,
    SelectContent,
    SelectGroup,
    SelectItem,
    SelectLabel,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";

import type { Condition, OperatorConfig, VariableInfo } from "@shared/types/conditions";

interface ConditionValueInputProps {
    condition: Condition;
    operatorConfig: OperatorConfig;
    selectedVariable: VariableInfo | undefined;
    allVariables: VariableInfo[];
    onChange: (updates: Partial<Condition>) => void;
}

export function ConditionValueInput({
    condition,
    operatorConfig,
    selectedVariable,
    allVariables,
    onChange,
}: ConditionValueInputProps) {

    // Helpers to safely get string values from potentially mixed types
    const getStringValue = (val: unknown): string => {
        if (val === null || val === undefined) {return "";}
        return String(val);
    };

    const handleValueChange = (val: string) => {
        onChange({ value: val });
    };

    const handleValue2Change = (val: string) => {
        onChange({ value2: val });
    };

    // Group variables for dropdown if needed
    const variablesBySection = useMemo(() => {
        if (condition.valueType !== "variable") {return {};}

        return allVariables.reduce((acc, variable) => {
            const sectionId = variable.sectionId;
            if (!acc[sectionId]) {
                acc[sectionId] = {
                    title: variable.sectionTitle,
                    variables: [],
                };
            }
            acc[sectionId].variables.push(variable);
            return acc;
        }, {} as Record<string, { title: string; variables: VariableInfo[] }>);
    }, [allVariables, condition.valueType]);

    // 1. Variable Reference Mode
    if (condition.valueType === "variable") {
        return (
            <Select value={getStringValue(condition.value)} onValueChange={handleValueChange}>
                <SelectTrigger className="w-[180px] text-sm bg-background">
                    <SelectValue placeholder="Select variable..." />
                </SelectTrigger>
                <SelectContent>
                    {Object.entries(variablesBySection).map(([sectionId, { title, variables: sectionVars }]) => (
                        <SelectGroup key={sectionId}>
                            <SelectLabel className="text-xs font-semibold text-muted-foreground">{title}</SelectLabel>
                            {sectionVars
                                .filter((v) => v.id !== condition.variable) // Don't allow comparing to self
                                .map((v) => (
                                    <SelectItem key={v.id} value={v.alias || v.id}>
                                        {v.alias || v.title}
                                    </SelectItem>
                                ))}
                        </SelectGroup>
                    ))}
                </SelectContent>
            </Select>
        );
    }

    // 2. Constant Value Mode
    const { valueType, needsTwoValues } = operatorConfig;

    // Choices (Dropdown)
    if (valueType === "choices" && selectedVariable?.choices) {
        return (
            <Select value={getStringValue(condition.value)} onValueChange={handleValueChange}>
                <SelectTrigger className="w-[180px] text-sm bg-background">
                    <SelectValue placeholder="Select option..." />
                </SelectTrigger>
                <SelectContent>
                    {selectedVariable.choices.map((choice) => (
                        <SelectItem key={choice.value} value={choice.value}>
                            {choice.label}
                        </SelectItem>
                    ))}
                </SelectContent>
            </Select>
        );
    }

    // Number Input
    if (valueType === "number") {
        return (
            <div className="flex items-center gap-2">
                <Input
                    type="number"
                    value={getStringValue(condition.value)}
                    onChange={(e) => handleValueChange(e.target.value)}
                    className="w-[100px] text-sm bg-background"
                    placeholder="Value"
                />
                {needsTwoValues && (
                    <>
                        <span className="text-muted-foreground text-sm">and</span>
                        <Input
                            type="number"
                            value={getStringValue(condition.value2)}
                            onChange={(e) => handleValue2Change(e.target.value)}
                            className="w-[100px] text-sm bg-background"
                            placeholder="Value"
                        />
                    </>
                )}
            </div>
        );
    }

    // Date Input
    if (valueType === "date") {
        return (
            <div className="flex items-center gap-2">
                <Input
                    type="date"
                    value={getStringValue(condition.value)}
                    onChange={(e) => handleValueChange(e.target.value)}
                    className="w-[140px] text-sm bg-background"
                />
                {needsTwoValues && (
                    <>
                        <span className="text-muted-foreground text-sm">and</span>
                        <Input
                            type="date"
                            value={getStringValue(condition.value2)}
                            onChange={(e) => handleValue2Change(e.target.value)}
                            className="w-[140px] text-sm bg-background"
                        />
                    </>
                )}
            </div>
        );
    }

    // Default Text Input
    return (
        <Input
            type="text"
            value={getStringValue(condition.value)}
            onChange={(e) => handleValueChange(e.target.value)}
            className="w-[180px] text-sm bg-background"
            placeholder="Value"
        />
    );
}

/**
 * LogicBuilder - Main component for building visibility conditions
 *
 * This is the top-level component that provides:
 * - Toggle to enable/disable conditional visibility
 * - The condition group editor
 * - Human-readable preview of the logic
 * - Save/cancel actions
 */

import { Eye, EyeOff, AlertCircle, Info } from "lucide-react";
import { useState, useEffect, useMemo } from "react";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Separator } from "@/components/ui/separator";
import { Switch } from "@/components/ui/switch";
import { useWorkflowVariables } from "@/lib/vault-hooks";

import { describeConditionExpression } from "@shared/conditionEvaluator";
import {
  createInitialExpression,
  hasValidConditions,
  countConditions,
} from "@shared/types/conditions";
import type {
  ConditionExpression,
  ConditionGroup as ConditionGroupType,
  VariableInfo,
} from "@shared/types/conditions";

import { ConditionGroup } from "./ConditionGroup";

interface LogicBuilderProps {
  /** The workflow ID to fetch variables from */
  workflowId: string;
  /** The element ID (step or section) being edited - used to filter out self-references */
  elementId: string;
  /** Type of element being edited */
  elementType: "step" | "section";
  /** Current condition expression (null means always visible) */
  value: ConditionExpression;
  /** Callback when the expression changes */
  onChange: (expression: ConditionExpression) => void;
  /** Whether changes are being saved */
  isSaving?: boolean;
}

export function LogicBuilder({
  workflowId,
  elementId,
  elementType,
  value,
  onChange,
  isSaving = false,
}: LogicBuilderProps) {
  // Fetch workflow variables
  const { data: rawVariables, isLoading } = useWorkflowVariables(workflowId);

  // Local state for the expression being edited
  const [localExpression, setLocalExpression] = useState<ConditionGroupType | null>(
    value ? { ...value } : null
  );
  const [hasConditions, setHasConditions] = useState<boolean>(value !== null);

  // Update local state when value prop changes
  useEffect(() => {
    setLocalExpression(value ? { ...value } : null);
    setHasConditions(value !== null);
  }, [value]);

  // Convert raw variables to VariableInfo format
  const variables: VariableInfo[] = useMemo(() => {
    if (!rawVariables) {return [];}

    return rawVariables
      .filter((v) => v.key !== elementId) // Filter out self-references
      .map((v) => ({
        id: v.key,
        alias: v.alias ?? null,
        label: v.label,
        title: v.label,
        type: v.type as VariableInfo["type"],
        sectionId: v.sectionId,
        sectionTitle: v.sectionTitle,
        // TODO: Fetch choices for choice-based steps
        choices: undefined,
      }));
  }, [rawVariables, elementId]);

  // Generate human-readable description
  const description = useMemo(() => {
    if (!hasConditions || !localExpression) {
      return "Always visible";
    }

    // Build variable labels map
    const variableLabels: Record<string, string> = {};
    variables.forEach((v) => {
      variableLabels[v.id] = v.alias || v.title;
      if (v.alias) {
        variableLabels[v.alias] = v.alias;
      }
    });

    return describeConditionExpression(localExpression, variableLabels);
  }, [hasConditions, localExpression, variables]);

  // Toggle conditional visibility on/off
  const handleToggleConditions = (enabled: boolean) => {
    setHasConditions(enabled);
    if (enabled && !localExpression) {
      const initial = createInitialExpression();
      setLocalExpression(initial);
    }
    // If disabling, we'll keep the local expression in case user re-enables
  };

  // Handle expression change
  const handleExpressionChange = (updated: ConditionGroupType) => {
    setLocalExpression(updated);
  };

  // Apply changes
  const handleApply = () => {
    if (!hasConditions) {
      onChange(null);
    } else if (localExpression && hasValidConditions(localExpression)) {
      onChange(localExpression);
    } else {
      // No valid conditions - treat as always visible
      onChange(null);
    }
  };

  // Reset to original value
  const handleReset = () => {
    setLocalExpression(value ? { ...value } : null);
    setHasConditions(value !== null);
  };

  // Check if there are unsaved changes
  const hasChanges = useMemo(() => {
    if (hasConditions !== (value !== null)) {return true;}
    if (!hasConditions) {return false;}
    // Deep compare would be better, but for now just check if both exist
    return JSON.stringify(localExpression) !== JSON.stringify(value);
  }, [hasConditions, localExpression, value]);

  // Count conditions for display
  const conditionCount = localExpression ? countConditions(localExpression) : 0;

  if (isLoading) {
    return (
      <div className="p-4 space-y-4">
        <div className="animate-pulse space-y-3">
          <div className="h-4 bg-muted rounded w-1/3" />
          <div className="h-20 bg-muted rounded" />
        </div>
      </div>
    );
  }

  if (variables.length === 0) {
    return (
      <div className="p-4">
        <Alert>
          <Info className="h-4 w-4" />
          <AlertDescription>
            Add some questions to your workflow first to create visibility conditions.
            Conditions can reference values from other questions.
          </AlertDescription>
        </Alert>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header with toggle */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className={`p-2 rounded-full ${hasConditions ? "bg-primary/10" : "bg-muted"}`}>
            {hasConditions ? (
              <EyeOff className="h-4 w-4 text-primary" />
            ) : (
              <Eye className="h-4 w-4 text-muted-foreground" />
            )}
          </div>
          <div>
            <Label className="text-sm font-medium">
              Conditional Visibility
            </Label>
            <p className="text-xs text-muted-foreground">
              {hasConditions
                ? `Show this ${elementType} only when conditions are met`
                : `This ${elementType} is always visible`}
            </p>
          </div>
        </div>
        <Switch
          checked={hasConditions}
          onCheckedChange={handleToggleConditions}
        />
      </div>

      {/* Condition Editor */}
      {hasConditions && localExpression && (
        <>
          <Separator />

          <div className="space-y-4">
            {/* Condition Group */}
            <ConditionGroup
              group={localExpression}
              variables={variables}
              onChange={handleExpressionChange}
              isRoot
            />

            {/* Preview */}
            <div className="rounded-md bg-muted/50 p-3 border">
              <div className="flex items-start gap-2">
                <AlertCircle className="h-4 w-4 text-muted-foreground mt-0.5 shrink-0" />
                <div className="space-y-1">
                  <p className="text-xs font-medium text-muted-foreground">Preview</p>
                  <p className="text-sm">
                    Show this {elementType} if: <span className="font-medium">{description}</span>
                  </p>
                  {conditionCount > 0 && (
                    <p className="text-xs text-muted-foreground">
                      {conditionCount} condition{conditionCount !== 1 ? "s" : ""}
                    </p>
                  )}
                </div>
              </div>
            </div>
          </div>
        </>
      )}

      {/* Actions */}
      {hasChanges && (
        <>
          <Separator />
          <div className="flex items-center justify-end gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={handleReset}
              disabled={isSaving}
            >
              Reset
            </Button>
            <Button
              size="sm"
              onClick={handleApply}
              disabled={isSaving}
            >
              {isSaving ? "Saving..." : "Apply Changes"}
            </Button>
          </div>
        </>
      )}
    </div>
  );
}

