export interface AddressBlockProps {
  step: Step;
  value: any;
  onChange: (value: AddressValue) => void;
  readOnly?: boolean;
}

interface Suggestion {
  description: string;
  place_id: string;
}

export function AddressBlockRenderer({ step, value, onChange, readOnly }: AddressBlockProps) {
  const config = step.config as AddressConfig;

  // Parse current value (nested object)
  const currentValue: AddressValue = value || {};

  const [suggestions, setSuggestions] = useState<Suggestion[]>([]);
  const [loading, setLoading] = useState(false);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const [shouldFetch, setShouldFetch] = useState(true); // Prevent fetching when selecting an item
  const [userLocation, setUserLocation] = useState<{ lat: number; lng: number } | null>(null);

  // Get user location on mount
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setUserLocation({
            lat: position.coords.latitude,
            lng: position.coords.longitude,
          });
        },
        (error) => {
          console.debug("[AddressBlock] Geolocation denied or failed", error);
        }
      );
    }
  }, []);


  // Helper to get auth headers
  const getHeaders = () => {
    const headers: Record<string, string> = {
      "Content-Type": "application/json",
    };

    // 1. Check for token in query params (often used in preview/iframe)
    const urlParams = new URLSearchParams(window.location.search);
    const queryToken = urlParams.get('token');
    if (queryToken) {
      headers["Authorization"] = `Bearer ${queryToken}`;
      return headers;
    }

    // 2. Check for Run ID in URL path and match with store
    // URL patterns: /run/:id, /preview/:id
    const pathParts = window.location.pathname.split('/');
    const storeState = usePreviewStore.getState();
    const knownTokens = storeState.tokens || {};

    // Iterate through path parts to find a UUID-like string that matches a known run
    for (const part of pathParts) {
      // Check store first (most reliable for preview)
      if (knownTokens[part]) {
        headers["Authorization"] = `Bearer ${knownTokens[part]}`;
        return headers;
      }
      // Check localStorage as fallback
      const localToken = localStorage.getItem(`run_token_${part}`);
      if (localToken) {
        headers["Authorization"] = `Bearer ${localToken}`;
        return headers;
      }
    }

    // 3. Fallback: Check if there's any active run token in localStorage if we can't find ID
    // (This is a "Hail Mary" - maybe only one run exists?)
    // Skipping for safety to avoid sending wrong token.

    return headers;
  };

  // Update a single field
  const updateField = (field: keyof AddressValue, newValue: string) => {
    onChange({
      ...currentValue,
      [field]: newValue,
    });
  };

  // Debounce search
  useEffect(() => {
    if (!shouldFetch || !currentValue.street || currentValue.street.length <= 3) {
      setSuggestions([]);
      return;
    }

    const timer = setTimeout(async () => {
      setLoading(true);
      try {
        const headers = getHeaders();
        let url = `/api/places/autocomplete?input=${encodeURIComponent(currentValue.street!)}`;

        if (userLocation) {
          url += `&lat=${userLocation.lat}&lng=${userLocation.lng}&radius=50000`; // 50km radius bias
        }

        const res = await fetch(url, {
          headers
        });

        if (res.status === 401) {
          console.warn("[AddressBlock] Unauthorized. Please Ensure you are logged in or have a valid session.");
          return;
        }

        const data = await res.json();

        if (Array.isArray(data)) {
          setSuggestions(data);
          setShowSuggestions(true);
        }
      } catch (err) {
        console.error("[AddressBlock] Autocomplete fetch error:", err);
      } finally {
        setLoading(false);
      }
    }, 500);

    return () => clearTimeout(timer);
  }, [currentValue.street, shouldFetch]);

  const handleStreetChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setShouldFetch(true);
    updateField("street", e.target.value);
  };

  const handleSelectSuggestion = async (placeId: string) => {
    setLoading(true);
    setShowSuggestions(false);
    setShouldFetch(false); // Don't search again for the filled value
    try {
      const headers = getHeaders();
      const res = await fetch(`/api/places/details?placeId=${placeId}`, {
        headers
      });
      const data = await res.json();

      if (data?.address_components) {
        // Parse address components
        let streetNum = "";
        let route = "";
        let city = "";
        let state = "";
        let zip = "";

        data.address_components.forEach((comp: any) => {
          if (comp.types.includes("street_number")) { streetNum = comp.long_name; }
          if (comp.types.includes("route")) { route = comp.long_name; }
          if (comp.types.includes("locality")) { city = comp.long_name; }
          // If locality is missing, try sublocality or neighborhood? usually locality is city.
          if (!city && comp.types.includes("sublocality")) { city = comp.long_name; }

          if (comp.types.includes("administrative_area_level_1")) { state = comp.short_name; }
          if (comp.types.includes("postal_code")) { zip = comp.long_name; }
        });

        onChange({
          street: `${streetNum} ${route}`.trim(),
          city,
          state,
          zip
        });
      }
    } catch (err) {
      console.error("Failed to get details", err);
    } finally {
      setLoading(false);
    }
  };

  // Close suggestions when clicking outside
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [wrapperRef]);


  return (
    <div className="space-y-3" ref={wrapperRef}>
      {/* Street */}
      <div className="space-y-1 relative">
        <Label htmlFor={`${step.id}-street`} className="text-sm">
          Street Address
        </Label>
        {/* Suggestions Popover */}
        <div className="relative">
          <Popover open={showSuggestions && suggestions.length > 0} onOpenChange={setShowSuggestions}>
            <PopoverTrigger asChild>
              <div className="relative">
                <Input
                  id={`${step.id}-street`}
                  type="text"
                  value={currentValue.street ?? ""}
                  onChange={handleStreetChange}
                  placeholder="123 Main St"
                  disabled={readOnly}
                  className="w-full"
                  autoComplete="chrome-off"
                  data-1p-ignore // Ignore 1Password
                  data-lpignore="true" // Ignore LastPass
                  onFocus={() => {
                    if (suggestions.length > 0) { setShowSuggestions(true); }
                  }}
                />
                {loading && (
                  <div className="absolute right-3 top-2.5">
                    <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
                  </div>
                )}
              </div>
            </PopoverTrigger>
            <PopoverContent className="p-0 w-[var(--radix-popover-trigger-width)]" align="start" onOpenAutoFocus={(e) => e.preventDefault()}>
              <Command shouldFilter={false}>
                <CommandList>
                  <CommandEmpty>No results found.</CommandEmpty>
                  <CommandGroup>
                    {suggestions.map((suggestion) => (
                      <CommandItem
                        key={suggestion.place_id}
                        value={suggestion.description}
                        onSelect={() => { void handleSelectSuggestion(suggestion.place_id); }}
                      >
                        <MapPin className="mr-2 h-4 w-4 text-muted-foreground" />
                        {suggestion.description}
                      </CommandItem>
                    ))}
                  </CommandGroup>
                </CommandList>
              </Command>
            </PopoverContent>
          </Popover>
        </div>
      </div>

      {/* City */}
      <div className="space-y-1">
        <Label htmlFor={`${step.id}-city`} className="text-sm">
          City
        </Label>
        <Input
          id={`${step.id}-city`}
          type="text"
          value={currentValue.city ?? ""}
          onChange={(e) => { void updateField("city", e.target.value); }}
          placeholder="Miami"
          disabled={readOnly}
        />
      </div>

      {/* State & ZIP (side by side) */}
      <div className="grid grid-cols-2 gap-3">
        {/* State */}
        <div className="space-y-1">
          <Label htmlFor={`${step.id}-state`} className="text-sm">
            State
          </Label>
          <Select
            value={currentValue.state ?? ""}
            onValueChange={(newValue) => updateField("state", newValue)}
            disabled={readOnly}
          >
            <SelectTrigger id={`${step.id}-state`}>
              <SelectValue placeholder="Select state" />
            </SelectTrigger>
            <SelectContent>
              {US_STATES.map((state) => (
                <SelectItem key={state.code} value={state.code}>
                  {state.name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {/* ZIP */}
        <div className="space-y-1">
          <Label htmlFor={`${step.id}-zip`} className="text-sm">
            ZIP Code
          </Label>
          <Input
            id={`${step.id}-zip`}
            type="text"
            value={currentValue.zip ?? ""}
            onChange={(e) => { void updateField("zip", e.target.value); }}
            placeholder="33101"
            maxLength={5}
            disabled={readOnly}
          />
        </div>
      </div>
    </div>
  );
}

/**
 * BlockRenderer - Core Block Rendering System
 *
 * Central router that renders the appropriate block component based on step type.
 * Supports all block types defined in the block registry with proper validation,
 * value storage, and alias-based data management.
 *
 * @version 2.0.0 - Runner Renderer Overhaul (Prompt 5)
 * @date December 2025
 */

import React from "react";

import { Label } from "@/components/ui/label";
import type { Step } from "@/types";

// Block Renderers
import { AddressBlockRenderer } from "./AddressBlock";
import { BooleanBlockRenderer } from "./BooleanBlock";
import { ChoiceBlockRenderer } from "./ChoiceBlock";
import { CurrencyBlockRenderer } from "./CurrencyBlock";
import { DateBlockRenderer } from "./DateBlock";
import { DateTimeBlockRenderer } from "./DateTimeBlock";
import { DisplayBlockRenderer } from "./DisplayBlock";
import { EmailBlockRenderer } from "./EmailBlock";
import { FinalBlockRenderer } from "./FinalBlock";
import { MultiFieldBlockRenderer } from "./MultiFieldBlock";
import { NumberBlockRenderer } from "./NumberBlock";
import { PhoneBlockRenderer } from "./PhoneBlock";
import { ScaleBlockRenderer } from "./ScaleBlock";
import { SignatureBlockRenderer } from "./SignatureBlockRenderer";
import { TextBlockRenderer } from "./TextBlock";
import { TimeBlockRenderer } from "./TimeBlock";
import { WebsiteBlockRenderer } from "./WebsiteBlock";

// ============================================================================
// TYPES
// ============================================================================

export interface BlockRendererProps {
  /** Step/block configuration */
  step: Step;

  /** Current value (keyed by step.alias or step.id) */
  value: any;

  /** Callback when value changes */
  onChange: (value: any) => void;

  /** Whether this field is required (computed from step + logic rules) */
  required?: boolean;

  /** Validation error message (if any) */
  error?: string;

  /** Read-only mode (for review/final documents) */
  readOnly?: boolean;

  /** Show validation state */
  showValidation?: boolean;

  /** Full context for resolving variables (e.g. dynamic lists) */
  context?: Record<string, any>;
}

// ============================================================================
// MAIN COMPONENT
// ============================================================================

export function BlockRenderer(props: BlockRendererProps) {
  const { step, value, onChange, required, error, readOnly, showValidation } = props;

  // -------------------------------------------------------------------------
  // Handle JS blocks (no UI, invisible execution)
  // -------------------------------------------------------------------------
  if (step.type === "js_question" || step.isVirtual) {
    // JS blocks and virtual steps do not render any UI
    return null;
  }

  // Generate ARIA IDs
  const descriptionId = step.description ? `${step.id}-description` : undefined;
  const errorId = showValidation && error ? `${step.id}-error` : undefined;

  // Combine IDs for aria-describedby
  const ariaDescribedBy = [descriptionId, errorId].filter(Boolean).join(" ") || undefined;

  // -------------------------------------------------------------------------
  // Render block input based on type
  // -------------------------------------------------------------------------
  const renderBlockInput = () => {
    switch (step.type) {
      // Text blocks
      case "short_text":
      case "long_text":
      case "text":
        // @ts-ignore - Prop injection for accessibility
        return <TextBlockRenderer step={step} value={value} onChange={onChange} readOnly={readOnly} ariaDescribedBy={ariaDescribedBy} />;

      // Boolean blocks
      case "yes_no":
      case "true_false":
      case "boolean":
        return <BooleanBlockRenderer step={step} value={value} onChange={onChange} readOnly={readOnly} />;

      // Validated inputs
      case "phone":
        return <PhoneBlockRenderer step={step} value={value} onChange={onChange} readOnly={readOnly} />;

      case "email":
        return <EmailBlockRenderer step={step} value={value} onChange={onChange} readOnly={readOnly} />;

      case "website":
        return <WebsiteBlockRenderer step={step} value={value} onChange={onChange} readOnly={readOnly} />;

      // Date/Time inputs
      case "date":
        return <DateBlockRenderer step={step} value={value} onChange={onChange} readOnly={readOnly} />;

      case "time":
        return <TimeBlockRenderer step={step} value={value} onChange={onChange} readOnly={readOnly} />;

      case "date_time":
        return <DateTimeBlockRenderer step={step} value={value} onChange={onChange} readOnly={readOnly} />;

      // Numeric inputs
      case "number":
        return <NumberBlockRenderer step={step} value={value} onChange={onChange} readOnly={readOnly} />;

      case "currency":
        return <CurrencyBlockRenderer step={step} value={value} onChange={onChange} readOnly={readOnly} />;

      case "scale":
        return <ScaleBlockRenderer step={step} value={value} onChange={onChange} readOnly={readOnly} />;

      // Choice inputs
      case "radio":
      case "multiple_choice":
      case "choice":
        return <ChoiceBlockRenderer step={step} value={value} onChange={onChange} readOnly={readOnly} context={props.context} />;

      // Complex blocks
      case "address":
        return <AddressBlockRenderer step={step} value={value} onChange={onChange} readOnly={readOnly} />;

      case "multi_field":
        return <MultiFieldBlockRenderer step={step} value={value} onChange={onChange} readOnly={readOnly} />;

      // Display blocks
      case "display":
        return <DisplayBlockRenderer step={step} context={props.context} />;

      // Final block (output/completion)
      case "final_documents":
        return <FinalBlockRenderer step={step} />;

      // Signature block (e-signature integration)
      case "signature_block":
        return <SignatureBlockRenderer step={step} />;

      // Legacy/fallback
      default:
        console.warn(`[BlockRenderer] Unsupported block type: ${step.type}`);
        return (
          <div className="text-sm text-muted-foreground italic">
            Unsupported block type: {step.type}
          </div>
        );
    }
  };

  // -------------------------------------------------------------------------
  // Render block with label and error
  // -------------------------------------------------------------------------
  // Display blocks, final blocks, and signature blocks don't have labels
  if (step.type === "display" || step.type === "final_documents" || step.type === "signature_block") {
    return renderBlockInput();
  }

  return (
    <div className="space-y-2">
      {/* Label */}
      <Label htmlFor={step.id}>
        {step.title}
        {required && <span className="text-destructive ml-1">*</span>}
      </Label>

      {/* Description/Help Text */}
      {step.description && (
        <p id={descriptionId} className="text-sm text-muted-foreground">{step.description}</p>
      )}

      {/* Input */}
      {renderBlockInput()}

      {/* Validation Error */}
      {showValidation && error && (
        <p id={errorId} className="text-sm text-destructive" role="alert">{error}</p>
      )}
    </div>
  );
}

/**
 * BooleanBlockRenderer - Boolean/Toggle Blocks
 *
 * Handles:
 * - yes_no (Yes/No toggle)
 * - true_false (True/False toggle)
 * - boolean (customizable labels)
 *
 * Features:
 * - Two-button boolean selector (recommended)
 * - Custom labels
 * - Store as boolean or string aliases
 *
 * Storage: boolean OR string (based on config)
 */

import React from "react";

import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import type { Step } from "@/types";

import type { BooleanAdvancedConfig, TrueFalseConfig } from "@/../../shared/types/stepConfigs";

export interface BooleanBlockProps {
  step: Step;
  value: any;
  onChange: (value: boolean | string) => void;
  readOnly?: boolean;
}

export function BooleanBlockRenderer({ step, value, onChange, readOnly }: BooleanBlockProps) {
  // Parse config
  let trueLabel = "Yes";
  let falseLabel = "No";
  let storeAsBoolean = true;
  let displayStyle: "toggle" | "radio" | "checkbox" | "buttons" = "buttons";

  if (step.type === "yes_no") {
    trueLabel = (step.config)?.yesLabel || "Yes";
    falseLabel = (step.config)?.noLabel || "No";
  } else if (step.type === "true_false") {
    const config = step.config as TrueFalseConfig;
    trueLabel = config?.trueLabel || "True";
    falseLabel = config?.falseLabel || "False";
  } else if (step.type === "boolean") {
    const config = step.config as BooleanAdvancedConfig;
    trueLabel = config?.trueLabel || "Yes";
    falseLabel = config?.falseLabel || "No";
    storeAsBoolean = config?.storeAsBoolean ?? true;
    displayStyle = config?.displayStyle || "buttons";
  }

  // Determine current value
  const isTrue = storeAsBoolean ? value === true : value === trueLabel;

  // Handle change
  const handleChange = (newValue: boolean) => {
    if (storeAsBoolean) {
      onChange(newValue);
    } else {
      onChange(newValue ? trueLabel : falseLabel);
    }
  };

  // Render as two-button selector (recommended)
  if (displayStyle === "buttons") {
    return (
      <div className="flex gap-2">
        <Button
          type="button"
          variant={isTrue ? "default" : "outline"}
          onClick={() => !readOnly && handleChange(true)}
          disabled={readOnly}
          className="flex-1"
        >
          {trueLabel}
        </Button>
        <Button
          type="button"
          variant={!isTrue && value !== undefined && value !== null ? "default" : "outline"}
          onClick={() => !readOnly && handleChange(false)}
          disabled={readOnly}
          className="flex-1"
        >
          {falseLabel}
        </Button>
      </div>
    );
  }

  // Render as radio group (alternative)
  return (
    <RadioGroup
      value={isTrue ? "true" : "false"}
      onValueChange={(v) => !readOnly && handleChange(v === "true")}
      disabled={readOnly}
    >
      <div className="flex items-center space-x-2">
        <RadioGroupItem value="true" id={`${step.id}-true`} />
        <Label htmlFor={`${step.id}-true`}>{trueLabel}</Label>
      </div>
      <div className="flex items-center space-x-2">
        <RadioGroupItem value="false" id={`${step.id}-false`} />
        <Label htmlFor={`${step.id}-false`}>{falseLabel}</Label>
      </div>
    </RadioGroup>
  );
}

/**
 * ChoiceBlockRenderer - Choice Input (Radio/Dropdown/Multiple)
 *
 * CRITICAL COMPONENT - Handles all choice-based inputs with alias support
 *
 * Handles:
 * - radio (legacy simple list)
 * - multiple_choice (legacy simple list)
 * - choice (advanced with full ChoiceOption objects or dynamic sources)
 *
 * Display modes:
 * - radio: Radio buttons (single choice)
 * - dropdown: Select menu (single choice)
 * - multiple: Checkboxes (multi-select)
 *
 * Option Sources:
 * - Static: Predefined options
 * - List: From a ListVariable (Read Table / List Tools blocks)
 * - Table Column: Direct table column read (convenience path)
 *
 * Value Storage Rules:
 * - Single choice (radio/dropdown): Store option.alias (string)
 * - Multi-choice (checkboxes): Store array of aliases (string[])
 * - Aliases are THE canonical value used in logic, JS, and documents
 *
 * Storage: string OR string[] (based on allowMultiple)
 */

import { ChevronsUpDown, Check } from "lucide-react";
import { useState, useEffect } from "react";

import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { Label } from "@/components/ui/label";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { generateOptionsFromList } from "@/lib/choice-utils";
import { cn } from "@/lib/utils";
import type { Step } from "@/types";

import type { ChoiceAdvancedConfig, ChoiceOption, DynamicOptionsConfig } from "@/../../shared/types/stepConfigs";


export interface ChoiceBlockProps {
  step: Step;
  value: any;
  onChange: (value: string | string[]) => void;
  readOnly?: boolean;
  context?: Record<string, any>;
}

// Helper for Searchable Dropdown
function SearchableDropdown({
  options,
  value,
  onChange,
  disabled,
  placeholder = "Select an option..."
}: {
  options: ChoiceOption[],
  value: string,
  onChange: (val: string) => void,
  disabled?: boolean,
  placeholder?: string
}) {
  const [open, setOpen] = useState(false);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          role="combobox"
          aria-expanded={open}
          className="w-full justify-between font-normal text-left"
          disabled={disabled}
        >
          {value
            ? options.find((option) => (option.alias || option.id) === value)?.label
            : <span className="text-muted-foreground">{placeholder}</span>}
          <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-[var(--radix-popover-trigger-width)] p-0">
        <Command>
          <CommandInput placeholder="Search..." />
          <CommandList>
            <CommandEmpty>No option found.</CommandEmpty>
            <CommandGroup>
              {options.map((option) => (
                <CommandItem
                  key={option.id}
                  value={option.label}
                  onSelect={() => {
                    onChange(option.alias || option.id);
                    setOpen(false);
                  }}
                >
                  <Check
                    className={cn(
                      "mr-2 h-4 w-4",
                      (option.alias || option.id) === value ? "opacity-100" : "opacity-0"
                    )}
                  />
                  {option.label}
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

export function ChoiceBlockRenderer({ step, value, onChange, readOnly, context }: ChoiceBlockProps) {
  // -------------------------------------------------------------------------
  // Parse configuration
  // -------------------------------------------------------------------------
  let displayMode: "radio" | "dropdown" | "multiple" = "radio";
  let allowMultiple = false;
  let isSearchable = false;
  const [options, setOptions] = useState<ChoiceOption[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // -------------------------------------------------------------------------
  // Extract options from step config
  // -------------------------------------------------------------------------
  useEffect(() => {
    async function loadOptions() {
      setLoading(true);
      setError(null);

      try {
        // Legacy radio type
        if (step.type === "radio") {
          displayMode = "radio";
          allowMultiple = false;

          const legacyOptions = ((step.config)?.options || (step.options)?.options) ?? [];

          // Handle both string[] and {id,label}[] formats
          if (Array.isArray(legacyOptions)) {
            const opts = legacyOptions.map((opt: any, idx: number) => {
              if (typeof opt === "string") {
                return { id: opt, label: opt, alias: opt };
              } else {
                return {
                  id: opt.id || `opt${idx}`,
                  label: opt.label || opt,
                  alias: opt.alias || opt.id || opt.label || `opt${idx}`,
                };
              }
            });
            setOptions(opts);
          }
        }

        // Legacy multiple_choice type
        else if (step.type === "multiple_choice") {
          displayMode = "multiple";
          allowMultiple = true;

          const legacyOptions = ((step.config)?.options || (step.options)?.options) ?? [];

          if (Array.isArray(legacyOptions)) {
            const opts = legacyOptions.map((opt: any, idx: number) => {
              if (typeof opt === "string") {
                return { id: opt, label: opt, alias: opt };
              } else {
                return {
                  id: opt.id || `opt${idx}`,
                  label: opt.label || opt,
                  alias: opt.alias || opt.id || opt.label || `opt${idx}`,
                };
              }
            });
            setOptions(opts);
          }
        }

        // Advanced choice type
        else if (step.type === "choice") {
          const config = step.config as ChoiceAdvancedConfig;
          displayMode = config?.display || "radio";
          allowMultiple = config?.allowMultiple ?? false;

          const configOptions = config?.options;

          // Determine if dynamic
          const isDynamic = configOptions && typeof configOptions === 'object' && 'type' in configOptions;

          if (isDynamic) {
            const dynamicConfig = configOptions;

            // Static options
            if (dynamicConfig.type === 'static') {
              const opts = dynamicConfig.options ?? [];
              setOptions(opts.map(opt => ({
                ...opt,
                alias: opt.alias || opt.id,
              })));
            }

            // From List Variable (with full transform support)
            else if (dynamicConfig.type === 'list') {
              const { listVariable } = dynamicConfig;

              if (context && listVariable && context[listVariable]) {
                const newOptions = generateOptionsFromList(context[listVariable], dynamicConfig, context);
                setOptions(newOptions);
              } else {
                // If not found, it might be loading or empty.
                if (options.length > 0) { setOptions([]); }
              }
            }

            // From Table Column (convenience path)
            else if (dynamicConfig.type === 'table_column') {
              const { dataSourceId, tableId, columnId, labelColumnId, limit = 100 } = dynamicConfig;

              // Fetch table rows
              try {
                const response = await fetch(
                  `/api/tables/${tableId}/rows?limit=${limit}`,
                  {
                    credentials: 'include',
                  }
                );

                if (!response.ok) {
                  throw new Error(`Failed to fetch table data: ${response.statusText}`);
                }

                const data = await response.json();
                const rows = data.rows ?? [];

                const labelCol = labelColumnId || columnId;

                const opts = rows.map((row: any, idx: number) => ({
                  id: row.data[columnId] || `opt-${idx}`,
                  label: String(row.data[labelCol] || row.data[columnId] || `Option ${idx}`),
                  alias: String(row.data[columnId] || `opt-${idx}`)
                }));

                setOptions(opts);
              } catch (err: any) {
                console.error('[ChoiceBlock] Error loading table column:', err);
                setError(err.message || 'Failed to load options from table');
                setOptions([]);
              }
            }
          } else {
            // Legacy: static array
            const opts = (configOptions) ?? [];
            setOptions(opts.map(opt => ({
              ...opt,
              alias: opt.alias || opt.id,
            })));
          }
        }
      } catch (err: any) {
        console.error('[ChoiceBlock] Error loading options:', err);
        setError(err.message || 'Failed to load options');
        setOptions([]);
      } finally {
        setLoading(false);
      }
    }

    loadOptions();
  }, [step, context]);

  // Get display mode from config
  if (step.type === "choice") {
    const config = step.config as ChoiceAdvancedConfig;
    displayMode = config?.display || "radio";
    allowMultiple = config?.allowMultiple ?? false;
    isSearchable = config?.searchable ?? false;
  }

  // -------------------------------------------------------------------------
  // Value handling
  // -------------------------------------------------------------------------
  const currentValue = value || (allowMultiple ? [] : "");

  // -------------------------------------------------------------------------
  // Loading & Error States
  // -------------------------------------------------------------------------
  if (loading) {
    return <div className="text-sm text-muted-foreground animate-pulse">Loading options...</div>;
  }

  if (error) {
    return (
      <div className="text-sm text-destructive border border-destructive/20 bg-destructive/5 rounded p-2">
        Error: {error}
      </div>
    );
  }

  if (options.length === 0) {
    return <div className="text-sm text-muted-foreground">No options available</div>;
  }

  // -------------------------------------------------------------------------
  // Render: Radio Buttons
  // -------------------------------------------------------------------------
  if (displayMode === "radio" && !allowMultiple) {
    return (
      <RadioGroup
        value={currentValue}
        onValueChange={(newValue) => !readOnly && onChange(newValue)}
        disabled={readOnly}
      >
        {options.map((option) => (
          <div key={option.id} className="flex items-center space-x-2">
            <RadioGroupItem value={option.alias || option.id} id={`${step.id}-${option.id}`} />
            <Label htmlFor={`${step.id}-${option.id}`} className="font-normal cursor-pointer">
              {option.label}
            </Label>
          </div>
        ))}
      </RadioGroup>
    );
  }

  // -------------------------------------------------------------------------
  // Render: Dropdown (Select)
  // -------------------------------------------------------------------------
  if (displayMode === "dropdown" && !allowMultiple) {
    if (isSearchable) {
      return (
        <SearchableDropdown
          options={options}
          value={currentValue as string}
          onChange={(val) => { if (!readOnly) { onChange(val); } }}
          disabled={readOnly}
        />
      );
    }

    return (
      <Select
        value={currentValue as string}
        onValueChange={(newValue) => !readOnly && onChange(newValue)}
        disabled={readOnly}
      >
        <SelectTrigger id={step.id}>
          <SelectValue placeholder="Select an option..." />
        </SelectTrigger>
        <SelectContent>
          {options.map((option) => (
            <SelectItem key={option.id} value={option.alias || option.id}>
              {option.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    );
  }

  // -------------------------------------------------------------------------
  // Render: Multiple Choice (Checkboxes)
  // -------------------------------------------------------------------------
  if (displayMode === "multiple" || allowMultiple) {
    const selectedAliases = Array.isArray(currentValue) ? currentValue : [];

    const handleToggle = (optionAlias: string, checked: boolean) => {
      if (readOnly) { return; }

      let newValue: string[];
      if (checked) {
        newValue = [...selectedAliases, optionAlias];
      } else {
        newValue = selectedAliases.filter((a: string) => a !== optionAlias);
      }
      onChange(newValue);
    };

    return (
      <div className="space-y-2">
        {options.map((option) => {
          const optionAlias = option.alias || option.id;
          const isChecked = selectedAliases.includes(optionAlias);

          return (
            <div key={option.id} className="flex items-center space-x-2">
              <Checkbox
                id={`${step.id}-${option.id}`}
                checked={isChecked}
                onCheckedChange={(checked) => handleToggle(optionAlias, !!checked)}
                disabled={readOnly}
              />
              <Label htmlFor={`${step.id}-${option.id}`} className="font-normal cursor-pointer">
                {option.label}
              </Label>
            </div>
          );
        })}
      </div>
    );
  }

  // Fallback
  return <div className="text-sm text-muted-foreground">Invalid choice configuration</div>;
}

/**
 * CurrencyBlockRenderer - Currency Input
 *
 * Features:
 * - $ prefix display
 * - Thousand separators (commas)
 * - Decimal support (whole or decimal)
 * - Min/max validation
 * - Max decimal places validation (2 places)
 *
 * Storage: number (pure numeric value without formatting)
 */

import React from "react";

import { Input } from "@/components/ui/input";
import type { Step } from "@/types";

import type { CurrencyConfig } from "@/../../shared/types/stepConfigs";

export interface CurrencyBlockProps {
  step: Step;
  value: any;
  onChange: (value: number | null) => void;
  readOnly?: boolean;
}

export function CurrencyBlockRenderer({ step, value, onChange, readOnly }: CurrencyBlockProps) {
  const config = step.config as CurrencyConfig;
  const currency = config?.currency || "USD";
  const allowDecimal = config?.allowDecimal ?? true;
  const min = config?.min;
  const max = config?.max;

  const [displayValue, setDisplayValue] = React.useState("");
  const [isFocused, setIsFocused] = React.useState(false);

  // Format number with commas and decimals
  const formatCurrency = (num: number | null): string => {
    if (num === null || num === undefined) {return "";}

    if (allowDecimal) {
      return num.toLocaleString("en-US", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      });
    } else {
      return Math.floor(num).toLocaleString("en-US");
    }
  };

  // Sync display value with prop value
  React.useEffect(() => {
    if (!isFocused) {
      if (value !== null && value !== undefined) {
        setDisplayValue(formatCurrency(value));
      } else {
        setDisplayValue("");
      }
    }
  }, [value, isFocused]);

  const handleFocus = () => {
    setIsFocused(true);
    // Show raw value when focused (easier to edit)
    if (value !== null && value !== undefined) {
      setDisplayValue(String(value));
    }
  };

  const handleBlur = () => {
    setIsFocused(false);
    // Re-format on blur
  };

  const handleChange = (newValue: string) => {
    // Remove formatting characters ($, commas)
    const cleanValue = newValue.replace(/[$,]/g, "");
    setDisplayValue(cleanValue);

    if (cleanValue === "") {
      onChange(null);
      return;
    }

    const parsed = allowDecimal ? parseFloat(cleanValue) : parseInt(cleanValue, 10);

    if (isNaN(parsed)) {
      return;
    }

    // Check decimal places
    if (allowDecimal && cleanValue.includes(".")) {
      const decimals = cleanValue.split(".")[1];
      // Hardcoded to 2 for currency, could be configurable in future
      if (decimals && decimals.length > 2) {
        return; // Ignore input if more than 2 decimal places
      }
    }

    // Enforce min/max
    if (min !== undefined && parsed < min) {return;}
    if (max !== undefined && parsed > max) {return;}

    onChange(parsed);
  };

  return (
    <div className="relative">
      <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">
        $
      </span>
      <Input
        id={step.id}
        type="text"
        value={displayValue}
        onChange={(e) => handleChange(e.target.value)}
        onFocus={handleFocus}
        onBlur={handleBlur}
        placeholder="0.00"
        disabled={readOnly}
        className="pl-7"
      />
    </div>
  );
}

/**
 * DateBlockRenderer - Date Picker
 *
 * Features:
 * - Date selection
 * - Min/max date enforcement
 * - Default to today option
 *
 * Storage: YYYY-MM-DD (ISO 8601 date string)
 */

