// HELPER FUNCTIONS
// ============================================================================
/**
 * Evaluate document conditions
 * Simplified implementation - will be enhanced with full logic engine later
 */
function evaluateDocumentConditions(
  conditions: LogicExpression,
  stepValues: Record<string, any>
): boolean {
  if (!conditions?.conditions || conditions.conditions.length === 0) {
    return true;
  }
  const operator = conditions.operator || 'AND';
  const results = conditions.conditions.map(cond => {
    const value = stepValues[cond.key];
    switch (cond.op) {
      case 'equals':
        return value === cond.value;
      case 'not_equals':
        return value !== cond.value;
      case 'contains':
        if (typeof value === 'string') {
          return value.includes(String(cond.value));
        }
        if (Array.isArray(value)) {
          return value.includes(cond.value);
        }
        return false;
      case 'greater_than':
        return Number(value) > Number(cond.value);
      case 'less_than':
        return Number(value) < Number(cond.value);
      case 'is_empty':
        return !value || value === '' || (Array.isArray(value) && value.length === 0);
      case 'is_not_empty':
        return !!value && value !== '' && (!Array.isArray(value) || value.length > 0);
      default:
        return true;
    }
  });
  if (operator === 'AND') {
    return results.every(r => r);
  } else {
    return results.some(r => r);
  }
}

/**
 * MultiFieldBlockRenderer - Multi-Field Input
 *
 * Handles grouped fields:
 * - first_last: First + Last Name
 * - contact: Email + Phone
 * - date_range: Start Date + End Date
 * - custom: User-defined fields
 *
 * Storage Format (nested JSON under step.alias):
 * {
 *   first: "Alice",
 *   last: "Smith"
 * }
 *
 * OR
 *
 * {
 *   email: "alice@example.com",
 *   phone: "5551234567"
 * }
 */

import React from "react";

import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import type { Step } from "@/types";

import type { MultiFieldConfig, MultiFieldValue } from "@/../../shared/types/stepConfigs";

export interface MultiFieldBlockProps {
  step: Step;
  value: any;
  onChange: (value: MultiFieldValue) => void;
  readOnly?: boolean;
}

export function MultiFieldBlockRenderer({ step, value, onChange, readOnly }: MultiFieldBlockProps) {
  const config = step.config as MultiFieldConfig;
  const layout = config?.layout || "first_last";
  const fields = config?.fields ?? [];

  // Parse current value (nested object)
  const currentValue: MultiFieldValue = value || {};

  // Update a single field
  const updateField = (fieldKey: string, newValue: string | number) => {
    onChange({
      ...currentValue,
      [fieldKey]: newValue,
    });
  };

  // Render field based on type
  const renderField = (field: any) => {
    const fieldValue = currentValue[field.key] ?? "";

    let inputType = "text";
    if (field.type === "email") {inputType = "email";}
    if (field.type === "phone") {inputType = "tel";}
    if (field.type === "date") {inputType = "date";}
    if (field.type === "number") {inputType = "number";}

    return (
      <div key={field.key} className="space-y-1">
        <Label htmlFor={`${step.id}-${field.key}`} className="text-sm">
          {field.label}
          {field.required && <span className="text-destructive ml-1">*</span>}
        </Label>
        <Input
          id={`${step.id}-${field.key}`}
          type={inputType}
          value={String(fieldValue)}
          onChange={(e) => {
            const newValue = field.type === "number" ? parseFloat(e.target.value) : e.target.value;
            updateField(field.key, newValue);
          }}
          placeholder={field.placeholder || field.label}
          disabled={readOnly}
        />
      </div>
    );
  };

  // Layout-specific rendering
  if (layout === "first_last" || layout === "contact") {
    // Side-by-side layout
    return (
      <div className="grid grid-cols-2 gap-3">
        {fields.map((field) => renderField(field))}
      </div>
    );
  }

  if (layout === "date_range") {
    // Date range layout
    return (
      <div className="space-y-3">
        {fields.map((field) => renderField(field))}
        {/* Validation: start <= end */}
        {currentValue.start && currentValue.end && currentValue.start > currentValue.end && (
          <p className="text-sm text-destructive">End date must be after start date</p>
        )}
      </div>
    );
  }

  // Custom layout (vertical)
  return (
    <div className="space-y-3">
      {fields.map((field) => renderField(field))}
    </div>
  );
}

/**
 * NumberBlockRenderer - Numeric Input
 *
 * Features:
 * - Integer and decimal support
 * - Min/max validation
 * - Step increment
 * - Precision control
 *
 * Storage: number (pure numeric value)
 */

import React from "react";

import { Input } from "@/components/ui/input";
import type { Step } from "@/types";

import type { NumberConfig, NumberAdvancedConfig } from "@/../../shared/types/stepConfigs";

export interface NumberBlockProps {
  step: Step;
  value: any;
  onChange: (value: number | null) => void;
  readOnly?: boolean;
}

export function NumberBlockRenderer({ step, value, onChange, readOnly }: NumberBlockProps) {
  const config = (step.config as NumberConfig) || (step.config as NumberAdvancedConfig);

  const min = config?.min;
  const max = config?.max;
  const step_value = config?.step || 1;
  const allowDecimal = config?.allowDecimal ?? true;
  const placeholder = (config as any)?.placeholder || "0";

  const [displayValue, setDisplayValue] = React.useState("");

  // Sync display value with prop value
  React.useEffect(() => {
    if (value !== null && value !== undefined) {
      setDisplayValue(String(value));
    } else {
      setDisplayValue("");
    }
  }, [value]);

  const handleChange = (newValue: string) => {
    setDisplayValue(newValue);

    // Empty string = null
    if (newValue === "") {
      onChange(null);
      return;
    }

    // Parse number
    const parsed = allowDecimal ? parseFloat(newValue) : parseInt(newValue, 10);

    if (isNaN(parsed)) {
      return;
    }

    // Enforce min/max
    if (min !== undefined && parsed < min) {return;}
    if (max !== undefined && parsed > max) {return;}

    onChange(parsed);
  };

  return (
    <Input
      id={step.id}
      type="number"
      value={displayValue}
      onChange={(e) => handleChange(e.target.value)}
      min={min}
      max={max}
      step={step_value}
      placeholder={placeholder}
      disabled={readOnly}
    />
  );
}

/**
 * PhoneBlockRenderer - Phone Number Input
 *
 * Features:
 * - US phone formatting (XXX) XXX-XXXX
 * - International support (future)
 * - Input masking
 * - Validation
 *
 * Storage: Normalized string (digits only or E.164 format)
 */

import React from "react";

import { Input } from "@/components/ui/input";
import type { Step } from "@/types";

import type { PhoneConfig } from "@/../../shared/types/stepConfigs";

export interface PhoneBlockProps {
  step: Step;
  value: any;
  onChange: (value: string) => void;
  readOnly?: boolean;
}

export function PhoneBlockRenderer({ step, value, onChange, readOnly }: PhoneBlockProps) {
  const config = step.config as PhoneConfig;
  const format = config?.format || "US";

  // Format phone number for display
  const formatPhoneDisplay = (phone: string): string => {
    if (!phone) {return "";}

    // Remove all non-digits
    const digits = phone.replace(/\D/g, "");

    if (format === "US") {
      // US format: (XXX) XXX-XXXX
      if (digits.length <= 3) {return digits;}
      if (digits.length <= 6) {return `(${digits.slice(0, 3)}) ${digits.slice(3)}`;}
      return `(${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6, 10)}`;
    }

    // International: just return digits
    return digits;
  };

  // Handle change with formatting
  const handleChange = (newValue: string) => {
    // Extract digits only
    const digits = newValue.replace(/\D/g, "");

    // Limit to 10 digits for US
    if (format === "US" && digits.length > 10) {return;}

    // Store normalized value (digits only)
    onChange(digits);
  };

  const displayValue = formatPhoneDisplay(value ?? "");

  return (
    <Input
      id={step.id}
      type="tel"
      value={displayValue}
      onChange={(e) => handleChange(e.target.value)}
      placeholder={format === "US" ? "(555) 123-4567" : "Phone number"}
      disabled={readOnly}
    />
  );
}

/**
 * ScaleBlockRenderer - Rating Scale Input
 *
 * Features:
 * - Slider mode (range input)
 * - Stars mode (clickable stars)
 * - Min/max labels
 * - Current value display
 *
 * Storage: number (whole number)
 */

import { Star } from "lucide-react";
import React from "react";

import { Slider } from "@/components/ui/slider";
import type { Step } from "@/types";

import type { ScaleConfig } from "@/../../shared/types/stepConfigs";

export interface ScaleBlockProps {
  step: Step;
  value: any;
  onChange: (value: number) => void;
  readOnly?: boolean;
}

export function ScaleBlockRenderer({ step, value, onChange, readOnly }: ScaleBlockProps) {
  const config = step.config as ScaleConfig;
  const min = config?.min ?? 1;
  const max = config?.max ?? 10;
  const step_value = config?.step ?? 1;
  const display = config?.display || "slider";
  const showValue = config?.showValue ?? true;
  const minLabel = config?.minLabel;
  const maxLabel = config?.maxLabel;

  const currentValue = value !== null && value !== undefined ? value : min;

  // Slider mode
  if (display === "slider") {
    return (
      <div className="space-y-4">
        <Slider
          id={step.id}
          value={[currentValue]}
          onValueChange={(vals) => !readOnly && onChange(vals[0])}
          min={min}
          max={max}
          step={step_value}
          disabled={readOnly}
          className="w-full"
        />

        <div className="flex justify-between items-center text-sm">
          {minLabel && <span className="text-muted-foreground">{minLabel}</span>}
          {showValue && (
            <span className="font-semibold">
              {currentValue} / {max}
            </span>
          )}
          {maxLabel && <span className="text-muted-foreground">{maxLabel}</span>}
        </div>
      </div>
    );
  }

  // Stars mode
  if (display === "stars") {
    const numStars = max;

    return (
      <div className="flex items-center gap-1">
        {Array.from({ length: numStars }, (_, i) => i + 1).map((starValue) => (
          <button
            key={starValue}
            type="button"
            onClick={() => !readOnly && onChange(starValue)}
            disabled={readOnly}
            className="transition-colors hover:scale-110 disabled:cursor-not-allowed"
          >
            <Star
              className={`w-8 h-8 ${
                starValue <= currentValue
                  ? "fill-yellow-400 text-yellow-400"
                  : "text-gray-300"
              }`}
            />
          </button>
        ))}
        {showValue && (
          <span className="ml-2 text-sm font-semibold">
            {currentValue} / {numStars}
          </span>
        )}
      </div>
    );
  }

  return null;
}

/**
 * Signature Block Renderer
 * Displays signature collection interface in workflow runner
 *
 * This component:
 * - Renders markdown header
 * - Shows signer information
 * - Lists documents requiring signature
 * - Handles signature initiation
 * - Supports preview mode simulation
 * - Shows signature status
 *
 * @version 1.0.0 - Prompt 11 (E-Signature Integration)
 * @date December 2025
 */

import { PenTool, FileText, CheckCircle2, XCircle, Clock, AlertCircle } from "lucide-react";
import { useState, useMemo } from "react";
import ReactMarkdown from "react-markdown";

import { Button } from "@/components/ui/button";
import type { Step } from "@/types";

import type { SignatureBlockConfig } from "@/../../shared/types/stepConfigs";

// ============================================================================
// TYPES
// ============================================================================

export interface SignatureBlockRendererProps {
  /** Step/block configuration */
  step: Step;

  /** All step values (for variable substitution and conditions) */
  stepValues?: Record<string, any>;

  /** Whether we're in preview mode */
  preview?: boolean;

  /** Callback when signature is initiated */
  onSign?: () => void;

  /** Callback when signature is declined */
  onDecline?: () => void;

  /** Current signature status */
  status?: 'pending' | 'signing' | 'signed' | 'declined' | 'expired' | 'error';

  /** Error message if status is 'error' */
  errorMessage?: string;
}

// ============================================================================
// MAIN COMPONENT
// ============================================================================

export function SignatureBlockRenderer({
  step,
  stepValues = {},
  preview = false,
  onSign,
  onDecline,
  status = 'pending',
  errorMessage,
}: SignatureBlockRendererProps) {
  const config = step.config as SignatureBlockConfig;
  const [isSimulating, setIsSimulating] = useState(false);

  // Replace variables in text fields (basic implementation)
  const replaceVariables = (text: string): string => {
    if (!text) {return text;}

    let result = text;
    Object.entries(stepValues).forEach(([key, value]) => {
      const regex = new RegExp(`{{${key}}}`, 'g');
      result = result.replace(regex, String(value ?? ''));
    });

    return result;
  };

  // Prepare display values
  const displayConfig = useMemo(() => ({
    signerRole: config?.signerRole || 'Signer',
    signerName: replaceVariables(config?.signerName ?? ''),
    signerEmail: replaceVariables(config?.signerEmail ?? ''),
    message: replaceVariables(config?.message ?? ''),
    markdownHeader: replaceVariables(config?.markdownHeader ?? ''),
    documents: config?.documents ?? [],
    provider: config?.provider || 'docusign',
    allowDecline: config?.allowDecline ?? false,
  }), [config, stepValues]);

  // Handle signature initiation in preview mode
  const handlePreviewSign = async () => {
    if (!preview) {return;}

    setIsSimulating(true);

    // Simulate 2-second signing process
    await new Promise(resolve => setTimeout(resolve, 2000));

    setIsSimulating(false);
    onSign?.();
  };

  // Handle decline in preview mode
  const handlePreviewDecline = async () => {
    if (!preview) {return;}

    setIsSimulating(true);
    await new Promise(resolve => setTimeout(resolve, 500));
    setIsSimulating(false);
    onDecline?.();
  };

  if (!config) {
    return (
      <div className="text-sm text-muted-foreground italic">
        Signature block configuration missing
      </div>
    );
  }

  // Status indicator component
  const StatusIndicator = () => {
    switch (status) {
      case 'signed':
        return (
          <div className="flex items-center gap-2 p-4 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 rounded-lg">
            <CheckCircle2 className="h-5 w-5 text-green-600 dark:text-green-400" />
            <div>
              <p className="font-medium text-green-900 dark:text-green-100">Signature Completed</p>
              <p className="text-sm text-green-700 dark:text-green-300">All documents have been signed</p>
            </div>
          </div>
        );

      case 'declined':
        return (
          <div className="flex items-center gap-2 p-4 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg">
            <XCircle className="h-5 w-5 text-red-600 dark:text-red-400" />
            <div>
              <p className="font-medium text-red-900 dark:text-red-100">Signature Declined</p>
              <p className="text-sm text-red-700 dark:text-red-300">The signature request was declined</p>
            </div>
          </div>
        );

      case 'expired':
        return (
          <div className="flex items-center gap-2 p-4 bg-orange-50 dark:bg-orange-900/20 border border-orange-200 dark:border-orange-800 rounded-lg">
            <Clock className="h-5 w-5 text-orange-600 dark:text-orange-400" />
            <div>
              <p className="font-medium text-orange-900 dark:text-orange-100">Signature Expired</p>
              <p className="text-sm text-orange-700 dark:text-orange-300">The signature request has expired</p>
            </div>
          </div>
        );

      case 'error':
        return (
          <div className="flex items-center gap-2 p-4 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg">
            <AlertCircle className="h-5 w-5 text-red-600 dark:text-red-400" />
            <div>
              <p className="font-medium text-red-900 dark:text-red-100">Signature Error</p>
              <p className="text-sm text-red-700 dark:text-red-300">
                {errorMessage || 'An error occurred while processing the signature request'}
              </p>
            </div>
          </div>
        );

      case 'signing':
        return (
          <div className="flex items-center gap-2 p-4 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg">
            <Clock className="h-5 w-5 text-blue-600 dark:text-blue-400 animate-pulse" />
            <div>
              <p className="font-medium text-blue-900 dark:text-blue-100">Signature In Progress</p>
              <p className="text-sm text-blue-700 dark:text-blue-300">Redirecting to signature provider...</p>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="space-y-6">
      {/* Preview Mode Badge */}
      {preview && (
        <div className="flex items-center gap-2 p-3 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg text-sm">
          <AlertCircle className="h-4 w-4 text-blue-600 dark:text-blue-400" />
          <span className="text-blue-900 dark:text-blue-100">
            <strong>Preview Mode:</strong> No actual signature request will be sent. This is a simulation.
          </span>
        </div>
      )}

      {/* Status Indicator */}
      <StatusIndicator />

      {/* Markdown Header */}
      {displayConfig.markdownHeader && status === 'pending' && (
        <div className="prose prose-sm max-w-none dark:prose-invert">
          <ReactMarkdown>{displayConfig.markdownHeader}</ReactMarkdown>
        </div>
      )}

      {/* Signer Information */}
      {status === 'pending' && (
        <div className="p-4 bg-muted/50 rounded-lg border space-y-3">
          <div className="flex items-center gap-2 text-sm font-medium">
            <PenTool className="h-4 w-4" />
            <span>Signature Required</span>
          </div>

          <div className="space-y-2 text-sm">
            <div>
              <span className="text-muted-foreground">Role:</span>
              <span className="ml-2 font-medium">{displayConfig.signerRole}</span>
            </div>

            {displayConfig.signerName && (
              <div>
                <span className="text-muted-foreground">Signer:</span>
                <span className="ml-2 font-medium">{displayConfig.signerName}</span>
              </div>
            )}

            {displayConfig.signerEmail && (
              <div>
                <span className="text-muted-foreground">Email:</span>
                <span className="ml-2 font-medium">{displayConfig.signerEmail}</span>
              </div>
            )}

            <div>
              <span className="text-muted-foreground">Provider:</span>
              <span className="ml-2 font-medium capitalize">{displayConfig.provider}</span>
            </div>
          </div>

          {/* Custom Message */}
          {displayConfig.message && (
            <div className="pt-2 border-t text-sm text-muted-foreground">
              {displayConfig.message}
            </div>
          )}
        </div>
      )}

      {/* Documents List */}
      {status === 'pending' && displayConfig.documents.length > 0 && (
        <div className="space-y-3">
          <h3 className="text-sm font-semibold">Documents to Sign</h3>

          <div className="space-y-2">
            {displayConfig.documents.map((doc, index) => (
              <div
                key={doc.id}
                className="flex items-center gap-3 p-3 border rounded-lg bg-background"
              >
                <FileText className="h-5 w-5 text-muted-foreground flex-shrink-0" />
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium truncate">
                    Document {index + 1}
                  </p>
                  <p className="text-xs text-muted-foreground truncate">
                    {doc.documentId}
                  </p>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* No Documents Warning */}
      {status === 'pending' && displayConfig.documents.length === 0 && (
        <div className="flex items-center gap-2 p-4 bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800 rounded-lg text-sm">
          <AlertCircle className="h-4 w-4 text-yellow-600 dark:text-yellow-400" />
          <span className="text-yellow-900 dark:text-yellow-100">
            No documents configured for signature
          </span>
        </div>
      )}

      {/* Action Buttons */}
      {status === 'pending' && displayConfig.documents.length > 0 && (
        <div className="flex gap-3">
          <Button
            onClick={preview ? handlePreviewSign : onSign}
            disabled={isSimulating}
            className="flex-1"
          >
            <PenTool className="h-4 w-4 mr-2" />
            {isSimulating ? 'Processing...' : preview ? 'Simulate Signature' : 'Continue to Sign'}
          </Button>

          {displayConfig.allowDecline && (
            <Button
              variant="outline"
              onClick={preview ? handlePreviewDecline : onDecline}
              disabled={isSimulating}
            >
              Decline
            </Button>
          )}
        </div>
      )}

      {/* Error Recovery Button */}
      {status === 'error' && (
        <Button onClick={onSign} className="w-full">
          Try Again
        </Button>
      )}
    </div>
  );
}

/**
 * TextBlockRenderer - Text Input Blocks
 *
 * Handles:
 * - short_text (single-line input)
 * - long_text (multi-line textarea)
 * - text (unified with variant config)
 *
 * Features:
 * - maxLength enforcement
 * - regex pattern validation
 * - placeholder support
 * - Auto-save on change
 *
 * Storage: String value
 */

import React from "react";

import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import type { Step } from "@/types";

import type { TextAdvancedConfig } from "@/../../shared/types/stepConfigs";

export interface TextBlockProps {
  step: Step;
  value: string | undefined | null;
  onChange: (value: string) => void;
  readOnly?: boolean;
  ariaDescribedBy?: string;
}

export function TextBlockRenderer({ step, value, onChange, readOnly, ariaDescribedBy }: TextBlockProps) {
  const currentValue = value ?? "";

  // Determine if this is short or long text
  let variant: "short" | "long" = "short";
  let maxLength: number | undefined;
  let placeholder: string | undefined;

  if (step.type === "short_text") {
    variant = "short";
    maxLength = (step.config)?.maxLength;
    placeholder = (step.config)?.placeholder || "Your answer...";
  } else if (step.type === "long_text") {
    variant = "long";
    maxLength = (step.config)?.maxLength;
    placeholder = (step.config)?.placeholder || "Your answer...";
  } else if (step.type === "text") {
    const config = step.config as TextAdvancedConfig;
    variant = config?.variant || "short";
    maxLength = config?.validation?.maxLength;
    placeholder = config?.placeholder || "Your answer...";
  }

  // Handle change
  const handleChange = (newValue: string) => {
    // Enforce maxLength
    if (maxLength && newValue.length > maxLength) {
      return;
    }
    onChange(newValue);
  };

  if (variant === "long") {
    return (
      <div className="space-y-1">
        <Textarea
          id={step.id}
          value={currentValue}
          onChange={(e) => handleChange(e.target.value)}
          placeholder={placeholder}
          rows={4}
          disabled={readOnly}
          className="resize-y"
          aria-describedby={ariaDescribedBy}
        />
        {maxLength && (
          <p className="text-xs text-muted-foreground text-right">
            {currentValue.length} / {maxLength}
          </p>
        )}
      </div>
    );
  }

  return (
    <div className="space-y-1">
      <Input
        id={step.id}
        type="text"
        value={currentValue}
        onChange={(e) => handleChange(e.target.value)}
        placeholder={placeholder}
        disabled={readOnly}
        maxLength={maxLength}
        aria-describedby={ariaDescribedBy}
      />
      {maxLength && (
        <p className="text-xs text-muted-foreground text-right">
          {currentValue.length} / {maxLength}
        </p>
      )}
    </div>
  );
}

/**
 * TimeBlockRenderer - Time Picker
 *
 * Features:
 * - Time selection
 * - 12h/24h format support
 * - Step increment (e.g., 15 minutes)
 *
 * Storage: HH:mm:ss (24-hour format ISO time string)
 */

import React from "react";

import { Input } from "@/components/ui/input";
import type { Step } from "@/types";

import type { TimeConfig } from "@/../../shared/types/stepConfigs";

export interface TimeBlockProps {
  step: Step;
  value: any;
  onChange: (value: string) => void;
  readOnly?: boolean;
}

export function TimeBlockRenderer({ step, value, onChange, readOnly }: TimeBlockProps) {
  const config = step.config as TimeConfig;
  const step_minutes = config?.step || 15;

  // Convert step to seconds for HTML input
  const stepSeconds = step_minutes * 60;

  return (
    <Input
      id={step.id}
      type="time"
      value={value ?? ""}
      onChange={(e) => onChange(e.target.value)}
      step={stepSeconds}
      disabled={readOnly}
    />
  );
}

/**
 * WebsiteBlockRenderer - Website/URL Input
 *
 * Features:
 * - URL validation
 * - Protocol enforcement (http/https)
 * - Auto-prepend https:// if missing
 *
 * Storage: String (URL)
 */

import React from "react";

import { Input } from "@/components/ui/input";
import type { Step } from "@/types";

import type { WebsiteConfig } from "@/../../shared/types/stepConfigs";

export interface WebsiteBlockProps {
  step: Step;
  value: any;
  onChange: (value: string) => void;
  readOnly?: boolean;
}

export function WebsiteBlockRenderer({ step, value, onChange, readOnly }: WebsiteBlockProps) {
  const config = step.config as WebsiteConfig;
  const placeholder = config?.placeholder || "https://example.com";

  const handleBlur = () => {
    // Auto-prepend https:// if missing
    if (value && !value.match(/^https?:\/\//i)) {
      onChange(`https://${value}`);
    }
  };

  return (
    <Input
      id={step.id}
      type="url"
      value={value ?? ""}
      onChange={(e) => onChange(e.target.value)}
      onBlur={handleBlur}
      placeholder={placeholder}
      disabled={readOnly}
    />
  );
}

/**
 * Block Validation Utilities
 *
 * Validates block values before section submission.
 * Handles all block types with proper nested data validation.
 */

import type { Step } from "@/types";

import type {
  AddressValue,
  MultiFieldValue,
  MultiFieldConfig,
} from "@/../../shared/types/stepConfigs";

/**
 * Validate a single step/block value
 * Returns error message if invalid, null if valid
 */
export function validateBlockValue(step: Step, value: any, required: boolean): string | null {
  // Required check
  if (required) {
    if (value === null || value === undefined || value === "") {
      return `${step.title} is required`;
    }

    // Check empty arrays (multiple choice)
    if (Array.isArray(value) && value.length === 0) {
      return `${step.title} requires at least one selection`;
    }

    // Check nested objects (address, multi-field)
    if (typeof value === "object" && !Array.isArray(value)) {
      // Address validation
      if (step.type === "address") {
        const addr = value as AddressValue;
        if (!addr.street || !addr.city || !addr.state || !addr.zip) {
          return `${step.title} requires all address fields`;
        }
      }

      // Multi-field validation
      if (step.type === "multi_field") {
        const config = step.config as MultiFieldConfig;
        const multiValue = value as MultiFieldValue;

        for (const field of config?.fields ?? []) {
          if (field.required && !multiValue[field.key]) {
            return `${field.label} is required`;
          }
        }
      }
    }
  }

  // Type-specific validation
  switch (step.type) {
    case "short_text":
    case "long_text":
    case "text":
      if (value && typeof value === "string") {
        const config = step.config; // TextConfig or TextAdvancedConfig
        const validation = config?.validation;

        // Max Length
        if (validation?.maxLength !== undefined && value.length > validation.maxLength) {
          return `Must be at most ${validation.maxLength} characters`;
        }

        // Min Length
        if (validation?.minLength !== undefined && value.length < validation.minLength) {
          return `Must be at least ${validation.minLength} characters`;
        }

        // Regex Pattern
        if (validation?.pattern) {
          try {
            const regex = new RegExp(validation.pattern);
            if (!regex.test(value)) {
              return validation.patternMessage || "Invalid format";
            }
          } catch (e) {
            // Ignore invalid regex in runner to prevent crash, but maybe log it
            console.warn("Invalid regex pattern in step config:", validation.pattern);
          }
        }
      }
      break;

    case "email":
      if (value && typeof value === "string") {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(value)) {
          return "Invalid email address";
        }
      }
      break;

    case "phone":
      if (value && typeof value === "string") {
        const phoneDigits = value.replace(/\D/g, "");
        if (phoneDigits.length !== 10) {
          return "Phone number must be 10 digits";
        }
      }
      break;

    case "website":
      if (value && typeof value === "string") {
        try {
          new URL(value);
        } catch {
          return "Invalid URL";
        }
      }
      break;

    case "number":
    case "currency":
      if (value !== null && value !== undefined) {
        const config = step.config;
        const num = typeof value === "number" ? value : parseFloat(value);

        if (isNaN(num)) {
          return "Invalid number";
        }

        if (config?.min !== undefined && num < config.min) {
          return `Value must be at least ${config.min}`;
        }

        if (config?.max !== undefined && num > config.max) {
          return `Value must be at most ${config.max}`;
        }
      }
      break;

    case "multi_field":
      if (value && typeof value === "object") {
        const config = step.config as MultiFieldConfig;
        const multiValue = value as MultiFieldValue;

        // Date range validation
        if (config?.layout === "date_range") {
          if (multiValue.start && multiValue.end && multiValue.start > multiValue.end) {
            return "End date must be after start date";
          }
        }
      }
      break;
  }

  return null;
}

/**
 * Validate all steps in a section
 * Returns map of stepId -> error message
 */
export function validateSectionSteps(
  steps: Step[],
  values: Record<string, any>,
  requiredMap: Record<string, boolean>
): Record<string, string> {
  const errors: Record<string, string> = {};

  for (const step of steps) {
    // Skip virtual steps and display blocks
    if (step.isVirtual || step.type === "display" || step.type === "js_question") {
      continue;
    }

    const value = values[step.id];
    const required = requiredMap[step.id] ?? step.required;

    const error = validateBlockValue(step, value, required);
    if (error) {
      errors[step.id] = error;
    }
  }

  return errors;
}

/**
 * Final Documents Section - Runner View
 * Displays generated documents for download
 */
import { useQuery, useMutation } from "@tanstack/react-query";
import axios from "axios";
import DOMPurify from "isomorphic-dompurify";
import { FileText, Download, Loader2, CheckCircle } from "lucide-react";
import { useEffect } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
interface FinalDocumentsSectionProps {
  runId: string;
  runToken?: string; // Optional run token for preview mode
  sectionConfig: {
    screenTitle?: string;
    title?: string;
    markdownMessage?: string;
    message?: string;
    showDocuments?: boolean;
    redirectUrl?: string;
    redirectDelaySeconds?: number;
    customLinks?: Array<{ label: string; url: string; style: 'button' | 'link' }>;
    brandingColor?: string;
    templates?: string[];
  };
}
interface GeneratedDocument {
  id: string;
  fileName: string;
  fileUrl: string;
  mimeType?: string;
  fileSize?: number;
  createdAt: string;
}
export function FinalDocumentsSection({ runId, runToken, sectionConfig }: FinalDocumentsSectionProps) {
  const title = sectionConfig.title || sectionConfig.screenTitle || "Your Completed Documents";
  const message = (sectionConfig.message || sectionConfig.markdownMessage) ?? "";
  const { showDocuments = true, customLinks, brandingColor, redirectUrl, redirectDelaySeconds = 5 } = sectionConfig;
  // Handle Redirect
  useEffect(() => {
    if (redirectUrl) {
      const timer = setTimeout(() => {
        window.location.href = redirectUrl;
      }, (redirectDelaySeconds || 5) * 1000);
      return () => clearTimeout(timer);
    }
  }, [redirectUrl, redirectDelaySeconds]);
  // Validate runId - don't proceed if it's null/undefined/empty
  const isValidRunId = runId && runId !== 'null' && runId !== 'undefined';
  // Mutation to trigger document generation
  const generateDocsMutation = useMutation({
    mutationFn: async () => {
      if (!isValidRunId) {
        throw new Error('Invalid run ID');
      }
      console.log('[FinalDocumentsSection] Triggering document generation for runId:', runId);
      const headers: Record<string, string> = {};
      if (runToken) {
        headers['Authorization'] = `Bearer ${runToken}`;
      }
      const response = await axios.post(`/api/runs/${runId}/generate-documents`, {}, { headers });
      console.log('[FinalDocumentsSection] Document generation response:', response.data);
      return response.data;
    },
    onSuccess: (data) => {
      console.log('[FinalDocumentsSection] Document generation succeeded:', data);
    },
    onError: (error) => {
      console.error('[FinalDocumentsSection] Document generation failed:', error);
    },
  });
  // Trigger document generation when component mounts - only if runId is valid
  useEffect(() => {
    if (isValidRunId) {
      console.log('[FinalDocumentsSection] Mounting with runId:', runId, 'runToken:', runToken ? 'present' : 'missing');
      generateDocsMutation.mutate();
    } else {
      console.warn('[FinalDocumentsSection] Invalid runId:', runId);
    }
  }, [runId]); // Only run once when runId changes
  // Fetch generated documents for this run - only if runId is valid
  const { data: documents = [], isLoading, error } = useQuery({
    queryKey: ["run-documents", runId],
    queryFn: async () => {
      if (!isValidRunId) {
        throw new Error('Invalid run ID');
      }
      const headers: Record<string, string> = {};
      if (runToken) {
        headers['Authorization'] = `Bearer ${runToken}`;
      }
      const response = await axios.get<{ documents: GeneratedDocument[] }>(`/api/runs/${runId}/documents`, { headers });
      return response.data.documents;
    },
    enabled: !!isValidRunId, // Only fetch if runId is valid
    refetchInterval: (query) => {
      // Only refetch if runId is valid
      if (!isValidRunId) { return false; }
      // If no documents yet, refetch every 2 seconds until they're ready
      const docs = query.state.data;
      if (!docs || docs.length === 0) {
        return 2000;
      }
      // Once we have documents, stop refetching
      return false;
    },
  });
  const formatFileSize = (bytes?: number) => {
    if (!bytes) { return ''; }
    const kb = bytes / 1024;
    if (kb < 1024) { return `${kb.toFixed(1)} KB`; }
    const mb = kb / 1024;
    return `${mb.toFixed(1)} MB`;
  };
  const getFileIcon = (mimeType?: string) => {
    if (mimeType?.includes('pdf')) {
      return '≡ƒôä';
    }
    if (mimeType?.includes('word') || mimeType?.includes('document')) {
      return '≡ƒô¥';
    }
    return '≡ƒôÄ';
  };
  // Show error if runId is invalid
  if (!isValidRunId) {
    return (
      <div className="max-w-3xl mx-auto p-6 space-y-6">
        <Card>
          <CardHeader>
            <CardTitle className="text-destructive">Unable to Load Documents</CardTitle>
            <CardDescription>
              The workflow run could not be identified. Please ensure you're accessing this page from a valid workflow run.
            </CardDescription>
          </CardHeader>
          <CardContent>
            <p className="text-sm text-muted-foreground">
              Run ID: <code className="px-2 py-1 bg-muted rounded">{runId || 'Not provided'}</code>
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }
  return (
    <div className="max-w-2xl mx-auto py-12 px-6 space-y-8 animate-in fade-in duration-500">
      {/* Success Header */}
      <div className="text-center space-y-6">
        <div className="mx-auto w-16 h-16 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-4 shadow-sm">
          <CheckCircle className="w-8 h-8" />
        </div>
        <div className="space-y-2">
          <h1
            className="text-3xl font-bold tracking-tight text-slate-900"
            style={brandingColor ? { color: brandingColor } : undefined}
          >
            {title}
          </h1>
          {/* Default subtitle if none provided in markdown */}
          {!message && (
            <p className="text-slate-500 text-lg">
              You have successfully completed this workflow.
            </p>
          )}
        </div>
      </div>
      {/* Markdown Message */}
      {message && (
        <div className="prose prose-slate prose-sm md:prose-base dark:prose-invert max-w-none text-center text-slate-600">
          <ReactMarkdown
            remarkPlugins={[remarkGfm]}
            urlTransform={(url) => {
              if (url.startsWith("http:") || url.startsWith("https:") || url.startsWith("mailto:")) {
                return url;
              }
              return "#";
            }}
          >
            {DOMPurify.sanitize(message, { ALLOWED_TAGS: ['b', 'i', 'em', 'strong', 'a', 'p', 'ul', 'ol', 'li', 'br', 'h1', 'h2', 'h3', 'h4'] })}
          </ReactMarkdown>
        </div>
      )}
      {/* Documents Section */}
      {showDocuments && (
        <Card className="border-slate-200 shadow-md overflow-hidden bg-white">
          <CardHeader className="bg-slate-50/50 border-b border-slate-100 pb-4">
            <CardTitle className="text-base font-semibold text-slate-800 flex items-center gap-2">
              <FileText className="w-4 h-4 text-slate-500" />
              Generated Documents
            </CardTitle>
          </CardHeader>
          <CardContent className="p-0">
            {error ? (
              <div className="text-center py-8 text-destructive p-4">
                <p className="text-sm font-medium">Unable to load documents</p>
                <p className="text-xs mt-1 opacity-80">{error instanceof Error ? error.message : 'Unknown error'}</p>
              </div>
            ) : documents.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-10 px-4 text-center">
                <Loader2 className="w-6 h-6 animate-spin text-primary mb-3" />
                <h3 className="text-sm font-medium text-slate-900">Preparing your documents...</h3>
                <p className="text-xs text-slate-500 mt-1">This usually takes just a moment.</p>
              </div>
            ) : (
              <div className="divide-y divide-slate-100">
                {documents.map((doc) => (
                  <div
                    key={doc.id}
                    className="flex items-center justify-between p-4 hover:bg-slate-50 transition-colors group"
                  >
                    <div className="flex items-center gap-4 flex-1 min-w-0">
                      <div className="w-10 h-10 rounded-lg bg-indigo-50 text-indigo-600 flex items-center justify-center shrink-0">
                        <span className="text-xl">{getFileIcon(doc.mimeType)}</span>
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="font-medium text-sm text-slate-900 truncate pr-4">{doc.fileName}</div>
                        {doc.fileSize && (
                          <div className="text-xs text-slate-500">
                            {formatFileSize(doc.fileSize)}
                          </div>
                        )}
                      </div>
                    </div>
                    <Button
                      size="sm"
                      className="ml-2 shrink-0 bg-slate-900 text-white hover:bg-slate-800 shadow-sm"
                      asChild
                    >
                      <a href={doc.fileUrl} download={doc.fileName} target="_blank" rel="noopener noreferrer">
                        <Download className="w-3.5 h-3.5 mr-2" />
                        Download
                      </a>
                    </Button>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      )}
      {/* Custom Links */}
      {
        customLinks && customLinks.length > 0 && (
          <div className="flex flex-col gap-3 pt-4">
            {customLinks.map((link, i) => (
              <Button
                key={i}
                variant={link.style === 'button' ? 'default' : 'outline'}
                size="lg"
                className="w-full text-base h-12"
                asChild
                style={link.style === 'button' && brandingColor ? { backgroundColor: brandingColor } : undefined}
              >
                <a href={link.url} target="_blank" rel="noopener noreferrer">
                  {link.label}
                </a>
              </Button>
            ))}
          </div>
        )
      }
      {/* Footer */}
      <div className="text-center pt-8 border-t border-slate-100 mt-8">
        <p className="text-sm text-slate-400">
          Documents are securely available for 30 days. You can close this window at any time.
        </p>
      </div>
    </div >
  );
}

import { CheckCircle2, ArrowRight, GitBranch, AlertCircle, FileText } from "lucide-react";
import { useMemo } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import type { ApiWorkflow } from "@/lib/vault-api";
import { useProjectWorkflows } from "@/lib/vault-hooks";

import { evaluateConditionExpression } from "@shared/conditionEvaluator";
interface AssignmentRule {
    targetWorkflowId: string;
    condition: any;
    enabled: boolean;
}
interface IntakeAssignmentSectionProps {
    workflow: ApiWorkflow;
    runValues: Record<string, any>;
    onComplete?: () => void;
}
export function IntakeAssignmentSection({ workflow, runValues, onComplete }: IntakeAssignmentSectionProps) {
    // Fetch candidate workflows to display their names/details
    const { data: projectWorkflows } = useProjectWorkflows(workflow.projectId || undefined);
    // Evaluate assignments
    const assignedWorkflows = useMemo(() => {
        if (!workflow.intakeConfig?.assignments) { return []; }
        if (!projectWorkflows) { return []; }
        const assignments = workflow.intakeConfig.assignments as AssignmentRule[];
        return assignments
            .filter(rule => {
                if (!rule.enabled) { return false; }
                // If no condition, it's always available
                if (!rule.condition) { return true; }
                // Evaluate condition against run values
                // Note: evaluateConditionExpression generic might need 'any' cast if strict types aren't matching
                try {
                    return evaluateConditionExpression(rule.condition, runValues);
                } catch (e) {
                    console.error("Failed to evaluate assignment rule", e);
                    return false;
                }
            })
            .map(rule => {
                const target = projectWorkflows.find(w => w.id === rule.targetWorkflowId);
                return {
                    ...rule,
                    targetWorkflow: target
                };
            })
            .filter(item => item.targetWorkflow); // Ensure target exists
    }, [workflow.intakeConfig, runValues, projectWorkflows]);
    return (
        <div className="space-y-6">
            <Card className="border-primary/20 bg-primary/5">
                <CardHeader>
                    <div className="flex items-center gap-3">
                        <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center text-primary">
                            <CheckCircle2 className="h-6 w-6" />
                        </div>
                        <div>
                            <CardTitle className="text-xl">Intake Complete</CardTitle>
                            <CardDescription>Client data has been successfully recorded.</CardDescription>
                        </div>
                    </div>
                </CardHeader>
            </Card>
            <div className="grid gap-4 md:grid-cols-1">
                <h3 className="text-lg font-semibold flex items-center gap-2">
                    <GitBranch className="h-5 w-5 text-secondary" />
                    Recommended Next Actions
                </h3>
                {assignedWorkflows.length > 0 ? (
                    <div className="grid gap-4">
                        {assignedWorkflows.map(({ targetWorkflow }, index) => (
                            <Card key={targetWorkflow!.id} className="hover:border-secondary transition-colors">
                                <CardContent className="p-4 flex items-center justify-between">
                                    <div className="flex items-center gap-4">
                                        <div className="h-10 w-10 bg-secondary/10 rounded-lg flex items-center justify-center text-secondary">
                                            <FileText className="h-5 w-5" />
                                        </div>
                                        <div>
                                            <h4 className="font-semibold">{targetWorkflow!.title}</h4>
                                            <p className="text-sm text-muted-foreground line-clamp-1">
                                                {targetWorkflow!.description || "No description"}
                                            </p>
                                        </div>
                                    </div>
                                    <Button variant="outline" className="gap-2">
                                        Start Workflow <ArrowRight className="h-4 w-4" />
                                    </Button>
                                </CardContent>
                            </Card>
                        ))}
                    </div>
                ) : (
                    <Card>
                        <CardContent className="p-6 text-center text-muted-foreground flex flex-col items-center gap-2">
                            <AlertCircle className="h-8 w-8 opacity-50" />
                            <p>No specific workflows matched the intake criteria.</p>
                        </CardContent>
                    </Card>
                )}
            </div>
        </div>
    );
}

import { Edit2, CheckCircle2 } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
interface ReviewSectionProps {
    sections: any[];
    allSteps: any[];
    values: Record<string, any>;
    onEditSection: (sectionIndex: number) => void;
    visibleSectionIds: string[];
}
export function ReviewSection({
    sections,
    allSteps,
    values,
    onEditSection,
    visibleSectionIds
}: ReviewSectionProps) {
    // Helper to format values for display
    const formatValue = (val: any): string => {
        if (val === null || val === undefined || val === "") {return "Not answered";}
        if (typeof val === "boolean") {return val ? "Yes" : "No";}
        if (val instanceof Date) {return val.toLocaleDateString();}
        if (Array.isArray(val)) {return val.join(", ");}
        if (typeof val === "object") {return JSON.stringify(val);} // Fallback
        return String(val);
    };
    return (
        <div className="space-y-8">
            <div className="text-center space-y-2 mb-8">
                <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-indigo-50 text-indigo-600 mb-2">
                    <CheckCircle2 className="w-6 h-6" />
                </div>
                <h2 className="text-2xl font-bold tracking-tight text-slate-900">Review your answers</h2>
                <p className="text-slate-500 max-w-md mx-auto">
                    Please review the information below. You can go back and make changes if needed before finalizing.
                </p>
            </div>
            <div className="space-y-6">
                {sections.map((section, index) => {
                    // Only show visible sections
                    if (!visibleSectionIds.includes(section.id)) {return null;}
                    const sectionSteps = allSteps.filter(s => s.sectionId === section.id);
                    // Hide sections with no visible steps? For now show all visible sections.
                    return (
                        <Card key={section.id} className="border-slate-200 shadow-sm overflow-hidden">
                            <CardHeader className="bg-slate-50/50 border-b border-slate-100 py-3 px-4 flex flex-row items-center justify-between">
                                <CardTitle className="text-sm font-semibold text-slate-700 uppercase tracking-wider">
                                    {section.title}
                                </CardTitle>
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    className="h-8 text-indigo-600 hover:text-indigo-700 hover:bg-indigo-50 px-2"
                                    onClick={() => onEditSection(index)}
                                >
                                    <Edit2 className="w-3 h-3 mr-1.5" />
                                    Edit
                                </Button>
                            </CardHeader>
                            <CardContent className="p-0">
                                <div className="divide-y divide-slate-100">
                                    {sectionSteps.map((step: any) => {
                                        // Hide un-answered or invisible steps if needed
                                        // For review, we usually want to show what was answered.
                                        // If a step was hidden by logic, it shouldn't be here (values might be empty or stale).
                                        // Ideally, we check step visibility too, but that requires re-running logic.
                                        // Simplification: Show if value exists or if it's in the list.
                                        const val = values[step.id];
                                        if (val === undefined || val === null || val === "") {return null;} // Skip empty for conciseness
                                        return (
                                            <div key={step.id} className="grid grid-cols-1 md:grid-cols-3 gap-1 md:gap-4 p-4 hover:bg-slate-50/30 transition-colors">
                                                <div className="text-sm font-medium text-slate-500 md:col-span-1">
                                                    {step.title}
                                                </div>
                                                <div className="text-sm text-slate-900 md:col-span-2 font-medium break-words">
                                                    {formatValue(val)}
                                                </div>
                                            </div>
                                        );
                                    })}
                                    {sectionSteps.every((s: any) => !values[s.id]) && (
                                        <div className="p-4 text-sm text-slate-400 italic text-center">
                                            No questions answered in this section.
                                        </div>
                                    )}
                                </div>
                            </CardContent>
                        </Card>
                    );
                })}
            </div>
        </div>
    );
}

/**
 * Run Filters Component
 * Stage 8: Filters for status, workflow, date range, and search
 */

import { X, Search } from 'lucide-react';
import React, { useState } from 'react';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { ListRunsParams } from '@/lib/vault-api';

interface RunFiltersProps {
  filters: ListRunsParams;
  onChange: (filters: ListRunsParams) => void;
}

export function RunFilters({ filters, onChange }: RunFiltersProps) {
  const [searchTerm, setSearchTerm] = useState(filters.q ?? '');

  const handleStatusChange = (value: string) => {
    onChange({
      ...filters,
      status: value === 'all' ? undefined : (value as 'pending' | 'success' | 'error'),
      cursor: undefined, // Reset pagination
    });
  };

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onChange({
      ...filters,
      q: searchTerm || undefined,
      cursor: undefined,
    });
  };

  const handleDateFromChange = (value: string) => {
    onChange({
      ...filters,
      from: value ? new Date(value).toISOString() : undefined,
      cursor: undefined,
    });
  };

  const handleDateToChange = (value: string) => {
    onChange({
      ...filters,
      to: value ? new Date(value).toISOString() : undefined,
      cursor: undefined,
    });
  };

  const handleClearFilters = () => {
    setSearchTerm('');
    onChange({ limit: filters.limit });
  };

  const hasActiveFilters = filters.status || filters.q || filters.from || filters.to;

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {/* Status filter */}
        <div className="space-y-2">
          <Label htmlFor="status">Status</Label>
          <Select
            value={filters.status || 'all'}
            onValueChange={handleStatusChange}
          >
            <SelectTrigger id="status">
              <SelectValue placeholder="All statuses" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All</SelectItem>
              <SelectItem value="success">Success</SelectItem>
              <SelectItem value="error">Error</SelectItem>
              <SelectItem value="pending">Pending</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* Date from */}
        <div className="space-y-2">
          <Label htmlFor="dateFrom">From</Label>
          <Input
            id="dateFrom"
            type="datetime-local"
            value={filters.from ? new Date(filters.from).toISOString().slice(0, 16) : ''}
            onChange={(e) => handleDateFromChange(e.target.value)}
          />
        </div>

        {/* Date to */}
        <div className="space-y-2">
          <Label htmlFor="dateTo">To</Label>
          <Input
            id="dateTo"
            type="datetime-local"
            value={filters.to ? new Date(filters.to).toISOString().slice(0, 16) : ''}
            onChange={(e) => handleDateToChange(e.target.value)}
          />
        </div>

        {/* Clear button */}
        <div className="flex items-end">
          {hasActiveFilters && (
            <Button
              variant="outline"
              onClick={handleClearFilters}
              className="w-full"
            >
              <X className="h-4 w-4 mr-2" />
              Clear Filters
            </Button>
          )}
        </div>
      </div>

      {/* Search */}
      <form onSubmit={handleSearchSubmit} className="flex gap-2">
        <div className="flex-1">
          <Input
            placeholder="Search by run ID, creator email, or input data..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <Button type="submit" variant="secondary">
          <Search className="h-4 w-4 mr-2" />
          Search
        </Button>
      </form>
    </div>
  );
}

/**
 * Stage 21: Run Outputs Panel
 *
 * UI for viewing and downloading generated documents from workflow runs.
 * Features:
 * - List all outputs (DOCX, PDF) for a run
 * - Show output status (pending, ready, failed)
 * - Download ready outputs
 * - Display error messages for failed outputs
 * - File metadata (size, created date, template key)
 * - Retry failed PDF conversions
 */

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import {
  FileText,
  Download,
  Loader2,
  AlertCircle,
  CheckCircle,
  Clock,
  RefreshCw,
} from 'lucide-react';
import React from 'react';
import { toast } from 'sonner';

import { Badge } from '../ui/badge';
import { Button } from '../ui/button';

interface RunOutput {
  id: string;
  runId: string;
  workflowVersionId: string;
  templateKey: string;
  fileType: 'docx' | 'pdf';
  storagePath: string;
  status: 'pending' | 'ready' | 'failed';
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

interface RunOutputsPanelProps {
  runId: string;
}

export function RunOutputsPanel({ runId }: RunOutputsPanelProps) {
  const queryClient = useQueryClient();

  // Fetch run outputs
  const {
    data: outputs,
    isLoading,
    error,
  } = useQuery<{ data: RunOutput[] }>({
    queryKey: ['run-outputs', runId],
    queryFn: async () => {
      const response = await fetch(`/api/runs/${runId}/outputs`, {
        credentials: 'include',
      });

      if (!response.ok) {
        throw new Error('Failed to fetch run outputs');
      }

      return response.json();
    },
    refetchInterval: (data: any) => {
      // Auto-refresh if there are pending outputs
      const hasPending = data?.data?.some((o: any) => o.status === 'pending');
      return hasPending ? 5000 : false; // Poll every 5 seconds
    },
  });

  // Download output mutation
  const downloadMutation = useMutation({
    mutationFn: async (outputId: string) => {
      const response = await fetch(`/api/runs/${runId}/outputs/${outputId}/download`, {
        credentials: 'include',
      });

      if (!response.ok) {
        throw new Error('Failed to download output');
      }

      // Get filename from Content-Disposition header or use default
      const contentDisposition = response.headers.get('Content-Disposition');
      const filenameMatch = contentDisposition?.match(/filename="?([^"]+)"?/);
      const filename = filenameMatch?.[1] || 'output.docx';

      // Download file
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      window.URL.revokeObjectURL(url);

      return { filename };
    },
    onSuccess: (result) => {
      toast.success(`Downloaded ${result.filename}`);
    },
    onError: (error: Error) => {
      toast.error(error.message);
    },
  });

  // Retry PDF conversion mutation
  const retryMutation = useMutation({
    mutationFn: async (outputId: string) => {
      const response = await fetch(`/api/runs/${runId}/outputs/${outputId}/retry`, {
        method: 'POST',
        credentials: 'include',
      });

      if (!response.ok) {
        throw new Error('Failed to retry PDF conversion');
      }

      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['run-outputs', runId] });
      toast.success('PDF conversion retry queued');
    },
    onError: (error: Error) => {
      toast.error(error.message);
    },
  });

  const handleDownload = (outputId: string) => {
    downloadMutation.mutate(outputId);
  };

  const handleRetry = (outputId: string) => {
    retryMutation.mutate(outputId);
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'ready':
        return <CheckCircle className="h-4 w-4 text-green-600" />;
      case 'pending':
        return <Clock className="h-4 w-4 text-yellow-600" />;
      case 'failed':
        return <AlertCircle className="h-4 w-4 text-red-600" />;
      default:
        return null;
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'ready':
        return (
          <Badge variant="default" className="bg-green-600">
            Ready
          </Badge>
        );
      case 'pending':
        return (
          <Badge variant="secondary" className="bg-yellow-600">
            Processing
          </Badge>
        );
      case 'failed':
        return (
          <Badge variant="destructive" className="bg-red-600">
            Failed
          </Badge>
        );
      default:
        return null;
    }
  };

  const formatFileSize = (path: string): string => {
    // Placeholder: In real implementation, would fetch file size from backend
    return 'N/A';
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-8 w-8 animate-spin text-gray-400" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-4 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg">
        <p className="text-red-900 dark:text-red-100 flex items-center gap-2">
          <AlertCircle className="h-4 w-4" />
          Error: {(error).message}
        </p>
      </div>
    );
  }

  if (!outputs?.data || outputs.data.length === 0) {
    return (
      <div className="text-center py-8 text-gray-500">
        <FileText className="h-12 w-12 mx-auto mb-2 opacity-50" />
        <p>No outputs generated yet</p>
        <p className="text-sm">
          Outputs will appear here once the workflow generates documents
        </p>
      </div>
    );
  }

  // Group outputs by template key
  const groupedOutputs = outputs.data.reduce((acc, output) => {
    if (!acc[output.templateKey]) {
      acc[output.templateKey] = [];
    }
    acc[output.templateKey].push(output);
    return acc;
  }, {} as Record<string, RunOutput[]>);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-semibold flex items-center gap-2">
          <FileText className="h-5 w-5" />
          Generated Documents ({outputs.data.length})
        </h3>
      </div>

      {Object.entries(groupedOutputs).map(([templateKey, outputs]) => (
        <div key={templateKey} className="space-y-2">
          <h4 className="font-medium text-sm text-gray-700 dark:text-gray-300">
            Template: <code className="bg-gray-100 dark:bg-gray-800 px-1 rounded">{templateKey}</code>
          </h4>

          <div className="space-y-2">
            {outputs.map((output) => (
              <div
                key={output.id}
                className="p-4 bg-white dark:bg-gray-800 border rounded-lg shadow-sm"
              >
                <div className="flex items-start justify-between">
                  <div className="flex items-start gap-3 flex-1">
                    {getStatusIcon(output.status)}

                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-1">
                        <FileText className="h-4 w-4 text-gray-500" />
                        <span className="font-medium">
                          {output.fileType.toUpperCase()} Output
                        </span>
                        {getStatusBadge(output.status)}
                      </div>

                      {output.status === 'ready' && output.storagePath && (
                        <p className="text-sm text-gray-600 dark:text-gray-400">
                          File: {output.storagePath}
                        </p>
                      )}

                      {output.status === 'pending' && (
                        <p className="text-sm text-yellow-700 dark:text-yellow-300 flex items-center gap-1">
                          <Loader2 className="h-3 w-3 animate-spin" />
                          Processing...
                        </p>
                      )}

                      {output.status === 'failed' && output.error && (
                        <div className="mt-2 p-2 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded">
                          <p className="text-sm text-red-900 dark:text-red-100">
                            <strong>Error:</strong> {output.error}
                          </p>
                        </div>
                      )}

                      <div className="flex items-center gap-2 mt-2 text-xs text-gray-500">
                        <span>
                          Created: {new Date(output.createdAt).toLocaleString()}
                        </span>
                        {output.status !== 'pending' && (
                          <>
                            <span>ΓÇó</span>
                            <span>
                              Updated: {new Date(output.updatedAt).toLocaleString()}
                            </span>
                          </>
                        )}
                      </div>
                    </div>
                  </div>

                  <div className="flex gap-2">
                    {output.status === 'ready' && (
                      <Button
                        size="sm"
                        onClick={() => { void handleDownload(output.id); }}
                        disabled={downloadMutation.isPending}
                      >
                        <Download className="h-4 w-4 mr-1" />
                        Download
                      </Button>
                    )}

                    {output.status === 'failed' && output.fileType === 'pdf' && (
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => { void handleRetry(output.id); }}
                        disabled={retryMutation.isPending}
                      >
                        <RefreshCw className="h-4 w-4 mr-1" />
                        Retry
                      </Button>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      ))}

      {outputs.data.some((o) => o.status === 'pending') && (
        <div className="p-3 bg-blue-50 dark:bg-blue-900/20 rounded-lg border border-blue-200 dark:border-blue-800">
          <p className="text-sm text-blue-900 dark:text-blue-100 flex items-center gap-2">
            <Loader2 className="h-4 w-4 animate-spin" />
            Some outputs are still being processed. This panel will auto-refresh.
          </p>
        </div>
      )}
    </div>
  );
}

/**
 * Runs Table Component
