import { MoreVertical , LucideIcon } from "lucide-react";
import { ReactNode } from "react";
import { Link, useLocation } from "wouter";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";



export interface EntityAction {
  label: string | ReactNode;
  icon?: LucideIcon;
  onClick?: (entity: any) => void;
  href?: string;
  variant?: "default" | "destructive";
  separator?: boolean; // Add separator before this item
}

export interface EntityCardProps {
  entity: {
    id: string;
    title: string;
    description?: string | null;
    updatedAt: string;
    [key: string]: any;
  };
  icon: LucideIcon;
  iconClassName?: string;
  link?: {
    href: string;
    label?: string;
  };
  actions?: EntityAction[];
  renderBadge?: (entity: any) => ReactNode;
  onClick?: (entity: any) => void;
  className?: string;
}

export function EntityCard({
  entity,
  icon: Icon,
  iconClassName = "bg-primary/10 text-primary",
  link,
  actions = [],
  renderBadge,
  onClick,
  className = "",
}: EntityCardProps) {
  const hasActions = actions.length > 0;
  const [, setLocation] = useLocation();

  // Handle card click navigation
  const handleCardClick = () => {
    if (onClick) {
      onClick(entity);
    } else if (link?.href) {
      setLocation(link.href);
    }
  };

  return (
    <Card
      className={`group hover:shadow-lg transition-shadow overflow-hidden h-full flex flex-col ${onClick || link ? 'cursor-pointer' : ''} ${className}`}
      onClick={onClick || link ? handleCardClick : undefined}
    >
      <CardHeader className="flex-1">
        <div className="flex items-start justify-between">
          <div className="flex items-start gap-3 flex-1">
            <div className={`p-2 rounded-lg ${iconClassName} shrink-0`}>
              <Icon className="w-5 h-5" />
            </div>
            <div className="flex-1 min-w-0">
              <TooltipProvider>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <div className="w-full">
                      <CardTitle className="w-full break-words line-clamp-2 leading-tight">
                        {entity.title}
                      </CardTitle>
                    </div>
                  </TooltipTrigger>
                  <TooltipContent>
                    <div className="max-w-[300px] break-words">{entity.title}</div>
                  </TooltipContent>
                </Tooltip>
              </TooltipProvider>
              {entity.description !== undefined && (
                <CardDescription className="mt-1 line-clamp-2">
                  {entity.description || "No description"}
                </CardDescription>
              )}
            </div>
          </div>

          {hasActions && (
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button
                  variant="ghost"
                  size="icon"
                  className="opacity-0 group-hover:opacity-100 transition-opacity"
                  onClick={(e) => e.stopPropagation()}
                >
                  <MoreVertical className="w-4 h-4" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                {actions.map((action, idx) => {
                  const isDestructive = action.variant === "destructive";
                  const ActionIcon = action.icon;

                  return (
                    <div key={idx}>
                      {action.separator && idx > 0 && <DropdownMenuSeparator />}

                      {action.href ? (
                        <DropdownMenuItem asChild>
                          <Link href={action.href}>
                            {ActionIcon && <ActionIcon className="w-4 h-4 mr-2" />}
                            {action.label}
                          </Link>
                        </DropdownMenuItem>
                      ) : (
                        <DropdownMenuItem
                          className={isDestructive ? "text-destructive" : ""}
                          onClick={(e) => {
                            e.stopPropagation();
                            action.onClick?.(entity);
                          }}
                        >
                          {ActionIcon && <ActionIcon className="w-4 h-4 mr-2" />}
                          {action.label}
                        </DropdownMenuItem>
                      )}
                    </div>
                  );
                })}
              </DropdownMenuContent>
            </DropdownMenu>
          )}
        </div>
      </CardHeader>

      <CardContent>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            {renderBadge?.(entity)}
          </div>
          <span className="text-xs text-muted-foreground">
            {new Date(entity.updatedAt).toLocaleDateString()}
          </span>
        </div>
      </CardContent>
    </Card>
  );
}

import React, { useState, useRef, useEffect } from "react";

import { Input } from "@/components/ui/input";

interface InlineEditableTitleProps {
  value: string;
  onSave: (value: string) => void;
  className?: string;
  placeholder?: string;
  autoFocus?: boolean;
  onEnterKey?: () => void;
}

export function InlineEditableTitle({
  value,
  onSave,
  className = "",
  placeholder = "Enter title...",
  autoFocus = false,
  onEnterKey,
}: InlineEditableTitleProps) {
  const [isEditing, setIsEditing] = useState(autoFocus);
  const [localValue, setLocalValue] = useState(value);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setLocalValue(value);
  }, [value]);

  useEffect(() => {
    if (isEditing && inputRef.current) {
      inputRef.current.focus();
      inputRef.current.select();
    }
  }, [isEditing]);

  const handleSave = () => {
    const trimmedValue = localValue.trim();
    console.log('[InlineEditableTitle] handleSave called', {
      originalValue: value,
      newValue: trimmedValue,
      isDifferent: trimmedValue !== value,
      willSave: trimmedValue && trimmedValue !== value
    });

    if (trimmedValue && trimmedValue !== value) {
      console.log('[InlineEditableTitle] Calling onSave with:', trimmedValue);
      onSave(trimmedValue);
    } else if (!trimmedValue) {
      console.log('[InlineEditableTitle] Empty value, reverting');
      setLocalValue(value); // Revert if empty
    } else {
      console.log('[InlineEditableTitle] No change detected, not saving');
    }
    setIsEditing(false);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter") {
      handleSave();
      if (onEnterKey) {
        onEnterKey();
      }
    } else if (e.key === "Escape") {
      setLocalValue(value);
      setIsEditing(false);
    }
  };

  if (isEditing) {
    return (
      <Input
        ref={inputRef}
        value={localValue}
        onChange={(e) => setLocalValue(e.target.value)}
        onBlur={handleSave}
        onKeyDown={handleKeyDown}
        className={`border-b-2 border-blue-500 focus-visible:ring-0 ${className}`}
        placeholder={placeholder}
      />
    );
  }

  return (
    <span
      onClick={() => setIsEditing(true)}
      className={`hover:text-blue-500 cursor-pointer transition-colors ${className}`}
      title="Click to edit"
    >
      {value || placeholder}
    </span>
  );
}

/**
 * JSON Viewer Component
 * Enhanced with expand/collapse, change highlighting, and copy path functionality
 */

import { ChevronRight, ChevronDown, Copy, Check } from "lucide-react";
import React, { useState, useEffect, useRef } from "react";

import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { cn } from "@/lib/utils";

interface JsonViewerProps {
  data: Record<string, any> | any;
  className?: string;
  maxHeight?: string;
  readOnly?: boolean;
  highlightChanges?: boolean;
}

// Hook to detect dark mode from HTML class
function useDarkModeObserver() {
  const [isDark, setIsDark] = useState(document.documentElement.classList.contains("dark"));

  useEffect(() => {
    const observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        if (mutation.attributeName === "class") {
          setIsDark(document.documentElement.classList.contains("dark"));
        }
      });
    });

    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    return () => observer.disconnect();
  }, []);

  return isDark;
}

// Helper to check if two values are effectively different
function isDifferent(val1: any, val2: any): boolean {
  if (val1 === val2) { return false; }
  if (typeof val1 !== typeof val2) { return true; }
  if (typeof val1 === 'object' && val1 !== null && val2 !== null) {
    if (Array.isArray(val1) !== Array.isArray(val2)) { return true; }
    return JSON.stringify(val1) !== JSON.stringify(val2);
  }
  return true;
}

export function JsonViewer({ data, className, maxHeight = '400px', readOnly = true, highlightChanges = true }: JsonViewerProps) {
  const isDark = useDarkModeObserver();
  const prevDataRef = useRef<Record<string, any>>({});
  const [changedPaths, setChangedPaths] = useState<Map<string, number>>(new Map());
  const [copiedAll, setCopiedAll] = useState(false);

  // Calculate changed paths
  useEffect(() => {
    if (!highlightChanges) { return; }

    const prevData = prevDataRef.current;
    const now = Date.now();
    const newChanges = new Map<string, number>();

    function findChanges(current: any, prev: any, path: string) {
      if (isDifferent(current, prev)) {
        newChanges.set(path, now);
      }
      if (typeof current === 'object' && current !== null && typeof prev === 'object' && prev !== null) {
        Object.keys(current).forEach(key => {
          const nextPath = path ? `${path}.${key}` : key;
          findChanges(current[key], prev[key], nextPath);
        });
      }
    }

    findChanges(data, prevData, "");

    if (newChanges.size > 0) {
      setChangedPaths(prev => {
        const map = new Map(prev);
        newChanges.forEach((ts, path) => map.set(path, ts));
        return map;
      });

      // Cleanup after 5 seconds
      setTimeout(() => {
        setChangedPaths(current => {
          const threshold = Date.now() - 5000;
          const map = new Map();
          current.forEach((ts, path) => {
            if (ts > threshold) { map.set(path, ts); }
          });
          return map;
        });
      }, 5000);
    }

    prevDataRef.current = data;
  }, [data, highlightChanges]);

  const handleCopyAll = async () => {
    await navigator.clipboard.writeText(JSON.stringify(data, null, 2));
    setCopiedAll(true);
    setTimeout(() => setCopiedAll(false), 2000);
  };

  // Handle non-object data
  if (typeof data !== 'object' || data === null) {
    return (
      <Card className={cn("relative p-4", className)}>
        <pre className="text-sm font-mono overflow-auto bg-muted/30 p-3 rounded-md" style={{ maxHeight }}>
          <code>{JSON.stringify(data, null, 2)}</code>
        </pre>
      </Card>
    );
  }

  return (
    <Card className={cn("relative", className)}>
      <div className="absolute top-2 right-2 z-10">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => { void handleCopyAll(); }}
          className="h-7 px-2"
        >
          {copiedAll ? (
            <>
              <Check className="h-3 w-3 mr-1" />
              Copied
            </>
          ) : (
            <>
              <Copy className="h-3 w-3 mr-1" />
              Copy All
            </>
          )}
        </Button>
      </div>

      <div
        className={cn("text-xs font-mono overflow-auto p-4 bg-slate-50 dark:bg-slate-950/50")}
        style={{ maxHeight }}
      >
        <JsonNode
          name="root"
          value={data}
          isLast={true}
          depth={0}
          path=""
          changedPaths={changedPaths}
          initiallyExpanded={true}
          readOnly={readOnly}
        />
      </div>
    </Card>
  );
}

interface JsonNodeProps {
  name: string | null;
  value: any;
  isLast: boolean;
  depth: number;
  path: string;
  changedPaths: Map<string, number>;
  initiallyExpanded?: boolean;
  readOnly?: boolean;
}

function JsonNode({ name, value, isLast, depth, path, changedPaths, initiallyExpanded = false, readOnly = true }: JsonNodeProps) {
  const [expanded, setExpanded] = useState(initiallyExpanded || depth < 2);
  const [copied, setCopied] = useState(false);
  const [copiedPath, setCopiedPath] = useState(false);

  // Highlight logic
  const lastChange = changedPaths.get(path);
  const isHighlighted = lastChange && (Date.now() - lastChange < 2000); // 2s highlight

  const isObject = typeof value === 'object' && value !== null;
  const isArray = Array.isArray(value);
  const isEmpty = isObject && Object.keys(value).length === 0;

  const handleCopy = (e: React.MouseEvent, text: string) => {
    e.stopPropagation();
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
  };

  const handleCopyPath = (e: React.MouseEvent, pathToCopy: string) => {
    e.stopPropagation();
    navigator.clipboard.writeText(pathToCopy);
    setCopiedPath(true);
    setTimeout(() => setCopiedPath(false), 1500);
  };

  const getTypeColor = (val: any) => {
    if (val === null) { return "text-rose-500"; }
    switch (typeof val) {
      case 'string': return "text-emerald-600 dark:text-emerald-400";
      case 'number': return "text-blue-600 dark:text-blue-400";
      case 'boolean': return "text-purple-600 dark:text-purple-400";
      default: return "text-gray-600 dark:text-gray-400";
    }
  };

  const renderValue = (val: any) => {
    if (val === null) { return "null"; }
    if (typeof val === 'string') { return `"${val}"`; }
    return String(val);
  };

  const containerClass = cn(
    "flex items-start group rounded-sm px-1 -ml-1 border border-transparent transition-colors",
    isHighlighted ? "bg-yellow-100 dark:bg-yellow-900/30 duration-500" : "hover:bg-black/5 dark:hover:bg-white/5",
  );

  if (isObject) {
    const keys = Object.keys(value);

    return (
      <div className="ml-0">
        <div className={containerClass} onClick={() => { if (!isEmpty) {setExpanded(!expanded);} }}>
          {/* Toggle */}
          {!isEmpty ? (
            <span className="cursor-pointer mr-1 mt-0.5 opacity-50 hover:opacity-100">
              {expanded ? <ChevronDown className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
            </span>
          ) : <span className="w-4 mr-1"></span>}

          {/* Key */}
          {name && (
            <span className="text-indigo-600 dark:text-indigo-400 mr-1 select-text" title={`Path: ${path}`}>
              {name}:
            </span>
          )}

          {/* Preview */}
          <span className="text-gray-500 dark:text-gray-400">
            {isArray ? "[" : "{"}
            {!expanded && !isEmpty && (
              <span className="mx-1 text-gray-400 italic">
                {keys.length} {keys.length === 1 ? 'item' : 'items'}
              </span>
            )}
            {isEmpty && (isArray ? "]" : "}")}
          </span>

          {/* Tools */}
          <div className="ml-auto opacity-0 group-hover:opacity-100 flex gap-1">
            {path && readOnly && (
              <button
                onClick={(e) => { void handleCopyPath(e, path); }}
                title="Copy Path"
                className="text-xs px-1.5 py-0.5 rounded bg-muted/50 hover:bg-muted"
              >
                {copiedPath ? <Check className="w-3 h-3 text-green-500" /> : "path"}
              </button>
            )}
            <button onClick={(e) => handleCopy(e, JSON.stringify(value, null, 2))} title="Copy Value">
              {copied ? <Check className="w-3 h-3 text-green-500" /> : <Copy className="w-3 h-3 text-gray-400 hover:text-gray-600" />}
            </button>
          </div>
        </div>

        {/* Children */}
        {expanded && !isEmpty && (
          <div className="ml-4 border-l border-gray-200 dark:border-gray-800 pl-2">
            {keys.map((key, i) => (
              <JsonNode
                key={key}
                name={isArray ? `[${key}]` : key}
                value={value[key]}
                isLast={i === keys.length - 1}
                depth={depth + 1}
                path={path ? `${path}.${key}` : key}
                changedPaths={changedPaths}
                readOnly={readOnly}
              />
            ))}
          </div>
        )}

        {expanded && !isEmpty && (
          <div className="ml-4 pl-1 text-gray-500 dark:text-gray-400">
            {isArray ? "]" : "}"}{!isLast && ","}
          </div>
        )}
      </div>
    )
  }

  // Primitive
  return (
    <div className={containerClass}>
      <span className="w-4 mr-1"></span>
      {name && (
        <span className="text-indigo-600 dark:text-indigo-400 mr-1 select-text" title={`Path: ${path}`}>
          {name}:
        </span>
      )}
      <span className={cn("break-all select-text", getTypeColor(value))}>
        {renderValue(value)}
      </span>
      {!isLast && <span className="text-gray-400">,</span>}

      {/* Tools */}
      <div className="ml-auto opacity-0 group-hover:opacity-100 flex gap-1">
        {path && readOnly && (
          <button
            onClick={(e) => { void handleCopyPath(e, path); }}
            title="Copy Path"
            className="text-xs px-1.5 py-0.5 rounded bg-muted/50 hover:bg-muted"
          >
            {copiedPath ? <Check className="w-3 h-3 text-green-500" /> : "path"}
          </button>
        )}
        <button onClick={(e) => handleCopy(e, String(value))} title="Copy Value">
          {copied ? <Check className="w-3 h-3 text-green-500" /> : <Copy className="w-3 h-3 text-gray-400 hover:text-gray-600" />}
        </button>
      </div>
    </div>
  );
}

