        </TabsContent>

        {/* Errors Tab */}
        {hasErrors && (
          <TabsContent value="errors" className="flex-1 overflow-auto p-4 m-0">
            <div className="space-y-3">
              <h3 className="text-sm font-semibold">
                {result.errors!.length} Error{result.errors!.length !== 1 ? 's' : ''} Found
              </h3>
