import { DevPanelBus } from "../../lib/devpanelBus";
import { versionAPI, type ApiWorkflowVersion } from "../../lib/vault-api";

import { queryKeys } from "./queryKeys";

export function useVersions(workflowId: string | undefined): UseQueryResult<ApiWorkflowVersion[]> {
    return useQuery({
        queryKey: queryKeys.versions(workflowId ?? ""),
        queryFn: () => versionAPI.list(workflowId ?? ""),
        enabled: !!workflowId && workflowId !== "undefined",
    });
}

export function usePublishWorkflow(): UseMutationResult<ApiWorkflowVersion, unknown, { workflowId: string; graphJson: unknown; notes?: string }> {
    const queryClient = useQueryClient();
    return useMutation({
        mutationFn: ({ workflowId, graphJson, notes }: { workflowId: string; graphJson: unknown; notes?: string }) =>
            versionAPI.publish(workflowId, { graphJson, notes }),
        onSuccess: async (_, variables) => {
            await queryClient.invalidateQueries({ queryKey: queryKeys.versions(variables.workflowId) });
            await queryClient.invalidateQueries({ queryKey: queryKeys.workflow(variables.workflowId) });
        },
    });
}

export function useRestoreVersion(): UseMutationResult<unknown, unknown, { workflowId: string; versionId: string }> {
    const queryClient = useQueryClient();
    return useMutation({
        mutationFn: ({ workflowId, versionId }: { workflowId: string; versionId: string }) =>
            versionAPI.restore(workflowId, versionId),
        onSuccess: async (_, variables) => {
            await queryClient.invalidateQueries({ queryKey: queryKeys.versions(variables.workflowId) });
            await queryClient.invalidateQueries({ queryKey: queryKeys.workflow(variables.workflowId) });
            await queryClient.invalidateQueries({ queryKey: queryKeys.sections(variables.workflowId) });
            // Invalidate everything basically
            await queryClient.invalidateQueries({ queryKey: ["workflows", variables.workflowId] });
            DevPanelBus.emitWorkflowUpdate();
        },
    });
}

import * as decoding from 'lib0/decoding';
import * as encoding from 'lib0/encoding';
import { Awareness } from 'y-protocols/awareness';
import * as awarenessProtocol from 'y-protocols/awareness';
import * as syncProtocol from 'y-protocols/sync';
import * as Y from 'yjs';

const MESSAGE_SYNC = 0;
const MESSAGE_AWARENESS = 1;

export interface WebSocketProviderOptions {
  params?: Record<string, string>;
  awareness?: Awareness;
  connect?: boolean;
}

export type WebSocketProviderStatus = 'connecting' | 'connected' | 'disconnected';

/**
 * Custom WebSocket provider for Y.js collaboration
 */
export class WebSocketProvider {
  public doc: Y.Doc;
  public awareness: Awareness;
  public url: string;
  public roomname: string;

  private ws: WebSocket | null = null;
  private wsconnecting = false;
  private wsconnected = false;
  private synced = false;
  private shouldConnect = true;

  private listeners = new Map<string, Set<Function>>();
  private reconnectTimeout: NodeJS.Timeout | null = null;
  private reconnectDelay = 1000;
  private maxReconnectDelay = 30000;

  constructor(
    serverUrl: string,
    roomname: string,
    doc: Y.Doc,
    options: WebSocketProviderOptions = {}
  ) {
    this.doc = doc;
    this.roomname = roomname;
    this.awareness = options.awareness || new Awareness(doc);

    // Build WebSocket URL with room parameter
    const url = new URL(serverUrl);
    url.searchParams.set('room', roomname);

    // Add additional params
    if (options.params) {
      Object.entries(options.params).forEach(([key, value]) => {
        url.searchParams.set(key, value);
      });
    }

    this.url = url.toString();

    // Setup document observers
    this.doc.on('update', this.handleDocUpdate);
    this.awareness.on('update', this.handleAwarenessUpdate);

    // Connect if requested
    if (options.connect !== false) {
      this.connect();
    }
  }

  /**
   * Connect to WebSocket server
   */
  public connect(): void {
    this.shouldConnect = true;
    if (this.wsconnected || this.wsconnecting) {
      return;
    }

    this.wsconnecting = true;
    this.emit('status', [{ status: 'connecting' }]);

    try {
      this.ws = new WebSocket(this.url);
      this.ws.binaryType = 'arraybuffer';

      this.ws.onopen = () => {
        this.wsconnecting = false;
        this.wsconnected = true;
        this.reconnectDelay = 1000;

        this.emit('status', [{ status: 'connected' }]);

        // Send sync step 1
        const encoder = encoding.createEncoder();
        encoding.writeVarUint(encoder, MESSAGE_SYNC);
        syncProtocol.writeSyncStep1(encoder, this.doc);
        this.send(encoding.toUint8Array(encoder));

        // Send awareness state
        if (this.awareness.getLocalState() !== null) {
          const awarenessEncoder = encoding.createEncoder();
          encoding.writeVarUint(awarenessEncoder, MESSAGE_AWARENESS);
          encoding.writeVarUint8Array(
            awarenessEncoder,
            awarenessProtocol.encodeAwarenessUpdate(this.awareness, [this.doc.clientID])
          );
          this.send(encoding.toUint8Array(awarenessEncoder));
        }
      };

      this.ws.onmessage = (event) => {
        this.handleMessage(new Uint8Array(event.data));
      };

      this.ws.onerror = (error) => {
        // Log locally if needed, but not user-facing debug
      };

      this.ws.onclose = (event) => {
        this.handleDisconnect();
      };
    } catch (error) {
      console.error('Failed to create WebSocket:', error);
      this.wsconnecting = false;
      this.scheduleReconnect();
    }
  }

  /**
   * Disconnect from WebSocket server
   */
  public disconnect(): void {
    this.shouldConnect = false;
    if (this.reconnectTimeout) {
      clearTimeout(this.reconnectTimeout);
      this.reconnectTimeout = null;
    }
    if (this.ws) {
      this.ws.close();
      this.ws = null;
    }
  }

  /**
   * Destroy provider and cleanup
   */
  public destroy(): void {
    this.disconnect();
    this.doc.off('update', this.handleDocUpdate);
    this.awareness.off('update', this.handleAwarenessUpdate);
    this.awareness.destroy();
  }

  /**
   * Send message to server
   */
  private send(message: Uint8Array): void {
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(message);
    }
  }

  /**
   * Handle incoming message from server
   */
  private handleMessage = (message: Uint8Array): void => {
    const decoder = decoding.createDecoder(message);
    const messageType = decoding.readVarUint(decoder);

    switch (messageType) {
      case MESSAGE_SYNC:
        const encoder = encoding.createEncoder();
        encoding.writeVarUint(encoder, MESSAGE_SYNC);
        const syncMessageType = syncProtocol.readSyncMessage(decoder, encoder, this.doc, this);

        if (encoding.length(encoder) > 1) {
          this.send(encoding.toUint8Array(encoder));
        }

        if (!this.synced && syncMessageType === syncProtocol.messageYjsSyncStep2) {
          this.synced = true;
          this.emit('synced', [true]);
          this.emit('sync', [true]);
        }
        break;

      case MESSAGE_AWARENESS:
        awarenessProtocol.applyAwarenessUpdate(
          this.awareness,
          decoding.readVarUint8Array(decoder),
          this
        );
        break;
    }
  };

  /**
   * Handle document update
   */
  private handleDocUpdate = (update: Uint8Array, origin: any): void => {
    if (origin !== this) {
      const encoder = encoding.createEncoder();
      encoding.writeVarUint(encoder, MESSAGE_SYNC);
      syncProtocol.writeUpdate(encoder, update);
      this.send(encoding.toUint8Array(encoder));
    }
  };

  /**
   * Handle awareness update
   */
  private handleAwarenessUpdate = (
    { added, updated, removed }: any,
    origin: any
  ): void => {
    const changedClients = added.concat(updated).concat(removed);
    const encoder = encoding.createEncoder();
    encoding.writeVarUint(encoder, MESSAGE_AWARENESS);
    encoding.writeVarUint8Array(
      encoder,
      awarenessProtocol.encodeAwarenessUpdate(this.awareness, changedClients)
    );
    this.send(encoding.toUint8Array(encoder));
  };

  /**
   * Handle disconnect
   */
  private handleDisconnect(): void {
    this.wsconnected = false;
    this.wsconnecting = false;
    this.synced = false;

    this.emit('status', [{ status: 'disconnected' }]);
    this.emit('synced', [false]);
    this.emit('sync', [false]);

    if (this.shouldConnect) {
      this.scheduleReconnect();
    }
  }

  /**
   * Schedule reconnect with exponential backoff
   */
  private scheduleReconnect(): void {
    if (this.reconnectTimeout) {
      clearTimeout(this.reconnectTimeout);
    }

    this.reconnectTimeout = setTimeout(() => {
      this.connect();
    }, this.reconnectDelay);

    // Exponential backoff
    this.reconnectDelay = Math.min(this.reconnectDelay * 2, this.maxReconnectDelay);
  }

  /**
   * Event emitter methods
   */
  public on(event: string, callback: Function): void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set());
    }
    this.listeners.get(event)!.add(callback);
  }

  public off(event: string, callback: Function): void {
    const callbacks = this.listeners.get(event);
    if (callbacks) {
      callbacks.delete(callback);
    }
  }

  private emit(event: string, args: any[]): void {
    const callbacks = this.listeners.get(event);
    if (callbacks) {
      callbacks.forEach((callback) => callback(...args));
    }
  }
}

import { useEffect, useRef, useState, useCallback } from 'react';
import { Awareness } from 'y-protocols/awareness';
import * as Y from 'yjs';

import { WebSocketProvider } from './WebSocketProvider';

import type { Node, Edge } from 'reactflow';

export interface CollabUser {
  userId: string;
  displayName: string;
  email: string;
  role: string;
  color: string;
  cursor?: { x: number; y: number };
  selectedNodeId?: string | null;
  mode?: 'easy' | 'advanced';
  activeBlockId?: string | null;
}

export interface CollabClientState {
  connected: boolean;
  synced: boolean;
  users: CollabUser[];

  error: string | null;
  user: {
    id: string;
    name: string;
    color: string;
    email?: string;
  };
}

export interface CollabClientActions {
  updateNodes: (nodes: Node[]) => void;
  updateEdges: (edges: Edge[]) => void;
  updateCursor: (x: number, y: number) => void;
  updateSelectedNode: (nodeId: string | null) => void;
  updateMode: (mode: 'easy' | 'advanced') => void;
  updateActiveBlock: (blockId: string | null) => void;
  disconnect: () => void;
}

interface UseCollabClientOptions {
  workflowId: string;
  tenantId: string;
  token: string;
  onNodesChange: (nodes: Node[]) => void;
  onEdgesChange: (edges: Edge[]) => void;
  enabled?: boolean;
  user: {
    id: string;
    name: string;
    color: string;
    email?: string;
  };
}

/**
 * React hook for real-time collaboration on workflow graphs
 */
export function useCollabClient(
  options: UseCollabClientOptions
): CollabClientState & CollabClientActions {
  const {
    workflowId,
    tenantId,
    token,
    onNodesChange,
    onEdgesChange,
    enabled = true,
    user,
  } = options;

  const [state, setState] = useState<CollabClientState>({
    connected: false,
    synced: false,
    users: [],

    error: null,
    user,
  });

  const docRef = useRef<Y.Doc | null>(null);
  const providerRef = useRef<WebSocketProvider | null>(null);
  const awarenessRef = useRef<Awareness | null>(null);
  const isLocalUpdateRef = useRef(false);

  // Room key format: tenant:{tenantId}:workflow:{workflowId}
  const roomKey = `tenant:${tenantId}:workflow:${workflowId}`;

  // Initialize Yjs document and WebSocket provider
  useEffect(() => {
    if (!enabled || !token) {return;}

    const doc = new Y.Doc();
    docRef.current = doc;

    // Get WebSocket URL
    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    // Use the same host/port as the application (no separate port needed)
    const wsUrl = `${protocol}//${window.location.host}/collab`;

    // Create WebSocket provider
    const provider = new WebSocketProvider(wsUrl, roomKey, doc, {
      params: { token },
      awareness: new Awareness(doc),
    });

    providerRef.current = provider;
    awarenessRef.current = provider.awareness;

    // Setup Yjs document structure
    const yGraph = doc.getMap('yGraph');
    if (!yGraph.has('nodes')) {
      yGraph.set('nodes', new Y.Array());
    }
    if (!yGraph.has('edges')) {
      yGraph.set('edges', new Y.Array());
    }

    // Initialize meta map
    // Initialize meta map
    doc.getMap('yMeta');

    // Initialize comments map
    // Initialize comments map
    doc.getMap('yComments');

    // Set local user state
    provider.awareness.setLocalStateField('user', {
      userId: user.id,
      displayName: user.name,
      color: user.color,
      email: user.email ?? '',
      role: 'editor', // Default role
      activeBlockId: null,
      mode: 'easy', // Default mode
      lastActive: Date.now()
    });

    // Connection event handlers

    // Connection event handlers
    provider.on('status', ({ status }: { status: string }) => {
      setState((prev) => ({
        ...prev,
        connected: status === 'connected',
        error: status === 'disconnected' ? 'Disconnected from server' : null,
      }));
    });

    provider.on('sync', (isSynced: boolean) => {
      setState((prev) => ({ ...prev, synced: isSynced }));
    });

    // Observe changes from remote
    const yNodes = yGraph.get('nodes') as Y.Array<Y.Map<any>>;
    const yEdges = yGraph.get('edges') as Y.Array<Y.Map<any>>;

    const handleNodesChange = () => {
      if (isLocalUpdateRef.current) {return;}

      const nodes = yNodes.toArray().map((yNode) => {
        const node: any = {};
        yNode.forEach((value, key) => {
          node[key] = value;
        });
        return node;
      });

      onNodesChange(nodes);
    };

    const handleEdgesChange = () => {
      if (isLocalUpdateRef.current) {return;}

      const edges = yEdges.toArray().map((yEdge) => {
        const edge: any = {};
        yEdge.forEach((value, key) => {
          edge[key] = value;
        });
        return edge;
      });

      onEdgesChange(edges);
    };

    yNodes.observe(handleNodesChange);
    yEdges.observe(handleEdgesChange);

    // Observe awareness changes (other users)
    const handleAwarenessChange = () => {
      const states = Array.from(awarenessRef.current!.getStates().values());
      const usersMap = new Map();

      states.forEach((state: any) => {
        if (state.user) {
          // If user already exists, we could check timestamps to keep latest, 
          // but for now simple dedupe by ID is sufficient.
          // We overwriting ensures we have *a* version of the user.
          usersMap.set(state.user.id || state.user.userId, state.user);
        }
      });

      const users = Array.from(usersMap.values());
      setState((prev) => ({ ...prev, users }));
    };

    awarenessRef.current.on('change', handleAwarenessChange);

    // Cleanup
    return () => {
      yNodes.unobserve(handleNodesChange);
      yEdges.unobserve(handleEdgesChange);
      awarenessRef.current?.off('change', handleAwarenessChange);
      provider.destroy();
      doc.destroy();
    };
    // Only depend on core connection parameters - callbacks are set up once
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enabled, workflowId, tenantId, token]);

  // Update nodes in Yjs document
  const updateNodes = useCallback((nodes: Node[]) => {
    if (!docRef.current) {return;}

    const yGraph = docRef.current.getMap('yGraph');
    const yNodes = yGraph.get('nodes') as Y.Array<Y.Map<any>>;

    isLocalUpdateRef.current = true;

    docRef.current.transact(() => {
      // Clear and rebuild array
      yNodes.delete(0, yNodes.length);

      nodes.forEach((node) => {
        const yNode = new Y.Map();
        Object.entries(node).forEach(([key, value]) => {
          // Serialize complex objects as JSON
          if (typeof value === 'object' && value !== null) {
            yNode.set(key, JSON.parse(JSON.stringify(value)));
          } else {
            yNode.set(key, value);
          }
        });
        yNodes.push([yNode]);
      });
    });

    // Reset flag after a short delay
    setTimeout(() => {
      isLocalUpdateRef.current = false;
    }, 50);
  }, []);

  // Update edges in Yjs document
  const updateEdges = useCallback((edges: Edge[]) => {
    if (!docRef.current) {return;}

    const yGraph = docRef.current.getMap('yGraph');
    const yEdges = yGraph.get('edges') as Y.Array<Y.Map<any>>;

    isLocalUpdateRef.current = true;

    docRef.current.transact(() => {
      // Clear and rebuild array
      yEdges.delete(0, yEdges.length);

      edges.forEach((edge) => {
        const yEdge = new Y.Map();
        Object.entries(edge).forEach(([key, value]) => {
          // Serialize complex objects as JSON
          if (typeof value === 'object' && value !== null) {
            yEdge.set(key, JSON.parse(JSON.stringify(value)));
          } else {
            yEdge.set(key, value);
          }
        });
        yEdges.push([yEdge]);
      });
    });

    // Reset flag after a short delay
    setTimeout(() => {
      isLocalUpdateRef.current = false;
    }, 50);
  }, []);

  // Update cursor position
  const updateCursor = useCallback((x: number, y: number) => {
    if (!awarenessRef.current) {return;}

    const currentState = awarenessRef.current.getLocalState();
    if (currentState?.user) {
      awarenessRef.current.setLocalStateField('user', {
        ...currentState.user,
        cursor: { x, y },
        lastActive: Date.now(),
      });
    }
  }, []);

  // Update selected node
  const updateSelectedNode = useCallback((nodeId: string | null) => {
    if (!awarenessRef.current) {return;}

    const currentState = awarenessRef.current.getLocalState();
    if (currentState?.user) {
      awarenessRef.current.setLocalStateField('user', {
        ...currentState.user,
        selectedNodeId: nodeId,
        lastActive: Date.now(),
      });
    }
  }, []);

  // Update user mode
  const updateMode = useCallback((mode: 'easy' | 'advanced') => {
    if (!awarenessRef.current) {return;}

    const currentState = awarenessRef.current.getLocalState();
    if (currentState?.user) {
      awarenessRef.current.setLocalStateField('user', {
        ...currentState.user,
        mode,
        lastActive: Date.now(),
      });
    }
  }, []);

  // Update active block (locking/presence)
  const updateActiveBlock = useCallback((blockId: string | null) => {
    if (!awarenessRef.current) {return;}

    const currentState = awarenessRef.current.getLocalState();
    if (currentState?.user) {
      // Optimize: Don't update if same
      if (currentState.user.activeBlockId === blockId) {return;}

      awarenessRef.current.setLocalStateField('user', {
        ...currentState.user,
        activeBlockId: blockId,
        lastActive: Date.now(),
      });
    }
  }, []);

  // Disconnect
  const disconnect = useCallback(() => {
    if (providerRef.current) {
      providerRef.current.destroy();
    }
    if (docRef.current) {
      docRef.current.destroy();
    }
  }, []);

  return {
    ...state,
    updateNodes,
    updateEdges,
    updateCursor,
    updateSelectedNode,
    updateMode,
    updateActiveBlock,
    disconnect,
  };
}

import { useState, useEffect, useCallback, useRef } from 'react';
import * as Y from 'yjs';

export interface Comment {
  id: string;
  userId: string;
  userName: string;
  text: string;
  timestamp: number;
}

interface UseCommentsOptions {
  doc: Y.Doc | null;
  nodeId: string | null;
}

/**
 * Hook for managing node-level comments
 */
export function useComments({ doc, nodeId }: UseCommentsOptions) {
  const [comments, setComments] = useState<Comment[]>([]);
  const yCommentsMapRef = useRef<Y.Map<any> | null>(null);

  // Load comments when node changes
  useEffect(() => {
    if (!doc || !nodeId) {
      setComments([]);
      return;
    }

    const yComments = doc.getMap('yComments');
    yCommentsMapRef.current = yComments;

    const loadComments = () => {
      const nodeComments = yComments.get(nodeId);
      if (nodeComments && Array.isArray(nodeComments)) {
        setComments([...nodeComments]);
      } else {
        setComments([]);
      }
    };

    // Load initial comments
    loadComments();

    // Observe changes
    const observer = () => {
      loadComments();
    };

    yComments.observe(observer);

    return () => {
      yComments.unobserve(observer);
    };
  }, [doc, nodeId]);

  // Add comment
  const addComment = useCallback(
    (text: string, userId: string, userName: string) => {
      if (!doc || !nodeId) {return;}

      const yComments = doc.getMap('yComments');

      doc.transact(() => {
        const nodeComments = (yComments.get(nodeId) as Comment[] | undefined) ?? [];

        const newComment: Comment = {
          id: `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
          userId,
          userName,
          text,
          timestamp: Date.now(),
        };

        yComments.set(nodeId, [...nodeComments, newComment]);
      });
    },
    [doc, nodeId]
  );

  // Delete comment
  const deleteComment = useCallback(
    (commentId: string) => {
      if (!doc || !nodeId) {return;}

      const yComments = doc.getMap('yComments');

      doc.transact(() => {
        const nodeComments = (yComments.get(nodeId) as Comment[] | undefined) ?? [];
        const filtered = nodeComments.filter((c: Comment) => c.id !== commentId);
        yComments.set(nodeId, filtered);
      });
    },
    [doc, nodeId]
  );

  // Get comment count for a specific node
  const getCommentCount = useCallback(
    (targetNodeId: string): number => {
      if (!doc) {return 0;}

      const yComments = doc.getMap('yComments');
      const nodeComments = yComments.get(targetNodeId) as Comment[] | undefined;
      return nodeComments ? nodeComments.length : 0;
    },
    [doc]
  );

  return {
    comments,
    addComment,
    deleteComment,
    getCommentCount,
  };
}

import * as React from "react"

const MOBILE_BREAKPOINT = 768

export function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState<boolean | undefined>(undefined)

  React.useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`)
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    }
    mql.addEventListener("change", onChange)
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    return () => mql.removeEventListener("change", onChange)
  }, [])

  return !!isMobile
}

import { useQuery } from '@tanstack/react-query';

import type { DatavaultColumn } from '@/lib/types/datavault';

import { DATAVAULT_CONFIG } from '@shared/config';

import * as api from '../lib/api/datavault';

/**
 * Batch reference resolution hook
 * Efficiently fetches all reference values for a set of rows in a single request
 * Fixes N+1 query problem where each reference cell made individual API calls
 *
 * Before: 100 rows ├ù 3 reference columns = 300 API requests
 * After: 1 batch API request
 */
export function useBatchReferences(
  rows: Array<{ row: { id: string }; values: Record<string, any> }>,
  columns: DatavaultColumn[]
) {
  // Extract reference columns
  const referenceColumns = columns.filter(col => col.type === 'reference');

  // Build batch request from rows and reference columns
  const requests = referenceColumns
    .map(column => {
      if (!column.reference?.tableId) {return null;}

      // Collect all unique rowIds referenced in this column
      const rowIds = rows
        .map(row => row.values[column.id])
        .filter((val): val is string => typeof val === 'string' && val.length > 0);

      const uniqueRowIds = [...new Set(rowIds)];

      if (uniqueRowIds.length === 0) {return null;}

      return {
        tableId: column.reference.tableId,
        rowIds: uniqueRowIds,
        displayColumnSlug: column.reference.displayColumnSlug || undefined,
      };
    })
    .filter((req): req is NonNullable<typeof req> => req !== null);

  return useQuery({
    queryKey: ['batchReferences', requests],
    queryFn: () => {
      if (requests.length === 0) {
        return Promise.resolve({});
      }
      return api.batchResolveReferences(requests);
    },
    enabled: requests.length > 0,
    staleTime: DATAVAULT_CONFIG.REFERENCE_CACHE_TIME,
  });
}

/**
 * Get reference display value from batch resolution result
 */
export function getReferenceDisplayValue(
  rowId: string | undefined | null,
  batchResult: Record<string, { displayValue: string; row: any }> | undefined
): { displayValue: string; isLoading: boolean; isError: boolean } {
  if (!rowId) {
    return { displayValue: 'ΓÇö', isLoading: false, isError: false };
  }

  if (!batchResult) {
    return { displayValue: 'Loading...', isLoading: true, isError: false };
  }

  const result = batchResult[rowId];
  if (!result) {
    return { displayValue: 'Not found', isLoading: false, isError: true };
  }

  return { displayValue: result.displayValue, isLoading: false, isError: false };
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';

import type {
  TenantBranding,
  TenantDomain,
  GetBrandingResponse,
  UpdateBrandingRequest,
  UpdateBrandingResponse,
  GetDomainsResponse,
  CreateDomainRequest,
  CreateDomainResponse,
  DeleteDomainResponse,
} from '@shared/types/branding';

/**
 * Stage 17: Branding API Hooks
 *
 * React Query hooks for managing tenant branding and custom domains.
 */

// =====================================================================
// BRANDING HOOKS
// =====================================================================

/**
 * Fetch tenant branding configuration
 */
export function useTenantBranding(tenantId: string | undefined) {
  return useQuery({
    queryKey: ['tenants', tenantId, 'branding'],
    queryFn: async (): Promise<TenantBranding | null> => {
      if (!tenantId) {throw new Error('Tenant ID is required');}

      const response = await fetch(`/api/tenants/${tenantId}/branding`, {
        credentials: 'include',
      });

      if (!response.ok) {
        throw new Error('Failed to fetch tenant branding');
      }

      const data: GetBrandingResponse = await response.json();
      return data.branding;
    },
    enabled: !!tenantId,
  });
}

/**
 * Update tenant branding configuration
 */
export function useUpdateTenantBranding(tenantId: string) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (branding: Partial<TenantBranding>): Promise<TenantBranding> => {
      const response = await fetch(`/api/tenants/${tenantId}/branding`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify(branding),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.message || 'Failed to update branding');
      }

      const data: UpdateBrandingResponse = await response.json();
      return data.branding;
    },
    onSuccess: () => {
      // Invalidate branding query to refetch
      queryClient.invalidateQueries({ queryKey: ['tenants', tenantId, 'branding'] });
    },
  });
}

// =====================================================================
// DOMAIN HOOKS
// =====================================================================

/**
 * Fetch tenant domains
 */
export function useTenantDomains(tenantId: string | undefined) {
  return useQuery({
    queryKey: ['tenants', tenantId, 'domains'],
    queryFn: async (): Promise<TenantDomain[]> => {
