    },
  });
}

/**
 * Custom hook for managing Choice block configuration state
 * Handles config parsing, migrations, and state management
 */

import { useState, useEffect } from 'react';

import type { ApiStep } from '@/lib/vault-api';

import type {
    ChoiceAdvancedConfig,
    ChoiceOption,
    LegacyMultipleChoiceConfig,
    LegacyRadioConfig,
    DynamicOptionsConfig
} from '@/../../shared/types/stepConfigs';

export interface ChoiceCardState {
    display: "radio" | "dropdown" | "multiple";
    allowMultiple: boolean;
    searchable: boolean;
    staticOptions: ChoiceOption[];
    dynamicOptions: Extract<DynamicOptionsConfig, { type: 'list' }>;
}

interface UseChoiceConfigResult {
    localConfig: ChoiceCardState | null;
    setLocalConfig: (config: ChoiceCardState) => void;
    sourceMode: "static" | "dynamic";
    setSourceMode: (mode: "static" | "dynamic") => void;
    isAdvancedMode: boolean;
}

const createEmptyDynamicConfig = (): Extract<DynamicOptionsConfig, { type: 'list' }> => ({
    type: 'list',
    listVariable: '',
    labelPath: '',
    valuePath: '',
    labelTemplate: '',
    groupByPath: '',
    enableSearch: false,
    includeBlankOption: false,
    blankLabel: '',
    transform: {
        filters: undefined,
        sort: undefined,
        limit: undefined,
        offset: undefined,
        dedupe: undefined,
        select: undefined
    }
});

/**
 * Parse and migrate choice config from various formats to unified state
 */
function parseChoiceConfig(step: ApiStep): {
    config: ChoiceCardState;
    mode: "static" | "dynamic";
    isAdvanced: boolean;
} {
    const isAdvanced = step.type === "choice";

    if (isAdvanced) {
        const config = step.config as ChoiceAdvancedConfig | undefined;
        const rawOptions = config?.options;

        let mode: "static" | "dynamic" = "static";
        let staticOptions: ChoiceOption[] = [];
        let dynamicOptions: Extract<DynamicOptionsConfig, { type: 'list' }> = createEmptyDynamicConfig();

        if (rawOptions && typeof rawOptions === 'object' && 'type' in rawOptions) {
            // Dynamic Config
            const dynConfig = rawOptions;
            if (dynConfig.type === 'static') {
                staticOptions = dynConfig.options ?? [];
            } else if (dynConfig.type === 'list') {
                mode = "dynamic";
                // Migrate old format to new format
                dynamicOptions = {
                    type: 'list',
                    listVariable: dynConfig.listVariable ?? '',
                    labelPath: ((dynConfig as unknown as { labelPath?: string; labelColumnId?: string }).labelPath ||
                        (dynConfig as unknown as { labelPath?: string; labelColumnId?: string }).labelColumnId) ?? '',
                    valuePath: ((dynConfig as unknown as { valuePath?: string; valueColumnId?: string }).valuePath ||
                        (dynConfig as unknown as { valuePath?: string; valueColumnId?: string }).valueColumnId) ?? '',
                    labelTemplate: dynConfig.labelTemplate,
                    groupByPath: dynConfig.groupByPath,
                    enableSearch: dynConfig.enableSearch,
                    includeBlankOption: dynConfig.includeBlankOption,
                    blankLabel: dynConfig.blankLabel,
                    transform: dynConfig.transform || createEmptyDynamicConfig().transform
                };
            }
        } else if (Array.isArray(rawOptions)) {
            staticOptions = rawOptions;
        }

        return {
            config: {
                display: config?.display || "radio",
                allowMultiple: config?.allowMultiple ?? false,
                searchable: config?.searchable ?? false,
                staticOptions,
                dynamicOptions
            },
            mode,
            isAdvanced: true
        };
    } else {
        // Easy mode legacy conversion
        const config = step.config as (LegacyMultipleChoiceConfig | LegacyRadioConfig) | undefined;
        const legacyOptions = config?.options ?? [];
        const options: ChoiceOption[] = Array.isArray(legacyOptions)
            ? legacyOptions.map((opt: string | { id?: string; label?: string; alias?: string }, idx: number) => ({
                id: typeof opt === 'object' && opt.id ? opt.id : `opt${idx + 1}`,
                label: typeof opt === 'string' ? opt : (opt.label || String(opt)),
                alias: typeof opt === 'string' ? `option${idx + 1}` : (opt.alias || opt.id || `option${idx + 1}`),
            }))
            : [];

        return {
            config: {
                display: step.type === "multiple_choice" ? "multiple" : "radio",
                allowMultiple: step.type === "multiple_choice",
                searchable: false,
                staticOptions: options,
                dynamicOptions: createEmptyDynamicConfig()
            },
            mode: "static",
            isAdvanced: false
        };
    }
}

/**
 * Hook for managing Choice block configuration
 */
export function useChoiceConfig(step: ApiStep): UseChoiceConfigResult {
    const [localConfig, setLocalConfig] = useState<ChoiceCardState | null>(null);
    const [sourceMode, setSourceMode] = useState<"static" | "dynamic">("static");
    const isAdvancedMode = step.type === "choice";

    // Parse config on mount or when step changes
    useEffect(() => {
        const { config, mode } = parseChoiceConfig(step);
        setLocalConfig(config);
        setSourceMode(mode);
    }, [step.config, step.type]);

    return {
        localConfig,
        setLocalConfig,
        sourceMode,
        setSourceMode,
        isAdvancedMode
    };
}

import confetti from "canvas-confetti";

import { useUserPreferences } from "./useUserPreferences";

export type ConfettiPreset = "success" | "ai" | "party" | "gentle";

interface PresetConfig {
  colors: string[];
  spread: number;
  scalar: number;
}

const PRESETS: Record<ConfettiPreset, PresetConfig> = {
  success: {
    colors: ["#34d399", "#10b981", "#6ee7b7"],
    spread: 70,
    scalar: 1.0
  },
  ai: {
    colors: ["#818cf8", "#c084fc", "#f9a8d4"],
    spread: 80,
    scalar: 1.1
  },
  party: {
    colors: ["#facc15", "#f472b6", "#60a5fa", "#4ade80"],
    spread: 100,
    scalar: 1.2
  },
  gentle: {
    colors: ["#a5f3fc", "#d9f99d", "#fde68a"],
    spread: 60,
    scalar: 0.8
  },
};

// Detect mobile devices for performance optimization
const isMobile = () => {
  return /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(
    navigator.userAgent
  ) || window.innerWidth < 768;
};

/**
 * Universal confetti hook for celebration moments across the app.
 * Automatically respects user preferences for celebration effects.
 *
 * @example
 * const { fire, cascade } = useConfetti();
 *
 * // Single burst
 * fire("success");
 *
 * // Continuous cascade (1 second)
 * cascade("party");
 */
export function useConfetti() {
  const { prefs } = useUserPreferences();
  const celebrationEffectsEnabled = prefs?.celebrationEffects ?? true;

  // Disable in test environments
  if (import.meta.env.MODE === "test") {
    return {
      fire: () => {},
      cascade: () => {}
    };
  }

  // Disable if user has turned off celebration effects
  if (!celebrationEffectsEnabled) {
    return {
      fire: () => {},
      cascade: () => {}
    };
  }

  /**
   * Fire a single confetti burst with the specified preset.
   *
   * @param preset - The confetti style preset to use
   * @param opts - Additional canvas-confetti options to override defaults
   */
  function fire(preset: ConfettiPreset = "success", opts = {}) {
    const config = PRESETS[preset] || PRESETS.success;
    const mobile = isMobile();

    confetti({
      particleCount: mobile ? 60 : 120, // Reduce particles on mobile
      origin: { y: 0.6 },
      ticks: 200,
      gravity: 0.8,
      ...config,
      ...opts,
    });
  }

  /**
   * Fire a continuous cascade of confetti from both sides of the screen.
   * Runs for 1 second with confetti shooting from left and right edges.
   *
   * @param preset - The confetti style preset to use
   */
  function cascade(preset: ConfettiPreset = "party") {
    const config = PRESETS[preset];
    const mobile = isMobile();
    const particleCount = mobile ? 3 : 5;
    const duration = 1000; // 1 second
    const end = Date.now() + duration;

    const frame = () => {
      // Left side
      confetti({
        ...config,
        particleCount,
        angle: 60,
        spread: 55,
        origin: { x: 0 },
      });

      // Right side
      confetti({
        ...config,
        particleCount,
        angle: 120,
        spread: 55,
        origin: { x: 1 },
      });

      if (Date.now() < end) {
        requestAnimationFrame(frame);
      }
    };

    frame();
  }

  return { fire, cascade };
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';

import * as api from '../lib/api/datavault';

import type {
  DatavaultDatabase,
  CreateDatabaseInput,
  UpdateDatabaseInput,
  DatavaultScopeType,
} from '../lib/types/datavault';

// ============================================================================
// Query Keys
// ============================================================================

export const datavaultKeys = {
  all: ['datavault'] as const,
  databases: () => [...datavaultKeys.all, 'databases'] as const,
  database: (id: string) => [...datavaultKeys.databases(), id] as const,
  databaseTables: (id: string) => [...datavaultKeys.database(id), 'tables'] as const,
  databasesByScope: (scopeType?: DatavaultScopeType, scopeId?: string) =>
    [...datavaultKeys.databases(), 'scope', scopeType, scopeId] as const,
};

// ============================================================================
// Database Queries
// ============================================================================

export function useDatabases(params?: {
  scopeType?: DatavaultScopeType;
  scopeId?: string;
}) {
  return useQuery({
    queryKey: params?.scopeType
      ? datavaultKeys.databasesByScope(params.scopeType, params.scopeId)
      : datavaultKeys.databases(),
    queryFn: () => api.getDatabases(params),
  });
}

export function useDatabase(id: string | undefined) {
  return useQuery({
    queryKey: id ? datavaultKeys.database(id) : ['datavault', 'databases', 'null'],
    queryFn: () => {
      if (!id) {throw new Error('Database ID is required');}
      return api.getDatabaseById(id);
    },
    enabled: !!id,
  });
}

export function useDatabaseTables(databaseId: string | undefined) {
  return useQuery({
    queryKey: databaseId
      ? datavaultKeys.databaseTables(databaseId)
      : ['datavault', 'databases', 'null', 'tables'],
    queryFn: () => {
      if (!databaseId) {throw new Error('Database ID is required');}
      return api.getTablesInDatabase(databaseId);
    },
    enabled: !!databaseId,
  });
}

// ============================================================================
// Database Mutations
// ============================================================================

export function useCreateDatabase() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (input: CreateDatabaseInput) => api.createDatabase(input),
    onSuccess: () => {
      // Invalidate all database queries
      queryClient.invalidateQueries({ queryKey: datavaultKeys.databases() });
    },
  });
}

export function useUpdateDatabase() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ id, input }: { id: string; input: UpdateDatabaseInput }) =>
      api.updateDatabase(id, input),
    onSuccess: (data) => {
      // Invalidate the specific database and all database lists
      queryClient.invalidateQueries({ queryKey: datavaultKeys.database(data.id) });
      queryClient.invalidateQueries({ queryKey: datavaultKeys.databases() });
    },
  });
}

export function useDeleteDatabase() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (id: string) => api.deleteDatabase(id),
    onSuccess: (_, id) => {
      // Remove the specific database from cache
      queryClient.removeQueries({ queryKey: datavaultKeys.database(id) });
      // Invalidate all database lists
      queryClient.invalidateQueries({ queryKey: datavaultKeys.databases() });
      // Invalidate tables list since deleted database's tables will be orphaned
      queryClient.invalidateQueries({ queryKey: ['datavault', 'tables'] });
    },
  });
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';

import * as api from '../lib/api/datavault';

import { datavaultKeys } from './useDatavaultDatabases';

import type {
  DatavaultTable,
  CreateTableInput,
  UpdateTableInput,
  MoveTableInput,
  TableSchema,
} from '../lib/types/datavault';

// ============================================================================
// Query Keys
// ============================================================================

export const tableKeys = {
  all: ['datavault', 'tables'] as const,
  lists: () => [...tableKeys.all, 'list'] as const,
  list: () => [...tableKeys.lists()] as const,
  table: (id: string) => [...tableKeys.all, id] as const,
  schema: (id: string) => [...tableKeys.table(id), 'schema'] as const,
  columns: (id: string) => [...tableKeys.table(id), 'columns'] as const,
  rows: (id: string) => [...tableKeys.table(id), 'rows'] as const,
  rowsPage: (id: string, offset: number) => [...tableKeys.rows(id), 'page', offset] as const,
};

// ============================================================================
// Table Queries
// ============================================================================

export function useTables() {
  return useQuery({
    queryKey: tableKeys.list(),
    queryFn: () => api.getTables(),
  });
}

export function useTable(id: string | undefined) {
  return useQuery({
    queryKey: id ? tableKeys.table(id) : ['datavault', 'tables', 'null'],
    queryFn: () => {
      if (!id) {throw new Error('Table ID is required');}
      return api.getTableById(id);
    },
    enabled: !!id,
  });
}

export function useTableSchema(tableId: string | undefined) {
  return useQuery({
    queryKey: tableId ? tableKeys.schema(tableId) : ['datavault', 'tables', 'null', 'schema'],
    queryFn: () => {
      if (!tableId) {throw new Error('Table ID is required');}
      return api.getTableSchema(tableId);
    },
    enabled: !!tableId,
  });
}

// ============================================================================
// Table Mutations
// ============================================================================

export function useCreateTable() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (input: CreateTableInput) => api.createTable(input),
    onSuccess: (data) => {
      // Invalidate tables list
      queryClient.invalidateQueries({ queryKey: tableKeys.lists() });

      // If table was created in a database, invalidate that database's tables
      if (data.databaseId) {
        queryClient.invalidateQueries({
          queryKey: datavaultKeys.databaseTables(data.databaseId),
        });
        // Also invalidate the database itself to update table count
        queryClient.invalidateQueries({
          queryKey: datavaultKeys.database(data.databaseId),
        });
      }
    },
  });
}

export function useUpdateTable() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ id, input }: { id: string; input: UpdateTableInput }) =>
      api.updateTable(id, input),
    onSuccess: (data) => {
      // Update the specific table
      queryClient.invalidateQueries({ queryKey: tableKeys.table(data.id) });
      // Invalidate tables list
      queryClient.invalidateQueries({ queryKey: tableKeys.lists() });

      // Invalidate database's tables if table is in a database
      if (data.databaseId) {
        queryClient.invalidateQueries({
          queryKey: datavaultKeys.databaseTables(data.databaseId),
        });
      }
    },
  });
}

export function useDeleteTable() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (id: string) => api.deleteTable(id),
    onSuccess: (_, id) => {
      // Remove the specific table from cache
      queryClient.removeQueries({ queryKey: tableKeys.table(id) });
      // Invalidate tables list
      queryClient.invalidateQueries({ queryKey: tableKeys.lists() });
      // Invalidate all database queries (to update table counts)
      queryClient.invalidateQueries({ queryKey: datavaultKeys.databases() });
    },
  });
}

export function useMoveTable() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ tableId, input }: { tableId: string; input: MoveTableInput }) =>
      api.moveTable(tableId, input),
    onSuccess: (data, variables) => {
      // Update the specific table
      queryClient.invalidateQueries({ queryKey: tableKeys.table(data.id) });
      // Invalidate tables list
      queryClient.invalidateQueries({ queryKey: tableKeys.lists() });

      // Invalidate source database if table was in a database before
      // (We'd need to track the old databaseId, but invalidating all is safer)
      queryClient.invalidateQueries({ queryKey: datavaultKeys.databases() });

      // Invalidate target database
      if (variables.input.databaseId) {
        queryClient.invalidateQueries({
          queryKey: datavaultKeys.databaseTables(variables.input.databaseId),
        });
        queryClient.invalidateQueries({
          queryKey: datavaultKeys.database(variables.input.databaseId),
        });
      }
    },
  });
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";

import { useToast } from "@/hooks/use-toast";
import { isUnauthorizedError } from "@/lib/authUtils";
import { apiRequest } from "@/lib/queryClient";

export interface RecipientGroup {
  id: string;
  creatorId: string;
  name: string;
  description: string | null;
  createdAt: string;
  updatedAt: string;
  memberCount?: number;
}

export interface GroupMember {
  recipientId: string;
  name: string;
  email: string;
  tags: string[] | null;
  addedAt: string;
}

export function useGroups() {
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Helper for error handling
  const handleMutationError = (error: any) => {
    if (isUnauthorizedError(error)) {
      toast({
        title: "Unauthorized",
        description: "You are logged out. Logging in again...",
        variant: "destructive",
      });
      setTimeout(() => {
        window.location.href = "/";
      }, 500);
      return;
    }
    toast({
      title: "Error",
      description: error.message,
      variant: "destructive",
    });
  };

  // Queries
  const {
    data: groups,
    isLoading: groupsLoading
  } = useQuery<RecipientGroup[]>({
    queryKey: ["/api/recipient-groups"],
    retry: false,
  });

  // Get members of a specific group
  const useGroupMembers = (groupId?: string) => {
    return useQuery<GroupMember[]>({
      queryKey: ["/api/recipient-groups", groupId, "members"],
      enabled: !!groupId,
      retry: false,
    });
  };

  // Mutations
  const createGroupMutation = useMutation({
    mutationFn: async (data: { name: string; description?: string }) => {
      return apiRequest("POST", "/api/recipient-groups", data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/recipient-groups"] });
      toast({
        title: "Success",
        description: "Group created successfully",
      });
    },
    onError: handleMutationError,
  });

  const updateGroupMutation = useMutation({
    mutationFn: async ({
      id,
      data
    }: {
      id: string;
      data: { name?: string; description?: string };
    }) => {
      return apiRequest("PUT", `/api/recipient-groups/${id}`, data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/recipient-groups"] });
      toast({
        title: "Success",
        description: "Group updated successfully",
      });
    },
    onError: handleMutationError,
  });

  const deleteGroupMutation = useMutation({
    mutationFn: async (id: string) => {
      return apiRequest("DELETE", `/api/recipient-groups/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/recipient-groups"] });
      toast({
        title: "Success",
        description: "Group deleted successfully",
      });
    },
    onError: handleMutationError,
  });

  const addMembersMutation = useMutation({
    mutationFn: async ({
      groupId,
      recipientIds
    }: {
      groupId: string;
      recipientIds: string[];
    }) => {
      return apiRequest("POST", `/api/recipient-groups/${groupId}/members`, {
        recipientIds
      });
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["/api/recipient-groups", variables.groupId, "members"] });
      queryClient.invalidateQueries({ queryKey: ["/api/recipient-groups"] });
      toast({
        title: "Success",
        description: "Members added to group successfully",
      });
    },
    onError: handleMutationError,
  });

  const removeMemberMutation = useMutation({
    mutationFn: async ({
      groupId,
      recipientId
    }: {
      groupId: string;
      recipientId: string;
    }) => {
      return apiRequest("DELETE", `/api/recipient-groups/${groupId}/members/${recipientId}`);
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["/api/recipient-groups", variables.groupId, "members"] });
      queryClient.invalidateQueries({ queryKey: ["/api/recipient-groups"] });
      toast({
        title: "Success",
        description: "Member removed from group successfully",
      });
    },
    onError: handleMutationError,
  });

  return {
    // Data
    groups,
    groupsLoading,

    // Queries
    useGroupMembers,

    // Mutations
    createGroup: createGroupMutation.mutate,
    createGroupPending: createGroupMutation.isPending,
    updateGroup: updateGroupMutation.mutate,
    updateGroupPending: updateGroupMutation.isPending,
    deleteGroup: deleteGroupMutation.mutate,
    deleteGroupPending: deleteGroupMutation.isPending,
    addMembers: addMembersMutation.mutate,
    addMembersPending: addMembersMutation.isPending,
    removeMember: removeMemberMutation.mutate,
    removeMemberPending: removeMemberMutation.isPending,
  };
}

/**
 * Infinite scroll hook for DataVault rows
 * Uses TanStack Query's useInfiniteQuery with offset-based pagination
 */

import { useInfiniteQuery } from "@tanstack/react-query";

import { datavaultAPI } from "@/lib/datavault-api";
import { datavaultQueryKeys } from "@/lib/datavault-hooks";

interface UseInfiniteRowsOptions {
  limit?: number;
}

export function useInfiniteRows(tableId: string, options: UseInfiniteRowsOptions = {}) {
  const limit = options.limit || 100;

  return useInfiniteQuery({
    queryKey: [...datavaultQueryKeys.tableRows(tableId), 'infinite', limit],
    queryFn: ({ pageParam = 0 }) =>
      datavaultAPI.listRows(tableId, { offset: pageParam, limit }),
    getNextPageParam: (lastPage, allPages) => {
      // Calculate total fetched across all pages
      const totalFetched = allPages.reduce((sum, page) => sum + page.rows.length, 0);
      // If there are more rows, return the offset for the next page
      if (totalFetched < lastPage.pagination.total) {
        return totalFetched; // This is the offset for next page
      }
      return undefined;
    },
    initialPageParam: 0,
  });
}

import { useQuery } from "@tanstack/react-query";

import type { ApiWorkflow, ApiRun, ApiStep } from "@/lib/vault-api";

interface IntakeData {
    values: Record<string, any>; // alias -> value
    sourceRunId?: string;
    sourceWorkflowTitle?: string;
    isLoading: boolean;
}

export function useIntakeRuntime(currentWorkflowId?: string): IntakeData {
    // Allow passing source run ID via URL
    const searchParams = new URLSearchParams(window.location.search);
    const sourceRunId = searchParams.get('intake_run_id') || searchParams.get('source_run_id');

    // 1. Fetch Current Workflow to get Intake Config
    const { data: currentWorkflow } = useQuery<ApiWorkflow>({
        queryKey: ['workflow', currentWorkflowId],
        queryFn: async () => {
            const res = await fetch(`/api/workflows/${currentWorkflowId}`);
            if (!res.ok) {throw new Error('Failed to fetch workflow');}
            return res.json();
        },
        enabled: !!currentWorkflowId,
        staleTime: 5 * 60 * 1000,
    });

    const upstreamWorkflowId = currentWorkflow?.intakeConfig?.upstreamWorkflowId;

    // 2. Fetch Upstream Workflow (for Aliases)
    const { data: upstreamWorkflow } = useQuery<ApiWorkflow & { steps?: ApiStep[] }>({
        queryKey: ['workflow-full', upstreamWorkflowId],
        queryFn: async () => {
            const res = await fetch(`/api/workflows/${upstreamWorkflowId}`);
            if (!res.ok) {throw new Error('Failed to fetch upstream workflow');}
            return res.json();
        },
        enabled: !!upstreamWorkflowId,
        staleTime: 5 * 60 * 1000,
    });

    // 3. Fetch Upstream Steps (to map StepID <-> Alias)
    // We need to fetch all steps of the upstream workflow
    // This is a bit expensive, simplified for now: assume we can get them or use an endpoint
    // Use existing "variables" endpoint or fetch sections->steps
    const { data: upstreamSteps } = useQuery<ApiStep[]>({
        queryKey: ['workflow-steps-flat', upstreamWorkflowId],
        queryFn: async () => {
            // Helper to fetch all steps (simplified compared to WorkflowRunner)
            // Ideally we have an endpoint /api/workflows/:id/variables or steps
            // Using sections endpoint as proxy
            const sectionsRes = await fetch(`/api/workflows/${upstreamWorkflowId}/sections`);
            if (!sectionsRes.ok) {return [];}
            const sections = await sectionsRes.json();

            const stepsPromises = sections.map((s: any) =>
                fetch(`/api/sections/${s.id}/steps`).then(r => r.json())
            );
            const stepsArrays = await Promise.all(stepsPromises);
            return stepsArrays.flat();
        },
        enabled: !!upstreamWorkflowId,
        staleTime: 5 * 60 * 1000,
    });

    // 4. Fetch Upstream Run Values
    const { data: upstreamRun } = useQuery<any>({
        queryKey: ['run', sourceRunId],
        queryFn: async () => {
            const res = await fetch(`/api/runs/${sourceRunId}`);
            if (!res.ok) {throw new Error('Failed to fetch upstream run');}
            return res.json().then(r => r.data); // result.data
        },
        enabled: !!sourceRunId && !!upstreamWorkflowId,
    });

    // 5. Resolve Values Map (Alias -> Value)
    const intakeValues: Record<string, any> = {};

    if (upstreamRun?.values && upstreamSteps) {
        upstreamRun.values.forEach((v: any) => {
            const step = upstreamSteps.find(s => s.id === v.stepId);
            if (step?.alias) {
                intakeValues[step.alias] = v.value;
            }
        });
    }

    return {
        values: intakeValues,
        sourceRunId: sourceRunId || undefined,
        sourceWorkflowTitle: upstreamWorkflow?.title,
        isLoading: !!upstreamWorkflowId && (!upstreamSteps || !upstreamRun) && !!sourceRunId
    };
}

/**
 * Intersection Observer hook for infinite scroll
 * Triggers callback when target element comes into view
 */

import { useEffect } from "react";

interface UseIntersectionObserverOptions {
  onIntersect: () => void;
  enabled?: boolean;
  root?: Element | null;
  rootMargin?: string;
  threshold?: number;
}

export function useIntersectionObserver(
  targetRef: React.RefObject<Element>,
  options: UseIntersectionObserverOptions
) {
  const { onIntersect, enabled = true, root = null, rootMargin = "0px", threshold = 1.0 } = options;

  useEffect(() => {
    if (!enabled || !targetRef.current) {return;}

    const observer = new IntersectionObserver(
      (entries) => {
        const [entry] = entries;
        if (entry.isIntersecting) {
          onIntersect();
        }
      },
      {
        root,
        rootMargin,
        threshold,
      }
    );

    observer.observe(targetRef.current);

    return () => {
      observer.disconnect();
    };
  }, [enabled, targetRef, onIntersect, root, rootMargin, threshold]);
}

import { useEffect, useCallback } from "react";

export interface KeyboardShortcut {
  key: string;
  ctrl?: boolean;
  shift?: boolean;
  alt?: boolean;
  description: string;
  action: () => void;
}

interface UseKeyboardShortcutsOptions {
  shortcuts: KeyboardShortcut[];
  enabled?: boolean;
}

/**
 * Hook for managing keyboard shortcuts in the survey builder
 * Supports Ctrl/Cmd modifiers and prevents conflicts with browser shortcuts
 */
export function useKeyboardShortcuts({
  shortcuts,
  enabled = true,
}: UseKeyboardShortcutsOptions) {
  const handleKeyDown = useCallback(
    (event: KeyboardEvent) => {
      if (!enabled) {return;}

      // Don't trigger shortcuts when typing in inputs, textareas, or contenteditable
      const target = event.target as HTMLElement;
      if (
        target.tagName === "INPUT" ||
        target.tagName === "TEXTAREA" ||
        target.isContentEditable
      ) {
        // Exception: Allow Ctrl+S even in inputs
        if (!(event.key === "s" && (event.ctrlKey || event.metaKey))) {
          return;
        }
      }

      for (const shortcut of shortcuts) {
        const ctrlPressed = event.ctrlKey || event.metaKey; // metaKey for Mac Cmd
        const shiftPressed = event.shiftKey;
        const altPressed = event.altKey;

        const keyMatches = event.key.toLowerCase() === shortcut.key.toLowerCase();
        const ctrlMatches = shortcut.ctrl ? ctrlPressed : !ctrlPressed;
        const shiftMatches = shortcut.shift ? shiftPressed : !shiftPressed;
        const altMatches = shortcut.alt ? altPressed : !altPressed;

        if (keyMatches && ctrlMatches && shiftMatches && altMatches) {
          event.preventDefault();
          event.stopPropagation();
          shortcut.action();
          break;
        }
      }
    },
    [shortcuts, enabled]
  );

  useEffect(() => {
    // MEMORY LEAK FIX: Always add/remove listener regardless of enabled flag
    // The enabled check is handled inside handleKeyDown callback
    // This prevents listeners from staying attached when enabled switches to false
    window.addEventListener("keydown", handleKeyDown);
    return () => {
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [handleKeyDown]); // Removed 'enabled' from deps since we always add/remove now
}

/**
 * Utility to get platform-specific modifier key name
 */
export function getModifierKey(): string {
  return navigator.platform.toLowerCase().includes("mac") ? "Γîÿ" : "Ctrl";
}

/**
 * Utility to format shortcut for display
 */
export function formatShortcut(shortcut: KeyboardShortcut): string {
  const parts: string[] = [];
  const modKey = getModifierKey();

  if (shortcut.ctrl) {parts.push(modKey);}
  if (shortcut.shift) {parts.push("Shift");}
  if (shortcut.alt) {parts.push("Alt");}
  parts.push(shortcut.key.toUpperCase());

  return parts.join(" + ");
}

/**
 * Custom hook for validating List Tools configuration
 * Handles timing checks and column validation
 */

import { useMemo } from 'react';

import { useTableColumns } from '@/hooks/useTableColumns';
import type { ApiBlock, ApiSection, ApiCollectionField } from '@/lib/vault-api';
import { useBlocks, useSections } from '@/lib/vault-hooks';

import type { ChoiceCardState } from './useChoiceConfig';

interface ValidationWarnings {
    timingWarning: string | null;
    labelColumnWarning: string | null;
    valueColumnWarning: string | null;
}

interface UseListToolsValidationParams {
    localConfig: ChoiceCardState | null;
    workflowId: string;
    sectionId: string;
}

/**
 * Hook for validating List Tools configuration
 */
export function useListToolsValidation({
    localConfig,
    workflowId,
    sectionId
}: UseListToolsValidationParams): ValidationWarnings & {
    sourceBlock: ApiBlock | null;
    sourceTableId: string | null;
    columns: any[]; // useTableColumns likely returns any specifically or a complex type we'll genericize later
    loadingColumns: boolean;
    blocks: ApiBlock[];
} {
    const { data: blocks = [] } = useBlocks(workflowId);
    const { data: sections = [] } = useSections(workflowId);

    // Find the source block
    const sourceBlock = useMemo(() => {
        if (!localConfig?.dynamicOptions.listVariable || !blocks || blocks.length === 0) {
            return null;
        }
        return blocks.find((b) =>
            b.config?.outputKey === localConfig.dynamicOptions.listVariable
        ) || null;
    }, [localConfig?.dynamicOptions.listVariable, blocks]);

    // Get table ID from source block
    const sourceTableId = useMemo(() => {
        if (!sourceBlock) {
            return null;
        }
        if (sourceBlock.type === 'read_table') {
            return sourceBlock.config?.tableId ?? null;
        }
        return null;
    }, [sourceBlock]);

    // Fetch columns
    const { data: columnsResponse, isLoading: loadingColumns } = useTableColumns(sourceTableId ?? undefined);
    const columns = Array.isArray(columnsResponse) ? columnsResponse : [];

    // Timing validation
    const timingWarning = useMemo(() => {
        if (!sourceBlock || !sections || sections.length === 0) {
            return null;
        }

        const blockPhase = sourceBlock.phase;
        const stepSection = sections.find((s) => s.id === sectionId);
        const blockSectionId = sourceBlock.sectionId;
        const blockSection = blockSectionId
            ? sections.find((s) => s.id === blockSectionId)
            : null;

        if (!stepSection) {
            return null;
        }

        // Safe phases
        if (blockPhase === 'onRunStart') {
            return null;
        }

        // Section-based checks
        if (blockPhase === 'onSectionEnter') {
            if (!blockSection) {
                return null; // Assume safe if global
            }

            if (blockSection.order > stepSection.order) {
                return "Read block runs in a later section.";
            }
            return null;
        }

        if (blockPhase === 'onSectionSubmit' || blockPhase === 'onNext') {
            if (!blockSection) {
                return "Block runs on submit but has no section?";
            }
            // Must be strictly previous section
            if (blockSection.order < stepSection.order) {
                return null;
            }
            return "Read block runs after the page is displayed (on Next/Submit).";
        }

        if (blockPhase === 'onRunComplete') {
            return "Read block runs at the end of the workflow.";
        }

        return null;
    }, [sourceBlock, sections, sectionId]);

    // Label column validation
    const labelColumnWarning = useMemo(() => {
        const id = localConfig?.dynamicOptions?.labelPath;
        if (!id || !sourceTableId || columns.length === 0) {
            return null;
        }
        if (id.includes('.')) {
            return null; // Dot notation assumed valid
        }
        if (!columns.find((c: { id?: string; name?: string }) => c.id === id || c.name === id)) {
            return "Selected column not found in source table.";
        }
        return null;
    }, [localConfig?.dynamicOptions?.labelPath, columns, sourceTableId]);

    // Value column validation
    const valueColumnWarning = useMemo(() => {
        const id = localConfig?.dynamicOptions?.valuePath;
        if (!id || !sourceTableId || columns.length === 0) {
            return null;
        }
        if (id.includes('.')) {
            return null;
        }
        if (!columns.find((c: { id?: string; name?: string }) => c.id === id || c.name === id)) {
            return "Selected column not found in source table.";
        }
        return null;
    }, [localConfig?.dynamicOptions?.valuePath, columns, sourceTableId]);

    return {
        timingWarning,
        labelColumnWarning,
        valueColumnWarning,
        sourceBlock,
        sourceTableId,
        columns,
        loadingColumns,
        blocks
    };
}

