export function useCreateColumn() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({
      tableId,
      input,
    }: {
      tableId: string;
      input: {
        name: string;
        type: string;
        required?: boolean;
        isPrimaryKey?: boolean;
        isUnique?: boolean;
        autoNumberStart?: number;
      };
    }) => api.createColumn(tableId, input),
    onSuccess: (data, variables) => {
      // Invalidate columns for this table
      queryClient.invalidateQueries({ queryKey: tableKeys.columns(variables.tableId) });
      // Invalidate schema (includes columns)
      queryClient.invalidateQueries({ queryKey: tableKeys.schema(variables.tableId) });
    },
  });
}

export function useUpdateColumn() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({
      columnId,
      tableId,
      input,
    }: {
      columnId: string;
      tableId: string;
      input: {
        name?: string;
        type?: string;
        required?: boolean;
        isPrimaryKey?: boolean;
        isUnique?: boolean;
      };
    }) => api.updateColumn(columnId, input),
    onSuccess: (data, variables) => {
      // Invalidate columns for this table
      queryClient.invalidateQueries({ queryKey: tableKeys.columns(variables.tableId) });
      // Invalidate schema
      queryClient.invalidateQueries({ queryKey: tableKeys.schema(variables.tableId) });
    },
  });
}

export function useDeleteColumn() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ columnId, tableId }: { columnId: string; tableId: string }) =>
      api.deleteColumn(columnId),
    onSuccess: (_, variables) => {
      // Invalidate columns for this table
      queryClient.invalidateQueries({ queryKey: tableKeys.columns(variables.tableId) });
      // Invalidate schema
      queryClient.invalidateQueries({ queryKey: tableKeys.schema(variables.tableId) });
      // Invalidate rows (since column data is removed)
      queryClient.invalidateQueries({ queryKey: tableKeys.rows(variables.tableId) });
    },
  });
}

export function useReorderColumns() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ tableId, columnIds }: { tableId: string; columnIds: string[] }) =>
      api.reorderColumns(tableId, columnIds),
    onMutate: async ({ tableId, columnIds }) => {
      // Cancel outgoing refetches
      await queryClient.cancelQueries({ queryKey: tableKeys.columns(tableId) });

      // Snapshot the previous value
      const previousColumns = queryClient.getQueryData<DatavaultColumn[]>(
        tableKeys.columns(tableId)
      );

      // Optimistically update to the new value
      if (previousColumns) {
        const reorderedColumns = columnIds
          .map((id) => previousColumns.find((col) => col.id === id))
          .filter((col): col is DatavaultColumn => col !== undefined)
          .map((col, index) => ({ ...col, orderIndex: index }));

        queryClient.setQueryData(tableKeys.columns(tableId), reorderedColumns);
      }

      // Return a context object with the snapshotted value
      return { previousColumns, tableId };
    },
    onError: (err, variables, context) => {
      // If the mutation fails, use the context returned from onMutate to roll back
      if (context?.previousColumns) {
        queryClient.setQueryData(tableKeys.columns(context.tableId), context.previousColumns);
      }
    },
    onSettled: (data, error, variables) => {
      // Always refetch after error or success
      queryClient.invalidateQueries({ queryKey: tableKeys.columns(variables.tableId) });
      queryClient.invalidateQueries({ queryKey: tableKeys.schema(variables.tableId) });
    },
  });
}

import { useInfiniteQuery, useMutation, useQueryClient } from '@tanstack/react-query';

import * as api from '../lib/api/datavault';

import { tableKeys } from './useDatavaultTables';

import type { DatavaultRow } from '../lib/types/datavault';

// ============================================================================
// Row Queries (Infinite)
// ============================================================================

const DEFAULT_PAGE_SIZE = 50;

export function useTableRows(tableId: string | undefined, pageSize: number = DEFAULT_PAGE_SIZE) {
  return useInfiniteQuery({
    queryKey: tableId ? tableKeys.rows(tableId) : ['datavault', 'tables', 'null', 'rows'],
    queryFn: ({ pageParam = 0 }) => {
      if (!tableId) {throw new Error('Table ID is required');}
      return api.getTableRows(tableId, {
        limit: pageSize,
        offset: pageParam,
      });
    },
    initialPageParam: 0,
    getNextPageParam: (lastPage, allPages) => {
      if (!lastPage.hasMore) {return undefined;}
      return allPages.length * pageSize;
    },
    enabled: !!tableId,
  });
}

// ============================================================================
// Row Mutations
// ============================================================================

export function useCreateRow() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ tableId, data }: { tableId: string; data: Record<string, any> }) =>
      api.createRow(tableId, data),
    onSuccess: (data, variables) => {
      // Invalidate rows for this table
      queryClient.invalidateQueries({ queryKey: tableKeys.rows(variables.tableId) });
    },
  });
}

export function useUpdateRow() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({
      rowId,
      tableId,
      data,
    }: {
      rowId: string;
      tableId: string;
      data: Record<string, any>;
    }) => api.updateRow(rowId, data),
    onMutate: async ({ rowId, tableId, data }) => {
      // Cancel outgoing refetches
      await queryClient.cancelQueries({ queryKey: tableKeys.rows(tableId) });

      // Snapshot the previous value
      const previousData = queryClient.getQueryData(tableKeys.rows(tableId));

      // Optimistically update the row
      queryClient.setQueryData(tableKeys.rows(tableId), (old: any) => {
        if (!old) {return old;}

        return {
          ...old,
          pages: old.pages.map((page: any) => ({
            ...page,
            rows: page.rows.map((row: DatavaultRow) =>
              row.id === rowId ? { ...row, data: { ...row.data, ...data } } : row
            ),
          })),
        };
      });

      return { previousData, tableId };
    },
    onError: (err, variables, context) => {
      // Roll back on error
      if (context?.previousData) {
        queryClient.setQueryData(tableKeys.rows(context.tableId), context.previousData);
      }
    },
    onSettled: (data, error, variables) => {
      // Always refetch after error or success
      queryClient.invalidateQueries({ queryKey: tableKeys.rows(variables.tableId) });
    },
  });
}

export function useDeleteRow() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ rowId, tableId }: { rowId: string; tableId: string }) => api.deleteRow(rowId),
    onMutate: async ({ rowId, tableId }) => {
      // Cancel outgoing refetches
      await queryClient.cancelQueries({ queryKey: tableKeys.rows(tableId) });

      // Snapshot the previous value
      const previousData = queryClient.getQueryData(tableKeys.rows(tableId));

      // Optimistically remove the row
      queryClient.setQueryData(tableKeys.rows(tableId), (old: any) => {
        if (!old) {return old;}

        return {
          ...old,
          pages: old.pages.map((page: any) => ({
            ...page,
            rows: page.rows.filter((row: DatavaultRow) => row.id !== rowId),
            total: page.total - 1,
          })),
        };
      });

      return { previousData, tableId };
    },
    onError: (err, variables, context) => {
      // Roll back on error
      if (context?.previousData) {
        queryClient.setQueryData(tableKeys.rows(context.tableId), context.previousData);
      }
    },
    onSettled: (data, error, variables) => {
      // Always refetch after error or success
      queryClient.invalidateQueries({ queryKey: tableKeys.rows(variables.tableId) });
    },
  });
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import axios from "axios";

interface Template {
  id: string;
  name: string;
  description: string | null;
  content: any;
  creatorId: string;
  isSystem: boolean;
  tags: string[];
  createdAt: string;
  updatedAt: string;
}

interface InsertTemplateVariables {
  templateId: string;
  surveyId: string;
}

interface SaveTemplateVariables {
  surveyId: string;
  name: string;
  description?: string;
}

interface UpdateTemplateVariables {
  id: string;
  data: {
    name?: string;
    description?: string;
    tags?: string[];
  };
}

interface TemplateShare {
  id: string;
  templateId: string;
  userId: string | null;
  userEmail: string | null;
  pendingEmail: string | null;
  access: "use" | "edit";
  invitedAt: string;
  acceptedAt: string | null;
}

interface ShareTemplateVariables {
  templateId: string;
  userId?: string;
  email?: string;
  access: "use" | "edit";
}

interface UpdateShareVariables {
  shareId: string;
  access: "use" | "edit";
}

export function useTemplates() {
  const queryClient = useQueryClient();

  const list = useQuery({
    queryKey: ["templates"],
    queryFn: async () => {
      const response = await axios.get<Template[]>("/api/templates");
      return response.data;
    },
    staleTime: 60_000, // 1 minute
  });

  const insert = useMutation({
    mutationFn: async ({ templateId, surveyId }: InsertTemplateVariables) => {
      const response = await axios.post(
        `/api/templates/${templateId}/insert/${surveyId}`
      );
      return response.data;
    },
    onSuccess: (_data, variables) => {
      // Invalidate survey queries to refetch updated data
      queryClient.invalidateQueries({ queryKey: ["survey", variables.surveyId] });
      queryClient.invalidateQueries({ queryKey: ["surveyPages", variables.surveyId] });
    },
  });

  const saveFromSurvey = useMutation({
    mutationFn: async ({ surveyId, name, description }: SaveTemplateVariables) => {
      const response = await axios.post(`/api/templates/from-survey/${surveyId}`, {
        name,
        description,
      });
      return response.data;
    },
    onSuccess: () => {
      // Invalidate templates list to show new template
      queryClient.invalidateQueries({ queryKey: ["templates"] });
    },
  });

  const update = useMutation({
    mutationFn: async ({ id, data }: UpdateTemplateVariables) => {
      const response = await axios.put(`/api/templates/${id}`, data);
      return response.data;
    },
    onSuccess: () => {
      // Invalidate templates list to show updated data
      queryClient.invalidateQueries({ queryKey: ["templates"] });
    },
  });

  const remove = useMutation({
    mutationFn: async (id: string) => {
      await axios.delete(`/api/templates/${id}`);
    },
    onSuccess: () => {
      // Invalidate templates list to remove deleted template
      queryClient.invalidateQueries({ queryKey: ["templates"] });
    },
  });

  return { list, insert, saveFromSurvey, update, remove };
}

export function useTemplateSharing(templateId?: string) {
  const queryClient = useQueryClient();

  const listShares = useQuery({
    queryKey: ["templateShares", templateId],
    queryFn: async () => {
      if (!templateId) {return [];}
      const response = await axios.get<TemplateShare[]>(`/api/templates/${templateId}/shares`);
      return response.data;
    },
    enabled: !!templateId,
    staleTime: 30_000, // 30 seconds
  });

  const share = useMutation({
    mutationFn: async (variables: ShareTemplateVariables) => {
      const response = await axios.post(`/api/templates/${variables.templateId}/share`, {
        userId: variables.userId,
        email: variables.email,
        access: variables.access,
      });
      return response.data;
    },
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: ["templateShares", variables.templateId] });
      queryClient.invalidateQueries({ queryKey: ["templates"] });
    },
  });

  const updateAccess = useMutation({
    mutationFn: async ({ shareId, access }: UpdateShareVariables) => {
      const response = await axios.put(`/api/template-shares/${shareId}`, { access });
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["templateShares"] });
    },
  });

  const revoke = useMutation({
    mutationFn: async (shareId: string) => {
      await axios.delete(`/api/template-shares/${shareId}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["templateShares"] });
      queryClient.invalidateQueries({ queryKey: ["templates"] });
    },
  });

  const listSharedWithMe = useQuery({
    queryKey: ["templatesSharedWithMe"],
    queryFn: async () => {
      const response = await axios.get(`/api/templates-shared-with-me`);
      return response.data;
    },
    staleTime: 60_000, // 1 minute
  });

  return { listShares, share, updateAccess, revoke, listSharedWithMe };
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import axios from "axios";
import { useEffect } from "react";

import { getQueryFn } from "@/lib/queryClient";

export interface UserPreferences {
  celebrationEffects?: boolean;
  darkMode?: "system" | "light" | "dark";
  aiHints?: boolean;
}

/**
 * Hook for managing user preferences
 * Provides access to user personalization settings with automatic syncing
 */
export function useUserPreferences() {
  const queryClient = useQueryClient();

  // Fetch user preferences
  const { data: prefs, isLoading } = useQuery<UserPreferences>({
    queryKey: ["preferences"],
    queryFn: getQueryFn({ on401: "returnNull" }),
    staleTime: 1000 * 60 * 5, // 5 minutes
  });

  // Update preferences mutation with optimistic updates
  const updateMutation = useMutation({
    mutationFn: async (updates: Partial<UserPreferences>) => {
      const response = await axios.put("/api/preferences", updates);
      return response.data;
    },
    onMutate: async (updates) => {
      // Cancel outgoing refetches
      await queryClient.cancelQueries({ queryKey: ["preferences"] });

      // Snapshot the previous value
      const previousPrefs = queryClient.getQueryData<UserPreferences>(["preferences"]);

      // Optimistically update to the new value
      if (previousPrefs) {
        queryClient.setQueryData<UserPreferences>(["preferences"], {
          ...previousPrefs,
          ...updates,
        });
      }

      // Return context with the previous value
      return { previousPrefs };
    },
    onError: (err, updates, context) => {
      // Rollback to previous value on error
      if (context?.previousPrefs) {
        queryClient.setQueryData(["preferences"], context.previousPrefs);
      }
    },
    onSettled: () => {
      // Always refetch after error or success to ensure sync with server
      queryClient.invalidateQueries({ queryKey: ["preferences"] });
    },
  });

  // Reset preferences mutation
  const resetMutation = useMutation({
    mutationFn: async () => {
      const response = await axios.post("/api/preferences/reset");
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["preferences"] });
    },
  });

  const currentPrefs = prefs || {
    celebrationEffects: true,
    darkMode: "system" as const,
    aiHints: true,
  };

  // Apply dark mode class to HTML element
  useEffect(() => {
    const applyTheme = (mode: "system" | "light" | "dark") => {
      const root = document.documentElement;

      if (mode === "dark") {
        root.classList.add("dark");
      } else if (mode === "light") {
        root.classList.remove("dark");
      } else {
        // System mode - check OS preference
        const prefersDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
        if (prefersDark) {
          root.classList.add("dark");
        } else {
          root.classList.remove("dark");
        }
      }
    };

    applyTheme(currentPrefs.darkMode ?? "system");

    // Listen for system theme changes when in system mode
    if (currentPrefs.darkMode === "system") {
      const mediaQuery = window.matchMedia("(prefers-color-scheme: dark)");
      const handleChange = (e: MediaQueryListEvent) => {
        if (currentPrefs.darkMode === "system") {
          applyTheme("system");
        }
      };

      mediaQuery.addEventListener("change", handleChange);
      return () => mediaQuery.removeEventListener("change", handleChange);
    }
  }, [currentPrefs.darkMode]);

  return {
    prefs: currentPrefs,
    isLoading,
    update: updateMutation.mutate,
    updateAsync: updateMutation.mutateAsync,
    reset: resetMutation.mutate,
    isUpdating: updateMutation.isPending,
  };
}

