import { toast } from "@/hooks/use-toast";
import { useCreateSection, useCreateStep, useUpdateStep, useUpdateWorkflow } from "@/lib/vault-hooks";
/**
 * AI Operations Application Logic
 * 
 * Takes the raw JSON suggestion from the AI backend and orchestrates the necessary
 * client-side mutations to apply those changes to the workflow.
 * 
 * This ensures that all validation, internal ID generation, and side-effects
 * (like updating the sidebar or graph) happen consistently with manual edits.
 */
interface AiSuggestion {
    newSections?: Array<{
        title: string;
        order?: number;
        steps?: Array<{
            title: string;
            type: string;
            description?: string;
        }>
    }>;
    newSteps?: Array<{
        sectionId: string; // might be "last" or "new" or a real ID if context was passed
        title: string;
        type: string;
    }>;
    // We can expand this for modifications later
}
// NOTE: This function needs to be used within a React component or hook context because 
// it relies on TanStack Query hooks. 
// However, hooks can't be called conditionally or in loops easily.
// A better pattern for this "Batch Operation" is to use the QueryClient directly 
// or pass the mutate functions in.
export async function applyAiSuggestions(
    workflowId: string,
    suggestions: AiSuggestion,
    // dependencies passed in to avoid hook rules issues
    mutations: {
        createSection: any,
        createStep: any
    }
) {
    console.log("Applying AI Suggestions:", suggestions);
    const sectionMap: Record<string, string> = {}; // map temporary IDs/Indices to real IDs
    try {
        // 1. Create New Sections
        if (suggestions.newSections) {
            for (const section of suggestions.newSections) {
                // Calculate order if not provided (append)
                const sectionData = {
                    workflowId,
                    title: section.title,
                    order: section.order ?? 999
                };
                const newSection = await mutations.createSection.mutateAsync(sectionData);
                // Add Steps for this new section
                if (section.steps) {
                    for (const step of section.steps) {
                        await mutations.createStep.mutateAsync({
                            sectionId: newSection.id,
                            title: step.title,
                            type: normalizeStepType(step.type),
                            order: 999 // auto-append
                        });
                    }
                }
            }
        }
        // 2. Add Steps to Existing Sections (if any)
        if (suggestions.newSteps) {
            for (const step of suggestions.newSteps) {
                // We need a way to resolve sectionId if it's vague. 
                // For MVP, we might assume it's adding to the currently selected section or the last one.
                // If sectionId is missing, we skip or error.
                if (step.sectionId) {
                    await mutations.createStep.mutateAsync({
                        sectionId: step.sectionId,
                        title: step.title,
                        type: normalizeStepType(step.type),
                        order: 999
                    });
                }
            }
        }
        toast({ title: "Changes Applied", description: "AI suggestions have been successfully applied." });
        return true;
    } catch (error: any) {
        console.error("Failed to apply AI changes:", error);
        toast({
            title: "Application Failed",
            description: "Could not apply some changes. The workflow state might be partial.",
            variant: "destructive"
        });
        return false;
    }
}
function normalizeStepType(type: string): string {
    const t = type.toLowerCase();
    if (t.includes("text") || t.includes("string")) {return "text";}
    if (t.includes("number") || t.includes("int")) {return "number";}
    if (t.includes("bool") || t.includes("toggle")) {return "boolean";}
    if (t.includes("choice") || t.includes("option") || t.includes("select")) {return "select";}
    if (t.includes("date")) {return "date";}
    if (t.includes("email")) {return "email";}
    return "text"; // Default fallback
}

/**
 * Analytics Client
 * Handles sending analytics events to the backend.
 * Gracefully handles failures to avoid disrupting the user experience.
 */

export interface AnalyticsEvent {
    runId: string;
    workflowId: string;
    versionId: string;
    type: string;
    blockId?: string;
    pageId?: string;
    payload?: Record<string, any>;
    timestamp?: string; // ISO string
    isPreview?: boolean;
}

class AnalyticsClient {
    private queue: AnalyticsEvent[] = [];
    private flushInterval: number | null = null;
    private FLUSH_DELAY = 1000;

    /**
     * Record an analytics event.
     * Events are queued and flushed in batches (not implemented yet, simple immediate send for now).
     */
    async record(event: AnalyticsEvent) {
        if (!event.runId || !event.workflowId) {
            // Silently skip - analytics is optional
            return;
        }

        // Add timestamp if missing
        if (!event.timestamp) {
            event.timestamp = new Date().toISOString();
        }

        try {
            await fetch('/api/workflow-analytics/events', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(event),
                keepalive: true // Ensure request survives page navigation
            });
        } catch (error) {
            // Silently fail - analytics is optional and should not clutter console
            // Only log in development if needed for debugging
            if (import.meta.env.DEV && import.meta.env.VITE_DEBUG_ANALYTICS) {
                console.warn('[Analytics] Failed to send event', error);
            }
        }
    }

    /**
     * Helper to record page view
     */
    async pageView(runId: string, workflowId: string, versionId: string, pageId: string, isPreview = false) {
        await this.record({
            runId,
            workflowId,
            versionId,
            type: 'page.view',
            pageId,
            isPreview
        });
    }

    /**
     * Helper to record run start
     */
    async runStart(runId: string, workflowId: string, versionId: string, isPreview = false) {
        await this.record({
            runId,
            workflowId,
            versionId,
            type: 'run.start',
            isPreview
        });
    }

    /**
     * Helper to record run completion
     */
    async runComplete(runId: string, workflowId: string, versionId: string, isPreview = false) {
        await this.record({
            runId,
            workflowId,
            versionId,
            type: 'workflow.complete',
            isPreview
        });
    }
}

export const analytics = new AnalyticsClient();

/**
 * API Client
 * Centralized API request handling
 * PR5: Added template test endpoint
 */

import type { TestResult } from "@/components/templates-test-runner/types";

const API_BASE = import.meta.env.VITE_BASE_URL ?? '';

/**
 * Template Test API
 */
export interface TestTemplateRequest {
  outputType: 'docx' | 'pdf' | 'both';
  sampleData: Record<string, any>;
}

export async function testTemplate(
  workflowId: string,
  templateId: string,
  request: TestTemplateRequest
): Promise<TestResult> {
  const response = await fetch(
    `${API_BASE}/api/workflows/${workflowId}/templates/${templateId}/test`,
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      credentials: 'include', // Include cookies for authentication
      body: JSON.stringify(request),
    }
  );

  if (!response.ok) {
    const error = await response.json();
    throw new Error(error.message || `HTTP ${response.status}: Failed to test template`);
  }

  return response.json();
}

/**
 * Block Registry
 * Centralized registry for all block types available in the workflow builder
 *
 * This registry defines:
 * - Block types and their metadata (label, icon, description)
 * - Mode filtering (Easy vs Advanced)
 * - Default configuration generators
 * - Block categories for UI grouping
 *
 * @version 2.0.0 - Block System Overhaul
 * @date December 2025
 */

import {
  Type,
  AlignLeft,
  ToggleLeft,
  Phone,
  Mail,
  Globe,
  Calendar,
  Clock,
  CalendarClock,
  Circle,
  CheckSquare,
  Hash,
  DollarSign,
  Star,
  FileText,
  MapPin,
  Grid3x3,
  Code2,
  FileDown,
  PenTool,
} from "lucide-react";

import type { StepConfig } from "@/../../shared/types/stepConfigs";

// ============================================================================
// TYPES
// ============================================================================

/**
 * Block Registry Entry
 * Defines a single block type and its properties
 */
export interface BlockRegistryEntry {
  /** Unique type identifier (stored in database) */
  type: string;

  /** Display label in UI */
  label: string;

  /** Icon component from lucide-react */
  icon: React.ComponentType<any>;

  /** Optional description/tooltip */
  description?: string;

  /** Category for grouping in UI */
  category: BlockCategory;

  /** Mode availability */
  modes: {
    easy: boolean;
    advanced: boolean;
  };

  /** Generate default config for this block type */
  createDefaultConfig: () => StepConfig;
}

/**
 * Block Categories for UI grouping
 */
export type BlockCategory =
  | "text"
  | "boolean"
