import { transformList, getFieldValue, isListVariable, arrayToListVariable } from "@/../../shared/listPipeline";

import type { ListVariable } from "@/../../shared/types/blocks";
import type { DynamicOptionsConfig, ChoiceOption } from "@/../../shared/types/stepConfigs";

/**
 * Generate choice options from a list variable with full transformation support
 * Uses the shared list pipeline for consistent behavior with List Tools blocks
 */
export function generateOptionsFromList(
  listData: any,
  config: DynamicOptionsConfig,
  context?: Record<string, any>
): ChoiceOption[] {
  if (config.type !== 'list') {return [];}

  const { listVariable, labelPath, valuePath, labelTemplate, groupByPath, transform, includeBlankOption, blankLabel } = config;

  // Normalize input to ListVariable
  let inputList: ListVariable;
  if (isListVariable(listData)) {
    inputList = listData;
  } else if (Array.isArray(listData)) {
    inputList = arrayToListVariable(listData);
  } else {
    console.warn('[generateOptionsFromList] Invalid list data:', listData);
    return [];
  }

  // Apply transformations (filter, sort, limit, dedupe, select)
  let transformedList = inputList;
  if (transform) {
    transformedList = transformList(inputList, transform, context);
  }

  // Map rows to options
  const opts: ChoiceOption[] = transformedList.rows.map((row, idx) => {
    // Value (stored data)
    const value = getFieldValue(row, valuePath);
    const alias = value !== undefined && value !== null ? String(value) : `opt-${idx}`;

    // Label (display text)
    let label = '';
    if (labelTemplate) {
      // Build column mapping (Name -> ID)
      const columnMap = new Map<string, string>();
      if (inputList.columns) {
        inputList.columns.forEach(col => {
          columnMap.set(col.name, col.id);
        });
      }

      // Template mode: Replace {FieldName} with values
      label = labelTemplate.replace(/\{([^}]+)\}/g, (_, fieldName) => {
        // Try direct field name first, then look up ID from mapping
        let val = getFieldValue(row, fieldName);
        if (val === undefined && columnMap.has(fieldName)) {
          val = getFieldValue(row, columnMap.get(fieldName)!);
        }
        return val !== undefined && val !== null ? String(val) : '';
      });
    } else {
      // Simple mode: Use labelPath
      const labelValue = getFieldValue(row, labelPath);
      label = labelValue !== undefined && labelValue !== null ? String(labelValue) : alias;
    }

    // Group (optional)
    const groupValue = groupByPath ? getFieldValue(row, groupByPath) : undefined;

    return {
      id: row.id || alias,
      label,
      alias,
      ...(groupValue !== undefined ? { group: String(groupValue) } : {})
    };
  });

  // Add blank option at the top
  if (includeBlankOption) {
    opts.unshift({
      id: 'blank',
      label: blankLabel ?? '',
      alias: ''
    });
  }

  return opts;
}

/**
 * Field Path Validation Helpers
 */

/**
 * Check if a field path exists in a list variable's columns
 */
export function validateFieldPath(
  fieldPath: string | undefined,
  listVariable: ListVariable | undefined
): { valid: boolean; message?: string } {
  if (!fieldPath) {
    return { valid: false, message: 'Field path is required' };
  }

  if (!listVariable?.columns || listVariable.columns.length === 0) {
    return { valid: true }; // Can't validate without column metadata, assume valid
  }

  // Check if field path matches any column ID or name
  const matchesColumn = listVariable.columns.some(col =>
    col.id === fieldPath || col.name === fieldPath
  );

  if (!matchesColumn) {
    return {
      valid: false,
      message: `Field "${fieldPath}" not found in source list`
    };
  }

  return { valid: true };
}

/**
 * Get available field paths from a list variable
 */
export function getAvailableFieldPaths(
  listVariable: ListVariable | undefined
): Array<{ id: string; name: string; type?: string }> {
  if (!listVariable?.columns) {
    return [];
  }

  return listVariable.columns.map(col => ({
    id: col.id,
    name: col.name,
    type: col.type
  }));
}

/**
 * Validate a full transform configuration
 */
export function validateTransformConfig(
  transform: any,
  sourceList: ListVariable | undefined
): Array<{ field: string; message: string }> {
  const errors: Array<{ field: string; message: string }> = [];

  if (!transform || !sourceList) {return errors;}

  // Validate filter field paths
  if (transform.filters?.rules) {
    transform.filters.rules.forEach((rule: any, index: number) => {
      const validation = validateFieldPath(rule.fieldPath, sourceList);
      if (!validation.valid) {
        errors.push({
          field: `filters.rules[${index}].fieldPath`,
          message: validation.message || 'Invalid field path'
        });
      }
    });
  }

  // Validate sort field paths
  if (transform.sort) {
    transform.sort.forEach((sortKey: any, index: number) => {
      const validation = validateFieldPath(sortKey.fieldPath, sourceList);
      if (!validation.valid) {
        errors.push({
          field: `sort[${index}].fieldPath`,
          message: validation.message || 'Invalid field path'
        });
      }
    });
  }

  // Validate dedupe field path
  if (transform.dedupe?.fieldPath) {
    const validation = validateFieldPath(transform.dedupe.fieldPath, sourceList);
    if (!validation.valid) {
      errors.push({
        field: 'dedupe.fieldPath',
        message: validation.message || 'Invalid field path'
      });
    }
  }

  // Validate select field paths
  if (transform.select) {
    transform.select.forEach((fieldPath: string, index: number) => {
      const validation = validateFieldPath(fieldPath, sourceList);
      if (!validation.valid) {
        errors.push({
          field: `select[${index}]`,
          message: validation.message || 'Invalid field path'
        });
      }
    });
  }

  return errors;
}

/**
 * Stage 17: Color Utilities
 *
 * Utilities for color manipulation, derivation, and contrast calculation.
 * Used for generating light/dark variants of branding colors.
 */

/**
 * Convert hex color to RGB components
 */
export function hexToRgb(hex: string): { r: number; g: number; b: number } | null {
  // Remove # if present
  hex = hex.replace(/^#/, '');

  // Parse 3-digit or 6-digit hex
  if (hex.length === 3) {
    hex = hex
      .split('')
      .map((char) => char + char)
      .join('');
  }

  if (hex.length !== 6) {
    return null;
  }

  const num = parseInt(hex, 16);
  return {
    r: (num >> 16) & 255,
    g: (num >> 8) & 255,
    b: num & 255,
  };
}

/**
 * Convert RGB to hex color
 */
export function rgbToHex(r: number, g: number, b: number): string {
  const toHex = (n: number) => {
    const hex = Math.round(Math.max(0, Math.min(255, n))).toString(16);
    return hex.length === 1 ? `0${  hex}` : hex;
  };

  return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Lighten a color by a percentage (0-100)
 */
export function lightenColor(hex: string, percent: number): string {
  const rgb = hexToRgb(hex);
  if (!rgb) {return hex;}

  const amount = (percent / 100) * 255;
  return rgbToHex(
    rgb.r + (255 - rgb.r) * (amount / 255),
    rgb.g + (255 - rgb.g) * (amount / 255),
    rgb.b + (255 - rgb.b) * (amount / 255)
  );
}

/**
 * Darken a color by a percentage (0-100)
 */
export function darkenColor(hex: string, percent: number): string {
  const rgb = hexToRgb(hex);
  if (!rgb) {return hex;}

  const factor = 1 - percent / 100;
  return rgbToHex(rgb.r * factor, rgb.g * factor, rgb.b * factor);
}

/**
 * Calculate relative luminance of a color (WCAG 2.0)
 * https://www.w3.org/TR/WCAG20/#relativeluminancedef
 */
export function getLuminance(hex: string): number {
  const rgb = hexToRgb(hex);
  if (!rgb) {return 0;}

  const [r, g, b] = [rgb.r, rgb.g, rgb.b].map((val) => {
    const sRGB = val / 255;
    return sRGB <= 0.03928 ? sRGB / 12.92 : Math.pow((sRGB + 0.055) / 1.055, 2.4);
  });

  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

/**
 * Calculate contrast ratio between two colors (WCAG 2.0)
 * Returns a value between 1 and 21
 */
export function getContrastRatio(color1: string, color2: string): number {
  const lum1 = getLuminance(color1);
  const lum2 = getLuminance(color2);

  const lighter = Math.max(lum1, lum2);
  const darker = Math.min(lum1, lum2);

  return (lighter + 0.05) / (darker + 0.05);
}

/**
 * Check if color combination meets WCAG AA standard (4.5:1 for normal text)
 */
export function meetsWCAGAA(foreground: string, background: string): boolean {
  return getContrastRatio(foreground, background) >= 4.5;
}

/**
 * Check if color combination meets WCAG AAA standard (7:1 for normal text)
 */
export function meetsWCAGAAA(foreground: string, background: string): boolean {
  return getContrastRatio(foreground, background) >= 7;
}

/**
 * Get the best contrast text color (black or white) for a background
 */
export function getContrastTextColor(backgroundColor: string): string {
  const whiteContrast = getContrastRatio('#FFFFFF', backgroundColor);
  const blackContrast = getContrastRatio('#000000', backgroundColor);

  return whiteContrast > blackContrast ? '#FFFFFF' : '#000000';
}

/**
 * Check if a color is considered "light"
 */
export function isLightColor(hex: string): boolean {
  return getLuminance(hex) > 0.5;
}

/**
 * Check if a color is considered "dark"
 */
export function isDarkColor(hex: string): boolean {
  return getLuminance(hex) <= 0.5;
}

/**
 * Adjust color brightness to ensure minimum contrast ratio
 * Returns a new color that meets the target contrast ratio
 */
export function adjustForContrast(
  color: string,
  backgroundColor: string,
  targetRatio: number = 4.5
): string {
  let adjustedColor = color;
  let iterations = 0;
  const maxIterations = 20;

  while (getContrastRatio(adjustedColor, backgroundColor) < targetRatio && iterations < maxIterations) {
    if (isLightColor(backgroundColor)) {
      // On light backgrounds, darken the color
      adjustedColor = darkenColor(adjustedColor, 5);
    } else {
      // On dark backgrounds, lighten the color
      adjustedColor = lightenColor(adjustedColor, 5);
    }
    iterations++;
  }

  return adjustedColor;
}

/**
 * Generate color palette variants from a base color
 */
export interface ColorPalette {
  base: string;
  light: string;
  lighter: string;
  dark: string;
  darker: string;
  contrast: string; // Best contrast text color
}

export function generateColorPalette(baseColor: string): ColorPalette {
  return {
    base: baseColor,
    light: lightenColor(baseColor, 15),
    lighter: lightenColor(baseColor, 30),
    dark: darkenColor(baseColor, 15),
    darker: darkenColor(baseColor, 30),
    contrast: getContrastTextColor(baseColor),
  };
}

/**
 * Validate hex color format
 */
export function isValidHexColor(hex: string): boolean {
  return /^#?([0-9A-Fa-f]{3}|[0-9A-Fa-f]{6})$/.test(hex);
}

/**
 * Normalize hex color (ensure it has # prefix and is 6 digits)
 */
export function normalizeHexColor(hex: string): string {
  hex = hex.replace(/^#/, '');

  if (hex.length === 3) {
    hex = hex
      .split('')
      .map((char) => char + char)
      .join('');
  }

  return `#${hex.toUpperCase()}`;
}

import { z } from "zod";

/**
 * Environment Configuration Schema
 * Centralizes all environment variable access and validation.
 */

const envSchema = z.object({
    // Base
    NODE_ENV: z.enum(["development", "test", "production"]).default("development"),
    PORT: z.string().transform(Number).default("5000"),

    // App
    VITE_API_URL: z.string().optional(), // Used by client
    APP_URL: z.string().optional(), // Used by server

    // Database
    DATABASE_URL: z.string().min(1, "DATABASE_URL is required"),

    // Security
    SESSION_SECRET: z.string().default("dev_secret_do_not_use_in_prod"),
    VITE_GOOGLE_CLIENT_ID: z.string().optional(),
    GOOGLE_CLIENT_SECRET: z.string().optional(),

    // Feature Flags (Optional overrides, otherwise defaults apply)
    // These map to the flags in featureFlags/definitions.ts
    VITE_ENABLE_BLOCKS_V2: z.string().transform(v => v === 'true').optional(),
    VITE_ENABLE_SCRIPTING_V1: z.string().transform(v => v === 'true').optional(),
    VITE_ENABLE_VALIDATION_V2: z.string().transform(v => v === 'true').optional(),
    VITE_ENABLE_VERSIONING: z.string().transform(v => v === 'true').optional(),
    VITE_ENABLE_ANALYTICS_V1: z.string().transform(v => v === 'true').optional(),
    VITE_ENABLE_COLLAB_V1: z.string().transform(v => v === 'true').optional(),
    VITE_ENABLE_PREVIEW_HOT_RELOAD: z.string().transform(v => v === 'true').optional(),
    VITE_ENABLE_AUTO_TEST_RUNNER: z.string().transform(v => v === 'true').optional(),

    // Integrations
    SLACK_BOT_TOKEN: z.string().optional(),
    SLACK_SIGNING_SECRET: z.string().optional(),
    SENDGRID_API_KEY: z.string().optional(),
    OPENAI_API_KEY: z.string().optional(),
    ANTHROPIC_API_KEY: z.string().optional(),

    // Observability
    LOG_LEVEL: z.enum(["debug", "info", "warn", "error"]).default("info"),
});

// Process the environment
// Note: In Vite, import.meta.env has client-side vars, process.env has server-side.
// This file is designed to be shared, but strict validation might need to differ slightly between client/server
// or be careful about what is accessed where.
// For now, we'll try to use a unified approach, prioritizing process.env for Node and import.meta.env for Vite if available.

const getRawEnv = () => {
    if (typeof process !== 'undefined' && process.env) {
        return process.env;
    }
    // @ts-ignore - Vite specific
    if (import.meta && import.meta.env) {
        // @ts-ignore
        return import.meta.env;
    }
    return {};
};

const rawEnv = getRawEnv();

// Parse and validate
// We use safeParse to avoid crashing the app immediately if loaded in a context 
// where not all vars are needed (like simple unit tests), but we log errors.
const parsed = envSchema.safeParse(rawEnv);

if (!parsed.success) {
    console.warn("ΓÜá∩╕Å  Environment validation failed:", parsed.error.format());
}

export const env = parsed.success ? parsed.data : (rawEnv as any);

// Helper to check if we are in production
export const isProduction = env.NODE_ENV === "production";
export const isDevelopment = env.NODE_ENV === "development";
export const isTest = env.NODE_ENV === "test";

