 * Common abstraction for all data sources (native tables, Google Sheets, future connectors)
 */

export type HealthStatus = 'healthy' | 'degraded' | 'unreachable';

export interface DataSourceHealth {
    status: HealthStatus;
    lastChecked: string; // ISO timestamp
    message: string; // Human-readable message
    details?: {
        authExpired?: boolean;
        rateLimited?: boolean;
        permissionDenied?: boolean;
    };
}

export interface ColumnMetadata {
    uuid: string;
    displayName: string;
    dataType?: 'string' | 'number' | 'date' | 'boolean' | 'json';
}

export interface TableMetadata {
    id: string;
    name: string;
    columns: ColumnMetadata[];
}

export interface ReadOptions {
    filters?: Array<{
        column: string; // UUID
        operator: '=' | '!=' | '>' | '<' | '>=' | '<=' | 'contains';
        value: any;
    }>;
    sort?: Array<{
        column: string; // UUID
        direction: 'asc' | 'desc';
    }>;
    limit?: number;
}

export interface WriteOptions {
    upsertStrategy: 'primary_key' | 'match_column' | 'append_only';
    primaryKeyColumn?: string; // UUID
    matchColumn?: string; // UUID
}

export interface WriteResult {
    rowsUpdated: number;
    rowsInserted: number;
    rowsFailed: number;
    errors: Array<{
        row: number;
        error: string;
        severity: 'warning' | 'error';
    }>;
}

/**
 * Base interface that all data source connectors must implement
 */
export interface DataSourceConnector {
    /**
     * Check health status of this data source
     */
    healthCheck(): Promise<DataSourceHealth>;

    /**
     * List all tables/sheets available in this data source
     */
    listTables(): Promise<TableMetadata[]>;

    /**
     * Get detailed column metadata for a specific table
     */
    getTableMetadata(tableId: string): Promise<TableMetadata>;

    /**
     * Read rows from a table
     * Returns rows as objects keyed by column UUID
     */
    readRows(tableId: string, options?: ReadOptions): Promise<Record<string, any>[]>;

    /**
     * Write rows to a table
     * Rows should be keyed by column UUID
     */
    writeRows(
        tableId: string,
        rows: Record<string, any>[],
        options?: WriteOptions
    ): Promise<WriteResult>;
}

/**
 * Google Sheets specific connector implementation
 */
export class GoogleSheetsConnector implements DataSourceConnector {
    constructor(
        private spreadsheetId: string,
        private accessToken: string
    ) { }

    async healthCheck(): Promise<DataSourceHealth> {
        try {
            // Try to fetch spreadsheet metadata
            const response = await fetch(
                `/api/google-sheets/${this.spreadsheetId}/health`,
                {
                    headers: {
                        'Authorization': `Bearer ${this.accessToken}`,
                    },
                    credentials: 'include',
                }
            );

            if (response.status === 401) {
                return {
                    status: 'degraded',
                    lastChecked: new Date().toISOString(),
                    message: 'Authentication refresh needed',
                    details: { authExpired: true },
                };
            }

            if (response.status === 403) {
                return {
                    status: 'unreachable',
                    lastChecked: new Date().toISOString(),
                    message: 'Permission denied - check sharing settings',
                    details: { permissionDenied: true },
                };
            }

            if (response.status === 429) {
                return {
                    status: 'degraded',
                    lastChecked: new Date().toISOString(),
                    message: 'Rate limit reached - will retry soon',
                    details: { rateLimited: true },
                };
            }

            if (!response.ok) {
                return {
                    status: 'unreachable',
                    lastChecked: new Date().toISOString(),
                    message: `HTTP ${response.status}: ${response.statusText}`,
                };
            }

            return {
                status: 'healthy',
                lastChecked: new Date().toISOString(),
                message: 'Connected successfully',
            };
        } catch (error) {
            return {
                status: 'unreachable',
                lastChecked: new Date().toISOString(),
                message: error instanceof Error ? error.message : 'Unknown error',
            };
        }
    }

    async listTables(): Promise<TableMetadata[]> {
        const response = await fetch(
            `/api/google-sheets/${this.spreadsheetId}/sheets`,
            {
                headers: {
                    'Authorization': `Bearer ${this.accessToken}`,
                },
                credentials: 'include',
            }
        );

        if (!response.ok) {
            throw new Error(`Failed to list sheets: ${response.statusText}`);
        }

        const data = await response.json();
        return data.sheets ?? [];
    }

    async getTableMetadata(sheetId: string): Promise<TableMetadata> {
        const response = await fetch(
            `/api/google-sheets/${this.spreadsheetId}/sheets/${sheetId}/metadata`,
            {
                headers: {
                    'Authorization': `Bearer ${this.accessToken}`,
                },
                credentials: 'include',
            }
        );

        if (!response.ok) {
            throw new Error(`Failed to get sheet metadata: ${response.statusText}`);
        }

        return response.json();
    }

    async readRows(sheetId: string, options?: ReadOptions): Promise<Record<string, any>[]> {
        const params = new URLSearchParams();
        if (options?.limit) {params.set('limit', options.limit.toString());}
        if (options?.filters) {params.set('filters', JSON.stringify(options.filters));}
        if (options?.sort) {params.set('sort', JSON.stringify(options.sort));}

        const response = await fetch(
            `/api/google-sheets/${this.spreadsheetId}/sheets/${sheetId}/rows?${params}`,
            {
                headers: {
                    'Authorization': `Bearer ${this.accessToken}`,
                },
                credentials: 'include',
            }
        );

        if (!response.ok) {
            throw new Error(`Failed to read rows: ${response.statusText}`);
        }

        const data = await response.json();
        return data.rows ?? [];
    }

    async writeRows(
        sheetId: string,
        rows: Record<string, any>[],
        options?: WriteOptions
    ): Promise<WriteResult> {
        const response = await fetch(
            `/api/google-sheets/${this.spreadsheetId}/sheets/${sheetId}/rows`,
            {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${this.accessToken}`,
                },
                credentials: 'include',
                body: JSON.stringify({
                    rows,
                    options,
                }),
            }
        );

        if (!response.ok) {
            throw new Error(`Failed to write rows: ${response.statusText}`);
        }

        return response.json();
    }
}

/**
 * Native table connector (for PostgreSQL/DataVault tables)
 */
export class NativeTableConnector implements DataSourceConnector {
    constructor(private dataSourceId: string) { }

    async healthCheck(): Promise<DataSourceHealth> {
        try {
            const response = await fetch(`/api/data-sources/${this.dataSourceId}/health`, {
                credentials: 'include',
            });

            if (!response.ok) {
                return {
                    status: 'unreachable',
                    lastChecked: new Date().toISOString(),
                    message: `Database unavailable: ${response.statusText}`,
                };
            }

            return {
                status: 'healthy',
                lastChecked: new Date().toISOString(),
                message: 'Database connection active',
            };
        } catch (error) {
            return {
                status: 'unreachable',
                lastChecked: new Date().toISOString(),
                message: error instanceof Error ? error.message : 'Unknown error',
            };
        }
    }

    async listTables(): Promise<TableMetadata[]> {
        const response = await fetch(`/api/data-sources/${this.dataSourceId}/tables`, {
            credentials: 'include',
        });

        if (!response.ok) {
            throw new Error(`Failed to list tables: ${response.statusText}`);
        }

        return response.json();
    }

    async getTableMetadata(tableId: string): Promise<TableMetadata> {
        const response = await fetch(`/api/tables/${tableId}/metadata`, {
            credentials: 'include',
        });

        if (!response.ok) {
            throw new Error(`Failed to get table metadata: ${response.statusText}`);
        }

        return response.json();
    }

    async readRows(tableId: string, options?: ReadOptions): Promise<Record<string, any>[]> {
        const response = await fetch(`/api/tables/${tableId}/rows`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            credentials: 'include',
            body: JSON.stringify(options || {}),
        });

        if (!response.ok) {
            throw new Error(`Failed to read rows: ${response.statusText}`);
        }

        const data = await response.json();
        return data.rows ?? [];
    }

    async writeRows(
        tableId: string,
        rows: Record<string, any>[],
        options?: WriteOptions
    ): Promise<WriteResult> {
        const response = await fetch(`/api/tables/${tableId}/rows`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            credentials: 'include',
            body: JSON.stringify({
                rows,
                options,
            }),
        });

        if (!response.ok) {
            throw new Error(`Failed to write rows: ${response.statusText}`);
        }

        return response.json();
    }
}

/**
 * DataVault API client
 * API functions for DataVault Phase 1 & Phase 2 (Databases)
 */

import type { DatavaultTable, DatavaultColumn, DatavaultRow, DatavaultRowNote, DatavaultApiToken, DatavaultTablePermission, DatavaultTableRole } from "@shared/schema";

import { apiRequest } from "./queryClient";

export interface ApiDatavaultTableWithStats extends DatavaultTable {
  columnCount: number;
  rowCount: number;
}

export interface ApiDatavaultRowWithValues {
  row: DatavaultRow;
  values: Record<string, any>; // columnId -> value
}

export interface DatavaultDatabase {
  id: string;
  tenantId: string;
  name: string;
  description: string | null;
  scopeType: 'account' | 'project' | 'workflow';
  scopeId: string | null;
  createdAt: string;
  updatedAt: string;
  tableCount?: number;
}

export interface ApiDatavaultApiToken extends Omit<DatavaultApiToken, 'tokenHash'> {
  // API never returns tokenHash for security
}

export interface ApiCreateTokenResponse {
  token: ApiDatavaultApiToken;
  plainToken: string;
  message: string;
}

export const datavaultAPI = {
  // ============================================================================
  // Databases (Phase 2)
  // ============================================================================

  listDatabases: async (params?: {
    scopeType?: 'account' | 'project' | 'workflow';
    scopeId?: string;
  }): Promise<DatavaultDatabase[]> => {
    const queryParams = new URLSearchParams();
    if (params?.scopeType) {queryParams.set('scopeType', params.scopeType);}
    if (params?.scopeId) {queryParams.set('scopeId', params.scopeId);}

    const url = `/api/datavault/databases${queryParams.toString() ? `?${queryParams}` : ''}`;
    const res = await apiRequest('GET', url);
    return res.json();
  },

  getDatabase: async (id: string): Promise<DatavaultDatabase> => {
    const res = await apiRequest('GET', `/api/datavault/databases/${id}`);
    return res.json();
  },

  createDatabase: async (data: {
    name: string;
    description?: string;
    scopeType: 'account' | 'project' | 'workflow';
    scopeId?: string;
  }): Promise<DatavaultDatabase> => {
    const res = await apiRequest('POST', '/api/datavault/databases', data);
    return res.json();
  },

  updateDatabase: async (
    id: string,
    data: {
      name?: string;
      description?: string;
      scopeType?: 'account' | 'project' | 'workflow';
      scopeId?: string | null;
    }
  ): Promise<DatavaultDatabase> => {
    const res = await apiRequest('PATCH', `/api/datavault/databases/${id}`, data);
    return res.json();
  },

  deleteDatabase: async (id: string): Promise<void> => {
    const res = await apiRequest('DELETE', `/api/datavault/databases/${id}`);
    if (res.status !== 204) {
      await res.json();
    }
  },

  transferDatabase: async (
    id: string,
    targetOwnerType: 'user' | 'org',
    targetOwnerUuid: string
  ): Promise<DatavaultDatabase> => {
    const res = await apiRequest('POST', `/api/datavault/databases/${id}/transfer`, {
      targetOwnerType,
      targetOwnerUuid,
    });
    return res.json();
  },

  getTablesInDatabase: async (databaseId: string): Promise<DatavaultTable[]> => {
    const res = await apiRequest('GET', `/api/datavault/databases/${databaseId}/tables`);
    return res.json();
  },

  // ============================================================================
  // Tables (Phase 1)
  // ============================================================================
  // Tables
  listTables: async (withStats = false): Promise<ApiDatavaultTableWithStats[]> => {
    const res = await apiRequest('GET', `/api/datavault/tables?stats=${withStats}`);
    return res.json();
  },

  getTable: async (tableId: string, withColumns = false): Promise<DatavaultTable> => {
    const res = await apiRequest('GET', `/api/datavault/tables/${tableId}?columns=${withColumns}`);
    return res.json();
  },

  createTable: async (data: {
    name: string;
    slug?: string;
    description?: string;
    databaseId?: string;
  }): Promise<DatavaultTable> => {
    const res = await apiRequest('POST', '/api/datavault/tables', data);
    return res.json();
  },

  updateTable: async (
    tableId: string,
    data: Partial<{ name: string; slug: string; description: string }>
  ): Promise<DatavaultTable> => {
    const res = await apiRequest('PATCH', `/api/datavault/tables/${tableId}`, data);
    return res.json();
  },

  deleteTable: async (tableId: string): Promise<void> => {
    const res = await apiRequest('DELETE', `/api/datavault/tables/${tableId}`);
    if (res.status !== 204) {
      await res.json();
    }
  },

  moveTable: async (tableId: string, databaseId: string | null): Promise<DatavaultTable> => {
    const res = await apiRequest('PATCH', `/api/datavault/tables/${tableId}/move`, { databaseId });
    return res.json();
  },

  getTableSchema: async (tableId: string) => {
    const res = await apiRequest('GET', `/api/datavault/tables/${tableId}/schema`);
    return res.json();
  },

  // Columns
  listColumns: async (tableId: string): Promise<DatavaultColumn[]> => {
    const res = await apiRequest('GET', `/api/datavault/tables/${tableId}/columns`);
    return res.json();
  },

  createColumn: async (
    tableId: string,
    data: {
      name: string;
      type: string;
      slug?: string;
      required?: boolean;
      orderIndex?: number;
    }
  ): Promise<DatavaultColumn> => {
    const res = await apiRequest('POST', `/api/datavault/tables/${tableId}/columns`, data);
    return res.json();
  },

  updateColumn: async (
    columnId: string,
    data: Partial<{ name: string; slug: string; required: boolean; orderIndex: number; widthPx: number }>
  ): Promise<DatavaultColumn> => {
    const res = await apiRequest('PATCH', `/api/datavault/columns/${columnId}`, data);
    return res.json();
  },

  deleteColumn: async (columnId: string): Promise<void> => {
    const res = await apiRequest('DELETE', `/api/datavault/columns/${columnId}`);
    if (res.status !== 204) {
      await res.json();
    }
  },

  reorderColumns: async (tableId: string, columnIds: string[]): Promise<void> => {
    const res = await apiRequest('POST', `/api/datavault/tables/${tableId}/columns/reorder`, { columnIds });
    if (res.status !== 204) {
      await res.json();
    }
  },

  // Rows
  listRows: async (
    tableId: string,
    options?: {
      limit?: number;
      offset?: number;
      showArchived?: boolean;
      sortBy?: string;
      sortOrder?: 'asc' | 'desc';
      filters?: Array<{ columnId: string; operator: string; value: any }>;
    }
  ): Promise<{
    rows: ApiDatavaultRowWithValues[];
    pagination: { limit: number; offset: number; total: number; hasMore: boolean };
  }> => {
    const params = new URLSearchParams();
    if (options?.limit) {params.append('limit', options.limit.toString());}
    if (options?.offset !== undefined) {params.append('offset', options.offset.toString());}
    if (options?.showArchived) {params.append('showArchived', 'true');}
    if (options?.sortBy) {params.append('sortBy', options.sortBy);}
    if (options?.sortOrder) {params.append('sortOrder', options.sortOrder);}
    if (options?.filters && options.filters.length > 0) {
      params.append('filters', JSON.stringify(options.filters));
    }
    const res = await apiRequest('GET', `/api/datavault/tables/${tableId}/rows?${params.toString()}`);
    return res.json();
  },

  getRow: async (rowId: string): Promise<ApiDatavaultRowWithValues> => {
    const res = await apiRequest('GET', `/api/datavault/rows/${rowId}`);
    return res.json();
  },

  createRow: async (
    tableId: string,
    values: Record<string, any>
  ): Promise<ApiDatavaultRowWithValues> => {
    const res = await apiRequest('POST', `/api/datavault/tables/${tableId}/rows`, { values });
    return res.json();
  },

  updateRow: async (rowId: string, values: Record<string, any>): Promise<void> => {
    const res = await apiRequest('PATCH', `/api/datavault/rows/${rowId}`, { values });
    if (res.status !== 204) {
      await res.json();
    }
  },

  deleteRow: async (rowId: string): Promise<void> => {
    const res = await apiRequest('DELETE', `/api/datavault/rows/${rowId}`);
    if (res.status !== 204) {
      await res.json();
    }
  },

  // Archive operations
  archiveRow: async (rowId: string): Promise<void> => {
    const res = await apiRequest('PATCH', `/api/datavault/rows/${rowId}/archive`);
    if (res.status !== 200) {
      await res.json();
    }
  },

  unarchiveRow: async (rowId: string): Promise<void> => {
    const res = await apiRequest('PATCH', `/api/datavault/rows/${rowId}/unarchive`);
    if (res.status !== 200) {
      await res.json();
    }
  },

  bulkArchiveRows: async (rowIds: string[]): Promise<void> => {
    const res = await apiRequest('PATCH', '/api/datavault/rows/bulk/archive', { rowIds });
    if (res.status !== 200) {
      await res.json();
    }
  },

  bulkUnarchiveRows: async (rowIds: string[]): Promise<void> => {
    const res = await apiRequest('PATCH', '/api/datavault/rows/bulk/unarchive', { rowIds });
    if (res.status !== 200) {
      await res.json();
    }
  },

  bulkDeleteRows: async (rowIds: string[]): Promise<void> => {
    const res = await apiRequest('DELETE', '/api/datavault/rows/bulk/delete', { rowIds });
    if (res.status !== 200) {
      await res.json();
    }
  },

  // ============================================================================
  // Row Notes (v4 Micro-Phase 3)
  // ============================================================================

  /**
   * Get all notes for a row
   * Returns notes ordered by creation time (newest first)
   */
  getRowNotes: async (rowId: string): Promise<DatavaultRowNote[]> => {
    const res = await apiRequest('GET', `/api/datavault/rows/${rowId}/notes`);
    return res.json();
  },

  /**
   * Create a new note for a row
   */
  createRowNote: async (rowId: string, text: string): Promise<DatavaultRowNote> => {
    const res = await apiRequest('POST', `/api/datavault/rows/${rowId}/notes`, { text });
    return res.json();
  },

  /**
   * Delete a note
   * Only the note owner or table owner can delete
   */
  deleteRowNote: async (noteId: string): Promise<void> => {
    const res = await apiRequest('DELETE', `/api/datavault/notes/${noteId}`);
    if (res.status !== 200) {
      await res.json();
    }
  },

  // ============================================================================
  // API Tokens (v4 Micro-Phase 5)
  // ============================================================================

  /**
   * List all API tokens for a database
   * Returns tokens without hash for security
   */
  listApiTokens: async (databaseId: string): Promise<{ tokens: ApiDatavaultApiToken[] }> => {
    const res = await apiRequest('GET', `/api/datavault/databases/${databaseId}/tokens`);
    return res.json();
  },

  /**
   * Create a new API token
   * Returns the plain token ONCE (never stored or returned again)
   */
  createApiToken: async (
    databaseId: string,
    data: {
      label: string;
      scopes: ('read' | 'write')[];
      expiresAt?: string;
    }
  ): Promise<ApiCreateTokenResponse> => {
    const res = await apiRequest('POST', `/api/datavault/databases/${databaseId}/tokens`, data);
    return res.json();
  },

  /**
   * Revoke (delete) an API token
   */
  deleteApiToken: async (tokenId: string, databaseId: string): Promise<void> => {
    const res = await apiRequest('DELETE', `/api/datavault/tokens/${tokenId}`, { databaseId });
    if (res.status !== 200) {
      await res.json();
    }
  },

  // ============================================================================
  // Table Permissions (v4 Micro-Phase 6)
  // ============================================================================

  /**
   * Get all permissions for a table (owner only)
   */
  listTablePermissions: async (tableId: string): Promise<DatavaultTablePermission[]> => {
    const res = await apiRequest('GET', `/api/datavault/tables/${tableId}/permissions`);
    return res.json();
  },

  /**
   * Grant or update permission for a user on a table (owner only)
   * Upserts the permission (creates or updates)
   */
  grantTablePermission: async (
    tableId: string,
    data: {
      userId: string;
      role: DatavaultTableRole;
    }
  ): Promise<DatavaultTablePermission> => {
    const res = await apiRequest('POST', `/api/datavault/tables/${tableId}/permissions`, data);
    return res.json();
  },

  /**
   * Revoke a permission (owner only)
   */
  revokeTablePermission: async (permissionId: string, tableId: string): Promise<void> => {
    const res = await apiRequest('DELETE', `/api/datavault/permissions/${permissionId}?tableId=${tableId}`);
    if (res.status !== 200) {
      await res.json();
    }
  },
};

import { env } from "../config/environment";

export enum FeatureFlag {
    // Core Systems
    BLOCKS_V2 = "blocks_v2_enabled",
    SCRIPTING_V1 = "scripting_v1_enabled",
    VALIDATION_V2 = "validation_v2_enabled",
    VERSIONING = "workflow_versioning_enabled",
    ANALYTICS_V1 = "analytics_v1_enabled",
    COLLAB_V1 = "collaboration_v1_enabled",

    // Preview
    PREVIEW_HOT_RELOAD = "preview_hot_reload_enabled",
    AUTO_TEST_RUNNER = "auto_test_runner_enabled",

    // Integrations & Blocks
    DOCGEN_V2 = "docgen_v2_enabled",
    SIGNATURE_V2 = "signature_v2_enabled",
    SIGNATURE_MOCK = "signature_mock_mode_enabled", // If true, don't send real envelopes

    // Experimental
    AI_AUTOFILL = "ai_autofill_enabled",
    EXPERIMENTAL_MODE = "experimental_mode"
}

export const DEFAULT_FLAGS: Record<FeatureFlag, boolean> = {
    [FeatureFlag.BLOCKS_V2]: true,
    [FeatureFlag.SCRIPTING_V1]: true,
    [FeatureFlag.VALIDATION_V2]: true,
    [FeatureFlag.VERSIONING]: true,
    [FeatureFlag.ANALYTICS_V1]: true,
    [FeatureFlag.COLLAB_V1]: false, // Still in dev
    [FeatureFlag.PREVIEW_HOT_RELOAD]: true,
    [FeatureFlag.AUTO_TEST_RUNNER]: true,
    [FeatureFlag.DOCGEN_V2]: true,
    [FeatureFlag.SIGNATURE_V2]: true,
    [FeatureFlag.SIGNATURE_MOCK]: env.NODE_ENV !== "production", // Default to mock in non-prod
    [FeatureFlag.AI_AUTOFILL]: false,
    [FeatureFlag.EXPERIMENTAL_MODE]: false,
};

/**
 * Resolve the initial state of flags based on environment variables.
 * Env vars override defaults.
 */
export const getInitialFeatureFlags = (): Record<FeatureFlag, boolean> => {
    return {
        [FeatureFlag.BLOCKS_V2]: env.VITE_ENABLE_BLOCKS_V2 ?? DEFAULT_FLAGS[FeatureFlag.BLOCKS_V2],
        [FeatureFlag.SCRIPTING_V1]: env.VITE_ENABLE_SCRIPTING_V1 ?? DEFAULT_FLAGS[FeatureFlag.SCRIPTING_V1],
        [FeatureFlag.VALIDATION_V2]: env.VITE_ENABLE_VALIDATION_V2 ?? DEFAULT_FLAGS[FeatureFlag.VALIDATION_V2],
        [FeatureFlag.VERSIONING]: env.VITE_ENABLE_VERSIONING ?? DEFAULT_FLAGS[FeatureFlag.VERSIONING],
        [FeatureFlag.ANALYTICS_V1]: env.VITE_ENABLE_ANALYTICS_V1 ?? DEFAULT_FLAGS[FeatureFlag.ANALYTICS_V1],
        [FeatureFlag.COLLAB_V1]: env.VITE_ENABLE_COLLAB_V1 ?? DEFAULT_FLAGS[FeatureFlag.COLLAB_V1],
        [FeatureFlag.PREVIEW_HOT_RELOAD]: env.VITE_ENABLE_PREVIEW_HOT_RELOAD ?? DEFAULT_FLAGS[FeatureFlag.PREVIEW_HOT_RELOAD],
        [FeatureFlag.AUTO_TEST_RUNNER]: env.VITE_ENABLE_AUTO_TEST_RUNNER ?? DEFAULT_FLAGS[FeatureFlag.AUTO_TEST_RUNNER],
        [FeatureFlag.DOCGEN_V2]: DEFAULT_FLAGS[FeatureFlag.DOCGEN_V2],
        [FeatureFlag.SIGNATURE_V2]: DEFAULT_FLAGS[FeatureFlag.SIGNATURE_V2],
        [FeatureFlag.SIGNATURE_MOCK]: DEFAULT_FLAGS[FeatureFlag.SIGNATURE_MOCK],
        [FeatureFlag.AI_AUTOFILL]: DEFAULT_FLAGS[FeatureFlag.AI_AUTOFILL],
        [FeatureFlag.EXPERIMENTAL_MODE]: DEFAULT_FLAGS[FeatureFlag.EXPERIMENTAL_MODE],
    };
};

/**
 * Google Sheets Connector - Column UUID Mapping
 * Ensures column identity stability across header renames
 */

export interface SheetColumn {
    uuid: string;           // Stable internal UUID
    displayName: string;    // Current header text
    letterCode: string;     // Sheet column (A, B, C, etc.)
    dataType?: 'string' | 'number' | 'date' | 'boolean';
    externallyRenamed?: boolean;  // Flag if header changed
}

export interface SheetMetadata {
    spreadsheetId: string;
    sheetId: string;
    sheetName: string;
    columns: SheetColumn[];
    lastSynced: string;     // ISO timestamp
}

export interface SheetWriteOptions {
    upsertStrategy: 'primary_key' | 'match_column';
    primaryKeyColumn?: string;  // UUID of PK column
    matchColumn?: string;       // UUID of match column
    matchValue?: any;           // Value to match against
}

export interface SheetWriteResult {
    rowsUpdated: number;
    rowsInserted: number;
    errors: SheetWriteError[];
}

export interface SheetWriteError {
    row: number;
    error: string;
    severity: 'warning' | 'error';
}

/**
 * Column UUID Manager
 * Handles mapping between stable UUIDs and sheet columns
 */
export class ColumnUUIDManager {
    /**
     * Generate initial column mapping from sheet header row
     */
    static generateColumnMapping(headerRow: string[], sheetId: string): SheetColumn[] {
        return headerRow.map((header, index) => ({
            uuid: crypto.randomUUID(),
            displayName: header,
            letterCode: this.indexToLetterCode(index),
        }));
    }

    /**
     * Detect renamed columns by comparing header rows
     */
    static detectRenames(
        storedColumns: SheetColumn[],
        currentHeaderRow: string[]
    ): SheetColumn[] {
        const updated = [...storedColumns];

        currentHeaderRow.forEach((currentHeader, index) => {
            const column = updated.find(col => col.letterCode === this.indexToLetterCode(index));

            if (column && column.displayName !== currentHeader) {
                // Header was renamed
                column.displayName = currentHeader;
                column.externallyRenamed = true;
            }
        });

        return updated;
    }

    /**
     * Convert 0-based index to Excel-style letter code (A, B, ..., Z, AA, AB, ...)
     */
    static indexToLetterCode(index: number): string {
        let code = '';
        let num = index;

        while (num >= 0) {
            code = String.fromCharCode(65 + (num % 26)) + code;
            num = Math.floor(num / 26) - 1;
        }

        return code;
    }

    /**
     * Get column letter code by UUID
     */
    static getLetterCodeByUUID(columns: SheetColumn[], uuid: string): string | null {
        const column = columns.find(col => col.uuid === uuid);
        return column?.letterCode ?? null;
    }

    /**
     * Get column UUID by display name
     */
    static getUUIDByDisplayName(columns: SheetColumn[], displayName: string): string | null {
        const column = columns.find(col => col.displayName === displayName);
        return column?.uuid ?? null;
    }
}

