 */
function randomNumber(min: number = 0, max: number = 9999, step: number = 1): number {
  const range = max - min;
  const steps = Math.floor(range / step);
  const randomSteps = Math.floor(Math.random() * (steps + 1));

  return min + (randomSteps * step);
}

