// ============================================================================
// BLOCK-SPECIFIC GENERATORS
// ============================================================================

/**
 * Generate random value for a text block
 */
function generateTextValue(step: ApiStep): string {
  const config = step.config as { variant?: 'short' | 'long' | 'text' } | undefined;

  // Check variant for advanced mode
  if (config?.variant === 'long') {
    return randomLongText();
  }

  // Legacy types
  if (step.type === 'long_text') {
    return randomLongText();
  }

  return randomShortText();
}

/**
 * Generate random value for a boolean block
 */
function generateBooleanValue(step: ApiStep): boolean | string {
  const config = step.config as BooleanAdvancedConfig | undefined;
  const value = randomBoolean();

  // Advanced mode: check if storing as alias
  if (config?.storeAsBoolean === false && config?.trueAlias && config?.falseAlias) {
    return value ? config.trueAlias : config.falseAlias;
  }

  return value;
}

/**
 * Generate random value for a choice block
 */
function generateChoiceValue(step: ApiStep): string | string[] {
  const config = step.config as ChoiceAdvancedConfig | undefined;

  // Handle advanced mode
  if (config?.options && Array.isArray(config.options)) {
    const options = config.options as Array<{ id: string; alias?: string }>;

    if (config.allowMultiple) {
      // Multiple selection: pick 1-3 random options
      const count = Math.min(
        Math.floor(Math.random() * 3) + 1,
        options.length
      );

      // Unique random selection
      const shuffled = [...options].sort(() => 0.5 - Math.random());
      const selectedOpts = shuffled.slice(0, count);

      return selectedOpts.map(opt => opt.alias || opt.id);
    } else {
      // Single selection
      const option = options[Math.floor(Math.random() * options.length)];
      return option.alias || option.id;
    }
  }

  // Legacy mode (simple string arrays)
  if (Array.isArray(config?.options)) {
    // Legacy support: options can be string[] despite type definition
    const options = config.options as unknown as string[];

    if (step.type === 'multiple_choice') {
      // Multiple selection
      const count = Math.min(
        Math.floor(Math.random() * 3) + 1,
        options.length
      );

      // Unique random selection
      const shuffled = [...options].sort(() => 0.5 - Math.random());
      return shuffled.slice(0, count);
    } else {
      // Single selection
      return options[Math.floor(Math.random() * options.length)];
    }
  }

  // Fallback
  return 'Option 1';
}

/**
 * Generate random value for a scale block
 */
function generateScaleValue(step: ApiStep): number {
  const config = step.config as ScaleConfig | undefined;

  const min = config?.min ?? 1;
  const max = config?.max ?? 10;
  const stepSize = config?.step ?? 1;

  return randomNumber(min, max, stepSize);
}

/**
 * Generate random value for a number block
 */
function generateNumberValue(step: ApiStep): number {
  const config = step.config as NumberConfig | undefined;

  const min = config?.min ?? 0;
  const max = config?.max ?? 9999;
  const stepSize = config?.step ?? 1;

  return randomNumber(min, max, stepSize);
}

/**
 * Generate random value for a currency block
 */
function generateCurrencyValue(step: ApiStep): number {
  const config = step.config as CurrencyConfig | undefined;

  const min = config?.min ?? 0;
  const max = config?.max ?? 10000;
  const allowDecimal = config?.allowDecimal ?? true;

  return randomCurrency(min, max, allowDecimal);
}

/**
 * Generate random value for an address block
 */
function generateAddressValue(step: ApiStep): Record<string, string> {
  const config = step.config as AddressConfig | undefined;

  return {
    street: randomStreet(),
    city: randomCity(),
    state: randomState(),
    zip: randomZip(),
  };
}

/**
 * Generate random value for a multi-field block
 */
function generateMultiFieldValue(step: ApiStep): Record<string, string | number> {
  const config = step.config as MultiFieldConfig | undefined;

  // Handle predefined layouts
  if (config?.layout === 'first_last') {
    return {
      first: randomFirstName(),
      last: randomLastName(),
    };
  }

  if (config?.layout === 'contact') {
    return {
      email: randomEmail(),
      phone: randomPhone(),
    };
  }

  if (config?.layout === 'date_range') {
    const start = randomDate();
    const startDate = new Date(start);
    startDate.setDate(startDate.getDate() + Math.floor(Math.random() * 30) + 1);
    const end = startDate.toISOString().split('T')[0];

    return {
      start,
      end,
    };
  }

  // Custom fields
  if (config?.fields && Array.isArray(config.fields)) {
    const result: Record<string, string | number> = {};

    for (const field of config.fields) {
      switch (field.type) {
        case 'text':
          result[field.key] = randomShortText();
          break;
        case 'email':
          result[field.key] = randomEmail();
          break;
        case 'phone':
          result[field.key] = randomPhone();
          break;
        case 'date':
          result[field.key] = randomDate();
          break;
        case 'number':
          result[field.key] = randomNumber();
          break;
        default:
          result[field.key] = randomShortText();
      }
    }

    return result;
  }

  // Fallback
  return {
    value: randomShortText(),
  };
}

// ============================================================================
// MAIN GENERATOR FUNCTION
// ============================================================================

type BlockValue = string | number | boolean | string[] | object | undefined;

/**
 * Generate random value for a single block/step
 *
 * @param step - The step definition
 * @returns Random value appropriate for the step type
 */
export function generateRandomValueForBlock(step: ApiStep): BlockValue {
  try {
    // Skip display blocks and JS blocks (no user input)
    if (step.type === 'display' || step.type === 'js_question' || step.type === 'computed') {
      return undefined;
    }

    // Text blocks
    if (step.type === 'short_text' || step.type === 'long_text' || step.type === 'text') {
      return generateTextValue(step);
    }

    // Boolean blocks
    if (step.type === 'yes_no' || step.type === 'true_false' || step.type === 'boolean') {
      return generateBooleanValue(step);
    }

    // Validated inputs
    if (step.type === 'email') {
      return randomEmail();
    }

    if (step.type === 'phone') {
      return randomPhone();
    }

    if (step.type === 'website') {
      return randomWebsite();
    }

    // Date/Time blocks
    if (step.type === 'date') {
      return randomDate();
    }

    if (step.type === 'time') {
      return randomTime();
    }

    if (step.type === 'date_time') {
      return randomDateTime();
    }

    // Choice blocks
    if (step.type === 'radio' || step.type === 'multiple_choice' || step.type === 'choice') {
      return generateChoiceValue(step);
    }

    // Numeric blocks
    if (step.type === 'number') {
      return generateNumberValue(step);
    }

    if (step.type === 'currency') {
      return generateCurrencyValue(step);
    }

    if (step.type === 'scale') {
      return generateScaleValue(step);
    }

    // Complex blocks
    if (step.type === 'address') {
      return generateAddressValue(step);
    }

    if (step.type === 'multi_field') {
      return generateMultiFieldValue(step);
    }

    // Fallback for unknown types
    // console.warn(`[RandomFill] Unknown block type: ${step.type}`);
    return randomShortText();

  } catch (error) {
    // console.error('[RandomFill] Error generating random value for block:', step.id, error);
    return randomShortText(); // Safe fallback
  }
}

/**
 * Generate random values for all blocks in a workflow
 *
 * @param steps - Array of all steps in the workflow
 * @returns Map of stepId -> random value
 */
export function generateRandomValuesForWorkflow(steps: ApiStep[]): Record<string, BlockValue> {
  const values: Record<string, BlockValue> = {};

  for (const step of steps) {
    const value = generateRandomValueForBlock(step);

    // Only store if value is defined (skip display blocks, etc.)
    if (value !== undefined) {
      values[step.id] = value;
    }
  }

  return values;
}

/**
 * Generate random values for specific steps (e.g., current page)
 *
 * @param steps - Array of steps to fill
 * @returns Map of stepId -> random value
 */
export function generateRandomValuesForSteps(steps: ApiStep[]): Record<string, BlockValue> {
  return generateRandomValuesForWorkflow(steps);
}

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useLocation } from "wouter";

import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";

/**
 * Creates a complete sample workflow with multiple sections, steps, logic, and blocks.
 * Demonstrates: Pages, Questions, Variables, Logic, and Documents.
 */
export function useCreateSampleWorkflow() {
    const { toast } = useToast();
    const [, navigate] = useLocation();
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: async () => {
            // 1. Create Workflow
            const workflowRes = await apiRequest("POST", "/api/workflows", {
                title: "Sample: Customer Intake",
                description: "A demo workflow showing forms, logic, and document generation. Feel free to edit or delete!",
            });
            const workflow = await workflowRes.json();
            const workflowId = workflow.id;

            // 2. Create Page 1: Contact Info
            const p1Res = await apiRequest("POST", "/api/sections", {
                workflowId,
                title: "Contact Information",
                order: 0,
            });
            const p1 = await p1Res.json();

            // P1 - Step 1: Name
            await apiRequest("POST", "/api/steps", {
                sectionId: p1.id,
                type: "short_text",
                title: "What is your full name?",
                alias: "full_name", // Variable alias
                required: true,
                order: 0,
                config: { placeholder: "e.g. Jane Doe" }
            });

            // P1 - Step 2: Email
            await apiRequest("POST", "/api/steps", {
                sectionId: p1.id,
                type: "email",
                title: "Email Address",
                alias: "email",
                required: true,
                order: 1,
                config: { placeholder: "jane@example.com" }
            });

            // 3. Create Page 2: Service Selection (Conditional)
            const p2Res = await apiRequest("POST", "/api/sections", {
                workflowId,
                title: "Service Preferences",
                order: 1,
            });
            const p2 = await p2Res.json();

            // P2 - Step 1: Service Type
            await apiRequest("POST", "/api/steps", {
                sectionId: p2.id,
                type: "single_choice",
                title: "Which service are you interested in?",
                alias: "service_type",
                required: true,
                order: 0,
                options: ["Consulting", "Development", "Design"],
                config: {}
            });

            // P2 - Step 2: Budget (Visible only if Development)
            await apiRequest("POST", "/api/steps", {
                sectionId: p2.id,
                type: "number",
                title: "Estimated Budget ($)",
                alias: "budget",
                required: false,
                order: 1,
                config: {},
                visibleIf: {
                    field: "service_type",
                    operator: "equals",
                    value: "Development"
                }
            });

            // 4. Create Logic Block (JS) - Auto-calculate tier
            // Note: Blocks are created via a separate endpoint, usually associated with a section or global?
            // Based on previous files, blocks seem to be separate entities.
            // Checking BlocksPanel implementation (hooks/useCreateBlock) -> /api/blocks
            // Let's add a PREFILL block at the start to set a default region

            await apiRequest("POST", "/api/blocks", {
                workflowId,
                type: "prefill",
                phase: "onRunStart",
                order: 0,
                enabled: true,
                config: {
                    mode: "static",
                    staticMap: { "region": "US-East" }
                }
            });

            // 5. Create Final Page
            const pFinalRes = await apiRequest("POST", "/api/sections", {
                workflowId,
                title: "Review & Submit",
                order: 2,
                config: {
                    finalBlock: true,
                    screenTitle: "All Done!",
                    markdownMessage: "# Thanks, {{full_name}}!\n\nWe will contact you at {{email}} regarding **{{service_type}}**.\n\nYour estimated budget is ${{budget}}.",
                    templates: []
                }
            });

            return workflow;
        },
        onSuccess: (workflow) => {
            toast({
                title: "Sample Created",
                description: "Welcome to your first workflow! Feel free to explore and edit.",
            });
            queryClient.invalidateQueries({ queryKey: ["workflows"] });
            // Navigate to builder
            navigate(`/workflows/${workflow.id}/builder`);
        },
        onError: (error: any) => {
            toast({
                title: "Error",
                description: "Failed to create sample workflow. Please try creating a new one manually.",
                variant: "destructive",
            });
        },
    });
}

