import { Loader2, CheckCircle, XCircle } from 'lucide-react';
import { useState, useEffect, useRef } from 'react';
import { useLocation, useRoute } from 'wouter';

import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { useToast } from '@/hooks/use-toast';
import { useAcceptInvite } from '@/hooks/useOrganizations';

export default function AcceptInvite() {
  const [, params] = useRoute('/invites/:token/accept');
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const acceptInvite = useAcceptInvite();

  const [status, setStatus] = useState<'loading' | 'success' | 'error'>('loading');
  const [orgInfo, setOrgInfo] = useState<{ orgId: string; orgName: string } | null>(null);
  const [errorMessage, setErrorMessage] = useState('');
  const hasAttemptedRef = useRef(false);

  useEffect(() => {
    const accept = async () => {
      const token = params?.token;

      if (!token) {
        setStatus('error');
        setErrorMessage('Invalid invitation link - missing token');
        return;
      }

      // Prevent duplicate accepts
      if (hasAttemptedRef.current) {
        return;
      }
      hasAttemptedRef.current = true;

      try {
        const result = await acceptInvite.mutateAsync(token);
        setOrgInfo(result);
        setStatus('success');
        toast({
          title: 'Success!',
          description: `You've joined ${result.orgName}`,
        });
      } catch (error: any) {
        setStatus('error');
        setErrorMessage(error.message || 'Failed to accept invitation');
        toast({
          title: 'Failed to accept invite',
          description: error.message || 'An error occurred',
          variant: 'destructive',
        });
      }
    };

    accept();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [params?.token]);

  return (
    <div className="min-h-screen flex items-center justify-center bg-muted/30 p-4">
      <Card className="w-full max-w-md">
        <CardHeader className="text-center">
          <CardTitle>Organization Invitation</CardTitle>
          <CardDescription>
            {status === 'loading' && 'Processing your invitation...'}
            {status === 'success' && 'Welcome to the team!'}
            {status === 'error' && 'Invitation Error'}
          </CardDescription>
        </CardHeader>
        <CardContent className="flex flex-col items-center space-y-4">
          {status === 'loading' && (
            <Loader2 className="h-12 w-12 animate-spin text-primary" />
          )}

          {status === 'success' && orgInfo && (
            <>
              <CheckCircle className="h-12 w-12 text-green-500" />
              <p className="text-center text-muted-foreground">
                You've successfully joined <strong>{orgInfo.orgName}</strong>
              </p>
              <Button asChild className="w-full">
                <a href={`/organizations/${orgInfo.orgId}`}>
                  Go to Organization
                </a>
              </Button>
            </>
          )}

          {status === 'error' && (
            <>
              <XCircle className="h-12 w-12 text-destructive" />
              <p className="text-center text-muted-foreground">{errorMessage}</p>
              <Button asChild variant="outline" className="w-full">
                <a href="/organizations">
                  View My Organizations
                </a>
              </Button>
            </>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Loader2, Save, RotateCcw, Bot, BarChart3 } from "lucide-react";
import { useState, useEffect } from "react";

import { AIPerformanceMonitor } from "@/components/admin/AIPerformanceMonitor";
import Header from "@/components/layout/Header";
import Sidebar from "@/components/layout/Sidebar";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Textarea } from "@/components/ui/textarea";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/hooks/useAuth";
import { apiRequest } from "@/lib/queryClient";

interface AiSettingsResponse {
    settings?: { systemPrompt: string };
    defaultPrompt?: string;
}

export default function AdminAiSettings() {
    const { toast } = useToast();
    const { isAuthenticated, isLoading: authLoading, user } = useAuth();
    const queryClient = useQueryClient();
    const [prompt, setPrompt] = useState("");

    // Fetch current settings
    const { data, isLoading, error } = useQuery<AiSettingsResponse>({
        queryKey: ["/api/admin/ai-settings"],
        enabled: !!isAuthenticated && user?.role === 'admin',
    });

    // Update effect when data loads
    useEffect(() => {
        if (data?.settings?.systemPrompt) {
            setPrompt(data.settings.systemPrompt);
        } else if (data?.defaultPrompt) {
            setPrompt(data.defaultPrompt);
        }
    }, [data]);

    // Save mutation
    const saveMutation = useMutation({
        mutationFn: async (newPrompt: string) => {
            const res = await apiRequest("PUT", "/api/admin/ai-settings", { systemPrompt: newPrompt });
            return res.json();
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["/api/admin/ai-settings"] });
            toast({
                title: "Settings Saved",
                description: "Global AI system prompt has been updated.",
            });
        },
        onError: (err: Error) => {
            toast({
                title: "Error",
                description: err.message,
                variant: "destructive",
            });
        },
    });

    const handleReset = () => {
        if (data?.defaultPrompt) {
            if (confirm("Are you sure you want to reset to the default system prompt? Unsaved changes will be lost.")) {
                setPrompt(data.defaultPrompt);
            }
        }
    };

    const handleSave = () => {
        if (prompt.length < 10) {
            toast({
                title: "Invalid Prompt",
                description: "Prompt must be at least 10 characters long.",
                variant: "destructive",
            });
            return;
        }
        saveMutation.mutate(prompt);
    };

    // Auth protection
    if (authLoading) {return null;}
    if (!isAuthenticated || user?.role !== 'admin') {
        return (
            <div className="flex h-screen items-center justify-center">
                <p>Access Denied</p>
            </div>
        );
    }

    return (
        <div className="flex h-screen bg-background">
            <Sidebar />
            <main className="flex-1 flex flex-col overflow-hidden">
                <Header
                    title="AI Settings"
                    description="Manage global AI configuration"
                />

                <div className="flex-1 overflow-auto p-6">
                    <Tabs defaultValue="prompt" className="space-y-6">
                        <TabsList>
                            <TabsTrigger value="prompt" className="flex items-center gap-2">
                                <Bot className="h-4 w-4" />
                                System Prompt
                            </TabsTrigger>
                            <TabsTrigger value="performance" className="flex items-center gap-2">
                                <BarChart3 className="h-4 w-4" />
                                AI Performance
                            </TabsTrigger>
                        </TabsList>

                        <TabsContent value="prompt" className="space-y-6">
                            <Card>
                                <CardHeader>
                                    <div className="flex items-center justify-between">
                                        <div>
                                            <CardTitle className="flex items-center gap-2">
                                                <Bot className="h-5 w-5 text-primary" />
                                                Global System Prompt
                                            </CardTitle>
                                            <CardDescription className="mt-2">
                                                This prompt governs the behavior of the AI workflow assistant.
                                                Use <code>{`{{interviewerRole}}`}</code>, <code>{`{{readingLevel}}`}</code>, and <code>{`{{tone}}`}</code> placeholders for dynamic preferences.
                                            </CardDescription>
                                        </div>
                                        <div className="flex gap-2">
                                            <Button variant="outline" onClick={() => { void handleReset(); }} disabled={isLoading || saveMutation.isPending}>
                                                <RotateCcw className="mr-2 h-4 w-4" />
                                                Reset to Default
                                            </Button>
                                            <Button onClick={() => { void handleSave(); }} disabled={isLoading || saveMutation.isPending}>
                                                {saveMutation.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Save className="mr-2 h-4 w-4" />}
                                                Save Changes
                                            </Button>
                                        </div>
                                    </div>
                                </CardHeader>
                                <CardContent>
                                    {isLoading ? (
                                        <div className="flex justify-center p-12">
                                            <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
                                        </div>
                                    ) : (
                                        <div className="space-y-4">
                                            <Textarea
                                                value={prompt}
                                                onChange={(e) => { void setPrompt(e.target.value); }}
                                                className="min-h-[500px] font-mono text-sm leading-relaxed"
                                                placeholder="Enter system prompt..."
                                            />
                                            <p className="text-sm text-muted-foreground text-right">
                                                {prompt.length} characters
                                            </p>
                                        </div>
                                    )}
                                </CardContent>
                            </Card>
                        </TabsContent>

                        <TabsContent value="performance" className="space-y-6">
                            <AIPerformanceMonitor />
                        </TabsContent>
                    </Tabs>
                </div>
            </main>
        </div>
    );
}

import { useQuery } from "@tanstack/react-query";
import { Download, Search, ChevronLeft, ChevronRight } from "lucide-react";
import { useState, useEffect } from "react";

import Header from "@/components/layout/Header";
import Sidebar from "@/components/layout/Sidebar";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/hooks/useAuth";
import { getQueryFn } from "@/lib/queryClient";


interface ActivityLog {
  id: string;
  timestamp: string;
  event: string;
  actorId?: string | null;
  actorEmail?: string | null;
  entityType?: string | null;
  entityId?: string | null;
  status?: string | null;
  ipAddress?: string | null;
  userAgent?: string | null;
  metadata?: any;
}

interface ActivityLogResult {
  rows: ActivityLog[];
  total: number;
}

export default function AdminLogs() {
  const { toast } = useToast();
  const { isAuthenticated, isLoading: authLoading } = useAuth();

  // Filter state
  const [searchQuery, setSearchQuery] = useState("");
  const [eventFilter, setEventFilter] = useState("");
  const [actorFilter, setActorFilter] = useState("");
  const [statusFilter, setStatusFilter] = useState("");
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");
  const [sortOrder, setSortOrder] = useState<"timestamp_desc" | "timestamp_asc">("timestamp_desc");

  // Pagination state
  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState(50);
  const limit = pageSize;

  // Build query params
  const queryParams = new URLSearchParams();
  if (searchQuery) {queryParams.set("q", searchQuery);}
  if (eventFilter) {queryParams.set("event", eventFilter);}
  if (actorFilter) {queryParams.set("actor", actorFilter);}
  if (statusFilter) {queryParams.set("status", statusFilter);}
  if (fromDate) {queryParams.set("from", fromDate);}
  if (toDate) {queryParams.set("to", toDate);}
  queryParams.set("sort", sortOrder);
  queryParams.set("limit", String(limit));
  queryParams.set("offset", String(page * limit));

  // Fetch logs
  const { data, isLoading, error } = useQuery<ActivityLogResult>({
    queryKey: [`/api/admin/logs?${queryParams.toString()}`],
    queryFn: getQueryFn({ on401: "returnNull" }),
    enabled: !!isAuthenticated,
    retry: false,
  });

  // Redirect if not authenticated
  useEffect(() => {
    if (!authLoading && !isAuthenticated) {
      toast({
        title: "Unauthorized",
        description: "You must be logged in to access this page",
        variant: "destructive",
      });
      setTimeout(() => {
        window.location.href = "/";
      }, 500);
    }
  }, [isAuthenticated, authLoading, toast]);

  // Show error if access denied (not admin)
  useEffect(() => {
    if (error) {
      // Only show access denied for actual 403 errors
      const is403 = error instanceof Error && error.message.includes("403");
      if (is403) {
        toast({
          title: "Access Denied",
          description: "You must be an admin to access this page",
          variant: "destructive",
        });
        setTimeout(() => {
          window.location.href = "/";
        }, 1000);
      } else {
        // For other errors, just log them
        console.error("Error loading activity logs:", error);
      }
    }
  }, [error, toast]);

  // Reset to first page when filters or page size change
  useEffect(() => {
    setPage(0);
  }, [searchQuery, eventFilter, actorFilter, statusFilter, fromDate, toDate, sortOrder, pageSize]);

  if (authLoading || !isAuthenticated || error) {
    return null;
  }

  const logs = data?.rows ?? [];
  const total = data?.total || 0;
  const totalPages = Math.ceil(total / limit);
  const hasNextPage = page < totalPages - 1;
  const hasPrevPage = page > 0;

  const formatTimestamp = (timestamp: string) => {
    const date = new Date(timestamp);
    return date.toLocaleString('en-US', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      hour12: false
    });
  };

  const getStatusBadgeClass = (status?: string | null) => {
    if (!status) {return "bg-gray-100 text-gray-700";}
    switch (status.toLowerCase()) {
      case "error":
        return "bg-red-100 text-red-700";
      case "success":
        return "bg-green-100 text-green-700";
      case "warn":
      case "warning":
        return "bg-yellow-100 text-yellow-700";
      default:
        return "bg-blue-100 text-blue-700";
    }
  };

  const handleExport = () => {
    const exportParams = new URLSearchParams();
    if (searchQuery) {exportParams.set("q", searchQuery);}
    if (eventFilter) {exportParams.set("event", eventFilter);}
    if (actorFilter) {exportParams.set("actor", actorFilter);}
    if (statusFilter) {exportParams.set("status", statusFilter);}
    if (fromDate) {exportParams.set("from", fromDate);}
    if (toDate) {exportParams.set("to", toDate);}
    exportParams.set("sort", sortOrder);

    window.location.href = `/api/admin/logs/export?${exportParams.toString()}`;
  };

  return (
    <div className="flex h-screen bg-background">
      <Sidebar />

      <main className="flex-1 flex flex-col overflow-hidden">
        <Header
          title="Activity Logs"
          description="View and filter system activity events"
        />

        <div className="flex-1 overflow-auto p-6 space-y-4">
          {/* Filters Section */}
          <Card>
            <CardContent className="p-4">
              <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-6 gap-3">
                {/* Search */}
                <div className="lg:col-span-2 relative">
                  <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-500" />
                  <Input
                    placeholder="Search events, actors..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="pl-10"
                  />
                </div>

                {/* Event Filter */}
                <Input
                  placeholder="Event type"
                  value={eventFilter}
                  onChange={(e) => setEventFilter(e.target.value)}
                />

                {/* Actor Filter */}
                <Input
                  placeholder="Actor (email/ID)"
                  value={actorFilter}
                  onChange={(e) => setActorFilter(e.target.value)}
                />

                {/* Date From */}
                <Input
                  type="date"
                  placeholder="From date"
                  value={fromDate}
                  onChange={(e) => setFromDate(e.target.value)}
                />

                {/* Date To */}
                <Input
                  type="date"
                  placeholder="To date"
                  value={toDate}
                  onChange={(e) => setToDate(e.target.value)}
                />
              </div>
            </CardContent>
          </Card>

          {/* Actions Bar */}
          <div className="flex items-center justify-between">
            <div className="text-sm text-gray-600">
              {isLoading ? "Loading..." : `${total.toLocaleString()} events`}
            </div>
            <div className="flex items-center gap-2">
              <select
                value={pageSize}
                onChange={(e) => setPageSize(Number(e.target.value))}
                className="border rounded-lg px-3 py-2 text-sm bg-white"
              >
                <option value="10">10 per page</option>
                <option value="50">50 per page</option>
                <option value="100">100 per page</option>
                <option value="1000">1000 per page</option>
              </select>
              <select
                value={sortOrder}
                onChange={(e) => setSortOrder(e.target.value as any)}
                className="border rounded-lg px-3 py-2 text-sm bg-white"
              >
                <option value="timestamp_desc">Newest first</option>
                <option value="timestamp_asc">Oldest first</option>
              </select>
              <Button onClick={handleExport} variant="outline" size="sm">
                <Download className="h-4 w-4 mr-2" />
                Export CSV
              </Button>
            </div>
          </div>

          {/* Logs Table */}
          <Card>
            <CardContent className="p-0">
              <div className="overflow-auto">
                <table className="min-w-[1400px] w-full text-sm">
                  <thead className="bg-gray-50 border-b">
                    <tr className="text-left">
                      <th className="px-4 py-3 font-medium text-gray-700">Time</th>
                      <th className="px-4 py-3 font-medium text-gray-700">Event</th>
                      <th className="px-4 py-3 font-medium text-gray-700">Actor Email</th>
                      <th className="px-4 py-3 font-medium text-gray-700">Entity</th>
                      <th className="px-4 py-3 font-medium text-gray-700">IP Address</th>
                      <th className="px-4 py-3 font-medium text-gray-700">User Agent</th>
                      <th className="px-4 py-3 font-medium text-gray-700">Status</th>
                      <th className="px-4 py-3 font-medium text-gray-700">Metadata</th>
                    </tr>
                  </thead>
                  <tbody>
                    {logs.map((log) => (
                      <tr key={log.id} className="border-b hover:bg-gray-50">
                        <td className="px-4 py-3 whitespace-nowrap text-gray-700">
                          {formatTimestamp(log.timestamp)}
                        </td>
                        <td className="px-4 py-3 font-medium">
                          {log.event}
                        </td>
                        <td className="px-4 py-3">
                          {log.actorEmail ? (
                            <span className="font-medium">{log.actorEmail}</span>
                          ) : log.actorId ? (
                            <span className="text-xs text-gray-500">{log.actorId.substring(0, 8)}...</span>
                          ) : (
                            <span className="text-gray-400">ΓÇö</span>
                          )}
                        </td>
                        <td className="px-4 py-3">
                          {log.entityType && log.entityId ? (
                            <span className="text-xs">
                              {log.entityType}:{log.entityId.substring(0, 8)}...
                            </span>
                          ) : log.entityId ? (
                            <span className="text-xs">{log.entityId.substring(0, 8)}...</span>
                          ) : (
                            <span className="text-gray-400">ΓÇö</span>
                          )}
                        </td>
                        <td className="px-4 py-3 whitespace-nowrap text-xs">
                          {log.ipAddress || <span className="text-gray-400">ΓÇö</span>}
                        </td>
                        <td className="px-4 py-3 max-w-xs truncate text-xs" title={log.userAgent ?? ''}>
                          {log.userAgent || <span className="text-gray-400">ΓÇö</span>}
                        </td>
                        <td className="px-4 py-3">
                          <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium ${getStatusBadgeClass(log.status)}`}>
                            {log.status || "info"}
                          </span>
                        </td>
                        <td className="px-4 py-3 max-w-md">
                          {log.metadata ? (
                            <details className="cursor-pointer">
                              <summary className="text-xs text-blue-600 hover:text-blue-800">
                                View JSON
                              </summary>
                              <pre className="mt-2 text-xs text-gray-600 whitespace-pre-wrap break-words bg-gray-50 p-2 rounded">
                                {JSON.stringify(log.metadata, null, 2)}
                              </pre>
                            </details>
                          ) : (
                            <span className="text-gray-400">ΓÇö</span>
                          )}
                        </td>
                      </tr>
                    ))}
                    {logs.length === 0 && !isLoading && (
                      <tr>
                        <td colSpan={8} className="px-4 py-8 text-center text-gray-500">
                          No activity logs found
                        </td>
                      </tr>
                    )}
                    {isLoading && (
                      <tr>
                        <td colSpan={8} className="px-4 py-8 text-center text-gray-500">
                          Loading...
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </CardContent>
          </Card>

          {/* Pagination */}
          {total > 0 && (
            <div className="flex items-center justify-between">
              <div className="text-sm text-gray-600">
                Showing {page * limit + 1} - {Math.min((page + 1) * limit, total)} of {total.toLocaleString()}
              </div>
              <div className="flex items-center gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setPage(p => p - 1)}
                  disabled={!hasPrevPage}
                >
                  <ChevronLeft className="h-4 w-4 mr-1" />
                  Previous
                </Button>
                <span className="text-sm text-gray-600">
                  Page {page + 1} of {totalPages}
                </span>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setPage(p => p + 1)}
                  disabled={!hasNextPage}
                >
                  Next
                  <ChevronRight className="h-4 w-4 ml-1" />
                </Button>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Users, Shield, ArrowLeft, ChevronUp, ChevronDown, Eye } from "lucide-react";
import { useEffect, useState } from "react";
import { Link } from "wouter";

import Header from "@/components/layout/Header";
import Sidebar from "@/components/layout/Sidebar";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/hooks/useAuth";
import { apiRequest } from "@/lib/queryClient";

interface User {
  id: string;
  email: string;
  firstName: string | null;
  lastName: string | null;
  profileImageUrl: string | null;
  role: 'admin' | 'creator';
  createdAt: string;
  workflowCount: number;
}

export default function AdminUsers() {
  const { toast } = useToast();
  const { isAuthenticated, isLoading: authLoading } = useAuth();
  const queryClient = useQueryClient();
  const [updatingUserId, setUpdatingUserId] = useState<string | null>(null);

  const { data: users, isLoading: usersLoading, error } = useQuery<User[]>({
    queryKey: ["/api/admin/users"],
    enabled: !!isAuthenticated,
    retry: false,
  });

  // Redirect if not authenticated
  useEffect(() => {
    if (!authLoading && !isAuthenticated) {
      toast({
        title: "Unauthorized",
        description: "You must be logged in",
        variant: "destructive",
      });
      setTimeout(() => {
        window.location.href = "/";
      }, 500);
    }
  }, [isAuthenticated, authLoading, toast]);

  // Show error if access denied
  useEffect(() => {
    if (error) {
      toast({
        title: "Access Denied",
        description: "You must be an admin to access this page",
        variant: "destructive",
      });
      setTimeout(() => {
        window.location.href = "/";
      }, 1000);
    }
  }, [error, toast]);

  const updateRoleMutation = useMutation({
    mutationFn: async ({ userId, role }: { userId: string; role: 'admin' | 'creator' }) => {
      return apiRequest("PUT", `/api/admin/users/${userId}/role`, { role });
    },
    onSuccess: (data: any) => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/users"] });
      queryClient.invalidateQueries({ queryKey: ["/api/admin/stats"] });
      toast({
        title: "Success",
        description: data.message || "User role updated successfully",
      });
      setUpdatingUserId(null);
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to update user role",
        variant: "destructive",
      });
      setUpdatingUserId(null);
    },
  });

  const handlePromoteToAdmin = (userId: string) => {
    setUpdatingUserId(userId);
    updateRoleMutation.mutate({ userId, role: 'admin' });
  };

  const handleDemoteToCreator = (userId: string) => {
    setUpdatingUserId(userId);
    updateRoleMutation.mutate({ userId, role: 'creator' });
  };

  if (authLoading || !isAuthenticated || error) {
    return null;
  }

  return (
    <div className="flex h-screen bg-background">
      <Sidebar />

      <main className="flex-1 flex flex-col overflow-hidden">
        <Header
          title="User Management"
          description="Manage user accounts and permissions"
          actions={
            <Link href="/admin">
              <Button variant="outline">
                <ArrowLeft className="mr-2 h-4 w-4" />
                Back to Admin
              </Button>
            </Link>
          }
        />

        <div className="flex-1 overflow-auto p-6">
          {usersLoading ? (
            <div className="space-y-4">
              {[1, 2, 3, 4].map((i) => (
                <Card key={i} className="animate-pulse">
                  <CardContent className="p-6">
                    <div className="h-16 bg-muted rounded"></div>
                  </CardContent>
                </Card>
              ))}
            </div>
          ) : users && users.length > 0 ? (
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Users className="h-5 w-5" />
                  All Users ({users.length})
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="overflow-x-auto">
                  <table className="w-full">
                    <thead>
                      <tr className="border-b border-border">
                        <th className="text-left p-3 text-sm font-medium text-muted-foreground">User</th>
                        <th className="text-left p-3 text-sm font-medium text-muted-foreground">Email</th>
                        <th className="text-left p-3 text-sm font-medium text-muted-foreground">Role</th>
                        <th className="text-left p-3 text-sm font-medium text-muted-foreground">Workflows</th>
                        <th className="text-left p-3 text-sm font-medium text-muted-foreground">Joined</th>
                        <th className="text-right p-3 text-sm font-medium text-muted-foreground">Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {users.map((user) => (
                        <tr key={user.id} className="border-b border-border hover:bg-accent/50">
                          <td className="p-3">
                            <div className="flex items-center gap-3">
                              {user.profileImageUrl ? (
                                <img
                                  src={user.profileImageUrl}
                                  alt={user.firstName || user.email}
                                  className="w-10 h-10 rounded-full object-cover"
                                />
                              ) : (
                                <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center">
                                  <Users className="h-5 w-5 text-primary" />
                                </div>
                              )}
                              <div>
                                <div className="font-medium">
                                  {user.firstName || user.lastName
                                    ? `${user.firstName ?? ''} ${user.lastName ?? ''}`.trim()
                                    : 'User'}
                                </div>
                                <div className="text-xs text-muted-foreground">
                                  ID: {user.id.slice(-8)}
                                </div>
                              </div>
                            </div>
                          </td>
                          <td className="p-3 text-sm">{user.email}</td>
                          <td className="p-3">
                            {user.role === 'admin' ? (
                              <Badge className="bg-purple-600">
                                <Shield className="h-3 w-3 mr-1" />
                                Admin
                              </Badge>
                            ) : (
                              <Badge variant="secondary">Creator</Badge>
                            )}
                          </td>
                          <td className="p-3 text-sm">{user.workflowCount}</td>
                          <td className="p-3 text-sm text-muted-foreground">
                            {new Date(user.createdAt).toLocaleDateString()}
                          </td>
                          <td className="p-3">
                            <div className="flex items-center justify-end gap-2">
                              <Link href={`/admin/users/${user.id}/surveys`}>
                                <Button variant="ghost" size="sm">
                                  <Eye className="h-4 w-4 mr-1" />
                                  View Workflows
                                </Button>
                              </Link>

                              {user.role === 'creator' ? (
                                <AlertDialog>
                                  <AlertDialogTrigger asChild>
                                    <Button
                                      variant="outline"
                                      size="sm"
                                      disabled={updatingUserId === user.id}
                                    >
                                      <ChevronUp className="h-4 w-4 mr-1" />
                                      Promote
                                    </Button>
                                  </AlertDialogTrigger>
                                  <AlertDialogContent>
                                    <AlertDialogHeader>
                                      <AlertDialogTitle>Promote to Admin</AlertDialogTitle>
                                      <AlertDialogDescription>
                                        Are you sure you want to promote {user.email} to admin?
                                        This will give them full administrative access to the system.
                                      </AlertDialogDescription>
                                    </AlertDialogHeader>
                                    <AlertDialogFooter>
                                      <AlertDialogCancel>Cancel</AlertDialogCancel>
                                      <AlertDialogAction
                                        onClick={() => { void handlePromoteToAdmin(user.id); }}
                                        className="bg-purple-600 hover:bg-purple-700"
                                      >
                                        Promote to Admin
                                      </AlertDialogAction>
                                    </AlertDialogFooter>
                                  </AlertDialogContent>
                                </AlertDialog>
                              ) : (
                                <AlertDialog>
                                  <AlertDialogTrigger asChild>
                                    <Button
                                      variant="outline"
                                      size="sm"
                                      disabled={updatingUserId === user.id}
                                    >
                                      <ChevronDown className="h-4 w-4 mr-1" />
                                      Demote
                                    </Button>
                                  </AlertDialogTrigger>
                                  <AlertDialogContent>
                                    <AlertDialogHeader>
                                      <AlertDialogTitle>Demote to Creator</AlertDialogTitle>
                                      <AlertDialogDescription>
                                        Are you sure you want to demote {user.email} to creator?
                                        This will remove their administrative access.
                                      </AlertDialogDescription>
                                    </AlertDialogHeader>
                                    <AlertDialogFooter>
                                      <AlertDialogCancel>Cancel</AlertDialogCancel>
                                      <AlertDialogAction
                                        onClick={() => { void handleDemoteToCreator(user.id); }}
                                        className="bg-destructive hover:bg-destructive/90"
                                      >
                                        Demote to Creator
                                      </AlertDialogAction>
                                    </AlertDialogFooter>
                                  </AlertDialogContent>
                                </AlertDialog>
                              )}
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </CardContent>
            </Card>
          ) : (
            <Card>
              <CardContent className="p-12 text-center">
                <Users className="mx-auto h-12 w-12 text-muted-foreground mb-4" />
                <h3 className="text-lg font-semibold mb-2">No Users Found</h3>
                <p className="text-muted-foreground">There are no users in the system yet.</p>
              </CardContent>
            </Card>
          )}
        </div>
      </main>
    </div>
  );
}

/**
 * Stage 17: Branding Settings Page
 *
 * Allows users to configure tenant branding including logo, colors, dark mode,
 * header text, and email sender information.
 */
import {
  Palette,
  Upload,
  Moon,
  Sun,
  Mail,
  User,
  MessageSquare,
  Loader2,
  Save,
  RotateCcw,
  Eye,
  Globe,
  ExternalLink,
} from 'lucide-react';
import { useState, useEffect } from 'react';
import { useParams, Link } from 'wouter';

import BrandingPreview from '@/components/branding/BrandingPreview';
import Header from '@/components/layout/Header';
import Sidebar from '@/components/layout/Sidebar';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { Textarea } from '@/components/ui/textarea';
import { useToast } from '@/hooks/use-toast';
import { useAuth } from '@/hooks/useAuth';
import { isValidHexColor, normalizeHexColor } from '@/lib/colorUtils';
import { brandingAPI, type TenantBranding } from '@/lib/vault-api';
export default function BrandingSettingsPage() {
  const { id: projectId } = useParams<{ id: string }>();
  const { user, isAuthenticated, isLoading: authLoading } = useAuth();
  const { toast } = useToast();
  const tenantId = user?.tenantId;
  // Local form state
  const [formData, setFormData] = useState<Partial<TenantBranding>>({
    logoUrl: '',
    primaryColor: '',
    accentColor: '',
    darkModeEnabled: false,
    intakeHeaderText: '',
    emailSenderName: '',
    emailSenderAddress: '',
  });
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);
  const [showPreview, setShowPreview] = useState(false);
  // Load initial branding
  useEffect(() => {
    if (tenantId) {
      loadBranding();
    }
  }, [tenantId]);
  const loadBranding = async () => {
    if (!tenantId) {return;}
    setIsLoading(true);
    try {
      const { branding } = await brandingAPI.getBranding(tenantId);
      if (branding) {
        setFormData(branding);
      }
    } catch (error) {
      console.error('Failed to load branding:', error);
      toast({
        title: 'Error',
        description: 'Failed to load branding settings',
        variant: 'destructive',
      });
    } finally {
      setIsLoading(false);
    }
  };
  const handleChange = (field: keyof TenantBranding, value: any) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
    setHasUnsavedChanges(true);
  };
  const handleColorChange = (field: 'primaryColor' | 'accentColor', value: string) => {
    // Only update if valid hex or empty
    if (value === '' || isValidHexColor(value)) {
      const normalized = value ? normalizeHexColor(value) : '';
      handleChange(field, normalized);
    }
  };
  const handleSave = async () => {
    if (!tenantId) {
      toast({
        title: 'Error',
        description: 'No tenant ID found',
        variant: 'destructive',
      });
      return;
    }
    // Validate colors
    if (formData.primaryColor && !isValidHexColor(formData.primaryColor)) {
      toast({
        title: 'Invalid Color',
        description: 'Primary color must be a valid hex color (e.g., #FF5733)',
        variant: 'destructive',
      });
      return;
    }
    if (formData.accentColor && !isValidHexColor(formData.accentColor)) {
      toast({
        title: 'Invalid Color',
        description: 'Accent color must be a valid hex color (e.g., #33FF57)',
        variant: 'destructive',
      });
      return;
    }
    setIsSaving(true);
    try {
      await brandingAPI.updateBranding(tenantId, formData);
      setHasUnsavedChanges(false);
      toast({
        title: 'Success',
        description: 'Branding settings saved successfully',
      });
    } catch (error: any) {
      console.error('Failed to save branding:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to save branding settings',
        variant: 'destructive',
      });
    } finally {
      setIsSaving(false);
    }
  };
  const handleReset = () => {
    loadBranding();
    setHasUnsavedChanges(false);
    toast({
      title: 'Reset',
      description: 'Changes have been discarded',
    });
  };
  // Redirect if not authenticated
  useEffect(() => {
    if (!authLoading && !isAuthenticated) {
      toast({
        title: 'Unauthorized',
        description: 'Please log in to access settings.',
        variant: 'destructive',
      });
      setTimeout(() => {
        window.location.href = '/';
      }, 500);
    }
  }, [isAuthenticated, authLoading, toast]);
  if (authLoading || isLoading) {
    return (
      <div className="flex h-screen bg-background">
        <Sidebar />
        <div className="flex-1 flex flex-col">
          <Header title="Branding Settings" />
          <div className="flex-1 flex items-center justify-center">
            <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
          </div>
        </div>
      </div>
    );
  }
  return (
    <div className="flex h-screen bg-background">
      <Sidebar />
      <div className="flex-1 flex flex-col overflow-hidden">
        <Header title="Branding Settings" />
        <main className="flex-1 overflow-y-auto p-6">
          <div className="max-w-4xl mx-auto space-y-6">
            {/* Page Header */}
            <div className="flex items-center justify-between">
              <div>
                <h1 className="text-3xl font-bold tracking-tight">Branding Settings</h1>
                <p className="text-muted-foreground mt-2">
                  Customize your tenant's branding, colors, and appearance
                </p>
              </div>
              <div className="flex items-center gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => { void window.open(`/intake/preview?tenantId=${tenantId}`, '_blank'); }}
                >
                  <ExternalLink className="h-4 w-4 mr-2" />
                  Open Full Preview
                </Button>
                <Link href={`/projects/${projectId}/settings/branding/domains`}>
                  <Button variant="outline" size="sm">
                    <Globe className="h-4 w-4 mr-2" />
                    Manage Domains
                  </Button>
                </Link>
                <Link href={`/projects/${projectId}/settings/email-templates`}>
                  <Button variant="outline" size="sm">
                    <Mail className="h-4 w-4 mr-2" />
                    Email Templates
                  </Button>
                </Link>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => { void setShowPreview(!showPreview); }}
                >
                  <Eye className="h-4 w-4 mr-2" />
                  {showPreview ? 'Hide' : 'Show'} Preview
                </Button>
              </div>
            </div>
            {hasUnsavedChanges && (
              <Card className="border-amber-500 bg-amber-50 dark:bg-amber-950/20">
                <CardContent className="pt-6">
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="font-medium text-amber-900 dark:text-amber-100">
                        You have unsaved changes
                      </p>
                      <p className="text-sm text-amber-700 dark:text-amber-300 mt-1">
                        Save your changes to apply them to your tenant
                      </p>
                    </div>
                    <div className="flex items-center gap-2">
                      <Button variant="outline" size="sm" onClick={() => { void handleReset(); }}>
                        <RotateCcw className="h-4 w-4 mr-2" />
                        Discard
                      </Button>
                      <Button size="sm" onClick={() => { void handleSave(); }} disabled={isSaving}>
                        {isSaving ? (
                          <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                        ) : (
                          <Save className="h-4 w-4 mr-2" />
                        )}
                        Save Changes
                      </Button>
                    </div>
                  </div>
                </CardContent>
              </Card>
            )}
            <div className="grid gap-6 md:grid-cols-2">
              {/* Left Column: Form */}
              <div className="space-y-6">
                {/* Logo */}
                <Card>
                  <CardHeader>
                    <CardTitle className="flex items-center gap-2">
                      <Upload className="h-5 w-5" />
                      Logo
                    </CardTitle>
                    <CardDescription>
                      Upload your organization's logo (displayed in intake portal header)
                    </CardDescription>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    <div className="space-y-2">
                      <Label htmlFor="logoUrl">Logo URL</Label>
                      <Input
                        id="logoUrl"
                        type="url"
                        placeholder="https://example.com/logo.png"
                        value={formData.logoUrl ?? ''}
                        onChange={(e) => { void handleChange('logoUrl', e.target.value); }}
                      />
                      <p className="text-xs text-muted-foreground">
                        Enter a URL to your logo image. Recommended size: 200x60px
                      </p>
                    </div>
                    {formData.logoUrl && (
                      <div className="mt-4 p-4 border rounded-lg bg-muted/50">
                        <p className="text-sm font-medium mb-2">Logo Preview:</p>
                        <img
                          src={formData.logoUrl}
                          alt="Logo preview"
                          className="h-12 object-contain"
                          onError={(e) => {
                            e.currentTarget.style.display = 'none';
                          }}
                        />
                      </div>
                    )}
                  </CardContent>
                </Card>
                {/* Colors */}
                <Card>
                  <CardHeader>
                    <CardTitle className="flex items-center gap-2">
                      <Palette className="h-5 w-5" />
                      Colors
                    </CardTitle>
                    <CardDescription>
                      Customize your brand colors (used throughout the intake portal)
                    </CardDescription>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    <div className="space-y-2">
                      <Label htmlFor="primaryColor">Primary Color</Label>
                      <div className="flex items-center gap-2">
                        <Input
                          id="primaryColor"
                          type="text"
                          placeholder="#3B82F6"
                          value={formData.primaryColor ?? ''}
                          onChange={(e) => { void handleColorChange('primaryColor', e.target.value); }}
                          className="flex-1"
                        />
                        <Input
                          type="color"
                          value={formData.primaryColor || '#3B82F6'}
                          onChange={(e) => { void handleColorChange('primaryColor', e.target.value); }}
                          className="w-14 h-10 p-1 cursor-pointer"
                        />
                      </div>
                      <p className="text-xs text-muted-foreground">
                        Used for headers, buttons, and primary UI elements
                      </p>
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="accentColor">Accent Color</Label>
                      <div className="flex items-center gap-2">
                        <Input
                          id="accentColor"
                          type="text"
                          placeholder="#10B981"
                          value={formData.accentColor ?? ''}
