                      disabled={!hasUnsavedChanges || isSaving}
                    >
                      <RotateCcw className="h-4 w-4 mr-2" />
                      Discard Changes
                    </Button>
                    <Button onClick={() => { void handleSave(); }} disabled={!hasUnsavedChanges || isSaving}>
                      {isSaving ? (
                        <Loader2 className="h-4 w-4 mr-2 animate-spin" />
