                </Card>
              </div>
            </TabsContent>


            <TabsContent value="management" className="space-y-4 sm:space-y-6">
              <Card>
                <CardHeader>
                  <CardTitle>Workflow Management</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="text-center py-8">
                    <Settings className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
