      </div>
    );
  }

  // Render preview with BrandingProvider
  return (
    <BrandingProvider tenantId={tenantId} enableTheming={true}>
      <IntakeDemo />
    </BrandingProvider>
  );
}

import { useQuery, useMutation } from '@tanstack/react-query';
import { Search, Download, Star } from "lucide-react";
import { useState } from 'react';
import { useLocation } from "wouter";

import Sidebar from "@/components/layout/Sidebar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { useToast } from "@/hooks/use-toast";


// Types
interface Template {
    id: string;
    title: string;
    description: string;
    category: string;
    usageCount: number;
    rating: number;
    isOfficial: boolean;
    tags?: string[];
}

export default function Marketplace() {
    const [searchTerm, setSearchTerm] = useState('');
    const [category, setCategory] = useState('all');
    const { toast } = useToast();
    const [, setLocation] = useLocation();

    // Fetch templates
    const { data: templates = [], isLoading } = useQuery<Template[]>({
        queryKey: ['templates', category, searchTerm],
        queryFn: async () => {
            const params = new URLSearchParams();
            if (searchTerm) {params.append('search', searchTerm);}
            if (category !== 'all') {params.append('category', category);}

            const res = await fetch(`/api/templates?${params.toString()}`);
            if (!res.ok) {throw new Error('Failed to fetch templates');}
            return res.json();
        }
    });

    // Install mutation
    const installMutation = useMutation({
        mutationFn: async (templateId: string) => {
            // For now, we need to know WHICH project to install to.
            // In a real app, we'd prompt for project selection or use current project context.
            // We'll hardcode a "default" or prompt via a simple window.prompt for v1 dev.
            // const projectId = "default-project-id"; 
            // Actually, let's just pass a dummy project ID; backend will likely ignore or we assume project exists.
            // Wait, backend `installTemplate` requires `projectId`.
            // We will rely on backend to handle user's default project if needed, or we should fetch projects.
            // For MVP, passing a placeholder.
            const projectId = "default";

            const res = await fetch(`/api/templates/${templateId}/install`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ projectId })
            });
            if (!res.ok) {throw new Error('Failed to install template');}
            return res.json();
        },
        onSuccess: (workflow) => {
            toast({
                title: "Template Installed",
                description: "Redirecting to workflow builder...",
                variant: "default"
            });
            // Redirect to builder
            setTimeout(() => {
                setLocation(`/builder/${workflow.id}`);
            }, 1000);
        },
        onError: () => {
            toast({
                title: "Installation Failed",
                description: "Could not install the template.",
                variant: "destructive"
            });
        }
    });

    const categories = ['all', 'legal', 'hr', 'finance', 'general', 'marketing'];

    return (
        <div className="flex h-screen bg-background">
            <Sidebar />
            <main className="flex-1 flex flex-col overflow-hidden">
                <div className="flex-1 overflow-auto p-6">
                    <div className="flex flex-col gap-6 max-w-7xl mx-auto">
                        <div>
                            <h1 className="text-3xl font-bold tracking-tight">Template Marketplace</h1>
                            <p className="text-muted-foreground">Discover and install pre-built workflows to get started faster.</p>
                        </div>

                        {/* Search and Filter */}
                        <div className="flex gap-4 items-center flex-wrap">
                            <div className="relative flex-1 min-w-[300px] max-w-sm">
                                <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
                                <Input
                                    placeholder="Search templates..."
                                    className="pl-8"
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                />
                            </div>
                            <div className="flex gap-2 flex-wrap">
                                {categories.map(cat => (
                                    <Button
                                        key={cat}
                                        variant={category === cat ? "default" : "outline"}
                                        size="sm"
                                        onClick={() => setCategory(cat)}
                                        className="capitalize"
                                    >
                                        {cat}
                                    </Button>
                                ))}
                            </div>
                        </div>

                        {/* Grid */}
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                            {isLoading ? (
                                <div className="col-span-full text-center py-20">Loading templates...</div>
                            ) : templates.length === 0 ? (
                                <div className="col-span-full text-center py-20 text-muted-foreground">No templates found.</div>
                            ) : (
                                templates.map((template) => (
                                    <Card key={template.id} className="flex flex-col hover:shadow-lg transition-all">
                                        <CardHeader>
                                            <div className="flex justify-between items-start">
                                                <div>
                                                    <CardTitle className="text-xl">{template.title}</CardTitle>
                                                    <CardDescription className="line-clamp-2 mt-2">{template.description}</CardDescription>
                                                </div>
                                                {template.isOfficial && (
                                                    <Badge variant="secondary" className="bg-blue-100 text-blue-800 hover:bg-blue-100">Official</Badge>
                                                )}
                                            </div>
                                        </CardHeader>
                                        <CardContent className="flex-1">
                                            <div className="flex gap-4 text-sm text-muted-foreground">
                                                <div className="flex items-center gap-1">
                                                    <Download className="h-4 w-4" />
                                                    <span>{template.usageCount} installs</span>
                                                </div>
                                                {template.rating > 0 && (
                                                    <div className="flex items-center gap-1">
                                                        <Star className="h-4 w-4 fill-yellow-400 text-yellow-400" />
                                                        <span>{(template.rating / 100).toFixed(1)}</span>
                                                    </div>
                                                )}
                                            </div>
                                            <div className="mt-4 flex flex-wrap gap-2">
                                                {template.tags?.map(tag => (
                                                    <Badge key={tag} variant="outline" className="text-xs">{tag}</Badge>
                                                ))}
                                            </div>
                                        </CardContent>
                                        <CardFooter>
                                            <Button
                                                className="w-full"
                                                onClick={() => installMutation.mutate(template.id)}
                                                disabled={installMutation.isPending}
                                            >
                                                {installMutation.isPending ? "Installing..." : "Use Template"}
                                            </Button>
                                        </CardFooter>
                                    </Card>
                                ))
                            )}
                        </div>
                    </div>
                </div>
            </main>
        </div>
    );
}

/**
 * New Workflow Creation Page
 * Shows a form to create a new workflow, then redirects to the builder
 */

import { ArrowLeft, Sparkles, LayoutTemplate } from "lucide-react";
import React, { useState } from "react";
import { useLocation } from "wouter";

import { TemplateBrowserDialog } from "@/components/templates/TemplateBrowserDialog";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Textarea } from "@/components/ui/textarea";
import { useToast } from "@/hooks/use-toast";
import { blueprintAPI, ApiBlueprint } from "@/lib/vault-api";
import { useCreateWorkflow } from "@/lib/vault-hooks";

export default function NewWorkflow() {
  const [, navigate] = useLocation();
  const { toast } = useToast();
  const createWorkflowMutation = useCreateWorkflow();

  const [isTemplateBrowserOpen, setIsTemplateBrowserOpen] = useState(false);
  const [formData, setFormData] = useState({
    title: "",
    description: "",
  });
  const [aiPrompt, setAiPrompt] = useState("");


  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.title.trim()) {
      toast({
        title: "Error",
        description: "Workflow title is required",
        variant: "destructive",
      });
      return;
    }

    try {
      // Prepare data, converting empty description to undefined
      const workflowData = {
        title: formData.title.trim(),
        ...(formData.description.trim() && { description: formData.description.trim() }),
      };

      const workflow = await createWorkflowMutation.mutateAsync(workflowData);
      toast({
        title: "Success",
        description: "Workflow created successfully",
      });
      // Navigate to the builder for the newly created workflow
      navigate(`/workflows/${workflow.id}/builder`);
    } catch (error) {
      toast({
        title: "Error",
        description: "Failed to create workflow",
      });
    }
  };

  const handleAiSubmit = async () => {
    if (!aiPrompt.trim()) {
      toast({
        title: "Error",
        description: "Please describe what you want to build.",
        variant: "destructive",
      });
      return;
    }

    try {
      // Create a default workflow shell
      const workflowData = {
        title: "AI Generated Workflow", // Could ask for this or generic
        description: "Created via AI Assistant",
      };

      const workflow = await createWorkflowMutation.mutateAsync(workflowData);

      toast({
        title: "Success",
        description: "Workflow created. Opening AI Assistant...",
      });

      // Navigate to builder with AI panel open and prompt
      navigate(`/workflows/${workflow.id}/builder?aiPanel=true&prompt=${encodeURIComponent(aiPrompt)}`);

    } catch (error) {
      console.error(error);
      toast({
        title: "Error",
        description: "Failed to create workflow",
        variant: "destructive",
      });
    }
  };

  const handleTemplateSelect = async (template: ApiBlueprint) => {
    try {
      // Instantiate workflow from blueprint
      const { workflowId } = await blueprintAPI.instantiate(template.id, {
        projectId: "" // Unfiled
      });

      toast({
        title: "Success",
        description: "Created workflow from template",
      });

      navigate(`/workflows/${workflowId}/builder`);

    } catch (error) {
      console.error(error);
      toast({
        title: "Error",
        description: "Failed to create workflow from template",
        variant: "destructive",
      });
    }
  };

  return (
    <div className="min-h-screen bg-background">
      <div className="container max-w-2xl mx-auto py-8 px-4">
        <Button
          variant="ghost"
          onClick={() => { void navigate("/workflows"); }}
          className="mb-4"
        >
          <ArrowLeft className="w-4 h-4 mr-2" />
          Back to Workflows
        </Button>

        <Card>
          <CardHeader>
            <CardTitle>Create New Workflow</CardTitle>
            <CardDescription>
              Enter the details for your new workflow. You'll be able to add sections, steps, and configure everything in the builder.
            </CardDescription>
          </CardHeader>
          <CardContent>
            <Tabs defaultValue="manual" className="space-y-4">
              <TabsList className="grid w-full grid-cols-3">
                <TabsTrigger value="manual">Manual Creation</TabsTrigger>
                <TabsTrigger value="template">Start from Template</TabsTrigger>
                <TabsTrigger value="ai">Create with AI</TabsTrigger>
              </TabsList>

              <TabsContent value="manual">
                <form onSubmit={(e) => { e.preventDefault(); void handleSubmit(e); }} className="space-y-4">
                  <div className="space-y-2">
                    <Label htmlFor="title">Title *</Label>
                    <Input
                      id="title"
                      placeholder="e.g., Customer Onboarding"
                      value={formData.title}
                      onChange={(e) => { void setFormData({ ...formData, title: e.target.value }); }}
                      autoFocus
                      required
                    />
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="description">Description</Label>
                    <Textarea
                      id="description"
                      placeholder="Describe what this workflow is for..."
                      value={formData.description}
                      onChange={(e) => { void setFormData({ ...formData, description: e.target.value }); }}
                      rows={4}
                    />
                  </div>

                  <div className="flex gap-3 justify-end pt-4">
                    <Button
                      type="button"
                      variant="outline"
                      onClick={() => { void navigate("/workflows"); }}
                    >
                      Cancel
                    </Button>
                    <Button
                      type="submit"
                      disabled={createWorkflowMutation.isPending}
                      className="bg-indigo-600 hover:bg-indigo-700"
                    >
                      {createWorkflowMutation.isPending ? "Creating..." : "Create Workflow"}
                    </Button>
                  </div>
                </form>
              </TabsContent>

              <TabsContent value="template">
                <div className="space-y-4 py-8 flex flex-col items-center justify-center text-center">
                  <div className="bg-primary/10 p-4 rounded-full mb-4">
                    <LayoutTemplate className="w-8 h-8 text-primary" />
                  </div>
                  <h3 className="text-lg font-medium">Browse Templates</h3>
                  <p className="text-muted-foreground max-w-md">
                    Start with a pre-built workflow. Browse our library of templates for workflows and forms.
                  </p>
                  <Button onClick={() => { void setIsTemplateBrowserOpen(true); }} className="mt-4">
                    Open Template Library
                  </Button>
                </div>
              </TabsContent>

              <TabsContent value="ai">
                <div className="space-y-4 py-2">
                  <div className="bg-indigo-50 border border-indigo-100 rounded-md p-4 flex gap-3">
                    <Sparkles className="w-5 h-5 text-indigo-600 flex-shrink-0 mt-0.5" />
                    <div className="text-sm text-indigo-900">
                      <p className="font-medium mb-1">Describe your workflow</p>
                      <p className="opacity-90">
                        Tell us what you want to build. Our AI assistant will generate the structure, steps, and logic for you to review.
                      </p>
                    </div>
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="ai-prompt">What do you want to build?</Label>
                    <Textarea
                      id="ai-prompt"
                      placeholder="e.g. A customer feedback form that asks for a rating, and if the rating is low, asks for detailed feedback and contact info."
                      className="min-h-[150px] text-base resize-none"
                      value={aiPrompt}
                      onChange={(e) => { void setAiPrompt(e.target.value); }}
                    />
                  </div>

                  <div className="flex gap-3 justify-end pt-4">
                    <Button
                      type="button"
                      variant="outline"
                      onClick={() => { void navigate("/workflows"); }}
                    >
                      Cancel
                    </Button>
                    <Button
                      className="bg-indigo-600 hover:bg-indigo-700"
                      onClick={() => { void handleAiSubmit(); }}
                      disabled={createWorkflowMutation.isPending}
                    >
                      <Sparkles className="w-4 h-4 mr-2" />
                      {createWorkflowMutation.isPending ? "Projecting..." : "Generate Workflow"}
                    </Button>
                  </div>
                </div>
              </TabsContent>
            </Tabs>
          </CardContent>
        </Card>
      </div>
      <TemplateBrowserDialog
        open={isTemplateBrowserOpen}
        onOpenChange={setIsTemplateBrowserOpen}
        onSelect={handleTemplateSelect}
      />
    </div>
  );
}

import { ArrowLeft, Users, Mail, Crown, UserMinus, Shield, AlertCircle } from 'lucide-react';
import React, { useState } from 'react';
import { useParams, useLocation } from 'wouter';

import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { useToast } from '@/hooks/use-toast';
import { useAuth } from '@/hooks/useAuth';
import {
  useOrganization,
  useOrganizationMembers,
  useOrganizationInvites,
  useUpdateOrganization,
  usePromoteMember,
  useDemoteMember,
  useRemoveMember,
  useCreateInvite,
  useRevokeInvite,
  useLeaveOrganization,
  useDeleteOrganization,
} from '@/hooks/useOrganizations';
export default function OrganizationDetail() {
  const { id: orgId } = useParams<{ id: string }>();
  const [, navigate] = useLocation();
  const { toast } = useToast();
  const { user } = useAuth();
  const { data: organization, isLoading: orgLoading, error: orgError } = useOrganization(orgId);
  const { data: members, isLoading: membersLoading } = useOrganizationMembers(orgId);
  const { data: invites, isLoading: invitesLoading } = useOrganizationInvites(orgId);
  const updateOrg = useUpdateOrganization(orgId);
  const promoteMember = usePromoteMember(orgId);
  const demoteMember = useDemoteMember(orgId);
  const removeMember = useRemoveMember(orgId);
  const createInvite = useCreateInvite(orgId);
  const revokeInvite = useRevokeInvite(orgId);
  const leaveOrg = useLeaveOrganization();
  const deleteOrg = useDeleteOrganization(orgId);
  const [isEditingOrg, setIsEditingOrg] = useState(false);
  const [orgName, setOrgName] = useState('');
  const [orgDescription, setOrgDescription] = useState('');
  const [isInviteDialogOpen, setIsInviteDialogOpen] = useState(false);
  const [inviteEmail, setInviteEmail] = useState('');
  const [isLeaveDialogOpen, setIsLeaveDialogOpen] = useState(false);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const [removingMemberId, setRemovingMemberId] = useState<string | null>(null);
  const isAdmin = organization?.role === 'admin';
  const handleEditOrg = () => {
    setOrgName(organization?.name ?? '');
    setOrgDescription(organization?.description ?? '');
    setIsEditingOrg(true);
  };
  const handleSaveOrg = async () => {
    if (!orgName.trim()) {
      toast({
        title: 'Name required',
        description: 'Organization name cannot be empty',
        variant: 'destructive',
      });
      return;
    }
    try {
      await updateOrg.mutateAsync({
        name: orgName.trim(),
        description: orgDescription.trim() || undefined,
      });
      toast({
        title: 'Organization updated',
        description: 'Changes saved successfully',
      });
      setIsEditingOrg(false);
    } catch (error) {
      console.error('Failed to update organization:', error);
      toast({
        title: 'Error',
        description: 'Failed to update organization. Please try again.',
        variant: 'destructive',
      });
    }
  };
  const handlePromote = async (userId: string) => {
    try {
      await promoteMember.mutateAsync(userId);
      toast({
        title: 'Member promoted',
        description: 'Member has been promoted to admin',
      });
    } catch (error) {
      console.error('Failed to promote member:', error);
      toast({
        title: 'Error',
        description: 'Failed to promote member. Please try again.',
        variant: 'destructive',
      });
    }
  };
  const handleDemote = async (userId: string) => {
    try {
      await demoteMember.mutateAsync(userId);
      toast({
        title: 'Member demoted',
        description: 'Admin has been demoted to member',
      });
    } catch (error) {
      console.error('Failed to demote member:', error);
      toast({
        title: 'Error',
        description: 'Failed to demote member. Please try again.',
        variant: 'destructive',
      });
    }
  };
  const handleRemoveMember = async (userId: string) => {
    try {
      await removeMember.mutateAsync(userId);
      toast({
        title: 'Member removed',
        description: 'Member has been removed from the organization',
      });
      setRemovingMemberId(null);
    } catch (error) {
      console.error('Failed to remove member:', error);
      toast({
        title: 'Error',
        description: 'Failed to remove member. Please try again.',
        variant: 'destructive',
      });
    }
  };
  const handleCreateInvite = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inviteEmail.trim()) {
      toast({
        title: 'Email required',
        description: 'Please enter an email address',
        variant: 'destructive',
      });
      return;
    }
    try {
      await createInvite.mutateAsync({ email: inviteEmail.trim() });
      toast({
        title: 'Invite sent',
        description: `Invitation sent to ${inviteEmail}`,
      });
      setIsInviteDialogOpen(false);
      setInviteEmail('');
    } catch (error) {
      console.error('Failed to create invite:', error);
      toast({
        title: 'Error',
        description: 'Failed to send invitation. Please try again.',
        variant: 'destructive',
      });
    }
  };
  const handleRevokeInvite = async (inviteId: string) => {
    try {
      await revokeInvite.mutateAsync(inviteId);
      toast({
        title: 'Invite revoked',
        description: 'Invitation has been revoked',
      });
    } catch (error) {
      console.error('Failed to revoke invite:', error);
      toast({
        title: 'Error',
        description: 'Failed to revoke invitation. Please try again.',
        variant: 'destructive',
      });
    }
  };
  const handleLeaveOrganization = async () => {
    if (!orgId) { return; }
    try {
      await leaveOrg.mutateAsync(orgId);
      toast({
        title: 'Left organization',
        description: `You have left ${organization?.name}`,
      });
      navigate('/organizations');
    } catch (error) {
      console.error('Failed to leave organization:', error);
      toast({
        title: 'Error',
        description: 'Failed to leave organization. Please try again.',
        variant: 'destructive',
      });
    }
  };
  const handleDeleteOrganization = async () => {
    if (!orgId) { return; }
    try {
      await deleteOrg.mutateAsync();
      toast({
        title: 'Organization deleted',
        description: `${organization?.name} has been permanently deleted`,
      });
      setIsDeleteDialogOpen(false);
      navigate('/organizations');
    } catch (error: any) {
      console.error('Failed to delete organization:', error);
      toast({
        title: 'Failed to delete organization',
        description: error.message || 'An error occurred',
        variant: 'destructive',
      });
    }
  };
  if (orgLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto mb-4"></div>
          <p className="text-muted-foreground">Loading organization...</p>
        </div>
      </div>
    );
  }
  if (orgError || !organization) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-center max-w-md">
          <AlertCircle className="h-12 w-12 text-destructive mx-auto mb-4" />
          <h2 className="text-xl font-semibold mb-2">Organization not found</h2>
          <p className="text-muted-foreground mb-6">
            {orgError instanceof Error ? orgError.message : 'This organization does not exist or you do not have access to it'}
          </p>
          <Button onClick={() => { void navigate('/organizations'); }}>
            <ArrowLeft className="h-4 w-4 mr-2" />
            Back to Organizations
          </Button>
        </div>
      </div>
    );
  }
  return (
    <div className="container mx-auto py-8 px-4 max-w-6xl">
      {/* Header */}
      <div className="mb-8">
        <Button variant="ghost" onClick={() => { void navigate('/organizations'); }} className="mb-4">
          <ArrowLeft className="h-4 w-4 mr-2" />
          Back to Organizations
        </Button>
        <Card>
          <CardHeader>
            <div className="flex items-start justify-between">
              <div className="flex-1">
                {isEditingOrg ? (
                  <div className="space-y-4">
                    <div>
                      <Label htmlFor="orgName">Organization Name</Label>
                      <Input
                        id="orgName"
                        value={orgName}
                        onChange={(e) => { void setOrgName(e.target.value); }}
                        placeholder="Organization name"
                      />
                    </div>
                    <div>
                      <Label htmlFor="orgDescription">Description</Label>
                      <Textarea
                        id="orgDescription"
                        value={orgDescription}
                        onChange={(e) => { void setOrgDescription(e.target.value); }}
                        placeholder="Organization description"
                        rows={3}
                      />
                    </div>
                  </div>
                ) : (
                  <>
                    <CardTitle className="text-2xl">{organization.name}</CardTitle>
                    {organization.description && (
                      <CardDescription className="mt-2">{organization.description}</CardDescription>
                    )}
                  </>
                )}
              </div>
              {isAdmin && (
                <div className="ml-4">
                  {isEditingOrg ? (
                    <div className="space-x-2">
                      <Button variant="outline" onClick={() => { void setIsEditingOrg(false); }}>
                        Cancel
                      </Button>
                      <Button onClick={() => { void handleSaveOrg(); }} disabled={updateOrg.isPending}>
                        {updateOrg.isPending ? 'Saving...' : 'Save'}
                      </Button>
                    </div>
                  ) : (
                    <Button variant="outline" onClick={() => { void handleEditOrg(); }}>
                      Edit
                    </Button>
                  )}
                </div>
              )}
            </div>
          </CardHeader>
        </Card>
      </div>
      {/* Members Section */}
      <Card className="mb-8">
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle>Members</CardTitle>
              <CardDescription>People who belong to this organization</CardDescription>
            </div>
            {isAdmin && (
              <Button onClick={() => { void setIsInviteDialogOpen(true); }}>
                <Mail className="h-4 w-4 mr-2" />
                Invite Member
              </Button>
            )}
          </div>
        </CardHeader>
        <CardContent>
          {membersLoading ? (
            <div className="text-center py-8">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mx-auto mb-4"></div>
              <p className="text-muted-foreground">Loading members...</p>
            </div>
          ) : !members || members.length === 0 ? (
            <div className="text-center py-8">
              <Users className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
              <p className="text-muted-foreground">No members yet</p>
            </div>
          ) : (
            <div className="space-y-2">
              {members.map((member) => (
                <div
                  key={member.userId}
                  className="flex items-center justify-between p-4 rounded-lg border bg-card hover:bg-accent/50 transition-colors"
                >
                  <div className="flex items-center space-x-4">
                    <div className="w-10 h-10 bg-primary/10 rounded-full flex items-center justify-center">
                      <Users className="h-5 w-5 text-primary" />
                    </div>
                    <div>
                      <div className="flex items-center space-x-2">
                        <p className="font-medium">{member.fullName || member.email}</p>
                        {member.role === 'admin' && (
                          <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-primary/10 text-primary">
                            <Crown className="h-3 w-3 mr-1" />
                            Admin
                          </span>
                        )}
                      </div>
                      <p className="text-sm text-muted-foreground">{member.email}</p>
                    </div>
                  </div>
                  {isAdmin && member.userId !== user?.id && (
                    <div className="flex items-center space-x-2">
                      {member.role === 'member' ? (
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => { void handlePromote(member.userId); }}
                          disabled={promoteMember.isPending}
                        >
                          <Shield className="h-4 w-4 mr-1" />
                          Promote
                        </Button>
                      ) : (
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => { void handleDemote(member.userId); }}
                          disabled={demoteMember.isPending}
                        >
                          Demote
                        </Button>
                      )}
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => { void setRemovingMemberId(member.userId); }}
                        disabled={removeMember.isPending}
                      >
                        <UserMinus className="h-4 w-4" />
                      </Button>
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>
      {/* Invites Section (Admin Only) */}
      {isAdmin && (
        <Card className="mb-8">
          <CardHeader>
            <CardTitle>Pending Invitations</CardTitle>
            <CardDescription>Invitations that have not yet been accepted</CardDescription>
          </CardHeader>
          <CardContent>
            {invitesLoading ? (
              <div className="text-center py-8">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mx-auto mb-4"></div>
                <p className="text-muted-foreground">Loading invitations...</p>
              </div>
            ) : !invites || invites.length === 0 ? (
              <div className="text-center py-8">
                <Mail className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
                <p className="text-muted-foreground">No pending invitations</p>
              </div>
            ) : (
              <div className="space-y-2">
                {invites.map((invite) => (
                  <div
                    key={invite.inviteId}
                    className="flex items-center justify-between p-4 rounded-lg border bg-card"
                  >
                    <div className="flex items-center space-x-4">
                      <div className="w-10 h-10 bg-muted rounded-full flex items-center justify-center">
                        <Mail className="h-5 w-5 text-muted-foreground" />
                      </div>
                      <div>
                        <p className="font-medium">{invite.invitedEmail}</p>
                        <p className="text-sm text-muted-foreground">
                          Invited by {invite.invitedByName || invite.invitedByEmail}
                        </p>
                      </div>
                    </div>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => { void handleRevokeInvite(invite.inviteId); }}
                      disabled={revokeInvite.isPending}
                    >
                      Revoke
                    </Button>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      )}
      {/* Danger Zone */}
      <Card className="border-destructive">
        <CardHeader>
          <CardTitle className="text-destructive">Danger Zone</CardTitle>
          <CardDescription>Actions that cannot be undone</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-between">
            <div>
              <p className="font-medium">Leave Organization</p>
              <p className="text-sm text-muted-foreground">
                You will lose access to all projects and workflows owned by this organization
              </p>
            </div>
            <Button variant="destructive" onClick={() => { void setIsLeaveDialogOpen(true); }}>
              Leave Organization
            </Button>
          </div>
        </CardContent>
      </Card>
      {/* Delete Organization (Admins Only) */}
      {isAdmin && (
        <Card className="border-destructive mt-4">
          <CardHeader>
            <CardTitle className="text-destructive">Delete Organization</CardTitle>
            <CardDescription>
              Permanently delete this organization and all its data
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="flex items-center justify-between">
              <div>
                <p className="font-medium">Delete this organization</p>
                <p className="text-sm text-muted-foreground">
                  This action cannot be undone. All members will lose access.
                </p>
              </div>
              <Button
                variant="destructive"
                onClick={() => { void setIsDeleteDialogOpen(true); }}
              >
                Delete Organization
              </Button>
            </div>
          </CardContent>
        </Card>
      )}
      {/* Invite Dialog */}
      <Dialog open={isInviteDialogOpen} onOpenChange={setIsInviteDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Invite Member</DialogTitle>
            <DialogDescription>
              Send an invitation to join {organization.name}
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={(e) => { e.preventDefault(); void handleCreateInvite(e); }}>
            <div className="space-y-4 py-4">
              <div className="space-y-2">
                <Label htmlFor="inviteEmail">Email Address</Label>
                <Input
                  id="inviteEmail"
                  type="email"
                  placeholder="member@example.com"
                  value={inviteEmail}
                  onChange={(e) => { void setInviteEmail(e.target.value); }}
                  required
                />
              </div>
            </div>
            <DialogFooter>
              <Button
                type="button"
                variant="outline"
                onClick={() => { void setIsInviteDialogOpen(false); }}
              >
                Cancel
              </Button>
              <Button type="submit" disabled={createInvite.isPending}>
                {createInvite.isPending ? 'Sending...' : 'Send Invitation'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
      {/* Leave Confirmation Dialog */}
      <Dialog open={isLeaveDialogOpen} onOpenChange={setIsLeaveDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Leave Organization</DialogTitle>
            <DialogDescription>
              Are you sure you want to leave {organization.name}? You will lose access to all
              organization resources.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button variant="outline" onClick={() => { void setIsLeaveDialogOpen(false); }}>
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={() => { void handleLeaveOrganization(); }}
              disabled={leaveOrg.isPending}
            >
              {leaveOrg.isPending ? 'Leaving...' : 'Leave Organization'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
      {/* Delete Confirmation Dialog */}
      <Dialog open={isDeleteDialogOpen} onOpenChange={setIsDeleteDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Delete Organization</DialogTitle>
            <DialogDescription>
              Are you sure you want to permanently delete {organization.name}?
              This will remove all members and cannot be undone.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => { void setIsDeleteDialogOpen(false); }}
              disabled={deleteOrg.isPending}
            >
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={() => { void handleDeleteOrganization(); }}
              disabled={deleteOrg.isPending}
            >
              {deleteOrg.isPending ? 'Deleting...' : 'Delete Organization'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
      {/* Remove Member Confirmation Dialog */}
      <Dialog open={!!removingMemberId} onOpenChange={() => setRemovingMemberId(null)}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Remove Member</DialogTitle>
            <DialogDescription>
              Are you sure you want to remove this member from the organization? They will lose
              access to all organization resources.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button variant="outline" onClick={() => { void setRemovingMemberId(null); }}>
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={() => { if (removingMemberId) {void handleRemoveMember(removingMemberId);} }}
              disabled={removeMember.isPending}
            >
              {removeMember.isPending ? 'Removing...' : 'Remove Member'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { Plus, Users, AlertCircle } from 'lucide-react';
import React, { useState } from 'react';
import { Link } from 'wouter';

import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import { useOrganizations, useCreateOrganization } from '@/hooks/useOrganizations';

export default function Organizations() {
  const { toast } = useToast();
  const { data: organizations, isLoading, error } = useOrganizations();
  const createOrg = useCreateOrganization();

  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);
  const [newOrgName, setNewOrgName] = useState('');
  const [newOrgDescription, setNewOrgDescription] = useState('');

  const handleCreateOrganization = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!newOrgName.trim()) {
      toast({
        title: 'Name required',
        description: 'Please enter an organization name',
        variant: 'destructive',
      });
      return;
    }

    try {
      await createOrg.mutateAsync({
        name: newOrgName.trim(),
        description: newOrgDescription.trim() || undefined,
      });

      toast({
        title: 'Organization created',
        description: `${newOrgName} has been created successfully`,
      });

      setIsCreateDialogOpen(false);
      setNewOrgName('');
      setNewOrgDescription('');
    } catch (error) {
      console.error('Failed to create organization:', error);
      toast({
        title: 'Error',
        description: 'Failed to create organization. Please try again.',
        variant: 'destructive',
      });
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto mb-4"></div>
          <p className="text-muted-foreground">Loading organizations...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-center max-w-md">
          <AlertCircle className="h-12 w-12 text-destructive mx-auto mb-4" />
          <h2 className="text-xl font-semibold mb-2">Error loading organizations</h2>
          <p className="text-muted-foreground">
            {error instanceof Error ? error.message : 'An unexpected error occurred'}
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="container mx-auto py-8 px-4 max-w-6xl">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-3xl font-bold">Organizations</h1>
          <p className="text-muted-foreground mt-2">
            Manage your team organizations and collaborate with members
          </p>
        </div>
        <Button onClick={() => { void setIsCreateDialogOpen(true); }}>
          <Plus className="h-4 w-4 mr-2" />
          New Organization
        </Button>
      </div>

      {!organizations || organizations.length === 0 ? (
        <Card>
          <CardContent className="py-12 text-center">
            <Users className="h-16 w-16 text-muted-foreground mx-auto mb-4" />
            <h3 className="text-xl font-semibold mb-2">No organizations yet</h3>
            <p className="text-muted-foreground mb-6 max-w-md mx-auto">
              Create an organization to collaborate with your team and manage shared resources.
            </p>
            <Button onClick={() => { void setIsCreateDialogOpen(true); }}>
              <Plus className="h-4 w-4 mr-2" />
              Create your first organization
            </Button>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {organizations.map((org) => (
            <Link key={org.id} href={`/organizations/${org.id}`}>
              <Card className="hover:shadow-lg transition-shadow cursor-pointer h-full">
                <CardHeader>
                  <div className="flex items-center justify-between mb-2">
                    <Users className="h-8 w-8 text-primary" />
                    <span className="text-xs font-medium px-2 py-1 rounded-full bg-primary/10 text-primary">
                      {org.role === 'admin' ? 'Admin' : 'Member'}
                    </span>
                  </div>
                  <CardTitle className="text-xl">{org.name}</CardTitle>
                  {org.description && (
                    <CardDescription className="line-clamp-2">{org.description}</CardDescription>
                  )}
                </CardHeader>
              </Card>
            </Link>
          ))}
        </div>
      )}

      {/* Create Organization Dialog */}
      <Dialog open={isCreateDialogOpen} onOpenChange={setIsCreateDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Create Organization</DialogTitle>
            <DialogDescription>
              Create a new organization to collaborate with your team.
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={(e) => { e.preventDefault(); void handleCreateOrganization(e); }}>
            <div className="space-y-4 py-4">
              <div className="space-y-2">
                <Label htmlFor="orgName">Organization Name *</Label>
                <Input
                  id="orgName"
                  placeholder="My Organization"
                  value={newOrgName}
                  onChange={(e) => { void setNewOrgName(e.target.value); }}
                  required
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="orgDescription">Description</Label>
                <Input
                  id="orgDescription"
                  placeholder="A brief description of your organization"
                  value={newOrgDescription}
                  onChange={(e) => { void setNewOrgDescription(e.target.value); }}
                />
              </div>
            </div>
            <DialogFooter>
              <Button
                type="button"
                variant="outline"
                onClick={() => { void setIsCreateDialogOpen(false); }}
              >
                Cancel
              </Button>
              <Button type="submit" disabled={createOrg.isPending}>
                {createOrg.isPending ? 'Creating...' : 'Create Organization'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * ProjectView Page
 * Displays a single project with its contained workflows
 */

import { ArrowLeft, Plus, Edit } from "lucide-react";
import { useState } from "react";
import { Link, useParams, useLocation } from "wouter";

import { WorkflowCard } from "@/components/dashboard/WorkflowCard";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Skeleton } from "@/components/ui/skeleton";
import { Textarea } from "@/components/ui/textarea";
import { useToast } from "@/hooks/use-toast";
import type { ApiWorkflow } from "@/lib/vault-api";
import {
  useProject,
  useUpdateProject,
  useArchiveProject,
  useDeleteProject,
  useCreateWorkflow,
  useUpdateWorkflow,
  useDeleteWorkflow,
  useMoveWorkflow,
} from "@/lib/vault-hooks";

export default function ProjectView() {
  const { id } = useParams<{ id: string }>();
  const [, setLocation] = useLocation();
  const { toast } = useToast();

  // Dialog states
  const [isCreateWorkflowOpen, setIsCreateWorkflowOpen] = useState(false);
  const [isEditProjectOpen, setIsEditProjectOpen] = useState(false);
  const [deleteWorkflowId, setDeleteWorkflowId] = useState<string | null>(null);

  // Form states
  const [newWorkflow, setNewWorkflow] = useState({ title: "", description: "" });
  const [editProject, setEditProject] = useState({ title: "", description: "" });

  // Data queries
  const { data: projectWithWorkflows, isLoading } = useProject(id);

  // Mutations
  const updateProjectMutation = useUpdateProject();
  const archiveProjectMutation = useArchiveProject();
  const deleteProjectMutation = useDeleteProject();
  const createWorkflowMutation = useCreateWorkflow();
  const updateWorkflowMutation = useUpdateWorkflow();
  const deleteWorkflowMutation = useDeleteWorkflow();
  const moveWorkflowMutation = useMoveWorkflow();

  // Handlers
  const handleCreateWorkflow = async () => {
    if (!newWorkflow.title.trim()) {
      toast({ title: "Error", description: "Workflow title is required", variant: "destructive" });
      return;
    }

    try {
      const workflow = await createWorkflowMutation.mutateAsync({
        ...newWorkflow,
        projectId: id,
      });
      toast({ title: "Success", description: "Workflow created successfully" });
      setIsCreateWorkflowOpen(false);
      setNewWorkflow({ title: "", description: "" });
    } catch (error) {
      toast({ title: "Error", description: "Failed to create workflow", variant: "destructive" });
    }
  };

  const handleUpdateProject = async () => {
    if (!editProject.title.trim()) {
      toast({ title: "Error", description: "Project title is required", variant: "destructive" });
      return;
    }

    try {
      await updateProjectMutation.mutateAsync({
        id: id,
        ...editProject,
      });
      toast({ title: "Success", description: "Project updated successfully" });
      setIsEditProjectOpen(false);
    } catch (error) {
      toast({ title: "Error", description: "Failed to update project", variant: "destructive" });
    }
  };

  const handleArchiveWorkflow = async (workflowId: string) => {
    try {
      await updateWorkflowMutation.mutateAsync({ id: workflowId, status: "archived" });
      toast({ title: "Success", description: "Workflow archived" });
    } catch (error) {
      toast({ title: "Error", description: "Failed to archive workflow", variant: "destructive" });
    }
  };

  const handleActivateWorkflow = async (workflowId: string) => {
    try {
      await updateWorkflowMutation.mutateAsync({ id: workflowId, status: "active" });
      toast({ title: "Success", description: "Workflow activated" });
    } catch (error) {
      toast({ title: "Error", description: "Failed to activate workflow", variant: "destructive" });
    }
  };

  const handleMoveWorkflowOut = async (workflow: ApiWorkflow) => {
    try {
      await moveWorkflowMutation.mutateAsync({
        id: workflow.id,
        projectId: null,
      });
      toast({ title: "Success", description: "Workflow moved out of project" });
    } catch (error) {
      toast({ title: "Error", description: "Failed to move workflow", variant: "destructive" });
    }
  };

  const handleDeleteWorkflow = async () => {
    if (!deleteWorkflowId) { return; }

    try {
      await deleteWorkflowMutation.mutateAsync(deleteWorkflowId);
      toast({ title: "Success", description: "Workflow deleted" });
      setDeleteWorkflowId(null);
    } catch (error) {
      toast({ title: "Error", description: "Failed to delete workflow", variant: "destructive" });
    }
  };

  const openEditDialog = () => {
    if (projectWithWorkflows) {
      setEditProject({
        title: projectWithWorkflows.title,
        description: projectWithWorkflows.description ?? "",
      });
      setIsEditProjectOpen(true);
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background">
        <div className="container mx-auto p-8 max-w-7xl">
          <Skeleton className="h-10 w-64 mb-8" />
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            {[1, 2, 3].map((i) => (
              <Card key={i}>
                <div className="p-6">
                  <Skeleton className="h-6 w-3/4 mb-2" />
                  <Skeleton className="h-4 w-full mb-4" />
                  <Skeleton className="h-4 w-1/2" />
                </div>
              </Card>
            ))}
          </div>
        </div>
      </div>
    );
  }

  if (!projectWithWorkflows) {
    return (
      <div className="min-h-screen bg-background">
        <div className="container mx-auto p-8 max-w-7xl">
          <Card>
            <CardContent className="flex flex-col items-center justify-center py-16">
              <h3 className="text-lg font-semibold mb-2">Project not found</h3>
              <p className="text-muted-foreground text-sm mb-4">
                The project you're looking for doesn't exist or you don't have access to it.
              </p>
              <Link href="/workflows">
                <Button>
                  <ArrowLeft className="w-4 h-4 mr-2" />
                  Back to Workflows
                </Button>
              </Link>
            </CardContent>
          </Card>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background">
      <div className="container mx-auto p-8 max-w-7xl">
        {/* Header with breadcrumb */}
        <div className="mb-8">
          <Link href="/workflows">
            <Button variant="ghost" className="mb-4 -ml-4">
              <ArrowLeft className="w-4 h-4 mr-2" />
              Back to Workflows
            </Button>
          </Link>
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-3xl font-bold tracking-tight">{projectWithWorkflows.title}</h1>
              {projectWithWorkflows.description && (
                <p className="text-muted-foreground mt-2">{projectWithWorkflows.description}</p>
              )}
            </div>
            <div className="flex gap-2">
              <Button variant="outline" onClick={openEditDialog}>
                <Edit className="w-4 h-4 mr-2" />
                Edit Project
              </Button>
              <Button onClick={() => { void setIsCreateWorkflowOpen(true); }}>
                <Plus className="w-4 h-4 mr-2" />
                New Workflow
              </Button>
            </div>
          </div>
        </div>

        {/* Workflows Grid */}
        {projectWithWorkflows.workflows.length === 0 ? (
          <Card className="border-dashed">
            <CardContent className="flex flex-col items-center justify-center py-16">
              <h3 className="text-lg font-semibold mb-2">No workflows in this project</h3>
              <p className="text-muted-foreground text-sm mb-4">
                Get started by creating your first workflow in this project
              </p>
              <Button onClick={() => { void setIsCreateWorkflowOpen(true); }}>
                <Plus className="w-4 h-4 mr-2" />
                Create Workflow
              </Button>
            </CardContent>
          </Card>
        ) : (
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            {projectWithWorkflows.workflows.map((workflow) => (
              <WorkflowCard
                key={workflow.id}
                workflow={workflow}
                onMove={(w) => { void handleMoveWorkflowOut(w); }}
                onArchive={(id) => { void handleArchiveWorkflow(id); }}
                onActivate={(id) => { void handleActivateWorkflow(id); }}
                onDelete={(id) => setDeleteWorkflowId(id)}
              />
            ))}
          </div>
        )}
      </div>

      {/* Edit Project Dialog */}
      <Dialog open={isEditProjectOpen} onOpenChange={setIsEditProjectOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Edit Project</DialogTitle>
            <DialogDescription>Update your project details</DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="project-title">Title *</Label>
              <Input
                id="project-title"
                placeholder="e.g., Customer Onboarding"
                value={editProject.title}
                onChange={(e) => { void setEditProject({ ...editProject, title: e.target.value }); }}
                onKeyDown={(e) => { void e.key === "Enter" && handleUpdateProject(); }}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="project-description">Description</Label>
              <Textarea
                id="project-description"
                placeholder="Optional description..."
                value={editProject.description}
                onChange={(e) => { void setEditProject({ ...editProject, description: e.target.value }); }}
                rows={3}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => { void setIsEditProjectOpen(false); }}>
              Cancel
            </Button>
            <Button onClick={() => { void handleUpdateProject(); }} disabled={updateProjectMutation.isPending}>
              {updateProjectMutation.isPending ? "Saving..." : "Update"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Create Workflow Dialog */}
      <Dialog open={isCreateWorkflowOpen} onOpenChange={setIsCreateWorkflowOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Create Workflow</DialogTitle>
            <DialogDescription>Create a new workflow in this project</DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="workflow-title">Title *</Label>
              <Input
                id="workflow-title"
                placeholder="e.g., Onboarding Survey"
                value={newWorkflow.title}
                onChange={(e) => { void setNewWorkflow({ ...newWorkflow, title: e.target.value }); }}
                onKeyDown={(e) => { void e.key === "Enter" && handleCreateWorkflow(); }}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="workflow-description">Description</Label>
              <Textarea
                id="workflow-description"
                placeholder="Optional description..."
                value={newWorkflow.description}
                onChange={(e) => { void setNewWorkflow({ ...newWorkflow, description: e.target.value }); }}
                rows={3}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => { void setIsCreateWorkflowOpen(false); }}>
              Cancel
            </Button>
            <Button onClick={() => { void handleCreateWorkflow(); }} disabled={createWorkflowMutation.isPending}>
              {createWorkflowMutation.isPending ? "Creating..." : "Create"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete Workflow Confirmation */}
      <AlertDialog open={!!deleteWorkflowId} onOpenChange={() => setDeleteWorkflowId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Workflow?</AlertDialogTitle>
            <AlertDialogDescription>
              This action cannot be undone. All sections, steps, blocks, and runs will be permanently deleted.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => { void handleDeleteWorkflow(); }}
              className="bg-destructive text-destructive-foreground"
            >
              {deleteWorkflowMutation.isPending ? "Deleting..." : "Delete"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useQuery } from '@tanstack/react-query';
import { Loader2, Download, FileText, CheckCircle2, AlertCircle, Play } from "lucide-react";
import { useEffect } from 'react';
import ReactMarkdown from 'react-markdown';
import { useRoute } from "wouter";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"; // Assuming Alert exists
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";

interface GeneratedDocument {
    id: string;
    fileName: string;
    fileUrl: string;
    mimeType: string;
    fileSize: number;
}

interface RunDetailsResponse {
    run: any;
    documents: GeneratedDocument[];
    finalBlockConfig: {
        title?: string;
        message?: string;
        showDocuments?: boolean;
        customLinks?: Array<{ label: string; url: string; style: 'button' | 'link' }>;
        brandingColor?: string;
        redirectUrl?: string;
    } | null;
}

export default function RunCompletionView() {
    const [match, params] = useRoute("/share/:token");
    const token = params?.token;

    const { data, isLoading, error } = useQuery<{ success: boolean; data: RunDetailsResponse }>({
        queryKey: ['shared-run', token],
        queryFn: async () => {
            const res = await fetch(`/api/shared/runs/${token}`);
            if (!res.ok) {
                const err = await res.json();
                throw new Error(err.error || 'Failed to load run');
            }
            return res.json();
        },
        enabled: !!token,
        retry: false
    });

    const { run, documents, finalBlockConfig } = data?.data || {};

    // Default configuration if missing (e.g. legacy runs without final block)
    const config = finalBlockConfig || {
        title: "Workflow Complete",
        message: "Thank you for completing the workflow. Your documents are ready below.",
        showDocuments: true,
        customLinks: [],
        brandingColor: "#10b981" // Default green
    };

    const brandingStyle = {
        backgroundColor: config.brandingColor || "#10b981",
    };

    // Redirect logic
    useEffect(() => {
        if (config.redirectUrl && !isLoading && data) {
            setTimeout(() => {
                window.location.href = config.redirectUrl!;
            }, 5000); // 5 second delay before redirect
        }
    }, [config.redirectUrl, isLoading, data]);

    if (isLoading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50">
                <Loader2 className="h-12 w-12 animate-spin text-primary" />
            </div>
        );
    }

    if (error) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4">
                <Alert variant="destructive" className="max-w-md">
                    <AlertCircle className="h-4 w-4" />
                    <AlertTitle>Error</AlertTitle>
                    <AlertDescription>
                        {error instanceof Error ? error.message : "This link is invalid or has expired."}
                    </AlertDescription>
                </Alert>
            </div>
        );
    }

    if (!data?.success) {
        return null; // Should be handled by error state
    }

    return (
        <div className="min-h-screen bg-gray-50 flex flex-col items-center py-12 px-4 sm:px-6 lg:px-8">
            <div className="max-w-3xl w-full space-y-8">

                {/* Header Section */}
                <div className="text-center">
                    <div
                        className="mx-auto flex h-16 w-16 items-center justify-center rounded-full text-white mb-4 shadow-lg"
                        style={brandingStyle}
                    >
                        <CheckCircle2 className="h-10 w-10" />
                    </div>


                    <h2 className="text-3xl font-bold tracking-tight text-gray-900 sm:text-4xl">
                        {(!run.completed && config.title === "Workflow Complete")
                            ? "Workflow Paused"
                            : (config.title || "Workflow Complete")}
                    </h2>

                    <div className="mt-4 text-lg text-gray-600 prose prose-sm max-w-none">
                        <ReactMarkdown>{config.message ?? ""}</ReactMarkdown>
                    </div>
                </div>

                {/* Documents Section */}
                {config.showDocuments && documents && documents.length > 0 && run.completed && run.accessSettings?.allow_redownload !== false && (
                    <Card className="overflow-hidden shadow-sm border-gray-200">
                        <CardHeader className="bg-gray-50/50 border-b border-gray-100">
                            <CardTitle className="text-xl flex items-center gap-2">
                                <FileText className="h-5 w-5 text-gray-500" />
                                Generated Documents
                            </CardTitle>
                            <CardDescription>
                                Please download your documents below.
                            </CardDescription>
                        </CardHeader>
                        <CardContent className="divide-y divide-gray-100 p-0">
                            {documents.map((doc) => (
                                <div key={doc.id} className="flex items-center justify-between p-4 hover:bg-gray-50 transition-colors">
                                    <div className="flex items-center gap-3">
                                        <div className="p-2 bg-blue-50 text-blue-600 rounded-lg">
                                            <FileText className="h-5 w-5" />
                                        </div>
                                        <div>
                                            <p className="font-medium text-gray-900">{doc.fileName}</p>
                                            <p className="text-sm text-gray-500">{(doc.fileSize / 1024).toFixed(1)} KB ΓÇó {doc.mimeType?.split('/')[1]?.toUpperCase() || 'FILE'}</p>
                                        </div>
                                    </div>
                                    <Button
                                        variant="outline"
                                        size="sm"
                                        asChild
                                        className="gap-2"
                                    >
                                        <a href={doc.fileUrl} download target="_blank" rel="noopener noreferrer">
                                            <Download className="h-4 w-4" />
                                            Download
                                        </a>
                                    </Button>
                                </div>
                            ))}
                        </CardContent>
                    </Card>
                )}

                {/* Resume Action */}
                {!run.completed && run.accessSettings?.allow_resume !== false && (
                    <div className="flex justify-center mt-8">
                        <Button size="lg" onClick={() => window.location.href = `/run/${run.id}?token=${run.runToken}`}>
                            <Play className="h-5 w-5 mr-2" />
                            Resume Workflow
                        </Button>
                    </div>
                )}

                {/* Actions / Links Section */}
                {(config.customLinks && config.customLinks.length > 0) && (
                    <div className="flex flex-col sm:flex-row gap-4 justify-center mt-8">
                        {config.customLinks.map((link, idx) => (
                            <Button
                                key={idx}
                                variant={link.style === 'button' ? 'default' : 'ghost'}
                                size="lg"
                                asChild
                                style={link.style === 'button' ? { backgroundColor: config.brandingColor } : {}}
                            >
                                <a href={link.url} target="_blank" rel="noopener noreferrer">
                                    {link.label}
                                </a>
                            </Button>
                        ))}
                    </div>
                )}

                {/* Footer / Branding */}
                <div className="mt-12 text-center text-sm text-gray-400">
                    Powered by ezBuildr
                </div>
            </div>
        </div>
    );
}

/**
 * Run Details Page
 * Stage 8: View run details with trace, inputs, outputs, logs, and metadata
 */
import { useQuery, useMutation } from '@tanstack/react-query';
import { formatDistanceToNow } from 'date-fns';
import { ArrowLeft, Download, PlayCircle, FileText, Share2, Copy } from 'lucide-react';
import { useState } from 'react';
import { useRoute, useLocation } from 'wouter';

import { TracePanel } from '@/components/runs/TracePanel';
import { JsonViewer } from '@/components/shared/JsonViewer';
import { LoadingState } from '@/components/shared/LoadingState';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader } from '@/components/ui/card';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { useToast } from '@/hooks/use-toast';
import { documentRunsAPI } from '@/lib/vault-api';
export default function RunDetails() {
  const [_, params] = useRoute('/runs/:id');
  const [_location, setLocation] = useLocation();
  const { toast } = useToast();
  const runId = params?.id;
  const [shareDialogOpen, setShareDialogOpen] = useState(false);
  const [shareLink, setShareLink] = useState("");
  const { data: run, isLoading, error } = useQuery({
    queryKey: ['document-run', runId],
    queryFn: () => documentRunsAPI.get(runId!),
    enabled: !!runId,
  });
  const { data: logs } = useQuery({
    queryKey: ['document-run-logs', runId],
    queryFn: () => documentRunsAPI.getLogs(runId!, { limit: 100 }),
    enabled: !!runId,
  });
  const rerunMutation = useMutation({
    mutationFn: () => documentRunsAPI.rerun(runId!),
    onSuccess: (data) => {
      toast({
        title: 'Run started',
        description: 'Workflow is being re-executed',
      });
      setLocation(`/runs/${data.runId}`);
    },
    onError: (error: Error) => {
      toast({
        variant: 'destructive',
        title: 'Re-run failed',
        description: error.message,
      });
    },
  });
  const shareMutation = useMutation({
    mutationFn: () => documentRunsAPI.share(runId!),
    onSuccess: (data) => {
      const link = `${window.location.origin}/share/${data.shareToken}`;
      setShareLink(link);
      setShareDialogOpen(true);
    },
    onError: (error: Error) => {
      toast({
        variant: 'destructive',
        title: 'Share failed',
        description: error.message,
      });
    },
  });
  const handleCopyLink = () => {
    navigator.clipboard.writeText(shareLink);
    toast({
      title: 'Copied!',
      description: 'Link copied to clipboard.',
    });
  };
  if (isLoading) {
    return <LoadingState />;
  }
  if (error || !run) {
    return (
      <div className="container mx-auto py-6">
        <div className="text-center">
          <p className="text-destructive">Error loading run details</p>
          <Button onClick={() => { void setLocation('/runs'); }} className="mt-4">
            Back to Runs
          </Button>
        </div>
      </div>
    );
  }
  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'success':
        return <Badge className="bg-green-500">Success</Badge>;
      case 'error':
        return <Badge variant="destructive">Error</Badge>;
      case 'pending':
        return <Badge variant="secondary">Pending</Badge>;
      default:
        return <Badge variant="outline">{status}</Badge>;
    }
  };
  const formatDuration = (ms?: number) => {
    if (!ms) {return '-';}
    if (ms < 1000) {return `${ms}ms`;}
    if (ms < 60000) {return `${(ms / 1000).toFixed(2)}s`;}
    return `${(ms / 60000).toFixed(2)}m`;
  };
  return (
    <div className="container mx-auto py-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => { void setLocation('/runs'); }}
          >
            <ArrowLeft className="h-4 w-4 mr-2" />
            Back
          </Button>
          <div>
            <h1 className="text-3xl font-bold">Run Details</h1>
            <p className="text-sm text-muted-foreground mt-1">
              {run.workflowVersion?.workflow?.name} ΓÇó {run.workflowVersion?.name}
            </p>
          </div>
        </div>
        <div className="flex gap-2">
          {run.status === 'success' && run.outputRefs && (
            <>
              <Button variant="outline" size="sm" asChild>
                <a
                  href={documentRunsAPI.downloadUrl(run.id, 'docx')}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  <Download className="h-4 w-4 mr-2" />
                  Download DOCX
                </a>
              </Button>
              <Button variant="outline" size="sm" asChild>
                <a
                  href={documentRunsAPI.downloadUrl(run.id, 'pdf')}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  <FileText className="h-4 w-4 mr-2" />
                  Download PDF
                </a>
              </Button>
            </>
          )}
          <Button
            variant="outline"
            size="sm"
            onClick={() => { void shareMutation.mutate(); }}
            disabled={shareMutation.isPending}
          >
            <Share2 className="h-4 w-4 mr-2" />
            Share
          </Button>
          <Button
            size="sm"
            onClick={() => { void rerunMutation.mutate(); }}
            disabled={rerunMutation.isPending}
          >
            <PlayCircle className="h-4 w-4 mr-2" />
            Re-run
          </Button>
        </div>
      </div>
      {/* Status Card */}
      <Card>
        <CardContent className="pt-6">
          <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
            <div>
              <div className="text-sm text-muted-foreground">Status</div>
              <div className="mt-1">{getStatusBadge(run.status)}</div>
            </div>
            <div>
              <div className="text-sm text-muted-foreground">Duration</div>
              <div className="mt-1 font-medium">{formatDuration(run.durationMs)}</div>
            </div>
            <div>
              <div className="text-sm text-muted-foreground">Started</div>
              <div className="mt-1 font-medium">
                {formatDistanceToNow(new Date(run.createdAt), { addSuffix: true })}
              </div>
            </div>
            <div>
              <div className="text-sm text-muted-foreground">Created By</div>
              <div className="mt-1 font-medium">
                {run.createdByUser?.email || run.createdBy}
              </div>
            </div>
            <div>
              <div className="text-sm text-muted-foreground">Run ID</div>
              <div className="mt-1 font-mono text-xs">{run.id.slice(0, 8)}...</div>
            </div>
          </div>
          {run.error && (
            <div className="mt-4 p-4 bg-destructive/10 border border-destructive rounded-md">
              <div className="text-sm font-semibold text-destructive">Error</div>
              <div className="mt-1 text-sm">{run.error}</div>
            </div>
          )}
        </CardContent>
      </Card>
      {/* Tabs */}
      <Card>
        <Tabs defaultValue="trace" className="w-full">
          <CardHeader>
            <TabsList>
              <TabsTrigger value="trace">Trace</TabsTrigger>
              <TabsTrigger value="inputs">Inputs</TabsTrigger>
              <TabsTrigger value="outputs">Outputs</TabsTrigger>
              <TabsTrigger value="logs">Logs</TabsTrigger>
              <TabsTrigger value="meta">Metadata</TabsTrigger>
            </TabsList>
          </CardHeader>
          <CardContent>
            {/* Trace Tab */}
            <TabsContent value="trace">
              {run.trace && run.trace.length > 0 ? (
                <TracePanel trace={run.trace} />
              ) : (
                <div className="text-center py-8 text-muted-foreground">
                  No trace data available
                </div>
              )}
            </TabsContent>
            {/* Inputs Tab */}
            <TabsContent value="inputs">
              {run.inputJson ? (
                <JsonViewer data={run.inputJson} maxHeight="600px" />
              ) : (
                <div className="text-center py-8 text-muted-foreground">
                  No input data
                </div>
              )}
            </TabsContent>
            {/* Outputs Tab */}
            <TabsContent value="outputs">
              {run.outputRefs ? (
                <div className="space-y-4">
                  <JsonViewer data={run.outputRefs} maxHeight="600px" />
                  {run.status === 'success' && (
                    <div className="flex gap-2">
                      <Button variant="outline" asChild>
                        <a
                          href={documentRunsAPI.downloadUrl(run.id, 'docx')}
                          target="_blank"
                          rel="noopener noreferrer"
                        >
                          <Download className="h-4 w-4 mr-2" />
                          Download DOCX
                        </a>
                      </Button>
                      <Button variant="outline" asChild>
                        <a
                          href={documentRunsAPI.downloadUrl(run.id, 'pdf')}
                          target="_blank"
                          rel="noopener noreferrer"
                        >
                          <FileText className="h-4 w-4 mr-2" />
                          Download PDF
                        </a>
                      </Button>
                    </div>
                  )}
                </div>
              ) : (
                <div className="text-center py-8 text-muted-foreground">
                  No output files
                </div>
              )}
            </TabsContent>
            {/* Logs Tab */}
            <TabsContent value="logs">
              {logs && logs.items.length > 0 ? (
                <div className="space-y-2">
                  {logs.items.map((log) => (
                    <div
                      key={log.id}
                      className="p-3 border rounded-md bg-muted/30 font-mono text-sm"
                    >
                      <div className="flex items-start gap-2">
                        <Badge variant={log.level === 'error' ? 'destructive' : 'secondary'}>
                          {log.level}
                        </Badge>
                        <div className="flex-1">
                          <div>{log.message}</div>
                          {log.nodeId && (
                            <div className="text-xs text-muted-foreground mt-1">
                              Node: {log.nodeId}
                            </div>
                          )}
                          <div className="text-xs text-muted-foreground mt-1">
                            {new Date(log.createdAt).toLocaleString()}
                          </div>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-8 text-muted-foreground">
                  No logs available
                </div>
              )}
            </TabsContent>
            {/* Metadata Tab */}
            <TabsContent value="meta">
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <div className="text-sm font-semibold">Run ID</div>
                    <div className="mt-1 font-mono text-sm">{run.id}</div>
                  </div>
                  <div>
                    <div className="text-sm font-semibold">Workflow Version ID</div>
                    <div className="mt-1 font-mono text-sm">{run.workflowVersionId}</div>
                  </div>
                  <div>
                    <div className="text-sm font-semibold">Workflow</div>
                    <div className="mt-1">{run.workflowVersion?.workflow?.name}</div>
                  </div>
                  <div>
                    <div className="text-sm font-semibold">Version</div>
                    <div className="mt-1">{run.workflowVersion?.name}</div>
                  </div>
                  <div>
                    <div className="text-sm font-semibold">Created At</div>
                    <div className="mt-1">{new Date(run.createdAt).toLocaleString()}</div>
                  </div>
                  <div>
                    <div className="text-sm font-semibold">Updated At</div>
                    <div className="mt-1">{new Date(run.updatedAt).toLocaleString()}</div>
                  </div>
                </div>
              </div>
            </TabsContent>
          </CardContent>
        </Tabs>
      </Card>
      <Dialog open={shareDialogOpen} onOpenChange={setShareDialogOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Share Run</DialogTitle>
            <DialogDescription>
              Anyone with this link can view the run completion page and download documents.
            </DialogDescription>
          </DialogHeader>
          <div className="flex items-center space-x-2">
            <div className="grid flex-1 gap-2">
              <Label htmlFor="link" className="sr-only">
                Link
              </Label>
              <Input
                id="link"
                defaultValue={shareLink}
                value={shareLink}
                readOnly
              />
            </div>
            <Button type="button" size="sm" className="px-3" onClick={() => { void handleCopyLink(); }}>
              <span className="sr-only">Copy</span>
              <Copy className="h-4 w-4" />
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div >
  );
}

/**
 * Runs Compare Page
 * Stage 8: Compare two runs side-by-side
 */

import { useQuery } from '@tanstack/react-query';
import { ArrowLeft } from 'lucide-react';
import { useLocation } from 'wouter';

import { JsonViewer } from '@/components/shared/JsonViewer';
import { LoadingState } from '@/components/shared/LoadingState';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { documentRunsAPI } from '@/lib/vault-api';

export default function RunsCompare() {
  const [_location, setLocation] = useLocation();

  // Get runA and runB from URL query params
  const searchParams = new URLSearchParams(window.location.search);
  const runA = searchParams.get('runA');
  const runB = searchParams.get('runB');

  const { data, isLoading, error } = useQuery({
    queryKey: ['compare-runs', runA, runB],
