            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => { void setIsCreateWorkflowOpen(false); }}>
              Cancel
            </Button>
            <Button onClick={() => { void handleCreateWorkflow(); }} disabled={createWorkflowMutation.isPending}>
              {createWorkflowMutation.isPending ? "Creating..." : "Create"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
      {/* Move Workflow Dialog */}
      <Dialog open={isMoveWorkflowOpen} onOpenChange={setIsMoveWorkflowOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Move Workflow</DialogTitle>
            <DialogDescription>
              Move "{movingWorkflow?.title}" to a project or unfiled
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="target-project">Target Project</Label>
              <Select
                value={targetProjectId || "unfiled"}
                onValueChange={(value) => setTargetProjectId(value === "unfiled" ? null : value)}
              >
                <SelectTrigger id="target-project">
                  <SelectValue placeholder="Select a project" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="unfiled">Unfiled</SelectItem>
                  {projects?.map((project) => (
                    <SelectItem key={project.id} value={project.id}>
                      {project.title}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => { void setIsMoveWorkflowOpen(false); }}>
              Cancel
            </Button>
            <Button onClick={() => { void handleMoveWorkflow(); }} disabled={moveWorkflowMutation.isPending}>
              {moveWorkflowMutation.isPending ? "Moving..." : "Move"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
      {/* Delete Project Confirmation */}
      <AlertDialog open={!!deleteProjectId} onOpenChange={() => setDeleteProjectId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Project?</AlertDialogTitle>
            <AlertDialogDescription>
              This action cannot be undone. The project will be deleted, but workflows inside will be moved to
              unfiled.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => { void handleDeleteProject(); }}
              className="bg-destructive text-destructive-foreground"
            >
              {deleteProjectMutation.isPending ? "Deleting..." : "Delete"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
      {/* Delete Workflow Confirmation */}
      <AlertDialog open={!!deleteWorkflowId} onOpenChange={() => setDeleteWorkflowId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Workflow?</AlertDialogTitle>
            <AlertDialogDescription>
              This action cannot be undone. All sections, steps, blocks, and runs will be permanently deleted.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => { void handleDeleteWorkflow(); }}
              className="bg-destructive text-destructive-foreground"
            >
              {deleteWorkflowMutation.isPending ? "Deleting..." : "Delete"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

/**
 * Workflow Runner - Participant view for completing workflows
 *
 * Supports two modes:
 * 1. Production mode: runId is a real database run
 * 2. Preview mode: previewEnvironment is an in-memory PreviewEnvironment instance
 */
import { useQuery } from "@tanstack/react-query";
import { ChevronLeft, ChevronRight, Check, Loader2, Database } from "lucide-react";
import { useState, useEffect, useMemo } from "react";

// import { useRunWithValues, useSections, useSteps, useSubmitSection, useNext, useCompleteRun } from "@/lib/vault-hooks";
// Importing individually to avoid lint 'Module not found' if aliases differ, but they seem to use @/lib/vault-hooks
import { BlockRenderer } from "@/components/runner/blocks";
import { ClientRunnerLayout } from "@/components/runner/ClientRunnerLayout";
import { FinalDocumentsSection } from "@/components/runner/sections/FinalDocumentsSection";
import { IntakeAssignmentSection } from "@/components/runner/sections/IntakeAssignmentSection";
import { ReviewSection } from "@/components/runner/sections/ReviewSection";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { useToast } from "@/hooks/use-toast";
import { useIntakeRuntime } from "@/hooks/useIntakeRuntime";
import { useWorkflowVisibility } from "@/hooks/useWorkflowVisibility";
import { analytics } from "@/lib/analytics";
import { PreviewEnvironment } from "@/lib/previewRunner/PreviewEnvironment";
import { usePreviewEnvironment } from "@/lib/previewRunner/usePreviewEnvironment";
