import { Mail } from "lucide-react";
import React, { useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { useToast } from "@/hooks/use-toast";
import { api } from "@/lib/api";

export default function PortalLogin() {
    const [email, setEmail] = useState("");
    const [submitted, setSubmitted] = useState(false);
    const [loading, setLoading] = useState(false);
    const { toast } = useToast();

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!email) {return;}

        setLoading(true);
        try {
            await api.post("/portal/auth/send", { email });
            setSubmitted(true);
            toast({
                title: "Magic Link Sent",
                description: "Check your email for a link to sign in.",
            });
        } catch (error) {
            toast({
                title: "Error",
                description: "Failed to send magic link. Please try again.",
                variant: "destructive",
            });
        } finally {
            setLoading(false);
        }
    };

    if (submitted) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4">
                <Card className="w-full max-w-md text-center">
                    <CardHeader>
                        <div className="mx-auto bg-green-100 p-3 rounded-full w-12 h-12 flex items-center justify-center mb-4">
                            <Mail className="h-6 w-6 text-green-600" />
                        </div>
                        <CardTitle>Check your email</CardTitle>
                        <CardDescription>
                            We've sent a magic link to <strong>{email}</strong>.
                            <br />
                            Click the link to sign in.
                        </CardDescription>
                    </CardHeader>
                    <CardContent>
                        <Button variant="outline" onClick={() => { void setSubmitted(false); }} className="mt-4">
                            Use a different email
                        </Button>
                    </CardContent>
                </Card>
            </div>
        );
    }

    return (
        <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4">
            <Card className="w-full max-w-md">
                <CardHeader>
                    <CardTitle>Client Portal</CardTitle>
                    <CardDescription>
                        Enter your email to access your completed workflows and documents.
                    </CardDescription>
                </CardHeader>
                <CardContent>
                    <form onSubmit={(e) => { e.preventDefault(); void handleSubmit(e); }} className="space-y-4">
                        <div className="space-y-2">
                            <Input
                                type="email"
                                placeholder="name@example.com"
                                value={email}
                                onChange={(e) => { void setEmail(e.target.value); }}
                                required
                                disabled={loading}
                            />
                        </div>
                        <Button type="submit" className="w-full" disabled={loading}>
                            {loading ? "Sending..." : "Send Magic Link"}
                        </Button>
                    </form>
                </CardContent>
            </Card>
        </div>
    );
}

import { Loader2 } from "lucide-react";
import { useEffect, useState } from "react";
import { useLocation } from "wouter";

import { useToast } from "@/hooks/use-toast";
import { api } from "@/lib/api";
export default function PortalMagicLink() {
    const [location, setLocation] = useLocation();
    const [verifying, setVerifying] = useState(true);
    const { toast } = useToast();
    useEffect(() => {
        const verifyToken = async () => {
            // Extract token from URL search params
            const searchParams = new URLSearchParams(window.location.search);
            const token = searchParams.get("token");
            if (!token) {
                toast({
                    title: "Invalid Link",
                    description: "No token provided in the link.",
                    variant: "destructive",
                });
                setLocation("/portal/login");
                return;
            }
            try {
                await api.post("/portal/auth/verify", { token });
                toast({
                    title: "Welcome back!",
                    description: "You have successfully signed in.",
                });
                setLocation("/portal");
            } catch (error) {
                toast({
                    title: "Sign In Failed",
                    description: "The link may be expired or invalid. Please try again.",
                    variant: "destructive",
                });
                setLocation("/portal/login");
            } finally {
                setVerifying(false); // Probably redirects before this, but good for cleanup
            }
        };
        void verifyToken();
    }, [setLocation, toast]);
    return (
        <div className="min-h-screen flex items-center justify-center bg-gray-50">
            <div className="text-center">
                <Loader2 className="h-10 w-10 animate-spin text-primary mx-auto mb-4" />
                <h2 className="text-xl font-semibold">Verifying your link...</h2>
            </div>
        </div>
    );
}

import { Loader2, AlertCircle } from "lucide-react";
import { useEffect, useState } from 'react';
import { useRoute } from "wouter";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";

import { FloatingAIAssist } from "./components/FloatingAIAssist";

interface PublicWorkflow {
    id: string;
    title: string;
    description: string;
    publicSettings?: any;
}

export default function PublicRunner() {
    const [, params] = useRoute("/w/:slug");
    const slug = params?.slug;

    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [workflow, setWorkflow] = useState<PublicWorkflow | null>(null);
    const [runState, setRunState] = useState<'idle' | 'running' | 'completed'>('idle');

    useEffect(() => {
        if (slug) {
            void fetchWorkflow();
        }
    }, [slug]);

    const fetchWorkflow = async () => {
        try {
            const res = await fetch(`/public/w/${slug}`);
            if (!res.ok) {
                if (res.status === 404) { throw new Error("Workflow not found or private"); }
                throw new Error("Failed to load workflow");
            }
            const data = await res.json();
            setWorkflow(data);
        } catch (err: any) {
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    const startRun = async () => {
        try {
            setRunState('running');
            const res = await fetch(`/public/w/${slug}/run`, { method: 'POST' });
            if (!res.ok) { throw new Error("Failed to start run"); }
            const data = await res.json();
            // In a real app, this would initialize a Multi-Step Runner component
            // For now, we simulate completion
            setTimeout(() => {
                setRunState('completed');
            }, 1000);
        } catch (err: any) {
            setError(err.message);
            setRunState('idle');
        }
    };

    if (loading) {
        return (
            <div className="flex h-screen items-center justify-center bg-gray-50">
                <Loader2 className="w-8 h-8 animate-spin text-primary" />
            </div>
        );
    }

    if (error) {
        return (
            <div className="flex h-screen items-center justify-center bg-gray-50 p-4">
                <Alert variant="destructive" className="max-w-md">
                    <AlertCircle className="h-4 w-4" />
                    <AlertTitle>Error</AlertTitle>
                    <AlertDescription>{error}</AlertDescription>
                </Alert>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-50 flex flex-col items-center py-12 px-4 sm:px-6 lg:px-8">
            <div className="max-w-3xl w-full space-y-8">
                <div className="text-center">
                    <h1 className="text-4xl font-extrabold text-gray-900 tracking-tight sm:text-5xl">
                        {workflow?.title}
                    </h1>
                    <p className="mt-4 text-lg text-gray-600">
                        {workflow?.description}
                    </p>
                </div>

                <Card className="mt-8 bg-white shadow-xl rounded-xl overflow-hidden border-0 ring-1 ring-gray-200">
                    <CardContent className="p-8">
                        {runState === 'idle' && (
                            <div className="text-center py-8">
                                <Button size="lg" onClick={() => { void startRun(); }} className="w-full sm:w-auto text-lg px-8 py-6 h-auto">
                                    Start Workflow
                                </Button>
                            </div>
                        )}

                        {runState === 'running' && (
                            <div className="flex flex-col items-center justify-center py-12 space-y-4">
                                <Loader2 className="w-12 h-12 animate-spin text-primary" />
                                <p className="text-gray-500">Initializing Workflow...</p>
                            </div>
                        )}

                        {runState === 'completed' && (
                            <div className="text-center py-8 space-y-4">
                                <div className="mx-auto w-16 h-16 bg-green-100 rounded-full flex items-center justify-center">
                                    <span className="text-2xl">≡ƒÄë</span>
                                </div>
                                <h3 className="text-xl font-medium text-gray-900">Completed!</h3>
                                <p className="text-gray-500">Thank you for completing this workflow.</p>
                            </div>
                        )}
                    </CardContent>
                </Card>

                <div className="text-center text-sm text-gray-400">
                    Powered by ezBuildr
                </div>
            </div>
            <FloatingAIAssist
                currentBlockText={workflow?.description || "Welcome to the workflow."} // Placeholder for current block
            />
        </div>

    );
}

import { Sparkles, X, MessageSquare, HelpCircle, Settings } from 'lucide-react';
