    return (
        <div className="fixed bottom-4 right-4 w-96 bg-background border rounded-xl shadow-2xl z-50 flex flex-col max-h-[80vh]">
            <div className="p-4 border-b flex justify-between items-center bg-muted/40 rounded-t-xl">
