                            </SelectContent>
                        </Select>
                    </div>
                    <div className="space-y-2">
                        <Label>Reading Level</Label>
                        <Select
                            value={settings.readingLevel}
                            onValueChange={(v: any) => setSettings({ readingLevel: v })}
                        >
                            <SelectTrigger>
