            <div className="space-y-2">
              {edges.map((edge) => (
                <Card key={edge.id} className="p-3">
                  <div className="space-y-2">
                    <div className="flex items-center gap-2">
                      <Badge
                        className={`${
                          nodeTypeColors[getNodeType(edge.source) as keyof typeof nodeTypeColors] || 'bg-gray-500'
                        } text-white text-xs`}
