                    </Button>
                  </div>
                </Card>
              ))}
            </div>
          )}
        </ScrollArea>
      </CardContent>
    </Card>
  );
}

import axios from 'axios';
import DOMPurify from 'dompurify';
import { Loader2, FileEdit } from 'lucide-react';
import mammoth from 'mammoth';
import { useState, useEffect, useMemo } from 'react';

import { Button } from '@/components/ui/button';
import { Dialog, DialogContent } from '@/components/ui/dialog';

import { AIAssistPanel } from './AIAssistPanel';
interface DocumentTemplateEditorProps {
    templateId: string;
    isOpen: boolean;
    onClose: () => void;
    workflowVariables: any[];
}
export function DocumentTemplateEditor({ templateId, isOpen, onClose, workflowVariables }: DocumentTemplateEditorProps) {
    const [htmlContent, setHtmlContent] = useState<string>('');
    const [isLoading, setIsLoading] = useState(false);
    const [fileBuffer, setFileBuffer] = useState<ArrayBuffer | undefined>(undefined);
    const [fileName, setFileName] = useState<string>('');
    // Fetch Template File
    // Note: Assuming an API exists to get the raw file or we reuse the upload buffer if new
    // For this mock, we'll try to fetch from a hypothetical download endpoint
    useEffect(() => {
        if (isOpen && templateId) {
            fetchTemplate();
        }
    }, [isOpen, templateId]);
    const fetchTemplate = async () => {
        setIsLoading(true);
        try {
            // Hypothetical endpoint to get file
            const response = await fetch(`/api/templates/${templateId}/download`);
            if (response.ok) {
                const buffer = await response.arrayBuffer();
                setFileBuffer(buffer);
                // Extract filename from header or default
                const disposition = response.headers.get('content-disposition');
                const name = disposition ? disposition.split('filename=')[1] : 'template.docx';
                setFileName(name.replace(/"/g, ''));
                if (name.endsWith('.docx')) {
                    const result = await mammoth.convertToHtml({ arrayBuffer: buffer });
                    setHtmlContent(result.value);
                } else if (name.endsWith('.pdf')) {
                    // Create a Blob URL for PDF preview
                    const blob = new Blob([buffer], { type: 'application/pdf' });
                    const url = URL.createObjectURL(blob);
                    setHtmlContent(url); // We'll use this as the src
                } else {
                    setHtmlContent("<p>Preview not available for this file type.</p>");
                }
            }
        } catch (e) {
            console.error("Failed to load template", e);
        } finally {
            setIsLoading(false);
        }
    };
    const handleApplyMapping = (mapping: any) => {
        console.log("Applying mapping", mapping);
        // TODO: Persist mapping to backend
    };
    // SECURITY FIX: Sanitize HTML content to prevent XSS attacks
    const sanitizedHtml = useMemo(() => {
        if (!htmlContent || fileName.endsWith('.pdf')) {
            return htmlContent;
        }
        return DOMPurify.sanitize(htmlContent, {
            ALLOWED_TAGS: [
                'p', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
                'ul', 'ol', 'li', 'strong', 'em', 'u', 'br',
                'table', 'thead', 'tbody', 'tr', 'td', 'th',
                'div', 'span', 'a', 'img', 'blockquote', 'pre', 'code'
            ],
            ALLOWED_ATTR: ['class', 'style', 'href', 'src', 'alt', 'title'],
            FORBID_TAGS: ['script', 'iframe', 'object', 'embed', 'link', 'form', 'input'],
            FORBID_ATTR: ['onerror', 'onload', 'onclick', 'onmouseover', 'onfocus', 'onblur']
        });
    }, [htmlContent, fileName]);
    return (
        <Dialog open={isOpen} onOpenChange={(val) => !val && onClose()}>
            <DialogContent className="max-w-[90vw] h-[90vh] flex flex-col p-0 gap-0 overflow-hidden">
                <div className="flex flex-1 overflow-hidden">
                    {/* Main Preview Area */}
                    <div className="flex-1 flex flex-col min-w-0 bg-gray-100 dark:bg-gray-950/50">
                        <div className="border-b bg-white dark:bg-zinc-900 p-4 flex items-center justify-between">
                            <div className="flex items-center gap-2">
                                <FileEdit className="w-5 h-5 text-blue-600" />
                                <h2 className="font-semibold">{fileName || 'Document Editor'}</h2>
                            </div>
                            <Button variant="ghost" size="sm" onClick={() => { void onClose(); }}>Close</Button>
                        </div>
                        <div className="flex-1 overflow-y-auto p-8 flex justify-center">
                            {isLoading ? (
                                <Loader2 className="animate-spin w-8 h-8 text-muted-foreground mt-10" />
                            ) : (
                                fileName.endsWith('.pdf') ? (
                                    <iframe
                                        src={htmlContent}
                                        className="w-full h-full min-h-[800px] shadow-lg"
                                        title="PDF Preview"
                                    />
                                ) : (
                                    <div
                                        className="bg-white shadow-lg p-10 min-h-[800px] w-[800px] prose dark:prose-invert max-w-none"
                                        dangerouslySetInnerHTML={{ __html: sanitizedHtml }}
                                    />
                                )
                            )}
                        </div>
                    </div>
                    {/* AI Assist Sidebar */}
                    <AIAssistPanel
                        templateId={templateId}
                        fileBuffer={fileBuffer}
                        fileName={fileName}
                        onApplyMapping={handleApplyMapping}
                        workflowVariables={workflowVariables}
                    />
                </div>
            </DialogContent>
        </Dialog>
    );
}

/**
 * ExpressionEditor - Monaco-based expression editor with autocomplete and diagnostics
 */

import Editor, { Monaco } from '@monaco-editor/react';
import { useRef, useEffect } from 'react';


import { useAvailableVars } from '../hooks/useAvailableVars';
import { useExpressionValidation } from '../hooks/useExpressionValidation';
import { useHelpers } from '../hooks/useHelpers';

import type { editor } from 'monaco-editor';

export interface ExpressionEditorProps {
  value: string;
  onChange: (value: string) => void;
  nodeId: string;
  workflowId: string;
  placeholder?: string;
  height?: string;
  language?: string;
}

export function ExpressionEditor({
  value,
  onChange,
  nodeId,
  workflowId,
  placeholder = 'Enter expression...',
  height = '100px',
  language = 'plaintext',
}: ExpressionEditorProps) {
  const editorRef = useRef<editor.IStandaloneCodeEditor | null>(null);
  const monacoRef = useRef<Monaco | null>(null);

  // Fetch available vars and helpers
  const { data: availableVarsData } = useAvailableVars(workflowId, nodeId);
  const { data: helpersData } = useHelpers();

  // Validation
  const { validate, validationResult, isValidating } = useExpressionValidation(
    workflowId,
    nodeId,
    300 // 300ms debounce
  );

  // Update validation when value changes
  useEffect(() => {
    if (value) {
      validate(value);
    }
  }, [value, validate]);

  // Update Monaco markers when validation result changes
  useEffect(() => {
    if (!editorRef.current || !monacoRef.current) {return;}

    const monaco = monacoRef.current;
    const model = editorRef.current.getModel();
    if (!model) {return;}

    // Clear previous markers
    monaco.editor.setModelMarkers(model, 'vl-expr', []);

    // Add new markers if there are errors
    if (validationResult && !validationResult.ok && validationResult.errors) {
      const markers = validationResult.errors.map((error) => ({
        severity: monaco.MarkerSeverity.Error,
        message: error.message,
        startLineNumber: error.start?.line ?? 1,
        startColumn: error.start?.col ?? 1,
        endLineNumber: error.end?.line ?? 1,
        endColumn: error.end?.col ?? 1000,
      }));

      monaco.editor.setModelMarkers(model, 'vl-expr', markers);
    }
  }, [validationResult]);

  const handleEditorDidMount = (editor: editor.IStandaloneCodeEditor, monaco: Monaco) => {
    editorRef.current = editor;
    monacoRef.current = monaco;

    // Register completion provider
    const disposable = monaco.languages.registerCompletionItemProvider(language, {
      triggerCharacters: ['.', '('],
      provideCompletionItems: (model, position) => {
        const word = model.getWordUntilPosition(position);
        const range = {
          startLineNumber: position.lineNumber,
          endLineNumber: position.lineNumber,
          startColumn: word.startColumn,
          endColumn: word.endColumn,
        };

        const suggestions: any[] = [];

        // Add variable suggestions
        if (availableVarsData?.vars) {
          for (const varName of availableVarsData.vars) {
            suggestions.push({
              label: varName,
              kind: monaco.languages.CompletionItemKind.Variable,
              insertText: varName,
              range,
              detail: 'Variable',
            });
          }
        }

        // Add helper function suggestions
        if (helpersData?.helpers) {
          for (const helper of helpersData.helpers) {
            // Create snippet with placeholders
            const insertText = `${helper.name}(\${1:arg})`;

            suggestions.push({
              label: helper.name,
              kind: monaco.languages.CompletionItemKind.Function,
              insertText,
              insertTextRules: monaco.languages.CompletionItemInsertTextRule.InsertAsSnippet,
              range,
              detail: helper.signature,
              documentation: helper.doc,
            });
          }
        }

        return { suggestions };
      },
    });

    // Cleanup on unmount
    return () => {
      disposable.dispose();
    };
  };

  const handleChange = (value: string | undefined) => {
    onChange(value ?? '');
  };

  return (
    <div className="relative border rounded-md overflow-hidden">
      <Editor
        height={height}
        language={language}
        value={value}
        onChange={handleChange}
        onMount={handleEditorDidMount}
        options={{
          minimap: { enabled: false },
          lineNumbers: 'off',
          glyphMargin: false,
          folding: false,
          lineDecorationsWidth: 0,
          lineNumbersMinChars: 0,
          scrollBeyondLastLine: false,
          renderLineHighlight: 'none',
          overviewRulerLanes: 0,
          hideCursorInOverviewRuler: true,
          overviewRulerBorder: false,
          wordWrap: 'on',
          fontSize: 13,
          fontFamily: 'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace',
          padding: { top: 8, bottom: 8 },
          suggest: {
            showWords: false,
          },
          quickSuggestions: {
            other: true,
            comments: false,
            strings: false,
          },
        }}
        theme="vs-light"
      />
      {isValidating && (
        <div className="absolute top-2 right-2 text-xs text-muted-foreground">
          Validating...
        </div>
      )}
    </div>
  );
}

