        <ComputeConfig
          config={localConfig}
          onUpdate={handleUpdate}
          workflowId={workflowId}
          nodeId={selectedNode.id}
        />
      )}
      {selectedNode.type === 'branch' && workflowId && (
        <BranchConfig
          config={localConfig}
          onUpdate={handleUpdate}
          workflowId={workflowId}
          nodeId={selectedNode.id}
        />
      )}
      {selectedNode.type === 'template' && workflowId && (
        <TemplateConfig
          config={localConfig}
          onUpdate={handleUpdate}
          workflowId={workflowId}
          nodeId={selectedNode.id}
        />
      )}
      {selectedNode.type === 'final' && workflowId && (
        <FinalBlockEditor
          config={localConfig}
          onUpdate={handleUpdate}
          workflowId={workflowId}
          nodeId={selectedNode.id}
        />
      )}
    </div>
  );
}
