        </div>
      </CardContent>
    </Card>
  );
}
// Branch Node Config
function BranchConfig({
  config,
  onUpdate,
  workflowId,
  nodeId,
}: {
  config: any;
  onUpdate: (updates: any) => void;
  workflowId: string;
  nodeId: string;
}) {
  const branches = config.branches ?? [];
  const addBranch = () => {
    const newBranches = [...branches, { condition: '', label: `Branch ${branches.length + 1}` }];
    onUpdate({ branches: newBranches });
  };
  const updateBranch = (index: number, updates: any) => {
    const newBranches = [...branches];
    newBranches[index] = { ...newBranches[index], ...updates };
    onUpdate({ branches: newBranches });
  };
  const removeBranch = (index: number) => {
    const newBranches = branches.filter((_: any, i: number) => i !== index);
    onUpdate({ branches: newBranches });
  };
  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-base">Branch Settings</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="space-y-3">
          {branches.map((branch: any, index: number) => (
            <Card key={index} className="p-3">
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <Label className="text-sm font-medium">Branch {index + 1}</Label>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => removeBranch(index)}
                  >
                    <X className="w-4 h-4" />
                  </Button>
                </div>
                <Input
                  value={branch.label ?? ''}
                  onChange={(e) => updateBranch(index, { label: e.target.value })}
                  placeholder="Branch label"
                  className="text-sm"
                />
                <Label className="text-xs">Condition</Label>
                <ExpressionEditor
                  value={branch.condition ?? ''}
                  onChange={(value) => updateBranch(index, { condition: value })}
                  nodeId={nodeId}
                  workflowId={workflowId}
                  placeholder="e.g., age >= 18"
                  height="60px"
                />
              </div>
            </Card>
          ))}
        </div>
        <Button onClick={addBranch} variant="outline" className="w-full">
          <Plus className="w-4 h-4 mr-2" />
          Add Branch
        </Button>
      </CardContent>
    </Card>
  );
}
// Template Node Config
function TemplateConfig({
  config,
  onUpdate,
  workflowId,
  nodeId,
}: {
  config: any;
  onUpdate: (updates: any) => void;
  workflowId: string;
  nodeId: string;
}) {
  const bindings = config.bindings || {};
  const addBinding = () => {
    const placeholder = prompt('Enter placeholder name:');
    if (placeholder) {
      onUpdate({
        bindings: {
          ...bindings,
          [placeholder]: '',
        },
      });
    }
  };
  const updateBinding = (placeholder: string, expression: string) => {
    onUpdate({
      bindings: {
        ...bindings,
        [placeholder]: expression,
      },
    });
  };
  const removeBinding = (placeholder: string) => {
    const newBindings = { ...bindings };
    delete newBindings[placeholder];
    onUpdate({ bindings: newBindings });
  };
  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-base">Template Settings</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="space-y-2">
          <Label htmlFor="templateId">Template ID</Label>
          <Input
            id="templateId"
            value={config.templateId ?? ''}
            onChange={(e) => onUpdate({ templateId: e.target.value })}
            placeholder="Enter template ID"
          />
        </div>
        <div className="space-y-2">
          <Label>Placeholder Bindings</Label>
          <div className="space-y-2">
            {Object.entries(bindings).map(([placeholder, expression]) => (
              <Card key={placeholder} className="p-3">
                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <Label className="text-sm font-mono">{placeholder}</Label>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => removeBinding(placeholder)}
                    >
                      <X className="w-4 h-4" />
                    </Button>
                  </div>
                  <ExpressionEditor
                    value={expression as string}
                    onChange={(value) => updateBinding(placeholder, value)}
                    nodeId={nodeId}
                    workflowId={workflowId}
                    placeholder="Expression or variable"
                    height="60px"
                  />
                </div>
              </Card>
            ))}
          </div>
          <Button onClick={addBinding} variant="outline" className="w-full">
            <Plus className="w-4 h-4 mr-2" />
            Add Binding
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

/**
 * PreviewPanel - Embedded run tester for workflows
 */

import { motion } from 'framer-motion';
import { Play, X, CheckCircle, XCircle, Clock, Download } from 'lucide-react';
import { useState } from 'react';

import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { ScrollArea } from '@/components/ui/scroll-area';

import { useRunWorkflow, useWorkflowRun } from '../hooks/useWorkflowAPI';

interface PreviewPanelProps {
  workflowId: string;
  onClose: () => void;
}

export function PreviewPanel({ workflowId, onClose }: PreviewPanelProps) {
  const [inputs, setInputs] = useState<Record<string, any>>({});
  const [runId, setRunId] = useState<string | undefined>();

  const runWorkflow = useRunWorkflow(workflowId);
  const { data: runData } = useWorkflowRun(runId);

  const handleInputChange = (key: string, value: any) => {
    setInputs(prev => ({ ...prev, [key]: value }));
  };

  const handleRun = async () => {
    try {
      const result = await runWorkflow.mutateAsync(inputs);
      setRunId(result.id);
    } catch (error) {
      console.error('Error running workflow:', error);
    }
  };

  const handleReset = () => {
    setInputs({});
    setRunId(undefined);
  };

  return (
    <motion.div
      initial={{ x: '100%' }}
      animate={{ x: 0 }}
      exit={{ x: '100%' }}
      transition={{ type: 'spring', damping: 25, stiffness: 200 }}
      className="h-full flex flex-col bg-background border-l"
    >
      {/* Header */}
      <div className="border-b px-4 py-3 flex items-center justify-between">
        <h3 className="font-semibold">Run Preview</h3>
        <Button variant="ghost" size="sm" onClick={() => { void onClose(); }}>
          <X className="w-4 h-4" />
        </Button>
      </div>

      <ScrollArea className="flex-1">
        <div className="p-4 space-y-4">
          {/* Input Form */}
          <Card>
            <CardHeader>
              <CardTitle className="text-base">Test Inputs</CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              <div className="space-y-2">
                <Label htmlFor="test-input-1">Sample Input 1</Label>
                <Input
                  id="test-input-1"
                  value={inputs.input1 ?? ''}
                  onChange={(e) => { void handleInputChange('input1', e.target.value); }}
                  placeholder="Enter test value"
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="test-input-2">Sample Input 2</Label>
                <Input
                  id="test-input-2"
                  value={inputs.input2 ?? ''}
                  onChange={(e) => { void handleInputChange('input2', e.target.value); }}
                  placeholder="Enter test value"
                />
              </div>

              <div className="flex gap-2">
                <Button
                  onClick={() => { void handleRun(); }}
                  disabled={runWorkflow.isPending}
                  className="flex-1"
                >
                  <Play className="w-4 h-4 mr-2" />
                  {runWorkflow.isPending ? 'Running...' : 'Run Workflow'}
                </Button>
                <Button
                  variant="outline"
                  onClick={() => { void handleReset(); }}
                >
                  Reset
                </Button>
              </div>
            </CardContent>
          </Card>

          {/* Run Status */}
          {runData && (
            <Card>
              <CardHeader>
                <div className="flex items-center justify-between">
                  <CardTitle className="text-base">Run Status</CardTitle>
                  <Badge
                    variant={
                      runData.status === 'completed'
                        ? 'default'
                        : runData.status === 'failed'
                        ? 'destructive'
                        : 'secondary'
                    }
                  >
                    {runData.status}
                  </Badge>
                </div>
              </CardHeader>
              <CardContent>
                <div className="space-y-2 text-sm">
                  <div className="flex justify-between">
                    <span className="text-muted-foreground">Run ID:</span>
                    <span className="font-mono text-xs">{runData.id.slice(0, 12)}...</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-muted-foreground">Started:</span>
                    <span>{new Date(runData.createdAt).toLocaleTimeString()}</span>
                  </div>
                  {runData.completedAt && (
                    <div className="flex justify-between">
                      <span className="text-muted-foreground">Completed:</span>
                      <span>{new Date(runData.completedAt).toLocaleTimeString()}</span>
                    </div>
                  )}
                </div>
              </CardContent>
            </Card>
          )}

          {/* Execution Trace */}
          {runData?.trace && runData.trace.length > 0 && (
            <Card>
              <CardHeader>
                <CardTitle className="text-base">Execution Trace</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-2">
                  {runData.trace.map((step, index) => (
                    <motion.div
                      key={step.nodeId}
                      initial={{ opacity: 0, y: 10 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ delay: index * 0.1 }}
                      className={`
                        p-3 rounded-md border
                        ${step.executed ? 'bg-green-50 dark:bg-green-950 border-green-300 dark:border-green-700' : ''}
                        ${step.skipped ? 'bg-gray-50 dark:bg-gray-900 border-gray-300 dark:border-gray-700' : ''}
                        ${step.error ? 'bg-red-50 dark:bg-red-950 border-red-300 dark:border-red-700' : ''}
                      `}
                    >
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2">
                          {step.executed && <CheckCircle className="w-4 h-4 text-green-600" />}
                          {step.skipped && <XCircle className="w-4 h-4 text-gray-500" />}
                          {step.error && <XCircle className="w-4 h-4 text-red-600" />}
                          {!step.executed && !step.skipped && !step.error && (
                            <Clock className="w-4 h-4 text-blue-600" />
                          )}
                          <span className="font-mono text-sm">{step.nodeId}</span>
                        </div>
                        {typeof step.conditionResult === 'boolean' && (
                          <Badge variant="outline" className="text-xs">
                            {step.conditionResult ? 'true' : 'false'}
                          </Badge>
                        )}
                      </div>
                      {step.error && (
                        <p className="text-xs text-red-600 mt-2">{step.error}</p>
                      )}
                    </motion.div>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}

          {/* Outputs */}
          {runData?.outputs && Object.keys(runData.outputs).length > 0 && (
            <Card>
              <CardHeader>
                <CardTitle className="text-base">Outputs</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-2">
                  {Object.entries(runData.outputs).map(([key, value]) => (
                    <div key={key} className="flex justify-between text-sm">
                      <span className="font-mono text-muted-foreground">{key}:</span>
                      <span className="font-mono">{JSON.stringify(value)}</span>
                    </div>
                  ))}
                </div>

                {/* Download buttons for generated documents */}
                {runData.outputs.documentUrl && (
                  <Button
                    variant="outline"
                    size="sm"
                    className="w-full mt-3"
                    onClick={() => { void window.open(runData.outputs.documentUrl as string, '_blank'); }}
                  >
                    <Download className="w-4 h-4 mr-2" />
                    Download Document
                  </Button>
                )}
              </CardContent>
            </Card>
          )}
        </div>
      </ScrollArea>
    </motion.div>
  );
}

/**
 * Stage 21: Template Management Panel
 *
 * UI for managing templates attached to workflow versions.
 * Features:
 * - View all attached templates
 * - Attach/detach templates
 * - Set template keys
 * - Mark primary template
 * - Upload new templates (AI Wizard)
 * - Configure template bindings
 */

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { FileText, Plus, Upload, Trash2, Star, StarOff, Settings } from 'lucide-react';
import { useState } from 'react';
import { toast } from 'sonner';

import { Badge } from '../../../components/ui/badge';
import { Button } from '../../../components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogFooter,
} from '../../../components/ui/dialog';
import { Input } from '../../../components/ui/input';
import { Label } from '../../../components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '../../../components/ui/select';


import { DocumentTemplateEditor } from './DocumentTemplateEditor';
import { TemplateUploadWizard } from './TemplateUploadWizard';

interface WorkflowTemplate {
  id: string;
  workflowVersionId: string;
  templateId: string;
  key: string;
  isPrimary: boolean;
  createdAt: string;
  template?: {
    id: string;
    name: string;
    description?: string;
    type: 'docx' | 'html';
    fileRef: string;
  };
}

interface Template {
  id: string;
  projectId: string;
  name: string;
  description?: string;
  type: 'docx' | 'html';
  fileRef: string;
  createdAt: string;
}

interface TemplateManagementPanelProps {
  workflowId: string;
  versionId: string;
  projectId: string;
}

export function TemplateManagementPanel({
  workflowId,
  versionId,
  projectId,
}: TemplateManagementPanelProps) {
  const queryClient = useQueryClient();

  const [isAttachDialogOpen, setIsAttachDialogOpen] = useState(false);
  const [selectedTemplateId, setSelectedTemplateId] = useState<string>('');
  const [templateKey, setTemplateKey] = useState('');
  const [isPrimary, setIsPrimary] = useState(false);
  const [editingTemplateContentId, setEditingTemplateContentId] = useState<string | null>(null);
  const [isUploadWizardOpen, setIsUploadWizardOpen] = useState(false);

  // Fetch attached templates
  const { data: attachedTemplates, isLoading: loadingAttached } = useQuery({
    queryKey: ['workflow-templates', versionId],
    queryFn: async () => {
      const response = await fetch(
        `/api/workflows/${workflowId}/versions/${versionId}/templates`,
        {
          credentials: 'include',
        }
      );

      if (!response.ok) {
        throw new Error('Failed to fetch templates');
      }

      const json = await response.json();
      return json.data as WorkflowTemplate[];
    },
  });

  // Fetch available templates from project
  const { data: projectTemplates, isLoading: loadingProject } = useQuery({
    queryKey: ['project-templates', projectId],
    queryFn: async () => {
      const response = await fetch(`/api/projects/${projectId}/templates`, {
        credentials: 'include',
      });

      if (!response.ok) {
        throw new Error('Failed to fetch project templates');
      }

      const json = await response.json();
      return json.data as Template[];
    },
  });

  // Attach template mutation
  const attachMutation = useMutation({
    mutationFn: async (data: {
      templateId: string;
      projectId: string;
      key: string;
      isPrimary: boolean;
    }) => {
      const response = await fetch(
        `/api/workflows/${workflowId}/versions/${versionId}/templates`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify(data),
        }
      );

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.message || 'Failed to attach template');
      }

      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['workflow-templates', versionId] });
      setIsAttachDialogOpen(false);
      setSelectedTemplateId('');
      setTemplateKey('');
      setIsPrimary(false);
      toast.success('Template attached successfully');
    },
    onError: (error: Error) => {
      toast.error(error.message);
    },
  });

  // Detach template mutation
  const detachMutation = useMutation({
    mutationFn: async (mappingId: string) => {
      const response = await fetch(
        `/api/workflow-templates/${mappingId}?workflowVersionId=${versionId}`,
        {
          method: 'DELETE',
          credentials: 'include',
        }
      );

      if (!response.ok) {
        throw new Error('Failed to detach template');
      }

      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['workflow-templates', versionId] });
      toast.success('Template detached successfully');
    },
    onError: (error: Error) => {
      toast.error(error.message);
    },
  });

  // Set primary mutation
  const setPrimaryMutation = useMutation({
    mutationFn: async (mappingId: string) => {
      const response = await fetch(
        `/api/workflow-templates/${mappingId}/set-primary?workflowVersionId=${versionId}`,
        {
          method: 'POST',
          credentials: 'include',
        }
      );

      if (!response.ok) {
        throw new Error('Failed to set primary template');
      }

      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['workflow-templates', versionId] });
      toast.success('Primary template updated');
    },
    onError: (error: Error) => {
      toast.error(error.message);
    },
  });

  const handleAttach = () => {
    if (!selectedTemplateId || !templateKey) {
      toast.error('Please select a template and enter a key');
      return;
    }

    attachMutation.mutate({
      templateId: selectedTemplateId,
      projectId,
      key: templateKey,
      isPrimary,
    });
  };

  const handleDetach = (mappingId: string) => {
    if (confirm('Are you sure you want to detach this template?')) {
      detachMutation.mutate(mappingId);
    }
  };

  const handleSetPrimary = (mappingId: string) => {
    setPrimaryMutation.mutate(mappingId);
  };

  // Filter out already attached templates
  const availableTemplates = projectTemplates?.filter(
    (template) =>
      !attachedTemplates?.some((attached) => attached.templateId === template.id)
  );

  return (
    <div className="p-4 border-l bg-gray-50 dark:bg-gray-900 overflow-y-auto h-full">
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-lg font-semibold flex items-center gap-2">
          <FileText className="h-5 w-5" />
          Templates
        </h2>

        <div className="flex gap-2">
          <Button size="sm" variant="ghost" onClick={() => { void setIsUploadWizardOpen(true); }}>
            <Upload className="h-4 w-4" />
          </Button>
          <Dialog open={isAttachDialogOpen} onOpenChange={setIsAttachDialogOpen}>
            <DialogTrigger asChild>
              <Button size="sm" variant="outline">
                <Plus className="h-4 w-4 mr-1" />
                Attach
              </Button>
            </DialogTrigger>

            <DialogContent>
              <DialogHeader>
                <DialogTitle>Attach Template to Workflow</DialogTitle>
              </DialogHeader>

              <div className="space-y-4 py-4">
                <div className="space-y-2">
                  <Label htmlFor="template">Template</Label>
                  <Select
                    value={selectedTemplateId}
                    onValueChange={(value) => {
                      setSelectedTemplateId(value);
                      // Auto-fill the display name with the template name
                      const template = availableTemplates?.find((t) => t.id === value);
                      if (template && !templateKey) {
                        setTemplateKey(template.name);
                      }
                    }}
                  >
                    <SelectTrigger id="template">
                      <SelectValue placeholder="Select a template" />
                    </SelectTrigger>
                    <SelectContent>
                      {availableTemplates?.map((template) => (
                        <SelectItem key={template.id} value={template.id}>
                          {template.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  {loadingProject && <p className="text-sm text-gray-500">Loading templates...</p>}
                  {availableTemplates?.length === 0 && (
                    <div className="mt-2">
                      <p className="text-sm text-gray-500 mb-2">
                        No available templates. Upload templates to your project first.
                      </p>
                    </div>
                  )}
                </div>

                <div className="space-y-2">
                  <Label htmlFor="key">Display Name</Label>
                  <Input
                    id="key"
                    placeholder="e.g., engagement_letter, schedule_a"
                    value={templateKey}
                    onChange={(e) => { void setTemplateKey(e.target.value); }}
                  />
                  <p className="text-sm text-gray-500">
                    Unique identifier for this template (used in Template nodes)
                  </p>
                </div>

                <div className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    id="primary"
                    checked={isPrimary}
                    onChange={(e) => { void setIsPrimary(e.target.checked); }}
                    className="rounded border-gray-300"
                  />
                  <Label htmlFor="primary" className="cursor-pointer">
                    Set as primary template
                  </Label>
                </div>
              </div>

              <DialogFooter>
                <Button variant="outline" onClick={() => { void setIsAttachDialogOpen(false); }}>
                  Cancel
                </Button>
                <Button onClick={() => { void handleAttach(); }} disabled={attachMutation.isPending}>
                  {attachMutation.isPending ? 'Attaching...' : 'Attach Template'}
                </Button>
              </DialogFooter>
            </DialogContent>
          </Dialog>
        </div>
      </div>

      {loadingAttached ? (
        <div className="text-center py-8 text-gray-500">Loading templates...</div>
      ) : attachedTemplates?.length === 0 ? (
        <div className="text-center py-8 text-gray-500">
          <FileText className="h-12 w-12 mx-auto mb-2 opacity-50" />
          <p>No templates attached</p>
          <p className="text-sm">Click "Attach" to add a template</p>
        </div>
      ) : (
        <div className="space-y-3">
          {attachedTemplates?.map((mapping) => (
            <div
              key={mapping.id}
              className="p-3 bg-white dark:bg-gray-800 rounded-lg border shadow-sm"
            >
              <div className="flex items-start justify-between mb-2">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
                    <h3 className="font-medium">{mapping.template?.name || 'Unknown'}</h3>
                    {mapping.isPrimary && (
                      <Badge variant="default" className="text-xs">
                        <Star className="h-3 w-3 mr-1" />
                        Primary
                      </Badge>
                    )}
                  </div>
                  <p className="text-sm text-gray-600 dark:text-gray-400">
                    Key: <code className="bg-gray-100 dark:bg-gray-700 px-1 rounded">{mapping.key}</code>
                  </p>
                  {mapping.template?.description && (
                    <p className="text-xs text-gray-500 mt-1">{mapping.template.description}</p>
                  )}
                </div>

                <div className="flex gap-1">
                  {!mapping.isPrimary && (
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => { void handleSetPrimary(mapping.id); }}
                      title="Set as primary"
                    >
                      <StarOff className="h-4 w-4" />
                    </Button>
                  )}
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => { void handleDetach(mapping.id); }}
                    title="Detach template"
                  >
                    <Trash2 className="h-4 w-4 text-red-500" />
                  </Button>
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => { void setEditingTemplateContentId(mapping.templateId); }}
                    title="AI Assist & Edit"
                  >
                    <Settings className="h-4 w-4 text-purple-500" />
                  </Button>
                </div>
              </div>

              <div className="flex items-center gap-2 text-xs text-gray-500">
                <Badge variant="outline" className="text-xs">
                  {mapping.template?.type?.toUpperCase() || 'DOCX'}
                </Badge>
                <span>ΓÇó</span>
                <span>{new Date(mapping.createdAt).toLocaleDateString()}</span>
              </div>
            </div>
          ))}
        </div>
      )}

      <div className="mt-6 p-3 bg-blue-50 dark:bg-blue-900/20 rounded-lg border border-blue-200 dark:border-blue-800">
        <p className="text-sm text-blue-900 dark:text-blue-100">
          ≡ƒÆí <strong>Tip:</strong> Use template keys in Template nodes to reference these
          templates. The primary template will be used by default.
        </p>
      </div>

      {editingTemplateContentId && (
        <DocumentTemplateEditor
          templateId={editingTemplateContentId}
          isOpen={!!editingTemplateContentId}
          onClose={() => setEditingTemplateContentId(null)}
          workflowVariables={[]} // TODO: Pass actual workflow variables
        />
      )}

      <TemplateUploadWizard
        projectId={projectId}
        open={isUploadWizardOpen}
        onOpenChange={setIsUploadWizardOpen}
      />
    </div>
  );
}

/**
 * Stage 21: Template Test Runner
 *
 * UI for testing templates with sample data.
 * Features:
 * - Analyze template structure (variables, loops, conditionals)
 * - Generate sample data automatically
 * - Validate template with custom data
 * - Preview rendered output
 * - Integration with TemplateAnalysisService
 */

import { useQuery, useMutation } from '@tanstack/react-query';
import {
  Code,
  PlayCircle,
  CheckCircle,
  AlertCircle,
  Loader2,
  FileCode,
  Database,
} from 'lucide-react';
import { useState } from 'react';
import { toast } from 'sonner';

import { Badge } from '../../../components/ui/badge';
import { Button } from '../../../components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '../../../components/ui/dialog';
import { Label } from '../../../components/ui/label';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../../../components/ui/tabs';
import { Textarea } from '../../../components/ui/textarea';


interface TemplateTestRunnerProps {
  templateId: string;
  projectId: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

interface TemplateAnalysis {
  variables: Array<{
    name: string;
    type: 'variable' | 'loop' | 'conditional' | 'helper';
    path?: string;
    helperName?: string;
  }>;
  loops: Array<{
    tag: string;
    context: string;
  }>;
  conditionals: Array<{
    tag: string;
    condition: string;
  }>;
  helpers: string[];
  stats: {
    variableCount: number;
    loopCount: number;
    conditionalCount: number;
    helperCount: number;
  };
}

interface ValidationResult {
  valid: boolean;
  coverage: number;
  missing: string[];
  extra: string[];
  errors: Array<{
    placeholder: string;
    error: string;
  }>;
}

export function TemplateTestRunner({
  templateId,
  projectId,
  open,
  onOpenChange,
}: TemplateTestRunnerProps) {
  const [sampleData, setSampleData] = useState('{}');
  const [activeTab, setActiveTab] = useState<'analysis' | 'test'>('analysis');

  // Fetch template analysis
  const {
    data: analysis,
    isLoading: loadingAnalysis,
    error: analysisError,
  } = useQuery<{ data: TemplateAnalysis }>({
    queryKey: ['template-analysis', templateId],
    queryFn: async () => {
      const response = await fetch(
        `/api/templates/${templateId}/analyze?projectId=${projectId}`,
        {
          credentials: 'include',
        }
      );

      if (!response.ok) {
        throw new Error('Failed to analyze template');
      }

      return response.json();
    },
    enabled: open,
  });

  // Generate sample data mutation
  const generateSampleMutation = useMutation({
    mutationFn: async () => {
      const response = await fetch(
        `/api/templates/${templateId}/sample-data?projectId=${projectId}`,
        {
          method: 'POST',
          credentials: 'include',
        }
      );

      if (!response.ok) {
        throw new Error('Failed to generate sample data');
      }

      return response.json();
    },
    onSuccess: (data) => {
      setSampleData(JSON.stringify(data.data, null, 2));
      setActiveTab('test');
      toast.success('Sample data generated');
    },
    onError: (error: Error) => {
      toast.error(error.message);
    },
  });

  // Validate template mutation
  const validateMutation = useMutation<{ data: ValidationResult }, Error, any>({
    mutationFn: async (data: any) => {
      const response = await fetch(
        `/api/templates/${templateId}/validate?projectId=${projectId}`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify({ sampleData: data }),
        }
      );

      if (!response.ok) {
        throw new Error('Failed to validate template');
      }

      return response.json();
    },
    onSuccess: (result) => {
      if (result.data.valid) {
        toast.success(`Validation passed! Coverage: ${(result.data.coverage * 100).toFixed(0)}%`);
      } else {
        toast.warning(`Validation issues found. Coverage: ${(result.data.coverage * 100).toFixed(0)}%`);
      }
    },
    onError: (error: Error) => {
      toast.error(error.message);
    },
  });

  const handleGenerateSample = () => {
    generateSampleMutation.mutate();
  };

  const handleValidate = () => {
    try {
      const data = JSON.parse(sampleData);
      validateMutation.mutate(data);
    } catch (error) {
      toast.error('Invalid JSON data');
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl max-h-[80vh] overflow-hidden flex flex-col">
        <DialogHeader>
          <DialogTitle>Test Template</DialogTitle>
        </DialogHeader>

        <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as any)} className="flex-1 flex flex-col overflow-hidden">
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="analysis">
              <FileCode className="h-4 w-4 mr-2" />
              Analysis
            </TabsTrigger>
            <TabsTrigger value="test">
              <Database className="h-4 w-4 mr-2" />
              Test Data
            </TabsTrigger>
          </TabsList>

          <TabsContent value="analysis" className="flex-1 overflow-y-auto mt-4">
            {loadingAnalysis ? (
              <div className="flex items-center justify-center py-12">
                <Loader2 className="h-8 w-8 animate-spin text-gray-400" />
              </div>
            ) : analysisError ? (
              <div className="p-4 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg">
                <p className="text-red-900 dark:text-red-100">
                  <AlertCircle className="h-4 w-4 inline mr-2" />
                  Error: {(analysisError).message}
                </p>
              </div>
            ) : analysis ? (
              <div className="space-y-6">
                {/* Stats Overview */}
                <div className="grid grid-cols-4 gap-4">
                  <div className="p-4 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg">
                    <div className="text-2xl font-bold text-blue-900 dark:text-blue-100">
                      {analysis.data.stats.variableCount}
                    </div>
                    <div className="text-sm text-blue-700 dark:text-blue-300">Variables</div>
                  </div>

                  <div className="p-4 bg-purple-50 dark:bg-purple-900/20 border border-purple-200 dark:border-purple-800 rounded-lg">
                    <div className="text-2xl font-bold text-purple-900 dark:text-purple-100">
                      {analysis.data.stats.loopCount}
                    </div>
                    <div className="text-sm text-purple-700 dark:text-purple-300">Loops</div>
                  </div>

                  <div className="p-4 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 rounded-lg">
                    <div className="text-2xl font-bold text-green-900 dark:text-green-100">
                      {analysis.data.stats.conditionalCount}
                    </div>
                    <div className="text-sm text-green-700 dark:text-green-300">Conditionals</div>
                  </div>

                  <div className="p-4 bg-orange-50 dark:bg-orange-900/20 border border-orange-200 dark:border-orange-800 rounded-lg">
                    <div className="text-2xl font-bold text-orange-900 dark:text-orange-100">
                      {analysis.data.stats.helperCount}
                    </div>
                    <div className="text-sm text-orange-700 dark:text-orange-300">Helpers</div>
                  </div>
                </div>

                {/* Variables List */}
                {analysis.data.variables.length > 0 && (
                  <div>
                    <h3 className="font-semibold mb-2 flex items-center gap-2">
                      <Code className="h-4 w-4" />
                      Variables ({analysis.data.variables.length})
                    </h3>
                    <div className="space-y-1 max-h-48 overflow-y-auto">
                      {analysis.data.variables.map((v, i) => (
                        <div
                          key={i}
                          className="flex items-center gap-2 p-2 bg-gray-50 dark:bg-gray-800 rounded"
                        >
                          <code className="text-sm flex-1">{v.name}</code>
                          <Badge variant="outline" className="text-xs">
                            {v.type}
                          </Badge>
                          {v.helperName && (
                            <Badge variant="secondary" className="text-xs">
                              {v.helperName}
                            </Badge>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Loops */}
                {analysis.data.loops.length > 0 && (
                  <div>
                    <h3 className="font-semibold mb-2">Loops ({analysis.data.loops.length})</h3>
                    <div className="space-y-1">
                      {analysis.data.loops.map((loop, i) => (
                        <div key={i} className="p-2 bg-purple-50 dark:bg-purple-900/20 rounded">
                          <code className="text-sm">{loop.tag}</code>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Conditionals */}
                {analysis.data.conditionals.length > 0 && (
                  <div>
                    <h3 className="font-semibold mb-2">
                      Conditionals ({analysis.data.conditionals.length})
                    </h3>
                    <div className="space-y-1">
                      {analysis.data.conditionals.map((cond, i) => (
                        <div key={i} className="p-2 bg-green-50 dark:bg-green-900/20 rounded">
                          <code className="text-sm">{cond.tag}</code>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Helpers */}
                {analysis.data.helpers.length > 0 && (
                  <div>
                    <h3 className="font-semibold mb-2">
                      Helper Functions ({analysis.data.helpers.length})
                    </h3>
                    <div className="flex flex-wrap gap-2">
                      {analysis.data.helpers.map((helper, i) => (
                        <Badge key={i} variant="secondary">
                          {helper}
                        </Badge>
                      ))}
                    </div>
                  </div>
                )}

                <div className="flex justify-end">
                  <Button onClick={handleGenerateSample} disabled={generateSampleMutation.isPending}>
                    {generateSampleMutation.isPending ? (
                      <>
                        <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                        Generating...
                      </>
                    ) : (
                      <>
                        <Database className="h-4 w-4 mr-2" />
                        Generate Sample Data
                      </>
                    )}
                  </Button>
                </div>
              </div>
            ) : null}
          </TabsContent>

          <TabsContent value="test" className="flex-1 overflow-y-auto mt-4">
            <div className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="sample-data">Sample Data (JSON)</Label>
                <Textarea
                  id="sample-data"
                  value={sampleData}
                  onChange={(e) => setSampleData(e.target.value)}
                  placeholder='{"name": "John Doe", "email": "john@example.com"}'
                  className="font-mono text-sm"
                  rows={15}
                />
                <p className="text-sm text-gray-500">
                  Enter JSON data to test template rendering
                </p>
              </div>

              {validateMutation.data && (
                <div
                  className={`p-4 rounded-lg border ${
                    validateMutation.data.data.valid
                      ? 'bg-green-50 dark:bg-green-900/20 border-green-200 dark:border-green-800'
                      : 'bg-yellow-50 dark:bg-yellow-900/20 border-yellow-200 dark:border-yellow-800'
                  }`}
                >
                  <div className="flex items-center gap-2 mb-2">
                    {validateMutation.data.data.valid ? (
                      <CheckCircle className="h-5 w-5 text-green-600" />
                    ) : (
                      <AlertCircle className="h-5 w-5 text-yellow-600" />
                    )}
                    <h3 className="font-semibold">
                      {validateMutation.data.data.valid
                        ? 'Validation Passed'
                        : 'Validation Warnings'}
                    </h3>
                  </div>

                  <div className="space-y-2 text-sm">
                    <p>
                      <strong>Coverage:</strong>{' '}
                      {(validateMutation.data.data.coverage * 100).toFixed(0)}%
                    </p>

                    {validateMutation.data.data.missing.length > 0 && (
                      <div>
                        <strong>Missing variables:</strong>
                        <ul className="list-disc list-inside mt-1">
                          {validateMutation.data.data.missing.map((v) => (
                            <li key={v}>
                              <code>{v}</code>
                            </li>
                          ))}
                        </ul>
                      </div>
                    )}

                    {validateMutation.data.data.extra.length > 0 && (
                      <div>
                        <strong>Extra variables (not in template):</strong>
                        <ul className="list-disc list-inside mt-1">
                          {validateMutation.data.data.extra.map((v) => (
                            <li key={v}>
                              <code>{v}</code>
                            </li>
                          ))}
                        </ul>
                      </div>
                    )}

                    {validateMutation.data.data.errors.length > 0 && (
                      <div>
                        <strong>Errors:</strong>
                        <ul className="list-disc list-inside mt-1">
                          {validateMutation.data.data.errors.map((err, i) => (
                            <li key={i}>
                              <code>{err.placeholder}</code>: {err.error}
                            </li>
                          ))}
                        </ul>
                      </div>
                    )}
                  </div>
                </div>
              )}

              <div className="flex justify-end gap-2">
                <Button
                  variant="outline"
                  onClick={handleGenerateSample}
                  disabled={generateSampleMutation.isPending}
                >
                  {generateSampleMutation.isPending ? (
                    <>
                      <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                      Generating...
                    </>
                  ) : (
                    <>
                      <Database className="h-4 w-4 mr-2" />
                      Generate Sample
                    </>
                  )}
                </Button>
                <Button onClick={handleValidate} disabled={validateMutation.isPending}>
                  {validateMutation.isPending ? (
                    <>
                      <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                      Validating...
                    </>
                  ) : (
                    <>
                      <PlayCircle className="h-4 w-4 mr-2" />
                      Validate
                    </>
                  )}
                </Button>
              </div>
            </div>
          </TabsContent>
        </Tabs>

        <DialogFooter className="mt-4">
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Close
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * Stage 21: Template Upload Dialog
 *
 * UI for uploading new templates to a project.
 * Features:
 * - File upload (DOCX only)
 * - Template metadata (name, description)
 * - Automatic analysis after upload
 * - Integration with DocumentTemplateService
 */

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { Upload, FileText, Loader2 } from 'lucide-react';
import React, { useState } from 'react';
import { toast } from 'sonner';

import { Button } from '../../../components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '../../../components/ui/dialog';
import { Input } from '../../../components/ui/input';
import { Label } from '../../../components/ui/label';
import { Textarea } from '../../../components/ui/textarea';


interface TemplateUploadDialogProps {
  projectId: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function TemplateUploadDialog({
  projectId,
  open,
  onOpenChange,
}: TemplateUploadDialogProps) {
  const queryClient = useQueryClient();

  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [file, setFile] = useState<File | null>(null);

  const uploadMutation = useMutation({
    mutationFn: async (data: FormData) => {
      const response = await fetch(`/api/projects/${projectId}/templates`, {
        method: 'POST',
        credentials: 'include',
        body: data,
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.message || 'Failed to upload template');
      }

      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['project-templates', projectId] });
      onOpenChange(false);
      resetForm();
      toast.success('Template uploaded successfully');
    },
    onError: (error: Error) => {
      toast.error(error.message);
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!name || !file) {
      toast.error('Please provide a name and select a file');
      return;
    }

    const formData = new FormData();
    formData.append('name', name);
    formData.append('description', description);
    formData.append('type', 'docx');
    formData.append('file', file);

    uploadMutation.mutate(formData);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];

    if (!selectedFile) {
      return;
    }

    // Validate file type
    const validExtensions = ['.docx'];
    const extension = selectedFile.name.toLowerCase().slice(selectedFile.name.lastIndexOf('.'));

    if (!validExtensions.includes(extension)) {
      toast.error('Only .docx files are supported');
      e.target.value = '';
      return;
    }

    setFile(selectedFile);

    // Auto-fill name if empty
    if (!name) {
      const filename = selectedFile.name.replace(/\.[^/.]+$/, '');
      setName(filename);
    }
  };

  const resetForm = () => {
    setName('');
    setDescription('');
    setFile(null);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Upload Template</DialogTitle>
        </DialogHeader>

        <form onSubmit={(e) => { e.preventDefault(); void handleSubmit(e); }}>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="file">Template File</Label>
              <div className="flex items-center gap-2">
                <Input
                  id="file"
                  type="file"
                  accept=".docx"
                  onChange={handleFileChange}
                  className="cursor-pointer"
                />
              </div>
              {file && (
                <div className="flex items-center gap-2 text-sm text-green-600 dark:text-green-400">
                  <FileText className="h-4 w-4" />
                  <span>{file.name}</span>
                  <span className="text-gray-500">
                    ({(file.size / 1024).toFixed(1)} KB)
                  </span>
                </div>
              )}
              <p className="text-sm text-gray-500">
                Upload a .docx file with template placeholders (e.g., {`{name}`}, {`{email}`})
              </p>
            </div>

            <div className="space-y-2">
              <Label htmlFor="name">Template Name</Label>
              <Input
                id="name"
                placeholder="e.g., Engagement Letter"
                value={name}
                onChange={(e) => { void setName(e.target.value); }}
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="description">Description (Optional)</Label>
              <Textarea
                id="description"
                placeholder="Describe what this template is used for"
                value={description}
                onChange={(e) => { void setDescription(e.target.value); }}
                rows={3}
              />
            </div>
          </div>

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => { void onOpenChange(false); }}
              disabled={uploadMutation.isPending}
            >
              Cancel
            </Button>
            <Button type="submit" disabled={uploadMutation.isPending || !file || !name}>
              {uploadMutation.isPending ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Uploading...
                </>
              ) : (
                <>
                  <Upload className="h-4 w-4 mr-2" />
                  Upload
                </>
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useMutation, useQueryClient } from '@tanstack/react-query';
import axios from 'axios';
import {   Loader2, Sparkles, CheckCircle, ArrowRight } from 'lucide-react';
import React, { useState } from 'react';
import { toast } from 'sonner';

import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogFooter,
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Textarea } from '@/components/ui/textarea';
interface TemplateUploadWizardProps {
    projectId: string;
    open: boolean;
    onOpenChange: (open: boolean) => void;
    workflowVariables?: any[];
}
export function TemplateUploadWizard({
    projectId,
    open,
    onOpenChange,
    workflowVariables = []
}: TemplateUploadWizardProps) {
    const queryClient = useQueryClient();
    const [step, setStep] = useState(1);
    // Form State
    const [name, setName] = useState('');
    const [description, setDescription] = useState('');
    const [file, setFile] = useState<File | null>(null);
    // AI State
    const [analysis, setAnalysis] = useState<any>(null);
    const [mappings, setMappings] = useState<any[]>([]);
    // 1. Upload & Analyze Mutation
    const uploadAndAnalyzeMutation = useMutation({
        mutationFn: async () => {
            // Just analyze first, don't save to DB yet (or save as draft?)
            // We'll analyze the file buffer directly
            if (!file) { throw new Error("No file"); }
            const formData = new FormData();
            formData.append('file', file);
            const res = await axios.post('/api/ai/doc/analyze', formData);
            return res.data.data;
        },
        onSuccess: (data) => {
            setAnalysis(data);
            if (data.variables) {
                // Automatically get mappings
                suggestMappingMutation.mutate(data.variables);
            }
            setStep(2);
        }
    });
    // 2. Suggest Mappings
    const suggestMappingMutation = useMutation({
        mutationFn: async (variables: any[]) => {
            const res = await axios.post('/api/ai/doc/suggest-mappings', {
                templateVariables: variables,
                workflowVariables
            });
            return res.data.data;
        },
        onSuccess: (data) => {
            setMappings(data);
        }
    });
    // 3. Final Save
    const saveMutation = useMutation({
        mutationFn: async () => {
            if (!file || !name) { throw new Error("Missing data"); }
            const formData = new FormData();
            formData.append('name', name);
            formData.append('description', description);
            formData.append('type', 'docx');
            formData.append('file', file);
            // We could also save the mappings metadata here if backend supported it
            const response = await fetch(`/api/projects/${projectId}/templates`, {
                method: 'POST',
                credentials: 'include',
                body: formData,
            });
            if (!response.ok) { throw new Error("Failed to save"); }
            return response.json();
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['project-templates', projectId] });
            toast.success('Template saved successfully');
            onOpenChange(false);
            reset();
        }
    });
    const reset = () => {
        setStep(1);
        setName('');
        setDescription('');
        setFile(null);
        setAnalysis(null);
        setMappings([]);
    };
    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const selectedFile = e.target.files?.[0];
        if (selectedFile) {
            setFile(selectedFile);
            if (!name) { setName(selectedFile.name.replace(/\.[^/.]+$/, '')); }
        }
    };
    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-xl">
                <DialogHeader>
                    <DialogTitle>
                        {step === 1 ? "Upload New Template" : "AI Template Analysis"}
                    </DialogTitle>
                </DialogHeader>
                {step === 1 && (
                    <div className="space-y-4 py-4">
                        <div className="space-y-2">
                            <Label htmlFor="file">Template File (.docx)</Label>
                            <Input id="file" type="file" accept=".docx" onChange={handleFileChange} />
                        </div>
                        <div className="space-y-2">
                            <Label htmlFor="name">Name</Label>
                            <Input id="name" value={name} onChange={e => setName(e.target.value)} />
                        </div>
                        <div className="space-y-2">
                            <Label htmlFor="description">Description (Optional)</Label>
                            <Textarea id="description" value={description} onChange={e => setDescription(e.target.value)} />
                        </div>
                    </div>
                )}
                {step === 2 && (
                    <div className="space-y-4 py-4">
                        <Alert className="bg-blue-50 dark:bg-blue-900/10 border-blue-200">
                            <Sparkles className="h-4 w-4 text-blue-600" />
                            <AlertTitle>Analysis Complete</AlertTitle>
                            <AlertDescription>
                                We found {analysis?.variables?.length || 0} variables. Review suggestions below.
                            </AlertDescription>
                        </Alert>
                        <ScrollArea className="h-[250px] border rounded-md p-4">
                            <div className="space-y-3">
                                {analysis?.variables?.map((v: any, i: number) => {
                                    const mapping = mappings.find(m => m.templateVariable === v.name);
                                    return (
                                        <div key={i} className="flex items-center justify-between p-2 bg-slate-50 dark:bg-slate-800 rounded text-sm">
                                            <div className="font-mono">{v.name}</div>
                                            <div className="flex items-center gap-2">
                                                <ArrowRight className="w-3 h-3 text-muted-foreground" />
                                                <Badge variant={mapping?.workflowVariableId ? "default" : "secondary"}>
                                                    {mapping?.workflowVariableId ? (
                                                        workflowVariables.find(wv => wv.id === mapping.workflowVariableId)?.label || "Mapped"
                                                    ) : "New Variable"}
                                                </Badge>
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        </ScrollArea>
                        <p className="text-xs text-muted-foreground">
                            Variables marked "New" can be automatically created in your workflow later.
                        </p>
                    </div>
                )}
                <DialogFooter>
                    {step === 1 ? (
                        <Button onClick={() => { void uploadAndAnalyzeMutation.mutate(); }} disabled={!file || !name || uploadAndAnalyzeMutation.isPending}>
                            {uploadAndAnalyzeMutation.isPending ? <Loader2 className="animate-spin mr-2" /> : <Sparkles className="mr-2 w-4 h-4" />}
                            Analyze & Continue
                        </Button>
                    ) : (
                        <div className="flex gap-2">
                            <Button variant="ghost" onClick={() => { void setStep(1); }}>Back</Button>
                            <Button onClick={() => { void saveMutation.mutate(); }} disabled={saveMutation.isPending}>
                                {saveMutation.isPending ? <Loader2 className="animate-spin mr-2" /> : <CheckCircle className="mr-2 w-4 h-4" />}
                                Save Template
                            </Button>
                        </div>
                    )}
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

