import { create } from 'zustand';

import type { Node, Edge } from 'reactflow';

export interface BuilderNode extends Node {
  type: 'question' | 'compute' | 'branch' | 'template' | 'final';
  data: {
    label: string;
    config: any;
  };
}

export interface BuilderState {
  // Graph state
  nodes: BuilderNode[];
  edges: Edge[];
  selectedNodeId: string | null;

  // UI state
  isDirty: boolean;
  isSaving: boolean;
  saveError: string | null;

  // Actions
  setNodes: (nodes: BuilderNode[]) => void;
  setEdges: (edges: Edge[]) => void;
  addNode: (type: BuilderNode['type'], position: { x: number; y: number }) => void;
  updateNode: (nodeId: string, data: Partial<BuilderNode['data']>) => void;
  deleteNode: (nodeId: string) => void;
  selectNode: (nodeId: string | null) => void;

  // Graph operations
  onNodesChange: (changes: any) => void;
  onEdgesChange: (changes: any) => void;
  onConnect: (connection: any) => void;

  // Save state
  setDirty: (dirty: boolean) => void;
  setSaving: (saving: boolean) => void;
  setSaveError: (error: string | null) => void;

  // Load from API
  loadGraph: (graphJson: any) => void;

  // Export to API format
  exportGraph: () => any;

  // Power User Actions
  duplicateNode: (nodeId: string) => void;
}

export const useBuilderStore = create<BuilderState>((set, get) => ({
  // Initial state
  nodes: [],
  edges: [],
  selectedNodeId: null,
  isDirty: false,
  isSaving: false,
  saveError: null,

  // Actions
  setNodes: (nodes) => set({ nodes, isDirty: true }),

  setEdges: (edges) => set({ edges, isDirty: true }),

  addNode: (type, position) => {
    const state = get();
    const id = `node_${Date.now()}`;

    const newNode: BuilderNode = {
      id,
      type,
      position,
      data: {
        label: `${type.charAt(0).toUpperCase() + type.slice(1)} Node`,
        config: getDefaultConfig(type),
      },
    };

    set({
      nodes: [...state.nodes, newNode],
      isDirty: true,
      selectedNodeId: id,
    });
  },

  updateNode: (nodeId, data) => {
    const state = get();
    set({
      nodes: state.nodes.map(node =>
        node.id === nodeId
          ? { ...node, data: { ...node.data, ...data } }
          : node
      ),
      isDirty: true,
    });
  },

  deleteNode: (nodeId) => {
    const state = get();
    set({
      nodes: state.nodes.filter(node => node.id !== nodeId),
      edges: state.edges.filter(edge => edge.source !== nodeId && edge.target !== nodeId),
      isDirty: true,
      selectedNodeId: state.selectedNodeId === nodeId ? null : state.selectedNodeId,
    });
  },

  duplicateNode: (nodeId) => {
    const state = get();
    const nodeToDuplicate = state.nodes.find(n => n.id === nodeId);
    if (!nodeToDuplicate) {return;}

    const newId = `node_${Date.now()}`;
    // Position slightly offset
    const newPosition = {
      x: nodeToDuplicate.position.x + 50,
      y: nodeToDuplicate.position.y + 50,
    };

    const newNode: BuilderNode = {
      ...nodeToDuplicate,
      id: newId,
      position: newPosition,
      data: {
        ...nodeToDuplicate.data,
        label: `${nodeToDuplicate.data.label} (Copy)`,
        // Deep copy config to avoid reference issues
        config: JSON.parse(JSON.stringify(nodeToDuplicate.data.config)),
      },
      selected: true,
    };

    set({
      nodes: [...state.nodes.map(n => ({ ...n, selected: false })), newNode],
      isDirty: true,
      selectedNodeId: newId,
    });
  },

  selectNode: (nodeId) => set({ selectedNodeId: nodeId }),

  onNodesChange: (changes) => {
    const state = get();
    const updatedNodes = applyNodeChanges(changes, state.nodes);
    set({ nodes: updatedNodes, isDirty: true });
  },

  onEdgesChange: (changes) => {
    const state = get();
    const updatedEdges = applyEdgeChanges(changes, state.edges);
    set({ edges: updatedEdges, isDirty: true });
  },

  onConnect: (connection) => {
    const state = get();
    const newEdge: Edge = {
      id: `edge_${Date.now()}`,
      source: connection.source,
      target: connection.target,
      sourceHandle: connection.sourceHandle,
      targetHandle: connection.targetHandle,
    };
    set({ edges: [...state.edges, newEdge], isDirty: true });
  },

  setDirty: (dirty) => set({ isDirty: dirty }),

  setSaving: (saving) => set({ isSaving: saving }),

  setSaveError: (error) => set({ saveError: error }),

  loadGraph: (graphJson) => {
    if (!graphJson?.nodes) {
      set({ nodes: [], edges: [] });
      return;
    }

    // Convert API format to React Flow format
    const nodes: BuilderNode[] = graphJson.nodes.map((node: any, index: number) => ({
      id: node.id,
      type: node.type,
      position: node.position || { x: 100 + index * 200, y: 100 + index * 100 },
      data: {
        label: node.config?.label || `${node.type} Node`,
        config: node.config,
      },
    }));

    const edges: Edge[] = (graphJson.edges ?? []).map((edge: any) => ({
      id: edge.id,
      source: edge.source,
      target: edge.target,
    }));

    set({ nodes, edges, isDirty: false });
  },

  exportGraph: () => {
    const state = get();

    return {
      nodes: state.nodes.map(node => ({
        id: node.id,
        type: node.type,
        position: node.position,
        config: node.data.config,
      })),
      edges: state.edges.map(edge => ({
        id: edge.id,
        source: edge.source,
        target: edge.target,
      })),
      startNodeId: state.nodes.length > 0 ? state.nodes[0].id : undefined,
    };
  },
}));

// Helper function to get default config for each node type
function getDefaultConfig(type: BuilderNode['type']): any {
  switch (type) {
    case 'question':
      return {
        label: 'New Question',
        key: `q_${Date.now()}`,
        inputType: 'text',
        required: false,
        condition: '',
      };
    case 'compute':
      return {
        expression: '',
        outputKey: `c_${Date.now()}`,
        condition: '',
      };
    case 'branch':
      return {
        branches: [],
        condition: '',
      };
    case 'template':
      return {
        templateId: '',
        bindings: {},
        condition: '',
      };
    case 'final':
      return {
        title: 'Completion',
        message: '### Thank you!\nYour submission has been received.',
        showDocuments: true,
        condition: '',
      };
    default:
      return {};
  }
}

// Helper to apply node changes (from React Flow)
function applyNodeChanges(changes: any[], nodes: BuilderNode[]): BuilderNode[] {
  const result = [...nodes];

  for (const change of changes) {
    switch (change.type) {
      case 'position':
        const nodeIndex = result.findIndex(n => n.id === change.id);
        if (nodeIndex !== -1 && change.position) {
          result[nodeIndex] = {
            ...result[nodeIndex],
            position: change.position,
          };
        }
        break;
      case 'remove':
        return result.filter(n => n.id !== change.id);
      case 'select':
        const idx = result.findIndex(n => n.id === change.id);
        if (idx !== -1) {
          result[idx] = {
            ...result[idx],
            selected: change.selected,
          };
        }
        break;
    }
  }

  return result;
}

// Helper to apply edge changes (from React Flow)
function applyEdgeChanges(changes: any[], edges: Edge[]): Edge[] {
  const result = [...edges];

  for (const change of changes) {
    switch (change.type) {
      case 'remove':
        return result.filter(e => e.id !== change.id);
      case 'select':
        const idx = result.findIndex(e => e.id === change.id);
        if (idx !== -1) {
          result[idx] = {
            ...result[idx],
            selected: change.selected,
          };
        }
        break;
    }
  }

  return result;
}

/**
 * DataVault Filter Store
 * Manages filter state for table views
 */

import { create } from "zustand";

/**
 * Stable empty array reference to avoid infinite re-renders in React.
 * When using Zustand selectors, returning a new [] each time causes
 * useSyncExternalStore to detect a "change" and re-render infinitely.
 * Always use this constant for fallback empty arrays.
 */
export const EMPTY_FILTERS: FilterCondition[] = [];

export type FilterOperator =
  | "equals"
  | "not_equals"
  | "contains"
  | "not_contains"
  | "greater_than"
  | "less_than"
  | "greater_than_or_equal"
  | "less_than_or_equal"
  | "is_empty"
  | "is_not_empty"
  | "in"
  | "not_in";

export interface FilterCondition {
  id: string; // Unique ID for React keys
  columnId: string;
  operator: FilterOperator;
  value: string | number | boolean | null;
}

interface FilterState {
  // Filters by table ID
  filtersByTable: Record<string, FilterCondition[]>;

  // Actions
  setFilters: (tableId: string, filters: FilterCondition[]) => void;
  addFilter: (tableId: string, filter: FilterCondition) => void;
  updateFilter: (tableId: string, filterId: string, updates: Partial<FilterCondition>) => void;
  removeFilter: (tableId: string, filterId: string) => void;
  clearFilters: (tableId: string) => void;
  // NOTE: getFilters was removed - use selector pattern instead:
  // const filters = useDatavaultFilterStore((s) => s.filtersByTable[tableId] ?? EMPTY_FILTERS);
}

export const useDatavaultFilterStore = create<FilterState>((set, get) => ({
  filtersByTable: {},

  setFilters: (tableId, filters) =>
    set((state) => ({
      filtersByTable: {
        ...state.filtersByTable,
        [tableId]: filters,
      },
    })),

  addFilter: (tableId, filter) =>
    set((state) => {
      const existing = state.filtersByTable[tableId] ?? [];
      return {
        filtersByTable: {
          ...state.filtersByTable,
          [tableId]: [...existing, filter],
        },
      };
    }),

  updateFilter: (tableId, filterId, updates) =>
    set((state) => {
      const existing = state.filtersByTable[tableId] ?? [];
      return {
        filtersByTable: {
          ...state.filtersByTable,
          [tableId]: existing.map((f) =>
            f.id === filterId ? { ...f, ...updates } : f
          ),
        },
      };
    }),

  removeFilter: (tableId, filterId) =>
    set((state) => {
      const existing = state.filtersByTable[tableId] ?? [];
      return {
        filtersByTable: {
          ...state.filtersByTable,
          [tableId]: existing.filter((f) => f.id !== filterId),
        },
      };
    }),

  clearFilters: (tableId) =>
    set((state) => ({
      filtersByTable: {
        ...state.filtersByTable,
        [tableId]: [],
      },
    })),
}));

import { eq, and, desc, lt, or, inArray } from 'drizzle-orm';
import { Router, type Request, Response } from 'express';

import * as schema from '@shared/schema';

import { db } from '../db';
import { hybridAuth } from '../middleware/auth';
import { requirePermission } from '../middleware/rbac';
import { requireTenant } from '../middleware/tenant';
import { createError, formatErrorResponse } from '../utils/errors';
import { createPaginatedResponse, decodeCursor } from '../utils/pagination';

import {
  createProjectSchema,
  updateProjectSchema,
  listProjectsQuerySchema,
  projectParamsSchema,
} from './validators/projects';

import type { AuthRequest } from '../middleware/auth';



const router = Router();

/**
 * GET /projects
 * List all projects for the authenticated user's tenant
 */
router.get(
  '/',
  hybridAuth,
  requireTenant,
  requirePermission('project:view'),
  async (req: Request, res: Response) => {
    try {
      const authReq = req as AuthRequest;
      const tenantId = authReq.tenantId!;

      // Validate query params
      const query = listProjectsQuerySchema.parse(req.query);
      const { cursor, limit } = query;

      // Build where clause
      const whereConditions = [
        eq(schema.projects.tenantId, tenantId),
        eq(schema.projects.archived, false),
        or(
          eq(schema.projects.ownerId, authReq.userId!),
          // Subquery for shared projects
          inArray(
            schema.projects.id,
            db.select({ projectId: schema.projectAccess.projectId })
              .from(schema.projectAccess)
              .where(eq(schema.projectAccess.principalId, authReq.userId!))
          )
        )
      ];

      // Add cursor condition if provided
      if (cursor) {
        const decoded = decodeCursor(cursor);
        if (decoded) {
          whereConditions.push(
            lt(schema.projects.createdAt, new Date(decoded.timestamp))
          );
        }
      }

      // Fetch projects (limit + 1 for pagination)
      const projects = await db.query.projects.findMany({
        where: and(...whereConditions),
        orderBy: [desc(schema.projects.createdAt)],
        limit: limit + 1,
        with: {
          workflows: {
            columns: {
              id: true,
              status: true,
            },
          },
        },
      });

      // Map to include workflowCount (excluding archived workflows)
      const projectsWithCount = projects.map((project: any) => {
        const { workflows, ...rest } = project;
        const activeWorkflows = workflows.filter((w: any) => w.status !== 'archived');
        return {
          ...rest,
          workflowCount: activeWorkflows.length,
        };
      });

      // Create paginated response
      const response = createPaginatedResponse(projectsWithCount, limit);

      res.json(response);
    } catch (error) {
      const formatted = formatErrorResponse(error);
      res.status(formatted.status).json(formatted.body);
    }
  }
);

/**
 * POST /projects
 * Create a new project
 */
router.post(
  '/',
  hybridAuth,
  requireTenant,
  requirePermission('project:create'),
  async (req: Request, res: Response) => {
    try {
      const authReq = req as AuthRequest;
      const tenantId = authReq.tenantId!;
      const userId = authReq.userId!;

      // Validate request body
      const data = createProjectSchema.parse(req.body);

      // Create project
      const [project] = await db
        .insert(schema.projects)
        .values({
          name: data.name,
          title: data.name, // Legacy field
          description: data.description ?? null,
          tenantId,
          creatorId: userId,
          ownerId: userId,
          createdBy: userId,
          archived: false,
        })
        .returning();

      res.status(201).json(project);
    } catch (error) {
      const formatted = formatErrorResponse(error);
      res.status(formatted.status).json(formatted.body);
    }
  }
);

/**
 * GET /projects/:id
 * Get project by ID
 */
router.get(
  '/:id',
  hybridAuth,
  requireTenant,
  requirePermission('project:view'),
  async (req: Request, res: Response) => {
    try {
      const authReq = req as AuthRequest;
      const tenantId = authReq.tenantId!;

      // Validate params
      const params = projectParamsSchema.parse(req.params);

      // Fetch project with workflows
      const project = await db.query.projects.findFirst({
        where: and(
          eq(schema.projects.id, params.id),
          eq(schema.projects.tenantId, tenantId)
        ),
        with: {
          workflows: true,
        },
      });

      if (!project) {
        throw createError.notFound('Project', params.id);
      }

      res.json(project);
    } catch (error) {
      const formatted = formatErrorResponse(error);
      res.status(formatted.status).json(formatted.body);
    }
  }
);

/**
 * PATCH /projects/:id
 * Update project
 */
router.patch(
  '/:id',
  hybridAuth,
  requireTenant,
  requirePermission('project:edit'),
  async (req: Request, res: Response) => {
    try {
      const authReq = req as AuthRequest;
      const tenantId = authReq.tenantId!;

      // Validate params and body
      const params = projectParamsSchema.parse(req.params);
      const data = updateProjectSchema.parse(req.body);

      // Check project exists and belongs to tenant
      const existing = await db.query.projects.findFirst({
        where: and(
          eq(schema.projects.id, params.id),
          eq(schema.projects.tenantId, tenantId)
        ),
      });

      if (!existing) {
        throw createError.notFound('Project', params.id);
      }

      // Update project
      const [updated] = await db
        .update(schema.projects)
        .set({
          ...(data.name !== undefined && { name: data.name }),
          ...(data.description !== undefined && { description: data.description }),
          updatedAt: new Date(),
        })
        .where(eq(schema.projects.id, params.id))
        .returning();

      res.json(updated);
    } catch (error) {
      const formatted = formatErrorResponse(error);
      res.status(formatted.status).json(formatted.body);
    }
  }
);

/**
 * DELETE /projects/:id
 * Soft-delete project (set archived = true)
 */
router.delete(
  '/:id',
  hybridAuth,
  requireTenant,
  requirePermission('project:delete'),
  async (req: Request, res: Response) => {
    try {
      const authReq = req as AuthRequest;
      const tenantId = authReq.tenantId!;

      // Validate params
      const params = projectParamsSchema.parse(req.params);

      // Check project exists and belongs to tenant
      const existing = await db.query.projects.findFirst({
        where: and(
          eq(schema.projects.id, params.id),
          eq(schema.projects.tenantId, tenantId)
        ),
      });

      if (!existing) {
        throw createError.notFound('Project', params.id);
      }

      // Soft delete (set archived = true)
      await db
        .update(schema.projects)
        .set({
          archived: true,
          updatedAt: new Date(),
        })
        .where(eq(schema.projects.id, params.id));

      res.status(204).send();
    } catch (error) {
      const formatted = formatErrorResponse(error);
      res.status(formatted.status).json(formatted.body);
    }
  }
);

export default router;

