import type { AuthRequest } from '../middleware/auth';
const router = Router();
/**
 * POST /workflows/:id/run
 * Execute a workflow
 */
router.post(
  '/workflows/:id/run',
  hybridAuth,
  requireTenant,
  requirePermission('workflow:run'),
  async (req: Request, res: Response) => {
    try {
      const authReq = req as AuthRequest;
