          },
        },
      });
      if (!workflow) {
        throw createError.notFound('Workflow', params.id);
      }
      // Verify tenant access
      if (!workflow.project || workflow.project.tenantId !== tenantId) {
        throw createError.forbidden('Access denied to this workflow');
