        res.json({
          ok: false,
          errors: [{
            message: result.error,
            start: { line: 0, col: 0 },
            end: { line: 0, col: expression.length },
          }],
        });
      }
    } catch (error) {
      const formatted = formatErrorResponse(error);
      res.status(formatted.status).json(formatted.body);
    }
  }
  )
