export class AiController {
    /* eslint-disable @typescript-eslint/no-unsafe-assignment */


    /**
     * Check if AI services are available
     */
    static async getStatus(req: Request, res: Response): Promise<void> {
        try {
            const hasApiKey = !!process.env.GEMINI_API_KEY;

            res.json({
                available: hasApiKey,
                model: hasApiKey ? (process.env.GEMINI_MODEL || "gemini-2.0-flash") : null,
                features: hasApiKey ? [
                    "workflow_generation",
                    "sentiment_analysis",
                    "text_summarization"
                ] : []
            });
        } catch (error) {
            res.status(500).json({
                available: false,
                error: "Unable to check AI service status"
            });
        }
    }

    /**
     * Quick sentiment analysis for text
     */
    static async analyzeSentiment(req: Request, res: Response): Promise<Response | void> {
        try {
            const body = req.body as { text?: unknown };
            const { text } = body;

            if (!text || typeof text !== 'string') {
                return res.status(400).json({ message: "Text is required" });
            }

            if (!process.env.GEMINI_API_KEY) {
                return res.status(503).json({
                    message: "AI analysis not available"
                });
            }

            const result = await geminiService.analyzeSentiment(text);

            res.json({
                success: true,
                ...result
            });

        } catch (error) {
            aiLogger.error({ error }, "[AI] Error analyzing sentiment");
            res.status(500).json({
                message: "Failed to analyze sentiment",
                error: process.env.NODE_ENV === 'development' && error instanceof Error ? error.message : undefined
            });
        }
    }

    /**
     * Generate a new workflow from a natural language description
     */
    static async generateWorkflow(req: Request, res: Response): Promise<void> {
        const startTime = Date.now();
        const authReq = req as AuthRequest;
        const userId = authReq.userId;

        try {
            // Validate request body
            const requestData = AIWorkflowGenerationRequestSchema.parse(req.body);

            aiLogger.info({
                userId,
                projectId: requestData.projectId,
                descriptionLength: requestData.description.length,
            }, 'AI workflow generation requested');

            // Create AI service
            const aiService = createAIServiceFromEnv();

            // Generate workflow
            const generatedWorkflow = await aiService.generateWorkflow(requestData);

            const duration = Date.now() - startTime;

            aiLogger.info({
                userId,
                projectId: requestData.projectId,
                duration,
                sectionsCount: generatedWorkflow.sections.length,
                rulesCount: generatedWorkflow.logicRules.length,
                blocksCount: generatedWorkflow.transformBlocks.length,
            }, 'AI workflow generation succeeded');

            // Extract quality score (attached by AIService)
            const qualityScore = (generatedWorkflow as unknown as { __qualityScore?: AIError['qualityScore'] }).__qualityScore;

            res.status(200).json({
                success: true,
                workflow: generatedWorkflow,
                metadata: {
                    duration,
                    sectionsGenerated: generatedWorkflow.sections.length,
                    logicRulesGenerated: generatedWorkflow.logicRules.length,
                    transformBlocksGenerated: generatedWorkflow.transformBlocks.length,
                },
                quality: qualityScore ? {
                    score: qualityScore.overall,
                    breakdown: qualityScore.breakdown,
                    passed: qualityScore.passed,
                    issues: qualityScore.issues,
                    suggestions: qualityScore.suggestions,
                } : undefined,
            });
        } catch (error) {
            const duration = Date.now() - startTime;

            aiLogger.error({
                error,
                userId,
                duration,
            }, 'AI workflow generation failed');

            AiController.handleAiError(res, error);
        }
    }

    /**
     * Suggest improvements to an existing workflow
     */
    static async suggestWorkflowImprovements(req: Request, res: Response): Promise<Response | void> {
        const startTime = Date.now();
        const authReq = req as AuthRequest;
        const userId = authReq.userId!;
        const workflowId = req.params.id;

        try {
            // Validate request body
            const requestData = AIWorkflowSuggestionRequestSchema.parse({
                ...req.body,
                workflowId,
            });

            aiLogger.info({
                userId,
                workflowId,
                descriptionLength: requestData.description.length,
            }, 'AI workflow suggestion requested');

            // Fetch existing workflow
            const workflow = await workflowService.getWorkflowWithDetails(workflowId, userId);
            if (!workflow) {
                return res.status(404).json({
                    success: false,
                    message: 'Workflow not found',
                    error: 'not_found',
                });
            }

            // Create AI service
            const aiService = createAIServiceFromEnv();

            // Generate suggestions
            const suggestions = await aiService.suggestWorkflowImprovements(
                requestData,
                {
                    sections: workflow.sections ?? [],
                    logicRules: workflow.logicRules ?? [],
                    transformBlocks: (workflow as unknown as { transformBlocks?: unknown[] }).transformBlocks ?? [],
                }
            );

            const duration = Date.now() - startTime;

            aiLogger.info({
                userId,
                workflowId,
                duration,
                newSectionsCount: suggestions.newSections.length,
                newRulesCount: suggestions.newLogicRules.length,
                newBlocksCount: suggestions.newTransformBlocks.length,
                modificationsCount: suggestions.modifications.length,
            }, 'AI workflow suggestion succeeded');

            res.status(200).json({
                success: true,
                suggestions,
                metadata: {
                    duration,
                    newSectionsCount: suggestions.newSections.length,
                    newLogicRulesCount: suggestions.newLogicRules.length,
                    newTransformBlocksCount: suggestions.newTransformBlocks.length,
                    modificationsCount: suggestions.modifications.length,
                },
            });
        } catch (error) {
            const duration = Date.now() - startTime;

            aiLogger.error({
                error,
                userId,
                workflowId,
                duration,
            }, 'AI workflow suggestion failed');

            AiController.handleAiError(res, error);
        }
    }

    /**
     * Suggest variable bindings for a template
     */
    static async suggestTemplateBindings(req: Request, res: Response): Promise<Response | void> {
        const startTime = Date.now();
        const authReq = req as AuthRequest;
        const userId = authReq.userId!;
        const templateId = req.params.templateId;

        try {
            // Validate request body
            const requestData = AITemplateBindingsRequestSchema.parse({
                ...req.body,
                templateId,
            });

            aiLogger.info({
                userId,
                templateId,
                workflowId: requestData.workflowId,
            }, 'AI template binding suggestion requested');

            // Fetch the workflow for alias validation
            const workflow = await workflowService.getWorkflowWithDetails(
                requestData.workflowId,
                userId
            );
            if (!workflow) {
                return res.status(404).json({
                    success: false,
                    message: 'Workflow not found',
                    error: 'not_found',
                });
            }

            // Get workflow variables
            const variables = await variableService.listVariables(
                requestData.workflowId,
                userId
            );

            // Get template placeholders (from request or fetch from template)
            const placeholders = requestData.placeholders ?? [];
            if ((placeholders.length === 0) && templateId) {
                // TODO: Fetch placeholders from template
                // For now, require placeholders to be provided
                return res.status(400).json({
                    success: false,
                    message: 'Placeholders must be provided',
                    error: 'validation_error',
                });
            }

            // Create AI service
            const aiService = createAIServiceFromEnv();

            // Generate binding suggestions with workflow for alias validation
            const bindingSuggestions = await aiService.suggestTemplateBindings(
                requestData,
                variables as AiVariable[],
                placeholders,
                workflow // Pass workflow for alias validation
            );

            const duration = Date.now() - startTime;

            aiLogger.info({
                userId,
                templateId,
                workflowId: requestData.workflowId,
                duration,
                suggestionsCount: bindingSuggestions.suggestions.length,
                warningsCount: bindingSuggestions.warnings?.length || 0,
            }, 'AI template binding suggestion succeeded');

            res.status(200).json({
                success: true,
                bindings: bindingSuggestions,
                metadata: {
                    duration,
                    suggestionsCount: bindingSuggestions.suggestions.length,
                    unmatchedPlaceholdersCount: bindingSuggestions.unmatchedPlaceholders.length,
                    unmatchedVariablesCount: bindingSuggestions.unmatchedVariables.length,
                    warningsCount: bindingSuggestions.warnings?.length || 0,
                },
            });
        } catch (error) {
            const duration = Date.now() - startTime;

            aiLogger.error({
                error,
                userId,
                templateId,
                duration,
            }, 'AI template binding suggestion failed');

            AiController.handleAiError(res, error);
        }
    }

    /**
     * Iteratively revise a workflow using natural language
     */
    static async reviseWorkflow(req: Request, res: Response): Promise<Response | void> {
        const authReq = req as AuthRequest;
        const userId = authReq.userId!;

        try {
            const requestData = AIWorkflowRevisionRequestSchema.parse(req.body);

            // Verify ownership first
            await workflowService.verifyAccess(requestData.workflowId, userId, 'edit');

            // Enqueue Job
            const job = await enqueueAiRevision({
                ...requestData,
                userId
            });

            aiLogger.info({
                userId,
                workflowId: requestData.workflowId,
                jobId: job.id
            }, 'AI workflow revision job enqueued');

            res.status(202).json({
                success: true,
                message: 'AI revision started in background',
                jobId: job.id,
                status: 'pending'
            });

        } catch (error) {
            const err = error as AIError;
            aiLogger.error({
                error: err.message || err,
                stack: err.stack
            }, 'Failed to enqueue AI revision job');

            // handleAiError can handle ZodError too, refer to lines below
            return AiController.handleAiError(res, error);
        }
    }

    /**
     * Check status of revision job
     */
    static async getRevisionJobStatus(req: Request, res: Response): Promise<Response | void> {
        try {
            const { jobId } = req.params;
            const job = await getAiRevisionJob(jobId);

            if (!job) {
                return res.status(404).json({
                    success: false,
                    message: 'Job not found',
                    error: 'not_found'
                });
            }

            // Verify user owns this job (job.data.userId === req.userId)
            const authReq = req as AuthRequest;
            if (job.data.userId !== authReq.userId) {
                return res.status(403).json({
                    success: false,
                    message: 'Access denied',
                    error: 'forbidden'
                });
            }

            const state = await job.getState();
            const result = job.returnvalue;
            const error = job.failedReason;

            res.json({
                success: true,
                jobId,
                status: state,
                result: state === 'completed' ? result : undefined,
                error: state === 'failed' ? error : undefined,
                progress: job.progress() as number | object
            });

        } catch (error) {
            aiLogger.error({ error }, 'Failed to get job status');
            res.status(500).json({
                success: false,
                message: 'Failed to get status',
                error: 'internal_error'
            });
        }
    }

    /**
     * Generate random plausible values for workflow steps
     */
    static async suggestValues(req: Request, res: Response): Promise<Response | void> {
        try {
            const body = req.body as { workflowId: string; steps: unknown; mode?: string };
            const { workflowId, mode = 'full' } = body;

            const rawSteps = body.steps;
            // Validate steps is an array and matching structure (basic check + cast)
            if (!Array.isArray(rawSteps) || rawSteps.length === 0) {
                return res.status(400).json({
                    success: false,
                    message: 'Steps array is required and must not be empty',
                    error: 'invalid_request',
                });
            }

            const steps = rawSteps as AiValueSuggestionStep[];

            // Validate AI configuration (GEMINI_API_KEY or AI_API_KEY)
            if (!process.env.GEMINI_API_KEY && !process.env.AI_API_KEY) {
                return res.status(503).json({
                    success: false,
                    message: 'AI service not configured - please set GEMINI_API_KEY or AI_API_KEY',
                    error: 'service_unavailable',
                });
            }

            aiLogger.info({
                workflowId,
                stepCount: steps.length,
                mode,
            }, 'AI value suggestion requested');

            // Create AI service and generate values
            const aiService = createAIServiceFromEnv();
            const values = await aiService.suggestValues(steps, mode as 'full' | 'partial');

            res.json({
                success: true,
                data: values,
            });
        } catch (error) {
            aiLogger.error({ error }, 'Error generating value suggestions');
            AiController.handleAiError(res, error);
        }
    }

    /**
     * Connect workflow nodes with logic rules
     */
    static async generateLogic(req: Request, res: Response): Promise<void> {
        const startTime = Date.now();
        const authReq = req as AuthRequest;
        const userId = authReq.userId!;

        try {
            const requestData = AIConnectLogicRequestSchema.parse(req.body);

            aiLogger.info({
                userId,
                workflowId: requestData.workflowId,
                descriptionLength: requestData.description.length,
            }, 'AI logic generation requested');

            await workflowService.verifyAccess(requestData.workflowId, userId, 'edit');

            const aiService = createAIServiceFromEnv();
            const result = await aiService.generateLogic(requestData);

            const duration = Date.now() - startTime;
            aiLogger.info({
                userId,
                workflowId: requestData.workflowId,
                duration,
                changeCount: result.diff.changes.length
            }, 'AI logic generation succeeded');

            res.status(200).json({
                success: true,
                ...result,
                metadata: {
                    duration,
                    changeCount: result.diff.changes.length
                }
            });

        } catch (error) {
            aiLogger.error({ error }, 'AI logic generation failed');
            AiController.handleAiError(res, error);
        }
    }

    /**
     * Analyze logic for issues
     */
    static async debugLogic(req: Request, res: Response): Promise<void> {
        try {
            const requestData = AIDebugLogicRequestSchema.parse(req.body);
            const aiService = createAIServiceFromEnv();
            const result = await aiService.debugLogic(requestData);
            res.status(200).json({ success: true, ...result });
        } catch (error) {
            aiLogger.error({ error }, 'AI debug logic failed');
            AiController.handleAiError(res, error);
        }
    }

    /**
     * Generate graph representation of logic
     */
    static async visualizeLogic(req: Request, res: Response): Promise<void> {
        try {
            const requestData = AIVisualizeLogicRequestSchema.parse(req.body);
            const aiService = createAIServiceFromEnv();
            const result = await aiService.visualizeLogic(requestData);
            res.status(200).json({ success: true, ...result });
        } catch (error) {
            aiLogger.error({ error }, 'AI visualize logic failed');
            AiController.handleAiError(res, error);
        }
    }

    /**
     * Centralized error handling for AI routes
     */
    private static handleAiError(res: Response, error: unknown): void {
        if (error === null || typeof error !== 'object') {
            res.status(500).json({
                success: false,
                message: 'Internal server error',
                error: 'internal_error',
            });
            return;
        }

        const err = error as AIError;

        if (err.code === 'RATE_LIMIT') {
            res.status(429).json({
                success: false,
                message: 'AI API rate limit exceeded. Please try again later.',
                error: 'ai_rate_limit',
            });
            return;
        }

        if (err.code === 'TIMEOUT') {
            res.status(504).json({
                success: false,
                message: 'AI request timed out. Please try again.',
                error: 'ai_timeout',
            });
            return;
        }

        if (err.name === 'ZodError') {
            res.status(400).json({
                success: false,
                message: 'Invalid request data',
                error: 'validation_error',
                details: err.errors,
            });
            return;
        }

        if (err.code === 'VALIDATION_ERROR') {
            res.status(422).json({
                success: false,
                message: 'AI generated invalid structure.',
                error: 'ai_validation_error',
                details: err.details,
            });
            return;
        }

        // Handle quality threshold errors - HTTP 422 Unprocessable Entity
        if (err.code === 'QUALITY_THRESHOLD' || err.name === 'QualityThresholdError') {
            res.status(422).json({
                success: false,
                message: (err.message as string) ?? 'Generated workflow quality is below minimum threshold.',
                error: 'quality_threshold_error',
                quality: {
                    score: err.qualityScore,
                    threshold: err.threshold,
                    breakdown: err.qualityBreakdown,
                    issues: err.qualityIssues,
                    suggestions: err.qualitySuggestions,
                },
            });
            return;
        }

        res.status(500).json({
            success: false,
            message: 'Internal server error',
            error: 'internal_error',
            details: process.env.NODE_ENV === 'development' ? err.message : undefined,
        });
    }
}

import dotenv from "dotenv";
dotenv.config();

import * as schema from "@shared/schema";

import { env } from "./config/env";
import { logger } from './logger';

import type { Pool as NeonPool } from '@neondatabase/serverless';
import type { NeonDatabase } from 'drizzle-orm/neon-serverless';
import type { NodePgDatabase } from 'drizzle-orm/node-postgres';
import type { Pool } from 'pg';

type DrizzleDB = NodePgDatabase<typeof schema> | NeonDatabase<typeof schema>;

let pool: Pool | NeonPool;
let _db: DrizzleDB | null = null;  // Internal db reference
let dbInitialized = false;
let dbInitPromise: Promise<void>;

// Initialize database connection
async function initializeDatabase() {
  if (dbInitialized) { return; }

  const databaseUrl = env.DATABASE_URL;
  const isDatabaseConfigured = !!databaseUrl && databaseUrl !== 'undefined' && databaseUrl !== '';

  if (!isDatabaseConfigured) {
    throw new Error(
      "DATABASE_URL must be set. Did you forget to provision a database?"
    );
  }

  // Detect if we're using Neon serverless or local PostgreSQL
  // In TEST environment, we force 'pg' (local/TCP) driver because Neon Serverless (WebSockets)
  // does not support 'search_path' in startup options, which is required for schema isolation.
  const isNeonDatabase = isDatabaseConfigured &&
    env.NODE_ENV !== 'test' &&
    (databaseUrl.includes('neon.tech') || databaseUrl.includes('neon.co'));

  logger.info(`DB: initializing... ${isNeonDatabase ? "Neon" : "Local"}`);
  if (isNeonDatabase) {
    // Use Neon serverless driver for cloud databases
    const { Pool: NeonPoolClass, neonConfig } = await import('@neondatabase/serverless');
    const ws = await import('ws');

    neonConfig.webSocketConstructor = ws.default;
    pool = new NeonPoolClass({ connectionString: databaseUrl });

    const { drizzle: drizzleNeon } = await import('drizzle-orm/neon-serverless');
    _db = drizzleNeon(pool as any, { schema });
  } else {
    // Use standard PostgreSQL driver for local databases
    logger.debug("DB: importing pg...");
    const pg = await import('pg');

    logger.debug("DB: creating pool...");
    pool = new pg.default.Pool({ connectionString: databaseUrl });

    // For test schemas, set search_path on new connections via on('connect')
    const testSchema = process.env.TEST_SCHEMA || (global as any).__TEST_SCHEMA__;
    if (testSchema && env.NODE_ENV === 'test') {
      pool.on('connect', async (client) => {
        try {
          await client.query(`SET search_path TO "${testSchema}", public`);
          logger.debug(`DB: Set search_path on new connection: "${testSchema}",public`);
        } catch (err: any) {
          logger.warn(`DB: Failed to set search_path on connection: ${err.message}`);
        }
      });

      logger.info(`DB: Configured on('connect') to set search_path="${testSchema}",public`);
    }

    logger.debug("DB: importing drizzle...");
    const { drizzle: drizzlePg } = await import('drizzle-orm/node-postgres');
    _db = drizzlePg(pool as any, { schema });
    logger.debug("DB: created.");
  }

  dbInitialized = true;
  logger.info("DB: initialized flag set.");
}

// Start initialization immediately only if database is configured
// If not configured, create a lazy promise that will reject when awaited
// For tests, we might initialize later manually
const initialDatabaseUrl = env.DATABASE_URL;
const isInitialConfigured = !!initialDatabaseUrl && initialDatabaseUrl !== 'undefined' && initialDatabaseUrl !== '';
const isTest = env.NODE_ENV === 'test';

if (isInitialConfigured) {
  if (isTest) {
    console.log("DB: Skipping auto-init because NODE_ENV=test");
  } else {
    console.log("DB: Auto-initializing...");
  }
} else {
  console.log("DB: Not auto-initializing because DATABASE_URL is missing/empty");
}

dbInitPromise = (isInitialConfigured && !isTest)
  ? initializeDatabase()
  : Promise.resolve();

// Getter to ensure db is initialized before use
function getDb() {
  if (!dbInitialized) {
    throw new Error("Database not initialized. Call await initializeDatabase() first.");
  }
  return _db;
}

// Close database connection (useful for tests)
async function closeDatabase() {
  if (pool) {
    logger.info("DB: closing pool...");
    await pool.end();
    dbInitialized = false;
    _db = null;
    logger.info("DB: pool closed.");
  }
}

// Create a getter for db that returns the initialized database
// This ensures that code importing { db } will get the properly initialized instance
const db = new Proxy({} as DrizzleDB, {
  get(target, prop) {
    if (!_db) {
      throw new Error("Database not initialized. Call await initializeDatabase() first.");
    }
    return _db[prop as keyof DrizzleDB];
  },
  set(target, prop, value) {
    if (!_db) {
      throw new Error("Database not initialized. Call await initializeDatabase() first.");
    }
    (_db as any)[prop] = value;
    return true;
  }
});

export { pool, db, getDb, initializeDatabase, closeDatabase, dbInitPromise };

import { Parser } from 'expr-eval';

/**
 * Expression Evaluator
 * Safe, deterministic expression evaluation with whitelisted helpers
 *
 * Uses expr-eval library for parsing/evaluating expressions.
 * Does NOT use eval(), Function(), or dynamic code generation.
 */

import type { VariableLineage, ListLineage } from '@shared/types/debug';

export type EvalContext = {
  vars: Record<string, unknown>;   // user answers + computed vars only
  workflowId?: string;             // Current workflow ID
  helpers?: Record<string, (...args: any[]) => any>;
  clock?: () => Date;              // injected clock for determinism (default fixed or from options)
  executionMode?: 'live' | 'preview' | 'snapshot'; // Execution mode
  writes?: Record<string, any>;    // Isolated writes for preview mode
  variableLineage?: Record<string, VariableLineage>; // Variable derivation history
  listLineage?: Record<string, ListLineage>; // List variable sources

  // Performance and Caching
  cache?: {
    queries: Map<string, any>;     // Cache for query results
    scripts: Map<string, any>;     // Cache for compiled scripts
  };
  metrics?: {
    dbTimeMs: number;
    jsTimeMs: number;
    queryCount: number;
  };
  resources?: {
    isolate?: any; // isolated-vm instance
  };

  // Guardrails
  executedSideEffects?: Set<string>; // Block IDs that have already executed a write/send
  limits?: {
    maxExecutionTimeMs?: number;
    maxSteps?: number;
    maxQueryCount?: number;
  };
};

export type ValidateResult = { ok: true } | { ok: false; error: string };

// Forbidden identifiers that could allow prototype access
const FORBIDDEN_IDENTIFIERS = [
  '__proto__',
  'constructor',
  'prototype',
  'eval',
  'Function',
  'this',
];

// Whitelisted helper functions
// Note: expr-eval has built-in functions we leverage:
// - roundTo(n, decimals) - use instead of round(n, decimals)
// - abs, ceil, floor, round (unary), sqrt, etc.
// - min, max, pow (multi-arg)
export const Helpers = {
  // Math helpers
  // Use expr-eval's built-in roundTo instead of custom round
  roundTo: (n: number, digits: number = 0): number => {
    const factor = Math.pow(10, digits);
    return Math.round(n * factor) / factor;
  },
  // Note: abs, ceil, floor are built-in unary ops in expr-eval
  // We include them here for consistency, but they work as-is
  abs: (n: number): number => Math.abs(n),
  ceil: (n: number): number => Math.ceil(n),
  floor: (n: number): number => Math.floor(n),
  // Note: min, max are built-in functions in expr-eval
  min: (...args: number[]): number => Math.min(...args),
  max: (...args: number[]): number => Math.max(...args),

  // String helpers
  len: (s: string): number => String(s).length,
  upper: (s: string): string => String(s).toUpperCase(),
  lower: (s: string): string => String(s).toLowerCase(),
  contains: (s: string, sub: string): boolean => String(s).includes(String(sub)),
  trim: (s: string): string => String(s).trim(),
  concat: (...parts: any[]): string => parts.map(p => String(p)).join(''),

  // Array helpers
  includes: (arr: any[], v: any): boolean => {
    if (!Array.isArray(arr)) {return false;}
    return arr.includes(v);
  },
  count: (arr: any[]): number => {
    if (!Array.isArray(arr)) {return 0;}
    return arr.length;
  },

  // Date helpers (deterministic via injected clock)
  dateDiff: (unit: string, fromISO: string, toISO?: string, clock?: () => Date): number => {
    const from = new Date(fromISO);
    const to = toISO ? new Date(toISO) : (clock ? clock() : new Date(0));

    const diffMs = to.getTime() - from.getTime();

    switch (unit) {
      case 'days':
        return Math.floor(diffMs / (1000 * 60 * 60 * 24));
      case 'hours':
        return Math.floor(diffMs / (1000 * 60 * 60));
      case 'minutes':
        return Math.floor(diffMs / (1000 * 60));
      case 'seconds':
        return Math.floor(diffMs / 1000);
      default:
        throw new Error(`Invalid date unit: ${unit}`);
    }
  },

  // Logic helpers
  coalesce: (...vals: any[]): any => {
    for (const val of vals) {
      if (val !== null && val !== undefined) {
        return val;
      }
    }
    return null;
  },
  isEmpty: (v: any): boolean => {
    if (v === null || v === undefined) {return true;}
    if (typeof v === 'string') {return v.trim().length === 0;}
    if (Array.isArray(v)) {return v.length === 0;}
    if (typeof v === 'object') {return Object.keys(v).length === 0;}
    return false;
  },
  not: (v: any): boolean => !v,

  // PDF Helpers
  checkbox: (v: any): string => v ? 'X' : '',
};

// List of all allowed helper names for validation
export const AllowedHelperNames = Object.keys(Helpers);

/**
 * Validate an expression for safety and correctness
 *
 * @param expr - Expression string to validate
 * @param allowedVars - List of allowed variable names
 * @returns Validation result
 */
export function validateExpression(expr: string, allowedVars: string[]): ValidateResult {
  try {
    // Check for forbidden identifiers in the expression string first
    const exprStr = expr.toLowerCase();
    for (const forbidden of FORBIDDEN_IDENTIFIERS) {
      // Use word boundary regex to check for forbidden identifiers
      const pattern = new RegExp(`\\b${forbidden.toLowerCase()}\\b`);
      if (pattern.test(exprStr)) {
        return {
          ok: false,
          error: `Forbidden identifier: ${forbidden}`,
        };
      }
    }

    // Parse the expression
    const parser = new Parser();

    // Register helper functions for validation
    // Note: All helpers registered as functions (not unaryOps) to support multi-arg
    for (const helperName of AllowedHelperNames) {
      // Use a variadic dummy function to support both single and multi-arg helpers
      parser.functions[helperName] = ((...args: any[]) => null) as any;
    }

    const parsed = parser.parse(expr);

    // Get all variables used in the expression
    const usedVars = parsed.variables();

    // Create set of allowed identifiers (vars only, since functions are registered separately)
    const allowedIdentifiers = new Set(allowedVars);

    // Check that all used variables are allowed
    for (const varName of usedVars) {
      // Skip if it's a helper function (already registered)
      if (AllowedHelperNames.includes(varName)) {
        continue;
      }

      if (!allowedIdentifiers.has(varName)) {
        return {
          ok: false,
          error: `Unknown identifier: ${varName}. Allowed: ${Array.from(allowedIdentifiers).join(', ')}`,
        };
      }
    }

    // Expression is valid
    return { ok: true };
  } catch (error) {
    return {
      ok: false,
      error: error instanceof Error ? error.message : 'Invalid expression syntax',
    };
  }
}

/**
 * Evaluate an expression safely
 *
 * @param expr - Expression string to evaluate
 * @param ctx - Evaluation context with variables and helpers
 * @param options - Optional evaluation options
 * @returns Evaluated result
 */
export function evaluateExpression(
  expr: string,
  ctx: EvalContext,
  options?: { maxOps?: number; timeoutMs?: number }
): any {
  const maxOps = options?.maxOps ?? 10000;
  const timeoutMs = options?.timeoutMs ?? 50;

  try {
    // Create operation counter
    let opCount = 0;
    const startTime = Date.now();

    // Create combined scope with vars and helpers
    const clock = ctx.clock ?? (() => new Date(0));

    // Bind clock to dateDiff helper
    const helpersWithClock = {
      ...Helpers,
      dateDiff: (unit: string, fromISO: string, toISO?: string) =>
        Helpers.dateDiff(unit, fromISO, toISO, clock),
    };

    // Filter out undefined values from vars
    const cleanVars: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(ctx.vars)) {
      if (value !== undefined) {
        cleanVars[key] = value;
      }
    }

    const scope = {
      ...cleanVars,
      ...helpersWithClock,
      ...ctx.helpers,
    };

    // Parse and evaluate
    const parser = new Parser();

    // Register functions
    for (const [name, fn] of Object.entries(helpersWithClock)) {
      parser.functions[name] = fn;
    }

    const parsed = parser.parse(expr);

    // Check for property access (not fully supported by expr-eval's variables() method)
    // We'll rely on the sandbox nature of expr-eval and the fact that we control the scope
    const exprStr = expr.toLowerCase();
    for (const forbidden of FORBIDDEN_IDENTIFIERS) {
      if (exprStr.includes(forbidden.toLowerCase())) {
        throw new Error(`Forbidden identifier: ${forbidden}`);
      }
    }

    // SECURITY FIX: Add operation counting to prevent DoS
    // Wrap all helpers to count operations and enforce limits
    const MAX_OPERATIONS = options?.maxOps ?? 10000;


    const wrappedHelpers: any = {};
    for (const [name, fn] of Object.entries(helpersWithClock)) {
      wrappedHelpers[name] = (...args: any[]) => {
        opCount++;
        if (opCount > MAX_OPERATIONS) {
          throw new Error(`Expression exceeded maximum operations (${MAX_OPERATIONS})`);
        }
        return (fn as any)(...args);
      };
    }

    // Add wrapped helpers to parser
    for (const [name, fn] of Object.entries(wrappedHelpers)) {
      parser.functions[name] = fn;
    }

    // Evaluate with timeout protection
    const timeoutId = setTimeout(() => {
      throw new Error(`Expression evaluation timeout (${timeoutMs}ms)`);
    }, timeoutMs);

    try {
      // Note: setTimeout doesn't interrupt JS execution, but operation counting does
      const result = parsed.evaluate(cleanVars as any);
      clearTimeout(timeoutId);

      // Additional time check
      const elapsed = Date.now() - startTime;
      if (elapsed > timeoutMs) {
        throw new Error(`Expression evaluation took too long (${elapsed}ms > ${timeoutMs}ms)`);
      }

      return result;
    } catch (evalError) {
      clearTimeout(timeoutId);
      throw evalError;
    }
  } catch (error) {
    // Sanitize error message (no stack traces)
    const message = error instanceof Error ? error.message : 'Expression evaluation failed';
    throw new Error(`Expression error: ${message}`);
  }
}

/**
 * Check if an expression is a simple boolean condition
 */
export function isBooleanExpression(expr: string): boolean {
  try {
    const parser = new Parser();
    const parsed = parser.parse(expr);
    // This is a heuristic - we can't definitively know without evaluating
    return true;
  } catch {
    return false;
  }
}

import type { WorkflowVersion } from '@shared/schema';
import type { ExecutionStep, VariableLineage, WorkflowTrace } from '@shared/types/debug';

import { createError } from '../utils/errors';

import { type EvalContext, evaluateExpression } from './expr';
import { executeNode } from './registry';
import { validateGraph, validateNodeConditions, type GraphJson } from './validate';
/**
 * Workflow Engine
 * Executes workflow graphs with conditional logic and expression evaluation
 *
 * Stage 5: Expression evaluator + conditional logic integration
 */
export interface RunGraphOptions {
  debug?: boolean;
  clock?: () => Date;              // Injected clock for deterministic evaluation
}
export interface RunGraphInput {
  workflowVersion: WorkflowVersion;
  inputJson: Record<string, any>;
  tenantId: string;
  executionMode?: 'live' | 'preview';
  options?: RunGraphOptions;
}
// DEPRECATED TraceEntry - Use ExecutionStep instead
export interface TraceEntry {
  nodeId: string;
  type: string;
  condition?: string;
  conditionResult?: boolean;
  status: 'executed' | 'skipped';
  outputsDelta?: Record<string, any>;
  sideEffects?: Record<string, any>;
  error?: string;
  timestamp: Date;
}
export interface RunGraphOutput {
  status: 'success' | 'error';
  outputRefs?: Record<string, any>;
  logs: Array<{
    level: 'info' | 'warn' | 'error';
    message: string;
    nodeId?: string;
    context?: Record<string, any>;
    timestamp: Date;
  }>;
  trace?: TraceEntry[];            // Legacy simple trace
  executionTrace?: WorkflowTrace;  // Full rich trace
  error?: string;
}
export async function runGraph(input: RunGraphInput): Promise<RunGraphOutput> {
  const { workflowVersion, inputJson, tenantId, options = {} } = input;
  const logs: RunGraphOutput['logs'] = [];
  const trace: TraceEntry[] = [];
  const executionSteps: ExecutionStep[] = [];
  const variableLineage: Record<string, VariableLineage> = {};
  // const listLineage: Record<string, ListLineage> = {}; // TODO: Implement List lineage
  const startTime = Date.now();
  try {
    // Log start
    logs.push({
      level: 'info',
      message: `Starting workflow execution for version ${workflowVersion.id}`,
      timestamp: new Date(),
    });
    // Parse and validate graphJson structure
    const graphJson = workflowVersion.graphJson as GraphJson;
    if (!graphJson || typeof graphJson !== 'object') {
      throw new Error('Invalid graphJson: must be an object');
    }
    if (options.debug) {
      logs.push({
        level: 'info',
        message: 'Debug mode enabled',
        context: { inputJson, graphJson },
        timestamp: new Date(),
      });
    }
    // Validate graph structure
    const graphValidation = validateGraph(graphJson);
    if (!graphValidation.valid) {
      const errorMessages = graphValidation.errors.map(e => e.message).join('; ');
      throw new Error(`Graph validation failed: ${errorMessages}`);
    }
    // Validate node conditions and expressions
    const conditionsValidation = validateNodeConditions(graphJson);
    if (!conditionsValidation.valid) {
      const errorMessages = conditionsValidation.errors
        .map(e => `${e.path || e.nodeId}: ${e.message}`)
        .join('; ');
      throw new Error(`Expression validation failed: ${errorMessages}`);
    }
    logs.push({
      level: 'info',
      message: 'Graph validation passed',
      timestamp: new Date(),
    });
    // Initialize execution context resources
    let ivm: typeof import("isolated-vm") | undefined;
    let isolate: import("isolated-vm").Isolate | undefined;
    try {
      ivm = await import("isolated-vm");
      isolate = new ivm.Isolate({ memoryLimit: 128 });
    } catch (e) {
      // Fallback or log if isolated-vm is missing (though it shouldn't be for live execution)
    }
    const context: EvalContext = {
      vars: { ...inputJson, input: inputJson },
      clock: options.clock || (() => new Date()),
      executionMode: input.executionMode || 'live',
      writes: input.executionMode === 'preview' ? {} : undefined,
      variableLineage,
      cache: {
        queries: new Map(),
        scripts: new Map() // Shared script cache for this run
      },
      metrics: {
        dbTimeMs: 0,
        jsTimeMs: 0,
        queryCount: 0
      },
      resources: {
        isolate
      },
      executedSideEffects: new Set(),
      limits: {
        maxExecutionTimeMs: 30000, // 30s hard limit
        maxSteps: 1000,
        // maxQueryCount not strictly enforced yet, but tracked
      }
    };
    // Get execution order (topological sort)
    const executionOrder = getExecutionOrder(graphJson);
    logs.push({
      level: 'info',
      message: `Executing ${executionOrder.length} nodes`,
      timestamp: new Date(),
    });
    // Execute nodes in order
    const outputRefs: Record<string, any> = {};
    try {
      for (const nodeId of executionOrder) {
        // Check limits
        if (Date.now() - startTime > (context.limits!.maxExecutionTimeMs!)) {
          throw new Error(`Execution time exceeded limit of ${context.limits!.maxExecutionTimeMs}ms`);
        }
        if (executionSteps.length >= context.limits!.maxSteps!) {
          throw new Error(`Execution step limit exceeded (${context.limits!.maxSteps})`);
        }
        const node = graphJson.nodes.find(n => n.id === nodeId);
        if (!node) {
          // ... (existing not found log) ...
          continue;
        }
        // SNAPSHOT EFFICIENCY: Skip blocks with already satisfied outputs (Part 5)
        const config = node.config as any;
        if (context.executionMode === 'snapshot' && config.outputKey && context.vars[config.outputKey] !== undefined) {
          const stepIndex = executionSteps.length;
          // We can push a "Skipped" step to maintain trace continuity if desired,
          // or just implicitly skip. For observability, explicit skip is better.
          executionSteps.push({
            stepNumber: stepIndex,
            blockId: nodeId,
            blockType: node.type,
            timestamp: new Date(),
            status: 'skipped',
            skippedReason: 'snapshot satisfied (cached output)',
            inputs: {},
            outputs: { [config.outputKey]: context.vars[config.outputKey] },
            durationMs: 0,
            metrics: { totalTimeMs: 0 }
          });
          continue; // Skip actual execution
        }
        try {
          const nodeStartTime = Date.now();
          const config = node.config as any;
          // SNAPSHOT EFFICIENCY: Skip blocks with already satisfied outputs (Part 5)
          if (context.executionMode === 'snapshot' && config.outputKey && context.vars[config.outputKey] !== undefined) {
            // ... existing snapshot logic ...
            const stepIndex = executionSteps.length;
            executionSteps.push({
              stepNumber: stepIndex,
              blockId: nodeId,
              blockType: node.type,
              timestamp: new Date(),
              status: 'skipped',
              skippedReason: 'snapshot satisfied (cached output)',
              inputs: {},
              outputs: { [config.outputKey]: context.vars[config.outputKey] },
              durationMs: 0,
              metrics: { totalTimeMs: 0 }
            });
            continue; // Skip actual execution
          }
          // check for condition
          if (config.condition) {
            try {
              const conditionResult = evaluateExpression(config.condition, context);
              if (options.debug) {
                // Debug logging removed - use logger if needed
              }
              if (!conditionResult) {
                const stepIndex = executionSteps.length;
                // Push skipped step
                executionSteps.push({
                  stepNumber: stepIndex,
                  blockId: nodeId,
                  blockType: node.type,
                  timestamp: new Date(),
                  status: 'skipped',
                  skippedReason: 'condition false',
                  inputs: {},
                  outputs: {},
                  durationMs: 0,
                  metrics: { totalTimeMs: 0 }
                });
                // Push legacy trace (for tests)
                trace.push({
                  nodeId,
                  type: node.type,
                  status: 'skipped',
                  condition: config.condition,
                  conditionResult: false,
                  timestamp: new Date()
                });
                logs.push({
                  level: 'info',
                  message: `Skipped node ${nodeId} (condition false)`,
                  nodeId,
                  timestamp: new Date()
                });
                continue;
              } else {
                // Log condition true (optional, maybe debug only)
                // Add condition result to trace if executed?
                // The existing legacy trace might expect it.
              }
            } catch (condError) {
              // If condition evaluation fails, treat as error? Or fail closed (skip)?
              // Usually treat as error.
              throw new Error(`Condition evaluation failed for node ${nodeId}: ${condError instanceof Error ? condError.message : String(condError)}`);
            }
          }
          // Execute node
          const nodeOutput = await executeNode({
            node,
            context,
            tenantId,
            userInputs: inputJson,
          });
          const nodeDuration = Date.now() - nodeStartTime;
          // NEW: Collect output references (files)
          if (nodeOutput.status === 'executed' && 'outputRef' in nodeOutput && nodeOutput.outputRef) {
            outputRefs[nodeId] = nodeOutput.outputRef;
          }
          // NEW: Populate ExecutionStep and Lineage
          const stepIndex = executionSteps.length;
          const outputsDelta: Record<string, any> = {};
          if (nodeOutput.status === 'executed' && 'varName' in nodeOutput && nodeOutput.varName) {
            outputsDelta[nodeOutput.varName] = nodeOutput.varValue;
            // CRITICAL: Update context variables for subsequent nodes
            context.vars[nodeOutput.varName] = nodeOutput.varValue;
            // Debug logging removed - use logger if needed
            variableLineage[nodeOutput.varName] = {
              variableName: nodeOutput.varName,
              sourceType: mapNodeToSourceType(node.type),
              createdByBlockId: nodeId,
              createdAtStep: stepIndex
            };
          }
          // Track cost metrics
          if (node.type === 'query') {
            context.metrics!.queryCount++;
            // approximating DB time as total node time for now
            context.metrics!.dbTimeMs += nodeDuration;
          } else if (node.type === 'compute') {
            // approximating JS time
            context.metrics!.jsTimeMs += nodeDuration;
          }
          const executionStep: ExecutionStep = {
            stepNumber: stepIndex,
            blockId: nodeId,
            blockType: node.type,
            timestamp: new Date(),
            status: nodeOutput.status as 'executed' | 'skipped' | 'error',
            inputs: {}, // TODO: Capture resolved inputs
            outputs: outputsDelta,
            error: 'error' in nodeOutput ? nodeOutput.error : undefined,
            skippedReason: nodeOutput.skipReason,
            sideEffects: 'sideEffects' in nodeOutput && nodeOutput.sideEffects ? { writes: nodeOutput.sideEffects } : undefined,
            durationMs: nodeDuration,
            metrics: {
              // Per-step metrics
              totalTimeMs: nodeDuration
            }
          };
          executionSteps.push(executionStep);
          // Legacy Trace population (required for tests)
          trace.push({
            nodeId,
            type: node.type,
            status: nodeOutput.status as any,
            outputsDelta: outputsDelta,
            sideEffects: 'sideEffects' in nodeOutput ? nodeOutput.sideEffects : undefined,
            error: 'error' in nodeOutput ? nodeOutput.error : undefined,
            timestamp: new Date(),
            conditionResult: config.condition ? true : undefined
          });
          // Log execution (required for tests)
          if (nodeOutput.status === 'executed') {
            logs.push({
              level: 'info',
              message: `Executed node ${nodeId}`,
              nodeId,
              timestamp: new Date()
            });
          } else if (nodeOutput.status === 'skipped') {
            // Already logged in condition check? Or here?
            // If skipped by executeNode (e.g. internal logic), log here.
            // But my manual condition check logs it earlier.
            // Check duplicates? The set logic relies on string includes.
          }
          // STOP EXECUTION if Final Block is reached
          if (node.type === 'final' && nodeOutput.status === 'executed') {
            logs.push({
              level: 'info',
              message: 'Final Block executed, stopping workflow',
              nodeId: nodeId,
              timestamp: new Date()
            });
            break; // Stop execution
          }
        } catch (error) {
          // ... (error handling) ...
          throw error;
        }
      }
    } finally {
      // Cleanup resources
      if (isolate) {
        isolate.dispose();
      }
    }
    // Log completion
    const duration = Date.now() - startTime;
    // ...
    return {
      status: 'success',
      outputRefs: Object.keys(outputRefs).length > 0 ? outputRefs : undefined,
      logs,
      trace: options.debug ? trace : undefined,
      executionTrace: options.debug ? {
        executionId: `exec-${new Date().toISOString()}`, // TODO: Use real ID
        workflowId: workflowVersion.workflowId,
        workflowVersionId: workflowVersion.id,
        startTime: new Date(startTime),
        endTime: new Date(),
        status: 'success',
        steps: executionSteps,
        variableLineage,
        listLineage: {},
        metrics: {
          totalDurationMs: duration,
          totalDbTimeMs: context.metrics?.dbTimeMs,
          totalJsTimeMs: context.metrics?.jsTimeMs,
          queryCount: context.metrics?.queryCount,
          executionMode: context.executionMode as any
        }
      } : undefined
    };
  } catch (error) {
    // ... (error handling)
    return {
      status: 'error',
      logs,
      trace: options.debug ? trace : undefined,
      error: error instanceof Error ? error.message : 'Unknown error',
    };
  }
}
/**
 * Get execution order for nodes (topological sort)
 */
function getExecutionOrder(graphJson: GraphJson): string[] {
  // Simple execution order: start node first, then follow edges
  if (graphJson.startNodeId) {
    const visited = new Set<string>();
    const order: string[] = [];
    const visit = (nodeId: string): void => {
      if (visited.has(nodeId)) { return; }
      visited.add(nodeId);
      order.push(nodeId);
      // Find outgoing edges
      if (graphJson.edges) {
        const outgoingEdges = graphJson.edges.filter(e => e.source === nodeId);
        for (const edge of outgoingEdges) {
          visit(edge.target);
        }
      }
    };
    visit(graphJson.startNodeId);
    // Add any remaining nodes (shouldn't happen if graph is connected)
    for (const node of graphJson.nodes) {
      if (!visited.has(node.id)) {
        order.push(node.id);
      }
    }
    return order;
  }
  // Fallback: just return nodes in order
  return graphJson.nodes.map(n => n.id);
}
/**
 * Validate workflow graph structure
 *
 * @param graphJson - Workflow graph JSON
 * @returns true if valid, throws error otherwise
 */
export function validateGraphStructure(graphJson: Record<string, any>): boolean {
  // Use new validation
  const result = validateGraph(graphJson as unknown as GraphJson);
  if (!result.valid) {
    const errorMessages = result.errors.map(e => e.message).join('; ');
    throw createError.validation(`Invalid graph structure: ${errorMessages}`);
  }
  return true;
}
function mapNodeToSourceType(nodeType: string): VariableLineage['sourceType'] {
  switch (nodeType) {
    case 'question': return 'question';
    case 'compute': return 'compute';
    case 'query': return 'query';
    case 'write': return 'writeResult';
    case 'http': return 'externalResult';
    default: return 'transform'; // Fallback
  }
}

import { v4 as uuidv4 } from 'uuid';

import type { DatavaultRow } from '@shared/schema';

import { datavaultRowsRepository } from '../../repositories/DatavaultRowsRepository';
import { evaluateExpression } from '../expr';

import type { EvalContext } from '../expr';

// ==========================================
// QUERY NODE
// ==========================================

/** Reusable status literals */
const STATUS_EXECUTED = 'executed';
const STATUS_SKIPPED = 'skipped';
const STATUS_ERROR = 'error';

/** Reusable error message string */
const UNKNOWN_ERROR_MSG = 'Unknown error';

/** Row ID required error messages */
const ROW_ID_REQUIRED_DELETE = 'Row ID required for delete';
const ROW_ID_REQUIRED_UPDATE = 'Row ID required for update';

/** Type for a flat row produced by query operations */
type FlatRow = {
    id: string;
    createdAt: Date | null;
    updatedAt: Date | null;
    [key: string]: unknown;
};

/** Type for preview write entries */
interface PreviewWrite {
    deleted?: boolean;
    data?: Record<string, unknown>;
}

/** Type for preview writes map: tableId -> rowId -> PreviewWrite */
type PreviewWritesMap = Record<string, Record<string, PreviewWrite>>;

export interface QueryNodeConfig {
    tableId: string;
    filters?: Array<{
        columnId: string; // or 'createdAt', 'updatedAt'
        operator: 'eq' | 'neq' | 'gt' | 'lt' | 'contains' | 'in';
        value: string; // Expression
    }>;
    limit?: number;
    outputKey: string; // Variable to store result
    condition?: string;
    singleRow?: boolean; // If true, returns object instead of array
}

export interface QueryNodeInput {
    nodeId: string;
    config: QueryNodeConfig;
    context: EvalContext;
    tenantId: string;
}

export interface QueryNodeOutput {
    status: 'executed' | 'skipped' | 'error';
    varName?: string;
    varValue?: unknown;
    skipReason?: string;
    error?: string;
    sideEffects?: Record<string, unknown>;
}

// eslint-disable-next-line complexity, sonarjs/cognitive-complexity -- Data query with filtering, caching, and preview overlay is inherently complex
export async function executeQueryNode(input: QueryNodeInput): Promise<QueryNodeOutput> {
    const { config, context } = input;

    try {
        if (config.condition !== undefined && config.condition !== null && config.condition !== '' && !evaluateExpression(config.condition, context)) {
            return { status: STATUS_SKIPPED, skipReason: 'condition false' };
        }

        // Optimization: Resolve filter values ONCE before iterating rows
        // This also allows us to build a stable cache key
        const resolvedFilters = config.filters ? config.filters.map(f => ({
            ...f,
            resolvedValue: evaluateExpression(f.value, context)
        })) : [];

        // CACHING LOGIC
        // Generate cache key based on tableId, resolved filters, and limit
        // We include context.executionMode to prevent preview cache leaking to live (though cache is ephemeral per run)
        const cacheKey = JSON.stringify({
            type: 'query',
            tableId: config.tableId,
            filters: resolvedFilters, // contains resolved values
            limit: config.limit,
            singleRow: config.singleRow,
            mode: context.executionMode
        });

        if (context.cache?.queries.has(cacheKey) === true) {
            const cachedResult: unknown = context.cache.queries.get(cacheKey);
            // Store outcome in vars (side effect of execution)
            context.vars[config.outputKey] = cachedResult;
            return {
                status: STATUS_EXECUTED,
                varName: config.outputKey,
                varValue: cachedResult,
                skipReason: 'cached' // Informational
            };
        }

        // 1. Fetch Live Data
        // We use a simplified fetch here. Real impl might need complex filtering repository method.
        // For MVP, we fetch 100 rows and filter in memory if filters are complex, 
        // or rely on repo for basic sorting/pagination.

        // Note: datavaultRowsRepository.getRowsWithValues returns { row, values }
        const rows = await datavaultRowsRepository.getRowsWithValues(config.tableId, {
            limit: 1000,
            showArchived: false,
        });

        // 2. Format as simple objects (combining row metadata + values)
        let flatRows: FlatRow[] = rows.map(r => ({
            id: r.row.id,
            createdAt: r.row.createdAt,
            updatedAt: r.row.updatedAt,
            ...r.values, // columnId -> value
        }));

        // 3. Overlay Preview Writes
        if (context.executionMode === 'preview' && context.writes !== undefined && context.writes !== null) {
            const writes = context.writes as PreviewWritesMap;
            const tableWrites: Record<string, PreviewWrite> = writes[config.tableId] ?? {};

            // Apply updates/creates/deletes
            // tableWrites is Record<rowId, { deleted?: boolean, data?: object }>

            // First, map existing rows by ID for easy access
            const rowMap = new Map<string, FlatRow>(flatRows.map(r => [r.id, r]));

            for (const [rowId, write] of Object.entries(tableWrites)) {
                if (write.deleted === true) {
                    rowMap.delete(rowId);
                } else {
                    // Update or Create
                    const existing: FlatRow = rowMap.get(rowId) ?? { id: rowId, createdAt: new Date(), updatedAt: null };
                    rowMap.set(rowId, { ...existing, ...write.data, updatedAt: new Date() });
                }
            }

            flatRows = Array.from(rowMap.values());
        }

        // 4. Client-side Filtering (Safe for MVP, mirrors DB logic)
        // Uses pre-resolved values for performance (PART 3)
        if (resolvedFilters.length > 0) {
            flatRows = flatRows.filter(row => {
                return resolvedFilters.every(filter => {
                    const rowValue = (row as any)[filter.columnId];
                    const filterValue = filter.resolvedValue;

                    switch (filter.operator) {
                        case 'eq': return rowValue == filterValue;
                        case 'neq': return rowValue != filterValue;
                        case 'gt': return rowValue > filterValue;
                        case 'lt': return rowValue < filterValue;
                        case 'contains': return String(rowValue).includes(String(filterValue));
                        case 'in': return Array.isArray(filterValue) && filterValue.includes(rowValue);
                        default: return true;
                    }
                });
            });
        }

        // 5. Limit and Select
        if (config.limit) {
            flatRows = flatRows.slice(0, config.limit);
        }

        const result = config.singleRow ? (flatRows[0] ?? null) : flatRows;

        // Store outcome
        context.vars[config.outputKey] = result;

        // Populate Cache
        if (context.cache) {
            context.cache.queries.set(cacheKey, result);
        }

        return {
            status: 'executed',
            varName: config.outputKey,
            varValue: result,
        };

    } catch (error) {
        return {
            status: 'error',
            error: error instanceof Error ? error.message : 'Unknown error'
        };
    }
}

// ==========================================
// WRITE NODE
// ==========================================

export interface WriteNodeConfig {
    tableId: string;
    operation: 'create' | 'update' | 'delete';
    rowId?: string; // Expression, required for update/delete
    data?: Record<string, string>; // columnId -> Expression
    outputKey?: string; // Stores resulting Row ID or Object
    condition?: string;
}

export interface WriteNodeInput {
    nodeId: string;
    config: WriteNodeConfig;
    context: EvalContext;
    tenantId: string;
    userInputs?: Record<string, any>; // Added userInputs to interface
}

export type WriteNodeOutput = QueryNodeOutput; // Same structure

export async function executeWriteNode(input: WriteNodeInput): Promise<WriteNodeOutput> {
    const { nodeId, config, context, tenantId, userInputs } = input;

    try {
        // IDEMPOTENCY GUARD (PART 4)
        if (context.executedSideEffects?.has(nodeId)) {
            // Already executed in this run
            // We treat this as a skip to prevent accidental loops or double-execution
            return {
                status: 'skipped',
                skipReason: 'already executed (idempotency guard)'
            };
        }

        if (config.condition) {
            if (!evaluateExpression(config.condition, context)) {
                return { status: 'skipped', skipReason: 'condition false' };
            }
        }

        // Prepare data
        const dataToWrite: Record<string, any> = {};
        if (config.data) {
            for (const [colId, expr] of Object.entries(config.data)) {
                dataToWrite[colId] = evaluateExpression(expr, context);
            }
        }

        // Identify Row ID
        let rowId = config.rowId ? evaluateExpression(config.rowId, context) : undefined;
        if (config.operation === 'create' && !rowId) {
            // Auto-generate ID if needed, though DB usually handles it. 
            // For Preview, we MUST generate it.
            rowId = uuidv4();
        }

        // PREVIEW MODE
        if (context.executionMode === 'preview') {
            context.writes = context.writes || {};
            if (!context.writes[config.tableId]) {
                context.writes[config.tableId] = {};
            }

            const tableWrites = context.writes[config.tableId];

            if (config.operation === 'delete') {
                if (!rowId) { throw new Error('Row ID required for delete'); }
                tableWrites[rowId] = { deleted: true };
            } else if (config.operation === 'update') {
                if (!rowId) { throw new Error('Row ID required for update'); }
                // We merge with existing "live" data logically, but here we just store the delta
                const currentWrite = tableWrites[rowId] || {};
                tableWrites[rowId] = {
                    ...currentWrite,
                    data: { ...(currentWrite.data || {}), ...dataToWrite }
                };
            } else if (config.operation === 'create') {
                // rowId is already generated above for create
                tableWrites[rowId] = {
                    data: { ...dataToWrite, id: rowId }
                };
            }

            // Store result
            if (config.outputKey) {
                context.vars[config.outputKey] = config.operation === 'create' ? { id: rowId, ...dataToWrite } : rowId;
            }

            // MARK EXECUTED
            if (context.executedSideEffects) {
                context.executedSideEffects.add(nodeId);
            }

            return {
                status: 'executed',
                varName: config.outputKey,
                varValue: config.outputKey ? context.vars[config.outputKey] : undefined, // Mirror live return
                sideEffects: {
                    tableId: config.tableId,
                    operation: config.operation,
                    rowId,
                    changes: config.operation === 'delete' ? { deleted: true } : dataToWrite
                }
            };
        }

        // LIVE MODE
        let result: any;

        if (config.operation === 'create') {
            const { row } = await datavaultRowsRepository.createRowWithValues(
                { tableId: config.tableId, tenantId: tenantId as any } as any, // Type cast for MVP
                Object.entries(dataToWrite).map(([k, v]) => ({ columnId: k, value: v }))
            );
            result = row;
            // Re-fetch to get full object with IDs if needed? Usually just ID is enough.
            if (config.outputKey) { context.vars[config.outputKey] = row; }

        } else if (config.operation === 'update') {
            if (!rowId) { throw new Error('Row ID required for update'); }
            await datavaultRowsRepository.updateRowValues(
                rowId,
                Object.entries(dataToWrite).map(([k, v]) => ({ columnId: k, value: v }))
            );
            result = { id: rowId, ...dataToWrite };
            const outKey = config.outputKey;
            if (outKey) { context.vars[outKey] = result; }

        } else if (config.operation === 'delete') {
            if (!rowId) { throw new Error('Row ID required for delete'); }
            await datavaultRowsRepository.deleteRow(rowId);
            result = { id: rowId, deleted: true };
        }

        // MARK EXECUTED
        if (context.executedSideEffects) {
            context.executedSideEffects.add(nodeId);
        }

        return {
            status: 'executed',
            varName: config.outputKey,
            varValue: config.outputKey ? context.vars[config.outputKey] : undefined
        };

    } catch (error) {
        return {
            status: 'error',
            error: error instanceof Error ? error.message : 'Unknown error'
        };
    }
}

/**
 * E-Signature Node Executor
 * Handles e-signature requests for document signing
 *
 * Stage 14: E-Signature Node + Document Review Portal
 */

import { evaluateExpression } from '../expr';

import type { EvalContext } from '../expr';

/**
 * E-Signature Node Configuration
 */
export interface EsignNodeConfig {
  signerType: 'internal' | 'external';
  signerEmailVar: string;              // Variable key holding signer email
  signerNameVar?: string;              // Optional variable key holding signer name
  provider: 'native' | 'docusign' | 'hellosign';
  documentOutputRef?: string;          // Which output ref to send for signing (from template node)
  message?: string;                    // Message for signer
  redirectUrlAfterSign?: string;       // Redirect URL after signing
  expiryHours?: number;                // Token expiry in hours (default 72)
  condition?: string;                  // Optional conditional execution
}

/**
 * E-Signature Node Input
 */
export interface EsignNodeInput {
  nodeId: string;
  config: EsignNodeConfig;
  context: EvalContext;
  runId: string;                       // Run ID for creating signature request
  workflowId: string;                  // Workflow ID
  tenantId: string;                    // Tenant ID
  projectId: string;                   // Project ID
  outputRefs?: Record<string, any>;    // Output refs from previous nodes (for document URL)
}

/**
 * E-Signature Node Output
 */
export interface EsignNodeOutput {
  status: 'executed' | 'skipped' | 'waiting';
  signatureRequestId?: string;         // Created signature request ID
  skipReason?: string;
  error?: string;
}

/**
 * Execute an e-signature node
 *
 * This node creates a signature request and pauses the workflow execution
 * until the document is signed or declined.
 *
 * @param input - Node configuration and execution context
 * @returns Execution result with waiting status
 */
export async function executeEsignNode(
  input: EsignNodeInput
): Promise<EsignNodeOutput> {
  const { nodeId, config, context, runId, workflowId, tenantId, projectId, outputRefs } = input;

  try {
    // Check condition if present
    if (config.condition) {
      const conditionResult = evaluateExpression(config.condition, context);
      if (!conditionResult) {
        return {
          status: 'skipped',
          skipReason: 'condition evaluated to false',
        };
      }
    }

    // Resolve signer email from context
    const signerEmail = context.vars[config.signerEmailVar];
    if (!signerEmail || typeof signerEmail !== 'string') {
      throw new Error(`Invalid or missing signer email in variable '${config.signerEmailVar}'`);
    }

    // Resolve signer name from context (optional)
    let signerName: string | undefined;
    if (config.signerNameVar) {
      const nameValue = context.vars[config.signerNameVar];
      if (nameValue && typeof nameValue === 'string') {
        signerName = nameValue;
      }
    }

    // Resolve document URL from output refs
    let documentUrl: string | undefined;
    if (config.documentOutputRef && outputRefs) {
      // Look for the output ref in the outputRefs object
      // The documentOutputRef is typically a node ID or output key
      const outputValue = outputRefs[config.documentOutputRef];
      if (outputValue) {
        // If it's an object with a url property, use that
        if (typeof outputValue === 'object' && 'url' in outputValue) {
          documentUrl = outputValue.url;
        } else if (typeof outputValue === 'string') {
          documentUrl = outputValue;
        }
      }
    }

    // Calculate expiry timestamp
    const expiryHours = config.expiryHours ?? 72; // Default 72 hours (3 days)
    const expiresAt = new Date(Date.now() + expiryHours * 60 * 60 * 1000);

    // Store signature request info in context for service layer to create
    // The actual database operation will be handled by the service layer
    context.vars['__pendingSignatureRequest'] = {
      nodeId,
      runId,
      workflowId,
      tenantId,
      projectId,
      signerEmail,
      signerName,
      provider: config.provider,
      documentUrl,
      message: config.message,
      redirectUrl: config.redirectUrlAfterSign,
      expiresAt: expiresAt.toISOString(),
    };

    return {
      status: 'waiting',
      // The service layer will create the signature request and return its ID
    };
  } catch (error) {
    return {
      status: 'skipped',
      error: error instanceof Error ? error.message : 'Unknown error',
    };
  }
}

/**
 * HTTP Node Executor
 * Handles HTTP/API requests with authentication, retries, and response mapping
 */
import crypto from 'crypto';

import { logger } from '../../logger';
import { httpCache } from '../../services/cache';
import { resolveConnection as resolveNewConnection, markConnectionUsed } from '../../services/connections';
import { resolveConnection as resolveOldConnection } from '../../services/externalConnections';
import { getOAuth2Token } from '../../services/oauth2';
import { getSecretValue } from '../../services/secrets';
import { select } from '../../utils/jsonselect';
import { evaluateExpression } from '../expr';

import type { EvalContext } from '../expr';
/**
 * HTTP Node Configuration
 */
export interface HttpNodeConfig {
  // Connection settings
  connectionId?: string;              // Optional reference to ExternalConnection
  baseUrl?: string;                   // Required if no connectionId
  path: string;                       // URL path (supports {{var}} templates)
  method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
  // Request configuration
  query?: Record<string, any>;        // Query parameters (supports {{var}} templates)
  headers?: Record<string, string>;   // Headers (supports {{var}} templates)
  body?: any;                         // Request body (JSON only for MVP)
  // Authentication
  auth?: {
    type: 'api_key' | 'bearer' | 'oauth2' | 'basic_auth' | 'none';
    location?: 'header' | 'query';   // For api_key
    keyName?: string;                 // Header/query param name for api_key
    secretRef?: string;               // Secret key for api_key/basic_auth
    tokenRef?: string;                // Secret key for bearer
    oauth2?: {
      tokenUrl: string;
      clientIdRef: string;            // Secret key for OAuth2 client ID
      clientSecretRef: string;        // Secret key for OAuth2 client secret
      scope?: string;
    };
  };
  // Retry and timeout configuration
  timeoutMs?: number;                 // Request timeout (default 8000ms)
  retries?: number;                   // Number of retries (default 2)
  backoffMs?: number;                 // Initial backoff delay (default 250ms)
  // Caching
  cacheTtlMs?: number;                // Optional cache TTL in milliseconds
  // Response mapping
  map: Array<{
    as: string;                       // Output variable name
    select: string;                   // JSONPath selector (e.g., $.data.user.id)
  }>;
  // Conditional execution
  condition?: string;                 // Optional condition expression
}
export interface HttpNodeInput {
  nodeId: string;
  config: HttpNodeConfig;
  context: EvalContext;
  projectId: string;                  // For secret/connection resolution
}
export interface HttpNodeOutput {
  status: 'executed' | 'skipped' | 'error';
  variables?: Record<string, any>;    // Mapped variables
  response?: {
    status: number;
    headers: Record<string, string>;
    data: any;
    cached: boolean;
  };
  skipReason?: string;
  error?: string;
  durationMs?: number;
}
/**
 * Execute an HTTP node
 */
export async function executeHttpNode(input: HttpNodeInput): Promise<HttpNodeOutput> {
  const { nodeId, config, context, projectId } = input;
  const startTime = Date.now();
  try {
    // IDEMPOTENCY GUARD
    if (context.executedSideEffects?.has(nodeId)) {
      return {
        status: 'skipped',
        skipReason: 'already executed (idempotency guard)',
        durationMs: 0
      };
    }
    // Check condition if present
    if (config.condition) {
      const conditionResult = evaluateExpression(config.condition, context);
      if (!conditionResult) {
        return {
          status: 'skipped',
          skipReason: 'condition evaluated to false',
        };
      }
    }
    // Resolve connection or use direct config
    const requestConfig = await resolveRequestConfig(config, projectId);
    // Build the full URL
    const url = buildUrl(requestConfig.baseUrl, config.path, config.query, context);
    // Resolve headers
    const headers = await resolveHeaders(requestConfig, config, context, projectId);
    // Resolve body
    const body = config.body ? interpolateTemplate(JSON.stringify(config.body), context) : undefined;
    // Check cache if enabled
    if (config.cacheTtlMs && config.method === 'GET') {
      const cacheKey = generateCacheKey(projectId, config.method, url, body);
      const cached = httpCache.get(cacheKey);
      if (cached) {
        // Map response to variables
        const variables = mapResponse(cached.data, config.map);
        for (const [key, value] of Object.entries(variables)) {
          context.vars[key] = value;
        }
        return {
          status: 'executed',
          variables,
          response: {
            status: cached.status,
            headers: cached.headers,
            data: cached.data,
            cached: true,
          },
          durationMs: Date.now() - startTime,
        };
      }
    }
    // Mock requests in preview mode
    if (context.executionMode === 'preview') {
      // Mock response
      const mockResponse = {
        status: 200,
        headers: {},
        data: { message: 'Mocked response in preview mode' },
        cached: false,
      };
      // Map mock response to variables
      const variables = mapResponse(mockResponse.data, config.map);
      for (const [key, value] of Object.entries(variables)) {
        context.vars[key] = value;
      }
      logger.info({
        url,
        method: config.method,
        body,
        headers,
      }, 'External send skipped in preview mode');
      return {
        status: 'executed',
        variables,
        response: mockResponse,
        skipReason: 'Preview mode - external send mocked',
        durationMs: 0,
      };
    }
    // Execute HTTP request with retries
    const response = await executeWithRetries({
      url,
      method: config.method,
      headers,
      body: body ? JSON.parse(body) : undefined,
      timeoutMs: config.timeoutMs ?? 8000,
      retries: config.retries ?? 2,
      backoffMs: config.backoffMs ?? 250,
    });
    // Cache response if enabled
    if (config.cacheTtlMs && config.method === 'GET') {
      const cacheKey = generateCacheKey(projectId, config.method, url, body);
      httpCache.set(cacheKey, response, config.cacheTtlMs);
    }
    // Map response to variables
    const variables = mapResponse(response.data, config.map);
    for (const [key, value] of Object.entries(variables)) {
      context.vars[key] = value;
    }
    // MARK EXECUTED
    if (context.executedSideEffects) {
      context.executedSideEffects.add(nodeId);
    }
    return {
      status: 'executed',
      variables,
      response: {
        status: response.status,
        headers: response.headers,
        data: response.data,
        cached: false,
      },
      durationMs: Date.now() - startTime,
    };
  } catch (error) {
    return {
      status: 'error',
      error: error instanceof Error ? error.message : 'Unknown error',
      durationMs: Date.now() - startTime,
    };
  }
}
/**
 * Resolve request configuration from connection or direct config
 * Tries new connections service first (Stage 16), then falls back to old externalConnections (Stage 9)
 */
async function resolveRequestConfig(
  config: HttpNodeConfig,
  projectId: string
): Promise<{
  baseUrl: string;
  auth?: HttpNodeConfig['auth'];
  defaultHeaders: Record<string, string>;
  timeoutMs: number;
  retries: number;
  backoffMs: number;
  accessToken?: string; // For OAuth2 3-legged flow
  connectionId?: string; // For marking as used
}> {
  if (config.connectionId) {
    // Try new connections service first (Stage 16)
    try {
      const resolved = await resolveNewConnection(projectId, config.connectionId);
      const connection = resolved.connection;
      // Mark connection as used
      markConnectionUsed(config.connectionId).catch(err => {
        logger.error({ err, connectionId: config.connectionId }, 'Failed to mark connection as used');
      });
      // Build auth config based on connection type
      let auth: HttpNodeConfig['auth'] | undefined;
      if (connection.type === 'api_key') {
        auth = {
          type: 'api_key',
          location: connection.authConfig.apiKeyLocation || 'header',
          keyName: connection.authConfig.apiKeyName || 'X-API-Key',
          secretRef: resolved.secrets[connection.authConfig.apiKeyRef || 'apiKey'],
        };
      } else if (connection.type === 'bearer') {
        auth = {
          type: 'bearer',
          tokenRef: resolved.secrets[connection.authConfig.tokenRef || 'token'],
        };
      } else if (connection.type === 'oauth2_client_credentials') {
        auth = {
          type: 'oauth2',
          oauth2: {
            tokenUrl: connection.authConfig.tokenUrl,
            clientIdRef: resolved.secrets[connection.authConfig.clientIdRef],
            clientSecretRef: resolved.secrets[connection.authConfig.clientSecretRef],
            scope: connection.authConfig.scope,
          },
        };
      } else if (connection.type === 'oauth2_3leg') {
        // For 3-legged OAuth, use the access token directly
        auth = {
          type: 'bearer',
          tokenRef: resolved.accessToken ?? '',
        };
      }
      return {
        baseUrl: connection.baseUrl ?? '',
        auth,
        defaultHeaders: connection.defaultHeaders || {},
        timeoutMs: connection.timeoutMs,
        retries: connection.retries,
        backoffMs: connection.backoffMs,
        accessToken: resolved.accessToken,
        connectionId: config.connectionId,
      };
    } catch (error) {
      logger.info({
        connectionId: config.connectionId,
        error: (error as Error).message,
      }, 'New connection not found, trying old externalConnection');
      // Fall back to old externalConnections service
      const connection = await resolveOldConnection(projectId, config.connectionId);
      if (!connection) {
        throw new Error(`Connection not found: ${config.connectionId}`);
      }
      return {
        baseUrl: connection.baseUrl,
        auth: {
          type: connection.authType as any,
          secretRef: connection.secretValue,
        },
        defaultHeaders: connection.defaultHeaders,
        timeoutMs: connection.timeoutMs,
        retries: connection.retries,
        backoffMs: connection.backoffMs,
      };
    }
  }
  if (!config.baseUrl) {
    throw new Error('baseUrl is required when connectionId is not provided');
  }
  return {
    baseUrl: config.baseUrl,
    auth: config.auth,
    defaultHeaders: {},
    timeoutMs: config.timeoutMs ?? 8000,
    retries: config.retries ?? 2,
    backoffMs: config.backoffMs ?? 250,
  };
}
/**
 * Resolve and build headers with authentication
 */
async function resolveHeaders(
  requestConfig: Awaited<ReturnType<typeof resolveRequestConfig>>,
  config: HttpNodeConfig,
  context: EvalContext,
  projectId: string
): Promise<Record<string, string>> {
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    'Accept': 'application/json',
    ...requestConfig.defaultHeaders,
    ...config.headers,
  };
  // Interpolate template variables in headers
  for (const [key, value] of Object.entries(headers)) {
    headers[key] = interpolateTemplate(value, context);
  }
  // Apply authentication
  const auth = config.auth || requestConfig.auth;
  if (auth && auth.type !== 'none') {
    switch (auth.type) {
      case 'api_key':
        if (auth.location === 'header' && auth.keyName && auth.secretRef) {
          const secret = await getSecretValue(projectId, auth.secretRef);
          if (secret) {
            headers[auth.keyName] = secret;
          }
        }
        break;
      case 'bearer':
        if (auth.tokenRef) {
          const token = await getSecretValue(projectId, auth.tokenRef);
          if (token) {
            headers['Authorization'] = `Bearer ${token}`;
          }
        }
        break;
      case 'oauth2':
        if (auth.oauth2) {
          const clientId = await getSecretValue(projectId, auth.oauth2.clientIdRef);
          const clientSecret = await getSecretValue(projectId, auth.oauth2.clientSecretRef);
          if (clientId && clientSecret) {
            const tokenResponse = await getOAuth2Token({
              tokenUrl: auth.oauth2.tokenUrl,
              clientId,
              clientSecret,
              scope: auth.oauth2.scope,
              projectId,
            });
            headers['Authorization'] = `${tokenResponse.token_type} ${tokenResponse.access_token}`;
          }
        }
        break;
      case 'basic_auth':
        if (auth.secretRef) {
          const credentials = await getSecretValue(projectId, auth.secretRef);
          if (credentials) {
            // Expect format: "username:password"
            const encoded = Buffer.from(credentials).toString('base64');
            headers['Authorization'] = `Basic ${encoded}`;
          }
        }
        break;
    }
  }
  return headers;
}
/**
 * Build full URL with query parameters
 */
function buildUrl(
  baseUrl: string,
  path: string,
  query: Record<string, any> | undefined,
  context: EvalContext
): string {
  // Interpolate templates in path
  const interpolatedPath = interpolateTemplate(path, context);
  // Build base URL
  let url = baseUrl;
  if (!url.endsWith('/') && !interpolatedPath.startsWith('/')) {
    url += '/';
  }
  url += interpolatedPath;
  // Add query parameters
  if (query && Object.keys(query).length > 0) {
    const params = new URLSearchParams();
    for (const [key, value] of Object.entries(query)) {
      const interpolatedValue = interpolateTemplate(String(value), context);
      params.append(key, interpolatedValue);
    }
    url += `?${  params.toString()}`;
  }
  return url;
}
/**
 * Interpolate {{var}} templates in a string
 */
function interpolateTemplate(template: string, context: EvalContext): string {
  return template.replace(/\{\{(\w+)\}\}/g, (match, varName) => {
    const value = context.vars[varName];
    return value !== undefined ? String(value) : match;
  });
}
/**
 * Execute HTTP request with retries and exponential backoff
 */
async function executeWithRetries(config: {
  url: string;
  method: string;
  headers: Record<string, string>;
  body?: any;
  timeoutMs: number;
  retries: number;
  backoffMs: number;
}): Promise<{ status: number; headers: Record<string, string>; data: any }> {
  let lastError: Error | null = null;
  for (let attempt = 0; attempt <= config.retries; attempt++) {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), config.timeoutMs);
      const response = await fetch(config.url, {
        method: config.method,
        headers: config.headers,
        body: config.body ? JSON.stringify(config.body) : undefined,
        signal: controller.signal,
      });
      clearTimeout(timeoutId);
      // Parse response
      const text = await response.text();
      let data: any;
      try {
        data = text ? JSON.parse(text) : null;
      } catch {
        data = text;
      }
      // Extract headers
      const headers: Record<string, string> = {};
      response.headers.forEach((value, key) => {
        headers[key] = value;
      });
      // Check for HTTP errors
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }
      return { status: response.status, headers, data };
    } catch (error) {
      lastError = error instanceof Error ? error : new Error('Unknown error');
      // Don't retry on certain errors
      if (lastError.message.includes('HTTP 4')) {
        // Client errors (4xx) shouldn't be retried
        throw lastError;
      }
      // Exponential backoff
      if (attempt < config.retries) {
        const delay = config.backoffMs * Math.pow(2, attempt);
        await new Promise(resolve => setTimeout(resolve, delay));
      }
    }
  }
  throw lastError || new Error('Request failed after retries');
}
/**
 * Map response data to variables using JSONPath selectors
 */
function mapResponse(data: any, mappings: Array<{ as: string; select: string }>): Record<string, any> {
  const variables: Record<string, any> = {};
  for (const mapping of mappings) {
    try {
      const value = select(data, mapping.select);
      variables[mapping.as] = value;
    } catch (error) {
      logger.warn({ error, select: mapping.select, as: mapping.as }, `Failed to map ${mapping.select} to ${mapping.as}`);
      variables[mapping.as] = undefined;
    }
  }
  return variables;
}
/**
 * Generate a cache key for HTTP responses
 */
function generateCacheKey(projectId: string, method: string, url: string, body?: string): string {
  const bodyHash = body ? crypto.createHash('sha256').update(body).digest('hex') : 'nobody';
  return `${projectId}:${method}:${url}:${bodyHash}`;
}

import { evaluateExpression } from '../expr';

import type { EvalContext } from '../expr';

/**
 * Question Node Executor
 * Handles question nodes that capture user input
 */

export interface QuestionNodeConfig {
  key: string;                     // Variable name to store answer
  questionText: string;            // Question prompt
  questionType: 'text' | 'number' | 'boolean' | 'select' | 'multiselect';
  required?: boolean;
  options?: Array<{ value: any; label: string }>;
  validation?: {
    min?: number;
    max?: number;
    pattern?: string;
  };
  condition?: string;              // Optional conditional execution
  skipBehavior?: 'skip' | 'hide' | 'disable';
}

export interface QuestionNodeInput {
  nodeId: string;
  config: QuestionNodeConfig;
  context: EvalContext;
  userAnswer?: any;                // Pre-provided answer (for batch execution)
}

export interface QuestionNodeOutput {
  status: 'executed' | 'skipped';
  varName?: string;                // Variable name that was set
  varValue?: any;                  // Value that was set
  skipReason?: string;
}

/**
 * Execute a question node
 *
 * @param input - Node configuration and execution context
 * @returns Execution result
 */
export async function executeQuestionNode(
  input: QuestionNodeInput
): Promise<QuestionNodeOutput> {
  const { nodeId, config, context, userAnswer } = input;

  try {
    // Check condition if present
    if (config.condition) {
      const conditionResult = evaluateExpression(config.condition, context);
      if (!conditionResult) {
        return {
          status: 'skipped',
          skipReason: 'condition evaluated to false',
        };
      }
    }

    // Validate answer if provided
    if (userAnswer !== undefined) {
      validateAnswer(config, userAnswer);
    }

    // In a real implementation, if userAnswer is not provided,
    // we would need to prompt the user interactively.
    // For now, we assume answers are provided upfront.
    const value = userAnswer;

    // Check required
    if (config.required && (value === undefined || value === null || value === '')) {
      throw new Error(`Question '${config.key}' is required but no answer provided`);
    }

    // Store in context
    context.vars[config.key] = value;
    console.error(`[DEBUG Question] Node ${nodeId} executed. Key: ${config.key}, Value: ${value}. Context keys: ${Object.keys(context.vars).length}`);

    return {
      status: 'executed',
      varName: config.key,
      varValue: value,
    };
  } catch (error) {
    throw new Error(
      `Question node ${nodeId} failed: ${error instanceof Error ? error.message : 'unknown error'}`
    );
  }
}

/**
 * Validate an answer against question configuration
 */
function validateAnswer(config: QuestionNodeConfig, answer: any): void {
  // Type validation
  switch (config.questionType) {
    case 'number':
      if (typeof answer !== 'number') {
        throw new Error(`Expected number for '${config.key}', got ${typeof answer}`);
      }
      if (config.validation?.min !== undefined && answer < config.validation.min) {
        throw new Error(`Value for '${config.key}' must be >= ${config.validation.min}`);
      }
      if (config.validation?.max !== undefined && answer > config.validation.max) {
        throw new Error(`Value for '${config.key}' must be <= ${config.validation.max}`);
      }
      break;

    case 'boolean':
      if (typeof answer !== 'boolean') {
        throw new Error(`Expected boolean for '${config.key}', got ${typeof answer}`);
      }
      break;

    case 'select':
      if (config.options) {
        const validValues = config.options.map(opt => opt.value);
        if (!validValues.includes(answer)) {
          throw new Error(
            `Invalid value for '${config.key}': ${answer}. Must be one of: ${validValues.join(', ')}`
          );
        }
      }
      break;

    case 'multiselect':
      if (!Array.isArray(answer)) {
        throw new Error(`Expected array for '${config.key}', got ${typeof answer}`);
      }
      if (config.options) {
        const validValues = config.options.map(opt => opt.value);
        for (const val of answer) {
          if (!validValues.includes(val)) {
            throw new Error(
              `Invalid value in '${config.key}': ${val}. Must be one of: ${validValues.join(', ')}`
            );
          }
        }
      }
      break;

    case 'text':
      if (typeof answer !== 'string') {
        throw new Error(`Expected string for '${config.key}', got ${typeof answer}`);
      }
      if (config.validation?.pattern) {
        const regex = new RegExp(config.validation.pattern);
        if (!regex.test(answer)) {
          throw new Error(`Value for '${config.key}' does not match required pattern`);
        }
      }
      break;
  }
}

import fs from 'fs/promises';
import path from 'path';

import { eq, and } from 'drizzle-orm';

import * as schema from '@shared/schema';

import { db } from '../../db';
import { logger } from '../../logger';
import { pdfService } from '../../services/document/PdfService';
import { renderDocx2 } from '../../services/docxRenderer2';
import { renderTemplate , getTemplateFilePath } from '../../services/templates';
import { evaluateExpression } from '../expr';

import type { EvalContext } from '../expr';
/**
 * Template Node Executor (Stage 21 - Multi-Template Support)
 * Handles document generation from templates with support for:
 * - Direct templateId (backward compatible)
 * - Template key resolution via workflowTemplates mapping (new)
 * - Enhanced DOCX rendering with loops/conditionals/helpers
 * - Output tracking in runOutputs table
 */
export interface TemplateNodeConfig {
  templateId?: string;             // Direct reference to template (legacy)
  templateKey?: string;            // Key to resolve from workflowTemplates mapping (new)
  bindings: Record<string, string>; // Map of template placeholders to expressions
  outputName?: string;             // Optional output file name
  condition?: string;              // Optional conditional execution
  skipBehavior?: 'skip' | 'hide' | 'disable';
  toPdf?: boolean;                 // Generate PDF version (Stage 21)
  engine?: 'legacy' | 'v2';        // Which rendering engine to use (default: v2)
}
export interface TemplateNodeInput {
  nodeId: string;
  config: TemplateNodeConfig;
  context: EvalContext;
  tenantId: string;
  runId?: string;                  // Run ID for output tracking (Stage 21)
  workflowVersionId?: string;      // Workflow version for template key resolution (Stage 21)
}
export interface TemplateNodeOutput {
  status: 'executed' | 'skipped';
  outputRef?: {
    fileRef: string;
    pdfRef?: string;
    format: string;
    size?: number;
  };
  bindings?: Record<string, any>;  // Resolved binding values
  skipReason?: string;
  error?: string;
}
/**
 * Execute a template node (Stage 21 - Multi-Template Support)
 *
 * @param input - Node configuration and execution context
 * @returns Execution result
 */
export async function executeTemplateNode(
  input: TemplateNodeInput
): Promise<TemplateNodeOutput> {
  const { nodeId, config, context, tenantId, runId, workflowVersionId } = input;
  try {
    // Check condition if present
    if (config.condition) {
      const conditionResult = evaluateExpression(config.condition, context);
      if (!conditionResult) {
        return {
          status: 'skipped',
          skipReason: 'condition evaluated to false',
        };
      }
    }
    // Resolve bindings by evaluating expressions
    const resolvedBindings: Record<string, any> = {};
    for (const [placeholder, expression] of Object.entries(config.bindings)) {
      try {
        resolvedBindings[placeholder] = evaluateExpression(expression, context);
      } catch (error) {
        throw new Error(
          `Failed to resolve binding '${placeholder}': ${error instanceof Error ? error.message : 'unknown error'}`
        );
      }
    }
    // Resolve template: either by templateKey (new) or templateId (legacy)
    let template: any;
    let templateKey: string | undefined;
    if (config.templateKey && workflowVersionId) {
      // New path: resolve template from workflowTemplates mapping
      templateKey = config.templateKey;
      const mapping = await db.query.workflowTemplates.findFirst({
        where: and(
          eq(schema.workflowTemplates.workflowVersionId, workflowVersionId),
          eq(schema.workflowTemplates.key, config.templateKey)
        ),
        with: {
          template: {
            with: {
              project: true,
            },
          },
        },
      });
      if (!mapping) {
        throw new Error(
          `Template with key '${config.templateKey}' not found in workflow version ${workflowVersionId}`
        );
      }
      template = mapping.template;
    } else if (config.templateId) {
      // Legacy path: direct templateId lookup
      template = await db.query.templates.findFirst({
        where: eq(schema.templates.id, config.templateId),
        with: {
          project: true,
        },
      });
      if (!template) {
        throw new Error(`Template ${config.templateId} not found`);
      }
    } else {
      throw new Error(
        'Template node must specify either templateKey (with workflowVersionId) or templateId'
      );
    }
    // Verify tenant access
    if (template.project.tenantId !== tenantId) {
      throw new Error(`Access denied to template ${template.id}`);
    }
    // Choose rendering engine (default to v2)
    const engine = config.engine || 'v2';
    const toPdf = config.toPdf ?? false;
    let result: { fileRef: string; pdfRef?: string; size: number; format: string };
    if (template.type === 'pdf') {
      // Stage 22: PDF Form Filling
      const templatePath = getTemplateFilePath(template.fileRef);
      const fileBuffer = await fs.readFile(templatePath);
      // Resolve mappings
      const pdfData: Record<string, string> = {};
      const mapping = (template.mapping as Record<string, string>) || {};
      for (const [field, variable] of Object.entries(mapping)) {
        try {
          // Resolve value. If it's a direct variable name or simple expression, evaluate it.
          // We assume the stored mapping is an expression or variable path.
          const val = evaluateExpression(variable, context);
          if (val !== undefined && val !== null) {
            pdfData[field] = String(val);
          }
        } catch (e) {
          logger.warn({ field, variable, error: e }, "Failed to resolve PDF mapping");
        }
      }
      const filledBuffer = await pdfService.fillPdf(fileBuffer, pdfData);
      // Save output
      const outputName = config.outputName
        ? (config.outputName.endsWith('.pdf') ? config.outputName : `${config.outputName}.pdf`)
        : `output-${nodeId}-${Date.now()}.pdf`;
      const outputDir = path.join(process.cwd(), 'server', 'files', 'outputs');
      await fs.mkdir(outputDir, { recursive: true });
      const outputPath = path.join(outputDir, outputName);
      await fs.writeFile(outputPath, filledBuffer);
      result = {
        fileRef: outputName,
        pdfRef: outputName,
        size: filledBuffer.length,
        format: 'pdf'
      };
    } else if (engine === 'v2') {
      // Use new docxRenderer2 with loops, conditionals, helpers
      const templatePath = getTemplateFilePath(template.fileRef);
      const outputDir = path.join(process.cwd(), 'server', 'files', 'outputs');
      // Ensure output directory exists
      await fs.mkdir(outputDir, { recursive: true });
      const renderResult = await renderDocx2({
        templatePath,
        data: resolvedBindings,
        outputDir,
        outputName: config.outputName,
        toPdf,
      });
      result = {
        fileRef: path.basename(renderResult.docxPath),
        pdfRef: renderResult.pdfPath ? path.basename(renderResult.pdfPath) : undefined,
        size: renderResult.size,
        format: 'docx',
      };
    } else {
      // Legacy rendering engine
      result = await renderTemplate(template.fileRef, resolvedBindings, {
        outputName: config.outputName,
        toPdf,
      });
    }
    // Store output in runOutputs table if runId is provided
    if (runId && workflowVersionId) {
      const fileType = toPdf && result.pdfRef ? 'pdf' : 'docx';
      const storagePath = toPdf && result.pdfRef ? result.pdfRef : result.fileRef;
      await db.insert(schema.runOutputs).values({
        runId,
        workflowVersionId,
        templateKey: templateKey || 'default',
        fileType,
        storagePath,
        status: 'ready',
      });
    }
    return {
      status: 'executed',
      outputRef: {
        fileRef: result.fileRef,
        pdfRef: result.pdfRef,
        format: result.format,
        size: result.size,
      },
      bindings: resolvedBindings,
    };
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'unknown error';
    // Store failed output in runOutputs table if runId is provided
    if (runId && workflowVersionId) {
      await db.insert(schema.runOutputs).values({
        runId,
        workflowVersionId,
        templateKey: config.templateKey || 'default',
        fileType: config.toPdf ? 'pdf' : 'docx',
        storagePath: '',
        status: 'failed',
        error: errorMessage,
      });
    }
    // Return error status instead of throwing
    // This allows the workflow to continue and log the error
    return {
      status: 'executed', // Mark as executed even on error
      error: errorMessage,
      bindings: {},
    };
  }
}
