/**
 * Webhook Node Executor
 * Sends outbound HTTP requests for workflow events (fire-and-forget or blocking)
 */

import { logger } from '../../logger';
import { resolveConnection as resolveNewConnection } from '../../services/connections';
import { redactObject } from '../../utils/encryption';
import { evaluateExpression } from '../expr';

import type { EvalContext } from '../expr';

/**
 * Webhook Node Configuration
 */
export interface WebhookNodeConfig {
  // Connection settings
  connectionId?: string;              // Optional reference to Connection
  url?: string;                       // Required if no connectionId
  method: 'POST' | 'PUT' | 'PATCH';   // Webhook methods (no GET/DELETE)

  // Request configuration
  headers?: Record<string, string>;   // Headers (supports {{var}} templates)
  body?: any;                         // Request body (JSON, supports {{var}} templates)

  // Behavior
  mode?: 'fire-and-forget' | 'blocking'; // Default: blocking
  retryPolicy?: {
    attempts?: number;                // Number of retries (default 3)
    backoffMs?: number;               // Initial backoff delay (default 1000ms)
  };

  // Conditional execution
  condition?: string;                 // Optional condition expression
}

export interface WebhookNodeInput {
  nodeId: string;
  config: WebhookNodeConfig;
  context: EvalContext;
  projectId?: string;                 // For connection resolution
}

export interface WebhookNodeOutput {
  status: 'executed' | 'skipped' | 'error';
  statusCode?: number;
  responseBody?: string;              // Limited to 512 bytes
  skipReason?: string;
  error?: string;
  durationMs?: number;
}

/**
 * Interpolate template variables in a string
 */
function interpolateTemplate(template: string, context: EvalContext): string {
  return template.replace(/\{\{([^}]+)\}\}/g, (_, key) => {
    const value = context.vars[key.trim()];
    return value !== undefined ? String(value) : '';
  });
}

/**
 * Interpolate template variables in an object (recursively)
 */
function interpolateObject(obj: any, context: EvalContext): any {
  if (typeof obj === 'string') {
    return interpolateTemplate(obj, context);
  } else if (Array.isArray(obj)) {
    return obj.map(item => interpolateObject(item, context));
  } else if (obj && typeof obj === 'object') {
    const result: any = {};
    for (const [key, value] of Object.entries(obj)) {
      result[key] = interpolateObject(value, context);
    }
    return result;
  }
  return obj;
}

/**
 * Execute webhook request with retries
 */
async function executeWebhookWithRetries(params: {
  url: string;
  method: string;
  headers: Record<string, string>;
  body: any;
  attempts: number;
  backoffMs: number;
}): Promise<{ statusCode: number; responseBody: string }> {
  const { url, method, headers, body, attempts, backoffMs } = params;
  let lastError: Error | null = null;

  for (let attempt = 0; attempt < attempts; attempt++) {
    try {
      const response = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
          ...headers,
        },
        body: JSON.stringify(body),
        signal: AbortSignal.timeout(10000), // 10 second timeout
      });

      // Read response body (limit to 512 bytes)
      const responseText = await response.text();
      const limitedBody = responseText.substring(0, 512);

      return {
        statusCode: response.status,
        responseBody: limitedBody,
      };
    } catch (error) {
      lastError = error as Error;

      // If not the last attempt, wait before retrying
      if (attempt < attempts - 1) {
        const delay = backoffMs * Math.pow(2, attempt);
        await new Promise(resolve => setTimeout(resolve, delay));
      }
    }
  }

  throw lastError || new Error('Webhook request failed');
}

/**
 * Execute a webhook node
 */
export async function executeWebhookNode(input: WebhookNodeInput): Promise<WebhookNodeOutput> {
  const { nodeId, config, context, projectId } = input;
  const startTime = Date.now();

  try {
    // IDEMPOTENCY GUARD
    if (context.executedSideEffects?.has(nodeId)) {
      return {
        status: 'skipped',
        skipReason: 'already executed (idempotency guard)',
        durationMs: 0
      };
    }

    // Check condition if present
    if (config.condition) {
      const conditionResult = evaluateExpression(config.condition, context);
      if (!conditionResult) {
        return {
          status: 'skipped',
          skipReason: 'condition evaluated to false',
        };
      }
    }

    // Resolve URL and headers
    let url = config.url ?? '';
    let headers: Record<string, string> = { ...(config.headers || {}) };
    let body = config.body || {};

    // If connectionId is provided, resolve connection
    if (config.connectionId && projectId) {
      try {
        const resolved = await resolveNewConnection(projectId, config.connectionId);
        const connection = resolved.connection;

        // Use connection's baseUrl if no URL provided
        if (!url && connection.baseUrl) {
          url = connection.baseUrl;
        }

        // Merge connection's default headers
        headers = {
          ...connection.defaultHeaders,
          ...headers,
        };

        // Inject auth based on connection type
        if (connection.type === 'api_key') {
          const apiKeyLocation = connection.authConfig.apiKeyLocation || 'header';
          const apiKeyName = connection.authConfig.apiKeyName || 'X-API-Key';
          const apiKey = resolved.secrets[connection.authConfig.apiKeyRef || 'apiKey'];

          if (apiKeyLocation === 'header') {
            headers[apiKeyName] = apiKey;
          }
        } else if (connection.type === 'bearer') {
          const token = resolved.secrets[connection.authConfig.tokenRef || 'token'];
          headers['Authorization'] = `Bearer ${token}`;
        } else if (connection.type === 'oauth2_client_credentials' || connection.type === 'oauth2_3leg') {
          if (resolved.accessToken) {
            headers['Authorization'] = `Bearer ${resolved.accessToken}`;
          }
        }
      } catch (error) {
        logger.error({
          nodeId,
          connectionId: config.connectionId,
          error: (error as Error).message,
        }, 'Failed to resolve connection for webhook');
        return {
          status: 'error',
          error: `Failed to resolve connection: ${(error as Error).message}`,
          durationMs: Date.now() - startTime,
        };
      }
    }

    // Validate URL
    if (!url) {
      return {
        status: 'error',
        error: 'No URL provided (set url or connectionId)',
        durationMs: Date.now() - startTime,
      };
    }

    // Interpolate templates
    url = interpolateTemplate(url, context);
    headers = interpolateObject(headers, context);
    body = interpolateObject(body, context);

    // Redact sensitive headers in logs
    const safeHeaders = redactObject(headers);
    logger.info({
      nodeId,
      url: redactObject({ url }).url,
      method: config.method,
      headers: safeHeaders,
    }, 'Executing webhook');

    // Execute webhook
    const mode = config.mode || 'blocking';
    const attempts = config.retryPolicy?.attempts || 3;
    const backoffMs = config.retryPolicy?.backoffMs || 1000;

    if (mode === 'fire-and-forget') {
      // Fire and forget - don't wait for response
      executeWebhookWithRetries({
        url,
        method: config.method,
        headers,
        body,
        attempts,
        backoffMs,
      }).catch(error => {
        logger.error({
          nodeId,
          error: (error as Error).message,
        }, 'Webhook fire-and-forget failed');
      });

      // MARK EXECUTED (Fire-and-forget)
      if (context.executedSideEffects) {
        context.executedSideEffects.add(nodeId);
      }

      return {
        status: 'executed',
        durationMs: Date.now() - startTime,
      };
    } else {
      // Blocking mode - wait for response
      const result = await executeWebhookWithRetries({
        url,
        method: config.method,
        headers,
        body,
        attempts,
        backoffMs,
      });

      // MARK EXECUTED (Blocking)
      if (context.executedSideEffects) {
        context.executedSideEffects.add(nodeId);
      }

      return {
        status: 'executed',
        statusCode: result.statusCode,
        responseBody: result.responseBody,
        durationMs: Date.now() - startTime,
      };
    }
  } catch (error) {
    logger.error({
      nodeId,
      error: (error as Error).message,
    }, 'Webhook node execution error');

    return {
      status: 'error',
      error: (error as Error).message,
      durationMs: Date.now() - startTime,
    };
  }
}

import { validateExpression } from './expr';

import type { BranchNodeConfig } from './nodes/branch';
import type { ComputeNodeConfig } from './nodes/compute';
import type { QuestionNodeConfig } from './nodes/question';
import type { TemplateNodeConfig } from './nodes/template';
import type { Node } from './registry';

/**
 * Static Graph and Expression Validation
 * Validates workflow graphs and expressions before execution
 */

export interface GraphJson {
  nodes: Node[];
  edges?: Array<{
    id: string;
    source: string;
    target: string;
  }>;
  startNodeId?: string;
}

export interface ValidationError {
  nodeId?: string;
  field?: string;
  message: string;
  path?: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

/**
 * Validate entire workflow graph
 *
 * @param graphJson - Workflow graph structure
 * @returns Validation result
 */
export function validateGraph(graphJson: GraphJson): ValidationResult {
  const errors: ValidationError[] = [];

  // Check basic structure
  if (!graphJson || typeof graphJson !== 'object') {
    return {
      valid: false,
      errors: [{ message: 'Graph must be an object' }],
    };
  }

  if (!Array.isArray(graphJson.nodes)) {
    return {
      valid: false,
      errors: [{ message: 'Graph must have a nodes array' }],
    };
  }

  // if (graphJson.nodes.length === 0) {
  //   return {
  //     valid: false,
  //     errors: [{ message: 'Graph must be an object' }],
  //   };
  // }

  // Validate node IDs are unique
  const nodeIds = new Set<string>();
  for (const node of graphJson.nodes) {
    if (nodeIds.has(node.id)) {
      errors.push({
        nodeId: node.id,
        message: `Duplicate node ID: ${node.id}`,
      });
    }
    nodeIds.add(node.id);
  }

  // Validate edges reference existing nodes
  if (graphJson.edges) {
    for (const edge of graphJson.edges) {
      if (!nodeIds.has(edge.source)) {
        errors.push({
          message: `Edge references non-existent source node: ${edge.source}`,
        });
      }
      if (!nodeIds.has(edge.target)) {
        errors.push({
          message: `Edge references non-existent target node: ${edge.target}`,
        });
      }
    }
  }

  // Check for cycles (simple DFS-based check)
  const cycleErrors = detectCycles(graphJson);
  errors.push(...cycleErrors);

  // Check reachability from start node
  if (graphJson.startNodeId) {
    if (!nodeIds.has(graphJson.startNodeId)) {
      errors.push({
        message: `Start node does not exist: ${graphJson.startNodeId}`,
      });
    } else {
      const unreachable = findUnreachableNodes(graphJson);
      for (const nodeId of unreachable) {
        errors.push({
          nodeId,
          message: `Node is unreachable from start node`,
        });
      }
    }
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

/**
 * Collect all available variables at each node in the graph
 *
 * @param graphJson - Workflow graph structure
 * @returns Map of node ID to available variable names
 */
export function collectAvailableVars(graphJson: GraphJson): Map<string, string[]> {
  const availableVars = new Map<string, string[]>();
  const allVars = new Set<string>(['input']); // Input is always available globally

  // First pass: collect all variable outputs
  for (const node of graphJson.nodes) {
    const nodeVars = getNodeOutputVars(node);
    nodeVars.forEach(v => allVars.add(v));
  }

  // Second pass: for each node, determine what's available
  // For simplicity, we assume all previously defined vars are available
  // In a more sophisticated implementation, we'd do topological ordering
  const orderedNodes = topologicalSort(graphJson);

  const varsAtNode = new Set<string>(['input']);
  for (const nodeId of orderedNodes) {
    const node = graphJson.nodes.find(n => n.id === nodeId);
    if (!node) {continue;}

    // Variables available at this node
    availableVars.set(nodeId, Array.from(varsAtNode));

    // Add this node's outputs for subsequent nodes
    const outputs = getNodeOutputVars(node);
    outputs.forEach(v => varsAtNode.add(v));
  }

  return availableVars;
}

/**
 * Validate all node conditions and expressions
 *
 * @param graphJson - Workflow graph structure
 * @returns Validation result
 */
export function validateNodeConditions(graphJson: GraphJson): ValidationResult {
  const errors: ValidationError[] = [];
  const availableVars = collectAvailableVars(graphJson);

  for (const node of graphJson.nodes) {
    const varsAtNode = availableVars.get(node.id) ?? [];

    // Validate node-level condition
    const config = node.config as any;
    if (config.condition) {
      const result = validateExpression(config.condition, varsAtNode);
      if (!result.ok) {
        errors.push({
          nodeId: node.id,
          field: 'condition',
          message: result.error,
          path: `nodes.${node.id}.config.condition`,
        });
      }
    }

    // Validate node-specific expressions
    switch (node.type) {
      case 'compute': {
        const computeConfig = config as ComputeNodeConfig;
        const result = validateExpression(computeConfig.expression, varsAtNode);
        if (!result.ok) {
          errors.push({
            nodeId: node.id,
            field: 'expression',
            message: result.error,
            path: `nodes.${node.id}.config.expression`,
          });
        }
        break;
      }

      case 'branch': {
        const branchConfig = config as BranchNodeConfig;
        for (let i = 0; i < branchConfig.branches.length; i++) {
          const branch = branchConfig.branches[i];
          const result = validateExpression(branch.condition, varsAtNode);
          if (!result.ok) {
            errors.push({
              nodeId: node.id,
              field: `branches[${i}].condition`,
              message: result.error,
              path: `nodes.${node.id}.config.branches[${i}].condition`,
            });
          }
        }
        break;
      }

      case 'template': {
        const templateConfig = config as TemplateNodeConfig;
        for (const [placeholder, expression] of Object.entries(templateConfig.bindings)) {
          const result = validateExpression(expression, varsAtNode);
          if (!result.ok) {
            errors.push({
              nodeId: node.id,
              field: `bindings.${placeholder}`,
              message: result.error,
              path: `nodes.${node.id}.config.bindings.${placeholder}`,
            });
          }
        }
        break;
      }
    }
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

/**
 * Get output variable names for a node
 */
function getNodeOutputVars(node: Node): string[] {
  const config = node.config as any;

  switch (node.type) {
    case 'question':
      return [(config as QuestionNodeConfig).key];
    case 'compute':
      return [(config as ComputeNodeConfig).outputKey];
    case 'branch':
    case 'template':
    default:
      return [];
  }
}

/**
 * Detect cycles in the graph
 */
function detectCycles(graphJson: GraphJson): ValidationError[] {
  const errors: ValidationError[] = [];
  const visited = new Set<string>();
  const recStack = new Set<string>();

  const adjacency = buildAdjacencyList(graphJson);

  function dfs(nodeId: string): boolean {
    visited.add(nodeId);
    recStack.add(nodeId);

    const neighbors = adjacency.get(nodeId) ?? [];
    for (const neighbor of neighbors) {
      if (!visited.has(neighbor)) {
        if (dfs(neighbor)) {
          return true;
        }
      } else if (recStack.has(neighbor)) {
        errors.push({
          nodeId,
          message: `Cycle detected involving node ${nodeId}`,
        });
        return true;
      }
    }

    recStack.delete(nodeId);
    return false;
  }

  for (const node of graphJson.nodes) {
    if (!visited.has(node.id)) {
      dfs(node.id);
    }
  }

  return errors;
}

/**
 * Find nodes unreachable from start node
 */
function findUnreachableNodes(graphJson: GraphJson): string[] {
  if (!graphJson.startNodeId) {return [];}

  const reachable = new Set<string>();
  const adjacency = buildAdjacencyList(graphJson);

  function dfs(nodeId: string) {
    reachable.add(nodeId);
    const neighbors = adjacency.get(nodeId) ?? [];
    for (const neighbor of neighbors) {
      if (!reachable.has(neighbor)) {
        dfs(neighbor);
      }
    }
  }

  dfs(graphJson.startNodeId);

  const unreachable: string[] = [];
  for (const node of graphJson.nodes) {
    if (!reachable.has(node.id)) {
      unreachable.push(node.id);
    }
  }

  return unreachable;
}

/**
 * Build adjacency list from graph
 */
function buildAdjacencyList(graphJson: GraphJson): Map<string, string[]> {
  const adjacency = new Map<string, string[]>();

  // Initialize all nodes
  for (const node of graphJson.nodes) {
    adjacency.set(node.id, []);
  }

  // Add edges
  if (graphJson.edges) {
    for (const edge of graphJson.edges) {
      const neighbors = adjacency.get(edge.source) ?? [];
      neighbors.push(edge.target);
      adjacency.set(edge.source, neighbors);
    }
  }

  return adjacency;
}

/**
 * Topological sort of nodes
 */
export function topologicalSort(graphJson: GraphJson): string[] {
  const adjacency = buildAdjacencyList(graphJson);
  const visited = new Set<string>();
  const result: string[] = [];

  function dfs(nodeId: string) {
    if (visited.has(nodeId)) {return;}
    visited.add(nodeId);

    const neighbors = adjacency.get(nodeId) ?? [];
    for (const neighbor of neighbors) {
      dfs(neighbor);
    }

    result.unshift(nodeId);
  }

  // Start from start node if available, otherwise process all
  if (graphJson.startNodeId) {
    dfs(graphJson.startNodeId);
  } else {
    for (const node of graphJson.nodes) {
      dfs(node.id);
    }
  }

  return result;
}

/**
 * Document Generation Error
 *
 * Rich error class for document generation failures with detailed context.
 * Provides structured error information for debugging and user feedback.
 *
 * Features:
 * - Phase tracking (load, normalize, map, render, save)
 * - Full context capture (template, run, step values, mapping)
 * - Error categorization (recoverable vs fatal)
 * - Suggested fixes
 * - Serializable for logging and API responses
 *
 * Usage:
 * ```typescript
 * throw new DocumentGenerationError(
 *   'Failed to render template',
 *   {
 *     phase: 'render',
 *     templateId,
 *     runId,
 *     originalError: error,
 *     recoverable: false
 *   }
 * );
 * ```
 */

import { createError } from '../utils/errors';

// ============================================================================
// TYPES
// ============================================================================

/**
 * Document generation phases
 */
export type DocumentGenerationPhase =
  | 'load'        // Loading template from storage
  | 'unlock'      // Unlocking PDF (qpdf)
  | 'normalize'   // Normalizing step values
  | 'map'         // Applying field mapping
  | 'render'      // Rendering document (docxtemplater, pdf-lib)
  | 'convert'     // Converting DOCX to PDF
  | 'save'        // Saving to storage
  | 'validate'    // Validating output
  | 'unknown';    // Unknown phase

/**
 * Error context
 */
export interface DocumentGenerationErrorContext {
  /** Which phase failed */
  phase: DocumentGenerationPhase;

  /** Template ID */
  templateId?: string;

  /** Template alias (from Final Block config) */
  templateAlias?: string;

  /** Workflow run ID */
  runId?: string;

  /** Workflow ID */
  workflowId?: string;

  /** Original error that caused this */
  originalError?: Error;

  /** Step values (sanitized - no sensitive data) */
  stepValues?: Record<string, any>;

  /** Field mapping */
  mapping?: any;

  /** Normalized data */
  normalizedData?: any;

  /** Mapped data */
  mappedData?: any;

  /** Is this error recoverable? */
  recoverable?: boolean;

  /** Suggested fix */
  suggestion?: string;

  /** Additional metadata */
  metadata?: Record<string, any>;
}

/**
 * Serialized error (for API responses and logging)
 */
export interface SerializedDocumentGenerationError {
  name: string;
  message: string;
  phase: DocumentGenerationPhase;
  templateId?: string;
  templateAlias?: string;
  runId?: string;
  workflowId?: string;
  recoverable: boolean;
  suggestion?: string;
  originalError?: {
    name: string;
    message: string;
    stack?: string;
  };
  timestamp: string;
}

// ============================================================================
// ERROR CLASS
// ============================================================================

export class DocumentGenerationError extends Error {
  public readonly phase: DocumentGenerationPhase;
  public readonly templateId?: string;
  public readonly templateAlias?: string;
  public readonly runId?: string;
  public readonly workflowId?: string;
  public readonly originalError?: Error;
  public readonly stepValues?: Record<string, any>;
  public readonly mapping?: any;
  public readonly normalizedData?: any;
  public readonly mappedData?: any;
  public readonly recoverable: boolean;
  public readonly suggestion?: string;
  public readonly metadata?: Record<string, any>;
  public readonly timestamp: Date;

  constructor(message: string, context: DocumentGenerationErrorContext) {
    super(message);

    this.name = 'DocumentGenerationError';
    this.phase = context.phase;
    this.templateId = context.templateId;
    this.templateAlias = context.templateAlias;
    this.runId = context.runId;
    this.workflowId = context.workflowId;
    this.originalError = context.originalError;
    this.stepValues = context.stepValues;
    this.mapping = context.mapping;
    this.normalizedData = context.normalizedData;
    this.mappedData = context.mappedData;
    this.recoverable = context.recoverable ?? false;
    this.suggestion = context.suggestion || this.getSuggestionForPhase(context.phase);
    this.metadata = context.metadata;
    this.timestamp = new Date();

    // Maintain proper stack trace
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, DocumentGenerationError);
    }

    // Append original error stack if available
    if (context.originalError?.stack) {
      this.stack = `${this.stack}\n\nCaused by: ${context.originalError.stack}`;
    }
  }

  /**
   * Serialize error for logging and API responses
   */
  toJSON(): SerializedDocumentGenerationError {
    return {
      name: this.name,
      message: this.message,
      phase: this.phase,
      templateId: this.templateId,
      templateAlias: this.templateAlias,
      runId: this.runId,
      workflowId: this.workflowId,
      recoverable: this.recoverable,
      suggestion: this.suggestion,
      originalError: this.originalError
        ? {
            name: this.originalError.name,
            message: this.originalError.message,
            stack: this.originalError.stack,
          }
        : undefined,
      timestamp: this.timestamp.toISOString(),
    };
  }

  /**
   * Get user-friendly error message
   */
  getUserMessage(): string {
    const phaseMessages: Record<DocumentGenerationPhase, string> = {
      load: 'Failed to load template',
      unlock: 'Failed to unlock PDF',
      normalize: 'Failed to process workflow data',
      map: 'Failed to map fields',
      render: 'Failed to generate document',
      convert: 'Failed to convert document to PDF',
      save: 'Failed to save document',
      validate: 'Generated document is invalid',
      unknown: 'Document generation failed',
    };

    const baseMessage = phaseMessages[this.phase] || 'Document generation failed';

    if (this.templateAlias) {
      return `${baseMessage} for "${this.templateAlias}"`;
    }

    return baseMessage;
  }

  /**
   * Get suggested fix based on phase
   */
  private getSuggestionForPhase(phase: DocumentGenerationPhase): string {
    const suggestions: Record<DocumentGenerationPhase, string> = {
      load: 'Check that the template file exists and is accessible',
      unlock: 'Ensure qpdf is installed and the PDF is not corrupted',
      normalize: 'Verify that step values are in the correct format',
      map: 'Check that all mapped fields have valid source variables',
      render: 'Verify template syntax and ensure all required fields are mapped',
      convert: 'Check PDF conversion service is running',
      save: 'Verify storage service is accessible and has sufficient space',
      validate: 'Review template structure and field mappings',
      unknown: 'Check logs for more details',
    };

    return suggestions[phase] || 'Contact support if the issue persists';
  }

  /**
   * Check if error is recoverable
   */
  isRecoverable(): boolean {
    return this.recoverable;
  }

  /**
   * Get sanitized context (removes sensitive data)
   */
  getSanitizedContext(): Partial<DocumentGenerationErrorContext> {
    return {
      phase: this.phase,
      templateId: this.templateId,
      templateAlias: this.templateAlias,
      runId: this.runId,
      workflowId: this.workflowId,
      recoverable: this.recoverable,
      suggestion: this.suggestion,
      metadata: this.metadata,
    };
  }

  /**
   * Convert to HTTP error response
   */
  toHttpError() {
    return createError.internal(this.getUserMessage(), {
      phase: this.phase,
      templateId: this.templateId,
      suggestion: this.suggestion,
      recoverable: this.recoverable,
    });
  }
}

// ============================================================================
// FACTORY FUNCTIONS
// ============================================================================

/**
 * Create error for template loading failure
 */
export function createTemplateLoadError(
  templateId: string,
  originalError: Error
): DocumentGenerationError {
  return new DocumentGenerationError('Failed to load template', {
    phase: 'load',
    templateId,
    originalError,
    recoverable: false,
    suggestion: 'Ensure the template file exists and is not corrupted',
  });
}

/**
 * Create error for PDF unlock failure
 */
export function createPdfUnlockError(
  templateId: string,
  originalError: Error
): DocumentGenerationError {
  return new DocumentGenerationError('Failed to unlock PDF', {
    phase: 'unlock',
    templateId,
    originalError,
    recoverable: true, // Can fallback to original PDF
    suggestion: 'Install qpdf or use an unencrypted PDF template',
  });
}

/**
 * Create error for normalization failure
 */
export function createNormalizationError(
  runId: string,
  originalError: Error,
  stepValues?: Record<string, any>
): DocumentGenerationError {
  return new DocumentGenerationError('Failed to normalize workflow data', {
    phase: 'normalize',
    runId,
    originalError,
    stepValues,
    recoverable: false,
    suggestion: 'Check that step values are valid JSON objects',
  });
}

/**
 * Create error for mapping failure
 */
export function createMappingError(
  templateId: string,
  runId: string,
  originalError: Error,
  mapping?: any
): DocumentGenerationError {
  return new DocumentGenerationError('Failed to apply field mapping', {
    phase: 'map',
    templateId,
    runId,
    originalError,
    mapping,
    recoverable: false,
    suggestion: 'Validate mapping configuration and ensure all source variables exist',
  });
}

/**
 * Create error for rendering failure
 */
export function createRenderError(
  templateId: string,
  runId: string,
  originalError: Error,
  mappedData?: any
): DocumentGenerationError {
  return new DocumentGenerationError('Failed to render document', {
    phase: 'render',
    templateId,
    runId,
    originalError,
    mappedData,
    recoverable: false,
    suggestion: 'Check template syntax and ensure all placeholders are valid',
  });
}

/**
 * Create error for PDF conversion failure
 */
export function createConversionError(
  templateId: string,
  runId: string,
  originalError: Error
): DocumentGenerationError {
  return new DocumentGenerationError('Failed to convert document to PDF', {
    phase: 'convert',
    templateId,
    runId,
    originalError,
    recoverable: true, // Can return DOCX instead
    suggestion: 'Ensure PDF conversion service is running (Puppeteer or LibreOffice)',
  });
}

/**
 * Create error for save failure
 */
export function createSaveError(
  templateId: string,
  runId: string,
  originalError: Error
): DocumentGenerationError {
  return new DocumentGenerationError('Failed to save document', {
    phase: 'save',
    templateId,
    runId,
    originalError,
    recoverable: true, // Document was generated, just not saved
    suggestion: 'Check storage service connectivity and available space',
  });
}

/**
 * Check if error is a DocumentGenerationError
 */
export function isDocumentGenerationError(error: any): error is DocumentGenerationError {
  return error instanceof DocumentGenerationError;
}

/**
 * Wrap any error as DocumentGenerationError
 */
export function wrapAsDocumentGenerationError(
  error: any,
  context: Partial<DocumentGenerationErrorContext>
): DocumentGenerationError {
  if (isDocumentGenerationError(error)) {
    return error;
  }

  return new DocumentGenerationError(
    error.message || 'Unknown document generation error',
    {
      phase: context.phase || 'unknown',
      originalError: error,
      ...context,
    }
  );
}

import { serialize } from "cookie";
import rateLimit from "express-rate-limit";
import { OAuth2Client, type TokenPayload } from "google-auth-library";

import { createLogger } from "./logger";
import { userRepository } from "./repositories";
import { authService } from "./services/AuthService";
import { templateSharingService } from "./services/TemplateSharingService";

import type { } from "./types";
import type { Express } from "express";
const logger = createLogger({ module: 'auth' });
// Initialize Google OAuth2 client
let googleClient: OAuth2Client | null = null;
function getGoogleClient(): OAuth2Client {
  if (!googleClient) {
    if (!process.env.GOOGLE_CLIENT_ID) {
      throw new Error("Environment variable GOOGLE_CLIENT_ID not provided");
    }
    googleClient = new OAuth2Client(process.env.GOOGLE_CLIENT_ID);
  }
  return googleClient;
}
/**
 * For testing only: allow injecting a custom OAuth client
 * @internal
 * @throws {Error} If called outside of test environment
 */
export function _testOnly_setGoogleClient(client: OAuth2Client | null) {
  if (process.env.NODE_ENV !== 'test' && process.env.NODE_ENV !== 'development') {
    throw new Error('_testOnly_setGoogleClient can only be called in test/development environments');
  }
  googleClient = client;
}
async function upsertUser(payload: TokenPayload) {
  try {
    // Get default tenant for new users
    const { getDb } = await import('./db');
    const { tenants } = await import('@shared/schema');
    const db = getDb();
    if (!db) { throw new Error("Database not initialized"); }
    const [defaultTenant] = await db.select().from(tenants).limit(1);
    if (!defaultTenant) {
      logger.error('No default tenant found in database');
      throw new Error("System not properly configured - no tenant found");
    }
    const userData = {
      id: payload.sub,
      email: payload.email ?? "",
      firstName: payload.given_name ?? null,
      lastName: payload.family_name ?? null,
      profileImageUrl: payload.picture ?? null,
      defaultMode: 'easy' as const,
      tenantId: defaultTenant.id,
      tenantRole: (process.env.NODE_ENV === 'development' ? 'owner' : 'viewer') as 'owner' | 'viewer' | 'builder' | 'runner',
      authProvider: 'google' as const,
      emailVerified: true,
      lastPasswordChange: null
    };
    logger.debug({ userId: userData.id, email: userData.email, tenantId: defaultTenant.id }, 'Upserting user');
    await userRepository.upsert(userData);
    return userData;
  } catch (error) {
    logger.error({ err: error, userId: payload.sub }, 'Failed to upsert user during authentication');
    throw new Error("Failed to create or update user account");
  }
}
export async function verifyGoogleToken(token: string): Promise<TokenPayload> {
  try {
    const client = getGoogleClient();
    logger.debug({ tokenLength: token?.length }, 'Verifying Google token');
    const ticket = await client.verifyIdToken({
      idToken: token,
      audience: process.env.GOOGLE_CLIENT_ID,
    });
    const payload = ticket.getPayload();
    if (!payload) { throw new Error("Invalid token payload"); }
    if (!payload.email_verified) {
      logger.warn({ email: payload.email }, 'Email not verified by Google');
      throw new Error("Email not verified by Google");
    }
    return payload;
  } catch (error) {
    logger.error({ err: error }, 'Google token verification failed');
    throw error;
  }
}
// Rate limiting for authentication endpoint
const authRateLimit = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: process.env.NODE_ENV === 'test' ? 1000 : 10,
  message: { message: 'Too many authentication attempts, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
// Helper function to validate Origin/Referer
function validateOrigin(req: any): boolean {
  const origin = req.get('Origin') || req.get('Referer');
  if (!origin) { return false; }
  try {
    const originUrl = new URL(origin);
    const allowedHosts = ['localhost', '127.0.0.1', '0.0.0.0'];
    if (process.env.ALLOWED_ORIGIN) {
      const allowedOrigins = process.env.ALLOWED_ORIGIN.split(',').map(origin => {
        try {
          return origin.includes('://') ? new URL(origin).hostname : origin.trim();
        } catch { return origin.trim(); }
      });
      allowedHosts.push(...allowedOrigins);
    }
    const validHosts = allowedHosts.filter(Boolean);
    return validHosts.some(host =>
      originUrl.hostname === host || originUrl.hostname.endsWith(`.${host}`)
    );
  } catch {
    return false;
  }
}
export async function setupAuth(app: Express) {
  app.set("trust proxy", 1);
  // Session middleware REMOVED
  // Google OAuth2 login route - accepts ID token from frontend
  app.post("/api/auth/google", authRateLimit, async (req, res) => {
    try {
      const { token, idToken } = req.body;
      const googleToken = token || idToken;
      if (!googleToken) {
        return res.status(400).json({ message: "ID token is required", error: "missing_token" });
      }
      // CSRF Protection: Validate Origin/Referer
      if (!validateOrigin(req)) {
        return res.status(403).json({ message: "Invalid request origin", error: "invalid_origin" });
      }
      // Verify and Upsert
      const payload = await verifyGoogleToken(googleToken);
      await upsertUser(payload);
      const dbUser = await userRepository.findById(payload.sub);
      if (!dbUser) { throw new Error('User not found after upsert'); }
      // Accept pending shares
      try {
        await templateSharingService.acceptPendingOnLogin({ ...dbUser, authProvider: 'google' } as any);
      } catch (e) {
        logger.warn('Failed to accept pending template shares');
      }
      // Generate Tokens using AuthService
      const jwtToken = authService.createToken(dbUser);
      const refreshToken = await authService.createRefreshToken(dbUser.id, {
        ip: req.ip,
        userAgent: req.headers['user-agent']
      });
      // Set Refresh Token Cookie
      res.setHeader('Set-Cookie', serialize('refresh_token', refreshToken, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'strict',
        path: '/',
        maxAge: 60 * 60 * 24 * 30 // 30 days
      }));
      logger.info({ email: payload.email }, 'OAuth2 login successful');
      res.json({
        message: "Authentication successful",
        token: jwtToken,
        user: {
          id: payload.sub,
          email: payload.email,
          firstName: dbUser.firstName,
          lastName: dbUser.lastName,
          profileImageUrl: dbUser.profileImageUrl,
          tenantId: dbUser.tenantId,
          role: dbUser.role,
          tenantRole: dbUser.tenantRole,
        }
      });
    } catch (error) {
      logger.error({ err: error }, 'Google authentication failed');
      res.status(401).json({ message: "Authentication failed", error: "auth_failed" });
    }
  });
}

/**
 * Metrics Rollup Job
 *
 * Aggregates raw metrics events into time-bucketed rollups for faster analytics queries.
 * Runs periodically to compute metrics for 1m, 5m, 1h, and 1d buckets.
 */
import { sql } from 'drizzle-orm';

import {
  metricsEvents,
  metricsRollups,
  type InsertMetricsRollup,
} from '../../shared/schema';
import { db } from '../db';
import logger from '../logger';
import sli from '../services/sli';
export type BucketSize = '1m' | '5m' | '1h' | '1d';
interface RollupParams {
  bucketSize: BucketSize;
  since?: Date;
  until?: Date;
}
/**
 * Run metrics rollup for all buckets
 */
export async function runRollup(params?: {
  bucketSize?: BucketSize;
  since?: Date;
  until?: Date;
}): Promise<void> {
  const buckets: BucketSize[] = params?.bucketSize ? [params.bucketSize] : ['1m', '5m', '1h', '1d'];
  for (const bucket of buckets) {
    try {
      await rollupBucket({
        bucketSize: bucket,
        since: params?.since,
        until: params?.until,
      });
    } catch (error) {
      logger.error({ err: error, bucket }, 'Rollup failed for bucket');
    }
  }
  // logger.info({ buckets }, 'Metrics rollup completed');
}
/**
 * Rollup a specific bucket size
 */
async function rollupBucket(params: RollupParams): Promise<void> {
  const bucketMs = getBucketMilliseconds(params.bucketSize);
  const now = new Date();
  // Default to last 2 buckets if not specified
  const until = params.until || now;
  const since = params.since || new Date(now.getTime() - bucketMs * 2);
  // Get bucket boundaries
  const buckets = getBucketBoundaries(since, until, bucketMs);
  // logger.debug({
  //   bucketSize: params.bucketSize,
  //   bucketCount: buckets.length,
  //   since,
  //   until,
  // }, 'Rolling up metrics');
  for (const bucket of buckets) {
    await rollupSingleBucket({
      bucketSize: params.bucketSize,
      bucketStart: bucket.start,
      bucketEnd: bucket.end,
    });
  }
}
/**
 * Rollup a single time bucket
 */
async function rollupSingleBucket(params: {
  bucketSize: BucketSize;
  bucketStart: Date;
  bucketEnd: Date;
}): Promise<void> {
  // Query all events in this bucket, grouped by tenant/project/workflow
  const query = sql`
    SELECT
      tenant_id,
      project_id,
      workflow_id,
      COUNT(*) FILTER (WHERE type = 'run_started') as runs_count,
      COUNT(*) FILTER (WHERE type = 'run_succeeded') as runs_success,
      COUNT(*) FILTER (WHERE type = 'run_failed') as runs_error,
      PERCENTILE_DISC(0.5) WITHIN GROUP (ORDER BY duration_ms) FILTER (WHERE type IN ('run_succeeded', 'run_failed') AND duration_ms IS NOT NULL) as dur_p50,
      PERCENTILE_DISC(0.95) WITHIN GROUP (ORDER BY duration_ms) FILTER (WHERE type IN ('run_succeeded', 'run_failed') AND duration_ms IS NOT NULL) as dur_p95,
      COUNT(*) FILTER (WHERE type = 'pdf_succeeded') as pdf_success,
      COUNT(*) FILTER (WHERE type = 'pdf_failed') as pdf_error,
      COUNT(*) FILTER (WHERE type = 'docx_succeeded') as docx_success,
      COUNT(*) FILTER (WHERE type = 'docx_failed') as docx_error,
      COUNT(*) FILTER (WHERE type = 'queue_enqueued') as queue_enqueued,
      COUNT(*) FILTER (WHERE type = 'queue_dequeued') as queue_dequeued
    FROM metrics_events
    WHERE ts >= ${params.bucketStart} AND ts < ${params.bucketEnd}
    GROUP BY tenant_id, project_id, workflow_id
  `;
  const results = await db.execute(query);
  // Upsert rollups for each group
  for (const row of results.rows as any[]) {
    const rollupData: InsertMetricsRollup = {
      tenantId: row.tenant_id,
      projectId: row.project_id,
      workflowId: row.workflow_id,
      bucketStart: params.bucketStart,
      bucket: params.bucketSize,
      runsCount: parseInt(row.runs_count) || 0,
      runsSuccess: parseInt(row.runs_success) || 0,
      runsError: parseInt(row.runs_error) || 0,
      durP50: row.dur_p50 ? Math.round(parseFloat(row.dur_p50)) : null,
      durP95: row.dur_p95 ? Math.round(parseFloat(row.dur_p95)) : null,
      pdfSuccess: parseInt(row.pdf_success) || 0,
      pdfError: parseInt(row.pdf_error) || 0,
      docxSuccess: parseInt(row.docx_success) || 0,
      docxError: parseInt(row.docx_error) || 0,
      queueEnqueued: parseInt(row.queue_enqueued) || 0,
      queueDequeued: parseInt(row.queue_dequeued) || 0,
    };
    // Upsert rollup using raw SQL (Drizzle doesn't support sql expressions in target array)
    await db.execute(sql`
      INSERT INTO metrics_rollups (
        tenant_id, project_id, workflow_id, bucket_start, bucket,
        runs_count, runs_success, runs_error, dur_p50, dur_p95,
        pdf_success, pdf_error, docx_success, docx_error,
        queue_enqueued, queue_dequeued, created_at, updated_at
      ) VALUES (
        ${rollupData.tenantId},
        ${rollupData.projectId},
        ${rollupData.workflowId},
        ${rollupData.bucketStart},
        ${rollupData.bucket},
        ${rollupData.runsCount},
        ${rollupData.runsSuccess},
        ${rollupData.runsError},
        ${rollupData.durP50},
        ${rollupData.durP95},
        ${rollupData.pdfSuccess},
        ${rollupData.pdfError},
        ${rollupData.docxSuccess},
        ${rollupData.docxError},
        ${rollupData.queueEnqueued},
        ${rollupData.queueDequeued},
        NOW(),
        NOW()
      )
      ON CONFLICT (
        tenant_id,
        project_id,
        COALESCE(workflow_id, '00000000-0000-0000-0000-000000000000'::uuid),
        bucket_start,
        bucket
      )
      DO UPDATE SET
        runs_count = ${rollupData.runsCount},
        runs_success = ${rollupData.runsSuccess},
        runs_error = ${rollupData.runsError},
        dur_p50 = ${rollupData.durP50},
        dur_p95 = ${rollupData.durP95},
        pdf_success = ${rollupData.pdfSuccess},
        pdf_error = ${rollupData.pdfError},
        docx_success = ${rollupData.docxSuccess},
        docx_error = ${rollupData.docxError},
        queue_enqueued = ${rollupData.queueEnqueued},
        queue_dequeued = ${rollupData.queueDequeued},
        updated_at = NOW()
    `);
  }
  // logger.debug({
  //   bucketSize: params.bucketSize,
  //   bucketStart: params.bucketStart,
  //   groupCount: results.rows.length,
  // }, 'Bucket rollup completed');
}
/**
 * Compute and save SLI windows after rollup
 */
export async function computeAndSaveSLIs(): Promise<void> {
  // Get all unique project/workflow combinations from recent rollups
  const query = sql`
    SELECT DISTINCT
      tenant_id,
      project_id,
      workflow_id
    FROM metrics_rollups
    WHERE bucket_start >= NOW() - INTERVAL '30 days'
  `;
  const results = await db.execute(query);
  for (const row of results.rows as any[]) {
    try {
      const sliResult = await sli.computeSLI({
        projectId: row.project_id,
        workflowId: row.workflow_id,
        window: '7d',
      });
      await sli.saveSLIWindow({
        tenantId: row.tenant_id,
        projectId: row.project_id,
        workflowId: row.workflow_id,
        sli: sliResult,
      });
    } catch (error) {
      logger.error({
        err: error,
        projectId: row.project_id,
        workflowId: row.workflow_id,
      }, 'Failed to compute SLI');
    }
  }
  logger.debug('SLI windows computed and saved');
}
/**
 * Get bucket boundaries for a time range
 */
function getBucketBoundaries(
  start: Date,
  end: Date,
  bucketMs: number
): Array<{ start: Date; end: Date }> {
  const buckets: Array<{ start: Date; end: Date }> = [];
  // Align start to bucket boundary
  const alignedStart = new Date(Math.floor(start.getTime() / bucketMs) * bucketMs);
  let current = alignedStart;
  while (current < end) {
    const bucketEnd = new Date(current.getTime() + bucketMs);
    buckets.push({
      start: new Date(current),
      end: bucketEnd,
    });
    current = bucketEnd;
  }
  return buckets;
}
/**
 * Get bucket size in milliseconds
 */
function getBucketMilliseconds(bucket: BucketSize): number {
  switch (bucket) {
    case '1m':
      return 60 * 1000;
    case '5m':
      return 5 * 60 * 1000;
    case '1h':
      return 60 * 60 * 1000;
    case '1d':
      return 24 * 60 * 60 * 1000;
  }
}
/**
 * Start rollup worker (runs periodically)
 */
export function startRollupWorker(intervalMs: number = 60000): NodeJS.Timeout {
  logger.info({ intervalMs }, 'Starting metrics rollup worker');
  const interval = setInterval(async () => {
    try {
      await runRollup();
      // Compute SLIs every 5 minutes
      if (Date.now() % (5 * 60 * 1000) < intervalMs) {
        await computeAndSaveSLIs();
      }
    } catch (error) {
      logger.error({ err: error }, 'Rollup worker error');
    }
  }, intervalMs);
  // Run immediately on start
  runRollup().catch((error) => {
    logger.error({ err: error }, 'Initial rollup failed');
  });
  return interval;
}
/**
 * Export rollup functions
 */
export default {
  runRollup,
  computeAndSaveSLIs,
  startRollupWorker,
};

