import { eq } from "drizzle-orm";

import { workflowRuns } from "@shared/schema";

import { db } from "../db";
import { logger } from "../logger";

import type { Request, Response, NextFunction } from "express";

/**
 * Extended request type with run authentication info
 */
export interface RunAuthRequest extends Request {
  runAuth?: {
    runId: string;
    workflowId: string;
    runToken: string;
  };
}

/**
 * Middleware to authenticate requests using Bearer runToken
 * Sets req.runAuth with run information if valid
 *
 * Usage:
 *   app.post('/api/runs/:runId/values', runTokenAuth, handler)
 *
 * Authorization header format:
 *   Authorization: Bearer <runToken>
 */
export async function runTokenAuth(
  req: RunAuthRequest,
  res: Response,
  next: NextFunction
): Promise<void> {
  try {
    // Extract token from Authorization header
    const authHeader = req.headers.authorization;
    if (!authHeader?.startsWith("Bearer ")) {
      res.status(401).json({
        success: false,
        error: "Unauthorized - Missing or invalid Authorization header",
      });
      return;
    }

    const token = authHeader.substring(7); // Remove "Bearer " prefix

    if (!token) {
      res.status(401).json({
        success: false,
        error: "Unauthorized - No token provided",
      });
      return;
    }

    // Look up the run by token
    const [run] = await db
      .select()
      .from(workflowRuns)
      .where(eq(workflowRuns.runToken, token))
      .limit(1);

    if (!run) {
      res.status(401).json({
        success: false,
        error: "Unauthorized - Invalid run token",
      });
      return;
    }

    // Set run auth info on request
    req.runAuth = {
      runId: run.id,
      workflowId: run.workflowId,
      runToken: token,
    };

    next();
  } catch (error) {
    logger.error({
      err: error,
      cause: error instanceof Error ? error.cause : undefined,
      stack: error instanceof Error ? error.stack : undefined
    }, "Error in runTokenAuth middleware");
    res.status(500).json({
      success: false,
      error: "Internal server error during authentication",
    });
  }
}

/**
 * Middleware that accepts EITHER session auth OR run token auth
 * Checks session first, then falls back to run token
 *
 * Sets either:
 *   - req.user (from session) OR
 *   - req.runAuth (from token)
 *
 * Usage:
 *   app.post('/api/runs/:runId/values', creatorOrRunTokenAuth, handler)
 */
export async function creatorOrRunTokenAuth(
  req: RunAuthRequest,
  res: Response,
  next: NextFunction
): Promise<void> {
  // Check if user is authenticated via hybridAuth (bearer token or cookie)
  // The hybridAuth middleware should run before this and set req.userId
  const userId = (req as any).userId;

  if (userId) {
    // User is authenticated, continue (assuming authorization validation happens in service)
    // We optionally populate req.user if downstream needs it, but mostly we just need to pass
    return next();
  }

  // Fall back to run token auth
  try {
    const authHeader = req.headers.authorization;
    if (!authHeader?.startsWith("Bearer ")) {
      res.status(401).json({
        success: false,
        error: "Unauthorized - Must be authenticated as creator or provide valid run token",
      });
      return;
    }

    const token = authHeader.substring(7);

    if (!token) {
      res.status(401).json({
        success: false,
        error: "Unauthorized - No token provided",
      });
      return;
    }

    // Look up the run by token
    const [run] = await db
      .select()
      .from(workflowRuns)
      .where(eq(workflowRuns.runToken, token))
      .limit(1);

    if (!run) {
      res.status(401).json({
        success: false,
        error: "Unauthorized - Invalid run token",
      });
      return;
    }

    // Set run auth info on request
    req.runAuth = {
      runId: run.id,
      workflowId: run.workflowId,
      runToken: token,
    };

    next();
  } catch (error) {
    logger.error({
      err: error,
      cause: error instanceof Error ? error.cause : undefined,
      stack: error instanceof Error ? error.stack : undefined
    }, "Error in creatorOrRunTokenAuth middleware");
    res.status(500).json({
      success: false,
      error: "Internal server error during authentication",
    });
  }
}

/**
 * Security Headers Middleware
 *
 * Implements comprehensive security headers using Helmet middleware to protect
 * against common web vulnerabilities. Based on OWASP recommendations and modern
 * security best practices.
 *
 * Headers implemented via Helmet:
 * - Content Security Policy (CSP) - Prevents XSS, code injection
 * - Strict-Transport-Security (HSTS) - Forces HTTPS
 * - X-Content-Type-Options - Prevents MIME sniffing
 * - X-Frame-Options - Prevents clickjacking
 * - X-XSS-Protection - Legacy XSS protection (for older browsers)
 * - Referrer-Policy - Controls referrer information
 * - Permissions-Policy - Controls browser features
 * - X-DNS-Prefetch-Control - Controls DNS prefetching
 * - X-Download-Options - Prevents IE from executing downloads
 * - X-Permitted-Cross-Domain-Policies - Controls cross-domain policies
 *
 * Created: December 22, 2025
 * Updated: December 25, 2025 - Migrated to Helmet middleware
 * Security Audit Fix
 */

import helmet from 'helmet';

import { createLogger } from '../logger.js';

import type { Request, Response, NextFunction } from 'express';

const logger = createLogger({ module: 'security-headers' });

/**
 * Security headers configuration
 */
interface SecurityHeadersConfig {
  /** Enable CSP header */
  enableCSP?: boolean;
  /** Enable HSTS header (only in production) */
  enableHSTS?: boolean;
  /** HSTS max age in seconds (default: 1 year) */
  hstsMaxAge?: number;
  /** Allow framing from same origin (default: DENY) */
  allowFraming?: 'DENY' | 'SAMEORIGIN';
  /** Additional CSP directives */
  cspDirectives?: Record<string, string[]>;
}

/**
 * Default security headers middleware using Helmet
 *
 * Usage:
 * ```typescript
 * import { securityHeaders } from './middleware/securityHeaders.js';
 * app.use(securityHeaders());
 * ```
 */
export function securityHeaders(config: SecurityHeadersConfig = {}) {
  const {
    enableCSP = true,
    enableHSTS = process.env.NODE_ENV === 'production',
    hstsMaxAge = 31536000, // 1 year
    allowFraming = 'DENY',
    cspDirectives = {},
  } = config;

  // Base CSP directives (strict but functional)
  const defaultDirectives: Record<string, string[]> = {
    'default-src': ["'self'"],
    'script-src': [
      "'self'",
      "'unsafe-inline'", // Required for React/Vite in development
      "'unsafe-eval'",   // Required for some JS libraries (consider removing in prod)
      'https://*.google.com',
      'https://*.gstatic.com',
      'https://*.googleapis.com',
    ],
    'style-src': [
      "'self'",
      "'unsafe-inline'", // Required for styled-components, Tailwind
      'https://*.googleapis.com',
      'https://*.google.com',
      'https://*.gstatic.com',
    ],
    'font-src': [
      "'self'",
      'https://*.gstatic.com',
      'https://*.googleapis.com',
      'data:', // Allow data URIs for fonts
    ],
    'img-src': [
      "'self'",
      'data:',       // Data URIs for inline images
      'blob:',       // Blob URLs for generated images
      'https:',      // Allow HTTPS images (consider restricting)
    ],
    'connect-src': [
      "'self'",
      'https://*.google.com',
      'https://*.googleapis.com',
      'https://*.gstatic.com',
      'wss://localhost:*', // WebSocket for development
      'ws://localhost:*',
    ],
    'frame-src': [
      "'self'",
      'https://*.google.com',
      'https://*.firebaseapp.com', // Firebase Auth if used
    ],
    'object-src': ["'none'"],
    'base-uri': ["'self'"],
    'form-action': ["'self'"],
    'frame-ancestors': ["'none'"], // Prevent framing (redundant with X-Frame-Options)
    'upgrade-insecure-requests': [], // Upgrade HTTP to HTTPS
  };

  // Merge with custom directives
  const mergedDirectives = { ...defaultDirectives, ...cspDirectives };

  // Convert directives to Helmet format
  const helmetCSPDirectives: Record<string, string[]> = {};
  for (const [key, values] of Object.entries(mergedDirectives)) {
    helmetCSPDirectives[key] = values;
  }

  // Configure Helmet with all security headers
  return helmet({
    // Content Security Policy
    contentSecurityPolicy: enableCSP ? {
      directives: helmetCSPDirectives,
    } : false,

    // HTTP Strict Transport Security
    hsts: enableHSTS ? {
      maxAge: hstsMaxAge,
      includeSubDomains: true,
      preload: true,
    } : false,

    // X-Frame-Options (clickjacking protection)
    frameguard: {
      action: allowFraming.toLowerCase() as 'deny' | 'sameorigin',
    },

    // X-Content-Type-Options (MIME sniffing protection)
    noSniff: true,

    // X-XSS-Protection (legacy XSS protection for older browsers)
    xssFilter: true,

    // Referrer-Policy
    referrerPolicy: {
      policy: 'no-referrer-when-downgrade',
    },

    // X-DNS-Prefetch-Control (controls DNS prefetching)
    dnsPrefetchControl: {
      allow: false,
    },

    // X-Download-Options (prevents IE from executing downloads in site context)
    ieNoOpen: true,

    // Hide X-Powered-By header
    hidePoweredBy: true,

    // Permissions-Policy (controls browser features)
    permittedCrossDomainPolicies: {
      permittedPolicies: 'none',
    },

    // Cross-Origin-Opener-Policy and Cross-Origin-Embedder-Policy
    // Set to unsafe-none for Google OAuth compatibility
    crossOriginOpenerPolicy: {
      policy: 'unsafe-none',
    },
    crossOriginEmbedderPolicy: false,
  });
}

/**
 * Relaxed security headers for development/testing
 *
 * Use this in development if strict CSP breaks your workflow.
 * NEVER use in production!
 */
export function relaxedSecurityHeaders() {
  logger.warn('Using relaxed security headers - NOT suitable for production');
  return securityHeaders({
    enableCSP: false,
    enableHSTS: false,
    allowFraming: 'SAMEORIGIN',
  });
}

/**
 * Maximum security headers for production
 *
 * Strictest possible configuration. Use this in production.
 * Removes unsafe-inline and unsafe-eval from CSP directives.
 */
export function strictSecurityHeaders() {
  logger.info('Using strict security headers - production configuration');
  return securityHeaders({
    enableCSP: true,
    enableHSTS: true,
    hstsMaxAge: 63072000, // 2 years
    allowFraming: 'DENY',
    cspDirectives: {
      // Override with strict directives (no unsafe-inline, no unsafe-eval)
      'script-src': [
        "'self'",
        'https://accounts.google.com',
        'https://www.google.com',
        'https://www.gstatic.com',
      ],
      'style-src': [
        "'self'",
        'https://fonts.googleapis.com',
        'https://accounts.google.com',
      ],
    },
  });
}

// Log security headers configuration on module load
logger.info({
  environment: process.env.NODE_ENV,
  hstsEnabled: process.env.NODE_ENV === 'production',
}, 'Security headers middleware loaded');

import { createLogger } from '../logger';

import type { Request, Response, NextFunction } from 'express';

const logger = createLogger({ module: 'timeout' });

/**
 * SECURITY FIX: Request Timeout Middleware
 * Prevents long-running requests from consuming server resources
 *
 * Default timeout: 30 seconds (configurable via REQUEST_TIMEOUT_MS env var)
 * Endpoints can override with custom timeout by setting res.locals.timeout
 */

const DEFAULT_TIMEOUT_MS = parseInt(process.env.REQUEST_TIMEOUT_MS ?? '120000', 10);

export function requestTimeout(req: Request, res: Response, next: NextFunction): void {
  // Allow endpoints to override timeout
  let timeoutMs = res.locals.timeout || DEFAULT_TIMEOUT_MS;

  // AUTO-EXTEND: AI routes need more time (default to 5 minutes for large PDFs)
  // Check both path and originalUrl to be safe against mounting differences
  if (req.path.includes('/ai/') || (req.originalUrl && req.originalUrl.includes('/ai/'))) {
    timeoutMs = 600000; // 10 minutes
  }

  // Set timeout on the socket connection
  if (req.socket) {
    req.socket.setTimeout(timeoutMs);
  }

  // Create a timeout handler
  const timeoutHandler = setTimeout(() => {
    if (!res.headersSent) {
      logger.warn({
        method: req.method,
        path: req.path,
        timeoutMs
      }, 'Request timeout');

      res.status(408).json({
        message: 'Request timeout',
        error: 'request_timeout'
      });
    }
  }, timeoutMs);

  // Clear timeout on response finish
  res.on('finish', () => {
    clearTimeout(timeoutHandler);
  });

  // Clear timeout on response close (client disconnected)
  res.on('close', () => {
    clearTimeout(timeoutHandler);
  });

  next();
}

/**
 * Extended timeout middleware for long-running operations
 * Use this for operations like document generation, AI processing, etc.
 */
export function extendedTimeout(timeoutMs: number = 120000) {
  return (req: Request, res: Response, next: NextFunction): void => {
    res.locals.timeout = timeoutMs;
    next();
  };
}

import { z } from 'zod';

import { createLogger } from '../logger';

import type { Request, Response, NextFunction } from 'express';

const logger = createLogger({ module: 'validate-id-middleware' });

// ============================================================
// SCHEMAS
// ============================================================

/**
 * UUID v4 format validator
 */
const uuidSchema = z.string().uuid('Invalid UUID format');

/**
 * Nanoid format validator (21 character alphanumeric)
 * Nanoid default alphabet: A-Za-z0-9_-
 */
const nanoidSchema = z.string().regex(
  /^[A-Za-z0-9_-]{21}$/,
  'Invalid nanoid format (expected 21 characters)'
);

/**
 * Flexible ID validator - accepts either UUID or nanoid
 * This is the most permissive validator
 */
const idSchema = z.string().min(1, 'ID cannot be empty').refine(
  (id) => {
    // Check if it's a valid UUID
    const uuidResult = uuidSchema.safeParse(id);
    if (uuidResult.success) {return true;}

    // Check if it's a valid nanoid
    const nanoidResult = nanoidSchema.safeParse(id);
    if (nanoidResult.success) {return true;}

    return false;
  },
  { message: 'Invalid ID format (must be UUID or nanoid)' }
);

/**
 * Slug format validator (URL-safe string)
 */
const slugSchema = z.string().regex(
  /^[a-z0-9]+(?:-[a-z0-9]+)*$/,
  'Invalid slug format (lowercase alphanumeric with hyphens)'
);

// ============================================================
// VALIDATOR FACTORY
// ============================================================

/**
 * Creates a validation middleware for route parameters
 *
 * @param paramName - Name of the route parameter to validate
 * @param schema - Zod schema to validate against
 * @param options - Validation options
 *
 * @example
 * // Validate UUID parameter
 * app.get('/api/users/:userId', validateParam('userId', uuidSchema), (req, res) => {
 *   const { userId } = req.params; // TypeScript knows this is valid
 * });
 *
 * @example
 * // Validate custom schema
 * app.get('/api/items/:itemId', validateParam('itemId', nanoidSchema), (req, res) => {
 *   // ...
 * });
 */
export function validateParam(
  paramName: string,
  schema: z.ZodSchema,
  options: { optional?: boolean } = {}
) {
  return (req: Request, res: Response, next: NextFunction): void => {
    try {
      const value = req.params[paramName];

      // Handle optional parameters
      if (options.optional && (value === undefined || value === null || value === '')) {
        return next();
      }

      // Validate parameter
      const result = schema.safeParse(value);

      if (!result.success) {
        const errorMessage = result.error.errors[0]?.message || 'Validation failed';
        logger.warn(
          { paramName, value, error: result.error.errors },
          'Parameter validation failed'
        );

        res.status(400).json({
          message: `Invalid ${paramName}: ${errorMessage}`,
          error: 'invalid_parameter',
          field: paramName
        });
        return;
      }

      // Validation passed, continue
      next();
    } catch (error) {
      logger.error({ error, paramName }, 'Validation middleware error');
      res.status(500).json({
        message: 'Internal validation error',
        error: 'internal_error'
      });
    }
  };
}

/**
 * Creates a validation middleware for query parameters
 *
 * @param queryName - Name of the query parameter to validate
 * @param schema - Zod schema to validate against
 * @param options - Validation options
 *
 * @example
 * app.get('/api/items', validateQuery('limit', z.coerce.number().min(1).max(100)), (req, res) => {
 *   const limit = parseInt(req.query.limit as string); // Safe to parse
 * });
 */
export function validateQuery(
  queryName: string,
  schema: z.ZodSchema,
  options: { optional?: boolean } = {}
) {
  return (req: Request, res: Response, next: NextFunction): void => {
    try {
      const value = req.query[queryName];

      // Handle optional query params
      if (options.optional && (value === undefined || value === null || value === '')) {
        return next();
      }

      // Validate query parameter
      const result = schema.safeParse(value);

      if (!result.success) {
        const errorMessage = result.error.errors[0]?.message || 'Validation failed';
        logger.warn(
          { queryName, value, error: result.error.errors },
          'Query parameter validation failed'
        );

        res.status(400).json({
          message: `Invalid ${queryName}: ${errorMessage}`,
          error: 'invalid_query_parameter',
          field: queryName
        });
        return;
      }

      // Validation passed, continue
      next();
    } catch (error) {
      logger.error({ error, queryName }, 'Query validation middleware error');
      res.status(500).json({
        message: 'Internal validation error',
        error: 'internal_error'
      });
    }
  };
}

/**
 * Creates a validation middleware for request body fields
 *
 * @param schema - Zod schema to validate the entire body against
 *
 * @example
 * app.post('/api/users', validateBody(z.object({
 *   email: z.string().email(),
 *   password: z.string().min(8)
 * })), (req, res) => {
 *   // req.body is validated
 * });
 */
export function validateBody(schema: z.ZodSchema) {
  return (req: Request, res: Response, next: NextFunction): void => {
    try {
      const result = schema.safeParse(req.body);

      if (!result.success) {
        const errors = result.error.errors.map(err => ({
          field: err.path.join('.'),
          message: err.message
        }));

        logger.warn({ errors, body: req.body }, 'Body validation failed');

        res.status(400).json({
          message: 'Validation failed',
          error: 'invalid_body',
          errors
        });
        return;
      }

      // Validation passed, continue
      next();
    } catch (error) {
      logger.error({ error }, 'Body validation middleware error');
      res.status(500).json({
        message: 'Internal validation error',
        error: 'internal_error'
      });
    }
  };
}

