async function handleConnection(ws: WebSocket, request: IncomingMessage): Promise<void> {
  logger.debug('New WebSocket connection attempt');

  // Extract room name from URL
  const url = new URL(request.url ?? '', `http://${request.headers.host}`);
  const roomName = url.searchParams.get('room');

  if (!roomName) {
    ws.close(1008, 'Missing room parameter');
    return;
  }

  try {
    // Authenticate connection
    const user = await authenticateConnection(request, roomName);

    // Get or create room
    const room = await getOrCreateRoom(roomName, user.tenantId);

    // Create connection object
    const clientId = generateClientId();
    const connection: CollabConnection = {
      ws,
      user,
      roomName,
      alive: true,
      clientId,
    };

    // Add connection to room and global map
    room.connections.add(connection);
    connections.set(ws, connection);

    // Set user presence
    setUserPresence(room.awareness, clientId, user);

    // Update metrics
    metrics.activeConnections = connections.size;

    logger.info(
      {
        userId: user.userId,
        roomName,
        activeUsers: room.connections.size,
      },
      'User joined collaboration room'
    );

    // Setup WebSocket handlers
    setupWebSocketHandlers(ws, connection, room);

    // Send initial sync
    sendInitialSync(ws, room);

  } catch (error) {
    handleAuthError(ws, error as Error);
  }
}

/**
 * Setup WebSocket event handlers
 */
function setupWebSocketHandlers(
  ws: WebSocket,
  connection: CollabConnection,
  room: Room
): void {
  // Handle incoming messages
  ws.on('message', async (data: Buffer) => {
    try {
      await handleMessage(connection, room, new Uint8Array(data));
    } catch (error) {
      logger.error({ error, userId: connection.user.userId }, 'Error handling message');
    }
  });

  // Handle pong (heartbeat response)
  ws.on('pong', () => {
    connection.alive = true;
  });

  // Handle connection close
  ws.on('close', (code, reason) => {
    handleDisconnection(connection, room);
  });

  // Handle errors
  ws.on('error', (error) => {
    logger.error({ error, userId: connection.user.userId }, 'WebSocket error');
  });
}

/**
 * Handle incoming message
 */
async function handleMessage(
  connection: CollabConnection,
  room: Room,
  message: Uint8Array
): Promise<void> {
  metrics.totalMessages++;

  try {
    const decoder = decoding.createDecoder(message);
    const messageType = decoding.readVarUint(decoder);

    switch (messageType) {
      case MESSAGE_SYNC:
        await handleSyncMessage(connection, room, decoder);
        break;

      case MESSAGE_AWARENESS:
        handleAwarenessMessage(connection, room, decoder);
        break;

      default:
        logger.warn({ messageType }, 'Unknown message type');
    }
  } catch (error: any) {
    logger.error({ error, userId: connection.user.userId, roomName: room.name }, 'Failed to decode message');
  }
}

/**
 * Handle sync protocol message
 */
async function handleSyncMessage(
  connection: CollabConnection,
  room: Room,
  decoder: decoding.Decoder
): Promise<void> {
  // Use a fresh encoder to capture any response (e.g. Sync Step 2)
  const encoder = encoding.createEncoder();
  encoding.writeVarUint(encoder, MESSAGE_SYNC);

  // readSyncMessage will:
  // 1. Read the message type.
  // 2. If Step 1: Write Sync Step 2 to the encoder.
  // 3. If Step 2 or Update: Read the update and apply it to room.doc using 'connection' as origin.
  //    This triggers doc.on('update'), where we handle persistence and broadcasting.
  syncProtocol.readSyncMessage(decoder, encoder, room.doc, connection);

  // If the protocol generated a response (e.g. Step 2), send it back
  if (encoding.length(encoder) > 1) { // > 1 because we wrote message type
    connection.ws.send(encoding.toUint8Array(encoder));
  }
}

/**
 * Handle awareness protocol message
 */
function handleAwarenessMessage(
  connection: CollabConnection,
  room: Room,
  decoder: decoding.Decoder
): void {
  const update = decoding.readVarUint8Array(decoder);

  // Apply awareness update
  awarenessProtocol.applyAwarenessUpdate(room.awareness, update, connection);

  // Broadcast to other connections
  broadcastAwarenessUpdate(room, update, connection.ws);
}

/**
 * Send initial sync to newly connected client
 */
function sendInitialSync(ws: WebSocket, room: Room): void {
  // Send sync step 1 (document state)
  const encoder = encoding.createEncoder();
  encoding.writeVarUint(encoder, MESSAGE_SYNC);
  syncProtocol.writeSyncStep1(encoder, room.doc);
  ws.send(encoding.toUint8Array(encoder));

  // Send awareness state
  const awarenessEncoder = encoding.createEncoder();
  encoding.writeVarUint(awarenessEncoder, MESSAGE_AWARENESS);
  encoding.writeVarUint8Array(
    awarenessEncoder,
    awarenessProtocol.encodeAwarenessUpdate(room.awareness, Array.from(room.awareness.getStates().keys()))
  );
  ws.send(encoding.toUint8Array(awarenessEncoder));

  logger.debug({ activeUsers: room.connections.size }, 'Sent initial sync');
}

/**
 * Broadcast update to all connections except sender
 */
function broadcastUpdate(room: Room, update: Uint8Array, senderWs: WebSocket): void {
  const encoder = encoding.createEncoder();
  encoding.writeVarUint(encoder, MESSAGE_SYNC);
  syncProtocol.writeUpdate(encoder, update);
  const message = encoding.toUint8Array(encoder);

  room.connections.forEach((conn) => {
    if (conn.ws !== senderWs && conn.ws.readyState === WebSocket.OPEN) {
      conn.ws.send(message);
    }
  });
}

/**
 * Broadcast awareness update to all connections except sender
 */
function broadcastAwarenessUpdate(
  room: Room,
  update: Uint8Array,
  senderWs: WebSocket
): void {
  const encoder = encoding.createEncoder();
  encoding.writeVarUint(encoder, MESSAGE_AWARENESS);
  encoding.writeVarUint8Array(encoder, update);
  const message = encoding.toUint8Array(encoder);

  room.connections.forEach((conn) => {
    if (conn.ws !== senderWs && conn.ws.readyState === WebSocket.OPEN) {
      conn.ws.send(message);
    }
  });
}

/**
 * Handle disconnection
 */
function handleDisconnection(connection: CollabConnection, room: Room): void {
  logger.info(
    {
      userId: connection.user.userId,
      roomName: room.name,
    },
    'User disconnected from collaboration room'
  );

  // Remove connection from room
  room.connections.delete(connection);
  connections.delete(connection.ws);

  // Remove user presence
  removeUserPresence(room.awareness, connection.clientId);

  // Update metrics
  metrics.activeConnections = connections.size;

  // If room is empty, clean it up after a delay
  if (room.connections.size === 0) {
    setTimeout(() => {
      if (room.connections.size === 0) {
        cleanupRoom(room.name);
      }
    }, 60000); // 1 minute delay
  }
}

/**
 * Get or create a room
 */
async function getOrCreateRoom(roomName: string, tenantId: string): Promise<Room> {
  let room = rooms.get(roomName);

  if (room) {
    return room;
  }

  logger.info({ roomName }, 'Creating new collaboration room');

  // Parse room name to get workflow ID
  const roomInfo = parseRoomKey(roomName);
  if (!roomInfo) {
    throw new Error('Invalid room key format');
  }

  // Get or create collab doc
  const docId = await getOrCreateCollabDoc(
    roomInfo.workflowId,
    tenantId,
    roomInfo.versionId
  );

  // Load document from database
  const doc = await loadDocument(docId);

  // Create awareness
  const awareness = createAwareness(doc);

  // Subscribe to Redis for multi-instance sync
  const unsubscribeRedis = subscribeToRoom(roomName, (update) => {
    Y.applyUpdate(doc, update, 'remote');
  });

  // Handle document updates (from clients or remote)
  doc.on('update', async (update: Uint8Array, origin: any) => {
    // 1. Update from Remote (Redis) -> Broadcast to local clients
    if (origin === 'remote') {
      broadcastUpdate(room!, update, null as any);
      return;
    }

    // 2. Update from Client Connection -> Persist & Broadcast
    if (origin && typeof origin === 'object' && origin.user) {
      const connection = origin as CollabConnection;

      // Check permissions (Soft enforcement: prevents propagation)
      if (!canMutate(connection.user)) {
        logger.warn({ userId: connection.user.userId }, 'User attempted to mutate without permission');
        return;
      }

      metrics.totalUpdates++;

      // Persist to DB & Publish to Redis
      try {
        const docId = await getDocIdForRoom(roomName, connection.user.tenantId);
        await saveUpdate(docId, update);
        await publishUpdate(roomName, update);
      } catch (error) {
        logger.error({ error }, 'Failed to persist update');
      }

      // Broadcast to other clients in the room
      broadcastUpdate(room!, update, connection.ws);
    }
  });

  // Create room
  room = {
    name: roomName,
    doc,
    awareness,
    connections: new Set(),
    unsubscribeRedis,
  };

  rooms.set(roomName, room);
  metrics.activeRooms = rooms.size;

  logger.info({ roomName, docId }, 'Collaboration room created');

  return room;
}

/**
 * Cleanup room when all users disconnect
 */
function cleanupRoom(roomName: string): void {
  const room = rooms.get(roomName);
  if (!room) {return;}

  logger.info({ roomName }, 'Cleaning up collaboration room');

  // Unsubscribe from Redis
  if (room.unsubscribeRedis) {
    room.unsubscribeRedis();
  }

  // Destroy awareness
  room.awareness.destroy();

  // Remove room
  rooms.delete(roomName);
  metrics.activeRooms = rooms.size;
}

/**
 * Parse room key (same as in auth.ts)
 */
function parseRoomKey(roomKey: string): {
  tenantId: string;
  workflowId: string;
  versionId?: string;
} | null {
  const parts = roomKey.split(':');

  if (parts.length < 4 || parts[0] !== 'tenant' || parts[2] !== 'workflow') {
    return null;
  }

  const result: any = {
    tenantId: parts[1],
    workflowId: parts[3],
  };

  if (parts.length >= 6 && parts[4] === 'version') {
    result.versionId = parts[5];
  }

  return result;
}

/**
 * Get docId for a room (cached or fetch)
 */
async function getDocIdForRoom(roomName: string, tenantId: string): Promise<string> {
  const roomInfo = parseRoomKey(roomName);
  if (!roomInfo) {
    throw new Error('Invalid room key');
  }

  return getOrCreateCollabDoc(
    roomInfo.workflowId,
    tenantId,
    roomInfo.versionId
  );
}

/**
 * Generate unique client ID
 */
let clientIdCounter = 0;
function generateClientId(): number {
  return ++clientIdCounter;
}

/**
 * Get collaboration metrics
 */
export function getMetrics(): typeof metrics & { roomDetails: any[] } {
  const roomDetails = Array.from(rooms.entries()).map(([name, room]) => ({
    name,
    activeUsers: room.connections.size,
    documentSize: Y.encodeStateAsUpdate(room.doc).length,
  }));

  return {
    ...metrics,
    roomDetails,
  };
}

/**
 * Get room statistics (for debug endpoint)
 */
export function getRoomStats(roomName: string): any {
  const room = rooms.get(roomName);
  if (!room) {
    return null;
  }

  return {
    name: room.name,
    activeUsers: room.connections.size,
    users: Array.from(room.connections).map((conn) => ({
      userId: conn.user.userId,
      displayName: conn.user.displayName,
      role: conn.user.role,
    })),
    documentSize: Y.encodeStateAsUpdate(room.doc).length,
    awarenessStates: room.awareness.getStates().size,
  };
}

/**
 * Cleanup and shutdown collaboration server
 */
export async function shutdown(): Promise<void> {
  logger.info('Shutting down collaboration server');

  // Clear intervals
  if (cleanupInterval) {
    clearInterval(cleanupInterval);
  }

  // Close all WebSocket connections
  connections.forEach((conn) => {
    conn.ws.close(1001, 'Server shutting down');
  });

  // Cleanup all rooms
  rooms.forEach((room, name) => {
    cleanupRoom(name);
  });

  // Cleanup persistence
  await cleanupPersistence();

  // Close WebSocket server
  if (wss) {
    wss.close();
  }

  logger.info('Collaboration server shutdown complete');
}

import { eq, desc, and, gt, isNull } from 'drizzle-orm';
import Redis from 'ioredis';
import * as Y from 'yjs';

import { collabDocs, collabUpdates, collabSnapshots } from '../../shared/schema';
import { db } from '../db';
import { createLogger } from '../logger';


const logger = createLogger({ module: 'collab-persistence' });

// Redis client for pub/sub
let redisPublisher: Redis | null = null;
let redisSubscriber: Redis | null = null;

const REDIS_URL = process.env.REDIS_URL;
const SNAPSHOT_INTERVAL = parseInt(process.env.COLLAB_SNAPSHOT_INTERVAL || '200', 10); // Every N updates
const UPDATES_TO_KEEP = parseInt(process.env.COLLAB_UPDATES_TO_KEEP || '1000', 10); // Keep last N updates

/**
 * Initialize Redis pub/sub for multi-instance collaboration
 */
export function initRedis() {
  if (!REDIS_URL) {
    logger.warn('REDIS_URL not configured, multi-instance collab will not work');
    return;
  }

  try {
    redisPublisher = new Redis(REDIS_URL);
    redisSubscriber = new Redis(REDIS_URL);

    redisPublisher.on('error', (err) => {
      logger.error({ error: err }, 'Redis publisher error');
    });

    redisSubscriber.on('error', (err) => {
      logger.error({ error: err }, 'Redis subscriber error');
    });

    logger.info('Redis pub/sub initialized for multi-instance collaboration');
  } catch (error) {
    logger.error({ error }, 'Failed to initialize Redis');
  }
}

/**
 * Publish update to Redis channel for other instances
 */
export async function publishUpdate(roomKey: string, update: Uint8Array): Promise<void> {
  if (!redisPublisher) {return;}

  try {
    const base64Update = Buffer.from(update).toString('base64');
    await redisPublisher.publish(`room:${roomKey}`, base64Update);
  } catch (error) {
    logger.error({ error, roomKey }, 'Failed to publish update to Redis');
  }
}

/**
 * Subscribe to Redis channel for room updates
 */
export function subscribeToRoom(
  roomKey: string,
  callback: (update: Uint8Array) => void
): () => void {
  if (!redisSubscriber) {
    return () => {}; // No-op unsubscribe
  }

  const channel = `room:${roomKey}`;

  const messageHandler = (receivedChannel: string, message: string) => {
    if (receivedChannel === channel) {
      try {
        const update = Buffer.from(message, 'base64');
        callback(new Uint8Array(update));
      } catch (error) {
        logger.error({ error, channel }, 'Failed to decode Redis update');
      }
    }
  };

  redisSubscriber.on('message', messageHandler);
  redisSubscriber.subscribe(channel);

  logger.debug({ channel }, 'Subscribed to Redis channel');

  // Return unsubscribe function
  return () => {
    redisSubscriber?.unsubscribe(channel);
    redisSubscriber?.off('message', messageHandler);
    logger.debug({ channel }, 'Unsubscribed from Redis channel');
  };
}

/**
 * Get or create a collaboration document
 */
export async function getOrCreateCollabDoc(
  workflowId: string,
  tenantId: string,
  versionId?: string | null
): Promise<string> {
  try {
    // Try to find existing doc
    const existing = await db.query.collabDocs.findFirst({
      where: and(
        eq(collabDocs.workflowId, workflowId),
        eq(collabDocs.tenantId, tenantId),
        versionId ? eq(collabDocs.versionId, versionId) : isNull(collabDocs.versionId)
      ),
    });

    if (existing) {
      return existing.id;
    }

    // Create new doc
    const [newDoc] = await db
      .insert(collabDocs)
      .values({
        workflowId,
        tenantId,
        versionId: versionId ?? null,
      })
      .returning();

    logger.info({ docId: newDoc.id, workflowId, tenantId }, 'Created new collab doc');
    return newDoc.id;
  } catch (error) {
    logger.error({ error, workflowId, tenantId }, 'Failed to get or create collab doc');
    throw error;
  }
}

/**
 * Load Yjs document from database (snapshot + updates)
 */
export async function loadDocument(docId: string): Promise<Y.Doc> {
  const doc = new Y.Doc();

  try {
    // Load latest snapshot
    const snapshot = await db.query.collabSnapshots.findFirst({
      where: eq(collabSnapshots.docId, docId),
      orderBy: [desc(collabSnapshots.clock)],
    });

    if (snapshot) {
      logger.debug({ docId, clock: snapshot.clock }, 'Loading snapshot');
      const stateBuffer = Buffer.from(snapshot.state, 'base64');
      Y.applyUpdate(doc, new Uint8Array(stateBuffer));

      // Load updates after snapshot
      const updates = await db.query.collabUpdates.findMany({
        where: and(
          eq(collabUpdates.docId, docId),
          gt(collabUpdates.seq, snapshot.clock)
        ),
        orderBy: [collabUpdates.seq],
      });

      logger.debug({ docId, updateCount: updates.length }, 'Loading updates after snapshot');

      for (const update of updates) {
        const updateBuffer = Buffer.from(update.update, 'base64');
        Y.applyUpdate(doc, new Uint8Array(updateBuffer));
      }
    } else {
      // No snapshot, load all updates
      const updates = await db.query.collabUpdates.findMany({
        where: eq(collabUpdates.docId, docId),
        orderBy: [collabUpdates.seq],
      });

      logger.debug({ docId, updateCount: updates.length }, 'Loading all updates (no snapshot)');

      for (const update of updates) {
        const updateBuffer = Buffer.from(update.update, 'base64');
        Y.applyUpdate(doc, new Uint8Array(updateBuffer));
      }
    }

    logger.info({ docId }, 'Document loaded successfully');
    return doc;
  } catch (error) {
    logger.error({ error, docId }, 'Failed to load document');
    throw error;
  }
}

/**
 * Save update to database
 */
export async function saveUpdate(docId: string, update: Uint8Array): Promise<number> {
  try {
    // Get next sequence number
    const lastUpdate = await db.query.collabUpdates.findFirst({
      where: eq(collabUpdates.docId, docId),
      orderBy: [desc(collabUpdates.seq)],
    });

    const seq = (lastUpdate?.seq || 0) + 1;

    // Save update
    const base64Update = Buffer.from(update).toString('base64');
    await db.insert(collabUpdates).values({
      docId,
      seq,
      update: base64Update,
    });

    logger.debug({ docId, seq }, 'Update saved');

    // Check if we should create a snapshot
    if (seq % SNAPSHOT_INTERVAL === 0) {
      await createSnapshot(docId, seq);
    }

    return seq;
  } catch (error) {
    logger.error({ error, docId }, 'Failed to save update');
    throw error;
  }
}

/**
 * Create a snapshot of the document state
 */
async function createSnapshot(docId: string, clock: number): Promise<void> {
  try {
    // Load current document state
    const doc = await loadDocument(docId);
    const state = Y.encodeStateAsUpdate(doc);
    const base64State = Buffer.from(state).toString('base64');

    // Save snapshot
    await db.insert(collabSnapshots).values({
      docId,
      clock,
      state: base64State,
    });

    logger.info({ docId, clock }, 'Snapshot created');

    // Optionally trim old updates (keep last UPDATES_TO_KEEP)
    const oldUpdates = await db.query.collabUpdates.findMany({
      where: and(
        eq(collabUpdates.docId, docId),
        gt(collabUpdates.seq, 0)
      ),
      orderBy: [desc(collabUpdates.seq)],
    });

    if (oldUpdates.length > UPDATES_TO_KEEP) {
      const deleteBeforeSeq = oldUpdates[UPDATES_TO_KEEP - 1].seq;
      await db
        .delete(collabUpdates)
        .where(
          and(
            eq(collabUpdates.docId, docId),
            gt(collabUpdates.seq, deleteBeforeSeq)
          )
        );

      logger.debug({ docId, deleteBeforeSeq }, 'Trimmed old updates');
    }
  } catch (error) {
    logger.error({ error, docId, clock }, 'Failed to create snapshot');
  }
}

/**
 * Export document as JSON (for publishing workflow)
 */
export async function exportDocumentAsJson(docId: string): Promise<any> {
  try {
    const doc = await loadDocument(docId);

    // Extract data from Yjs document
    const yGraph = doc.getMap('yGraph');
    const yMeta = doc.getMap('yMeta');
    const yComments = doc.getMap('yComments');

    // Convert to plain JSON
    const nodes = (yGraph.get('nodes') as any)?.toJSON() ?? [];
    const edges = (yGraph.get('edges') as any)?.toJSON() ?? [];
    const meta = (yMeta as any).toJSON();
    const comments: Record<string, any> = {};

    yComments.forEach((value: any, key: string) => {
      comments[key] = value.toJSON();
    });

    return {
      nodes,
      edges,
      meta,
      comments,
    };
  } catch (error) {
    logger.error({ error, docId }, 'Failed to export document as JSON');
    throw error;
  }
}

/**
 * Import JSON graph into Yjs document
 */
export async function importJsonToDocument(
  docId: string,
  graphJson: any
): Promise<void> {
  try {
    const doc = await loadDocument(docId);

    doc.transact(() => {
      // Import graph data
      const yGraph = doc.getMap('yGraph');
      const yNodes = new Y.Array();
      const yEdges = new Y.Array();

      if (graphJson.nodes) {
        graphJson.nodes.forEach((node: any) => {
          const yNode = new Y.Map();
          Object.entries(node).forEach(([key, value]) => {
            yNode.set(key, value);
          });
          yNodes.push([yNode]);
        });
      }

      if (graphJson.edges) {
        graphJson.edges.forEach((edge: any) => {
          const yEdge = new Y.Map();
          Object.entries(edge).forEach(([key, value]) => {
            yEdge.set(key, value);
          });
          yEdges.push([yEdge]);
        });
      }

      yGraph.set('nodes', yNodes);
      yGraph.set('edges', yEdges);

      // Import metadata
      if (graphJson.meta) {
        const yMeta = doc.getMap('yMeta');
        Object.entries(graphJson.meta).forEach(([key, value]) => {
          yMeta.set(key, value);
        });
      }
    });

    // Save the update
    const update = Y.encodeStateAsUpdate(doc);
    await saveUpdate(docId, update);

    logger.info({ docId }, 'JSON imported to document');
  } catch (error) {
    logger.error({ error, docId }, 'Failed to import JSON to document');
    throw error;
  }
}

/**
 * Get collaboration metrics for observability
 */
export async function getCollabMetrics(docId: string): Promise<{
  updateCount: number;
  snapshotCount: number;
  lastUpdate: Date | null;
  documentSize: number;
}> {
  try {
    const updates = await db.query.collabUpdates.findMany({
      where: eq(collabUpdates.docId, docId),
    });

    const snapshots = await db.query.collabSnapshots.findMany({
      where: eq(collabSnapshots.docId, docId),
    });

    const lastUpdate = updates.length > 0
      ? updates.reduce((latest: any, update: any) =>
          update.ts > latest ? update.ts : latest,
          updates[0].ts
        )
      : null;

    const doc = await loadDocument(docId);
    const state = Y.encodeStateAsUpdate(doc);

    return {
      updateCount: updates.length,
      snapshotCount: snapshots.length,
      lastUpdate,
      documentSize: state.length,
    };
  } catch (error) {
    logger.error({ error, docId }, 'Failed to get collab metrics');
    throw error;
  }
}

/**
 * Cleanup function for graceful shutdown
 */
export async function cleanup(): Promise<void> {
  logger.info('Cleaning up collaboration persistence');

  if (redisPublisher) {
    await redisPublisher.quit();
    redisPublisher = null;
  }

  if (redisSubscriber) {
    await redisSubscriber.quit();
    redisSubscriber = null;
  }

  logger.info('Collaboration persistence cleanup complete');
}

import { sql } from "drizzle-orm";

import { activityLogSource } from "../config/activityLog.config";
import { db } from "../db";
import { ActivityLog, ActivityLogQuery, ActivityLogInsert, ActivityLogResult } from "../types/activityLog";

import type { DbTransaction } from "./BaseRepository";

/**
 * Schema-Agnostic Activity Log Repository
 *
 * This repository uses raw SQL queries based on the configuration in activityLog.config.ts
 * This allows it to work with any table structure by mapping logical fields to actual columns.
 *
 * Default configuration uses the existing analyticsEvents table.
 */
export class ActivityLogRepository {
  private readonly tableName = activityLogSource.table;
  private readonly columns = activityLogSource.columns;

  /**
   * Get database instance (supports transactions)
   */
  private getDb(tx?: DbTransaction) {
    return tx || db;
  }

  /**
   * Find activity logs with filtering, pagination, and sorting
   */
  async find(query: ActivityLogQuery, tx?: DbTransaction): Promise<ActivityLogResult> {
    const {
      q,
      event,
      actor,
      entityType,
      entityId,
      status,
      from,
      to,
      limit = 50,
      offset = 0,
      sort = "timestamp_desc"
    } = query || {};

    const database = this.getDb(tx);

    // Build WHERE conditions
    const conditions: any[] = [];
    const params: Record<string, any> = {};

    // Free text search: search across event and actorEmail (if available)
    if (q) {
      const searchConditions: any[] = [
        sql`${sql.raw(this.columns.event)} ILIKE ${`%${  q  }%`}`
      ];
      if (this.columns.actorEmail) {
        searchConditions.push(
          sql`${sql.raw(this.columns.actorEmail)} ILIKE ${`%${  q  }%`}`
        );
      }
      conditions.push(sql`(${sql.join(searchConditions, sql` OR `)})`);
    }

    // Event filter
    if (event && this.columns.event) {
      conditions.push(sql`${sql.raw(this.columns.event)} = ${event}`);
    }

    // Actor filter (use ILIKE for partial email matching, only use ID if it looks like a UUID)
    if (actor) {
      if (this.columns.actorEmail) {
        // Use ILIKE for partial matching (e.g., "scooter" matches "scooter4356@gmail.com")
        conditions.push(sql`${sql.raw(this.columns.actorEmail)} ILIKE ${`%${  actor  }%`}`);
      } else if (this.columns.actorId) {
        // Only try to match by ID if the input looks like a valid UUID
        const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
        if (uuidRegex.test(actor)) {
          conditions.push(sql`${sql.raw(this.columns.actorId)} = ${actor}`);
        }
      }
    }

    // Entity type filter
    if (entityType && this.columns.entityType) {
      conditions.push(sql`${sql.raw(this.columns.entityType)} = ${entityType}`);
    }

    // Entity ID filter
    if (entityId && this.columns.entityId) {
      conditions.push(sql`${sql.raw(this.columns.entityId)} = ${entityId}`);
    }

    // Status filter
    if (status && this.columns.status) {
      conditions.push(sql`${sql.raw(this.columns.status)} = ${status}`);
    }

    // Date range filters
    if (from && this.columns.timestamp) {
      conditions.push(sql`${sql.raw(this.columns.timestamp)} >= ${from}::timestamptz`);
    }
    if (to && this.columns.timestamp) {
      conditions.push(sql`${sql.raw(this.columns.timestamp)} <= ${to}::timestamptz`);
    }

    // Build WHERE clause
    const whereClause = conditions.length > 0
      ? sql`WHERE ${sql.join(conditions, sql` AND `)}`
      : sql``;

    // Get total count
    const countQuery = sql`
      SELECT COUNT(*)::int AS total
      FROM ${sql.raw(this.tableName)}
      ${whereClause}
    `;

    const countResult = await database.execute(countQuery);
    const total = (countResult.rows[0])?.total ?? 0;

    // Build SELECT columns
    const selectColumns = [
      sql`${sql.raw(this.columns.id)} as id`,
      sql`${sql.raw(this.columns.timestamp)} as timestamp`,
      sql`${sql.raw(this.columns.event)} as event`,
      this.columns.actorId
        ? sql`${sql.raw(this.columns.actorId)} as "actorId"`
        : sql`NULL as "actorId"`,
      this.columns.actorEmail
        ? sql`${sql.raw(this.columns.actorEmail)} as "actorEmail"`
        : sql`NULL as "actorEmail"`,
      this.columns.entityType
        ? sql`${sql.raw(this.columns.entityType)} as "entityType"`
        : sql`NULL as "entityType"`,
      this.columns.entityId
        ? sql`${sql.raw(this.columns.entityId)} as "entityId"`
        : sql`NULL as "entityId"`,
      this.columns.status
        ? sql`${sql.raw(this.columns.status)} as status`
        : sql`NULL as status`,
      this.columns.ipAddress
        ? sql`${sql.raw(this.columns.ipAddress)} as "ipAddress"`
        : sql`NULL as "ipAddress"`,
      this.columns.userAgent
        ? sql`${sql.raw(this.columns.userAgent)} as "userAgent"`
        : sql`NULL as "userAgent"`,
      this.columns.metadata
        ? sql`${sql.raw(this.columns.metadata)} as metadata`
        : sql`NULL as metadata`
    ];

    // Determine sort order
    const orderDirection = sort === "timestamp_asc" ? sql`ASC` : sql`DESC`;
    const orderBy = sql`ORDER BY ${sql.raw(this.columns.timestamp)} ${orderDirection}`;

    // Build main query
    const dataQuery = sql`
      SELECT ${sql.join(selectColumns, sql`, `)}
      FROM ${sql.raw(this.tableName)}
      ${whereClause}
      ${orderBy}
      LIMIT ${limit}
      OFFSET ${offset}
    `;

    const dataResult = await database.execute(dataQuery);
    const rows = dataResult.rows as ActivityLog[];

    return { rows, total };
  }

  /**
   * Insert a new activity log entry (optional - for manual logging)
   *
   * Note: If you're already logging via analyticsEvents, you may not need this.
   * This method only maps columns that exist in the configuration.
   */
  async insert(entry: ActivityLogInsert, tx?: DbTransaction): Promise<void> {
    const database = this.getDb(tx);

    const columns: string[] = [];
    const values: any[] = [];
    const placeholders: any[] = [];

    // Helper to add a column if it exists in config
    const addColumn = (configKey: keyof typeof this.columns, value: any) => {
      const columnName = this.columns[configKey];
      if (!columnName || value === undefined) {return;}

      columns.push(columnName);
      values.push(value);
      placeholders.push(sql`${value}`);
    };

    // Map fields to columns
    addColumn("id", entry.id || sql`gen_random_uuid()`);
    addColumn("timestamp", entry.timestamp || new Date().toISOString());
    addColumn("event", entry.event);
    addColumn("actorId", entry.actorId ?? null);
    addColumn("actorEmail", entry.actorEmail ?? null);
    addColumn("entityType", entry.entityType ?? null);
    addColumn("entityId", entry.entityId ?? null);
    addColumn("status", entry.status ?? "info");
    addColumn("ipAddress", entry.ipAddress ?? null);
    addColumn("userAgent", entry.userAgent ?? null);
    addColumn("metadata", entry.metadata ?? null);

    if (columns.length === 0) {
      throw new Error("No valid columns to insert");
    }

    // Build INSERT query
    const insertQuery = sql`
      INSERT INTO ${sql.raw(this.tableName)} (${sql.raw(columns.join(", "))})
      VALUES (${sql.join(placeholders, sql`, `)})
    `;

    await database.execute(insertQuery);
  }

  /**
   * Get unique event types (for filter dropdowns)
   */
  async getUniqueEvents(tx?: DbTransaction): Promise<string[]> {
    const database = this.getDb(tx);

    const query = sql`
      SELECT DISTINCT ${sql.raw(this.columns.event)} as event
      FROM ${sql.raw(this.tableName)}
      WHERE ${sql.raw(this.columns.event)} IS NOT NULL
      ORDER BY ${sql.raw(this.columns.event)}
    `;

    const result = await database.execute(query);
    return (result.rows as any[]).map(row => row.event);
  }

  /**
   * Get unique actors (for filter dropdowns)
   */
  async getUniqueActors(tx?: DbTransaction): Promise<string[]> {
    const database = this.getDb(tx);

    // Try actorEmail first, fallback to actorId
    const actorColumn = this.columns.actorEmail || this.columns.actorId;
    if (!actorColumn) {return [];}

    const query = sql`
      SELECT DISTINCT ${sql.raw(actorColumn)} as actor
      FROM ${sql.raw(this.tableName)}
      WHERE ${sql.raw(actorColumn)} IS NOT NULL
      ORDER BY ${sql.raw(actorColumn)}
      LIMIT 100
    `;

    const result = await database.execute(query);
    return (result.rows as any[]).map(row => row.actor);
  }
}

import { eq, type SQL, ExtractTablesWithRelations } from "drizzle-orm";

import * as schema from "@shared/schema";

import { db } from "../db";

import type {  } from "drizzle-orm/node-postgres";
import type { PgTable, PgTransaction } from "drizzle-orm/pg-core";
// Type alias for database transactions
export type DbTransaction = PgTransaction<
  any, // Use any for HKT to support both NodePg and Neon
  typeof schema,
  ExtractTablesWithRelations<typeof schema>
>;
/**
 * Base repository providing common CRUD operations
 * All domain-specific repositories should extend this class
 */
export abstract class BaseRepository<TTable extends PgTable, TSelect, TInsert> {
  protected readonly dbInstance: typeof db | undefined;
  constructor(protected readonly table: TTable, dbInstance?: typeof db) {
    // Store the provided instance, but if none provided, leave undefined
    // to use the getter pattern below
    this.dbInstance = dbInstance;
  }
  /**
   * Get database connection (or transaction if provided)
   * Always references the current value of db to avoid initialization race conditions
   */
  protected getDb(tx?: DbTransaction) {
    // If transaction provided, use it
    if (tx) { return tx; }
    // If explicit db instance was provided in constructor (for tests), use it
    if (this.dbInstance !== undefined) { return this.dbInstance; }
    // Otherwise, use the current value of the db module variable
    // This ensures we always get the initialized db, even if repository
    // was instantiated before database initialization completed
    return db;
  }
  /**
   * Find a single record by ID
   */
  async findById(id: string, tx?: DbTransaction): Promise<TSelect | undefined> {
    const database = this.getDb(tx);
    const idColumn = (this.table as any).id;
    const [record] = await database
      .select()
      .from(this.table as any)
      .where(eq(idColumn, id));
    return record as TSelect | undefined;
  }
  /**
   * Find all records (optionally filtered)
   */
  async findAll(where?: SQL, orderBy?: SQL, tx?: DbTransaction): Promise<TSelect[]> {
    const database = this.getDb(tx);
    let query = database.select().from(this.table as any);
    if (where) {
      query = query.where(where) as any;
    }
    if (orderBy) {
      query = query.orderBy(orderBy) as any;
    }
    return query as Promise<TSelect[]>;
  }
  /**
   * Create a new record
   */
  async create(data: TInsert, tx?: DbTransaction): Promise<TSelect> {
    const database = this.getDb(tx);
    const [record] = await database
      .insert(this.table as any)
      .values(data as any)
      .returning();
    return record as TSelect;
  }
  /**
   * Update a record by ID
   */
  async update(
    id: string,
    updates: Partial<TInsert>,
    tx?: DbTransaction
  ): Promise<TSelect> {
    const database = this.getDb(tx);
    const idColumn = (this.table as any).id;
    try {
      const tableName = (this.table as any)[Symbol.for("drizzle:Name")] || (this.table as any)._?.name || 'unknown';
      process.stdout.write(`[DEBUG] BaseRepository.update ${tableName}: id=${id}, updates=${JSON.stringify(updates)}\n`);
    } catch (e) { process.stdout.write("Log error\n"); }
    const [record] = await database
      .update(this.table as any)
      .set(updates as any)
      .where(eq(idColumn, id))
      .returning();
    return record as TSelect;
  }
  /**
   * Delete a record by ID
   */
  async delete(id: string, tx?: DbTransaction): Promise<void> {
    const database = this.getDb(tx);
    const idColumn = (this.table as any).id;
    await database
      .delete(this.table as any)
      .where(eq(idColumn, id));
  }
  /**
   * Delete multiple records matching a condition
   */
  async deleteWhere(where: SQL, tx?: DbTransaction): Promise<void> {
    const database = this.getDb(tx);
    await database
      .delete(this.table as any)
      .where(where);
  }
  /**
   * Count records (optionally filtered)
   */
  async count(where?: SQL, tx?: DbTransaction): Promise<number> {
    const database = this.getDb(tx);
    let query = database.select({ count: db.select().from(this.table as any) as any }).from(this.table as any);
    if (where) {
      query = query.where(where) as any;
    }
    const [result] = await query;
    return Number(result?.count || 0);
  }
  /**
   * Execute a transaction with multiple operations
   */
  async transaction<T>(
    callback: (tx: DbTransaction) => Promise<T>
  ): Promise<T> {
    return db.transaction(callback);
  }
}

import { eq, and, desc, sql } from "drizzle-orm";

import { templates, type Template, type InsertTemplate } from "@shared/schema";

