import { templateShares, users } from "../../shared/schema";
import { db } from "../db";

export class TemplateShareRepository {
  /**
   * List all shares for a specific template
   * Returns both accepted (userId set) and pending (pendingEmail set) shares
   */
  async listByTemplate(templateId: string) {
    return db
      .select({
        id: templateShares.id,
        templateId: templateShares.templateId,
        userId: templateShares.userId,
        userEmail: users.email,
        pendingEmail: templateShares.pendingEmail,
        access: templateShares.access,
        invitedAt: templateShares.invitedAt,
        acceptedAt: templateShares.acceptedAt,
      })
      .from(templateShares)
      .leftJoin(users, eq(users.id, templateShares.userId))
      .where(eq(templateShares.templateId, templateId));
  }

  /**
   * List all templates shared with a specific user (by userId or their email)
   */
  async listForUser(userId: string, userEmail: string) {
    return db
      .select({
        id: templateShares.id,
        templateId: templateShares.templateId,
        access: templateShares.access,
        invitedAt: templateShares.invitedAt,
        acceptedAt: templateShares.acceptedAt,
      })
      .from(templateShares)
      .where(
        or(
          eq(templateShares.userId, userId),
          eq(templateShares.pendingEmail, userEmail.toLowerCase())
        )
      );
  }

  /**
   * Add a share for an existing user
   */
  async addUserShare(templateId: string, targetUserId: string, access: "use" | "edit") {
    const [share] = await db
      .insert(templateShares)
      .values({
        templateId,
        userId: targetUserId,
        access,
      })
      .onConflictDoNothing()
      .returning();

    return share;
  }

  /**
   * Add a pending share by email (for users not yet in the system)
   */
  async addEmailInvite(templateId: string, email: string, access: "use" | "edit") {
    const [share] = await db
      .insert(templateShares)
      .values({
        templateId,
        pendingEmail: email.toLowerCase(),
        access,
      })
      .onConflictDoNothing()
      .returning();

    return share;
  }

  /**
   * Accept pending email invites when a user logs in
   * Converts pendingEmail shares to userId shares
   */
  async acceptPendingForUser(userId: string, email: string) {
    return db
      .update(templateShares)
      .set({
        userId,
        acceptedAt: sql`now()`,
        pendingEmail: null,
      })
      .where(
        and(
          eq(templateShares.pendingEmail, email.toLowerCase()),
          isNull(templateShares.userId)
        )
      )
      .returning();
  }

  /**
   * Update access level for a share
   */
  async updateAccess(shareId: string, access: "use" | "edit") {
    const [share] = await db
      .update(templateShares)
      .set({ access })
      .where(eq(templateShares.id, shareId))
      .returning();

    return share;
  }

  /**
   * Revoke a share (delete it)
   */
  async revoke(shareId: string) {
    await db.delete(templateShares).where(eq(templateShares.id, shareId));
    return true;
  }

  /**
   * Check if a user has access to a template and what level
   */
  async getAccessLevel(templateId: string, userId: string, userEmail: string): Promise<"use" | "edit" | null> {
    const [share] = await db
      .select({
        access: templateShares.access,
      })
      .from(templateShares)
      .where(
        and(
          eq(templateShares.templateId, templateId),
          or(
            eq(templateShares.userId, userId),
            eq(templateShares.pendingEmail, userEmail.toLowerCase())
          )
        )
      )
      .limit(1);

    return share?.access ?? null;
  }

  /**
   * Check if a share exists for a template and user/email
   */
  async findByTemplateAndUser(
    templateId: string,
    userId?: string,
    email?: string
  ) {
    const conditions = [eq(templateShares.templateId, templateId)];

    if (userId) {
      conditions.push(eq(templateShares.userId, userId));
    }

    if (email) {
      conditions.push(eq(templateShares.pendingEmail, email.toLowerCase()));
    }

    const [share] = await db
      .select()
      .from(templateShares)
      .where(and(...conditions))
      .limit(1);

    return share;
  }
}

import { eq, sql, count, getTableColumns } from "drizzle-orm";

import { users, workflows, type User, type UpsertUser } from "@shared/schema";

import { db } from "../db";
import { logger } from "../logger";

import { BaseRepository, type DbTransaction } from "./BaseRepository";

/**
 * Repository for user-related database operations
 * Handles Google OAuth user management
 */
export class UserRepository extends BaseRepository<typeof users, User, UpsertUser> {
  constructor() {
    super(users);
  }

  /**
   * Find user by email address
   */
  async findByEmail(email: string, tx?: DbTransaction): Promise<User | undefined> {
    const database = this.getDb(tx);
    const [user] = await database
      .select()
      .from(users)
      .where(eq(users.email, email));
    return user;
  }

  /**
   * Upsert user (create or update based on email)
   * Used for Google OAuth authentication
   * IMPORTANT: Only updates fields provided in userData to preserve existing fields like 'role'
   */
  async upsert(userData: UpsertUser, tx?: DbTransaction): Promise<User> {
    const database = this.getDb(tx);

    try {
      // First, try to find existing user by email
      if (userData.email) {
        const existingUser = await this.findByEmail(userData.email, tx);

        if (existingUser) {
          // Update existing user with new data, but only update provided fields
          // This preserves fields like 'role' that aren't included in Google OAuth userData
          const updateData: any = {
            updatedAt: new Date(),
          };

          // Only include fields that are explicitly provided
          if (userData.firstName !== undefined) { updateData.firstName = userData.firstName; }
          if (userData.lastName !== undefined) { updateData.lastName = userData.lastName; }
          if (userData.profileImageUrl !== undefined) { updateData.profileImageUrl = userData.profileImageUrl; }
          // Update auth provider and verification status if provided (e.g. linking Google account)
          if (userData.authProvider) { updateData.authProvider = userData.authProvider; }
          if (userData.emailVerified !== undefined) { updateData.emailVerified = userData.emailVerified; }

          // DEV FIX: In development, force update tenantRole to 'owner' if provided
          // This ensures developers are not stuck as 'viewer'
          if (process.env.NODE_ENV === 'development' && userData.tenantRole === 'owner') {
            updateData.tenantRole = 'owner';
          }

          // Note: We intentionally don't update email or role here to preserve existing values

          const [updatedUser] = await database
            .update(users)
            .set(updateData)
            .where(eq(users.email, userData.email))
            .returning();
          return updatedUser;
        }
      }

      // If no existing user found, insert new user
      // Handle conflict on ID in case it's provided and already exists
      const [user] = await database
        .insert(users)
        .values(userData as any)
        .onConflictDoUpdate({
          target: users.id,
          set: {
            firstName: userData.firstName,
            lastName: userData.lastName,
            profileImageUrl: userData.profileImageUrl,
            updatedAt: new Date(),
          },
        })
        .returning();

      // Legacy systemStats tracking removed (survey system deprecated Nov 2025)
      // systemStats table no longer exists in schema
      try {
        const { systemStatsRepository } = await import("./SystemStatsRepository");
        await systemStatsRepository.incrementUsersCreated();
      } catch (e) {
        logger.warn({ err: e }, "Failed to increment user stats");
      }

      return user;
    } catch (error) {
      // If we still get a constraint violation, it could be due to race conditions
      // Try to find the existing user again and update
      if (error instanceof Error && error.message.includes('duplicate key') && userData.email) {
        const existingUser = await this.findByEmail(userData.email, tx);

        if (existingUser) {
          // Only update provided fields to preserve existing role
          const updateData: any = {
            updatedAt: new Date(),
          };

          if (userData.firstName !== undefined) { updateData.firstName = userData.firstName; }
          if (userData.lastName !== undefined) { updateData.lastName = userData.lastName; }
          if (userData.profileImageUrl !== undefined) { updateData.profileImageUrl = userData.profileImageUrl; }

          const [updatedUser] = await database
            .update(users)
            .set(updateData)
            .where(eq(users.email, userData.email))
            .returning();
          return updatedUser;
        }
      }

      // If we can't handle the error, re-throw it
      throw error;
    }
  }

  /**
   * Get all users (admin only)
   */
  async findAllUsers(tx?: DbTransaction): Promise<User[]> {
    const database = this.getDb(tx);
    return database
      .select()
      .from(users)
      .orderBy(users.createdAt);
  }

  /**
   * Get all users with their workflow count (admin only)
   * Optimized to use a single query with LEFT JOIN instead of fetching all workflows
   */
  async findAllUsersWithWorkflowCounts(tx?: DbTransaction): Promise<(User & { workflowCount: number })[]> {
    const database = this.getDb(tx);

    // Select all user columns plus the count of workflows
    const rows = await database
      .select({
        ...getTableColumns(users),
        workflowCount: count(workflows.id),
      })
      .from(users)
      .leftJoin(workflows, eq(users.id, workflows.creatorId))
      .groupBy(users.id)
      .orderBy(users.createdAt);

    return rows.map(row => ({
      ...row,
      workflowCount: Number(row.workflowCount)
    }));
  }

  /**
   * Get user statistics (admin only)
   * Optimized to use a single query instead of fetching all users
   */
  async getUserStats(tx?: DbTransaction) {
    const database = this.getDb(tx);
    const { systemStatsRepository } = await import("./SystemStatsRepository");

    // Run queries in parallel
    const [stats, systemStats] = await Promise.all([
      database
        .select({
          admins: sql<number>`sum(case when ${users.role} = 'admin' then 1 else 0 end)`,
          creators: sql<number>`sum(case when ${users.role} = 'creator' then 1 else 0 end)`,
        })
        .from(users),
      systemStatsRepository.getStats()
    ]);

    return {
      total: systemStats.totalUsersCreated, // Use lifetime total
      active: Number(stats[0]?.admins || 0) + Number(stats[0]?.creators || 0), // Optional: tracked active users
      admins: Number(stats[0]?.admins || 0),
      creators: Number(stats[0]?.creators || 0),
    };
  }

  /**
   * Update user role (admin only)
   */
  async updateRole(userId: string, role: 'admin' | 'creator', tx?: DbTransaction): Promise<User> {
    const database = this.getDb(tx);
    const [updatedUser] = await database
      .update(users)
      .set({ role, updatedAt: new Date() })
      .where(eq(users.id, userId))
      .returning();

    if (!updatedUser) {
      throw new Error('User not found');
    }

    return updatedUser;
  }

  /**
   * Update user fields
   */
  async updateUser(userId: string, data: Partial<User>, tx?: DbTransaction): Promise<User> {
    const database = this.getDb(tx);
    const updateData: any = { ...data, updatedAt: new Date() };

    // Remove undefined fields
    Object.keys(updateData).forEach(key => updateData[key] === undefined && delete updateData[key]);

    const [updatedUser] = await database
      .update(users)
      .set(updateData)
      .where(eq(users.id, userId))
      .returning();

    if (!updatedUser) {
      throw new Error('User not found');
    }

    return updatedUser;
  }

  /**
   * Check database connectivity
   */
  async ping(): Promise<boolean> {
    try {
      await db.execute(sql`SELECT 1`);
      return true;
    } catch (error) {
      logger.error({ err: error }, 'Database ping failed');
      return false;
    }
  }
}

