            res.status(500).json({ message: "Failed to fetch AI settings" });
        }
    }));
    /**
     * PUT /api/admin/ai-settings
     * Update global AI settings
     */
    app.put('/api/admin/ai-settings', hybridAuth, isAdmin, asyncHandler(async (req: Request, res: Response) => {
        try {
            if (!req.adminUser) {
                return res.status(401).json({ message: "Unauthorized" });
            }
            const { systemPrompt } = req.body;
            if (!systemPrompt || typeof systemPrompt !== 'string' || systemPrompt.length < 10) {
                return res.status(400).json({ message: "Invalid system prompt. Must be a string of at least 10 characters." });
            }
            const updated = await aiSettingsService.updateGlobalSettings(systemPrompt, req.adminUser.id);
            logger.info(
                { adminId: req.adminUser.id, promptLength: systemPrompt.length },
                'Admin updated global AI settings'
            );
            res.json(updated);
        } catch (error) {
            logger.error({ err: error, adminId: req.adminUser!.id }, 'Error updating AI settings');
            res.status(500).json({ message: "Failed to update AI settings" });
        }
    }));
    /**
     * GET /api/admin/ai-settings/feedback/stats
     * Get global AI feedback statistics (admin only)
     */
    app.get('/api/admin/ai-settings/feedback/stats', hybridAuth, isAdmin, asyncHandler(async (req: Request, res: Response) => {
        try {
            if (!req.adminUser) {
                return res.status(401).json({ message: "Unauthorized" });
            }
            const { days = '30', operationType } = req.query;
            const daysAgo = new Date();
            daysAgo.setDate(daysAgo.getDate() - parseInt(days as string));
            // Build query conditions
            const conditions = [gte(aiWorkflowFeedback.createdAt, daysAgo)];
            if (operationType && typeof operationType === 'string') {
                conditions.push(eq(aiWorkflowFeedback.operationType, operationType));
            }
            // Get all feedback matching conditions
            const allFeedback = await db
                .select()
                .from(aiWorkflowFeedback)
                .where(and(...conditions))
                .orderBy(desc(aiWorkflowFeedback.createdAt));
            // Calculate statistics
            const totalFeedback = allFeedback.length;
            const avgRating = totalFeedback > 0
                ? allFeedback.reduce((sum, f) => sum + f.rating, 0) / totalFeedback
                : 0;
            const avgQualityScore = allFeedback.filter(f => f.qualityScore !== null).length > 0
                ? allFeedback
                    .filter(f => f.qualityScore !== null)
                    .reduce((sum, f) => sum + (f.qualityScore || 0), 0) / allFeedback.filter(f => f.qualityScore !== null).length
                : 0;
            const qualityPassRate = allFeedback.filter(f => f.qualityPassed !== null).length > 0
                ? (allFeedback.filter(f => f.qualityPassed === true).length / allFeedback.filter(f => f.qualityPassed !== null).length) * 100
                : 0;
            const ratingDistribution = {
                5: allFeedback.filter(f => f.rating === 5).length,
                4: allFeedback.filter(f => f.rating === 4).length,
                3: allFeedback.filter(f => f.rating === 3).length,
                2: allFeedback.filter(f => f.rating === 2).length,
                1: allFeedback.filter(f => f.rating === 1).length,
            };
            // Group by operation type
            const byOperationType = allFeedback.reduce((acc, f) => {
                if (!acc[f.operationType]) {
                    acc[f.operationType] = { count: 0, totalRating: 0, totalQualityScore: 0, qualityScoreCount: 0 };
                }
                acc[f.operationType].count++;
                acc[f.operationType].totalRating += f.rating;
                if (f.qualityScore !== null) {
                    acc[f.operationType].totalQualityScore += f.qualityScore;
                    acc[f.operationType].qualityScoreCount++;
                }
                return acc;
            }, {} as Record<string, { count: number; totalRating: number; totalQualityScore: number; qualityScoreCount: number }>);
            // Calculate averages for each operation type
            const operationTypeStats = Object.entries(byOperationType).map(([type, stats]) => ({
                operationType: type,
                count: stats.count,
                avgRating: stats.totalRating / stats.count,
                avgQualityScore: stats.qualityScoreCount > 0 ? stats.totalQualityScore / stats.qualityScoreCount : null,
            }));
            // Group by AI provider
            const byProvider = allFeedback
                .filter(f => f.aiProvider)
                .reduce((acc, f) => {
                    const provider = f.aiProvider!;
                    if (!acc[provider]) {
                        acc[provider] = { count: 0, totalRating: 0, totalQualityScore: 0, qualityScoreCount: 0 };
                    }
                    acc[provider].count++;
                    acc[provider].totalRating += f.rating;
                    if (f.qualityScore !== null) {
                        acc[provider].totalQualityScore += f.qualityScore;
                        acc[provider].qualityScoreCount++;
                    }
                    return acc;
                }, {} as Record<string, { count: number; totalRating: number; totalQualityScore: number; qualityScoreCount: number }>);
            const providerStats = Object.entries(byProvider).map(([provider, stats]) => ({
                provider,
                count: stats.count,
                avgRating: stats.totalRating / stats.count,
                avgQualityScore: stats.qualityScoreCount > 0 ? stats.totalQualityScore / stats.qualityScoreCount : null,
            }));
            // Time series data (daily)
            const dailyStats = allFeedback.reduce((acc, f) => {
                if (!f.createdAt) { return acc; }
                const date = f.createdAt.toISOString().split('T')[0];
                if (!acc[date]) {
                    acc[date] = { date, count: 0, totalRating: 0, totalQualityScore: 0, qualityScoreCount: 0 };
                }
                acc[date].count++;
                acc[date].totalRating += f.rating;
                if (f.qualityScore !== null) {
                    acc[date].totalQualityScore += f.qualityScore;
                    acc[date].qualityScoreCount++;
                }
                return acc;
            }, {} as Record<string, { date: string; count: number; totalRating: number; totalQualityScore: number; qualityScoreCount: number }>);
            const timeSeriesData = Object.values(dailyStats)
                .map(day => ({
                    date: day.date,
                    count: day.count,
                    avgRating: day.totalRating / day.count,
                    avgQualityScore: day.qualityScoreCount > 0 ? day.totalQualityScore / day.qualityScoreCount : null,
                }))
                .sort((a, b) => a.date.localeCompare(b.date));
            res.json({
                success: true,
                stats: {
                    totalFeedback,
                    avgRating: Math.round(avgRating * 10) / 10,
                    avgQualityScore: Math.round(avgQualityScore * 10) / 10,
                    qualityPassRate: Math.round(qualityPassRate * 10) / 10,
                    ratingDistribution,
                    byOperationType: operationTypeStats,
                    byProvider: providerStats,
                    timeSeries: timeSeriesData,
                    period: `${days} days`,
                },
            });
        } catch (error: any) {
            logger.error({ error }, 'Failed to get admin AI feedback stats');
            res.status(500).json({
                success: false,
                message: 'Failed to get feedback statistics',
            });
        }
    }));
    /**
     * GET /api/admin/ai-settings/feedback/recent
     * Get recent AI feedback entries with details (admin only)
     */
    app.get('/api/admin/ai-settings/feedback/recent', hybridAuth, isAdmin, asyncHandler(async (req: Request, res: Response) => {
        try {
            if (!req.adminUser) {
                return res.status(401).json({ message: "Unauthorized" });
            }
            const { limit = '50', operationType, minRating, maxRating } = req.query;
            // Build query conditions
            const conditions = [];
            if (operationType && typeof operationType === 'string') {
                conditions.push(eq(aiWorkflowFeedback.operationType, operationType));
            }
            const recentFeedback = await db
                .select({
                    id: aiWorkflowFeedback.id,
                    workflowId: aiWorkflowFeedback.workflowId,
                    userId: aiWorkflowFeedback.userId,
                    operationType: aiWorkflowFeedback.operationType,
                    rating: aiWorkflowFeedback.rating,
                    comment: aiWorkflowFeedback.comment,
                    aiProvider: aiWorkflowFeedback.aiProvider,
                    aiModel: aiWorkflowFeedback.aiModel,
                    qualityScore: aiWorkflowFeedback.qualityScore,
                    qualityPassed: aiWorkflowFeedback.qualityPassed,
                    issuesCount: aiWorkflowFeedback.issuesCount,
                    requestDescription: aiWorkflowFeedback.requestDescription,
                    createdAt: aiWorkflowFeedback.createdAt,
                })
                .from(aiWorkflowFeedback)
                .where(conditions.length > 0 ? and(...conditions) : undefined)
                .orderBy(desc(aiWorkflowFeedback.createdAt))
                .limit(parseInt(limit as string));
            // Apply rating filters in memory (easier than complex SQL)
            let filtered = recentFeedback;
            if (minRating) {
                filtered = filtered.filter(f => f.rating >= parseInt(minRating as string));
            }
            if (maxRating) {
                filtered = filtered.filter(f => f.rating <= parseInt(maxRating as string));
            }
            res.json({
                success: true,
                feedback: filtered,
            });
        } catch (error: any) {
            logger.error({ error }, 'Failed to get recent AI feedback');
            res.status(500).json({
                success: false,
                message: 'Failed to get recent feedback',
            });
        }
    }));
}

import { logger } from '../logger';
import { isAdmin } from '../middleware/adminAuth';
import { hybridAuth } from '../middleware/auth';
import { placeholderUserCleanupService } from '../services/PlaceholderUserCleanupService';
import { asyncHandler } from '../utils/asyncHandler';

import type { Express, Request, Response } from 'express';

/**
 * Admin Cleanup Routes
 * Provides endpoints for running cleanup jobs
 */
export function registerAdminCleanupRoutes(app: Express): void {
  /**
   * POST /api/admin/cleanup/placeholder-users
   * Clean up placeholder users with no pending invites
   * Admin only
   */
  app.post('/api/admin/cleanup/placeholder-users', hybridAuth, isAdmin, asyncHandler(async (req: Request, res: Response) => {
    try {
      const adminUser = (req as any).adminUser;
      if (!adminUser) {
        return res.status(401).json({ message: 'Unauthorized' });
      }

      const deletedCount = await placeholderUserCleanupService.cleanupExpiredPlaceholders();

      logger.info({ adminId: adminUser.id, email: adminUser.email, deletedCount }, 'Admin executed placeholder user cleanup');

      res.json({
        message: 'Placeholder user cleanup completed',
        deletedCount,
      });
    } catch (error) {
      logger.error({ error, adminId: (req as any).adminUser?.id }, 'Error running placeholder cleanup');
      res.status(500).json({
        message: 'Failed to run placeholder user cleanup',
        error: process.env.NODE_ENV === 'development' && error instanceof Error ? error.message : undefined,
      });
    }
  }));

  /**
   * GET /api/admin/cleanup/placeholder-users/stats
   * Get statistics about placeholder users
   * Admin only
   */
  app.get('/api/admin/cleanup/placeholder-users/stats', hybridAuth, isAdmin, asyncHandler(async (req: Request, res: Response) => {
    try {
      const adminUser = (req as any).adminUser;
      if (!adminUser) {
        return res.status(401).json({ message: 'Unauthorized' });
      }

      const stats = await placeholderUserCleanupService.getPlaceholderStats();

      logger.info({ adminId: adminUser.id, email: adminUser.email }, 'Admin fetched placeholder user stats');

      res.json(stats);
    } catch (error) {
      logger.error({ error, adminId: (req as any).adminUser?.id }, 'Error getting placeholder stats');
      res.status(500).json({
        message: 'Failed to get placeholder user statistics',
        error: process.env.NODE_ENV === 'development' && error instanceof Error ? error.message : undefined,
      });
    }
  }));
}

import { createLogger } from "../logger";
import { isAdmin } from "../middleware/adminAuth";
import { hybridAuth } from "../middleware/auth";
import { userRepository } from "../repositories/UserRepository";
import { WorkflowRepository } from "../repositories/WorkflowRepository";
import { WorkflowRunRepository } from "../repositories/WorkflowRunRepository";
import { accountLockoutService } from "../services/AccountLockoutService";
import { ActivityLogService } from "../services/ActivityLogService";
import { mfaService } from "../services/MfaService";
import { asyncHandler } from "../utils/asyncHandler";

import type { Express, Request, Response } from "express";

const logger = createLogger({ module: 'admin-routes' });
const activityLogService = new ActivityLogService();

/**
 * Register admin-only routes
 * These routes require admin role for access
 *
 * NOTE: Refactored from survey-based to workflow-based (Nov 2025)
 */
export function registerAdminRoutes(app: Express): void {
  const workflowRepository = new WorkflowRepository();
  const workflowRunRepository = new WorkflowRunRepository();

  // ============================================================================
  // User Management
  // ============================================================================

  /**
   * GET /api/admin/users
   * Get all users in the system
   */
  app.get('/api/admin/users', hybridAuth, isAdmin, asyncHandler(async (req: Request, res: Response) => {
    try {
      if (!req.adminUser) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      // Use optimized query to get users and workflow counts in one go
      const usersWithStats = await userRepository.findAllUsersWithWorkflowCounts();

      logger.info(
        { adminId: req.adminUser.id, userCount: usersWithStats.length },
        'Admin fetched all users'
      );

      res.json(usersWithStats);
    } catch (error) {
      logger.error({ err: error, adminId: req.adminUser!.id }, 'Error fetching all users');
      res.status(500).json({ message: "Failed to fetch users" });
    }
  }));

  /**
   * PUT /api/admin/users/:userId/role
   * Update user role (promote/demote admin)
   */
  app.put('/api/admin/users/:userId/role', hybridAuth, isAdmin, asyncHandler(async (req: Request, res: Response) => {
    try {
      if (!req.adminUser) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      const { userId } = req.params;
      const { role } = req.body;

      if (!role || (role !== 'admin' && role !== 'creator')) {
        return res.status(400).json({
          message: "Invalid role. Must be 'admin' or 'creator'"
        });
      }

      // Prevent self-demotion
      if (userId === req.adminUser.id && role === 'creator') {
        return res.status(400).json({
          message: "You cannot demote yourself from admin"
        });
      }

      // Critical: Prevent demoting the last admin
      if (role === 'creator') {
        const allUsers = await userRepository.findAllUsers();
        const adminCount = allUsers.filter(u => u.role === 'admin').length;

        // Check if the user being demoted is currently an admin
        const targetUser = allUsers.find(u => u.id === userId);
        if (targetUser?.role === 'admin' && adminCount <= 1) {
          return res.status(400).json({
            message: "Cannot demote the last admin. Promote another user to admin first."
          });
        }
      }

      const updatedUser = await userRepository.updateRole(userId, role);

      logger.info(
        {
          adminId: req.adminUser.id,
          targetUserId: userId,
          newRole: role,
          oldRole: role === 'admin' ? 'creator' : 'admin'
        },
        `Admin ${role === 'admin' ? 'promoted' : 'demoted'} user`
      );

      res.json({
        message: `User ${role === 'admin' ? 'promoted to admin' : 'demoted to creator'}`,
        user: updatedUser
      });
    } catch (error) {
      logger.error(
        { err: error, adminId: req.adminUser!.id, userId: req.params.userId },
        'Error updating user role'
      );

      if (error instanceof Error && error.message === 'User not found') {
        return res.status(404).json({ message: "User not found" });
      }

      res.status(500).json({ message: "Failed to update user role" });
    }
  }));

  /**
   * POST /api/admin/users/:userId/unlock
   * Unlock a locked user account
   */
  app.post('/api/admin/users/:userId/unlock', hybridAuth, isAdmin, asyncHandler(async (req: Request, res: Response) => {
    try {
      if (!req.adminUser) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      const { userId } = req.params;

      // Verify user exists
      const user = await userRepository.findById(userId);
      if (!user) {
        return res.status(404).json({ message: "User not found" });
      }

      // Check if account is actually locked
      const lockStatus = await accountLockoutService.isAccountLocked(userId);
      if (!lockStatus.locked) {
        return res.status(400).json({
          message: "Account is not currently locked"
        });
      }

      // Unlock the account
      await accountLockoutService.unlockAccount(userId);

      logger.info(
        {
          adminId: req.adminUser.id,
          targetUserId: userId,
          targetEmail: user.email
        },
        'Admin unlocked user account'
      );

      res.json({
        message: "Account unlocked successfully",
        user: {
          id: user.id,
          email: user.email
        }
      });
    } catch (error) {
      logger.error(
        { err: error, adminId: req.adminUser!.id, userId: req.params.userId },
        'Error unlocking user account'
      );
      res.status(500).json({ message: "Failed to unlock account" });
    }
  }));

  /**
   * POST /api/admin/users/:userId/reset-mfa
   * Reset MFA for a user (for locked out users)
   */
  app.post('/api/admin/users/:userId/reset-mfa', hybridAuth, isAdmin, asyncHandler(async (req: Request, res: Response) => {
    try {
      if (!req.adminUser) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      const { userId } = req.params;

      // Verify user exists
      const user = await userRepository.findById(userId);
      if (!user) {
        return res.status(404).json({ message: "User not found" });
      }

      // Check if user has MFA enabled
      if (!user.mfaEnabled) {
        return res.status(400).json({
          message: "User does not have MFA enabled"
        });
      }

      // Reset MFA (disables and deletes all MFA data)
      await mfaService.adminResetMfa(userId);

      logger.warn(
        {
          adminId: req.adminUser.id,
          targetUserId: userId,
          targetEmail: user.email
        },
        'Admin reset user MFA'
      );

      res.json({
        message: "MFA reset successfully. User can now log in without MFA.",
        user: {
          id: user.id,
          email: user.email
        }
      });
    } catch (error) {
      logger.error(
        { err: error, adminId: req.adminUser!.id, userId: req.params.userId },
        'Error resetting user MFA'
      );
      res.status(500).json({ message: "Failed to reset MFA" });
    }
  }));

  /**
   * GET /api/admin/users/:userId/workflows
   * Get all workflows for a specific user
   */
  app.get('/api/admin/users/:userId/workflows', hybridAuth, isAdmin, asyncHandler(async (req: Request, res: Response) => {
    try {
      if (!req.adminUser) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      const { userId } = req.params;

      // Verify user exists
      const user = await userRepository.findById(userId);
      if (!user) {
        return res.status(404).json({ message: "User not found" });
      }

      const workflows = await workflowRepository.findByCreatorId(userId);

      logger.info(
        { adminId: req.adminUser.id, targetUserId: userId, workflowCount: workflows.length },
        'Admin fetched user workflows'
      );

      res.json({
        user: {
          id: user.id,
          email: user.email,
          firstName: user.firstName,
          lastName: user.lastName,
        },
        workflows
      });
    } catch (error) {
      logger.error(
        { err: error, adminId: req.adminUser!.id, userId: req.params.userId },
        'Error fetching user workflows'
      );
      res.status(500).json({ message: "Failed to fetch user workflows" });
    }
  }));

  // ============================================================================
  // Workflow Management (Admin can view/edit any workflow)
  // ============================================================================

  /**
   * GET /api/admin/workflows
   * Get all workflows in the system
   */
  app.get('/api/admin/workflows', hybridAuth, isAdmin, asyncHandler(async (req: Request, res: Response) => {
    try {
      if (!req.adminUser) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      // Get all users first (for mapping creators)
      const users = await userRepository.findAllUsers();
      const userMap = new Map(users.map(u => [u.id, u]));

      // Get all workflows directly
      const allWorkflows = await workflowRepository.findAll();

      const workflowsWithCreators = allWorkflows.map((workflow) => {
        const user = workflow.creatorId ? userMap.get(workflow.creatorId) : null;
        return {
          ...workflow,
          creator: user ? {
            id: user.id,
            email: user.email,
            firstName: user.firstName,
            lastName: user.lastName,
          } : {
            id: 'unknown',
            email: 'deleted-user@example.com',
            firstName: 'Deleted',
            lastName: 'User'
          }
        };
      });

      logger.info(
        { adminId: req.adminUser.id, workflowCount: workflowsWithCreators.length },
        'Admin fetched all workflows'
      );

      res.json(workflowsWithCreators);
    } catch (error) {
      logger.error({ err: error, adminId: req.adminUser!.id }, 'Error fetching all workflows');
      res.status(500).json({ message: "Failed to fetch workflows" });
    }
  }));

  /**
   * GET /api/admin/workflows/:workflowId
   * Get any workflow (including full details)
   */
  app.get('/api/admin/workflows/:workflowId', hybridAuth, isAdmin, asyncHandler(async (req: Request, res: Response) => {
    try {
      if (!req.adminUser) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      const workflow = await workflowRepository.findById(req.params.workflowId);

      if (!workflow) {
        return res.status(404).json({ message: "Workflow not found" });
      }

      logger.info(
        { adminId: req.adminUser.id, workflowId: req.params.workflowId },
        'Admin fetched workflow details'
      );

      res.json(workflow);
    } catch (error) {
      logger.error(
        { err: error, adminId: req.adminUser!.id, workflowId: req.params.workflowId },
        'Error fetching workflow'
      );
      res.status(500).json({ message: "Failed to fetch workflow" });
    }
  }));

  /**
   * GET /api/admin/workflows/:workflowId/runs
   * Get all runs for any workflow
   */
  app.get('/api/admin/workflows/:workflowId/runs', hybridAuth, isAdmin, asyncHandler(async (req: Request, res: Response) => {
    try {
      if (!req.adminUser) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      const workflow = await workflowRepository.findById(req.params.workflowId);

      if (!workflow) {
        return res.status(404).json({ message: "Workflow not found" });
      }

      const runs = await workflowRunRepository.findByWorkflowId(req.params.workflowId);

      logger.info(
        { adminId: req.adminUser.id, workflowId: req.params.workflowId, runCount: runs.length },
        'Admin fetched workflow runs'
      );

      res.json(runs);
    } catch (error) {
      logger.error(
        { err: error, adminId: req.adminUser!.id, workflowId: req.params.workflowId },
        'Error fetching workflow runs'
      );
      res.status(500).json({ message: "Failed to fetch runs" });
    }
  }));

  /**
   * DELETE /api/admin/workflows/:workflowId
   * Delete any workflow
   */
  app.delete('/api/admin/workflows/:workflowId', hybridAuth, isAdmin, asyncHandler(async (req: Request, res: Response) => {
    try {
      if (!req.adminUser) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      const workflow = await workflowRepository.findById(req.params.workflowId);

      if (!workflow) {
        return res.status(404).json({ message: "Workflow not found" });
      }

      // Count runs before deletion (they'll be cascade deleted)
      const runs = await workflowRunRepository.findByWorkflowId(req.params.workflowId);
      const runCount = runs.length;

      // Delete the workflow (cascade deletes sections, steps, runs, etc.)
      await workflowRepository.delete(req.params.workflowId);

      logger.warn(
        {
          adminId: req.adminUser.id,
          workflowId: req.params.workflowId,
          workflowTitle: workflow.title,
          deletedRuns: runCount
        },
        'Admin deleted workflow'
      );

      res.json({ message: "Workflow deleted successfully" });
    } catch (error) {
      logger.error(
        { err: error, adminId: req.adminUser!.id, workflowId: req.params.workflowId },
        'Error deleting workflow'
      );
      res.status(500).json({ message: "Failed to delete workflow" });
    }
  }));

  // ============================================================================
  // Admin Dashboard Stats
  // ============================================================================

  /**
   * GET /api/admin/stats
   * Get system-wide statistics
   */
  app.get('/api/admin/stats', hybridAuth, isAdmin, asyncHandler(async (req: Request, res: Response) => {
    try {
      if (!req.adminUser) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      // Fetch stats in parallel for better performance
      const [userStats, workflowStats, runStats] = await Promise.all([
        userRepository.getUserStats(),
        workflowRepository.getWorkflowStats(),
        workflowRunRepository.getRunStats()
      ]);

      const stats = {
        totalUsers: userStats.total,
        adminUsers: userStats.admins,
        creatorUsers: userStats.creators,
        totalWorkflows: workflowStats.total,
        activeWorkflows: workflowStats.active,
        draftWorkflows: workflowStats.draft,
        archivedWorkflows: workflowStats.archived,
        totalRuns: runStats.total,
        completedRuns: runStats.completed,
        inProgressRuns: runStats.inProgress,
      };

      logger.info({ adminId: req.adminUser.id }, "Admin fetched system stats");

      res.json(stats);
    } catch (error) {
      logger.error({ err: error, adminId: req.adminUser!.id }, "Error fetching admin stats");
      res.status(500).json({ message: "Failed to fetch statistics" });
    }
  }));

  // ============================================================================
  // Activity Logs
  // ============================================================================

  /**
   * GET /api/admin/logs
