        secure: process.env.NODE_ENV === 'production',
        sameSite: 'strict',
        path: '/',
        maxAge: 60 * 60 * 24 * 30
      }));
      logger.info({ userId: user.id, email: user.email }, 'User registered');
      res.status(201).json({
