router.post('/', requireAuth, asyncHandler(async (req, res) => {
    try {
        const { name, description, sourceWorkflowId, metadata, isPublic } = req.body;

        if (!name || !sourceWorkflowId) {
            res.status(400).json({ error: "Name and Source Workflow ID are required" });
            return;
        }

        const template = await templateService.createFromWorkflow({
            name,
            description,
            sourceWorkflowId,
            creatorId: req.user!.id as string,
            tenantId: req.user?.tenantId || 'default-tenant',
            metadata,
            isPublic
        });

        res.json({ data: template });
    } catch (error) {
        logger.error({ error }, 'Create blueprint error');
        res.status(500).json({ error: error instanceof Error ? error.message : 'Failed to create blueprint' });
    }
}));

// Instantiate blueprint
router.post('/:id/instantiate', requireAuth, asyncHandler(async (req, res) => {
    try {
        const { id } = req.params;
        const { projectId, name } = req.body;

        // if (!projectId) {
        //     return res.status(400).json({ error: "Target Project ID is required" });
        // }

        const result = await templateService.instantiate({
            templateId: id,
            projectId,
            userId: req.user!.id as string,
            tenantId: req.user?.tenantId || 'default-tenant',
            name
        });

        res.json({ data: result });
    } catch (error) {
        logger.error({ error }, 'Instantiate blueprint error');
        res.status(500).json({ error: error instanceof Error ? error.message : 'Failed to instantiate blueprint' });
    }
}));

export function registerBlueprintRoutes(app: Express) {
    app.use('/api/blueprints', router);
}

import { z } from 'zod';

import { partialTenantBrandingSchema } from '@shared/types/branding';

import { createLogger } from '../logger';
import { hybridAuth } from '../middleware/auth';
import { requirePermission } from '../middleware/rbac';
import { validateTenantParam } from '../middleware/tenant';
import { brandingService } from '../services/BrandingService';
import { asyncHandler } from '../utils/asyncHandler';

import type { Express, Request, Response } from 'express';
const logger = createLogger({ module: 'branding-routes' });
/**
 * Stage 17: Branding & Tenant Customization Routes
 *
 * Provides APIs for:
 * - Tenant branding configuration (logo, colors, text)
 * - Custom domain management
 */
export function registerBrandingRoutes(app: Express): void {
  // =====================================================================
  // BRANDING ENDPOINTS
  // =====================================================================
  /**
   * GET /api/tenants/:tenantId/branding
   * Get tenant branding configuration
   */
  app.get(
    '/api/tenants/:tenantId/branding',
    hybridAuth,
    validateTenantParam,
    asyncHandler(async (req: Request, res: Response) => {
      try {
        const { tenantId } = req.params;
        const branding = await brandingService.getBrandingByTenantId(tenantId);
        res.json({
          branding: branding ?? null,
        });
      } catch (error) {
        logger.error({ error }, 'Failed to fetch tenant branding');
        res.status(500).json({
          message: 'Failed to fetch branding',
          error: 'internal_error',
        });
      }
    })
  );
  /**
   * PATCH /api/tenants/:tenantId/branding
   * Update tenant branding configuration (owner/builder only)
   */
  app.patch(
    '/api/tenants/:tenantId/branding',
    hybridAuth,
    validateTenantParam,
    requirePermission('tenant:update' as any),
    asyncHandler(async (req: Request, res: Response) => {
      try {
        const { tenantId } = req.params;
        // Validate request body
        const validationResult = partialTenantBrandingSchema.safeParse(req.body);
        if (!validationResult.success) {
          res.status(400).json({
            message: 'Invalid branding data',
            error: 'validation_error',
            details: validationResult.error.errors,
          });
          return;
        }
        const updatedBranding = await brandingService.updateBranding(
          tenantId,
          validationResult.data
        );
        logger.info({ tenantId }, 'Tenant branding updated');
        res.json({
          message: 'Branding updated successfully',
          branding: updatedBranding,
        });
      } catch (error) {
        logger.error({ error }, 'Failed to update tenant branding');
        res.status(500).json({
          message: 'Failed to update branding',
          error: 'internal_error',
        });
      }
    })
  );
  // =====================================================================
  // DOMAIN ENDPOINTS
  // =====================================================================
  /**
   * GET /api/tenants/:tenantId/domains
   * Get all custom domains for a tenant
   */
  app.get(
    '/api/tenants/:tenantId/domains',
    hybridAuth,
    validateTenantParam,
    asyncHandler(async (req: Request, res: Response) => {
      try {
        const { tenantId } = req.params;
        const domains = await brandingService.getDomainsByTenantId(tenantId);
        res.json({
          domains,
          total: domains.length,
        });
      } catch (error) {
        logger.error({ error }, 'Failed to fetch tenant domains');
        res.status(500).json({
          message: 'Failed to fetch domains',
          error: 'internal_error',
        });
      }
    })
  );
  /**
   * POST /api/tenants/:tenantId/domains
   * Add a custom domain to a tenant (owner/builder only)
   */
  app.post(
    '/api/tenants/:tenantId/domains',
    hybridAuth,
    validateTenantParam,
    requirePermission('tenant:update' as any),
    asyncHandler(async (req: Request, res: Response) => {
      try {
        const { tenantId } = req.params;
        // Validate request body
        const createTenantDomainSchema = z.object({
          domain: z.string().min(1) // Assuming schema structure or defining locally if import fails? No, import should work.
        });
        // Actually, importing schema is better. Line 1 imports it.
        // Assuming req.body matches schema. I'll rely on original logic unless I see it.
        // Original: const validationResult = createTenantDomainSchema.safeParse(req.body);
        // Correct.
        const validationResult = createTenantDomainSchema.safeParse(req.body);
        if (!validationResult.success) {
          res.status(400).json({
            message: 'Invalid domain data',
            error: 'validation_error',
            details: validationResult.error.errors,
          });
          return;
        }
        const { domain } = validationResult.data;
        // Check if domain is available
        const isAvailable = await brandingService.isDomainAvailable(domain);
        if (!isAvailable) {
          res.status(409).json({
            message: 'Domain already exists',
            error: 'domain_exists',
          });
          return;
        }
        const newDomain = await brandingService.addDomain(tenantId, domain);
        logger.info({ tenantId, domain }, 'Custom domain added');
        res.status(201).json({
          message: 'Domain added successfully',
          domain: newDomain,
        });
      } catch (error: any) {
        if (error.message === 'Domain already exists') {
          res.status(409).json({
            message: 'Domain already exists',
            error: 'domain_exists',
          });
          return;
        }
        logger.error({ error }, 'Failed to add domain');
        res.status(500).json({
          message: 'Failed to add domain',
          error: 'internal_error',
        });
      }
    })
  );
  /**
   * DELETE /api/tenants/:tenantId/domains/:domainId
   * Remove a custom domain from a tenant (owner/builder only)
   */
  app.delete(
    '/api/tenants/:tenantId/domains/:domainId',
    hybridAuth,
    validateTenantParam,
    requirePermission('tenant:update' as any),
    asyncHandler(async (req: Request, res: Response) => {
      try {
        const { tenantId, domainId } = req.params;
        const success = await brandingService.removeDomain(tenantId, domainId);
        if (!success) {
          res.status(404).json({
            message: 'Domain not found',
            error: 'domain_not_found',
          });
          return;
        }
        logger.info({ tenantId, domainId }, 'Custom domain removed');
        res.json({
          message: 'Domain removed successfully',
        });
      } catch (error: any) {
        if (error.message === 'Domain does not belong to this tenant') {
          res.status(403).json({
            message: 'Domain does not belong to this tenant',
            error: 'forbidden',
          });
          return;
        }
        logger.error({ error }, 'Failed to remove domain');
        res.status(500).json({
          message: 'Failed to remove domain',
          error: 'internal_error',
        });
      }
    })
  );
}

import { z } from 'zod';

import { insertCollectionSchema, insertCollectionFieldSchema, insertRecordSchema } from '@shared/schema';

import { logger } from '../logger';
import { hybridAuth, type AuthRequest } from '../middleware/auth';
import { collectionFieldService } from '../services/CollectionFieldService';
import { collectionService } from '../services/CollectionService';
import { recordService } from '../services/RecordService';
import { asyncHandler } from '../utils/asyncHandler';

import type { Express, Request, Response } from 'express';


/**
 * Register collections/datastore routes
 * Stage 19: Collections/Datastore System
 *
 * Collections are tenant-scoped data tables similar to Airtable bases
 */
export function registerCollectionsRoutes(app: Express): void {
  // ===================================================================
  // COLLECTION ENDPOINTS
  // ===================================================================

  /**
   * GET /api/tenants/:tenantId/collections
   * List all collections for a tenant
   */
  app.get('/api/tenants/:tenantId/collections', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId } = req.params;
      const withStats = req.query.stats === 'true';

      const collections = withStats
        ? await collectionService.listCollectionsWithStats(tenantId)
        : await collectionService.listCollections(tenantId);

      res.json(collections);
    } catch (error) {
      logger.error({ error }, 'Error fetching collections');
      res.status(500).json({ message: 'Failed to fetch collections' });
    }
  }));

  /**
   * POST /api/tenants/:tenantId/collections
   * Create a new collection
   */
  app.post('/api/tenants/:tenantId/collections', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId } = req.params;

      const collectionData = insertCollectionSchema.parse({
        ...req.body,
        tenantId,
      });

      const collection = await collectionService.createCollection(collectionData);
      res.status(201).json(collection);
    } catch (error) {
      logger.error({ error }, 'Error creating collection');

      if (error instanceof z.ZodError) {
        return res.status(400).json({
          message: 'Invalid input',
          errors: error.errors,
        });
      }

      const message = error instanceof Error ? error.message : 'Failed to create collection';
      res.status(500).json({ message });
    }
  }));

  /**
   * GET /api/tenants/:tenantId/collections/:collectionId
   * Get a single collection with optional fields
   */
  app.get('/api/tenants/:tenantId/collections/:collectionId', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId, collectionId } = req.params;
      const includeFields = req.query.fields === 'true';

      const collection = includeFields
        ? await collectionService.getCollectionWithFields(collectionId, tenantId)
        : await collectionService.getCollection(collectionId, tenantId);

      res.json(collection);
    } catch (error) {
      logger.error({ error }, 'Error fetching collection');
      const message = error instanceof Error ? error.message : 'Failed to fetch collection';
      const status = message.includes('not found') ? 404 : message.includes('Access denied') ? 403 : 500;
      res.status(status).json({ message });
    }
  }));

  /**
   * GET /api/tenants/:tenantId/collections/slug/:slug
   * Get collection by slug
   */
  app.get('/api/tenants/:tenantId/collections/slug/:slug', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId, slug } = req.params;

      const collection = await collectionService.getCollectionBySlug(tenantId, slug);

      if (!collection) {
        return res.status(404).json({ message: 'Collection not found' });
      }

      res.json(collection);
    } catch (error) {
      logger.error({ error }, 'Error fetching collection by slug');
      res.status(500).json({ message: 'Failed to fetch collection' });
    }
  }));

  /**
   * PATCH /api/tenants/:tenantId/collections/:collectionId
   * Update a collection
   */
  app.patch('/api/tenants/:tenantId/collections/:collectionId', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId, collectionId } = req.params;

      const updateSchema = z.object({
        name: z.string().min(1).optional(),
        slug: z.string().min(1).optional(),
        description: z.string().nullable().optional(),
      });

      const updateData = updateSchema.parse(req.body);

      const collection = await collectionService.updateCollection(collectionId, tenantId, updateData);
      res.json(collection);
    } catch (error) {
      logger.error({ error }, 'Error updating collection');

      if (error instanceof z.ZodError) {
        return res.status(400).json({
          message: 'Invalid input',
          errors: error.errors,
        });
      }

      const message = error instanceof Error ? error.message : 'Failed to update collection';
      const status = message.includes('not found') ? 404 : message.includes('Access denied') ? 403 : 500;
      res.status(status).json({ message });
    }
  }));

  /**
   * DELETE /api/tenants/:tenantId/collections/:collectionId
   * Delete a collection (cascades to fields and records)
   */
  app.delete('/api/tenants/:tenantId/collections/:collectionId', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId, collectionId } = req.params;

      await collectionService.deleteCollection(collectionId, tenantId);
      res.status(204).send();
    } catch (error) {
      logger.error({ error }, 'Error deleting collection');
      const message = error instanceof Error ? error.message : 'Failed to delete collection';
      const status = message.includes('not found') ? 404 : message.includes('Access denied') ? 403 : 500;
      res.status(status).json({ message });
    }
  }));

  // ===================================================================
  // COLLECTION FIELD ENDPOINTS
  // ===================================================================

  /**
   * GET /api/tenants/:tenantId/collections/:collectionId/fields
   * List all fields in a collection
   */
  app.get('/api/tenants/:tenantId/collections/:collectionId/fields', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId, collectionId } = req.params;

      // Verify collection ownership first
      await collectionService.verifyTenantOwnership(collectionId, tenantId);

      const fields = await collectionFieldService.listFields(collectionId);
      res.json(fields);
    } catch (error) {
      logger.error({ error }, 'Error fetching fields');
      const message = error instanceof Error ? error.message : 'Failed to fetch fields';
      const status = message.includes('not found') ? 404 : message.includes('Access denied') ? 403 : 500;
      res.status(status).json({ message });
    }
  }));

  /**
   * POST /api/tenants/:tenantId/collections/:collectionId/fields
   * Create a new field in a collection
   */
  app.post('/api/tenants/:tenantId/collections/:collectionId/fields', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId, collectionId } = req.params;

      // Verify collection ownership first
      await collectionService.verifyTenantOwnership(collectionId, tenantId);

      const fieldData = insertCollectionFieldSchema.parse({
        ...req.body,
        collectionId,
      });

      const field = await collectionFieldService.createField(fieldData);
      res.status(201).json(field);
    } catch (error) {
      logger.error({ error }, 'Error creating field');

      if (error instanceof z.ZodError) {
        return res.status(400).json({
          message: 'Invalid input',
          errors: error.errors,
        });
      }

      const message = error instanceof Error ? error.message : 'Failed to create field';
      const status = message.includes('not found') ? 404 : message.includes('requires options') || message.includes('must be') ? 400 : 500;
      res.status(status).json({ message });
    }
  }));

  /**
   * POST /api/tenants/:tenantId/collections/:collectionId/fields/bulk
   * Bulk create fields in a collection
   */
  app.post('/api/tenants/:tenantId/collections/:collectionId/fields/bulk', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId, collectionId } = req.params;

      // Verify collection ownership first
      await collectionService.verifyTenantOwnership(collectionId, tenantId);

      const bulkSchema = z.object({
        fields: z.array(insertCollectionFieldSchema.omit({ collectionId: true })),
      });

      const { fields: fieldsData } = bulkSchema.parse(req.body);

      const fields = await collectionFieldService.bulkCreateFields(collectionId, fieldsData as any);
      res.status(201).json(fields);
    } catch (error) {
      logger.error({ error }, 'Error bulk creating fields');

      if (error instanceof z.ZodError) {
        return res.status(400).json({
          message: 'Invalid input',
          errors: error.errors,
        });
      }

      const message = error instanceof Error ? error.message : 'Failed to create fields';
      res.status(500).json({ message });
    }
  }));

  /**
   * GET /api/tenants/:tenantId/collections/:collectionId/fields/:fieldId
   * Get a single field
   */
  app.get('/api/tenants/:tenantId/collections/:collectionId/fields/:fieldId', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId, collectionId, fieldId } = req.params;

      // Verify collection ownership first
      await collectionService.verifyTenantOwnership(collectionId, tenantId);

      const field = await collectionFieldService.getField(fieldId);

      if (!field) {
        return res.status(404).json({ message: 'Field not found' });
      }

      // Verify field belongs to collection
      if (field.collectionId !== collectionId) {
        return res.status(403).json({ message: 'Field belongs to different collection' });
      }

      res.json(field);
    } catch (error) {
      logger.error({ error }, 'Error fetching field');
      const message = error instanceof Error ? error.message : 'Failed to fetch field';
      res.status(500).json({ message });
    }
  }));

  /**
   * PATCH /api/tenants/:tenantId/collections/:collectionId/fields/:fieldId
   * Update a field
   */
  app.patch('/api/tenants/:tenantId/collections/:collectionId/fields/:fieldId', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId, collectionId, fieldId } = req.params;

      // Verify collection ownership first
      await collectionService.verifyTenantOwnership(collectionId, tenantId);

      const updateSchema = z.object({
        name: z.string().min(1).optional(),
        slug: z.string().min(1).optional(),
        isRequired: z.boolean().optional(),
        options: z.any().optional(),
        defaultValue: z.any().optional(),
      });

      const updateData = updateSchema.parse(req.body);

      const field = await collectionFieldService.updateField(fieldId, collectionId, updateData);
      res.json(field);
    } catch (error) {
      logger.error({ error }, 'Error updating field');

      if (error instanceof z.ZodError) {
        return res.status(400).json({
          message: 'Invalid input',
          errors: error.errors,
        });
      }

      const message = error instanceof Error ? error.message : 'Failed to update field';
      const status = message.includes('not found') ? 404 : message.includes('Access denied') ? 403 : message.includes('must be') ? 400 : 500;
      res.status(status).json({ message });
    }
  }));

  /**
   * DELETE /api/tenants/:tenantId/collections/:collectionId/fields/:fieldId
   * Delete a field
   */
  app.delete('/api/tenants/:tenantId/collections/:collectionId/fields/:fieldId', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId, collectionId, fieldId } = req.params;

      // Verify collection ownership first
      await collectionService.verifyTenantOwnership(collectionId, tenantId);

      await collectionFieldService.deleteField(fieldId, collectionId);
      res.status(204).send();
    } catch (error) {
      logger.error({ error }, 'Error deleting field');
      const message = error instanceof Error ? error.message : 'Failed to delete field';
      const status = message.includes('not found') ? 404 : message.includes('Access denied') ? 403 : 500;
      res.status(status).json({ message });
    }
  }));

  // ===================================================================
  // RECORD ENDPOINTS
  // ===================================================================

  /**
   * GET /api/tenants/:tenantId/collections/:collectionId/records
   * List records in a collection with pagination
   */
  app.get('/api/tenants/:tenantId/collections/:collectionId/records', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId, collectionId } = req.params;

      // SECURITY FIX: Validate pagination parameters properly (no NaN from parseInt)
      const { paginationSchema } = await import('../utils/validation');
      const pagination = paginationSchema.partial().parse({
        limit: req.query.limit,
        offset: req.query.offset,
      });

      const orderBy = (req.query.orderBy as 'created_at' | 'updated_at') || 'created_at';
      const order = (req.query.order as 'asc' | 'desc') || 'desc';

      const records = await recordService.listRecords(collectionId, tenantId, {
        limit: pagination.limit,
        offset: pagination.offset,
        orderBy,
        order,
      });

      // Also return count if requested
      if (req.query.includeCount === 'true') {
        const count = await recordService.countRecords(collectionId, tenantId);
        return res.json({ records, count });
      }

      res.json(records);
    } catch (error) {
      logger.error({ error }, 'Error fetching records');
      const message = error instanceof Error ? error.message : 'Failed to fetch records';
      const status = message.includes('not found') || message.includes('access denied') ? 404 : 500;
      res.status(status).json({ message });
    }
  }));

  /**
   * POST /api/tenants/:tenantId/collections/:collectionId/records
   * Create a new record
   */
  app.post('/api/tenants/:tenantId/collections/:collectionId/records', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId, collectionId } = req.params;
      const authReq = req as AuthRequest;
      const userId = authReq.userId;

      const recordData = insertRecordSchema.parse({
        tenantId,
        collectionId,
        data: req.body.data || req.body, // Support both {data: {...}} and direct {...}
      });

      const record = await recordService.createRecord(recordData, userId);
      res.status(201).json(record);
    } catch (error) {
      logger.error({ error }, 'Error creating record');

      if (error instanceof z.ZodError) {
        return res.status(400).json({
          message: 'Invalid input',
          errors: error.errors,
        });
      }

      const message = error instanceof Error ? error.message : 'Failed to create record';
      const status = message.includes('Required field') || message.includes('must be') || message.includes('Unknown field') ? 400 : 500;
      res.status(status).json({ message });
    }
  }));

  /**
   * POST /api/tenants/:tenantId/collections/:collectionId/records/bulk
   * Bulk create records
   */
  app.post('/api/tenants/:tenantId/collections/:collectionId/records/bulk', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId, collectionId } = req.params;
      const authReq = req as AuthRequest;
      const userId = authReq.userId;

      const bulkSchema = z.object({
        records: z.array(z.record(z.any())),
      });

      const { records: recordsData } = bulkSchema.parse(req.body);

      const records = await recordService.bulkCreateRecords(collectionId, tenantId, recordsData, userId);
      res.status(201).json(records);
    } catch (error) {
      logger.error({ error }, 'Error bulk creating records');

      if (error instanceof z.ZodError) {
        return res.status(400).json({
          message: 'Invalid input',
          errors: error.errors,
        });
      }

      const message = error instanceof Error ? error.message : 'Failed to create records';
      res.status(500).json({ message });
    }
  }));

  /**
   * POST /api/tenants/:tenantId/collections/:collectionId/records/query
   * Query records by JSONB filters
   */
  app.post('/api/tenants/:tenantId/collections/:collectionId/records/query', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId, collectionId } = req.params;

      const querySchema = z.object({
        filters: z.record(z.any()),
      });

      const { filters } = querySchema.parse(req.body);

      const records = await recordService.findRecordsByFilters(collectionId, tenantId, filters);
      res.json(records);
    } catch (error) {
      logger.error({ error }, 'Error querying records');

      if (error instanceof z.ZodError) {
        return res.status(400).json({
          message: 'Invalid input',
          errors: error.errors,
        });
      }

      const message = error instanceof Error ? error.message : 'Failed to query records';
      res.status(500).json({ message });
    }
  }));

  /**
   * GET /api/tenants/:tenantId/collections/:collectionId/records/:recordId
   * Get a single record
   */
  app.get('/api/tenants/:tenantId/collections/:collectionId/records/:recordId', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId, recordId } = req.params;

      const record = await recordService.getRecord(recordId, tenantId);
      res.json(record);
    } catch (error) {
      logger.error({ error }, 'Error fetching record');
      const message = error instanceof Error ? error.message : 'Failed to fetch record';
      const status = message.includes('not found') ? 404 : message.includes('Access denied') ? 403 : 500;
      res.status(status).json({ message });
    }
  }));

  /**
   * PATCH /api/tenants/:tenantId/collections/:collectionId/records/:recordId
   * Update a record
   */
  app.patch('/api/tenants/:tenantId/collections/:collectionId/records/:recordId', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId, recordId } = req.params;
      const authReq = req as AuthRequest;
      const userId = authReq.userId;

      // Updates can be partial field updates
      const updates = req.body.data || req.body; // Support both {data: {...}} and direct {...}

      const record = await recordService.updateRecord(recordId, tenantId, updates, userId);
      res.json(record);
    } catch (error) {
      logger.error({ error }, 'Error updating record');

      const message = error instanceof Error ? error.message : 'Failed to update record';
      const status = message.includes('not found') ? 404 : message.includes('Access denied') ? 403 : message.includes('must be') || message.includes('Unknown field') ? 400 : 500;
      res.status(status).json({ message });
    }
  }));

  /**
   * DELETE /api/tenants/:tenantId/collections/:collectionId/records/:recordId
   * Delete a record
   */
  app.delete('/api/tenants/:tenantId/collections/:collectionId/records/:recordId', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId, recordId } = req.params;

      await recordService.deleteRecord(recordId, tenantId);
      res.status(204).send();
    } catch (error) {
      logger.error({ error }, 'Error deleting record');
      const message = error instanceof Error ? error.message : 'Failed to delete record';
      const status = message.includes('not found') ? 404 : message.includes('Access denied') ? 403 : 500;
      res.status(status).json({ message });
    }
  }));

  /**
   * GET /api/tenants/:tenantId/collections/:collectionId/records/count
   * Count records in a collection
   */
  app.get('/api/tenants/:tenantId/collections/:collectionId/records/count', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId, collectionId } = req.params;

      const count = await recordService.countRecords(collectionId, tenantId);
      res.json({ count });
    } catch (error) {
      logger.error({ error }, 'Error counting records');
      res.status(500).json({ message: 'Failed to count records' });
    }
  }));
}

import { createLogger } from "../logger";
import { hybridAuth, type AuthRequest } from '../middleware/auth';
import { WorkflowRepository } from "../repositories/WorkflowRepository";
import { WorkflowRunRepository } from "../repositories/WorkflowRunRepository";
import { asyncHandler } from '../utils/asyncHandler';

import type { Express, Request, Response } from "express";

const logger = createLogger({ module: 'dashboard-routes' });

/**
 * Register dashboard-related routes
 * Provides overview statistics and metrics for the workflow dashboard
 *
 * NOTE: Refactored from survey-based to workflow-based (Nov 2025)
 */
export function registerDashboardRoutes(app: Express): void {
  const workflowRepository = new WorkflowRepository();
  const workflowRunRepository = new WorkflowRunRepository();

  /**
   * GET /api/dashboard/stats
   * Get dashboard statistics for the authenticated user
   * Returns workflow counts and run statistics
   */
  app.get('/api/dashboard/stats', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const authReq = req as AuthRequest;
      const userId = authReq.userId;
      if (!userId) {
        res.status(401).json({ message: "Unauthorized - no user ID" });
        return;
      }

      // Get user's workflows
      const workflows = await workflowRepository.findByCreatorId(userId);
      const workflowIds = workflows.map((w: any) => w.id);

      // Count workflows by status
      const draftCount = workflows.filter((w: any) => w.status === 'draft').length;
      const activeCount = workflows.filter((w: any) => w.status === 'active').length;
      const archivedCount = workflows.filter((w: any) => w.status === 'archived').length;

      // Get run counts (basic implementation)
      let totalRuns = 0;
      let completedRuns = 0;

      if (workflowIds.length > 0) {
        // Get all runs for user's workflows
        const runs = await workflowRunRepository.findByWorkflowIds(workflowIds);
        totalRuns = runs.length;
        completedRuns = runs.filter((r: any) => r.completed).length;
      }

      const stats = {
        totalWorkflows: workflows.length,
        draftWorkflows: draftCount,
        activeWorkflows: activeCount,
        archivedWorkflows: archivedCount,
        totalRuns,
        completedRuns,
        inProgressRuns: totalRuns - completedRuns
      };

      res.json(stats);
    } catch (error) {
      logger.error({ error }, "Error fetching dashboard stats");
      res.status(500).json({ message: "Failed to fetch dashboard stats" });
    }
  }));

  /**
   * GET /api/dashboard/workflows
   * Get recent workflows with basic info
   */
  app.get('/api/dashboard/workflows', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const authReq = req as AuthRequest;
      const userId = authReq.userId;
      if (!userId) {
        res.status(401).json({ message: "Unauthorized - no user ID" });
        return;
      }

      // SECURITY FIX: Validate limit parameter properly (no NaN from parseInt)
      const { numericParamSchema } = await import('../utils/validation');
      const limitSchema = numericParamSchema(1, 100).default(10);
      const limit = req.query.limit ? limitSchema.parse(req.query.limit) : 10;
      const status = req.query.status as string | undefined;

      const workflows = await workflowRepository.findByCreatorId(userId);

      // Filter by status if provided
      let filteredWorkflows = workflows;
      if (status && ['draft', 'active', 'archived'].includes(status)) {
        filteredWorkflows = workflows.filter((w: any) => w.status === status);
      }

      // Sort by most recently updated
      const sortedWorkflows = filteredWorkflows.sort((a: any, b: any) => {
        const aTime = a.updatedAt ? new Date(a.updatedAt).getTime() : 0;
        const bTime = b.updatedAt ? new Date(b.updatedAt).getTime() : 0;
        return bTime - aTime;
      });

      // Limit results
      const limitedWorkflows = sortedWorkflows.slice(0, limit);

      res.json(limitedWorkflows);
    } catch (error) {
      logger.error({ error }, "Error fetching dashboard workflows");
      res.status(500).json({ message: "Failed to fetch dashboard workflows" });
    }
  }));

  /**
   * GET /api/dashboard/recent-runs
   * Get recent workflow runs across all user's workflows
   */
  app.get('/api/dashboard/recent-runs', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const authReq = req as AuthRequest;
      const userId = authReq.userId;
      if (!userId) {
        res.status(401).json({ message: "Unauthorized - no user ID" });
        return;
      }

      // SECURITY FIX: Validate limit parameter properly (no NaN from parseInt)
      const { numericParamSchema } = await import('../utils/validation');
      const limitSchema = numericParamSchema(1, 100).default(10);
      const limit = req.query.limit ? limitSchema.parse(req.query.limit) : 10;

      // Get user's workflows
      const workflows = await workflowRepository.findByCreatorId(userId);
      const workflowIds = workflows.map((w: any) => w.id);

      if (workflowIds.length === 0) {
        res.json([]);
        return;
      }

      // Get runs for user's workflows
      const runs = await workflowRunRepository.findByWorkflowIds(workflowIds);

      // Sort by most recent first
      const sortedRuns = runs.sort((a: any, b: any) => {
        const aTime = a.createdAt ? new Date(a.createdAt).getTime() : 0;
        const bTime = b.createdAt ? new Date(b.createdAt).getTime() : 0;
        return bTime - aTime;
      });

      // Limit results
      const limitedRuns = sortedRuns.slice(0, limit);

      // Enrich runs with workflow titles
      const workflowMap = new Map(workflows.map((w: any) => [w.id, w]));
      const enrichedRuns = limitedRuns.map((run: any) => ({
        ...run,
        workflowTitle: workflowMap.get(run.workflowId)?.title || 'Unknown Workflow'
      }));

      res.json(enrichedRuns);
    } catch (error) {
      logger.error({ error }, "Error fetching recent runs");
      res.status(500).json({ message: "Failed to fetch recent runs" });
    }
  }));
}

import { z } from 'zod';

import { DATAVAULT_CONFIG } from '@shared/config';
import {
  insertDatavaultTableSchema,
  insertDatavaultColumnSchema,
  insertDatavaultRowSchema,
} from '@shared/schema';

import { logger } from '../logger';
import { hybridAuth, getAuthUserTenantId, getAuthUserId } from '../middleware/auth';
import {
  apiLimiter,
  batchLimiter,
  createLimiter,
  deleteLimiter,
  strictLimiter,
} from '../middleware/rateLimiter';
import {
  datavaultTablesService,
  datavaultColumnsService,
  datavaultRowsService,
  datavaultRowNotesService,
  datavaultTablePermissionsService,
} from '../services';
import { AclService } from '../services/AclService';
import { datavaultDatabasesService } from '../services/DatavaultDatabasesService';
import { asyncHandler } from '../utils/asyncHandler';
import { validationMessages } from '../utils/validationMessages';

import type { Express, Request, Response } from 'express';
const aclService = new AclService();
/**
 * Register DataVault routes
 * DataVault Phase 1: Tenant-scoped custom data tables
 *
 * DataVault provides a flexible data storage system where creators can define
 * custom tables, columns, and manage data without altering the database schema.
 */
export function registerDatavaultRoutes(app: Express): void {
  // Apply global rate limiting to all DataVault routes
  app.use('/api/datavault', apiLimiter);
  // Helper to get tenantId with proper error handling
  const getTenantId = (req: Request): string => {
    const tenantId = getAuthUserTenantId(req);
    if (!tenantId) {
      logger.error(
        {
          userId: getAuthUserId(req),
          path: req.path
        },
        'User session missing tenantId - user may need to log out and log back in'
      );
      throw new Error('Your account is not properly configured. Please log out and log back in to fix this issue.');
    }
    return tenantId;
  };
  // ===================================================================
  // DATABASE ENDPOINTS
  // ===================================================================
  /**
   * GET /api/datavault/databases
   * List all databases for the authenticated tenant
   */
  app.get('/api/datavault/databases', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const tenantId = getTenantId(req);
      const userId = getAuthUserId(req);
      if (!userId) {
        return res.status(401).json({ message: 'Authentication required' });
      }
      const { scopeType, scopeId } = req.query;
      let databases;
      if (scopeType && typeof scopeType === 'string') {
        // SECURITY FIX: Verify user has access to the requested scope before returning data
        if (scopeId && typeof scopeId === 'string') {
          if (scopeType === 'project') {
            // Verify user has at least 'view' access to the project
            const projectRole = await aclService.resolveRoleForProject(userId, scopeId);
            if (projectRole === 'none') {
              return res.status(403).json({
                message: 'Access denied: You do not have permission to view this project'
              });
            }
          } else if (scopeType === 'workflow') {
            // Verify user has at least 'view' access to the workflow
            const workflowRole = await aclService.resolveRoleForWorkflow(userId, scopeId);
            if (workflowRole === 'none') {
              return res.status(403).json({
                message: 'Access denied: You do not have permission to view this workflow'
              });
            }
          }
          // For 'account' scope: tenantId check is sufficient (already done above)
        }
        databases = await datavaultDatabasesService.getDatabasesByScope(
          tenantId,
          scopeType as any,
          scopeId as string
        );
      } else {
        databases = await datavaultDatabasesService.getDatabasesForTenant(tenantId, userId);
      }
      res.json(databases);
    } catch (error) {
      logger.error({ error }, 'Error fetching DataVault databases');
      const message = error instanceof Error ? error.message : 'Failed to fetch databases';
      res.status(500).json({ message });
    }
  }));
  /**
   * POST /api/datavault/databases
   * Create a new database
   */
  app.post('/api/datavault/databases', createLimiter, hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const tenantId = getTenantId(req);
      const createSchema = z.object({
        name: z.string()
          .min(1, { message: validationMessages.database.nameMinLength })
          .max(255, { message: validationMessages.database.nameMaxLength }),
        description: z.string()
          .max(1000, { message: validationMessages.database.descriptionMaxLength })
          .optional(),
        scopeType: z.enum(['account', 'project', 'workflow'], {
          errorMap: () => ({ message: validationMessages.invalidOption('scopeType', ['account', 'project', 'workflow']) })
        }),
        scopeId: z.string().uuid({ message: validationMessages.invalidUuid }).optional(),
      });
      const input = createSchema.parse(req.body);
      const database = await datavaultDatabasesService.createDatabase({
        ...input,
        tenantId,
      });
      res.status(201).json(database);
    } catch (error) {
      logger.error({ error }, 'Error creating DataVault database');
      if (error instanceof z.ZodError) {
        return res.status(400).json({
          message: 'Invalid input',
          errors: error.errors,
        });
      }
      const message = error instanceof Error ? error.message : 'Failed to create database';
      res.status(500).json({ message });
    }
  }));
  /**
   * GET /api/datavault/databases/:id
   * Get a single database with stats
   */
  app.get('/api/datavault/databases/:id', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const tenantId = getTenantId(req);
      const { id } = req.params;
      const database = await datavaultDatabasesService.getDatabaseById(id, tenantId);
      res.json(database);
    } catch (error) {
      logger.error({ error }, 'Error fetching DataVault database');
      const message = error instanceof Error ? error.message : 'Failed to fetch database';
      const status = message.includes('not found') ? 404 : message.includes('Unauthorized') ? 403 : 500;
      res.status(status).json({ message });
    }
  }));
  /**
   * PATCH /api/datavault/databases/:id
   * Update a database
   */
  app.patch('/api/datavault/databases/:id', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const tenantId = getTenantId(req);
      const { id } = req.params;
      const updateSchema = z.object({
        name: z.string()
          .min(1, { message: validationMessages.database.nameMinLength })
          .max(255, { message: validationMessages.database.nameMaxLength })
          .optional(),
        description: z.string()
          .max(1000, { message: validationMessages.database.descriptionMaxLength })
          .optional(),
        scopeType: z.enum(['account', 'project', 'workflow'], {
          errorMap: () => ({ message: validationMessages.invalidOption('scopeType', ['account', 'project', 'workflow']) })
        }).optional(),
        scopeId: z.string().uuid({ message: validationMessages.invalidUuid }).optional().nullable(),
      });
      const input = updateSchema.parse(req.body);
      const database = await datavaultDatabasesService.updateDatabase(id, tenantId, {
        ...input,
        scopeId: input.scopeId ?? undefined,
      });
      res.json(database);
    } catch (error) {
      logger.error({ error }, 'Error updating DataVault database');
      if (error instanceof z.ZodError) {
        return res.status(400).json({
          message: 'Invalid input',
          errors: error.errors,
        });
      }
      const message = error instanceof Error ? error.message : 'Failed to update database';
      const status = message.includes('not found') ? 404 : message.includes('Unauthorized') ? 403 : 500;
      res.status(status).json({ message });
    }
  }));
  /**
   * DELETE /api/datavault/databases/:id
   * Delete a database (tables will be moved to main folder)
   */
  app.delete('/api/datavault/databases/:id', deleteLimiter, hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const tenantId = getTenantId(req);
      const { id } = req.params;
      await datavaultDatabasesService.deleteDatabase(id, tenantId);
      res.status(204).send();
    } catch (error) {
      logger.error({ error }, 'Error deleting DataVault database');
      const message = error instanceof Error ? error.message : 'Failed to delete database';
      const status = message.includes('not found') ? 404 : message.includes('Unauthorized') ? 403 : 500;
      res.status(status).json({ message });
    }
  }));
  /**
   * GET /api/datavault/databases/:id/tables
   * Get all tables in a database
   */
  app.get('/api/datavault/databases/:id/tables', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const tenantId = getTenantId(req);
      const { id } = req.params;
      const tables = await datavaultDatabasesService.getTablesInDatabase(id, tenantId);
      res.json(tables);
    } catch (error) {
      logger.error({ error }, 'Error fetching database tables');
      const message = error instanceof Error ? error.message : 'Failed to fetch tables';
      const status = message.includes('not found') ? 404 : message.includes('Unauthorized') ? 403 : 500;
      res.status(status).json({ message });
    }
  }));
  // ===================================================================
  // TABLE ENDPOINTS
  // ===================================================================
  /**
   * GET /api/datavault/tables
   * List all tables for the authenticated tenant
   */
  app.get('/api/datavault/tables', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const tenantId = getTenantId(req);
      const withStats = req.query.stats === 'true';
      const userId = getAuthUserId(req);
      if (!userId) {
        return res.status(401).json({ message: 'Authentication required' });
      }
      const tables = withStats
        ? await datavaultTablesService.listTablesWithStats(tenantId, userId)
        : await datavaultTablesService.listTables(tenantId, userId);
      res.json(tables);
    } catch (error) {
      logger.error({ error }, 'Error fetching DataVault tables');
      const message = error instanceof Error ? error.message : 'Failed to fetch tables';
      res.status(500).json({ message });
    }
  }));
  /**
   * POST /api/datavault/tables
   * Create a new table
   */
  app.post('/api/datavault/tables', createLimiter, hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const tenantId = getTenantId(req);
      const userId = getAuthUserId(req);
      const tableData = insertDatavaultTableSchema.parse({
        ...req.body,
        tenantId,
        ownerUserId: userId,
      });
      const table = await datavaultTablesService.createTable(tableData);
      res.status(201).json(table);
    } catch (error) {
      logger.error({ error }, 'Error creating DataVault table');
      if (error instanceof z.ZodError) {
        return res.status(400).json({
          message: 'Invalid input',
          errors: error.errors,
        });
      }
      const message = error instanceof Error ? error.message : 'Failed to create table';
      res.status(500).json({ message });
    }
  }));
  /**
   * GET /api/datavault/tables/:tableId
   * Get a single table with optional columns
   * Requires: read permission
   */
  app.get('/api/datavault/tables/:tableId', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const tenantId = getTenantId(req);
      const userId = getAuthUserId(req);
      const { tableId } = req.params;
      const includeColumns = req.query.columns === 'true';
      if (!userId) {
        return res.status(401).json({ message: 'Authentication required' });
      }
      if (!z.string().uuid().safeParse(tableId).success) {
        return res.status(400).json({ message: 'Invalid table ID format' });
      }
      // Check read permission
      await datavaultTablesService.requirePermission(userId, tableId, tenantId, 'read');
      const table = includeColumns
        ? await datavaultTablesService.getTableWithColumns(tableId, tenantId)
        : await datavaultTablesService.getTable(tableId, tenantId);
      res.json(table);
    } catch (error) {
      logger.error({ error }, 'Error fetching DataVault table');
      const message = error instanceof Error ? error.message : 'Failed to fetch table';
      const status = message.includes('not found') ? 404 : message.includes('Access denied') ? 403 : 500;
      res.status(status).json({ message });
    }
  }));
  /**
   * PATCH /api/datavault/tables/:tableId
   * Update a table
   * Requires: owner permission
   */
  app.patch('/api/datavault/tables/:tableId', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const tenantId = getTenantId(req);
      const userId = getAuthUserId(req);
      const { tableId } = req.params;
      if (!userId) {
        return res.status(401).json({ message: 'Authentication required' });
      }
      // Check owner permission
      await datavaultTablesService.requirePermission(userId, tableId, tenantId, 'owner');
      const updateSchema = z.object({
        name: z.string().min(1).optional(),
        slug: z.string().min(1).optional(),
        description: z.string().nullable().optional(),
      });
      const updateData = updateSchema.parse(req.body);
      const table = await datavaultTablesService.updateTable(tableId, tenantId, updateData);
      res.json(table);
    } catch (error) {
      logger.error({ error }, 'Error updating DataVault table');
      if (error instanceof z.ZodError) {
        return res.status(400).json({
          message: 'Invalid input',
          errors: error.errors,
        });
      }
      const message = error instanceof Error ? error.message : 'Failed to update table';
      const status = message.includes('not found') ? 404 : message.includes('Access denied') ? 403 : 500;
      res.status(status).json({ message });
    }
  }));
  /**
   * PATCH /api/datavault/tables/:tableId/move
   * Move table to a database or main folder
   */
  app.patch('/api/datavault/tables/:tableId/move', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const tenantId = getTenantId(req);
      const { tableId } = req.params;
      const moveSchema = z.object({
        databaseId: z.string().uuid().nullable(),
      });
      const { databaseId } = moveSchema.parse(req.body);
      const table = await datavaultTablesService.moveTable(tableId, tenantId, databaseId);
      res.json(table);
    } catch (error) {
      logger.error({ error }, 'Error moving DataVault table');
      if (error instanceof z.ZodError) {
        return res.status(400).json({
          message: 'Invalid input',
          errors: error.errors,
        });
      }
      const message = error instanceof Error ? error.message : 'Failed to move table';
      const status = message.includes('not found') ? 404 : message.includes('Access denied') ? 403 : 500;
      res.status(status).json({ message });
    }
  }));
  /**
   * DELETE /api/datavault/tables/:tableId
   * Delete a table (cascades to columns, rows, and values)
   * Requires: owner permission
   */
  app.delete('/api/datavault/tables/:tableId', deleteLimiter, hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const tenantId = getTenantId(req);
      const userId = getAuthUserId(req);
      const { tableId } = req.params;
      if (!userId) {
        return res.status(401).json({ message: 'Authentication required' });
      }
      // Check owner permission
      await datavaultTablesService.requirePermission(userId, tableId, tenantId, 'owner');
      await datavaultTablesService.deleteTable(tableId, tenantId);
      res.status(204).send();
    } catch (error) {
      logger.error({ error }, 'Error deleting DataVault table');
      const message = error instanceof Error ? error.message : 'Failed to delete table';
      const status = message.includes('not found') ? 404 : message.includes('Access denied') ? 403 : 500;
      res.status(status).json({ message });
    }
  }));
  /**
   * GET /api/datavault/tables/:tableId/schema
   * Get table schema (for workflow builder integration)
   * Returns: { id, name, slug, description, databaseId, columns: [...] }
   * Requires: read permission
   */
  app.get('/api/datavault/tables/:tableId/schema', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const tenantId = getTenantId(req);
      const userId = getAuthUserId(req);
      const { tableId } = req.params;
      if (!userId) {
        return res.status(401).json({ message: 'Authentication required' });
      }
      if (!z.string().uuid().safeParse(tableId).success) {
        return res.status(400).json({ message: 'Invalid table ID format' });
      }
      // Check read permission
      await datavaultTablesService.requirePermission(userId, tableId, tenantId, 'read');
      const schema = await datavaultTablesService.getTableSchema(tableId, tenantId);
      res.json(schema);
    } catch (error) {
      logger.error({ error }, 'Error fetching DataVault table schema');
      const message = error instanceof Error ? error.message : 'Failed to fetch table schema';
      const status = message.includes('not found') ? 404 : message.includes('Access denied') ? 403 : 500;
      res.status(status).json({ message });
    }
  }));
  // ===================================================================
  // COLUMN ENDPOINTS
  // ===================================================================
  /**
   * GET /api/datavault/tables/:tableId/columns
   * List all columns for a table
   */
  app.get('/api/datavault/tables/:tableId/columns', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
