        logger.info({ orgId, targetUserId, adminUserId: userId }, 'Admin demoted to member');
        res.json({ message: 'Admin demoted to member successfully' });
      } catch (error) {
        logger.error(
          {
            error,
            orgId: req.params.orgId,
            targetUserId: req.params.targetUserId,
