import { createLogger } from "../logger";
import { hybridAuth, type AuthRequest } from '../middleware/auth';
import { userRepository } from "../repositories";
import { TemplateSharingService } from "../services/TemplateSharingService";
import { asyncHandler } from "../utils/asyncHandler";

import type { Express, Request, Response } from "express";

const logger = createLogger({ module: "template-sharing-routes" });
const sharingService = new TemplateSharingService();

/**
 * Register template sharing routes
 * Handles template collaboration and permission management
 */
export function registerTemplateSharingRoutes(app: Express): void {

  /**
   * GET /api/templates/:id/shares
   * List all shares for a template (owner/admin only)
   */
  app.get("/api/templates/:id/shares", hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { id } = req.params;
      const authReq = req as AuthRequest;
      const userId = authReq.userId;
      if (!userId) {
        return res.status(401).json({ error: "Unauthorized - no user ID" });
      }
      const user = await userRepository.findById(userId);
      if (!user) {
        return res.status(404).json({ error: "User not found" });
      }

      const shares = await sharingService.listShares(id, user);
      res.json(shares);
    } catch (error: any) {
      logger.error({ error }, "Error listing shares");
      if (error.message.includes("Unauthorized")) {
        return res.status(403).json({ error: error.message });
      }
      if (error.message.includes("not found")) {
        return res.status(404).json({ error: error.message });
      }
      res.status(500).json({ error: "Failed to list shares" });
    }
  }));

  /**
   * POST /api/templates/:id/share
   * Share a template with a user (by userId or email)
   * Body: { userId?: string, email?: string, access: "use" | "edit" }
   */
  app.post("/api/templates/:id/share", hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const authReq = req as AuthRequest;
      const userId = authReq.userId;
      if (!userId) {
        return res.status(401).json({ error: "Unauthorized - no user ID" });
      }
      const user = await userRepository.findById(userId);
      if (!user) {
        return res.status(404).json({ error: "User not found" });
      }

      const { id } = req.params;
      const { userId: targetUserId, email, access } = req.body;


      if (!access || !["use", "edit"].includes(access)) {
        return res.status(400).json({ error: "Invalid access level. Must be 'use' or 'edit'" });
      }

      if (!targetUserId && !email) {
        return res.status(400).json({ error: "Must provide either userId or email" });
      }

      const share = await sharingService.shareWithUser(id, user, {
        userId: targetUserId,
        email,
        access,
      });

      res.json(share);
    } catch (error: any) {
      logger.error({ error }, "Error sharing template");
      if (error.message.includes("Unauthorized")) {
        return res.status(403).json({ error: error.message });
      }
      if (error.message.includes("not found")) {
        return res.status(404).json({ error: error.message });
      }
      if (error.message.includes("Cannot share")) {
        return res.status(400).json({ error: error.message });
      }
      res.status(500).json({ error: "Failed to share template" });
    }
  }));

  /**
   * PUT /api/template-shares/:shareId
   * Update access level for a share
   * Body: { access: "use" | "edit" }
   */
  app.put("/api/template-shares/:shareId", hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const authReq = req as AuthRequest;
      const userId = authReq.userId;
      if (!userId) {
        return res.status(401).json({ error: "Unauthorized - no user ID" });
      }
      const user = await userRepository.findById(userId);
      if (!user) {
        return res.status(404).json({ error: "User not found" });
      }

      const { shareId } = req.params;
      const { access } = req.body;


      if (!access || !["use", "edit"].includes(access)) {
        return res.status(400).json({ error: "Invalid access level. Must be 'use' or 'edit'" });
      }

      const share = await sharingService.updateAccess(shareId, user, access);

      if (!share) {
        return res.status(404).json({ error: "Share not found" });
      }

      res.json(share);
    } catch (error: any) {
      logger.error({ error }, "Error updating share access");
      if (error.message.includes("Unauthorized")) {
        return res.status(403).json({ error: error.message });
      }
      res.status(500).json({ error: "Failed to update share access" });
    }
  }));

  /**
   * DELETE /api/template-shares/:shareId
   * Revoke a share
   */
  app.delete("/api/template-shares/:shareId", hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const authReq = req as AuthRequest;
      const userId = authReq.userId;
      if (!userId) {
        return res.status(401).json({ error: "Unauthorized - no user ID" });
      }
      const user = await userRepository.findById(userId);
      if (!user) {
        return res.status(404).json({ error: "User not found" });
      }

      const { shareId } = req.params;

      const success = await sharingService.revoke(shareId, user);

      if (success) {
        res.json({ ok: true });
      } else {
        res.status(404).json({ error: "Share not found" });
      }
    } catch (error: any) {
      logger.error({ error }, "Error revoking share");
      if (error.message.includes("Unauthorized")) {
        return res.status(403).json({ error: error.message });
      }
      res.status(500).json({ error: "Failed to revoke share" });
    }
  }));

  /**
   * GET /api/templates-shared-with-me
   * List all templates shared with the current user
   */
  app.get("/api/templates-shared-with-me", hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const authReq = req as AuthRequest;
      const userId = authReq.userId;
      if (!userId) {
        return res.status(401).json({ error: "Unauthorized - no user ID" });
      }

      const user = await userRepository.findById(userId);
      if (!user) {
        return res.status(404).json({ error: "User not found" });
      }

      const sharedTemplates = await sharingService.listSharedWithUser(userId, user.email ?? "");
      res.json(sharedTemplates);
    } catch (error: any) {
      logger.error({ error }, "Error listing shared templates");
      res.status(500).json({ error: "Failed to list shared templates" });
    }
  }));
}

import { eq } from "drizzle-orm";

import { tenants, users, projects } from "@shared/schema";

import { db } from "../db";
import { createLogger } from "../logger";
import { hybridAuth, type AuthRequest } from "../middleware/auth";
import { requireOwner, requirePermission } from "../middleware/rbac";
import { requireTenant, validateTenantParam } from "../middleware/tenant";
import { userRepository } from "../repositories";
import { asyncHandler } from "../utils/asyncHandler";

import type { Express, Request, Response } from "express";



const logger = createLogger({ module: 'tenant-routes' });

/**
 * Register tenant-related routes
 * Provides APIs for tenant management and access control
 */
export function registerTenantRoutes(app: Express): void {
  /**
   * GET /api/tenants/current
   * Get the current user's tenant information
   */
  app.get('/api/tenants/current', hybridAuth, requireTenant, asyncHandler(async (req: Request, res: Response) => {
    try {
      const authReq = req as AuthRequest;
      const tenantId = authReq.tenantId;

      if (!tenantId) {
        return res.status(404).json({
          message: 'No tenant found for current user',
          error: 'no_tenant',
        });
      }

      // Get tenant information
      const [tenant] = await db
        .select()
        .from(tenants)
        .where(eq(tenants.id, tenantId));

      if (!tenant) {
        return res.status(404).json({
          message: 'Tenant not found',
          error: 'tenant_not_found',
        });
      }

      res.json({
        id: tenant.id,
        name: tenant.name,
        billingEmail: tenant.billingEmail,
        plan: tenant.plan,
        createdAt: tenant.createdAt,
        updatedAt: tenant.updatedAt,
      });
    } catch (error) {
      logger.error({ error }, 'Failed to fetch current tenant');
      res.status(500).json({
        message: 'Failed to fetch tenant',
        error: 'internal_error',
      });
    }
  }));

  /**
   * GET /api/tenants/:tenantId
   * Get specific tenant information (must be a member of the tenant)
   */
  app.get('/api/tenants/:tenantId', hybridAuth, validateTenantParam, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId } = req.params;

      // Get tenant information
      const [tenant] = await db
        .select()
        .from(tenants)
        .where(eq(tenants.id, tenantId));

      if (!tenant) {
        return res.status(404).json({
          message: 'Tenant not found',
          error: 'tenant_not_found',
        });
      }

      res.json({
        id: tenant.id,
        name: tenant.name,
        billingEmail: tenant.billingEmail,
        plan: tenant.plan,
        createdAt: tenant.createdAt,
        updatedAt: tenant.updatedAt,
      });
    } catch (error) {
      logger.error({ error }, 'Failed to fetch tenant');
      res.status(500).json({
        message: 'Failed to fetch tenant',
        error: 'internal_error',
      });
    }
  }));

  /**
   * PUT /api/tenants/:tenantId
   * Update tenant information (owner only)
   */
  app.put('/api/tenants/:tenantId', hybridAuth, validateTenantParam, requireOwner, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId } = req.params;
      const { name, billingEmail, plan } = req.body;

      // Validate input
      const updateData: any = {
        updatedAt: new Date(),
      };

      if (name !== undefined) { updateData.name = name; }
      if (billingEmail !== undefined) { updateData.billingEmail = billingEmail; }
      if (plan !== undefined) { updateData.plan = plan; }

      // Update tenant
      const [updatedTenant] = await db
        .update(tenants)
        .set(updateData)
        .where(eq(tenants.id, tenantId))
        .returning();

      if (!updatedTenant) {
        return res.status(404).json({
          message: 'Tenant not found',
          error: 'tenant_not_found',
        });
      }

      logger.info({ tenantId }, 'Tenant updated');

      res.json({
        message: 'Tenant updated successfully',
        tenant: {
          id: updatedTenant.id,
          name: updatedTenant.name,
          billingEmail: updatedTenant.billingEmail,
          plan: updatedTenant.plan,
          updatedAt: updatedTenant.updatedAt,
        },
      });
    } catch (error) {
      logger.error({ error }, 'Failed to update tenant');
      res.status(500).json({
        message: 'Failed to update tenant',
        error: 'internal_error',
      });
    }
  }));

  /**
   * GET /api/tenants/:tenantId/users
   * Get all users in a tenant (owner or builder)
   */
  app.get('/api/tenants/:tenantId/users', hybridAuth, validateTenantParam, requirePermission('tenant:view'), asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId } = req.params;

      // Get all users in the tenant
      const tenantUsers = await db
        .select({
          id: users.id,
          email: users.email,
          firstName: users.firstName,
          lastName: users.lastName,
          fullName: users.fullName,
          profileImageUrl: users.profileImageUrl,
          role: users.tenantRole,
          authProvider: users.authProvider,
          createdAt: users.createdAt,
        })
        .from(users)
        .where(eq(users.tenantId, tenantId));

      res.json({
        users: tenantUsers,
        total: tenantUsers.length,
      });
    } catch (error) {
      logger.error({ error }, 'Failed to fetch tenant users');
      res.status(500).json({
        message: 'Failed to fetch users',
        error: 'internal_error',
      });
    }
  }));

  /**
   * GET /api/tenants/:tenantId/projects
   * Get all projects in a tenant
   */
  app.get('/api/tenants/:tenantId/projects', hybridAuth, validateTenantParam, requirePermission('project:view'), asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId } = req.params;

      // Get all projects in the tenant
      const tenantProjects = await db
        .select()
        .from(projects)
        .where(eq(projects.tenantId, tenantId));

      res.json({
        projects: tenantProjects,
        total: tenantProjects.length,
      });
    } catch (error) {
      logger.error({ error }, 'Failed to fetch tenant projects');
      res.status(500).json({
        message: 'Failed to fetch projects',
        error: 'internal_error',
      });
    }
  }));

  /**
   * POST /api/tenants
   * Create a new tenant (for future multi-tenant signup)
   */
  app.post('/api/tenants', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const authReq = req as AuthRequest;
      const { name, billingEmail, plan } = req.body;

      // Validate input
      if (!name) {
        return res.status(400).json({
          message: 'Tenant name is required',
          error: 'missing_fields',
        });
      }

      // Create tenant
      const [newTenant] = await db
        .insert(tenants)
        .values({
          name,
          billingEmail: billingEmail ?? null,
          plan: plan || 'free',
        })
        .returning();

      // Update user's tenantId and role to owner
      if (authReq.userId) {
        await userRepository.updateUser(authReq.userId, {
          tenantId: newTenant.id,
          tenantRole: 'owner',
        });
      }

      logger.info({ tenantId: newTenant.id, userId: authReq.userId }, 'Tenant created');

      res.status(201).json({
        message: 'Tenant created successfully',
        tenant: {
          id: newTenant.id,
          name: newTenant.name,
          billingEmail: newTenant.billingEmail,
          plan: newTenant.plan,
          createdAt: newTenant.createdAt,
        },
      });
    } catch (error) {
      logger.error({ error }, 'Failed to create tenant');
      res.status(500).json({
        message: 'Failed to create tenant',
        error: 'internal_error',
      });
    }
  }));

  /**
   * PUT /api/tenants/:tenantId/users/:userId/role
   * Update user role in tenant (owner only)
   */
  app.put('/api/tenants/:tenantId/users/:userId/role', hybridAuth, validateTenantParam, requireOwner, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId, userId } = req.params;
      const { role } = req.body;

      // Validate role
      const validRoles = ['owner', 'builder', 'runner', 'viewer'];
      if (!role || !validRoles.includes(role)) {
        return res.status(400).json({
          message: 'Invalid role. Must be one of: owner, builder, runner, viewer',
          error: 'invalid_role',
        });
      }

      // Update user role
      const [updatedUser] = await db
        .update(users)
        .set({
          tenantRole: role,
          updatedAt: new Date(),
        })
        .where(eq(users.id, userId))
        .returning();

      if (!updatedUser) {
        return res.status(404).json({
          message: 'User not found',
          error: 'user_not_found',
        });
      }

      // Verify user belongs to the tenant
      if (updatedUser.tenantId !== tenantId) {
        return res.status(403).json({
          message: 'User does not belong to this tenant',
          error: 'user_not_in_tenant',
        });
      }

      logger.info({ tenantId, userId, newRole: role }, 'User role updated');

      res.json({
        message: 'User role updated successfully',
        user: {
          id: updatedUser.id,
          email: updatedUser.email,
          firstName: updatedUser.firstName,
          lastName: updatedUser.lastName,
          role: updatedUser.tenantRole,
        },
      });
    } catch (error) {
      logger.error({ error }, 'Failed to update user role');
      res.status(500).json({
        message: 'Failed to update user role',
        error: 'internal_error',
      });
    }
  }));
}

import { z } from "zod";

import { insertTransformBlockSchema } from "@shared/schema";

import { createLogger } from "../logger";
import { hybridAuth, type AuthRequest } from '../middleware/auth';
import { autoRevertToDraft } from "../middleware/autoRevertToDraft";
import { transformBlockRepository } from "../repositories/TransformBlockRepository";
import { transformBlockService } from "../services/TransformBlockService";
import { asyncHandler } from "../utils/asyncHandler";

import type { Express, Request, Response } from "express";

const logger = createLogger({ module: "transform-blocks-routes" });

// Rate limiting for test endpoint (in-memory, per user)
const testRateLimits = new Map<string, { count: number; resetAt: number }>();
const TEST_RATE_LIMIT = 10; // requests per minute
const TEST_RATE_WINDOW = 60 * 1000; // 1 minute

function checkTestRateLimit(userId: string): { allowed: boolean; error?: string } {
  const now = Date.now();
  const userLimit = testRateLimits.get(userId);

  if (!userLimit || now > userLimit.resetAt) {
    // Reset or initialize
    testRateLimits.set(userId, {
      count: 1,
      resetAt: now + TEST_RATE_WINDOW,
    });
    return { allowed: true };
  }

  if (userLimit.count >= TEST_RATE_LIMIT) {
    return {
      allowed: false,
      error: `Rate limit exceeded. Maximum ${TEST_RATE_LIMIT} test requests per minute.`,
    };
  }

  userLimit.count++;
  return { allowed: true };
}

/**
 * Register transform block routes
 * Handles CRUD operations and test execution for transform blocks
 */
export function registerTransformBlockRoutes(app: Express): void {
  /**
   * POST /api/workflows/:workflowId/transform-blocks
   * Create a new transform block
   */
  app.post('/api/workflows/:workflowId/transform-blocks', hybridAuth, autoRevertToDraft, asyncHandler(async (req: Request, res: Response) => {
    try {
      const userId = (req as AuthRequest).userId;
      if (!userId) {
        return res.status(401).json({ success: false, error: "Unauthorized - no user ID" });
      }

      const { workflowId } = req.params;

      // Merge workflowId from URL params into body data for schema validation
      const dataWithWorkflowId = { ...req.body, workflowId };

      // Validate request body
      const blockData = insertTransformBlockSchema.parse(dataWithWorkflowId);

      const block = await transformBlockService.createBlock(workflowId, userId, blockData);
      res.status(201).json({ success: true, data: block });
    } catch (error) {
      logger.error({ error }, "Error creating transform block");
      const message = error instanceof Error ? error.message : "Failed to create transform block";

      if (error instanceof z.ZodError) {
        return res.status(400).json({ success: false, error: "Invalid request data", details: error.errors });
      }

      const status = message.includes("not found") ? 404 : message.includes("Access denied") ? 403 : message.includes("limit") ? 400 : 500;
      res.status(status).json({ success: false, error: message });
    }
  }));

  /**
   * GET /api/workflows/:workflowId/transform-blocks
