/**
 * AI Service Facade
 *
 * This service acts as a unified entry point for all AI capabilities,
 * delegating actual work to specialized services.
 *
 * Features:
 * - Workflow Generation (via WorkflowGenerationService)
 * - Workflow Suggestions (via WorkflowSuggestionService)
 * - Workflow Revision (via WorkflowRevisionService)
 * - Logic Assistance (via WorkflowLogicService)
 * - Workflow Optimization (via WorkflowOptimizationService)
 */
import {
  AIProviderConfig,
  AIProvider,
  AIGeneratedWorkflow,
  AIWorkflowGenerationRequest,
  AIWorkflowSuggestion,
  AIWorkflowSuggestionRequest,
  AITemplateBindingsResponse,
  AITemplateBindingsRequest,
  AIWorkflowRevisionRequest,
  AIWorkflowRevisionResponse,
  AIConnectLogicRequest,
  AIConnectLogicResponse,
  AIDebugLogicRequest,
  AIDebugLogicResponse,
  AIVisualizeLogicRequest,
  AIVisualizeLogicResponse,
} from '../../shared/types/ai';
import { createLogger } from '../logger';

import { AIPromptBuilder } from './ai/AIPromptBuilder';
import { AIProviderClient } from './ai/AIProviderClient';
import { QualityImprovementConfig, ImprovementResult } from './ai/IterativeQualityImprover';
import { WorkflowGenerationService } from './ai/WorkflowGenerationService';
import { WorkflowLogicService } from './ai/WorkflowLogicService';
import { workflowOptimizationService, WorkflowOptimizationService } from './ai/WorkflowOptimizationService';
import { WorkflowRevisionService } from './ai/WorkflowRevisionService';
import { WorkflowSuggestionService } from './ai/WorkflowSuggestionService';
import { WorkflowWithAliases } from './AliasResolver';
import { QualityScore } from './WorkflowQualityValidator';
const logger = createLogger({ module: 'ai-service' });
/**
 * AI Service for workflow generation and suggestions
 */
export class AIService {
  private generationService: WorkflowGenerationService;
  private suggestionService: WorkflowSuggestionService;
  private revisionService: WorkflowRevisionService;
  private logicService: WorkflowLogicService;
  private optimizationService: WorkflowOptimizationService;
  // Keep config for potential introspection
  private config: AIProviderConfig;
  constructor(config: AIProviderConfig) {
    this.config = config;
    // Initialize shared dependencies
    const client = new AIProviderClient(config);
    const promptBuilder = new AIPromptBuilder();
    // Initialize specialized services
    this.generationService = new WorkflowGenerationService(client, promptBuilder);
    this.suggestionService = new WorkflowSuggestionService(client, promptBuilder);
    this.revisionService = new WorkflowRevisionService(client, promptBuilder);
    this.logicService = new WorkflowLogicService(client, promptBuilder);
    this.optimizationService = workflowOptimizationService;
  }
  /**
   * Generate a new workflow from a natural language description
   */
  async generateWorkflow(
    request: AIWorkflowGenerationRequest,
  ): Promise<AIGeneratedWorkflow> {
    return this.generationService.generateWorkflow(request);
  }

  /**
   * Generate a workflow with automatic iterative quality improvement.
   *
   * This method generates an initial workflow, then iteratively refines it
   * until quality targets are met or cost limits are reached.
   *
   * Cost vs Quality Balancing:
   * - targetQualityScore: Stop when this score is reached (default: 80)
   * - maxIterations: Maximum refinement attempts (default: 3)
   * - minImprovementThreshold: Stop if improvement per iteration drops below this (default: 5)
   * - maxTotalCostCents: Budget cap for iterations (default: 25)
   *
   * @param request - The generation request with description and constraints
   * @param qualityConfig - Optional configuration for quality improvement loop
   * @returns The improved workflow with quality metrics and iteration details
   */
  async generateWorkflowWithQualityLoop(
    request: AIWorkflowGenerationRequest,
    qualityConfig?: Partial<QualityImprovementConfig>,
  ): Promise<{
    workflow: AIGeneratedWorkflow;
    qualityScore: QualityScore;
    improvement: ImprovementResult;
  }> {
    return this.generationService.generateWorkflowWithQualityLoop(request, qualityConfig);
  }
  /**
   * Suggest improvements to an existing workflow
   */
  async suggestWorkflowImprovements(
    request: AIWorkflowSuggestionRequest,
    existingWorkflow: {
      sections: any[];
      logicRules?: any[];
      transformBlocks?: any[];
    },
  ): Promise<AIWorkflowSuggestion> {
    return this.suggestionService.suggestWorkflowImprovements(request, existingWorkflow);
  }
  /**
   * Suggest template variable bindings
   * @param request - The binding request
   * @param variables - Available workflow variables
   * @param placeholders - Template placeholders to match
   * @param workflow - Optional workflow structure for alias validation
   */
  async suggestTemplateBindings(
    request: AITemplateBindingsRequest,
    variables: Array<{ alias: string; label: string; type: string }>,
    placeholders: string[],
    workflow?: WorkflowWithAliases,
  ): Promise<AITemplateBindingsResponse> {
    return this.suggestionService.suggestTemplateBindings(request, variables, placeholders, workflow);
  }
  /**
   * Suggest random plausible values for workflow steps
   */
  async suggestValues(
    steps: Array<{
      key: string;
      type: string;
      label?: string;
      options?: string[];
      description?: string;
    }>,
    mode: 'full' | 'partial' = 'full'
  ): Promise<Record<string, any>> {
    return this.suggestionService.suggestValues(steps, mode);
  }
  /**
   * Revise an existing workflow based on user instructions
   */
  async reviseWorkflow(
    request: AIWorkflowRevisionRequest,
  ): Promise<AIWorkflowRevisionResponse> {
    return this.revisionService.reviseWorkflow(request);
  }
  /**
   * Generate logic connections based on natural language description
   */
  async generateLogic(
    request: AIConnectLogicRequest,
  ): Promise<AIConnectLogicResponse> {
    return this.logicService.generateLogic(request);
  }
  /**
   * Debug logic for contradictions and issues
   */
  async debugLogic(
    request: AIDebugLogicRequest,
  ): Promise<AIDebugLogicResponse> {
    return this.logicService.debugLogic(request);
  }
  /**
   * Visualize logic as a graph
   */
  async visualizeLogic(
    request: AIVisualizeLogicRequest,
  ): Promise<AIVisualizeLogicResponse> {
    return this.logicService.visualizeLogic(request);
  }
}
/**
 * Get default model for provider
 */
function getDefaultModel(provider: AIProvider): string {
  switch (provider) {
    case 'openai':
      return 'gpt-4-turbo-preview';
    case 'anthropic':
      return 'claude-3-5-sonnet-20241022';
    case 'gemini':
      return 'gemini-2.0-flash';
    default:
      throw new Error(`Unknown provider: ${provider}`);
  }
}
/**
 * Create AIService instance from environment variables
 */
export function createAIServiceFromEnv(): AIService {
  // Check for GEMINI_API_KEY first
  const geminiKey = process.env.GEMINI_API_KEY;
  if (geminiKey) {
    const model = process.env.GEMINI_MODEL || 'gemini-2.0-flash';
    logger.info({ provider: 'gemini', model }, 'AI Service initialized');
    const config: AIProviderConfig = {
      provider: 'gemini' as AIProvider,
      apiKey: geminiKey,
      model,
      temperature: 0.7,
      maxTokens: 4000,
    };
    return new AIService(config);
  }
  // Fall back to AI_API_KEY
  const provider = (process.env.AI_PROVIDER || 'openai') as AIProvider;
  const apiKey = process.env.AI_API_KEY;
  if (!apiKey) {
    const errorMsg = [
      'ΓòÉ'.repeat(80),
      'Γ¥î AI SERVICE CONFIGURATION ERROR',
      'ΓòÉ'.repeat(80),
      '',
      'No AI provider API key found. Set GEMINI_API_KEY or AI_API_KEY.',
      '',
      'ΓòÉ'.repeat(80),
    ].join('\n');
    throw new Error(errorMsg);
  }
  const modelWorkflow = process.env.AI_MODEL_WORKFLOW || getDefaultModel(provider);
  logger.info({ provider, model: modelWorkflow }, 'AI Service initialized');
  const config: AIProviderConfig = {
    provider,
    apiKey,
    model: modelWorkflow,
    temperature: 0.7,
    maxTokens: 4000,
  };
  return new AIService(config);
}
/**
 * Validate AI configuration at startup (non-throwing)
 */
export function validateAIConfig(): { configured: boolean; provider?: string; model?: string; error?: string } {
  try {
    const geminiKey = process.env.GEMINI_API_KEY;
    if (geminiKey) {
      const model = process.env.GEMINI_MODEL || 'gemini-2.0-flash';
      return { configured: true, provider: 'gemini', model };
    }
    const apiKey = process.env.AI_API_KEY;
    if (!apiKey) {
      return {
        configured: false,
        error: 'No API key configured. Set GEMINI_API_KEY or AI_API_KEY environment variable.'
      };
    }
    const provider = process.env.AI_PROVIDER || 'openai';
    const model = process.env.AI_MODEL_WORKFLOW || getDefaultModel(provider as AIProvider);
    return { configured: true, provider, model };
  } catch (error: any) {
    return { configured: false, error: error.message };
  }
}

import { ActivityLogRepository } from "../repositories/ActivityLogRepository";
import { ActivityLogQuery, ActivityLogInsert, ActivityLogResult } from "../types/activityLog";

/**
 * Activity Log Service
 *
 * Provides business logic for activity log operations including:
 * - Querying and filtering logs
 * - Exporting logs to CSV
 * - Manual log creation (optional)
 */
export class ActivityLogService {
  constructor(private repo = new ActivityLogRepository()) {}

  /**
   * List activity logs with filtering, pagination, and sorting
   */
  async list(query: ActivityLogQuery): Promise<ActivityLogResult> {
    return this.repo.find(query);
  }

  /**
   * Export activity logs to CSV format
   *
   * @param query - Filter criteria (same as list)
   * @returns Object with filename and CSV content
   */
  async exportCsv(query: ActivityLogQuery): Promise<{ filename: string; csv: string }> {
    // Get all matching rows (with a reasonable limit for export)
    const exportQuery = {
      ...query,
      limit: query.limit || 5000,  // Default export limit
      offset: 0                     // Always start from beginning for export
    };

    const { rows } = await this.repo.find(exportQuery);

    // Define CSV headers
    const headers = [
      "timestamp",
      "event",
      "actorId",
      "actorEmail",
      "entityType",
      "entityId",
      "status",
      "ipAddress",
      "userAgent",
      "metadata"
    ];

    // Helper to escape CSV values
    const escapeCsv = (value: any): string => {
      if (value === null || value === undefined) {return "";}

      // Convert objects/arrays to JSON strings
      if (typeof value === "object") {
        value = JSON.stringify(value);
      }

      const stringValue = String(value);

      // Escape double quotes and wrap in quotes if contains special chars
      if (stringValue.includes('"') || stringValue.includes(',') || stringValue.includes('\n')) {
        return `"${stringValue.replace(/"/g, '""')}"`;
      }

      return stringValue;
    };

    // Build CSV rows
    const csvRows = [
      // Header row
      headers.join(","),
      // Data rows
      ...rows.map(row =>
        headers
          .map(header => escapeCsv((row as any)[header]))
          .join(",")
      )
    ];

    const csv = csvRows.join("\n");

    // Generate filename with timestamp
    const timestamp = new Date().toISOString().replace(/:/g, '-').split('.')[0];
    const filename = `activity-logs-${timestamp}.csv`;

    return { filename, csv };
  }

  /**
   * Manually log an activity event
   *
   * Optional method - use this to record custom events that aren't
   * automatically tracked by your analytics system.
   *
   * @param event - Event name/type
   * @param details - Additional event details
   */
  async log(
    event: string,
    details?: Partial<{
      actorId: string | null;
      actorEmail: string | null;
      entityType: string | null;
      entityId: string | null;
      status: string | null;
      ipAddress: string | null;
      userAgent: string | null;
      metadata: any;
    }>
  ): Promise<void> {
    const entry: ActivityLogInsert = {
      event,
      timestamp: new Date().toISOString(),
      actorId: details?.actorId ?? null,
      actorEmail: details?.actorEmail ?? null,
      entityType: details?.entityType ?? null,
      entityId: details?.entityId ?? null,
      status: details?.status ?? "info",
      ipAddress: details?.ipAddress ?? null,
      userAgent: details?.userAgent ?? null,
      metadata: details?.metadata ?? null
    };

    await this.repo.insert(entry);
  }

  /**
   * Get unique event types for filter dropdowns
   */
  async getUniqueEvents(): Promise<string[]> {
    return this.repo.getUniqueEvents();
  }

  /**
   * Get unique actors for filter dropdowns
   */
  async getUniqueActors(): Promise<string[]> {
    return this.repo.getUniqueActors();
  }
}

/**
 * AliasResolver - Centralized Step Alias Resolution Utility
 *
 * Provides consistent alias-to-ID resolution across the entire application.
 * Consolidates scattered alias resolution logic into a single, testable utility.
 *
 * Usage patterns:
 * 1. Create resolver from steps: AliasResolver.fromSteps(steps)
 * 2. Create resolver from workflow: AliasResolver.fromWorkflow(workflow)
 * 3. Use inline resolver: AliasResolver.createInlineResolver(steps)
 */

import { createLogger } from '../logger';

const logger = createLogger({ module: 'alias-resolver' });

export interface StepWithAlias {
  id: string;
  alias?: string | null;
  sectionId?: string;
  title?: string;
}

export interface SectionWithAlias {
  id: string;
  alias?: string | null;
  title?: string;
}

export interface WorkflowWithAliases {
  sections?: Array<{
    id: string;
    alias?: string | null;
    title?: string;
    steps?: StepWithAlias[];
  }>;
}

export interface ResolutionResult {
  id: string;
  type: 'step' | 'section';
  alias?: string;
  title?: string;
}

export interface ResolutionError {
  aliasOrId: string;
  reason: 'not_found' | 'ambiguous' | 'invalid_input';
  suggestions?: string[];
  context?: string;
}

export type AliasResolverFn = (aliasOrId: string) => string | undefined;

/**
 * AliasResolver provides centralized alias-to-ID resolution
 */
export class AliasResolver {
  private aliasToId: Map<string, string> = new Map();
  private idToAlias: Map<string, string> = new Map();
  private stepDetails: Map<string, ResolutionResult> = new Map();
  private sectionDetails: Map<string, ResolutionResult> = new Map();
  private errors: ResolutionError[] = [];

  private constructor() {}

  /**
   * Create resolver from an array of steps
   */
  static fromSteps(steps: StepWithAlias[]): AliasResolver {
    const resolver = new AliasResolver();

    for (const step of steps) {
      if (!step.id) {
        resolver.errors.push({
          aliasOrId: step.alias || 'unknown',
          reason: 'invalid_input',
          context: `Step missing ID: ${JSON.stringify(step)}`,
        });
        continue;
      }

      // Map ID to itself (allows lookup by ID)
      resolver.aliasToId.set(step.id, step.id);

      // Map alias to ID if alias exists
      if (step.alias) {
        const normalizedAlias = step.alias.toLowerCase();

        // Check for duplicate aliases
        if (resolver.aliasToId.has(normalizedAlias)) {
          const existingId = resolver.aliasToId.get(normalizedAlias);
          if (existingId !== step.id) {
            resolver.errors.push({
              aliasOrId: step.alias,
              reason: 'ambiguous',
              context: `Duplicate alias "${step.alias}" maps to both ${existingId} and ${step.id}`,
            });
          }
        }

        resolver.aliasToId.set(normalizedAlias, step.id);
        resolver.aliasToId.set(step.alias, step.id); // Also store original case
        resolver.idToAlias.set(step.id, step.alias);
      }

      // Store step details for rich resolution
      resolver.stepDetails.set(step.id, {
        id: step.id,
        type: 'step',
        alias: step.alias || undefined,
        title: step.title,
      });
    }

    return resolver;
  }

  /**
   * Create resolver from a workflow structure (sections + steps)
   */
  static fromWorkflow(workflow: WorkflowWithAliases): AliasResolver {
    const resolver = new AliasResolver();
    const allSteps: StepWithAlias[] = [];

    for (const section of workflow.sections ?? []) {
      // Add section to resolver
      if (section.id) {
        resolver.aliasToId.set(section.id, section.id);

        if (section.alias) {
          const normalizedAlias = section.alias.toLowerCase();
          resolver.aliasToId.set(normalizedAlias, section.id);
          resolver.aliasToId.set(section.alias, section.id);
          resolver.idToAlias.set(section.id, section.alias);
        }

        resolver.sectionDetails.set(section.id, {
          id: section.id,
          type: 'section',
          alias: section.alias || undefined,
          title: section.title,
        });
      }

      // Collect steps
      if (section.steps) {
        allSteps.push(...section.steps.map(s => ({ ...s, sectionId: section.id })));
      }
    }

    // Add all steps using fromSteps logic
    const stepResolver = AliasResolver.fromSteps(allSteps);

    // Merge step data into this resolver
    stepResolver.aliasToId.forEach((id, alias) => resolver.aliasToId.set(alias, id));
    stepResolver.idToAlias.forEach((alias, id) => resolver.idToAlias.set(id, alias));
    stepResolver.stepDetails.forEach((details, id) => resolver.stepDetails.set(id, details));
    resolver.errors.push(...stepResolver.errors);

    return resolver;
  }

  /**
   * Create an inline resolver function (for use with evaluateConditionExpression)
   * This is the most common pattern used throughout the codebase
   */
  static createInlineResolver(steps: StepWithAlias[]): AliasResolverFn {
    const resolver = AliasResolver.fromSteps(steps);
    return (aliasOrId: string) => resolver.resolve(aliasOrId);
  }

  /**
   * Create a Map<string, string> for alias resolution (alias -> id)
   * Compatible with RunExecutionCoordinator and block runners
   */
  static createAliasMap(steps: StepWithAlias[]): Record<string, string> {
    const resolver = AliasResolver.fromSteps(steps);
    return resolver.toAliasMap();
  }

  /**
   * Resolve an alias or ID to a step/section ID
   * Returns undefined if not found
   */
  resolve(aliasOrId: string): string | undefined {
    if (!aliasOrId) {return undefined;}

    // Try exact match first
    if (this.aliasToId.has(aliasOrId)) {
      return this.aliasToId.get(aliasOrId);
    }

    // Try case-insensitive match
    const normalized = aliasOrId.toLowerCase();
    if (this.aliasToId.has(normalized)) {
      return this.aliasToId.get(normalized);
    }

    return undefined;
  }

  /**
   * Resolve with detailed result including type and metadata
   */
  resolveWithDetails(aliasOrId: string): ResolutionResult | undefined {
    const id = this.resolve(aliasOrId);
    if (!id) {return undefined;}

    // Check steps first, then sections
    if (this.stepDetails.has(id)) {
      return this.stepDetails.get(id);
    }
    if (this.sectionDetails.has(id)) {
      return this.sectionDetails.get(id);
    }

    return { id, type: 'step' };
  }

  /**
   * Resolve or throw an error with helpful context
   */
  resolveOrThrow(aliasOrId: string, context?: string): string {
    const resolved = this.resolve(aliasOrId);

    if (!resolved) {
      const error = this.createNotFoundError(aliasOrId, context);
      logger.error({ aliasOrId, context, error }, 'Alias resolution failed');
      throw new AliasResolutionError(error);
    }

    return resolved;
  }

  /**
   * Resolve multiple aliases, returning results and errors
   */
  resolveMany(aliasesOrIds: string[]): { resolved: Map<string, string>; errors: ResolutionError[] } {
    const resolved = new Map<string, string>();
    const errors: ResolutionError[] = [];

    for (const aliasOrId of aliasesOrIds) {
      const id = this.resolve(aliasOrId);
      if (id) {
        resolved.set(aliasOrId, id);
      } else {
        errors.push(this.createNotFoundError(aliasOrId));
      }
    }

    return { resolved, errors };
  }

  /**
   * Get the alias for an ID (reverse lookup)
   */
  getAlias(id: string): string | undefined {
    return this.idToAlias.get(id);
  }

  /**
   * Check if an alias or ID exists in the resolver
   */
  has(aliasOrId: string): boolean {
    return this.resolve(aliasOrId) !== undefined;
  }

  /**
   * Get all registered aliases
   */
  getAllAliases(): string[] {
    return Array.from(this.idToAlias.values());
  }

  /**
   * Get all registered IDs
   */
  getAllIds(): string[] {
    return Array.from(this.idToAlias.keys());
  }

  /**
   * Get any errors encountered during resolution
   */
  getErrors(): ResolutionError[] {
    return [...this.errors];
  }

  /**
   * Check if resolver has any errors
   */
  hasErrors(): boolean {
    return this.errors.length > 0;
  }

  /**
   * Convert to a Record<string, string> for compatibility with existing code
   */
  toAliasMap(): Record<string, string> {
    const map: Record<string, string> = {};
    this.aliasToId.forEach((id, alias) => {
      map[alias] = id;
    });
    return map;
  }

  /**
   * Convert to inline resolver function
   */
  toResolverFn(): AliasResolverFn {
    return (aliasOrId: string) => this.resolve(aliasOrId);
  }

  /**
   * Create a not-found error with suggestions
   */
  private createNotFoundError(aliasOrId: string, context?: string): ResolutionError {
    // Find similar aliases for suggestions
    const allAliases = this.getAllAliases();
    const suggestions = allAliases
      .filter(alias => {
        const normalized = aliasOrId.toLowerCase();
        const aliasLower = alias.toLowerCase();
        return aliasLower.includes(normalized) ||
               normalized.includes(aliasLower) ||
               this.levenshteinDistance(normalized, aliasLower) <= 3;
      })
      .slice(0, 3);

    return {
      aliasOrId,
      reason: 'not_found',
      suggestions: suggestions.length > 0 ? suggestions : undefined,
      context,
    };
  }

  /**
   * Calculate Levenshtein distance for fuzzy matching
   */
  private levenshteinDistance(a: string, b: string): number {
    if (a.length === 0) {return b.length;}
    if (b.length === 0) {return a.length;}

    const matrix: number[][] = [];

    for (let i = 0; i <= b.length; i++) {
      matrix[i] = [i];
    }

    for (let j = 0; j <= a.length; j++) {
      matrix[0][j] = j;
    }

    for (let i = 1; i <= b.length; i++) {
      for (let j = 1; j <= a.length; j++) {
        if (b.charAt(i - 1) === a.charAt(j - 1)) {
          matrix[i][j] = matrix[i - 1][j - 1];
        } else {
          matrix[i][j] = Math.min(
            matrix[i - 1][j - 1] + 1,
            matrix[i][j - 1] + 1,
            matrix[i - 1][j] + 1
          );
        }
      }
    }

    return matrix[b.length][a.length];
  }
}

/**
 * Custom error class for alias resolution failures
 */
export class AliasResolutionError extends Error {
  public readonly resolutionError: ResolutionError;

  constructor(error: ResolutionError) {
    const message = AliasResolutionError.formatMessage(error);
    super(message);
    this.name = 'AliasResolutionError';
    this.resolutionError = error;
  }

  private static formatMessage(error: ResolutionError): string {
    let message = `Failed to resolve alias or ID "${error.aliasOrId}": ${error.reason}`;

    if (error.suggestions && error.suggestions.length > 0) {
      message += `. Did you mean: ${error.suggestions.join(', ')}?`;
    }

    if (error.context) {
      message += ` Context: ${error.context}`;
    }

    return message;
  }
}

/**
 * Utility functions for common resolution patterns
 */
export const AliasResolverUtils = {
  /**
   * Resolve logic rule aliases to IDs
   */
  resolveLogicRules<T extends { conditionStepAlias?: string; targetAlias?: string }>(
    rules: T[],
    resolver: AliasResolver
  ): { resolved: T[]; errors: ResolutionError[] } {
    const resolved: T[] = [];
    const errors: ResolutionError[] = [];

    for (const rule of rules) {
      const resolvedRule = { ...rule };
      let hasError = false;

      if (rule.conditionStepAlias) {
        const conditionId = resolver.resolve(rule.conditionStepAlias);
        if (conditionId) {
          (resolvedRule as any).conditionStepId = conditionId;
        } else {
          errors.push({
            aliasOrId: rule.conditionStepAlias,
            reason: 'not_found',
            context: 'Logic rule condition step',
          });
          hasError = true;
        }
      }

      if (rule.targetAlias) {
        const targetId = resolver.resolve(rule.targetAlias);
        if (targetId) {
          (resolvedRule as any).targetId = targetId;
        } else {
          errors.push({
            aliasOrId: rule.targetAlias,
            reason: 'not_found',
            context: 'Logic rule target',
          });
          hasError = true;
        }
      }

      if (!hasError) {
        resolved.push(resolvedRule);
      }
    }

    return { resolved, errors };
  },

  /**
   * Build data context with both IDs and aliases as keys
   */
  buildDualKeyContext(
    stepValues: Array<{ stepId: string; value: any }>,
    resolver: AliasResolver
  ): Record<string, any> {
    const context: Record<string, any> = {};

    for (const sv of stepValues) {
      // Add by ID
      context[sv.stepId] = sv.value;

      // Add by alias if available
      const alias = resolver.getAlias(sv.stepId);
      if (alias) {
        context[alias] = sv.value;
      }
    }

    return context;
  },
};

export default AliasResolver;

import crypto from 'crypto';

import bcrypt from 'bcrypt';
import { eq, and, gt, lt } from "drizzle-orm";
import jwt, { type SignOptions } from 'jsonwebtoken';
import zxcvbn from 'zxcvbn';

import {
    refreshTokens,
    passwordResetTokens,
    emailVerificationTokens,
    users,
    type User
} from "@shared/schema";


import {
    PASSWORD_CONFIG,
    JWT_CONFIG,
    REFRESH_TOKEN_CONFIG,
    PASSWORD_RESET_CONFIG,
    EMAIL_VERIFICATION_CONFIG,
    PASSWORD_POLICY
} from "../config/auth";
import { env } from "../config/env";
import { db } from "../db";
import {
    InvalidTokenError,
    TokenExpiredError,
    InvalidCredentialsError
} from "../errors/AuthErrors";
import { createLogger } from "../logger";
import { hashToken } from "../utils/encryption";

import { accountLockoutService } from "./AccountLockoutService";
import { sendPasswordResetEmail, sendVerificationEmail } from "./emailService";

const log = createLogger({ module: 'auth-service' });

const SALT_ROUNDS = PASSWORD_CONFIG.SALT_ROUNDS;
const JWT_EXPIRY = process.env.JWT_EXPIRY || '15m';
const JWT_SECRET = env.JWT_SECRET;

export interface PortalTokenPayload {
    email: string;
    portal: true;
    iat?: number;
    exp?: number;
}

export interface JWTPayload {
    userId: string;
    email: string;
    tenantId: string | null;
    role: 'admin' | 'creator' | 'owner' | 'builder' | 'runner' | 'viewer' | null;
    tenantRole?: 'owner' | 'builder' | 'runner' | 'viewer' | null;
    iat?: number;
    exp?: number;
}

export interface RefreshTokenMetadata {
    userAgent?: string;
    ip?: string;
    [key: string]: any;
}

export class AuthService {
    private db: typeof db;

    constructor(database = db) {
        this.db = database;
    }

    // =================================================================
    // JWT & CRYPTO CORE
    // =================================================================

    /**
     * Create a JWT token for a user
     */
    createToken(user: User): string {
        if (!JWT_SECRET) {
            throw new Error('JWT_SECRET not configured');
        }

        try {
            const payload: JWTPayload = {
                userId: user.id,
                email: user.email,
                tenantId: user.tenantId ?? null,
                role: user.role as any, // System role (admin/creator)
                tenantRole: user.tenantRole as any, // Tenant role (owner/builder/etc)
            };

            const options: SignOptions = {
                expiresIn: JWT_EXPIRY as any,
                algorithm: 'HS256',
            };

            return jwt.sign(payload, JWT_SECRET, options);
        } catch (error) {
            log.error({ error, userId: user.id }, 'Failed to create JWT token');
            throw new Error('Token creation failed', { cause: error });
        }
    }

    /**
     * Verify and decode a JWT access token
     *
     * Validates the JWT signature using HS256 algorithm and returns the decoded payload.
     * Automatically checks token expiration and throws descriptive errors.
     *
     * @param token - The JWT token to verify (without "Bearer " prefix)
     * @returns {JWTPayload} The decoded token payload containing userId, email, tenantId, and role
     *
     * @throws {Error} 'JWT not configured' if JWT_SECRET is not set
     * @throws {Error} 'Token expired' if the token has passed its expiration time
     * @throws {Error} 'Invalid token' for signature mismatch or malformed tokens
     *
     * @security
     * - Uses HS256 (HMAC-SHA256) for signature verification
     * - Enforces algorithm whitelist (only HS256 accepted)
     * - Automatic expiration validation via jwt library
     *
     * @example
     * ```typescript
     * try {
     *   const payload = authService.verifyToken(token);
     *   console.log('User ID:', payload.userId);
     *   console.log('Email:', payload.email);
     * } catch (error) {
     *   if (error.message === 'Token expired') {
     *     // Refresh token flow
     *   } else {
     *     // Invalid token - force re-authentication
     *   }
     * }
     * ```
     */
    verifyToken(token: string): JWTPayload {
        if (!JWT_SECRET) { throw new Error('JWT not configured'); }

        try {
            return jwt.verify(token, JWT_SECRET, { algorithms: ['HS256'] }) as JWTPayload;
        } catch (error) {
            if (error instanceof jwt.TokenExpiredError) {
                throw new TokenExpiredError('Token has expired');
            }
            throw new InvalidTokenError('Invalid or malformed token');
        }
    }

    /**
     * Create a special JWT token for Portal users (email-only)
     */
    createPortalToken(email: string): string {
        if (!JWT_SECRET) { throw new Error('JWT_SECRET not configured'); }
        const payload = { email, portal: true };
        return jwt.sign(payload, JWT_SECRET, { expiresIn: '24h', algorithm: 'HS256' });
    }

    /**
     * Verify a Portal JWT token
     */
    verifyPortalToken(token: string): { email: string } {
        if (!JWT_SECRET) { throw new Error('JWT not configured'); }
        try {
            const payload = jwt.verify(token, JWT_SECRET) as PortalTokenPayload;
            if (!payload.portal || !payload.email) { throw new Error('Invalid portal token'); }
            return { email: payload.email };
        } catch (error) {
            throw new Error('Invalid portal token');
        }
    }

    /**
     * Hash a password using bcrypt
     */
    async hashPassword(password: string): Promise<string> {
        return bcrypt.hash(password, SALT_ROUNDS);
    }

    /**
     * Compare a password with its hash
     */
    async comparePassword(password: string, hash: string): Promise<boolean> {
        return bcrypt.compare(password, hash);
    }

    /**
     * Extract token from Authorization header
     */
    extractTokenFromHeader(authHeader: string | undefined): string | null {
        if (!authHeader) { return null; }
        if (authHeader.startsWith('Bearer ')) {
            return authHeader.substring(7);
        }
        return authHeader;
    }

    /**
     * Check if a token looks like a JWT
     */
    looksLikeJwt(token: string): boolean {
        if (!token) { return false; }
        const parts = token.split('.');
        return parts.length === 3 && parts.every(part => part.length > 0);
    }

    // =================================================================
    // VALIDATION HELPER
    // =================================================================

    /**
     * Validate password strength using zxcvbn
     *
     * @param password - The password to validate
     * @param userInputs - Optional user information (email, firstName, lastName) to prevent personal info in password
     * @returns {valid: boolean, message?: string, score?: number, feedback?: object}
     */
    validatePasswordStrength(password: string, userInputs?: string[]): { valid: boolean; message?: string; score?: number; feedback?: any } {
        // Check length first (before expensive zxcvbn check)
        if (password.length < PASSWORD_POLICY.MIN_LENGTH) {
            return { valid: false, message: `Password must be at least ${PASSWORD_POLICY.MIN_LENGTH} characters long` };
        }
        if (password.length > PASSWORD_POLICY.MAX_LENGTH) {
            return { valid: false, message: `Password must be at most ${PASSWORD_POLICY.MAX_LENGTH} characters long` };
        }

        // Use zxcvbn for strength scoring (0-4 scale)
        const result = zxcvbn(password, userInputs ?? []);

        // Require score of 3 or higher (strong password)
        // 0: too guessable (risky password)
        // 1: very guessable (protection from throttled online attacks)
        // 2: somewhat guessable (protection from unthrottled online attacks)
        // 3: safely unguessable (moderate protection from offline slow-hash scenario)
        // 4: very unguessable (strong protection from offline slow-hash scenario)
        const minScore = PASSWORD_POLICY.MIN_STRENGTH_SCORE || 3;

        if (result.score < minScore) {
            // Provide helpful feedback from zxcvbn
            const suggestions = result.feedback.suggestions.join(' ') || 'Try a stronger password.';
            const warning = result.feedback.warning ? `${result.feedback.warning}. ` : '';
            return {
                valid: false,
                message: `${warning}${suggestions}`,
                score: result.score,
                feedback: result.feedback
            };
        }

        return { valid: true, score: result.score };
    }

    validateEmail(email: string): boolean {
        // RFC 5321: Maximum email length is 254 characters
        if (!email || email.length > 254 || email.length < 3) {
            return false;
        }

        // Stricter regex: local-part@domain.tld
        // - Local part: 1-64 chars, no spaces, cannot start or end with dot
        // - Domain: 1-255 chars, no spaces, ASCII only (no unicode)
        // - TLD: at least 2 chars
        const emailRegex = /^[^\s@]{1,64}@[^\s@]{1,255}\.[^\s@]{2,}$/;

        if (!emailRegex.test(email)) {
            return false;
        }

        // Split for additional validation
        const [localPart, domain] = email.split('@');

        // SECURITY FIX: Reject emails starting or ending with dot in local part
        if (localPart.startsWith('.') || localPart.endsWith('.')) {
            return false;
        }

        // No consecutive dots
        if (email.includes('..')) {
            return false;
        }

        // Domain must have at least one dot
        if (!domain?.includes('.')) {
            return false;
        }

        // SECURITY FIX: Reject unicode domains (or convert to punycode)
        // This prevents homograph attacks and ensures ASCII-only domains
        // eslint-disable-next-line no-control-regex
        if (/[^\x00-\x7F]/.test(domain)) {
            return false; // Reject non-ASCII characters in domain
        }

        return true;
    }

    // =================================================================
    // REFRESH TOKENS
    // =================================================================

    /**
     * Create a new refresh token for a user
     *
     * Generates a cryptographically secure random refresh token (80 hex characters),
     * hashes it with SHA-256, and stores it in the database with a 30-day expiration.
     * The plain token is returned to the client for use in HTTP-only cookies.
     *
     * @param userId - The user ID to associate the token with
     * @param metadata - Optional metadata including IP address and user agent for device tracking
     * @returns {Promise<string>} The plain (unhashed) refresh token to be sent to the client
     *
     * @throws {Error} If database insertion fails
     *
     * @security
     * - Token is 40 bytes (80 hex chars) providing 160 bits of entropy
     * - SHA-256 hash stored in database (prevents token theft via database breach)
     * - Tokens expire after 30 days
     * - Device fingerprinting via IP/User-Agent for suspicious activity detection
     *
     * @example
     * ```typescript
     * const refreshToken = await authService.createRefreshToken('user-123', {
     *   ip: '192.168.1.1',
     *   userAgent: 'Mozilla/5.0...'
     * });
     * // Set in HTTP-only cookie
     * res.setHeader('Set-Cookie', serialize('refresh_token', refreshToken, {
     *   httpOnly: true,
     *   secure: true,
     *   sameSite: 'strict'
     * }));
     * ```
     */
    async createRefreshToken(userId: string, metadata: RefreshTokenMetadata = {}): Promise<string> {
        const plainToken = crypto.randomBytes(40).toString('hex');
        const tokenHash = hashToken(plainToken);

        const expiresAt = new Date();
        expiresAt.setDate(expiresAt.getDate() + 30); // 30 days

        // Import device utilities (dynamic import to avoid circular dependencies)
        const { parseDeviceName, getLocationFromIP } = await import('../utils/deviceFingerprint');

        const deviceName = metadata.userAgent ? parseDeviceName(metadata.userAgent) : null;
        const ipAddress = metadata.ip ?? null;
        const location = ipAddress ? getLocationFromIP(ipAddress) : null;

        await this.db.insert(refreshTokens).values({
            userId,
            token: tokenHash,
            expiresAt,
            metadata,
            deviceName,
            ipAddress,
            location,
            lastUsedAt: new Date(),
            revoked: false
        });

        return plainToken;
    }

    /**
     * Verify and rotate a refresh token (automatic token rotation)
     *
     * Implements automatic refresh token rotation as recommended by OAuth 2.0 Security Best Practices (RFC 8252).
     * When a refresh token is used, it is immediately revoked and a new one is issued. This limits the
     * window of opportunity for token theft and enables detection of token reuse attacks.
     *
     * @param plainToken - The plain (unhashed) refresh token from the client
     * @returns {Promise<object|null>} Object containing userId and newRefreshToken if valid, null if invalid/expired
     *
     * @throws {Error} If database operations fail
     *
     * @security
     * - **Reuse Detection**: If a revoked token is used, ALL user sessions are revoked (indicates token theft)
     * - **Single Use**: Each refresh token can only be used once (automatic rotation)
     * - **Expiration Check**: Tokens are validated against expiration timestamp
     * - **Hash Comparison**: Only hashed tokens are stored/compared (prevents database breach impact)
     *
     * @example
     * ```typescript
     * const result = await authService.rotateRefreshToken(oldToken);
     * if (result) {
     *   // Generate new access token
     *   const accessToken = authService.createToken(user);
     *   // Set new refresh token in cookie
     *   res.setHeader('Set-Cookie', serialize('refresh_token', result.newRefreshToken, { ... }));
     *   res.json({ token: accessToken });
     * } else {
     *   // Invalid/expired/reused token - force login
     *   res.status(401).json({ message: 'Invalid refresh token' });
     * }
     * ```
     */
    async rotateRefreshToken(plainToken: string): Promise<{ userId: string, newRefreshToken: string } | null> {
        const tokenHash = hashToken(plainToken);

        // DEBUG LOG
        // logger is available as 'log' from imports
        log.info({ tokenHash, plainTokenLen: plainToken.length }, 'DEBUG: rotateRefreshToken called');

        // Find token purely by hash to detect state
        const storedToken = await this.db.query.refreshTokens.findFirst({
            where: eq(refreshTokens.token, tokenHash)
        });

        if (!storedToken) {
            log.warn({ tokenHash }, 'Security: Unknown refresh token used (Not Found in DB)');

            // DEBUG: List all tokens for debugging (careful in prod, safe in test)
            if (process.env.NODE_ENV === 'test') {
                const allTokens = await this.db.select().from(refreshTokens);
                log.info({ allTokensCount: allTokens.length, sampleToken: allTokens[0]?.token }, 'DEBUG: Tokens in DB');
            }
            return null;
        }

        // Reuse Detection: If token is already revoked, this is a theft attempt
        if (storedToken.revoked) {
            log.warn({ userId: storedToken.userId, tokenHash }, 'Security: REUSED REFRESH TOKEN DETECTED. Revoking all sessions.');
            await this.revokeAllUserTokens(storedToken.userId);
            return null;
        }

        // Expiry check
        if (storedToken.expiresAt < new Date()) {
            log.warn({ userId: storedToken.userId }, 'Security: Expired refresh token used');
            return null;
        }

        // Valid token -> Rotate it
        // Valid token -> Rotate it (Atomic Check-and-Set)
        // Ensure we only update if it's still not revoked.
        const [revokedToken] = await this.db.update(refreshTokens)
            .set({ revoked: true })
            .where(and(
                eq(refreshTokens.id, storedToken.id),
                eq(refreshTokens.revoked, false)
            ))
            .returning();

        if (!revokedToken) {
            // Race condition: Token was revoked between read and write
            log.warn({ userId: storedToken.userId, tokenHash }, 'Security: REUSED REFRESH TOKEN DETECTED (Concurrent). Revoking all sessions.');
            await this.revokeAllUserTokens(storedToken.userId);
            return null;
        }

        // Issue a new refresh token
        const newRefreshToken = await this.createRefreshToken(storedToken.userId, storedToken.metadata as any);

        return {
            userId: storedToken.userId,
            newRefreshToken
        };
    }

    async revokeRefreshToken(plainToken: string): Promise<void> {
        const tokenHash = hashToken(plainToken);
        await this.db.update(refreshTokens)
            .set({ revoked: true })
            .where(eq(refreshTokens.token, tokenHash));
    }

    async revokeAllUserTokens(userId: string): Promise<void> {
        await this.db.update(refreshTokens)
            .set({ revoked: true })
            .where(eq(refreshTokens.userId, userId));
    }

    async validateRefreshToken(plainToken: string): Promise<string | null> {
        const tokenHash = hashToken(plainToken);

        const storedToken = await this.db.query.refreshTokens.findFirst({
            where: and(
                eq(refreshTokens.token, tokenHash),
                eq(refreshTokens.revoked, false),
                gt(refreshTokens.expiresAt, new Date())
            )
        });

        return storedToken ? storedToken.userId : null;
    }

    // =================================================================
    // PASSWORD RESET
    // =================================================================

    async generatePasswordResetToken(email: string): Promise<string | null> {
        const user = await this.db.query.users.findFirst({
            where: eq(users.email, email)
        });

        if (!user) { return null; }

        const plainToken = crypto.randomBytes(32).toString('hex');
        const tokenHash = hashToken(plainToken);
        const expiresAt = new Date(Date.now() + PASSWORD_RESET_CONFIG.TOKEN_EXPIRY_MS);

        await this.db.update(passwordResetTokens)
            .set({ used: true })
            .where(eq(passwordResetTokens.userId, user.id));

        await this.db.insert(passwordResetTokens).values({
            userId: user.id,
            token: tokenHash,
            expiresAt,
            used: false
        });

        await sendPasswordResetEmail(email, plainToken);
        log.info({ email }, 'Password reset email sent');

        return plainToken;
    }

    async verifyPasswordResetToken(plainToken: string): Promise<string | null> {
        const tokenHash = hashToken(plainToken);

        const storedToken = await this.db.query.passwordResetTokens.findFirst({
            where: and(
                eq(passwordResetTokens.token, tokenHash),
                eq(passwordResetTokens.used, false),
                gt(passwordResetTokens.expiresAt, new Date())
            )
        });

        if (!storedToken) { return null; }
        return storedToken.userId;
    }

    async consumePasswordResetToken(plainToken: string): Promise<void> {
        const tokenHash = hashToken(plainToken);
        await this.db.update(passwordResetTokens)
            .set({ used: true })
            .where(eq(passwordResetTokens.token, tokenHash));
    }

    // =================================================================
    // EMAIL VERIFICATION
    // =================================================================

    async generateEmailVerificationToken(userId: string, email: string): Promise<string> {
        const plainToken = crypto.randomBytes(32).toString('hex');
        const tokenHash = hashToken(plainToken);
        const expiresAt = new Date(Date.now() + EMAIL_VERIFICATION_CONFIG.TOKEN_EXPIRY_MS);

        await this.db.insert(emailVerificationTokens).values({
            userId,
            token: tokenHash,
            expiresAt
        });

        await sendVerificationEmail(email, plainToken);

        return plainToken;
    }

    async verifyEmail(plainToken: string): Promise<boolean> {
        const tokenHash = hashToken(plainToken);

        const storedToken = await this.db.query.emailVerificationTokens.findFirst({
            where: and(
                eq(emailVerificationTokens.token, tokenHash),
                gt(emailVerificationTokens.expiresAt, new Date())
            )
        });

        if (!storedToken) { return false; }

        await this.db.update(users)
            .set({ emailVerified: true })
            .where(eq(users.id, storedToken.userId));

        await this.db.delete(emailVerificationTokens)
            .where(eq(emailVerificationTokens.id, storedToken.id));

        return true;
    }
    async cleanupExpiredTokens(): Promise<void> {
        const now = new Date();

        // SECURITY FIX: Delete tokens that are (revoked AND expired) OR just expired
        // Using OR logic to consolidate cleanup in one query
        await this.db.delete(refreshTokens)
            .where(lt(refreshTokens.expiresAt, now));

        await this.db.delete(passwordResetTokens)
            .where(lt(passwordResetTokens.expiresAt, now));

        await this.db.delete(emailVerificationTokens)
            .where(lt(emailVerificationTokens.expiresAt, now));

        // Cleanup old login attempts (30 days retention)
        await accountLockoutService.cleanupOldAttempts();

        log.info('Cleaned up expired tokens and old login attempts');
    }
}

export const authService = new AuthService();

import type { Block } from "@shared/schema";
import type {
  BlockContext,
  BlockResult,
  BlockPhase,
} from "@shared/types/blocks";
import type { LifecycleHookPhase } from "@shared/types/scripting";

import { db } from "../db";
import { logger } from "../logger";

import { analyticsService } from "./analytics/AnalyticsService";

// Import specialized block runners
import { BranchBlockRunner } from "./blockRunners/BranchBlockRunner";
import { CollectionBlockRunner } from "./blockRunners/CollectionBlockRunner";
import { ExternalSendBlockRunner } from "./blockRunners/ExternalSendBlockRunner";
import { ListToolsBlockRunner } from "./blockRunners/ListToolsBlockRunner";
import { PrefillBlockRunner } from "./blockRunners/PrefillBlockRunner";
import { QueryBlockRunner } from "./blockRunners/QueryBlockRunner";
import { ReadTableBlockRunner } from "./blockRunners/ReadTableBlockRunner";
import { ValidateBlockRunner } from "./blockRunners/ValidateBlockRunner";
import { WriteBlockRunner } from "./blockRunners/WriteBlockRunner";
import { blockService } from "./BlockService";
import { lifecycleHookService } from "./scripting/LifecycleHookService";
import { transformBlockService } from "./TransformBlockService";

import type { IBlockRunner } from "./blockRunners/types";


/**
 * BlockRunner Service
 * Executes blocks at various workflow runtime phases
 * Handles both generic blocks (prefill, validate, branch) and transform blocks (JS/Python)
 *
 * REFACTORED: Now uses strategy pattern with specialized block runners
 */
export class BlockRunner {
  private blockSvc: typeof blockService;
  private transformSvc: typeof transformBlockService;
  private runnerRegistry: Map<string, IBlockRunner>;

  constructor(
    blockSvc?: typeof blockService,
    transformSvc?: typeof transformBlockService
  ) {
    this.blockSvc = blockSvc || blockService;
    this.transformSvc = transformSvc || transformBlockService;

    // Initialize runner registry with specialized runners
    this.runnerRegistry = new Map();
    this.registerRunner(new PrefillBlockRunner());
    this.registerRunner(new ValidateBlockRunner());
    this.registerRunner(new BranchBlockRunner());
    this.registerRunner(new QueryBlockRunner());
    this.registerRunner(new WriteBlockRunner());
    this.registerRunner(new ExternalSendBlockRunner());
    this.registerRunner(new ReadTableBlockRunner());
    this.registerRunner(new ListToolsBlockRunner());

    // Collection runner handles multiple types
    const collectionRunner = new CollectionBlockRunner();
    this.runnerRegistry.set("create_record", collectionRunner);
    this.runnerRegistry.set("update_record", collectionRunner);
    this.runnerRegistry.set("find_record", collectionRunner);
    this.runnerRegistry.set("delete_record", collectionRunner);
  }

  /**
   * Register a block runner
   */
  private registerRunner(runner: IBlockRunner): void {
    this.runnerRegistry.set(runner.getBlockType(), runner);
  }

  /**
   * Get runner for a block type
   */
  private getRunner(blockType: string): IBlockRunner | undefined {
    return this.runnerRegistry.get(blockType);
  }

  /**
   * Run all blocks for a given phase WITH TRANSACTION WRAPPER
   * Execution order: lifecycle hooks ΓåÆ transform blocks ΓåÆ generic blocks
   *
   * TRANSACTION FIX: All write operations within this phase are wrapped in a single database
   * transaction. If any block fails, all previous writes are rolled back atomically.
   * Use this for critical workflows where data consistency is essential.
   *
   * NOTE: External side effects (HTTP calls, emails, external APIs) cannot be rolled back
   * by database transactions. Design your workflows accordingly.
   */
  async runPhaseWithTransaction(context: BlockContext): Promise<BlockResult> {
    return db.transaction(async (tx) => {
      // Execute the phase with transaction context
      return this.runPhase(context, tx);
    });
  }

  /**
   * Run all blocks for a given phase
   * Execution order: lifecycle hooks ΓåÆ transform blocks ΓåÆ generic blocks
   * Returns combined result from all blocks
   *
   * NOTE: Individual write operations use transactions (see WriteRunner), but cross-block
   * operations are not wrapped in a single transaction by default. Each block commits independently.
   * Use runPhaseWithTransaction() for atomic cross-block operations.
   *
   * @param context - Block execution context
   * @param tx - Optional database transaction (for atomic cross-block operations)
   */
  async runPhase(context: BlockContext, tx?: any): Promise<BlockResult> {
    let currentData = { ...context.data };
    const allErrors: string[] = [];
    let nextSectionId: string | undefined;

    // 0. Execute lifecycle hooks BEFORE other blocks (if runId is provided)
    if (context.runId) {
      // Map block phases to lifecycle hook phases
      const lifecyclePhaseMap: Record<BlockPhase, LifecycleHookPhase | null> = {
        onRunStart: null, // No lifecycle hook phase for onRunStart (could add if needed)
        onSectionEnter: "beforePage",
        onSectionSubmit: "afterPage",
        onNext: null, // No lifecycle hook phase for onNext
        onRunComplete: null, // No lifecycle hook phase for onRunComplete (could add beforeFinalBlock later)
      };

      const lifecyclePhase = lifecyclePhaseMap[context.phase];

      if (lifecyclePhase) {
        try {
          const lifecycleResult = await lifecycleHookService.executeHooksForPhase({
            workflowId: context.workflowId,
            runId: context.runId,
            phase: lifecyclePhase,
            sectionId: context.sectionId,
            data: currentData,
            userId: context.queryParams?.userId, // Optional user ID from context
          });

          // Merge lifecycle hook outputs into data
          currentData = { ...currentData, ...lifecycleResult.data };

          // Collect any lifecycle hook errors (non-breaking)
          if (lifecycleResult.errors) {
            for (const error of lifecycleResult.errors) {
              allErrors.push(`Lifecycle hook "${error.hookName}": ${error.error}`);
            }
          }

          // Log console output from lifecycle hooks (debug)
          if (lifecycleResult.consoleOutput && lifecycleResult.consoleOutput.length > 0) {
            logger.debug(
              {
                phase: lifecyclePhase,
                hookCount: lifecycleResult.consoleOutput.length,
              },
              "Lifecycle hooks produced console output"
            );
          }
        } catch (error) {
          logger.error({ error }, "Error executing lifecycle hooks in phase");
          allErrors.push(
            `Lifecycle hook execution failed: ${error instanceof Error ? error.message : "unknown error"}`
          );
        }
      }
    }

    // 1. Execute transform blocks (if runId is provided)
    if (context.runId) {
      try {
        const transformResult = await this.transformSvc.executeAllForPhase({
          workflowId: context.workflowId,
          runId: context.runId,
          phase: context.phase,
          sectionId: context.sectionId,
          data: currentData,
        });

        // Merge transform block outputs into data
        currentData = { ...currentData, ...transformResult.data };

        // Collect any transform block errors
        if (transformResult.errors) {
          for (const error of transformResult.errors) {
            allErrors.push(`Transform block "${error.blockName}": ${error.error}`);
          }
        }
      } catch (error) {
        logger.error({ error }, "Error executing transform blocks in phase");
        allErrors.push(`Transform block execution failed: ${error instanceof Error ? error.message : 'unknown error'}`);
      }
    }

    // 2. Execute generic blocks (prefill, validate, branch)
    const blocks = await this.blockSvc.getBlocksForPhase(
      context.workflowId,
      context.phase,
      context.sectionId
    );

    if (blocks.length === 0 && allErrors.length === 0) {
      return { success: true, data: currentData };
    }

    // Execute blocks in order
    for (const block of blocks) {
      const result = await this.executeBlock(block, {
        ...context,
        data: currentData,
      });

      if (!result.success) {
        if (result.errors) {
          allErrors.push(...result.errors);
        }
      }

      // Merge data updates from prefill blocks
      if (result.data) {
        currentData = { ...currentData, ...result.data };
      }

      // Capture branch decision (only first match wins)
      if (result.nextSectionId && !nextSectionId) {
        nextSectionId = result.nextSectionId;
      }
    }

    return {
      success: allErrors.length === 0,
      data: currentData,
      errors: allErrors.length > 0 ? allErrors : undefined,
      nextSectionId,
    };
  }

  /**
   * Execute a single block using strategy pattern
   *
   * REFACTORED: Delegates to specialized block runners based on block type
   */
  private async executeBlock(block: Block, context: BlockContext): Promise<BlockResult> {
    // Stage 15: Analytics - Block Start
    // ERROR HANDLING FIX: Wrap analytics in try/catch to prevent workflow crashes
    if (context.runId) {
      try {
        await analyticsService.recordEvent({
          runId: context.runId,
          workflowId: context.workflowId,
          versionId: context.versionId || 'draft',
          type: 'block.start',
          blockId: block.id,
          pageId: context.sectionId,
          timestamp: new Date().toISOString(),
          isPreview: context.mode === 'preview',
          payload: {
            blockType: block.type
          }
        });
      } catch (analyticsError) {
        // Log but don't fail the workflow due to analytics failures
        logger.warn({ error: analyticsError, blockId: block.id }, 'Failed to record block.start analytics event');
      }
    }

    let result: BlockResult;

    try {
      // Get appropriate runner for this block type
      const runner = this.getRunner(block.type as string);

      if (runner) {
        // Delegate to specialized runner
        result = await runner.execute(block.config, context, block);
      } else {
        logger.warn(`Unknown block type: ${block.type}`);
        result = { success: true };
      }
    } catch (error) {
      // Catch unexpected errors during block execution
      const errorMsg = error instanceof Error ? error.message : "unknown error";

      // ERROR HANDLING FIX: Wrap analytics in try/catch
      if (context.runId) {
        try {
          await analyticsService.recordEvent({
            runId: context.runId,
            workflowId: context.workflowId,
            versionId: context.versionId || 'draft',
            type: 'block.error',
            blockId: block.id,
            pageId: context.sectionId,
            timestamp: new Date().toISOString(),
            isPreview: context.mode === 'preview',
            payload: {
              error: errorMsg,
              blockType: block.type
            }
          });
        } catch (analyticsError) {
          logger.warn({ error: analyticsError, blockId: block.id }, 'Failed to record block.error analytics event');
        }
      }
      throw error;
    }

    // Stage 15: Analytics - Block End (Complete or Validated Error)
    // ERROR HANDLING FIX: Wrap analytics in try/catch
    if (context.runId) {
      try {
        const eventType = result.success ? 'block.complete' : 'validation.error';

        await analyticsService.recordEvent({
          runId: context.runId,
          workflowId: context.workflowId,
          versionId: context.versionId || 'draft',
          type: eventType,
          blockId: block.id,
          pageId: context.sectionId,
          timestamp: new Date().toISOString(),
          isPreview: context.mode === 'preview',
          payload: {
            blockType: block.type,
            errors: result.errors
          }
        });
      } catch (analyticsError) {
        logger.warn({ error: analyticsError, blockId: block.id }, 'Failed to record block completion analytics event');
      }
    }

    return result;
  }

}

// Singleton instance
export const blockRunner = new BlockRunner();

import crypto from "crypto";

import logger from "../logger";

import type { CaptchaChallenge, CaptchaResponse, CaptchaType } from "../../shared/types/intake.js";

/**
 * CAPTCHA Service for Intake Portal (Stage 12.5)
 *
 * Generates and validates CAPTCHA challenges for anti-bot protection.
 * Supports simple math puzzles (MVP) and reCAPTCHA (optional).
 */

interface StoredChallenge {
  answer: string;
  expiresAt: number;
  attempts: number;
}

const MAX_ATTEMPTS = 3;
const CHALLENGE_EXPIRY_MS = 10 * 60 * 1000; // 10 minutes

// In-memory store for challenges (would use Redis in production)
const challengeStore = new Map<string, StoredChallenge>();

export class CaptchaService {
  /**
   * Generate a simple math CAPTCHA challenge
   */
  static generateSimpleChallenge(): CaptchaChallenge {
    const num1 = Math.floor(Math.random() * 20) + 1; // 1-20
    const num2 = Math.floor(Math.random() * 20) + 1; // 1-20
    const answer = (num1 + num2).toString();
    const token = crypto.randomBytes(16).toString("hex");
    const expiresAt = Date.now() + CHALLENGE_EXPIRY_MS;

    // Store challenge
    challengeStore.set(token, {
      answer,
      expiresAt,
      attempts: 0,
    });

    // Clean up expired challenges periodically
    this.cleanupExpired();

    return {
      type: "simple",
      question: `What is ${num1} + ${num2}?`,
      token,
      expiresAt,
    };
  }

  /**
   * Validate a CAPTCHA response
   */
  static async validateCaptcha(
    response: CaptchaResponse,
    workflowId: string
  ): Promise<{ valid: boolean; error?: string }> {
    if (response.type === "simple") {
      return this.validateSimpleChallenge(response);
    } else if (response.type === "recaptcha") {
      return this.validateRecaptcha(response.recaptchaToken);
    }

    return { valid: false, error: "Invalid CAPTCHA type" };
  }

  /**
   * Validate simple math challenge
   */
  private static validateSimpleChallenge(
    response: CaptchaResponse
  ): { valid: boolean; error?: string } {
    const { token, answer } = response;

    if (!token || !answer) {
      return { valid: false, error: "Missing CAPTCHA token or answer" };
    }

    const challenge = challengeStore.get(token);

    if (!challenge) {
      return { valid: false, error: "Invalid or expired CAPTCHA token" };
    }

    // Check expiry
    if (Date.now() > challenge.expiresAt) {
      challengeStore.delete(token);
      return { valid: false, error: "CAPTCHA has expired" };
    }

    // Check attempts
    if (challenge.attempts >= MAX_ATTEMPTS) {
      challengeStore.delete(token);
      return { valid: false, error: "Too many attempts. Please refresh." };
    }

    // Increment attempts
    challenge.attempts++;

    // Check answer
    const isCorrect = answer.trim() === challenge.answer;

    if (isCorrect) {
      // Clean up used token
      challengeStore.delete(token);
      return { valid: true };
    } else {
      // Check if this was the last attempt
      if (challenge.attempts >= MAX_ATTEMPTS) {
        challengeStore.delete(token);
        return { valid: false, error: "Too many attempts. Please refresh." };
      }

      // Update attempt count
      challengeStore.set(token, challenge);
      return {
        valid: false,
        error: `Incorrect answer. ${MAX_ATTEMPTS - challenge.attempts} attempts remaining.`,
      };
    }
  }

  /**
   * Validate Google reCAPTCHA (optional feature)
   */
  private static async validateRecaptcha(
    recaptchaToken?: string
  ): Promise<{ valid: boolean; error?: string }> {
    if (!recaptchaToken) {
      return { valid: false, error: "Missing reCAPTCHA token" };
    }

    const secretKey = process.env.RECAPTCHA_SECRET;

    if (!secretKey) {
      logger.warn("RECAPTCHA_SECRET not configured. Falling back to simple CAPTCHA.");
      return { valid: false, error: "reCAPTCHA not configured on server" };
    }

    try {
      const response = await fetch("https://www.google.com/recaptcha/api/siteverify", {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
        },
        body: new URLSearchParams({
          secret: secretKey,
          response: recaptchaToken,
        }),
      });

      const data = await response.json();

      if (data.success) {
        return { valid: true };
      } else {
        logger.error({ errors: data["error-codes"] }, "reCAPTCHA validation failed");
        return { valid: false, error: "reCAPTCHA verification failed" };
      }
    } catch (error) {
      logger.error({ error }, "Error validating reCAPTCHA");
      return { valid: false, error: "Failed to verify reCAPTCHA" };
    }
  }

  /**
   * Clean up expired challenges
   */
  private static cleanupExpired(): void {
    const now = Date.now();
    for (const [token, challenge] of challengeStore.entries()) {
      if (now > challenge.expiresAt) {
        challengeStore.delete(token);
      }
    }
  }

  /**
   * Get challenge statistics (for monitoring)
   */
  static getStats(): { activeChallenges: number } {
    this.cleanupExpired();
    return {
      activeChallenges: challengeStore.size,
    };
  }
}

import {  or , sql } from "drizzle-orm";

import { blocks, transformBlocks } from "@shared/schema";
import type { DatavaultColumn, InsertDatavaultColumn } from "@shared/schema";

import { db } from "../db";
import { ConflictError } from "../errors/AppError";
import {
  datavaultColumnsRepository,
  datavaultTablesRepository,
  datavaultRowsRepository,
  type DbTransaction,
} from "../repositories";
/**
 * Service layer for DataVault column business logic
 * Handles column CRUD operations with validation and authorization
 */
export class DatavaultColumnsService {
  private columnsRepo: typeof datavaultColumnsRepository;
  private tablesRepo: typeof datavaultTablesRepository;
  private rowsRepo: typeof datavaultRowsRepository;
  constructor(
    columnsRepo?: typeof datavaultColumnsRepository,
    tablesRepo?: typeof datavaultTablesRepository,
    rowsRepo?: typeof datavaultRowsRepository
  ) {
    this.columnsRepo = columnsRepo || datavaultColumnsRepository;
    this.tablesRepo = tablesRepo || datavaultTablesRepository;
    this.rowsRepo = rowsRepo || datavaultRowsRepository;
  }
  /**
   * Generate URL-safe slug from name
   */
  private generateSlug(name: string): string {
    return name
      .toLowerCase()
      .trim()
      .replace(/[^a-z0-9]+/g, '_')
      .replace(/^_+|_+$/g, '');
  }
  /**
   * Ensure slug is unique for the table
   */
  private async ensureUniqueSlug(
    tableId: string,
    baseSlug: string,
    excludeId?: string,
    tx?: DbTransaction
  ): Promise<string> {
    let slug = baseSlug;
    let counter = 1;
    while (await this.columnsRepo.slugExists(tableId, slug, excludeId, tx)) {
      slug = `${baseSlug}_${counter}`;
      counter++;
    }
    return slug;
  }
  /**
   * Verify table belongs to tenant
   */
  private async verifyTableOwnership(
    tableId: string,
    tenantId: string,
    tx?: DbTransaction
  ): Promise<void> {
    const table = await this.tablesRepo.findById(tableId, tx);
    if (!table) {
      console.log(`[DEBUG] Table not found: ${tableId}`);
      throw new Error("Table not found");
    }
    if (table.tenantId !== tenantId) {
      throw new Error("Access denied - table belongs to different tenant");
    }
  }
  /**
   * Verify column belongs to tenant's table
   */
  async verifyColumnOwnership(
    columnId: string,
    tenantId: string,
    tx?: DbTransaction
  ): Promise<DatavaultColumn> {
    const column = await this.columnsRepo.findById(columnId, tx);
    if (!column) {
      throw new Error("Column not found");
    }
    // Verify the table belongs to the tenant
    await this.verifyTableOwnership(column.tableId, tenantId, tx);
    return column;
  }
  /**
   * Validate primary key constraints
   */
  private async validatePrimaryKey(
    tableId: string,
    isPrimaryKey: boolean,
    columnId?: string,
    tx?: DbTransaction
  ): Promise<void> {
    if (isPrimaryKey) {
      const columns = await this.columnsRepo.findByTableId(tableId, tx);
      const existingPrimaryKey = columns.find(c => c.isPrimaryKey && c.id !== columnId);
      if (existingPrimaryKey) {
        throw new Error(
          `Table already has a primary key column: "${existingPrimaryKey.name}". ` +
          `Each table can only have one primary key. Please unset the existing primary key first.`
        );
      }
    }
  }
  /**
   * Validate unique constraints for column values
   */
  private async validateUniqueConstraint(
    columnId: string,
    isUnique: boolean,
    tx?: DbTransaction
  ): Promise<void> {
    if (isUnique) {
      // Check if there are duplicate values in existing rows
      const hasDuplicates = await this.rowsRepo.checkColumnHasDuplicates(columnId, tx);
      if (hasDuplicates) {
        throw new Error(
          'Cannot make this column unique because it contains duplicate values. ' +
          'Please remove duplicates first.'
        );
      }
    }
  }
  /**
   * Validate select/multiselect column options
   */
  private validateSelectOptions(
    type: string,
    options: any | null | undefined
  ): void {
    if (type === 'select' || type === 'multiselect') {
      // Select/multiselect columns require options
      if (!options || !Array.isArray(options) || options.length === 0) {
        throw new Error('Select and multiselect columns require at least one option');
      }
      // Validate option structure
      const valueSet = new Set<string>();
      for (const option of options) {
        if (!option.label || !option.value) {
          throw new Error('Each option must have both label and value');
        }
        // Check for duplicate values
        if (valueSet.has(option.value)) {
          throw new Error(`Duplicate option value: ${option.value}`);
        }
        valueSet.add(option.value);
        // Validate color if provided (simple Tailwind color names)
        if (option.color && typeof option.color !== 'string') {
          throw new Error('Option color must be a string');
        }
      }
    }
  }
  /**
   * Validate reference column configuration
   */
  private async validateReferenceColumn(
    type: string,
    referenceTableId: string | null | undefined,
    referenceDisplayColumnSlug: string | null | undefined,
    tenantId: string,
    tx?: DbTransaction
  ): Promise<void> {
    if (type === 'reference') {
      // Reference columns require referenceTableId
      if (!referenceTableId) {
        throw new Error('Reference columns require referenceTableId');
      }
      // Verify the referenced table exists and belongs to the same tenant
      const refTable = await this.tablesRepo.findById(referenceTableId, tx);
      if (!refTable) {
        throw new Error('Referenced table not found');
      }
      if (refTable.tenantId !== tenantId) {
        throw new Error('Referenced table must belong to the same tenant');
      }
      // If displayColumnSlug is provided, verify it exists in the referenced table
      if (referenceDisplayColumnSlug) {
        const refColumn = await this.columnsRepo.findByTableAndSlug(
          referenceTableId,
          referenceDisplayColumnSlug,
          tx
        );
        if (!refColumn) {
          throw new Error(
            `Display column '${referenceDisplayColumnSlug}' not found in referenced table`
          );
        }
      }
    }
  }
  /**
   * Detect circular reference dependencies
   * Uses depth-first search to find cycles in the reference graph
   */
  private async detectCircularReference(
    tableId: string,
    referenceTableId: string,
    tx?: DbTransaction
  ): Promise<boolean> {
    const visited = new Set<string>();
    const recursionStack = new Set<string>();
    const hasCycle = async (currentTableId: string): Promise<boolean> => {
      if (recursionStack.has(currentTableId)) {
        return true; // Cycle detected
      }
      if (visited.has(currentTableId)) {
        return false; // Already checked this path
      }
      visited.add(currentTableId);
      recursionStack.add(currentTableId);
      // Get all reference columns for current table
      const columns = await this.columnsRepo.findByTableId(currentTableId, tx);
      const referenceColumns = columns.filter(col => col.type === 'reference' && col.referenceTableId);
      // Check each reference for cycles
      for (const col of referenceColumns) {
        if (await hasCycle(col.referenceTableId!)) {
          return true;
        }
      }
      recursionStack.delete(currentTableId);
      return false;
    };
    // Simulate adding the new reference and check for cycles
    return hasCycle(referenceTableId);
  }
  /**
   * Create a new column
   */
  async createColumn(
    data: InsertDatavaultColumn,
    tenantId: string,
    tx?: DbTransaction
  ): Promise<DatavaultColumn> {
    // Verify table ownership
    await this.verifyTableOwnership(data.tableId, tenantId, tx);
    // Validate select/multiselect options
    this.validateSelectOptions(data.type, data.options);
    // Validate reference column configuration
    await this.validateReferenceColumn(
      data.type,
      data.referenceTableId,
      data.referenceDisplayColumnSlug,
      tenantId,
      tx
    );
    // Check for circular reference dependencies
    if (data.type === 'reference' && data.referenceTableId) {
      const hasCircularRef = await this.detectCircularReference(
        data.tableId,
        data.referenceTableId,
        tx
      );
      if (hasCircularRef) {
        throw new ConflictError(
          `Cannot create reference column: would create circular dependency with table ${data.referenceTableId}`
        );
      }
    }
    // Clear reference fields if type is not 'reference'
    let referenceTableId = data.referenceTableId;
    let referenceDisplayColumnSlug = data.referenceDisplayColumnSlug;
    if (data.type !== 'reference') {
      referenceTableId = null;
      referenceDisplayColumnSlug = null;
    }
    // Clear options if type is not 'select' or 'multiselect'
    let options = data.options;
    if (data.type !== 'select' && data.type !== 'multiselect') {
      options = null;
    }
    // Validate primary key constraints
    if (data.isPrimaryKey) {
      await this.validatePrimaryKey(data.tableId, true, undefined, tx);
    }
    // Generate slug if not provided
    const baseSlug = data.slug || this.generateSlug(data.name);
    const uniqueSlug = await this.ensureUniqueSlug(data.tableId, baseSlug, undefined, tx);
    // Get next order index if not provided
    let orderIndex = data.orderIndex;
    if (orderIndex === undefined || orderIndex === null) {
      const maxOrder = await this.columnsRepo.getMaxOrderIndex(data.tableId, tx);
      orderIndex = maxOrder + 1;
    }
    // Primary key columns must be required and unique
    const required = data.isPrimaryKey ? true : (data.required ?? false);
    const isUnique = data.isPrimaryKey ? true : (data.isUnique ?? false);
    return this.columnsRepo.create(
      {
        ...data,
        slug: uniqueSlug,
        orderIndex,
        required,
        isUnique,
        referenceTableId,
        referenceDisplayColumnSlug,
        options,
      },
      tx
    );
  }
  /**
   * Get column by ID with tenant verification
   */
  async getColumn(
    columnId: string,
    tenantId: string,
    tx?: DbTransaction
  ): Promise<DatavaultColumn> {
    return this.verifyColumnOwnership(columnId, tenantId, tx);
  }
  /**
   * List columns for a table
   */
  async listColumns(
    tableId: string,
    tenantId: string,
    tx?: DbTransaction
  ): Promise<DatavaultColumn[]> {
    await this.verifyTableOwnership(tableId, tenantId, tx);
    return this.columnsRepo.findByTableId(tableId, tx);
  }
  /**
   * Update column (name only - type changes not allowed)
   */
  async updateColumn(
    columnId: string,
    tenantId: string,
    data: Partial<InsertDatavaultColumn>,
    tx?: DbTransaction
  ): Promise<DatavaultColumn> {
    const column = await this.verifyColumnOwnership(columnId, tenantId, tx);
    // Prevent type changes
    if (data.type && data.type !== column.type) {
      throw new Error("Cannot change column type after creation");
    }
    // If select/multiselect options are being updated, validate them
    const typeToValidate = data.type || column.type;
    const optionsToValidate = data.options !== undefined ? data.options : column.options;
    this.validateSelectOptions(typeToValidate, optionsToValidate);
    // If reference-related fields are being updated, validate them
    const refTableId = data.referenceTableId !== undefined ? data.referenceTableId : column.referenceTableId;
    const refDisplaySlug = data.referenceDisplayColumnSlug !== undefined
      ? data.referenceDisplayColumnSlug
      : column.referenceDisplayColumnSlug;
    await this.validateReferenceColumn(
      typeToValidate,
      refTableId,
      refDisplaySlug,
      tenantId,
      tx
    );
    // Check for circular reference dependencies if referenceTableId is being changed
    if (typeToValidate === 'reference' && refTableId && refTableId !== column.referenceTableId) {
      const hasCircularRef = await this.detectCircularReference(
        column.tableId,
        refTableId,
        tx
      );
      if (hasCircularRef) {
        throw new ConflictError(
          `Cannot update reference column: would create circular dependency with table ${refTableId}`
        );
      }
    }
    // Clear reference fields if type is not 'reference'
    if (typeToValidate !== 'reference') {
      data.referenceTableId = null;
      data.referenceDisplayColumnSlug = null;
    }
    // Clear options if type is not 'select' or 'multiselect'
    if (typeToValidate !== 'select' && typeToValidate !== 'multiselect') {
      data.options = null;
    }
    // Validate primary key changes
    if (data.isPrimaryKey !== undefined && data.isPrimaryKey !== column.isPrimaryKey) {
      if (data.isPrimaryKey) {
        // Setting as primary key
        await this.validatePrimaryKey(column.tableId, true, columnId, tx);
      } else {
        // Removing primary key - check if table has at least one other column
        const allColumns = await this.columnsRepo.findByTableId(column.tableId, tx);
        if (allColumns.length === 1) {
          throw new Error(
            'Cannot remove primary key from the only column in the table. ' +
            'Tables must have at least one primary key column.'
          );
        }
        // If removing primary key, warn that another column should be designated
        // (this is handled by the frontend)
      }
    }
    // Validate unique constraint changes
    if (data.isUnique !== undefined && data.isUnique && !column.isUnique) {
      await this.validateUniqueConstraint(columnId, true, tx);
    }
    // If name changed, regenerate slug
    if (data.name && !data.slug) {
      const baseSlug = this.generateSlug(data.name);
      data.slug = await this.ensureUniqueSlug(column.tableId, baseSlug, columnId, tx);
    }
    // If slug provided, ensure it's unique
    if (data.slug) {
      data.slug = await this.ensureUniqueSlug(column.tableId, data.slug, columnId, tx);
    }
    // If setting as primary key, force required and unique
    if (data.isPrimaryKey) {
      data.required = true;
      data.isUnique = true;
    }
    return this.columnsRepo.update(columnId, data, tx);
  }
  /**
   * Delete column (also deletes all associated values)
   */
  async deleteColumn(columnId: string, tenantId: string, tx?: DbTransaction): Promise<void> {
    const column = await this.verifyColumnOwnership(columnId, tenantId, tx);
    // Guardrail: Check for references in workflows
    await this.checkColumnUsage(columnId, tx);
    // Prevent deleting the only primary key column
    if (column.isPrimaryKey) {
      const allColumns = await this.columnsRepo.findByTableId(column.tableId, tx);
      const primaryKeyColumns = allColumns.filter(c => c.isPrimaryKey);
      if (primaryKeyColumns.length === 1) {
        throw new Error(
          'Cannot delete the primary key column. Tables must have at least one primary key column. ' +
          'Please designate another column as the primary key before deleting this one.'
        );
      }
    }
    // Delete all values for this column first (though CASCADE should handle it)
    await this.rowsRepo.deleteValuesByColumnId(columnId, tx);
    // If this is an auto-number column, cleanup its PostgreSQL sequence
    if (column.type === 'auto_number') {
      await this.rowsRepo.cleanupAutoNumberSequence(columnId, tx);
    }
    // Delete the column
    await this.columnsRepo.delete(columnId, tx);
  }
  /**
   * Reorder columns for a table
   */
  async reorderColumns(
    tableId: string,
    tenantId: string,
    columnIds: string[],
    tx?: DbTransaction
  ): Promise<void> {
    await this.verifyTableOwnership(tableId, tenantId, tx);
    // Verify all columns belong to the table
    const columns = await this.columnsRepo.findByTableId(tableId, tx);
    const tableColumnIds = new Set(columns.map((c) => c.id));
    for (const columnId of columnIds) {
      if (!tableColumnIds.has(columnId)) {
        throw new Error(`Column ${columnId} does not belong to table ${tableId}`);
      }
    }
    await this.columnsRepo.reorderColumns(tableId, columnIds, tx);
  }
  /**
   * Get column by slug
   */
  async getColumnBySlug(
    tableId: string,
    tenantId: string,
    slug: string,
    tx?: DbTransaction
  ): Promise<DatavaultColumn | undefined> {
    await this.verifyTableOwnership(tableId, tenantId, tx);
    return this.columnsRepo.findByTableAndSlug(tableId, slug, tx);
  }
  /**
   * Check if column is used in any workflows (blocks or transforms)
   * This is a guardrail to prevent breaking changes
   */
  private async checkColumnUsage(columnId: string, tx?: DbTransaction): Promise<void> {
    const database = tx || db;
    // Check blocks config for column ID reference (naive JSON string search for UUID)
    // This catches usage in "Create Record", "Update Record", etc.
    const matchingBlocks = await database
      .select({ id: blocks.id, type: blocks.type, workflowId: blocks.workflowId })
      .from(blocks)
      .where(sql`${blocks.config}::text LIKE ${`%${columnId}%`}`)
      .limit(1);
    if (matchingBlocks.length > 0) {
      throw new Error(
        `Cannot delete column: It is referenced by a ${matchingBlocks[0].type} block in workflow ${matchingBlocks[0].workflowId}`
      );
    }
    // Check transform blocks code or config
    const matchingTransforms = await database
      .select({ id: transformBlocks.id, name: transformBlocks.name, workflowId: transformBlocks.workflowId })
      .from(transformBlocks)
      .where(
        or(
          sql`${transformBlocks.code} LIKE ${`%${columnId}%`}`,
          sql`${transformBlocks.inputKeys}::text LIKE ${`%${columnId}%`}`
        )
      )
      .limit(1);
    if (matchingTransforms.length > 0) {
      throw new Error(
        `Cannot delete column: It is referenced by transform block "${matchingTransforms[0].name}" in workflow ${matchingTransforms[0].workflowId}`
      );
    }
  }
}
// Singleton instance
export const datavaultColumnsService = new DatavaultColumnsService();

import type { DatavaultRow, InsertDatavaultRow, DatavaultColumn } from "@shared/schema";

import { db } from "../db";
import {
  datavaultRowsRepository,
  datavaultTablesRepository,
  datavaultColumnsRepository,
  type DbTransaction,
} from "../repositories";

/**
 * Service layer for DataVault row business logic
 * Handles row and value CRUD operations with validation and type coercion
 */
export class DatavaultRowsService {
  private rowsRepo: typeof datavaultRowsRepository;
  private tablesRepo: typeof datavaultTablesRepository;
  private columnsRepo: typeof datavaultColumnsRepository;

  constructor(
    rowsRepo?: typeof datavaultRowsRepository,
    tablesRepo?: typeof datavaultTablesRepository,
    columnsRepo?: typeof datavaultColumnsRepository
  ) {
    this.rowsRepo = rowsRepo || datavaultRowsRepository;
    this.tablesRepo = tablesRepo || datavaultTablesRepository;
    this.columnsRepo = columnsRepo || datavaultColumnsRepository;
  }

  /**
   * Verify table belongs to tenant
   */
  private async verifyTableOwnership(
    tableId: string,
    tenantId: string,
    tx?: DbTransaction
  ): Promise<void> {
    const table = await this.tablesRepo.findById(tableId, tx);

    if (!table) {
      throw new Error("Table not found");
    }

    if (table.tenantId !== tenantId) {
      throw new Error("Access denied - table belongs to different tenant");
    }
  }

  /**
   * Verify row belongs to tenant's table
   */
  async verifyRowOwnership(
    rowId: string,
    tenantId: string,
    tx?: DbTransaction
  ): Promise<DatavaultRow> {
    const row = await this.rowsRepo.findById(rowId, tx);

    if (!row) {
      throw new Error("Row not found");
    }

    // Verify the table belongs to the tenant
    await this.verifyTableOwnership(row.tableId, tenantId, tx);

    return row;
  }

  /**
   * Validate and coerce value based on column type
   */
  private validateAndCoerceValue(value: any, column: DatavaultColumn): any {
    if (value === null || value === undefined) {
      if (column.required && column.type !== 'auto_number' && column.type !== 'autonumber') {
        throw new Error(`Column '${column.name}' is required`);
      }
      return null;
    }

    switch (column.type) {
      case 'text':
      case 'email':
      case 'phone':
      case 'url':
        return String(value);

      case 'number':
        const num = Number(value);
        if (isNaN(num)) {
          throw new Error(`Column '${column.name}' must be a valid number`);
        }
        return num;

      case 'auto_number':
      case 'autonumber':
        // Auto-number values should be strings (for autonumber with prefix) or numbers (legacy auto_number)
        // The value is generated automatically, so we just validate it exists
        return typeof value === 'string' ? value : Number(value);

      case 'boolean':
        if (typeof value === 'boolean') {return value;}
        if (typeof value === 'string') {
          const lower = value.toLowerCase();
          if (lower === 'true' || lower === '1' || lower === 'yes') {return true;}
          if (lower === 'false' || lower === '0' || lower === 'no') {return false;}
        }
        return Boolean(value);

      case 'date':
      case 'datetime':
        if (value instanceof Date) {return value.toISOString();}
        const date = new Date(value);
        if (isNaN(date.getTime())) {
          throw new Error(`Column '${column.name}' must be a valid date`);
        }
        return date.toISOString();

      case 'json':
        if (typeof value === 'object') {return value;}
        try {
          return JSON.parse(String(value));
        } catch {
          throw new Error(`Column '${column.name}' must be valid JSON`);
        }

      case 'reference':
        // Reference values must be valid UUIDs
        const stringValue = String(value);
        const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
        if (!uuidRegex.test(stringValue)) {
          throw new Error(`Column '${column.name}' must be a valid UUID reference`);
        }
        return stringValue;

      case 'select':
        // Select values must be one of the defined options
        const selectValue = String(value);
        const selectOptions = column.options as Array<{ value: string; label: string; color?: string }> | null;
        if (!selectOptions || selectOptions.length === 0) {
          throw new Error(`Column '${column.name}' has no defined options`);
        }
        const validSelectValues = new Set(selectOptions.map(opt => opt.value));
        if (!validSelectValues.has(selectValue)) {
          throw new Error(
            `Column '${column.name}' value must be one of: ${Array.from(validSelectValues).join(', ')}`
          );
        }
        return selectValue;

      case 'multiselect':
        // Multiselect values must be an array of valid option values
        let multiselectValues: string[];
        if (Array.isArray(value)) {
          multiselectValues = value.map(v => String(v));
        } else {
          throw new Error(`Column '${column.name}' must be an array`);
        }
        const multiselectOptions = column.options as Array<{ value: string; label: string; color?: string }> | null;
        if (!multiselectOptions || multiselectOptions.length === 0) {
          throw new Error(`Column '${column.name}' has no defined options`);
        }
        const validMultiselectValues = new Set(multiselectOptions.map(opt => opt.value));
        for (const val of multiselectValues) {
          if (!validMultiselectValues.has(val)) {
            throw new Error(
              `Column '${column.name}' contains invalid value '${val}'. Valid values: ${Array.from(validMultiselectValues).join(', ')}`
            );
          }
        }
        return multiselectValues;

      default:
        return value;
    }
  }

  /**
   * Validate row data against column definitions
   */
  private async validateRowData(
    tableId: string,
    values: Record<string, any>,
    tx?: DbTransaction
  ): Promise<Array<{ columnId: string; value: any }>> {
    const columns = await this.columnsRepo.findByTableId(tableId, tx);
    const columnMap = new Map(columns.map((c) => [c.id, c]));
    const validatedValues: Array<{ columnId: string; value: any }> = [];

    // Check required columns (excluding auto_number columns)
    for (const column of columns) {
      if (column.required && column.type !== 'auto_number' && column.type !== 'autonumber' && !(column.id in values)) {
        throw new Error(`Required column '${column.name}' is missing`);
      }
    }

    // Generate auto-number values for auto_number and autonumber columns
    // Get tenant ID for autonumber sequence
    const table = await this.tablesRepo.findById(tableId, tx);
    if (!table) {
      throw new Error('Table not found');
    }
    const tenantId = table.tenantId;

    try {
      for (const column of columns) {
        // Handle legacy auto_number type
        if (column.type === 'auto_number' && !(column.id in values)) {
          const startValue = column.autoNumberStart ?? 1;
          const nextNumber = await this.rowsRepo.getNextAutoNumber(tableId, column.id, startValue, tx);
          values[column.id] = nextNumber;
        }

        // Handle new autonumber type with prefix, padding, and yearly reset
        if (column.type === 'autonumber' && !(column.id in values)) {
          const prefix = column.autonumberPrefix ?? null;
          const padding = column.autonumberPadding ?? 4;
          const resetPolicy = column.autonumberResetPolicy ?? 'never';
          const options = column.options as any;
          const format = options?.format ?? null;

          const nextValue = await this.rowsRepo.getNextAutonumber(
            tenantId,
            tableId,
            column.id,
            { prefix, padding, resetPolicy, format, tx }
          );
          values[column.id] = nextValue;
        }
      }
    } catch (error) {
      throw error;
    }

    // Validate and coerce each value
    for (const [columnId, value] of Object.entries(values)) {
      const column = columnMap.get(columnId);
      if (!column) {
        throw new Error(`Column ${columnId} not found in table`);
      }

      const coercedValue = this.validateAndCoerceValue(value, column);

      // Additional validation for reference columns
      if (column.type === 'reference' && coercedValue !== null && column.referenceTableId) {
        // Verify the referenced row exists in the referenced table
        const referencedRow = await this.rowsRepo.findById(coercedValue, tx);
        if (!referencedRow) {
          throw new Error(
            `Column '${column.name}' references a non-existent row: ${coercedValue}`
          );
        }
        // Verify the referenced row belongs to the correct table
        if (referencedRow.tableId !== column.referenceTableId) {
          throw new Error(
            `Column '${column.name}' references a row from the wrong table`
          );
        }
      }

      validatedValues.push({ columnId, value: coercedValue });
    }

    return validatedValues;
  }

  /**
   * Create a new row with values
   * Wrapped in transaction to ensure atomicity
   */
  async createRow(
    tableId: string,
    tenantId: string,
    values: Record<string, any>,
    createdBy?: string,
    tx?: DbTransaction
  ): Promise<{ row: DatavaultRow; values: Record<string, any> }> {
    // If transaction provided, use it; otherwise create a new one
    if (tx) {
      return this._createRowImpl(tableId, tenantId, values, createdBy, tx);
    }

    return db.transaction(async (newTx: DbTransaction) => {
      return this._createRowImpl(tableId, tenantId, values, createdBy, newTx);
    });
  }

  /**
   * Internal implementation of createRow
   * Must be called within a transaction
   */
  private async _createRowImpl(
    tableId: string,
    tenantId: string,
    values: Record<string, any>,
    createdBy: string | undefined,
    tx: DbTransaction
  ): Promise<{ row: DatavaultRow; values: Record<string, any> }> {
    await this.verifyTableOwnership(tableId, tenantId, tx);

    // Validate and coerce values
    const validatedValues = await this.validateRowData(tableId, values, tx);

    // Create row with values
    const result = await this.rowsRepo.createRowWithValues(
      {
        tableId,
        createdBy,
        updatedBy: createdBy,
      },
      validatedValues,
      tx
    );

    // Transform values array into Record<columnId, value>
    const valuesRecord: Record<string, any> = {};
    for (const valueObj of result.values) {
      valuesRecord[valueObj.columnId] = valueObj.value;
    }

    return {
      row: result.row,
      values: valuesRecord,
    };
  }

  /**
   * Get row by ID with tenant verification
   */
  async getRow(rowId: string, tenantId: string, tx?: DbTransaction): Promise<{ row: DatavaultRow; values: Record<string, any> } | null> {
    const row = await this.verifyRowOwnership(rowId, tenantId, tx);
    const result = await this.rowsRepo.getRowWithValues(rowId, tx);

    if (!result) {return null;}

    // Transform values array into Record<columnId, value>
    const valuesRecord: Record<string, any> = {};
    for (const valueObj of result.values) {
      valuesRecord[valueObj.columnId] = valueObj.value;
    }

    return {
      row: result.row,
      values: valuesRecord,
    };
  }

  /**
   * List rows for a table with pagination
   */
  async listRows(
    tableId: string,
    tenantId: string,
    options?: {
      limit?: number;
      offset?: number;
    },
    tx?: DbTransaction
  ) {
    await this.verifyTableOwnership(tableId, tenantId, tx);
    return this.rowsRepo.getRowsWithValues(tableId, options, tx);
  }

  /**
   * Count rows for a table
   */
  async countRows(tableId: string, tenantId: string, tx?: DbTransaction): Promise<number> {
    await this.verifyTableOwnership(tableId, tenantId, tx);
    return this.rowsRepo.countByTableId(tableId, tx);
  }

  /**
   * Update row values
   * Wrapped in transaction to ensure atomicity
   */
  async updateRow(
    rowId: string,
    tenantId: string,
    values: Record<string, any>,
    updatedBy?: string,
    tx?: DbTransaction
  ): Promise<void> {
    // If transaction provided, use it; otherwise create a new one
    if (tx) {
      return this._updateRowImpl(rowId, tenantId, values, updatedBy, tx);
    }

    return db.transaction(async (newTx: DbTransaction) => {
      return this._updateRowImpl(rowId, tenantId, values, updatedBy, newTx);
    });
  }

  /**
   * Internal implementation of updateRow
   * Must be called within a transaction
   */
  private async _updateRowImpl(
    rowId: string,
    tenantId: string,
    values: Record<string, any>,
    updatedBy: string | undefined,
    tx: DbTransaction
  ): Promise<void> {
    const row = await this.verifyRowOwnership(rowId, tenantId, tx);

    // Validate and coerce values (only for provided columns)
    const validatedValues = await this.validateRowData(row.tableId, values, tx);

    // Update row values
    await this.rowsRepo.updateRowValues(rowId, validatedValues, updatedBy, tx);
  }

  /**
   * Check if row is referenced by other rows
   * Returns list of tables/columns that reference this row
   */
  async getRowReferences(
    rowId: string,
    tenantId: string,
    tx?: DbTransaction
  ): Promise<Array<{ referencingTableId: string; referencingColumnId: string; referenceCount: number }>> {
    await this.verifyRowOwnership(rowId, tenantId, tx);
    return this.rowsRepo.getRowReferences(rowId, tx);
  }

  /**
   * Delete row
   * Note: References to this row will be automatically set to NULL by database trigger
   */
  async deleteRow(rowId: string, tenantId: string, tx?: DbTransaction): Promise<void> {
    await this.verifyRowOwnership(rowId, tenantId, tx);
    await this.rowsRepo.deleteRow(rowId, tx);
  }

  /**
   * Bulk delete rows
   * Uses batch operations for efficiency (2 queries instead of 2N)
   * Wrapped in transaction to ensure atomicity
   */
  async bulkDeleteRows(
    rowIds: string[],
    tenantId: string,
    tx?: DbTransaction
  ): Promise<void> {
    if (rowIds.length === 0) {return;}

    // If transaction provided, use it; otherwise create a new one
    if (tx) {
      return this._bulkDeleteRowsImpl(rowIds, tenantId, tx);
    }

    return db.transaction(async (newTx: DbTransaction) => {
      return this._bulkDeleteRowsImpl(rowIds, tenantId, newTx);
    });
  }

  /**
   * Internal implementation of bulkDeleteRows
   * Must be called within a transaction
   */
  private async _bulkDeleteRowsImpl(
    rowIds: string[],
    tenantId: string,
    tx: DbTransaction
  ): Promise<void> {
    // Batch verify ownership (1 query instead of N)
    await this.rowsRepo.batchVerifyOwnership(rowIds, tenantId, tx);

    // Batch delete (1 query instead of N)
    await this.rowsRepo.batchDeleteRows(rowIds, tx);
  }

  /**
   * Batch resolve reference values
   * Efficiently fetches multiple referenced rows in a single query
   * Fixes N+1 query problem for reference columns
   *
   * @param requests Array of {tableId, rowIds[], displayColumnSlug} objects
   * @param tenantId Tenant ID for authorization
   * @returns Map of rowId -> {displayValue, row}
   */
  async batchResolveReferences(
    requests: Array<{
      tableId: string;
      rowIds: string[];
      displayColumnSlug?: string;
    }>,
    tenantId: string,
    tx?: DbTransaction
  ): Promise<Map<string, { displayValue: string; row: any }>> {
    const resultMap = new Map<string, { displayValue: string; row: any }>();

    if (requests.length === 0) {return resultMap;}

    // Verify all tables belong to tenant
    const uniqueTableIds = [...new Set(requests.map(r => r.tableId))];
    for (const tableId of uniqueTableIds) {
      await this.verifyTableOwnership(tableId, tenantId, tx);
    }

    // Batch fetch all rows
    const rowData = await this.rowsRepo.batchFindByIds(requests, tx);

    // Extract display values
    requests.forEach(({ tableId, rowIds, displayColumnSlug }) => {
      rowIds.forEach(rowId => {
        const data = rowData.get(rowId);
        if (!data) {
          // Row not found, create placeholder
          resultMap.set(rowId, {
            displayValue: 'Not found',
            row: null
          });
          return;
        }

        let displayValue: string;
        if (displayColumnSlug && data.values[displayColumnSlug] !== undefined) {
          displayValue = String(data.values[displayColumnSlug]);
        } else {
          // Fallback to row ID if no display column specified
          displayValue = `${rowId.substring(0, 8)  }...`;
        }

        resultMap.set(rowId, {
          displayValue,
          row: {
            ...data.row,
            values: data.values
          }
        });
      });
    });

    return resultMap;
  }

  /**
   * Archive (soft delete) a row
   */
  async archiveRow(
    tenantId: string,
    rowId: string,
    tx?: DbTransaction
  ): Promise<void> {
    // Verify ownership
    await this.verifyRowOwnership(rowId, tenantId, tx);

    // Archive the row
    await this.rowsRepo.archiveRow(rowId, tx);
  }

  /**
   * Unarchive (restore) a row
   */
  async unarchiveRow(
    tenantId: string,
    rowId: string,
    tx?: DbTransaction
  ): Promise<void> {
    // Verify ownership
    await this.verifyRowOwnership(rowId, tenantId, tx);

    // Unarchive the row
    await this.rowsRepo.unarchiveRow(rowId, tx);
  }

  /**
   * Bulk archive rows
   */
  async bulkArchiveRows(
    tenantId: string,
    rowIds: string[],
    tx?: DbTransaction
  ): Promise<void> {
    if (rowIds.length === 0) {return;}

    // Verify all rows belong to tenant
    await this.rowsRepo.batchVerifyOwnership(rowIds, tenantId, tx);

    // Bulk archive
    await this.rowsRepo.bulkArchiveRows(rowIds, tx);
  }

  /**
   * Bulk unarchive rows
   */
  async bulkUnarchiveRows(
    tenantId: string,
    rowIds: string[],
    tx?: DbTransaction
  ): Promise<void> {
    if (rowIds.length === 0) {return;}

    // Verify all rows belong to tenant
    await this.rowsRepo.batchVerifyOwnership(rowIds, tenantId, tx);

    // Bulk unarchive
    await this.rowsRepo.bulkUnarchiveRows(rowIds, tx);
  }

  /**
   * Get rows with filtering, sorting, and archiving support
   */
  async getRowsWithOptions(
    tenantId: string,
    tableId: string,
    options: {
      limit?: number;
      offset?: number;
      showArchived?: boolean;
      sortBy?: string;
      sortOrder?: 'asc' | 'desc';
    } = {},
    tx?: DbTransaction
  ): Promise<{
    rows: Array<{ row: DatavaultRow; values: Record<string, any> }>;
    total: number;
  }> {
    // Verify table ownership
    await this.verifyTableOwnership(tableId, tenantId, tx);

    // Get rows
    const rows = await this.rowsRepo.getRowsWithValues(tableId, options, tx);

    // Get total count
    const total = await this.rowsRepo.countByTableIdWithFilter(
      tableId,
      options.showArchived ?? false,
      tx
    );

    return { rows, total };
  }
}

