import { randomUUID } from "crypto";

import type { Workflow, WorkflowRun, InsertStepValue } from "@shared/schema";


import { IntakeConfigSchema } from "../../shared/zod-schemas.js";
import { createLogger } from "../logger";
import { workflowRepository, workflowRunRepository, stepValueRepository, sectionRepository, projectRepository, stepRepository } from "../repositories";

import { CaptchaService } from "./CaptchaService.js";
import { intakeReceiptService } from "./IntakeReceiptService";
import { runService } from "./RunService";

import type { IntakeConfig, IntakeSubmitResult, CaptchaResponse } from "../../shared/types/intake.js";

const logger = createLogger({ module: "intake-service" });

/**
 * Service for public intake portal
 * Handles anonymous and authenticated workflow runs via public links
 */
export class IntakeService {
  /**
   * Get published workflow by slug (for intake portal)
   * Returns workflow metadata and tenant branding info
   */
  async getPublishedWorkflow(slug: string): Promise<{
    workflow: Workflow;
    sections: any[];
    intakeConfig: IntakeConfig;
    tenantBranding?: {
      name: string;
      logo?: string;
      primaryColor?: string;
    };
  }> {
    // PERFORMANCE FIX: Use indexed query instead of loading all workflows
    const workflow = await workflowRepository.findBySlug(slug);

    if (!workflow) {
      throw new Error("Workflow not found");
    }

    if (!workflow.isPublic) {
      throw new Error("Workflow is not public");
    }

    // Get workflow sections and steps
    const sections = await sectionRepository.findByWorkflowId(workflow.id);

    // Parse intakeConfig (JSONB field)
    const parsedConfig = IntakeConfigSchema.safeParse(workflow.intakeConfig);
    const intakeConfig: IntakeConfig = parsedConfig.success ? parsedConfig.data : {};
    if (!parsedConfig.success) {
      logger.warn({ workflowId: workflow.id, error: parsedConfig.error }, "Invalid intake configuration found");
    }

    // Get tenant branding (if projectId exists)
    let tenantBranding;
    if (workflow.projectId) {
      const project = await projectRepository.findById(workflow.projectId);
      if (project?.name) {
        // TODO: Add tenant branding fields to schema
        tenantBranding = {
          name: project.name,
        };
      }
    }

    return {
      workflow,
      sections,
      intakeConfig,
      tenantBranding,
    };
  }

  /**
   * Create a new intake run
   * Supports both authenticated and anonymous runs
   * Stage 12.5: Supports URL-based prefill
   */
  async createIntakeRun(
    slug: string,
    userId?: string,
    initialAnswers?: Record<string, any>,
    prefillParams?: Record<string, string>
  ): Promise<{ runId: string; runToken: string }> {
    // PERFORMANCE FIX: Use indexed query instead of loading all workflows
    const workflow = await workflowRepository.findBySlug(slug);

    if (!workflow) {
      throw new Error("Workflow not found");
    }

    if (!workflow.isPublic) {
      throw new Error("Workflow is not public");
    }

    // Check if login is required
    if (workflow.requireLogin && !userId) {
      throw new Error("Authentication required for this workflow");
    }

    // Parse intakeConfig
    const parsedConfig = IntakeConfigSchema.safeParse(workflow.intakeConfig);
    const intakeConfig: IntakeConfig = parsedConfig.success ? parsedConfig.data : {};

    // Generate run token
    const runToken = randomUUID();

    // Create run
    const run = await workflowRunRepository.create({
      workflowId: workflow.id,
      runToken,
      createdBy: userId ? `creator:${userId}` : "anon",
      completed: false,
      metadata: {
        intake: true,
        slug,
      },
    });

    // Handle prefill from URL parameters (Stage 12.5)
    if (prefillParams && intakeConfig.allowPrefill && intakeConfig.allowedPrefillKeys) {
      // Get all steps to map aliases to stepIds
      const allSteps = await stepRepository.findByWorkflowIdWithAliases(workflow.id);
      const aliasToStepId = new Map<string, string>();
      for (const step of allSteps) {
        if (step.alias) {
          aliasToStepId.set(step.alias, step.id);
        }
      }

      // Process prefill parameters
      for (const [key, value] of Object.entries(prefillParams)) {
        // Only prefill if key is in allowedPrefillKeys
        if (intakeConfig.allowedPrefillKeys.includes(key)) {
          const stepId = aliasToStepId.get(key);
          if (stepId) {
            await stepValueRepository.upsert({
              runId: run.id,
              stepId,
              value,
            });
            logger.info({ runId: run.id, key, stepId }, "Prefilled value from URL");
          }
        }
      }
    }

    // Save initial answers if provided (takes precedence over prefill)
    if (initialAnswers) {
      for (const [stepId, value] of Object.entries(initialAnswers)) {
        await stepValueRepository.upsert({
          runId: run.id,
          stepId,
          value,
        });
      }
    }

    logger.info({ runId: run.id, slug, userId }, "Created intake run");

    return {
      runId: run.id,
      runToken: run.runToken,
    };
  }

  /**
   * Save intake run progress (partial answers)
   * Used for draft/resume functionality
   */
  async saveIntakeProgress(
    runToken: string,
    answers: Record<string, any>
  ): Promise<void> {
    // Find run by token
    const run = await workflowRunRepository.findByToken(runToken);

    if (!run) {
      throw new Error("Run not found");
    }

    if (run.completed) {
      throw new Error("Run is already completed");
    }

    // Save all answers
    for (const [stepId, value] of Object.entries(answers)) {
      await stepValueRepository.upsert({
        runId: run.id,
        stepId,
        value,
      });
    }

    logger.info({ runId: run.id, answerCount: Object.keys(answers).length }, "Saved intake progress");
  }

  /**
   * Submit intake run (complete the workflow)
   * Stage 12.5: Validates CAPTCHA and sends email receipt
   */
  async submitIntakeRun(
    runToken: string,
    finalAnswers: Record<string, any>,
    captchaResponse?: CaptchaResponse
  ): Promise<IntakeSubmitResult> {
    // Find run by token
    const run = await workflowRunRepository.findByToken(runToken);

    if (!run) {
      throw new Error("Run not found");
    }

    if (run.completed) {
      throw new Error("Run is already completed");
    }

    // Get workflow to check intakeConfig
    const workflow = await workflowRepository.findById(run.workflowId);
    if (!workflow) {
      throw new Error("Workflow not found");
    }

    const parsedConfig = IntakeConfigSchema.safeParse(workflow.intakeConfig);
    const intakeConfig: IntakeConfig = parsedConfig.success ? parsedConfig.data : {};

    // Stage 12.5: Validate CAPTCHA if required
    if (intakeConfig.requireCaptcha) {
      if (!captchaResponse) {
        throw new Error("CAPTCHA response required");
      }

      const captchaResult = await CaptchaService.validateCaptcha(
        captchaResponse,
        workflow.id
      );

      if (!captchaResult.valid) {
        return {
          runId: run.id,
          status: "error",
          errors: [captchaResult.error || "CAPTCHA validation failed"],
        };
      }
    }

    // Save final answers
    for (const [stepId, value] of Object.entries(finalAnswers)) {
      await stepValueRepository.upsert({
        runId: run.id,
        stepId,
        value,
      });
    }

    // Complete the run using RunService
    try {
      await runService.completeRunNoAuth(run.id);

      logger.info({ runId: run.id }, "Completed intake run");

      const result: IntakeSubmitResult = {
        runId: run.id,
        status: "success",
      };

      // Stage 12.5: Send email receipt via separate service
      const receiptResult = await intakeReceiptService.sendReceipt(run.id, workflow, intakeConfig);
      if (receiptResult.attempted) {
        result.emailReceipt = {
          attempted: true,
          to: receiptResult.to,
          success: receiptResult.success,
          error: receiptResult.error
        };
      }



      return result;
    } catch (error) {
      logger.error({ error, runId: run.id }, "Failed to complete intake run");
      return {
        runId: run.id,
        status: "error",
        errors: [error instanceof Error ? error.message : "Unknown error"],
      };
    }
  }



  /**
   * Get intake run status
   * Used for polling after submission
   */
  async getIntakeRunStatus(runToken: string): Promise<{
    status: string;
    runId?: string;
    error?: string;
    completed: boolean;
  }> {
    const run = await workflowRunRepository.findByToken(runToken);

    if (!run) {
      throw new Error("Run not found");
    }

    return {
      status: run.completed ? "completed" : "pending",
      runId: run.id,
      completed: run.completed ?? false,
    };
  }
}

export const intakeService = new IntakeService();

import { evaluateConditionExpression } from "@shared/conditionEvaluator";
import type { Section, Step, LogicRule } from "@shared/schema";
import {
  evaluateRules,
  calculateNextSection,
  resolveNextSection,
  validateRequiredSteps,
  getEffectiveRequiredSteps,
} from "@shared/workflowLogic";

import {
  sectionRepository,
  stepRepository,
  logicRuleRepository,
  stepValueRepository,
} from "../repositories";

/**
 * Navigation result from logic evaluation
 */
export interface NavigationResult {
  visibleSections: string[];
  visibleSteps: string[];
  requiredSteps: string[];
  skipToSectionId?: string;
  nextSectionId: string | null;
  currentProgress: number; // 0-100
}

/**
 * Validation result for workflow completion
 */
export interface ValidationResult {
  valid: boolean;
  missingSteps: string[];
  missingStepTitles?: string[];
}

/**
 * Service layer for workflow logic evaluation and navigation
 */
export class LogicService {
  private sectionRepo: typeof sectionRepository;
  private stepRepo: typeof stepRepository;
  private logicRuleRepo: typeof logicRuleRepository;
  private valueRepo: typeof stepValueRepository;

  constructor(
    sectionRepo?: typeof sectionRepository,
    stepRepo?: typeof stepRepository,
    logicRuleRepo?: typeof logicRuleRepository,
    valueRepo?: typeof stepValueRepository
  ) {
    this.sectionRepo = sectionRepo || sectionRepository;
    this.stepRepo = stepRepo || stepRepository;
    this.logicRuleRepo = logicRuleRepo || logicRuleRepository;
    this.valueRepo = valueRepo || stepValueRepository;
  }

  /**
   * Evaluate logic and determine next section for a workflow run
   *
   * PERFORMANCE OPTIMIZED (Dec 2025):
   * Pre-builds rule index Maps for O(1) lookup instead of O(n) filtering
   *
   * @param workflowId - Workflow ID
   * @param runId - Current run ID
   * @param currentSectionId - Current section ID (null if starting)
   * @returns Navigation result with next section and visibility info
   */
  async evaluateNavigation(
    workflowId: string,
    runId: string,
    currentSectionId: string | null
  ): Promise<NavigationResult> {
    // Load all workflow components
    const sections = await this.sectionRepo.findByWorkflowId(workflowId);
    const sectionIds = sections.map((s) => s.id);
    const steps = await this.stepRepo.findBySectionIds(sectionIds);
    const logicRules = await this.logicRuleRepo.findByWorkflowId(workflowId);
    const currentValues = await this.valueRepo.findByRunId(runId);

    // Build data object for evaluation
    const data: Record<string, any> = {};
    currentValues.forEach((v) => {
      data[v.stepId] = v.value;
    });

    // OPTIMIZATION: Pre-build rule indexes (O(n) once instead of O(n*m) repeatedly)
    const sectionHideRulesMap = new Map<string, LogicRule[]>();
    const stepHideRulesMap = new Map<string, LogicRule[]>();
    for (const rule of logicRules) {
      if (rule.action === "hide") {
        if (rule.targetType === "section" && rule.targetSectionId) {
          if (!sectionHideRulesMap.has(rule.targetSectionId)) {
            sectionHideRulesMap.set(rule.targetSectionId, []);
          }
          sectionHideRulesMap.get(rule.targetSectionId)!.push(rule);
        } else if (rule.targetType === "step" && rule.targetStepId) {
          if (!stepHideRulesMap.has(rule.targetStepId)) {
            stepHideRulesMap.set(rule.targetStepId, []);
          }
          stepHideRulesMap.get(rule.targetStepId)!.push(rule);
        }
      }
    }

    // Evaluate all rules
    const evalResult = evaluateRules(logicRules, data);

    // Build visible sections set
    // Start with all sections, then apply hide rules
    const allSectionIds = new Set(sections.map((s) => s.id));
    const visibleSections = new Set(
      Array.from(allSectionIds).filter((id) => {
        // If explicitly shown by a rule, include it
        if (evalResult.visibleSections.has(id)) {return true;}
        // If not explicitly hidden, include it (default visible)
        // OPTIMIZATION: O(1) lookup instead of O(n) filter
        const hideRules = sectionHideRulesMap.get(id);
        if (!hideRules || hideRules.length === 0) {return true;}
        // If there are hide rules, check if any are triggered
        return !hideRules.some((rule) => {
          const actualValue = data[rule.conditionStepId];
          // Simple condition check - should use evaluateCondition but keeping it simple
          return actualValue !== undefined;
        });
      })
    );

    // Build visible steps set (only from visible sections)
    const visibleSteps = new Set(
      steps
        .filter((step) => visibleSections.has(step.sectionId))
        .filter((step) => {
          // 1. Check step-level visibleIf
          if (step.visibleIf) {
            const aliasResolver = (name: string) => steps.find((s) => s.alias === name)?.id;
            const isVisible = evaluateConditionExpression(
              step.visibleIf as any,
              data,
              aliasResolver
            );
            if (!isVisible) {return false;}
          }

          // 2. Check logic rules
          // If explicitly shown by a rule, include it
          if (evalResult.visibleSteps.has(step.id)) {return true;}
          // If explicitly hidden by a rule, exclude it
          // OPTIMIZATION: O(1) lookup instead of O(n) filter
          const hideRules = stepHideRulesMap.get(step.id);
          if (!hideRules || hideRules.length === 0) {return true;}
          return !hideRules.some((rule) => {
            const actualValue = data[rule.conditionStepId];
            return actualValue !== undefined;
          });
        })
        .map((s) => s.id)
    );

    // Get initially required steps
    const initialRequiredSteps = new Set(steps.filter((s) => s.required).map((s) => s.id));

    // Get effective required steps (considering logic rules)
    const effectiveRequiredSteps = getEffectiveRequiredSteps(
      initialRequiredSteps,
      logicRules,
      data
    );

    // Filter to only include visible required steps
    const visibleRequiredSteps = new Set(
      Array.from(effectiveRequiredSteps).filter((id) => visibleSteps.has(id))
    );

    // Calculate normal next section
    const nextSectionId = calculateNextSection(
      currentSectionId,
      sections.map((s) => ({ id: s.id, order: s.order })),
      visibleSections
    );

    // Resolve final next section (considering skip logic)
    const resolvedNextSectionId = resolveNextSection(
      nextSectionId,
      evalResult.skipToSectionId,
      sections.map((s) => ({ id: s.id, order: s.order })),
      visibleSections
    );

    // Calculate progress
    const currentProgress = this.calculateProgress(
      currentSectionId,
      sections,
      visibleSections
    );

    return {
      visibleSections: Array.from(visibleSections),
      visibleSteps: Array.from(visibleSteps),
      requiredSteps: Array.from(visibleRequiredSteps),
      skipToSectionId: evalResult.skipToSectionId,
      nextSectionId: resolvedNextSectionId,
      currentProgress,
    };
  }

  /**
   * Validate workflow completion
   *
   * PERFORMANCE OPTIMIZED (Dec 2025):
   * Uses same Map-based optimization as evaluateNavigation
   *
   * @param workflowId - Workflow ID
   * @param runId - Run ID to validate
   * @returns Validation result
   */
  async validateCompletion(workflowId: string, runId: string): Promise<ValidationResult> {
    // Load all workflow components
    const sections = await this.sectionRepo.findByWorkflowId(workflowId);
    const sectionIds = sections.map((s) => s.id);
    const steps = await this.stepRepo.findBySectionIds(sectionIds);
    const logicRules = await this.logicRuleRepo.findByWorkflowId(workflowId);
    const currentValues = await this.valueRepo.findByRunId(runId);

    // Build data object for evaluation
    const data: Record<string, any> = {};
    currentValues.forEach((v) => {
      data[v.stepId] = v.value;
    });

    // OPTIMIZATION: Pre-build rule indexes
    const sectionHideRulesMap = new Map<string, LogicRule[]>();
    const stepHideRulesMap = new Map<string, LogicRule[]>();
    for (const rule of logicRules) {
      if (rule.action === "hide") {
        if (rule.targetType === "section" && rule.targetSectionId) {
          if (!sectionHideRulesMap.has(rule.targetSectionId)) {
            sectionHideRulesMap.set(rule.targetSectionId, []);
          }
          sectionHideRulesMap.get(rule.targetSectionId)!.push(rule);
        } else if (rule.targetType === "step" && rule.targetStepId) {
          if (!stepHideRulesMap.has(rule.targetStepId)) {
            stepHideRulesMap.set(rule.targetStepId, []);
          }
          stepHideRulesMap.get(rule.targetStepId)!.push(rule);
        }
      }
    }

    // Evaluate rules to determine visibility
    const evalResult = evaluateRules(logicRules, data);

    // Build visible sections
    const allSectionIds = new Set(sections.map((s) => s.id));
    const visibleSections = new Set(Array.from(allSectionIds).filter((id) => {
      if (evalResult.visibleSections.has(id)) {return true;}
      // OPTIMIZATION: O(1) lookup
      const hideRules = sectionHideRulesMap.get(id);
      if (!hideRules || hideRules.length === 0) {return true;}
      return !hideRules.some((rule) => {
        const actualValue = data[rule.conditionStepId];
        return actualValue !== undefined;
      });
    }));

    // Build visible steps
    const visibleStepsInVisibleSections = steps.filter((step) =>
      visibleSections.has(step.sectionId)
    );

    const visibleSteps = new Set(
      visibleStepsInVisibleSections
        .filter((step) => {
          // 1. Check step-level visibleIf
          if (step.visibleIf) {
            const aliasResolver = (name: string) => steps.find((s) => s.alias === name)?.id;
            const isVisible = evaluateConditionExpression(
              step.visibleIf as any,
              data,
              aliasResolver
            );
            if (!isVisible) {return false;}
          }

          // 2. Check logic rules
          if (evalResult.visibleSteps.has(step.id)) {return true;}
          // OPTIMIZATION: O(1) lookup
          const hideRules = stepHideRulesMap.get(step.id);
          if (!hideRules || hideRules.length === 0) {return true;}
          return !hideRules.some((rule) => {
            const actualValue = data[rule.conditionStepId];
            return actualValue !== undefined;
          });
        })
        .map((s) => s.id)
    );

    // Get initially required steps
    const initialRequiredSteps = new Set(steps.filter((s) => s.required).map((s) => s.id));

    // Get effective required steps
    const effectiveRequiredSteps = getEffectiveRequiredSteps(
      initialRequiredSteps,
      logicRules,
      data
    );

    // Filter to only visible required steps
    const visibleRequiredSteps = new Set(
      Array.from(effectiveRequiredSteps).filter((id) => visibleSteps.has(id))
    );

    // Validate all visible required steps have values
    const validation = validateRequiredSteps(visibleRequiredSteps, data);

    // Get step titles for missing steps
    const missingStepTitles = validation.missingSteps
      .map((stepId) => steps.find((s) => s.id === stepId)?.title)
      .filter(Boolean) as string[];

    return {
      valid: validation.valid,
      missingSteps: validation.missingSteps,
      missingStepTitles,
    };
  }

  /**
   * Calculate progress percentage
   *
   * @param currentSectionId - Current section ID
   * @param sections - All sections
   * @param visibleSections - Set of visible section IDs
   * @returns Progress percentage (0-100)
   */
  private calculateProgress(
    currentSectionId: string | null,
    sections: Section[],
    visibleSections: Set<string>
  ): number {
    if (!currentSectionId) {
      return 0;
    }

    // Get sorted visible sections
    const sortedVisibleSections = sections
      .filter((s) => visibleSections.has(s.id))
      .sort((a, b) => a.order - b.order);

    if (sortedVisibleSections.length === 0) {
      return 100;
    }

    // Find index of current section
    const currentIndex = sortedVisibleSections.findIndex((s) => s.id === currentSectionId);

    if (currentIndex === -1) {
      return 0;
    }

    // Calculate progress: (currentIndex + 1) / total * 100
    const progress = Math.round(((currentIndex + 1) / sortedVisibleSections.length) * 100);

    return Math.min(100, Math.max(0, progress));
  }

  /**
   * Check if a section is visible based on logic rules and current data
   *
   * @param workflowId - Workflow ID
   * @param sectionId - Section ID to check
   * @param data - Current step values (key = stepId or alias, value = step value)
   * @returns true if section is visible, false otherwise
   */
  async isSectionVisible(
    workflowId: string,
    sectionId: string,
    data: Record<string, any>
  ): Promise<boolean> {
    const logicRules = await this.logicRuleRepo.findByWorkflowId(workflowId);
    const evalResult = evaluateRules(logicRules, data);

    // Check if explicitly shown
    if (evalResult.visibleSections.has(sectionId)) {
      return true;
    }

    // Check for hide rules
    const hideRules = logicRules.filter(
      (r) => r.targetType === "section" && r.targetSectionId === sectionId && r.action === "hide"
    );

    // If no hide rules, section is visible by default
    if (hideRules.length === 0) {
      return true;
    }

    // Check if any hide rules are triggered
    const isHidden = hideRules.some((rule) => {
      const actualValue = data[rule.conditionStepId];
      return actualValue !== undefined;
    });

    return !isHidden;
  }

  /**
   * Check if a step is visible based on logic rules and current data
   *
   * @param workflowId - Workflow ID
   * @param stepId - Step ID to check
   * @param data - Current step values (key = stepId or alias, value = step value)
   * @returns true if step is visible, false otherwise
   */
  async isStepVisible(
    workflowId: string,
    stepId: string,
    data: Record<string, any>
  ): Promise<boolean> {
    // Need to fetch step to check visibleIf
    const step = await this.stepRepo.findById(stepId);
    if (!step) {return false;}

    // Check step-level visibleIf
    if (step.visibleIf) {
      const allSteps = await this.stepRepo.findByWorkflowIdWithAliases(workflowId);
      const aliasResolver = (name: string) => allSteps.find((s) => s.alias === name)?.id;

      const isVisible = evaluateConditionExpression(
        step.visibleIf as any,
        data,
        aliasResolver
      );
      if (!isVisible) {return false;}
    }

    const logicRules = await this.logicRuleRepo.findByWorkflowId(workflowId);
    const evalResult = evaluateRules(logicRules, data);

    // Check if explicitly shown
    if (evalResult.visibleSteps.has(stepId)) {
      return true;
    }

    // Check for hide rules
    const hideRules = logicRules.filter(
      (r) => r.targetType === "step" && r.targetStepId === stepId && r.action === "hide"
    );

    // If no hide rules, step is visible by default
    if (hideRules.length === 0) {
      return true;
    }

    // Check if any hide rules are triggered
    const isHidden = hideRules.some((rule) => {
      const actualValue = data[rule.conditionStepId];
      return actualValue !== undefined;
    });

    return !isHidden;
  }

  /**
   * Check if a step is required based on logic rules and current data
   *
   * @param workflowId - Workflow ID
   * @param stepId - Step ID to check
   * @param data - Current step values (key = stepId or alias, value = step value)
   * @returns true if step is required, false otherwise
   */
  async isStepRequired(
    workflowId: string,
    stepId: string,
    data: Record<string, any>
  ): Promise<boolean> {
    const step = await this.stepRepo.findById(stepId);
    if (!step) {
      return false;
    }

    const logicRules = await this.logicRuleRepo.findByWorkflowId(workflowId);
    const evalResult = evaluateRules(logicRules, data);

    // Check if explicitly marked as required by a rule
    if (evalResult.requiredSteps.has(stepId)) {
      return true;
    }

    // Check for make_optional rules
    const makeOptionalRules = logicRules.filter(
      (r) => r.targetType === "step" && r.targetStepId === stepId && r.action === "make_optional"
    );

    // If there are make_optional rules and any are triggered, step is optional
    if (makeOptionalRules.length > 0) {
      const isMadeOptional = makeOptionalRules.some((rule) => {
        const actualValue = data[rule.conditionStepId];
        return actualValue !== undefined;
      });

      if (isMadeOptional) {
        return false;
      }
    }

    // Check step-level visibleIf first (if step is hidden, it's not required)
    if (step.visibleIf) {
      const allSteps = await this.stepRepo.findByWorkflowIdWithAliases(workflowId);
      const aliasResolver = (name: string) => allSteps.find((s) => s.alias === name)?.id;

      const isVisible = evaluateConditionExpression(
        step.visibleIf as any,
        data,
        aliasResolver
      );
      if (!isVisible) {return false;}
    }

    // Default to the step's base required flag
    return step.required ?? false;
  }
}

// Singleton instance
export const logicService = new LogicService();

import crypto from "crypto";

import bcrypt from "bcrypt";
import { eq, and } from "drizzle-orm";
import QRCode from "qrcode";
import speakeasy from "speakeasy";

import { mfaSecrets, mfaBackupCodes, users } from "@shared/schema";

import { db } from "../db";
import { createLogger } from "../logger";



const log = createLogger({ module: 'mfa-service' });

const BACKUP_CODES_COUNT = 10;
const BACKUP_CODE_LENGTH = 8;
const BCRYPT_ROUNDS = 10; // Backup codes are one-time use, lower rounds acceptable

export class MfaService {
    // =================================================================
    // TOTP SETUP
    // =================================================================

    /**
     * Generate a new TOTP secret for a user
     * Returns the secret and a QR code data URL
     */
    async generateTotpSecret(userId: string, userEmail: string): Promise<{
        secret: string;
        qrCodeDataUrl: string;
        backupCodes: string[];
    }> {
        // Generate TOTP secret
        const secret = speakeasy.generateSecret({
            name: `ezBuildr (${userEmail})`,
            issuer: 'ezBuildr',
            length: 32
        });

        if (!secret.base32) {
            throw new Error('Failed to generate TOTP secret');
        }

        // Generate QR code
        const qrCodeDataUrl = await QRCode.toDataURL(secret.otpauth_url ?? '');

        // Generate backup codes
        const backupCodes = this.generateBackupCodes();

        // Store secret in database (disabled by default until verified)
        await db.insert(mfaSecrets)
            .values({
                userId,
                secret: secret.base32,
                enabled: false,
                createdAt: new Date()
            })
            .onConflictDoUpdate({
                target: mfaSecrets.userId,
                set: {
                    secret: secret.base32,
                    enabled: false, // Reset to disabled when regenerating
                    createdAt: new Date()
                }
            });

        // Store hashed backup codes
        await this.storeBackupCodes(userId, backupCodes);

        log.info({ userId }, 'Generated TOTP secret');

        return {
            secret: secret.base32,
            qrCodeDataUrl,
            backupCodes
        };
    }

    /**
     * Verify a TOTP code and enable MFA
     */
    async verifyAndEnableMfa(userId: string, token: string): Promise<boolean> {
        // Get user's secret
        const mfaSecret = await db.query.mfaSecrets.findFirst({
            where: eq(mfaSecrets.userId, userId)
        });

        if (!mfaSecret) {
            log.warn({ userId }, 'No MFA secret found for user');
            return false;
        }

        // Verify the TOTP token
        const isValid = speakeasy.totp.verify({
            secret: mfaSecret.secret,
            encoding: 'base32',
            token,
            window: 2 // Allow 2 time steps before/after (60 seconds total window)
        });

        if (!isValid) {
            log.warn({ userId }, 'Invalid TOTP token provided');
            return false;
        }

        // Enable MFA
        await db.update(mfaSecrets)
            .set({
                enabled: true,
                enabledAt: new Date()
            })
            .where(eq(mfaSecrets.userId, userId));

        // Update user record
        await db.update(users)
            .set({ mfaEnabled: true })
            .where(eq(users.id, userId));

        log.info({ userId }, 'MFA enabled successfully');

        return true;
    }

    // =================================================================
    // TOTP VERIFICATION
    // =================================================================

    /**
     * Verify a TOTP code for login
     */
    async verifyTotp(userId: string, token: string): Promise<boolean> {
        // Get user's secret
        const mfaSecret = await db.query.mfaSecrets.findFirst({
            where: and(
                eq(mfaSecrets.userId, userId),
                eq(mfaSecrets.enabled, true)
            )
        });

        if (!mfaSecret) {
            log.warn({ userId }, 'No enabled MFA secret found for user');
            return false;
        }

        // Verify the TOTP token
        const isValid = speakeasy.totp.verify({
            secret: mfaSecret.secret,
            encoding: 'base32',
            token,
            window: 2 // Allow 2 time steps before/after
        });

        if (isValid) {
            log.info({ userId }, 'TOTP verification successful');
        } else {
            log.warn({ userId }, 'TOTP verification failed');
        }

        return isValid;
    }

    /**
     * Check if user has MFA enabled
     */
    async isMfaEnabled(userId: string): Promise<boolean> {
        const user = await db.query.users.findFirst({
            where: eq(users.id, userId)
        });

        return user?.mfaEnabled ?? false;
    }

    // =================================================================
    // BACKUP CODES
    // =================================================================

    /**
     * Generate backup codes (plain text)
     */
    private generateBackupCodes(): string[] {
        const codes: string[] = [];

        for (let i = 0; i < BACKUP_CODES_COUNT; i++) {
            // Generate random alphanumeric code
            const code = crypto.randomBytes(BACKUP_CODE_LENGTH)
                .toString('hex')
                .slice(0, BACKUP_CODE_LENGTH)
                .toUpperCase();

            // Format as XXXX-XXXX for readability
            const formattedCode = `${code.slice(0, 4)}-${code.slice(4)}`;
            codes.push(formattedCode);
        }

        return codes;
    }

    /**
     * Store hashed backup codes in database
     */
    private async storeBackupCodes(userId: string, codes: string[]): Promise<void> {
        // Delete existing backup codes
        await db.delete(mfaBackupCodes)
            .where(eq(mfaBackupCodes.userId, userId));

        // Hash and store new codes
        const hashedCodes = await Promise.all(
            codes.map(async (code) => ({
                userId,
                codeHash: await bcrypt.hash(code, BCRYPT_ROUNDS),
                used: false,
                createdAt: new Date()
            }))
        );

        await db.insert(mfaBackupCodes).values(hashedCodes);

        log.info({ userId, count: codes.length }, 'Stored backup codes');
    }

    /**
     * Verify and consume a backup code
     */
    async verifyBackupCode(userId: string, code: string): Promise<boolean> {
        // Get all unused backup codes for user
        const codes = await db.query.mfaBackupCodes.findMany({
            where: and(
                eq(mfaBackupCodes.userId, userId),
                eq(mfaBackupCodes.used, false)
            )
        });

        if (codes.length === 0) {
            log.warn({ userId }, 'No unused backup codes available');
            return false;
        }

        // Try to match the code
        for (const storedCode of codes) {
            const isMatch = await bcrypt.compare(code, storedCode.codeHash);

            if (isMatch) {
                // Mark code as used
                await db.update(mfaBackupCodes)
                    .set({
                        used: true,
                        usedAt: new Date()
                    })
                    .where(eq(mfaBackupCodes.id, storedCode.id));

                log.info({ userId }, 'Backup code verified and consumed');

                // Warn if this was the last code
                if (codes.length === 1) {
                    log.warn({ userId }, 'Last backup code used - user should regenerate');
                }

                return true;
            }
        }

        log.warn({ userId }, 'Invalid backup code provided');
        return false;
    }

    /**
     * Regenerate backup codes
     */
    async regenerateBackupCodes(userId: string): Promise<string[]> {
        const backupCodes = this.generateBackupCodes();
        await this.storeBackupCodes(userId, backupCodes);

        log.info({ userId }, 'Regenerated backup codes');

        return backupCodes;
    }

    /**
     * Get remaining backup codes count
     */
    async getRemainingBackupCodesCount(userId: string): Promise<number> {
        const codes = await db.query.mfaBackupCodes.findMany({
            where: and(
                eq(mfaBackupCodes.userId, userId),
                eq(mfaBackupCodes.used, false)
            )
        });

        return codes.length;
    }

    // =================================================================
    // DISABLE MFA
    // =================================================================

    /**
     * Disable MFA for a user (requires password verification)
     */
    async disableMfa(userId: string): Promise<void> {
        // Disable MFA secret
        await db.update(mfaSecrets)
            .set({ enabled: false })
            .where(eq(mfaSecrets.userId, userId));

        // Update user record
        await db.update(users)
            .set({ mfaEnabled: false })
            .where(eq(users.id, userId));

        // Delete backup codes
        await db.delete(mfaBackupCodes)
            .where(eq(mfaBackupCodes.userId, userId));

        log.info({ userId }, 'MFA disabled');
    }

    /**
     * Admin reset MFA (for locked out users)
     */
    async adminResetMfa(userId: string): Promise<void> {
        await this.disableMfa(userId);

        // Also delete the secret
        await db.delete(mfaSecrets)
            .where(eq(mfaSecrets.userId, userId));

        log.warn({ userId }, 'Admin reset MFA');
    }
}

export const mfaService = new MfaService();

/**
 * Stage 21: PDF Conversion Queue Service
 *
 * Queue-based PDF conversion with retry logic and status tracking.
 * Features:
 * - Background job processing
 * - Exponential backoff retry (3 attempts max)
 * - Status tracking in runOutputs table
 * - Error logging and recovery
 * - Graceful shutdown
 */

import fs from 'fs/promises';
import path from 'path';

import { eq, and } from 'drizzle-orm';

import { runOutputs } from '@shared/schema';

import { db } from '../db';
import { logger } from '../logger';

import { convertDocxToPdf2 } from './docxRenderer2';
import { getOutputFilePath } from './templates';


import type { DbTransaction } from '../repositories/BaseRepository';

export interface PdfConversionJob {
  id: string;                   // runOutput.id
  runId: string;
  workflowVersionId: string;
  templateKey: string;
  docxPath: string;              // Full path to DOCX file
  attempt: number;               // Current attempt (1-indexed)
  maxAttempts: number;           // Maximum retry attempts (default: 3)
  createdAt: Date;
}

export interface PdfConversionResult {
  success: boolean;
  pdfPath?: string;
  error?: string;
  attemptsMade: number;
}

/**
 * PDF Queue Service
 * Manages background PDF conversion queue
 */
export class PdfQueueService {
  private isRunning = false;
  private pollingInterval: NodeJS.Timeout | null = null;
  private retryTimeouts = new Set<NodeJS.Timeout>();
  private readonly POLL_INTERVAL_MS = 5000; // Poll every 5 seconds
  private readonly MAX_RETRIES = 3;
  private readonly BACKOFF_BASE_MS = 1000; // 1 second base

  /**
   * Start the background queue processor
   */
  start(): void {
    if (this.isRunning) {
      logger.warn('PDF queue processor is already running');
      return;
    }

    this.isRunning = true;
    logger.info('PDF queue processor started');

    // Start polling for pending jobs
    this.pollingInterval = setInterval(() => {
      this.processQueue().catch((error) => {
        logger.error({ error }, 'Error processing PDF queue');
      });
    }, this.POLL_INTERVAL_MS);

    // Process immediately on start
    this.processQueue().catch((error) => {
      logger.error({ error }, 'Error processing PDF queue on start');
    });
  }

  /**
   * Stop the background queue processor
   */
  stop(): void {
    if (!this.isRunning) {
      return;
    }

    this.isRunning = false;

    if (this.pollingInterval) {
      clearInterval(this.pollingInterval);
      this.pollingInterval = null;
    }

    // Clear any pending retry timeouts
    for (const timeout of this.retryTimeouts) {
      clearTimeout(timeout);
    }
    this.retryTimeouts.clear();

    logger.info('PDF queue processor stopped');
  }

  /**
   * Enqueue a DOCX file for PDF conversion
   *
   * @param docxPath - Path to DOCX file (relative to outputs dir)
   * @param runId - Run ID
   * @param workflowVersionId - Workflow version ID
   * @param templateKey - Template key
   * @returns Output ID
   */
  async enqueue(
    docxPath: string,
    runId: string,
    workflowVersionId: string,
    templateKey: string,
    tx?: DbTransaction
  ): Promise<string> {
    const database = tx || db;

    // Create pending PDF output entry
    const [output] = await database
      .insert(runOutputs)
      .values({
        runId,
        workflowVersionId,
        templateKey,
        fileType: 'pdf',
        storagePath: '', // Will be set after conversion
        status: 'pending',
      })
      .returning();

    logger.info({ outputId: output.id, docxPath }, 'Enqueued PDF conversion job');

    return output.id;
  }

  /**
   * Process pending PDF conversion jobs
   */
  private async processQueue(): Promise<void> {
    if (!this.isRunning) {
      return;
    }

    try {
      // Find all pending PDF outputs
      const pendingOutputs = await db.query.runOutputs.findMany({
        where: and(
          eq(runOutputs.fileType, 'pdf'),
          eq(runOutputs.status, 'pending')
        ),
        orderBy: (outputs: any, { asc }: any) => [asc(outputs.createdAt)],
        limit: 10, // Process up to 10 jobs per batch
      });

      if (pendingOutputs.length === 0) {
        return;
      }

      logger.info({ count: pendingOutputs.length }, 'Processing pending PDF conversion jobs');

      // Process each job
      for (const output of pendingOutputs) {
        await this.processJob(output);
      }
    } catch (error) {
      logger.error({ error }, 'Error in processQueue');
    }
  }

  /**
   * Process a single PDF conversion job
   */
  private async processJob(output: any): Promise<void> {
    const attempt = (output.error ? JSON.parse(output.error || '{}').attempt || 0 : 0) + 1;
    const jobId = output.id;

    logger.info({ jobId, attempt, maxRetries: this.MAX_RETRIES }, 'Processing PDF job');

    try {
      // Find corresponding DOCX output
      const docxOutput = await db.query.runOutputs.findFirst({
        where: and(
          eq(runOutputs.runId, output.runId),
          eq(runOutputs.templateKey, output.templateKey),
          eq(runOutputs.fileType, 'docx')
        ),
      });

      if (!docxOutput) {
        throw new Error(`DOCX output not found for template key: ${output.templateKey}`);
      }

      if (!docxOutput.storagePath) {
        throw new Error(`DOCX storagePath is empty`);
      }

      // Get full path to DOCX file
      const docxPath = getOutputFilePath(docxOutput.storagePath);

      // Verify DOCX file exists
      await fs.access(docxPath);

      // Convert DOCX to PDF
      const pdfPath = await convertDocxToPdf2(docxPath);

      // Verify PDF was created
      await fs.access(pdfPath);

      // Extract just the filename for storagePath
      const pdfFilename = path.basename(pdfPath);

      // Update output status to ready
      await db
        .update(runOutputs)
        .set({
          storagePath: pdfFilename,
          status: 'ready',
          error: null,
          updatedAt: new Date(),
        })
        .where(eq(runOutputs.id, output.id));

      logger.info({ jobId, pdfFilename }, 'PDF job completed successfully');
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';

      logger.error({ jobId, attempt, error: errorMessage }, 'PDF job failed');

      // Determine if we should retry
      if (attempt < this.MAX_RETRIES) {
        // Calculate backoff delay
        const backoffMs = this.BACKOFF_BASE_MS * Math.pow(2, attempt - 1);

        logger.info({ jobId, backoffMs }, 'Will retry PDF job');

        // Update error with attempt count and backoff info
        await db
          .update(runOutputs)
          .set({
            error: JSON.stringify({
              message: errorMessage,
              attempt,
              nextRetryAt: new Date(Date.now() + backoffMs).toISOString(),
            }),
            updatedAt: new Date(),
          })
          .where(eq(runOutputs.id, output.id));

        // Schedule retry (simple setTimeout for now, could use proper job queue)
        // Schedule retry (simple setTimeout for now, could use proper job queue)
        const timeout = setTimeout(() => {
          this.retryTimeouts.delete(timeout);
          this.processJob(output).catch((err) => {
            logger.error({ jobId, error: err }, 'Error retrying PDF job');
          });
        }, backoffMs);
        this.retryTimeouts.add(timeout);
      } else {
        // Max retries exceeded, mark as failed
        await db
          .update(runOutputs)
          .set({
            status: 'failed',
            error: JSON.stringify({
              message: errorMessage,
              attempt,
              maxRetriesExceeded: true,
            }),
            updatedAt: new Date(),
          })
          .where(eq(runOutputs.id, output.id));

        logger.error({ jobId, attempt }, 'PDF job FAILED after max retries');
      }
    }
  }

  /**
   * Get job status
   */
  async getJobStatus(outputId: string): Promise<{
    status: 'pending' | 'ready' | 'failed';
    storagePath?: string;
    error?: string;
    attempt?: number;
  } | null> {
    const output = await db.query.runOutputs.findFirst({
      where: eq(runOutputs.id, outputId),
    });

    if (!output) {
      return null;
    }

    let attempt: number | undefined;
    if (output.error) {
      try {
        const errorData = JSON.parse(output.error);
        attempt = errorData.attempt;
      } catch {
        // Ignore parse errors
      }
    }

    return {
      status: output.status,
      storagePath: output.storagePath || undefined,
      error: output.error || undefined,
      attempt,
    };
  }

  /**
   * Convert DOCX to PDF immediately (synchronous, no queue)
   * Use this for immediate conversions when queue is not needed
   */
  async convertImmediate(
    docxPath: string,
    runId: string,
    workflowVersionId: string,
    templateKey: string,
    tx?: DbTransaction
  ): Promise<PdfConversionResult> {
    const database = tx || db;

    try {
      // Convert DOCX to PDF
      const pdfPath = await convertDocxToPdf2(docxPath);

      // Verify PDF was created
      await fs.access(pdfPath);

      // Extract just the filename
      const pdfFilename = path.basename(pdfPath);

      // Store output
      await database.insert(runOutputs).values({
        runId,
        workflowVersionId,
        templateKey,
        fileType: 'pdf',
        storagePath: pdfFilename,
        status: 'ready',
      });

      return {
        success: true,
        pdfPath: pdfFilename,
        attemptsMade: 1,
      };
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';

      // Store failed output
      await database.insert(runOutputs).values({
        runId,
        workflowVersionId,
        templateKey,
        fileType: 'pdf',
        storagePath: '',
        status: 'failed',
        error: errorMessage,
      });

      return {
        success: false,
        error: errorMessage,
        attemptsMade: 1,
      };
    }
  }
}

// Singleton instance
export const pdfQueueService = new PdfQueueService();

// Auto-start in non-test environments
if (process.env.NODE_ENV !== 'test') {
  pdfQueueService.start();

  // Graceful shutdown
  process.on('SIGTERM', () => {
    logger.info('SIGTERM received, stopping PDF queue processor');
    pdfQueueService.stop();
  });

  process.on('SIGINT', () => {
    logger.info('SIGINT received, stopping PDF queue processor');
    pdfQueueService.stop();
  });
}

import { eq, and, desc } from "drizzle-orm";

import { workflowRuns } from "@shared/schema";

import { db } from "../db";
import { logger } from "../logger";
export class PortalService {
    /**
     * List runs accessible to a given email
     * Returns: Run ID, Date, Status, Workflow Title
     * Filters: Completed/In-Progress
     */
    async listRunsForEmail(email: string) {
        try {
            // Find runs associated with this email
