}

export interface ValidationWarning {
  code: string;
  message: string;
  variable?: string;
  severity: 'info' | 'warning' | 'error';
}

/**
 * Analyze a DOCX template
 */
export async function analyzeTemplate(fileRef: string): Promise<TemplateAnalysis> {
  // Verify file exists
  const exists = await templateFileExists(fileRef);
  if (!exists) {
    throw createError.notFound('Template file');
  }

  const templatePath = getTemplateFilePath(fileRef);

  try {
    // Read template file
    const content = await fs.readFile(templatePath, 'binary');
    const zip = new PizZip(content);

    // Create docxtemplater instance
    const doc = new Docxtemplater(zip, {
      paragraphLoop: true,
      linebreaks: true,
    });

    // Get full text
    const fullText = doc.getFullText();

    // Extract all placeholders
    const placeholders = extractAllPlaceholders(fullText);

    // Categorize placeholders
    const variables: PlaceholderInfo[] = [];
    const loops: LoopInfo[] = [];
    const conditionals: ConditionalInfo[] = [];
    const helpersUsed = new Set<string>();

    for (const ph of placeholders) {
      if (ph.type === 'loop') {
        loops.push({
          variable: ph.name,
          depth: ph.depth || 0,
        });
      } else if (ph.type === 'conditional') {
        conditionals.push({
          variable: ph.name,
          type: ph.conditionalType as 'if' | 'unless',
        });
      } else if (ph.type === 'helper') {
        if (ph.helperName) {
          helpersUsed.add(ph.helperName);
        }
      }
      variables.push(ph);
    }

    // Calculate stats
    const uniqueVars = new Set(
      variables.filter((v) => v.type === 'variable').map((v) => v.name)
    );

    const stats = {
      totalPlaceholders: placeholders.length,
      uniqueVariables: uniqueVars.size,
      loopCount: loops.length,
      conditionalCount: conditionals.length,
      helperCallCount: Array.from(helpersUsed).length,
      maxNestingDepth: calculateMaxDepth(loops),
    };

    return {
      variables,
      loops,
      conditionals,
      helpers: Array.from(helpersUsed).sort(),
      stats,
    };
  } catch (error: any) {
    if (error.code === 'ENOENT') {
      throw createError.notFound('Template file', templatePath);
    }
    throw createError.internal(
      `Failed to analyze template: ${error.message || 'Unknown error'}`
    );
  }
}

/**
 * Extract all placeholders from template text
 */
function extractAllPlaceholders(text: string): PlaceholderInfo[] {
  const placeholders: PlaceholderInfo[] = [];
  const regex = /\{([#\/]?)([^{}]+?)\}/g;
  let match;

  const loopStack: { name: string; depth: number }[] = [];

  while ((match = regex.exec(text)) !== null) {
    const prefix = match[1]; // '#' for opening, '/' for closing, '' for simple
    const content = match[2].trim();

    if (prefix === '/') {
      // Closing tag - pop from loop stack
      loopStack.pop();
      continue;
    }

    const parts = content.split(/\s+/);
    const currentDepth = loopStack.length;

    if (prefix === '#') {
      // Control structure
      const controlType = parts[0];

      if (['if', 'unless'].includes(controlType)) {
        // Conditional
        const varName = parts[1] ?? '';
        placeholders.push({
          name: varName,
          type: 'conditional',
          conditionalType: controlType,
        } as PlaceholderInfo);
      } else if (['each', 'for'].includes(controlType)) {
        // Loop with explicit keyword
        const varName = parts[1] ?? '';
        loopStack.push({ name: varName, depth: currentDepth });
        placeholders.push({
          name: varName,
          type: 'loop',
          depth: currentDepth,
        } as PlaceholderInfo);
      } else {
        // Simple loop syntax: {#items}
        loopStack.push({ name: controlType, depth: currentDepth });
        placeholders.push({
          name: controlType,
          type: 'loop',
          depth: currentDepth,
        } as PlaceholderInfo);
      }
    } else {
      // Simple variable or helper call
      if (parts.length > 1 && parts[0] in docxHelpers) {
        // Helper call: {helper variable}
        placeholders.push({
          name: parts[1],
          type: 'helper',
          helperName: parts[0],
          path: parts[1].includes('.') ? parts[1] : undefined,
        });
      } else {
        // Simple variable: {variable} or {user.name}
        placeholders.push({
          name: parts[0],
          type: 'variable',
          path: parts[0].includes('.') ? parts[0] : undefined,
        });
      }
    }
  }

  return placeholders;
}

/**
 * Calculate max nesting depth
 */
function calculateMaxDepth(loops: LoopInfo[]): number {
  if (loops.length === 0) {return 0;}
  return Math.max(...loops.map((l) => l.depth)) + 1;
}

/**
 * Validate template with sample data
 */
export async function validateTemplateWithData(
  fileRef: string,
  sampleData: Record<string, any>
): Promise<ValidationResult> {
  // Analyze template
  const analysis = await analyzeTemplate(fileRef);

  // Extract unique variable names (excluding helpers and system vars)
  const templateVars = new Set<string>();
  for (const variable of analysis.variables) {
    if (variable.type === 'variable' || variable.type === 'loop' || variable.type === 'conditional') {
      // For nested paths, take the root variable
      const rootVar = variable.path ? variable.path.split('.')[0] : variable.name;
      templateVars.add(rootVar);
    }
  }

  // Get data keys (excluding helpers)
  const dataKeys = Object.keys(sampleData).filter((key) => !(key in docxHelpers));

  // Find missing variables
  const missing: string[] = [];
  for (const varName of Array.from(templateVars)) {
    if (!(varName in sampleData) && !(varName in docxHelpers)) {
      missing.push(varName);
    }
  }

  // Find extra keys
  const extra = dataKeys.filter((key) => !templateVars.has(key));

  // Generate warnings
  const warnings: ValidationWarning[] = [];

  // Check for type mismatches
  for (const variable of analysis.variables) {
    if (variable.type === 'loop') {
      const value = sampleData[variable.name];
      if (value !== undefined && !Array.isArray(value)) {
        warnings.push({
          code: 'TYPE_MISMATCH',
          message: `Loop variable '${variable.name}' should be an array`,
          variable: variable.name,
          severity: 'error',
        });
      }
    }
  }

  // Check for potentially empty arrays
  for (const variable of analysis.variables) {
    if (variable.type === 'loop') {
      const value = sampleData[variable.name];
      if (Array.isArray(value) && value.length === 0) {
        warnings.push({
          code: 'EMPTY_ARRAY',
          message: `Loop variable '${variable.name}' is an empty array`,
          variable: variable.name,
          severity: 'warning',
        });
      }
    }
  }

  // Check for unused helpers
  for (const helper of analysis.helpers) {
    warnings.push({
      code: 'HELPER_USED',
      message: `Helper function '${helper}' is used in template`,
      severity: 'info',
    });
  }

  // Calculate coverage
  const totalRequired = templateVars.size;
  const provided = totalRequired - missing.length;
  const coverage = totalRequired > 0 ? Math.round((provided / totalRequired) * 100) : 100;

  return {
    valid: missing.length === 0 && warnings.filter((w) => w.severity === 'error').length === 0,
    coverage,
    missing,
    extra,
    warnings,
  };
}

/**
 * Get suggested sample data for a template
 * Generates placeholder values based on variable names and types
 */
export async function generateSampleData(fileRef: string): Promise<Record<string, any>> {
  const analysis = await analyzeTemplate(fileRef);
  const sampleData: Record<string, any> = {};

  for (const variable of analysis.variables) {
    if (variable.type === 'variable') {
      // Generate sample value based on name
      sampleData[variable.name] = generateSampleValue(variable.name);
    } else if (variable.type === 'loop') {
      // Generate sample array
      sampleData[variable.name] = [
        { id: 1, name: `Sample ${variable.name} 1` },
        { id: 2, name: `Sample ${variable.name} 2` },
      ];
    } else if (variable.type === 'conditional') {
      // Generate boolean
      sampleData[variable.name] = true;
    }
  }

  return sampleData;
}

/**
 * Generate sample value based on variable name heuristics
 */
function generateSampleValue(varName: string): any {
  const lower = varName.toLowerCase();

  // Date fields
  if (lower.includes('date') || lower.includes('time')) {
    return new Date().toISOString();
  }

  // Numeric fields
  if (
    lower.includes('amount') ||
    lower.includes('price') ||
    lower.includes('total') ||
    lower.includes('quantity') ||
    lower.includes('count')
  ) {
    return 1234.56;
  }

  // Boolean fields
  if (
    lower.includes('is') ||
    lower.includes('has') ||
    lower.includes('should') ||
    lower.includes('enabled')
  ) {
    return true;
  }

  // Email fields
  if (lower.includes('email')) {
    return 'sample@example.com';
  }

  // Phone fields
  if (lower.includes('phone')) {
    return '(555) 123-4567';
  }

  // Name fields
  if (lower.includes('name')) {
    return 'Sample Name';
  }

  // Default: string
  return `Sample ${varName}`;
}

/**
 * Compare two templates and find differences
 */
export async function compareTemplates(
  fileRef1: string,
  fileRef2: string
): Promise<{
  added: string[];
  removed: string[];
  unchanged: string[];
}> {
  const analysis1 = await analyzeTemplate(fileRef1);
  const analysis2 = await analyzeTemplate(fileRef2);

  const vars1 = new Set(analysis1.variables.map((v) => v.name));
  const vars2 = new Set(analysis2.variables.map((v) => v.name));

  const added = Array.from(vars2).filter((v) => !vars1.has(v));
  const removed = Array.from(vars1).filter((v) => !vars2.has(v));
  const unchanged = Array.from(vars1).filter((v) => vars2.has(v));

  return {
    added: added.sort(),
    removed: removed.sort(),
    unchanged: unchanged.sort(),
  };
}

/**
 * Template Analytics Service
 *
 * Track and analyze document generation metrics:
 * - Success/failure rates
 * - Performance metrics
 * - Common errors
 * - Usage statistics
 * - Popular mappings
 *
 * Features:
 * - Real-time metrics tracking
 * - Aggregated statistics
 * - Trend analysis
 * - Error pattern detection
 * - Performance insights
 *
 * Usage:
 * ```typescript
 * // Track generation
 * await templateAnalytics.trackGeneration(templateId, 'success', 1234);
 *
 * // Get insights
 * const insights = await templateAnalytics.getTemplateInsights(templateId);
 * console.log('Success rate:', insights.successRate);
 * console.log('Avg duration:', insights.avgDuration);
 * ```
 */
import { eq, and, desc, gte, sql, count } from 'drizzle-orm';

import { templateGenerationMetrics, templates } from '../../shared/schema';
import { db } from '../db';
import { logger } from '../logger';
// ============================================================================
// TYPES
// ============================================================================
export interface GenerationMetric {
  id: string;
  templateId: string;
  runId: string | null;
  result: 'success' | 'failure' | 'skipped';
  durationMs: number | null;
  errorMessage: string | null;
  createdAt: Date;
}
export interface TemplateInsights {
  templateId: string;
  templateName: string;
  totalGenerations: number;
  successCount: number;
  failureCount: number;
  skippedCount: number;
  successRate: number; // 0-100
  avgDuration: number | null; // milliseconds
  medianDuration: number | null;
  p95Duration: number | null; // 95th percentile
  commonErrors: Array<{
    error: string;
    count: number;
    percentage: number;
  }>;
  recentGenerations: GenerationMetric[];
  trends: {
    last7Days: TrendData;
    last30Days: TrendData;
  };
}
export interface TrendData {
  totalGenerations: number;
  successRate: number;
  avgDuration: number | null;
  changeFromPrevious: {
    generations: number; // % change
    successRate: number; // % change
    duration: number; // % change
  };
}
export interface SystemWideMetrics {
  totalTemplates: number;
  totalGenerations: number;
  overallSuccessRate: number;
  avgGenerationTime: number | null;
  topTemplates: Array<{
    templateId: string;
    templateName: string;
    generationCount: number;
    successRate: number;
  }>;
  recentErrors: Array<{
    templateId: string;
    templateName: string;
    error: string;
    occurredAt: Date;
  }>;
}
// ============================================================================
// SERVICE CLASS
// ============================================================================
export class TemplateAnalyticsService {
  /**
   * Track a document generation event
   */
  async trackGeneration(
    templateId: string,
    result: 'success' | 'failure' | 'skipped',
    durationMs?: number,
    errorMessage?: string,
    runId?: string
  ): Promise<void> {
    try {
      await db.insert(templateGenerationMetrics).values({
        templateId,
        runId: runId ?? null,
        result,
        durationMs: durationMs ?? null,
        errorMessage: errorMessage ?? null,
      });
      logger.debug(
        {
          templateId,
          result,
          durationMs,
        },
        'Generation metric tracked'
      );
    } catch (error: any) {
      logger.error({ error, templateId }, 'Failed to track generation metric');
      // Don't throw - metrics tracking shouldn't break generation
    }
  }
  /**
   * Get comprehensive insights for a template
   */
  async getTemplateInsights(templateId: string): Promise<TemplateInsights> {
    logger.info({ templateId }, 'Fetching template insights');
    // Get template info
    const [template] = await db
      .select()
      .from(templates)
      .where(eq(templates.id, templateId))
      .limit(1);
    if (!template) {
      throw new Error('Template not found');
    }
    // Get all metrics for this template
    const metrics = await db
      .select()
      .from(templateGenerationMetrics)
      .where(eq(templateGenerationMetrics.templateId, templateId))
      .orderBy(desc(templateGenerationMetrics.createdAt));
    // Calculate basic stats
    const totalGenerations = metrics.length;
    const successCount = metrics.filter((m) => m.result === 'success').length;
    const failureCount = metrics.filter((m) => m.result === 'failure').length;
    const skippedCount = metrics.filter((m) => m.result === 'skipped').length;
    const successRate = totalGenerations > 0 ? (successCount / totalGenerations) * 100 : 0;
    // Calculate duration stats (only for successful generations)
    const durations = metrics
      .filter((m) => m.result === 'success' && m.durationMs !== null)
      .map((m) => m.durationMs as number)
      .sort((a, b) => a - b);
    const avgDuration =
      durations.length > 0
        ? durations.reduce((sum, d) => sum + d, 0) / durations.length
        : null;
    const medianDuration =
      durations.length > 0
        ? durations[Math.floor(durations.length / 2)]
        : null;
    const p95Duration =
      durations.length > 0
        ? durations[Math.floor(durations.length * 0.95)]
        : null;
    // Analyze common errors
    const errors = metrics
      .filter((m) => m.result === 'failure' && m.errorMessage)
      .map((m) => m.errorMessage as string);
    const errorCounts = errors.reduce((acc, error) => {
      acc[error] = (acc[error] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);
    const commonErrors = Object.entries(errorCounts)
      .map(([error, count]) => ({
        error,
        count,
        percentage: (count / failureCount) * 100,
      }))
      .sort((a, b) => b.count - a.count)
      .slice(0, 5); // Top 5 errors
    // Get recent generations (last 10)
    const recentGenerations = metrics.slice(0, 10) as GenerationMetric[];
    // Calculate trends
    const now = new Date();
    const last7Days = await this.calculateTrend(templateId, 7);
    const last30Days = await this.calculateTrend(templateId, 30);
    return {
      templateId,
      templateName: template.name,
      totalGenerations,
      successCount,
      failureCount,
      skippedCount,
      successRate: Math.round(successRate * 100) / 100,
      avgDuration: avgDuration ? Math.round(avgDuration) : null,
      medianDuration,
      p95Duration,
      commonErrors,
      recentGenerations,
      trends: {
        last7Days,
        last30Days,
      },
    };
  }
  /**
   * Calculate trend data for a time period
   */
  private async calculateTrend(templateId: string, days: number): Promise<TrendData> {
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - days);
    const previousStartDate = new Date();
    previousStartDate.setDate(previousStartDate.getDate() - days * 2);
    // Current period
    const currentMetrics = await db
      .select()
      .from(templateGenerationMetrics)
      .where(
        and(
          eq(templateGenerationMetrics.templateId, templateId),
          gte(templateGenerationMetrics.createdAt, startDate)
        )
      );
    // Previous period (for comparison)
    const previousMetrics = await db
      .select()
      .from(templateGenerationMetrics)
      .where(
        and(
          eq(templateGenerationMetrics.templateId, templateId),
          gte(templateGenerationMetrics.createdAt, previousStartDate),
          sql`${templateGenerationMetrics.createdAt} < ${startDate}`
        )
      );
    // Calculate current stats
    const currentTotal = currentMetrics.length;
    const currentSuccess = currentMetrics.filter((m) => m.result === 'success').length;
    const currentSuccessRate = currentTotal > 0 ? (currentSuccess / currentTotal) * 100 : 0;
    const currentDurations = currentMetrics
      .filter((m) => m.result === 'success' && m.durationMs)
      .map((m) => m.durationMs as number);
    const currentAvgDuration =
      currentDurations.length > 0
        ? currentDurations.reduce((sum, d) => sum + d, 0) / currentDurations.length
        : null;
    // Calculate previous stats
    const previousTotal = previousMetrics.length;
    const previousSuccess = previousMetrics.filter((m) => m.result === 'success').length;
    const previousSuccessRate = previousTotal > 0 ? (previousSuccess / previousTotal) * 100 : 0;
    const previousDurations = previousMetrics
      .filter((m) => m.result === 'success' && m.durationMs)
      .map((m) => m.durationMs as number);
    const previousAvgDuration =
      previousDurations.length > 0
        ? previousDurations.reduce((sum, d) => sum + d, 0) / previousDurations.length
        : null;
    // Calculate changes
    const generationsChange =
      previousTotal > 0 ? ((currentTotal - previousTotal) / previousTotal) * 100 : 0;
    const successRateChange = currentSuccessRate - previousSuccessRate;
    const durationChange =
      previousAvgDuration && currentAvgDuration
        ? ((currentAvgDuration - previousAvgDuration) / previousAvgDuration) * 100
        : 0;
    return {
      totalGenerations: currentTotal,
      successRate: Math.round(currentSuccessRate * 100) / 100,
      avgDuration: currentAvgDuration ? Math.round(currentAvgDuration) : null,
      changeFromPrevious: {
        generations: Math.round(generationsChange * 100) / 100,
        successRate: Math.round(successRateChange * 100) / 100,
        duration: Math.round(durationChange * 100) / 100,
      },
    };
  }
  /**
   * Get system-wide metrics
   */
  async getSystemWideMetrics(): Promise<SystemWideMetrics> {
    logger.info('Fetching system-wide metrics');
    // Total templates
    const totalTemplates = await db
      .select({ count: count() })
      .from(templates)
      .then((result) => result[0]?.count || 0);
    // Total generations
    const totalGenerations = await db
      .select({ count: count() })
      .from(templateGenerationMetrics)
      .then((result) => result[0]?.count || 0);
    // Overall success rate
    const successCount = await db
      .select({ count: count() })
      .from(templateGenerationMetrics)
      .where(eq(templateGenerationMetrics.result, 'success'))
      .then((result) => result[0]?.count || 0);
    const overallSuccessRate =
      totalGenerations > 0 ? (successCount / totalGenerations) * 100 : 0;
    // Average generation time
    const avgGenerationTime = await db
      .select({
        avg: sql<number>`AVG(${templateGenerationMetrics.durationMs})`,
      })
      .from(templateGenerationMetrics)
      .where(
        and(
          eq(templateGenerationMetrics.result, 'success'),
          sql`${templateGenerationMetrics.durationMs} IS NOT NULL`
        )
      )
      .then((result) => result[0]?.avg ?? null);
    // Top templates by generation count
    const topTemplatesData = await db
      .select({
        templateId: templateGenerationMetrics.templateId,
        count: count(),
        successCount: sql<number>`SUM(CASE WHEN ${templateGenerationMetrics.result} = 'success' THEN 1 ELSE 0 END)`,
      })
      .from(templateGenerationMetrics)
      .groupBy(templateGenerationMetrics.templateId)
      .orderBy(desc(count()))
      .limit(5);
    // Get template names
    const topTemplates = await Promise.all(
      topTemplatesData.map(async (t) => {
        const [template] = await db
          .select()
          .from(templates)
          .where(eq(templates.id, t.templateId))
          .limit(1);
        return {
          templateId: t.templateId,
          templateName: template?.name || 'Unknown',
          generationCount: t.count,
          successRate: t.count > 0 ? (t.successCount / t.count) * 100 : 0,
        };
      })
    );
    // Recent errors (last 10)
    const recentErrorsData = await db
      .select()
      .from(templateGenerationMetrics)
      .where(eq(templateGenerationMetrics.result, 'failure'))
      .orderBy(desc(templateGenerationMetrics.createdAt))
      .limit(10);
    const recentErrors = await Promise.all(
      recentErrorsData.map(async (e) => {
        const [template] = await db
          .select()
          .from(templates)
          .where(eq(templates.id, e.templateId))
          .limit(1);
        return {
          templateId: e.templateId,
          templateName: template?.name || 'Unknown',
          error: e.errorMessage || 'Unknown error',
          occurredAt: e.createdAt!,
        };
      })
    );
    return {
      totalTemplates,
      totalGenerations,
      overallSuccessRate: Math.round(overallSuccessRate * 100) / 100,
      avgGenerationTime: avgGenerationTime ? Math.round(avgGenerationTime) : null,
      topTemplates,
      recentErrors,
    };
  }
  /**
   * Clean up old metrics (keep last N days)
   */
  async cleanupOldMetrics(retentionDays: number = 90): Promise<number> {
    logger.info({ retentionDays }, 'Cleaning up old metrics');
    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - retentionDays);
    const deleted = await db
      .delete(templateGenerationMetrics)
      .where(sql`${templateGenerationMetrics.createdAt} < ${cutoffDate}`)
      .returning({ id: templateGenerationMetrics.id });
    logger.info({ deletedCount: deleted.length, retentionDays }, 'Old metrics cleaned up');
    return deleted.length;
  }
  /**
   * Get metrics for a specific time range
   */
  async getMetricsInRange(
    templateId: string,
    startDate: Date,
    endDate: Date
  ): Promise<GenerationMetric[]> {
    const metrics = await db
      .select()
      .from(templateGenerationMetrics)
      .where(
        and(
          eq(templateGenerationMetrics.templateId, templateId),
          gte(templateGenerationMetrics.createdAt, startDate),
          sql`${templateGenerationMetrics.createdAt} <= ${endDate}`
        )
      )
      .orderBy(desc(templateGenerationMetrics.createdAt));
    return metrics as GenerationMetric[];
  }
  /**
   * Export metrics to CSV
   */
  async exportMetricsToCsv(templateId: string): Promise<string> {
    const metrics = await db
      .select()
      .from(templateGenerationMetrics)
      .where(eq(templateGenerationMetrics.templateId, templateId))
      .orderBy(desc(templateGenerationMetrics.createdAt));
    // CSV header
    let csv = 'ID,Template ID,Run ID,Result,Duration (ms),Error,Created At\n';
    // CSV rows
    for (const metric of metrics) {
      csv += `${metric.id},${metric.templateId},${metric.runId ?? ''},${metric.result},${
        metric.durationMs ?? ''
      },"${(metric.errorMessage ?? '').replace(/"/g, '""')}",${metric.createdAt}\n`;
    }
    return csv;
  }
}
