/**
 * AI Error Handling
 *
 * Unified error handling for all AI services
 */

import type { AIErrorCode } from './types';

export interface AIErrorDetails {
  code: AIErrorCode;
  message: string;
  details?: any;
  retryable?: boolean;
  retryAfterSeconds?: number;
}

/**
 * Custom AI Error class
 */
export class AIError extends Error {
  public readonly code: AIErrorCode;
  public readonly details?: any;
  public readonly retryable: boolean;
  public readonly retryAfterSeconds?: number;

  constructor(
    message: string,
    code: AIErrorCode,
    details?: any,
    retryable = false,
    retryAfterSeconds?: number
  ) {
    super(message);
    this.name = 'AIError';
    this.code = code;
    this.details = details;
    this.retryable = retryable;
    this.retryAfterSeconds = retryAfterSeconds;

    // Maintains proper stack trace for where our error was thrown (only available on V8)
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, AIError);
    }
  }

  /**
   * Convert to JSON for API responses
   */
  toJSON(): AIErrorDetails {
    return {
      code: this.code,
      message: this.message,
      details: this.details,
      retryable: this.retryable,
      retryAfterSeconds: this.retryAfterSeconds,
    };
  }

  /**
   * Create error from unknown error object
   */
  static fromUnknown(error: unknown, defaultCode: AIErrorCode = 'API_ERROR'): AIError {
    if (error instanceof AIError) {
      return error;
    }

    if (error instanceof Error) {
      return new AIError(error.message, defaultCode, {
        originalError: error.name,
        stack: error.stack,
      });
    }

    return new AIError(String(error), defaultCode);
  }
}

/**
 * Create an AI error (factory function for backwards compatibility)
 */
export function createAIError(
  message: string,
  code: AIErrorCode,
  details?: any,
  retryable = false,
  retryAfterSeconds?: number
): AIError {
  return new AIError(message, code, details, retryable, retryAfterSeconds);
}

/**
 * Check if error is a rate limit error
 */
export function isRateLimitError(error: any): boolean {
  return (
    error?.code === 'RATE_LIMIT' ||
    error?.status === 429 ||
    error?.code === 'rate_limit_exceeded' ||
    error?.message?.includes('429') ||
    error?.message?.includes('Quota exceeded') ||
    error?.message?.includes('rate limit')
  );
}

/**
 * Check if error is a timeout error
 */
export function isTimeoutError(error: any): boolean {
  return (
    error?.code === 'TIMEOUT' ||
    error?.code === 'ETIMEDOUT' ||
    error?.message?.includes('timeout') ||
    error?.message?.includes('timed out')
  );
}

/**
 * Extract retry-after seconds from error
 */
export function getRetryAfter(error: any): number {
  // Check for Retry-After header (seconds)
  if (error?.response?.headers?.['retry-after']) {
    const retryAfter = parseInt(error.response.headers['retry-after'], 10);
    if (!isNaN(retryAfter)) {
      return retryAfter * 1000; // Convert to ms
    }
  }

  // Check for rate limit reset timestamp
  if (error?.response?.headers?.['x-ratelimit-reset']) {
    const resetTime = parseInt(error.response.headers['x-ratelimit-reset'], 10);
    if (!isNaN(resetTime)) {
      const now = Math.floor(Date.now() / 1000);
      const waitSeconds = Math.max(0, resetTime - now);
      return waitSeconds * 1000; // Convert to ms
    }
  }

  // Default to 60 seconds if no info available
  return 60000;
}

/**
 * Quality threshold details for quality rejection errors
 */
export interface QualityThresholdDetails {
  qualityScore: number;
  threshold: number;
  issues: Array<{
    severity: 'error' | 'warning' | 'suggestion';
    category: string;
    message: string;
    location?: string;
    suggestion?: string;
  }>;
  suggestions: string[];
  breakdown: {
    aliases: number;
    types: number;
    structure: number;
    ux: number;
    completeness: number;
    validation: number;
  };
}

/**
 * Quality Threshold Error - thrown when AI-generated workflow quality is below minimum threshold
 */
export class QualityThresholdError extends AIError {
  public readonly qualityScore: number;
  public readonly threshold: number;
  public readonly qualityIssues: QualityThresholdDetails['issues'];
  public readonly qualitySuggestions: string[];
  public readonly qualityBreakdown: QualityThresholdDetails['breakdown'];

  constructor(details: QualityThresholdDetails) {
    super(
      `Generated workflow quality score (${details.qualityScore}) is below minimum threshold (${details.threshold})`,
      'QUALITY_THRESHOLD',
      details,
      false // not retryable automatically
    );
    this.name = 'QualityThresholdError';
    this.qualityScore = details.qualityScore;
    this.threshold = details.threshold;
    this.qualityIssues = details.issues;
    this.qualitySuggestions = details.suggestions;
    this.qualityBreakdown = details.breakdown;

    // Maintains proper stack trace
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, QualityThresholdError);
    }
  }

  /**
   * Convert to JSON for API responses
   */
  toJSON(): AIErrorDetails & { quality: QualityThresholdDetails } {
    return {
      ...super.toJSON(),
      quality: {
        qualityScore: this.qualityScore,
        threshold: this.threshold,
        issues: this.qualityIssues,
        suggestions: this.qualitySuggestions,
        breakdown: this.qualityBreakdown,
      },
    };
  }
}

/**
 * Check if error is a quality threshold error
 */
export function isQualityThresholdError(error: any): error is QualityThresholdError {
  return error instanceof QualityThresholdError || error?.code === 'QUALITY_THRESHOLD';
}

/**
 * AI Provider Client
 *
 * Unified client that delegates to provider-specific implementations
 * Handles retry logic, rate limiting, and telemetry
 */

import { createLogger } from '../../logger';

import { AIError, isRateLimitError, isTimeoutError, getRetryAfter } from './AIError';
import { estimateTokenCount } from './AIServiceUtils';
import { ModelRegistry } from './ModelRegistry';
import { ProviderFactory } from './providers/ProviderFactory';

import type { IAIProvider } from './providers/types';
import type { TaskType } from './types';
import type { AIProvider, AIProviderConfig } from '../../../shared/types/ai';

const logger = createLogger({ module: 'ai-provider-client' });

/**
 * AI Provider Client - handles all LLM API calls with retry logic and telemetry
 */
export class AIProviderClient {
  private provider: IAIProvider | null = null;
  private config: AIProviderConfig;

  constructor(config: AIProviderConfig = {} as any) {
    this.config = config;

    // Only create provider if we have a valid config
    if (config.provider && config.apiKey) {
      try {
        this.provider = ProviderFactory.createProvider(config);
      } catch (error: any) {
        logger.warn({ error: error.message, config: { provider: config.provider } }, 'Failed to create provider');
      }
    }
  }

  async callLLM(prompt: string, taskType: TaskType, systemMessage?: string): Promise<string> {
    if (!this.provider) {
      throw new AIError('AI provider not initialized', 'API_ERROR', {
        config: { provider: this.config.provider }
      });
    }

    const { provider, model } = this.config;
    const startTime = Date.now();
    const promptTokens = estimateTokenCount(prompt);

    // Get task-specific max tokens
    const maxTokens = this.config.maxTokens || ModelRegistry.getTaskMaxTokens(taskType);

    // Telemetry: Track AI request
    logger.info({
      event: 'ai_request_started',
      provider,
      model,
      taskType,
      promptTokens,
      maxTokens,
    }, 'AI request started');

    const maxRetries = 6;
    let attempt = 0;

    while (attempt <= maxRetries) {
      try {
        // Delegate to provider
        const response = await this.provider.generateResponse(prompt, taskType, systemMessage);

        // Telemetry: Track success
        const responseTokens = estimateTokenCount(response);
        const duration = Date.now() - startTime;
        const cost = ModelRegistry.estimateCost(provider as any, model, promptTokens, responseTokens);

        logger.info({
          event: 'ai_request_success',
          provider,
          model,
          taskType,
          promptTokens,
          responseTokens,
          totalTokens: promptTokens + responseTokens,
          durationMs: duration,
          estimatedCostUSD: cost,
        }, 'AI request succeeded');

        return response;
      } catch (error: any) {
        // Handle rate limiting with retry
        if (isRateLimitError(error)) {
          const retryAfterMs = getRetryAfter(error);

          if (attempt < maxRetries) {
            const waitMs = retryAfterMs || (Math.pow(2, attempt) * 1000); // Exponential backoff

            if (waitMs <= 60000) { // Max 60 second wait
              logger.warn({ attempt, waitMs }, 'Rate limit hit, retrying...');
              await new Promise(resolve => setTimeout(resolve, waitMs));
              attempt++;
              continue;
            }
          }

          // Otherwise, throw rate limit error
          const duration = Date.now() - startTime;
          logger.error({
            event: 'ai_request_failed',
            provider,
            model,
            taskType,
            errorType: 'RATE_LIMIT',
            durationMs: duration,
            attempts: attempt + 1,
          }, 'AI request failed: rate limit');

          throw new AIError(
            'AI API rate limit exceeded. Please try again later.',
            'RATE_LIMIT',
            { originalError: error.message, retryAfterSeconds: retryAfterMs ? Math.ceil(retryAfterMs / 1000) : 60 },
            true,
            retryAfterMs ? Math.ceil(retryAfterMs / 1000) : 60
          );
        }

        // Handle timeouts with retry
        if (isTimeoutError(error)) {
          if (attempt < maxRetries) {
            logger.warn({ attempt }, 'Timeout, retrying...');
            await new Promise(resolve => setTimeout(resolve, 1000));
            attempt++;
            continue;
          }

          const duration = Date.now() - startTime;
          logger.error({
            event: 'ai_request_failed',
            provider,
            model,
            taskType,
            errorType: 'TIMEOUT',
            durationMs: duration,
            attempts: attempt + 1,
          }, 'AI request failed: timeout');

          throw new AIError('AI API request timed out', 'TIMEOUT', { originalError: error.message }, true);
        }

        // Generic API error - no retry
        const duration = Date.now() - startTime;
        logger.error({
          event: 'ai_request_failed',
          provider,
          model,
          taskType,
          errorType: 'API_ERROR',
          errorMessage: error.message,
          durationMs: duration,
          attempts: attempt + 1,
        }, 'AI request failed: API error');

        throw AIError.fromUnknown(error, 'API_ERROR');
      }
    }

    throw new Error('Unexpected retry loop exit');
  }

}

