/**
 * Check if alert is in cooldown period
 */
function isInCooldown(key: string, cooldownMinutes: number): boolean {
  const lastAlert = alertCooldowns.get(key);
  if (!lastAlert) {
    return false;
  }

  const cooldownMs = cooldownMinutes * 60 * 1000;
  const elapsed = Date.now() - lastAlert.getTime();

  return elapsed < cooldownMs;
}

/**
 * Set cooldown for alert key
 */
function setCooldown(key: string): void {
  alertCooldowns.set(key, new Date());
}

/**
 * Determine alert severity based on SLI violations
 */
function getSeverity(sliResult: any): 'warning' | 'critical' {
  // Critical if error budget is burned > 100%
  if (sliResult.errorBudgetBurnPct > 100) {
    return 'critical';
  }

  // Critical if success rate is very low
  if (sliResult.successPct < sliResult.target.successPct - 5) {
    return 'critical';
  }

  // Critical if p95 is way over target
  if (sliResult.p95Ms > sliResult.target.p95Ms * 2) {
    return 'critical';
  }

  return 'warning';
}

/**
 * Build alert title
 */
function buildAlertTitle(sliResult: any, workflowId?: string): string {
  const scope = workflowId ? 'Workflow' : 'Project';
  const violations: string[] = [];

  if (sliResult.successPct < sliResult.target.successPct) {
    violations.push('Success Rate');
  }

  if (sliResult.p95Ms > sliResult.target.p95Ms) {
    violations.push('P95 Latency');
  }

  return `${scope} SLI Violation: ${violations.join(', ')}`;
}

/**
 * Build alert message
 */
function buildAlertMessage(sliResult: any): string {
  const lines: string[] = [];

  lines.push('Service Level Indicator (SLI) targets have been violated:');
  lines.push('');

  if (sliResult.successPct < sliResult.target.successPct) {
    lines.push(
      `Γ¥î Success Rate: ${sliResult.successPct.toFixed(2)}% (target: ${sliResult.target.successPct}%)`
    );
  } else {
    lines.push(
      `Γ£à Success Rate: ${sliResult.successPct.toFixed(2)}% (target: ${sliResult.target.successPct}%)`
    );
  }

  if (sliResult.p95Ms > sliResult.target.p95Ms) {
    lines.push(
      `Γ¥î P95 Latency: ${sliResult.p95Ms}ms (target: ${sliResult.target.p95Ms}ms)`
    );
  } else {
    lines.push(
      `Γ£à P95 Latency: ${sliResult.p95Ms}ms (target: ${sliResult.target.p95Ms}ms)`
    );
  }

  lines.push('');
  lines.push(
    `Error Budget Burn: ${sliResult.errorBudgetBurnPct.toFixed(2)}% (${sliResult.target.errorBudgetPct}% allowed)`
  );
  lines.push(`Total Runs: ${sliResult.totalRuns}`);
  lines.push(`Failed Runs: ${sliResult.failedRuns}`);
  lines.push('');
  lines.push(
    `Window: ${sliResult.windowStart.toISOString()} - ${sliResult.windowEnd.toISOString()}`
  );

  return lines.join('\n');
}

/**
 * Batch evaluate SLIs for all projects/workflows
 * Typically called by rollup job after aggregation
 */
export async function batchEvaluateAlerts(): Promise<void> {
  try {
    // Get all unique project/workflow combinations from recent rollups
    const query = `
      SELECT DISTINCT
        project_id,
        workflow_id
      FROM metrics_rollups
      WHERE bucket_start >= NOW() - INTERVAL '7 days'
    `;

    const result = await db.execute({ sql: query, args: [] } as any) as any;

    for (const row of result.rows as any[]) {
      try {
        await evaluateAndAlert({
          projectId: row.project_id,
          workflowId: row.workflow_id,
        });
      } catch (error) {
        logger.error({
          projectId: row.project_id,
          workflowId: row.workflow_id,
          error,
        }, 'Failed to evaluate alert');
      }
    }

    logger.info('Batch alert evaluation completed');
  } catch (error) {
    logger.error({ error }, 'Batch alert evaluation failed');
  }
}

/**
 * Export alert functions
 */
export default {
  evaluateAndAlert,
  batchEvaluateAlerts,
};

/**
 * AggregationService.ts
 * Computes aggregated metrics for runs and workflows.
 */
import { eq, and } from "drizzle-orm";

import {
    workflowRunEvents,
    workflowRunMetrics,
    blockMetrics,
    workflowAnalyticsSnapshots,
    workflowRuns
} from "../../../shared/schema";
import { db } from "../../db";
import logger from "../../logger";
class AggregationService {
    /**
     * Aggregate metrics for a single run after it completes
     */
    async aggregateRun(runId: string) {
        try {
            const events = await db
                .select()
                .from(workflowRunEvents)
                .where(eq(workflowRunEvents.runId, runId))
                .orderBy(workflowRunEvents.timestamp);
            if (events.length === 0) {return;}
            const startEvent = events[0];
            const endEvent = events[events.length - 1];
            const totalTimeMs = endEvent.timestamp.getTime() - startEvent.timestamp.getTime();
            // Count unique pages and blocks visited
            const pagesVisited = new Set(events.filter((e: any) => e.pageId).map((e: any) => e.pageId)).size;
            const blocksVisited = new Set(events.filter((e: any) => e.blockId).map((e: any) => e.blockId)).size;
            const validationErrors = events.filter((e: any) => e.type === 'validation.error').length;
            const scriptErrors = events.filter((e: any) => e.type === 'script.error').length;
            const isCompleted = events.some((e: any) => e.type === 'workflow.complete');
            // Upsert metrics
            await db.insert(workflowRunMetrics).values({
                runId,
                workflowId: startEvent.workflowId,
                versionId: startEvent.versionId,
                totalTimeMs,
                pagesVisited,
                blocksVisited,
                validationErrors,
                scriptErrors,
                completed: isCompleted,
                completedAt: isCompleted ? endEvent.timestamp : null,
                isPreview: startEvent.isPreview,
            }).onConflictDoUpdate({
                target: workflowRunMetrics.runId,
                set: {
                    totalTimeMs,
                    pagesVisited,
                    blocksVisited,
                    validationErrors,
                    scriptErrors,
                    completed: isCompleted,
                    completedAt: isCompleted ? endEvent.timestamp : null,
                }
            });
            // Update block stats (increment counts)
            this.updateBlockMetrics(events);
        } catch (error) {
            logger.error({ error, runId }, "Failed to aggregate run metrics");
        }
    }
    /**
     * Update aggregated block metrics incrementally
     * This is a naive implementation; for scale, we might want to do this in batches or background jobs
     */
    private async updateBlockMetrics(events: typeof workflowRunEvents.$inferSelect[]) {
        // Group events by blockId
        const blockEvents = events.reduce((acc, event) => {
            if (!event.blockId || !event.versionId) {return acc;}
            if (!acc[event.blockId]) {acc[event.blockId] = [];}
            acc[event.blockId].push(event);
            return acc;
        }, {} as Record<string, typeof workflowRunEvents.$inferSelect[]>);
        for (const [blockId, bEvents] of Object.entries(blockEvents)) {
            const visitCount = bEvents.filter((e: any) => e.type === 'block.enter' || e.type === 'block.start').length; // Assuming logical visit
            const errors = bEvents.filter((e: any) => e.type === 'validation.error').length;
            // Naive time spent: sum of (exit - enter) ... requires strict pairing logic, skipping for now
            // Just increment visit counts
            if (visitCount > 0 || errors > 0) {
                // Upsert block metrics
                const versionId = bEvents[0].versionId;
                const workflowId = bEvents[0].workflowId;
                // Check if exists
                const existing = await db.query.blockMetrics.findFirst({
                    where: and(
                        eq(blockMetrics.versionId, versionId),
                        eq(blockMetrics.blockId, blockId)
                    )
                });
                if (existing) {
                    await db.update(blockMetrics)
                        .set({
                            totalVisits: (existing.totalVisits || 0) + visitCount,
                            validationErrorCount: (existing.validationErrorCount || 0) + errors,
                        })
                        .where(eq(blockMetrics.id, existing.id));
                } else {
                    await db.insert(blockMetrics).values({
                        workflowId,
                        versionId,
                        blockId,
                        totalVisits: visitCount,
                        validationErrorCount: errors,
                    });
                }
            }
        }
    }
    /**
     * Nightly aggregation for dashboard
     * (Can be triggered via cron or manual API)
     */
    async computeDailySnapshot(workflowId: string, versionId: string, date: Date = new Date()) {
        // Logic to aggregate all runs/events for a day and store in workflow_analytics_snapshots
        // Implementation deferred to Part 3 refinement
    }
}
