/**
 * BranchingService.ts
 * Analyzes the most common paths users take through the workflow.
 */
import {  sql } from "drizzle-orm";

import { workflowRunEvents } from "../../../shared/schema";
import { db } from "../../db";
export interface BranchNode {
    id: string; // pageId
    data: { label: string; value: number }; // value = flow count
}
export interface BranchEdge {
    source: string;
    target: string;
    value: number; // count of users traversing this edge
}
export interface BranchingGraph {
    nodes: BranchNode[];
    edges: BranchEdge[];
}
class BranchingService {
    async getBranchingGraph(workflowId: string, versionId: string): Promise<BranchingGraph> {
        // We need to construct sequences of page views per run
        // 1. Fetch all page.view events ordered by run, timestamp
        const query = sql`
        SELECT run_id, page_id, timestamp
        FROM ${workflowRunEvents}
        WHERE 
            workflow_id = ${workflowId} 
            AND version_id = ${versionId}
            AND type = 'page.view'
        ORDER BY run_id, timestamp
    `;
        const result = await db.execute(query);
        const rows = result.rows as any[];
        const transitions: Record<string, number> = {}; // "pageA->pageB" => count
        const pageCounts: Record<string, number> = {}; // "pageA" => visitors
        // 2. Process in memory (efficient enough for <10k rows, otherwise need sophisticated SQL window functions)
        let currentRunId: string | null = null;
        let lastPageId: string | null = null;
        rows.forEach((row: any) => {
            pageCounts[row.page_id] = (pageCounts[row.page_id] || 0) + 1;
            if (row.run_id !== currentRunId) {
                // New run
                currentRunId = row.run_id;
                lastPageId = row.page_id;
                // Start node -> first page? Optional.
            } else {
                // Same run, transition
                if (lastPageId && row.page_id) {
                    const key = `${lastPageId}->${row.page_id}`;
                    transitions[key] = (transitions[key] || 0) + 1;
                }
                lastPageId = row.page_id;
            }
        });
        // 3. Construct Graph
        const nodes: BranchNode[] = Object.keys(pageCounts).map(pageId => ({
            id: pageId,
            data: {
                label: `Page ${pageId.substring(0, 8)}`,
                value: pageCounts[pageId]
            }
        }));
        const edges: BranchEdge[] = Object.keys(transitions).map(key => {
            const [source, target] = key.split('->');
            return {
                source,
                target,
                value: transitions[key]
            };
        });
        return { nodes, edges };
    }
}
export const branchingService = new BranchingService();

/**
 * DropoffService.ts
 * Analyzes where users abandon the workflow.
 */
import {    sql } from "drizzle-orm";

import { workflowRunEvents } from "../../../shared/schema";
import { db } from "../../db";
export interface FunnelStep {
    stepId: string; // pageId or blockId
    label: string;
    visitors: number;
    dropoffs: number;
    dropoffRate: number;
}
class DropoffService {
    async getDropoffFunnel(workflowId: string, versionId: string): Promise<FunnelStep[]> {
        // 1. Get all page view events for this version
        // Group by pageId and count unique runIds
        // Note: We need the order of pages to build a proper funnel.
        // For linear flows, "Section Order" from DB helps.
        // For non-linear, we might just list top drop-off pages by count.
        // SQL aggregation:
        // SELECT page_id, count(distinct run_id) as visitors
        // FROM events WHERE type = 'page.view' AND ... GROUP BY page_id
        const pageViews = await db.execute(sql`
        SELECT 
            page_id as "pageId",
            count(distinct run_id) as "visitors"
        FROM ${workflowRunEvents}
        WHERE 
            workflow_id = ${workflowId} 
            AND version_id = ${versionId}
            AND type = 'page.view'
            AND page_id IS NOT NULL
        GROUP BY page_id
    `);
        // Calculate dropoffs... 
        // Dropoff = Visitors of Page X - Visitors of Page X+1? 
        // That only works for linear.
        // Better definition of dropoff:
        // A run "dropped off at Page X" if the LAST event of the run was on Page X and run !completed.
        const dropoffCounts = await db.execute(sql`
        WITH LastEvents AS (
            SELECT DISTINCT ON (run_id) 
                run_id, 
                page_id, 
                type
            FROM ${workflowRunEvents}
            WHERE 
                workflow_id = ${workflowId} 
                AND version_id = ${versionId}
                AND page_id IS NOT NULL
            ORDER BY run_id, timestamp DESC
        )
        SELECT 
            page_id as "pageId", 
            count(*) as "dropoffs"
        FROM LastEvents
        WHERE type != 'workflow.complete' 
        GROUP BY page_id
    `);
        // Merge data
        const funnel: Record<string, FunnelStep> = {};
        // Populate visitors
        for (const row of pageViews.rows as any[]) {
            funnel[row.pageId] = {
                stepId: row.pageId,
                label: `Page ${  row.pageId.substring(0, 8)}`, // Todo: Join with Sections table for real title
                visitors: Number(row.visitors),
                dropoffs: 0,
                dropoffRate: 0
            };
        }
        // Populate dropoffs
        for (const row of dropoffCounts.rows as any[]) {
            if (funnel[row.pageId]) {
                funnel[row.pageId].dropoffs = Number(row.dropoffs);
                funnel[row.pageId].dropoffRate = funnel[row.pageId].visitors > 0
                    ? (Number(row.dropoffs) / funnel[row.pageId].visitors) * 100
                    : 0;
            }
        }
        // Return as array (sorted by some logic? maybe visitors desc)
        return Object.values(funnel).sort((a, b) => b.visitors - a.visitors);
    }
}
export const dropoffService = new DropoffService();

/**
 * HeatmapService.ts
 * Provides block-level metrics for heatmap visualization.
 */

import { eq, and } from "drizzle-orm";

import { blockMetrics } from "../../../shared/schema";
import { db } from "../../db";

export interface BlockHeatmapData {
    blockId: string;
    avgTimeMs: number;
    errorRate: number;
    visits: number;
    score: number; // 0-100 "pain score"
}

class HeatmapService {
    async getBlockHeatmap(workflowId: string, versionId: string): Promise<BlockHeatmapData[]> {
        const metrics = await db
            .select()
            .from(blockMetrics)
            .where(
                and(
                    eq(blockMetrics.workflowId, workflowId),
                    eq(blockMetrics.versionId, versionId)
                )
            );

        return metrics.map((m: any) => {
            const visits = m.totalVisits || 0;
            const errors = m.validationErrorCount || 0;
            const errorRate = visits > 0 ? (errors / visits) * 100 : 0;

            // Calculate a "pain score"
            // Factors: Error rate (high weight), Time spent (medium weight - tricky without baseline)
            let score = errorRate * 5; // e.g. 20% error rate = 100 score
            if (score > 100) {score = 100;}

            return {
                blockId: m.blockId,
                avgTimeMs: m.avgTimeMs || 0,
                errorRate,
                visits,
                score
            };
        });
    }
}

export const heatmapService = new HeatmapService();

import { WorkflowJSON, WorkflowBlock } from "@shared/types/workflow";

import { ChangeImpactReport, ChangeReason, Severity } from "./types";
export class WorkflowChangeAnalyzer {
    /**
     * Analyzes changes between two workflow versions and returns an impact report.
     * @param oldVersion The baseline version (e.g., current published).
     * @param newVersion The target version (e.g., draft or next version).
     */
    public analyze(oldVersion: WorkflowJSON, newVersion: WorkflowJSON): ChangeImpactReport {
        const report: ChangeImpactReport = {
            severity: "safe",
            reasons: [],
            affectedSystems: {
                snapshots: false,
                documents: false,
                dataWrites: false,
                externalSends: false
            }
        };
        // 1. Flatten items for easy lookup
        const oldItems = this.flattenWorkflow(oldVersion);
        const newItems = this.flattenWorkflow(newVersion);
        // 2. Analyze Deleted/Changed Variables
        for (const [id, oldBlock] of oldItems) {
            const newBlock = newItems.get(id);
            if (!newBlock) {
                // Block/Variable Deleted
                this.checkDeletionImpact(id, oldBlock, newItems, report);
            } else {
                // Block/Variable Changed
                this.checkModificationImpact(oldBlock, newBlock, report);
            }
        }
        // 3. Analyze New Variables (Soft Breaking mostly)
        for (const [id, newBlock] of newItems) {
            if (!oldItems.has(id)) {
                this.checkAdditionImpact(newBlock, report);
            }
        }
        // 4. Aggregation Severity
        report.severity = this.calculateOverallSeverity(report.reasons);
        return report;
    }
    private flattenWorkflow(workflow: WorkflowJSON): Map<string, WorkflowBlock> {
        const map = new Map<string, WorkflowBlock>();
        workflow.pages.forEach(page => {
            page.blocks.forEach(block => {
                map.set(block.id, block);
            });
        });
        return map;
    }
    private checkDeletionImpact(id: string, oldBlock: WorkflowBlock, newItems: Map<string, WorkflowBlock>, report: ChangeImpactReport) {
        // Simple heuristic: If it's a step (variable), deleting it is RISKY.
        // We need usage detection to be precise, but for now, let's assume if it was a data-bearing step, it's Hard Breaking.
        const type = oldBlock.type;
        // Check if it was a variable-bearing step
        const isVariable = !["prefill", "validate", "branch", "delete_record", "display"].includes(type as string);
        if (isVariable) {
            const alias = oldBlock.alias || oldBlock.variableName; // Check both legacy and new props
            // Check usage in NEW version to see if anything breaks
            const usage = this.findUsage(id, alias, newItems);
            if (usage.length > 0) {
                report.reasons.push({
                    severity: "hard_breaking",
                    message: `Variable '${oldBlock.title || id}' was deleted but is still referenced by: ${usage.join(", ")}`,
                    targetId: id,
                    targetType: "variable"
                });
                // Set affected systems based on usage types
                report.affectedSystems.snapshots = true;
                report.affectedSystems.documents = usage.some(u => u.includes("Document"));
                report.affectedSystems.dataWrites = usage.some(u => u.includes("Write") || u.includes("Record"));
                report.affectedSystems.externalSends = usage.some(u => u.includes("External"));
            } else {
                // Deleted but unused - Safe? Or Soft if it was required?
                // Let's say Soft for now as it alters schema.
                report.reasons.push({
                    severity: "soft_breaking",
                    message: `Variable '${oldBlock.title || id}' was deleted. Snapshots containing this data may be incomplete.`,
                    targetId: id,
                    targetType: "variable"
                });
                report.affectedSystems.snapshots = true;
            }
        }
    }
    private checkModificationImpact(oldBlock: WorkflowBlock, newBlock: WorkflowBlock, report: ChangeImpactReport) {
        // Type Change
        if (oldBlock.type !== newBlock.type) {
            report.reasons.push({
                severity: "hard_breaking",
                message: `Variable '${oldBlock.title || oldBlock.id}' changed type from ${oldBlock.type} to ${newBlock.type}.`,
                targetId: oldBlock.id,
                targetType: "variable"
            });
            report.affectedSystems.snapshots = true;
        }
        // Required Flag Change (Soft Breaking)
        if (!oldBlock.required && newBlock.required) {
            report.reasons.push({
                severity: "soft_breaking",
                message: `Variable '${oldBlock.title || oldBlock.id}' is now required.`,
                targetId: oldBlock.id,
                targetType: "variable"
            });
            report.affectedSystems.snapshots = true;
        }
        // TODO: Deep check on config changes (e.g. column mapping changes)
    }
    private checkAdditionImpact(newBlock: WorkflowBlock, report: ChangeImpactReport) {
        if (newBlock.required) {
            report.reasons.push({
                severity: "soft_breaking",
                message: `New required variable '${newBlock.title || newBlock.id}' added.`,
                targetId: newBlock.id,
                targetType: "variable"
            });
            report.affectedSystems.snapshots = true; // Snapshots won't have this value
        }
    }
    // Helper to build alias map
    private buildAliasMap(items: Map<string, WorkflowBlock>): Map<string, string> {
        const aliasMap = new Map<string, string>(); // ID -> Alias
        for (const [id, block] of items) {
            if (block.alias) {
                aliasMap.set(id, block.alias);
            }
        }
        return aliasMap;
    }
    // Reverse map for lookup
    private buildReverseAliasMap(items: Map<string, WorkflowBlock>): Map<string, string> {
        const revMap = new Map<string, string>(); // Alias -> ID
        for (const [id, block] of items) {
            if (block.alias) {
                revMap.set(block.alias, id);
            }
        }
        return revMap;
    }
    private findUsage(targetId: string, targetAlias: string | undefined, items: Map<string, WorkflowBlock>): string[] {
        const usages: string[] = [];
        for (const [id, block] of items) {
            // Check config for references
            // 1. JS Question inputs
            if (block.type === 'js_question' && block.config) {
                const inputs = (block.config.inputKeys as string[]) ?? [];
                if (inputs.includes(targetId) || (targetAlias && inputs.includes(targetAlias))) {
                    usages.push(`JS Block '${block.title || id}'`);
                }
            }
            // 2. Logic (References in visibleIf) - Simple String Match for now (imperfect but safe)
            if (block.visibleIf) {
                const json = JSON.stringify(block.visibleIf);
                if (json.includes(targetId) || (targetAlias && json.includes(`"${targetAlias}"`))) {
                    usages.push(`Logic in '${block.title || id}'`);
                }
            }
            // 3. Data writes (Create/Update Record)
            if ((block.type === 'create_record' || block.type === 'update_record') && block.config?.fieldMap) {
                const map = block.config.fieldMap as Record<string, string>;
                const values = Object.values(map);
                if (values.includes(targetId) || (targetAlias && values.includes(targetAlias))) {
                    usages.push(`Record Write '${block.title || id}'`);
                }
            }
            // 4. External Sends
            if ((block.type as string) === 'external_send' && block.config?.payloadMappings) {
                const mappings = block.config.payloadMappings as Array<{ key: string, value: string }>;
                // Value can be expression or direct ref
                for (const m of mappings) {
                    if (m.value.includes(targetId) || (targetAlias && m.value.includes(targetAlias))) {
                        usages.push(`External Send '${block.title || id}'`);
                    }
                }
            }
        }
        return usages;
    }
    private calculateOverallSeverity(reasons: ChangeReason[]): Severity {
        if (reasons.some(r => r.severity === "hard_breaking")) {return "hard_breaking";}
        if (reasons.some(r => r.severity === "soft_breaking")) {return "soft_breaking";}
        return "safe";
    }
}

/**
 * Base class for all block runners
 * Provides common utilities and helper methods
 */

import { logger } from "../../logger";

import type {
  BlockContext,
  BlockResult,
  Block,
  IBlockRunner,
  ComparisonOperator,
  WhenCondition,
  AssertExpression,
  ReadTableOperator,
} from "./types";

// Security: limit regex pattern size to prevent ReDoS
const MAX_REGEX_PATTERN_LENGTH = 100;

/**
 * Abstract base class for block runners
 */
export abstract class BaseBlockRunner implements IBlockRunner {
  /**
   * Execute the block - must be implemented by subclasses
   */
  abstract execute(config: any, context: BlockContext, block: Block): Promise<BlockResult>;

  /**
   * Get the block type this runner handles - must be implemented by subclasses
   */
  abstract getBlockType(): string;

  /**
   * Evaluate a when condition
   */
  protected evaluateCondition(condition: WhenCondition, data: Record<string, any>): boolean {
    const actualValue = this.getValueByPath(data, condition.key);
    return this.compareValues(actualValue, condition.op, condition.value);
  }

  /**
   * Evaluate an assertion
   */
  protected evaluateAssertion(assertion: AssertExpression, data: Record<string, any>): boolean {
    const actualValue = this.getValueByPath(data, assertion.key);

    switch (assertion.op) {
      case "is_not_empty":
        return !this.isEmpty(actualValue);

      case "greater_than":
        return this.compareNumeric(actualValue, assertion.value) > 0;

      case "less_than":
        return this.compareNumeric(actualValue, assertion.value) < 0;

      case "equals":
        return this.isEqual(actualValue, assertion.value);

      case "not_equals":
        return !this.isEqual(actualValue, assertion.value);

      case "regex":
        return this.matchesRegex(actualValue, assertion.value);

      default:
        logger.warn(`Unknown assertion operator: ${assertion.op}`);
        return false;
    }
  }

  /**
   * Compare two values using the specified operator
   */
  protected compareValues(
    actualValue: any,
    operator: ComparisonOperator,
    expectedValue?: any
  ): boolean {
    switch (operator) {
      case "equals":
        return this.isEqual(actualValue, expectedValue);

      case "not_equals":
        return !this.isEqual(actualValue, expectedValue);

      case "contains":
        return this.contains(actualValue, expectedValue);

      case "greater_than":
        return this.compareNumeric(actualValue, expectedValue) > 0;

      case "less_than":
        return this.compareNumeric(actualValue, expectedValue) < 0;

      case "is_empty":
        return this.isEmpty(actualValue);

      case "is_not_empty":
        return !this.isEmpty(actualValue);

      default:
        logger.warn(`Unknown comparison operator: ${operator}`);
        return false;
    }
  }

  /**
   * Check if two values are equal
   */
  protected isEqual(actual: any, expected: any): boolean {
    // Handle arrays
    if (Array.isArray(actual) && Array.isArray(expected)) {
      return JSON.stringify([...actual].sort()) === JSON.stringify([...expected].sort());
    }

    // Handle strings (case-insensitive)
    if (typeof actual === "string" && typeof expected === "string") {
      return actual.toLowerCase() === expected.toLowerCase();
    }

    // Handle booleans
    if (typeof actual === "boolean" || typeof expected === "boolean") {
      return Boolean(actual) === Boolean(expected);
    }

    // Standard equality
    return actual === expected;
  }

  /**
   * Check if actual contains expected value
   */
  protected contains(actual: any, expected: any): boolean {
    if (Array.isArray(actual)) {
      return actual.some((item) => this.isEqual(item, expected));
    }

    if (typeof actual === "string" && typeof expected === "string") {
      return actual.toLowerCase().includes(expected.toLowerCase());
    }

    return false;
  }

  /**
   * Compare two values numerically
   */
  protected compareNumeric(actual: any, expected: any): number {
    const numActual = parseFloat(actual);
    const numExpected = parseFloat(expected);

    if (isNaN(numActual) || isNaN(numExpected)) {
      return 0;
    }

    return numActual - numExpected;
  }

  /**
   * Check if value is empty
   */
  protected isEmpty(value: any): boolean {
    if (value === null || value === undefined) {
      return true;
    }

    if (typeof value === "string") {
      return value.trim() === "";
    }

    if (Array.isArray(value)) {
      return value.length === 0;
    }

    if (typeof value === "object") {
      return Object.keys(value).length === 0;
    }

    return false;
  }

  /**
   * Check if value matches regex pattern
   * Security: Enforces max pattern length
   */
  protected matchesRegex(value: any, pattern: any): boolean {
    if (typeof value !== "string") {
      return false;
    }

    try {
      const patternStr = String(pattern);
      if (patternStr.length > MAX_REGEX_PATTERN_LENGTH) {
        logger.warn(`Regex pattern too long (DoS prevention): ${patternStr.slice(0, 50)}...`);
        return false;
      }
      const regex = new RegExp(patternStr);
      return regex.test(value);
    } catch (error) {
      logger.warn(`Invalid regex pattern: ${pattern}`);
      return false;
    }
  }

  /**
   * Get value by path (dot notation support)
   */
  protected getValueByPath(data: Record<string, any>, path: string): any {
    const keys = path.split(".");
    let result = data;

    for (const key of keys) {
      if (result == null) {
        return undefined;
      }
      result = result[key];
    }

    return result;
  }

  /**
   * Set value by path (dot notation support)
   */
  protected setValueByPath(obj: any, path: string, value: any): void {
    const parts = path.split(".");
    let current = obj;

    for (let i = 0; i < parts.length - 1; i++) {
      const part = parts[i];
      if (!(part in current)) {
        current[part] = {};
      }
      current = current[part];
    }

    current[parts[parts.length - 1]] = value;
  }

  /**
   * Redact sensitive PII from logs
   */
  protected redact(data: any): any {
    if (!data) {return data;}
    if (typeof data !== "object") {return data;}

    const sensitiveKeys = [
      "password",
      "token",
      "secret",
      "key",
      "ssn",
      "social",
      "credit",
      "card",
      "cvv",
      "email",
      "phone",
      "address",
      "dob",
      "birth",
    ];

    if (Array.isArray(data)) {
      return data.map((item) => this.redact(item));
    }

    const result: any = { ...data };
    for (const key of Object.keys(result)) {
      const lowerKey = key.toLowerCase();
      if (sensitiveKeys.some((s) => lowerKey.includes(s))) {
        result[key] = "[REDACTED]";
      } else if (typeof result[key] === "object") {
        result[key] = this.redact(result[key]);
      }
    }
    return result;
  }
}

/**
 * Collection Block Runner
 * Handles collection operations (create, update, find, delete records)
 */

import { logger } from "../../logger";
import { recordService } from "../RecordService";

import { BaseBlockRunner } from "./BaseBlockRunner";

import type {
  BlockContext,
  BlockResult,
  Block,
  CreateRecordConfig,
  UpdateRecordConfig,
  FindRecordConfig,
  DeleteRecordConfig,
} from "./types";

export class CollectionBlockRunner extends BaseBlockRunner {
  private recordSvc: typeof recordService;

  constructor(recordSvc?: typeof recordService) {
    super();
    this.recordSvc = recordSvc || recordService;
  }

  getBlockType(): string {
    // This handles multiple types
    return "collection";
  }

  async execute(config: any, context: BlockContext, block: Block): Promise<BlockResult> {
    const blockType = block.type as string;

    switch (blockType) {
      case "create_record":
        return this.executeCreateRecord(config as CreateRecordConfig, context);
      case "update_record":
        return this.executeUpdateRecord(config as UpdateRecordConfig, context);
      case "find_record":
        return this.executeFindRecord(config as FindRecordConfig, context);
      case "delete_record":
        return this.executeDeleteRecord(config as DeleteRecordConfig, context);
      default:
        logger.warn(`Unknown collection block type: ${blockType}`);
        return { success: false, errors: [`Unknown block type: ${blockType}`] };
    }
  }

  /**
   * Execute create_record block
   */
  private async executeCreateRecord(
    config: CreateRecordConfig,
    context: BlockContext
  ): Promise<BlockResult> {
    try {
      const tenantId = await this.getTenantIdFromWorkflow(context.workflowId);
      if (!tenantId) {
        return {
          success: false,
          errors: ["Failed to resolve tenantId from workflow"],
        };
      }

      // Build record data from fieldMap
      const recordData: Record<string, any> = {};
      const { aliasMap } = context;

      for (const [fieldSlug, stepAlias] of Object.entries(config.fieldMap)) {
        const dataKey = aliasMap?.[stepAlias] || stepAlias;
        const value = context.data[dataKey];

        if (value !== undefined && value !== null) {
          recordData[fieldSlug] = value;
        }
      }

      logger.info(
        { tenantId, collectionId: config.collectionId, recordData: this.redact(recordData) },
        "Creating record via block"
      );

      const record = await this.recordSvc.createRecord({
        tenantId,
        collectionId: config.collectionId,
        data: recordData,
      });

      const updates: Record<string, any> = {};
      if (config.outputKey) {
        updates[config.outputKey] = record.id;
      }

      return {
        success: true,
        data: updates,
      };
    } catch (error) {
      logger.error({ error, config }, "Error executing create_record block");
      return {
        success: false,
        errors: [
          `Failed to create record: ${error instanceof Error ? error.message : "unknown error"}`,
        ],
      };
    }
  }

  /**
   * Execute update_record block
   */
  private async executeUpdateRecord(
    config: UpdateRecordConfig,
    context: BlockContext
  ): Promise<BlockResult> {
    try {
      const tenantId = await this.getTenantIdFromWorkflow(context.workflowId);
      if (!tenantId) {
        return {
          success: false,
          errors: ["Failed to resolve tenantId from workflow"],
        };
      }

      const { aliasMap } = context;
      const recordIdKey = aliasMap?.[config.recordIdKey] || config.recordIdKey;
      const recordId = context.data[recordIdKey];

      if (!recordId) {
        return {
          success: false,
          errors: [`Record ID not found in data key: ${config.recordIdKey}`],
        };
      }

      // Build update data from fieldMap
      const updateData: Record<string, any> = {};
      for (const [fieldSlug, stepAlias] of Object.entries(config.fieldMap)) {
        const dataKey = aliasMap?.[stepAlias] || stepAlias;
        const value = context.data[dataKey];

        if (value !== undefined && value !== null) {
          updateData[fieldSlug] = value;
        }
      }

      logger.info(
        {
          tenantId,
          collectionId: config.collectionId,
          recordId,
          updateData: this.redact(updateData),
        },
        "Updating record via block"
      );

      await this.recordSvc.updateRecord(recordId, tenantId, updateData);

      return {
        success: true,
      };
    } catch (error) {
      logger.error({ error, config }, "Error executing update_record block");
      return {
        success: false,
        errors: [
          `Failed to update record: ${error instanceof Error ? error.message : "unknown error"}`,
        ],
      };
    }
  }

  /**
   * Execute find_record block
   */
  private async executeFindRecord(
    config: FindRecordConfig,
    context: BlockContext
  ): Promise<BlockResult> {
    try {
      const tenantId = await this.getTenantIdFromWorkflow(context.workflowId);
      if (!tenantId) {
        return {
          success: false,
          errors: ["Failed to resolve tenantId from workflow"],
        };
      }

      logger.info(
        { tenantId, collectionId: config.collectionId, filters: config.filters },
        "Finding records via block"
      );

      const result = (await this.recordSvc.findByFilters(
        tenantId,
        config.collectionId,
        (config.filters ?? []) as any[],
        { page: 1, limit: config.limit || 1 }
      )) as any;

      if (!result?.records || !Array.isArray(result.records)) {
        return {
          success: false,
          errors: ["Invalid response from record service"],
        };
      }

      if (result.records.length === 0 && config.failIfNotFound) {
        return {
          success: false,
          errors: ["No records found matching the criteria"],
        };
      }

      const updates: Record<string, any> = {};
      updates[config.outputKey] =
        config.limit === 1 ? result.records[0] ?? null : result.records;

      return {
        success: true,
        data: updates,
      };
    } catch (error) {
      logger.error({ error, config }, "Error executing find_record block");
      return {
        success: false,
        errors: [
          `Failed to find records: ${error instanceof Error ? error.message : "unknown error"}`,
        ],
      };
    }
  }

  /**
   * Execute delete_record block
   */
  private async executeDeleteRecord(
    config: DeleteRecordConfig,
    context: BlockContext
  ): Promise<BlockResult> {
    try {
      const tenantId = await this.getTenantIdFromWorkflow(context.workflowId);
      if (!tenantId) {
        return {
          success: false,
          errors: ["Failed to resolve tenantId from workflow"],
        };
      }

      const { aliasMap } = context;
      const recordIdKey = aliasMap?.[config.recordIdKey] || config.recordIdKey;
      const recordId = context.data[recordIdKey];

      if (!recordId) {
        return {
          success: false,
          errors: [`Record ID not found in data key: ${config.recordIdKey}`],
        };
      }

      logger.info(
        { tenantId, collectionId: config.collectionId, recordId },
        "Deleting record via block"
      );

      await this.recordSvc.deleteRecord(tenantId, config.collectionId, recordId);

      return {
        success: true,
      };
    } catch (error) {
      logger.error({ error, config }, "Error executing delete_record block");
      return {
        success: false,
        errors: [
          `Failed to delete record: ${error instanceof Error ? error.message : "unknown error"}`,
        ],
      };
    }
  }

  /**
   * Helper: Get tenantId from workflowId
   */
  private async getTenantIdFromWorkflow(workflowId: string): Promise<string | null> {
    try {
      const { workflowRepository } = await import("../../repositories");
      const workflow = await workflowRepository.findById(workflowId);

      if (!workflow) {
        logger.warn({ workflowId }, "Workflow not found");
        return null;
      }

      // 1. Try Project linkage
      if (workflow.projectId) {
        const { projectRepository } = await import("../../repositories");
        const project = await projectRepository.findById(workflow.projectId);
        if (project) {
          return project.tenantId;
        }
        logger.warn(
          { projectId: workflow.projectId, workflowId },
          "Project not found for workflow, falling back to creator"
        );
      }

      // 2. Fallback: Creator's Tenant
      if (workflow.creatorId) {
        const { userRepository } = await import("../../repositories");
        const creator = await userRepository.findById(workflow.creatorId);

        if (creator?.tenantId) {
          return creator.tenantId;
        }
      }

      logger.warn(
        { workflowId, creatorId: workflow.creatorId },
        "Could not resolve tenantId from project or creator"
      );
      return null;
    } catch (error) {
      logger.error({ error, workflowId }, "Error fetching tenantId from workflow");
      return null;
    }
  }
}

/**
 * Prefill Block Runner
 * Seeds data with static values or query parameters
 */

import { BaseBlockRunner } from "./BaseBlockRunner";

import type { BlockContext, BlockResult, Block, PrefillConfig } from "./types";

export class PrefillBlockRunner extends BaseBlockRunner {
  getBlockType(): string {
    return "prefill";
  }

  async execute(config: PrefillConfig, context: BlockContext, block: Block): Promise<BlockResult> {
    const updates: Record<string, any> = {};
    const overwrite = config.overwrite ?? false;

    if (config.mode === "static" && config.staticMap) {
      for (const [key, value] of Object.entries(config.staticMap)) {
        // Only set if key doesn't exist or overwrite is true
        if (overwrite || context.data[key] === undefined) {
          updates[key] = value;
        }
      }
    } else if (config.mode === "query" && config.queryKeys && context.queryParams) {
      for (const key of config.queryKeys) {
        const value = context.queryParams[key];
        if (value !== undefined) {
          // Only set if key doesn't exist or overwrite is true
          if (overwrite || context.data[key] === undefined) {
            updates[key] = value;
          }
        }
      }
    }

    return {
      success: true,
      data: updates,
    };
  }
}

/**
 * Read Table Block Runner
 * Reads data from a DataVault table and outputs a List
 */

import { and, eq, sql } from "drizzle-orm";

import { datavaultRows } from "@shared/schema";

import { db } from "../../db";
import { logger } from "../../logger";
import { stepValueRepository, datavaultColumnsRepository } from "../../repositories";

import { BaseBlockRunner } from "./BaseBlockRunner";

import type { BlockContext, BlockResult, Block, ReadTableConfig, ReadTableOperator } from "./types";

export class ReadTableBlockRunner extends BaseBlockRunner {
  getBlockType(): string {
    return "read_table";
  }

  async execute(config: any, context: BlockContext, block: Block): Promise<BlockResult> {
    const tableConfig = config as ReadTableConfig;
    try {
      // Check runCondition
      if (tableConfig.runCondition) {
        const shouldRun = this.evaluateCondition(tableConfig.runCondition, context.data);
        if (!shouldRun) {
          logger.info({ phase: context.phase }, "Skipping read_table block due to condition");
          return { success: true };
        }
      }

      // Get tenantId from workflow
      const tenantId = await this.getTenantIdFromWorkflow(context.workflowId);
      if (!tenantId) {
        return {
          success: false,
          errors: ["Failed to resolve tenantId from workflow"],
        };
      }

      // Import services dynamically to avoid circular dependencies
      const { datavaultTablesService } = await import('../DatavaultTablesService');

      // Verify table exists and belongs to tenant
      let table;
      try {
        table = await datavaultTablesService.verifyTenantOwnership(tableConfig.tableId, tenantId);
      } catch (error) {
        return {
          success: false,
          errors: [(error as Error).message]
        };
      }

      // Get table columns for metadata
      const allColumns = await datavaultColumnsRepository.findByTableId(tableConfig.tableId);
      const columnMap = new Map(allColumns.map(c => [c.id, c]));

      // Determine selected columns for output
      let outputColumns = allColumns;
      if (tableConfig.columns && tableConfig.columns.length > 0) {
        outputColumns = allColumns.filter(c => tableConfig.columns!.includes(c.id));
      }

      // Build filter conditions
      let filterConditions: any[] = [];
      if (tableConfig.filters && tableConfig.filters.length > 0) {
        filterConditions = tableConfig.filters.map(filter => {
          const column = columnMap.get(filter.columnId);
          if (!column) {
            logger.warn({ columnId: filter.columnId }, "Filter references unknown column");
            return null;
          }

          // Resolve value from context data if it's a variable reference
          let resolvedValue = filter.value;
          if (typeof filter.value === 'string' && filter.value.startsWith('{{') && filter.value.endsWith('}}')) {
            const variableName = filter.value.slice(2, -2).trim();
            const dataKey = context.aliasMap?.[variableName] || variableName;
            resolvedValue = context.data[dataKey];
          }

          return {
            columnId: filter.columnId,
            column,
            operator: filter.operator,
            value: resolvedValue
          };
        }).filter(Boolean);
      }

      // Query rows with filters
      const limit = tableConfig.limit || 100;
      const rows = await this.queryTableRows({
        tableId: tableConfig.tableId,
        tenantId,
        filters: filterConditions,
        sort: tableConfig.sort,
        limit,
        columns: columnMap
      });

      // Build standardized list variable result
      const listVariable = {
        metadata: {
          source: 'read_table' as const,
          sourceId: tableConfig.tableId,
          tableName: table.name,
          queryParams: {
            filters: tableConfig.filters,
            sort: tableConfig.sort,
            limit: tableConfig.limit,
            selectedColumns: tableConfig.columns
          },
          filteredBy: tableConfig.filters?.map(f => f.columnId),
          sortedBy: tableConfig.sort
        },
        rows: rows.map(row => {
          // Convert internal row structure to column name-accessible object
          const rowData: Record<string, any> = { id: row.id };
          for (const col of outputColumns) {
            rowData[col.id] = row.data?.[col.id] ?? null;
          }
          return rowData;
        }),
        count: rows.length,
        columns: outputColumns.map(c => ({
          id: c.id,
          name: c.name,
          type: c.type
        }))
      };

      // Persist to virtual step if runId is present
      const persistenceWarnings: string[] = [];
      if (context.runId && block.virtualStepId) {
        try {
          await stepValueRepository.upsert({
            runId: context.runId,
            stepId: block.virtualStepId,
            value: listVariable,
          });
          logger.debug({
            blockId: block.id,
            virtualStepId: block.virtualStepId,
            rowCount: listVariable.count
          }, "Persisted read_table block output");
        } catch (error) {
          const errorMsg = error instanceof Error ? error.message : 'Unknown error';
          logger.error({ error, blockId: block.id }, "Failed to persist read_table block output");
          persistenceWarnings.push(`Warning: Failed to persist output to virtual step: ${errorMsg}`);
        }
      }

      return {
        success: true,
        data: {
          [tableConfig.outputKey]: listVariable
        },
        // Include warnings if persistence failed (non-breaking but should be visible)
        ...(persistenceWarnings.length > 0 ? { errors: persistenceWarnings } : {})
      };

    } catch (error) {
      logger.error({ error, config: tableConfig }, "Read table block failed");
      return {
        success: false,
        errors: [`Read table failed: ${error instanceof Error ? error.message : 'unknown error'}`]
      };
    }
  }

  /**
   * Query table rows with filters and sorting
   * Internal helper method for read_table block
   */
  private async queryTableRows(params: {
    tableId: string;
    tenantId: string;
    filters: Array<{
      columnId: string;
      column: any;
      operator: ReadTableOperator;
      value: any;
    }>;
    sort?: { columnId: string; direction: "asc" | "desc" };
    limit: number;
    columns: Map<string, any>;
  }): Promise<any[]> {
    // Build WHERE conditions
    const whereConditions = [eq(datavaultRows.tableId, params.tableId)];

    for (const filter of params.filters) {
      // SECURITY FIX: Validate columnId to prevent SQL injection
      if (!/^[a-zA-Z0-9_-]+$/.test(filter.columnId)) {
        logger.warn({ columnId: filter.columnId }, 'Invalid columnId detected - skipping filter');
        continue;
      }

      const columnPath = `data->>'${filter.columnId}'`;

      switch (filter.operator) {
        case 'equals':
          if (filter.value !== null && filter.value !== undefined) {
            whereConditions.push(sql`${sql.raw(columnPath)} = ${filter.value}`);
          }
          break;

        case 'not_equals':
          if (filter.value !== null && filter.value !== undefined) {
            whereConditions.push(sql`${sql.raw(columnPath)} != ${filter.value}`);
          }
          break;

        case 'contains':
          if (filter.value) {
            whereConditions.push(sql`${sql.raw(columnPath)} LIKE ${`%${filter.value}%`}`);
          }
          break;

        case 'starts_with':
          if (filter.value) {
            whereConditions.push(sql`${sql.raw(columnPath)} LIKE ${`${filter.value}%`}`);
          }
          break;

        case 'ends_with':
          if (filter.value) {
            whereConditions.push(sql`${sql.raw(columnPath)} LIKE ${`%${filter.value}`}`);
          }
          break;

        case 'greater_than':
          if (filter.column.type === 'number') {
            whereConditions.push(sql`(${sql.raw(columnPath)})::numeric > ${filter.value}`);
          } else if (filter.column.type === 'date' || filter.column.type === 'datetime') {
            whereConditions.push(sql`${sql.raw(columnPath)} > ${filter.value}`);
          }
          break;

        case 'less_than':
          if (filter.column.type === 'number') {
            whereConditions.push(sql`(${sql.raw(columnPath)})::numeric < ${filter.value}`);
          } else if (filter.column.type === 'date' || filter.column.type === 'datetime') {
            whereConditions.push(sql`${sql.raw(columnPath)} < ${filter.value}`);
          }
          break;

        case 'is_empty':
          whereConditions.push(sql`(${sql.raw(columnPath)} IS NULL OR ${sql.raw(columnPath)} = '')`);
          break;

        case 'is_not_empty':
          whereConditions.push(sql`(${sql.raw(columnPath)} IS NOT NULL AND ${sql.raw(columnPath)} != '')`);
          break;

        case 'in':
          if (Array.isArray(filter.value) && filter.value.length > 0) {
            // SECURITY FIX: Use parameterized array
            const values = filter.value.map(v => String(v));
            whereConditions.push(sql`${sql.raw(columnPath)} = ANY(${values})`);
          }
          break;
      }
    }

    // Build query
    let query = db
      .select()
      .from(datavaultRows)
      .where(and(...whereConditions))
      .limit(params.limit);

    // Add sorting
    if (params.sort) {
      const sortColumn = params.columns.get(params.sort.columnId);
      if (sortColumn) {
        // SECURITY FIX: Validate columnId
        if (!/^[a-zA-Z0-9_-]+$/.test(params.sort.columnId)) {
          logger.warn({ columnId: params.sort.columnId }, 'Invalid sort columnId detected - skipping sort');
        } else {
          const columnPath = `data->>'${params.sort.columnId}'`;
          if (params.sort.direction === 'asc') {
            query = (query as any).orderBy(sql`${sql.raw(columnPath)} ASC`);
          } else {
            query = (query as any).orderBy(sql`${sql.raw(columnPath)} DESC`);
          }
        }
      }
    }

    return query;
  }

  /**
   * Helper: Get tenantId from workflowId
   */
  private async getTenantIdFromWorkflow(workflowId: string): Promise<string | null> {
    try {
      const { workflowRepository } = await import("../../repositories");
      const workflow = await workflowRepository.findById(workflowId);

      if (!workflow) {
        logger.warn({ workflowId }, "Workflow not found");
        return null;
      }

      // 1. Try Project linkage
      if (workflow.projectId) {
        const { projectRepository } = await import("../../repositories");
        const project = await projectRepository.findById(workflow.projectId);
        if (project) {
          return project.tenantId;
        }
        logger.warn(
          { projectId: workflow.projectId, workflowId },
          "Project not found for workflow, falling back to creator"
        );
      }

      // 2. Fallback: Creator's Tenant
      if (workflow.creatorId) {
        const { userRepository } = await import("../../repositories");
        const creator = await userRepository.findById(workflow.creatorId);

        if (creator?.tenantId) {
          return creator.tenantId;
        }
      }

      logger.warn(
        { workflowId, creatorId: workflow.creatorId },
        "Could not resolve tenantId from project or creator"
      );
      return null;
    } catch (error) {
      logger.error({ error, workflowId }, "Error fetching tenantId from workflow");
      return null;
    }
  }
}

