/**
 * Create a new connection
 */
export async function createConnection(
  input: CreateConnectionInput
): Promise<Connection> {
  // TYPE SAFETY FIX: Validate connection type before creating
  validateConnectionType(input.type);

  // Check for name uniqueness
  const existing = await getConnectionByName(input.projectId, input.name);
  if (existing) {
    throw new Error(`Connection with name "${input.name}" already exists in this project`);
  }

  // Get tenantId from project
  const project = await db
    .select({ tenantId: projects.tenantId })
    .from(projects)
    .where(eq(projects.id, input.projectId))
    .limit(1);

  if (project.length === 0) {
    throw new Error(`Project not found: ${input.projectId}`);
  }

  const tenantId = project[0].tenantId;

  // TYPE SAFETY FIX: Sanitize headers before storing
  const sanitizedHeaders = sanitizeHeaders(input.defaultHeaders);

  // Insert connection
  const result = await db
    .insert(connections)
    .values({
      tenantId: tenantId!,
      projectId: input.projectId,
      name: input.name,
      type: input.type,
      baseUrl: input.baseUrl,
      authConfig: input.authConfig ?? {},
      secretRefs: input.secretRefs ?? {},
      defaultHeaders: sanitizedHeaders,
      timeoutMs: input.timeoutMs ?? 8000,
      retries: input.retries ?? 2,
      backoffMs: input.backoffMs ?? 250,
      enabled: true,
    })
    .returning();

  return getConnection(input.projectId, result[0].id) as Promise<Connection>;
}

/**
 * Update a connection
 */
export async function updateConnection(
  projectId: string,
  connectionId: string,
  input: UpdateConnectionInput
): Promise<Connection> {
  // Check if connection exists
  const existing = await getConnection(projectId, connectionId);
  if (!existing) {
    throw new Error(`Connection not found: ${connectionId}`);
  }

  // Check name uniqueness if name is being changed
  if (input.name && input.name !== existing.name) {
    const nameConflict = await getConnectionByName(projectId, input.name);
    if (nameConflict) {
      throw new Error(`Connection with name "${input.name}" already exists in this project`);
    }
  }

  // TYPE SAFETY FIX: Sanitize headers before updating
  const sanitizedHeaders = input.defaultHeaders ? sanitizeHeaders(input.defaultHeaders) : undefined;

  // Update connection
  await db
    .update(connections)
    .set({
      name: input.name,
      baseUrl: input.baseUrl,
      authConfig: input.authConfig ?? undefined,
      secretRefs: input.secretRefs ?? undefined,
      defaultHeaders: sanitizedHeaders,
      timeoutMs: input.timeoutMs,
      retries: input.retries,
      backoffMs: input.backoffMs,
      enabled: input.enabled,
      updatedAt: new Date(),
    })
    .where(
      and(
        eq(connections.id, connectionId),
        eq(connections.projectId, projectId)
      )
    );

  return getConnection(projectId, connectionId) as Promise<Connection>;
}

/**
 * Delete a connection
 */
export async function deleteConnection(
  projectId: string,
  connectionId: string
): Promise<void> {
  await db
    .delete(connections)
    .where(
      and(
        eq(connections.id, connectionId),
        eq(connections.projectId, projectId)
      )
    );
}

/**
 * Resolve a connection with decrypted secrets
 * INTERNAL USE ONLY - never expose via API
 */
export async function resolveConnection(
  projectId: string,
  connectionId: string
): Promise<ResolvedConnection> {
  const connection = await getConnection(projectId, connectionId);
  if (!connection) {
    throw new Error(`Connection not found: ${connectionId}`);
  }

  if (!connection.enabled) {
    throw new Error(`Connection is disabled: ${connection.name}`);
  }

  // Decrypt all referenced secrets
  const secrets: Record<string, string> = {};
  for (const [refName, secretKey] of Object.entries(connection.secretRefs)) {
    const secretValue = await getSecretValue(projectId, secretKey);
    secrets[refName] = secretValue ?? '';
  }

  // Decrypt OAuth2 access token if available
  let accessToken: string | undefined;
  if (connection.oauthState?.accessToken) {
    try {
      accessToken = decrypt(connection.oauthState.accessToken);

      // Check if token is expired
      const now = Date.now();
      if (connection.oauthState.expiresAt && now >= connection.oauthState.expiresAt) {
        // Token expired - try to refresh if refresh token available
        if (connection.oauthState.refreshToken && connection.type === 'oauth2_3leg') {
          accessToken = await refreshConnectionToken(projectId, connectionId);
        } else {
          throw new Error('OAuth2 access token expired and cannot be refreshed');
        }
      }
    } catch (error) {
      logger.error({ error, connectionId }, 'Failed to decrypt OAuth2 access token');
      throw new Error('Failed to decrypt OAuth2 access token');
    }
  }

  return {
    connection,
    secrets,
    accessToken,
  };
}

/**
 * Test a connection by making a simple request
 */
export async function testConnection(
  projectId: string,
  connectionId: string
): Promise<{ success: boolean; statusCode?: number; message: string; responseTime?: number }> {
  const resolved = await resolveConnection(projectId, connectionId);
  const connection = resolved.connection;

  if (!connection.baseUrl) {
    throw new Error('Connection has no baseUrl to test');
  }

  const startTime = Date.now();

  try {
    // Build headers
    const headers: Record<string, string> = {
      ...connection.defaultHeaders,
    };

    // Add auth headers based on connection type
    if (connection.type === 'api_key') {
      const apiKeyLocation = connection.authConfig.apiKeyLocation || 'header';
      const apiKeyName = connection.authConfig.apiKeyName || 'X-API-Key';
      const apiKey = resolved.secrets[connection.authConfig.apiKeyRef || 'apiKey'];

      if (apiKeyLocation === 'header') {
        headers[apiKeyName] = apiKey;
      }
    } else if (connection.type === 'bearer') {
      const token = resolved.secrets[connection.authConfig.tokenRef || 'token'];
      headers['Authorization'] = `Bearer ${token}`;
    } else if (connection.type === 'oauth2_client_credentials' || connection.type === 'oauth2_3leg') {
      if (resolved.accessToken) {
        headers['Authorization'] = `Bearer ${resolved.accessToken}`;
      }
    }

    // Make test request
    const response = await fetch(connection.baseUrl, {
      method: 'GET',
      headers,
      signal: AbortSignal.timeout(connection.timeoutMs),
    });

    const responseTime = Date.now() - startTime;

    // Update lastTestedAt
    await db
      .update(connections)
      .set({ lastTestedAt: new Date() })
      .where(eq(connections.id, connectionId));

    return {
      success: response.ok,
      statusCode: response.status,
      message: response.ok ? 'Connection test successful' : `HTTP ${response.status}: ${response.statusText}`,
      responseTime,
    };
  } catch (error) {
    const responseTime = Date.now() - startTime;
    return {
      success: false,
      message: `Connection test failed: ${(error as Error).message}`,
      responseTime,
    };
  }
}

/**
 * Initiate OAuth2 3-legged authorization flow
 */
export async function initiateOAuth2Flow(
  projectId: string,
  connectionId: string,
  baseUrl: string
): Promise<{ authorizationUrl: string; state: string }> {
  const connection = await getConnection(projectId, connectionId);
  if (!connection) {
    throw new Error(`Connection not found: ${connectionId}`);
  }

  if (connection.type !== 'oauth2_3leg') {
    throw new Error(`Connection type must be oauth2_3leg, got: ${connection.type}`);
  }

  // Resolve secrets for client ID and secret
  const clientId = (await getSecretValue(projectId, connection.authConfig.clientIdRef)) ?? '';
  const clientSecret = (await getSecretValue(projectId, connection.authConfig.clientSecretRef)) ?? '';

  const config: OAuth2ThreeLegConfig = {
    authUrl: connection.authConfig.authUrl,
    tokenUrl: connection.authConfig.tokenUrl,
    clientId,
    clientSecret,
    redirectUri: `${baseUrl}/api/connections/oauth/callback`,
    scope: connection.authConfig.scope,
    tenantId: connection.tenantId,
    projectId: connection.projectId,
  };

  return generateOAuth2AuthorizationUrl(config, connectionId);
}

/**
 * Handle OAuth2 callback and store tokens
 */
export async function handleOAuth2Callback(
  projectId: string,
  connectionId: string,
  code: string
): Promise<Connection> {
  const connection = await getConnection(projectId, connectionId);
  if (!connection) {
    throw new Error(`Connection not found: ${connectionId}`);
  }

  if (connection.type !== 'oauth2_3leg') {
    throw new Error(`Connection type must be oauth2_3leg, got: ${connection.type}`);
  }

  // Resolve secrets for client ID and secret
  const clientId = (await getSecretValue(projectId, connection.authConfig.clientIdRef)) ?? '';
  const clientSecret = (await getSecretValue(projectId, connection.authConfig.clientSecretRef)) ?? '';

  const config: OAuth2ThreeLegConfig = {
    authUrl: connection.authConfig.authUrl,
    tokenUrl: connection.authConfig.tokenUrl,
    clientId,
    clientSecret,
    redirectUri: connection.authConfig.redirectUri,
    scope: connection.authConfig.scope,
    tenantId: connection.tenantId,
    projectId: connection.projectId,
  };

  // Exchange code for tokens
  const tokenResponse: OAuth2ThreeLegTokenResponse = await exchangeOAuth2Code(config, code);

  // Encrypt and store tokens
  const oauthState: OAuth2State = {
    accessToken: encrypt(tokenResponse.access_token),
    refreshToken: tokenResponse.refresh_token ? encrypt(tokenResponse.refresh_token) : undefined,
    expiresAt: Date.now() + (tokenResponse.expires_in * 1000),
    scope: tokenResponse.scope,
    tokenType: tokenResponse.token_type,
  };

  // Update connection with OAuth state
  await db
    .update(connections)
    .set({
      oauthState,
      updatedAt: new Date(),
    })
    .where(eq(connections.id, connectionId));

  return getConnection(projectId, connectionId) as Promise<Connection>;
}

/**
 * Refresh OAuth2 access token
 * Returns the new decrypted access token
 */
export async function refreshConnectionToken(
  projectId: string,
  connectionId: string
): Promise<string> {
  const connection = await getConnection(projectId, connectionId);
  if (!connection) {
    throw new Error(`Connection not found: ${connectionId}`);
  }

  if (connection.type !== 'oauth2_3leg') {
    throw new Error(`Connection type must be oauth2_3leg, got: ${connection.type}`);
  }

  if (!connection.oauthState?.refreshToken) {
    throw new Error('No refresh token available');
  }

  // Resolve secrets for client ID and secret
  const clientId = (await getSecretValue(projectId, connection.authConfig.clientIdRef)) ?? '';
  const clientSecret = (await getSecretValue(projectId, connection.authConfig.clientSecretRef)) ?? '';

  const config: OAuth2ThreeLegConfig = {
    authUrl: connection.authConfig.authUrl,
    tokenUrl: connection.authConfig.tokenUrl,
    clientId,
    clientSecret,
    redirectUri: connection.authConfig.redirectUri,
    scope: connection.authConfig.scope,
    tenantId: connection.tenantId,
    projectId: connection.projectId,
  };

  // Refresh token
  const tokenResponse = await refreshOAuth2Token(config, connection.oauthState.refreshToken);

  // Encrypt and update tokens
  const oauthState: OAuth2State = {
    accessToken: encrypt(tokenResponse.access_token),
    refreshToken: tokenResponse.refresh_token ? encrypt(tokenResponse.refresh_token) : connection.oauthState.refreshToken,
    expiresAt: Date.now() + (tokenResponse.expires_in * 1000),
    scope: tokenResponse.scope,
    tokenType: tokenResponse.token_type,
  };

  // Update connection
  await db
    .update(connections)
    .set({
      oauthState,
      updatedAt: new Date(),
    })
    .where(eq(connections.id, connectionId));

  // Return decrypted access token
  return tokenResponse.access_token;
}

/**
 * Get connection status (for UI display)
 */
export async function getConnectionStatus(
  projectId: string,
  connectionId: string
): Promise<ConnectionStatus> {
  const connection = await getConnection(projectId, connectionId);
  if (!connection) {
    throw new Error(`Connection not found: ${connectionId}`);
  }

  const status: ConnectionStatus = {
    id: connection.id,
    name: connection.name,
    type: connection.type,
    enabled: connection.enabled,
    lastTestedAt: connection.lastTestedAt,
    lastUsedAt: connection.lastUsedAt,
  };

  // Add OAuth2 token status if applicable
  if (connection.oauthState) {
    status.oauthTokenExpiry = connection.oauthState.expiresAt != null
      ? new Date(connection.oauthState.expiresAt)
      : undefined;
    status.oauthTokenValid = connection.oauthState.expiresAt != null
      ? Date.now() < connection.oauthState.expiresAt
      : false;
  }

  return status;
}

/**
 * Update last used timestamp
 */
export async function markConnectionUsed(connectionId: string): Promise<void> {
  await db
    .update(connections)
    .set({ lastUsedAt: new Date() })
    .where(eq(connections.id, connectionId));
}

/**
 * DOCX Sanitizer
 *
 * Security hardening for uploaded DOCX templates.
 * Removes potentially dangerous content:
 * - VBA macros
 * - ActiveX controls
 * - External references
 * - Embedded files
 * - Custom XML with external refs
 *
 * Features:
 * - Safe template processing
 * - Detailed sanitization report
 * - Preserve template functionality
 * - Minimal file size increase
 *
 * Usage:
 * ```typescript
 * const sanitizer = new DocxSanitizer();
 * const result = await sanitizer.sanitize(docxBuffer);
 *
 * if (result.sanitized) {
 *   console.log('Removed:', result.removedItems);
 *   await saveFile(result.buffer);
 * }
 * ```
 */

import JSZip from 'jszip';

import { logger } from '../../logger';

// ============================================================================
// TYPES
// ============================================================================

export interface SanitizationResult {
  /** Whether any sanitization was performed */
  sanitized: boolean;

  /** Cleaned buffer */
  buffer: Buffer;

  /** Items that were removed */
  removedItems: string[];

  /** Warnings about potentially dangerous content */
  warnings: string[];

  /** Size comparison */
  sizeChange: {
    before: number;
    after: number;
    delta: number;
    percentage: number;
  };
}

// ============================================================================
// SANITIZER CLASS
// ============================================================================

export class DocxSanitizer {
  // Dangerous files to remove
  private readonly DANGEROUS_FILES = [
    'word/vbaProject.bin', // VBA macros
    'word/activeX/', // ActiveX controls (directory)
    'word/embeddings/', // Embedded files (directory)
    'customXml/', // Custom XML with potential external refs
  ];

  // External relationship types to remove
  private readonly DANGEROUS_REL_TYPES = [
    'http://schemas.openxmlformats.org/officeDocument/2006/relationships/oleObject',
    'http://schemas.openxmlformats.org/officeDocument/2006/relationships/package',
    'http://schemas.microsoft.com/office/2006/relationships/vbaProject',
    'http://schemas.openxmlformats.org/officeDocument/2006/relationships/frame',
  ];

  /**
   * Sanitize a DOCX buffer
   */
  async sanitize(buffer: Buffer): Promise<SanitizationResult> {
    logger.info('Sanitizing DOCX template');

    const originalSize = buffer.length;
    const removedItems: string[] = [];
    const warnings: string[] = [];

    try {
      // Load DOCX as ZIP
      const zip = await JSZip.loadAsync(buffer);

      // Step 1: Remove dangerous files
      for (const dangerousPath of this.DANGEROUS_FILES) {
        if (dangerousPath.endsWith('/')) {
          // Remove directory
          const removed = this.removeDirectory(zip, dangerousPath);
          if (removed.length > 0) {
            removedItems.push(...removed);
            logger.warn({ path: dangerousPath, count: removed.length }, 'Removed dangerous directory');
          }
        } else {
          // Remove single file
          const file = zip.file(dangerousPath);
          if (file) {
            zip.remove(dangerousPath);
            removedItems.push(dangerousPath);
            logger.warn({ path: dangerousPath }, 'Removed dangerous file');
          }
        }
      }

      // Step 2: Sanitize relationships (remove external refs)
      const relsFiles = Object.keys(zip.files).filter((path) =>
        path.endsWith('.rels')
      );

      for (const relsPath of relsFiles) {
        const file = zip.file(relsPath);
        if (file) {
          const content = await file.async('string');
          const { sanitized, content: sanitizedContent, removed } =
            await this.sanitizeRelationships(content);

          if (sanitized) {
            zip.file(relsPath, sanitizedContent);
            removedItems.push(...removed.map((r) => `${relsPath}:${r}`));
            logger.warn({ path: relsPath, removed }, 'Sanitized relationships');
          }
        }
      }

      // Step 3: Check for suspicious content in document.xml
      const docXml = zip.file('word/document.xml');
      if (docXml) {
        const content = await docXml.async('string');
        const suspiciousPatterns = this.detectSuspiciousPatterns(content);

        if (suspiciousPatterns.length > 0) {
          warnings.push(...suspiciousPatterns);
          logger.warn({ patterns: suspiciousPatterns }, 'Detected suspicious patterns in document');
        }
      }

      // Step 4: Remove custom properties with external refs
      const customProps = zip.file('docProps/custom.xml');
      if (customProps) {
        const content = await customProps.async('string');

        if (this.hasExternalReferences(content)) {
          zip.remove('docProps/custom.xml');
          removedItems.push('docProps/custom.xml');
          warnings.push('Removed custom properties with external references');
        }
      }

      // Generate sanitized buffer
      const sanitizedBuffer = await zip.generateAsync({
        type: 'nodebuffer',
        compression: 'DEFLATE',
        compressionOptions: { level: 9 },
      });

      const newSize = sanitizedBuffer.length;
      const delta = newSize - originalSize;
      const percentage = originalSize > 0 ? (delta / originalSize) * 100 : 0;

      logger.info(
        {
          originalSize,
          newSize,
          delta,
          removedItems: removedItems.length,
          warnings: warnings.length,
        },
        'DOCX sanitization complete'
      );

      return {
        sanitized: removedItems.length > 0 || warnings.length > 0,
        buffer: sanitizedBuffer,
        removedItems,
        warnings,
        sizeChange: {
          before: originalSize,
          after: newSize,
          delta,
          percentage: Math.round(percentage * 100) / 100,
        },
      };
    } catch (error: any) {
      logger.error({ error }, 'DOCX sanitization failed');
      throw new Error(`Failed to sanitize DOCX: ${error.message}`);
    }
  }

  /**
   * Remove a directory from ZIP
   */
  private removeDirectory(zip: JSZip, dirPath: string): string[] {
    const removed: string[] = [];

    Object.keys(zip.files).forEach((path) => {
      if (path.startsWith(dirPath)) {
        zip.remove(path);
        removed.push(path);
      }
    });

    return removed;
  }

  /**
   * Sanitize relationships XML
   */
  private async sanitizeRelationships(
    content: string
  ): Promise<{ sanitized: boolean; content: string; removed: string[] }> {
    let sanitized = false;
    const removed: string[] = [];

    // Parse XML and remove dangerous relationship types
    for (const dangerousType of this.DANGEROUS_REL_TYPES) {
      if (content.includes(dangerousType)) {
        // Remove relationship elements with this type
        const regex = new RegExp(
          `<Relationship[^>]*Type="${dangerousType.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}"[^>]*/>`,
          'g'
        );

        const matches = content.match(regex);
        if (matches) {
          content = content.replace(regex, '');
          sanitized = true;
          removed.push(...matches.map((m) => dangerousType));
        }
      }
    }

    // Remove external targets (TargetMode="External")
    if (content.includes('TargetMode="External"')) {
      // Keep only safe external links (http/https to known domains)
      const externalRegex = /<Relationship([^>]*)TargetMode="External"([^>]*)\/>/g;
      const matches = Array.from(content.matchAll(externalRegex));

      for (const match of matches) {
        const rel = match[0];
        const targetMatch = rel.match(/Target="([^"]*)"/);

        if (targetMatch) {
          const target = targetMatch[1];

          // Only allow http/https links
          if (!target.startsWith('http://') && !target.startsWith('https://')) {
            content = content.replace(rel, '');
            sanitized = true;
            removed.push(`External:${target}`);
          }
        }
      }
    }

    return { sanitized, content, removed };
  }

  /**
   * Detect suspicious patterns in document XML
   */
  private detectSuspiciousPatterns(content: string): string[] {
    const warnings: string[] = [];

    // Check for scripting
    if (content.includes('<w:jc w:val="script"') || content.includes('javascript:')) {
      warnings.push('Document contains potential script references');
    }

    // Check for form controls (can be used for phishing)
    if (content.includes('<w:fldChar') && content.includes('MACROBUTTON')) {
      warnings.push('Document contains macro button fields');
    }

    // Check for external data references
    if (content.includes('w:dataBinding') || content.includes('w:sdtContent')) {
      warnings.push('Document contains data binding or structured content');
    }

    return warnings;
  }

  /**
   * Check if content has external references
   */
  private hasExternalReferences(content: string): boolean {
    // Check for external schemas or namespaces
    if (content.includes('xmlns:') && content.includes('http://')) {
      // This is normal for Office documents, but check for suspicious ones
      const suspiciousPatterns = [
        'vt:lpwstr',
        'vt:variant',
        'op:string',
      ];

      for (const pattern of suspiciousPatterns) {
        if (content.includes(pattern)) {
          return true;
        }
      }
    }

    return false;
  }

  /**
   * Quick check if DOCX needs sanitization (without processing)
   */
  async needsSanitization(buffer: Buffer): Promise<{
    needed: boolean;
    reasons: string[];
  }> {
    const reasons: string[] = [];

    try {
      const zip = await JSZip.loadAsync(buffer);

      // Check for dangerous files
      for (const dangerousPath of this.DANGEROUS_FILES) {
        if (dangerousPath.endsWith('/')) {
          const files = Object.keys(zip.files).filter((p) => p.startsWith(dangerousPath));
          if (files.length > 0) {
            reasons.push(`Contains ${dangerousPath} (${files.length} files)`);
          }
        } else {
          if (zip.file(dangerousPath)) {
            reasons.push(`Contains ${dangerousPath}`);
          }
        }
      }

      // Check relationships
      const relsFile = zip.file('word/_rels/document.xml.rels');
      if (relsFile) {
        const content = await relsFile.async('string');

        for (const dangerousType of this.DANGEROUS_REL_TYPES) {
          if (content.includes(dangerousType)) {
            reasons.push(`Contains relationship type: ${dangerousType}`);
          }
        }
      }

      return {
        needed: reasons.length > 0,
        reasons,
      };
    } catch (error: any) {
      logger.error({ error }, 'Failed to check if sanitization needed');
      return { needed: false, reasons: [] };
    }
  }
}

// Singleton instance
export const docxSanitizer = new DocxSanitizer();

/**
 * Enhanced Document Engine
 *
 * Extends the existing DocumentEngine with Final Block capabilities:
 * - Variable normalization (flatten nested, convert arrays)
 * - Field mapping (map workflow variables to document fields)
 * - Conditional document generation
 * - Multi-document rendering
 *
 * This is a THIN WRAPPER that preserves all existing functionality while
 * adding new capabilities needed for Final Block integration.
 *
 * @version 1.0.0 - Final Block Extension (Prompt 10)
 * @date December 6, 2025
 */

import {
  DocumentGenerationError,
  createNormalizationError,
  createMappingError,
  createRenderError,
  wrapAsDocumentGenerationError,
  isDocumentGenerationError
} from '../../errors/DocumentGenerationError.js';
import { createLogger } from '../../logger.js';
import { templateAnalytics } from '../TemplateAnalyticsService.js';

import { DocumentEngine } from './DocumentEngine.js';
import { applyMapping, type DocumentMapping, type MappingResult } from './MappingInterpreter.js';
import { normalizeVariables, type NormalizedData, type NormalizationOptions } from './VariableNormalizer.js';

import type { DocumentGenerationOptions, DocumentGenerationResult } from './DocumentEngine.js';
import type { FinalBlockConfig, LogicExpression } from '../../../shared/types/stepConfigs.js';

const logger = createLogger({ module: 'enhanced-doc-engine' });

// ============================================================================
// TYPES
// ============================================================================

/**
 * Enhanced generation options (with normalization and mapping)
 */
export interface EnhancedGenerationOptions extends Omit<DocumentGenerationOptions, 'data'> {
  /** Raw step values (will be normalized) */
  rawData: Record<string, unknown>;

  /** Optional field mapping */
  mapping?: DocumentMapping;

  /** Normalization options */
  normalizationOptions?: NormalizationOptions;

  /** Whether to apply normalization (default: true) */
  normalize?: boolean;

  /** PDF conversion strategy */
  pdfStrategy?: 'puppeteer' | 'libreoffice';
}

/**
 * Enhanced generation result (with mapping metadata)
 */

export interface EnhancedGenerationResult extends DocumentGenerationResult {
  /** Normalized data that was used */
  normalizedData: NormalizedData;

  /** Mapping result (if mapping was applied) */
  mappingResult?: MappingResult;

  /** Document alias (for Final Block) */
  alias?: string;
}

/**
 * Single document configuration for Final Block
 */
export interface FinalBlockDocument {
  /** Document ID (reference to template) */
  documentId: string;

  /** Template file path */
  templatePath: string;

  /** Document alias */
  alias: string;

  /** Optional field mapping */
  mapping?: DocumentMapping;

  /** Optional conditional logic */
  conditions?: LogicExpression | null;
}

/**
 * Final Block rendering options
 */
export interface FinalBlockRenderOptions {
  /** Documents to generate */
  documents: FinalBlockDocument[];

  /** Step values from workflow run */
  stepValues: Record<string, unknown>;

  /** Output directory */
  outputDir?: string;

  /** Whether to convert to PDF */
  toPdf?: boolean;

  /** PDF conversion strategy */
  pdfStrategy?: 'puppeteer' | 'libreoffice';

  /** Normalization options */
  normalizationOptions?: NormalizationOptions;
}

/**
 * Final Block rendering result
 */
export interface FinalBlockRenderResult {
  /** Successfully generated documents */
  documents: EnhancedGenerationResult[];

  /** Documents that were skipped (conditions = false) */
  skipped: Array<{
    alias: string;
    reason: string;
  }>;

  /** Documents that failed to generate */
  failed: Array<{
    alias: string;
    error: string;
    phase?: string;
    recoverable?: boolean;
    suggestion?: string;
    details?: unknown;
  }>;

  /** Total number of documents attempted */
  totalAttempted: number;

  /** Total number of documents generated */
  totalGenerated: number;
}

// ============================================================================
// ENHANCED DOCUMENT ENGINE CLASS
// ============================================================================

/**
 * Enhanced Document Engine
 *
 * Wraps existing DocumentEngine with Final Block capabilities.
 * Preserves all existing functionality - this is ADDITIVE, not a replacement.
 */
export class EnhancedDocumentEngine {
  private engine: DocumentEngine;

  constructor() {
    this.engine = new DocumentEngine();
  }

  /**
   * Generate document with normalization and mapping
   *
   * This method extends the base DocumentEngine.generate() with:
   * - Automatic variable normalization
   * - Field mapping application
   * - Metadata tracking
   *
   * @param options - Enhanced generation options
   * @returns Enhanced generation result
   */
  async generateWithMapping(
    options: EnhancedGenerationOptions
  ): Promise<EnhancedGenerationResult> {
    const {
      rawData,
      mapping,
      normalizationOptions = {},
      normalize = true,
      ...baseOptions
    } = options;

    logger.info({
      outputName: baseOptions.outputName,
      hasMapping: !!mapping,
      normalize,
    }, 'Generating document with mapping');

    try {
      // Step 1: Normalize variables
      let normalizedData: NormalizedData;
      try {
        normalizedData = normalize
          ? normalizeVariables(rawData, normalizationOptions)
          : (rawData as NormalizedData);

        logger.debug({
          originalKeys: Object.keys(rawData).length,
          normalizedKeys: Object.keys(normalizedData).length,
        }, 'Variables normalized');
      } catch (error: unknown) {
        throw createNormalizationError(
          baseOptions.outputName || 'unknown',
          error as any,
          rawData
        );
      }

      // Step 2: Apply mapping (if provided)
      let mappingResult: MappingResult | undefined;
      let finalData: NormalizedData = normalizedData;

      if (mapping) {
        try {
          mappingResult = applyMapping(normalizedData, mapping);
          finalData = mappingResult.data;

          logger.debug({
            mapped: mappingResult.mapped.length,
            missing: mappingResult.missing.length,
            unused: mappingResult.unused.length,
          }, 'Mapping applied');

          // Log warnings for missing source variables
          if (mappingResult.missing.length > 0) {
            logger.warn({
              missing: mappingResult.missing,
            }, 'Mapping references missing variables');
          }
        } catch (error: unknown) {
          throw createMappingError(
            baseOptions.templatePath,
            baseOptions.outputName || 'unknown',
            error as any,
            mapping
          );
        }
      }

      // Step 3: Generate document using base engine
      let result: DocumentGenerationResult;
      const startTime = Date.now();

      try {
        result = await this.engine.generate({
          ...baseOptions,
          data: finalData,
        });

        const duration = Date.now() - startTime;

        logger.info({
          outputName: baseOptions.outputName,
          docxPath: result.docxPath,
          pdfPath: result.pdfPath,
          durationMs: duration,
        }, 'Document generated successfully');

        // Track successful generation (if templateId is available)
        if (baseOptions.templatePath && !baseOptions.templatePath.startsWith('preview-')) {
          templateAnalytics.trackGeneration(
            baseOptions.templatePath,
            'success',
            duration,
            undefined,
            baseOptions.outputName
          ).catch((err) => {
            logger.warn({ error: err }, 'Failed to track generation metric');
          });
        }
      } catch (error: unknown) {
        const duration = Date.now() - startTime;

        // Track failed generation
        if (baseOptions.templatePath && !baseOptions.templatePath.startsWith('preview-')) {
          templateAnalytics.trackGeneration(
            baseOptions.templatePath,
            'failure',
            duration,
            (error as Error).message,
            baseOptions.outputName
          ).catch((err) => {
            logger.warn({ error: err }, 'Failed to track generation metric');
          });
        }

        throw createRenderError(
          baseOptions.templatePath,
          baseOptions.outputName || 'unknown',
          error as any,
          finalData
        );
      }

      // Step 4: Return enhanced result
      return {
        ...result,
        normalizedData,
        mappingResult,
      };
    } catch (error: unknown) {
      // Wrap non-DocumentGenerationError errors
      if (!isDocumentGenerationError(error)) {
        throw wrapAsDocumentGenerationError(error, {
          phase: 'unknown',
          templateId: baseOptions.templatePath,
          runId: baseOptions.outputName,
        });
      }
      throw error;
    }
  }

  /**
   * Generate document using base engine (passthrough)
   *
   * This preserves the original DocumentEngine.generate() behavior.
   * No normalization or mapping - just direct passthrough.
   *
   * @param options - Base generation options
   * @returns Base generation result
   */
  async generate(options: DocumentGenerationOptions): Promise<DocumentGenerationResult> {
    return this.engine.generate(options);
  }

  /**
   * Render all documents for a Final Block
   *
   * This is the main entry point for Final Block document generation.
   *
   * Workflow:
   * 1. Normalize step values once (reused for all documents)
   * 2. For each document:
   *    a. Evaluate conditions ΓåÆ skip if false
   *    b. Apply mapping
   *    c. Generate document
   *    d. Handle errors gracefully
   * 3. Return results + metadata
   *
   * @param options - Final Block render options
   * @returns Render result with all documents
   */
  async renderFinalBlock(
    options: FinalBlockRenderOptions
  ): Promise<FinalBlockRenderResult> {
    const {
      documents,
      stepValues,
      outputDir,
      toPdf = false,
      pdfStrategy = 'puppeteer',
      normalizationOptions = {},
    } = options;

    logger.info({
      documentCount: documents.length,
      toPdf,
      pdfStrategy,
    }, 'Rendering Final Block documents');

    // Pre-normalize step values once (reused for all documents)
    const normalizedStepValues = normalizeVariables(stepValues, normalizationOptions);

    logger.debug({
      originalKeys: Object.keys(stepValues).length,
      normalizedKeys: Object.keys(normalizedStepValues).length,
    }, 'Step values normalized');

    const results: EnhancedGenerationResult[] = [];
    const skipped: FinalBlockRenderResult['skipped'] = [];
    const failed: FinalBlockRenderResult['failed'] = [];

    // Process each document
    for (const doc of documents) {
      try {
        // Step 1: Evaluate conditions
        if (doc.conditions) {
          const conditionMet = this.evaluateConditions(doc.conditions, stepValues);

          if (!conditionMet) {
            skipped.push({
              alias: doc.alias,
              reason: 'Conditions not met',
            });
            logger.info({ alias: doc.alias }, 'Document skipped (conditions not met)');
            continue;
          }
        }

        // Step 2: Generate document
        const result = await this.generateWithMapping({
          templatePath: doc.templatePath,
          rawData: stepValues, // Pass raw data, will be normalized internally
          mapping: doc.mapping,
          outputName: doc.alias,
          outputDir,
          toPdf,
          pdfStrategy,
          normalizationOptions,
          normalize: true,
        });

        results.push({
          ...result,
          alias: doc.alias,
        });

        logger.info({
          alias: doc.alias,
          docxPath: result.docxPath,
          pdfPath: result.pdfPath,
        }, 'Document generated successfully');
      } catch (error: unknown) {
        // Enhanced error logging with full context
        const docError = isDocumentGenerationError(error)
          ? error
          : wrapAsDocumentGenerationError(error, {
            phase: 'render',
            templateId: doc.documentId,
            templateAlias: doc.alias,
          });

        failed.push({
          alias: doc.alias,
          error: docError.getUserMessage(),
          phase: docError.phase,
          recoverable: docError.recoverable,
          suggestion: docError.suggestion,
          details: docError.toJSON(),
        });

        logger.error({
          alias: doc.alias,
          documentId: doc.documentId,
          phase: docError.phase,
          error: docError.toJSON(),
        }, 'Document generation failed');

        // Continue with other documents (graceful degradation)
      }
    }

    const finalResult: FinalBlockRenderResult = {
      documents: results,
      skipped,
      failed,
      totalAttempted: documents.length,
      totalGenerated: results.length,
    };

    logger.info({
      totalAttempted: finalResult.totalAttempted,
      generated: finalResult.totalGenerated,
      skipped: skipped.length,
      failed: failed.length,
    }, 'Final Block rendering complete');

    return finalResult;
  }

  /**
   * Evaluate conditional logic for document inclusion
   *
   * Uses simplified logic evaluation (can be replaced with full logic engine later)
   *
   * @param conditions - Logic expression
   * @param stepValues - Step values to evaluate against
   * @returns Whether conditions are met
   */
  private evaluateConditions(
    conditions: LogicExpression,
    stepValues: Record<string, unknown>
  ): boolean {
    if (!conditions?.conditions || conditions.conditions.length === 0) {
      return true;
    }

    const operator = conditions.operator || 'AND';
    const results = conditions.conditions.map(cond => {
      const value = stepValues[cond.key];

      switch (cond.op) {
        case 'equals':
          return value === cond.value;
        case 'not_equals':
          return value !== cond.value;
        case 'contains':
          if (typeof value === 'string') {
            return value.includes(String(cond.value));
          }
          if (Array.isArray(value)) {
            return value.includes(cond.value);
          }
          return false;
        case 'greater_than':
          return Number(value) > Number(cond.value);
        case 'less_than':
          return Number(value) < Number(cond.value);
        case 'is_empty':
          return !value || value === '' || (Array.isArray(value) && value.length === 0);
        case 'is_not_empty':
          return !!value && value !== '' && (!Array.isArray(value) || value.length > 0);
        default:
          return true;
      }
    });

    if (operator === 'AND') {
      return results.every(r => r);
    } else {
      return results.some(r => r);
    }
  }
}

