/**
 * Mapping Validator
 *
 * Validates field mappings before document generation to catch errors early.
 * Provides detailed validation reports with warnings and suggestions.
 *
 * Features:
 * - Structural validation (syntax, types, duplicates)
 * - Coverage analysis (unmapped fields, unused sources)
 * - Type compatibility checking
 * - Dry-run generation with test data
 * - Detailed error and warning reporting
 *
 * Usage:
 * ```typescript
 * const validator = new MappingValidator();
 * const report = await validator.validateWithTestData(
 *   templateId,
 *   mapping,
 *   testStepValues
 * );
 *
 * if (!report.valid) {
 *   console.error('Mapping errors:', report.errors);
 * }
 * ```
 */
import { eq } from 'drizzle-orm';

import { templates } from '../../../shared/schema';
import { db } from '../../db';
import { logger } from '../../logger';

import { applyMapping } from './MappingInterpreter';
import { normalizeVariables } from './VariableNormalizer';

import type { DocumentMapping } from './MappingInterpreter';
// ============================================================================
// TYPES
// ============================================================================
export interface ValidationError {
  type: string;
  message: string;
  field?: string;
  details?: any;
  suggestion?: string;
}
export interface ValidationWarning {
  type: string;
  message: string;
  field?: string;
  suggestion?: string;
  details?: any;
}
export interface CoverageStats {
  totalTemplateFields: number;
  mappedFields: number;
  unmappedFields: string[];
  unusedSources: string[];
  coveragePercentage: number;
}
export interface TypeMismatch {
  field: string;
  expectedType: string;
  receivedType: string;
  value: any;
  suggestion?: string;
}
export interface ValidationReport {
  valid: boolean;
  errors: ValidationError[];
  warnings: ValidationWarning[];
  coverage: CoverageStats;
  typeMismatches: TypeMismatch[];
  dryRunSuccess: boolean;
  dryRunOutput?: any;
}
// ============================================================================
// MAPPING VALIDATOR CLASS
// ============================================================================
export class MappingValidator {
  /**
   * Validate mapping with test data
   *
   * Performs comprehensive validation:
   * 1. Structural validation (syntax, duplicates, circular refs)
   * 2. Coverage analysis (all fields mapped?)
   * 3. Source variable existence check
   * 4. Type compatibility check
   * 5. Dry-run generation test
   */
  async validateWithTestData(
    templateId: string,
    mapping: DocumentMapping,
    testStepValues: Record<string, any>
  ): Promise<ValidationReport> {
    logger.info({ templateId }, 'Validating mapping with test data');
    const report: ValidationReport = {
      valid: true,
      errors: [],
      warnings: [],
      coverage: {
        totalTemplateFields: 0,
        mappedFields: 0,
        unmappedFields: [],
        unusedSources: [],
        coveragePercentage: 0,
      },
      typeMismatches: [],
      dryRunSuccess: false,
    };
    try {
      // Step 1: Load template
      const [template] = await db
        .select()
        .from(templates)
        .where(eq(templates.id, templateId))
        .limit(1);
      if (!template) {
        report.errors.push({
          type: 'template_not_found',
          message: `Template ${templateId} not found`,
        });
        report.valid = false;
        return report;
      }
      // Step 2: Structural validation
      const structuralErrors = this.validateStructure(mapping);
      report.errors.push(...structuralErrors);
      if (structuralErrors.length > 0) {
        report.valid = false;
        return report;
      }
      // Step 3: Coverage analysis
      report.coverage = this.analyzeCoverage(template, mapping);
      // Warn about unmapped fields
      if (report.coverage.unmappedFields.length > 0) {
        report.warnings.push({
          type: 'incomplete_coverage',
          message: `${report.coverage.unmappedFields.length} template field(s) are not mapped`,
          details: { fields: report.coverage.unmappedFields },
          suggestion: 'Map all template fields to ensure complete document generation',
        });
      }
      // Step 4: Source variable existence check
      const sourceErrors = this.validateSourceVariables(mapping, testStepValues);
      report.warnings.push(...sourceErrors);
      // Step 5: Dry-run generation
      try {
        const normalized = normalizeVariables(testStepValues);
        const mappingResult = applyMapping(normalized, mapping);
        report.dryRunSuccess = true;
        report.dryRunOutput = mappingResult.data;
        // Step 6: Type compatibility check
        if (template.metadata && (template.metadata as any).fields) {
          const typeMismatches = this.checkTypeCompatibility(
            (template.metadata as any).fields,
            mappingResult.data
          );
          report.typeMismatches = typeMismatches;
          if (typeMismatches.length > 0) {
            report.warnings.push({
              type: 'type_mismatches',
              message: `${typeMismatches.length} field(s) have type mismatches`,
              details: { mismatches: typeMismatches },
              suggestion: 'Review field types to ensure correct data formatting',
            });
          }
        }
        // Warn about unused sources
        if (report.coverage.unusedSources.length > 0) {
          report.warnings.push({
            type: 'unused_sources',
            message: `${report.coverage.unusedSources.length} workflow variable(s) are not used in mapping`,
            details: { sources: report.coverage.unusedSources },
            suggestion: 'Remove unused variables from test data or add mappings',
          });
        }
      } catch (error: any) {
        report.errors.push({
          type: 'dry_run_failed',
          message: `Mapping application failed: ${error.message}`,
          details: { error: error.message },
        });
        report.valid = false;
        report.dryRunSuccess = false;
      }
      // Final validation status
      report.valid = report.errors.length === 0;
      logger.info(
        {
          templateId,
          valid: report.valid,
          errorCount: report.errors.length,
          warningCount: report.warnings.length,
          coverage: report.coverage.coveragePercentage,
        },
        'Mapping validation completed'
      );
      return report;
    } catch (error: any) {
      logger.error({ error, templateId }, 'Mapping validation failed');
      report.errors.push({
        type: 'validation_error',
        message: error.message || 'Unknown validation error',
      });
      report.valid = false;
      return report;
    }
  }
  /**
   * Validate mapping structure
   *
   * Checks for:
   * - Valid JSON structure
   * - Duplicate target fields
   * - Circular references
   * - Invalid mapping types
   */
  private validateStructure(mapping: DocumentMapping): ValidationError[] {
    const errors: ValidationError[] = [];
    if (!mapping || typeof mapping !== 'object') {
      errors.push({
        type: 'invalid_structure',
        message: 'Mapping must be an object',
      });
      return errors;
    }
    const targetFields = Object.keys(mapping);
    // Check for duplicate target fields (shouldn't happen in object, but check anyway)
    const duplicates = targetFields.filter(
      (field, index) => targetFields.indexOf(field) !== index
    );
    if (duplicates.length > 0) {
      errors.push({
        type: 'duplicate_targets',
        message: `Duplicate target fields found: ${duplicates.join(', ')}`,
        details: { duplicates },
      });
    }
    // Validate each mapping entry
    for (const [target, config] of Object.entries(mapping || {})) {
      if (!config || typeof config !== 'object') {
        errors.push({
          type: 'invalid_mapping_entry',
          message: `Invalid mapping configuration for field "${target}"`,
          field: target,
        });
        continue;
      }
      // Check for required properties
      if (!config.type) {
        errors.push({
          type: 'missing_type',
          message: `Mapping type missing for field "${target}"`,
          field: target,
        });
      }
      if (!config.source) {
        errors.push({
          type: 'missing_source',
          message: `Source variable missing for field "${target}"`,
          field: target,
        });
      }
      // Check for circular references (target === source)
      if (config.source === target) {
        errors.push({
          type: 'circular_reference',
          message: `Circular reference detected: "${target}" maps to itself`,
          field: target,
          suggestion: 'Change the source variable to a different field',
        });
      }
      // Validate mapping type
      const validTypes = ['variable', 'constant', 'expression'];
      if (config.type && !validTypes.includes(config.type)) {
        errors.push({
          type: 'invalid_type',
          message: `Invalid mapping type "${config.type}" for field "${target}"`,
          field: target,
          details: { validTypes },
          suggestion: `Use one of: ${validTypes.join(', ')}`,
        });
      }
    }
    return errors;
  }
  /**
   * Analyze coverage (which fields are mapped vs unmapped)
   */
  private analyzeCoverage(
    template: any,
    mapping: DocumentMapping
  ): CoverageStats {
    const templateFields =
      template.metadata?.fields?.map((f: any) => f.name) ?? [];
    const mappedFields = Object.keys(mapping || {});
    const unmappedFields = templateFields.filter(
      (field: string) => !mappedFields.includes(field)
    );
    const totalFields = templateFields.length;
    const coverage =
      totalFields > 0
        ? (mappedFields.length / totalFields) * 100
        : 0;
    return {
      totalTemplateFields: totalFields,
      mappedFields: mappedFields.length,
      unmappedFields,
      unusedSources: [], // Will be populated after dry run
      coveragePercentage: Math.round(coverage * 100) / 100,
    };
  }
  /**
   * Check if source variables exist in test data
   */
  private validateSourceVariables(
    mapping: DocumentMapping,
    testStepValues: Record<string, any>
  ): ValidationWarning[] {
    const warnings: ValidationWarning[] = [];
    const normalized = normalizeVariables(testStepValues);
    for (const [target, config] of Object.entries(mapping || {})) {
      if (config.type === 'variable' && config.source) {
        if (!(config.source in normalized)) {
          warnings.push({
            type: 'missing_source_variable',
            message: `Source variable "${config.source}" not found in test data`,
            field: target,
            suggestion: `Add "${config.source}" to test data or change the mapping`,
          });
        }
      }
    }
    return warnings;
  }
  /**
   * Check type compatibility between template fields and mapped values
   */
  private checkTypeCompatibility(
    templateFields: any[],
    mappedData: Record<string, any>
  ): TypeMismatch[] {
    const mismatches: TypeMismatch[] = [];
    for (const field of templateFields) {
      const value = mappedData[field.name];
      if (value === undefined || value === null) {
        continue; // Skip missing values
      }
      const expectedType = field.type || 'unknown';
      const receivedType = this.getValueType(value);
      if (!this.isCompatibleType(expectedType, receivedType, value)) {
        mismatches.push({
          field: field.name,
          expectedType,
          receivedType,
          value,
          suggestion: this.getSuggestion(expectedType, receivedType, value),
        });
      }
    }
    return mismatches;
  }
  /**
   * Get the type of a value
   */
  private getValueType(value: any): string {
    if (value === null) {return 'null';}
    if (Array.isArray(value)) {return 'array';}
    if (value instanceof Date) {return 'date';}
    return typeof value;
  }
  /**
   * Check if types are compatible
   */
  private isCompatibleType(
    expectedType: string,
    receivedType: string,
    value: any
  ): boolean {
    // Exact match
    if (expectedType === receivedType) {return true;}
    // Compatible conversions
    const compatibilityMap: Record<string, string[]> = {
      text: ['string', 'number', 'boolean', 'date'],
      checkbox: ['boolean', 'string', 'number'],
      dropdown: ['string', 'number'],
      radio: ['string', 'number'],
      unknown: ['string', 'number', 'boolean', 'date', 'array', 'object'],
    };
    const compatibleTypes = compatibilityMap[expectedType] ?? [];
    return compatibleTypes.includes(receivedType);
  }
  /**
   * Get suggestion for type mismatch
   */
  private getSuggestion(
    expectedType: string,
    receivedType: string,
    value: any
  ): string {
    if (expectedType === 'checkbox' && receivedType === 'string') {
      return 'Convert string to boolean ("true"/"false")';
    }
    if (expectedType === 'text' && receivedType === 'date') {
      return 'Format date as string (e.g., YYYY-MM-DD)';
    }
    if (expectedType === 'text' && receivedType === 'array') {
      return 'Join array elements into a string';
    }
    if (expectedType === 'dropdown' && receivedType === 'number') {
      return 'Convert number to string';
    }
    return `Convert ${receivedType} to ${expectedType}`;
  }
  /**
   * Quick validation (structure only, no test data)
   */
  async validateStructureOnly(
    templateId: string,
    mapping: DocumentMapping
  ): Promise<Pick<ValidationReport, 'valid' | 'errors' | 'warnings'>> {
    const errors = this.validateStructure(mapping);
    return {
      valid: errors.length === 0,
      errors,
      warnings: [],
    };
  }
}
// Singleton instance
export const mappingValidator = new MappingValidator();

/**
 * Stage 22: PDF Service
 * 
 * Handles PDF form unlocking, field extraction, and filling.
 * Uses a hybrid approach:
 * - node-qpdf2 (qpdf): For robust unlocking/decryption of government forms
 * - pdf-lib: For field extraction and filling
 */
import { execFile } from 'child_process';
import fs from 'fs/promises';
import os from 'os';
import path from 'path';
import { promisify } from 'util';

import { PDFDocument, PDFTextField, PDFCheckBox, PDFDropdown, PDFRadioGroup } from 'pdf-lib';

import { logger } from '../../logger';
import { createError } from '../../utils/errors';

// SECURITY: Use execFile with argument arrays to prevent shell injection
// execFile does NOT spawn a shell, making it immune to command injection
const execFileAsync = promisify(execFile);
export interface PdfField {
    name: string;
    type: 'text' | 'checkbox' | 'radio' | 'dropdown' | 'button' | 'signature' | 'unknown';
    pageIndex: number; // 0-based
    rect?: { x: number; y: number; width: number; height: number }; // User space coordinates
    value?: string;
    options?: string[]; // For dropdowns/radios
    isReadOnly?: boolean;
}
export interface PdfMetadata {
    pageCount: number;
    fields: PdfField[];
    isEncrypted: boolean;
}
export class PdfService {
    /**
     * Unlock a PDF by removing encryption/restrictions using qpdf
     * This is essential for government forms that are "locked" for editing
     */
    async unlockPdf(inputBuffer: Buffer): Promise<Buffer> {
        const tempDir = os.tmpdir();
        const inputPath = path.join(tempDir, `locked-${Date.now()}.pdf`);
        const outputPath = path.join(tempDir, `unlocked-${Date.now()}.pdf`);
        try {
            await fs.writeFile(inputPath, inputBuffer);
            // SECURITY: Use execFile with argument array (no shell, no injection risk)
            // qpdf --decrypt input.pdf output.pdf
            // This command removes restrictions (like filling prevention)
            await execFileAsync('qpdf', ['--decrypt', inputPath, outputPath]);
            return await fs.readFile(outputPath);
        } catch (error: any) {
            logger.error({ error }, 'Failed to unlock PDF with qpdf');
            // Fallback: If qpdf fails or isn't installed, return original buffer
            // The caller might still be able to use it if it wasn't actually locked
            logger.warn('Returning original PDF buffer due to unlock failure');
            return inputBuffer;
        } finally {
            // Cleanup temp files
            await Promise.all([
                fs.unlink(inputPath).catch(() => { }),
                fs.unlink(outputPath).catch(() => { }),
            ]);
        }
    }
    /**
     * Extract form fields and metadata from a PDF
     */
    async extractFields(pdfBuffer: Buffer): Promise<PdfMetadata> {
        try {
            const pdfDoc = await PDFDocument.load(pdfBuffer, { ignoreEncryption: true });
            const form = pdfDoc.getForm();
            const fields = form.getFields();
            const extractedFields: PdfField[] = [];
            const pageCount = pdfDoc.getPageCount();
            const pages = pdfDoc.getPages();
            for (const field of fields) {
                const name = field.getName();
                const type = this.getFieldType(field);
                // Find which page the field is on and its coordinates
                const widgets = field.acroField.getWidgets();
                let pageIndex = 0;
                let rect: { x: number; y: number; width: number; height: number } | undefined;
                if (widgets.length > 0) {
                    const widget = widgets[0];
                    const rectangle = widget.getRectangle();
                    rect = {
                        x: rectangle.x,
                        y: rectangle.y,
                        width: rectangle.width,
                        height: rectangle.height,
                    };
                    // Find page index
                    const pageRef = widget.P;
                    if (pageRef) {
                        try {
                            // Compare refs using tag/gen to avoid type mismatches
                            pageIndex = pages.findIndex(p => {
                                const pRef = p.ref as any;
                                const wRef = pageRef as any;
                                return pRef && wRef && pRef.tag === wRef.tag && pRef.gen === wRef.gen;
                            });
                        } catch (e) {
                            // ignore page finding error
                        }
                    }
                }
                if (pageIndex === -1) {pageIndex = 0;}
                let options: string[] | undefined;
                if (field instanceof PDFDropdown) {
                    options = field.getOptions();
                } else if (field instanceof PDFRadioGroup) {
                    options = field.getOptions();
                }
                extractedFields.push({
                    name,
                    type,
                    pageIndex,
                    rect,
                    options,
                    isReadOnly: field.isReadOnly(),
                });
            }
            return {
                pageCount,
                fields: extractedFields,
                isEncrypted: pdfDoc.isEncrypted,
            };
        } catch (error: any) {
            logger.error({ error }, 'Failed to extract PDF fields');
            throw createError.internal(`Failed to parse PDF: ${  error.message}`);
        }
    }
    /**
     * Fill a PDF form with data
     * @param mapping - Map of PDF field names to string values
     */
    async fillPdf(pdfBuffer: Buffer, mapping: Record<string, string>): Promise<Buffer> {
        try {
            const pdfDoc = await PDFDocument.load(pdfBuffer);
            const form = pdfDoc.getForm();
            for (const [fieldName, value] of Object.entries(mapping)) {
                if (value === undefined || value === null || value === '') {continue;}
                try {
                    const field = form.getField(fieldName);
                    if (field instanceof PDFTextField) {
                        field.setText(String(value));
                    } else if (field instanceof PDFCheckBox) {
                        if (String(value).toLowerCase() === 'true' || value === '1' || value === 'yes') {
                            field.check();
                        } else {
                            field.uncheck();
                        }
                    } else if (field instanceof PDFDropdown) {
                        field.select(String(value));
                    } else if (field instanceof PDFRadioGroup) {
                        field.select(String(value));
                    }
                } catch (err) {
                    // Field might not exist or wrong type, log and continue
                    logger.warn({ fieldName, error: err }, 'Failed to fill PDF field');
                }
            }
            // Flatten the form to prevent further editing (optional, but good for final docs)
            form.flatten();
            return Buffer.from(await pdfDoc.save());
        } catch (error: any) {
            logger.error({ error }, 'Failed to fill PDF');
            throw createError.internal(`Failed to generate PDF: ${  error.message}`);
        }
    }
    private getFieldType(field: any): PdfField['type'] {
        if (field instanceof PDFTextField) {return 'text';}
        if (field instanceof PDFCheckBox) {return 'checkbox';}
        if (field instanceof PDFDropdown) {return 'dropdown';}
        if (field instanceof PDFRadioGroup) {return 'radio';}
        return 'unknown';
    }
}
export const pdfService = new PdfService();

import Docxtemplater from 'docxtemplater';
import PizZip from 'pizzip';

import { logger } from '../../logger';

import { TemplateParser } from './TemplateParser';

export interface ScanResult {
    fixed: boolean;
    buffer: Buffer;
    repairs: string[];
    isValid: boolean;
    errors?: string[];
}

export class TemplateScanner {
    private parser: TemplateParser;

    constructor() {
        this.parser = new TemplateParser();
    }

    /**
     * Scan a DOCX buffer, attempt to fix common issues, and validate
     */
    async scanAndFix(buffer: Buffer): Promise<ScanResult> {
        const repairs: string[] = [];
        let currentBuffer = buffer;
        let fixed = false;

        try {
            // 1. Load Zip
            const zip = new PizZip(currentBuffer);

            // 2. Get document.xml
            const docXml = zip.file('word/document.xml')?.asText();

            if (!docXml) {
                return {
                    fixed: false,
                    buffer,
                    repairs,
                    isValid: false,
                    errors: ['Could not find word/document.xml in DOCX file']
                };
            }

            // 3. Normalize XML (remove invisible chars)
            const normalizedXml = this.normalizeXml(docXml);

            // 4. Apply fixes
            const { xml: newXml, repairs: xmlRepairs } = this.repairXml(normalizedXml);

            if (normalizedXml !== docXml) {
                // repairs.push('Normalized invisible characters'); // Optional: don't report if just cleaning
            }

            if (xmlRepairs.length > 0) {
                repairs.push(...xmlRepairs);
                fixed = true;
            }

            // 5. If fixed or normalized, update zip
            if (fixed || normalizedXml !== docXml) {
                zip.file('word/document.xml', newXml);
                currentBuffer = zip.generate({ type: 'nodebuffer' });
            }

            // 6. Validate
            try {
                this.validateBuffer(currentBuffer);

                return {
                    fixed: fixed || normalizedXml !== docXml,
                    buffer: currentBuffer,
                    repairs,
                    isValid: true
                };

            } catch (error: any) {
                // Log the XML context for debugging
                const errorContext = this.extractErrorContext(newXml, error);
                logger.error({
                    error: error.message,
                    context: errorContext,
                    repairsApplied: repairs
                }, 'Template validation failed after repairs');

                // If validation fails
                return {
                    fixed: fixed || normalizedXml !== docXml,
                    buffer: currentBuffer,
                    repairs,
                    isValid: false,
                    errors: this.extractErrors(error)
                };
            }

        } catch (error: any) {
            logger.error({ error }, 'Template scanning failed');
            return {
                fixed: false,
                buffer,
                repairs,
                isValid: false,
                errors: [error.message]
            };
        }
    }

    /**
     * Remove invisible characters and normalize spaces
     */
    private normalizeXml(xml: string): string {
        return xml
            .replace(/\u200B/g, '') // Zero-width space
            .replace(/\uFEFF/g, '') // BOM
            .replace(/\u00A0/g, ' '); // Non-breaking space -> regular space
    }

    /**
     * Repair XML content by fixing common template issues
     */
    public repairXml(xml: string): { xml: string; repairs: string[] } {
        let newXml = xml;
        const repairs: string[] = [];

        // Fix 1: Duplicate delimiters (e.g. {{{{ or <w:t>{{</w:t><w:t>{{</w:t>)
        // Strategy: Find {{ followed by (tags or whitespace or non-brace chars) followed by {{
        // We want to keep the first {{ and the intermediate content, but remove the second {{

        // Regex for Open: ({{)((?:(?!}}|{{)[\s\S])*)({{)
        // Capture group 1: {{
        // Capture group 2: Intermediate content (anything that doesn't contain }} or {{, including newlines)
        // Capture group 3: {{
        // Replace with: $1$2 (Keep first {{, keep intermediate, remove second {{)
        const duplicateOpenRegex = /({{)((?:(?!}}|{{)[\s\S])*)({{)/g;
        let loopCountOpen = 0;
        while (duplicateOpenRegex.test(newXml) && loopCountOpen < 5) {
            newXml = newXml.replace(duplicateOpenRegex, '$1$2');
            repairs.push('Fixed duplicate open delimiters');
            loopCountOpen++;
        }

        // Regex for Close: (}})((?:(?!}}|{{)[\s\S])*)(}})
        // Capture group 1: }}
        // Capture group 2: Intermediate content
        // Capture group 3: }}
        // Replace with: $1$2 (Keep first }}, keep intermediate, remove second }})
        const duplicateCloseRegex = /(}})((?:(?!}}|{{)[\s\S])*)(}})/g;
        let loopCountClose = 0;
        while (duplicateCloseRegex.test(newXml) && loopCountClose < 5) {
            newXml = newXml.replace(duplicateCloseRegex, '$1$2');
            repairs.push('Fixed duplicate close delimiters');
            loopCountClose++;
        }

        // Fix 2: Split tags (XML tags inside placeholders)
        let hasSplitTags = true;
        let loopCount = 0;
        const maxLoops = 10;

        while (hasSplitTags && loopCount < maxLoops) {
            const originalXml = newXml;
            // Regex to find {{...<...>...}}
            // This regex looks for {{ followed by any characters that are NOT } (lazy), 
            // then a tag <...>, then any characters (lazy) until }}
            newXml = newXml.replace(/({{[^}]*?)(<[^>]+>)(.*?}})/g, '$1$3');

            if (newXml !== originalXml) {
                hasSplitTags = true;
                loopCount++;
            } else {
                hasSplitTags = false;
            }
        }

        if (loopCount > 0) {
            repairs.push(`Removed hidden XML formatting tags from ${loopCount} placeholders`);
        }

        return { xml: newXml, repairs };
    }

    private validateBuffer(buffer: Buffer) {
        const zip = new PizZip(buffer);
        const doc = new Docxtemplater(zip, {
            paragraphLoop: true,
            linebreaks: true,
            delimiters: { start: '{{', end: '}}' }
        });
        doc.compile();
    }

    private extractErrors(error: any): string[] {
        if (error.properties?.errors) {
            return error.properties.errors.map((e: any) => e.message || e.name);
        }
        return [error.message];
    }

    private extractErrorContext(xml: string, error: any): any {
        if (!error.properties) {return null;}

        // Handle Multi error
        if (error.properties.errors && Array.isArray(error.properties.errors)) {
            return error.properties.errors.map((e: any) => this.extractErrorContext(xml, e));
        }

        // Try to find the tag in the XML
        const tag = error.properties.xtag;
        if (!tag) {return null;}

        const index = xml.indexOf(tag);
        if (index === -1) {return `Tag '${tag}' not found in XML`;}

        // Return 100 chars before and after
        const start = Math.max(0, index - 100);
        const end = Math.min(xml.length, index + 100);
        const snippet = xml.substring(start, end);

        // Create hex dump of snippet for deep debugging
        const hex = Buffer.from(snippet).toString('hex').match(/../g)?.join(' ');

        return {
            tag,
            snippet,
            hex
        };
    }
}

export const templateScanner = new TemplateScanner();

/**
 * Variable Normalizer
 *
 * Transforms complex step values into flat key-value pairs suitable for
 * document template rendering.
 *
 * Capabilities:
 * - Flatten nested objects using dot notation
 * - Convert arrays to comma-separated strings
 * - Handle multi-field values (address, name, etc.)
 * - Preserve simple values unchanged
 * - Type-safe with TypeScript
 *
 * @version 1.0.0 - Final Block Extension (Prompt 10)
 * @date December 6, 2025
 */

import type { AddressValue, MultiFieldValue } from '../../../shared/types/stepConfigs';

// ============================================================================
// TYPES
// ============================================================================

/**
 * Normalization options
 */
export interface NormalizationOptions {
  /** Whether to flatten nested objects with dot notation (default: true) */
  flattenNested?: boolean;

  /** Whether to convert arrays to comma-separated strings (default: true) */
  joinArrays?: boolean;

  /** Delimiter for joining arrays (default: ", ") */
  arrayDelimiter?: string;

  /** Whether to include null/undefined values as empty strings (default: true) */
  includeEmpty?: boolean;

  /** Maximum depth for nested object flattening (default: 10) */
  maxDepth?: number;
}

/**
 * Normalized data structure (flat key-value pairs)
 */
export type NormalizedData = Record<string, string | number | boolean | string[]>;

// ============================================================================
// MAIN FUNCTION
// ============================================================================

/**
 * Normalize step values for document template rendering
 *
 * @param stepValues - Raw step values from workflow run
 * @param options - Normalization options
 * @returns Flat key-value pairs suitable for template rendering
 *
 * @example
 * ```typescript
 * const normalized = normalizeVariables({
 *   firstName: "John",
 *   lastName: "Doe",
 *   address: {
 *     street: "123 Main St",
 *     city: "NYC"
 *   },
 *   hobbies: ["biking", "hiking"]
 * });
 *
 * // Result:
 * {
 *   "firstName": "John",
 *   "lastName": "Doe",
 *   "address.street": "123 Main St",
 *   "address.city": "NYC",
 *   "hobbies": "biking, hiking"
 * }
 * ```
 */
export function normalizeVariables(
  stepValues: Record<string, any>,
  options: NormalizationOptions = {}
): NormalizedData {
  const opts: Required<NormalizationOptions> = {
    flattenNested: options.flattenNested ?? true,
    joinArrays: options.joinArrays ?? true,
    arrayDelimiter: options.arrayDelimiter ?? ', ',
    includeEmpty: options.includeEmpty ?? true,
    maxDepth: options.maxDepth ?? 10,
  };

  const result: NormalizedData = {};

  // Process each step value
  for (const [key, value] of Object.entries(stepValues)) {
    processValue(result, key, value, opts, 0);
  }

  return result;
}

// ============================================================================
// PROCESSING FUNCTIONS
// ============================================================================

/**
 * Process a single value and add to result
 */
function processValue(
  result: NormalizedData,
  key: string,
  value: any,
  opts: Required<NormalizationOptions>,
  depth: number
): void {
  // Prevent infinite recursion
  if (depth > opts.maxDepth) {
    result[key] = '[Max depth exceeded]';
    return;
  }

  // Handle null/undefined
  if (value === null || value === undefined) {
    if (opts.includeEmpty) {
      result[key] = '';
    }
    return;
  }

  // Handle primitive types
  if (isPrimitive(value)) {
    result[key] = value;
    return;
  }

  // Handle arrays
  if (Array.isArray(value)) {
    if (opts.joinArrays) {
      result[key] = joinArray(value, opts.arrayDelimiter);
    } else {
      result[key] = JSON.stringify(value);
    }
    return;
  }

  // Handle Date objects
  if (value instanceof Date) {
    result[key] = value.toISOString();
    return;
  }

  // Handle objects (nested structures)
  if (typeof value === 'object' && value !== null) {
    if (opts.flattenNested) {
      flattenObject(result, key, value, opts, depth + 1);
    } else {
      result[key] = JSON.stringify(value);
    }
    return;
  }

  // Fallback: convert to string
  result[key] = String(value);
}

/**
 * Flatten a nested object using dot notation
 */
function flattenObject(
  result: NormalizedData,
  prefix: string,
  obj: Record<string, any>,
  opts: Required<NormalizationOptions>,
  depth: number
): void {
  for (const [childKey, childValue] of Object.entries(obj)) {
    const newKey = prefix ? `${prefix}.${childKey}` : childKey;
    processValue(result, newKey, childValue, opts, depth);
  }
}

/**
 * Join array elements into a string
 */
function joinArray(arr: any[], delimiter: string): string {
  return arr
    .map(item => {
      if (item === null || item === undefined) {
        return '';
      }
      if (typeof item === 'object') {
        return JSON.stringify(item);
      }
      return String(item);
    })
    .filter(item => item !== '') // Remove empty entries
    .join(delimiter);
}

/**
 * Check if value is a primitive type
 */
function isPrimitive(value: any): value is string | number | boolean {
  return (
    typeof value === 'string' ||
    typeof value === 'number' ||
    typeof value === 'boolean'
  );
}

// ============================================================================
// SPECIALIZED NORMALIZERS
// ============================================================================

/**
 * Normalize address value with optional prefix
 *
 * @example
 * ```typescript
 * normalizeAddress({
 *   street: "123 Main St",
 *   city: "NYC",
 *   state: "NY",
 *   zip: "10001"
 * }, "billingAddress");
 *
 * // Result:
 * {
 *   "billingAddress.street": "123 Main St",
 *   "billingAddress.city": "NYC",
 *   "billingAddress.state": "NY",
 *   "billingAddress.zip": "10001"
 * }
 * ```
 */
export function normalizeAddress(
  address: AddressValue | null | undefined,
  prefix?: string
): NormalizedData {
  if (!address) {return {};}

  const result: NormalizedData = {};
  const fields = ['street', 'street2', 'city', 'state', 'zip', 'country'] as const;

  for (const field of fields) {
    const value = address[field];
    if (value !== null && value !== undefined) {
      const key = prefix ? `${prefix}.${field}` : field;
      result[key] = value;
    }
  }

  return result;
}

/**
 * Normalize multi-field value with optional prefix
 *
 * @example
 * ```typescript
 * normalizeMultiField({
 *   first: "John",
 *   last: "Doe",
 *   email: "john@example.com"
 * }, "contact");
 *
 * // Result:
 * {
 *   "contact.first": "John",
 *   "contact.last": "Doe",
 *   "contact.email": "john@example.com"
 * }
 * ```
 */
export function normalizeMultiField(
  multiField: MultiFieldValue | null | undefined,
  prefix?: string
): NormalizedData {
  if (!multiField) {return {};}

  const result: NormalizedData = {};

  for (const [field, value] of Object.entries(multiField)) {
    if (value !== null && value !== undefined) {
      const key = prefix ? `${prefix}.${field}` : field;
      result[key] = value;
    }
  }

  return result;
}

/**
 * Normalize choice value (single or multiple selections)
 *
 * @example
 * ```typescript
 * normalizeChoice(["option1", "option2"], ", ");
 * // Result: "option1, option2"
 *
 * normalizeChoice("single_option", ", ");
 * // Result: "single_option"
 * ```
 */
export function normalizeChoice(
  choice: string | string[] | null | undefined,
  delimiter: string = ', '
): string {
  if (!choice) {return '';}
  if (Array.isArray(choice)) {
    return choice.join(delimiter);
  }
  return String(choice);
}

// ============================================================================
// UTILITY FUNCTIONS
// ============================================================================

/**
 * Merge normalized data objects
 * Later entries override earlier ones for conflicting keys
 */
export function mergeNormalizedData(
  ...datasets: NormalizedData[]
): NormalizedData {
  return Object.assign({}, ...datasets);
}

/**
 * Filter normalized data by key prefix
 *
 * @example
 * ```typescript
 * const data = {
 *   "user.name": "John",
 *   "user.email": "john@example.com",
 *   "order.total": 100
 * };
 *
 * filterByPrefix(data, "user.");
 * // Result: { "user.name": "John", "user.email": "john@example.com" }
 * ```
 */
export function filterByPrefix(
  data: NormalizedData,
  prefix: string
): NormalizedData {
  const result: NormalizedData = {};

  for (const [key, value] of Object.entries(data)) {
    if (key.startsWith(prefix)) {
      result[key] = value;
    }
  }

  return result;
}

/**
 * Remove prefix from all keys in normalized data
 *
 * @example
 * ```typescript
 * const data = {
 *   "user.name": "John",
 *   "user.email": "john@example.com"
 * };
 *
 * stripPrefix(data, "user.");
 * // Result: { "name": "John", "email": "john@example.com" }
 * ```
 */
export function stripPrefix(
  data: NormalizedData,
  prefix: string
): NormalizedData {
  const result: NormalizedData = {};

  for (const [key, value] of Object.entries(data)) {
    if (key.startsWith(prefix)) {
      const newKey = key.substring(prefix.length);
      result[newKey] = value;
    } else {
      result[key] = value;
    }
  }

  return result;
}

/**
 * Get nested value from object using dot notation path
 *
 * @example
 * ```typescript
 * const obj = { user: { profile: { name: "John" } } };
 * getNestedValue(obj, "user.profile.name"); // "John"
 * getNestedValue(obj, "user.missing.path"); // undefined
 * ```
 */
export function getNestedValue(
  obj: Record<string, any>,
  path: string
): any {
  const keys = path.split('.');
  let current: any = obj;

  for (const key of keys) {
    if (current === null || current === undefined) {
      return undefined;
    }
    current = current[key];
  }

  return current;
}

// ============================================================================
// VALIDATION
// ============================================================================

/**
 * Validate that all required variables are present in normalized data
 *
 * @returns Array of missing variable names (empty if all present)
 */
export function validateRequiredVariables(
  normalizedData: NormalizedData,
  requiredVariables: string[]
): string[] {
  const missing: string[] = [];

  for (const variable of requiredVariables) {
    const value = normalizedData[variable];
    if (value === null || value === undefined || value === '') {
      missing.push(variable);
    }
  }

  return missing;
}

/**
 * Check if normalized data has all keys from a list
 */
export function hasAllKeys(
  normalizedData: NormalizedData,
  keys: string[]
): boolean {
  return keys.every(key => key in normalizedData);
}

/**
 * Get statistics about normalized data
 */
export function getNormalizationStats(normalizedData: NormalizedData): {
  totalKeys: number;
  emptyValues: number;
  numberValues: number;
  stringValues: number;
  booleanValues: number;
  nestedKeys: number; // Keys with dots
} {
  let emptyValues = 0;
  let numberValues = 0;
  let stringValues = 0;
  let booleanValues = 0;
  let nestedKeys = 0;

  for (const [key, value] of Object.entries(normalizedData)) {
    if (value === '' || value === null || value === undefined) {
      emptyValues++;
    }
    if (typeof value === 'number') {
      numberValues++;
    }
    if (typeof value === 'string') {
      stringValues++;
    }
    if (typeof value === 'boolean') {
      booleanValues++;
    }
    if (key.includes('.')) {
      nestedKeys++;
    }
  }

  return {
    totalKeys: Object.keys(normalizedData).length,
    emptyValues,
    numberValues,
    stringValues,
    booleanValues,
    nestedKeys,
  };
}

// ============================================================================
// EXPORTS
// ============================================================================

export default {
  normalizeVariables,
  normalizeAddress,
  normalizeMultiField,
  normalizeChoice,
  mergeNormalizedData,
  filterByPrefix,
  stripPrefix,
  getNestedValue,
  validateRequiredVariables,
  hasAllKeys,
  getNormalizationStats,
};

/**
 * ZIP Bundler
 *
 * Creates ZIP archives for multi-document outputs from Final Blocks.
 * Reuses pizzip library.
 *
 * Features:
 * - Bundle multiple DOCX/PDF documents
 * - Generate manifest file
 * - Configurable compression
 * - Memory-efficient streaming
 *
 * @version 1.0.1 - Security Hardening
 * @date December 8, 2025
 */

import { promises as fs } from 'fs';
import path from 'path';

import PizZip from 'pizzip';

import { createLogger } from '../../logger';

const logger = createLogger({ module: 'zip-bundler' });

// Safety Limits
const MAX_TOTAL_SIZE = 200 * 1024 * 1024; // 200MB
const MAX_FILE_COUNT = 100;
const MAX_SINGLE_FILE_SIZE = 50 * 1024 * 1024; // 50MB

// ============================================================================
// TYPES
// ============================================================================

export interface ZipDocument {
  filename: string;
  buffer: Buffer;
  mimeType?: string;
  size?: number;
}

export interface ZipOptions {
  compressionLevel?: number;
  includeManifest?: boolean;
  customManifest?: string;
  metadata?: Record<string, string>;
}

export interface ZipResult {
  filename: string;
  buffer: Buffer;
  size: number;
  fileCount: number;
  createdAt: Date;
}

// ============================================================================
// MAIN FUNCTIONS
// ============================================================================

/**
 * Create ZIP archive from document buffers
 */
export async function createZipArchive(
  documents: ZipDocument[],
  archiveName: string,
  options: ZipOptions = {}
): Promise<ZipResult> {
  const opts: Required<ZipOptions> = {
    compressionLevel: options.compressionLevel ?? 6,
    includeManifest: options.includeManifest ?? true,
    customManifest: options.customManifest ?? '',
    metadata: options.metadata ?? {},
  };

  // 1. Fail Fast checks
  if (documents.length === 0) {
    throw new Error('Cannot create ZIP archive: no documents provided');
  }
  if (documents.length > MAX_FILE_COUNT) {
    throw new Error(`Too many documents (max: ${MAX_FILE_COUNT})`);
  }

  // 2. Validate Total Size before processing
  const totalSize = calculateTotalSize(documents);
  if (totalSize > MAX_TOTAL_SIZE) {
    throw new Error(`Total archive size exceeds limit of ${MAX_TOTAL_SIZE / (1024 * 1024)}MB`);
  }

  logger.info({
    archiveName,
    fileCount: documents.length,
    totalSize,
  }, 'Creating ZIP archive');

  try {
    const zip = new PizZip();
    const usedFilenames = new Set<string>();

    for (const doc of documents) {
      // 3. Security: Sanitize filename (Prevention of LFI/Path Traversal)
      let sanitizedFilename = sanitizeFilename(doc.filename);

      // Handle duplicates
      if (usedFilenames.has(sanitizedFilename)) {
        const ext = path.extname(sanitizedFilename);
        const name = path.basename(sanitizedFilename, ext);
        let counter = 1;
        while (usedFilenames.has(`${name}_${counter}${ext}`)) {
          counter++;
        }
        sanitizedFilename = `${name}_${counter}${ext}`;
      }
      usedFilenames.add(sanitizedFilename);

      // Validate single file size
      if (doc.buffer.length > MAX_SINGLE_FILE_SIZE) {
        throw new Error(`File ${sanitizedFilename} exceeds max size of ${MAX_SINGLE_FILE_SIZE / (1024 * 1024)}MB`);
      }

      zip.file(sanitizedFilename, doc.buffer, {
        compression: 'DEFLATE',
        compressionOptions: {
          level: opts.compressionLevel as any,
        },
      });
    }

    // Add manifest
    if (opts.includeManifest) {
      const manifestContent = opts.customManifest ||
        generateManifest(documents, opts.metadata);

      zip.file('manifest.txt', manifestContent, {
        compression: 'DEFLATE',
        compressionOptions: {
          level: opts.compressionLevel as any,
        },
      });
    }

    // Generate ZIP buffer
    const zipBuffer = zip.generate({
      type: 'nodebuffer' as any,
      compression: 'DEFLATE',
      compressionOptions: {
        level: opts.compressionLevel as any,
      },
    }) as unknown as Buffer;

    const result: ZipResult = {
      filename: `${sanitizeFilename(archiveName, false)}.zip`,
      buffer: zipBuffer,
      size: zipBuffer.length,
      fileCount: documents.length,
      createdAt: new Date(),
    };

    return result;
  } catch (error) {
    logger.error({ error, archiveName }, 'Failed to create ZIP archive');
    throw new Error(`ZIP creation failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }
}

/**
 * Create ZIP archive from file paths
 * Securely reads only basenames of files.
 */
export async function createZipFromPaths(
  filePaths: string[],
  archiveName: string,
  options: ZipOptions = {}
): Promise<ZipResult> {
  const documents: ZipDocument[] = [];

  for (const filePath of filePaths) {
    try {
      const buffer = await fs.readFile(filePath);
      const filename = path.basename(filePath); // Security: Always use basename
      const stats = await fs.stat(filePath);

      documents.push({
        filename,
        buffer,
        size: stats.size,
      });
    } catch (error) {
      logger.error({ filePath, error }, 'Failed to read file for ZIP');
      throw new Error(`Failed to read file: ${path.basename(filePath)}`);
    }
  }

  return createZipArchive(documents, archiveName, options);
}

/**
 * Save ZIP archive to disk
 */
export async function saveZipToDisk(
  zipResult: ZipResult,
  outputPath: string
): Promise<string> {
  // Security: Ensure we are only writing to the intended directory
  // We do NOT sanitize the whole path here (consumer may want nested folders),
  // but we must sanitize the filename.
  const sanitizedFilename = sanitizeFilename(zipResult.filename);
  const fullPath = path.join(outputPath, sanitizedFilename);

  // Verify that fullPath is inside outputPath (Path Traversal check)
  const resolvedOut = path.resolve(outputPath);
  const resolvedFull = path.resolve(fullPath);
  if (!resolvedFull.startsWith(resolvedOut)) {
    throw new Error("Security Error: Attempted path traversal in ZIP save");
  }

  try {
    await fs.mkdir(outputPath, { recursive: true });
    await fs.writeFile(fullPath, zipResult.buffer);
    return fullPath;
  } catch (error) {
    logger.error({ error, outputPath }, 'Failed to save ZIP to disk');
    throw new Error(`Failed to save ZIP: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }
}

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

function generateManifest(
  documents: ZipDocument[],
  metadata: Record<string, string>
): string {
  const lines: string[] = [];
  lines.push('==========================================');
  lines.push('  WORKFLOW DOCUMENT BUNDLE');
  lines.push('==========================================');
  lines.push('');

  if (Object.keys(metadata).length > 0) {
    lines.push('Metadata:');
    for (const [key, value] of Object.entries(metadata)) {
      lines.push(`  ${key}: ${value}`);
    }
    lines.push('');
  }

  lines.push(`Generated: ${new Date().toISOString()}`);
  lines.push(`Total Files: ${documents.length}`);
  lines.push('');
  lines.push('Files Included:');
  lines.push('------------------------------------------');

  for (let i = 0; i < documents.length; i++) {
    const doc = documents[i];
    const size = doc.size ?? doc.buffer.length;
    const sizeMB = (size / (1024 * 1024)).toFixed(2);
    lines.push(`${i + 1}. ${doc.filename}`);
    lines.push(`   Size: ${sizeMB} MB`);
    if (doc.mimeType) {lines.push(`   Type: ${doc.mimeType}`);}
    lines.push('');
  }
  lines.push('------------------------------------------');
  return lines.join('\n');
}

/**
 * Sanitize filename for ZIP archive
 * STRICT WHITELIST: Only allows [a-zA-Z0-9._-]
 */
function sanitizeFilename(filename: string, includeExtension: boolean = true): string {
  // 1. Strip path components
  const base = path.basename(filename);

  // 2. Strict Whitelist replacement
  // Replace anything that is NOT a letter, number, dot, underscore, or dash
  let sanitized = base.replace(/[^a-zA-Z0-9._-]/g, '_');

  // 3. Trim
  sanitized = sanitized.trim();

  if (!sanitized || sanitized === '.' || sanitized === '..') {
    sanitized = 'document';
  }

  if (includeExtension && !path.extname(sanitized)) {
    sanitized += '.bin';
  }

  return sanitized;
}

export function calculateTotalSize(documents: ZipDocument[]): number {
  return documents.reduce((total, doc) => {
    return total + (doc.size ?? doc.buffer.length);
  }, 0);
}

export function validateDocuments(documents: ZipDocument[]): string[] {
  const errors: string[] = [];
  if (documents.length === 0) {errors.push('No documents provided');}
  if (documents.length > MAX_FILE_COUNT) {errors.push(`Too many documents (max: ${MAX_FILE_COUNT})`);}

  for (let i = 0; i < documents.length; i++) {
    const doc = documents[i];
    if (!doc.filename) {errors.push(`Document ${i}: Missing filename`);}
    if (!doc.buffer) {errors.push(`Document ${i}: Missing buffer`);}
    if (doc.buffer && doc.buffer.length === 0) {errors.push(`Document ${i} (${doc.filename}): Empty buffer`);}
    if (doc.buffer && doc.buffer.length > MAX_SINGLE_FILE_SIZE) {errors.push(`Document ${i} (${doc.filename}): Too large`);}
  }

  const totalSize = calculateTotalSize(documents);
  if (totalSize > MAX_TOTAL_SIZE) {errors.push(`Total archive size too large`);}

  return errors;
}

export function getZipStats(zipResult: ZipResult): {
  compressionRatio: string;
  averageFileSize: string;
  sizeMB: string;
} {
  const sizeMB = (zipResult.size / (1024 * 1024)).toFixed(2);
  const avgFileSize = (zipResult.size / zipResult.fileCount / 1024).toFixed(2);
  return {
    compressionRatio: 'N/A',
    averageFileSize: `${avgFileSize} KB`,
    sizeMB: `${sizeMB} MB`,
  };
}

export async function createFinalBlockZip(
  documents: ZipDocument[],
  workflowId: string,
  runId: string,
  metadata?: Record<string, string>
): Promise<ZipResult> {
  const errors = validateDocuments(documents);
  if (errors.length > 0) {
    throw new Error(`Invalid documents for ZIP: ${errors.join(', ')}`);
  }

  const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
  const archiveName = `final-docs-${runId.slice(0, 8)}-${timestamp}`;

  const fullMetadata = {
    'Workflow ID': workflowId,
    'Run ID': runId,
    'Generated At': new Date().toISOString(),
    ...metadata,
  };

  return createZipArchive(documents, archiveName, {
    compressionLevel: 6,
    includeManifest: true,
    metadata: fullMetadata,
  });
}

