export type { IPdfExtractor, PdfMetadata, PdfField, ExtractionResult } from './IPdfExtractor';

/**
 * PDF-Lib Extractor
 *
 * Primary PDF field extractor using pdf-lib library.
 * This is the default extractor and works for most standard PDFs.
 *
 * Supports:
 * - AcroForm fields (text, checkbox, radio, dropdown)
 * - Encrypted PDFs (with ignoreEncryption flag)
 * - Field coordinates and metadata
 *
 * Limitations:
 * - Doesn't work with XFA forms (XML Forms Architecture)
 * - May struggle with heavily customized or malformed PDFs
 */

import { PDFDocument, PDFTextField, PDFCheckBox, PDFDropdown, PDFRadioGroup } from 'pdf-lib';

import { logger } from '../../../logger';

import { FieldValidator } from './IPdfExtractor';

import type { IPdfExtractor, ExtractionResult, PdfField, PdfMetadata } from './IPdfExtractor';

export class PdfLibExtractor implements IPdfExtractor {
  readonly name = 'pdf-lib';
  readonly priority = 1; // Primary extractor

  async canHandle(buffer: Buffer): Promise<boolean> {
    try {
      // Try to load the PDF
      const pdfDoc = await PDFDocument.load(buffer, {
        ignoreEncryption: true,
        throwOnInvalidObject: false,
      });

      // Check if it has a form
      const form = pdfDoc.getForm();
      const fields = form.getFields();

      // Can handle if we successfully loaded and found fields
      return true; // Even PDFs without fields can be "handled"
    } catch (error) {
      logger.debug({ error, extractor: this.name }, 'Cannot handle PDF');
      return false;
    }
  }

  async extract(buffer: Buffer): Promise<ExtractionResult> {
    try {
      logger.debug({ extractor: this.name }, 'Attempting PDF field extraction');

      const pdfDoc = await PDFDocument.load(buffer, {
        ignoreEncryption: true,
        throwOnInvalidObject: false,
      });

      const form = pdfDoc.getForm();
      const fields = form.getFields();
      const pageCount = pdfDoc.getPageCount();
      const pages = pdfDoc.getPages();

      const extractedFields: PdfField[] = [];

      for (const field of fields) {
        const name = field.getName();
        const type = this.getFieldType(field);

        // Find which page the field is on and its coordinates
        const widgets = field.acroField.getWidgets();
        let pageIndex = 0;
        let rect: { x: number; y: number; width: number; height: number } | undefined;

        if (widgets.length > 0) {
          const widget = widgets[0];
          const rectangle = widget.getRectangle();

          rect = {
            x: rectangle.x,
            y: rectangle.y,
            width: rectangle.width,
            height: rectangle.height,
          };

          // Find page index
          const pageRef = widget.P();
          if (pageRef) {
            try {
              const foundIndex = pages.findIndex(p => {
                // Compare refs
                if (p.ref === pageRef) {return true;}

                const pRef = p.ref as any;
                const wRef = pageRef as any;

                // Robust comparison helper
                const getObjNum = (ref: any) => ref.objectNumber ?? (typeof ref.tag === 'string' ? parseInt(ref.tag.split(' ')[0]) : undefined);
                const getGenNum = (ref: any) => ref.generationNumber ?? (typeof ref.tag === 'string' ? parseInt(ref.tag.split(' ')[1]) : undefined);

                const pObj = getObjNum(pRef);
                const wObj = getObjNum(wRef);
                const pGen = getGenNum(pRef) ?? 0;
                const wGen = getGenNum(wRef) ?? 0;

                return pObj !== undefined && wObj !== undefined && pObj === wObj && pGen === wGen;
              });

              if (foundIndex !== -1) {
                pageIndex = foundIndex;
              }
            } catch (e) {
              logger.debug({ error: e, fieldName: name }, 'Failed to determine field page');
            }
          }
        }

        // Get field options (for dropdowns/radios)
        let options: string[] | undefined;
        if (field instanceof PDFDropdown) {
          options = field.getOptions();
        } else if (field instanceof PDFRadioGroup) {
          options = field.getOptions();
        }

        // Get current value (if any)
        let value: string | undefined;
        try {
          if (field instanceof PDFTextField) {
            value = field.getText() || undefined;
          } else if (field instanceof PDFCheckBox) {
            value = field.isChecked() ? 'true' : 'false';
          } else if (field instanceof PDFDropdown) {
            const selected = field.getSelected();
            value = selected.length > 0 ? selected[0] : undefined;
          } else if (field instanceof PDFRadioGroup) {
            value = field.getSelected() || undefined;
          }
        } catch (e) {
          logger.debug({ error: e, fieldName: name }, 'Failed to get field value');
        }

        extractedFields.push({
          name,
          type,
          pageIndex,
          rect,
          value,
          options,
          isReadOnly: field.isReadOnly(),
        });
      }

      // Validate extracted fields
      const warnings = FieldValidator.validate(extractedFields);

      const metadata: PdfMetadata = {
        pageCount,
        fields: extractedFields,
        isEncrypted: pdfDoc.isEncrypted,
        extractorUsed: this.name,
        extractionWarnings: warnings.length > 0 ? warnings : undefined,
      };

      logger.info(
        {
          extractor: this.name,
          fieldCount: extractedFields.length,
          pageCount,
          hasWarnings: warnings.length > 0,
        },
        'PDF fields extracted successfully'
      );

      return {
        success: true,
        metadata,
      };
    } catch (error: any) {
      logger.error(
        {
          error,
          extractor: this.name,
          message: error.message,
        },
        'PDF field extraction failed'
      );

      return {
        success: false,
        error: error.message || 'Unknown extraction error',
      };
    }
  }

  private getFieldType(field: any): PdfField['type'] {
    if (field instanceof PDFTextField) {return 'text';}
    if (field instanceof PDFCheckBox) {return 'checkbox';}
    if (field instanceof PDFDropdown) {return 'dropdown';}
    if (field instanceof PDFRadioGroup) {return 'radio';}
    return 'unknown';
  }
}

/**
 * Stage 21: DOCX Template Helpers
 *
 * Advanced helper functions for document generation with support for:
 * - String manipulation (upper, lower, capitalize, titleCase)
 * - Date formatting (with custom formats)
 * - Currency formatting (multi-currency)
 * - Number formatting (decimals, thousands)
 * - Array operations (join, length, first, last)
 * - Conditional helpers
 */

import { formatters } from '../utils/formatters';

/**
 * Capitalize first letter of string
 */
export function capitalize(s: string | null | undefined): string {
  if (!s) {return '';}
  return s.charAt(0).toUpperCase() + s.slice(1).toLowerCase();
}

/**
 * Join array elements with separator
 */
export function join(arr: any[] | null | undefined, separator: string = ', '): string {
  if (!arr || !Array.isArray(arr)) {return '';}
  return arr.filter(item => item != null).join(separator);
}

/**
 * Get array length
 */
export function length(arr: any[] | null | undefined): number {
  if (!arr || !Array.isArray(arr)) {return 0;}
  return arr.length;
}

/**
 * Get first element of array
 */
export function first(arr: any[] | null | undefined): any {
  if (!arr || !Array.isArray(arr) || arr.length === 0) {return null;}
  return arr[0];
}

/**
 * Get last element of array
 */
export function last(arr: any[] | null | undefined): any {
  if (!arr || !Array.isArray(arr) || arr.length === 0) {return null;}
  return arr[arr.length - 1];
}

/**
 * Check if value is empty (null, undefined, '', [], {})
 */
export function isEmpty(value: any): boolean {
  if (value === null || value === undefined || value === '') {return true;}
  if (Array.isArray(value)) {return value.length === 0;}
  if (typeof value === 'object') {return Object.keys(value).length === 0;}
  return false;
}

/**
 * Check if value is not empty
 */
export function isNotEmpty(value: any): boolean {
  return !isEmpty(value);
}

/**
 * Default value if empty
 */
export function defaultValue(value: any, defaultVal: any): any {
  return isEmpty(value) ? defaultVal : value;
}

/**
 * Format date with custom format string
 * Supports: YYYY, MM, DD, HH, mm, ss
 */
export function formatDate(
  iso: string | Date | null | undefined,
  format: string = 'MM/DD/YYYY'
): string {
  if (!iso) {return '';}

  try {
    const d = typeof iso === 'string' ? new Date(iso) : iso;
    if (isNaN(d.getTime())) {return '';}

    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    const hours = String(d.getHours()).padStart(2, '0');
    const minutes = String(d.getMinutes()).padStart(2, '0');
    const seconds = String(d.getSeconds()).padStart(2, '0');

    return format
      .replace('YYYY', String(year))
      .replace('MM', month)
      .replace('DD', day)
      .replace('HH', hours)
      .replace('mm', minutes)
      .replace('ss', seconds);
  } catch (error) {
    return '';
  }
}

/**
 * Format currency with symbol
 */
export function formatCurrency(
  amount: number | null | undefined,
  currencyCode: string = 'USD',
  showSymbol: boolean = true
): string {
  if (amount === null || amount === undefined || isNaN(amount)) {
    return showSymbol ? '$0.00' : '0.00';
  }

  try {
    const formatted = new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: currencyCode,
    }).format(amount);

    if (!showSymbol) {
      // Remove currency symbol
      return formatted.replace(/[^0-9.,\-]/g, '').trim();
    }

    return formatted;
  } catch (error) {
    // Fallback
    return showSymbol ? `${currencyCode} ${amount.toFixed(2)}` : amount.toFixed(2);
  }
}

/**
 * Format number with custom decimals
 */
export function formatNumber(
  n: number | null | undefined,
  decimals: number = 0,
  thousandsSep: boolean = true
): string {
  if (n === null || n === undefined || isNaN(n)) {
    return '0';
  }

  if (thousandsSep) {
    return n.toLocaleString('en-US', {
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals,
    });
  }

  return n.toFixed(decimals);
}

/**
 * Math operations
 */
export function add(a: number, b: number): number {
  return (a || 0) + (b || 0);
}

export function subtract(a: number, b: number): number {
  return (a || 0) - (b || 0);
}

export function multiply(a: number, b: number): number {
  return (a || 0) * (b || 0);
}

export function divide(a: number, b: number): number {
  if (!b || b === 0) {return 0;}
  return (a || 0) / b;
}

/**
 * Pluralize word based on count
 */
export function pluralize(
  count: number,
  singular: string,
  plural?: string
): string {
  if (count === 1) {return singular;}
  return plural || `${singular}s`;
}

/**
 * Truncate string to length
 */
export function truncate(s: string | null | undefined, maxLength: number, suffix: string = '...'): string {
  if (!s) {return '';}
  if (s.length <= maxLength) {return s;}
  return s.substring(0, maxLength - suffix.length) + suffix;
}

/**
 * Replace string
 */
export function replace(
  s: string | null | undefined,
  search: string,
  replacement: string
): string {
  if (!s) {return '';}
  return s.replace(new RegExp(search, 'g'), replacement);
}

/**
 * Combine all helpers into single object
 * This includes both formatters from utils/formatters.ts and new helpers
 */
export const docxHelpers = {
  // From formatters.ts
  ...formatters,

  // String helpers
  capitalize,
  truncate,
  replace,

  // Array helpers
  join,
  length,
  first,
  last,

  // Conditional helpers
  isEmpty,
  isNotEmpty,
  defaultValue,

  // Enhanced formatting
  formatDate,
  formatCurrency,
  formatNumber,

  // Math helpers
  add,
  subtract,
  multiply,
  divide,

  // Utility helpers
  pluralize,
};

/**
 * Create a custom parser function for docxtemplater
 * This enables angular-like expressions with filters
 */
export function createAngularParser() {
  return {
    get(scope: any, context: string) {
      // Handle dot notation (e.g., "user.name")
      const keys = context.split('.');
      let current = scope;

      for (const key of keys) {
        if (current == null) {return '';}
        current = current[key];
      }

      return current;
    },
  };
}

/**
 * DOCX Rendering Service
 * Handles DOCX template rendering and PDF conversion using docxtemplater
 */

// import { exec } from 'child_process'; // Removed
import fsSync from 'fs';
import fs from 'fs/promises';
import path from 'path';
// import { promisify } from 'util'; // Removed

import Docxtemplater from 'docxtemplater';
import { PDFDocument, StandardFonts, rgb } from 'pdf-lib';
import PizZip from 'pizzip';

import { logger } from '../logger';
import { createError } from '../utils/errors';
import { formatters } from '../utils/formatters';

// import { execAsync } from '../utils/exec'; // Use PdfConverter instead
import { PdfConverter } from './document/PdfConverter';

async function convertDocxToPdf(inputPath: string): Promise<string> {
  const converter = new PdfConverter();
  const outputPath = inputPath.replace(/\.docx$/, '.pdf');
  await converter.convert({
    docxPath: inputPath,
    outputPath,
  });
  return outputPath;
}

export interface RenderOptions {
  templatePath: string;
  data: Record<string, any>;
  outputDir?: string;
  outputName?: string;
  toPdf?: boolean;
}

export interface RenderResult {
  docxPath: string;
  pdfPath?: string;
  size: number;
}

/**
 * Render a DOCX template with data
 * @param options - Rendering options
 * @returns Paths to generated files
 */
export async function renderDocx(options: RenderOptions): Promise<RenderResult> {
  const {
    templatePath,
    data,
    outputDir = path.join(process.cwd(), 'server', 'files', 'outputs'),
    outputName,
    toPdf = false,
  } = options;

  // Validate template exists
  try {
    await fs.access(templatePath);
  } catch (error) {
    throw createError.notFound('Template file', templatePath);
  }

  // Ensure output directory exists
  await fs.mkdir(outputDir, { recursive: true });

  try {
    // Read template file
    const content = await fs.readFile(templatePath, 'binary');
    const zip = new PizZip(content);

    // Create docxtemplater instance with options
    const doc = new Docxtemplater(zip, {
      paragraphLoop: true,
      linebreaks: true,
      delimiters: { start: '{{', end: '}}' },
      nullGetter: () => '', // Return empty string for null/undefined values
    });

    // Merge data with formatters for template use
    const templateData = {
      ...data,
      ...formatters,
    };

    // Render with data
    try {
      await doc.renderAsync(templateData);
    } catch (error: any) {
      if (error.properties?.errors) {
        console.error('Docxtemplater MultiError:', JSON.stringify(error.properties.errors, null, 2));
        const errorMessages = error.properties.errors
          .map((e: any) => e.message)
          .join(', ');
        throw createError.internal(`Failed to render template: ${errorMessages}`);
      }
      throw createError.internal('Failed to render template', error);
    }

    // Generate output filename
    const timestamp = Date.now();
    const basename = outputName || path.basename(templatePath, '.docx');
    const outputFileName = `${basename}-${timestamp}.docx`;
    const outputPath = path.join(outputDir, outputFileName);

    // Write rendered document
    const buffer = doc.getZip().generate({
      type: 'nodebuffer',
      compression: 'DEFLATE',
    });

    await fs.writeFile(outputPath, buffer);

    // Get file size
    const stats = await fs.stat(outputPath);
    const size = stats.size;

    const result: RenderResult = {
      docxPath: outputPath,
      size,
    };

    // Convert to PDF if requested
    if (toPdf) {
      try {
        const pdfPath = await convertDocxToPdf(outputPath);
        result.pdfPath = pdfPath;
      } catch (error) {
        logger.warn({ error }, 'PDF conversion failed');
        // PDF conversion is optional, don't fail the entire operation
        // The DOCX file is still valid
      }
    }

    return result;
  } catch (error: any) {
    // If it's already a formatted error, re-throw it
    if (error.code && error.status) {
      throw error;
    }

    // Otherwise, wrap in a generic error
    throw createError.internal(
      `Failed to render template: ${error.message || 'Unknown error'}`
    );
  }
}

/**
 */
export async function extractPlaceholdersFromDocx(
  templatePath: string
): Promise<string[]> {
  try {
    // Validate template exists
    await fs.access(templatePath);

    // Read template file
    const content = await fs.readFile(templatePath, 'binary');
    const zip = new PizZip(content);

    // Create docxtemplater instance
    const doc = new Docxtemplater(zip, {
      paragraphLoop: true,
      linebreaks: true,
      delimiters: { start: '{{', end: '}}' },
    });

    // Get full text from document
    const fullText = doc.getFullText();

    // Extract placeholders using regex
    // Matches {{placeholder}}, {{#if condition}}, {{#each items}}, etc.
    const placeholderRegex = /\{\{[#\/]?(\w+)(?:\s+\w+)?\}\}/g;
    const matches = fullText.matchAll(placeholderRegex);

    const placeholders = new Set<string>();

    for (const match of matches) {
      const placeholder = match[1];
      // Filter out control structures (if, each, etc.)
      if (!['if', 'each', 'unless', 'with'].includes(placeholder)) {
        placeholders.add(placeholder);
      }
    }

    return Array.from(placeholders).sort();
  } catch (error: any) {
    if (error.code === 'ENOENT') {
      throw createError.notFound('Template file', templatePath);
    }
    throw createError.internal(
      `Failed to extract placeholders: ${error.message || 'Unknown error'}`
    );
  }
}

/**
 * Validate template data against placeholders
 * @param placeholders - Expected placeholders
 * @param data - Data to validate
 * @returns Array of missing placeholder names
 */
export function validateTemplateData(
  placeholders: string[],
  data: Record<string, any>
): string[] {
  const missing: string[] = [];

  for (const placeholder of placeholders) {
    // Check if placeholder exists in data (including formatters)
    if (!(placeholder in data) && !(placeholder in formatters)) {
      missing.push(placeholder);
    }
  }

  return missing;
}

/**
 * Get file size in bytes
 */
export async function getFileSize(filePath: string): Promise<number> {
  try {
    const stats = await fs.stat(filePath);
    return stats.size;
  } catch (error) {
    return 0;
  }
}

