// ============================================================================
// ENVELOPE BUILDER
// ============================================================================

export class EnvelopeBuilder {
  constructor(private provider: IEsignProvider) {}

  /**
   * Build and send signature envelope
   */
  async buildEnvelope(request: BuildEnvelopeRequest): Promise<CreateEnvelopeResponse> {
    const {
      runId,
      stepId,
      config,
      variableData,
      preview = false,
      returnUrl,
    } = request;

    // 1. Resolve documents
    const documents = await this.resolveDocuments(config.documents, variableData);

    // 2. Build signer info
    const signer = this.buildSignerInfo(config, variableData);

    // 3. Apply variable substitution to text fields
    const message = this.substituteVariables(config.message ?? '', variableData);

    // 4. Create envelope request
    const envelopeRequest: CreateEnvelopeRequest = {
      runId,
      stepId,
      documents,
      signer,
      variableData,
      message,
      expiresInDays: config.expiresInDays || 30,
      allowDecline: config.allowDecline ?? false,
      returnUrl: returnUrl || config.redirectUrl || undefined,
      preview,
    };

    // 5. Call provider to create envelope
    return this.provider.createEnvelope(envelopeRequest);
  }

  // --------------------------------------------------------------------------
  // DOCUMENT RESOLUTION
  // --------------------------------------------------------------------------

  /**
   * Resolve document sources from configuration
   */
  private async resolveDocuments(
    documentConfigs: SignatureBlockConfig['documents'],
    variableData: Record<string, any>
  ): Promise<SignatureDocument[]> {
    const documents: SignatureDocument[] = [];

    for (const docConfig of documentConfigs) {
      // Resolve document from various sources
      const source = await this.resolveDocumentSource(docConfig.documentId);

      if (!source) {
        console.warn(`[EnvelopeBuilder] Document not found: ${docConfig.documentId}`);
        continue;
      }

      documents.push({
        id: docConfig.id,
        name: source.name,
        filePath: source.filePath,
        mimeType: source.mimeType,
        mapping: docConfig.mapping,
      });
    }

    return documents;
  }

  /**
   * Resolve document source by ID
   * Can come from:
   * 1. Generated documents (Final Block output)
   * 2. Uploaded template library
   * 3. Workflow file attachments
   */
  private async resolveDocumentSource(documentId: string): Promise<DocumentSource | null> {
    // TODO: Implement document resolution logic
    // This should query:
    // 1. runGeneratedDocuments table for Final Block outputs
    // 2. templates table for uploaded templates
    // 3. File storage for workflow attachments

    // Placeholder implementation
    console.warn(`[EnvelopeBuilder] Document resolution not yet implemented: ${documentId}`);

    // For now, return a placeholder
    if (documentId === 'placeholder') {
      return null;
    }

    // Example return:
    return {
      id: documentId,
      name: 'Document.pdf',
      filePath: `/path/to/document/${documentId}.pdf`,
      mimeType: 'application/pdf',
    };
  }

  // --------------------------------------------------------------------------
  // SIGNER INFO
  // --------------------------------------------------------------------------

  /**
   * Build signer information with variable substitution
   */
  private buildSignerInfo(
    config: SignatureBlockConfig,
    variableData: Record<string, any>
  ): SignerInfo {
    return {
      role: config.signerRole,
      name: this.substituteVariables(config.signerName ?? '', variableData),
      email: this.substituteVariables(config.signerEmail ?? '', variableData),
      routingOrder: config.routingOrder || 1,
      signerId: undefined, // Will be set by signature request service
    };
  }

  // --------------------------------------------------------------------------
  // VARIABLE SUBSTITUTION
  // --------------------------------------------------------------------------

  /**
   * Replace {{variable}} placeholders with actual values
   */
  private substituteVariables(template: string, variableData: Record<string, any>): string {
    if (!template) {return template;}

    let result = template;

    // Replace {{variableName}} with values
    Object.entries(variableData).forEach(([key, value]) => {
      const regex = new RegExp(`{{\\s*${key}\\s*}}`, 'g');
      result = result.replace(regex, String(value ?? ''));
    });

    return result;
  }

  // --------------------------------------------------------------------------
  // ROUTING LOGIC
  // --------------------------------------------------------------------------

  /**
   * Determine if this signature block should execute now
   * based on routing order and previously completed signatures
   */
  static shouldExecuteBlock(
    currentBlock: SignatureBlockConfig,
    allSignatureBlocks: Array<{ config: SignatureBlockConfig; completed: boolean }>,
    currentRoutingOrder: number
  ): boolean {
    // All blocks with lower routing order must be completed
    const lowerOrderBlocks = allSignatureBlocks.filter(
      block => block.config.routingOrder < currentRoutingOrder
    );

    const allLowerOrderComplete = lowerOrderBlocks.every(block => block.completed);

    // This block must match current routing order
    const isCurrentOrder = currentBlock.routingOrder === currentRoutingOrder;

    return isCurrentOrder && allLowerOrderComplete;
  }

  /**
   * Get next routing order to execute
   */
  static getNextRoutingOrder(
    allSignatureBlocks: Array<{ config: SignatureBlockConfig; completed: boolean }>
  ): number {
    // Find the lowest routing order that's not fully completed
    const incompleteBlocks = allSignatureBlocks.filter(block => !block.completed);

    if (incompleteBlocks.length === 0) {
      return Infinity; // All done
    }

    return Math.min(
      ...incompleteBlocks.map(block => block.config.routingOrder)
    );
  }

  /**
   * Check if all signature blocks in workflow are completed
   */
  static allSignaturesComplete(
    allSignatureBlocks: Array<{ config: SignatureBlockConfig; completed: boolean }>
  ): boolean {
    return allSignatureBlocks.every(block => block.completed);
  }
}

/**
 * E-Signature Provider Interface
 * Defines the contract for all e-signature providers
 *
 * This interface allows ezBuildr to support multiple signature providers:
 * - DocuSign
 * - HelloSign (Dropbox Sign)
 * - Native signature UI
 * - Future providers
 *
 * @version 1.0.0 - Prompt 11 (E-Signature Integration)
 * @date December 2025
 */

// ============================================================================
// TYPES
// ============================================================================

/**
 * Document to be signed
 */
export interface SignatureDocument {
  /** Unique identifier for this document */
  id: string;

  /** Document name/title */
  name: string;

  /** File path or URL to the document */
  filePath: string;

  /** MIME type */
  mimeType: string;

  /** Variable-to-field mapping */
  mapping?: Record<string, {
    type: 'variable';
    source: string;
  }>;
}

/**
 * Signer information
 */
export interface SignerInfo {
  /** Signer's role (e.g., "Applicant", "Attorney") */
  role: string;

  /** Signer's full name */
  name?: string;

  /** Signer's email address */
  email?: string;

  /** Routing order (1, 2, 3...) - lower signs first */
  routingOrder: number;

  /** Unique identifier for this signer in the workflow run */
  signerId?: string;
}

/**
 * Envelope creation request
 */
export interface CreateEnvelopeRequest {
  /** Workflow run ID */
  runId: string;

  /** Signature block step ID */
  stepId: string;

  /** Documents to be signed */
  documents: SignatureDocument[];

  /** Signer information */
  signer: SignerInfo;

  /** Workflow variable data (for field pre-filling) */
  variableData: Record<string, any>;

  /** Custom message to signer */
  message?: string;

  /** Expiration in days */
  expiresInDays?: number;

  /** Allow signer to decline */
  allowDecline?: boolean;

  /** Return URL after signing */
  returnUrl?: string;

  /** Preview mode (don't actually send) */
  preview?: boolean;
}

/**
 * Envelope creation response
 */
export interface CreateEnvelopeResponse {
  /** Provider-specific envelope ID */
  envelopeId: string;

  /** URL for signer to access */
  signingUrl: string;

  /** Envelope status */
  status: 'created' | 'sent' | 'delivered' | 'signed' | 'completed' | 'declined' | 'voided';

  /** Provider-specific metadata */
  metadata?: Record<string, any>;
}

/**
 * Envelope status query response
 */
export interface EnvelopeStatusResponse {
  /** Provider-specific envelope ID */
  envelopeId: string;

  /** Current status */
  status: 'created' | 'sent' | 'delivered' | 'signed' | 'completed' | 'declined' | 'voided' | 'expired';

  /** Signer status */
  signerStatus?: 'pending' | 'signing' | 'signed' | 'declined';

  /** Signed document URLs (if completed) */
  signedDocumentUrls?: string[];

  /** Completion timestamp */
  completedAt?: Date;

  /** Provider-specific metadata */
  metadata?: Record<string, any>;
}

/**
 * Webhook/callback event
 */
export interface SignatureEvent {
  /** Event type */
  type: 'sent' | 'viewed' | 'signed' | 'declined' | 'completed' | 'voided' | 'expired';

  /** Provider-specific envelope ID */
  envelopeId: string;

  /** Timestamp */
  timestamp: Date;

  /** Event-specific data */
  data?: Record<string, any>;
}

// ============================================================================
// PROVIDER INTERFACE
// ============================================================================

/**
 * Abstract E-Signature Provider
 * All providers must implement this interface
 */
export interface IEsignProvider {
  /**
   * Provider name (e.g., "docusign", "hellosign", "native")
   */
  readonly name: string;

  /**
   * Create a new signature envelope
   * @param request Envelope creation parameters
   * @returns Envelope details and signing URL
   */
  createEnvelope(request: CreateEnvelopeRequest): Promise<CreateEnvelopeResponse>;

  /**
   * Get envelope status
   * @param envelopeId Provider-specific envelope ID
   * @returns Current envelope status
   */
  getEnvelopeStatus(envelopeId: string): Promise<EnvelopeStatusResponse>;

  /**
   * Cancel/void an envelope
   * @param envelopeId Provider-specific envelope ID
   * @param reason Cancellation reason
   */
  voidEnvelope(envelopeId: string, reason?: string): Promise<void>;

  /**
   * Download signed documents
   * @param envelopeId Provider-specific envelope ID
   * @returns Array of signed document buffers
   */
  downloadSignedDocuments(envelopeId: string): Promise<Buffer[]>;

  /**
   * Verify webhook/callback signature (for security)
   * @param payload Webhook payload
   * @param signature Signature header from provider
   * @returns True if signature is valid
   */
  verifyWebhookSignature(payload: any, signature: string): Promise<boolean>;

  /**
   * Parse webhook event
   * @param payload Webhook payload from provider
   * @returns Normalized signature event
   */
  parseWebhookEvent(payload: any): Promise<SignatureEvent>;
}

// ============================================================================
// PROVIDER FACTORY
// ============================================================================

/**
 * E-Signature Provider Factory
 * Instantiates the appropriate provider based on configuration
 */
export class EsignProviderFactory {
  private static providers: Map<string, IEsignProvider> = new Map();

  /**
   * Register a provider implementation
   */
  static registerProvider(name: string, provider: IEsignProvider): void {
    this.providers.set(name.toLowerCase(), provider);
  }

  /**
   * Get provider by name
   */
  static getProvider(name: string): IEsignProvider {
    const provider = this.providers.get(name.toLowerCase());
    if (!provider) {
      throw new Error(`E-signature provider not found: ${name}`);
    }
    return provider;
  }

  /**
   * Get all registered providers
   */
  static getAllProviders(): string[] {
    return Array.from(this.providers.keys());
  }

  /**
   * Check if provider exists
   */
  static hasProvider(name: string): boolean {
    return this.providers.has(name.toLowerCase());
  }
}

// ============================================================================
// ERROR CLASSES
// ============================================================================

/**
 * Base error for e-signature operations
 */
export class EsignError extends Error {
  constructor(
    message: string,
    public readonly code: string,
    public readonly provider?: string,
    public readonly details?: any
  ) {
    super(message);
    this.name = 'EsignError';
  }
}

/**
 * Provider configuration error
 */
export class EsignConfigError extends EsignError {
  constructor(message: string, provider?: string) {
    super(message, 'CONFIG_ERROR', provider);
    this.name = 'EsignConfigError';
  }
}

/**
 * API communication error
 */
export class EsignApiError extends EsignError {
  constructor(message: string, provider?: string, details?: any) {
    super(message, 'API_ERROR', provider, details);
    this.name = 'EsignApiError';
  }
}

/**
 * Invalid envelope state error
 */
export class EsignStateError extends EsignError {
  constructor(message: string, provider?: string) {
    super(message, 'STATE_ERROR', provider);
    this.name = 'EsignStateError';
  }
}

/**
 * Signature Block Service
 * High-level service for signature block execution in workflows
 *
 * Responsibilities:
 * - Execute signature blocks during workflow runs
 * - Create signature requests in database
 * - Integrate with e-signature providers
 * - Handle callbacks and status updates
 * - Manage multi-signer routing
 *
 * @version 1.0.0 - Prompt 11 (E-Signature Integration)
 * @date December 2025
 */

import { createLogger } from '../../logger';

import { EnvelopeBuilder } from './EnvelopeBuilder';
import { EsignProviderFactory } from './EsignProvider';

