/**
 * External Connections Service
 * Manages reusable API connection configurations for HTTP nodes
 */
import { eq, and } from 'drizzle-orm';

import { externalConnections, secrets } from '@shared/schema';

import { db } from '../db';

import { getSecretValueById } from './secrets';
/**
 * Connection with secret metadata (no plaintext values)
 */
export interface ConnectionWithSecret {
  id: string;
  projectId: string;
  name: string;
  baseUrl: string;
  authType: string;
  secretId: string | null;
  secretKey?: string; // Key name from secrets table
  defaultHeaders: Record<string, any>;
  timeoutMs: number | null;
  retries: number | null;
  backoffMs: number | null;
  createdAt: Date | null;
  updatedAt: Date | null;
}
/**
 * Input for creating a new connection
 */
export interface CreateConnectionInput {
  projectId: string;
  name: string;
  baseUrl: string;
  authType: 'api_key' | 'bearer' | 'oauth2' | 'basic_auth' | 'none';
  secretId?: string | null;
  defaultHeaders?: Record<string, string>;
  timeoutMs?: number;
  retries?: number;
  backoffMs?: number;
}
/**
 * Input for updating a connection
 */
export interface UpdateConnectionInput {
  name?: string;
  baseUrl?: string;
  authType?: 'api_key' | 'bearer' | 'oauth2' | 'basic_auth' | 'none';
  secretId?: string | null;
  defaultHeaders?: Record<string, string>;
  timeoutMs?: number;
  retries?: number;
  backoffMs?: number;
}
/**
 * List all external connections for a project
 */
export async function listConnections(projectId: string): Promise<ConnectionWithSecret[]> {
  const results = await db
    .select({
      connection: externalConnections,
    })
    .from(externalConnections)
    .where(eq(externalConnections.projectId, projectId));
  return results.map((r: any) => {
    const refs = (r.connection.secretRefs as Record<string, string>) || {};
    const mainSecretId = refs.main ?? null;
    return {
      id: r.connection.id,
      projectId: r.connection.projectId,
      name: r.connection.name,
      baseUrl: r.connection.baseUrl,
      authType: r.connection.type,
      secretId: mainSecretId,
      secretKey: undefined, // Cannot join efficiently yet
      defaultHeaders: (r.connection.defaultHeaders as Record<string, any>) || {},
      timeoutMs: r.connection.timeoutMs,
      retries: r.connection.retries,
      backoffMs: r.connection.backoffMs,
      createdAt: r.connection.createdAt,
      updatedAt: r.connection.updatedAt,
    };
  });
}
/**
 * Get a connection by ID
 */
export async function getConnection(projectId: string, connectionId: string): Promise<ConnectionWithSecret | null> {
  const results = await db
    .select({
      connection: externalConnections,
    })
    .from(externalConnections)
    .where(and(eq(externalConnections.id, connectionId), eq(externalConnections.projectId, projectId)));
  if (results.length === 0) { return null; }
  const r = results[0];
  const refs = (r.connection.secretRefs as Record<string, string>) || {};
  const mainSecretId = refs.main ?? null;
  return {
    id: r.connection.id,
    projectId: r.connection.projectId,
    name: r.connection.name,
    baseUrl: r.connection.baseUrl ?? '',
    authType: r.connection.type ?? '',
    secretId: mainSecretId,
    secretKey: undefined,
    defaultHeaders: (r.connection.defaultHeaders as Record<string, any>) || {},
    timeoutMs: r.connection.timeoutMs,
    retries: r.connection.retries,
    backoffMs: r.connection.backoffMs,
    createdAt: r.connection.createdAt,
    updatedAt: r.connection.updatedAt,
  };
}
/**
 * Get connection by name
 */
export async function getConnectionByName(projectId: string, name: string): Promise<ConnectionWithSecret | null> {
  const results = await db
    .select({
      connection: externalConnections,
    })
    .from(externalConnections)
    .where(and(eq(externalConnections.projectId, projectId), eq(externalConnections.name, name)));
  if (results.length === 0) { return null; }
  const r = results[0];
  const refs = (r.connection.secretRefs as Record<string, string>) || {};
  const mainSecretId = refs.main ?? null;
  return {
    id: r.connection.id,
    projectId: r.connection.projectId,
    name: r.connection.name,
    baseUrl: r.connection.baseUrl ?? '',
    authType: r.connection.type ?? '',
    secretId: mainSecretId,
    secretKey: undefined,
    defaultHeaders: (r.connection.defaultHeaders as Record<string, any>) || {},
    timeoutMs: r.connection.timeoutMs,
    retries: r.connection.retries,
    backoffMs: r.connection.backoffMs,
    createdAt: r.connection.createdAt,
    updatedAt: r.connection.updatedAt,
  };
}
/**
 * Check if a connection name already exists
 */
export async function connectionNameExists(projectId: string, name: string, excludeId?: string): Promise<boolean> {
  const results = await db
    .select({ id: externalConnections.id })
    .from(externalConnections)
    .where(and(eq(externalConnections.projectId, projectId), eq(externalConnections.name, name)));
  if (excludeId) {
    return results.some((r: any) => r.id !== excludeId);
  }
  return results.length > 0;
}
/**
 * Create a new external connection
 */
export async function createConnection(input: CreateConnectionInput): Promise<ConnectionWithSecret> {
  // Check for duplicate name
  const exists = await connectionNameExists(input.projectId, input.name);
  if (exists) {
    throw new Error(`Connection with name '${input.name}' already exists in this project`);
  }
  // Validate secret if provided
  if (input.secretId) {
    const results = await db
      .select({ id: secrets.id })
      .from(secrets)
      .where(and(eq(secrets.id, input.secretId), eq(secrets.projectId, input.projectId)));
    if (results.length === 0) {
      throw new Error('Secret not found in this project');
    }
  }
  // Insert
  const [result] = await db
    .insert(externalConnections)
    .values({
      projectId: input.projectId,
      name: input.name,
      baseUrl: input.baseUrl,
      type: input.authType as any, // Cast to match schema enum
      secretRefs: input.secretId ? { main: input.secretId } : {},
      defaultHeaders: input.defaultHeaders || {},
      timeoutMs: input.timeoutMs ?? 8000,
      retries: input.retries ?? 2,
      backoffMs: input.backoffMs ?? 250,
    } as any) // Explicit cast for schema mismatch
    .returning();
  // Get with secret key
  const connection = await getConnection(input.projectId, result.id);
  if (!connection) {
    throw new Error('Failed to create connection');
  }
  return connection;
}
/**
 * Update an external connection
 */
export async function updateConnection(
  projectId: string,
  connectionId: string,
  input: UpdateConnectionInput
): Promise<ConnectionWithSecret> {
  // Check if connection exists
  const existing = await getConnection(projectId, connectionId);
  if (!existing) {
    throw new Error('Connection not found');
  }
  // Check for duplicate name if name is being changed
  if (input.name && input.name !== existing.name) {
    const exists = await connectionNameExists(projectId, input.name, connectionId);
    if (exists) {
      throw new Error(`Connection with name '${input.name}' already exists in this project`);
    }
  }
  // Validate secret if provided
  if (input.secretId) {
    const results = await db
      .select({ id: secrets.id })
      .from(secrets)
      .where(and(eq(secrets.id, input.secretId), eq(secrets.projectId, projectId)));
    if (results.length === 0) {
      throw new Error('Secret not found in this project');
    }
  }
  // Build update object
  const updates: Partial<any> = {}; // using any to bypass schema strictness for now
  if (input.name !== undefined) { updates.name = input.name; }
  if (input.baseUrl !== undefined) { updates.baseUrl = input.baseUrl; }
  if (input.authType !== undefined) { updates.type = input.authType; }
  if (input.secretId !== undefined) {
    updates.secretRefs = input.secretId ? { main: input.secretId } : {};
  }
  if (input.defaultHeaders !== undefined) { updates.defaultHeaders = input.defaultHeaders; }
  if (input.timeoutMs !== undefined) { updates.timeoutMs = input.timeoutMs; }
  if (input.retries !== undefined) { updates.retries = input.retries; }
  if (input.backoffMs !== undefined) { updates.backoffMs = input.backoffMs; }
  // Update
  const [result] = await db
    .update(externalConnections)
    .set(updates)
    .where(and(eq(externalConnections.id, connectionId), eq(externalConnections.projectId, projectId)))
    .returning();
  if (!result) {
    throw new Error('Failed to update connection');
  }
  // Get with secret key
  const connection = await getConnection(projectId, result.id);
  if (!connection) {
    throw new Error('Failed to retrieve updated connection');
  }
  return connection;
}
/**
 * Delete an external connection
 */
export async function deleteConnection(projectId: string, connectionId: string): Promise<boolean> {
  const result = await db
    .delete(externalConnections)
    .where(and(eq(externalConnections.id, connectionId), eq(externalConnections.projectId, projectId)))
    .returning({ id: externalConnections.id });
  return result.length > 0;
}
/**
 * Resolve a connection with its secret value (for execution)
 * WARNING: Returns decrypted secret value. Only use for workflow execution.
 */
export interface ResolvedConnection {
  id: string;
  name: string;
  baseUrl: string;
  authType: string;
  secretValue?: string; // Decrypted secret value
  defaultHeaders: Record<string, any>;
  timeoutMs: number;
  retries: number;
  backoffMs: number;
}
export async function resolveConnection(
  projectId: string,
  connectionId: string
): Promise<ResolvedConnection | null> {
  const connection = await getConnection(projectId, connectionId);
  if (!connection) { return null; }
  let secretValue: string | undefined;
  if (connection.secretId) {
    const value = await getSecretValueById(projectId, connection.secretId);
    secretValue = value ?? undefined;
  }
  return {
    id: connection.id,
    name: connection.name,
    baseUrl: connection.baseUrl,
    authType: connection.authType,
    secretValue,
    defaultHeaders: connection.defaultHeaders,
    timeoutMs: connection.timeoutMs ?? 8000,
    retries: connection.retries ?? 2,
    backoffMs: connection.backoffMs ?? 250,
  };
}

import { randomUUID } from 'crypto';
import fs from 'fs';
import os from 'os';
import path from 'path';
import { promisify } from 'util';

import multer from 'multer';

import { logger } from '../logger';

const unlinkAsync = promisify(fs.unlink);
const mkdirAsync = promisify(fs.mkdir);

// Standard ESM import for multer v2
const multerInstance = multer;

// File upload configuration
export const UPLOAD_DIR = process.env.UPLOAD_DIR || './uploads';
export const MAX_FILE_SIZE = process.env.MAX_FILE_SIZE ?
  parseInt(process.env.MAX_FILE_SIZE, 10) :
  10 * 1024 * 1024; // 10MB default
export const ALLOWED_FILE_TYPES = [
  'image/jpeg',
  'image/png',
  'image/gif',
  'application/pdf',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.ms-excel',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'text/plain',
  'text/csv'
];

// Ensure upload directory exists
async function ensureUploadDir() {
  try {
    await fs.promises.access(UPLOAD_DIR);
  } catch {
    await mkdirAsync(UPLOAD_DIR, { recursive: true });
  }
}

// Configure multer storage
const storage = multerInstance.diskStorage({
  destination: async (req: Express.Request, file: Express.Multer.File, cb: (error: Error | null, destination: string) => void) => {
    await ensureUploadDir();
    cb(null, UPLOAD_DIR);
  },
  filename: (req: Express.Request, file: Express.Multer.File, cb: (error: Error | null, filename: string) => void) => {
    // Generate unique filename while preserving extension
    const ext = path.extname(file.originalname);
    const filename = `${randomUUID()}${ext}`;
    cb(null, filename);
  }
});

// File filter for validation
const fileFilter = (req: any, file: Express.Multer.File, cb: multer.FileFilterCallback) => {
  // Check file type
  if (!ALLOWED_FILE_TYPES.includes(file.mimetype)) {
    return cb(new Error(`File type ${file.mimetype} is not allowed`));
  }

  cb(null, true);
};

// Create multer instance
export const upload = multerInstance({
  storage,
  fileFilter,
  limits: {
    fileSize: MAX_FILE_SIZE,
    files: 5 // Max 5 files per request
  }
});

// Validate file upload configuration
export function validateFileUploadConfig(config: any) {
  if (!config) { return true; } // No restrictions

  const errors: string[] = [];

  if (config.maxFileSize && typeof config.maxFileSize !== 'number') {
    errors.push('maxFileSize must be a number');
  }

  if (config.maxFiles && typeof config.maxFiles !== 'number') {
    errors.push('maxFiles must be a number');
  }

  if (config.acceptedTypes && !Array.isArray(config.acceptedTypes)) {
    errors.push('acceptedTypes must be an array');
  }

  return errors.length === 0 ? true : errors.join(', ');
}

// Check if file type matches accepted types
export function isFileTypeAccepted(mimeType: string, acceptedTypes?: string[]): boolean {
  if (!acceptedTypes || acceptedTypes.length === 0) {
    return ALLOWED_FILE_TYPES.includes(mimeType);
  }

  return acceptedTypes.some(type => {
    if (type.includes('*')) {
      // Handle wildcards like 'image/*'
      const [category] = type.split('/');
      return mimeType.startsWith(`${category}/`);
    }

    if (type.startsWith('.')) {
      // Handle extensions like '.pdf'
      const extension = type;
      // Get mime type for extension (simplified mapping)
      const mimeTypeMap: Record<string, string> = {
        '.pdf': 'application/pdf',
        '.doc': 'application/msword',
        '.docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
        '.jpg': 'image/jpeg',
        '.jpeg': 'image/jpeg',
        '.png': 'image/png',
        '.gif': 'image/gif',
        '.txt': 'text/plain',
        '.csv': 'text/csv'
      };
      return mimeTypeMap[extension] === mimeType;
    }

    return type === mimeType;
  });
}

// Delete file from filesystem
export async function deleteFile(filename: string): Promise<void> {
  const filePath = path.join(UPLOAD_DIR, filename);
  try {
    await unlinkAsync(filePath);
  } catch (error) {
    logger.error({ error }, 'Error deleting file');
    // Don't throw error if file doesn't exist
  }
}

// Get file path
export function getFilePath(filename: string): string {
  return path.join(UPLOAD_DIR, filename);
}

// Check if file exists
export async function fileExists(filename: string): Promise<boolean> {
  try {
    await fs.promises.access(path.join(UPLOAD_DIR, filename));
    return true;
  } catch {
    return false;
  }
}

// Get file stats
export async function getFileStats(filename: string) {
  try {
    const filePath = path.join(UPLOAD_DIR, filename);
    const stats = await fs.promises.stat(filePath);
    return {
      size: stats.size,
      created: stats.birthtime,
      modified: stats.mtime
    };
  } catch {
    return null;
  }
}

/**
 * Scan specific directories and cleanup files older than maxAgeMs
 */
export async function cleanupTempFiles(maxAgeMs = 3600000): Promise<number> {
  const dirsToClean = [
    UPLOAD_DIR,
    path.join(process.cwd(), 'server', 'files', 'outputs', 'previews'),
    os.tmpdir()
  ];

  let cleaned = 0;
  const now = Date.now();

  for (const dir of dirsToClean) {
    try {
      await fs.promises.access(dir).catch(() => null);
      const files = await fs.promises.readdir(dir);

      for (const file of files) {
        const isSystemTemp = dir === os.tmpdir();
        // Prefixes used by our app in temp
        // file- : multer default (we changed to fieldname-...) fieldname is 'file' so 'file-'
        // preview- : TemplatePreviewService
        // upload- : some other uploads?
        // rec- : recording?
        const safePrefixes = ['file-', 'preview-', 'upload-', 'rec-'];

        if (isSystemTemp && !safePrefixes.some(p => file.startsWith(p))) {
          continue;
        }

        const filePath = path.join(dir, file);
        try {
          const stats = await fs.promises.stat(filePath);
          if (now - stats.mtimeMs > maxAgeMs) {
            await fs.promises.unlink(filePath);
            cleaned++;
          }
        } catch (e) {
          // Ignore
        }
      }
    } catch (e) {
      logger.warn({ dir, error: e }, 'Failed to scan temp dir for cleanup');
    }
  }
  return cleaned;
}

