export interface ExecutionContext {
    workflowId: string;
    runId: string;
    userId?: string;
    mode: 'live' | 'preview';
}
export class RunExecutionCoordinator {
    constructor(
        private persistence = runPersistenceWriter,
        private logicSvc = logicService,
        private stepRepo = stepRepository,
        private sectionRepo = sectionRepository,
        private workflowRepo = workflowRepository
    ) { }
    /**
     * Calculate next step/section
     */
    async next(context: ExecutionContext, currentSectionId: string | null): Promise<NavigationResult> {
        const { runId, workflowId, mode } = context;
        // Get current data
        const dataMap = await this.persistence.getRunValues(runId);
        // 1. Execute JS Questions for current section (if any)
        if (currentSectionId) {
            await this.executeJsQuestions(runId, currentSectionId, dataMap, context);
        }
        // 2. Execute onNext blocks
        // Note: BlockRunner still needs refactoring to accept Mode, but for now we pass context
        // Ideally BlockRunner should be stateless or accept context
        const aliasMap = await this.getAliasMap(workflowId);
        const blockResult = await blockRunner.runPhase({
            workflowId,
            runId,
            phase: "onNext",
            sectionId: currentSectionId ?? undefined,
            data: dataMap,
            mode, // Pass execution mode
            aliasMap,
        });
        // 3. Determine Navigation
        let navigation: NavigationResult;
        if (blockResult.nextSectionId) {
            navigation = {
                nextSectionId: blockResult.nextSectionId,
                currentProgress: 0,
                visibleSections: [],
                visibleSteps: [],
                requiredSteps: [],
            };
        } else {
            navigation = await this.logicSvc.evaluateNavigation(
                workflowId,
                runId,
                currentSectionId
            );
        }
        // 4. Update Run State (RunService usually does this, but Coordinator can orchestrate)
        // Coordinator returns the result, caller (RunService fa├ºade) might save state?
        // Or Coordinator delegates to Persistence?
        // Let's delegate to Persistence to keep it "Coordinator"
        if (navigation.nextSectionId !== currentSectionId) {
            await this.persistence.updateRun(runId, {
                currentSectionId: navigation.nextSectionId,
                progress: navigation.currentProgress
            });
        }
        return navigation;
    }
    /**
     * Submit data for a section
     */
    async submitSection(
        context: ExecutionContext,
        sectionId: string,
        values: Array<{ stepId: string, value: any }>
    ): Promise<{ success: boolean; errors?: string[] }> {
        const { runId, workflowId } = context;
        // 1. Persist Values
        await this.persistence.bulkSaveValues(runId, values, workflowId);
        // 2. Get updated data map
        const dataMap = await this.persistence.getRunValues(runId);
        const aliasMap = await this.getAliasMap(workflowId);
        // 3. Validate required fields (respecting visibility)
        const steps = await this.stepRepo.findBySectionId(sectionId);
        const visibility = await intakeQuestionVisibilityService.evaluatePageQuestions(
            sectionId,
            runId,
            dataMap
        );
        const validationResult = validatePage(
            steps,
            dataMap,
            visibility.visibleQuestions
        );
        if (!validationResult.valid) {
            // Format errors for user-friendly display
            const errorMessages = validationResult.errors.map(err => {
                const step = steps.find(s => s.id === err.fieldId);
                const fieldName = step?.title || 'Field';
                // Take first error message for each field
                return `${fieldName}: ${err.errors[0]}`;
            });
            logger.warn({ runId, sectionId, errors: errorMessages }, "Section validation failed");
            return { success: false, errors: errorMessages };
        }
        // 4. Execute JS Questions
        const jsResult = await this.executeJsQuestions(runId, sectionId, dataMap, context, aliasMap);
        if (!jsResult.success) {
            return { success: false, errors: jsResult.errors };
        }
        // 5. Execute onSectionSubmit blocks
        const blockResult = await blockRunner.runPhase({
            workflowId,
            runId,
            phase: "onSectionSubmit",
            sectionId,
            data: dataMap,
            mode: context.mode, // Pass execution mode
            aliasMap,
        });
        return {
            success: blockResult.success,
            errors: blockResult.errors,
        };
    }
    /**
     * Execute JS questions using ScriptEngine
     */
    private async executeJsQuestions(
        runId: string,
        sectionId: string,
        dataMap: Record<string, any>,
        context: ExecutionContext,
        aliasMap?: Record<string, string>
    ): Promise<{ success: boolean; errors?: string[] }> {
        const errors: string[] = [];
        // Find JS questions
        const allSteps = await this.stepRepo.findBySectionId(sectionId);
        const jsQuestions = allSteps.filter(step => step.type === 'js_question');
        for (const step of jsQuestions) {
            if (!step.options || !isJsQuestionConfig(step.options)) { continue; }
            const config = step.options;
            const result = await scriptEngine.execute({
                language: 'javascript',
                code: config.code,
                inputKeys: config.inputKeys,
                data: dataMap,
                context: {
                    workflowId: context.workflowId,
                    runId,
                    phase: 'question_execution',
                    metadata: { stepId: step.id }
                },
                timeoutMs: config.timeoutMs || 1000,
                aliasMap,
            });
            if (!result.ok) {
                errors.push(`JS Question "${step.title}" failed: ${result.error}`);
                continue;
            }
            // Save output
            await this.persistence.saveStepValue(
                runId,
                step.id,
                result.output,
                context.workflowId
            );
            dataMap[step.id] = result.output; // Update local map
        }
        return {
            success: errors.length === 0,
            errors: errors.length > 0 ? errors : undefined
        };
    }
    /**
     * Build alias map for workflow
     */
    private async getAliasMap(workflowId: string): Promise<Record<string, string>> {
        const sections = await this.sectionRepo.findByWorkflowId(workflowId);
        const sectionIds = sections.map(s => s.id);
        const steps = await this.stepRepo.findBySectionIds(sectionIds);
        const map: Record<string, string> = {};
        for (const step of steps) {
            if (step.alias) {
                map[step.alias] = step.id;
            }
        }
        return map;
    }
}
export const runExecutionCoordinator = new RunExecutionCoordinator();

/**
 * Document Hook Service
 * Manages document hooks and their execution during document generation
 */

import type {
  DocumentHook,
  DocumentHookPhase,
  DocumentHookExecutionResult,
  CreateDocumentHookInput,
  UpdateDocumentHookInput,
  TestHookInput,
  TestHookResult,
} from "@shared/types/scripting";

import { logger } from "../../logger";
import { documentHookRepository } from "../../repositories/DocumentHookRepository";
import { scriptExecutionLogRepository } from "../../repositories/ScriptExecutionLogRepository";
import { workflowRepository } from "../../repositories/WorkflowRepository";

import { scriptEngine } from "./ScriptEngine";

export class DocumentHookService {
  /**
   * Execute all hooks for a given phase
   * Non-breaking: continues on errors and collects them
   */
  async executeHooksForPhase(params: {
    workflowId: string;
    runId: string;
    phase: DocumentHookPhase;
    documentId?: string;
    data: Record<string, any>;
    userId?: string;
  }): Promise<DocumentHookExecutionResult> {
    const { workflowId, runId, phase, documentId, data, userId } = params;

    try {
      // Fetch enabled hooks for this phase
      const hooks = await documentHookRepository.findEnabledByPhase(
        workflowId,
        phase,
        documentId
      );

      if (hooks.length === 0) {
        return {
          success: true,
          data,
        };
      }

      logger.debug(
        {
          workflowId,
          runId,
          phase,
          documentId,
          hookCount: hooks.length,
        },
        "DocumentHookService: Executing hooks for phase"
      );

      const errors: Array<{ hookId: string; hookName: string; error: string }> = [];
      const consoleOutput: Array<{ hookName: string; logs: any[][] }> = [];
      let resultData = { ...data };

      // Execute hooks sequentially in order
      for (const hook of hooks) {
        const hookStartTime = Date.now();

        try {
          // Execute the hook
          const result = await scriptEngine.execute({
            language: hook.language,
            code: hook.code,
            inputKeys: hook.inputKeys,
            data: resultData,
            context: {
              workflowId,
              runId,
              phase,
              userId,
              metadata: documentId ? { documentId } : {},
            },
            timeoutMs: hook.timeoutMs || 3000,
            consoleEnabled: true,
          });

          const durationMs = Date.now() - hookStartTime;

          if (result.ok) {
            // Merge output into resultData
            if (result.output && typeof result.output === "object" && result.output !== null) {
              resultData = { ...resultData, ...result.output };
            } else if (result.output !== undefined && hook.outputKeys.length > 0) {
              // Single value output
              const key = hook.outputKeys[0];
              if (key) {resultData[key] = result.output;}
            }

            // Collect console logs
            if (result.consoleLogs && result.consoleLogs.length > 0) {
              consoleOutput.push({
                hookName: hook.name,
                logs: result.consoleLogs,
              });
            }

            // Log successful execution
            await this.logExecution({
              runId,
              scriptType: "document_hook",
              scriptId: hook.id,
              scriptName: hook.name,
              phase,
              status: "success",
              consoleOutput: result.consoleLogs,
              inputSample: this.truncateSample(data),
              outputSample: this.truncateSample(result.output),
              durationMs,
            });

            logger.debug(
              {
                hookId: hook.id,
                hookName: hook.name,
                durationMs,
              },
              "DocumentHookService: Hook executed successfully"
            );
          } else {
            // Hook failed
            errors.push({
              hookId: hook.id,
              hookName: hook.name,
              error: result.error || "Unknown error",
            });

            // Log error
            await this.logExecution({
              runId,
              scriptType: "document_hook",
              scriptId: hook.id,
              scriptName: hook.name,
              phase,
              status: result.error?.includes("Timeout") ? "timeout" : "error",
              errorMessage: result.error,
              durationMs,
            });

            logger.warn(
              {
                hookId: hook.id,
                hookName: hook.name,
                error: result.error,
              },
              "DocumentHookService: Hook execution failed"
            );
          }
        } catch (error) {
          // Unexpected error during hook execution
          const errorMessage = error instanceof Error ? error.message : "Unknown error";
          errors.push({
            hookId: hook.id,
            hookName: hook.name,
            error: errorMessage,
          });

          await this.logExecution({
            runId,
            scriptType: "document_hook",
            scriptId: hook.id,
            scriptName: hook.name,
            phase,
            status: "error",
            errorMessage,
            durationMs: Date.now() - hookStartTime,
          });

          logger.error(
            {
              hookId: hook.id,
              hookName: hook.name,
              error,
            },
            "DocumentHookService: Unexpected error during hook execution"
          );
        }
      }

      return {
        success: errors.length === 0,
        data: resultData,
        errors: errors.length > 0 ? errors : undefined,
        consoleOutput: consoleOutput.length > 0 ? consoleOutput : undefined,
      };
    } catch (error) {
      logger.error(
        {
          error,
          workflowId,
          runId,
          phase,
        },
        "DocumentHookService: Failed to execute hooks for phase"
      );

      // Non-breaking: return original data on error
      return {
        success: false,
        data,
        errors: [
          {
            hookId: "system",
            hookName: "System Error",
            error: error instanceof Error ? error.message : "Unknown error",
          },
        ],
      };
    }
  }

  /**
   * Create a new document hook
   */
  async createHook(
    workflowId: string,
    userId: string,
    data: CreateDocumentHookInput
  ): Promise<DocumentHook> {
    // Verify workflow ownership
    const workflow = await workflowRepository.findById(workflowId);
    if (!workflow) {
      throw new Error("Workflow not found");
    }
    if (workflow.creatorId && workflow.creatorId !== userId) {
      throw new Error("Unauthorized: You do not own this workflow");
    }

    // Create hook
    const hook = await documentHookRepository.create({
      ...data,
      workflowId,
    });

    logger.info(
      {
        hookId: hook.id,
        workflowId,
        phase: hook.phase,
      },
      "DocumentHookService: Created document hook"
    );

    return hook as DocumentHook;
  }

  /**
   * Update a document hook
   */
  async updateHook(
    hookId: string,
    userId: string,
    data: UpdateDocumentHookInput
  ): Promise<DocumentHook> {
    // Get hook and verify ownership
    const hook = await documentHookRepository.findByIdWithWorkflow(hookId);
    if (!hook) {
      throw new Error("Hook not found");
    }

    const workflow = await workflowRepository.findById(hook.workflowId);
    if (!workflow || (workflow.creatorId && workflow.creatorId !== userId)) {
      throw new Error("Unauthorized: You do not own this workflow");
    }

    // Update hook
    const updated = await documentHookRepository.update(hookId, data);

    logger.info(
      {
        hookId,
        workflowId: hook.workflowId,
      },
      "DocumentHookService: Updated document hook"
    );

    return updated as DocumentHook;
  }

  /**
   * Delete a document hook
   */
  async deleteHook(hookId: string, userId: string): Promise<void> {
    // Get hook and verify ownership
    const hook = await documentHookRepository.findByIdWithWorkflow(hookId);
    if (!hook) {
      throw new Error("Hook not found");
    }

    const workflow = await workflowRepository.findById(hook.workflowId);
    if (!workflow || (workflow.creatorId && workflow.creatorId !== userId)) {
      throw new Error("Unauthorized: You do not own this workflow");
    }

    // Delete hook
    await documentHookRepository.delete(hookId);

    logger.info(
      {
        hookId,
        workflowId: hook.workflowId,
      },
      "DocumentHookService: Deleted document hook"
    );
  }

  /**
   * Test a hook with sample data
   */
  async testHook(
    hookId: string,
    userId: string,
    testInput: TestHookInput
  ): Promise<TestHookResult> {
    // Get hook and verify ownership
    const hook = await documentHookRepository.findByIdWithWorkflow(hookId);
    if (!hook) {
      throw new Error("Hook not found");
    }

    const workflow = await workflowRepository.findById(hook.workflowId);
    if (!workflow || (workflow.creatorId && workflow.creatorId !== userId)) {
      throw new Error("Unauthorized: You do not own this workflow");
    }

    // Execute hook with test data
    const result = await scriptEngine.execute({
      language: hook.language,
      code: hook.code,
      inputKeys: hook.inputKeys,
      data: testInput.testData,
      context: {
        workflowId: testInput.context?.workflowId || hook.workflowId,
        runId: testInput.context?.runId || "test-run",
        phase: testInput.context?.phase || hook.phase,
        userId: testInput.context?.userId,
        metadata: testInput.context?.metadata,
      },
      timeoutMs: hook.timeoutMs || 3000,
      consoleEnabled: true,
    });

    return {
      success: result.ok,
      output: result.output,
      error: result.error,
      consoleLogs: result.consoleLogs,
      durationMs: result.durationMs,
    };
  }

  /**
   * List all hooks for a workflow
   */
  async listHooks(workflowId: string, userId: string): Promise<DocumentHook[]> {
    // Verify workflow ownership
    const workflow = await workflowRepository.findById(workflowId);
    if (!workflow) {
      throw new Error("Workflow not found");
    }
    if (workflow.creatorId && workflow.creatorId !== userId) {
      throw new Error("Unauthorized: You do not own this workflow");
    }

    return (await documentHookRepository.findByWorkflowId(workflowId)) as DocumentHook[];
  }

  /**
   * Log script execution to database
   */
  private async logExecution(params: {
    runId: string;
    scriptType: string;
    scriptId: string;
    scriptName?: string;
    phase?: string;
    status: "success" | "error" | "timeout";
    errorMessage?: string;
    consoleOutput?: any[][];
    inputSample?: any;
    outputSample?: any;
    durationMs?: number;
  }): Promise<void> {
    try {
      await scriptExecutionLogRepository.createLog({
        runId: params.runId,
        scriptType: params.scriptType,
        scriptId: params.scriptId,
        scriptName: params.scriptName,
        phase: params.phase,
        status: params.status,
        errorMessage: params.errorMessage,
        consoleOutput: params.consoleOutput
          ? JSON.parse(JSON.stringify(params.consoleOutput))
          : null,
        inputSample: params.inputSample,
        outputSample: params.outputSample,
        durationMs: params.durationMs,
      });
    } catch (error) {
      logger.error(
        {
          error,
          scriptId: params.scriptId,
        },
        "DocumentHookService: Failed to log execution"
      );
      // Non-fatal: don't throw
    }
  }

  /**
   * Truncate sample data to first 1KB
   */
  private truncateSample(data: any): any {
    if (data === undefined || data === null) {
      return null;
    }

    try {
      const json = JSON.stringify(data);
      if (json.length > 1024) {
        return JSON.parse(`${json.slice(0, 1024)}...`);
      }
      return data;
    } catch {
      return null;
    }
  }
}

// Singleton instance
export const documentHookService = new DocumentHookService();

/**
 * Helper Library for Custom Scripting System
 * Provides safe utility functions available in script sandbox
 */

import {
  addDays,
  addHours,
  addMinutes,
  addSeconds,
  addMonths,
  addYears,
  subDays,
  subHours,
  subMinutes,
  subSeconds,
  subMonths,
  subYears,
  differenceInDays,
  differenceInHours,
  differenceInMinutes,
  differenceInSeconds,
  differenceInMonths,
  differenceInYears,
  format as formatDate,
  parseISO,
  parse as parseDateFns,
} from "date-fns";

import type { HelperLibraryAPI } from "@shared/types/scripting";

// ===================================================================
// CONSOLE CAPTURE
// ===================================================================

/**
 * Create console helpers that capture output
 */
export function createConsoleHelpers(): {
  helpers: { log: (...args: any[]) => void; warn: (...args: any[]) => void; error: (...args: any[]) => void };
  getLogs: () => any[][];
} {
  const logs: any[][] = [];

  return {
    helpers: {
      log: (...args: any[]) => {
        logs.push(args);
      },
      warn: (...args: any[]) => {
        logs.push(["[WARN]", ...args]);
      },
      error: (...args: any[]) => {
        logs.push(["[ERROR]", ...args]);
      },
    },
    getLogs: () => logs,
  };
}

// ===================================================================
// DATE HELPERS
// ===================================================================

const dateHelpers = {
  now: (): string => {
    return new Date().toISOString();
  },

  add: (date: string, value: number, unit: "days" | "hours" | "minutes" | "seconds" | "months" | "years"): string => {
    try {
      const parsedDate = parseISO(date);
      let result: Date;

      switch (unit) {
        case "days":
          result = addDays(parsedDate, value);
          break;
        case "hours":
          result = addHours(parsedDate, value);
          break;
        case "minutes":
          result = addMinutes(parsedDate, value);
          break;
        case "seconds":
          result = addSeconds(parsedDate, value);
          break;
        case "months":
          result = addMonths(parsedDate, value);
          break;
        case "years":
          result = addYears(parsedDate, value);
          break;
        default:
          throw new Error(`Unknown unit: ${unit}`);
      }

      return result.toISOString();
    } catch (error) {
      return "Invalid Date";
    }
  },

  subtract: (date: string, value: number, unit: "days" | "hours" | "minutes" | "seconds" | "months" | "years"): string => {
    try {
      const parsedDate = parseISO(date);
      let result: Date;

      switch (unit) {
        case "days":
          result = subDays(parsedDate, value);
          break;
        case "hours":
          result = subHours(parsedDate, value);
          break;
        case "minutes":
          result = subMinutes(parsedDate, value);
          break;
        case "seconds":
          result = subSeconds(parsedDate, value);
          break;
        case "months":
          result = subMonths(parsedDate, value);
          break;
        case "years":
          result = subYears(parsedDate, value);
          break;
        default:
          throw new Error(`Unknown unit: ${unit}`);
      }

      return result.toISOString();
    } catch (error) {
      return "Invalid Date";
    }
  },

  format: (date: string, formatString: string): string => {
    try {
      const parsedDate = parseISO(date);
      return formatDate(parsedDate, formatString);
    } catch (error) {
      return "Invalid Date";
    }
  },

  parse: (dateString: string, formatString?: string): string => {
    try {
      if (formatString) {
        // Use date-fns parse with format string
        // Use UTC midnight as reference date to avoid timezone issues
        const referenceDate = new Date(Date.UTC(2000, 0, 1));
        const parsed = parseDateFns(dateString, formatString, referenceDate);

        // Convert to UTC by manually constructing ISO string
        const year = parsed.getFullYear();
        const month = String(parsed.getMonth() + 1).padStart(2, '0');
        const day = String(parsed.getDate()).padStart(2, '0');
        return `${year}-${month}-${day}T00:00:00.000Z`;
      } else {
        // Fallback to native Date parsing
        return new Date(dateString).toISOString();
      }
    } catch (error) {
      return "Invalid Date";
    }
  },

  diff: (date1: string, date2: string, unit: "days" | "hours" | "minutes" | "seconds" | "months" | "years"): number => {
    try {
      const parsed1 = parseISO(date1);
      const parsed2 = parseISO(date2);

      // Return absolute difference (always positive)
      let result: number;
      switch (unit) {
        case "days":
          result = differenceInDays(parsed2, parsed1);
          break;
        case "hours":
          result = differenceInHours(parsed2, parsed1);
          break;
        case "minutes":
          result = differenceInMinutes(parsed2, parsed1);
          break;
        case "seconds":
          result = differenceInSeconds(parsed2, parsed1);
          break;
        case "months":
          result = differenceInMonths(parsed2, parsed1);
          break;
        case "years":
          result = differenceInYears(parsed2, parsed1);
          break;
        default:
          throw new Error(`Unknown unit: ${unit}`);
      }
      return result;
    } catch (error) {
      return 0;
    }
  },
};

// ===================================================================
// STRING HELPERS
// ===================================================================

const stringHelpers = {
  upper: (str: string): string => (str ? str.toUpperCase() : ""),

  lower: (str: string): string => str.toLowerCase(),

  trim: (str: string): string => str.trim(),

  replace: (str: string, search: string | RegExp, replacement: string): string => {
    // Replace all occurrences by default
    if (typeof search === 'string') {
      return str.replaceAll(search, replacement);
    } else {
      // For RegExp, use global flag
      return str.replace(search, replacement);
    }
  },

  split: (str: string, separator: string): string[] => {
    return str.split(separator);
  },

  join: (arr: string[], separator: string): string => {
    return arr.join(separator);
  },

  slug: (str: string): string => {
    return str
      .toLowerCase()
      .replace(/\s+/g, "-")
      .replace(/[^a-z0-9-]/g, "");
  },

  capitalize: (str: string): string => {
    if (!str) { return str; }
    return str.charAt(0).toUpperCase() + str.slice(1).toLowerCase();
  },

  truncate: (str: string, length: number): string => {
    if (str.length <= length) { return str; }
    return `${str.slice(0, length)}...`;
  },
};

// ===================================================================
// NUMBER HELPERS
// ===================================================================

const numberHelpers = {
  round: (num: number, decimals: number = 0): number => {
    if (typeof num !== 'number' || isNaN(num)) { return NaN; }
    return Number(num.toFixed(decimals));
  },

  ceil: (num: number): number => {
    return Math.ceil(num);
  },

  floor: (num: number): number => {
    return Math.floor(num);
  },

  abs: (num: number): number => {
    return Math.abs(num);
  },

  clamp: (num: number, min: number, max: number): number => {
    return Math.max(min, Math.min(max, num));
  },

  formatCurrency: (num: number, currency: string = "USD"): string => {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency,
    }).format(num);
  },

  currency: (num: number, currency: string = "USD"): string => {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency,
    }).format(num);
  },

  percent: (num: number, decimals: number = 2): string => {
    const percentage = num * 100;
    return `${percentage.toFixed(decimals)}%`;
  },
};

// ===================================================================
// ARRAY HELPERS
// ===================================================================

const arrayHelpers = {
  unique: (arr: any[]): any[] => {
    return [...new Set(arr)];
  },

  flatten: (arr: any[]): any[] => {
    return arr.flat(Infinity);
  },

  chunk: (arr: any[], size: number): any[][] => {
    const chunks: any[][] = [];
    for (let i = 0; i < arr.length; i += size) {
      chunks.push(arr.slice(i, i + size));
    }
    return chunks;
  },

  sortBy: (arr: any[], key: string): any[] => {
    return [...arr].sort((a, b) => {
      const aVal = a[key];
      const bVal = b[key];
      if (aVal < bVal) { return -1; }
      if (aVal > bVal) { return 1; }
      return 0;
    });
  },

  filter: (arr: any[], predicate: (item: any, index: number) => boolean): any[] => {
    return arr.filter(predicate);
  },

  map: (arr: any[], mapper: (item: any, index: number) => any): any[] => {
    return arr.map(mapper);
  },
};

// ===================================================================
// OBJECT HELPERS
// ===================================================================

const objectHelpers = {
  keys: (obj: Record<string, any>): string[] => {
    return Object.keys(obj);
  },

  values: (obj: Record<string, any>): any[] => {
    return Object.values(obj);
  },

  pick: (obj: Record<string, any>, keys: string[]): Record<string, any> => {
    const result: Record<string, any> = {};
    for (const key of keys) {
      if (key in obj) {
        result[key] = obj[key];
      }
    }
    return result;
  },

  omit: (obj: Record<string, any>, keys: string[]): Record<string, any> => {
    const result = { ...obj };
    for (const key of keys) {
      delete result[key];
    }
    return result;
  },

  merge: (...objects: Record<string, any>[]): Record<string, any> => {
    return Object.assign({}, ...objects);
  },
};

// ===================================================================
// MATH HELPERS
// ===================================================================

const mathHelpers = {
  random: (min: number = 0, max: number = 1): number => {
    return Math.random() * (max - min) + min;
  },

  randomInt: (min: number, max: number): number => {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  },

  sum: (arr: number[]): number => {
    return arr.reduce((a, b) => a + b, 0);
  },

  avg: (arr: number[]): number => {
    if (arr.length === 0) { return 0; }
    return arr.reduce((a, b) => a + b, 0) / arr.length;
  },

  min: (arr: number[]): number => {
    return Math.min(...arr);
  },

  max: (arr: number[]): number => {
    return Math.max(...arr);
  },
};

