                    <strong>New to Vault-Logic?</strong> Sign in with Google using this email address to automatically accept the invitation.
                </p>
            </div>
        </div>

        <div style="text-align: center; color: #9ca3af; font-size: 12px; margin-top: 40px;">
            <p style="margin: 0;">Sent from <strong>Vault-Logic</strong></p>
            <p style="margin: 5px 0 0 0;">Professional survey and polling platform</p>
        </div>
    </body>
    </html>
  `;

  const senderEmail = fromEmail || process.env.SENDGRID_FROM_EMAIL;

  if (!senderEmail) {
    return { success: false, error: 'Sender email not configured. Please set SENDGRID_FROM_EMAIL environment variable.' };
  }

  return sendEmail({
    to: recipientEmail,
    from: senderEmail,
    subject,
    text: textContent,
    html: htmlContent,
  });
}

/**
 * SLI (Service Level Indicator) Service
 *
 * Computes and tracks SLI metrics for workflows and projects:
 * - Success percentage (availability)
 * - P95 latency (performance)
 * - Error budget burn rate
 */
import { eq, and, gte, lte, isNull, desc } from 'drizzle-orm';

import {
  sliConfigs,
  sliWindows,
  metricsRollups,
  metricsEvents,
  type InsertSliConfig,
  type InsertSliWindow,
  type SliConfig,
} from '../../shared/schema';
import { db } from '../db';
import logger from '../logger';
export interface SliResult {
  successPct: number;
  p95Ms: number;
  errorBudgetBurnPct: number;
  totalRuns: number;
  successfulRuns: number;
  failedRuns: number;
  windowStart: Date;
  windowEnd: Date;
  target: {
    successPct: number;
    p95Ms: number;
    errorBudgetPct: number;
  };
  violatesTarget: boolean;
}
/**
 * Compute SLI for a project or workflow within a time window
 */
export async function computeSLI(params: {
  projectId: string;
  workflowId?: string;
  window?: '1d' | '7d' | '30d';
}): Promise<SliResult> {
  const window = params.window || '7d';
  const windowMs = parseWindow(window);
  const now = new Date();
  const windowStart = new Date(now.getTime() - windowMs);
  // Get or create SLI config
  const config = await getOrCreateConfig({
    projectId: params.projectId,
    workflowId: params.workflowId,
    window,
  });
  // Get rollup data for the window
  const rollups = await getRollupsForWindow({
    projectId: params.projectId,
    workflowId: params.workflowId,
    start: windowStart,
    end: now,
  });
  // Compute metrics from rollups
  let totalRuns = 0;
  let successfulRuns = 0;
  let failedRuns = 0;
  const durations: number[] = [];
  for (const rollup of rollups) {
    totalRuns += rollup.runsCount;
    successfulRuns += rollup.runsSuccess;
    failedRuns += rollup.runsError;
    // Collect p95 values for weighted percentile calculation
    if (rollup.durP95) {
      durations.push(rollup.durP95);
    }
  }
  // Calculate success percentage
  const successPct = totalRuns > 0 ? (successfulRuns / totalRuns) * 100 : 100;
  // Calculate p95 (simple average of rollup p95s - good enough for now)
  const p95Ms = durations.length > 0 ? Math.round(durations.reduce((a, b) => a + b, 0) / durations.length) : 0;
  // Calculate error budget burn
  const actualErrorPct = 100 - successPct;
  const errorBudgetBurnPct = config.errorBudgetPct > 0 ? (actualErrorPct / config.errorBudgetPct) * 100 : 0;
  // Check if targets are violated
  const violatesTarget = successPct < config.targetSuccessPct || p95Ms > config.targetP95Ms;
  return {
    successPct: Math.round(successPct * 100) / 100,
    p95Ms,
    errorBudgetBurnPct: Math.round(errorBudgetBurnPct * 100) / 100,
    totalRuns,
    successfulRuns,
    failedRuns,
    windowStart,
    windowEnd: now,
    target: {
      successPct: config.targetSuccessPct,
      p95Ms: config.targetP95Ms,
      errorBudgetPct: config.errorBudgetPct,
    },
    violatesTarget,
  };
}
/**
 * Save computed SLI to sli_windows table
 */
export async function saveSLIWindow(params: {
  tenantId: string;
  projectId: string;
  workflowId?: string;
  sli: SliResult;
}): Promise<void> {
  const insertData: InsertSliWindow = {
    tenantId: params.tenantId,
    projectId: params.projectId,
    workflowId: params.workflowId ?? null,
    windowStart: params.sli.windowStart,
    windowEnd: params.sli.windowEnd,
    successPct: Math.round(params.sli.successPct),
    p95Ms: params.sli.p95Ms,
    errorBudgetBurnPct: Math.round(params.sli.errorBudgetBurnPct),
  };
  await db.insert(sliWindows).values(insertData);
  logger.debug({
    projectId: params.projectId,
    workflowId: params.workflowId,
    successPct: params.sli.successPct,
  }, 'SLI window saved');
}
/**
 * Get or create SLI configuration
 * Returns existing config or creates default
 */
export async function getOrCreateConfig(params: {
  projectId: string;
  workflowId?: string;
  window?: '1d' | '7d' | '30d';
}): Promise<SliConfig> {
  const conditions = [eq(sliConfigs.projectId, params.projectId)];
  if (params.workflowId) {
    conditions.push(eq(sliConfigs.workflowId, params.workflowId));
  } else {
    conditions.push(isNull(sliConfigs.workflowId));
  }
  const existing = await db
    .select()
    .from(sliConfigs)
    .where(and(...conditions))
    .limit(1);
  if (existing.length > 0) {
    return existing[0];
  }
  // Create default config
  // Need tenantId - get from project
  const project = await db.query.projects.findFirst({
    where: (projects: any, { eq }: any) => eq(projects.id, params.projectId),
  });
  if (!project) {
    throw new Error(`Project not found: ${params.projectId}`);
  }
  const defaultConfig: InsertSliConfig = {
    tenantId: project.tenantId!,
    projectId: params.projectId,
    workflowId: params.workflowId ?? null,
    targetSuccessPct: 99,
    targetP95Ms: 5000,
    errorBudgetPct: 1,
    window: params.window || '7d',
  };
  const [created] = await db.insert(sliConfigs).values(defaultConfig).returning();
  logger.info({
    projectId: params.projectId,
    workflowId: params.workflowId,
  }, 'SLI config created with defaults');
  return created;
}
/**
 * Update SLI configuration
 */
export async function updateConfig(params: {
  id: string;
  targetSuccessPct?: number;
  targetP95Ms?: number;
  errorBudgetPct?: number;
  window?: '1d' | '7d' | '30d';
}): Promise<SliConfig> {
  const updateData: Partial<InsertSliConfig> = {};
  if (params.targetSuccessPct !== undefined) {
    updateData.targetSuccessPct = params.targetSuccessPct;
  }
  if (params.targetP95Ms !== undefined) {
    updateData.targetP95Ms = params.targetP95Ms;
  }
  if (params.errorBudgetPct !== undefined) {
    updateData.errorBudgetPct = params.errorBudgetPct;
  }
  if (params.window !== undefined) {
    updateData.window = params.window;
  }
  const [updated] = await db
    .update(sliConfigs)
    .set(updateData)
    .where(eq(sliConfigs.id, params.id))
    .returning();
  if (!updated) {
    throw new Error(`SLI config not found: ${params.id}`);
  }
  logger.info({ id: params.id, updates: updateData }, 'SLI config updated');
  return updated;
}
/**
 * Get SLI configuration for a project or workflow
 */
export async function getConfig(params: {
  projectId: string;
  workflowId?: string;
}): Promise<SliConfig | null> {
  const conditions = [eq(sliConfigs.projectId, params.projectId)];
  if (params.workflowId) {
    conditions.push(eq(sliConfigs.workflowId, params.workflowId));
  } else {
    conditions.push(isNull(sliConfigs.workflowId));
  }
  const result = await db
    .select()
    .from(sliConfigs)
    .where(and(...conditions))
    .limit(1);
  return result.length > 0 ? result[0] : null;
}
/**
 * Get rollup data for a time window
 */
async function getRollupsForWindow(params: {
  projectId: string;
  workflowId?: string;
  start: Date;
  end: Date;
}): Promise<typeof metricsRollups.$inferSelect[]> {
  const conditions = [
    eq(metricsRollups.projectId, params.projectId),
    gte(metricsRollups.bucketStart, params.start),
    lte(metricsRollups.bucketStart, params.end),
  ];
  if (params.workflowId) {
    conditions.push(eq(metricsRollups.workflowId, params.workflowId));
  }
  return db
    .select()
    .from(metricsRollups)
    .where(and(...conditions))
    .orderBy(metricsRollups.bucketStart);
}
/**
 * Get recent SLI windows
 */
export async function getRecentWindows(params: {
  projectId: string;
  workflowId?: string;
  limit?: number;
}): Promise<typeof sliWindows.$inferSelect[]> {
  const conditions = [eq(sliWindows.projectId, params.projectId)];
  if (params.workflowId) {
    conditions.push(eq(sliWindows.workflowId, params.workflowId));
  }
  return db
    .select()
    .from(sliWindows)
    .where(and(...conditions))
    .orderBy(desc(sliWindows.windowEnd))
    .limit(params.limit || 10);
}
/**
 * Parse window string to milliseconds
 */
function parseWindow(window: '1d' | '7d' | '30d'): number {
  switch (window) {
    case '1d':
      return 24 * 60 * 60 * 1000;
    case '7d':
      return 7 * 24 * 60 * 60 * 1000;
    case '30d':
      return 30 * 24 * 60 * 60 * 1000;
    default:
      return 7 * 24 * 60 * 60 * 1000; // Default to 7d
  }
}
/**
 * Export all SLI service functions
 */
export default {
  computeSLI,
  saveSLIWindow,
  getOrCreateConfig,
  updateConfig,
  getConfig,
  getRecentWindows,
};

import fs from 'fs/promises';
import path from 'path';

import { nanoid } from 'nanoid';

import { logger } from '../../logger';
import { createError } from '../../utils/errors';

import { StorageProvider } from './types';

export class DiskStorageProvider implements StorageProvider {
    private baseDir: string;

    constructor(baseDir?: string) {
        this.baseDir = baseDir || path.join(process.cwd(), 'server', 'files');
    }

    async init(): Promise<void> {
        try {
            await fs.mkdir(this.baseDir, { recursive: true });
        } catch (error) {
            logger.error({ error }, 'Failed to initialize disk storage');
            throw createError.internal('Failed to initialize file storage');
        }
    }

    async saveFile(buffer: Buffer, originalName: string, mimeType: string): Promise<string> {
        await this.init();

        const ext = path.extname(originalName);
        const fileName = `${nanoid(16)}${ext}`;
        return this.uploadFile(fileName, buffer, mimeType);
    }

    async uploadFile(key: string, buffer: Buffer, mimeType: string, metadata?: Record<string, any>): Promise<string> {
        await this.init();
        const filePath = path.join(this.baseDir, key);

        // Ensure directory exists
        await fs.mkdir(path.dirname(filePath), { recursive: true });

        try {
            await fs.writeFile(filePath, buffer);
            // We could store metadata in a sidecar file if needed, but skipping for Disk provider for now
            return key;
        } catch (error) {
            logger.error({ error, key }, 'Failed to save file to disk');
            throw createError.internal('Failed to save file');
        }
    }

    async deleteFile(fileRef: string): Promise<void> {
        const filePath = path.join(this.baseDir, fileRef);
        try {
            await fs.unlink(filePath);
        } catch (error: any) {
            if (error.code !== 'ENOENT') {
                logger.error({ error, fileRef }, 'Failed to delete file from disk');
            }
        }
    }

    async exists(fileRef: string): Promise<boolean> {
        const filePath = path.join(this.baseDir, fileRef);
        try {
            await fs.access(filePath);
            return true;
        } catch {
            return false;
        }
    }

    async getFile(fileRef: string): Promise<Buffer> {
        const filePath = path.join(this.baseDir, fileRef);
        try {
            return await fs.readFile(filePath);
        } catch (error) {
            if ((error as any).code === 'ENOENT') {
                throw createError.notFound('File not found in storage');
            }
            throw error;
        }
    }

    async getLocalPath(fileRef: string): Promise<string> {
        const filePath = path.join(this.baseDir, fileRef);
        const exists = await this.exists(fileRef);
        if (!exists) {
            // For Disk provider, we check existance. If not found, throw.
            throw createError.notFound('File not found in storage');
        }
        return filePath;
    }

    async getMetadata(fileRef: string): Promise<any> {
        const filePath = path.join(this.baseDir, fileRef);
        try {
            const stats = await fs.stat(filePath);
            return {
                size: stats.size,
                lastModified: stats.mtime,
                contentType: 'application/octet-stream', // We don't store mime type on disk currently
            };
        } catch (error: any) {
            if (error.code === 'ENOENT') {
                throw createError.notFound('File not found');
            }
            throw error;
        }
    }

    async getSignedUrl(fileRef: string, expiresIn?: number): Promise<string> {
        // Return a local API URL relative to the server
        // Requires an endpoint to serve these files, e.g. /api/storage/files/:key
        return `/api/storage/files/${fileRef}`;
    }

    async list(prefix: string): Promise<string[]> {
        await this.init();
        const dir = path.join(this.baseDir, prefix);
        try {
            const files = await fs.readdir(dir);
            return files.map(f => path.join(prefix, f).replace(/\\/g, '/'));
        } catch (error: any) {
            if (error.code === 'ENOENT') {
                return [];
            }
            throw error;
        }
    }
}

import fs from 'fs/promises';
import os from 'os';
import path from 'path';
import { Stream } from 'stream';

import { S3, GetObjectCommand, PutObjectCommand, DeleteObjectCommand, HeadObjectCommand, ListObjectsV2Command } from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';
import { nanoid } from 'nanoid';

import { logger } from '../../logger';
import { createError } from '../../utils/errors';

import { StorageProvider } from './types';

/**
 * AWS S3 Storage Provider
 * Stores files in Amazon S3 (or S3-compatible storage like MinIO)
 */
export class S3StorageProvider implements StorageProvider {
  private s3: S3;
  private bucket: string;
  private region: string;
  private endpoint?: string;

  constructor(options?: {
    bucket?: string;
    region?: string;
    accessKeyId?: string;
    secretAccessKey?: string;
    endpoint?: string;
  }) {
    // Get configuration from options or environment variables
    this.bucket = (options?.bucket || process.env.AWS_S3_BUCKET) ?? '';
    this.region = options?.region || process.env.AWS_REGION || 'us-east-1';
    const accessKeyId = options?.accessKeyId || process.env.AWS_ACCESS_KEY_ID;
    const secretAccessKey = options?.secretAccessKey || process.env.AWS_SECRET_ACCESS_KEY;
    this.endpoint = options?.endpoint || process.env.AWS_S3_ENDPOINT;

    // We don't throw here if bucket is missing, as we might not be using S3 provider
    // Validation happens in init()

    // Initialize S3 client
    this.s3 = new S3({
      region: this.region,
      credentials: accessKeyId && secretAccessKey ? {
        accessKeyId,
        secretAccessKey,
      } : undefined,
      endpoint: this.endpoint || undefined,
      forcePathStyle: !!this.endpoint, // Required for MinIO and some S3-compatible services
    });
  }

  async init(): Promise<void> {
    if (!this.bucket) {
      throw new Error('S3 bucket name is required (set AWS_S3_BUCKET environment variable)');
    }
    logger.info({ bucket: this.bucket, region: this.region }, 'S3StorageProvider initialized');
  }

  async saveFile(buffer: Buffer, originalName: string, mimeType: string): Promise<string> {
    const ext = path.extname(originalName);
    const fileRef = `${nanoid(16)}${ext}`;
    return this.uploadFile(fileRef, buffer, mimeType);
  }

  async uploadFile(key: string, buffer: Buffer, mimeType: string, metadata?: Record<string, any>): Promise<string> {
    try {
      await this.s3.send(new PutObjectCommand({
        Bucket: this.bucket,
        Key: key,
        Body: buffer,
        ContentType: mimeType,
        Metadata: metadata as Record<string, string>, // S3 metadata is string-only
        ServerSideEncryption: 'AES256',
      }));

      logger.info({ key, bucket: this.bucket, size: buffer.length }, 'File uploaded to S3');
      return key;
    } catch (error) {
      logger.error({ error, key }, 'Failed to upload file to S3');
      throw createError.internal('Failed to save file');
    }
  }

  async deleteFile(fileRef: string): Promise<void> {
    try {
      await this.s3.send(new DeleteObjectCommand({
        Bucket: this.bucket,
        Key: fileRef,
      }));
      logger.info({ fileRef }, 'File deleted from S3');
    } catch (error) {
      logger.error({ error, fileRef }, 'Failed to delete file from S3');
      // Don't throw for delete failure to allow cleanup flow to continue
    }
  }

  async exists(fileRef: string): Promise<boolean> {
    try {
      await this.s3.send(new HeadObjectCommand({
        Bucket: this.bucket,
        Key: fileRef,
      }));
      return true;
    } catch (error: any) {
      if (error.name === 'NotFound' || error.$metadata?.httpStatusCode === 404) {
        return false;
      }
      return false;
    }
  }

  async getFile(fileRef: string): Promise<Buffer> {
    try {
      const response = await this.s3.send(new GetObjectCommand({
        Bucket: this.bucket,
        Key: fileRef,
      }));

      // Convert stream to buffer
      const chunks: Uint8Array[] = [];
      if (response.Body) {
        // @ts-ignore - AWS SDK types for Body are complex (Readable | ReadableStream | Blob)
        for await (const chunk of response.Body) {
          chunks.push(chunk);
        }
      }
      return Buffer.concat(chunks);
    } catch (error: any) {
      if (error.name === 'NoSuchKey' || error.$metadata?.httpStatusCode === 404) {
        throw createError.notFound('File not found in S3');
      }
      logger.error({ error, fileRef }, 'Failed to download file from S3');
      throw createError.internal('Failed to retrieve file');
    }
  }

  async getMetadata(fileRef: string): Promise<any> {
    try {
      const response = await this.s3.send(new HeadObjectCommand({
        Bucket: this.bucket,
        Key: fileRef,
      }));

      return {
        contentType: response.ContentType || 'application/octet-stream',
        size: response.ContentLength || 0,
        etag: response.ETag,
        lastModified: response.LastModified,
      };
    } catch (error: any) {
      if (error.name === 'NotFound' || error.$metadata?.httpStatusCode === 404) {
        throw createError.notFound('File not found in S3');
      }
      logger.error({ error, fileRef }, 'Failed to get metadata from S3');
      throw createError.internal('Failed to get file metadata');
    }
  }

  async getSignedUrl(fileRef: string, expiresIn: number = 300): Promise<string> {
    try {
      const command = new GetObjectCommand({
        Bucket: this.bucket,
        Key: fileRef,
      });

      const url = await getSignedUrl(this.s3, command, {
        expiresIn: expiresIn,
      });

      logger.debug({ fileRef, expiresIn }, 'Generated signed URL for S3 file');
      return url;
    } catch (error) {
      logger.error({ error, fileRef }, 'Failed to generate signed URL for S3 file');
      throw createError.internal('Failed to generate signed URL');
    }
  }

  async list(prefix: string): Promise<string[]> {
    try {
      const response = await this.s3.send(new ListObjectsV2Command({
        Bucket: this.bucket,
        Prefix: prefix,
      }));

      const keys = (response.Contents ?? [])
        .map(obj => obj.Key)
        .filter((key): key is string => !!key);

      logger.debug({ prefix, count: keys.length }, 'Listed files in S3');
      return keys;
    } catch (error) {
      logger.error({ error, prefix }, 'Failed to list files in S3');
      throw createError.internal('Failed to list files in S3');
    }
  }

  async getLocalPath(fileRef: string): Promise<string> {
    // Check if file exists in temp dir first
    const tempDir = os.tmpdir();
    // Sanitize fileRef for filename
    const sanitizedRef = fileRef.replace(/[^a-zA-Z0-9.-]/g, '_');
    const tempFilePath = path.join(tempDir, `s3-cache-${sanitizedRef}`);

    try {
      // Check cache
      await fs.access(tempFilePath);
      return tempFilePath;
    } catch {
      // Not cached, download it
      logger.debug({ fileRef }, 'Downloading S3 file to local cache');
      const buffer = await this.getFile(fileRef);
      await fs.writeFile(tempFilePath, buffer);
      return tempFilePath;
    }
  }
}

/**
 * RunLifecycleService
 *
 * Handles workflow run lifecycle operations.
 * Responsibilities:
 * - Execute onRunStart blocks
 * - Generate documents for completed runs
 * - Execute DataVault writebacks
 * - Manage initial value population
 * - Determine start section with auto-advance
 */

import { logger } from "../../logger";
import { stepValueRepository, stepRepository, sectionRepository } from "../../repositories";
import { blockRunner } from "../BlockRunner";
import { documentGenerationService } from "../DocumentGenerationService";
import { logicService } from "../LogicService";
import { RunPersistenceWriter } from "../runs/RunPersistenceWriter";
import { writebackExecutionService } from "../WritebackExecutionService";

import type { PopulateValuesOptions, SnapshotValueMap, DocumentGenerationResult, WritebackExecutionResult } from "./types";


export class RunLifecycleService {
  constructor(
    private valueRepo = stepValueRepository,
    private stepRepo = stepRepository,
    private sectionRepo = sectionRepository,
    private persistence = new RunPersistenceWriter(),
    private logicSvc = logicService
  ) { }

  /**
   * Execute onRunStart blocks
   * Called after run creation to initialize computed values
   */
  async executeOnRunStart(
    runId: string,
    workflowId: string,
    versionId?: string
  ): Promise<{ success: boolean; errors?: string[] }> {
    try {
      const values = await this.persistence.getRunValues(runId);

      const blockResult = await blockRunner.runPhase({
        workflowId,
        runId,
        phase: "onRunStart",
        data: values,
        versionId: versionId || 'draft',
      });

      if (!blockResult.success && blockResult.errors) {
        logger.warn({ runId, errors: blockResult.errors }, `onRunStart block errors for run ${runId}`);
        return { success: false, errors: blockResult.errors };
      }

      return { success: true };
    } catch (error) {
      logger.error({ runId, error }, `Failed to execute onRunStart blocks for run ${runId}`);
      return { success: false, errors: [(error as Error).message] };
    }
  }

  /**
   * Populate step values with initial values and defaults
   * Priority: initialValues > snapshotValues > randomValues > step defaultValue
   */
  async populateInitialValues(
    runId: string,
    workflowId: string,
    options: PopulateValuesOptions
  ): Promise<void> {
    const { initialValues, snapshotValues, randomValues } = options;

    // Get all sections for the workflow
    const sections = await this.sectionRepo.findByWorkflowId(workflowId);
    const sectionIds = sections.map(s => s.id);

    // Get all steps for these sections
    const allSteps = await this.stepRepo.findBySectionIds(sectionIds);

    const valuesToSave: Array<{ stepId: string; value: any }> = [];

    // Populate step values
    for (const step of allSteps) {
      if (step.isVirtual) {continue;}

      let valueToSet: any = undefined;

      // Priority 1: initialValues (by alias or stepId)
      if (initialValues) {
        if (step.alias && initialValues[step.alias] !== undefined) {
          valueToSet = initialValues[step.alias];
        } else if (initialValues[step.id] !== undefined) {
          valueToSet = initialValues[step.id];
        }
      }

      // Priority 2: snapshotValues
      if (valueToSet === undefined && snapshotValues) {
        const key = step.alias || step.id;
        if (snapshotValues[key] !== undefined) {
          valueToSet = snapshotValues[key];
        }
      }

      // Priority 3: randomValues
      if (valueToSet === undefined && randomValues) {
        const key = step.alias || step.id;
        if (randomValues[key] !== undefined) {
          valueToSet = randomValues[key];
        }
      }

      // Priority 4: step's defaultValue
      if (valueToSet === undefined && step.defaultValue !== undefined && step.defaultValue !== null) {
        valueToSet = step.defaultValue;
      }

      // Add to list if we have a value
      if (valueToSet !== undefined) {
        valuesToSave.push({
          stepId: step.id,
          value: valueToSet,
        });
      }
    }

    if (valuesToSave.length > 0) {
      await this.persistence.bulkSaveValues(runId, valuesToSave, workflowId);
    }
  }

  /**
   * Load and merge values from snapshot
   */
  async loadSnapshotValues(snapshotId: string): Promise<{ values: Record<string, any>; valueMap: SnapshotValueMap }> {
    const { snapshotService } = await import('../SnapshotService');
    const snapshot = await snapshotService.getSnapshotById(snapshotId);

    if (!snapshot) {
      throw new Error(`Snapshot not found: ${snapshotId}`);
    }

    // Check Snapshot Compatibility (Stage 400 Safety Signal)
    const compatibility = await snapshotService.validateSnapshot(snapshotId);
    if (!compatibility.valid) {
      if (compatibility.severity === 'hard_breaking') {
        logger.error({
          snapshotId,
          reasons: compatibility.reasons
        }, "Prevented run creation from incompatible snapshot (Hard Breaking)");
        throw new Error(`Snapshot is incompatible with current workflow: ${compatibility.reasons.join(", ")}`);
      } else if (compatibility.severity === 'soft_breaking') {
        logger.warn({
          snapshotId,
          reasons: compatibility.reasons
        }, "Run created from snapshot with missing fields (Soft Breaking)");
      }
    }

    const snapshotValues = await snapshotService.getSnapshotValues(snapshotId);
    const snapshotValueMap = snapshot.values as SnapshotValueMap;

    return { values: snapshotValues, valueMap: snapshotValueMap };
  }

  /**
   * Generate random values using AI
   */
  async generateRandomValues(workflowId: string): Promise<Record<string, any>> {
    const { createAIServiceFromEnv } = await import('../AIService');

    // Get all steps for the workflow
    const allSteps = await this.stepRepo.findByWorkflowIdWithAliases(workflowId);
    const visibleSteps = allSteps.filter(s => !s.isVirtual);

    // Build step data for AI
    const stepData = visibleSteps.map(step => ({
      key: step.alias || step.id,
      type: step.type,
      label: step.title,
      options: step.options as any[] | undefined,
      description: step.description || undefined,
    }));

    // Call AI service to generate random values
    const aiService = createAIServiceFromEnv();
    return aiService.suggestValues(stepData, 'full');
  }

  /**
   * Determine the appropriate start section for a run
   * Used for auto-advance when creating runs from snapshots
   *
   * Rules:
   * A) Skip invisible sections via existing logic
   * B) For each required visible step:
   *    - If no run value ΓåÆ stop here
   *    - If snapshot version mismatch ΓåÆ stop here
   * C) If all satisfied ΓåÆ jump to first visible final block
   * D) Else fallback to workflow's first section
   */
  async determineStartSection(
    runId: string,
    workflowId: string,
    snapshotValues?: SnapshotValueMap
  ): Promise<string> {
    // Get all sections for the workflow
    const sections = await this.sectionRepo.findByWorkflowId(workflowId);
    if (sections.length === 0) {
      throw new Error("Workflow has no sections");
    }

    // Sort sections by order
    const sortedSections = [...sections].sort((a, b) => (a.order || 0) - (b.order || 0));

    // Get all step values for the run
    const runValues = await this.valueRepo.findByRunId(runId);
    const runValueMap = new Map(runValues.map(v => [v.stepId, v]));

    // Get all steps for the workflow
    const allSteps = await this.stepRepo.findByWorkflowIdWithAliases(workflowId);
    const stepMap = new Map(allSteps.map(s => [s.id, s]));

    // Build data map for logic evaluation
    const dataMap: Record<string, any> = {};
    for (const value of runValues) {
      const step = stepMap.get(value.stepId);
      if (step) {
        const key = step.alias || step.id;
        dataMap[key] = value.value;
      }
    }

    // Iterate through sections to find the first incomplete one
    for (const section of sortedSections) {
      // Check if section is visible using logic service
      const sectionVisible = await this.logicSvc.isSectionVisible(
        workflowId,
        section.id,
        dataMap
      );

      if (!sectionVisible) {
        continue; // Skip invisible sections
      }

      // Get steps for this section
      const sectionSteps = allSteps.filter(s => s.sectionId === section.id && !s.isVirtual);

      // Check if all required steps have valid values
      let allRequiredStepsSatisfied = true;

      for (const step of sectionSteps) {
        // Check if step is visible
        const stepVisible = await this.logicSvc.isStepVisible(
          workflowId,
          step.id,
          dataMap
        );

        if (!stepVisible) {
          continue; // Skip invisible steps
        }

        // Check if step is required
        const isRequired = await this.logicSvc.isStepRequired(
          workflowId,
          step.id,
          dataMap
        );

        if (!isRequired) {
          continue; // Skip optional steps
        }

        // Check if step has a value
        const hasValue = runValueMap.has(step.id);

        if (!hasValue) {
          // Required step missing value - stop here
          allRequiredStepsSatisfied = false;
          break;
        }

        // If snapshot values provided, check for version mismatch
        if (snapshotValues) {
          const key = step.alias || step.id;
          const snapshotData = snapshotValues[key];

          if (snapshotData) {
            const stepUpdatedAt = step.updatedAt?.toISOString() || new Date(0).toISOString();
            if (stepUpdatedAt > snapshotData.stepUpdatedAt) {
              // Step was updated after snapshot - treat as incomplete
              allRequiredStepsSatisfied = false;
              break;
            }
          }
        }
      }

      if (!allRequiredStepsSatisfied) {
        // Found first incomplete section - return this section
        return section.id;
      }
    }

    // All sections complete - return the last section (or first if none)
    return sortedSections[sortedSections.length - 1]?.id || sortedSections[0].id;
  }

  /**
   * Generate documents for a completed run
   */
  async generateDocuments(runId: string): Promise<DocumentGenerationResult> {
    try {
      await documentGenerationService.generateDocumentsForRun(runId);
      logger.info({ runId }, 'Documents generated successfully');

      // Count generated documents
      const { runGeneratedDocumentsRepository } = await import('../../repositories');
      const documents = await runGeneratedDocumentsRepository.findByRunId(runId);

      return {
        success: true,
        documentsGenerated: documents.length
      };
    } catch (error) {
      logger.error({ error, runId }, 'Document generation failed');
      return {
        success: false,
        documentsGenerated: 0,
        errors: [(error as Error).message]
      };
    }
  }

  /**
   * Execute DataVault writebacks for a completed run
   */
  async executeWritebacks(
    runId: string,
    workflowId: string,
    userId?: string
  ): Promise<WritebackExecutionResult> {
    try {
      const result = await writebackExecutionService.executeWritebacksForRun(
        runId,
        workflowId,
        userId || undefined
      );

      if (result.rowsCreated > 0) {
        logger.info(
          { runId, rowsCreated: result.rowsCreated },
          'DataVault writeback completed'
        );
      }

      if (result.errors.length > 0) {
        logger.warn(
          { runId, errors: result.errors },
          'Some writeback mappings failed'
        );
      }

      return {
        success: result.errors.length === 0,
        rowsCreated: result.rowsCreated,
        errors: result.errors
      };
    } catch (error) {
      logger.error({ error, runId }, 'Writeback execution failed');
      return {
        success: false,
        rowsCreated: 0,
        errors: [(error as Error).message]
      };
    }
  }
}

