/**
 * Utility functions for formatting and extracting answer values
 *
 * Handles the conversion of jsonb answer values to readable strings,
 * accounting for various data structures used by different question types.
 */

/**
 * Safely extract text value from an answer
 * Handles the case where text values are stored as { text: "value" } objects
 *
 * @param value - The raw answer value (can be string, number, boolean, object, array, etc.)
 * @returns The extracted text value, or the original value if it's already a primitive
 */
export function extractTextValue(value: any): string {
  // Handle null/undefined
  if (value === null || value === undefined) {
    return '';
  }

  // If it's an object with a 'text' property, extract it
  if (typeof value === 'object' && !Array.isArray(value) && 'text' in value) {
    return String(value.text ?? '');
  }

  // For arrays, join with semicolons
  if (Array.isArray(value)) {
    return value.map(v => extractTextValue(v)).join('; ');
  }

  // For other objects (excluding Date), return empty string or convert to JSON
  if (typeof value === 'object' && !(value instanceof Date)) {
    // Check if it's a file upload object
    if ('files' in value) {
      return `${value.files?.length || 0} file(s)`;
    }
    // For other objects, return empty string to avoid [object Object]
    return '';
  }

  // For primitives (string, number, boolean, Date), convert to string
  return String(value);
}

/**
 * Format an answer value based on the question type
 *
 * @param value - The raw answer value
 * @param questionType - The type of question (short_text, multiple_choice, etc.)
 * @returns Formatted string representation of the answer
 */
export function formatAnswerValue(value: any, questionType: string): string {
  if (!value) {return '';}

  switch (questionType) {
    case 'short_text':
    case 'long_text':
      // Extract text from objects like { text: "answer" }
      return extractTextValue(value);

    case 'multiple_choice':
      // Handle array of selections
      if (Array.isArray(value)) {
        return value.map(v => extractTextValue(v)).join('; ');
      }
      return extractTextValue(value);

    case 'radio':
      // Single selection
      return extractTextValue(value);

    case 'yes_no':
      // Boolean or string representation
      if (typeof value === 'boolean') {
        return value ? 'Yes' : 'No';
      }
      if (typeof value === 'object' && 'text' in value) {
        return extractTextValue(value);
      }
      return value === 'Yes' || value === true || value === 'yes' ? 'Yes' : 'No';

    case 'date_time':
      // Date formatting
      if (typeof value === 'object' && 'text' in value) {
        return extractTextValue(value);
      }
      if (value instanceof Date) {
        return value.toISOString();
      }
      return String(value);

    case 'file_upload':
      // File upload metadata
      if (typeof value === 'object' && 'files' in value) {
        const fileCount = value.files?.length || 0;
        return `${fileCount} file(s)`;
      }
      return '';

    default:
      // Fallback for unknown types
      return extractTextValue(value);
  }
}

/**
 * Simple concurrency limiter (semaphore)
 * Used to limit concurrent heavy operations like DOCX scanning or PDF conversion
 * to prevent CPU spikes and OOM.
 */
export class ConcurrencyLimiter {
    private queue: (() => void)[] = [];
    private activeCount = 0;

    constructor(private maxConcurrency: number) { }

    async run<T>(fn: () => Promise<T>): Promise<T> {
        if (this.activeCount < this.maxConcurrency) {
            this.activeCount++;
            return this.execute(fn);
        }
        return new Promise<T>((resolve, reject) => {
            this.queue.push(() => {
                this.activeCount++;
                this.execute(fn).then(resolve).catch(reject);
            });
        });
    }

    private async execute<T>(fn: () => Promise<T>): Promise<T> {
        try {
            return await fn();
        } finally {
            this.activeCount--;
            if (this.queue.length > 0) {
                const next = this.queue.shift();
                next?.();
            }
        }
    }

    get pending() {
        return this.queue.length;
    }

    get active() {
        return this.activeCount;
    }
}

/**
 * Diff utility for comparing workflow versions
 * Provides machine-readable diffs and human-readable summaries
 */

export interface DiffChange {
  type: 'added' | 'removed' | 'changed';
  path: string;
  oldValue?: any;
  newValue?: any;
}

export interface GraphDiff {
  nodesAdded: Array<{ id: string; type: string }>;
  nodesRemoved: Array<{ id: string; type: string }>;
  nodesChanged: Array<{ id: string; changes: DiffChange[] }>;
  edgesAdded: Array<{ from: string; to: string }>;
  edgesRemoved: Array<{ from: string; to: string }>;
}

export interface VersionDiff {
  graphDiff: GraphDiff;
  bindingsDiff: DiffChange[];
  templatesDiff: DiffChange[];
  checksums: {
    old: string | null;
    new: string | null;
  };
  summary: string[];
}

/**
 * Compare two graphs and return detailed diff
 */
function compareGraphs(oldGraph: any, newGraph: any): GraphDiff {
  const diff: GraphDiff = {
    nodesAdded: [],
    nodesRemoved: [],
    nodesChanged: [],
    edgesAdded: [],
    edgesRemoved: [],
  };

  const oldNodes = new Map((oldGraph?.nodes ?? []).map((n: any) => [n.id, n]));
  const newNodes = new Map((newGraph?.nodes ?? []).map((n: any) => [n.id, n]));

  // Find added and changed nodes
  for (const [id, newNode] of newNodes) {
    const oldNode = oldNodes.get(id);
    if (!oldNode) {
      diff.nodesAdded.push({ id: id as string, type: (newNode as any).type || 'unknown' });
    } else {
      const changes = compareObjects(oldNode, newNode, `nodes.${id as string}`);
      if (changes.length > 0) {
        diff.nodesChanged.push({ id: id as string, changes });
      }
    }
  }

  // Find removed nodes
  for (const [id, oldNode] of oldNodes) {
    if (!newNodes.has(id)) {
      diff.nodesRemoved.push({ id: id as string, type: (oldNode as any).type || 'unknown' });
    }
  }

  // Compare edges
  const oldEdges = new Set((oldGraph?.edges ?? []).map((e: any) => `${e.source}->${e.target}`));
  const newEdges = new Set((newGraph?.edges ?? []).map((e: any) => `${e.source}->${e.target}`));

  for (const edge of newEdges) {
    if (!oldEdges.has(edge)) {
      const [from, to] = (edge as string).split('->');
      diff.edgesAdded.push({ from, to });
    }
  }

  for (const edge of oldEdges) {
    if (!newEdges.has(edge)) {
      const [from, to] = (edge as string).split('->');
      diff.edgesRemoved.push({ from, to });
    }
  }

  return diff;
}

/**
 * Compare two objects and return list of changes
 */
function compareObjects(oldObj: any, newObj: any, basePath: string = ''): DiffChange[] {
  const changes: DiffChange[] = [];

  // Get all unique keys
  const allKeys = new Set([
    ...Object.keys(oldObj || {}),
    ...Object.keys(newObj || {}),
  ]);

  for (const key of allKeys) {
    const path = basePath ? `${basePath}.${key}` : key;
    const oldVal = oldObj?.[key];
    const newVal = newObj?.[key];

    if (oldVal === undefined && newVal !== undefined) {
      changes.push({ type: 'added', path, newValue: newVal });
    } else if (oldVal !== undefined && newVal === undefined) {
      changes.push({ type: 'removed', path, oldValue: oldVal });
    } else if (JSON.stringify(oldVal) !== JSON.stringify(newVal)) {
      changes.push({ type: 'changed', path, oldValue: oldVal, newValue: newVal });
    }
  }

  return changes;
}

/**
 * Generate human-readable summary from diff
 */
function generateSummary(diff: VersionDiff): string[] {
  const summary: string[] = [];

  // Graph changes
  if (diff.graphDiff.nodesAdded.length > 0) {
    summary.push(`Added ${diff.graphDiff.nodesAdded.length} node(s)`);
  }
  if (diff.graphDiff.nodesRemoved.length > 0) {
    summary.push(`Removed ${diff.graphDiff.nodesRemoved.length} node(s)`);
  }
  if (diff.graphDiff.nodesChanged.length > 0) {
    summary.push(`Modified ${diff.graphDiff.nodesChanged.length} node(s)`);
  }
  if (diff.graphDiff.edgesAdded.length > 0) {
    summary.push(`Added ${diff.graphDiff.edgesAdded.length} connection(s)`);
  }
  if (diff.graphDiff.edgesRemoved.length > 0) {
    summary.push(`Removed ${diff.graphDiff.edgesRemoved.length} connection(s)`);
  }

  // Binding changes
  if (diff.bindingsDiff.length > 0) {
    const added = diff.bindingsDiff.filter(c => c.type === 'added').length;
    const removed = diff.bindingsDiff.filter(c => c.type === 'removed').length;
    const changed = diff.bindingsDiff.filter(c => c.type === 'changed').length;
    if (added > 0) {summary.push(`Added ${added} binding(s)`);}
    if (removed > 0) {summary.push(`Removed ${removed} binding(s)`);}
    if (changed > 0) {summary.push(`Modified ${changed} binding(s)`);}
  }

  // Template changes
  if (diff.templatesDiff.length > 0) {
    const added = diff.templatesDiff.filter(c => c.type === 'added').length;
    const removed = diff.templatesDiff.filter(c => c.type === 'removed').length;
    if (added > 0) {summary.push(`Added ${added} template(s)`);}
    if (removed > 0) {summary.push(`Removed ${removed} template(s)`);}
  }

  if (summary.length === 0) {
    summary.push('No changes detected');
  }

  return summary;
}

/**
 * Compute diff between two workflow versions
 */
export function computeVersionDiff(
  oldVersion: {
    graphJson: any;
    bindings?: any;
    templateIds?: string[];
    checksum?: string | null;
  },
  newVersion: {
    graphJson: any;
    bindings?: any;
    templateIds?: string[];
    checksum?: string | null;
  }
): VersionDiff {
  const diff: VersionDiff = {
    graphDiff: compareGraphs(oldVersion.graphJson, newVersion.graphJson),
    bindingsDiff: compareObjects(oldVersion.bindings || {}, newVersion.bindings || {}, 'bindings'),
    templatesDiff: compareObjects(
      { templates: oldVersion.templateIds ?? [] },
      { templates: newVersion.templateIds ?? [] },
      'templates'
    ),
    checksums: {
      old: oldVersion.checksum ?? null,
      new: newVersion.checksum ?? null,
    },
    summary: [],
  };

  diff.summary = generateSummary(diff);

  return diff;
}

/**
 * Enhanced Sandbox Executor for Custom Scripting System
 * Extends sandboxExecutor.ts with helper library and context injection
 */

import { spawn } from "child_process";
import vm from "vm";

import type { ScriptExecutionResult, ScriptContextAPI, HelperLibraryAPI } from "@shared/types/scripting";

import { createLogger } from "../logger";
import { createHelperLibrary } from "../services/scripting/HelperLibrary";

const logger = createLogger({ module: "enhanced-sandbox" });

// Security Constants (Mirrored from sandboxExecutor)
const MAX_CODE_SIZE = parseInt(process.env.SANDBOX_MAX_CODE_SIZE ?? "32768", 10);
const MAX_INPUT_SIZE = parseInt(process.env.SANDBOX_MAX_INPUT_SIZE ?? "65536", 10);
const MAX_OUTPUT_SIZE = parseInt(process.env.SANDBOX_MAX_OUTPUT_SIZE ?? "65536", 10);
const MIN_TIMEOUT_MS = 100;
const MAX_TIMEOUT_MS = 3000;

// Local interfaces for optional isolated-vm dependency
interface IvmIsolate {
  dispose(): void;
  createContext(): Promise<IvmContext>;
  compileScript(code: string): Promise<IvmScript>;
}
interface IvmContext {
  global: IvmReference;
  release(): void;
}
interface IvmReference {
  set(name: string, value: unknown, options?: unknown): Promise<void>;
  derefInto(): unknown;
  copyInto(): unknown;
  copy(): Promise<unknown>;
  applySync(target: unknown, args: unknown[], options?: unknown): unknown;
}
interface IvmScript {
  run(context: IvmContext, options?: unknown): Promise<unknown>;
}


interface ExecuteCodeWithHelpersParams {
  language: "javascript" | "python";
  code: string;
  input: Record<string, unknown>;
  context: ScriptContextAPI;
  helpers?: Record<string, unknown> | HelperLibraryAPI;
  timeoutMs?: number;
  consoleEnabled?: boolean;
  // Performance optimizations
  isolate?: IvmIsolate; // Re-use existing Isolate
  scriptCache?: Map<string, IvmScript>; // Cache compiled scripts
}

/**
 * Execute JavaScript code with helpers and context injection
 */
/**
 * Execute JavaScript code with helpers and context injection using isolated-vm
 */
async function runJsWithHelpers(
  code: string,
  input: Record<string, unknown>,
  context: ScriptContextAPI,
  helpers: Record<string, unknown> | HelperLibraryAPI | undefined,
  timeoutMs: number,
  consoleEnabled: boolean,
  existingIsolate?: IvmIsolate,
  scriptCache?: Map<string, IvmScript>
): Promise<ScriptExecutionResult> {
  const helperLib = createHelperLibrary({ consoleEnabled });
  // When consoleEnabled, always use helperLib.helpers to ensure console capture works
  const actualHelpers = consoleEnabled ? helperLib.helpers : (helpers || helperLib.helpers);

  let ivm: typeof import("isolated-vm") | undefined;
  try {
    ivm = await import("isolated-vm");
  } catch (error) {
    logger.warn({ error }, "isolated-vm not found, falling back to node 'vm' module");
    const result = await runJsWithVmFallback(code, input, context, actualHelpers as Record<string, any>, timeoutMs, consoleEnabled);
    // Merge logs from helper library (which captures helpers.console.* calls)
    if (helperLib.getConsoleLogs) {
      const libLogs = helperLib.getConsoleLogs();
      if (libLogs && libLogs.length > 0) {
        result.consoleLogs = [...(result.consoleLogs ?? []), ...libLogs];
      }
    }
    return result;
  }

  // Create or reuse Isolate
  const isolate = (existingIsolate as IvmIsolate) || new ivm.Isolate({ memoryLimit: 128 });
  const disposeIsolate = !existingIsolate; // Only dispose if we created it


  // Enforce timeout limits
  const actualTimeout = Math.min(Math.max(timeoutMs, MIN_TIMEOUT_MS), MAX_TIMEOUT_MS);

  // Validate code size
  if (code.length > MAX_CODE_SIZE) {
    return { ok: false, error: `Code size exceeds ${MAX_CODE_SIZE / 1024}KB limit` };
  }

  // Validate input size
  try {
    const inputJson = JSON.stringify(input);
    if (inputJson.length > MAX_INPUT_SIZE) {
      if (disposeIsolate) { isolate.dispose(); }
      return { ok: false, error: `Input size exceeds ${MAX_INPUT_SIZE / 1024}KB limit` };
    }
  } catch (e) {
    if (disposeIsolate) { isolate.dispose(); }
    return { ok: false, error: "InputSerializationError: Input must be JSON serializable" };
  }

  try {
    const ctx = await isolate.createContext();
    const jail = ctx.global;

    // 2. Setup Global Scope
    await jail.set("global", jail.derefInto());

    // 3. Transfer Input (Data)
    await jail.set("input", new ivm.ExternalCopy(input).copyInto());

    // 4. Transfer Context (Data - confirmed purely JSON)
    await jail.set("context", new ivm.ExternalCopy(context).copyInto());

    // 5. Setup Helpers Bridge
    // We can't transfer functions directly. We create a structure map and a generic caller.

    // Helper to get structure
    const getStructure = (obj: unknown): unknown => {
      if (typeof obj === 'function') { return '__fn__'; }
      if (typeof obj === 'object' && obj !== null) {
        const struct: any = {};
        for (const k of Object.keys(obj)) {
          (struct)[k] = getStructure((obj as any)[k]);
        }
        return struct;
      }
      return '__val__'; // Primitive value (we don't support passing values this way currently, only functions or nested objects)
    };

    const helpersStructure = getStructure(actualHelpers);
    await jail.set("_helpersStructure", new ivm.ExternalCopy(helpersStructure).copyInto());

    // Setup emit callback
    let emittedValue: unknown = undefined;
    await jail.set("_emitCallback", new ivm.Reference((val: unknown) => {
      // Handle potential reference if val is object
      // But typically we want the value. ivm passes value for primitives, Reference for objects?
      // Actually with primitives it passes value.
      // If it's a reference, we should probably copy it immediately?
      // But Reference.copy() returns promise. Reference in callback?
      // Let's assume we can store it and copy later if needed, or better, Request Copy in arguments?
      // We can use same trick as callHost?
      emittedValue = val;
    }));

    // Setup console capture callbacks
    const capturedConsoleLogs: unknown[][] = [];
    await jail.set("_consoleLog", new ivm.Reference((...args: unknown[]) => {
      capturedConsoleLogs.push(args);
    }));
    await jail.set("_consoleWarn", new ivm.Reference((...args: unknown[]) => {
      capturedConsoleLogs.push(['[WARN]', ...args]);
    }));
    await jail.set("_consoleError", new ivm.Reference((...args: unknown[]) => {
      capturedConsoleLogs.push(['[ERROR]', ...args]);
    }));



    // We MUST allow the callback to be async (returns Promise) if target is async?
    // But isolated-vm 'applySync' cannot wait for Promise.
    // If target is async, we MUST use 'apply' in sandbox.
    // However, HelperLibrary functions are synchronous.
    // So we can use a synchronous callback for them.
    // But 'callHostParams' is async?
    // Let's make it sync if we can.
    // Wait, 'ExternalCopy' is synchronous.
    // If all helpers are synchronous, we can define the callback as synchronous?
    // ivm.Reference function wrapper is ... depends on how we define it.
    // Let's rely on ivm handling.
    // If we define:
    // jail.setSync("callHost", new ivm.Reference( (path, ...args) => ... ));

    await jail.set("callHost", new ivm.Reference((path: string[], ...args: unknown[]) => {
      // With { arguments: { copy: true } }, path and args are copied by value (not References)

      let target: any = actualHelpers;
      // Debug log
      // logger.debug({ path: path.join('.') }, 'Bridge Path');

      for (const key of path) {
        if (!target) {
          throw new Error(`Helper not found: ${path.join('.')}`);
        }
        target = target[key];
      }

      const fn = target as Function;

      // Args are already copies
      const res = fn(...args);

      // Handle void return (undefined)
      if (res === undefined) { return undefined; }

      return new ivm.ExternalCopy(res).copyInto();
    }));

    // Bootstrap Script to rebuild helpers object
    const bootstrapCode = `
      function buildHelpers(struct, path = []) {
        if (struct === '__fn__') {
          return function(...args) {
            // Force copy of arguments to avoid Reference issues
            return callHost.applySync(undefined, [path, ...args], { arguments: { copy: true } });
          };
        }
        if (typeof struct === 'object') {
           const obj = {};
           for (const k in struct) {
             obj[k] = buildHelpers(struct[k], [...path, k]);
           }
           return obj;
        }
        return undefined;
      }

      const helpers = buildHelpers(_helpersStructure);

      // Define global console for capturing output
      global.console = {
        log: function(...args) {
          _consoleLog.applySync(undefined, args, { arguments: { copy: true } });
        },
        warn: function(...args) {
          _consoleWarn.applySync(undefined, args, { arguments: { copy: true } });
        },
        error: function(...args) {
          _consoleError.applySync(undefined, args, { arguments: { copy: true } });
        },
        info: function(...args) {
          _consoleLog.applySync(undefined, ['[INFO]', ...args], { arguments: { copy: true } });
        }
      };

      // Override helpers.console to use the same capture mechanism
      helpers.console = global.console;

      // Define global emit
      global.emit = function(val) {
         try {
           _emitCallback.applySync(undefined, [val], { arguments: { copy: true } });
         } catch (e) {
           // Ignore emit errors or log?
         }
      };

      // Wrap user code
      (function(input, context, helpers) {
         ${code}
      })(input, context, helpers);
    `;

    // 6. Compile & Run
    // 6. Compile & Run
    // Check cache
    // Simple hash: code string itself (could use SHA-256 for large code)
    const cacheKey = code;
    let script: IvmScript;

    if (scriptCache?.has(cacheKey)) {
      script = scriptCache.get(cacheKey)!;
    } else {
      script = await isolate.compileScript(bootstrapCode);
      if (scriptCache) {
        scriptCache.set(cacheKey, script);
      }
    }

    const startTime = Date.now();

    const resultRef = await script.run(ctx, {
      timeout: actualTimeout,
      copy: true
    });

    const durationMs = Date.now() - startTime;

    // Unpack result if needed (same as runJsIsolatedVm)
    let output = resultRef;

    // Prioritize emitted value if exists
    if (emittedValue !== undefined) {
      output = emittedValue;
    } else if (typeof resultRef === 'object' && resultRef !== null && typeof (resultRef as any).copy === 'function') {
      output = await (resultRef as any).copy();
    }

    // Explicitly dispose context (script is cached or disposed by isolate)
    ctx.release();

    return {
      ok: true,
      output: output,
      consoleLogs: capturedConsoleLogs.length > 0 ? capturedConsoleLogs : undefined,
      durationMs,
    };

  } catch (error: any) {
    const msg = error.message || String(error);
    if (msg.includes("timed out") || msg.includes("timeout")) {
      return { ok: false, error: "TimeoutError: Execution exceeded time limit" };
    }
    return { ok: false, error: `SandboxError: ${msg}` };
  } finally {
    if (disposeIsolate && isolate) {
      isolate.dispose();
    }
  }
}

/**
 * Execute Python code with helpers and context injection
 * Helpers are serialized as utility functions available in Python
 */
async function runPythonWithHelpers(
  code: string,
  input: Record<string, unknown>,
  context: ScriptContextAPI,
  timeoutMs: number,
  _consoleEnabled: boolean
): Promise<ScriptExecutionResult> {
  return new Promise((resolve) => {
    try {
      // Enforce timeout limits
      const actualTimeout = Math.min(Math.max(timeoutMs, MIN_TIMEOUT_MS), MAX_TIMEOUT_MS);

      // Validate code size
      if (code.length > MAX_CODE_SIZE) {
        resolve({
          ok: false,
          error: `Code size exceeds ${MAX_CODE_SIZE / 1024}KB limit`,
        });
        return;
      }

      // Validate input size BEFORE combining with code to prevent DoS
      const inputJson = JSON.stringify(input);
      if (inputJson.length > MAX_INPUT_SIZE) {
        resolve({
          ok: false,
          error: `Input size exceeds ${MAX_INPUT_SIZE / 1024}KB limit. Size: ${inputJson.length} bytes.`,
        });
        return;
      }

      // Serialize context for Python
      const contextJson = JSON.stringify(context);

      // Prepare payload (Input + Code)
      const payload = {
        input,
        __sys_code__: code,
        __sys_context__: contextJson // Pass context string to be parsed in python
      };

      // Final combined size check (defense in depth)
      const payloadJson = JSON.stringify(payload);
      if (payloadJson.length > MAX_INPUT_SIZE + MAX_CODE_SIZE) {
        resolve({
          ok: false,
          error: `Combined payload size exceeds maximum allowed. Consider reducing input or code size.`,
        });
        return;
      }

      // Python wrapper script with helpers and context
      // Reads input, context, and code from stdin
      const pythonWrapper = `
import json
import sys
import math
from datetime import datetime, timedelta

# Restricted builtins - only safe operations allowed
safe_builtins = {
    'abs': abs,
    'all': all,
    'any': any,
    'bool': bool,
    'dict': dict,
    'enumerate': enumerate,
    'filter': filter,
    'float': float,
    'int': int,
    'len': len,
    'list': list,
    'map': map,
    'max': max,
    'min': min,
    'pow': pow,
    'range': range,
    'round': round,
    'set': set,
    'sorted': sorted,
    'str': str,
    'sum': sum,
    'tuple': tuple,
    'zip': zip,
    'True': True,
    'False': False,
    'None': None,
}

# Read payload from stdin
try:
    payload = json.loads(sys.stdin.read())
    input_data = payload.get('input', {})
    context_data = json.loads(payload.get('__sys_context__', '{}'))
    user_code = payload.get('__sys_code__', '')
except Exception as e:
    print(json.dumps({"ok": False, "error": "SystemError: Failed to read input payload"}))
    sys.exit(1)

# Track output
result = None
emit_called = False
console_logs = []

def emit(value):
    global result, emit_called
    if emit_called:
        raise Exception("emit() can only be called once")
    emit_called = True
    result = value

# Helper functions (Python implementations)
class Helpers:
    class date:
        @staticmethod
        def now():
            return datetime.now().isoformat()

        @staticmethod
        def add(date_str, value, unit):
            try:
                dt = datetime.fromisoformat(date_str.replace('Z', '+00:00'))
                if unit == 'days':
                    return (dt + timedelta(days=value)).isoformat()
                elif unit == 'hours':
                    return (dt + timedelta(hours=value)).isoformat()
                elif unit == 'minutes':
                    return (dt + timedelta(minutes=value)).isoformat()
                elif unit == 'seconds':
                    return (dt + timedelta(seconds=value)).isoformat()
                else:
                    raise ValueError(f"Unknown unit: {unit}")
            except Exception as e:
                raise ValueError(f"Date error: {str(e)}")

    class string:
        @staticmethod
        def upper(s):
            return str(s).upper()

        @staticmethod
        def lower(s):
            return str(s).lower()

        @staticmethod
        def trim(s):
            return str(s).strip()

        @staticmethod
        def slug(s):
            import re
            s = str(s).lower()
            s = re.sub(r'\\s+', '-', s)
            s = re.sub(r'[^a-z0-9-]', '', s)
            return s

    class number:
        @staticmethod
        def round(num, decimals=0):
            return round(float(num), decimals)

        @staticmethod
        def ceil(num):
            return math.ceil(float(num))

        @staticmethod
        def floor(num):
            return math.floor(float(num))

        @staticmethod
        def abs(num):
            return abs(float(num))

    class array:
        @staticmethod
        def unique(arr):
            # Sort to make deterministic, but handle mixed types gracefully
            return list(set(arr))

        @staticmethod
        def flatten(arr):
            result = []
            for item in arr:
                if isinstance(item, list):
                    result.extend(Helpers.array.flatten(item))
                else:
                    result.append(item)
            return result

    class math:
        @staticmethod
        def sum(arr):
            return sum(arr)

        @staticmethod
        def avg(arr):
            return sum(arr) / len(arr) if len(arr) > 0 else 0

        @staticmethod
        def min(arr):
            return min(arr)

        @staticmethod
        def max(arr):
            return max(arr)

    class console:
        @staticmethod
        def log(*args):
            console_logs.append(list(args))

        @staticmethod
        def warn(*args):
            console_logs.append(['[WARN]'] + list(args))

        @staticmethod
        def error(*args):
            console_logs.append(['[ERROR]'] + list(args))

helpers = Helpers()

# Create execution namespace
namespace = {
    '__builtins__': safe_builtins,
    'input': input_data,
    'context': context_data,
    'helpers': helpers,
    'emit': emit,
}

# Execute user code
try:
    exec(user_code, namespace)
except Exception as e:
    print(json.dumps({
        "ok": False, 
        "error": f"{type(e).__name__}: {str(e)}",
        "consoleLogs": console_logs
    }))
    sys.exit(0)

if not emit_called:
    print(json.dumps({
        "ok": False, 
        "error": "Code did not call emit() to produce output", 
        "consoleLogs": console_logs
    }))
    sys.exit(0)

# Output result as JSON
output = {
    "ok": True,
    "output": result
}

if console_logs:
    output["consoleLogs"] = console_logs

try:
    print(json.dumps(output))
except Exception as e:
     print(json.dumps({
        "ok": False, 
        "error": "OutputError: Failed to serialize output", 
        "consoleLogs": console_logs
    }))
`;

      let stdout = "";
      let stderr = "";
      let killed = false;
      const startTime = Date.now();

      // Spawn Python subprocess
      const pythonProcess = spawn("python3", ["-c", pythonWrapper], {
        timeout: actualTimeout,
        stdio: ["pipe", "pipe", "pipe"],
      });

      // Set timeout to kill process
      const timeoutHandle = setTimeout(() => {
        if (!pythonProcess.killed) {
          killed = true;
          pythonProcess.kill("SIGKILL");
        }
      }, actualTimeout);

      // Collect stdout
      pythonProcess.stdout.on("data", (data: Buffer) => {
        stdout += data.toString();
        // Enforce max output size
        if (stdout.length > MAX_OUTPUT_SIZE) {
          pythonProcess.kill("SIGKILL");
          killed = true;
        }
      });

      // Collect stderr
      pythonProcess.stderr.on("data", (data: Buffer) => {
        stderr += data.toString();
        if (stderr.length > MAX_OUTPUT_SIZE) {
          pythonProcess.kill("SIGKILL");
          killed = true;
        }
      });

      // Handle process completion
      pythonProcess.on("close", (code: number | null) => {
        clearTimeout(timeoutHandle);
        const durationMs = Date.now() - startTime;

        if (killed) {
          resolve({
            ok: false,
            error: "TimeoutError: Execution exceeded time limit",
            durationMs,
          });
          return;
        }

        if (code !== 0) {
          const errorLines = stderr.trim().split("\n");
          const lastLine = errorLines[errorLines.length - 1] || "Unknown error";
          resolve({
            ok: false,
            error: `PythonProcessError: ${lastLine.slice(0, 500)}`,
            durationMs,
          });
          return;
        }

        try {
          // Parse JSON output
          const result = JSON.parse(stdout.trim());
          result.durationMs = durationMs;
          resolve(result);
        } catch (parseError) {
          resolve({
            ok: false,
            error: `OutputError: Failed to parse Python output - ${parseError instanceof Error ? parseError.message : 'unknown error'}`,
            durationMs,
          });
        }
      });

      // Handle process errors
      pythonProcess.on("error", (error: Error) => {
        clearTimeout(timeoutHandle);
        resolve({
          ok: false,
          error: `ProcessError: ${error.message}`,
          durationMs: Date.now() - startTime,
        });
      });

      // Send payload to stdin
      pythonProcess.stdin.write(payloadJson);
      pythonProcess.stdin.end();
    } catch (error: any) {
      resolve({
        ok: false,
        error: `SetupError: ${error instanceof Error ? error.message : 'unknown error'}`,
      });
    }
  }); // End Promise
}

/**
 * Execute code with helpers and context injection
 * Main entry point for enhanced sandbox execution
 */
export async function executeCodeWithHelpers(
  params: ExecuteCodeWithHelpersParams
): Promise<ScriptExecutionResult> {
  const {
    language,
    code,
    input,
    context,
    helpers,
    timeoutMs = 1000,
    consoleEnabled = false,
  } = params;

  if (language === "javascript") {
    return runJsWithHelpers(
      code,
      input,
      context,
      helpers,
      timeoutMs,
      consoleEnabled,
      params.isolate,
      params.scriptCache
    );
  } else if (language === "python") {
    return runPythonWithHelpers(code, input, context, timeoutMs, consoleEnabled);
  } else {
    return {
      ok: false,
      error: `Unsupported language: ${language}`,
    };
  }
}

/**
 * Fallback execution using Node's native vm module
 * Used when isolated-vm is not available (e.g. dev/test environments)
 */
async function runJsWithVmFallback(
  code: string,
  input: Record<string, unknown>,
  context: ScriptContextAPI,
  actualHelpers: Record<string, unknown> | HelperLibraryAPI | undefined,
  timeoutMs: number,
  _consoleEnabled: boolean
): Promise<ScriptExecutionResult> {
  const consoleLogs: unknown[][] = [];

  const sandbox = {
    input,
    context,
    helpers: actualHelpers,
    console: {
      log: (...args: unknown[]) => consoleLogs.push(args),
      warn: (...args: unknown[]) => consoleLogs.push(['[WARN]', ...args]),
      error: (...args: unknown[]) => consoleLogs.push(['[ERROR]', ...args]),
      info: (...args: unknown[]) => consoleLogs.push(['[INFO]', ...args]),
    },
    emit: (val: unknown) => {
      // Mimic emit behavior: captures the value as the result
      (sandbox as any).__emitResult__ = val;
    }
  };

  const startTime = Date.now();
  try {
    // Wrap code in function IIFE to mimic isolated-vm behavior
    const wrappedCode = `
      (function(input, context, helpers) {
        ${code}
      })(input, context, helpers);
    `;

    const script = new vm.Script(wrappedCode);
    const result = script.runInNewContext(sandbox, {
      timeout: timeoutMs
    });

    return {
      ok: true,
      output: (sandbox as any).__emitResult__ !== undefined ? (sandbox as any).__emitResult__ : result,
      consoleLogs: consoleLogs.length > 0 ? consoleLogs : undefined,
      durationMs: Date.now() - startTime
    };
  } catch (error: any) {
    const msg = error.message;
    if (msg.includes("timed out")) {
      return { ok: false, error: "TimeoutError: Execution exceeded time limit" };
    }
    return { ok: false, error: `SandboxError: ${msg}` };
  }
}

/**
 * Centralized Error Handling Utilities
 * Provides consistent error handling across the backend
 */

import { Response } from "express";

/**
 * Base API Error class
 */
export class ApiError extends Error {
  constructor(
    message: string,
    public statusCode: number = 500,
    public code: string = 'INTERNAL_ERROR'
  ) {
    super(message);
    this.name = 'ApiError';
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Validation Error (400)
 */
export class ValidationError extends ApiError {
  constructor(
    message: string,
    public details?: Record<string, string>
  ) {
    super(message, 400, 'VALIDATION_ERROR');
    this.name = 'ValidationError';
  }
}

/**
 * Not Found Error (404)
 */
export class NotFoundError extends ApiError {
  constructor(resource: string = 'Resource') {
    super(`${resource} not found`, 404, 'NOT_FOUND');
    this.name = 'NotFoundError';
  }
}

/**
 * Unauthorized Error (401)
 */
export class UnauthorizedError extends ApiError {
  constructor(message = 'Unauthorized') {
    super(message, 401, 'UNAUTHORIZED');
    this.name = 'UnauthorizedError';
  }
}

/**
 * Forbidden Error (403)
 */
export class ForbiddenError extends ApiError {
  constructor(message = 'Access denied') {
    super(message, 403, 'FORBIDDEN');
    this.name = 'ForbiddenError';
  }
}

/**
 * Conflict Error (409)
 */
export class ConflictError extends ApiError {
  constructor(message: string) {
    super(message, 409, 'CONFLICT');
    this.name = 'ConflictError';
  }
}

/**
 * Bad Request Error (400)
 */
export class BadRequestError extends ApiError {
  constructor(message: string) {
    super(message, 400, 'BAD_REQUEST');
    this.name = 'BadRequestError';
  }
}

/**
 * Convert unknown error to ApiError
 */
export function handleError(error: unknown): ApiError {
  if (error instanceof ApiError) {
    return error;
  }

  if (error instanceof Error) {
    // Check for specific error patterns
    const message = error.message.toLowerCase();

    if (message.includes('not found')) {
      return new NotFoundError();
    }
    if (message.includes('unauthorized') || message.includes('authentication')) {
      return new UnauthorizedError(error.message);
    }
    if (message.includes('forbidden') || message.includes('permission')) {
      return new ForbiddenError(error.message);
    }
    if (message.includes('validation') || message.includes('invalid')) {
      return new ValidationError(error.message);
    }
    if (message.includes('conflict') || message.includes('already exists')) {
      return new ConflictError(error.message);
    }

    return new ApiError(error.message, 500, 'INTERNAL_ERROR');
  }

  return new ApiError('An unexpected error occurred', 500, 'INTERNAL_ERROR');
}

/**
 * Send standardized error response
 */
export function sendErrorResponse(res: Response, error: ApiError): Response {
  const response: any = {
    success: false,
    error: {
      code: error.code,
      message: error.message,
    },
  };

  // Add validation details if available
  if (error instanceof ValidationError && error.details) {
    response.error.details = error.details;
  }

  // Include stack trace in development
  if (process.env.NODE_ENV === 'development') {
    response.error.stack = error.stack;
  }

  return res.status(error.statusCode).json(response);
}

/**
 * Async route handler wrapper
 * Catches errors and sends standardized error responses
 */
export function asyncHandler(
  fn: (req: any, res: Response, next?: any) => Promise<any>
) {
  return (req: any, res: Response, next: any) => {
    Promise.resolve(fn(req, res, next)).catch((error) => {
      const apiError = handleError(error);
      sendErrorResponse(res, apiError);
    });
  };
}

/**
 * Standardized error codes for API responses
 */
export const ErrorCode = {
  // Authentication & Authorization
  UNAUTHORIZED: 'UNAUTHORIZED',
  FORBIDDEN: 'FORBIDDEN',
  NO_TENANT: 'NO_TENANT',
  TENANT_MISMATCH: 'TENANT_MISMATCH',

  // Resource
  NOT_FOUND: 'NOT_FOUND',
  CONFLICT: 'CONFLICT',

  // Validation
  VALIDATION_ERROR: 'VALIDATION_ERROR',
  INVALID_INPUT: 'INVALID_INPUT',

  // Workflow
  WORKFLOW_NOT_DRAFT: 'WORKFLOW_NOT_DRAFT',
  WORKFLOW_NO_VERSION: 'WORKFLOW_NO_VERSION',
  VERSION_NOT_FOUND: 'VERSION_NOT_FOUND',

  // Template
  INVALID_FILE_TYPE: 'INVALID_FILE_TYPE',
  FILE_UPLOAD_ERROR: 'FILE_UPLOAD_ERROR',

  // Run
  RUN_EXECUTION_ERROR: 'RUN_EXECUTION_ERROR',

  // System
  INTERNAL_ERROR: 'INTERNAL_ERROR',
  DATABASE_ERROR: 'DATABASE_ERROR',
} as const;

export type ErrorCodeType = typeof ErrorCode[keyof typeof ErrorCode];

/**
 * Standardized API error response shape
 */
export interface ApiErrorResponse {
  error: {
    code: ErrorCodeType;
    message: string;
    details?: any;
  };
}

/**
 * Custom API Error class
 */
export class ApiError extends Error {
  constructor(
    public code: ErrorCodeType,
    message: string,
    public details?: any,
    public statusCode: number = 500
  ) {
    super(message);
    this.name = 'ApiError';
  }

  toJSON(): ApiErrorResponse {
    return {
      error: {
        code: this.code,
        message: this.message,
        details: this.details,
      },
    };
  }
}

/**
 * Error factory functions for common error types
 */
export const createError = {
  unauthorized(message = 'Authentication required', details?: any): ApiError {
    return new ApiError(ErrorCode.UNAUTHORIZED, message, details, 401);
  },

  forbidden(message = 'Permission denied', details?: any): ApiError {
    return new ApiError(ErrorCode.FORBIDDEN, message, details, 403);
  },

  notFound(resource: string, id?: string, details?: any): ApiError {
    const message = id ? `${resource} with id '${id}' not found` : `${resource} not found`;
    return new ApiError(ErrorCode.NOT_FOUND, message, details, 404);
  },

  conflict(message: string, details?: any): ApiError {
    return new ApiError(ErrorCode.CONFLICT, message, details, 409);
  },

  validation(message: string, details?: any): ApiError {
    return new ApiError(ErrorCode.VALIDATION_ERROR, message, details, 400);
  },

  invalidInput(message: string, details?: any): ApiError {
    return new ApiError(ErrorCode.INVALID_INPUT, message, details, 400);
  },

  badRequest(message: string, details?: any): ApiError {
    return new ApiError(ErrorCode.INVALID_INPUT, message, details, 400);
  },

  workflowNotDraft(message = 'Workflow must be in draft status to edit'): ApiError {
    return new ApiError(ErrorCode.WORKFLOW_NOT_DRAFT, message, undefined, 400);
  },

  workflowNoVersion(message = 'No published version available for this workflow'): ApiError {
    return new ApiError(ErrorCode.WORKFLOW_NO_VERSION, message, undefined, 400);
  },

  invalidFileType(message = 'Invalid file type', details?: any): ApiError {
    return new ApiError(ErrorCode.INVALID_FILE_TYPE, message, details, 400);
  },

  internal(message = 'Internal server error', details?: any): ApiError {
    return new ApiError(ErrorCode.INTERNAL_ERROR, message, details, 500);
  },

  database(message = 'Database error', details?: any): ApiError {
    return new ApiError(ErrorCode.DATABASE_ERROR, message, details, 500);
  },
};

/**
 * Format error response for Express
 */
export function formatErrorResponse(error: any): { status: number; body: ApiErrorResponse } {
  if (error instanceof ApiError) {
    return {
      status: error.statusCode,
      body: error.toJSON(),
    };
  }

  // Handle Zod validation errors
  if (error.name === 'ZodError') {
    return {
      status: 400,
      body: {
        error: {
          code: ErrorCode.VALIDATION_ERROR,
          message: 'Validation failed',
          details: error.errors,
        },
      },
    };
  }

  // Generic error
  return {
    status: 500,
    body: {
      error: {
        code: ErrorCode.INTERNAL_ERROR,
        message: error.message || 'Internal server error',
      },
    },
  };
}

/**
 * Smart Field Name Normalizer
 *
 * Intelligent field name matching for auto-mapping suggestions.
 * Uses multiple strategies to find the best matches between template fields
 * and workflow variables.
 *
 * Features:
 * - Case-insensitive matching
 * - Common abbreviation expansion
 * - Special character normalization
 * - Levenshtein distance (fuzzy matching)
 * - Semantic similarity
 * - Confidence scoring
 *
 * Usage:
 * ```typescript
 * const normalizer = new FieldNameNormalizer();
 *
 * const matches = normalizer.findBestMatches(
 *   ['client_name', 'client_email', 'invoice_total'],
 *   ['clientName', 'emailAddress', 'totalAmount']
 * );
 *
 * console.log(matches);
 * // [
 * //   { templateField: 'client_name', workflowVariable: 'clientName', confidence: 0.95, method: 'normalized' },
 * //   { templateField: 'client_email', workflowVariable: 'emailAddress', confidence: 0.78, method: 'semantic' },
 * //   ...
 * // ]
 * ```
 */

// ============================================================================
// TYPES
// ============================================================================

export interface FieldMatch {
  templateField: string;
  workflowVariable: string | null;
  confidence: number; // 0-1
  method: 'exact' | 'normalized' | 'fuzzy' | 'semantic' | 'abbreviation';
  alternatives?: Array<{
    variable: string;
    confidence: number;
  }>;
}

export interface NormalizationOptions {
  /** Minimum confidence score to consider a match (0-1) */
  minConfidence?: number;

  /** Maximum Levenshtein distance for fuzzy matches */
  maxDistance?: number;

  /** Include alternative suggestions */
  includeAlternatives?: boolean;

  /** Number of alternatives to include */
  alternativeCount?: number;
}

// ============================================================================
// ABBREVIATION DICTIONARY
// ============================================================================

const COMMON_ABBREVIATIONS: Record<string, string[]> = {
  // Names
  fname: ['firstname', 'first_name', 'givenname'],
  lname: ['lastname', 'last_name', 'surname', 'familyname'],
  mname: ['middlename', 'middle_name'],

  // Contact
  addr: ['address'],
  st: ['street'],
  apt: ['apartment'],
  tel: ['telephone', 'phone'],
  mob: ['mobile', 'cellphone'],
  ph: ['phone'],
  fax: ['facsimile'],

  // Business
  co: ['company'],
  org: ['organization', 'organisation'],
  dept: ['department'],
  mgr: ['manager'],
  emp: ['employee'],

  // Dates
  dob: ['dateofbirth', 'birthdate'],
  dt: ['date'],
  yr: ['year'],
  mo: ['month'],

  // Location
  zip: ['zipcode', 'postalcode'],
  ctry: ['country'],
  prov: ['province'],

  // Document
  doc: ['document'],
  num: ['number'],
  qty: ['quantity'],
  amt: ['amount'],
  tot: ['total'],
  inv: ['invoice'],

  // Misc
  desc: ['description'],
  stat: ['status'],
  info: ['information'],
  id: ['identifier'],
  ref: ['reference'],
  acct: ['account'],
  bal: ['balance'],
};

// Common word substitutions
const WORD_SUBSTITUTIONS: Record<string, string[]> = {
  client: ['customer', 'patron'],
  email: ['emailaddress', 'mail'],
  phone: ['telephone', 'phonenumber', 'contact'],
  name: ['fullname'],
  total: ['sum', 'amount'],
  date: ['datetime', 'timestamp'],
};

// ============================================================================
// NORMALIZER CLASS
// ============================================================================

export class FieldNameNormalizer {
  private options: Required<NormalizationOptions>;

  constructor(options: NormalizationOptions = {}) {
    this.options = {
      minConfidence: options.minConfidence ?? 0.6,
      maxDistance: options.maxDistance ?? 3,
      includeAlternatives: options.includeAlternatives ?? true,
      alternativeCount: options.alternativeCount ?? 3,
    };
  }

  /**
   * Find best matches for all template fields
   */
  findBestMatches(
    templateFields: string[],
    workflowVariables: string[]
  ): FieldMatch[] {
    const matches: FieldMatch[] = [];

    for (const templateField of templateFields) {
      const match = this.findBestMatch(templateField, workflowVariables);
      matches.push(match);
    }

    return matches;
  }

  /**
   * Find best match for a single template field
   */
  findBestMatch(
    templateField: string,
    workflowVariables: string[]
  ): FieldMatch {
    // Try each matching strategy in order of precision
    const strategies: Array<{
      name: FieldMatch['method'];
      fn: (field: string, vars: string[]) => { variable: string; confidence: number } | null;
    }> = [
      { name: 'exact', fn: this.exactMatch.bind(this) },
      { name: 'normalized', fn: this.normalizedMatch.bind(this) },
      { name: 'abbreviation', fn: this.abbreviationMatch.bind(this) },
      { name: 'semantic', fn: this.semanticMatch.bind(this) },
      { name: 'fuzzy', fn: this.fuzzyMatch.bind(this) },
    ];

    let bestMatch: FieldMatch = {
      templateField,
      workflowVariable: null,
      confidence: 0,
      method: 'exact',
    };

    // Try each strategy
    for (const strategy of strategies) {
      const result = strategy.fn(templateField, workflowVariables);

      if (result && result.confidence > bestMatch.confidence) {
        bestMatch = {
          templateField,
          workflowVariable: result.variable,
          confidence: result.confidence,
          method: strategy.name,
        };

        // If we found a high-confidence match, stop searching
        if (result.confidence >= 0.95) {
          break;
        }
      }
    }

    // Add alternatives if requested
    if (this.options.includeAlternatives && workflowVariables.length > 1) {
      bestMatch.alternatives = this.findAlternatives(
        templateField,
        workflowVariables,
        bestMatch.workflowVariable
      );
    }

    return bestMatch;
  }

  /**
   * Exact match (case-insensitive)
   */
  private exactMatch(
    field: string,
    variables: string[]
  ): { variable: string; confidence: number } | null {
    const normalized = field.toLowerCase();

    for (const variable of variables) {
      if (variable.toLowerCase() === normalized) {
        return { variable, confidence: 1.0 };
      }
    }

    return null;
  }

  /**
   * Normalized match (remove special chars, case-insensitive)
   */
  private normalizedMatch(
    field: string,
    variables: string[]
  ): { variable: string; confidence: number } | null {
    const normalizedField = this.normalize(field);

    for (const variable of variables) {
      const normalizedVar = this.normalize(variable);

      if (normalizedField === normalizedVar) {
        return { variable, confidence: 0.95 };
      }
    }

    return null;
  }

  /**
   * Abbreviation expansion match
   */
  private abbreviationMatch(
    field: string,
    variables: string[]
  ): { variable: string; confidence: number } | null {
    const normalizedField = this.normalize(field);

    // Check if field is an abbreviation
    for (const [abbr, expansions] of Object.entries(COMMON_ABBREVIATIONS)) {
      if (normalizedField === abbr || normalizedField.includes(abbr)) {
        // Try to match expanded forms
        for (const expansion of expansions) {
          for (const variable of variables) {
            const normalizedVar = this.normalize(variable);

            if (normalizedVar === expansion || normalizedVar.includes(expansion)) {
              return { variable, confidence: 0.85 };
            }
          }
        }
      }
    }

    // Check if variable is an abbreviation
    for (const variable of variables) {
      const normalizedVar = this.normalize(variable);

      for (const [abbr, expansions] of Object.entries(COMMON_ABBREVIATIONS)) {
        if (normalizedVar === abbr || normalizedVar.includes(abbr)) {
          for (const expansion of expansions) {
            if (normalizedField === expansion || normalizedField.includes(expansion)) {
              return { variable, confidence: 0.85 };
            }
          }
        }
      }
    }

    return null;
  }

  /**
   * Semantic match (word substitutions)
   */
  private semanticMatch(
    field: string,
    variables: string[]
  ): { variable: string; confidence: number } | null {
    const normalizedField = this.normalize(field);

    for (const [word, synonyms] of Object.entries(WORD_SUBSTITUTIONS)) {
      if (normalizedField.includes(word)) {
        // Try to match with synonyms
        for (const synonym of synonyms) {
          for (const variable of variables) {
            const normalizedVar = this.normalize(variable);

            const replacedField = normalizedField.replace(word, synonym);

            if (replacedField === normalizedVar) {
              return { variable, confidence: 0.80 };
            }
          }
        }
      }
    }

    return null;
  }

  /**
   * Fuzzy match (Levenshtein distance)
   */
  private fuzzyMatch(
    field: string,
    variables: string[]
  ): { variable: string; confidence: number } | null {
    const normalizedField = this.normalize(field);

    let bestMatch: { variable: string; distance: number } | null = null;

    for (const variable of variables) {
      const normalizedVar = this.normalize(variable);
      const distance = this.levenshteinDistance(normalizedField, normalizedVar);

      if (
        distance <= this.options.maxDistance &&
        (!bestMatch || distance < bestMatch.distance)
      ) {
        bestMatch = { variable, distance };
      }
    }

    if (bestMatch) {
      // Calculate confidence based on distance
      const maxLength = Math.max(normalizedField.length, this.normalize(bestMatch.variable).length);
      const confidence = 1 - bestMatch.distance / maxLength;

      if (confidence >= this.options.minConfidence) {
        return { variable: bestMatch.variable, confidence };
      }
    }

    return null;
  }

  /**
   * Find alternative matches
   */
  private findAlternatives(
    field: string,
    variables: string[],
    excludeVariable: string | null
  ): Array<{ variable: string; confidence: number }> {
    const alternatives: Array<{ variable: string; confidence: number }> = [];

    for (const variable of variables) {
      if (variable === excludeVariable) {continue;}

      // Calculate confidence using fuzzy matching
      const normalizedField = this.normalize(field);
      const normalizedVar = this.normalize(variable);
      const distance = this.levenshteinDistance(normalizedField, normalizedVar);
      const maxLength = Math.max(normalizedField.length, normalizedVar.length);
      const confidence = 1 - distance / maxLength;

      if (confidence >= this.options.minConfidence) {
        alternatives.push({ variable, confidence });
      }
    }

    // Sort by confidence and take top N
    return alternatives
      .sort((a, b) => b.confidence - a.confidence)
      .slice(0, this.options.alternativeCount);
  }

  /**
   * Normalize a field name
   */
  private normalize(name: string): string {
    return name
      .toLowerCase()
      .replace(/[^a-z0-9]/g, '') // Remove special chars
      .replace(/\s+/g, ''); // Remove spaces
  }

  /**
   * Calculate Levenshtein distance (edit distance)
   */
  private levenshteinDistance(str1: string, str2: string): number {
    const len1 = str1.length;
    const len2 = str2.length;

    // Create matrix
    const matrix: number[][] = [];

    for (let i = 0; i <= len1; i++) {
      matrix[i] = [i];
    }

    for (let j = 0; j <= len2; j++) {
      matrix[0][j] = j;
    }

    // Fill matrix
    for (let i = 1; i <= len1; i++) {
      for (let j = 1; j <= len2; j++) {
        const cost = str1[i - 1] === str2[j - 1] ? 0 : 1;

        matrix[i][j] = Math.min(
          matrix[i - 1][j] + 1, // deletion
          matrix[i][j - 1] + 1, // insertion
          matrix[i - 1][j - 1] + cost // substitution
        );
      }
    }

    return matrix[len1][len2];
  }

  /**
   * Batch normalize field names
   */
  static normalizeAll(fields: string[]): Record<string, string> {
    const normalizer = new FieldNameNormalizer();
    const result: Record<string, string> = {};

    for (const field of fields) {
      result[field] = normalizer.normalize(field);
    }

    return result;
  }

  /**
   * Check if two field names are similar
   */
  static areSimilar(field1: string, field2: string, threshold: number = 0.7): boolean {
    const normalizer = new FieldNameNormalizer({ minConfidence: threshold });
    const match = normalizer.findBestMatch(field1, [field2]);
    return match.confidence >= threshold;
  }
}

// Singleton instance
export const fieldNameNormalizer = new FieldNameNormalizer();

/**
 * JSON Path Selector Utility
 * Minimal JSONPath-like selector for extracting values from JSON responses
 *
 * Supported syntax:
 * - Root: $ or @
 * - Dot notation: $.user.name
 * - Bracket notation: $['user']['name']
 * - Array index: $.items[0]
 * - Nested: $.users[0].profile.email
 *
 * Not supported (for MVP):
 * - Wildcards: $.*
 * - Recursive descent: $..name
 * - Filters: $[?(@.price < 10)]
 * - Slices: $[0:5]
 */

/**
 * Select a value from a JSON object using a path selector
 *
 * @param obj The object to select from
 * @param selector The selector path (e.g., '$.user.name', '$.items[0].id')
 * @returns The selected value, or undefined if not found
 */
export function select(obj: any, selector: string): any {
  if (!obj || typeof obj !== 'object') {
    return undefined;
  }

  // Normalize selector
  const normalized = normalizeSelector(selector);
  if (!normalized) {
    return undefined;
  }

  // Parse into path parts
  const parts = parseSelector(normalized);

  // Traverse the object
  return traverse(obj, parts);
}

/**
 * Normalize a selector string
 * Converts various formats to a consistent format
 */
function normalizeSelector(selector: string): string | null {
  if (!selector || typeof selector !== 'string') {
    return null;
  }

  let s = selector.trim();

  // Remove leading $ or @
  if (s.startsWith('$') || s.startsWith('@')) {
    s = s.substring(1);
  }

  // Remove leading dot if present
  if (s.startsWith('.')) {
    s = s.substring(1);
  }

  return s;
}

/**
 * Parse a selector into path parts
 * Example: "user.profile['email']" -> ['user', 'profile', 'email']
 * Example: "items[0].name" -> ['items', '0', 'name']
 */
function parseSelector(selector: string): string[] {
  if (!selector) {
    return [];
  }

  const parts: string[] = [];
  let current = '';
  let inBracket = false;
  let inQuote = false;
  let quoteChar = '';

  for (let i = 0; i < selector.length; i++) {
    const char = selector[i];

    if (char === '[' && !inQuote) {
      // Start of bracket notation
      if (current) {
        parts.push(current);
        current = '';
      }
      inBracket = true;
    } else if (char === ']' && !inQuote) {
      // End of bracket notation
      if (current) {
        parts.push(current);
        current = '';
      }
      inBracket = false;
    } else if ((char === '"' || char === "'") && inBracket) {
      // Quote inside bracket
      if (!inQuote) {
        inQuote = true;
        quoteChar = char;
      } else if (char === quoteChar) {
        inQuote = false;
        quoteChar = '';
      }
    } else if (char === '.' && !inBracket && !inQuote) {
      // Dot separator
      if (current) {
        parts.push(current);
        current = '';
      }
    } else {
      // Regular character
      current += char;
    }
  }

  // Add final part
  if (current) {
    parts.push(current);
  }

  return parts;
}

/**
 * Traverse an object following a path
 */
function traverse(obj: any, parts: string[]): any {
  let current = obj;

  for (const part of parts) {
    if (current === null || current === undefined) {
      return undefined;
    }

    // Handle array index
    if (/^\d+$/.test(part)) {
      const index = parseInt(part, 10);
      if (Array.isArray(current)) {
        current = current[index];
      } else {
        return undefined;
      }
    } else {
      // Handle object property
      if (typeof current === 'object' && part in current) {
        current = current[part];
      } else {
        return undefined;
      }
    }
  }

  return current;
}

/**
 * Validate a selector syntax
 * Returns true if the selector is valid, false otherwise
 */
export function validateSelector(selector: string): { valid: boolean; error?: string } {
  if (!selector || typeof selector !== 'string') {
    return { valid: false, error: 'Selector must be a non-empty string' };
  }

  try {
    const normalized = normalizeSelector(selector);
    if (normalized === null) {
      return { valid: false, error: 'Invalid selector format' };
    }

    const parts = parseSelector(normalized);
    if (parts.length === 0 && normalized.length > 0) {
      return { valid: false, error: 'Failed to parse selector' };
    }

    // Check for unclosed brackets
    const openBrackets = (normalized.match(/\[/g) ?? []).length;
    const closeBrackets = (normalized.match(/\]/g) ?? []).length;
    if (openBrackets !== closeBrackets) {
      return { valid: false, error: 'Unclosed brackets in selector' };
    }

    return { valid: true };
  } catch (error) {
    return { valid: false, error: (error as Error).message };
  }
}

/**
 * Test a selector against a sample object
 * Useful for debugging and validation
 */
export function testSelector(obj: any, selector: string): {
  success: boolean;
  value?: any;
  error?: string;
} {
  try {
    const validation = validateSelector(selector);
    if (!validation.valid) {
      return { success: false, error: validation.error };
    }

    const value = select(obj, selector);
    return { success: true, value };
  } catch (error) {
    return { success: false, error: (error as Error).message };
  }
}

/**
 * Select multiple values using multiple selectors
 * Returns an object with selector results
 */
export function selectMultiple(
  obj: any,
  selectors: Record<string, string>
): Record<string, any> {
  const results: Record<string, any> = {};

  for (const [key, selector] of Object.entries(selectors)) {
    results[key] = select(obj, selector);
  }

  return results;
}

/**
 * List Variable Validator
 * Validates that an object conforms to the ListVariable interface
 */

import type { ListVariable } from "@shared/types/blocks";

import { logger } from "../logger";

/**
 * Check if a value is a valid ListVariable
 */
export function isListVariable(value: unknown): value is ListVariable {
  if (!value || typeof value !== "object") {
    return false;
  }

  const v = value as any;

  // Check required properties
  if (!v.metadata || typeof v.metadata !== "object") {
    return false;
  }

  if (!v.rows || !Array.isArray(v.rows)) {
    return false;
  }

  if (typeof v.count !== "number") {
    return false;
  }

  if (!v.columns || !Array.isArray(v.columns)) {
    return false;
  }

  // Check metadata has required fields
  if (!v.metadata.source) {
    return false;
  }

  // Check columns have required structure
  for (const col of v.columns) {
    if (!col.id || !col.name || !col.type) {
      return false;
    }
  }

  return true;
}

/**
 * Validate and normalize a potential ListVariable output
 * Returns the value if valid, or null if invalid
 */
export function validateListVariable(
  value: unknown,
  context?: { stepId?: string; stepAlias?: string }
): ListVariable | null {
  if (!isListVariable(value)) {
    logger.warn(
      {
        stepId: context?.stepId,
        stepAlias: context?.stepAlias,
        hasMetadata: !!(value as any)?.metadata,
        hasRows: Array.isArray((value as any)?.rows),
        hasCount: typeof (value as any)?.count === "number",
        hasColumns: Array.isArray((value as any)?.columns),
      },
      "Invalid ListVariable format in JS block output"
    );
    return null;
  }

  return value;
}

/**
 * Create an empty ListVariable
 */
export function createEmptyListVariable(
  source: "read_table" | "query" | "list_tools" = "read_table"
): ListVariable {
  return {
    metadata: {
      source,
    },
    rows: [],
    count: 0,
    columns: [],
  };
}

import { logger } from "../logger";

// Magic Bytes
const SIGNATURES = {
    PDF: [0x25, 0x50, 0x44, 0x46], // %PDF
    ZIP: [0x50, 0x4B, 0x03, 0x04], // PK.. (Common ZIP)
};

/**
 * Validate that the file buffer matches the expected format signature.
 * 
 * @param buffer - File content buffer
 * @param filename - Original filename (for extension check context)
 * @returns boolean - true if valid, false if mismatch
 */
export function validateMagicBytes(buffer: Buffer, filename: string): boolean {
    if (!buffer || buffer.length < 4) {return false;}

    const ext = filename.toLowerCase().split('.').pop() ?? '';

    // Check PDF
    if (ext === 'pdf') {
        const isPdf = compareBytes(buffer, SIGNATURES.PDF);
        if (!isPdf) {
            logger.warn({ filename, head: buffer.subarray(0, 4).toString('hex') }, 'Magic Byte Mismatch: Expected PDF');
        }
        return isPdf;
    }

    // Check DOCX (Zip container)
    if (ext === 'docx') {
        const isZip = compareBytes(buffer, SIGNATURES.ZIP);
        if (!isZip) {
            // Some docx tools might use empty/spanned zip signatures? 
            // Stick to standard PK\x03\x04 for now.
            logger.warn({ filename, head: buffer.subarray(0, 4).toString('hex') }, 'Magic Byte Mismatch: Expected ZIP/DOCX');
        }
        return isZip;
    }

    // Allow others (txt/md) or default true if not strictly enforced
    if (['txt', 'md'].includes(ext)) {
        return true;
    }

    // If extension is not one we strictly check, assume safe (or handled by other validators)
    // But for this task, we focus on PDF/DOCX spoofing.
    return true;
}

function compareBytes(buffer: Buffer, signature: number[]): boolean {
    for (let i = 0; i < signature.length; i++) {
        if (buffer[i] !== signature[i]) {return false;}
    }
    return true;
}

import { z } from 'zod';

/**
 * Pagination query parameters schema
 */
export const paginationQuerySchema = z.object({
  cursor: z.string().optional(),
  limit: z.coerce.number().int().min(1).max(100).default(20),
});

export type PaginationQuery = z.infer<typeof paginationQuerySchema>;

/**
 * Paginated response wrapper
 */
export interface PaginatedResponse<T> {
  items: T[];
  nextCursor: string | null;
  hasMore: boolean;
}

/**
 * Create paginated response
 */
export function createPaginatedResponse<T extends { id: string; createdAt: Date | null }>(
  items: T[],
  limit: number
): PaginatedResponse<T> {
  const hasMore = items.length > limit;
  const responseItems = hasMore ? items.slice(0, limit) : items;

  const nextCursor = hasMore && responseItems.length > 0
    ? encodeCursor(responseItems[responseItems.length - 1])
    : null;

  return {
    items: responseItems,
    nextCursor,
    hasMore,
  };
}

/**
 * Cursor encoding/decoding
 * Format: base64(id:timestamp)
 */
export function encodeCursor(item: { id: string; createdAt: Date | null }): string {
  const timestamp = item.createdAt?.getTime() || Date.now();
  const payload = `${item.id}:${timestamp}`;
  return Buffer.from(payload).toString('base64');
}

export function decodeCursor(cursor: string): { id: string; timestamp: number } | null {
  try {
    const decoded = Buffer.from(cursor, 'base64').toString('utf-8');
    const [id, timestampStr] = decoded.split(':');
    const timestamp = parseInt(timestampStr, 10);

    if (!id || isNaN(timestamp)) {
      return null;
    }

    return { id, timestamp };
  } catch {
    return null;
  }
}

/**
 * Build WHERE clause for cursor pagination
 * This uses a composite index on (createdAt, id) for efficient pagination
 */
export function buildCursorWhere(cursor: string | undefined): { timestamp?: Date; id?: string } | null {
  if (!cursor) {
    return null;
  }

  const decoded = decodeCursor(cursor);
  if (!decoded) {
    return null;
  }

  return {
    timestamp: new Date(decoded.timestamp),
    id: decoded.id,
  };
}

/**
 * Standardized API Response Utilities
 *
 * Provides consistent response formats for success and error cases.
 */

import { Response } from 'express';

import { AuthErrorCode, AuthenticationError, isAuthenticationError } from '../errors/AuthErrors';

/**
 * Standard error response structure
 */
export interface ErrorResponse {
  success: false;
  error: {
    code: string;
    message: string;
    details?: Record<string, unknown>;
    timestamp: string;
  };
}

/**
 * Standard success response structure
 */
export interface SuccessResponse<T = unknown> {
  success: true;
  data: T;
  timestamp: string;
}

/**
 * Authentication error code mappings
 */
export const AUTH_ERROR_CODES = {
  AUTHENTICATION_FAILED: AuthErrorCode.AUTHENTICATION_FAILED,
  TOKEN_EXPIRED: AuthErrorCode.TOKEN_EXPIRED,
  INVALID_TOKEN: AuthErrorCode.INVALID_TOKEN,
  INVALID_CREDENTIALS: AuthErrorCode.INVALID_CREDENTIALS,
  ACCOUNT_LOCKED: AuthErrorCode.ACCOUNT_LOCKED,
  EMAIL_NOT_VERIFIED: AuthErrorCode.EMAIL_NOT_VERIFIED,
  MFA_REQUIRED: AuthErrorCode.MFA_REQUIRED,
  UNAUTHORIZED: AuthErrorCode.UNAUTHORIZED,
  FORBIDDEN: AuthErrorCode.FORBIDDEN,
} as const;

/**
 * General error codes for non-auth errors
 */
export const ERROR_CODES = {
  VALIDATION_ERROR: 'ERR_001',
  NOT_FOUND: 'ERR_002',
  INTERNAL_ERROR: 'ERR_003',
  BAD_REQUEST: 'ERR_004',
  CONFLICT: 'ERR_005',
  RATE_LIMIT_EXCEEDED: 'ERR_006',
  SERVICE_UNAVAILABLE: 'ERR_007',
} as const;

/**
 * Create a standardized error response
 */
export function errorResponse(
  code: string,
  message: string,
  details?: Record<string, unknown>
): ErrorResponse {
  return {
    success: false,
    error: {
      code,
      message,
      ...(details && { details }),
      timestamp: new Date().toISOString(),
    },
  };
}

/**
 * Create a standardized success response
 */
export function successResponse<T>(data: T): SuccessResponse<T> {
  return {
    success: true,
    data,
    timestamp: new Date().toISOString(),
  };
}

/**
 * Send an error response from an Error object
 */
export function sendErrorResponse(
  res: Response,
  error: Error | AuthenticationError,
  statusCode?: number
): Response {
  // Handle authentication errors
  if (isAuthenticationError(error)) {
    return res.status(error.statusCode).json(
      errorResponse(error.code, error.message, {
        // Include additional details for specific error types
        ...(error instanceof Error && error.constructor.name !== 'AuthenticationError'
          ? { errorType: error.constructor.name }
          : {}),
      })
    );
  }

  // Handle validation errors (e.g., from Zod)
  if (error.name === 'ZodError') {
    return res.status(400).json(
      errorResponse(ERROR_CODES.VALIDATION_ERROR, 'Validation failed', {
        validationErrors: (error as any).errors,
      })
    );
  }

  // Handle generic errors
  const status = statusCode || 500;
  const code = status === 404 ? ERROR_CODES.NOT_FOUND : ERROR_CODES.INTERNAL_ERROR;

  return res.status(status).json(errorResponse(code, error.message));
}

/**
 * Send a success response
 */
export function sendSuccessResponse<T>(res: Response, data: T, statusCode: number = 200): Response {
  return res.status(statusCode).json(successResponse(data));
}

/**
 * Send a paginated response
 */
export interface PaginatedResponse<T> {
  success: true;
  data: T[];
  pagination: {
    page: number;
    pageSize: number;
    totalItems: number;
    totalPages: number;
    hasNext: boolean;
    hasPrevious: boolean;
  };
  timestamp: string;
}

export function paginatedResponse<T>(
  data: T[],
  page: number,
  pageSize: number,
  totalItems: number
): PaginatedResponse<T> {
  const totalPages = Math.ceil(totalItems / pageSize);

  return {
    success: true,
    data,
    pagination: {
      page,
      pageSize,
      totalItems,
      totalPages,
      hasNext: page < totalPages,
      hasPrevious: page > 1,
    },
    timestamp: new Date().toISOString(),
  };
}

/**
 * Send a paginated response
 */
export function sendPaginatedResponse<T>(
  res: Response,
  data: T[],
  page: number,
  pageSize: number,
  totalItems: number,
  statusCode: number = 200
): Response {
  return res.status(statusCode).json(paginatedResponse(data, page, pageSize, totalItems));
}

/**
 * Common HTTP status codes
 */
export const HTTP_STATUS = {
  OK: 200,
  CREATED: 201,
  NO_CONTENT: 204,
  BAD_REQUEST: 400,
  UNAUTHORIZED: 401,
  FORBIDDEN: 403,
  NOT_FOUND: 404,
  CONFLICT: 409,
  UNPROCESSABLE_ENTITY: 422,
  TOO_MANY_REQUESTS: 429,
  INTERNAL_SERVER_ERROR: 500,
  SERVICE_UNAVAILABLE: 503,
} as const;

/**
 * Helper to send common status responses
 */
export const send = {
  ok: <T>(res: Response, data: T) => sendSuccessResponse(res, data, HTTP_STATUS.OK),
  created: <T>(res: Response, data: T) => sendSuccessResponse(res, data, HTTP_STATUS.CREATED),
  noContent: (res: Response) => res.status(HTTP_STATUS.NO_CONTENT).send(),
  badRequest: (res: Response, message: string) =>
    res.status(HTTP_STATUS.BAD_REQUEST).json(errorResponse(ERROR_CODES.BAD_REQUEST, message)),
  unauthorized: (res: Response, message: string = 'Authentication required') =>
    res
      .status(HTTP_STATUS.UNAUTHORIZED)
      .json(errorResponse(AUTH_ERROR_CODES.UNAUTHORIZED, message)),
  forbidden: (res: Response, message: string = 'Insufficient permissions') =>
    res.status(HTTP_STATUS.FORBIDDEN).json(errorResponse(AUTH_ERROR_CODES.FORBIDDEN, message)),
  notFound: (res: Response, message: string = 'Resource not found') =>
    res.status(HTTP_STATUS.NOT_FOUND).json(errorResponse(ERROR_CODES.NOT_FOUND, message)),
  conflict: (res: Response, message: string) =>
    res.status(HTTP_STATUS.CONFLICT).json(errorResponse(ERROR_CODES.CONFLICT, message)),
  rateLimitExceeded: (res: Response, message: string = 'Too many requests') =>
    res
      .status(HTTP_STATUS.TOO_MANY_REQUESTS)
      .json(errorResponse(ERROR_CODES.RATE_LIMIT_EXCEEDED, message)),
  internalError: (res: Response, message: string = 'Internal server error') =>
    res
      .status(HTTP_STATUS.INTERNAL_SERVER_ERROR)
      .json(errorResponse(ERROR_CODES.INTERNAL_ERROR, message)),
  serviceUnavailable: (res: Response, message: string = 'Service temporarily unavailable') =>
    res
      .status(HTTP_STATUS.SERVICE_UNAVAILABLE)
      .json(errorResponse(ERROR_CODES.SERVICE_UNAVAILABLE, message)),
};

import { Request, Response, NextFunction } from 'express';
import DOMPurify from 'isomorphic-dompurify';

/**
 * Sanitizes a string by removing all HTML tags and scripts
 * Prevents XSS attacks by stripping dangerous content
 */
export function sanitizeString(input: string): string {
  if (typeof input !== 'string') {return input;}

  // Remove HTML tags and scripts while keeping text content
  return DOMPurify.sanitize(input, {
    ALLOWED_TAGS: [], // No HTML tags allowed
    KEEP_CONTENT: true, // Keep text content
  });
}

/**
 * Recursively sanitizes all string values in an object
 * Handles nested objects and arrays
 */
export function sanitizeObject<T extends Record<string, any>>(obj: T): T {
  if (obj === null || obj === undefined) {return obj;}
  if (typeof obj !== 'object') {return obj;}

  const sanitized: any = Array.isArray(obj) ? [] : {};

  for (const [key, value] of Object.entries(obj)) {
    if (typeof value === 'string') {
      sanitized[key] = sanitizeString(value);
    } else if (Array.isArray(value)) {
      sanitized[key] = value.map(item =>
        typeof item === 'object' ? sanitizeObject(item) :
        typeof item === 'string' ? sanitizeString(item) : item
      );
    } else if (typeof value === 'object' && value !== null) {
      sanitized[key] = sanitizeObject(value);
    } else {
      sanitized[key] = value;
    }
  }

  return sanitized;
}

/**
 * Express middleware to sanitize all string inputs in req.body and req.query
 * Apply this after express.json() and express.urlencoded() middleware
 *
 * Usage:
 * app.use(express.json());
 * app.use(sanitizeInputs); // Apply sanitization
 */
export function sanitizeInputs(req: Request, res: Response, next: NextFunction): void {
  if (req.body && typeof req.body === 'object') {
    req.body = sanitizeObject(req.body);
  }

  if (req.query && typeof req.query === 'object') {
    req.query = sanitizeObject(req.query as Record<string, any>);
  }

  next();
}

/**
 * Snapshot Helper Utilities
 *
 * Functions for detecting missing values and validating snapshots
 * against the current workflow structure.
 */

import type { Step } from '@shared/schema';

/**
 * Information about a missing or invalid snapshot value
 */
export interface MissingValue {
  stepId: string;
  alias: string | null;
  reason: 'not_in_snapshot' | 'step_deleted' | 'type_changed' | 'invalid_format';
}

/**
 * Result of snapshot validation
 */
export interface SnapshotValidation {
  isValid: boolean;
  missingValues: MissingValue[];
  outdatedHash: boolean;
  currentHash: string;
}

/**
 * Finds missing or invalid values when comparing a snapshot to current workflow
 *
 * @param snapshotValues - Values stored in the snapshot (alias -> value)
 * @param currentSteps - Current workflow steps
 * @returns Array of missing values with reasons
 */
export function findMissingValues(
  snapshotValues: Record<string, any>,
  currentSteps: Step[]
): MissingValue[] {
  const missingValues: MissingValue[] = [];

  // Build a map of current steps by alias and by ID
  const stepsByAlias = new Map<string, Step>();
  const stepsById = new Map<string, Step>();

  for (const step of currentSteps) {
    if (step.alias) {
      stepsByAlias.set(step.alias, step);
    }
    stepsById.set(step.id, step);
  }

  // Check each step in the workflow to see if it has a value in the snapshot
  for (const step of currentSteps) {
    // Skip virtual steps (computed values)
    if (step.isVirtual) {continue;}

    // Skip final_documents and other system blocks
    if (step.type === 'final_documents') {continue;}

    // Determine the key used in snapshot (prefer alias, fall back to ID)
    const key = step.alias || step.id;

    // Check if value exists in snapshot
    if (!(key in snapshotValues)) {
      missingValues.push({
        stepId: step.id,
        alias: step.alias,
        reason: 'not_in_snapshot',
      });
      continue;
    }

    // Value exists - validate format for complex types
    const value = snapshotValues[key];

    if (step.type === 'address' && typeof value !== 'object') {
      missingValues.push({
        stepId: step.id,
        alias: step.alias,
        reason: 'invalid_format',
      });
    } else if (step.type === 'multi_field' && typeof value !== 'object') {
      missingValues.push({
        stepId: step.id,
        alias: step.alias,
        reason: 'invalid_format',
      });
    } else if (step.type === 'multiple_choice' && !Array.isArray(value)) {
      missingValues.push({
        stepId: step.id,
        alias: step.alias,
        reason: 'invalid_format',
      });
    }
  }

  return missingValues;
}

/**
 * Finds the first visible step with a missing value
 *
 * Takes into account section order and step order.
 *
 * @param missingValues - Array of missing values
 * @param allSteps - All workflow steps (with sectionId and order)
 * @returns The first missing step, or null if none
 */
export function findFirstMissingStep(
  missingValues: MissingValue[],
  allSteps: Step[]
): Step | null {
  if (missingValues.length === 0) {return null;}

  // Get missing step IDs
  const missingStepIds = new Set(missingValues.map(mv => mv.stepId));

  // Filter to missing steps only
  const missingSteps = allSteps.filter(step => missingStepIds.has(step.id));

  if (missingSteps.length === 0) {return null;}

  // Sort by section order, then step order
  missingSteps.sort((a, b) => {
    // Note: We'd need section order here, but for now sort by step order
    // In practice, the caller will need to provide section context
    return a.order - b.order;
  });

  return missingSteps[0];
}

/**
 * Converts snapshot values from versioned format to simple key-value
 *
 * Legacy snapshots store: { alias: { value, stepId, stepUpdatedAt } }
 * New snapshots store: { alias: value }
 *
 * This helper normalizes both formats.
 *
 * @param snapshotValues - Raw snapshot values from DB
 * @returns Normalized key-value map
 */
export function normalizeSnapshotValues(snapshotValues: any): Record<string, any> {
  const normalized: Record<string, any> = {};

  for (const [key, val] of Object.entries(snapshotValues)) {
    // Check if it's versioned format
    if (val && typeof val === 'object' && 'value' in val) {
      normalized[key] = (val as any).value;
    } else {
      // Simple format
      normalized[key] = val;
    }
  }

  return normalized;
}

/**
 * Checks if a value is complete for a given step type
 *
 * @param stepType - The type of the step
 * @param value - The value to validate
 * @returns true if value is complete and valid
 */
export function isValueComplete(stepType: string, value: any): boolean {
  if (value === null || value === undefined || value === '') {
    return false;
  }

  switch (stepType) {
    case 'address':
      return (
        typeof value === 'object' &&
        value.street &&
        value.city &&
        value.state &&
        value.zip
      );

    case 'multi_field':
      return typeof value === 'object' && Object.keys(value).length > 0;

    case 'multiple_choice':
      return Array.isArray(value) && value.length > 0;

    default:
      return true;
  }
}

/**
 * Step Configuration Utilities
 *
 * Backend utilities for handling step configurations, including:
 * - Config validation
 * - Config normalization
 * - Value sanitization
 * - Type-specific helpers
 *
 * @version 2.0.0 - Block System Overhaul
 * @date December 2025
 */

import type {
  AddressValue,
  MultiFieldValue,
  ChoiceValue,
  StepConfig,
  ChoiceOption,
  ChoiceAdvancedConfig,
  MultiFieldConfig,
  AddressConfig,
  AddressAdvancedConfig,
  ScaleConfig,
  ScaleAdvancedConfig,
  BooleanAdvancedConfig,
  EmailConfig,
  EmailAdvancedConfig,
  PhoneConfig,
  PhoneAdvancedConfig,
  WebsiteConfig,
  WebsiteAdvancedConfig,
  NumberConfig,
  NumberAdvancedConfig,
  NumberValidation,
  CurrencyConfig,
  LegacyMultipleChoiceConfig,
  LegacyYesNoConfig,
  FileUploadConfig,
} from '@shared/types/stepConfigs';
import { validateStepConfig } from '@shared/validation/stepConfigSchemas';

