/**
 * Sanitize a step value based on its type and config
 *
 * @param stepType - The step type
 * @param value - Raw value from user input
 * @param config - Step configuration
 * @returns Sanitized value ready for storage
 */
export function sanitizeStepValue(
  stepType: string,
  value: unknown,
  config?: StepConfig
): unknown {
  if (value === null || value === undefined) {
    return value;
  }

  switch (stepType) {
    case 'email':
    case 'email_advanced':
      return sanitizeEmailValue(value, config);

    case 'phone':
    case 'phone_advanced':
      return sanitizePhoneValue(value, config);

    case 'website':
    case 'website_advanced':
      return sanitizeWebsiteValue(value, config);

    case 'number':
    case 'number_advanced':
    case 'currency':
      return sanitizeNumberValue(value, config);

    case 'address':
    case 'address_advanced':
      return sanitizeAddressValue(value, config);

    case 'multi_field':
      return sanitizeMultiFieldValue(value, config);

    case 'choice':
    case 'multiple_choice':
    case 'radio':
      return sanitizeChoiceValue(value, config);

    case 'date':
    case 'time':
    case 'datetime':
    case 'datetime_unified':
    case 'date_time':
      return sanitizeDateTimeValue(value, config);

    case 'scale':
    case 'scale_advanced':
      return sanitizeScaleValue(value, config);

    default:
      // For unknown types, return as-is
      return value;
  }
}

/**
 * Sanitize email value
 */
/**
 * Sanitize email value
 */
function sanitizeEmailValue(value: unknown, config?: StepConfig): string | string[] {
  const emailConfig = config as (EmailConfig | EmailAdvancedConfig) | undefined;
  if (typeof value === 'string') {
    const email = value.trim().toLowerCase();
    if (emailConfig?.allowMultiple && email.includes(',')) {
      return email.split(',').map(e => e.trim()).filter(Boolean);
    }
    return email;
  }
  if (Array.isArray(value)) {
    return value.map(e => String(e).trim().toLowerCase()).filter(Boolean);
  }
  return value as string | string[];
}

/**
 * Sanitize phone value
 */
function sanitizePhoneValue(value: unknown, _config?: StepConfig): string {
  if (typeof value !== 'string') {
    return String(value);
  }
  // Remove all non-digit characters except +
  return value.replace(/[^\d+]/g, '');
}

/**
 * Sanitize website value
 */
function sanitizeWebsiteValue(value: unknown, config?: StepConfig): string {
  const webConfig = config as (WebsiteConfig | WebsiteAdvancedConfig) | undefined;
  if (typeof value !== 'string') {
    return String(value);
  }

  let url = value.trim();

  // Add protocol if required and missing
  if (webConfig?.requireProtocol && !url.match(/^[a-z]+:\/\//i)) {
    url = `https://${url}`;
  }

  return url;
}

/**
 * Sanitize number value
 */
function sanitizeNumberValue(value: unknown, config?: StepConfig): number | null {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  const num = typeof value === 'number' ? value : parseFloat(String(value).replace(/[^0-9.-]/g, ''));

  if (isNaN(num)) {
    return null;
  }

  const numConfig = config as (NumberConfig | NumberAdvancedConfig | CurrencyConfig) | undefined;

  // Apply precision if specified
  const precision = (numConfig as NumberValidation)?.precision ?? (numConfig as NumberAdvancedConfig)?.validation?.precision;
  if (precision !== undefined) {
    return parseFloat(num.toFixed(precision));
  }

  // For currency modes with no decimal
  // Safe cast for checking mode/allowDecimal presence
  const currencyConfig = numConfig as CurrencyConfig & NumberAdvancedConfig & NumberConfig;
  if (currencyConfig?.mode === 'currency_whole' || (currencyConfig?.allowDecimal === false)) {
    return Math.round(num);
  }

  return num;
}

/**
 * Sanitize address value
 */
function sanitizeAddressValue(value: unknown, config?: StepConfig): AddressValue {
  if (!value || typeof value !== 'object') {
    return {};
  }

  const address: AddressValue = {};
  const addrConfig = config as (AddressConfig | AddressAdvancedConfig) | undefined;

  // Ensure all expected fields are present
  const fields = addrConfig?.fields || ['street', 'city', 'state', 'zip'];

  for (const field of fields) {
    const fieldKey = typeof field === 'string' ? field : field.key;
    const valObj = value as Record<string, unknown>;
    if (valObj[fieldKey]) {
      (address as Record<string, string>)[fieldKey] = String(valObj[fieldKey]).trim();
    }
  }

  return address;
}

/**
 * Sanitize multi-field value
 */
function sanitizeMultiFieldValue(value: unknown, config?: StepConfig): MultiFieldValue {
  if (!value || typeof value !== 'object') {
    return {};
  }

  const result: MultiFieldValue = {};
  const mfConfig = config as MultiFieldConfig | undefined;
  const fields = mfConfig?.fields ?? [];

  for (const field of fields) {
    const key = field.key;
    const valObj = value as Record<string, unknown>;
    if (valObj[key] !== undefined) {
      // Type-specific sanitization
      switch (field.type) {
        case 'email':
          result[key] = sanitizeEmailValue(valObj[key], {}); // Recursion safe
          break;
        case 'phone':
          result[key] = sanitizePhoneValue(valObj[key], {});
          break;
        case 'number':
          result[key] = sanitizeNumberValue(valObj[key], {});
          break;
        default:
          result[key] = valObj[key] as string | number | boolean | null | string[];
      }
    }
  }

  return result;
}

/**
 * Sanitize choice value
 */
/**
 * Sanitize choice value
 */
function sanitizeChoiceValue(value: unknown, config?: StepConfig): ChoiceValue {
  if (Array.isArray(value)) {
    return (value as unknown[]).filter(Boolean).map(String);
  }
  if (typeof value === 'string') {
    return value;
  }
  if (value === null || value === undefined) {
    const choiceConfig = config as (ChoiceAdvancedConfig | LegacyMultipleChoiceConfig) | undefined;
    return choiceConfig?.allowMultiple ? [] : '';
  }
  return String(value);
}

/**
 * Sanitize date/time value
 */
function sanitizeDateTimeValue(value: unknown, _config?: StepConfig): string | null {
  if (!value) {
    return null;
  }

  if (typeof value === 'string') {
    // Validate ISO format
    const date = new Date(value);
    if (isNaN(date.getTime())) {
      return null;
    }
    return value;
  }

  if (value instanceof Date) {
    return value.toISOString();
  }

  return null;
}

/**
 * Sanitize scale value
 */
function sanitizeScaleValue(value: unknown, config?: StepConfig): number | null {
  const num = sanitizeNumberValue(value, {});

  if (num === null) {
    return null;
  }

  const scaleConfig = config as (ScaleConfig | ScaleAdvancedConfig) | undefined;

  // Clamp to min/max
  if (scaleConfig?.min !== undefined && num < scaleConfig.min) {
    return scaleConfig.min;
  }
  if (scaleConfig?.max !== undefined && num > scaleConfig.max) {
    return scaleConfig.max;
  }

  // Round to nearest step
  if (scaleConfig?.step) {
    const steps = Math.round((num - (scaleConfig.min || 0)) / scaleConfig.step);
    return (scaleConfig.min || 0) + (steps * scaleConfig.step);
  }

  return num;
}

// ============================================================================
// VALUE VALIDATION
// ============================================================================

/**
 * Validate a step value against its type and config
 *
 * @param stepType - The step type
 * @param value - Value to validate
 * @param config - Step configuration
 * @param required - Whether the field is required
 * @returns Validation result
 */
export function validateStepValue(
  stepType: string,
  value: unknown,
  config?: StepConfig,
  required?: boolean
): {
  valid: boolean;
  errors: string[];
} {
  const errors: string[] = [];

  // Check required
  if (required && (value === null || value === undefined || value === '')) {
    errors.push('This field is required');
    return { valid: false, errors };
  }

  // Skip validation if empty and not required
  if (!required && (value === null || value === undefined || value === '')) {
    return { valid: true, errors: [] };
  }

  // Type-specific validation
  switch (stepType) {
    case 'email':
    case 'email_advanced':
      validateEmail(value, config as EmailConfig | EmailAdvancedConfig, errors);
      break;

    case 'phone':
    case 'phone_advanced':
      validatePhone(value, config as PhoneConfig | PhoneAdvancedConfig, errors);
      break;

    case 'website':
    case 'website_advanced':
      validateWebsite(value, config as WebsiteConfig | WebsiteAdvancedConfig, errors);
      break;

    case 'number':
    case 'number_advanced':
    case 'currency':
      validateNumber(value, config as NumberConfig | NumberAdvancedConfig | CurrencyConfig, errors);
      break;

    case 'scale':
    case 'scale_advanced':
      validateScale(value, config as ScaleConfig | ScaleAdvancedConfig, errors);
      break;

    case 'choice':
    case 'multiple_choice':
      validateChoice(value, config as ChoiceAdvancedConfig | LegacyMultipleChoiceConfig, errors);
      break;

    case 'address':
    case 'address_advanced':
      validateAddress(value, config as AddressConfig | AddressAdvancedConfig, errors);
      break;

    case 'multi_field':
      validateMultiField(value, config as MultiFieldConfig, errors);
      break;
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

function validateEmail(value: unknown, config: EmailConfig | EmailAdvancedConfig | undefined, errors: string[]): void {
  const emails = Array.isArray(value) ? value : [value];

  for (const email of emails) {
    if (typeof email !== 'string' || !email.match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/)) {
      errors.push(`Invalid email address: ${email}`);
    }

    if (!config) { continue; }

    // Type guard for advanced config
    if ('restrictDomains' in config && config.restrictDomains && config.restrictDomains.length > 0) {
      const domain = (email as string).split('@')[1];
      if (!config.restrictDomains.includes(domain)) {
        errors.push(`Email domain not allowed: ${domain}`);
      }
    }

    if ('blockDomains' in config && config.blockDomains && config.blockDomains.length > 0) {
      const domain = (email as string).split('@')[1];
      if (config.blockDomains.includes(domain)) {
        errors.push(`Email domain blocked: ${domain}`);
      }
    }
  }

  if (config && 'maxEmails' in config && config.maxEmails && emails.length > config.maxEmails) {
    errors.push(`Maximum ${config.maxEmails} emails allowed`);
  }
}

function validatePhone(value: unknown, _config: PhoneConfig | PhoneAdvancedConfig | undefined, errors: string[]): void {
  if (typeof value !== 'string') {
    errors.push('Phone number must be a string');
    return;
  }

  // Basic phone validation (10+ digits)
  const digits = value.replace(/\D/g, '');
  if (digits.length < 10) {
    errors.push('Phone number must be at least 10 digits');
  }
}

function validateWebsite(value: unknown, config: WebsiteConfig | WebsiteAdvancedConfig | undefined, errors: string[]): void {
  if (typeof value !== 'string') {
    errors.push('Website must be a string');
    return;
  }

  try {
    const url = new URL(value.startsWith('http') ? value : `https://${value}`);

    if (config?.requireProtocol && !value.match(/^[a-z]+:\/\//i)) {
      errors.push('URL must include protocol (http:// or https://)');
    }

    if (config && 'allowedProtocols' in config && config.allowedProtocols && config.allowedProtocols.length > 0) {
      // Cast protocol to satisfy literal type if needed, or check validity first
      const cleanProtocol = url.protocol.replace(':', '');
      if (!config.allowedProtocols.includes(cleanProtocol as any)) {
        errors.push(`Protocol not allowed: ${url.protocol}`);
      }
    }

    if (config && 'restrictDomains' in config && config.restrictDomains && config.restrictDomains.length > 0) {
      if (!config.restrictDomains.includes(url.hostname)) {
        errors.push(`Domain not allowed: ${url.hostname}`);
      }
    }

    if (config && 'blockDomains' in config && config.blockDomains && config.blockDomains.length > 0) {
      if (config.blockDomains.includes(url.hostname)) {
        errors.push(`Domain blocked: ${url.hostname}`);
      }
    }
  } catch (e) {
    errors.push('Invalid URL format');
  }
}

function validateNumber(value: unknown, config: NumberConfig | NumberAdvancedConfig | CurrencyConfig | NumberValidation | undefined, errors: string[]): void {
  const num = typeof value === 'number' ? value : parseFloat(String(value));

  if (isNaN(num)) {
    errors.push('Invalid number');
    return;
  }

  // Handle both StepConfig and NumberValidation shapes
  let validation: NumberValidation | undefined;
  if (config && 'validation' in config) {
    validation = (config).validation;
  } else {
    validation = config as NumberValidation | undefined;
  }

  if (validation?.min !== undefined && num < validation.min) {
    errors.push(`Value must be at least ${validation.min}`);
  }

  if (validation?.max !== undefined && num > validation.max) {
    errors.push(`Value must be at most ${validation.max}`);
  }
}

function validateScale(value: unknown, config: ScaleConfig | ScaleAdvancedConfig | undefined, errors: string[]): void {
  validateNumber(value, config, errors);
}

function validateChoice(value: unknown, config: ChoiceAdvancedConfig | LegacyMultipleChoiceConfig | undefined, errors: string[]): void {
  const values = Array.isArray(value) ? value : [value];

  // Safe extraction of options
  let options: ChoiceOption[] = [];
  if (config && 'options' in config) {
    if (Array.isArray(config.options)) {
      options = config.options;
    } else if (config.options && typeof config.options === 'object' && 'type' in config.options && (config.options as any).type === 'static') {
      // Handle DynamicOptionsConfig wrapper if present in schema but acting static
      options = ((config.options as any).options) as ChoiceOption[];
    }
  }

  const validOptions = options.map((opt) => opt.id || opt.alias);

  for (const val of values) {
    if (typeof val === 'string' && !validOptions.includes(val)) {
      errors.push(`Invalid option: ${val}`);
    }
  }

  // Safe checks for min/max
  const min = config && 'min' in config ? config.min : undefined;
  const max = config && 'max' in config ? config.max : undefined;

  if (min !== undefined && values.length < min) {
    errors.push(`Select at least ${min} option(s)`);
  }

  if (max !== undefined && values.length > max) {
    errors.push(`Select at most ${max} option(s)`);
  }
}

function validateAddress(value: unknown, config: AddressConfig | AddressAdvancedConfig | undefined, errors: string[]): void {
  if (!value || typeof value !== 'object') {
    errors.push('Address must be an object');
    return;
  }

  const valObj = value as Record<string, unknown>;

  // Check requireAll existence safely
  const requireAll = config && 'requireAll' in config ? config.requireAll : false;

  const requiredFields = requireAll
    ? (config?.fields || ['street', 'city', 'state', 'zip'])
    : [];

  for (const field of requiredFields) {
    const fieldKey = typeof field === 'string' ? field : field.key;
    if (!valObj[fieldKey] || String(valObj[fieldKey]).trim() === '') {
      const fieldLabel = typeof field === 'object' ? field.label : fieldKey;
      errors.push(`${fieldLabel} is required`);
    }
  }
}

function validateMultiField(value: unknown, config: StepConfig | undefined, errors: string[]): void {
  if (!value || typeof value !== 'object') {
    errors.push('Multi-field value must be an object');
    return;
  }

  const mfConfig = config as MultiFieldConfig | undefined;
  const valObj = value as Record<string, unknown>;

  for (const field of mfConfig?.fields ?? []) {
    if (field.required && (!valObj[field.key] || valObj[field.key] === '')) {
      errors.push(`${field.label} is required`);
    }

    // Type-specific validation for each field
    if (valObj[field.key]) {
      switch (field.type) {
        case 'email':
          validateEmail(valObj[field.key], undefined, errors);
          break;
        case 'phone':
          validatePhone(valObj[field.key], undefined, errors);
          break;
        case 'number':
          validateNumber(valObj[field.key], field.validation as NumberValidation, errors);
          break;
      }
    }
  }
}

// ============================================================================
// TYPE CHECKING HELPERS
// ============================================================================

/**
 * Check if a step type requires complex value storage
 */
export function isComplexValueType(stepType: string): boolean {
  return [
    'address',
    'address_advanced',
    'multi_field',
    'file_upload',
  ].includes(stepType);
}

/**
 * Check if a step type supports multiple values
 */
export function isMultiValueType(stepType: string): boolean {
  return [
    'multiple_choice',
    'choice', // when allowMultiple=true
    'file_upload', // when maxFiles>1
  ].includes(stepType);
}

/**
 * Get the default value for a step type
 */
export function getDefaultValue(stepType: string, config?: StepConfig): unknown {
  switch (stepType) {
    case 'choice':
    case 'multiple_choice': {
      const choiceConfig = config as (ChoiceAdvancedConfig | LegacyMultipleChoiceConfig) | undefined;
      return choiceConfig?.allowMultiple || (choiceConfig && 'minSelections' in choiceConfig) ? [] : '';
    }

    case 'boolean':
    case 'yes_no':
    case 'true_false': {
      const boolConfig = config as (BooleanAdvancedConfig | LegacyYesNoConfig) | undefined;
      return boolConfig?.defaultValue ?? false;
    }

    case 'number':
    case 'number_advanced':
    case 'currency':
    case 'scale':
    case 'scale_advanced': {
      const numOrScale = config as (NumberConfig | ScaleConfig) | undefined;
      const advNum = config as NumberAdvancedConfig | undefined;
      return numOrScale?.min ?? advNum?.validation?.min ?? 0;
    }

    case 'address':
    case 'address_advanced':
      return {};

    case 'multi_field':
      return {};

    case 'file_upload': {
      const fileConfig = config as FileUploadConfig | undefined;
      return (fileConfig?.maxFiles ?? 1) > 1 ? [] : null;
    }

    default:
      return '';
  }
}

/**
 * Validation Utilities
 * Reusable Zod schemas for common validation patterns
 */

import { z } from 'zod';

import { DATAVAULT_CONFIG } from '@shared/config';

/**
 * SECURITY FIX: Pagination validation schema
 * Prevents NaN and invalid values from parseInt
 */
export const paginationSchema = z.object({
  limit: z.coerce
    .number()
    .int()
    .min(1, 'Limit must be at least 1')
    .max(DATAVAULT_CONFIG.MAX_PAGE_SIZE, `Limit cannot exceed ${DATAVAULT_CONFIG.MAX_PAGE_SIZE}`)
    .default(DATAVAULT_CONFIG.DEFAULT_PAGE_SIZE),
  offset: z.coerce
    .number()
    .int()
    .min(0, 'Offset must be non-negative')
    .max(DATAVAULT_CONFIG.MAX_OFFSET, `Offset cannot exceed ${DATAVAULT_CONFIG.MAX_OFFSET}`)
    .default(0),
});

/**
 * ID parameter validation (ensures valid UUID or string ID)
 */
export const idParamSchema = z.string().min(1, 'ID is required');

/**
 * Page number validation (for page-based pagination)
 */
export const pageNumberSchema = z.coerce
  .number()
  .int()
  .min(1, 'Page number must be at least 1')
  .default(1);

/**
 * Numeric query parameter validation
 */
export const numericParamSchema = (min?: number, max?: number) => {
  let schema = z.coerce.number().int();

  if (min !== undefined) {
    schema = schema.min(min, `Value must be at least ${min}`);
  }

  if (max !== undefined) {
    schema = schema.max(max, `Value cannot exceed ${max}`);
  }

  return schema;
};

/**
 * Helper to safely parse query parameters with Zod
 * Returns parsed values or throws a validation error
 */
export function parseQueryParams<T>(
  schema: z.ZodSchema<T>,
  params: Record<string, any>
): T {
  try {
    return schema.parse(params);
  } catch (error) {
    if (error instanceof z.ZodError) {
      const message = error.errors.map(e => `${e.path.join('.')}: ${e.message}`).join(', ');
      throw new Error(`Invalid query parameters: ${message}`);
    }
    throw error;
  }
}

/**
 * Condition Adapter
 *
 * Adapts between the new UI-friendly condition format (used by LogicBuilder)
 * and the existing backend condition format (used by IntakeNavigationService).
 *
 * New Format (UI):
 * {
 *   type: "group",
 *   operator: "AND",
 *   conditions: [
 *     { type: "condition", variable: "age", operator: "greater_than", value: 18, valueType: "constant" }
 *   ]
 * }
 *
 * Existing Format (Backend):
 * {
 *   and: [
 *     { op: "gt", left: { type: "variable", path: "age" }, right: { type: "value", value: 18 } }
 *   ]
 * }
 */


import {
  evaluateConditionExpression as evaluateNewCondition,
  type DataMap,
} from "@shared/conditionEvaluator";
import type {
  ConditionExpression as NewConditionExpression,
  Condition as NewCondition,
  ConditionGroup as NewConditionGroup,
  ComparisonOperator as NewOperator,
  ScriptCondition,
} from "@shared/types/conditions";

import { logger } from "../logger";

import {
  evaluateCondition as evaluateExistingCondition,
  type ConditionExpression as ExistingConditionExpression,
  type EvaluationContext,
} from "./conditions";

// ========================================================================
// FORMAT DETECTION
// ========================================================================

/**
 * Detects whether a condition expression uses the new UI format or the existing backend format
 */
export function isNewFormat(expression: any): expression is NewConditionGroup {
  if (!expression || typeof expression !== "object") { return false; }
  return expression.type === "group" || expression.type === "condition" || expression.type === "script";
}

export function isExistingFormat(expression: any): expression is ExistingConditionExpression {
  if (!expression || typeof expression !== "object") { return false; }
  return "and" in expression || "or" in expression || "not" in expression || "op" in expression;
}

// ========================================================================
// OPERATOR MAPPING
// ========================================================================

/**
 * Maps new UI operators to existing backend operators
 */
const operatorMap: Record<NewOperator, string | null> = {
  // Equality
  equals: "equals",
  not_equals: "notEquals",

  // Text
  contains: "contains",
  not_contains: "notContains",
  starts_with: "startsWith",
  ends_with: "endsWith",

  // Numeric
  greater_than: "gt",
  less_than: "lt",
  greater_or_equal: "gte",
  less_or_equal: "lte",
  between: null, // Handle specially

  // Boolean shortcuts
  is_true: "equals", // Converts to equals + value: true
  is_false: "equals", // Converts to equals + value: false

  // Empty checks
  is_empty: "isEmpty",
  is_not_empty: "notEmpty",

  // Array
  includes: "contains",
  not_includes: "notContains",
  includes_all: null, // Handle specially
  includes_any: null, // Handle specially

  // Date Difference
  diff_days: null,
  diff_weeks: null,
  diff_months: null,
  diff_years: null,

  // Date Helpers
  before: null,
  after: null,
  on_or_before: null,
  on_or_after: null,
};

// ========================================================================
// CONVERSION FUNCTIONS
// ========================================================================

/**
 * Converts new format condition to existing format
 */
export function convertNewToExisting(
  expression: NewConditionGroup | NewCondition | { type: "script" }
): ExistingConditionExpression | null {
  if (expression.type === "group") {
    return convertGroup(expression);
  } else if (expression.type === "condition") {
    return convertCondition(expression);
  } else {
    // Script conditions not supported in existing backend format
    return null;
  }
}

function convertGroup(group: NewConditionGroup): ExistingConditionExpression | null {
  const convertedConditions = group.conditions
    .map((item) => convertNewToExisting(item))
    .filter((c): c is ExistingConditionExpression => c !== null);

  if (convertedConditions.length === 0) {
    return null;
  }

  if (convertedConditions.length === 1) {
    return convertedConditions[0];
  }

  if (group.operator === "AND") {
    return { and: convertedConditions };
  } else {
    return { or: convertedConditions };
  }
}

function convertCondition(condition: NewCondition): ExistingConditionExpression | null {
  if (!condition.variable) {
    return null;
  }

  const operator = condition.operator;
  const backendOp = operatorMap[operator];

  // Handle special operators
  if (operator === "is_true") {
    return {
      op: "equals",
      left: { type: "variable", path: condition.variable },
      right: { type: "value", value: true },
    };
  }

  if (operator === "is_false") {
    return {
      op: "equals",
      left: { type: "variable", path: condition.variable },
      right: { type: "value", value: false },
    };
  }

  if (operator === "between" && condition.value !== undefined && condition.value2 !== undefined) {
    // Convert to: (value >= min) AND (value <= max)
    return {
      and: [
        {
          op: "gte",
          left: { type: "variable", path: condition.variable },
          right: { type: "value", value: condition.value as any },
        },
        {
          op: "lte",
          left: { type: "variable", path: condition.variable },
          right: { type: "value", value: condition.value2 as any },
        },
      ],
    };
  }

  if (operator === "includes_all" && Array.isArray(condition.value)) {
    // Convert to: AND of contains for each value
    const checks = condition.value.map((val: any) => ({
      op: "contains",
      left: { type: "variable", path: condition.variable },
      right: { type: "value", value: val },
    })) as ExistingConditionExpression[];
    return { and: checks };
  }

  if (operator === "includes_any" && Array.isArray(condition.value)) {
    // Convert to: OR of contains for each value
    const checks = condition.value.map((val: any) => ({
      op: "contains",
      left: { type: "variable", path: condition.variable },
      right: { type: "value", value: val },
    })) as ExistingConditionExpression[];
    return { or: checks };
  }

  if (!backendOp) {
    logger.warn(`Unknown operator: ${operator}`);
    return null;
  }

  // Create left operand (always the variable)
  const left: any = { type: "variable", path: condition.variable };

  // Create right operand
  let right: any;
  if (operator === "is_empty" || operator === "is_not_empty") {
    // These don't need a right operand, but the existing format requires one
    right = { type: "value", value: null };
  } else if (condition.valueType === "variable" && typeof condition.value === "string") {
    right = { type: "variable", path: condition.value };
  } else {
    right = { type: "value", value: condition.value };
  }

  return { op: backendOp as any, left, right };
}

// ========================================================================
// UNIFIED EVALUATION FUNCTION
// ========================================================================

/**
 * Evaluates a condition expression (either format) against the given context
 *
 * @param expression - The condition expression (new or existing format)
 * @param variables - The variable values (step values by alias or ID)
 * @returns boolean result of the condition evaluation
 */
export function evaluateVisibility(
  expression: any,
  variables: Record<string, any>
): boolean {
  // Null/undefined means always visible
  if (!expression) {
    return true;
  }

  // Handle legacy string format
  if (typeof expression === 'string') {
    const converted = parseLegacyStringCondition(expression);
    if (converted) {
      const context: EvaluationContext = { variables };
      return evaluateExistingCondition(converted, context);
    }
    // If parsing failed but it was a string, warn and default to visible (or false?)
    // The test `handle malformed visibility expression gracefully` expects it NOT to throw.
    // If bad expr, default to true (visible) is safer for user content.
    logger.warn(`Failed to parse legacy string condition: "${expression}", defaulting to visible`);
    return true;
  }

  // Detect format and evaluate
  if (isNewFormat(expression)) {
    // Use the new shared evaluator
    return evaluateNewCondition(expression, variables);
  } else if (isExistingFormat(expression)) {
    // Use the existing backend evaluator
    const context: EvaluationContext = { variables };
    return evaluateExistingCondition(expression, context);
  } else {
    // Unknown format - default to visible
    logger.warn("Unknown condition expression format, defaulting to visible");
    return true;
  }
}

/**
 * Parses a legacy string condition into the existing backend format
 * Supports basic comparisons: var == val, var > val, etc.
 */
function parseLegacyStringCondition(expr: string): ExistingConditionExpression | null {
  expr = expr.trim();
  if (!expr) { return null; }

  // Handle AND logic
  if (expr.includes('&&')) {
    const parts = expr.split('&&');
    const conditions = parts.map(p => parseLegacyStringCondition(p)).filter(c => c !== null);
    if (conditions.length > 0) {
      // Cast to any because ExistingConditionExpression recursive type might be strict
      return { and: conditions } as any;
    }
    return null;
  }


  // Simple boolean variable check: "myVar" -> myVar == true
  if (/^[a-zA-Z0-9_.]+$/.test(expr)) {
    return {
      op: "equals",
      left: { type: "variable", path: expr },
      right: { type: "value", value: true }
    };
  }

  // Check for operators
  const ops = [
    { token: "==", op: "equals" },
    { token: "!=", op: "notEquals" },
    { token: ">=", op: "gte" },
    { token: "<=", op: "lte" },
    { token: ">", op: "gt" },
    { token: "<", op: "lt" }
  ];

  for (const { token, op } of ops) {
    if (expr.includes(token)) {
      const parts = expr.split(token);
      if (parts.length !== 2) { continue; } // Only handle binary ops

      const leftPath = parts[0].trim();
      const rightValStr = parts[1].trim();

      // Ensure both sides have content
      if (!leftPath || (!rightValStr && rightValStr !== '0' && rightValStr !== "''" && rightValStr !== '""')) {
        // Allow empty string literals or 0, but reject truly empty expression parts
        // If rightValStr is empty string "" (result of trim on " "), reject it if it's not a quoted empty string.
        // Wait, if input was `var == ""`, split gives `""`.
        // If input was `var == `, split gives empty string.
        // We should allow quoted empty strings, but reject missing values.
        // If original was `""`, then it's a value.
        // But here `rightValStr` is the raw text.
        // If it's empty, and not quoted, it's missing.
        if (rightValStr === "") { return null; }
      }

      let rightVal: any = rightValStr;

      // Parse value
      if (rightValStr === "true") { rightVal = true; }
      else if (rightValStr === "false") { rightVal = false; }
      else if (rightValStr === "null") { rightVal = null; }
      else if (!isNaN(Number(rightValStr))) { rightVal = Number(rightValStr); }
      else if ((rightValStr.startsWith('"') && rightValStr.endsWith('"')) || (rightValStr.startsWith("'") && rightValStr.endsWith("'"))) {
        rightVal = rightValStr.slice(1, -1);
      }

      return {
        op: op as any,
        left: { type: "variable", path: leftPath },
        right: { type: "value", value: rightVal }
      };
    }
  }

  return null;
}

/**
 * Batch evaluate visibility for multiple items
 */
export function evaluateVisibilityBatch<T extends { id: string; visibleIf?: any }>(
  items: T[],
  variables: Record<string, any>
): Map<string, boolean> {
  const results = new Map<string, boolean>();

  for (const item of items) {
    results.set(item.id, evaluateVisibility(item.visibleIf, variables));
  }

  return results;
}

/**
 * Condition System for Intake Runner 2.0
 *
 * This module provides a flexible, expression-based condition evaluation engine
 * that supports composite conditions (AND/OR/NOT), variable references, and
 * multiple data types.
 *
 * Key features:
 * - Composite conditions (and, or, not)
 * - Variable references with dot notation support
 * - Multiple value types (string, number, boolean, array, date)
 * - Rich operator set
 * - Type-safe evaluation
 * - Integration with workflow data and collection records
 */

import { logger } from '../logger';

// ========================================================================
// TYPE DEFINITIONS
// ========================================================================

/**
 * Supported operators for conditions
 */
export type ConditionOperator =
  | 'equals'
  | 'notEquals'
  | 'gt'           // greater than
  | 'gte'          // greater than or equal
  | 'lt'           // less than
  | 'lte'          // less than or equal
  | 'in'           // value in array
  | 'notIn'        // value not in array
  | 'contains'     // array/string contains value
  | 'notContains'  // array/string doesn't contain value
  | 'isEmpty'      // value is null/undefined/empty string/empty array
  | 'notEmpty'     // value is not empty
  | 'startsWith'   // string starts with
  | 'endsWith'     // string ends with
  | 'matches';     // regex match

/**
 * Value types supported in conditions
 */
export type ConditionValue = string | number | boolean | null | string[] | number[];

/**
 * Variable reference (e.g., "firstName", "address.city", "items[0].name")
 */
export interface VariableReference {
  type: 'variable';
  path: string;
}

/**
 * Literal value
 */
export interface ValueLiteral {
  type: 'value';
  value: ConditionValue;
}

/**
 * Operand can be either a variable reference or a literal value
 */
export type ConditionOperand = VariableReference | ValueLiteral;

/**
 * Basic comparison condition
 */
export interface ComparisonCondition {
  op: ConditionOperator;
  left: ConditionOperand;
  right: ConditionOperand;
}

/**
 * Composite AND condition
 */
export interface AndCondition {
  and: ConditionExpression[];
}

/**
 * Composite OR condition
 */
export interface OrCondition {
  or: ConditionExpression[];
}

/**
 * Negation condition
 */
export interface NotCondition {
  not: ConditionExpression;
}

/**
 * Top-level condition expression type
 */
export type ConditionExpression =
  | ComparisonCondition
  | AndCondition
  | OrCondition
  | NotCondition;

/**
 * Context for condition evaluation
 */
export interface EvaluationContext {
  /** Workflow variables (step values by alias or ID) */
  variables: Record<string, any>;
  /** Collection record data (if prefilled from a collection) */
  record?: Record<string, any>;
}

// ========================================================================
// HELPER FUNCTIONS
// ========================================================================

/**
 * Resolves a variable path to its value in the context
 * Supports dot notation: "address.city", "items[0].name"
 */
function resolveVariable(path: string, context: EvaluationContext): any {
  // First try to resolve from variables
  const parts = path.split('.');
  let current: any = context.variables;

  for (const part of parts) {
    // Handle array indexing: items[0]
    const arrayMatch = part.match(/^(\w+)\[(\d+)\]$/);
    if (arrayMatch) {
      const [, name, index] = arrayMatch;
      current = current?.[name]?.[parseInt(index, 10)];
    } else {
      current = current?.[part];
    }

    if (current === undefined) {
      break;
    }
  }

  // If found in variables, return it
  if (current !== undefined) {
    return current;
  }

  // Otherwise try record data
  if (context.record) {
    current = context.record;
    for (const part of parts) {
      const arrayMatch = part.match(/^(\w+)\[(\d+)\]$/);
      if (arrayMatch) {
        const [, name, index] = arrayMatch;
        current = current?.[name]?.[parseInt(index, 10)];
      } else {
        current = current?.[part];
      }

      if (current === undefined) {
        break;
      }
    }
  }

  return current;
}

/**
 * Resolves an operand to its actual value
 */
function resolveOperand(operand: ConditionOperand, context: EvaluationContext): any {
  if (operand.type === 'value') {
    return operand.value;
  } else {
    return resolveVariable(operand.path, context);
  }
}

/**
 * Checks if a value is empty
 */
function isEmpty(value: any): boolean {
  if (value === null || value === undefined) {
    return true;
  }

  if (typeof value === 'string') {
    return value.trim() === '';
  }

  if (Array.isArray(value)) {
    return value.length === 0;
  }

  if (typeof value === 'object') {
    return Object.keys(value).length === 0;
  }

  return false;
}

/**
 * Coerces values to comparable types
 */
function coerceToComparable(value: any): string | number | boolean | null {
  if (value === null || value === undefined) {
    return null;
  }

  if (typeof value === 'boolean') {
    return value;
  }

  if (typeof value === 'number') {
    return value;
  }

  if (typeof value === 'string') {
    return value;
  }

  // Convert other types to string for comparison
  return String(value);
}

/**
 * Normalizes a value for case-insensitive comparison
 */
function normalize(value: any): any {
  if (typeof value === 'string') {
    return value.toLowerCase().trim();
  }
  return value;
}

// ========================================================================
// OPERATOR EVALUATION FUNCTIONS
// ========================================================================

/**
 * Evaluates a comparison condition
 */
function evaluateComparison(
  operator: ConditionOperator,
  left: any,
  right: any
): boolean {
  switch (operator) {
    case 'equals':
      return normalize(left) === normalize(right);

    case 'notEquals':
      return normalize(left) !== normalize(right);

    case 'gt':
      return Number(left) > Number(right);

    case 'gte':
      return Number(left) >= Number(right);

    case 'lt':
      return Number(left) < Number(right);

    case 'lte':
      return Number(left) <= Number(right);

    case 'in':
      if (!Array.isArray(right)) {
        return false;
      }
      return right.some(item => normalize(item) === normalize(left));

    case 'notIn':
      if (!Array.isArray(right)) {
        return true;
      }
      return !right.some(item => normalize(item) === normalize(left));

    case 'contains':
      if (Array.isArray(left)) {
        return left.some(item => normalize(item) === normalize(right));
      }
      if (typeof left === 'string' && typeof right === 'string') {
        return normalize(left).includes(normalize(right));
      }
      return false;

    case 'notContains':
      if (Array.isArray(left)) {
        return !left.some(item => normalize(item) === normalize(right));
      }
      if (typeof left === 'string' && typeof right === 'string') {
        return !normalize(left).includes(normalize(right));
      }
      return true;

    case 'isEmpty':
      return isEmpty(left);

    case 'notEmpty':
      return !isEmpty(left);

    case 'startsWith':
      if (typeof left === 'string' && typeof right === 'string') {
        return normalize(left).startsWith(normalize(right));
      }
      return false;

    case 'endsWith':
      if (typeof left === 'string' && typeof right === 'string') {
        return normalize(left).endsWith(normalize(right));
      }
      return false;

    case 'matches':
      if (typeof left === 'string' && typeof right === 'string') {
        try {
          const regex = new RegExp(right);
          return regex.test(left);
        } catch {
          return false;
        }
      }
      return false;

    default:
      logger.warn(`Unknown operator: ${operator}`);
      return false;
  }
}

// ========================================================================
// MAIN EVALUATION FUNCTION
// ========================================================================

/**
 * Evaluates a condition expression against the given context
 *
 * @param expression - The condition expression to evaluate
 * @param context - The evaluation context (variables, record data)
 * @returns boolean result of the condition evaluation
 */
export function evaluateCondition(
  expression: ConditionExpression,
  context: EvaluationContext
): boolean {
  // Handle composite AND condition
  if ('and' in expression) {
    return expression.and.every(subExpr => evaluateCondition(subExpr, context));
  }

  // Handle composite OR condition
  if ('or' in expression) {
    return expression.or.some(subExpr => evaluateCondition(subExpr, context));
  }

  // Handle NOT condition
  if ('not' in expression) {
    return !evaluateCondition(expression.not, context);
  }

  // Handle basic comparison condition
  if ('op' in expression) {
    const left = resolveOperand(expression.left, context);
    const right = resolveOperand(expression.right, context);
    return evaluateComparison(expression.op, left, right);
  }

  // Unknown expression type
  logger.warn('Unknown condition expression type');
  return false;
}

// ========================================================================
// UTILITY FUNCTIONS
// ========================================================================

/**
 * Creates a variable reference operand
 */
export function varRef(path: string): VariableReference {
  return { type: 'variable', path };
}

/**
 * Creates a value literal operand
 */
export function value(val: ConditionValue): ValueLiteral {
  return { type: 'value', value: val };
}

/**
 * Validates a condition expression structure
 * Returns an array of error messages (empty if valid)
 */
export function validateConditionExpression(expression: any): string[] {
  const errors: string[] = [];

  if (!expression || typeof expression !== 'object') {
    errors.push('Condition expression must be an object');
    return errors;
  }

  // Check if it's a composite condition
  if ('and' in expression) {
    if (!Array.isArray(expression.and)) {
      errors.push('AND condition must have an array of sub-expressions');
    } else {
      expression.and.forEach((subExpr: any, i: number) => {
        const subErrors = validateConditionExpression(subExpr);
        errors.push(...subErrors.map(err => `AND[${i}]: ${err}`));
      });
    }
    return errors;
  }

  if ('or' in expression) {
    if (!Array.isArray(expression.or)) {
      errors.push('OR condition must have an array of sub-expressions');
    } else {
      expression.or.forEach((subExpr: any, i: number) => {
        const subErrors = validateConditionExpression(subExpr);
        errors.push(...subErrors.map(err => `OR[${i}]: ${err}`));
      });
    }
    return errors;
  }

  if ('not' in expression) {
    if (!expression.not || typeof expression.not !== 'object') {
      errors.push('NOT condition must have a sub-expression');
    } else {
      const subErrors = validateConditionExpression(expression.not);
      errors.push(...subErrors.map(err => `NOT: ${err}`));
    }
    return errors;
  }

  // Check if it looks like a comparison condition (has left/right but maybe missing op)
  if ('left' in expression || 'right' in expression || 'op' in expression) {
    if (!expression.op || typeof expression.op !== 'string') {
      errors.push('Comparison condition must have an operator');
    }

    if (!expression.left || typeof expression.left !== 'object') {
      errors.push('Comparison condition must have a left operand');
    } else {
      if (!expression.left.type || !['variable', 'value'].includes(expression.left.type)) {
        errors.push('Left operand must have type "variable" or "value"');
      }
    }

    if (!expression.right || typeof expression.right !== 'object') {
      errors.push('Comparison condition must have a right operand');
    } else {
      if (!expression.right.type || !['variable', 'value'].includes(expression.right.type)) {
        errors.push('Right operand must have type "variable" or "value"');
      }
    }

    return errors;
  }

  errors.push('Condition expression must have one of: and, or, not, or op');
  return errors;
}

