  const condition: ConditionExpression = {
    op: 'equals',
    left: varRef('employmentStatus'),
    right: value('employed'),
  };

  const context: EvaluationContext = {
    variables: {
      employmentStatus: 'employed',
    },
  };

  return evaluateCondition(condition, context); // true
};

