  const condition: ConditionExpression = {
    and: [
      { op: 'gte', left: varRef('age'), right: value(18) },
      { op: 'gt', left: varRef('annualIncome'), right: value(50000) },
      { op: 'equals', left: varRef('citizenship'), right: value('US') },
    ],
  };

  const context: EvaluationContext = {
    variables: {
