/**
 * Intake Runner State Machine (Stage 20 PR 7)
 *
 * Pure state machine for intake workflow navigation and validation.
 * Integrates page conditions, question visibility, and validation.
 */
import type { Step } from "@shared/schema";

import { validatePage } from "./validation";

import type { IntakeNavigationService } from "../services/IntakeNavigationService";
import type { IntakeQuestionVisibilityService } from "../services/IntakeQuestionVisibilityService";
export interface IntakeRunnerState {
  /** Current page index (0-based) */
  currentPageIndex: number;
  /** Current page ID */
  currentPageId: string | null;
  /** All answers collected so far */
  answers: Record<string, any>;
  /** Pages that have been visited */
  visitedPages: Set<string>;
  /** Validation errors for current page */
  errors: Map<string, string[]>;
  /** Can navigate to next page */
  canGoNext: boolean;
  /** Can navigate to previous page */
  canGoBack: boolean;
  /** Progress percentage (0-100) */
  progress: number;
  /** Is workflow complete */
  isComplete: boolean;
}
export interface StateTransition {
  type: 'NEXT' | 'BACK' | 'GOTO' | 'UPDATE_ANSWER' | 'SUBMIT';
  pageId?: string;
  answersaround?: Record<string, any>;
}
export class IntakeStateMachine {
  constructor(
    private navigationService: IntakeNavigationService,
    private visibilityService: IntakeQuestionVisibilityService
  ) { }
  /**
   * Initialize state for a new workflow run
   */
  async initializeState(
    workflowId: string,
    runId: string,
    recordData?: Record<string, any>
  ): Promise<IntakeRunnerState> {
    const nav = await this.navigationService.evaluateNavigation(
      workflowId,
      runId,
      null,
      recordData
    );
    const firstPageId = nav.visiblePages.length > 0 ? nav.visiblePages[0] : null;
    return {
      currentPageIndex: 0,
      currentPageId: firstPageId,
      answers: {},
      visitedPages: new Set(firstPageId ? [firstPageId] : []),
      errors: new Map(),
      canGoNext: false, // Determined after validation
      canGoBack: false,
      progress: nav.progress,
      isComplete: false,
    };
  }
  /**
   * Navigate to next page
   */
  async goNext(
    state: IntakeRunnerState,
    workflowId: string,
    runId: string,
    recordData?: Record<string, any>
  ): Promise<IntakeRunnerState> {
    if (!state.canGoNext) {
      return state; // Can't advance if validation failed
    }
    const nav = await this.navigationService.evaluateNavigation(
      workflowId,
      runId,
      state.currentPageId,
      recordData
    );
    if (!nav.nextPageId) {
      // Reached end
      return {
        ...state,
        isComplete: true,
        canGoNext: false,
      };
    }
    const nextPageIndex = state.currentPageIndex + 1;
    const visitedPages = new Set(state.visitedPages);
    visitedPages.add(nav.nextPageId);
    return {
      ...state,
      currentPageIndex: nextPageIndex,
      currentPageId: nav.nextPageId,
      visitedPages,
      errors: new Map(), // Clear errors for new page
      canGoNext: false, // Will be determined after validation
      canGoBack: nav.previousPageId !== null,
      progress: nav.progress,
    };
  }
  /**
   * Navigate to previous page
   */
  async goBack(
    state: IntakeRunnerState,
    workflowId: string,
    runId: string,
    recordData?: Record<string, any>
  ): Promise<IntakeRunnerState> {
    if (!state.canGoBack) {
      return state;
    }
    const nav = await this.navigationService.evaluateNavigation(
      workflowId,
      runId,
      state.currentPageId,
      recordData
    );
    if (!nav.previousPageId) {
      return state; // No previous page
    }
    const prevPageIndex = state.currentPageIndex - 1;
    return {
      ...state,
      currentPageIndex: prevPageIndex,
      currentPageId: nav.previousPageId,
      errors: new Map(), // Clear errors
      canGoNext: true, // Allow going forward (page already visited)
      canGoBack: prevPageIndex > 0,
      progress: nav.progress,
    };
  }
  /**
   * Update answers and revalidate
   */
  async updateAnswers(
    state: IntakeRunnerState,
    updates: Record<string, any>,
    steps: Step[],
    sectionId: string,
    runId: string,
    recordData?: Record<string, any>
  ): Promise<IntakeRunnerState> {
    const newAnswers = {
      ...state.answers,
      ...updates,
    };
    // Get visible steps for current page
    const visibility = await this.visibilityService.evaluatePageQuestions(
      sectionId,
      runId,
      recordData
    );
    // Validate page
    const validationResult = validatePage(steps, newAnswers, visibility.visibleQuestions);
    const errors = new Map<string, string[]>();
    for (const error of validationResult.errors) {
      errors.set(error.fieldId, error.errors);
    }
    return {
      ...state,
      answers: newAnswers,
      errors,
      canGoNext: validationResult.valid,
    };
  }
  /**
   * Submit workflow (complete)
   */
  async submit(
    state: IntakeRunnerState
  ): Promise<IntakeRunnerState> {
    return {
      ...state,
      isComplete: true,
      canGoNext: false,
      canGoBack: false,
    };
  }
}

/**
 * Validation Engine for Intake Runner 2.0 (Stage 20 PR 6)
 *
 * Centralized validation with field-level validators, page aggregation,
 * and integration with conditional visibility.
 */

import type { Step, Section } from "@shared/schema";
import type { RepeaterConfig, RepeaterValue } from "@shared/types/repeater";

import { repeaterService } from "../services/RepeaterService";

export interface ValidationRule {
  type: 'required' | 'minLength' | 'maxLength' | 'min' | 'max' | 'email' | 'regex' | 'date';
  value?: any;
  message?: string;
}

export interface FieldValidationConfig {
  required?: boolean;
  minLength?: number;
  maxLength?: number;
  min?: number;
  max?: number;
  pattern?: string; // Regex pattern
  email?: boolean;
  custom?: (value: any) => string | null; // Custom validator
}

export interface ValidationError {
  fieldId: string;
  fieldTitle: string;
  errors: string[];
}

export interface PageValidationResult {
  valid: boolean;
  errors: ValidationError[];
  errorCount: number;
}

/**
 * Validates a single field value
 */
export function validateField(
  value: any,
  config: FieldValidationConfig,
  fieldTitle: string
): string[] {
  const errors: string[] = [];

  // Required validation
  if (config.required && isEmpty(value)) {
    errors.push(`${fieldTitle} is required`);
    return errors; // Stop if required and empty
  }

  // Skip other validations if empty and not required
  if (isEmpty(value)) {
    return errors;
  }

  // String length validations
  if (typeof value === 'string') {
    if (config.minLength !== undefined && value.length < config.minLength) {
      errors.push(`${fieldTitle} must be at least ${config.minLength} characters`);
    }
    if (config.maxLength !== undefined && value.length > config.maxLength) {
      errors.push(`${fieldTitle} must be at most ${config.maxLength} characters`);
    }
  }

  // Numeric range validations
  if (typeof value === 'number' || !isNaN(Number(value))) {
    const numValue = typeof value === 'number' ? value : Number(value);
    if (config.min !== undefined && numValue < config.min) {
      errors.push(`${fieldTitle} must be at least ${config.min}`);
    }
    if (config.max !== undefined && numValue > config.max) {
      errors.push(`${fieldTitle} must be at most ${config.max}`);
    }
  }

  // Email validation
  if (config.email && typeof value === 'string') {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(value)) {
      errors.push(`${fieldTitle} must be a valid email address`);
    }
  }

  // Pattern validation
  if (config.pattern && typeof value === 'string') {
    try {
      const regex = new RegExp(config.pattern);
      if (!regex.test(value)) {
        errors.push(`${fieldTitle} format is invalid`);
      }
    } catch (e) {
      // Invalid regex pattern - skip validation
    }
  }

  // Custom validation
  if (config.custom) {
    const customError = config.custom(value);
    if (customError) {
      errors.push(customError);
    }
  }

  return errors;
}

/**
 * Validates all fields on a page
 */
export function validatePage(
  steps: Step[],
  values: Record<string, any>,
  visibleStepIds: string[] // From IntakeQuestionVisibilityService
): PageValidationResult {
  const errors: ValidationError[] = [];

  for (const step of steps) {
    // Skip hidden steps
    if (!visibleStepIds.includes(step.id)) {
      continue;
    }

    // Skip virtual steps
    if (step.isVirtual) {
      continue;
    }

    const value = values[step.id];
    const fieldErrors: string[] = [];

    // Handle repeater fields specially
    if (step.type === 'repeater' && step.repeaterConfig) {
      const repeaterConfig = step.repeaterConfig as unknown as RepeaterConfig;
      const repeaterValue = value as RepeaterValue | null;
      const validationResult = repeaterService.validateRepeater(repeaterValue, repeaterConfig);

      if (!validationResult.valid) {
        // Add global errors
        fieldErrors.push(...validationResult.globalErrors);

        // Add instance errors
        validationResult.instanceErrors.forEach((instanceErrors, instanceId) => {
          fieldErrors.push(...instanceErrors.map(e => `Instance: ${e}`));
        });
      }
    } else {
      // Standard field validation
      const config: FieldValidationConfig = {
        required: step.required ?? undefined,
        // TODO: Extract from step.config if stored there
      };

      const stepErrors = validateField(value, config, step.title);
      fieldErrors.push(...stepErrors);
    }

    if (fieldErrors.length > 0) {
      errors.push({
        fieldId: step.id,
        fieldTitle: step.title,
        errors: fieldErrors,
      });
    }
  }

  return {
    valid: errors.length === 0,
    errors,
    errorCount: errors.reduce((sum, e) => sum + e.errors.length, 0),
  };
}

/**
 * Checks if a value is empty
 */
function isEmpty(value: any): boolean {
  if (value === null || value === undefined) {
    return true;
  }

  if (typeof value === 'string') {
    return value.trim() === '';
  }

  if (Array.isArray(value)) {
    return value.length === 0;
  }

  if (typeof value === 'object') {
    return Object.keys(value).length === 0;
  }

  return false;
}

/**
 * Formats validation errors for display
 */
export function formatValidationErrors(result: PageValidationResult): string[] {
  const messages: string[] = [];

  for (const error of result.errors) {
    for (const msg of error.errors) {
      messages.push(msg);
    }
  }

  return messages;
}

/**
 * Gets first error for a field (for inline display)
 */
export function getFieldError(
  result: PageValidationResult,
  fieldId: string
): string | null {
  const error = result.errors.find(e => e.fieldId === fieldId);
  return error && error.errors.length > 0 ? error.errors[0] : null;
}
